INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b66a6d57-20c6-4b8d-9c43-77e82d279108', 'NC26.3.ANR.1', 2, 'numeric', 'Equivalent forms: regroup place values', 'A warehouse stores $2{,}800$ pencils in bundles of 100 pencils. How many bundles is that?', '[]', '28', '2800/100', 'Each bundle holds 100 pencils. $2{,}800 \div 100 = 28$, so there are 28 bundles. (28 hundreds make 2,800.)', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,800 = 28 hundreds, so 28 bundles of 100.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
