INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('773cd3e0-ff95-4cb5-a714-a7017d4198c8', 'NC26.3.ANR.1', 2, 'choice', 'Order numbers', 'Maya puts $7{,}014$, $7{,}401$, $7{,}140$ and $7{,}104$ in order from least to greatest. Which list is hers?', '["7,014; 7,140; 7,104; 7,401","7,401; 7,140; 7,104; 7,014","7,014; 7,104; 7,401; 7,140","7,014; 7,104; 7,140; 7,401"]', '7,014; 7,104; 7,140; 7,401', NULL, 'All have 7 thousands. Compare the hundreds: 0, 4, 1 and 1. So 7,014 is least and 7,401 is greatest. For 7,104 and 7,140, compare the tens: 0 tens is less than 4 tens. Order: 7,014; 7,104; 7,140; 7,401.', 'checked', '{"lint":[],"solve":{"answer":"7,014; 7,104; 7,140; 7,401","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hundreds: 7,014 (0), 7,104 (1), 7,140 (1), 7,401 (4). 7,104 < 7,140 by tens. Order: 7,014; 7,104; 7,140; 7,401.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
