INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9d19a82-0b8a-4c77-90e5-a58cc2ed04f1', 'NC26.3.ANR.1', 3, 'choice', 'Order four numbers', 'Which list shows $6{,}058$, $6{,}508$, $6{,}085$ and $5{,}860$ in order from least to greatest?', '["6,058; 6,085; 6,508; 5,860","5,860; 6,085; 6,058; 6,508","5,860; 6,058; 6,085; 6,508","6,508; 6,085; 6,058; 5,860"]', '5,860; 6,058; 6,085; 6,508', NULL, '5,860 has only 5 thousands, so it is the least. The other three have 6 thousands. Compare their hundreds: 0, 5 and 0. So 6,508 is the greatest. For 6,058 and 6,085, both have 0 hundreds; compare tens: 5 tens is less than 8 tens. Order: 5,860; 6,058; 6,085; 6,508.', 'checked', '{"lint":[],"solve":{"answer":"5,860; 6,058; 6,085; 6,508","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,860 is least (5 thousands). Then 6,058 < 6,085 (tens 5 < 8) < 6,508 (hundreds 5). Order: 5,860; 6,058; 6,085; 6,508.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
