INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d8d684a-cd05-462c-832d-e8dbe74d2bd3', 'NC26.3.ANR.1', 3, 'numeric', 'Add thousands, hundreds and tens in steps', 'Start at $2{,}450$. Add 3 thousands, then add 5 hundreds, then add 4 tens. What number do you reach?', '[]', '5990', '2450+3000+500+40', 'Add 3 thousands: 2,450 + 3,000 = 5,450. Add 5 hundreds: 5,450 + 500 = 5,950. Add 4 tens: 5,950 + 40 = 5,990.', 'checked', '{"lint":[],"solve":{"answer":"5990","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,450 + 3,000 = 5,450; + 500 = 5,950; + 40 = 5,990.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
