INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3d96eeb-cb8b-4345-b36c-8feeda7148d4', 'NC26.3.ANR.1', 3, 'numeric', 'Equivalent forms: groups of ten in a number', 'How many groups of 10 are in $3{,}460$?', '[]', '346', '3460/10', 'Every 10 ones make one ten. $3{,}460$ ones is the same as 346 tens, because $346 \times 10 = 3{,}460$.', 'checked', '{"lint":[],"solve":{"answer":"346","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,460 = 346 tens (3,460 / 10 = 346). So there are 346 groups of 10.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
