INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd9ccf92-012d-4a9b-9421-e98c8fa5ad08', 'NC26.3.ANR.1', 3, 'numeric', 'Value of a digit', 'In $5{,}555$, the value of the 5 in the thousands place is how many times the value of the 5 in the hundreds place?', '[]', '10', '5000/500', 'The 5 in the thousands place is worth 5,000. The 5 in the hundreds place is worth 500. Since $5{,}000 \div 500 = 10$, it is worth 10 times as much.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: the ''ten times'' relationship between places is usually a Grade 4 emphasis; acceptable as a place-value stretch item.","work":"Thousands 5 = 5,000; hundreds 5 = 500. 5,000 / 500 = 10 (500 x 10 = 5,000).","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25824f0f-a598-409c-8db7-035adb70f8c3', 'NC26.3.ANR.1', 3, 'choice', 'Value of a digit', 'Which number has a digit 4 whose value is ten times the value of the digit 4 in $1{,}043$?', '["4,012","1,340","2,401","1,204"]', '2,401', '2401', 'In 1,043 the 4 is in the tens place and is worth 40. Ten times 40 is 400, so we need a 4 in the hundreds place. That is 2,401. In 4,012 the 4 is worth 4,000, in 1,340 it is worth 40, and in 1,204 it is worth 4.', 'checked', '{"lint":[],"solve":{"answer":"2,401","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''ten times'' relationship is more typically Grade 4; fine as a harder Grade 3 item.","work":"In 1,043 the 4 is in the tens place: 40. Ten times 40 = 400, so need 4 in the hundreds place. 4,012: 4,000. 2,401: 400. 1,204: 4. 1,340: 40. Answer 2,401.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26180006-3e1b-4ded-b14e-1ab70a8fc92c', 'NC26.3.ANR.1', 3, 'numeric', 'Value of a digit', 'What is the sum of the values of the digits 2 and 8 in $2{,}480$?', '[]', '2080', '2000+80', 'The 2 is in the thousands place, so it is worth 2,000. The 8 is in the tens place, so it is worth 80. $2{,}000 + 80 = 2{,}080$.', 'checked', '{"lint":[],"solve":{"answer":"2080","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,480: the 2 is worth 2,000; the 8 is in the tens place, worth 80. 2,000 + 80 = 2,080.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfc50082-4f1c-44b3-9b63-5c5b3895b5ba', 'NC26.3.ANR.1', 3, 'numeric', 'Write a number from its places', 'A four-digit number has a ones digit of 5. Its tens digit is 3 more than its ones digit. Its hundreds digit is 0. Its thousands digit is 4 less than its ones digit. What is the number?', '[]', '1085', '1*1000+0*100+8*10+5', 'Ones digit: 5. Tens digit: $5 + 3 = 8$. Hundreds digit: 0. Thousands digit: $5 - 4 = 1$. The number is 1,085.', 'checked', '{"lint":[],"solve":{"answer":"1085","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones 5. Tens 5 + 3 = 8. Hundreds 0. Thousands 5 - 4 = 1. Number 1,085.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e66ebe8f-7335-4e34-9a78-9a95820dd05b', 'NC26.3.ANR.1', 3, 'choice', 'Write a number from its places', 'A four-digit number has 8 in the thousands place. Its hundreds digit is 5 less than its thousands digit. Its tens digit is double its hundreds digit. Its ones digit is 0. Which number is it?', '["8,306","8,630","8,360","8,036"]', '8,360', '8360', 'Thousands digit: 8. Hundreds digit: $8 - 5 = 3$. Tens digit: $2 \times 3 = 6$. Ones digit: 0. The number is 8,360.', 'checked', '{"lint":[],"solve":{"answer":"8,360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thousands 8. Hundreds 8 - 5 = 3. Tens 2 x 3 = 6. Ones 0. Number 8,360.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d612993e-a423-40d9-a077-606a456ba9f9', 'NC26.3.ANR.1', 3, 'numeric', 'Write a number from its places', 'What is the smallest four-digit number you can make using each of the digits 4, 0, 9 and 2 exactly once?', '[]', '2049', '2049', 'To make the number small, put the smallest digits in the biggest places. But a four-digit number cannot start with 0, so the smallest digit that can go first is 2. Then use 0, 4 and 9 in order: 2,049.', 'checked', '{"lint":[],"solve":{"answer":"2049","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits 0, 2, 4, 9. The thousands digit cannot be 0 (it would not be four-digit), so use the smallest nonzero, 2, then the rest in increasing order: 0, 4, 9. Number 2,049.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('208bbb07-c005-4748-bf65-7a2df1e2d97e', 'NC26.3.ANR.1', 3, 'choice', 'Expanded form', 'Which choice shows $4{,}608$ in expanded form using multiplication?', '["$4 \\times 1{,}000 + 6 \\times 100 + 0 \\times 10 + 8 \\times 1$","$4 \\times 100 + 6 \\times 10 + 0 \\times 1 + 8 \\times 1$","$4 \\times 1{,}000 + 6 \\times 10 + 0 \\times 100 + 8 \\times 1$","$8 \\times 1{,}000 + 0 \\times 100 + 6 \\times 10 + 4 \\times 1$"]', '$4 \times 1{,}000 + 6 \times 100 + 0 \times 10 + 8 \times 1$', NULL, '4,608 has 4 thousands, 6 hundreds, 0 tens and 8 ones. So it is $4 \times 1{,}000 + 6 \times 100 + 0 \times 10 + 8 \times 1$. The other choices put a digit in the wrong place.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times 1{,}000 + 6 \\times 100 + 0 \\times 10 + 8 \\times 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,608 = 4 x 1,000 + 6 x 100 + 0 x 10 + 8 x 1. Check others: 8,064; 4,000 + 60 + 0 + 8 = 4,068; 400 + 60 + 0 + 8 = 468. Only option B.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
