VALUES ('d1eaac96-2a56-4687-a54b-59f9998fd748', 'NC26.3.ANR.1', 3, 'numeric', 'Expanded form', 'Kim writes $3{,}000 + 14 \times 100 + 8$. What number is that?', '[]', '4408', '3000+14*100+8', '$14 \times 100 = 1{,}400$. Then $3{,}000 + 1{,}400 + 8 = 4{,}408$.', 'checked', '{"lint":[],"solve":{"answer":"4408","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 100 = 1,400. 3,000 + 1,400 + 8 = 4,408.","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
