INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12d5b991-5f20-401e-b403-7ecf4f427c17', 'NC26.3.ANR.1', 3, 'choice', 'Number words and standard form', 'Which choice does NOT name $4{,}120$?', '["four thousand, one hundred twenty","four thousand, twelve","41 hundreds and 20 ones","412 tens"]', 'four thousand, twelve', NULL, '4,120 is "four thousand, one hundred twenty". Also 41 hundreds and 20 ones is $4{,}100 + 20 = 4{,}120$, and 412 tens is $412 \times 10 = 4{,}120$. But "four thousand, twelve" is 4,012.', 'checked', '{"lint":[],"solve":{"answer":"four thousand, twelve","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"412 tens = 4,120 (yes). Words ''four thousand, one hundred twenty'' = 4,120 (yes). 41 hundreds + 20 ones = 4,100 + 20 = 4,120 (yes). ''four thousand, twelve'' = 4,012 (no).","run_id":"claude-code","at":"2026-10-17T19:22:04.066Z"}}', 'ai', NULL, NULL)
