INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('500f3906-672b-4922-a6b8-fc314f3b81ef', 'NC26.3.ANR.2', 1, 'choice', 'Strategies and properties of addition and subtraction', 'Which number sentence has the same sum as $146 + 53$?', '["$53 + 146$","$146 - 53$","$146 + 35$","$164 + 53$"]', '$53 + 146$', NULL, 'You can add two numbers in either order and get the same sum, so $146 + 53 = 53 + 146$. The other choices use different numbers.', 'checked', '{"lint":[],"solve":{"answer":"$53 + 146$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"146 + 53 = 199. 53 + 146 = 199 (commutative). 146 + 35 = 181; 164 + 53 = 217; 146 - 53 = 93.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
