INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89bc60e6-7567-4e21-855c-004008ef6a07', 'NC26.3.ANR.2', 1, 'choice', 'Strategies and properties of addition and subtraction', 'Hugo says $483 - 215 = 268$. Which choice can he use to check his answer?', '["Add $483 + 215$ and see if the sum is 268","Add $268 + 483$ and see if the sum is 215","Add $268 + 215$ and see if the sum is 483","Subtract $215 - 268$ and see if the difference is 483"]', 'Add $268 + 215$ and see if the sum is 483', NULL, 'Addition undoes subtraction. If $483 - 215 = 268$, then the answer added to the number taken away must give back the start: $268 + 215 = 483$.', 'checked', '{"lint":[],"solve":{"answer":"Add $268 + 215$ and see if the sum is 483","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtraction is checked by adding the difference to the part taken away: 268 + 215 = 483, which matches. Option A.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
