VALUES ('8ca31863-9e80-41d8-9f7b-5e301b7f6a04', 'NC26.3.ANR.2', 1, 'numeric', 'Equation with a missing number or digit', 'Find the number that makes this true: $70 + ? = 120$.', '[]', '50', '120-70', '$? = 120 - 70 = 50$. Check: $70 + 50 = 120$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 - 70 = 50.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
