INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42f486c0-5088-4c58-a1c0-e868aee04632', 'NC26.3.ANR.2', 1, 'choice', 'Equation with a missing number or digit', 'Which number makes $85 - ? = 40$ true?', '["45","125","55","35"]', '45', '85-40', 'The missing number is what is taken away from 85 to leave 40: $85 - 40 = 45$. Check: $85 - 45 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"85 - 40 = 45; check 85 - 45 = 40.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
