INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d977a0f-d230-4b69-b54c-522bb082f214', 'NC26.3.ANR.2', 1, 'numeric', 'Equation with a missing number or digit', 'A number minus 25 is 60. What is the number?', '[]', '85', '60+25', 'Taking away 25 left 60, so put the 25 back: $60 + 25 = 85$. Check: $85 - 25 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? - 25 = 60, so ? = 60 + 25 = 85.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
