INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb967900-5a04-457d-b4a4-d2d246203951', 'NC26.3.ANR.2', 2, 'choice', 'Add in a story', 'A hiker climbed 275 meters in the morning and 189 meters in the afternoon. How many meters did the hiker climb in all?', '["464","454","364","474"]', '464', '275+189', 'Ones: $5 + 9 = 14$, write 4 and carry 1 ten. Tens: $7 + 8 + 1 = 16$, write 6 and carry 1 hundred. Hundreds: $2 + 1 + 1 = 4$. The hiker climbed 464 meters.', 'checked', '{"lint":[],"solve":{"answer":"464","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"275 + 189: 200 + 100 = 300, 70 + 80 = 150, 5 + 9 = 14. 300 + 150 + 14 = 464.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
