INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f0bf5d5-bf73-4130-be94-ef233c025fd6', 'NC26.3.ANR.2', 2, 'choice', 'Add in a story', 'At a fair, 384 children rode the Ferris wheel on Saturday and 297 children rode it on Sunday. How many children rode it on the two days?', '["671","581","681","781"]', '681', '384+297', 'Ones: $4 + 7 = 11$, write 1 and carry 1 ten. Tens: $8 + 9 + 1 = 18$, write 8 and carry 1 hundred. Hundreds: $3 + 2 + 1 = 6$. The total is 681 children.', 'checked', '{"lint":[],"solve":{"answer":"681","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"384 + 297 = 384 + 300 - 3 = 684 - 3 = 681.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
