INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f41d7c9-526d-4f2a-9e20-ca5c85dbd9fe', 'NC26.3.ANR.2', 2, 'numeric', 'Subtract in a story (take away or compare)', 'A museum had 842 visitors on Saturday and 566 visitors on Sunday. How many more visitors came on Saturday than on Sunday?', '[]', '276', '842-566', 'Find the difference: $842 - 566$. Ones: trade a ten, $12 - 6 = 6$. Tens: now 3 tens, so trade a hundred, $13 - 6 = 7$. Hundreds: now 7 hundreds, $7 - 5 = 2$. The answer is 276. Check: $566 + 276 = 842$.', 'checked', '{"lint":[],"solve":{"answer":"276","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"842 - 566: 842 - 500 = 342, - 60 = 282, - 6 = 276. Check 566 + 276 = 842.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
