INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d03357b-4a71-4ae5-b91d-da14a124a97e', 'NC26.3.ANR.2', 2, 'choice', 'Subtract in a story (take away or compare)', 'Eli''s book has 603 pages. He has read 278 pages. How many pages does he still have to read?', '["475","335","325","881"]', '325', '603-278', 'Subtract: $603 - 278$. There are 0 tens, so trade 1 hundred for 10 tens, then 1 ten for 10 ones: 5 hundreds, 9 tens, 13 ones. Ones: $13 - 8 = 5$. Tens: $9 - 7 = 2$. Hundreds: $5 - 2 = 3$. The answer is 325. Check: $325 + 278 = 603$.', 'checked', '{"lint":[],"solve":{"answer":"325","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"603 - 278: 603 - 200 = 403, - 70 = 333, - 8 = 325. Check 278 + 325 = 603.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d89ccad7-36bf-4ffa-a35c-ae5fce8e8b36', 'NC26.3.ANR.2', 2, 'numeric', 'Subtract in a story (take away or compare)', 'A water tank holds 920 liters. After 465 liters are used, how many liters are left?', '[]', '455', '920-465', 'Subtract: $920 - 465$. Ones: $0 - 5$, so trade: tens go from 2 to 1 and ones become 10, so $10 - 5 = 5$. Tens: $1 - 6$, so trade a hundred: $11 - 6 = 5$. Hundreds: $8 - 4 = 4$. The answer is 455. Check: $455 + 465 = 920$.', 'checked', '{"lint":[],"solve":{"answer":"455","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"920 - 465: 920 - 400 = 520, - 60 = 460, - 5 = 455. Check 465 + 455 = 920.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
