INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52917678-413d-49dc-8e65-191a4c88e667', 'NC26.3.ANR.2', 2, 'choice', 'Subtract in a story (take away or compare)', 'A zoo has 713 animals. Of these, 289 are birds. How many of the animals are not birds?', '["576","424","534","1,002"]', '424', '713-289', 'Subtract: $713 - 289$. Ones: trade a ten, $13 - 9 = 4$. Tens: now 0 tens, so trade a hundred, $10 - 8 = 2$. Hundreds: now 6 hundreds, $6 - 2 = 4$. The answer is 424. Check: $424 + 289 = 713$.', 'checked', '{"lint":[],"solve":{"answer":"424","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"713 - 289 = 713 - 300 + 11 = 413 + 11 = 424. Check 289 + 424 = 713.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
