INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4263de6-27f2-4435-a3a7-fcd0ff22e690', 'NC26.3.ANR.2', 2, 'numeric', 'Find the unknown in a story', 'A library had 329 books. After a delivery it had 512 books. How many books were delivered?', '[]', '183', '512-329', 'Books delivered: $329 + ? = 512$, so $? = 512 - 329$. Ones: trade a ten, $12 - 9 = 3$. Tens: now 0 tens, so trade a hundred, $10 - 2 = 8$. Hundreds: $4 - 3 = 1$. The answer is 183. Check: $329 + 183 = 512$.', 'checked', '{"lint":[],"solve":{"answer":"183","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"329 + ? = 512; 512 - 329 = 183. Check 329 + 183 = 512.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
