INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b7d096-44d3-4ae9-a3ff-60a1de75df52', 'NC26.3.ANR.2', 2, 'choice', 'Find the unknown in a story', 'Bo has 245 points in a game. He needs 600 points to win a prize. How many more points does he need?', '["845","355","455","365"]', '355', '600-245', 'Find $600 - 245$. Count up from 245 to 250 is 5, from 250 to 300 is 50, and from 300 to 600 is 300. $5 + 50 + 300 = 355$. Check: $245 + 355 = 600$.', 'checked', '{"lint":[],"solve":{"answer":"355","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 - 245 = 355. Check 245 + 355 = 600.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
