INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f0ceb33-f44e-47e8-b08d-7e08c4e54c07', 'NC26.3.ANR.2', 2, 'numeric', 'Find the unknown in a story', 'After 276 people left a theater, 349 people were still inside. How many people were in the theater before anyone left?', '[]', '625', '349+276', 'The people before = the people who left + the people still inside. $276 + 349$: ones $6 + 9 = 15$, tens $7 + 4 + 1 = 12$, hundreds $2 + 3 + 1 = 6$. The answer is 625.', 'checked', '{"lint":[],"solve":{"answer":"625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start - 276 = 349, so start = 349 + 276 = 625.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('020acb22-ed64-49d2-ad72-94e9b7c13d17', 'NC26.3.ANR.2', 2, 'numeric', 'Add or subtract by place value', 'Lia finds $752 - 238$ by taking away 200, then 30, then 8. What is the answer?', '[]', '514', '752-238', '$752 - 200 = 552$. $552 - 30 = 522$. $522 - 8 = 514$.', 'checked', '{"lint":[],"solve":{"answer":"514","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"752 - 200 = 552; 552 - 30 = 522; 522 - 8 = 514.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
