INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8d08c9d-d57a-48fb-aa26-a68132b8dace', 'NC26.3.ANR.2', 2, 'choice', 'Add or subtract by place value', 'Which choice shows $463 + 128$ split into hundreds, tens and ones?', '["$(400 + 100) + (60 + 2) + (3 + 8)$","$(400 + 100) + (60 + 20) + (3 + 8)$","$(400 + 10) + (60 + 20) + (3 + 8)$","$(400 + 100) + (6 + 2) + (3 + 8)$"]', '$(400 + 100) + (60 + 20) + (3 + 8)$', NULL, '463 is $400 + 60 + 3$ and 128 is $100 + 20 + 8$. So the hundreds are $400 + 100$, the tens are $60 + 20$ and the ones are $3 + 8$. The other choices use 2, 10 or 6 where a different place value is needed.', 'checked', '{"lint":[],"solve":{"answer":"$(400 + 100) + (60 + 20) + (3 + 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"463 = 400 + 60 + 3; 128 = 100 + 20 + 8. Hundreds (400 + 100), tens (60 + 20), ones (3 + 8). Option C. Others mis-split (6 + 2, 60 + 2, 400 + 10).","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7a9d912-dccf-4d65-9f8e-a0de989e707c', 'NC26.3.ANR.2', 2, 'numeric', 'Add or subtract by place value', 'Kofi adds $276 + 145$. He adds the ones: $6 + 5 = 11$. He adds the tens: $70 + 40 = 110$. He adds the hundreds: $200 + 100 = 300$. What is the total of his three results?', '[]', '421', '276+145', '$11 + 110 + 300$: $11 + 110 = 121$, and $121 + 300 = 421$. So $276 + 145 = 421$.', 'checked', '{"lint":[],"solve":{"answer":"421","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 + 110 + 300 = 421. Check 276 + 145 = 421.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63eb56fc-fcae-483a-90b6-44bf7e50481a', 'NC26.3.ANR.2', 2, 'numeric', 'Strategies and properties of addition and subtraction', 'Add $26 + 38 + 14$ by adding $26 + 14$ first. What is the total?', '[]', '78', '26+38+14', '$26 + 14 = 40$. Then $40 + 38 = 78$.', 'checked', '{"lint":[],"solve":{"answer":"78","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26 + 14 = 40; 40 + 38 = 78.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
