INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50c31e81-ef63-417d-a00b-78642a6bb78a', 'NC26.3.ANR.2', 3, 'numeric', 'Add or subtract by place value', 'Dev wants $705 - 328$. He subtracts $705 - 300 = 405$, and then subtracts the rest, 28, from 405. What is the answer?', '[]', '377', '705-328', 'After taking away 300, 28 is left to take away: $405 - 28$. Take away 20 to get 385, then 8 more to get 377. The answer is 377. Check: $377 + 328 = 705$.', 'checked', '{"lint":[],"solve":{"answer":"377","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"405 - 28 = 377. Check 328 + 377 = 705.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
