INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60ac10c3-e5ab-41f1-93a3-7d33e4508539', 'NC26.3.ANR.2', 3, 'numeric', 'Strategies and properties of addition and subtraction', 'Jana counts up to find $1{,}000 - 647$. She goes from 647 to 650, then to 700, then to $1{,}000$. How many does she count up in all?', '[]', '353', '3+50+300', '647 to 650 is 3. 650 to 700 is 50. 700 to 1,000 is 300. $3 + 50 + 300 = 353$. So $1{,}000 - 647 = 353$.', 'checked', '{"lint":[],"solve":{"answer":"353","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"647 to 650: 3; 650 to 700: 50; 700 to 1,000: 300. 3 + 50 + 300 = 353.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
