VALUES ('b255b4c2-7922-40bb-abad-365d6a9853ad', 'NC26.3.ANR.2', 3, 'choice', 'Strategies and properties of addition and subtraction', 'Which choice does NOT equal $374 + 258$?', '["$258 + 374$","$380 + 252$","$370 + 268$","$376 + 256$"]', '$370 + 268$', NULL, '$374 + 258 = 632$. $258 + 374 = 632$, $380 + 252 = 632$ and $376 + 256 = 632$. But $370 + 268 = 638$, which is different.', 'checked', '{"lint":[],"solve":{"answer":"$370 + 268$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"374 + 258 = 632. 258 + 374 = 632; 380 + 252 = 632; 376 + 256 = 632; 370 + 268 = 638. Only the last differs.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
