VALUES ('e52b06b4-63a2-4b05-b63e-5a16ec5cbc0a', 'NC26.3.ANR.2', 3, 'choice', 'Subtract with regrouping', 'Which difference equals 268?', '["$514 - 256$","$524 - 246$","$504 - 246$","$514 - 246$"]', '$514 - 246$', NULL, '$514 - 246$: ones $14 - 6 = 8$, tens $0 - 4$ means trade, so $10 - 4 = 6$, hundreds $4 - 2 = 2$. That is 268. The other differences are 258, 278 and 258.', 'checked', '{"lint":[],"solve":{"answer":"$514 - 246$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"504 - 246 = 258; 514 - 256 = 258; 524 - 246 = 278; 514 - 246 = 268. Only the last.","run_id":"claude-code","at":"2026-10-17T19:22:04.103Z"}}', 'ai', NULL, NULL)
