INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49225eab-2da1-4672-bd23-e6387f0e946b', 'NC26.3.ANR.2', 3, 'numeric', 'Find a missing digit in a three-digit sum', 'A three-digit number is written 4?7, where ? is a digit that cannot be read. When 286 is added to this number, the sum is 733. What digit does the ? stand for?', '[]', '4', '(733-286-407)/10', 'Look at the ones: 7 + 6 = 13, so write 3 and regroup 1 ten. In the tens column, ? + 8 + 1 ten must end in 3, so ? + 9 = 13 and ? = 4. Check: 447 + 286 = 733.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4?7 + 286 = 733, so 4?7 = 733 - 286 = 447. Check: 447 + 286 = 733. The missing digit is 4. Only one digit works since the number is fixed by the subtraction.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48a181e4-faf0-4957-a1b5-ee83217660a9', 'NC26.3.ANR.3', 1, 'choice', 'Equal groups as a multiplication sentence', 'There are 4 bags with 6 apples in each bag. Which multiplication sentence shows the number of apples in all?', '["$4 + 6 = 10$","$4 \\times 6 = 24$","$6 \\times 6 = 36$","$4 \\times 4 = 16$"]', '$4 \times 6 = 24$', NULL, '4 bags with 6 apples in each bag is 4 equal groups of 6. That is $4 \times 6 = 24$ apples.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times 6 = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal groups of 6: 4 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
