VALUES ('1f8972d0-8da7-4b2c-8144-3b641a4be784', 'NC26.3.ANR.3', 2, 'numeric', 'Multiplying by multiples of 10', 'Pedro practices piano for 30 minutes every day. How many minutes does he practice in 5 days?', '[]', '150', '5*30', '$5 \times 3 = 15$, so 5 groups of 3 tens is 15 tens, which is 150 minutes.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 30 = 15 tens = 150.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
