INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('572ff38e-5cc2-46e9-8791-589bdd77ddb3', 'NC26.3.ANR.3', 3, 'choice', 'Breaking a factor apart to multiply', 'Which expression does NOT equal $8 \times 4$?', '["$(4 \\times 4) + (4 \\times 4)$","$(5 \\times 4) + (3 \\times 4)$","$(2 \\times 4) + (6 \\times 4)$","$(6 \\times 4) + (3 \\times 4)$"]', '$(6 \times 4) + (3 \times 4)$', NULL, '$8 \times 4 = 32$. The groups $4 + 4$, $5 + 3$ and $2 + 6$ all make 8, so they give 32. But $6 + 3 = 9$ groups of 4 is 36.', 'checked', '{"lint":[],"solve":{"answer":"$(6 \\times 4) + (3 \\times 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 4 = 32. 16+16 = 32; 8+24 = 32; 24+12 = 36; 20+12 = 32. Only (6 x 4) + (3 x 4) is not 32 (it is 9 x 4).","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
