INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8c66c4b-da43-4d33-af2d-0590e1b7abeb', 'NC26.3.ANR.3', 3, 'numeric', 'Breaking a factor apart to multiply', 'Ned breaks 9 into $4 + \square$ to find $9 \times 7$, writing $(4 \times 7) + (\square \times 7)$. What number goes in both boxes?', '[]', '5', '9-4', 'The two parts of 9 must add to 9, so $4 + \square = 9$ and the box holds 5. Check: $(4 \times 7) + (5 \times 7) = 28 + 35 = 63 = 9 \times 7$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 = 4 + 5, so box = 5: 28 + 35 = 63.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
