VALUES ('423817e1-606f-401d-9594-2f96a3feb405', 'NC26.3.ANR.3', 3, 'choice', 'Multiplying by multiples of 10', 'Which expression is equal to $7 \times 50$?', '["$(7 \\times 5) \\times 10$","$7 \\times 5$","$(7 + 5) \\times 10$","$(7 \\times 5) \\times 100$"]', '$(7 \times 5) \times 10$', NULL, '50 is 5 tens, so $7 \times 50 = (7 \times 5) \times 10 = 35 \times 10 = 350$.', 'checked', '{"lint":[],"solve":{"answer":"$(7 \\times 5) \\times 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 50 = 7 x 5 x 10 = 35 x 10 = 350. (7 x 5) x 100 = 3500, 7 x 5 = 35, (7+5) x 10 = 120.","run_id":"claude-code","at":"2026-10-17T19:20:12.112Z"}}', 'ai', NULL, NULL)
