INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('009247d9-d3fa-4c98-b46a-0341e0c304ad', 'NC26.3.ANR.4', 1, 'choice', 'Division as repeated subtraction or skip counting', 'Which repeated subtraction can be used to find $15 \div 5$?', '["$15 - 5 - 5 - 5 = 0$","$15 - 10 - 5 = 0$","$15 - 15 = 0$","$15 - 5 = 10$"]', '$15 - 5 - 5 - 5 = 0$', NULL, 'Take the same amount, 5, away from 15 again and again until nothing is left: $15 - 5 - 5 - 5 = 0$. You subtract 5 three times, so $15 \div 5 = 3$. In the other choices the amounts taken away are not all 5, or the subtraction stops after one step.', 'checked', '{"lint":[],"solve":{"answer":"$15 - 5 - 5 - 5 = 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 / 5 by repeated subtraction: take 5 away until 0: 15 - 5 - 5 - 5 = 0, three times, so 3. Option with 10 then 5 is not repeated subtraction of 5; 15 - 15 and 15 - 5 = 10 do not show it.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
