INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('420edbb9-d29d-4961-8b29-300d16519762', 'NC26.3.ANR.4', 1, 'choice', 'Use a multiplication fact to divide (fact families)', 'Which division fact is in the same fact family as $4 \times 7 = 28$?', '["$28 \\div 4 = 24$","$7 \\div 28 = 4$","$28 \\div 7 = 7$","$28 \\div 4 = 7$"]', '$28 \div 4 = 7$', NULL, 'A fact family uses the same three numbers: 4, 7 and 28. From $4 \times 7 = 28$ we get $28 \div 4 = 7$ and $28 \div 7 = 4$. Only $28 \div 4 = 7$ is listed and true.', 'checked', '{"lint":[],"solve":{"answer":"$28 \\div 4 = 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fact family of 4, 7, 28: 28 / 4 = 7 and 28 / 7 = 4. Option 28 / 7 = 7 is false; 28 / 4 = 24 false; 7 / 28 = 4 false.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
