INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29aba859-7098-4981-b113-bc8fe5344e05', 'NC26.3.ANR.4', 2, 'numeric', 'Use a multiplication fact to divide (fact families)', 'Max does not remember $72 \div 9$. He thinks, "9 times what number makes 72?" What is $72 \div 9$?', '[]', '8', '72/9', '$9 \times 8 = 72$, so $72 \div 9 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 8 = 72 so 72 / 9 = 8.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
