INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('277524f0-c2ea-4216-9abc-06308c6afdab', 'NC26.3.ANR.4', 2, 'numeric', 'Equation with an unknown divisor', 'Some children share 56 grapes equally, and each child gets 7 grapes. If $c$ is the number of children, then $56 \div c = 7$. What is $c$?', '[]', '8', '56/7', '$56 \div 8 = 7$, so $c = 8$. There are 8 children. Check: $8 \times 7 = 56$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 / c = 7: 7 x 8 = 56, c = 8.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
