VALUES ('7cb75c53-92c3-4f50-a8c1-1e8e5b5bcff3', 'NC26.3.ANR.4', 2, 'choice', 'Equation with an unknown dividend', 'Which value of $m$ makes $m \div 4 = 9$ true?', '["13","5","32","36"]', '36', '4*9', '$m = 4 \times 9 = 36$. Check: $36 \div 4 = 9$. The other choices come from adding (13), subtracting (5), or a wrong fact (32).', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m / 4 = 9: m = 4 x 9 = 36.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
