INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a57534f0-bb89-4898-b958-ff7907a442b8', 'NC26.3.ANR.4', 2, 'choice', 'Write or match an equation for a division story', 'Nine friends share 63 raisins equally. Let $r$ be the number of raisins each friend gets. Which equation can be used to find $r$?', '["$63 \\times 9 = r$","$9 \\div 63 = r$","$63 \\div 9 = r$","$r \\div 9 = 63$"]', '$63 \div 9 = r$', NULL, 'Sharing 63 raisins equally among 9 friends is $63 \div 9 = r$, so $r = 7$. The equation $r \div 9 = 63$ would mean each friend gets 63 raisins in a share of $r$.', 'checked', '{"lint":[],"solve":{"answer":"$63 \\div 9 = r$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each gets 63 / 9 = r (r = 7).","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
