INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('976fb5f1-e2f8-44a8-a3bd-9a838d80a525', 'NC26.3.ANR.4', 2, 'choice', 'Write or match an equation for a division story', 'A baker packs 48 rolls into bags of 6 rolls each. Let $b$ be the number of bags. Which equation can be used to find $b$?', '["$6 \\times b = 48$","$6 \\times 48 = b$","$48 + 6 = b$","$48 \\times b = 6$"]', '$6 \times b = 48$', NULL, '$b$ bags with 6 rolls each make 48 rolls, so $6 \times b = 48$. That is the same as $48 \div 6 = b$, so $b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times b = 48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b bags of 6 make 48: 6 x b = 48 (b = 8). Others wrong.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5826e1a-a096-4450-93a7-d8d1c5bf04f2', 'NC26.3.ANR.4', 2, 'choice', 'Write or match an equation for a division story', 'Ruth puts 54 books into 6 equal stacks. Let $s$ be the number of books in each stack. Which equation does NOT fit this story?', '["$54 \\div 6 = s$","$6 \\times s = 54$","$s \\times 6 = 54$","$54 - 6 = s$"]', '$54 - 6 = s$', NULL, 'Equal stacks of $s$ books, 6 stacks, 54 books in all: $54 \div 6 = s$, $6 \times s = 54$ and $s \times 6 = 54$ all fit. Subtracting 6 from 54 does not describe putting books into equal stacks.', 'checked', '{"lint":[],"solve":{"answer":"$54 - 6 = s$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s = 54 / 6 = 9; 6 x s = 54 and s x 6 = 54 also fit. 54 - 6 = 48 does not fit.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bfec64e-2ee3-46c0-9e1c-2c8e9f7c78f6', 'NC26.3.ANR.4', 2, 'choice', 'Meaning of the quotient and the divisor', 'In a division equation, the divisor is the number you divide by. In $63 \div 9 = 7$, which number is the divisor?', '["9","63","7","Both 9 and 7"]', '9', '9', 'You divide 63 by 9, so 9 is the divisor. The 63 is the number being divided and 7 is the quotient.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dividing 63 by 9: divisor is 9.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
