INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('436db093-deb9-4e44-af84-9587809caaa0', 'NC26.3.ANR.4', 2, 'choice', 'Meaning of the quotient and the divisor', 'In $48 \div 8 = 6$, the answer 6 is called the quotient. 48 apples are put into bags with 8 apples in each bag. What does the quotient tell you?', '["The number of apples in each bag","The total number of apples","The number of apples left over","The number of bags"]', 'The number of bags', NULL, 'Each bag holds 8 apples, so 8 is the size of each group. The quotient 6 tells how many bags are filled.', 'checked', '{"lint":[],"solve":{"answer":"The number of bags","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 apples, 8 per bag: 48 / 8 = 6 bags. The quotient is the number of bags.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0313092b-7c98-4711-8612-8dc2b41c7263', 'NC26.3.ANR.4', 2, 'numeric', 'Meaning of the quotient and the divisor', 'Nora divides 56 plums into 8 equal groups, and each group has 7 plums. If she makes groups of 8 plums instead, how many groups will there be?', '[]', '7', '56/8', '$56 \div 8 = 7$ can be read two ways: 8 groups of 7, or groups of 8 that make 7 groups. With groups of 8 plums there are 7 groups.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"56 plums in groups of 8: 56 / 8 = 7 groups.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
