INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af711ec3-cd87-435a-8dce-1feae2ee2230', 'NC26.3.ANR.4', 3, 'numeric', 'Share equally: find the size of each group', 'A teacher has 4 packs of 9 markers. She shares all of the markers equally among 6 tables. How many markers does each table get?', '[]', '6', '4*9/6', 'There are $4 \times 9 = 36$ markers in all. Sharing them among 6 tables gives $36 \div 6 = 6$ markers for each table.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total markers 4 x 9 = 36. Shared among 6 tables: 36 / 6 = 6.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
