INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e7c909f-b645-46cc-9fff-50124d7721e8', 'NC26.3.ANR.4', 3, 'numeric', 'Share equally: find the size of each group', 'Hana had 50 marbles. She gave 5 of them to her cousin, then shared the rest equally among 5 friends. How many marbles did each friend get?', '[]', '9', '(50-5)/5', 'After giving 5 away, Hana has $50 - 5 = 45$ marbles. Sharing them among 5 friends gives $45 \div 5 = 9$ marbles each.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 5 = 45 left. 45 / 5 = 9 each.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
