INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('859f387c-c394-4fbe-b04f-e908b1eae953', 'NC26.3.ANR.4', 3, 'choice', 'Division strategy: break the total into easier facts', 'Ana knows $40 \div 8 = 5$. She wants to use it to find $80 \div 8$. What should she do next?', '["Add 5 and 8 to get 13","Subtract 5 from 40 to get 35","Double 5 to get 10","Multiply 5 by 8 to get 40"]', 'Double 5 to get 10', NULL, '80 is double 40, so there are twice as many groups of 8. Double 5 to get 10. Check: $10 \times 8 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"Double 5 to get 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80 is double 40, so 80 / 8 is double 40 / 8: 2 x 5 = 10.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1f727ee-2acd-4353-a65a-77ac24820e20', 'NC26.3.ANR.4', 3, 'numeric', 'Division strategy: break the total into easier facts', 'Tess divides a number by 8 by splitting it into 40 and 24. She finds $40 \div 8 = 5$ and $24 \div 8 = 3$. What is the number she started with?', '[]', '64', '40+24', 'The two parts add up to the whole number: $40 + 24 = 64$. Check: $64 \div 8 = 8$, and $5 + 3 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number = 40 + 24 = 64. Check 64 / 8 = 8 = 5 + 3.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13954915-e9b1-4867-a42f-99fa131b1858', 'NC26.3.ANR.4', 3, 'choice', 'Division strategy: break the total into easier facts', 'Which way of splitting 72 is NOT helpful for finding $72 \div 9$?', '["$70 + 2$","$36 + 36$","$45 + 27$","$63 + 9$"]', '$70 + 2$', NULL, 'A helpful split uses parts that are multiples of 9. $36 + 36$, $45 + 27$ and $63 + 9$ all do. But 70 and 2 are not multiples of 9, so they are not easy to divide by 9.', 'checked', '{"lint":[],"solve":{"answer":"$70 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45+27 (5+3), 63+9 (7+1), 36+36 (4+4) all split into multiples of 9 and give 8. 70 + 2: neither part divides by 9, so not helpful.","run_id":"claude-code","at":"2026-10-17T19:07:57.528Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a49a0ee4-9682-40ec-8b35-1af2def8aac6', 'NC26.3.ANR.4', 3, 'choice', 'Division as repeated subtraction or skip counting', 'Which way of finding $30 \div 5$ is NOT correct?', '["Skip count by 5s from 0 up to 30, and count the jumps","Subtract 5 from 30 again and again until you reach 0, and count the subtractions","Find the missing number in $5 + \\square = 30$","Find the missing number in $5 \\times \\square = 30$"]', 'Find the missing number in $5 + \square = 30$', NULL, 'Division asks how many 5s fit in 30, so skip counting by 5s, subtracting 5s until 0, and finding the missing factor in $5 \times \square = 30$ all work (each gives 6). The missing number in $5 + \square = 30$ is 25, which is a subtraction answer, not $30 \div 5$.', 'checked', '{"lint":[],"solve":{"answer":"Find the missing number in $5 + \\square = 30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Repeated subtraction, skip counting and 5 x ? = 30 all give 6. 5 + ? = 30 gives 25, not the quotient.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
