INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b939ec9-b2da-407f-ac18-7869efdf6d29', 'NC26.3.ANR.5', 2, 'choice', 'Explaining multiplication and division in context', 'Which situation needs division to solve?', '["Nia has 20 marbles and puts 5 in each bag. How many bags can she fill?","Nia has 5 bags with 4 marbles in each bag. How many marbles in all?","Nia has 20 marbles and finds 5 more. How many now?","Nia has 20 marbles and loses 5. How many are left?"]', 'Nia has 20 marbles and puts 5 in each bag. How many bags can she fill?', NULL, 'Putting 20 marbles into bags of 5 asks how many groups of 5 are in 20, which is $20 \div 5 = 4$. The others need multiplication, addition or subtraction.', 'checked', '{"lint":[],"solve":{"answer":"Nia has 20 marbles and puts 5 in each bag. How many bags can she fill?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 marbles, 5 in each bag, how many bags: 20 / 5 = 4. The others need multiplication (5 x 4), subtraction, addition.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
