VALUES ('e499dc11-e0c8-4ad4-ae7b-5c261ef9807c', 'NC26.3.ANR.5', 2, 'numeric', 'Finding the unknown number', 'Mia has 32 crayons in 8 boxes, with the same number in each box. This can be written as $8 \times n = 32$. What is the value of $n$?', '[]', '4', '32/8', '$8 \times 4 = 32$, so $n = 4$ crayons in each box.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x n = 32, n = 4.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
