INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf72464e-e46e-46ba-b0bf-ad0a75330112', 'NC26.3.ANR.5', 3, 'choice', 'Explaining multiplication and division in context', 'A farmer has 63 pears. He puts 7 pears in each basket. Which number sentence shows how many baskets he fills?', '["$63 \\times 7 = 441$","$63 - 7 = 56$","$63 \\div 7 = 9$","$63 + 7 = 70$"]', '$63 \div 7 = 9$', NULL, 'The question is how many groups of 7 are in 63, so divide: $63 \div 7 = 9$ baskets.', 'checked', '{"lint":[],"solve":{"answer":"$63 \\div 7 = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63 pears, 7 per basket: 63 / 7 = 9 baskets.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
