INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7d62ac9-0203-44dc-8ca8-430c40792c84', 'NC26.3.ANR.5', 3, 'choice', 'Inverse relationship and fact families', 'Which multiplication equation can be used to find the missing number in $\square \div 5 = 9$?', '["$9 \\times 5 = \\square$","$9 \\div 5 = \\square$","$5 \\times \\square = 9$","$\\square \\times 9 = 5$"]', '$9 \times 5 = \square$', NULL, 'Dividing by 5 gave 9, so multiplying 9 by 5 undoes it: $9 \times 5 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 5 = \\square$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"box / 5 = 9 means box = 9 x 5 = 45. 9 / 5 = box is division, 5 x box = 9 and box x 9 = 5 are wrong.","run_id":"claude-code","at":"2026-10-17T19:20:12.151Z"}}', 'ai', NULL, NULL)
