INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fece441-1b0d-4a99-bf67-41e51b965943', 'NC26.3.ANR.6', 1, 'choice', 'Two-step: add and subtract in a story', 'There are 20 children on a bus. At the first stop 5 more children get on. At the next stop 3 children get off. How many children are on the bus now?', '["25","22","17","28"]', '22', '20+5-3', 'First $20 + 5 = 25$ children. Then $25 - 3 = 22$. The choice 25 forgets the 3 who get off, 17 forgets the 5 who get on, and 28 adds the 3.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 5 = 25; 25 - 3 = 22.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
