INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0f559de-a148-47db-8a93-a722014dd5e6', 'NC26.3.ANR.6', 1, 'numeric', 'Two-step: add and subtract in a story', 'A pond has 15 ducks. 6 ducks swim away, and then 3 new ducks swim in. How many ducks are on the pond now?', '[]', '12', '15-6+3', 'After 6 swim away there are $15 - 6 = 9$ ducks. After 3 swim in there are $9 + 3 = 12$ ducks.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 - 6 = 9; 9 + 3 = 12.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
