INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aaa62a91-cb4f-41e5-901b-a03defedc2c7', 'NC26.3.ANR.6', 1, 'choice', 'Two-step: add or subtract first, then multiply', 'Pete buys 6 apples and Tia buys 4 apples. Each apple costs 2 dollars. How many dollars do they spend in all?', '["14","20","12","10"]', '20', '(6+4)*2', 'Together they buy $6 + 4 = 10$ apples. At 2 dollars each, $10 \times 2 = 20$ dollars. The choice 14 multiplies only the 4, 12 counts only Pete, and 10 forgets the price.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 4 = 10 apples; 10 x 2 = 20 dollars.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
