VALUES ('b5a4f4a2-e8b1-4c94-816f-fd72c45c800c', 'NC26.3.ANR.6', 1, 'numeric', 'Two-step: compare two products', 'Nora has 3 boxes with 4 stickers in each box. Ravi has 2 boxes with 5 stickers in each box. How many more stickers does Nora have than Ravi?', '[]', '2', '3*4-2*5', 'Nora has $3 \times 4 = 12$ stickers. Ravi has $2 \times 5 = 10$ stickers. Nora has $12 - 10 = 2$ more.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nora 3 x 4 = 12; Ravi 2 x 5 = 10; 12 - 10 = 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
