INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea8633be-c1f8-4518-933c-5178ea29dd46', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: add and subtract in a story', 'A store had 128 pencils. It got 50 more pencils on Monday and sold 76 pencils on Tuesday. How many pencils does the store have now?', '["154","254","102","52"]', '102', '128+50-76', 'First $128 + 50 = 178$ pencils. Then $178 - 76 = 102$. The choice 154 takes away 50 and adds 76, 254 adds both, and 52 forgets the 50 new pencils.', 'checked', '{"lint":[],"solve":{"answer":"102","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"128 + 50 = 178; 178 - 76 = 102.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
