INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a95d895f-7a2c-4ce0-ab4b-678e86fe2dc2', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: add or subtract first, then multiply', 'A farm stand sold 5 baskets of peaches on Saturday and 4 baskets on Sunday. Each basket holds 7 peaches. How many peaches were sold in all?', '["16","35","63","28"]', '63', '(5+4)*7', 'The stand sold $5 + 4 = 9$ baskets. At 7 peaches each, $9 \times 7 = 63$ peaches. The choice 35 counts only Saturday, 28 counts only Sunday, and 16 adds 5 + 4 + 7.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 4 = 9 baskets; 9 x 7 = 63 peaches.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
