INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f87e520e-839e-459a-b54e-547900f26531', 'NC26.3.ANR.6', 2, 'choice', 'Two-step: compare two products', 'Each of 4 boxes holds 9 pens. Each of 5 cups holds 5 pens. How many more pens are in the boxes than in the cups?', '["61","25","11","3"]', '11', '4*9-5*5', 'The boxes hold $4 \times 9 = 36$ pens and the cups hold $5 \times 5 = 25$ pens. The difference is $36 - 25 = 11$. The choice 61 adds them, 25 is just the cups, and 3 comes from 4 + 9 - 5 - 5.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boxes 4 x 9 = 36; cups 5 x 5 = 25; 36 - 25 = 11.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
