INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afc1762e-e2a3-4869-a00b-765a9537bbf8', 'NC26.3.ANR.6', 2, 'numeric', 'Two-step: "more than" and "fewer than" stories', 'A red kite has a string 35 meters long. The blue kite string is 12 meters shorter than the red one. The green kite string is 8 meters longer than the blue one. How many meters long is the green kite string?', '[]', '31', '35-12+8', 'The blue string is $35 - 12 = 23$ meters. The green string is $23 + 8 = 31$ meters.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue 35 - 12 = 23; green 23 + 8 = 31.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
