INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2323cc7e-2804-40af-ba50-7a69eb42c600', 'NC26.3.ANR.6', 2, 'numeric', 'Estimate the answer to a story', 'Theo has 62 pencils. He gives away 38 pencils and then buys 29 more. Round each number to the nearest ten. About how many pencils does Theo have now?', '[]', '50', '60-40+30', '62 rounds to 60, 38 rounds to 40 and 29 rounds to 30. The estimate is $60 - 40 + 30 = 50$ pencils.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62 -> 60, 38 -> 40, 29 -> 30; 60 - 40 + 30 = 50. (Exact 53.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
