INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('853c1f08-311f-45c5-9e02-7717f94901a6', 'NC26.3.ANR.6', 2, 'choice', 'Estimate the answer to a story', 'A library has 497 fiction books and 312 nonfiction books. It lends out 198 of them. Round each number to the nearest hundred. About how many books are left on the shelves?', '["800","600","1000","400"]', '600', '500+300-200', '497 rounds to 500, 312 rounds to 300 and 198 rounds to 200. The estimate is $500 + 300 - 200 = 600$ books. The choice 800 forgets the books lent out, and 1000 adds them instead.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"497 -> 500, 312 -> 300, 198 -> 200; 500 + 300 - 200 = 600. (Exact 611.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
