VALUES ('620bd49c-5155-427b-ae64-0b44e7552ca5', 'NC26.3.ANR.6', 2, 'numeric', 'Estimate a product by rounding', 'A garden has 7 rows with 32 plants in each row. Round 32 to the nearest ten. About how many plants are in the garden?', '[]', '210', '30*7', '32 rounds to 30. The garden has about $30 \times 7 = 210$ plants.', 'checked', '{"lint":[],"solve":{"answer":"210","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"32 -> 30; 7 x 30 = 210.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
