INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0306b508-1937-4375-94ae-d34da9f8b6aa', 'NC26.3.ANR.6', 2, 'choice', 'Check whether an answer is reasonable', 'Rosa found that $502 - 198 = 304$. To check, she rounded each number to the nearest hundred and found $500 - 200 = 300$. What can Rosa say about her answer?', '["It is not reasonable, because 304 is not equal to 300.","It is not reasonable, because the estimate should be 500.","It is reasonable, because 304 is close to the estimate of 300.","It is not reasonable, because 502 should not be rounded."]', 'It is reasonable, because 304 is close to the estimate of 300.', NULL, 'An estimate is not expected to match exactly. Since 304 is very close to the estimate of 300, Rosa''s answer is reasonable.', 'checked', '{"lint":[],"solve":{"answer":"It is reasonable, because 304 is close to the estimate of 300.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimate 500 - 200 = 300; 304 is close to 300, so the answer is reasonable. (Exact 502 - 198 = 304 is correct.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a55ae7c-daa3-426b-9edc-688fe47b3e71', 'NC26.3.ANR.6', 2, 'choice', 'Check whether an answer is reasonable', 'Which expression has an estimate of 600 when each number is rounded to the nearest hundred?', '["$198 + 405$","$349 + 148$","$782 - 118$","$551 + 149$"]', '$198 + 405$', NULL, '$198 + 405$ rounds to $200 + 400 = 600$. The others round to $300 + 100 = 400$, $800 - 100 = 700$ and $600 + 100 = 700$.', 'checked', '{"lint":[],"solve":{"answer":"$198 + 405$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"198+405 -> 200+400 = 600. 782-118 -> 800-100 = 700. 551+149 -> 600+100 = 700. 349+148 -> 300+100 = 400. Only the first gives 600.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95e3f3d8-8a4b-49ac-a79b-240a3c275587', 'NC26.3.ANR.6', 2, 'choice', 'Choose the equation or expression for a story', 'Sam has 5 boxes with 6 pencils in each box. He gets 4 more pencils. Let $p$ be the number of pencils Sam has now. Which equation matches the story?', '["$p = 5 + 6 + 4$","$p = 5 \\times 6 - 4$","$p = 5 \\times (6 + 4)$","$p = 5 \\times 6 + 4$"]', '$p = 5 \times 6 + 4$', NULL, 'The boxes hold $5 \times 6$ pencils, and he gets 4 more, so $p = 5 \times 6 + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$p = 5 \\times 6 + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 boxes of 6 = 5 x 6, plus 4 more: p = 5 x 6 + 4 (= 34).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
