INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('562d1b6b-bd39-4791-9344-fbfbd5e05bd4', 'NC26.3.ANR.6', 2, 'choice', 'Choose the equation or expression for a story', 'Mia has 30 dollars. She buys 4 books that cost 5 dollars each. Which expression shows how many dollars Mia has left?', '["$30 - 4 + 5$","$30 - 4 \\times 5$","$(30 - 4) \\times 5$","$30 + 4 \\times 5$"]', '$30 - 4 \times 5$', NULL, 'The books cost $4 \times 5$ dollars in all, and that is taken from 30: $30 - 4 \times 5$.', 'checked', '{"lint":[],"solve":{"answer":"$30 - 4 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost 4 x 5 = 20; left 30 - 20 = 10: 30 - 4 x 5 (multiplication first).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
