INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a9034fe-7702-495e-becc-a25eb4e8c374', 'NC26.3.ANR.6', 2, 'numeric', 'Find a missing amount in a two-step story', 'A shop has 7 shelves with 5 toys on each shelf, and some more toys in a box. There are 41 toys in all. How many toys are in the box?', '[]', '6', '41-7*5', 'The shelves hold $7 \times 5 = 35$ toys. The box holds $41 - 35 = 6$ toys.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 5 = 35 on shelves; 41 - 35 = 6 in the box.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
