INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a94ac3c-a7e8-4195-b071-b0389cc84d9e', 'NC26.3.ANR.6', 2, 'choice', 'Find a missing amount in a two-step story', 'Ava bought 3 packs of cards with 8 cards in each pack. Now she has 40 cards in all. How many cards did Ava have before she bought the packs?', '["64","16","29","37"]', '16', '40-3*8', 'She bought $3 \times 8 = 24$ cards, so before that she had $40 - 24 = 16$. The choice 64 adds the 24, 29 takes away 3 and 8 separately, and 37 takes away only 3.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 8 = 24 bought; 40 - 24 = 16 before.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('895cefc0-982c-46f7-918a-497ea78b90cf', 'NC26.3.ANR.6', 2, 'choice', 'Decide what to find first, or decide with the total', 'A store sold 14 red shirts and 9 blue shirts on Monday. It sold 12 shirts on Tuesday. To find how many more shirts were sold on Monday than on Tuesday, what should you find first?', '["How many blue shirts were sold","How many shirts were sold on Monday","How many shirts were sold on Tuesday","How many red shirts were sold on Tuesday"]', 'How many shirts were sold on Monday', NULL, 'Tuesday''s total (12) is already given. First find Monday''s total, $14 + 9 = 23$, and then subtract: $23 - 12 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"How many shirts were sold on Monday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First find Monday''s total: 14 + 9 = 23, then 23 - 12 = 11. Tuesday''s total (12) is already given.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6ca63fb-5984-4991-a36c-ca93175e2832', 'NC26.3.ANR.6', 2, 'numeric', 'Decide what to find first, or decide with the total', 'Dan has 5 boxes with 8 crayons in each box. He loses 7 crayons. To find how many crayons are left, Dan first finds how many crayons are in all 5 boxes. What number does he find first?', '[]', '40', '5*8', 'The first step is $5 \times 8 = 40$ crayons. Then he subtracts the 7 lost crayons to get 33.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 8 = 40 crayons in all boxes (then 40 - 7 = 33).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
