INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbf6ac78-0a8f-4f60-9f7d-7a94f18aa0db', 'NC26.3.ANR.6', 3, 'numeric', 'Two-step: add two products', 'At a carnival, a ring toss costs 3 tickets for each turn and a dart game costs 4 tickets for each turn. Jo plays the ring toss 6 times and the dart game 5 times. How many tickets does Jo use?', '[]', '38', '6*3+5*4', 'The ring toss uses $6 \times 3 = 18$ tickets. The dart game uses $5 \times 4 = 20$ tickets. In all, $18 + 20 = 38$ tickets.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 3 = 18 tickets; 5 x 4 = 20 tickets; 18 + 20 = 38.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
