INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84a25673-f514-4636-a4e2-5fb2b1bee847', 'NC26.3.ANR.6', 3, 'choice', 'Two-step: "more than" and "fewer than" stories', 'A zoo has 54 birds. It has 17 fewer reptiles than birds. How many birds and reptiles does the zoo have in all?', '["91","37","71","108"]', '91', '54+(54-17)', 'The zoo has $54 - 17 = 37$ reptiles. In all, $54 + 37 = 91$. The choice 37 is only the reptiles, 71 adds the 17 instead, and 108 counts the same number of reptiles as birds.', 'checked', '{"lint":[],"solve":{"answer":"91","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reptiles 54 - 17 = 37; total 54 + 37 = 91.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
