INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ca55c24-ed11-492f-a65e-32531ef70a9c', 'NC26.3.ANR.6', 3, 'numeric', 'Estimate a sum or difference by rounding', 'Round each number to the nearest hundred, then add to estimate $148 + 291 + 304$.', '[]', '700', '100+300+300', '148 rounds to 100, 291 rounds to 300 and 304 rounds to 300. The estimate is $100 + 300 + 300 = 700$.', 'checked', '{"lint":[],"solve":{"answer":"700","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"148 -> 100, 291 -> 300, 304 -> 300; 100 + 300 + 300 = 700.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
