INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f53fc5b5-4808-4659-9df7-b2a657d66680', 'NC26.3.ANR.6', 3, 'choice', 'Estimate a sum or difference by rounding', 'Which number sentence shows an estimate of $346 + 528$ made by rounding each number to the nearest hundred?', '["$350 + 530 = 880$","$300 + 530 = 830$","$300 + 500 = 800$","$400 + 500 = 900$"]', '$300 + 500 = 800$', NULL, '346 rounds to 300 (the tens digit 4 is less than 5) and 528 rounds to 500 (the tens digit 2 is less than 5). The estimate is $300 + 500 = 800$. The other choices round to the nearest ten or round 346 up.', 'checked', '{"lint":[],"solve":{"answer":"$300 + 500 = 800$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"346 -> 300, 528 -> 500; 300 + 500 = 800.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46379dbe-fc86-4f4c-b614-3d1b203bb279', 'NC26.3.ANR.6', 3, 'numeric', 'Estimate the answer to a story', 'A truck carries 304 boxes. It drops off 98 boxes at the first stop and 107 boxes at the second stop. Round each number to the nearest hundred. About how many boxes are still on the truck?', '[]', '100', '300-100-100', '304 rounds to 300, 98 rounds to 100 and 107 rounds to 100. The estimate is $300 - 100 - 100 = 100$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"304 -> 300, 98 -> 100, 107 -> 100; 300 - 100 - 100 = 100. (Exact 99.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42e72acf-25c3-492f-9ced-9453a9db7d13', 'NC26.3.ANR.6', 3, 'choice', 'Estimate the answer to a story', 'A farm picked 386 apples on Monday and 214 apples on Tuesday. It packed 290 apples into boxes. Round each number to the nearest ten. About how many apples are not packed yet?', '["300","600","310","910"]', '310', '390+210-290', '386 rounds to 390, 214 rounds to 210 and 290 stays 290. The estimate is $390 + 210 - 290 = 310$. The choice 300 rounds to the nearest hundred instead, 600 forgets the packed apples, and 910 adds them.', 'checked', '{"lint":[],"solve":{"answer":"310","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nearest ten: 386 -> 390, 214 -> 210, 290 -> 290; 390 + 210 - 290 = 310. (Exact is also 310; nearest hundred would give 300.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d6e5353-b0a1-4eb3-9187-8d521ced4883', 'NC26.3.ANR.6', 3, 'numeric', 'Estimate a product by rounding', 'A group has 100 dollars. Each ticket costs 19 dollars, and the group buys 4 tickets. Round 19 to the nearest ten. About how many dollars does the group have left?', '[]', '20', '100-4*20', '19 rounds to 20. Four tickets cost about $4 \times 20 = 80$ dollars. The group has about $100 - 80 = 20$ dollars left.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"19 -> 20; 4 x 20 = 80; 100 - 80 = 20. (Exact 24.)","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
