INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a7bfa4d-4671-4118-a5c2-6a517234324e', 'NC26.3.ANR.6', 3, 'choice', 'Check whether an answer is reasonable', 'Without finding exact answers, which expression has an answer closest to 400?', '["$52 \\times 4$","$19 \\times 4$","$25 \\times 4$","$98 \\times 4$"]', '$98 \times 4$', NULL, 'Round each number: $98 \times 4$ is about $100 \times 4 = 400$. The others are about $50 \times 4 = 200$, $20 \times 4 = 80$ and $25 \times 4 = 100$, which are much farther from 400.', 'checked', '{"lint":[],"solve":{"answer":"$98 \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25x4 = 100, 52x4 is about 200, 19x4 is about 80, 98x4 is about 100x4 = 400. Closest: 98 x 4.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05fbbcb2-d4a3-4f70-9b91-168e8fc01e41', 'NC26.3.ANR.6', 3, 'choice', 'Choose the equation or expression for a story', 'Jo has 3 bags with 8 marbles in each bag. He gives away $g$ marbles and has 17 marbles left. Which equation matches the story?', '["$3 + 8 - g = 17$","$3 \\times 8 + g = 17$","$3 \\times 8 - g = 17$","$8 - 3 \\times g = 17$"]', '$3 \times 8 - g = 17$', NULL, 'Jo starts with $3 \times 8$ marbles, gives away $g$, and has 17 left: $3 \times 8 - g = 17$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 8 - g = 17$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 8 = 24 marbles, gives away g, 17 left: 3 x 8 - g = 17 (g = 7).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
