INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2685f38-c4b0-4b7e-a6b4-4d4a2e6f58f7', 'NC26.3.ANR.6', 3, 'choice', 'Choose the equation or expression for a story', 'Which story matches the expression $4 \times 6 - 5$?', '["Four bags hold 6 apples each, and 5 more apples are added.","Four bags hold 5 apples each, and then 6 apples are eaten.","Four bags hold 6 apples each, and 5 more bags are added.","Four bags hold 6 apples each, and then 5 apples are eaten."]', 'Four bags hold 6 apples each, and then 5 apples are eaten.', NULL, '$4 \times 6$ is 4 bags of 6 apples, and subtracting 5 means 5 apples are taken away or eaten.', 'checked', '{"lint":[],"solve":{"answer":"Four bags hold 6 apples each, and then 5 apples are eaten.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = four bags of 6; - 5 = five apples taken away (eaten).","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
