INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94c34b6c-7a89-4804-a398-2b204561d353', 'NC26.3.ANR.6', 3, 'numeric', 'Find a missing amount in a two-step story', 'Nate had 52 dollars. He bought a hat for 18 dollars and a book. Now he has 9 dollars left. How many dollars did the book cost?', '[]', '25', '52-18-9', 'After the hat Nate had $52 - 18 = 34$ dollars. He has 9 dollars left, so the book cost $34 - 9 = 25$ dollars. Check: $18 + 25 + 9 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spent 52 - 9 = 43; book 43 - 18 = 25. Check: 52 - 18 - 25 = 9.","run_id":"claude-code","at":"2026-10-17T19:23:45.733Z"}}', 'ai', NULL, NULL)
