VALUES ('4e1ba0d4-5509-470b-ab7c-98018a669bc5', 'NC26.3.ANR.7', 1, 'choice', 'A whole as a fraction, and fractions equal to whole numbers', 'Which fraction is equal to 1 whole?', '["$\\frac{1}{4}$","$\\frac{4}{8}$","$\\frac{4}{4}$","$\\frac{3}{4}$"]', '$\frac{4}{4}$', NULL, 'When the numerator and denominator are the same, all the parts are counted, so $\frac{4}{4} = 1$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerator equals denominator: 4/4 = 1. Others are less than 1.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
