INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f27e5e49-fbd8-418e-9c0b-68870c6ae98b', 'NC26.3.ANR.7', 1, 'numeric', 'Equivalent fractions: find the missing number', 'Sam colors 1 of the 2 equal parts of a bar. Ana has a bar of the same size that is cut into 4 equal parts. How many of Ana''s parts must she color to color the same amount as Sam?', '[]', '2', '4/2', 'One half equals two fourths, so $\frac{1}{2} = \frac{2}{4}$. Ana must color 2 of her parts.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 2/4, so Ana colors 2 parts.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
