VALUES ('2eb18c9b-8ea2-4644-bef1-a8297a47fe24', 'NC26.3.ANR.7', 1, 'choice', 'Equivalent fractions: find the missing number', 'Which fraction is equal to $\frac{1}{2}$?', '["$\\frac{1}{4}$","$\\frac{2}{3}$","$\\frac{3}{8}$","$\\frac{4}{8}$"]', '$\frac{4}{8}$', NULL, 'Half of 8 equal parts is 4 parts, so $\frac{1}{2} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2 (4 is half of 8). 2/3, 3/8, 1/4 are not.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
