INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90b9c1fc-432c-4643-a1fb-a38d190bdfb3', 'NC26.3.ANR.7', 1, 'choice', 'Recognize equal fractions', 'Two bars are the same size. Bar A has 2 of its 4 equal parts colored. Bar B has 1 of its 2 equal parts colored. Which statement is true?', '["The same amount of each bar is colored.","More of Bar A is colored.","More of Bar B is colored.","The bars cannot be compared."]', 'The same amount of each bar is colored.', NULL, 'Two fourths and one half name the same amount: $\frac{2}{4} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"The same amount of each bar is colored.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bar A 2/4 = 1/2; Bar B 1/2. Same amount.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
