INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f537be8f-4733-40e6-aae5-056143c5e692', 'NC26.3.ANR.7', 1, 'numeric', 'Compare fractions with the same denominator', 'Lee read $\frac{5}{6}$ of her book. Jo read $\frac{2}{6}$ of his book. The two books are the same length. Write the fraction for the person who read less. Write your answer like 1/2.', '[]', '2/6', '2/6', 'Both fractions have sixths, so compare the numerators: 2 is less than 5. Jo read less, $\frac{2}{6}$ of his book.', 'checked', '{"lint":[],"solve":{"answer":"2/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Equivalent 1/3 must be accepted (compare by value).","work":"Same whole, same denominator: 2/6 < 5/6, so Jo read less: 2/6 (= 1/3).","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
