INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('827ad140-b468-4a69-a58c-79bb4c23aca2', 'NC26.3.ANR.7', 1, 'choice', 'Compare fractions with the same numerator', 'Four pizzas of the same size are cut into 2, 4, 6 and 8 equal slices. Which fraction names the biggest single slice?', '["$\\frac{1}{4}$","$\\frac{1}{6}$","$\\frac{1}{8}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, 'The fewer the equal slices, the bigger each slice is. A pizza cut into 2 slices has the biggest slices, each $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fewer equal slices of the same whole means bigger slices; 2 slices -> 1/2 is biggest.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
