VALUES ('8dd8c88d-f4da-43d2-aab2-5e5e05644371', 'NC26.3.ANR.7', 2, 'choice', 'Unit fraction: one equal part of a whole', 'Which of these fractions is a unit fraction?', '["$\\frac{1}{8}$","$\\frac{2}{3}$","$\\frac{3}{4}$","$\\frac{5}{6}$"]', '$\frac{1}{8}$', NULL, 'A unit fraction has a numerator of 1. Only $\frac{1}{8}$ has a numerator of 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A unit fraction has numerator 1: 1/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
