INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdd91aed-a3e6-4920-a549-ae79074fa5f3', 'NC26.3.ANR.7', 2, 'numeric', 'Meaning of the numerator and the denominator', 'A pie is cut into 8 equal slices. $\frac{3}{8}$ of the pie has been eaten. How many slices have not been eaten?', '[]', '5', '8-3', 'The pie has 8 slices and 3 have been eaten. The slices not eaten are $8 - 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 eaten = 3 slices; 8 - 3 = 5 not eaten.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
