INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f379ddb3-ed00-45f3-9369-7aa8c8218cd1', 'NC26.3.ANR.7', 2, 'choice', 'Meaning of the numerator and the denominator', 'A bar is cut into 6 equal parts. Kim colors 4 of them. Which fraction names the colored part?', '["$\\frac{4}{6}$","$\\frac{6}{4}$","$\\frac{2}{6}$","$\\frac{4}{2}$"]', '$\frac{4}{6}$', NULL, '4 of the 6 equal parts are colored, so the fraction is $\frac{4}{6}$. The numerator counts the colored parts and the denominator counts all the parts.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 of 6 equal parts colored: 4/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
