INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db519183-cc3e-4aa3-aa3f-395a93771325', 'NC26.3.ANR.7', 2, 'choice', 'Fraction shown by the shaded parts of a shape', 'A square is cut into 6 equal parts. 1 part is red, 2 parts are blue, and the rest are white. What fraction of the square is white?', '["$\\frac{3}{6}$","$\\frac{1}{6}$","$\\frac{2}{6}$","$\\frac{6}{3}$"]', '$\frac{3}{6}$', NULL, 'The red and blue parts are $1 + 2 = 3$ parts, so $6 - 3 = 3$ parts are white. The fraction is $\frac{3}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 - 1 - 2 = 3 white parts: 3/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f489cf4-bb63-457a-af3e-987d1b1e5243', 'NC26.3.ANR.7', 2, 'numeric', 'Fraction shown by the shaded parts of a shape', 'A garden bed is divided into 8 equal sections. Tomatoes grow in 3 sections, peppers grow in 2 sections, and the rest of the sections have beans. What fraction of the garden bed has beans? Write your answer like 1/2.', '[]', '3/8', '(8-3-2)/8', 'Tomatoes and peppers use $3 + 2 = 5$ sections, so $8 - 5 = 3$ sections have beans. The fraction is $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - 3 - 2 = 3 sections of beans: 3/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a77ab56-1bb3-4518-9ff1-ea6a6b5a65b0', 'NC26.3.ANR.7', 2, 'choice', 'Fraction shown by the shaded parts of a shape', 'A pizza is cut into 8 equal slices. Max eats 2 slices and Nia eats 3 slices. What fraction of the pizza did the two children eat in all?', '["$\\frac{5}{16}$","$\\frac{3}{8}$","$\\frac{5}{8}$","$\\frac{2}{8}$"]', '$\frac{5}{8}$', NULL, 'Together they ate $2 + 3 = 5$ of the 8 equal slices, which is $\frac{5}{8}$. The denominator stays 8 because the slices are still eighths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 = 5 slices of 8: 5/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
