INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0449b024-ab48-4bb6-88bb-a75d0d00023f', 'NC26.3.ANR.7', 2, 'choice', 'Fraction at a point on a number line', 'A number line from 0 to 1 is split into 6 equal parts. Which fraction names the point that is 4 parts from 0?', '["$\\frac{6}{4}$","$\\frac{4}{8}$","$\\frac{2}{6}$","$\\frac{4}{6}$"]', '$\frac{4}{6}$', NULL, 'Each part is $\frac{1}{6}$. A point 4 parts from 0 is at $\frac{4}{6}$. The fraction $\frac{2}{6}$ would be 2 parts from 0.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sixths; 4 parts from 0 is 4/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
