INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27d0ff9c-3189-49bf-853b-8f5f94e897e8', 'NC26.3.ANR.7', 2, 'numeric', 'Fraction at a point on a number line', 'A number line from 0 to 1 is split into 8 equal parts. A frog starts at 0 and jumps 7 parts to the right. What fraction names where the frog lands? Write your answer like 1/2.', '[]', '7/8', '7/8', 'Each part is $\frac{1}{8}$. After jumping 7 parts the frog is at $\frac{7}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"7/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eighths; 7 parts from 0 is 7/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
