INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b1e3292-3447-4308-b3ad-2eb6c1ff0cba', 'NC26.3.ANR.7', 2, 'choice', 'Fraction at a point on a number line', 'A number line from 0 to 1 is split into 6 equal parts. Which fraction names the point exactly halfway between 0 and 1?', '["$\\frac{1}{6}$","$\\frac{3}{6}$","$\\frac{4}{6}$","$\\frac{6}{3}$"]', '$\frac{3}{6}$', NULL, 'Halfway is 3 of the 6 equal parts from 0, so the point is at $\frac{3}{6}$, which is the same as one half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halfway between 0 and 1 in sixths is 3 parts: 3/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
