INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cc02d1f-100b-4ec9-833f-c187c99e9886', 'NC26.3.ANR.7', 2, 'numeric', 'Build a fraction from unit fractions', 'Mia has 7 pieces of ribbon. Each piece is $\frac{1}{8}$ of a whole ribbon. She puts all the pieces together. What fraction of a whole ribbon is that? Write your answer like 1/2.', '[]', '7/8', '7*(1/8)', '7 pieces that are each $\frac{1}{8}$ make $\frac{7}{8}$ of a whole ribbon.', 'checked', '{"lint":[],"solve":{"answer":"7/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 pieces of 1/8 = 7/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
