INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea2b0e7e-24a7-4493-b6e7-cf871ae0ce4f', 'NC26.3.ANR.7', 2, 'choice', 'Build a fraction from unit fractions', 'Which tells how $\frac{5}{6}$ is made?', '["6 parts that are each $\\frac{1}{5}$ of a whole","5 parts that are each $\\frac{1}{6}$ of a whole","5 parts that are each $\\frac{1}{5}$ of a whole","6 parts that are each $\\frac{1}{6}$ of a whole"]', '5 parts that are each $\frac{1}{6}$ of a whole', NULL, '$\frac{5}{6}$ is 5 copies of the unit fraction $\frac{1}{6}$. Six parts that are each $\frac{1}{6}$ would make a whole.', 'checked', '{"lint":[],"solve":{"answer":"5 parts that are each $\\frac{1}{6}$ of a whole","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 = 5 copies of 1/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
