INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a98e6ca-1d84-416c-bbf6-956b4ed4f356', 'NC26.3.ANR.7', 2, 'numeric', 'A whole as a fraction, and fractions equal to whole numbers', 'Each pizza is cut into 8 equal slices. The class eats 16 slices. How many whole pizzas did the class eat?', '[]', '2', '16/8', 'Each pizza has 8 slices. $16 \div 8 = 2$, so the class ate 2 pizzas. In fractions, $\frac{16}{8} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 slices per pizza; 16 = 8 + 8, so 2 whole pizzas (16/8 = 2).","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
