INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a83b094f-f347-4051-933f-fba3528549bd', 'NC26.3.ANR.7', 2, 'numeric', 'A whole as a fraction, and fractions equal to whole numbers', 'What whole number is equal to $\frac{8}{4}$?', '[]', '2', '8/4', '$\frac{8}{4}$ means 8 fourths. Every 4 fourths make 1 whole, so 8 fourths make 2 wholes.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 fourths = 4/4 + 4/4 = 2.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e53170c7-2f2f-4090-b5c5-231a914e403e', 'NC26.3.ANR.7', 2, 'choice', 'A whole as a fraction, and fractions equal to whole numbers', 'Which list has only fractions that are equal to 1?', '["$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{1}{8}$","$\\frac{2}{2}$, $\\frac{3}{4}$, $\\frac{8}{8}$","$\\frac{2}{2}$, $\\frac{3}{3}$, $\\frac{8}{8}$","$\\frac{2}{1}$, $\\frac{3}{1}$, $\\frac{8}{1}$"]', '$\frac{2}{2}$, $\frac{3}{3}$, $\frac{8}{8}$', NULL, 'A fraction equals 1 when its numerator and denominator are the same. In the first list $\frac{3}{3}$, $\frac{2}{2}$ and $\frac{8}{8}$ all do. $\frac{3}{4}$ does not, and $\frac{2}{1}$, $\frac{3}{1}$ and $\frac{8}{1}$ are 2, 3 and 8.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{2}$, $\\frac{3}{3}$, $\\frac{8}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/2, 3/3, 8/8 each equal 1. First list equals 2, 3, 8; second are unit fractions; third has 3/4.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5dd80b2-6309-4831-84be-d1f4641f48f4', 'NC26.3.ANR.7', 2, 'numeric', 'Equivalent fractions: find the missing number', 'Find the missing number: $\frac{2}{3} = \frac{\square}{6}$', '[]', '4', '2*6/3', 'Each third is cut into 2 equal parts, so 3 parts become 6 parts and 2 parts become 4 parts. So $\frac{2}{3} = \frac{4}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each third = 2 sixths; 2/3 = 4/6.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ceab16de-69e5-49b7-963b-73ebb70ac785', 'NC26.3.ANR.7', 2, 'numeric', 'Equivalent fractions: find the missing number', 'Fill in the box to complete the equal fractions: $\frac{3}{4} = \frac{6}{\square}$', '[]', '8', '6/(3/4)', 'The numerator went from 3 to 6, which is doubled, so double the denominator too: $4 \times 2 = 8$. So $\frac{3}{4} = \frac{6}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerator doubled 3 -> 6, so denominator 4 -> 8: 3/4 = 6/8.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b315ac2-d095-4da2-837a-95a0dd1a010f', 'NC26.3.ANR.7', 2, 'numeric', 'Equivalent fractions: find the missing number', 'Lia uses 2 of the 4 equal pieces of a ribbon. Sam has a ribbon of the same length cut into 8 equal pieces. How many of Sam''s pieces equal the amount Lia used?', '[]', '4', '2*8/4', 'Each of Lia''s pieces is 2 of Sam''s pieces. So 2 pieces of Lia''s equal $2 \times 2 = 4$ of Sam''s pieces, and $\frac{2}{4} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/4 = 4/8, so 4 of Sam''s pieces.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1f63bbc-7e6c-4055-b1dd-81d6da7d7a5c', 'NC26.3.ANR.7', 2, 'choice', 'Recognize equal fractions', 'Which fraction is equal to $\frac{2}{3}$?', '["$\\frac{3}{6}$","$\\frac{2}{6}$","$\\frac{4}{6}$","$\\frac{3}{4}$"]', '$\frac{4}{6}$', NULL, 'Cutting each third into 2 parts makes sixths, and 2 thirds become 4 sixths: $\frac{2}{3} = \frac{4}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6. 2/6 = 1/3, 3/6 = 1/2, 3/4 differ.","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
