INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e08ca44e-cff1-4def-930e-3d6d74048a4b', 'NC26.3.ANR.7', 2, 'choice', 'Recognize equal fractions', 'Which fraction is not equal to $\frac{1}{2}$?', '["$\\frac{2}{4}$","$\\frac{3}{8}$","$\\frac{3}{6}$","$\\frac{4}{8}$"]', '$\frac{3}{8}$', NULL, '$\frac{2}{4}$, $\frac{3}{6}$ and $\frac{4}{8}$ are each half of their whole. Half of 8 is 4, so $\frac{3}{8}$ is less than one half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8, 3/6, 2/4 all equal 1/2; 3/8 does not (1/2 = 4/8).","run_id":"claude-code","at":"2026-10-17T19:23:45.773Z"}}', 'ai', NULL, NULL)
