VALUES ('112743b5-c96d-49ac-82ac-2eec96358786', 'NC26.3.SGMR.1', 1, 'numeric', 'Points, lines and line segments', 'Maria draws 3 separate line segments on a page. How many endpoints do the 3 segments have in all?', '[]', '6', '3*2', 'Each line segment has 2 endpoints. $3 \times 2 = 6$ endpoints.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each segment has 2 endpoints; 3 x 2 = 6.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
