INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dffa022e-a6b4-4a12-95bd-9abed642d172', 'NC26.3.SGMR.1', 1, 'choice', 'Points, lines and line segments', 'Which sentence is true about a line segment?', '["It goes on forever in both directions.","It has two endpoints.","It has no length.","It always makes a square corner."]', 'It has two endpoints.', NULL, 'A line segment is a straight piece with a start and an end. Because it stops at both ends, it has two endpoints and it can be measured.', 'checked', '{"lint":[],"solve":{"answer":"It has two endpoints.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A segment has two endpoints; it has length, does not go on forever, and makes no corner.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
