INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c3fcf07-1070-4199-ae02-de2823a859a6', 'NC26.3.SGMR.1', 2, 'choice', 'Relate kinds of quadrilaterals', 'A square always has 4 right angles. Which other shape always has 4 right angles?', '["a rhombus","a trapezoid","a parallelogram","a rectangle"]', 'a rectangle', NULL, 'Every rectangle has 4 right angles. A rhombus, a trapezoid and a parallelogram can have angles that are not right angles.', 'checked', '{"lint":[],"solve":{"answer":"a rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rectangle always has 4 right angles; trapezoid, parallelogram and rhombus need not.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10a3582f-b1b6-436e-95cf-3c0cda25b5b3', 'NC26.3.SGMR.1', 2, 'choice', 'Relate kinds of quadrilaterals', 'Dana says every shape with 4 sides is a square. Which shape shows that Dana is wrong?', '["a square","a triangle","a circle","a rectangle with two long sides and two short sides"]', 'a rectangle with two long sides and two short sides', NULL, 'The shape must have 4 sides and not be a square. A rectangle with long and short sides does that. A square would fit what Dana said, and a triangle and a circle do not have 4 sides.', 'checked', '{"lint":[],"solve":{"answer":"a rectangle with two long sides and two short sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A counterexample must have 4 sides and not be a square: a rectangle with long and short sides. Circle and triangle do not have 4 sides.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('156efefd-d145-45cf-9d0f-57d1d4353fbd', 'NC26.3.SGMR.1', 3, 'choice', 'Relate kinds of quadrilaterals', 'Which statement is true?', '["Every rectangle is also a square.","Every rhombus has four right angles.","Every square is also a rectangle.","Every quadrilateral has four equal sides."]', 'Every square is also a rectangle.', NULL, 'A square has 4 sides and 4 right angles, so it is a special kind of rectangle. But a rectangle can have long and short sides, so not every rectangle is a square. A rhombus can lean, and any quadrilateral can have sides of different lengths.', 'checked', '{"lint":[],"solve":{"answer":"Every square is also a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has 4 right angles and opposite sides parallel/equal, so it is a rectangle. The other statements are false (a non-square rhombus has no right angles, a 2-by-3 rectangle is not a square, a trapezoid need not have equal sides).","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d00e2122-4f46-4042-af4d-d87772a4b9e3', 'NC26.3.SGMR.1', 3, 'choice', 'Perpendicular to a parallel pair', 'Lines A, B and C are all on one flat page. Line A is parallel to line B. Line C crosses line A and makes a right angle with it. What is true about line C and line B?', '["Line C is perpendicular to line B.","Line C is parallel to line B.","Line C is the same line as line B.","Line C makes an acute angle with line B."]', 'Line C is perpendicular to line B.', NULL, 'Parallel lines A and B lean the same way. If line C makes a square corner with line A, it makes a square corner with line B too. So line C is perpendicular to line B.', 'checked', '{"lint":[],"solve":{"answer":"Line C is perpendicular to line B.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C is perpendicular to A, and B is parallel to A, so C crosses B at a right angle too: C is perpendicular to B.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f303aac-8a84-47a9-a303-fada02d93679', 'NC26.3.SGMR.1', 3, 'numeric', 'Count right angles in three shapes', 'A page has a rectangle, a square and a rhombus that is not a square. How many right angles do the three shapes have in all?', '[]', '8', '4+4+0', 'The rectangle has 4 right angles and the square has 4. A rhombus that is not a square has no right angles. In all: 4 + 4 + 0 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 4 right angles, square 4, a rhombus that is not a square has none (one right angle would force all four). 4 + 4 + 0 = 8.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4a588ca-c7ae-4adf-b224-4c1100f07493', 'NC26.3.SGMR.1', 3, 'numeric', 'Points, lines and line segments', 'Points A, B, C and D lie in order on one straight line. How many different line segments can be named using two of these points as endpoints?', '[]', '6', '3+2+1', 'The segments are AB, AC, AD, BC, BD and CD. That is 6. A quick count is $3 + 2 + 1 = 6$: three start at A, two more start at B, and one more starts at C.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs: AB, AC, AD, BC, BD, CD = 6.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1afb8fe0-cc91-4100-a4d4-6fb50e993f79', 'NC26.3.SGMR.1', 3, 'choice', 'Points, lines and line segments', 'Which statement about lines and line segments is true?', '["You can measure the length of a whole line, but not a line segment.","You can measure both a line and a line segment.","You can measure the length of a line segment, but not of a whole line, because a line never ends.","A line segment never ends, but a line has two endpoints."]', 'You can measure the length of a line segment, but not of a whole line, because a line never ends.', NULL, 'A line segment stops at both ends, so it has a length that can be measured. A line goes on forever, so it cannot be measured.', 'checked', '{"lint":[],"solve":{"answer":"You can measure the length of a line segment, but not of a whole line, because a line never ends.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A segment has a measurable length; a line never ends, so it cannot be measured.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5554d6-0e69-4195-8da6-515d29b91c6a', 'NC26.3.SGMR.1', 3, 'choice', 'Points, lines and line segments', 'Segment XY has endpoints X and Y. Point Z is on segment XY, between X and Y. Which statement is true?', '["Segment XZ is longer than segment XY.","Segment XZ is shorter than segment XY.","Segment XZ is the same length as segment XY.","Point Z is not on segment XY."]', 'Segment XZ is shorter than segment XY.', NULL, 'Segment XZ is only a part of segment XY, so it is shorter. Z is on the segment, so "Point Z is not on segment XY" is false.', 'checked', '{"lint":[],"solve":{"answer":"Segment XZ is shorter than segment XY.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Z is strictly between X and Y, so XZ is part of XY and shorter.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03f55e31-32f6-4b31-8100-0ac18f0c8851', 'NC26.3.SGMR.1', 3, 'choice', 'Parallel lines', 'Lines p, q and r are three different lines on one flat page. Line p is parallel to line q, and line r is parallel to line q. What is true about lines p and r?', '["They are perpendicular.","They are parallel.","They cross at one point.","They make an acute angle."]', 'They are parallel.', NULL, 'Lines that are each parallel to the same line all run in the same direction. So p and r never meet: they are parallel to each other.', 'checked', '{"lint":[],"solve":{"answer":"They are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two different lines both parallel to q on one plane are parallel to each other.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93bb35b7-7130-44ae-8f18-00b7a2a02287', 'NC26.3.SGMR.1', 3, 'numeric', 'Parallel lines', 'A page shows a square, a rectangle and a trapezoid with exactly one pair of parallel sides. How many pairs of parallel sides are there in all three shapes together?', '[]', '5', '2+2+1', 'The square has 2 pairs, the rectangle has 2 pairs and the trapezoid has 1 pair. $2 + 2 + 1 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square 2 + rectangle 2 + trapezoid 1 = 5.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
