INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bd3f0f4-6a05-438a-846c-174ad7a25491', 'NC26.3.SGMR.1', 3, 'choice', 'Parallel lines', 'Which statement about a rectangle is true?', '["Opposite sides are perpendicular, and sides that meet at a corner are parallel.","All 4 sides are parallel to each other.","No sides are perpendicular.","Opposite sides are parallel, and sides that meet at a corner are perpendicular."]', 'Opposite sides are parallel, and sides that meet at a corner are perpendicular.', NULL, 'Sides across from each other never meet, so they are parallel. Sides that meet at a corner make a right angle, so they are perpendicular.', 'checked', '{"lint":[],"solve":{"answer":"Opposite sides are parallel, and sides that meet at a corner are perpendicular.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In a rectangle opposite sides are parallel and adjacent sides meet at right angles (perpendicular).","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d08f91b-c0ff-426a-beca-49600bdd3787', 'NC26.3.SGMR.1', 3, 'numeric', 'Parallel lines', 'Two parallel lines that run left to right are crossed by two parallel lines that run up and down, like the # sign. All the lines cross at square corners. The lines cross at 4 points. How many right angles are made altogether?', '[]', '16', '4*4', 'Each crossing point has 4 right angles around it. With 4 crossing points, $4 \times 4 = 16$ right angles.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each of the 4 crossing points has 4 right angles around it: 4 x 4 = 16.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19114a98-61c3-4ddb-8ba3-dc8cbd256b0c', 'NC26.3.SGMR.1', 3, 'choice', 'Perpendicular lines', 'Line a is perpendicular to line b. Line b is perpendicular to line c. The three lines are different and are on one flat page. What is true about lines a and c?', '["They are parallel.","They are perpendicular.","They cross at an acute angle.","They cross at an obtuse angle."]', 'They are parallel.', NULL, 'Line a meets line b at a square corner, and so does line c. So a and c both run across b in the same direction, and they never meet. They are parallel.', 'checked', '{"lint":[],"solve":{"answer":"They are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a and c are both perpendicular to b on one plane, so they run in the same direction and are parallel.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61ba55d2-a318-47f2-8de1-708211fdceeb', 'NC26.3.SGMR.1', 3, 'numeric', 'Perpendicular lines', 'A rectangle has 4 corners. At each corner two sides meet at a right angle. How many pairs of sides in a rectangle are perpendicular to each other?', '[]', '4', NULL, 'Each of the 4 corners is made by one pair of perpendicular sides. So there are 4 pairs.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides T, B, L, R. Perpendicular pairs meet at corners: T-L, T-R, B-L, B-R = 4 (T-B and L-R are parallel).","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca3a39f1-4f04-4f96-b81c-cfb55259d7a3', 'NC26.3.SGMR.1', 3, 'numeric', 'Perpendicular lines', 'A rhombus that is not a square has no right angles. How many pairs of its sides are perpendicular to each other?', '[]', '0', NULL, 'Sides are perpendicular only when they meet at a right angle. This rhombus has no right angles, so none of its sides are perpendicular.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent sides meet at non-right angles; opposite sides are parallel. So 0 perpendicular pairs.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
