INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6820d21d-d407-494a-a286-27b681ce4b22', 'NC26.3.SGMR.1', 3, 'choice', 'Perpendicular lines', 'Two streets cross, and one of the 4 corners they make is a right angle. What is true about the other 3 corners?', '["They are all acute angles.","Two are obtuse angles and one is acute.","They are all right angles.","They are all obtuse angles."]', 'They are all right angles.', NULL, 'If two straight lines cross at a square corner, they are perpendicular, and all 4 corners around the crossing are right angles.', 'checked', '{"lint":[],"solve":{"answer":"They are all right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"If one angle where two lines cross is right, the lines are perpendicular and all 4 angles are right angles.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ae7dbf3-6007-4f8f-bfb9-91177bfcbdd9', 'NC26.3.SGMR.1', 3, 'choice', 'Right, acute and obtuse angles', 'The hands of a clock make a square corner at 3:00 and a straight line at 6:00. What kind of angle do the hands make at 4:00?', '["an acute angle","a right angle","an obtuse angle","a straight line"]', 'an obtuse angle', NULL, 'At 4:00 the hands are farther apart than at 3:00 but not as far as at 6:00. So the angle is wider than a square corner but not a straight line: it is obtuse.', 'checked', '{"lint":[],"solve":{"answer":"an obtuse angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:00 is between 3:00 (right) and 6:00 (straight): wider than a right angle, less than straight: obtuse.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a611ae03-af68-4339-92c0-86624bf45114', 'NC26.3.SGMR.1', 3, 'choice', 'Right, acute and obtuse angles', 'At which time do the hands of a clock make an obtuse angle?', '["2:00","5:00","3:00","1:00"]', '5:00', NULL, 'At 3:00 the hands make a square corner and at 6:00 they make a straight line, so the angle at 5:00 is wider than a square corner but not straight. That is obtuse. At 1:00 and 2:00 the angle is acute.', 'checked', '{"lint":[],"solve":{"answer":"5:00","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5:00 is 5 hour-marks apart, between 3 (right) and 6 (straight): obtuse. 1:00 and 2:00 are acute; 3:00 is right.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e80215af-b07b-47aa-916d-1624b48ef63b', 'NC26.3.SGMR.1', 3, 'numeric', 'Right, acute and obtuse angles', 'Look at the hands of a clock at 12:00, at 3:00, at 6:00 and at 9:00. At how many of these four times do the hands make a right angle?', '[]', '2', NULL, 'The hands make a right angle at 3:00 and at 9:00. At 6:00 they make a straight line and at 12:00 they lie on top of each other. So 2 of the times.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12:00 hands overlap; 3:00 right; 6:00 straight; 9:00 right. Answer 2.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f5b1fa7-78c5-4375-89c6-684b500412b2', 'NC26.3.SGMR.1', 3, 'numeric', 'Right angles in shapes', 'A page shows 1 square, 2 rectangles and 1 triangle that has one right angle. How many right angles are there in all four shapes?', '[]', '13', '4+2*4+1', 'The square has 4 right angles. The 2 rectangles have $2 \times 4 = 8$. The triangle has 1. $4 + 8 + 1 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square 4 + 2 rectangles x 4 = 8 + right triangle 1 = 13.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99b9a0e6-8033-4f7a-9be0-5277ef5c036e', 'NC26.3.SGMR.1', 3, 'numeric', 'Right angles in shapes', 'Rina draws a rectangle. She cuts it into 2 smaller rectangles with one straight cut from the middle of the top side to the middle of the bottom side. How many right angles do the 2 smaller rectangles have in all?', '[]', '8', '2*4', 'The cut makes 2 rectangles. Each has 4 right angles. $2 \times 4 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A vertical cut from midpoint of top to midpoint of bottom is perpendicular to both, giving 2 rectangles with 4 right angles each: 8.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cd58e81-5efe-4a24-a392-c6382de6de20', 'NC26.3.SGMR.1', 3, 'choice', 'Sides, corners and parallel sides of quadrilaterals', 'How are a rectangle and a rhombus alike?', '["Both have four right angles.","Both have two pairs of parallel sides.","Both have four sides of equal length.","Both have exactly one pair of parallel sides."]', 'Both have two pairs of parallel sides.', NULL, 'A rectangle and a rhombus each have opposite sides that are parallel, so each has 2 pairs. A rectangle does not need equal sides, and a rhombus does not need right angles.', 'checked', '{"lint":[],"solve":{"answer":"Both have two pairs of parallel sides.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rectangle and rhombus are parallelograms: two pairs of parallel sides. Not both have equal sides or right angles.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fb14612-ce98-4a9e-9943-91e340fc92f6', 'NC26.3.SGMR.1', 3, 'numeric', 'Sides, corners and parallel sides of quadrilaterals', 'Maya has a square, a rectangle, a rhombus and a trapezoid that has exactly one pair of parallel sides. How many of the 4 shapes have two pairs of parallel sides?', '[]', '3', NULL, 'The square, the rectangle and the rhombus each have 2 pairs of parallel sides. The trapezoid has only 1 pair. So 3 shapes.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, rectangle, rhombus have 2 pairs each; the trapezoid has 1. Answer 3.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b3e9f80-2358-4b53-a61b-bc5e90070ae6', 'NC26.3.SGMR.1', 3, 'numeric', 'Sides, corners and parallel sides of quadrilaterals', 'Maya has a square, a rectangle, a rhombus and a trapezoid. How many of these 4 shapes ALWAYS have four right angles?', '[]', '2', NULL, 'Every square and every rectangle has 4 right angles. A rhombus and a trapezoid can have angles that are not right angles. So 2 shapes always do.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square and rectangle always have 4 right angles; rhombus and trapezoid not always. Answer 2.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
