INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('833e07d4-c8c0-44eb-9d97-e124c9c6a3bf', 'NC26.3.SGMR.1', 3, 'numeric', 'Sides, corners and parallel sides of quadrilaterals', 'A rhombus has one side that is 9 centimeters long. A rectangle has two sides of 9 centimeters and two sides of 4 centimeters. How many of the 8 sides of these two shapes are 9 centimeters long?', '[]', '6', '4+2', 'All 4 sides of a rhombus are equal, so all 4 are 9 centimeters long. The rectangle has 2 sides of 9 centimeters. $4 + 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rhombus: all 4 sides 9 cm. Rectangle: 2 sides 9 cm. 4 + 2 = 6.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
