INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4758a45a-8f23-491d-a1df-5007637511a1', 'NC26.3.SGMR.1', 3, 'choice', 'Sides, corners and parallel sides of quadrilaterals', 'How is a square different from a rectangle that is not a square?', '["A square has 4 right angles, but the other rectangle does not.","The other rectangle has parallel sides, but a square does not.","A square has 3 sides, but the other rectangle has 4.","A square has 4 equal sides, but the sides of the other rectangle are not all equal."]', 'A square has 4 equal sides, but the sides of the other rectangle are not all equal.', NULL, 'Both shapes have 4 right angles, 4 sides and two pairs of parallel sides. The difference is that every side of a square is the same length.', 'checked', '{"lint":[],"solve":{"answer":"A square has 4 equal sides, but the sides of the other rectangle are not all equal.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both have 4 right angles and parallel sides; the difference is a square''s 4 equal sides.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a9ec601-f103-47ca-9bf1-de61c857a1cc', 'NC26.3.SGMR.1', 3, 'choice', 'Identify a quadrilateral from its features', 'A quadrilateral has 4 sides of equal length. Which of these must also be true?', '["It has 4 right angles.","It has exactly one pair of parallel sides.","Its opposite sides are parallel.","It has 2 acute angles."]', 'Its opposite sides are parallel.', NULL, 'A quadrilateral with 4 equal sides is a rhombus (a square is one kind), and the opposite sides of a rhombus are parallel. It may or may not have right angles, and it never has just one pair of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Its opposite sides are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides = rhombus, whose opposite sides are always parallel. Right angles only if square; acute angles fail for a square; it has 2 pairs, not one.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af01a555-c35f-4509-a121-0267209ab203', 'NC26.3.SGMR.1', 3, 'choice', 'Identify a quadrilateral from its features', 'Which quadrilateral could have 2 acute angles and 2 obtuse angles, but no right angles?', '["a rhombus that is not a square","a rectangle","a square","a triangle"]', 'a rhombus that is not a square', NULL, 'A rectangle and a square have only right angles. A triangle has only 3 angles. A rhombus that is not a square has two narrow angles and two wide angles.', 'checked', '{"lint":[],"solve":{"answer":"a rhombus that is not a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A non-square rhombus has 2 acute and 2 obtuse angles. Square and rectangle have right angles; a triangle is not a quadrilateral.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8729b4c-99c5-4b39-ba09-0688f97ab3e6', 'NC26.3.SGMR.1', 3, 'choice', 'Identify a quadrilateral from its features', 'Ivy describes a quadrilateral: "Opposite sides are parallel, I have 4 right angles, and my sides are not all equal." Which quadrilateral is it?', '["a square","a rectangle that is not a square","a rhombus that is not a square","a trapezoid with exactly one pair of parallel sides"]', 'a rectangle that is not a square', NULL, 'Four right angles and two pairs of parallel sides make a rectangle. The sides are not all equal, so it is not a square. A rhombus has no right angles here, and a trapezoid has one pair of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"a rectangle that is not a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides parallel, 4 right angles, sides not all equal: a rectangle that is not a square.","run_id":"claude-code","at":"2026-10-17T19:22:21.444Z"}}', 'ai', NULL, NULL)
