INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e0b550e-1f5b-4bfb-b3d1-88ce5bcc1f51', 'NC26.3.SGMR.3', 1, 'choice', 'Area or perimeter: which to find, and which units', 'Which unit would you use to measure the perimeter of a rectangular rug?', '["square feet","square inches","gallons","feet"]', 'feet', NULL, 'Perimeter is a length, so it is measured in units of length such as feet. Square units measure area.', 'checked', '{"lint":[],"solve":{"answer":"feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter is a length, measured in linear units: feet.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
