INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eebed060-b9b7-4291-995d-f7d8252db9b5', 'NC26.3.SGMR.3', 2, 'choice', 'Area of a shape split into rectangles', 'A rectangle 8 units long and 7 units wide is split into a part that is 8 by 4 and a part that is 8 by 3. Which expression gives the area of the whole rectangle?', '["$8 \\times 4 + 8 \\times 3$","$8 \\times 4 \\times 3$","$8 + 4 + 8 + 3$","$8 \\times 4 + 3$"]', '$8 \times 4 + 8 \times 3$', NULL, 'The area of the whole is the sum of the areas of the two parts: $8 \times 4 + 8 \times 3 = 32 + 24 = 56$, which is also $8 \times 7$.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times 4 + 8 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = sum of parts = 8 x 4 + 8 x 3 = 32 + 24 = 56 = 8 x 7.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
