INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48c8c16b-2a08-4982-943f-e90c3cdeb4b3', 'NC26.3.SGMR.3', 2, 'numeric', 'Missing side length from the perimeter', 'A pentagon has a perimeter of 40 centimeters. Four of its sides are 6, 9, 7 and 8 centimeters long. How many centimeters long is the fifth side?', '[]', '10', '40-6-9-7-8', 'The four known sides total $6 + 9 + 7 + 8 = 30$ centimeters. The fifth side is $40 - 30 = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 9 + 7 + 8 = 30; 40 - 30 = 10 cm.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
