INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e074712-583e-4a3c-a59d-138073d928cc', 'NC26.3.SGMR.3', 2, 'choice', 'Area or perimeter: which to find, and which units', 'A rectangular poster is 4 feet by 3 feet. Rosa puts a wooden frame around its edges. Which tells how much wood the frame needs?', '["12 square feet","14 feet","7 feet","12 feet"]', '14 feet', NULL, 'The frame goes around the edge, so we need the perimeter: $4 + 3 + 4 + 3 = 14$ feet. The choice 12 square feet is the area of the poster.', 'checked', '{"lint":[],"solve":{"answer":"14 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Frame goes around: perimeter = 4 + 3 + 4 + 3 = 14 feet. 12 square feet is the area.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
