INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e29ffc3e-f311-4199-917c-87b415374efa', 'NC26.3.SGMR.3', 2, 'choice', 'Area or perimeter: which to find, and which units', 'Which measurement needs square units?', '["the perimeter of a poster","the length of a fence","the height of a door","the area of a poster"]', 'the area of a poster', NULL, 'Area counts the unit squares that cover a surface, so it is written in square units. Perimeter, the length of a fence and a height are all lengths.', 'checked', '{"lint":[],"solve":{"answer":"the area of a poster","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area is measured in square units; the others are lengths.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
