INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4dbe1e1d-9b4b-47b7-9cd7-01633f212ac1', 'NC26.3.SGMR.3', 2, 'choice', 'Area or perimeter: which to find, and which units', 'A cloth cover for a rectangular table is 5 feet by 3 feet, and ribbon is sewn along its whole edge. Which question is answered by finding the AREA of the cover?', '["How much ribbon goes along the edge?","How long is the longest side?","How much cloth is the cover made from?","How far is it around the cover?"]', 'How much cloth is the cover made from?', NULL, 'The amount of cloth is the flat space the cover takes up, which is its area: $5 \times 3 = 15$ square feet. The other questions are about lengths or the distance around.', 'checked', '{"lint":[],"solve":{"answer":"How much cloth is the cover made from?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area tells how much surface the cloth covers: how much cloth. Ribbon/around are perimeter; longest side is a length.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c21b420-60c4-4073-b619-72ce9b8b7c95', 'NC26.3.SGMR.3', 2, 'choice', 'Area and perimeter together', 'Rectangle A is 8 units by 3 units. Rectangle B is 6 units by 4 units. Which statement is true?', '["They have the same area, but A has the longer perimeter","They have the same area and the same perimeter","A has the greater area and the longer perimeter","B has the greater area and the longer perimeter"]', 'They have the same area, but A has the longer perimeter', NULL, 'Both have an area of 24 square units ($8 \times 3$ and $6 \times 4$). Rectangle A has a perimeter of 22 units and Rectangle B has 20 units.', 'checked', '{"lint":[],"solve":{"answer":"They have the same area, but A has the longer perimeter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: area 24, perimeter 22. B: area 24, perimeter 20. Same area, A longer perimeter.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
