INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e267454-0b39-47e7-9cce-fc8b7f77b855', 'NC26.3.SGMR.3', 2, 'choice', 'Area and perimeter together', 'Which pair of rectangles has the same area?', '["a 3 by 8 rectangle and a 5 by 5 rectangle","a 2 by 12 rectangle and a 6 by 4 rectangle","a 9 by 4 rectangle and a 7 by 5 rectangle","a 10 by 3 rectangle and a 6 by 6 rectangle"]', 'a 2 by 12 rectangle and a 6 by 4 rectangle', NULL, '$2 \times 12 = 24$ and $6 \times 4 = 24$. The other pairs have areas 24 and 25, 36 and 35, and 30 and 36.', 'checked', '{"lint":[],"solve":{"answer":"a 2 by 12 rectangle and a 6 by 4 rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x12=24 & 6x4=24 (same). 30 vs 36; 24 vs 25; 36 vs 35.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
