INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb1346d7-8f38-4837-8a98-2b1180ac602f', 'NC26.3.SGMR.3', 3, 'numeric', 'Area by tiling with unit squares', 'Dev covers a rectangle with 3 rows of 8 unit squares. Then he adds 2 more rows of 8 unit squares below, with no gaps. How many unit squares cover the rectangle now?', '[]', '40', '3*8+2*8', 'There are now $3 + 2 = 5$ rows with 8 squares in each row, so $5 \times 8 = 40$ unit squares. (Or $24 + 16 = 40$.)', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2 = 5 rows of 8: 5 x 8 = 40 (or 24 + 16).","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
