INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a73b281-8d7b-45a8-a4a1-fc3ad7c6f208', 'NC26.3.SGMR.3', 3, 'numeric', 'Area by tiling with unit squares', 'Rectangle A is covered by 5 rows with 4 unit squares in each row. Rectangle B is covered by 3 rows with 7 unit squares in each row. How many more unit squares cover Rectangle B than Rectangle A?', '[]', '1', '3*7-5*4', 'Rectangle A uses $5 \times 4 = 20$ squares. Rectangle B uses $3 \times 7 = 21$ squares. Rectangle B uses $21 - 20 = 1$ more square.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5 x 4 = 20. B: 3 x 7 = 21. 21 - 20 = 1.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
