INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6f6f49a-06db-4519-a53c-cf6bdb0e251d', 'NC26.3.SGMR.3', 3, 'numeric', 'Missing side length from the area', 'A square mirror has an area of 81 square inches. How many inches long is each side of the mirror?', '[]', '9', NULL, 'All sides of a square are equal, so we need a number that times itself is 81. $9 \times 9 = 81$, so each side is 9 inches.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s x s = 81, s = 9 inches.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
