INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c5fbf88-a901-4cfb-b6b5-a4a3f014e86c', 'NC26.3.SGMR.3', 3, 'choice', 'Area of a shape split into rectangles', 'A flag is 6 inches tall and 10 inches wide. A blue stripe along the left side is 6 inches tall and 4 inches wide. The rest of the flag is red. What is the area of the red part in square inches?', '["60","24","36","16"]', '36', '6*(10-4)', 'The red part is a rectangle 6 inches tall and $10 - 4 = 6$ inches wide, so its area is $6 \times 6 = 36$ square inches. The choice 60 is the whole flag and 24 is the blue stripe.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flag 6 x 10 = 60. Blue 6 x 4 = 24. Red = 60 - 24 = 36 (6 by 6).","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
