INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58348c4a-79a6-41b0-a8f2-78a917b1ec52', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a shape split into rectangles', 'A playground has three rectangular parts that do not overlap. The sand area is 5 meters by 4 meters, the grass area is 6 meters by 3 meters, and the court is 4 meters by 2 meters. What is the total area of the playground in square meters?', '[]', '46', '5*4+6*3+4*2', 'Sand: $5 \times 4 = 20$. Grass: $6 \times 3 = 18$. Court: $4 \times 2 = 8$. Total: $20 + 18 + 8 = 46$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x4=20, 6x3=18, 4x2=8; 20 + 18 + 8 = 46.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
