INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efc8e74d-6f23-467a-9765-e9cf59a616c7', 'NC26.3.SGMR.3', 3, 'choice', 'Area of a shape split into rectangles', 'An L-shaped patio is made of a rectangle that is 9 feet by 2 feet and a rectangle that is 4 feet by 3 feet. The two rectangles touch along one side and do not overlap. What is the area of the patio in square feet?', '["18","36","27","30"]', '30', '9*2+4*3', 'The first rectangle has area $9 \times 2 = 18$ square feet. The second has area $4 \times 3 = 12$ square feet. Together: $18 + 12 = 30$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 2 = 18, 4 x 3 = 12; 18 + 12 = 30.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f7b0184-df05-44ea-b4f0-c4013c77f0e1', 'NC26.3.SGMR.3', 3, 'numeric', 'Area of a shape split into rectangles', 'A board is 9 inches long and 7 inches wide. Mia saws it across into three pieces that are each 9 inches long. Two of the pieces are 2 inches wide and 3 inches wide. What is the area of the third piece in square inches?', '[]', '18', '9*7-9*2-9*3', 'The third piece is $7 - 2 - 3 = 2$ inches wide, so its area is $9 \times 2 = 18$ square inches. (Check: $63 - 18 - 27 = 18$.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Widths add to 7: third = 7 - 2 - 3 = 2 in. Area = 9 x 2 = 18 (check 63 - 18 - 27 = 18).","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d4e2c6a-f803-46bc-86c6-d97738f4f3c5', 'NC26.3.SGMR.3', 3, 'choice', 'Perimeter of a polygon (adding all the sides)', 'A field has five sides that are 14 meters, 9 meters, 12 meters, 8 meters and 17 meters long. What is the perimeter of the field in meters?', '["46","51","43","60"]', '60', '14+9+12+8+17', 'Add all five sides: $14 + 9 + 12 + 8 + 17 = 60$ meters. Each other choice leaves out one side.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 + 9 + 12 + 8 + 17 = 60 meters.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
