INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d28c90d-09a4-4ba6-849e-083ef8e03c34', 'NC26.3.SGMR.3', 3, 'choice', 'Perimeter of a polygon (adding all the sides)', 'A rectangle is 3 times as long as it is wide. Its width is 4 centimeters. What is its perimeter in centimeters?', '["32","16","48","22"]', '32', '2*(3*4+4)', 'The length is $3 \times 4 = 12$ centimeters. The perimeter is $12 + 4 + 12 + 4 = 32$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 4, length 3 x 4 = 12. Perimeter = 12 + 4 + 12 + 4 = 32 cm.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
