INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2be68729-19e1-4905-a827-35595617a599', 'NC26.3.SGMR.3', 3, 'numeric', 'Perimeter of a polygon (adding all the sides)', 'Gia walks 3 times around a square block. Each side of the block is 40 meters long. How many meters does she walk in all?', '[]', '480', '3*4*40', 'One trip around is $4 \times 40 = 160$ meters. Three trips are $3 \times 160 = 480$ meters.', 'checked', '{"lint":[],"solve":{"answer":"480","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Once around = 4 x 40 = 160 m. Three times = 3 x 160 = 480 m.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
