INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89d79c04-0736-4c4e-8ea4-90b57afa246a', 'NC26.3.SGMR.3', 3, 'choice', 'Missing side length from the perimeter', 'A rectangular field has a perimeter of 38 yards. Its width is 7 yards. How many yards long is the field?', '["12","31","24","19"]', '12', '(38-2*7)/2', 'The two widths total $2 \times 7 = 14$ yards, which leaves $38 - 14 = 24$ yards for the two lengths. One length is $24 \div 2 = 12$ yards.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 38 / 2 = 19; length = 19 - 7 = 12 yards.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
