INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc11214d-5c99-4776-b508-476fe6dda9be', 'NC26.3.SGMR.3', 3, 'choice', 'Missing side length from the perimeter', 'A triangle has two sides of equal length. Its third side is 6 centimeters long and its perimeter is 26 centimeters. How many centimeters long is each of the two equal sides?', '["20","13","32","10"]', '10', '(26-6)/2', 'The two equal sides share $26 - 6 = 20$ centimeters, so each is $20 \div 2 = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26 - 6 = 20 for the two equal sides; 20 / 2 = 10 cm.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
