INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('deccc997-a09d-41e2-b7fd-45363c979049', 'NC26.3.SGMR.3', 3, 'numeric', 'Missing side length from the perimeter', 'A square has sides of 7 centimeters. A rectangle has the same perimeter as the square and is 9 centimeters long. How many centimeters wide is the rectangle?', '[]', '5', '(4*7-2*9)/2', 'The square''s perimeter is $4 \times 7 = 28$ centimeters. The rectangle''s two lengths take $2 \times 9 = 18$, leaving $28 - 18 = 10$ for the two widths. Each width is $10 \div 2 = 5$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square perimeter 4 x 7 = 28. Rectangle: length + width = 14; width = 14 - 9 = 5 cm.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
