INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79b530a3-2a1f-4792-9bf5-181fcdef18f4', 'NC26.3.SGMR.3', 3, 'numeric', 'Missing side length from the perimeter', 'A four-sided shape has a perimeter of 46 units. Two of its sides are each 11 units long. The other two sides are equal in length. How many units long is each of the other two sides?', '[]', '12', '(46-2*11)/2', 'The two sides of 11 take $2 \times 11 = 22$ units, leaving $46 - 22 = 24$ units for the other two sides. Each is $24 \div 2 = 12$ units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"46 - 11 - 11 = 24; 24 / 2 = 12 units.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
