INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc71c2fd-c2f1-4391-a15f-41f424ae9ab6', 'NC26.3.SGMR.3', 3, 'choice', 'Missing side length from the perimeter', 'A rectangle has a perimeter of 22 units. Which could be its length and width?', '["7 units and 5 units","6 units and 4 units","8 units and 3 units","9 units and 4 units"]', '8 units and 3 units', NULL, 'The perimeter is $2 \times (\text{length} + \text{width})$, so the length and width must add to 11. $8 + 3 = 11$. The other pairs add to 12, 10 and 13.', 'checked', '{"lint":[],"solve":{"answer":"8 units and 3 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need length + width = 11. 9+4=13, 7+5=12, 6+4=10, 8+3=11. Only 8 and 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.105Z"}}', 'ai', NULL, NULL)
