VALUES ('7c1f2121-a752-4aeb-9109-7f3acb583e8d', 'NC26.3.RD.1', 1, 'numeric', 'Compare categories: how many more or fewer', 'A graph shows that 12 students chose cats and 7 students chose dogs. How many more students chose cats than dogs?', '[]', '5', '12-7', 'Subtract to compare: $12 - 7 = 5$ more students chose cats.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 7 = 5.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
