VALUES ('8f0fa6f0-cfbb-4a59-a7e5-c1fdc4ed567b', 'NC26.3.RD.1', 1, 'numeric', 'Two-step problems from a graph or table', 'A frequency table shows 9 votes for soccer, 5 votes for tennis and 6 votes for golf. Then 3 more students vote for tennis. How many votes does tennis have now?', '[]', '8', '5+3', 'Tennis had 5 votes and gets 3 more: $5 + 3 = 8$ votes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 = 8.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
