INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffa0b28f-0463-4938-a935-f9296b28ae36', 'NC26.3.RD.1', 1, 'choice', 'Pose a question that data can answer', 'Which question has answers that can be sorted into groups like red, blue and green?', '["How many pencils do you have?","How tall are you?","What is your favorite color?","How old are you?"]', 'What is your favorite color?', NULL, 'Colors are categories. The other questions have number answers, not color groups.', 'checked', '{"lint":[],"solve":{"answer":"What is your favorite color?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Favorite color gives categories like red, blue, green; the others give numbers.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
