INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ff1e986-8b5e-4b50-ae56-5a259536d629', 'NC26.3.RD.1', 1, 'choice', 'Draw conclusions and make predictions from data', 'In a class vote, 15 of the 20 students chose dogs as their favorite pet. The class votes again next week. Which prediction makes the most sense?', '["Nobody will choose dogs","Dogs will probably get the most votes again","Exactly 20 students will choose dogs","Cats will get the most votes"]', 'Dogs will probably get the most votes again', NULL, 'Dogs got most of the votes this time, so it is reasonable to predict dogs will do well again.', 'checked', '{"lint":[],"solve":{"answer":"Dogs will probably get the most votes again","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs won strongly (15 of 20), so likely again; the others are unsupported or certain-sounding.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
