INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c3018b9-a8fa-4d00-b4b8-17ebf6273596', 'NC26.3.RD.1', 2, 'numeric', 'Read and use a frequency table', 'A frequency table shows the pets students have: dog 11, cat 8, fish 5, bird 3 and rabbit 2. Each student named one pet. How many students have either a dog or a cat?', '[]', '19', '11+8', 'Add the dog row and the cat row: $11 + 8 = 19$ students.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each student named one pet: dog 11 + cat 8 = 19.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9463573-8398-47de-afc2-1d39e9a68bfd', 'NC26.3.RD.1', 2, 'numeric', 'Read and use a frequency table', '36 students voted for a field trip. A frequency table shows that the zoo got 14 votes, the museum got 9 votes, and the park got all the rest of the votes. How many votes did the park get?', '[]', '13', '36-14-9', 'The zoo and the museum got $14 + 9 = 23$ votes. The park got the rest: $36 - 23 = 13$ votes.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 + 9 = 23; 36 - 23 = 13 votes for the park.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
