INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bdd29d0-a2a7-4f02-836b-413074d4cd5b', 'NC26.3.RD.1', 2, 'choice', 'Read and use a frequency table', 'A frequency table shows how many times each fruit was chosen: apples 7, pears 12, plums 5 and cherries 12. Which statement is true?', '["Apples were chosen the most","Pears and cherries were chosen the same number of times","Plums were chosen more often than apples","Cherries were chosen the fewest"]', 'Pears and cherries were chosen the same number of times', NULL, 'Pears and cherries both have 12, so they were chosen the same number of times. Apples (7) were not the most, plums (5) were chosen less often than apples (7), and cherries (12) were not the fewest.', 'checked', '{"lint":[],"solve":{"answer":"Pears and cherries were chosen the same number of times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pears 12 and cherries 12 are equal. Apples (7) not most; plums 5 < apples 7; cherries not fewest.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
