INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75e3face-b776-4a07-93f2-c05f278628ad', 'NC26.3.RD.1', 2, 'numeric', 'Tally marks and organizing a list of answers', 'Twelve students named the pet they own. The answers were: dog, cat, dog, fish, cat, dog, bird, cat, dog, fish, dog, cat. How many students own a cat or a fish?', '[]', '6', NULL, 'Count the cats: 4 (the 2nd, 5th, 8th and 12th answers). Count the fish: 2 (the 4th and 10th). Together: $4 + 2 = 6$ students.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dog 5, cat 4 (positions 2,5,8,12), fish 2 (4,10), bird 1; total 12. Cat or fish = 4 + 2 = 6.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
