VALUES ('51bb575c-7582-46c0-8e37-91eaa8d2c265', 'NC26.3.RD.1', 2, 'numeric', 'Read a scaled bar graph', 'A bar graph''s scale counts by 2s. The bar for green ends at 14. The bar for blue is 6 shorter than the bar for green. How many students chose blue?', '[]', '8', '14-6', 'The blue bar ends 6 below the green bar: $14 - 6 = 8$ students.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 - 6 = 8.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
