INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3789f18-e515-40f0-aee1-9b2b21cb30af', 'NC26.3.RD.1', 2, 'numeric', 'Two-step problems from a graph or table', 'A bar graph''s scale counts by 5s. The bars end at 40 for apples, 15 for pears and 20 for plums. How many more students chose apples than chose pears and plums together?', '[]', '5', '40-(15+20)', 'Pears and plums together: $15 + 20 = 35$. Apples: 40. The difference is $40 - 35 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pears + plums = 15 + 20 = 35. 40 - 35 = 5.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
