INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efb400aa-6ce7-4c06-9eac-2b86a3886df9', 'NC26.3.RD.1', 2, 'numeric', 'Two-step problems from a graph or table', 'A frequency table shows the trees planted: oak 12, maple 9, pine 15 and birch 6. How many more pine and oak trees together were planted than maple and birch trees together?', '[]', '12', '(15+12)-(9+6)', 'Pine and oak: $15 + 12 = 27$. Maple and birch: $9 + 6 = 15$. The difference is $27 - 15 = 12$ trees.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pine + oak = 27; maple + birch = 15. 27 - 15 = 12.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
