INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7defc4f-e740-4751-b0af-86dba3d36325', 'NC26.3.RD.1', 2, 'numeric', 'Make a graph: choose a scale or the number of symbols', 'Rae makes a bar graph whose scale counts by 6s: 0, 6, 12, 18, 24. The top of the bar for games should be at 18. How many lines above 0 is that?', '[]', '3', '18/6', 'Each line adds 6, so 18 is the $18 \div 6 = 3$rd line above 0.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 1st, 12 = 2nd, 18 = 3rd line. 18 / 6 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
