INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a6a5f16-4359-4e54-820f-d9254717030f', 'NC26.3.RD.1', 2, 'choice', 'Pose a question that data can answer', 'Mr. Cho wants to learn which game third graders would like to play at recess. Which is the best question to ask?', '["Which game would you like to play at recess: soccer, kickball, tag or jump rope?","Do you like games?","Is soccer the best game?","What did you eat for lunch?"]', 'Which game would you like to play at recess: soccer, kickball, tag or jump rope?', NULL, 'A good question asks about the topic and offers choices that can be counted. "Do you like games?" does not show which game, and the last question is about something else.', 'checked', '{"lint":[],"solve":{"answer":"Which game would you like to play at recess: soccer, kickball, tag or jump rope?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Best question is unbiased, on topic, with clear choices: the list of recess games.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0470ade-ee36-4eeb-a80a-7ad97a1415f8', 'NC26.3.RD.1', 2, 'choice', 'Pose a question that data can answer', 'Lia wants to find out how the students in her class get to school. Which question should she ask so the answers are easy to put in a frequency table?', '["Why do you get to school?","How do you get to school: walk, bike, bus or car?","Do you like school?","What time do you get to school?"]', 'How do you get to school: walk, bike, bus or car?', NULL, 'This question gives a few categories that Lia can tally. The other questions do not tell how students get to school.', 'checked', '{"lint":[],"solve":{"answer":"How do you get to school: walk, bike, bus or car?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Giving the categories walk, bike, bus, car makes a frequency table easy.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08e31cb9-534a-45b2-9bce-33d44dc22bf1', 'NC26.3.RD.1', 2, 'choice', 'Plan and carry out data collection', 'Ben asked his class which sport they like best and wrote down every answer. What should he do next?', '["Throw the answers away","Ask the same question again","Write his conclusion before looking at any data","Put the answers in a table or graph"]', 'Put the answers in a table or graph', NULL, 'After collecting data, the next step is to organize it in a frequency table or graph so it is easy to read. Then he can draw conclusions.', 'checked', '{"lint":[],"solve":{"answer":"Put the answers in a table or graph","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After collecting, organize the data in a table or graph.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c372e8dd-eecb-4042-a766-c77a8644a4d3', 'NC26.3.RD.1', 2, 'numeric', 'Plan and carry out data collection', 'Jo plans to ask 24 students for their favorite fruit. So far she has tallied 9 votes for apples, 7 for bananas and 5 for pears. How many more students does she still need to ask?', '[]', '3', '24-9-7-5', 'She has asked $9 + 7 + 5 = 21$ students. She still needs to ask $24 - 21 = 3$ students.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 + 7 + 5 = 21 asked. 24 - 21 = 3 more.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bb7fa6d-a904-4c2f-bb55-b90e7c381e58', 'NC26.3.RD.1', 2, 'choice', 'Draw conclusions and make predictions from data', 'A frequency table shows the pets of 30 students: dog 12, cat 9, fish 5 and bird 4. Which statement is true?', '["Dogs are the most common pet","Fish and birds together are the most common pet","Cats are the least common pet","Exactly 12 students have no pet"]', 'Dogs are the most common pet', NULL, 'Dog has the greatest number, 12. Fish and birds together make 9, which is less than 12. Birds are the least common, not cats. The table does not tell about students with no pet.', 'checked', '{"lint":[],"solve":{"answer":"Dogs are the most common pet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 12 is most. Fish + birds 9 < 12; cats 9 not least (bird 4); 12 + 9 + 5 + 4 = 30 so nobody lacks a pet.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce3aa039-ab9b-4497-bb1d-7b020332f280', 'NC26.3.RD.1', 2, 'choice', 'Draw conclusions and make predictions from data', 'A bar graph shows how students get to school: bus 24, walk 12, car 16 and bike 4. Which statement is NOT supported by the graph?', '["Twice as many students ride the bus as walk","More students come by car than by bike","More students walk than come by car","Bike is the least common way to get to school"]', 'More students walk than come by car', NULL, 'Walk is 12 and car is 16, so more students come by car than walk. The other three statements match the graph.', 'checked', '{"lint":[],"solve":{"answer":"More students walk than come by car","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bike 4 least: supported. Bus 24 = 2 x walk 12: supported. Walk 12 < car 16, so ''more walk than car'' is NOT supported. Car 16 > bike 4: supported.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5ef3a46-b6fd-42ca-be4f-884214f60216', 'NC26.3.RD.1', 2, 'numeric', 'Draw conclusions and make predictions from data', 'A bar graph shows how many students bought lunch: Monday 20, Tuesday 22, Wednesday 24 and Thursday 26. If the pattern continues, how many students will probably buy lunch on Friday?', '[]', '28', '26+2', 'The numbers go up by 2 each day, so Friday will probably be $26 + 2 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increases by 2 each day: 26 + 2 = 28.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('636dd41d-b544-4ab1-b7d5-3bf0a92ecbec', 'NC26.3.RD.1', 3, 'numeric', 'Picture graph with a half symbol', 'In a picture graph, each smiley face stands for 6 students. The row for art has 3 whole smiley faces and 1 half smiley face. How many students does the art row stand for?', '[]', '21', '3*6+6/2', '3 whole faces: $3 \times 6 = 18$ students. A half face is half of 6, which is 3 students. Total: 18 + 3 = 21 students.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 faces x 6 = 18; half face = 3; 18 + 3 = 21.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('551e9b4e-ab27-4d1d-afba-8d13a31f4db0', 'NC26.3.RD.1', 3, 'choice', 'Draw a conclusion from a frequency table', 'A class made a frequency table of how students get to school: walk 12, bus 18, car 8, bike 2. Which statement is supported by the data?', '["More students walk than ride the bus.","Most students ride a bike.","Exactly half of the students ride the bus.","More students ride the bus than walk."]', 'More students ride the bus than walk.', NULL, 'The bus has 18 and walking has 12, so more students ride the bus. Bike has the fewest (2). The class has 12 + 18 + 8 + 2 = 40 students, and half of 40 is 20, not 18.', 'checked', '{"lint":[],"solve":{"answer":"More students ride the bus than walk.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bus 18 > walk 12, so more ride the bus than walk (true). Bike 2 is fewest; total 40, half is 20, bus is 18, not half.","run_id":"claude-code","at":"2026-10-17T18:28:55.059Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c823cf2-196e-43da-b016-0f3d609a0510', 'NC26.3.RD.1', 3, 'numeric', 'Read and use a frequency table', '50 students voted for an ice cream flavor. A frequency table shows vanilla 15, chocolate 12 and strawberry 9. The rest of the students chose mint. How many more students chose vanilla than mint?', '[]', '1', '15-(50-15-12-9)', 'Vanilla, chocolate and strawberry total $15 + 12 + 9 = 36$ votes, so mint got $50 - 36 = 14$ votes. Vanilla got $15 - 14 = 1$ more vote than mint.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 12 + 9 = 36; mint = 50 - 36 = 14. Vanilla - mint = 15 - 14 = 1.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39ec83ac-25c8-44a3-a672-1d6172b4e26f', 'NC26.3.RD.1', 3, 'numeric', 'Read and use a frequency table', 'A bakery table shows how many cookies were sold: oatmeal 18, chocolate chip 27 and sugar 15. The bakery also sold 4 more peanut butter cookies than sugar cookies. How many cookies were sold in all?', '[]', '79', '18+27+15+(15+4)', 'Peanut butter cookies sold: $15 + 4 = 19$. Total: $18 + 27 + 15 + 19 = 79$ cookies.', 'checked', '{"lint":[],"solve":{"answer":"79","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Peanut butter = 15 + 4 = 19. Total = 18 + 27 + 15 + 19 = 79.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cdb55f36-2df4-4d6e-9103-c98cc2d055bb', 'NC26.3.RD.1', 3, 'choice', 'Read and use a frequency table', 'A frequency table shows votes for a class pet: hamster 13, rabbit 9, turtle 13 and gecko 7. Which statement is NOT true?', '["Hamster got more votes than any other pet","Rabbit got more votes than gecko","Hamster and turtle got the same number of votes","Gecko got the fewest votes"]', 'Hamster got more votes than any other pet', NULL, 'Hamster and turtle each got 13 votes, so hamster did not get more votes than every other pet. The other three statements are true.', 'checked', '{"lint":[],"solve":{"answer":"Hamster got more votes than any other pet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Gecko 7 fewest: true. Rabbit 9 > gecko 7: true. Hamster 13 ties turtle 13, so ''more than any other'' is false. Hamster = turtle: true.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10f775da-2038-4d66-bf44-f2db821b53e6', 'NC26.3.RD.1', 3, 'numeric', 'Tally marks and organizing a list of answers', 'A tally chart shows how many books were returned each day. Monday: 2 full groups of five and 1 mark. Tuesday: 1 full group and 4 marks. Wednesday: 3 full groups. Thursday: 2 full groups and 2 marks. Friday: 1 full group and 3 marks. How many books were returned in all?', '[]', '55', '11+9+15+12+8', 'Monday 11, Tuesday 9, Wednesday 15, Thursday 12 and Friday 8. Add them: $11 + 9 + 15 + 12 + 8 = 55$ books.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mon 11, Tue 9, Wed 15, Thu 12, Fri 8. 11 + 9 + 15 + 12 + 8 = 55.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
