INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c9024d2-fa2b-4b7e-86ab-fc8a41e6558a', 'NC26.3.RD.1', 3, 'numeric', 'Read a scaled bar graph', 'A bar graph''s scale counts by 10s. The bar for walk ends halfway between 30 and 40. The bar for bike ends halfway between 10 and 20. How many more students walk than bike?', '[]', '20', '35-15', 'Halfway between 30 and 40 is 35, and halfway between 10 and 20 is 15. The difference is $35 - 15 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walk 35, bike 15. 35 - 15 = 20.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
