INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('165f7637-c750-4932-99da-c9b4dd96f3d8', 'NC26.3.RD.1', 3, 'numeric', 'Read a scaled bar graph', 'A bar graph''s scale counts by 5s. It shows pages read: Ana''s bar ends at 35, Ben''s at 20 and Cy''s at 25. Dee read as many pages as Ben and Cy together. At what number does Dee''s bar end?', '[]', '45', '20+25', 'Dee read $20 + 25 = 45$ pages, so her bar ends at 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ben 20 + Cy 25 = 45.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
