INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cbc69a4-3ad2-449f-85e1-45afd293bf4b', 'NC26.3.RD.1', 3, 'numeric', 'Compare categories: how many more or fewer', 'A bar graph''s scale counts by 20s. The bars end at 60 for Monday, 100 for Tuesday and 80 for Wednesday. Thursday''s bar is 20 shorter than Monday''s bar. How many fewer does Thursday show than Tuesday?', '[]', '60', '100-(60-20)', 'Thursday shows $60 - 20 = 40$. Tuesday shows 100. The difference is $100 - 40 = 60$ fewer.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thursday = 60 - 20 = 40. Tuesday 100. 100 - 40 = 60.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
