INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4363cf6-e7be-4778-817e-02772d12c6b6', 'NC26.3.RD.1', 3, 'numeric', 'Two-step problems from a graph or table', 'In a picture graph, each picture stands for 3 students. The dog row has 9 pictures, the cat row has 6 pictures and the fish row has 2 pictures. How many more students chose dogs than chose cats and fish together?', '[]', '3', '9*3-(6*3+2*3)', 'Dogs: $9 \times 3 = 27$. Cats and fish: $6 \times 3 + 2 \times 3 = 18 + 6 = 24$. The difference is $27 - 24 = 3$ students.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 27; cats 18 + fish 6 = 24. 27 - 24 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89af8976-bf08-4fc0-9a7a-25ca9b2488e6', 'NC26.3.RD.1', 3, 'numeric', 'Two-step problems from a graph or table', 'A bar graph''s scale counts by 4s. The bars show books read by four teams: Reds 24, Blues 16, Greens 20 and Yellows 12. The two teams that read the most books are joined into one team. How many books did the joined team read?', '[]', '44', '24+20', 'The two highest bars are Reds (24) and Greens (20). Joined: $24 + 20 = 44$ books.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top two: Reds 24 and Greens 20. 24 + 20 = 44.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7a8e439-b7c7-4302-bf00-ab5470453199', 'NC26.3.RD.1', 3, 'choice', 'Two-step problems from a graph or table', 'A bar graph shows the number of students who bought lunch: Monday 40, Tuesday 20, Wednesday 60 and Thursday 30. Which statement is true?', '["Thursday had twice as many students as Tuesday","Wednesday had 30 more students than Monday","Tuesday had half as many students as Wednesday","Wednesday had as many students as Monday and Tuesday together"]', 'Wednesday had as many students as Monday and Tuesday together', NULL, 'Monday and Tuesday together: $40 + 20 = 60$, the same as Wednesday. Twice Tuesday is 40, not 30. Wednesday is $60 - 40 = 20$ more than Monday, not 30. Half of Wednesday is 30, not 20.', 'checked', '{"lint":[],"solve":{"answer":"Wednesday had as many students as Monday and Tuesday together","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thu 30 vs Tue 20: not twice. Wed 60 - Mon 40 = 20, not 30. Mon + Tue = 60 = Wed: true. Tue 20 is a third of Wed 60, not half.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db5ba5eb-a492-4d89-a1a3-5ea0927e0c96', 'NC26.3.RD.1', 3, 'numeric', 'Two-step problems from a graph or table', 'A bar graph''s scale counts by 5s. It shows sit-ups: Monday 15, Tuesday 25 and Wednesday 20. On Thursday Mia does as many sit-ups as on Monday and Tuesday together. On Friday she does 5 fewer than on Thursday. How many sit-ups does she do on Friday?', '[]', '35', '15+25-5', 'Thursday: $15 + 25 = 40$ sit-ups. Friday: $40 - 5 = 35$ sit-ups.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thursday = 15 + 25 = 40. Friday = 40 - 5 = 35.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b04aac4d-e43c-442a-96d6-a16d89d4f51a', 'NC26.3.RD.1', 3, 'numeric', 'Make a graph: choose a scale or the number of symbols', 'Mia draws a picture graph in which each picture stands for 9 students. Three rows need to show 18 students, 27 students and 36 students. How many pictures does she draw in all?', '[]', '9', '(18+27+36)/9', 'The rows need $18 \div 9 = 2$, $27 \div 9 = 3$ and $36 \div 9 = 4$ pictures. In all: $2 + 3 + 4 = 9$ pictures.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/9 = 2, 27/9 = 3, 36/9 = 4. 2 + 3 + 4 = 9 pictures.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93b2b4a5-8929-49cb-bf00-ed0f67323dbf', 'NC26.3.RD.1', 3, 'choice', 'Make a graph: choose a scale or the number of symbols', 'Zoe''s data are 12, 18, 30 and 24. Which bar graph scale lands exactly on every one of these numbers?', '["counting by 4s","counting by 5s","counting by 8s","counting by 6s"]', 'counting by 6s', NULL, 'All four numbers are multiples of 6, so counting by 6s (6, 12, 18, 24, 30) lands on all of them. 18 is not a multiple of 4, 12 is not a multiple of 5, and 12 is not a multiple of 8.', 'checked', '{"lint":[],"solve":{"answer":"counting by 6s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12, 18, 24, 30 are all multiples of 6. By 4s misses 18, 30; by 8s misses 12, 18, 30; by 5s misses 12, 18, 24.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7daa583b-c5de-40b8-9310-b517958e038c', 'NC26.3.RD.1', 3, 'numeric', 'Make a graph: choose a scale or the number of symbols', 'Tess makes a bar graph with a scale that counts by 5s. Her data are 15 for football, 25 for basketball and 10 for baseball. How many lines taller is the basketball bar than the baseball bar?', '[]', '3', '(25-10)/5', 'The basketball bar is $25 \div 5 = 5$ lines tall and the baseball bar is $10 \div 5 = 2$ lines tall. The basketball bar is $5 - 2 = 3$ lines taller.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Basketball 25 = 5 lines; baseball 10 = 2 lines. 5 - 2 = 3 lines.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0eb85bd9-e972-4fef-8d36-7b8c2cc1ed91', 'NC26.3.RD.1', 3, 'choice', 'Pose a question that data can answer', 'Which question is a fair way to find out the class''s favorite pizza topping?', '["Which topping do you like best: cheese, pepperoni or mushroom?","Don''t you agree that pepperoni is the best topping?","What toppings does your mom like?","Do you eat pizza?"]', 'Which topping do you like best: cheese, pepperoni or mushroom?', NULL, 'A fair question does not push people toward one answer. "Don''t you agree that pepperoni is the best topping?" pushes toward pepperoni, asking what your mom likes asks about someone else, and "Do you eat pizza?" does not ask about toppings.', 'checked', '{"lint":[],"solve":{"answer":"Which topping do you like best: cheese, pepperoni or mushroom?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fair = asks the student''s own preference, not leading: the choice of three toppings.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00228252-4a1a-42a6-8469-31bf1eabd625', 'NC26.3.RD.1', 3, 'choice', 'Pose a question that data can answer', 'Which question would give different answers from different students, so collecting data makes sense?', '["How many days are in a week?","How many sides does a triangle have?","What is 6 times 7?","How many brothers and sisters does each student in our class have?"]', 'How many brothers and sisters does each student in our class have?', NULL, 'Students can have different numbers of brothers and sisters, so data is needed. The other questions have the same answer for everyone.', 'checked', '{"lint":[],"solve":{"answer":"How many brothers and sisters does each student in our class have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only the number of siblings varies from student to student; the others have one fixed answer.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0afc23d2-8eab-4f26-b850-badda5d55ad3', 'NC26.3.RD.1', 3, 'choice', 'Plan and carry out data collection', 'Ken wants to find out what third graders eat for breakfast. Which set of categories for his table has a place for every answer and no overlap?', '["cereal, cereal with milk, eggs, toast","cereal, eggs, toast, something else","cereal, eggs","breakfast, cereal, eggs, toast"]', 'cereal, eggs, toast, something else', NULL, 'Good categories let every answer fit in exactly one row. "Something else" catches other answers. Cereal and cereal with milk overlap, and "breakfast" overlaps with everything. The list with only cereal and eggs has no row for toast.', 'checked', '{"lint":[],"solve":{"answer":"cereal, eggs, toast, something else","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''something else'' catches every other answer and the four categories do not overlap. Others overlap (cereal / cereal with milk; breakfast) or leave answers out.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ae19709-0be6-4d3b-9639-485640390c8b', 'NC26.3.RD.1', 3, 'choice', 'Plan and carry out data collection', 'Anna and Ben each want to find the favorite sport of all third graders at their school. Anna asks the 5 students on the soccer team. Ben asks every third grader to pick a sport from a list. Whose plan is better?', '["Anna''s, because soccer players know sports","Anna''s, because she asks fewer students","Ben''s, because he asks all the third graders","Both are the same"]', 'Ben''s, because he asks all the third graders', NULL, 'Ben asks the whole group he wants to know about. Anna only asks soccer players, so her results may not show what all third graders think.', 'checked', '{"lint":[],"solve":{"answer":"Ben''s, because he asks all the third graders","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Asking all third graders represents the whole group; soccer players are biased.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d91cb15e-152e-4637-9a7e-f046517edb95', 'NC26.3.RD.1', 3, 'choice', 'Plan and carry out data collection', 'A class makes a tally chart of pets with rows for dog, cat, fish and bird. One student has a rabbit. What is the best fix for the chart?', '["Count the rabbit as a cat","Leave the rabbit out","Count the rabbit twice","Add a row for rabbit or other"]', 'Add a row for rabbit or other', NULL, 'Every answer should have a row of its own. Adding a row for rabbit (or other) keeps the data true.', 'checked', '{"lint":[],"solve":{"answer":"Add a row for rabbit or other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every answer needs a place: add a rabbit (or other) row.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b135b9a0-4f8b-4e94-a726-1be48eaaeade', 'NC26.3.RD.1', 3, 'choice', 'Draw conclusions and make predictions from data', 'Sam asked 10 students at the soccer field which sport they like best. Nine said soccer. Sam says, "Most students in our school like soccer best." What is wrong with his conclusion?', '["Nine is too small a number","He asked only students at the soccer field, so his data may not show the whole school","Soccer is not a sport","He should have asked fewer students"]', 'He asked only students at the soccer field, so his data may not show the whole school', NULL, 'Students at the soccer field are more likely to like soccer. Sam did not ask a fair group of the whole school, so he cannot conclude this about all students.', 'checked', '{"lint":[],"solve":{"answer":"He asked only students at the soccer field, so his data may not show the whole school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sample (students at the soccer field) is biased and not the whole school.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ec846d0-9b1c-4e50-af8f-d60aedf0ff7a', 'NC26.3.RD.1', 3, 'numeric', 'Draw conclusions and make predictions from data', 'In a picture graph, each picture stands for 5 books. Monday has 4 pictures, Tuesday has 6 pictures and Wednesday has 8 pictures. If the pattern continues, how many books will Thursday''s row stand for?', '[]', '50', '10*5', 'The number of pictures goes up by 2 each day: 4, 6, 8, so Thursday will probably have 10 pictures. Ten pictures stand for $10 \times 5 = 50$ books.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pictures 4, 6, 8 grow by 2, so Thursday 10 pictures = 50 books (books 20, 30, 40, 50).","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48285590-c49a-4f98-bc7f-708e3f0ff59b', 'NC26.3.RD.1', 3, 'choice', 'Draw conclusions and make predictions from data', 'A bar graph shows votes for a favorite season: spring 7, summer 14, fall 9 and winter 6. Which statement is true?', '["Fall got twice as many votes as winter","Winter and spring together got more votes than summer","Summer got 7 more votes than fall","Summer got twice as many votes as spring"]', 'Summer got twice as many votes as spring', NULL, '14 is twice 7. Twice winter is 12, not 9. Winter and spring together make 13, which is less than 14. Summer is $14 - 9 = 5$ more than fall, not 7.', 'checked', '{"lint":[],"solve":{"answer":"Summer got twice as many votes as spring","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Summer - fall = 5, not 7. Summer 14 = 2 x spring 7: true. Fall 9 is not 2 x 6. Winter + spring = 13 < 14.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41fa40c6-5e0d-47fc-9471-32343921c5de', 'NC26.3.RD.1', 3, 'choice', 'Draw conclusions and make predictions from data', 'A bar graph shows how many students chose each lunch: pizza 18, salad 7 and sandwich 11. Which question can NOT be answered by looking at the graph?', '["How many more students chose pizza than salad?","Which lunch did the fewest students choose?","Why did so many students choose pizza?","How many students chose a lunch in all?"]', 'Why did so many students choose pizza?', NULL, 'The graph shows how many chose each lunch, but not the reasons. The other questions can be answered with the numbers on the graph.', 'checked', '{"lint":[],"solve":{"answer":"Why did so many students choose pizza?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The graph gives counts, not reasons: ''Why...'' cannot be answered. Total (36), difference (11) and fewest (salad) can.","run_id":"claude-code","at":"2026-10-17T19:22:45.144Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('821e58ee-a321-4f01-84f9-5eee48ef2101', 'NC26.3.RD.1', 3, 'choice', 'Show a number of students with whole and half symbols', 'In a picture graph, each circle stands for 8 students, and half a circle stands for 4 students. 28 students chose art. Which shows the row for art?', '["3 whole circles and 1 half circle","3 whole circles and 2 half circles","7 whole circles","4 whole circles"]', '3 whole circles and 1 half circle', NULL, 'Each whole circle is 8 students. 3 whole circles are 3 x 8 = 24 students, and 28 - 24 = 4 students are left. 4 students is exactly 1 half circle. So the row has 3 whole circles and 1 half circle.', 'checked', '{"lint":[],"solve":{"answer":"3 whole circles and 1 half circle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 8 = 3 remainder 4, so 3 whole circles (24) and 1 half circle (4) = 28. Others: 4 whole = 32; 7 whole = 56; 3 whole + 2 halves = 24 + 8 = 32. Only one option equals 28.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
