INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('545d739c-b7b2-499e-bbe7-55e5ac804274', 'NC26.4.ANR.1', 2, 'choice', 'Each place is ten times the place to its right', 'Which statement about the digit 5 in $55{,}120$ is true?', '["The first 5 is worth 100 times as much as the second 5.","The two 5s are worth the same amount.","The first 5 is worth 10 times as much as the second 5.","The second 5 is worth 10 times as much as the first 5."]', 'The first 5 is worth 10 times as much as the second 5.', NULL, 'The first 5 is in the ten-thousands place (50,000) and the second is in the thousands place (5,000). 50,000 is 10 times 5,000.', 'checked', '{"lint":[],"solve":{"answer":"The first 5 is worth 10 times as much as the second 5.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"55,120: first 5 = 50,000, second 5 = 5,000. 50,000 = 10 x 5,000, so the first is 10 times the second.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('879d98d0-7188-49d2-abb2-b5be947c9f06', 'NC26.4.ANR.1', 2, 'choice', 'Compare two multi-digit numbers', 'Which statement is true?', '["$72{,}406 < 72{,}046$","$72{,}406 > 72{,}046$","$72{,}406 > 72{,}640$","$72{,}406 = 72{,}460$"]', '$72{,}406 > 72{,}046$', NULL, 'The first three digits decide: 72,4 vs 72,0 means 72,406 is greater than 72,046. It is less than 72,640 and not equal to 72,460.', 'checked', '{"lint":[],"solve":{"answer":"$72{,}406 > 72{,}046$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72,406 vs 72,046: hundreds 4 > 0, so 72,406 > 72,046 (true). 72,406 = 72,460 false. 72,406 > 72,640 false (4 < 6 hundreds).","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
