INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c92f5705-7b37-41a1-8775-ce20a5267c10', 'NC26.4.ANR.1', 2, 'numeric', 'Compare two multi-digit numbers', 'Of $62{,}045$, $62{,}405$ and $62{,}054$, which number is the least?', '[]', '62045', '62045', 'All three start with 62. Next compare the hundreds: 0, 4, 0. The two with 0 hundreds are less; of those, 45 < 54. So 62,045 is the least.', 'checked', '{"lint":[],"solve":{"answer":"62045","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62,045, 62,405, 62,054: hundreds 0,4,0 -> 62,405 largest; of 62,045 and 62,054, tens 4 < 5, so 62,045 least.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
