VALUES ('4660489f-112c-4285-873e-1abe96cc53ea', 'NC26.4.ANR.1', 3, 'numeric', 'Write a number in expanded form', 'The expanded form of a number is $50{,}000 + 6{,}000 + 90 + 4$. What is the sum of the digits of the number?', '[]', '24', '5+6+0+9+4', 'The number is 56,094. Its digits are 5, 6, 0, 9 and 4, and 5 + 6 + 0 + 9 + 4 = 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50,000 + 6,000 + 90 + 4 = 56,094. Digit sum 5+6+0+9+4 = 24.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
