INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26864dc6-a9d5-485b-9ef3-4dfea4899ccf', 'NC26.4.ANR.1', 3, 'choice', 'Write a number in expanded form', 'When a number is written in expanded form, you add the values of its digits that are not zero. Which number has exactly two numbers to add?', '["12,345","40,501","76,030","30,200"]', '30,200', '30200', '30,200 = 30,000 + 200 (two parts). 12,345 has five parts, and 40,501 and 76,030 each have three.', 'checked', '{"lint":[],"solve":{"answer":"30,200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nonzero digits: 40,501 -> 4,5,1 (3); 76,030 -> 7,6,3 (3); 30,200 -> 3,2 (2); 12,345 -> 5. Only 30,200 = 30,000 + 200.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
