VALUES ('fb0732df-4384-441b-b038-e3486f2cf4f2', 'NC26.4.ANR.1', 3, 'choice', 'Number names (word form) and standard form', 'Which pair shows two names for the same number?', '["\"thirty thousand, four hundred\" and \"30,040\"","\"twelve thousand, three hundred five\" and \"12,035\"","\"eight thousand, ninety\" and \"80,090\"","\"forty-five thousand, six\" and \"45,006\""]', '"forty-five thousand, six" and "45,006"', NULL, 'Forty-five thousand, six is 45,006. The others are 30,400, 12,305 and 8,090, which do not match 30,040, 12,035 and 80,090.', 'checked', '{"lint":[],"solve":{"answer":"\"forty-five thousand, six\" and \"45,006\"","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"eight thousand, ninety = 8,090 not 80,090. forty-five thousand, six = 45,006 (match). thirty thousand, four hundred = 30,400 not 30,040. twelve thousand, three hundred five = 12,305 not 12,035.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
