INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd369d48-6323-4d50-b1fd-757e1d27ce6e', 'NC26.4.ANR.1', 3, 'numeric', 'Number names (word form) and standard form', 'What number is one more than sixty-nine thousand, nine hundred ninety-nine? Write your answer with digits.', '[]', '70000', '69999+1', 'Sixty-nine thousand, nine hundred ninety-nine is 69,999. One more is 70,000.', 'checked', '{"lint":[],"solve":{"answer":"70000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"69,999 + 1 = 70,000 (all the 9s regroup).","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
