INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ce61a7d-bb26-496a-b117-092d35d91b12', 'NC26.4.ANR.1', 3, 'choice', 'Compare two multi-digit numbers', 'The numbers $63{,}482$ and $63{,}187$ have the same digits in the first two places. Reading from the left, in which place do their digits first differ?', '["thousands","tens","ones","hundreds"]', 'hundreds', NULL, 'Ten-thousands: 6 and 6. Thousands: 3 and 3. Hundreds: 4 and 1. They first differ in the hundreds place (so 63,482 is greater).', 'checked', '{"lint":[],"solve":{"answer":"hundreds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63,482 vs 63,187: ten-thousands 6=6, thousands 3=3, hundreds 4 vs 1 differ first.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
