INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e42eac8-ab58-4420-8c1f-32cd3b205f4a', 'NC26.4.ANR.1', 3, 'choice', 'Order numbers', 'Sara has number cards $8{,}973$; $80{,}397$; $89{,}730$ and $8{,}397$. She lines them up starting with the greatest card. Which list shows her line?', '["89,730; 80,397; 8,973; 8,397","89,730; 80,397; 8,397; 8,973","8,973; 8,397; 80,397; 89,730","89,730; 8,973; 80,397; 8,397"]', '89,730; 80,397; 8,973; 8,397', NULL, 'The two 5-digit numbers come first: 89,730 > 80,397. Of the two 4-digit numbers, 8,973 > 8,397.', 'checked', '{"lint":[],"solve":{"answer":"89,730; 80,397; 8,973; 8,397","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Five-digit cards: 89,730 > 80,397. Four-digit: 8,973 > 8,397. Line: 89,730; 80,397; 8,973; 8,397.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
