INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd50d77e-26eb-424d-a601-91c6fbf931b7', 'NC26.4.ANR.1', 3, 'numeric', 'Use place value to build or find a number', 'I am a five-digit number. My ten-thousands digit is 6. My thousands digit is half of my ten-thousands digit. My hundreds digit is 0. My tens digit is 1 more than my thousands digit. My ones digit is 2 less than my ten-thousands digit. What number am I?', '[]', '63044', '60000+3000+0+40+4', 'Ten-thousands 6; thousands 3 (half of 6); hundreds 0; tens 4 (3 + 1); ones 4 (6 - 2). The number is 63,044.', 'checked', '{"lint":[],"solve":{"answer":"63044","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ten-thousands 6; thousands 6/2 = 3; hundreds 0; tens 3 + 1 = 4; ones 6 - 2 = 4. Number 63,044.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8938229-38e9-4ccc-9eb4-6dea9c6d3f6a', 'NC26.4.ANR.1', 3, 'numeric', 'Use place value to build or find a number', 'What is the least five-digit number that has a 7 in the thousands place and uses five different digits?', '[]', '17023', '17023', 'The ten-thousands digit cannot be 0, so the least choice is 1. The thousands digit is 7. Then use the least unused digits: 0 for the hundreds, 2 for the tens and 3 for the ones. The number is 17,023.', 'checked', '{"lint":[],"solve":{"answer":"17023","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ten-thousands: least nonzero digit not 7 = 1. Thousands = 7. Remaining places smallest unused digits in order: 0, 2, 3. Number 17,023 (digits 1,7,0,2,3 all different).","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4824224c-b7d5-45b0-b965-4d90197b4211', 'NC26.4.ANR.1', 3, 'choice', 'Use place value to build or find a number', 'A number is greater than $50{,}000$ and less than $60{,}000$. The digit in its thousands place is 8 and the digit in its hundreds place is 0. Which could be the number?', '["50,805","58,502","58,052","85,042"]', '58,052', '58052', 'Between 50,000 and 60,000 the first digit is 5. With thousands 8 and hundreds 0 we get 58,0__, so 58,052 fits.', 'checked', '{"lint":[],"solve":{"answer":"58,052","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Must be 5x,xxx with thousands 8 and hundreds 0: 58,0xx. 58,502 has hundreds 5; 58,052 fits; 85,042 > 60,000; 50,805 has thousands 0.","run_id":"claude-code","at":"2026-10-17T20:03:27.854Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fcf6c28-a7ec-4c98-8a50-cb349bd60250', 'NC26.4.ANR.1', 3, 'numeric', 'Value of each digit', 'The digit in the thousands place and the digit in the hundreds place of $36{,}420$ are swapped, making a new number. How much less than $36{,}420$ is the new number?', '[]', '1800', '36420-34620', 'The 6 is in the thousands place and the 4 is in the hundreds place. Swapping them gives $34{,}620$. The difference is $36{,}420 - 34{,}620 = 1{,}800$. Check by place value: the 6 loses 5,400 of value (6,000 down to 600), and the 4 gains 3,600 (400 up to 4,000), so the number drops by 1,800.', 'checked', '{"lint":[],"solve":{"answer":"1800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36,420: thousands digit 6, hundreds digit 4. Swapped: 34,620. 36,420 - 34,620 = 1,800.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f18a3e79-aedd-49ce-8576-060a69bc23dc', 'NC26.4.ANR.1', 3, 'choice', 'Number names (word form) and standard form', 'Which number is written in words as seventy thousand, three hundred two?', '["73,002","70,302","70,320","7,302"]', '70,302', '70302', 'Seventy thousand is 70,000, three hundred is 300 and two is 2. Put together, that is 70,302. The ten-thousands place holds the 7, the thousands place holds a 0, and the tens place holds a 0.', 'checked', '{"lint":[],"solve":{"answer":"70,302","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Seventy thousand = 70,000; three hundred two = 302. 70,302.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce53eeae-188f-4889-88a8-a3827547cba0', 'NC26.4.ANR.2', 1, 'numeric', 'Add two 4-digit numbers', 'What is $4{,}326 + 2{,}573$?', '[]', '6899', '4326+2573', 'Add each place, starting with the ones: 6 + 3 = 9, 2 + 7 = 9, 3 + 5 = 8, 4 + 2 = 6. No place needs regrouping, so the sum is 6,899.', 'checked', '{"lint":[],"solve":{"answer":"6899","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,326 + 2,573: ones 6+3=9, tens 2+7=9, hundreds 3+5=8, thousands 4+2=6. = 6,899.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('578ade9e-e484-4766-8e30-ce4d7ceb419a', 'NC26.4.ANR.2', 1, 'numeric', 'Subtract two 4-digit numbers', 'What is $8{,}465 - 3{,}142$?', '[]', '5323', '8465-3142', 'Subtract each place, starting with the ones: 5 - 2 = 3, 6 - 4 = 2, 4 - 1 = 3, 8 - 3 = 5. The difference is 5,323.', 'checked', '{"lint":[],"solve":{"answer":"5323","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8,465 - 3,142: ones 5-2=3, tens 6-4=2, hundreds 4-1=3, thousands 8-3=5. = 5,323.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7c47c6b-3a22-4724-8eb7-656bdbeda6ea', 'NC26.4.ANR.2', 1, 'choice', 'Add with regrouping in a word problem', 'A school collected 1,250 cans in May and 1,375 cans in June. How many cans did it collect in all?', '["2,625","2,525","2,725","2,635"]', '2,625', '2625', 'Add: 1,250 + 1,375. Ones: 0 + 5 = 5. Tens: 5 + 7 = 12, so write 2 and regroup 1 hundred. Hundreds: 2 + 3 + 1 = 6. Thousands: 1 + 1 = 2. The total is 2,625. (2,525 forgets the regrouped hundred.)', 'checked', '{"lint":[],"solve":{"answer":"2,625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,250 + 1,375 = 2,625.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
