VALUES ('e0e99834-8596-4d55-ab0d-a9febfdf0549', 'NC26.4.ANR.2', 1, 'choice', 'Add multi-digit numbers with the standard algorithm', 'Which is the sum of $6{,}250$ and $2{,}875$?', '["8,025","9,025","8,125","9,125"]', '9,125', '6250+2875', 'Ones: 0 + 5 = 5. Tens: 5 + 7 = 12, write 2 and regroup 1 hundred. Hundreds: 2 + 8 + 1 = 11, write 1 and regroup 1 thousand. Thousands: 6 + 2 + 1 = 9. The sum is 9,125.', 'checked', '{"lint":[],"solve":{"answer":"9,125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,250 + 2,875: ones 0+5=5; tens 5+7=12 (2, carry 1); hundreds 2+8+1=11 (1, carry 1); thousands 6+2+1=9. Sum 9,125.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
