INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('599c2e23-20c3-4924-8e5c-c45d20cb939b', 'NC26.4.ANR.2', 1, 'choice', 'Find and fix a mistake in a calculation', 'Dev worked out $3{,}456 + 2{,}789$ and got $5{,}245$. What mistake did he most likely make?', '["He forgot to add the 1 regrouped from the hundreds into the thousands.","He forgot to regroup the ones into the tens.","He wrote the ones digit in the tens place.","He subtracted the thousands instead of adding them."]', 'He forgot to add the 1 regrouped from the hundreds into the thousands.', NULL, 'The correct sum is 6,245. Dev''s thousands digit is 5 = 3 + 2, so he left out the 1 regrouped from the hundreds (4 + 7 + 1 = 12).', 'checked', '{"lint":[],"solve":{"answer":"He forgot to add the 1 regrouped from the hundreds into the thousands.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct: 3,456 + 2,789 = 6,245. Dev''s 5,245 is 1,000 short. Hundreds 4+7+1=12 -> carry 1 thousand; omitting it gives thousands 3+2=5. (Forgetting the ones regroup would give 6,235.)","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea64a621-2730-47ca-9cd5-64cb23e02709', 'NC26.4.ANR.2', 1, 'numeric', 'Find and fix a mistake in a calculation', 'Mia worked out $5{,}000 - 2{,}345$ and got $3{,}765$. What is the correct answer?', '[]', '2655', '5000-2345', '5,000 - 2,345 = 2,655. Check: 2,655 + 2,345 = 5,000, but 3,765 + 2,345 = 6,110.', 'checked', '{"lint":[],"solve":{"answer":"2655","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,000 - 2,345 = 2,655. Check 2,345 + 2,655 = 5,000.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
