VALUES ('9b952a2e-23a8-4729-8aa8-04956ae7aec3', 'NC26.4.ANR.2', 2, 'choice', 'Find a missing number in an addition or subtraction sentence', 'Which number goes in the box? $52{,}300 - \square = 27{,}845$', '["80,145","25,455","24,555","24,455"]', '24,455', '52300-27845', 'Subtract: 52,300 - 27,845 = 24,455. Check: 52,300 - 24,455 = 27,845.', 'checked', '{"lint":[],"solve":{"answer":"24,455","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Box = 52,300 - 27,845 = 24,455. Check 27,845 + 24,455 = 52,300.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
