INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('406d628d-d90f-4b63-8aa9-ce3ce7eda2e9', 'NC26.4.ANR.2', 2, 'choice', 'Find a missing number in an addition or subtraction sentence', 'A number increased by $18{,}450$ gives $60{,}000$. What is the number?', '["78,450","41,550","42,550","41,450"]', '41,550', '60000-18450', 'Subtract: 60,000 - 18,450 = 41,550. Check: 41,550 + 18,450 = 60,000.', 'checked', '{"lint":[],"solve":{"answer":"41,550","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + 18,450 = 60,000, so n = 60,000 - 18,450 = 41,550.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
