INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81a1904c-7acb-4588-8219-73e1ff0fc7af', 'NC26.4.ANR.2', 2, 'choice', 'Understand regrouping in the algorithm', 'Adding the hundreds in $4{,}870 + 3{,}560$ gives 13 hundreds. Which shows how the 13 hundreds are regrouped?', '["3 thousands and 1 hundred","1 thousand and 3 hundreds","13 thousands","1 thousand and 13 hundreds"]', '1 thousand and 3 hundreds', NULL, '10 hundreds make 1 thousand, so 13 hundreds is 1 thousand and 3 hundreds.', 'checked', '{"lint":[],"solve":{"answer":"1 thousand and 3 hundreds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 5 = 13 hundreds = 1,300 = 1 thousand and 3 hundreds.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
