INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('edb80b22-5de5-4b0d-a428-d6c40bcecafc', 'NC26.4.ANR.2', 2, 'choice', 'Connect earlier strategies to the standard algorithm', 'Ira thinks: "$4{,}997$ is 3 less than $5{,}000$, so $8{,}000 - 4{,}997$ is 3 more than $8{,}000 - 5{,}000$." What is $8{,}000 - 4{,}997$?', '["2,997","3,000","2,003","3,003"]', '3,003', '8000-5000+3', '8,000 - 5,000 = 3,000. Taking away 3 less means 3 more is left: 3,003.', 'checked', '{"lint":[],"solve":{"answer":"3,003","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8,000 - 5,000 = 3,000; subtracting 3 less leaves 3 more: 3,003. Check 4,997 + 3,003 = 8,000.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
