INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30490ac8-f85c-4aed-b6bc-5a4d4264d028', 'NC26.4.ANR.2', 2, 'choice', 'Connect earlier strategies to the standard algorithm', 'Pat finds $5{,}380 + 2{,}475$ by thinking $5{,}380 + 2{,}000 = 7{,}380$, then $7{,}380 + 400 = 7{,}780$, then adding the rest. What is the sum?', '["7,780","7,845","8,855","7,855"]', '7,855', '5380+2475', 'The rest is 75: 7,780 + 75 = 7,855. Check with the algorithm: 5,380 + 2,475 = 7,855.', 'checked', '{"lint":[],"solve":{"answer":"7,855","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7,780 + 75 = 7,855. Check 5,380 + 2,475 = 7,855.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
