INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dc865e0-8373-4c4b-8b44-681dd3977fa5', 'NC26.4.ANR.2', 2, 'choice', 'Find and fix a mistake in a calculation', 'Leo wrote $52{,}000 - 17{,}348 = 45{,}348$. What mistake did he make?', '["He forgot to subtract the thousands.","In each place he subtracted the smaller digit from the larger digit instead of regrouping.","He added the digits in the ones place.","He regrouped but forgot to write the regrouped ten."]', 'In each place he subtracted the smaller digit from the larger digit instead of regrouping.', NULL, 'The correct answer is 34,652. Leo found the difference of the two digits in each place (4, 5, 3, 4, 8) instead of regrouping.', 'checked', '{"lint":[],"solve":{"answer":"In each place he subtracted the smaller digit from the larger digit instead of regrouping.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct 52,000 - 17,348 = 34,652. Leo: 5-1=4, then |2-7|=5, |0-3|=3, |0-4|=4, |0-8|=8 -> 45,348, i.e. smaller digit from larger in each place.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bbda0c8-3748-476a-9deb-e9cb89c5318b', 'NC26.4.ANR.2', 2, 'numeric', 'Find and fix a mistake in a calculation', 'Ana found $39{,}406 + 24{,}685 = 64{,}081$, but she made a mistake. What is the correct sum?', '[]', '64091', '39406+24685', 'Ones: 6 + 5 = 11, write 1 and regroup 1 ten. Tens: 0 + 8 + 1 = 9. Hundreds: 4 + 6 = 10, write 0 and regroup. Thousands: 9 + 4 + 1 = 14. Ten-thousands: 3 + 2 + 1 = 6. The sum is 64,091.', 'checked', '{"lint":[],"solve":{"answer":"64091","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"39,406 + 24,685: ones 6+5=11 (1 c1); tens 0+8+1=9; hundreds 4+6=10 (0 c1); thousands 9+4+1=14 (4 c1); ten-thousands 3+2+1=6. 64,091.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c16b118a-6838-46bf-a035-8d5ab1c74f4c', 'NC26.4.ANR.2', 2, 'choice', 'Find and fix a mistake in a calculation', 'Tara added $3{,}482 + 215$ and got $5{,}632$. What mistake did she most likely make?', '["She forgot to regroup the ones.","She left out the ones when adding.","She lined up the digits from the left instead of by place value.","She subtracted instead of adding."]', 'She lined up the digits from the left instead of by place value.', NULL, 'The correct sum is 3,697. Tara got 3,482 + 2,150 = 5,632, so 215 was written as 2,150, with its digits lined up from the left.', 'checked', '{"lint":[],"solve":{"answer":"She lined up the digits from the left instead of by place value.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct 3,482 + 215 = 3,697. Lining up from the left treats 215 as 2,150: 3,482 + 2,150 = 5,632, Tara''s answer.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
