VALUES ('f645c63e-330a-4318-9f2f-e08dc6503559', 'NC26.4.ANR.2', 3, 'numeric', 'Solve an addition word problem', 'A shop sold $12{,}450$ cups of tea in spring, $18{,}375$ cups in summer and $9{,}860$ cups in fall. How many cups did it sell in the three seasons?', '[]', '40685', '12450+18375+9860', '12,450 + 18,375 = 30,825. Then 30,825 + 9,860 = 40,685.', 'checked', '{"lint":[],"solve":{"answer":"40685","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12,450 + 18,375 = 30,825; 30,825 + 9,860 = 40,685.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
