VALUES ('3857f7de-9f0c-4cc1-a786-3423007d4c00', 'NC26.4.ANR.2', 3, 'numeric', 'Solve a two-step add and subtract problem', 'A game player had $62{,}430$ points. She spent $18{,}765$ points on a prize, then earned $9{,}850$ points, and then gave $7{,}998$ points to a friend. How many points does she have now?', '[]', '45517', '62430-18765+9850-7998', '62,430 - 18,765 = 43,665. Then 43,665 + 9,850 = 53,515. Then 53,515 - 7,998 = 45,517.', 'checked', '{"lint":[],"solve":{"answer":"45517","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"62,430 - 18,765 = 43,665; + 9,850 = 53,515; - 7,998 = 45,517.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
