VALUES ('5ca185ad-d323-4b36-832c-5c82d13176c4', 'NC26.4.ANR.2', 3, 'choice', 'Find a missing number in an addition or subtraction sentence', 'Which number makes this true? $12{,}500 + \square - 3{,}000 = 20{,}000$', '["7,500","11,500","10,500","9,500"]', '10,500', '20000+3000-12500', 'Undo the subtraction: 20,000 + 3,000 = 23,000, so 12,500 + box = 23,000. The box is 23,000 - 12,500 = 10,500.', 'checked', '{"lint":[],"solve":{"answer":"10,500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12,500 + box - 3,000 = 20,000, so 12,500 + box = 23,000, box = 10,500. Check 23,000 - 3,000 = 20,000.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
