INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cdd846d-968a-4056-bb38-ad8764cf244b', 'NC26.4.ANR.2', 3, 'numeric', 'Understand regrouping in the algorithm', 'How many times do you need to regroup (carry) when you add $68{,}764 + 27{,}359$ with the standard algorithm?', '[]', '4', '4', 'Ones: 4 + 9 = 13 (carry). Tens: 6 + 5 + 1 = 12 (carry). Hundreds: 7 + 3 + 1 = 11 (carry). Thousands: 8 + 7 + 1 = 16 (carry). Ten-thousands: 6 + 2 + 1 = 9 (no carry). That is 4 carries.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"68,764 + 27,359: ones 4+9=13 (carry); tens 6+5+1=12 (carry); hundreds 7+3+1=11 (carry); thousands 8+7+1=16 (carry); ten-thousands 6+2+1=9 (no carry). 4 regroupings; sum 96,123.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17d1e6e9-94ae-4e9e-aba5-280e7fd43f88', 'NC26.4.ANR.2', 3, 'numeric', 'Understand regrouping in the algorithm', 'Mr. Cruz subtracts $40{,}000 - 12{,}345$ with the standard algorithm. He regroups from the left, one place at a time, until the ones place has enough to subtract from. After all the regrouping, how many ones are in the ones place?', '[]', '10', '10', '40,000 becomes 3 ten-thousands, 9 thousands, 9 hundreds, 9 tens and 10 ones. So there are 10 ones.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40,000: 4 ten-thousands -> 3 and 10 thousands; 10 thousands -> 9 and 10 hundreds; 10 hundreds -> 9 and 10 tens; 10 tens -> 9 and 10 ones. Ones place has 10.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3b67e35-1fa1-426c-b25e-59e72b461799', 'NC26.4.ANR.2', 3, 'choice', 'Understand regrouping in the algorithm', 'When adding $9{,}876 + 5{,}432$ with the standard algorithm, starting at the ones, which is the first place where you need to regroup?', '["ones","tens","hundreds","thousands"]', 'tens', NULL, 'Ones: 6 + 2 = 8, no regrouping. Tens: 7 + 3 = 10, so you regroup here.', 'checked', '{"lint":[],"solve":{"answer":"tens","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9,876 + 5,432: ones 6+2=8 (no regroup); tens 7+3=10 (regroup). First regroup at tens.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa3a8acb-b5b6-4be1-9a2a-21c38feb78e2', 'NC26.4.ANR.2', 3, 'numeric', 'Connect earlier strategies to the standard algorithm', 'To add $38{,}475 + 27{,}648$, a student writes the partial sums $50{,}000$, $15{,}000$, $1{,}000$, 110 and 13. What is the total of the partial sums?', '[]', '66123', '50000+15000+1000+110+13', '50,000 + 15,000 = 65,000. Then + 1,000 = 66,000. Then + 110 = 66,110. Then + 13 = 66,123.', 'checked', '{"lint":[],"solve":{"answer":"66123","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50,000 + 15,000 = 65,000; + 1,000 = 66,000; + 110 = 66,110; + 13 = 66,123. Check 38,475 + 27,648 = 66,123.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24f6fbda-0d5f-4dab-922d-778db7cea4a1', 'NC26.4.ANR.2', 3, 'numeric', 'Connect earlier strategies to the standard algorithm', 'Zoe finds $62{,}000 - 38{,}500$ by counting up: from $38{,}500$ to $40{,}000$, and then from $40{,}000$ to $62{,}000$. What is the total she counted up?', '[]', '23500', '(40000-38500)+(62000-40000)', '38,500 to 40,000 is 1,500. 40,000 to 62,000 is 22,000. Together: 23,500, which is 62,000 - 38,500.', 'checked', '{"lint":[],"solve":{"answer":"23500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38,500 to 40,000 = 1,500; 40,000 to 62,000 = 22,000. Total 23,500.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9f238f5-b35f-4a35-9c07-0b31fb52976c', 'NC26.4.ANR.2', 3, 'choice', 'Connect earlier strategies to the standard algorithm', 'Which expression is equal to $48{,}250 - 19{,}999$?', '["$48{,}250 - 20{,}000 - 1$","$48{,}250 - 20{,}000 + 1$","$48{,}250 + 20{,}000 - 1$","$48{,}250 - 20{,}000$"]', '$48{,}250 - 20{,}000 + 1$', NULL, '19,999 is 1 less than 20,000. Taking away 1 less leaves 1 more, so 48,250 - 19,999 = 48,250 - 20,000 + 1.', 'checked', '{"lint":[],"solve":{"answer":"$48{,}250 - 20{,}000 + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"19,999 = 20,000 - 1, so subtracting 19,999 = subtracting 20,000 then adding 1 back: 48,250 - 20,000 + 1 = 28,251.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66bffe18-9b5b-4702-8f3a-a6320eac12da', 'NC26.4.ANR.2', 3, 'choice', 'Find and fix a mistake in a calculation', 'Which equation is NOT true?', '["$33{,}217 + 49{,}785 = 82{,}002$","$26{,}480 + 15{,}730 = 42{,}210$","$51{,}904 - 28{,}376 = 23{,}528$","$70{,}000 - 4{,}165 = 65{,}835$"]', '$33{,}217 + 49{,}785 = 82{,}002$', NULL, '33,217 + 49,785 = 83,002, not 82,002. The other three equations are correct.', 'checked', '{"lint":[],"solve":{"answer":"$33{,}217 + 49{,}785 = 82{,}002$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,165 + 65,835 = 70,000 (true). 26,480 + 15,730 = 42,210 (true). 28,376 + 23,528 = 51,904 (true). 33,217 + 49,785 = 83,002, not 82,002 (false).","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcb6dd27-068d-440e-921f-dbfae8e0b5d3', 'NC26.4.ANR.2', 3, 'choice', 'Find and fix a mistake in a calculation', 'Priya found $71{,}000 - 35{,}480 = 35{,}520$. Which addition checks her answer?', '["$71{,}000 + 35{,}480 = 35{,}520$","$35{,}520 - 35{,}480 = 71{,}000$","$71{,}000 + 35{,}520 = 35{,}480$","$35{,}520 + 35{,}480 = 71{,}000$"]', '$35{,}520 + 35{,}480 = 71{,}000$', NULL, 'Subtraction is checked by adding the answer to the number taken away: 35,520 + 35,480 = 71,000, so her answer is right.', 'checked', '{"lint":[],"solve":{"answer":"$35{,}520 + 35{,}480 = 71{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check a difference by adding it to the number subtracted: 35,520 + 35,480 = 71,000. Only the last option is an addition of that form (and it is true).","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24d44c8f-3999-40e8-a7f6-f14d8b1c3f34', 'NC26.4.ANR.2', 3, 'numeric', 'Find and fix a mistake in a calculation', 'A student found $36{,}859 + 27{,}574 = 64{,}423$. How much too small is the student''s answer?', '[]', '10', '(36859+27574)-64423', '36,859 + 27,574 = 64,433. The student''s answer is 64,423, which is 10 too small (for example, the 1 regrouped from the ones may have been left out of the tens).', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36,859 + 27,574: ones 13 (3 c1); tens 5+7+1=13 (3 c1); hundreds 8+5+1=14 (4 c1); thousands 6+7+1=14 (4 c1); ten-thousands 6. Correct 64,433. 64,433 - 64,423 = 10.","run_id":"claude-code","at":"2026-10-17T20:03:27.890Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
