INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f17961c-f1ca-45ca-94bc-15d4be4a1d96', 'NC26.4.ANR.3', 1, 'choice', 'Factors and factor pairs', 'Which of these is a factor of 18?', '["4","5","6","8"]', '6', '18/3', '$18 \div 6 = 3$ with nothing left over, so 6 is a factor of 18. Dividing 18 by 4, 5 or 8 always leaves a remainder.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 18: 1, 2, 3, 6, 9, 18. Of 8, 6, 4, 5 only 6 divides 18 (18 = 6 x 3).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
