INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2527b84-9ad5-4671-bb3e-6857e63e21a8', 'NC26.4.ANR.3', 1, 'choice', 'Factors and factor pairs', 'A factor pair of 24 is 4 and another number. What is the other number?', '["6","20","28","96"]', '6', '24/4', 'A factor pair multiplies to 24. Since $4 \times 6 = 24$, the other number is $24 \div 4 = 6$. The choice 20 subtracts, 28 adds and 96 multiplies by 4.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 / 4 = 6, so 4 and 6 is a factor pair.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
