INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec40a8f6-1f2e-4639-bf5d-5a6133b67688', 'NC26.4.ANR.3', 1, 'choice', 'Factors and factor pairs', 'Which pair of numbers is a factor pair of 16?', '["6 and 10","4 and 12","5 and 11","2 and 8"]', '2 and 8', NULL, 'A factor pair multiplies to 16, and $2 \times 8 = 16$. The other pairs add up to 16 but do not multiply to 16: $6 \times 10 = 60$, $4 \times 12 = 48$ and $5 \times 11 = 55$.', 'checked', '{"lint":[],"solve":{"answer":"2 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 8 = 16. 6 x 10 = 60, 5 x 11 = 55, 4 x 12 = 48.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
