VALUES ('498a0155-3e93-4388-8695-267e8a56cf67', 'NC26.4.ANR.3', 1, 'choice', 'Prime and composite numbers', 'Which number is composite?', '["7","11","15","13"]', '15', '3*5', '$15 = 3 \times 5$, so 15 has factors besides 1 and itself. That makes it composite. The numbers 7, 11 and 13 each have only the factors 1 and themselves, so they are prime.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 = 3 x 5 is composite; 13, 7, 11 are prime.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
