VALUES ('88a81c51-2dad-49e7-a568-310c457fb304', 'NC26.4.ANR.3', 1, 'numeric', 'Prime and composite numbers', 'What is the smallest prime number?', '[]', '2', NULL, 'The number 1 is not prime, because it has only one factor. The number 2 has exactly two factors, 1 and 2, so 2 is the smallest prime number.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 is not prime; 2 has factors 1 and 2 only. Smallest prime is 2.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
