VALUES ('237fb787-440a-4ee8-a0ef-8cf5257a9816', 'NC26.4.ANR.3', 1, 'choice', 'Remainders', 'What is the remainder when 23 is divided by 4?', '["5","2","6","3"]', '3', '23-4*5', '$4 \times 5 = 20$ and $23 - 20 = 3$. So $23 \div 4 = 5$ remainder 3. The choice 5 is the quotient.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"23 = 5 x 4 + 3; remainder 3.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
