INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71c01ed4-b988-41a5-be78-860592fc2f12', 'NC26.4.ANR.3', 1, 'numeric', 'Remainders', 'A baker has 29 muffins. She fills as many boxes as she can with exactly 6 muffins in each box. How many muffins are left over?', '[]', '5', '29-4*6', '$29 \div 6 = 4$ with a remainder of 5, because $4 \times 6 = 24$ and $29 - 24 = 5$. She fills 4 boxes and has 5 muffins left over.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x4=24, 29-24=5.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
