INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e71a3a6-ac2b-42fa-91c6-9f7404b27f35', 'NC26.4.ANR.3', 2, 'numeric', 'Prime and composite numbers', 'How many prime numbers are there between 20 and 30?', '[]', '2', NULL, 'Check each number: 21 = 3 × 7, 22 is even, 23 is prime, 24 is even, 25 = 5 × 5, 26 is even, 27 = 3 × 9, 28 is even and 29 is prime. Only 23 and 29 are prime, so the answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 = 3x7, 22, 24, 25 = 5x5, 26, 27 = 3x9, 28 composite; 23 and 29 prime -> 2.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
