INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c69cedaa-70cc-4141-92a1-6bf4da5b4d14', 'NC26.4.ANR.3', 2, 'numeric', 'Prime and composite numbers', 'What is the only prime number between 30 and 34?', '[]', '31', NULL, 'The numbers between 30 and 34 are 31, 32 and 33. 32 is even, and $33 = 3 \times 11$. The number 31 has only the factors 1 and 31, so it is prime.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 30 and 34: 31, 32, 33. 32 even, 33 = 3x11, 31 prime.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
