INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e901f55-ff47-4fd3-b8a9-51d1460b3981', 'NC26.4.ANR.3', 2, 'choice', 'Multiplication and division facts to 10 x 10', 'Which equation is NOT true?', '["$3 \\times 9 = 27$","$4 \\times 7 = 28$","$6 \\times 6 = 36$","$5 \\times 8 = 45$"]', '$5 \times 8 = 45$', NULL, '$5 \times 8 = 40$, not 45, so that equation is not true. The other three are correct facts.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 8 = 45$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 8 = 40, not 45. 4x7=28, 3x9=27, 6x6=36 are true.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
