VALUES ('decea7ac-1d6b-4584-82cf-01e45f86fca9', 'NC26.4.ANR.3', 2, 'numeric', 'Multi-digit products', 'A farmer picks 125 apples each day for 7 days. How many apples does he pick in all?', '[]', '875', '125*7', '$100 \times 7 = 700$, $20 \times 7 = 140$ and $5 \times 7 = 35$. Add: $700 + 140 + 35 = 875$ apples.', 'checked', '{"lint":[],"solve":{"answer":"875","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 x 7 = 700 + 140 + 35 = 875.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
