VALUES ('d98e5ceb-7165-4c3b-a321-4916b93a84c5', 'NC26.4.ANR.3', 2, 'choice', 'Multi-digit quotients', 'What is $2{,}592 \div 8$?', '["314","324","334","342"]', '324', '2592/8', '$2{,}400 \div 8 = 300$, $160 \div 8 = 20$ and $32 \div 8 = 4$. Add: $300 + 20 + 4 = 324$. Check: $8 \times 324 = 2{,}592$.', 'checked', '{"lint":[],"solve":{"answer":"324","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,592 / 8 = 324 (8 x 324 = 2,592).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
