INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ec139cc-0148-4e37-9449-ccd02bcd0094', 'NC26.4.ANR.3', 2, 'choice', 'Multi-digit quotients', 'Zane says that $234 \div 6 = 39$. Which multiplication fact shows that he is right?', '["$6 \\times 39 = 234$","$234 \\times 6 = 1{,}404$","$39 \\times 234 = 9{,}126$","$234 - 39 = 195$"]', '$6 \times 39 = 234$', NULL, 'Division is checked by multiplying the quotient by the divisor: $6 \times 39 = 234$. The other equations are true but they do not check the division.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 39 = 234$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Division checked by multiplication: 6 x 39 = 234.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
