INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11a41a68-d1dd-4e9b-906a-982e9f1cd753', 'NC26.4.ANR.3', 3, 'numeric', 'Factors and factor pairs', 'What is the largest factor of 54 that is less than 20?', '[]', '18', '54/3', 'The factor pairs of 54 are $1 \times 54$, $2 \times 27$, $3 \times 18$ and $6 \times 9$. The factors are 1, 2, 3, 6, 9, 18, 27 and 54. The largest one below 20 is 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 54: 1, 2, 3, 6, 9, 18, 27, 54. Largest below 20 is 18.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
