INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cb79621-4c51-4322-af92-fd232380fff2', 'NC26.4.ANR.3', 3, 'choice', 'Prime and composite numbers', 'Which statement about the number 1 is true?', '["It is prime, because it is the smallest number","It is composite, because it divides every number","It is both prime and composite","It is neither prime nor composite"]', 'It is neither prime nor composite', NULL, 'A prime has exactly two factors and a composite has more than two. The number 1 has only one factor, itself, so it is neither prime nor composite.', 'checked', '{"lint":[],"solve":{"answer":"It is neither prime nor composite","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 has only one factor, so it is neither prime nor composite.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
