INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd73a27f-c1f8-4f82-8e6a-23edbdc19bc4', 'NC26.4.ANR.3', 3, 'choice', 'Prime and composite numbers', 'Which of these odd numbers is composite?', '["53","57","59","61"]', '57', '3*19', '$57 = 3 \times 19$ (the digits add up to 12, so 3 divides it), so 57 is composite. The numbers 53, 59 and 61 have no factors other than 1 and themselves.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"57 = 3 x 19 (5+7=12, divisible by 3). 59, 53, 61 are prime.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
