INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a47a439-262a-45ae-bcfc-8da16624a2bf', 'NC26.4.ANR.3', 3, 'numeric', 'Multiplicative comparison', 'Nina has 3 times as many marbles as Omar, and Omar has 4 times as many marbles as Pat. Pat has 7 marbles. How many marbles does Nina have?', '[]', '84', '3*4*7', 'Omar has $4 \times 7 = 28$ marbles. Nina has $3 \times 28 = 84$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Omar = 4 x 7 = 28; Nina = 3 x 28 = 84.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
