INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('298236cc-d9c0-4303-82ec-372ea013186e', 'NC26.4.ANR.3', 3, 'choice', 'Multiplicative comparison', 'Ravi has 6 stickers. Tess has 24 stickers. Which sentence is true?', '["Tess has 18 more stickers than Ravi, and 6 times as many","Tess has 18 more stickers than Ravi, and 4 times as many","Tess has 30 more stickers than Ravi, and 4 times as many","Tess has 4 more stickers than Ravi, and 18 times as many"]', 'Tess has 18 more stickers than Ravi, and 4 times as many', NULL, 'The difference is $24 - 6 = 18$, so Tess has 18 more stickers. The comparison by multiplying is $24 \div 6 = 4$, so she has 4 times as many. Both parts must be right.', 'checked', '{"lint":[],"solve":{"answer":"Tess has 18 more stickers than Ravi, and 4 times as many","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 - 6 = 18 more; 24 / 6 = 4 times as many.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9630c8c-05ac-4cea-a6ec-ce06821a37b7', 'NC26.4.ANR.3', 3, 'numeric', 'Multiplicative comparison', 'A red pole is 120 centimeters tall. It is 8 times as tall as a green pole. A yellow pole is 3 times as tall as the green pole. How tall is the yellow pole, in centimeters?', '[]', '45', '120/8*3', 'The green pole is $120 \div 8 = 15$ centimeters tall. The yellow pole is $3 \times 15 = 45$ centimeters tall.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Green = 120 / 8 = 15 cm. Yellow = 3 x 15 = 45 cm.","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
