INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1949fc3c-04fc-4586-aded-6e067e14e4ac', 'NC26.4.ANR.3', 3, 'numeric', 'Remainders', 'A whole number between 40 and 49 leaves a remainder of 3 when it is divided by 7. What is the number?', '[]', '45', '7*6+3', 'Multiples of 7 near this range are 42 and 49. The number is 3 more than a multiple of 7: $42 + 3 = 45$. Check: $45 \div 7 = 6$ remainder 3.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7k + 3: 38, 45, 52. Only 45 is between 40 and 49 (45 = 7 x 6 + 3).","run_id":"claude-code","at":"2026-10-17T19:23:39.129Z"}}', 'ai', NULL, NULL)
