INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65ca06bd-6a6e-4b59-9aea-20f71d8f589c', 'NC26.4.ANR.4', 1, 'numeric', 'Two-step problem: multiply and divide', 'A box holds 4 rows of 6 muffins. The muffins are shared equally among 3 children. How many muffins does each child get?', '[]', '8', '4*6/3', 'The box holds $4 \times 6 = 24$ muffins. Each child gets $24 \div 3 = 8$ muffins.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24; 24 / 3 = 8.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
