INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b5f87d1-e943-4c7d-9d00-02f8bb23faf1', 'NC26.4.ANR.4', 1, 'choice', 'Equation with a letter: choose the equation for a story', 'Ravi has 40 dollars. He buys 3 notebooks that cost $n$ dollars each and has 10 dollars left. Which equation matches the story?', '["$40 - 3 + n = 10$","$3 \\times n - 40 = 10$","$40 \\div 3 - n = 10$","$40 - 3 \\times n = 10$"]', '$40 - 3 \times n = 10$', NULL, 'The notebooks cost $3 \times n$ dollars in all. Ravi starts with 40 dollars and ends with 10, so $40 - 3 \times n = 10$. Check with $n = 10$: $40 - 30 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$40 - 3 \\times n = 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spent 3 x n; 40 - 3 x n = 10.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc197869-6bec-49fd-b4df-b9da3357661c', 'NC26.4.ANR.4', 1, 'choice', 'Equation with a letter: choose the equation for a story', 'Nina had 20 marbles. She lost $m$ marbles and then had 14 left. Which equation matches the story?', '["$20 + m = 14$","$m - 20 = 14$","$20 - m = 14$","$20 \\times m = 14$"]', '$20 - m = 14$', NULL, 'Losing marbles takes away from 20, and what is left is 14. So $20 - m = 14$.', 'checked', '{"lint":[],"solve":{"answer":"$20 - m = 14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 20, lose m, left 14: 20 - m = 14.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
