INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5bf528a-3f82-44a9-95c2-8702477a5d4d', 'NC26.4.ANR.4', 1, 'choice', 'Equation with a letter: choose the equation for a story', 'Eight friends each have the same number of cards, $c$. They have 72 cards in all. Which equation matches the story?', '["$8 + c = 72$","$c \\div 8 = 72$","$8 \\times c = 72$","$72 \\times 8 = c$"]', '$8 \times c = 72$', NULL, '8 friends with $c$ cards each have $8 \times c$ cards, and that is 72. So $8 \times c = 72$, which gives $c = 9$.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times c = 72$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 groups of c make 72: 8 x c = 72.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
