INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3cc9851-3e10-4768-9382-68e85dcdc43b', 'NC26.4.ANR.4', 1, 'numeric', 'Equation with a letter: solve a two-step equation', 'What is the value of $n$ in $2 \times n + 1 = 9$?', '[]', '4', '(9-1)/2', 'First take away 1: $9 - 1 = 8$, so $2 \times n = 8$. Then $n = 8 \div 2 = 4$. Check: $2 \times 4 + 1 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n = 9 - 1 = 8; n = 4.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
