INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f9e2aee-a2bc-4334-a593-017be52ea751', 'NC26.4.ANR.4', 1, 'choice', 'Check by estimation: is the answer reasonable', 'Dan says that $52 + 49 = 301$. Use rounding to check. Which statement is correct?', '["It is reasonable, because $50 + 50 = 100$, which is close to 301","It is not reasonable, because $50 + 50 = 100$, which is far from 301","It is reasonable, because 301 is more than 52 and more than 49","It is reasonable, because $50 \\times 6 = 300$"]', 'It is not reasonable, because $50 + 50 = 100$, which is far from 301', NULL, '52 rounds to 50 and 49 rounds to 50. The estimate is $50 + 50 = 100$, which is far from 301. So the answer is not reasonable. The correct sum is 101.', 'checked', '{"lint":[],"solve":{"answer":"It is not reasonable, because $50 + 50 = 100$, which is far from 301","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 + 49 is about 50 + 50 = 100, far from 301, so 301 is not reasonable (exact 101).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
