INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c048f304-2500-4ed6-bfca-cbd91c017180', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: divide, then add or subtract', 'Lisa paid 63 dollars for 7 tickets that all cost the same. A snack costs 5 dollars. How many dollars do one ticket and one snack cost together?', '[]', '14', '63/7+5', 'One ticket costs $63 \div 7 = 9$ dollars. With the snack: $9 + 5 = 14$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"63 / 7 = 9 per ticket; 9 + 5 = 14.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
