INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('897e4de7-32ba-4555-948a-2d2506450a0b', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: add or subtract, then multiply or divide', 'Kara has 96 beads. She uses 18 beads on a necklace, then puts the rest equally into 6 bags. How many beads are in each bag?', '[]', '13', '(96-18)/6', 'After the necklace, $96 - 18 = 78$ beads are left. Each bag gets $78 \div 6 = 13$ beads.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"96 - 18 = 78; 78 / 6 = 13.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
