INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab5cc003-0759-4c25-ba43-55f3e79484cd', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem: add or subtract, then multiply or divide', 'A farmer has 215 eggs in one basket and 169 eggs in another. He packs all of the eggs into boxes that hold 8 eggs each. How many boxes does he fill?', '[]', '48', '(215+169)/8', 'There are $215 + 169 = 384$ eggs. The number of boxes is $384 \div 8 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"215 + 169 = 384; 384 / 8 = 48 exactly.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
