INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd90523c-fb09-4e32-8c8d-d39bcf6494a5', 'NC26.4.ANR.4', 2, 'numeric', 'Two-step problem with a remainder', 'A teacher has 4 boxes with 25 crayons in each box. She gives the same number of crayons to each of 9 students, as many as she can. How many crayons are left over?', '[]', '1', '100-9*11', 'She has $4 \times 25 = 100$ crayons. Since $9 \times 11 = 99$, each student gets 11 crayons and $100 - 99 = 1$ crayon is left over.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 25 = 100; 100 = 9 x 11 + 1, so 1 left over.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
