INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab5eb1d3-a5be-424f-a27d-e5d0941a6f4f', 'NC26.4.ANR.4', 2, 'choice', 'Check by estimation: is the answer reasonable', 'Jo estimates $47 + 38$ by rounding 47 up to 50 and 38 up to 40, which gives 90. Is the exact sum greater than 90 or less than 90?', '["Greater than 90, because both numbers were rounded up","Greater than 90, because both numbers were rounded down","Less than 90, because both numbers were rounded up","Exactly 90, because rounding does not change a sum"]', 'Less than 90, because both numbers were rounded up', NULL, 'Both numbers were made bigger, so the estimate is bigger than the exact sum. The exact sum is $47 + 38 = 85$, which is less than 90.', 'checked', '{"lint":[],"solve":{"answer":"Less than 90, because both numbers were rounded up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rounded up, so the estimate is too big; exact 47 + 38 = 85 < 90.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5a093f1-47ff-43bd-807a-0fbde2d5db2d', 'NC26.4.ANR.4', 2, 'numeric', 'Check by estimation: a two-step answer', 'A farm has 31 rows of corn with 49 plants in each row. Deer eat 205 of the plants. Round 31 to 30, 49 to 50 and 205 to 200. Use them to estimate how many plants are left.', '[]', '1300', '30*50-200', 'The farm has about $30 \times 50 = 1{,}500$ plants. After the deer, about $1{,}500 - 200 = 1{,}300$ plants are left.', 'checked', '{"lint":[],"solve":{"answer":"1300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 x 50 = 1,500; 1,500 - 200 = 1,300 (exact 1,519 - 205 = 1,314).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9772a3fa-6bbe-4374-884d-fd850a51c9e0', 'NC26.4.ANR.4', 3, 'numeric', 'Multiplicative comparison then add', 'A theater sells 128 tickets on Friday. On Saturday it sells 3 times as many tickets as on Friday. How many tickets does it sell on the two days together?', '[]', '512', '128+3*128', 'Saturday: 3 x 128 = 384 tickets. Both days: 128 + 384 = 512 tickets.', 'checked', '{"lint":[],"solve":{"answer":"512","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Saturday 3 x 128 = 384; total 128 + 384 = 512.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40158e9d-1771-4146-9ccb-5621989587c3', 'NC26.4.ANR.4', 3, 'numeric', 'Work backward to find a starting amount', 'Kai had some marbles. He bought 3 bags with 15 marbles in each bag. Now he has 80 marbles. How many marbles did Kai have at first?', '[]', '35', '80-3*15', 'The bags hold 3 x 15 = 45 marbles. Kai had 80 - 45 = 35 marbles at first. Check: 35 + 45 = 80.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bought 3 x 15 = 45; start = 80 - 45 = 35.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6f989d9-d68a-4280-b2f9-1c91140e73a6', 'NC26.4.ANR.4', 3, 'choice', 'Match a story to an equation', 'Which story can be solved with $n = 3 \times 14 + 8$?', '["14 bags of 8 beads each, then 3 more beads are added. How many beads?","3 bags of 14 beads each, then 8 beads are given away. How many beads are left?","14 beads are shared equally by 3 bags, then 8 more beads are added. How many beads?","3 bags of 14 beads each, then 8 more beads are added. How many beads?"]', '3 bags of 14 beads each, then 8 more beads are added. How many beads?', NULL, '$3 \times 14$ means 3 groups of 14, and $+ 8$ means 8 more. So the story is 3 bags of 14 beads each with 8 more beads added.', 'checked', '{"lint":[],"solve":{"answer":"3 bags of 14 beads each, then 8 more beads are added. How many beads?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 14 + 8 = 3 groups of 14, then add 8: 3 bags of 14 beads each, then 8 more added.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a513e2c1-96ea-495b-8ed8-42425b8f0cfc', 'NC26.4.ANR.4', 3, 'numeric', 'Two-step problem: add and subtract', 'A store had 624 shirts. It sold some shirts, and then 150 more shirts arrived. Now the store has 502 shirts. How many shirts did it sell?', '[]', '272', '624+150-502', 'After the delivery of 150 shirts the store has 502, so before the delivery it had $502 - 150 = 352$ shirts. It started with 624, so it sold $624 - 352 = 272$ shirts. Check: $624 - 272 + 150 = 502$.', 'checked', '{"lint":[],"solve":{"answer":"272","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before the delivery: 502 - 150 = 352. Sold: 624 - 352 = 272. Check 624 - 272 + 150 = 502.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bacfc040-76be-43f4-bca5-071ca9ee1db8', 'NC26.4.ANR.4', 3, 'numeric', 'Two-step problem: add and subtract', 'Room A collected 238 cans. Room B collected 57 fewer cans than Room A. How many cans did the two rooms collect altogether?', '[]', '419', '238+(238-57)', 'Room B collected $238 - 57 = 181$ cans. Together: $238 + 181 = 419$ cans.', 'checked', '{"lint":[],"solve":{"answer":"419","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Room B: 238 - 57 = 181. Together: 238 + 181 = 419.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
