INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0675363b-70e6-4f35-a985-cd0d31dc9a1a', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem: multiply, then add or subtract', 'A bakery bakes 24 trays of rolls with 36 rolls on each tray. It sells 750 rolls. How many rolls are left?', '["114","864","786","60"]', '114', '24*36-750', 'The bakery bakes $24 \times 36 = 864$ rolls. After selling 750, $864 - 750 = 114$ rolls are left. The choice 864 forgets to subtract, 786 adds 36 to 750, and 60 adds 24 and 36.', 'checked', '{"lint":[],"solve":{"answer":"114","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 36 = 720 + 144 = 864; 864 - 750 = 114.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7537bfcb-b0a2-4068-81aa-2b36d9a6478f', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem: multiply, then add or subtract', 'Ana earns 12 dollars each hour for 9 hours. She spends 47 dollars on a coat. How many dollars does she have left?', '["155","108","61","35"]', '61', '12*9-47', 'Ana earns $12 \times 9 = 108$ dollars. After the coat, $108 - 47 = 61$ dollars are left. The choice 155 adds the coat, and 108 stops after the first step.', 'checked', '{"lint":[],"solve":{"answer":"61","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 9 = 108; 108 - 47 = 61.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
