INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b6ccfc0-33c1-44c2-9c68-1ea1008d41ae', 'NC26.4.ANR.4', 3, 'numeric', 'Two-step problem: multiply, then add or subtract', 'A museum charges 9 dollars for each child and 14 dollars for each adult. A group has 23 children and 4 adults. What is the total cost in dollars?', '[]', '263', '23*9+4*14', 'The children cost $23 \times 9 = 207$ dollars. The adults cost $4 \times 14 = 56$ dollars. Together: $207 + 56 = 263$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"263","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Children 23 x 9 = 207; adults 4 x 14 = 56; total 263.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2519b189-618a-45e2-ad4a-2d231143f423', 'NC26.4.ANR.4', 3, 'numeric', 'Two-step problem: divide, then add or subtract', 'A library has $1{,}248$ books to put on 8 shelves in equal numbers. After that, the librarian removes 37 books from each shelf. How many books are on each shelf now?', '[]', '119', '1248/8-37', 'Each shelf gets $1{,}248 \div 8 = 156$ books. After removing 37, each shelf has $156 - 37 = 119$ books.', 'checked', '{"lint":[],"solve":{"answer":"119","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,248 / 8 = 156 (8 x 156 = 1,248); 156 - 37 = 119.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
