INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c556b2b-950c-496a-aca7-f0504dbca0eb', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem: divide, then add or subtract', 'A trail is $2{,}100$ meters long. A marker is placed at the start of the trail, and then one every 300 meters along the trail, up to and including the end of the trail. How many markers are there?', '["7","8","9","6"]', '8', '2100/300+1', 'The trail has $2{,}100 \div 300 = 7$ gaps between markers. Because there is a marker at the start as well, there is one more marker than there are gaps: $7 + 1 = 8$ markers.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,100 / 300 = 7 gaps. Markers at 0, 300, ..., 2,100: 7 + 1 = 8.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21ccf64e-d155-48b6-b8d5-7bcd3a906f75', 'NC26.4.ANR.4', 3, 'choice', 'Two-step problem: add or subtract, then multiply or divide', 'A club has 600 dollars. It spends 240 dollars on supplies and shares the rest equally among 4 teams. How many dollars does each team get?', '["360","90","540","840"]', '90', '(600-240)/4', 'After the supplies, $600 - 240 = 360$ dollars are left. Each team gets $360 \div 4 = 90$ dollars. The choice 360 stops early, and 540 divides only 240 by 4.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 - 240 = 360; 360 / 4 = 90.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
