INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d4831ed-e3c0-49eb-840b-eb0a1d767227', 'NC26.4.ANR.4', 3, 'numeric', 'Two-step problem: add or subtract, then multiply or divide', 'Gina has 38 stickers and Hal has 47 stickers. They share all of the stickers equally among 5 albums. How many stickers go in each album?', '[]', '17', '(38+47)/5', 'Together they have $38 + 47 = 85$ stickers. Each album gets $85 \div 5 = 17$ stickers.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38 + 47 = 85; 85 / 5 = 17.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
