INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d672a545-4c25-4ccc-87f0-5166c7ffe137', 'NC26.4.ANR.4', 3, 'numeric', 'Two-step problem: multiply and divide', 'A machine makes 5 toys every minute. It runs for 48 minutes. The toys are packed equally into 8 crates. How many toys are in each crate?', '[]', '30', '5*48/8', 'The machine makes $5 \times 48 = 240$ toys. Each crate gets $240 \div 8 = 30$ toys.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 48 = 240; 240 / 8 = 30.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
