VALUES ('53d200a4-6051-48e6-9e51-93d62079dccf', 'NC26.4.ANR.4', 3, 'numeric', 'Equation with a letter: find the unknown in one step', 'Find the value of $q$: $2{,}000 - q = 1{,}376$.', '[]', '624', '2000-1376', 'The missing part is $q = 2{,}000 - 1{,}376 = 624$. Check: $2{,}000 - 624 = 1{,}376$.', 'checked', '{"lint":[],"solve":{"answer":"624","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"q = 2,000 - 1,376 = 624.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
