INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34132b14-1171-4cca-84f4-e68ce3a69295', 'NC26.4.ANR.4', 3, 'numeric', 'Check by estimation: sum or difference', 'A store sold $2{,}847$ items in May and $3{,}162$ items in June. Round each number to the nearest hundred. Use them to estimate how many items the store sold in the two months.', '[]', '6000', '2800+3200', '$2{,}847$ rounds to $2{,}800$ and $3{,}162$ rounds to $3{,}200$. The estimate is $2{,}800 + 3{,}200 = 6{,}000$ items.', 'checked', '{"lint":[],"solve":{"answer":"6000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,847 -> 2,800; 3,162 -> 3,200; sum 6,000.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
