INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ee4c4ea-0507-4911-87bb-fcc166b82ddc', 'NC26.4.ANR.4', 3, 'numeric', 'Check by estimation: product', 'Round each number to its greatest place, then estimate $396 \times 7$.', '[]', '2800', '400*7', '396 rounds to 400 and 7 stays 7. The estimate is $400 \times 7 = 2{,}800$.', 'checked', '{"lint":[],"solve":{"answer":"2800","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"396 -> 400 (hundreds place); 7 stays 7; 400 x 7 = 2,800.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
