INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e355e4d-539b-4086-81a4-fd37bc457874', 'NC26.4.ANR.4', 3, 'choice', 'Check by estimation: product', 'A gym runs 31 classes a week, and 48 people come to each class. Which is the best estimate of the number of people who come to classes in one week?', '["$150$","$2{,}500$","$1{,}200$","$1{,}500$"]', '$1{,}500$', NULL, '31 is close to 30 and 48 is close to 50, so the estimate is $30 \times 50 = 1{,}500$. The choice $2{,}500$ rounds 31 up to 50, and $1{,}200$ rounds 48 down to 40.', 'checked', '{"lint":[],"solve":{"answer":"$1{,}500$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31 -> 30, 48 -> 50; 30 x 50 = 1,500 (exact 1,488).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0227300-8f8e-4ee7-8112-efe7c2910974', 'NC26.4.ANR.4', 3, 'choice', 'Check by estimation: quotient', 'Which is the best estimate for $5{,}912 \div 3$?', '["$200$","$1{,}000$","$2{,}000$","$3{,}000$"]', '$2{,}000$', NULL, '$5{,}912$ is close to $6{,}000$, and $6{,}000 \div 3 = 2{,}000$. The exact answer is about $1{,}970$, so $2{,}000$ is the best estimate.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,912 is close to 6,000; 6,000 / 3 = 2,000 (exact about 1,971).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
