INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51b0b19f-408b-4e35-9c63-d3958a4a649d', 'NC26.4.ANR.4', 3, 'choice', 'Check by estimation: is the answer reasonable', 'A factory packs $4{,}812$ toys equally into 6 boxes. Which is the only reasonable number of toys in each box?', '["$80$","$8{,}020$","$208$","$802$"]', '$802$', NULL, '$4{,}812$ is close to $4{,}800$, and $4{,}800 \div 6 = 800$. So each box has about 800 toys. Only $802$ is close. The exact quotient is $4{,}812 \div 6 = 802$.', 'checked', '{"lint":[],"solve":{"answer":"$802$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,812 is about 4,800; 4,800 / 6 = 800, so 802 (exact 6 x 802 = 4,812).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
