INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('287dd235-a4eb-425c-b470-0d9e781d81be', 'NC26.4.ANR.4', 3, 'choice', 'Check by estimation: is the answer reasonable', 'To estimate $762 - 288$, Tia rounds 762 down to 700 and 288 up to 300, and gets 400. Which statement about the exact difference is true?', '["Greater than 400, because 762 was rounded down and 288 was rounded up","Less than 400, because 762 was rounded down and 288 was rounded up","Greater than 400, because 762 was rounded up and 288 was rounded down","Less than 400, because 762 was rounded up and 288 was rounded down"]', 'Greater than 400, because 762 was rounded down and 288 was rounded up', NULL, 'Rounding 762 down makes the first number smaller, and rounding 288 up makes the number taken away bigger. Both make the estimate smaller than the exact answer. So the exact difference is greater than 400. It is $762 - 288 = 474$.', 'checked', '{"lint":[],"solve":{"answer":"Greater than 400, because 762 was rounded down and 288 was rounded up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Making the first number smaller and the subtracted number bigger makes the estimate too small; exact 762 - 288 = 474 > 400.","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2835a82-9176-4884-8adc-20100fc913e5', 'NC26.4.ANR.4', 3, 'numeric', 'Check by estimation: a two-step answer', 'Aria sold 18 bracelets for 12 dollars each and 21 rings for 9 dollars each. Round every number to the nearest ten. Use them to estimate how many dollars she earned.', '[]', '400', '20*10+20*10', '18 rounds to 20, 12 to 10, 21 to 20 and 9 to 10. The estimate is $20 \times 10 + 20 \times 10 = 200 + 200 = 400$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"400","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 -> 20, 12 -> 10, 21 -> 20, 9 -> 10. 20 x 10 + 20 x 10 = 200 + 200 = 400 (exact 216 + 189 = 405).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23e315a6-d859-4677-a29a-69dd61154f6b', 'NC26.4.ANR.4', 3, 'choice', 'Check by estimation: a two-step answer', 'A school buys 4 boxes of markers at 29 dollars each and 3 boxes of paper at 18 dollars each. Round each price to the nearest ten dollars. About how many dollars does the school spend?', '["180","150","210","120"]', '180', '4*30+3*20', '29 rounds to 30 and 18 rounds to 20. The estimate is $4 \times 30 + 3 \times 20 = 120 + 60 = 180$ dollars. The choice 120 leaves out the paper.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29 -> 30, 18 -> 20. 4 x 30 + 3 x 20 = 120 + 60 = 180 (exact 116 + 54 = 170).","run_id":"claude-code","at":"2026-10-17T19:23:39.170Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56fa85e7-d8bc-45c8-b384-d2684b5a6149', 'NC26.4.ANR.5', 1, 'numeric', 'Find an equivalent fraction', 'What number does $n$ stand for so that the fractions are equal? $\frac{1}{2} = \frac{n}{8}$', '[]', '4', '1*8/2', 'The denominator 2 was multiplied by 4 to make 8, so multiply the numerator 1 by 4 as well. $n = 4$, and $\frac{1}{2} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8 (multiply top and bottom by 4). n = 4.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad62ccf2-4129-4759-aa7c-4a86020d0996', 'NC26.4.ANR.5', 1, 'choice', 'Tenths as decimals', 'Which decimal is equal to $\frac{7}{10}$?', '["0.07","0.17","0.7","7.10"]', '0.7', '7/10', '$\frac{7}{10}$ means 7 tenths, which is written 0.7. (0.07 is 7 hundredths.)', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/10 = seven tenths = 0.7.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab72ad21-f827-4a36-be6b-69ec23b4f87c', 'NC26.4.ANR.5', 1, 'choice', 'Compare a fraction to one half', 'Which fraction is greater than $\frac{1}{2}$?', '["$\\frac{3}{8}$","$\\frac{2}{5}$","$\\frac{1}{3}$","$\\frac{5}{8}$"]', '$\frac{5}{8}$', NULL, 'Half of 8 is 4, so a fraction with denominator 8 is greater than $\frac{1}{2}$ when its numerator is more than 4. $\frac{5}{8}$ is greater than $\frac{1}{2}$, and $\frac{3}{8}$ is less. Half of 5 is 2 and a half, so $\frac{2}{5}$ (numerator 2) is less than $\frac{1}{2}$. One of 3 equal parts is less than half of the whole, so $\frac{1}{3}$ is less than $\frac{1}{2}$. Only $\frac{5}{8}$ is greater than $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half of 8 is 4, so 5/8 > 4/8 = 1/2. 2/5 < 2.5/5, 1/3 < 1/2, 3/8 < 4/8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('506d643e-6c05-49fd-916a-75ec0ded2806', 'NC26.4.ANR.5', 1, 'numeric', 'Find a missing number in equivalent fractions', 'Fill in the missing number so the two fractions name the same amount: $\frac{1}{3} = \frac{3}{n}$. What is $n$?', '[]', '9', '3*(3/1)', 'The top number went from 1 to 3, so it was multiplied by 3. Multiply the bottom number by 3 too: $3 \times 3 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 3/n: numerator 1 x3 = 3, so denominator 3 x3 = 9.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7187e223-8b0b-4db1-a490-2938e932df14', 'NC26.4.ANR.5', 1, 'numeric', 'Find a missing number in equivalent fractions', 'The fractions $\frac{2}{3}$ and $\frac{n}{6}$ are equivalent. Find $n$.', '[]', '4', '2*(6/3)', 'The bottom number went from 3 to 6, so it was multiplied by 2. Multiply the top number by 2 as well: $2 \times 2 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = n/6: denominator x2, so n = 2x2 = 4.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7972744f-46f8-46fe-8701-313e9d304a84', 'NC26.4.ANR.5', 1, 'numeric', 'Find a missing number in equivalent fractions', '$\frac{3}{5} = \frac{6}{n}$ Complete the equation by finding $n$.', '[]', '10', '5*(6/3)', 'The top number was multiplied by 2 ($3 \times 2 = 6$), so the bottom number is too: $5 \times 2 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 = 6/n: numerator x2, so n = 5x2 = 10.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95604cd7-5bef-4641-a441-73ebc347952d', 'NC26.4.ANR.5', 1, 'choice', 'Recognize equivalent fractions', 'Which fraction names the same amount as $\frac{2}{3}$?', '["$\\frac{3}{4}$","$\\frac{2}{6}$","$\\frac{4}{6}$","$\\frac{4}{9}$"]', '$\frac{4}{6}$', NULL, 'Multiply the top and bottom of $\frac{2}{3}$ by 2 to get $\frac{4}{6}$. Adding 1 to both parts ($\frac{3}{4}$) or changing only one part does not keep the amount the same.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6 (x2). 2/6 = 1/3, 3/4 no, 4/9 no.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23a9f273-45bb-4aca-8e14-5f5f5d0330b7', 'NC26.4.ANR.5', 1, 'choice', 'Recognize equivalent fractions', 'Which fraction is another name for one half?', '["$\\frac{4}{8}$","$\\frac{1}{4}$","$\\frac{2}{3}$","$\\frac{5}{8}$"]', '$\frac{4}{8}$', NULL, 'One half is 1 out of 2 equal parts. Multiplying both numbers by 4 gives $\frac{4}{8}$, which is also one half. The other fractions are not half of a whole.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/8 = 1/2. 1/4, 5/8, 2/3 are not 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61b86a04-a952-422d-b88e-feec67cf7ded', 'NC26.4.ANR.5', 1, 'numeric', 'Equivalent fractions in a story', 'A pizza is cut into 4 equal slices and Mia eats 2 of them. Her brother has a pizza of the same size that is cut into 8 equal slices. How many of his slices are the same amount as Mia''s 2 slices?', '[]', '4', '2*(8/4)', 'Cutting each fourth into 2 pieces makes eighths twice as many. Mia''s 2 slices become $2 \times 2 = 4$ slices, so $\frac{2}{4} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/4 of a pizza = 4/8, so 4 of the eighth-slices.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1e2710f-8bba-42bd-bf8d-985c6d631906', 'NC26.4.ANR.5', 1, 'choice', 'Compare a fraction with one half', 'A bottle holds some juice. Which amount is MORE than half of the bottle?', '["$\\frac{5}{8}$","$\\frac{1}{4}$","$\\frac{3}{8}$","$\\frac{2}{5}$"]', '$\frac{5}{8}$', NULL, 'Half of 8 equal parts is 4 parts. $\frac{5}{8}$ is 5 parts, which is more than 4. The others are less than half: 1 of 4, 3 of 8 and 2 of 5 are all under half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half = 4/8 = 2.5/5. 3/8 < 1/2, 2/5 < 1/2, 1/4 < 1/2, 5/8 > 4/8.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d39c8952-5577-434e-b460-a06ba3c495d2', 'NC26.4.ANR.5', 1, 'numeric', 'Compare a fraction with one half', 'How many eighths make one half?', '[]', '4', '8/2', 'A whole has 8 eighths. One half of the whole is $8 \div 2 = 4$ eighths, so $\frac{1}{2} = \frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 4/8, so 4 eighths.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8defc404-2b49-40f7-9776-cb193489652b', 'NC26.4.ANR.5', 1, 'choice', 'Compare a fraction with one half', 'Which fraction is greater than one half but less than 1?', '["$\\frac{1}{2}$","$\\frac{7}{6}$","$\\frac{2}{3}$","$\\frac{3}{8}$"]', '$\frac{2}{3}$', NULL, '$\frac{2}{3}$ is more than half (half of 3 is 1.5 and 2 is more) and less than a whole. $\frac{1}{2}$ is exactly half, $\frac{7}{6}$ is more than 1, and $\frac{3}{8}$ is less than half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 > 1/2 (4/6 > 3/6) and < 1. 1/2 equals half, 7/6 > 1, 3/8 < 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcc40915-b722-4713-b2b8-a0c63a03d788', 'NC26.4.ANR.5', 1, 'choice', 'Use the benchmarks 0, one half and 1', 'A water bottle is $\frac{1}{10}$ full. Which sentence is best?', '["It is closest to empty.","It is closest to half full.","It is closest to full.","It is exactly half full."]', 'It is closest to empty.', NULL, 'One tenth is very small. Half would be 5 tenths and full would be 10 tenths, so $\frac{1}{10}$ is closest to 0 (empty).', 'checked', '{"lint":[],"solve":{"answer":"It is closest to empty.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/10 is very close to 0, far from 1/2 = 5/10. Closest to empty.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
