INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e307b7a9-8285-4948-91de-c571ebd3bf91', 'NC26.4.ANR.5', 1, 'numeric', 'Use the benchmarks 0, one half and 1', 'Which of these fractions is closest to 1: $\frac{1}{5}$, $\frac{1}{2}$, $\frac{2}{5}$, $\frac{9}{10}$? Type that fraction.', '[]', '9/10', '9/10', '$\frac{9}{10}$ is only $\frac{1}{10}$ away from 1. The others are much further from a whole: $\frac{1}{5}$ and $\frac{2}{5}$ are less than half, and $\frac{1}{2}$ is half way.', 'checked', '{"lint":[],"solve":{"answer":"9/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/10 is 1/10 from 1; 1/2 is 1/2 away, 2/5 is 3/5 away, 1/5 is 4/5 away. Closest: 9/10.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
