INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1321eaf9-64f3-4eef-9499-10eb3b3af76a', 'NC26.4.ANR.5', 2, 'numeric', 'Find a missing number in equivalent fractions', 'What number goes in place of $n$ to make this true? $\frac{3}{8} = \frac{n}{24}$', '[]', '9', '3*(24/8)', 'The bottom number was multiplied by 3 ($8 \times 3 = 24$), so multiply the top number by 3: $3 \times 3 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = n/24: 8x3 = 24, so n = 3x3 = 9.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e39eb0ce-5d5f-4071-b886-3bb362fb6391', 'NC26.4.ANR.5', 2, 'numeric', 'Find a missing number in equivalent fractions', 'Find $n$: $\frac{5}{12} = \frac{15}{n}$.', '[]', '36', '12*(15/5)', 'The top number was multiplied by 3 ($5 \times 3 = 15$), so multiply the bottom number by 3: $12 \times 3 = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/12 = 15/n: 5x3 = 15, so n = 12x3 = 36.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fa0a4de-3ab8-4760-b3fa-e7ee6ad9de00', 'NC26.4.ANR.5', 2, 'choice', 'Recognize equivalent fractions', 'Which fraction is NOT equivalent to $\frac{2}{5}$?', '["$\\frac{4}{10}$","$\\frac{6}{15}$","$\\frac{8}{20}$","$\\frac{4}{7}$"]', '$\frac{4}{7}$', NULL, '$\frac{4}{10}$, $\frac{6}{15}$ and $\frac{8}{20}$ are made by multiplying the top and bottom of $\frac{2}{5}$ by 2, 3 and 4. $\frac{4}{7}$ comes from adding 2 to both numbers, which changes the amount.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/15 = 2/5 (x3), 8/20 = 2/5 (x4), 4/10 = 2/5 (x2). 4/7 is not (2/5 = 4/10).","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22639caf-b32c-4415-ab49-8ad01182b163', 'NC26.4.ANR.5', 2, 'choice', 'Recognize equivalent fractions', 'Which pair of fractions is equivalent?', '["$\\frac{2}{3}$ and $\\frac{4}{5}$","$\\frac{3}{4}$ and $\\frac{9}{12}$","$\\frac{5}{6}$ and $\\frac{10}{18}$","$\\frac{1}{4}$ and $\\frac{2}{6}$"]', '$\frac{3}{4}$ and $\frac{9}{12}$', NULL, '$\frac{3}{4}$ and $\frac{9}{12}$ match because $3 \times 3 = 9$ and $4 \times 3 = 12$. In the other pairs the top and bottom do not grow by the same factor.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$ and $\\frac{9}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 vs 2/6=1/3 no; 5/6 vs 10/18=5/9 no; 2/3 vs 4/5 no; 3/4 = 9/12 (x3) yes.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85f5285a-46d2-4194-828f-6d50dc87d68c', 'NC26.4.ANR.5', 2, 'numeric', 'Equivalent fractions in a story', 'A ribbon is cut into 6 equal parts and 4 of the parts are painted blue. A second ribbon of the same length is cut into 3 equal parts. How many parts of the second ribbon must be painted blue to cover the same amount?', '[]', '2', '4/(6/3)', 'Each part of the second ribbon is as long as 2 parts of the first. So the 4 blue parts of the first ribbon match $4 \div 2 = 2$ parts of the second: $\frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6 = 2/3, so 2 of the 3 parts.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f40dbcf9-eccc-46ca-8cf1-3b50522fb9dc', 'NC26.4.ANR.5', 2, 'numeric', 'Compare a fraction with one half', 'What is the greatest whole number $n$ for which $\frac{n}{10}$ is less than one half?', '[]', '4', '10/2-1', 'One half is $\frac{5}{10}$. A fraction $\frac{n}{10}$ is less than $\frac{5}{10}$ when $n$ is less than 5. The greatest whole number less than 5 is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 5/10, so n/10 < 5/10 means n < 5; greatest whole n is 4.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('189f8992-2e42-4a14-82f9-3cc0db60e7bc', 'NC26.4.ANR.5', 2, 'choice', 'Use the benchmarks 0, one half and 1', 'Which fraction is closest to 0?', '["$\\frac{5}{6}$","$\\frac{3}{8}$","$\\frac{4}{6}$","$\\frac{1}{12}$"]', '$\frac{1}{12}$', NULL, '$\frac{1}{12}$ is a tiny part of a whole. $\frac{3}{8}$ is nearly half, and $\frac{5}{6}$ and $\frac{4}{6}$ are well above half.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/12 is only one small piece from 0; 3/8, 4/6, 5/6 are much larger.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d03cfe2d-1905-40b0-bfd2-d09db93dbd75', 'NC26.4.ANR.5', 2, 'choice', 'Use the benchmarks 0, one half and 1', 'Which fraction is closest to one half?', '["$\\frac{1}{6}$","$\\frac{5}{6}$","$\\frac{7}{12}$","$\\frac{11}{12}$"]', '$\frac{7}{12}$', NULL, 'One half is $\frac{6}{12}$. $\frac{7}{12}$ is only $\frac{1}{12}$ away. $\frac{1}{6}$ is close to 0, and $\frac{5}{6}$ and $\frac{11}{12}$ are close to 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 = 6/12. 1/6 = 2/12 (4/12 away), 7/12 (1/12 away), 5/6 = 10/12 (4/12 away), 11/12 (5/12 away). Closest 7/12.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c1445e9-c9f9-4b0d-814b-501bbef53f08', 'NC26.4.ANR.5', 2, 'choice', 'Compare fractions with the same denominator or numerator', 'Which statement is true when the top numbers are the same?', '["$\\frac{4}{8} > \\frac{4}{6}$","$\\frac{3}{5} < \\frac{3}{4}$","$\\frac{5}{12} > \\frac{5}{10}$","$\\frac{1}{3} < \\frac{1}{5}$"]', '$\frac{3}{5} < \frac{3}{4}$', NULL, 'With the same top number, the fraction with the smaller bottom number is greater because its pieces are larger. Fifths are smaller than fourths, so $\frac{3}{5} < \frac{3}{4}$. Each of the other three statements points the wrong way.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{5} < \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator: smaller denominator is bigger. 4/8 < 4/6 (false), 3/5 < 3/4 (true), 5/12 < 5/10 (false), 1/3 > 1/5 (false).","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8bc8044-69e8-4492-983b-6270dfb4d7ef', 'NC26.4.ANR.5', 2, 'choice', 'Compare fractions with the same denominator or numerator', 'Ravi ran $\frac{5}{8}$ mile and Jade ran $\frac{5}{6}$ mile. Who ran farther?', '["Ravi, because 8 is greater than 6","Ravi, because eighths are bigger than sixths","Jade, because sixths are bigger than eighths","Same distance, because both numerators are 5"]', 'Jade, because sixths are bigger than eighths', NULL, 'Both fractions have 5 pieces. A whole cut into 6 parts has larger pieces than one cut into 8 parts, so 5 sixths is more than 5 eighths. Jade ran farther.', 'checked', '{"lint":[],"solve":{"answer":"Jade, because sixths are bigger than eighths","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same numerator 5; sixths are bigger than eighths, so 5/6 > 5/8. Jade.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b28aefb-e061-42f5-8bdb-dc74d0f2ff13', 'NC26.4.ANR.5', 2, 'choice', 'Compare fractions with unlike denominators', 'Maya has $\frac{2}{3}$ of a pizza. Which amount would be MORE pizza than Maya has?', '["$\\frac{3}{5}$","$\\frac{3}{4}$","$\\frac{1}{2}$","$\\frac{5}{8}$"]', '$\frac{3}{4}$', NULL, 'Use twelfths: $\frac{2}{3} = \frac{8}{12}$ and $\frac{3}{4} = \frac{9}{12}$, so $\frac{3}{4}$ is greater. $\frac{3}{5}$, $\frac{1}{2}$ and $\frac{5}{8}$ are all less than $\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 ~ 0.667. 3/5 = 0.6, 5/8 = 0.625, 1/2 = 0.5 are less; 3/4 = 0.75 is more (9/12 > 8/12).","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4988c922-7fbb-4c58-8927-1bc9679f34fa', 'NC26.4.ANR.5', 2, 'choice', 'Compare fractions with unlike denominators', 'Which statement is correct?', '["$\\frac{3}{4} > \\frac{5}{6}$","$\\frac{2}{5} < \\frac{1}{3}$","$\\frac{5}{8} > \\frac{3}{5}$","$\\frac{7}{10} < \\frac{2}{3}$"]', '$\frac{5}{8} > \frac{3}{5}$', NULL, 'Use a common denominator of 40: $\frac{5}{8} = \frac{25}{40}$ and $\frac{3}{5} = \frac{24}{40}$, so $\frac{5}{8} > \frac{3}{5}$. In the others, $\frac{3}{4} < \frac{5}{6}$, $\frac{2}{5} > \frac{1}{3}$ and $\frac{7}{10} > \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8} > \\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5=6/15 > 5/15=1/3 so first false. 7/10=21/30 > 20/30 so second false. 5/8=25/40 > 24/40=3/5 true. 3/4=9/12 < 10/12 false.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('570aa56a-b13f-486b-9bb2-74c49c6e957c', 'NC26.4.ANR.5', 2, 'choice', 'Order fractions', 'Put these fractions in order, starting with the least: $\frac{1}{3}$, $\frac{5}{6}$ and $\frac{1}{2}$. Which list is right?', '["$\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{5}{6}$","$\\frac{1}{2}$, $\\frac{1}{3}$, $\\frac{5}{6}$","$\\frac{5}{6}$, $\\frac{1}{2}$, $\\frac{1}{3}$","$\\frac{1}{3}$, $\\frac{5}{6}$, $\\frac{1}{2}$"]', '$\frac{1}{3}$, $\frac{1}{2}$, $\frac{5}{6}$', NULL, 'Use sixths: $\frac{1}{3} = \frac{2}{6}$, $\frac{1}{2} = \frac{3}{6}$ and $\frac{5}{6}$. Least to greatest: $\frac{2}{6}$, $\frac{3}{6}$, $\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3}$, $\\frac{1}{2}$, $\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 2/6, 1/2 = 3/6, 5/6. Order 1/3, 1/2, 5/6.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3256dfe3-0fc0-4f81-9fd6-740244b1f0dd', 'NC26.4.ANR.5', 2, 'numeric', 'Order fractions', 'Which is the least fraction in this list: $\frac{3}{4}$, $\frac{5}{8}$, $\frac{7}{8}$ and $\frac{1}{2}$? Type that fraction.', '[]', '1/2', '1/2', 'Use eighths: $\frac{3}{4} = \frac{6}{8}$, $\frac{5}{8}$, $\frac{7}{8}$ and $\frac{1}{2} = \frac{4}{8}$. The least is $\frac{4}{8}$, which is $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In eighths: 6/8, 5/8, 7/8, 4/8. Least 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
