INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bc4a780-1bc6-404f-8047-f9fc60abe8e9', 'NC26.4.ANR.5', 2, 'choice', 'Write a decimal as a fraction', 'Which fraction names the same amount as the decimal 0.09?', '["$\\frac{9}{10}$","$\\frac{9}{100}$","$\\frac{90}{100}$","$\\frac{1}{9}$"]', '$\frac{9}{100}$', NULL, '0.09 is nine hundredths, $\frac{9}{100}$. $\frac{9}{10}$ and $\frac{90}{100}$ both equal 0.9.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{100}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.09 = 9 hundredths = 9/100.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
