INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8ce6c31-7eaf-4618-abe8-addf32f0031c', 'NC26.4.ANR.5', 2, 'numeric', 'Rename fractions as hundredths', 'Find the missing number: $\frac{1}{4} = \frac{n}{100}$', '[]', '25', '100/4', 'It takes 4 equal parts to make 100 hundredths, so each fourth is $100 \div 4 = 25$ hundredths. So $\frac{1}{4} = \frac{25}{100}$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 25 = 100, so 1/4 = 25/100.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
