INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a50e86de-cb82-4da0-9767-6d5b7663f00e', 'NC26.4.ANR.5', 2, 'choice', 'Compare decimals', 'Which comparison of two decimals is true?', '["$0.7 < 0.65$","$0.08 > 0.1$","$0.4 > 0.35$","$0.3 = 0.03$"]', '$0.4 > 0.35$', NULL, '0.4 is 0.40, which is 40 hundredths. That is more than 35 hundredths. The others are false: 0.7 is more than 0.65, 0.08 is less than 0.1, and 0.3 is ten times 0.03.', 'checked', '{"lint":[],"solve":{"answer":"$0.4 > 0.35$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3 = 0.30 != 0.03; 0.08 < 0.10; 0.40 > 0.35 true; 0.70 > 0.65.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b3d9459-4d5d-4e2f-acec-2167de2c802d', 'NC26.4.ANR.5', 2, 'choice', 'Compare decimals', 'Which decimal is less than 0.5?', '["0.45","0.55","0.6","0.7"]', '0.45', '0.45', '0.5 is 0.50, or 50 hundredths. 0.45 is 45 hundredths, so it is less. 0.55, 0.6 and 0.7 are all more than 0.5. A decimal with more digits is not always greater.', 'checked', '{"lint":[],"solve":{"answer":"0.45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.45 < 0.50; 0.6, 0.55, 0.7 are greater.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
