INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7fa40ad8-9db5-44c7-b370-37b40242059f', 'NC26.4.ANR.5', 2, 'choice', 'Place value in decimals', 'Which number has a 7 in the hundredths place?', '["7.34","4.7","3.17","37.4"]', '3.17', NULL, 'In 3.17 the digits after the decimal point are 1 (tenths) and 7 (hundredths). The other numbers have their 7 in the ones or tenths place.', 'checked', '{"lint":[],"solve":{"answer":"3.17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.17: 7 is hundredths. 37.4: ones. 7.34: ones. 4.7: tenths.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
