INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e009b117-a1ba-4055-a7eb-d8ab5f87ed9a', 'NC26.4.ANR.5', 2, 'numeric', 'Decimals in measurement and money stories', 'A string is 0.35 meter long. There are 100 centimeters in a meter. How many centimeters long is the string?', '[]', '35', '0.35*100', '0.35 meter is 35 hundredths of a meter. Each hundredth of a meter is 1 centimeter, so the string is 35 centimeters long.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.35 m = 35/100 m = 35 cm.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
