INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71ccdc22-441c-486a-9524-5f69f724c609', 'NC26.4.ANR.5', 2, 'numeric', 'Decimals in measurement and money stories', 'Four students jumped 1.45, 1.5, 1.09 and 1.4 meters. How many meters did the student with the longest jump go?', '[]', '1.5', '1.5', 'Write them with hundredths: 1.45, 1.50, 1.09 and 1.40. The greatest is 1.50, which is 1.5 meters.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.45, 1.50, 1.09, 1.40 -> longest 1.5.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
