INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4dd0af2c-0277-4c61-9815-d7be619cefb7', 'NC26.4.ANR.5', 3, 'numeric', 'Write a decimal as a fraction', '$4.6 = \frac{n}{10}$ What number does $n$ stand for?', '[]', '46', '4.6*10', '4.6 is 46 tenths: 4 wholes are 40 tenths, plus 6 more tenths. So $n = 46$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.6 = 46 tenths = 46/10.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
