INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0e9c68d-2215-4241-909e-30341c357033', 'NC26.4.ANR.5', 3, 'numeric', 'Decimals in measurement and money stories', 'Four swimmers finished a race in 24.9, 24.09, 24.19 and 24.91 seconds. The winner has the least time. What was the winning time in seconds?', '[]', '24.09', '24.09', 'All the times start with 24. Compare the rest in hundredths: 0.90, 0.09, 0.19 and 0.91. The least is 0.09, so the winning time was 24.09 seconds.', 'checked', '{"lint":[],"solve":{"answer":"24.09","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24.90, 24.09, 24.19, 24.91 -> least 24.09.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
