INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dfb5b1bc-3be4-4c3b-86da-0a36f7ca19ab', 'NC26.4.ANR.5', 3, 'choice', 'Decimals in measurement and money stories', 'Ben says 0.8 meter is shorter than 0.75 meter because 8 is less than 75. What mistake did Ben make?', '["He should have counted the digits, and 0.75 has more digits, so it is longer.","He compared 8 and 75 as whole numbers, but 0.8 is 0.80, which is more than 0.75.","There is no mistake, because 8 is less than 75.","He should have said they are equal, because both start with 0."]', 'He compared 8 and 75 as whole numbers, but 0.8 is 0.80, which is more than 0.75.', NULL, '0.8 is 8 tenths, which is 80 hundredths. That is more than 75 hundredths. A decimal with fewer digits can be greater.', 'checked', '{"lint":[],"solve":{"answer":"He compared 8 and 75 as whole numbers, but 0.8 is 0.80, which is more than 0.75.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8 = 0.80 > 0.75; Ben compared 8 and 75 as whole numbers.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
