INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c2beb93-2d3b-455c-8df6-a1784c98f951', 'NC26.4.ANR.5', 3, 'choice', 'Find a number between two numbers', 'Which fraction lies between $\frac{2}{3}$ and $\frac{5}{6}$?', '["$\\frac{1}{2}$","$\\frac{7}{8}$","$\\frac{3}{5}$","$\\frac{3}{4}$"]', '$\frac{3}{4}$', NULL, 'Use twelfths: $\frac{2}{3} = \frac{8}{12}$ and $\frac{5}{6} = \frac{10}{12}$. The fraction $\frac{3}{4} = \frac{9}{12}$ is between them.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twelfths: 2/3 = 8/12, 5/6 = 10/12, 3/4 = 9/12 between. 3/5 < 2/3, 1/2 < 2/3, 7/8 > 5/6 (1/8 short of 1 vs 1/6).","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
