VALUES ('d469f667-099a-4944-9cd4-b706c533424a', 'NC26.4.ANR.5', 3, 'choice', 'Compare a fraction with a decimal', 'Which of these numbers is the greatest?', '["$\\frac{41}{100}$","0.4","$\\frac{3}{10}$","0.35"]', '$\frac{41}{100}$', NULL, 'Write each one in hundredths: 0.4 is 40, $\frac{3}{10}$ is 30, 0.35 is 35 and $\frac{41}{100}$ is 41. The greatest is $\frac{41}{100}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{41}{100}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.30, 0.35, 0.40, 0.41 -> greatest 41/100.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
