INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1d36581-c6b2-4088-bc69-3e923f3fa683', 'NC26.4.ANR.5', 3, 'choice', 'Compare a fraction with a decimal', 'Which pair of numbers is equal?', '["0.09 and $\\frac{9}{10}$","0.2 and $\\frac{2}{10}$","1.5 and $\\frac{15}{100}$","0.30 and $\\frac{3}{100}$"]', '0.2 and $\frac{2}{10}$', NULL, '0.2 is two tenths, so it equals $\frac{2}{10}$. 0.09 is $\frac{9}{100}$, 1.5 is $\frac{15}{10}$, and 0.30 is $\frac{30}{100}$.', 'checked', '{"lint":[],"solve":{"answer":"0.2 and $\\frac{2}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.30 = 30/100 no; 0.09 = 9/100 no; 1.5 = 150/100 no; 0.2 = 2/10 yes.","run_id":"claude-code","at":"2026-10-17T20:03:15.086Z"}}', 'ai', NULL, NULL)
