INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0be403d2-0413-4c28-917a-e17d35d64399', 'NC26.4.ANR.6', 1, 'numeric', 'Add fractions with like denominators', 'What is $\frac{2}{8} + \frac{3}{8}$?', '[]', '5/8', '2/8+3/8', 'The denominators are the same, so add the numerators: 2 + 3 = 5. The sum is $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/8 + 3/8 = 5/8.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
