INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c24ca82c-50c7-4afb-999a-2a9119ff3f88', 'NC26.4.ANR.6', 1, 'choice', 'Decompose a fraction into a sum', 'Which sum is equal to $\frac{5}{6}$?', '["$\\frac{2}{6} + \\frac{2}{6}$","$\\frac{2}{6} + \\frac{3}{6}$","$\\frac{3}{6} + \\frac{3}{6}$","$\\frac{2}{3} + \\frac{3}{3}$"]', '$\frac{2}{6} + \frac{3}{6}$', NULL, '$\frac{5}{6}$ is 5 sixths. 2 sixths + 3 sixths = 5 sixths. The first sum is 4 sixths, the third is 6 sixths, and the last has thirds, not sixths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{6} + \\frac{3}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/6 + 3/6 = 5/6. Others: 5/3, 6/6, 4/6.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d93a7344-2856-4297-a82f-91a9f3899078', 'NC26.4.ANR.6', 1, 'numeric', 'Add fractions with like denominators', 'Find the sum: $\frac{1}{6} + \frac{2}{6}$', '[]', '3/6', '1/6+2/6', 'The pieces are all sixths, so add the numerators and keep the denominator: $1 + 2 = 3$, so the sum is $\frac{3}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"3/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Like denominators: 1 + 2 = 3 sixths -> 3/6 (= 1/2).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
