INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12b4944d-5610-42c2-96d4-b3887c7b8bef', 'NC26.4.ANR.6', 2, 'choice', 'Find a fraction of a set', 'A bag has 24 marbles. $\frac{3}{8}$ of the marbles are red. How many marbles are red?', '["3","72","21","9"]', '9', '24/8*3', '$\frac{1}{8}$ of 24 is 24 divided by 8 = 3. So $\frac{3}{8}$ of 24 is 3 x 3 = 9 marbles. (3 is only one eighth, and 72 is 24 x 3.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/8 of 24 = 3; 3/8 of 24 = 9.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd02849e-e0ba-4357-9eb0-4eaf494ecbef', 'NC26.4.ANR.6', 2, 'numeric', 'Add fractions with like denominators', 'Add and write the sum as a mixed number: $\frac{5}{8} + \frac{7}{8}$', '[]', '1 4/8', '5/8+7/8', '$\frac{5}{8} + \frac{7}{8} = \frac{12}{8}$. Eight eighths make 1 whole, so $\frac{12}{8} = 1\frac{4}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"1 4/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 + 7/8 = 12/8 = 8/8 + 4/8 = 1 4/8 (= 1 1/2).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a104d28-31bd-4e22-803b-83b167ce3733', 'NC26.4.ANR.6', 2, 'choice', 'Add fractions with like denominators', 'Which addition equation is correct?', '["$\\frac{2}{12} + \\frac{5}{12} = \\frac{7}{12}$","$\\frac{2}{12} + \\frac{5}{12} = \\frac{7}{24}$","$\\frac{3}{8} + \\frac{3}{8} = \\frac{6}{16}$","$\\frac{1}{4} + \\frac{2}{4} = \\frac{2}{4}$"]', '$\frac{2}{12} + \frac{5}{12} = \frac{7}{12}$', NULL, 'When the denominators match, add the numerators and keep the denominator. $2 + 5 = 7$, so $\frac{7}{12}$. The other equations add the denominators or give the wrong numerator.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{12} + \\frac{5}{12} = \\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/12 + 5/12 = 7/12 (true). 7/24 adds denominators; 1/4 + 2/4 = 3/4 not 2/4; 3/8 + 3/8 = 6/8 not 6/16.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccb9927b-9873-4814-b792-6f1e5817c7af', 'NC26.4.ANR.6', 2, 'choice', 'Add fractions with like denominators', 'Find $\frac{4}{9} + \frac{7}{9}$.', '["$\\frac{11}{18}$","$\\frac{3}{9}$","$\\frac{28}{9}$","$1\\frac{2}{9}$"]', '$1\frac{2}{9}$', NULL, '$\frac{4}{9} + \frac{7}{9} = \frac{11}{9}$. Nine ninths make 1 whole, so $\frac{11}{9} = 1\frac{2}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{2}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/9 + 7/9 = 11/9 = 1 2/9. 11/18, 28/9, 3/9 are wrong.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
