INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('837b2d08-820b-471d-9c11-ffaaa2bcab4a', 'NC26.4.ANR.6', 2, 'choice', 'Subtract fractions with like denominators', 'Subtract: $\frac{11}{12} - \frac{4}{12}$', '["$\\frac{7}{24}$","$\\frac{15}{12}$","$\\frac{7}{8}$","$\\frac{7}{12}$"]', '$\frac{7}{12}$', NULL, 'The pieces are twelfths. Subtract the numerators: $11 - 4 = 7$, and the denominator stays 12: $\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/12 - 4/12 = 7/12.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
