INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41ae4180-d324-4155-b1ba-6993247917c1', 'NC26.4.ANR.6', 2, 'choice', 'Subtract fractions with like denominators', 'Which subtraction has a difference of $\frac{3}{8}$?', '["$\\frac{7}{8} - \\frac{4}{8}$","$\\frac{7}{8} - \\frac{3}{8}$","$\\frac{3}{8} - \\frac{3}{8}$","$\\frac{5}{8} - \\frac{3}{8}$"]', '$\frac{7}{8} - \frac{4}{8}$', NULL, '$\frac{7}{8} - \frac{4}{8} = \frac{3}{8}$. The other subtractions leave $\frac{4}{8}$, 0 and $\frac{2}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{8} - \\frac{4}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8-3/8 = 4/8; 5/8-3/8 = 2/8; 3/8-3/8 = 0; 7/8-4/8 = 3/8.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
