INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac261464-8d46-4163-bbda-7d93da8d99e8', 'NC26.4.ANR.6', 2, 'choice', 'Add or subtract fractions in a story', 'Lila walked $\frac{9}{12}$ mile and Ken walked $\frac{4}{12}$ mile. How much farther did Lila walk than Ken?', '["$\\frac{13}{12}$","$\\frac{5}{24}$","$\\frac{4}{12}$","$\\frac{5}{12}$"]', '$\frac{5}{12}$', NULL, 'Subtract: $\frac{9}{12} - \frac{4}{12} = \frac{5}{12}$ mile farther.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/12 - 4/12 = 5/12 mile.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
