INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7aa112ce-defb-42e3-a12e-d41336a6179b', 'NC26.4.ANR.6', 2, 'choice', 'Add mixed numbers with like denominators', 'A baker uses $3\frac{2}{6}$ cups of flour for bread and $1\frac{3}{6}$ cups of flour for rolls. How many cups of flour does the baker use in all?', '["$4\\frac{5}{12}$","$4\\frac{5}{6}$","$3\\frac{5}{6}$","$4\\frac{1}{6}$"]', '$4\frac{5}{6}$', NULL, 'Wholes: $3 + 1 = 4$. Sixths: $\frac{2}{6} + \frac{3}{6} = \frac{5}{6}$. In all, $4\frac{5}{6}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"$4\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 1 = 4; 2/6 + 3/6 = 5/6; 4 5/6 cups.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
