INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de873f0c-d156-4398-9259-6f28d280c7c4', 'NC26.4.ANR.6', 2, 'numeric', 'Add mixed numbers with like denominators', '$2\frac{3}{4} + 1\frac{2}{4}$ Find the sum as a mixed number.', '[]', '4 1/4', '2+3/4+1+2/4', 'Wholes: $2 + 1 = 3$. Fourths: $\frac{3}{4} + \frac{2}{4} = \frac{5}{4} = 1\frac{1}{4}$. Then $3 + 1\frac{1}{4} = 4\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"4 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 1 = 3; 3/4 + 2/4 = 5/4 = 1 1/4; total 4 1/4.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
