INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c6c4302-0d35-4bbf-ab2e-422f9494957c', 'NC26.4.ANR.6', 2, 'choice', 'Add mixed numbers with like denominators', 'What is the sum of $3\frac{1}{5}$ and $2\frac{3}{5}$?', '["$5\\frac{4}{10}$","$4\\frac{4}{5}$","$5\\frac{2}{5}$","$5\\frac{4}{5}$"]', '$5\frac{4}{5}$', NULL, 'Wholes: $3 + 2 = 5$. Fifths: $\frac{1}{5} + \frac{3}{5} = \frac{4}{5}$. The sum is $5\frac{4}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$5\\frac{4}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2 = 5; 1/5 + 3/5 = 4/5; 5 4/5. (5 4/10 adds denominators.)","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
