INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11eee1b0-c727-43f0-b46e-ae816cfbf880', 'NC26.4.ANR.6', 2, 'choice', 'Subtract mixed numbers with like denominators', 'A ribbon is $7\frac{4}{5}$ meters long. Ana cuts off $3\frac{2}{5}$ meters. How many meters of ribbon are left?', '["$4\\frac{2}{5}$","$11\\frac{1}{5}$","$3\\frac{2}{5}$","$4\\frac{2}{10}$"]', '$4\frac{2}{5}$', NULL, 'Wholes: $7 - 3 = 4$. Fifths: $\frac{4}{5} - \frac{2}{5} = \frac{2}{5}$. So $4\frac{2}{5}$ meters are left.', 'checked', '{"lint":[],"solve":{"answer":"$4\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 - 3 = 4; 4/5 - 2/5 = 2/5; 4 2/5 m.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
