INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d872468a-2f55-4945-b31b-3a01ac21f518', 'NC26.4.ANR.6', 2, 'choice', 'Subtract mixed numbers with like denominators', 'Which difference is equal to $2\frac{3}{8}$?', '["$5\\frac{5}{8} - 3\\frac{3}{8}$","$5\\frac{5}{8} - 3\\frac{2}{8}$","$6\\frac{5}{8} - 3\\frac{2}{8}$","$4\\frac{5}{8} - 3\\frac{2}{8}$"]', '$5\frac{5}{8} - 3\frac{2}{8}$', NULL, '$5\frac{5}{8} - 3\frac{2}{8}$: wholes $5 - 3 = 2$, eighths $\frac{5}{8} - \frac{2}{8} = \frac{3}{8}$. That is $2\frac{3}{8}$. The other choices give $2\frac{2}{8}$, $3\frac{3}{8}$ and $1\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$5\\frac{5}{8} - 3\\frac{2}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 5/8 - 3 3/8 = 2 2/8; 6 5/8 - 3 2/8 = 3 3/8; 4 5/8 - 3 2/8 = 1 3/8; 5 5/8 - 3 2/8 = 2 3/8.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
