VALUES ('d9597075-f55b-404a-9dc9-cd1241884e14', 'NC26.4.ANR.6', 2, 'choice', 'Mixed numbers and fractions greater than one', 'Which fraction is equal to $3\frac{1}{2}$?', '["$\\frac{4}{2}$","$\\frac{3}{2}$","$\\frac{5}{2}$","$\\frac{7}{2}$"]', '$\frac{7}{2}$', NULL, 'Each whole is $\frac{2}{2}$, so 3 wholes are $\frac{6}{2}$. Add the extra half: $\frac{7}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 1/2 = 6/2 + 1/2 = 7/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
