INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e15e5ab-d90b-475f-b806-f084bc786c67', 'NC26.4.ANR.6', 2, 'choice', 'Multiply a fraction by a whole number in a story', 'Each glass holds $\frac{2}{3}$ cup of juice. How many cups of juice are in 4 glasses?', '["$2\\frac{2}{3}$","$\\frac{8}{12}$","$1\\frac{1}{3}$","$\\frac{6}{3}$"]', '$2\frac{2}{3}$', NULL, '$4 \times \frac{2}{3} = \frac{8}{3}$. Three thirds make 1 cup, so $\frac{8}{3} = 2\frac{2}{3}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 2/3 = 8/3 = 2 2/3 cups.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('886c2570-6fb9-49c6-a364-9a016e068c5e', 'NC26.4.ANR.6', 2, 'choice', 'Multiply a fraction by a whole number in a story', 'A board is $\frac{3}{5}$ meter long. Three boards of this size are laid end to end. How long is the line of boards, in meters?', '["$\\frac{9}{15}$","$1\\frac{1}{5}$","$1\\frac{4}{5}$","$\\frac{3}{15}$"]', '$1\frac{4}{5}$', NULL, '$3 \times \frac{3}{5} = \frac{9}{5}$. Five fifths make 1 meter, so $\frac{9}{5} = 1\frac{4}{5}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{4}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3/5 = 9/5 = 1 4/5 m.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65894021-6d0a-4274-bd14-c973870f26ba', 'NC26.4.ANR.6', 2, 'choice', 'Find a fraction of a number', 'What is $\frac{3}{5}$ of 20?', '["4","60","12","23"]', '12', '3/5*20', 'One fifth of 20 is $20 \div 5 = 4$. Three fifths is $3 \times 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 of 20 = 4; 3 x 4 = 12.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
