INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23e186f5-6cc9-4dfc-9ea7-0f93de185363', 'NC26.4.ANR.6', 2, 'choice', 'Find a fraction of a number', 'Which number is equal to $\frac{3}{4}$ of 24?', '["6","18","21","72"]', '18', '3/4*24', 'One fourth of 24 is $24 \div 4 = 6$. Three fourths is $3 \times 6 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 of 24 = 6; 3 x 6 = 18.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
