INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3acc3edd-2d28-439f-a8a6-9bec41492fe0', 'NC26.4.ANR.6', 2, 'choice', 'Find a fraction of a set in a story', 'A farm has 30 animals. $\frac{5}{6}$ of them are hens. How many hens are on the farm?', '["5","25","35","150"]', '25', '5/6*30', 'One sixth of 30 is $30 \div 6 = 5$. Five sixths is $5 \times 5 = 25$ hens.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 / 6 = 5; 5 x 5 = 25 hens.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
