INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('658b721b-2da3-4be4-bed7-5bf57fabee07', 'NC26.4.ANR.6', 2, 'numeric', 'Find a missing fraction in an equation', '$\frac{n}{12} - \frac{5}{12} = \frac{4}{12}$ Find $n$.', '[]', '9', '4+5', 'The starting amount is the difference plus what was taken away: $4 + 5 = 9$. So $n = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n - 5 = 4, n = 9.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
