INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee07f935-3472-4efc-ba68-73d55ac4052c', 'NC26.4.ANR.6', 2, 'choice', 'Explain fraction operations', 'Ana added $\frac{2}{5} + \frac{1}{5}$ and got $\frac{3}{10}$. What mistake did Ana make?', '["She subtracted the numerators instead of adding.","She added the denominators as well as the numerators.","She added the numerators but forgot the whole numbers.","She multiplied the numerators instead of adding."]', 'She added the denominators as well as the numerators.', NULL, 'The correct sum is $\frac{3}{5}$. Ana got $\frac{3}{10}$ because she added $5 + 5 = 10$ for the denominator. The denominator stays 5.', 'checked', '{"lint":[],"solve":{"answer":"She added the denominators as well as the numerators.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct sum 3/5; she got 3/10 by adding 5 + 5 for the denominator.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
