INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61219427-e983-4541-bffb-52a1ac586837', 'NC26.4.ANR.6', 3, 'numeric', 'Add fractions with like denominators', 'Add all three fractions: $\frac{3}{10} + \frac{9}{10} + \frac{8}{10}$', '[]', '2', '3/10+9/10+8/10', '$3 + 9 + 8 = 20$ tenths, which is $\frac{20}{10} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 9 + 8 = 20 tenths = 20/10 = 2.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
