INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9690fd73-307e-4937-b7c0-d156b1833bfd', 'NC26.4.ANR.6', 3, 'numeric', 'Subtract fractions with like denominators', 'Subtract and write the answer as a fraction: $1 - \frac{3}{8}$', '[]', '5/8', '1-3/8', 'Write 1 as $\frac{8}{8}$. Then $\frac{8}{8} - \frac{3}{8} = \frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 = 8/8; 8/8 - 3/8 = 5/8.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
