INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdcedd2f-8ca9-4371-86de-ade4d2aeb292', 'NC26.4.ANR.6', 3, 'numeric', 'Subtract fractions with like denominators', 'Subtract and write the answer as a mixed number: $3 - \frac{2}{5}$', '[]', '2 3/5', '3-2/5', 'Take 1 whole from the 3 and write it as $\frac{5}{5}$. Then 3 is $2\frac{5}{5}$, and $2\frac{5}{5} - \frac{2}{5} = 2\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2 3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 = 2 5/5; 2 5/5 - 2/5 = 2 3/5.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
