INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('677943cf-99d2-4b62-bedf-d378acf8a46b', 'NC26.4.ANR.6', 3, 'numeric', 'Add or subtract fractions in a story', 'A rope is $\frac{11}{12}$ yard long. Ben cuts off $\frac{5}{12}$ yard and later cuts off another $\frac{3}{12}$ yard. How many yards of rope are left?', '[]', '3/12', '11/12-5/12-3/12', 'He cuts off $\frac{5}{12} + \frac{3}{12} = \frac{8}{12}$ yard in all. Then $\frac{11}{12} - \frac{8}{12} = \frac{3}{12}$ yard is left.', 'checked', '{"lint":[],"solve":{"answer":"3/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11/12 - 5/12 = 6/12; 6/12 - 3/12 = 3/12 yard (= 1/4).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
