INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db76ef53-c322-4f0d-98b9-587a78f7e86d', 'NC26.4.ANR.6', 3, 'numeric', 'Add or subtract fractions in a story', 'Pete ran $\frac{7}{10}$ mile on Monday and $\frac{5}{10}$ mile on Tuesday. How many miles did he run altogether? Write your answer as a mixed number.', '[]', '1 2/10', '7/10+5/10', '$\frac{7}{10} + \frac{5}{10} = \frac{12}{10}$. Ten tenths make 1 whole, so $\frac{12}{10} = 1\frac{2}{10}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"1 2/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/10 + 5/10 = 12/10 = 1 2/10 miles (= 1 1/5).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d598f7e7-9895-4146-8196-ca1e898cc008', 'NC26.4.ANR.6', 3, 'choice', 'Add mixed numbers with like denominators', 'On Saturday Sofia walked $2\frac{5}{8}$ miles and on Sunday she walked $3\frac{6}{8}$ miles. How many miles did she walk on the two days?', '["$6\\frac{3}{16}$","$6\\frac{3}{8}$","$5\\frac{3}{8}$","$6\\frac{1}{8}$"]', '$6\frac{3}{8}$', NULL, 'Wholes: $2 + 3 = 5$. Eighths: $\frac{5}{8} + \frac{6}{8} = \frac{11}{8} = 1\frac{3}{8}$. Then $5 + 1\frac{3}{8} = 6\frac{3}{8}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"$6\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 = 5; 5/8 + 6/8 = 11/8 = 1 3/8; total 6 3/8 miles.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad781c09-e0eb-4535-bef5-bb202fbd520b', 'NC26.4.ANR.6', 3, 'numeric', 'Add mixed numbers with like denominators', '$5\frac{7}{10} + 2\frac{6}{10}$ Find the sum.', '[]', '8 3/10', '5+7/10+2+6/10', 'Wholes: $5 + 2 = 7$. Tenths: $\frac{7}{10} + \frac{6}{10} = \frac{13}{10} = 1\frac{3}{10}$. Then $7 + 1\frac{3}{10} = 8\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"8 3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 2 = 7; 7/10 + 6/10 = 13/10 = 1 3/10; total 8 3/10.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93debbaf-e7ee-4647-a08f-f7e7958dbd84', 'NC26.4.ANR.6', 3, 'numeric', 'Add mixed numbers with like denominators', 'Find the total of three lengths in feet: $1\frac{3}{8}$, $2\frac{4}{8}$ and $1\frac{6}{8}$.', '[]', '5 5/8', '1+3/8+2+4/8+1+6/8', 'Wholes: $1 + 2 + 1 = 4$. Eighths: $\frac{3}{8} + \frac{4}{8} + \frac{6}{8} = \frac{13}{8} = 1\frac{5}{8}$. Then $4 + 1\frac{5}{8} = 5\frac{5}{8}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"5 5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 + 2 + 1 = 4; 3/8 + 4/8 + 6/8 = 13/8 = 1 5/8; total 5 5/8 feet.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
