INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de8c10e4-839d-4f86-bdb1-c8daa0184ecd', 'NC26.4.ANR.6', 3, 'numeric', 'Subtract mixed numbers with like denominators', '$5\frac{1}{6} - 2\frac{4}{6}$ What is the difference?', '[]', '2 3/6', '5+1/6-2-4/6', 'There are not enough sixths to take away 4. Write $5\frac{1}{6}$ as $4\frac{7}{6}$. Then $4\frac{7}{6} - 2\frac{4}{6} = 2\frac{3}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"2 3/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/6 = 4 7/6; 4 7/6 - 2 4/6 = 2 3/6 (= 2 1/2).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
