INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6abcd38-edb5-4dd8-83b4-eedebef67540', 'NC26.4.ANR.6', 3, 'numeric', 'Subtract mixed numbers with like denominators', 'A board is $9\frac{3}{8}$ feet long. A carpenter cuts off $4\frac{5}{8}$ feet. How many feet of the board are left?', '[]', '4 6/8', '9+3/8-4-5/8', 'Write $9\frac{3}{8}$ as $8\frac{11}{8}$. Then $8\frac{11}{8} - 4\frac{5}{8} = 4\frac{6}{8}$ feet.', 'checked', '{"lint":[],"solve":{"answer":"4 6/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 3/8 = 8 11/8; 8 11/8 - 4 5/8 = 4 6/8 feet (= 4 3/4).","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
