INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe215eaf-08aa-4dfc-8f62-111f8d349af0', 'NC26.4.ANR.6', 3, 'numeric', 'Mixed numbers and fractions greater than one', 'A cook has $5\frac{5}{6}$ cups of rice and uses a scoop that holds $\frac{1}{6}$ cup. How many scoops of rice does the cook have?', '[]', '35', '(5+5/6)/(1/6)', 'Each cup holds 6 scoops, so 5 cups are $5 \times 6 = 30$ scoops. Add the extra 5 sixths: 35 scoops. That is $5\frac{5}{6} = \frac{35}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''How many scoops of rice does the cook have?'' is slightly loose; ''how many full 1/6-cup scoops'' would be clearer. Answer unaffected.","work":"5 5/6 = 30/6 + 5/6 = 35/6, i.e. 35 sixth-cup scoops.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
