INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c615eb2-c8ec-4f6d-b951-05bc01002b90', 'NC26.4.ANR.6', 3, 'choice', 'Mixed numbers and fractions greater than one', 'Which mixed number is equal to $\frac{29}{6}$?', '["$4\\frac{1}{6}$","$5\\frac{5}{6}$","$5\\frac{1}{6}$","$4\\frac{5}{6}$"]', '$4\frac{5}{6}$', NULL, '$29 \div 6 = 4$ with 5 left over, so $\frac{29}{6} = 4\frac{5}{6}$. Check: $4 \times 6 + 5 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"$4\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 24, 29 - 24 = 5: 29/6 = 4 5/6.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
