INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d9332d3-d0c4-4525-bf37-889a8877d806', 'NC26.4.ANR.6', 3, 'choice', 'Decompose a fraction or a mixed number', 'Which sum is equal to $2\frac{1}{3}$?', '["$1 + 1 + \\frac{1}{2}$","$\\frac{2}{3} + \\frac{2}{3} + \\frac{2}{3}$","$\\frac{3}{3} + \\frac{3}{3} + \\frac{1}{3}$","$\\frac{3}{3} + \\frac{3}{3} + \\frac{3}{3}$"]', '$\frac{3}{3} + \frac{3}{3} + \frac{1}{3}$', NULL, 'Each $\frac{3}{3}$ is 1 whole, so $\frac{3}{3} + \frac{3}{3} + \frac{1}{3} = 2 + \frac{1}{3} = 2\frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{3} + \\frac{3}{3} + \\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/3 + 3/3 + 1/3 = 1 + 1 + 1/3 = 2 1/3. Others: 3, 2, 2 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb0c9d8e-8ebb-4ec0-b2a2-cd819f7f23d9', 'NC26.4.ANR.6', 3, 'numeric', 'Decompose a fraction or a mixed number', '$3\frac{2}{5} = 2 + \frac{n}{5}$ What is $n$?', '[]', '7', '(3+2/5-2)*5', 'Take 2 wholes away from $3\frac{2}{5}$ and 1 whole and $\frac{2}{5}$ are left: $1\frac{2}{5} = \frac{7}{5}$. So $n = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 2/5 = 2 + 1 + 2/5 = 2 + 5/5 + 2/5 = 2 + 7/5; n = 7.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
