INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87e81224-d40c-40d2-92dd-6ae2284ea8b6', 'NC26.4.ANR.6', 3, 'numeric', 'Decompose a fraction or a mixed number', 'How many fourths are in $2\frac{1}{4}$?', '[]', '9', '(2+1/4)/(1/4)', 'Each whole has 4 fourths, so 2 wholes have 8 fourths. Add 1 more fourth: 9 fourths.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 1/4 = 8/4 + 1/4 = 9/4; 9 fourths.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
