INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5ca833a-dc2b-4564-8025-1c780698c0ea', 'NC26.4.ANR.6', 3, 'numeric', 'Multiply a fraction by a whole number', '$7 \times \frac{5}{6}$ Write the product as a mixed number.', '[]', '5 5/6', '7*5/6', '$7 \times 5 = 35$ sixths, which is $\frac{35}{6}$. Since $35 = 5 \times 6 + 5$, this is $5\frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"5 5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 5/6 = 35/6 = 5 5/6.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
