VALUES ('8998c6c6-3000-4741-a550-ce8bc23ba69d', 'NC26.4.ANR.6', 3, 'numeric', 'Multiply a fraction by a whole number', 'Write $6 \times \frac{5}{12}$ as a mixed number.', '[]', '2 6/12', '6*5/12', '$6 \times 5 = 30$ twelfths, which is $\frac{30}{12}$. Since $30 = 2 \times 12 + 6$, this is $2\frac{6}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 5/12 = 30/12 = 2 6/12 = 2 1/2.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
