INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a5b0dd4-80ed-4b56-91c9-612c11a350b3', 'NC26.4.ANR.6', 3, 'choice', 'Multiply a fraction by a whole number in a story', 'A frog jumps $\frac{5}{6}$ meter each time and makes 4 jumps. How far does it travel in all?', '["$\\frac{9}{6}$","$\\frac{20}{24}$","$4\\frac{5}{6}$","$3\\frac{2}{6}$"]', '$3\frac{2}{6}$', NULL, '$4 \times \frac{5}{6} = \frac{20}{6}$. Since $20 = 3 \times 6 + 2$, this is $3\frac{2}{6}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{2}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 5/6 = 20/6 = 3 2/6 m.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
