INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be889e51-ecea-4723-8738-022f573e8389', 'NC26.4.ANR.6', 3, 'numeric', 'Find a fraction of a number', 'What is $\frac{7}{8}$ of 56?', '[]', '49', '7/8*56', 'One eighth of 56 is $56 \div 8 = 7$. Seven eighths is $7 \times 7 = 49$.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/8 of 56 = 7; 7 x 7 = 49.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
