INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3f0efb5-725e-47e6-8da2-5a5b907c3862', 'NC26.4.ANR.6', 3, 'numeric', 'Find a fraction of a set in a story', 'There are 36 students in a club. $\frac{1}{4}$ of them play chess and $\frac{1}{3}$ of them play checkers. No student plays both games. How many students play chess or checkers?', '[]', '21', '36/4+36/3', 'Chess: $36 \div 4 = 9$ students. Checkers: $36 \div 3 = 12$ students. Together, $9 + 12 = 21$ students.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Chess 36/4 = 9; checkers 36/3 = 12; no overlap, 9 + 12 = 21.","run_id":"claude-code","at":"2026-10-17T20:03:15.124Z"}}', 'ai', NULL, NULL)
