INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19a6fdeb-f283-4127-912d-61019cb6f55a', 'NC26.4.ANR.7', 1, 'choice', 'Find the rule of a number pattern', 'Which rule describes this pattern? 5, 10, 15, 20, 25', '["Multiply by 2","Add 10","Add 5","Add 4"]', 'Add 5', NULL, 'Each number is 5 more than the one before: 10 - 5 = 5, 15 - 10 = 5, and so on. The rule is add 5. (Multiplying by 2 works for 5 to 10, but 10 x 2 = 20, not 15.)', 'checked', '{"lint":[],"solve":{"answer":"Add 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each term is 5 more than the one before: add 5. Multiply by 2 fails at 10 -> 15.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a233c8e6-35e3-4cc6-a05d-12752302d999', 'NC26.4.ANR.7', 1, 'choice', 'Tell growing patterns from repeating patterns', 'Which of these is a growing pattern?', '["red, blue, red, blue, red, blue","A, B, B, A, B, B, A, B","triangle, circle, triangle, circle","2, 4, 6, 8, 10, 12"]', '2, 4, 6, 8, 10, 12', NULL, 'A repeating pattern has a part that repeats over and over. A growing pattern changes by a rule, such as getting 2 bigger each time. Only 2, 4, 6, 8, 10, 12 grows. The others repeat.', 'checked', '{"lint":[],"solve":{"answer":"2, 4, 6, 8, 10, 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 4, 6, 8, 10, 12 increases by 2 each time (growing). The other three repeat a unit.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
