INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('495d34a7-67b1-49c0-bf29-504b93d00441', 'NC26.4.ANR.7', 1, 'choice', 'Generate a pattern from a rule', 'Which list is a pattern that starts at 6 and follows the rule "add 5"?', '["6, 12, 18, 24","6, 11, 16, 21","5, 10, 15, 20","6, 10, 14, 18"]', '6, 11, 16, 21', NULL, 'Start at 6. Then 6 + 5 = 11, 11 + 5 = 16 and 16 + 5 = 21. The list 6, 11, 16, 21 is the one.', 'checked', '{"lint":[],"solve":{"answer":"6, 11, 16, 21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6, 6+5=11, 16, 21. Only 6, 11, 16, 21 starts at 6 and adds 5.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
