INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf0c7035-1880-4810-9825-00505e74cb7b', 'NC26.4.ANR.7', 3, 'numeric', 'Find a missing number or an error in a pattern', 'Ravi writes a pattern with the rule "subtract 6" starting at 50: 50, 44, 38, 33, 26, 20. One number in his list is wrong. Which number is it?', '[]', '33', NULL, '50, 44, 38, then 38 - 6 = 32, not 33. After that, 32 - 6 = 26 and 26 - 6 = 20 fit. So 33 is the wrong number.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50, 44, 38, 32, 26, 20. 33 is wrong.","run_id":"claude-code","at":"2026-10-17T19:20:19.061Z"}}', 'ai', NULL, NULL)
