INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('504d46d8-6cf7-490b-836a-73c4d2f3f910', 'NC26.4.SGMR.1', 3, 'choice', 'Multi-step angle problems', 'Angle P measures 40 degrees. Angle Q is twice as large as angle P. Angle R is 25 degrees less than angle Q. The three angles are placed side by side. What is the measure of the whole angle, in degrees?', '["120","175","145","225"]', '175', '40+2*40+(2*40-25)', 'Angle Q is 2 x 40 = 80 degrees. Angle R is 80 - 25 = 55 degrees. Together: 40 + 80 + 55 = 175 degrees.', 'checked', '{"lint":[],"solve":{"answer":"175","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 40, Q = 80, R = 80 - 25 = 55. Total 40 + 80 + 55 = 175.","run_id":"claude-code","at":"2026-10-17T19:20:19.100Z"}}', 'ai', NULL, NULL)
