INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd68db1f-1add-4e0c-9581-385a28f3831b', 'NC26.4.SGMR.2', 2, 'choice', 'Notation for points, lines, rays and segments', 'Which statement about a ray and a line segment is true?', '["A ray has one endpoint and a line segment has two.","A ray has two endpoints and a line segment has one.","A ray has no endpoints and a line segment has two.","A ray and a line segment both have one endpoint."]', 'A ray has one endpoint and a line segment has two.', NULL, 'A ray begins at one endpoint and goes on forever. A line segment is a piece of a line with an endpoint at each end.', 'checked', '{"lint":[],"solve":{"answer":"A ray has one endpoint and a line segment has two.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A ray has one endpoint; a segment has two.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
