INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59010f22-8bcd-4ccc-9bb8-3c4867d35cf8', 'NC26.4.SGMR.2', 2, 'choice', 'Classify a triangle by its angles', 'Which set of angle measures belongs to a right triangle?', '["90, 40 and 50 degrees","80, 50 and 50 degrees","100, 40 and 40 degrees","60, 60 and 60 degrees"]', '90, 40 and 50 degrees', NULL, 'A right triangle must have one 90 degree angle. The set 80, 50, 50 is all acute, 100, 40, 40 has an obtuse angle, and 60, 60, 60 is all acute.', 'checked', '{"lint":[],"solve":{"answer":"90, 40 and 50 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 90, 40, 50 contains a 90 degree angle (sum 180). Others: obtuse, acute, acute.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
