INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91f54e52-649e-42e6-af13-88d97045975f', 'NC26.4.SGMR.2', 2, 'numeric', 'Parallel sides and right angles of a quadrilateral', 'A tile design uses 6 rectangles and 4 squares. How many right angles are there in all the shapes together?', '[]', '40', '(6+4)*4', 'Each rectangle and each square has 4 right angles. There are $6 + 4 = 10$ shapes, so $10 \times 4 = 40$ right angles.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each rectangle and square has 4 right angles: 6x4 + 4x4 = 24 + 16 = 40.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
