VALUES ('9b69b413-df4e-4920-a0f9-91c922903fdb', 'NC26.4.SGMR.2', 2, 'numeric', 'Relationships among quadrilaterals', 'Think about a square, a rectangle and a rhombus. How many of these three shapes always have four sides of equal length?', '[]', '2', NULL, 'A square and a rhombus always have four equal sides. A rectangle can have long sides and short sides. So 2 shapes.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square yes, rhombus yes, rectangle not always. Count = 2.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4823f276-8823-406c-b64d-c7ae3a93d7a9', 'NC26.4.SGMR.2', 2, 'choice', 'Relationships among quadrilaterals', 'Which shape belongs to both the group of rectangles and the group of rhombuses?', '["a rectangle with two long sides and two short sides","a rhombus with no right angles","a parallelogram with unequal sides","a square"]', 'a square', NULL, 'A rectangle needs four right angles and a rhombus needs four equal sides. Only a square has both.', 'checked', '{"lint":[],"solve":{"answer":"a square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has four right angles (rectangle) and four equal sides (rhombus).","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df0fa3a9-63fd-4dc0-a3ac-4a5c95464c0b', 'NC26.4.SGMR.2', 2, 'numeric', 'Relationships among quadrilaterals', 'Think about these four shapes: a square, a rectangle, a rhombus and a parallelogram. How many of them always have two pairs of parallel sides?', '[]', '4', NULL, 'Each of these four shapes has both pairs of opposite sides parallel. So all 4 do.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, rectangle, rhombus and parallelogram are all parallelograms: 4.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9350c88-d952-4fc9-8f5d-599d8d1a63a9', 'NC26.4.SGMR.2', 2, 'choice', 'Relationships among quadrilaterals', 'Which group of names fits a square?', '["rectangle only","rectangle, rhombus and parallelogram","rhombus only","parallelogram only"]', 'rectangle, rhombus and parallelogram', NULL, 'A square has four right angles (rectangle), four equal sides (rhombus), and two pairs of parallel sides (parallelogram). So all three names fit.', 'checked', '{"lint":[],"solve":{"answer":"rectangle, rhombus and parallelogram","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square is a rectangle, a rhombus and a parallelogram.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
