INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff9f76af-bb14-4de2-8e7f-b1ec8c0a25f8', 'NC26.4.SGMR.2', 2, 'numeric', 'Sort and count shapes by an attribute', 'Zoe has cut-out shapes: 3 triangles, 2 squares and 4 rectangles. How many of her shapes are quadrilaterals?', '[]', '6', '2+4', 'Squares and rectangles have 4 sides, so they are quadrilaterals. Triangles are not. $2 + 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares and rectangles are quadrilaterals: 2 + 4 = 6.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
