INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c9d027b-5662-49d5-9f0e-c0e63110accd', 'NC26.4.SGMR.2', 2, 'numeric', 'Side lengths and perimeter of triangles and quadrilaterals', 'An isosceles triangle has one side of 6 cm that is different from the other two sides. The other two sides are equal. The perimeter of the triangle is 22 cm. How long is each of the two equal sides, in centimeters?', '[]', '8', '(22-6)/2', 'The two equal sides together measure $22 - 6 = 16$ centimeters. Each one is $16 \div 2 = 8$ centimeters. Check: $8 + 8 + 6 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22-6=16; 16/2=8. Check 8,8,6 is a valid triangle.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
