INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0723da12-fc96-49b6-a2da-da1dcddda4b6', 'NC26.4.SGMR.2', 3, 'choice', 'Classify a triangle by both its angles and its sides', 'A triangle has sides of 5 cm, 5 cm and 6 cm, and all three of its angles are less than 90 degrees. Which name fits?', '["acute scalene triangle","obtuse isosceles triangle","acute isosceles triangle","right isosceles triangle"]', 'acute isosceles triangle', NULL, 'Two sides are equal (5 cm and 5 cm), so it is isosceles. All angles are less than 90 degrees, so it is acute.', 'checked', '{"lint":[],"solve":{"answer":"acute isosceles triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All angles < 90: acute. 5, 5, 6 has two equal sides: isosceles.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b65dfe-45d4-48b1-a026-f14f50bf38ed', 'NC26.4.SGMR.2', 3, 'choice', 'Name a quadrilateral from its sides and angles', 'Ana draws a four-sided shape with four equal sides. Which fact would tell you that it must be a square?', '["Its opposite sides are parallel.","Its opposite angles are equal.","All four of its angles are right angles.","Its perimeter is 20 cm."]', 'All four of its angles are right angles.', NULL, 'Every shape with four equal sides (a rhombus) has parallel opposite sides and equal opposite angles. Only four right angles makes it a square. The perimeter does not decide the shape.', 'checked', '{"lint":[],"solve":{"answer":"All four of its angles are right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four equal sides is a rhombus; adding four right angles makes it a square. Parallel sides and equal opposite angles hold for any rhombus; perimeter says nothing.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1cb1e88-1a28-405f-95c7-78a08551e9b9', 'NC26.4.SGMR.2', 3, 'choice', 'Name a quadrilateral from its sides and angles', 'A parallelogram is drawn. Which fact would tell you that it must be a rectangle?', '["It has four right angles.","Its opposite sides are equal.","It has two pairs of parallel sides.","Its opposite angles are equal."]', 'It has four right angles.', NULL, 'Every parallelogram has equal opposite sides, two pairs of parallel sides, and equal opposite angles. Only having four right angles makes it a rectangle.', 'checked', '{"lint":[],"solve":{"answer":"It has four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every parallelogram has equal opposite angles, two pairs of parallel sides and equal opposite sides. Four right angles makes it a rectangle.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be4da827-7cc1-4b22-8534-59794a274db0', 'NC26.4.SGMR.2', 3, 'choice', 'Parallel sides and right angles of a quadrilateral', 'Which statement is true about parallelograms and rectangles?', '["Only a parallelogram has four right angles.","Both have two pairs of parallel sides.","Only a rectangle has two pairs of parallel sides.","A rectangle has no right angles."]', 'Both have two pairs of parallel sides.', NULL, 'Both pairs of opposite sides are parallel in a parallelogram and in a rectangle. A rectangle has four right angles; a parallelogram might not have any.', 'checked', '{"lint":[],"solve":{"answer":"Both have two pairs of parallel sides.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rectangles and parallelograms have two pairs of parallel sides. A rectangle has right angles; a parallelogram need not.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
