INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11407056-6006-423f-9739-b56a893a2ae4', 'NC26.4.SGMR.2', 3, 'choice', 'Parallel sides and right angles of a quadrilateral', 'A quadrilateral has exactly one pair of parallel sides and two right angles. Which shape could it be?', '["rectangle","rhombus","parallelogram","trapezoid"]', 'trapezoid', NULL, 'Exactly one pair of parallel sides rules out a rectangle, a rhombus and a parallelogram, which all have two pairs. A trapezoid can have exactly one pair, and it can have two right angles.', 'checked', '{"lint":[],"solve":{"answer":"trapezoid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelogram, rhombus and rectangle have two parallel pairs. A right trapezoid has one pair and two right angles.","run_id":"claude-code","at":"2026-10-17T19:22:54.972Z"}}', 'ai', NULL, NULL)
