VALUES ('7c4f8b03-8639-4a61-b4b6-98d561331c64', 'NC26.4.SGMR.3', 1, 'numeric', 'Find elapsed time across the hour', 'The first class of the day starts at 8:45 a.m. and ends at 9:35 a.m. How many minutes long is the class?', '[]', '50', '15+35', 'From 8:45 to 9:00 is 15 minutes. From 9:00 to 9:35 is 35 more minutes. In all, $15 + 35 = 50$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8:45 to 9:00 is 15 min; 9:00 to 9:35 is 35 min. 15 + 35 = 50.","run_id":"claude-code","at":"2026-10-17T19:22:55.011Z"}}', 'ai', NULL, NULL)
