INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48e6c0d4-db30-4805-836f-eea156351e56', 'NC26.4.SGMR.4', 1, 'choice', 'Find a missing side from the perimeter', 'A rectangle has a perimeter of 18 meters and a width of 3 meters. What is its length in meters?', '["6","15","12","9"]', '6', '(18-2*3)/2', 'The two widths use 6 meters, leaving $18 - 6 = 12$ meters for the two lengths, so one length is 6 meters. 9 is half the perimeter, which is length plus width.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 18 / 2 = 9. Length = 9 - 3 = 6 meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
