INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2483659-2b0a-4e5c-abda-bfacca1a345e', 'NC26.4.SGMR.4', 1, 'numeric', 'Find a missing side from the perimeter', 'The two lengths of a rectangle add up to 10 cm, and its perimeter is 16 cm. How many centimeters is one width?', '[]', '3', '(16-10)/2', 'The two widths use $16 - 10 = 6$ cm, so one width is $6 \div 2 = 3$ cm.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = two lengths + two widths. Two widths = 16 - 10 = 6 cm, so one width = 3 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
