INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9dd44b05-c17f-4c2b-86cb-33cf111be144', 'NC26.4.SGMR.4', 1, 'numeric', 'Area of a rectilinear figure: add rectangles', 'An L-shaped patio is made of a 6 foot by 3 foot rectangle joined to a 4 foot by 2 foot rectangle. The two parts touch along an edge but do not overlap. What is the area of the patio in square feet?', '[]', '26', '6*3+4*2', '$6 \times 3 = 18$ and $4 \times 2 = 8$. Total area = $18 + 8 = 26$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 6 x 3 + 4 x 2 = 18 + 8 = 26 square feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
