INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc124fa1-862c-4c13-aa9e-9b17892e6bdc', 'NC26.4.SGMR.4', 1, 'numeric', 'Fixed area, changing perimeter', 'Eli has 12 square tiles with sides of 1 inch. He makes a rectangle 3 tiles wide and 4 tiles long, with no gaps. Then he uses the same 12 tiles to make a rectangle 2 tiles wide and 6 tiles long. How many inches greater is the perimeter of the second rectangle than the first?', '[]', '2', '2*(2+6)-2*(3+4)', 'First rectangle: $2 \times (3 + 4) = 14$ inches. Second rectangle: $2 \times (2 + 6) = 16$ inches. The area is 12 square inches both times, but the perimeter is $16 - 14 = 2$ inches greater.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First: 3 x 4, perimeter 2 x (3 + 4) = 14 in. Second: 2 x 6, perimeter 2 x (2 + 6) = 16 in. Difference = 2 inches.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
