INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afe21b08-f276-45ca-9601-c3702ad88c37', 'NC26.4.SGMR.4', 1, 'choice', 'Fixed area, changing perimeter', 'Rectangle X is 4 units by 4 units and rectangle Y is 8 units by 2 units. Both have an area of 16 square units. Which statement is true?', '["Rectangle X has the greater perimeter","Rectangle Y has the greater perimeter","The two rectangles have the same perimeter","Rectangle Y has the greater area"]', 'Rectangle Y has the greater perimeter', NULL, 'X: $2 \times (4 + 4) = 16$ units. Y: $2 \times (8 + 2) = 20$ units. The areas are the same, but Y has the greater perimeter.', 'checked', '{"lint":[],"solve":{"answer":"Rectangle Y has the greater perimeter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X perimeter = 2 x (4 + 4) = 16; Y perimeter = 2 x (8 + 2) = 20. Areas equal. So Y has the greater perimeter.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
