INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44d364ee-79b4-454e-862f-dc1983d43a9d', 'NC26.4.SGMR.4', 1, 'numeric', 'Fixed perimeter, changing area', 'A rectangle is 5 units long and 1 unit wide. A second rectangle has the same perimeter and is 3 units long. How many square units greater is the area of the second rectangle than the area of the first?', '[]', '4', '3*3-5*1', 'The first has perimeter $2 \times (5 + 1) = 12$. The second is 3 long, so its width is $6 - 3 = 3$. Its area is $3 \times 3 = 9$ and the first area is $5 \times 1 = 5$. The difference is $9 - 5 = 4$ square units.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First: 5 x 1, perimeter 12, area 5. Second: length 3, so width = 6 - 3 = 3, area 9. Difference = 9 - 5 = 4 square units.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
