INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac0086c9-1ef2-471c-af55-90c18aef6b3a', 'NC26.4.SGMR.4', 2, 'choice', 'Area of a rectilinear figure: add rectangles', 'An L-shaped rug is made of a 9 by 2 rectangle and a 4 by 3 rectangle that do not overlap. Which expression gives the area of the rug in square units?', '["$(9 + 2) \\times (4 + 3)$","$9 \\times 2 \\times 4 \\times 3$","$2 \\times (9 + 2) + 2 \\times (4 + 3)$","$(9 \\times 2) + (4 \\times 3)$"]', '$(9 \times 2) + (4 \times 3)$', NULL, 'The area of each part is length $\times$ width, and the two areas are added.', 'checked', '{"lint":[],"solve":{"answer":"$(9 \\times 2) + (4 \\times 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area of non-overlapping parts adds: (9 x 2) + (4 x 3) = 18 + 12 = 30. Other options multiply sums, multiply all, or give perimeters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
