INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c2eb2d8-3c34-4816-b253-f6bbeb46306c', 'NC26.4.SGMR.4', 2, 'choice', 'Area of a rectilinear figure: subtract a cut-out', 'A piece of cardboard is 15 cm long and 10 cm wide. A square with sides of 4 cm is cut out of one corner. What is the area of the cardboard that is left, in square centimeters?', '["150","166","134","16"]', '134', '15*10-4*4', 'Whole piece: $15 \times 10 = 150$. Cut-out: $4 \times 4 = 16$. Left: $150 - 16 = 134$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"134","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 x 10 - 4 x 4 = 150 - 16 = 134 square cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
