INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23c2de87-2ea8-4b40-bd4b-f6c6ec60bcbe', 'NC26.4.SGMR.4', 2, 'choice', 'Area of a rectilinear figure: subtract a cut-out', 'A wall is 12 feet long and 8 feet tall. A door in it is 7 feet tall and 3 feet wide, and the door is not painted. How many square feet of the wall are painted?', '["96","21","117","75"]', '75', '12*8-7*3', 'Wall: $12 \times 8 = 96$. Door: $7 \times 3 = 21$. Painted: $96 - 21 = 75$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wall 12 x 8 = 96; door 7 x 3 = 21. Painted = 96 - 21 = 75 square feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
