INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2152a5c9-7963-4718-99f6-03ee457be38a', 'NC26.4.SGMR.4', 2, 'numeric', 'Fixed area, changing perimeter', 'A rectangle with an area of 30 square meters is 10 meters long. A second rectangle with the same area is 5 meters long. How many meters greater is the perimeter of the first rectangle than the perimeter of the second?', '[]', '4', '2*(10+30/10)-2*(5+30/5)', 'First: width $30 \div 10 = 3$, perimeter $2 \times (10 + 3) = 26$. Second: width $30 \div 5 = 6$, perimeter $2 \times (5 + 6) = 22$. The difference is $26 - 22 = 4$ meters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First: 10 x 3, perimeter 26. Second: 5 x 6, perimeter 22. Difference = 4 meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('741beff6-b2ef-4c74-a2a0-69caf7c72fc0', 'NC26.4.SGMR.4', 2, 'choice', 'Fixed area, changing perimeter', 'A gardener wants a rectangular bed with an area of 48 square feet and sides that are whole numbers of feet. Which size has the smallest perimeter?', '["4 feet by 12 feet","3 feet by 16 feet","2 feet by 24 feet","6 feet by 8 feet"]', '6 feet by 8 feet', NULL, 'All four have an area of 48. Perimeters: $6$ by $8$ is 28, $4$ by $12$ is 32, $3$ by $16$ is 38, $2$ by $24$ is 52. The sides closest in size give the smallest perimeter: 6 feet by 8 feet.', 'checked', '{"lint":[],"solve":{"answer":"6 feet by 8 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 2x24 -> 52; 4x12 -> 32; 3x16 -> 38; 6x8 -> 28. Smallest is 6 by 8.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8132e9bb-0119-413f-bc42-7040e6b68aa6', 'NC26.4.SGMR.4', 2, 'choice', 'Fixed area, changing perimeter', 'Three rectangles each have an area of 24 square units. They measure 1 by 24, 3 by 8, and 4 by 6. Which statement is NOT true?', '["All three rectangles have the same perimeter","The 4 by 6 rectangle has the smallest perimeter","The 1 by 24 rectangle has the greatest perimeter","The 3 by 8 rectangle has a perimeter of 22 units"]', 'All three rectangles have the same perimeter', NULL, 'Perimeters: 1 by 24 is 50, 3 by 8 is 22, 4 by 6 is 20. They are all different, so the statement that they are the same is the one that is not true.', 'checked', '{"lint":[],"solve":{"answer":"All three rectangles have the same perimeter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 1x24 -> 50; 3x8 -> 22; 4x6 -> 20. True: 3x8 has 22; 1x24 greatest; 4x6 smallest. Not true: all three have the same perimeter.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ba5f52e-cf16-49ef-9668-13dcaef3408c', 'NC26.4.SGMR.4', 2, 'choice', 'Fixed perimeter, changing area', 'Rosa uses exactly 24 feet of border to make a rectangular flower bed. Its sides are whole numbers of feet. What is the greatest area the bed could have, in square feet?', '["35","27","36","20"]', '36', '6*6', 'Half the border is 12 feet, so length plus width is 12. The areas are 11, 20, 27, 32, 35 and 36. The greatest, 36 square feet, comes from the 6 by 6 square.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 12. Areas: 1x11=11, 2x10=20, 3x9=27, 4x8=32, 5x7=35, 6x6=36. Greatest = 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e2a55a9-fb71-45da-b83b-cf982a783a20', 'NC26.4.SGMR.4', 2, 'choice', 'Fixed perimeter, changing area', 'A rectangle has a perimeter of 30 cm. Which pair of side lengths is NOT possible for this rectangle?', '["8 cm long and 8 cm wide","10 cm long and 5 cm wide","12 cm long and 3 cm wide","9 cm long and 6 cm wide"]', '8 cm long and 8 cm wide', NULL, 'Length plus width must be $30 \div 2 = 15$. $10 + 5$, $12 + 3$ and $9 + 6$ all make 15, but $8 + 8 = 16$, which would give a perimeter of 32 cm.', 'checked', '{"lint":[],"solve":{"answer":"8 cm long and 8 cm wide","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width must be 15. 9+6=15, 12+3=15, 10+5=15, but 8+8=16 (perimeter 32). Not possible: 8 by 8.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e643d224-8dc1-461c-a1df-a368e0ae1dc4', 'NC26.4.SGMR.4', 2, 'choice', 'Choose area or perimeter for the situation', 'A rectangular field is 50 yards long and 30 yards wide. Which question can be answered by finding $2 \times (50 + 30)$?', '["How many square yards of grass cover the field?","How many yards longer is the field than it is wide?","How many yards of fence go around the field?","How many yards must you walk to go along one length and one width?"]', 'How many yards of fence go around the field?', NULL, '$2 \times (50 + 30)$ is the perimeter, the distance around the field, which is the length of fence needed.', 'checked', '{"lint":[],"solve":{"answer":"How many yards of fence go around the field?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x (50 + 30) = 160 is the perimeter: the fence around the field. One length and one width is 80; area is 1500; difference is 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
