INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('065f9633-b463-4482-bae1-6ce3bc003d80', 'NC26.4.SGMR.4', 3, 'choice', 'Smallest perimeter for a given area', 'Which rectangle has an area of 64 square centimeters and the smallest perimeter?', '["8 cm by 8 cm","4 cm by 16 cm","2 cm by 32 cm","1 cm by 64 cm"]', '8 cm by 8 cm', NULL, 'All four have area 64 square centimeters. Perimeters: 8 by 8 is 2 x 16 = 32 cm, 4 by 16 is 2 x 20 = 40 cm, 2 by 32 is 2 x 34 = 68 cm and 1 by 64 is 2 x 65 = 130 cm. The smallest is 8 cm by 8 cm.', 'checked', '{"lint":[],"solve":{"answer":"8 cm by 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeters: 1x64 -> 130, 2x32 -> 68, 4x16 -> 40, 8x8 -> 32. Smallest: 8 cm by 8 cm.","run_id":"claude-code","at":"2026-10-17T18:37:02.149Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82a327d0-a905-4f71-901a-71a8276c0ff8', 'NC26.4.SGMR.4', 3, 'choice', 'Area of a rectangle in context', 'A rectangular parking lot is 67 meters long and 48 meters wide. What is its area in square meters?', '["230","115","3216","2680"]', '3216', '67*48', '$67 \times 48 = 67 \times 40 + 67 \times 8 = 2680 + 536 = 3216$ square meters. 2680 stops after the tens, 115 is the sum of the sides, and 230 is the perimeter.', 'checked', '{"lint":[],"solve":{"answer":"3216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"67 x 48 = 67 x 50 - 67 x 2 = 3350 - 134 = 3216 square meters. 2680 = 67 x 40 (partial product), 230 perimeter, 115 sum.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('288671a0-cefc-471d-9d39-cd8a96695900', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectangle in context', 'The floor of a rectangular room is 18 feet long and 12 feet wide. Each square tile covers 1 square foot, and each box holds 8 tiles. How many boxes of tiles will cover the floor with no gaps and none left over?', '[]', '27', '18*12/8', 'The floor needs $18 \times 12 = 216$ tiles. Each box holds 8, so $216 \div 8 = 27$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 18 x 12 = 216 square feet = 216 tiles. Boxes = 216 / 8 = 27 exactly.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f012de5-5c10-442d-b513-9ad762b7c836', 'NC26.4.SGMR.4', 3, 'numeric', 'Perimeter of a rectangle in context', 'A rectangular field is 150 yards long and 75 yards wide. A fence post is placed every 5 yards all the way around the edge of the field, including one at each corner. How many posts are needed?', '[]', '90', '2*(150+75)/5', 'The distance around is $2 \times (150 + 75) = 450$ yards. A post every 5 yards gives $450 \div 5 = 90$ posts.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 2 x (150 + 75) = 450 yards. Around a closed loop, posts every 5 yards: 450 / 5 = 90 posts. 150 and 75 are multiples of 5, so a post lands on each corner (consistent with the stem).","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69fc06d2-1ff6-4d53-9ada-d16ce78b175c', 'NC26.4.SGMR.4', 3, 'numeric', 'Perimeter of a rectangle in context', 'A rectangular yard is 48 feet long and 35 feet wide. Fencing costs 3 dollars for each foot. How many dollars does it cost to fence all four sides?', '[]', '498', '2*(48+35)*3', 'The fence is the perimeter: $2 \times (48 + 35) = 166$ feet. At 3 dollars a foot it costs $166 \times 3 = 498$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"498","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 2 x (48 + 35) = 2 x 83 = 166 feet. Cost = 166 x 3 = 498 dollars.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
