INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d49575ec-e27a-4ba9-bf93-a60a7cdba0a8', 'NC26.4.SGMR.4', 3, 'numeric', 'Perimeter of a rectangle in context', 'A running track is a rectangle 120 meters long and 80 meters wide. Jo wants to run exactly 2000 meters by going around the track. How many times must she go around?', '[]', '5', '2000/(2*(120+80))', 'One time around is $2 \times (120 + 80) = 400$ meters. $2000 \div 400 = 5$ times around.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One lap = 2 x (120 + 80) = 400 meters. 2000 / 400 = 5 laps.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
