VALUES ('b02cf27c-f2ed-434f-993a-a3c976be94f4', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the area', 'A rectangular field has an area of $1{,}456$ square meters. It is 8 meters wide. How many meters long is it?', '[]', '182', '1456/8', '$1456 \div 8 = 182$ meters. Check: $182 \times 8 = 1456$.', 'checked', '{"lint":[],"solve":{"answer":"182","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length = 1456 / 8 = 182 meters (8 x 182 = 1456).","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
