VALUES ('ccb2bb18-5b22-4a2b-b83f-19a52a2e4fda', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the area', 'A rectangle has an area of 84 square meters and a width of 7 meters. What is its perimeter in meters?', '[]', '38', '2*(84/7+7)', 'Length = $84 \div 7 = 12$ meters. Perimeter = $2 \times (12 + 7) = 38$ meters.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length = 84 / 7 = 12 m. Perimeter = 2 x (12 + 7) = 38 meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
