INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb77096c-7d73-490c-9718-f1a2b3b8d464', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the perimeter', 'A rectangle has a perimeter of 36 cm. Its length is twice its width. What is its width in centimeters?', '[]', '6', '36/6', 'Length plus width is $36 \div 2 = 18$ cm. The length is 2 widths, so 18 cm is 3 widths. One width is $18 \div 3 = 6$ cm.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 18. Length = 2 x width, so 3 x width = 18, width = 6 cm (length 12; 2 x 18 = 36).","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
