INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('610c42d8-17f0-4e41-9ed0-f9c31110542b', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the perimeter', 'Fencing costs 4 dollars per foot. Leo spent 288 dollars to fence all the way around a rectangular pen that is 25 feet long. How many feet wide is the pen?', '[]', '11', '(288/4-2*25)/2', 'The fence is $288 \div 4 = 72$ feet long. The two lengths use 50 feet, leaving 22 feet for the two widths. One width is 11 feet.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter = 288 / 4 = 72 feet. Length + width = 36. Width = 36 - 25 = 11 feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
