INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7d83b17-5f79-40be-96cd-1aa57219195d', 'NC26.4.SGMR.4', 3, 'numeric', 'Find a missing side from the perimeter', 'A rectangle has a perimeter of 90 meters and a width of 18 meters. What is its area in square meters?', '[]', '486', '(90-2*18)/2*18', 'The two widths use 36 meters, leaving 54 meters for the two lengths, so the length is 27 meters. Area = $27 \times 18 = 486$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"486","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 45, so length = 45 - 18 = 27 m. Area = 27 x 18 = 270 + 216 = 486 square meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
