INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7809296-7cf0-4669-aba9-10117bc24ed9', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: add rectangles', 'A playground is made from three rectangles that do not overlap. They measure 20 m by 10 m, 15 m by 8 m, and 6 m by 5 m. What is the total area of the playground in square meters?', '[]', '350', '20*10+15*8+6*5', '$20 \times 10 = 200$, $15 \times 8 = 120$ and $6 \times 5 = 30$. Total: $200 + 120 + 30 = 350$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 x 10 + 15 x 8 + 6 x 5 = 200 + 120 + 30 = 350 square meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
