INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed74678a-294f-4484-ba5a-d1d8054ccaed', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: add rectangles', 'A floor plan has four rectangular rooms that do not overlap. They measure 8 ft by 6 ft, 7 ft by 5 ft, 9 ft by 4 ft, and 3 ft by 3 ft. What is the total area of the four rooms in square feet?', '[]', '128', '8*6+7*5+9*4+3*3', '$48 + 35 + 36 + 9 = 128$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"128","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 6 + 7 x 5 + 9 x 4 + 3 x 3 = 48 + 35 + 36 + 9 = 128 square feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
