INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fb58724-f161-444d-8c20-98cfe51c3744', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: add rectangles', 'An L-shaped garden is made of two rectangles that do not overlap. One is 9 meters by 6 meters. The whole garden has an area of 84 square meters. The other rectangle is 5 meters wide. How many meters long is it?', '[]', '6', '(84-9*6)/5', 'The first part has area $9 \times 6 = 54$. The other part has area $84 - 54 = 30$. Its length is $30 \div 5 = 6$ meters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First rectangle 9 x 6 = 54. Other rectangle area = 84 - 54 = 30. Length = 30 / 5 = 6 meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
