INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6b29ee6-9bcd-423d-b959-7c8fa1f99b88', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: subtract a cut-out', 'A rectangular pool is 20 meters long and 8 meters wide. A walkway 2 meters wide goes all the way around the pool. What is the area of the walkway alone, in square meters?', '[]', '128', '(20+4)*(8+4)-20*8', 'The pool and walkway together are $20 + 2 + 2 = 24$ m by $8 + 2 + 2 = 12$ m, an area of $24 \times 12 = 288$. The pool is $20 \times 8 = 160$. Walkway: $288 - 160 = 128$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"128","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer rectangle (pool + walkway) = (20 + 4) x (8 + 4) = 24 x 12 = 288. Pool = 20 x 8 = 160. Walkway = 288 - 160 = 128 square meters.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95867471-5852-4881-a21a-cef248ab71e2', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: subtract a cut-out', 'A wall is 14 feet long and 9 feet high. It has two windows, each 3 feet wide and 6 feet high, and the windows are not painted. One can of paint covers 15 square feet. How many cans will cover the rest of the wall with none left over?', '[]', '6', '(14*9-2*3*6)/15', 'Wall: $14 \times 9 = 126$. Two windows: $2 \times (3 \times 6) = 36$. Painted: $126 - 36 = 90$ square feet. Cans: $90 \div 15 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wall 14 x 9 = 126. Windows 2 x (3 x 6) = 36. To paint = 126 - 36 = 90. Cans = 90 / 15 = 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
