INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9772f7f-f2f0-4e13-acfb-fb93cee18056', 'NC26.4.SGMR.4', 3, 'numeric', 'Area of a rectilinear figure: subtract a cut-out', 'A rectangular field is 36 yards long and 25 yards wide. It has two ponds. One pond is 8 yards by 5 yards and the other is 6 yards by 6 yards. How many square yards of the field are not pond?', '[]', '824', '36*25-8*5-6*6', 'Field: $36 \times 25 = 900$. Ponds: $8 \times 5 = 40$ and $6 \times 6 = 36$. Not pond: $900 - 40 - 36 = 824$ square yards.', 'checked', '{"lint":[],"solve":{"answer":"824","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Field 36 x 25 = 900. Ponds 8 x 5 = 40 and 6 x 6 = 36, total 76. Not pond = 900 - 76 = 824 square yards.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
