INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c9996c1-09aa-4ed3-8c4c-4da6ab5ccecb', 'NC26.4.SGMR.4', 3, 'numeric', 'Fixed area, changing perimeter', 'The area of a rectangle is 28 square centimeters, and its sides are whole numbers of centimeters. What is the greatest perimeter it could have, in centimeters?', '[]', '58', '2*(1+28)', 'The whole-number pairs are 1 by 28, 2 by 14 and 4 by 7. Perimeters: 58, 32 and 22. The greatest is 58 cm.', 'checked', '{"lint":[],"solve":{"answer":"58","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole-number pairs: 1x28 (P 58), 2x14 (P 32), 4x7 (P 22). Greatest = 58 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
