INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbbde519-b17f-454e-922f-a73fa8a52b38', 'NC26.4.SGMR.4', 3, 'numeric', 'Fixed perimeter, changing area', 'Two rectangles each have a perimeter of 46 units. Rectangle R is 17 units long and rectangle S is 12 units long. How many square units greater is the area of S than the area of R?', '[]', '30', '12*(23-12)-17*(23-17)', 'Length plus width is $46 \div 2 = 23$. R is 6 wide: $17 \times 6 = 102$. S is 11 wide: $12 \times 11 = 132$. The difference is $132 - 102 = 30$ square units.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length + width = 23. R: 17 x 6 = 102. S: 12 x 11 = 132. Difference = 132 - 102 = 30 square units.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
