INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e526daf-c883-4f77-863e-3199ad844d53', 'NC26.4.SGMR.4', 3, 'numeric', 'Square area and perimeter', 'A square garden has an area of 144 square feet. What is the perimeter of the garden in feet?', '[]', '48', '4*12', 'Since $12 \times 12 = 144$, each side is 12 feet. Perimeter = $4 \times 12 = 48$ feet.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side x side = 144, side = 12 ft. Perimeter = 4 x 12 = 48 feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.631Z"}}', 'ai', NULL, NULL)
