INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac67fa65-b8ea-441e-b64b-af028c53e8f9', 'NC26.4.RD.1', 1, 'choice', 'Read a bar graph', 'A bar graph shows how many students chose each snack. The bar for apples reaches 12, the bar for crackers reaches 9 and the bar for popcorn reaches 15. How many more students chose popcorn than crackers?', '["3","24","6","21"]', '6', '15-9', '$15 - 9 = 6$ more students. (3 is popcorn minus apples, 24 is popcorn plus crackers, and 21 is apples plus crackers.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Popcorn 15 - crackers 9 = 6.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
