VALUES ('d117aed8-ae03-4151-8ea2-3525053ae1f2', 'NC26.4.RD.1', 1, 'choice', 'Median', 'Which description matches the median of a data set?', '["The value that occurs most often","The greatest value minus the least value","The total of the values","The middle value when the data are listed in order"]', 'The middle value when the data are listed in order', NULL, 'The median is the middle value after the data are put in order from least to greatest.', 'checked', '{"lint":[],"solve":{"answer":"The middle value when the data are listed in order","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median is the middle value of ordered data.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
