INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d657ef71-4b47-4b2c-9398-4ed9e138bcbd', 'NC26.4.RD.1', 1, 'choice', 'Draw a conclusion from data', 'A bar graph shows the favorite pets of 28 students: dogs 14, cats 9, fish 5. Which conclusion is supported by the data?', '["Every student in the school likes dogs best","Fish are the most popular pet","Cats are the least popular pet","More of these students chose dogs than any other pet"]', 'More of these students chose dogs than any other pet', NULL, 'Dogs have the tallest bar (14). Fish (5) are the least popular, and the data cannot speak for the whole school.', 'checked', '{"lint":[],"solve":{"answer":"More of these students chose dogs than any other pet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs 14 is the most of these 28 students. Fish (5) is least, not cats; the data say nothing about every student in the school.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
