INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d0cd2e7-b893-4202-a8bc-9b0fc235cce4', 'NC26.4.RD.1', 2, 'choice', 'Numerical or categorical question', 'Which pair shows a numerical question first and a categorical question second?', '["What kind of book do you like? / How many pages are in your book?","How many pages are in your book? / How many books did you read?","What kind of book do you like? / Who is your favorite writer?","How many pages are in your book? / What kind of book do you like?"]', 'How many pages are in your book? / What kind of book do you like?', NULL, '"How many pages" is answered with a number (numerical). "What kind of book" is answered with words (categorical). The pair must be in that order.', 'checked', '{"lint":[],"solve":{"answer":"How many pages are in your book? / What kind of book do you like?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need numerical then categorical. ''How many pages...'' is numerical; ''What kind of book...'' is categorical. Option 2 matches. Option 1 is numerical/numerical, option 3 reversed, option 4 categorical/categorical.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c91d70-01bf-4f99-aee7-05783c429fb8', 'NC26.4.RD.1', 2, 'numeric', 'Numerical or categorical question', 'Six survey questions are listed. 1. How many minutes do you practice piano? 2. What instrument do you play? 3. How many students are in your music class? 4. Which song is your favorite? 5. How old were you when you began lessons? 6. Do you like to sing? How many of the six questions are numerical questions?', '[]', '3', '3', 'Questions 1, 3 and 5 are answered with numbers. Questions 2, 4 and 6 are answered with names or yes and no, so they are categorical. That makes 3 numerical questions.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 minutes: numerical. 2 instrument: categorical. 3 how many students: numerical. 4 song: categorical. 5 age began: numerical. 6 yes/no: categorical. Numerical: 1, 3, 5 = 3.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d36c2e4-6149-4af1-a151-02ce935a3c5d', 'NC26.4.RD.1', 2, 'choice', 'Numerical or categorical question', 'Maya wants to show her classmates'' answers on a line plot, which needs numbers on a number line. Which question should she ask?', '["What is your favorite bedtime story?","How many hours did you sleep last night?","What color are your pajamas?","Which room do you sleep in?"]', 'How many hours did you sleep last night?', NULL, 'A line plot shows numerical data. Only the question about hours has numbers as answers.', 'checked', '{"lint":[],"solve":{"answer":"How many hours did you sleep last night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A line plot needs numerical answers. Only ''How many hours did you sleep last night?'' gives numbers.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
