INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcfb8c85-9074-4728-a091-5f59adcf6e05', 'NC26.4.RD.1', 2, 'choice', 'Plan how to collect data', 'A teacher wants to know how many minutes students at the school spend getting to school each day. Which plan will give the best data?', '["Ask students from every grade how many minutes it takes them to get to school","Ask only the students who ride the bus","Ask students whether they like their trip to school","Ask only the students who arrive first in the morning"]', 'Ask students from every grade how many minutes it takes them to get to school', NULL, 'The plan must ask for a number of minutes and must include students from the whole school, not just one group.', 'checked', '{"lint":[],"solve":{"answer":"Ask students from every grade how many minutes it takes them to get to school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The question is about minutes for all students; asking students from every grade how many minutes gives numerical data from the whole school. Others are biased samples or ask the wrong question.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
