INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5c2226d-21d3-4be6-9122-5799757f4a00', 'NC26.4.RD.1', 3, 'choice', 'Numerical or categorical question', 'Leo asked, "How do you get to school?" The answers were walk, bus, car, bus, bike, walk, car, bus. Which statement is true?', '["It is a numerical question, and the mode is bus","It is a categorical question, and the mode is walk","It is a categorical question, and the mode is bus","It is a numerical question, and the mode is car"]', 'It is a categorical question, and the mode is bus', NULL, 'The answers are words, so the question is categorical. Bus appears 3 times, walk 2, car 2 and bike 1, so the mode is bus.', 'checked', '{"lint":[],"solve":{"answer":"It is a categorical question, and the mode is bus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Answers are words, so categorical. Counts: walk 2, bus 3, car 2, bike 1. Mode is bus.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
