INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f02a10a0-e0a0-47f9-af33-cfad0d6e5ff0', 'NC26.4.RD.1', 3, 'numeric', 'Frequency tables and tally marks', 'A class of 30 students was asked how many pets each has. 0 pets: 6 students. 1 pet: 11 students. 2 pets: 7 students. 4 pets: 2 students. The rest of the students have 3 pets. How many students have 3 pets?', '[]', '4', '30-(6+11+7+2)', 'The rows given total $6 + 11 + 7 + 2 = 26$ students. The rest are $30 - 26 = 4$ students.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 11 + 7 + 2 = 26; 30 - 26 = 4 students have 3 pets.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
