INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cc6418b-a8ff-447b-80cb-720562efc23c', 'NC26.4.RD.1', 3, 'choice', 'Frequency tables and tally marks', 'A frequency table shows how many siblings students have. 0 siblings: 6 students. 1 sibling: 10 students. 2 siblings: 9 students. 3 siblings: 5 students. Which statement is true?', '["The most common number of siblings is 3","More students have 1 sibling than any other number of siblings","Exactly 15 students have 2 or more siblings","24 students were asked"]', 'More students have 1 sibling than any other number of siblings', NULL, '10 students have 1 sibling, which is the greatest count. 2 or more siblings is $9 + 5 = 14$ students, and the total asked is $6 + 10 + 9 + 5 = 30$ students.', 'checked', '{"lint":[],"solve":{"answer":"More students have 1 sibling than any other number of siblings","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6+10+9+5 = 30. Most common is 1 (10), not 3. Not 24 asked. 2 or more: 9+5 = 14, not 15. 1 sibling (10) is more than any other: true.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
