INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dabd86c-2b16-474f-956d-9781076a6fbe', 'NC26.4.RD.1', 3, 'numeric', 'Frequency tables and tally marks', 'A team''s goals per game are in a frequency table. 0 goals: 2 games. 1 goal: 4 games. 2 goals: 3 games. 3 goals: 1 game. How many goals did the team score in all?', '[]', '13', '0*2+1*4+2*3+3*1', 'Multiply each number of goals by its number of games and add: $0 \times 2 + 1 \times 4 + 2 \times 3 + 3 \times 1 = 0 + 4 + 6 + 3 = 13$ goals.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0x2 + 1x4 + 2x3 + 3x1 = 0 + 4 + 6 + 3 = 13 goals.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
