INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59baf9e6-c2b7-4d40-b9b4-9e9c5d7b1e77', 'NC26.4.RD.1', 3, 'numeric', 'Frequency tables and tally marks', 'The numbers of cavities found in 15 children are 0, 2, 1, 0, 3, 1, 0, 2, 1, 1, 0, 4, 1, 2 and 0. How many of the children had at least 2 cavities?', '[]', '5', '5', 'The values that are 2 or more are 2, 3, 2, 4 and 2. That is 5 children.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tally: 0 five times, 1 five times, 2 three times, 3 once, 4 once (total 15). At least 2: 3 + 1 + 1 = 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
