INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23276d10-e6a9-4b9b-9c19-3fc5db36ee49', 'NC26.4.RD.1', 3, 'numeric', 'Compare categories in a table', 'Students voted for a class pet. The turtle got 6 votes. The hamster got 3 more votes than the turtle. The fish got twice as many votes as the turtle. How many votes did the hamster and the fish get altogether?', '[]', '21', '(6+3)+2*6', 'Hamster: $6 + 3 = 9$ votes. Fish: $2 \times 6 = 12$ votes. Together: $9 + 12 = 21$ votes.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hamster 6 + 3 = 9; fish 2 x 6 = 12; 9 + 12 = 21.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
