INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f514d8b3-fd07-4cf2-9854-4442835dd73b', 'NC26.4.RD.1', 3, 'numeric', 'Read a bar graph', 'The bars of a bar graph show 36, 28, 44 and 32 pages read by four students. The scale counts by 4s. How many lines taller is the tallest bar than the shortest bar?', '[]', '4', '(44-28)/4', 'The tallest bar is 44 and the shortest is 28, a difference of 16. Each line is 4, so that is $16 \div 4 = 4$ lines.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tallest 44, shortest 28; difference 16; 16 / 4 = 4 lines.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
