INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd1eda7c-2d2a-418c-9d4b-b9f76728eb95', 'NC26.4.RD.1', 3, 'numeric', 'Double bar graph: compare two data sets', 'A double bar graph compares the books three students read in May and in June. Ali: May 8, June 12. Bea: May 10, June 7. Cam: May 6, June 9. How many more books did the three students read in June than in May?', '[]', '4', '(12+7+9)-(8+10+6)', 'June: $12 + 7 + 9 = 28$. May: $8 + 10 + 6 = 24$. The difference is $28 - 24 = 4$ books.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"May 8 + 10 + 6 = 24; June 12 + 7 + 9 = 28; 28 - 24 = 4.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
