INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26e7370b-61cc-448b-a771-5529f5916f3b', 'NC26.4.RD.1', 3, 'choice', 'Double bar graph: compare two data sets', 'A double bar graph shows the books read by two grades. Fall: Grade 3 read 12 and Grade 4 read 15. Spring: Grade 3 read 18 and Grade 4 read 15. Which statement is true?', '["Grade 3 read fewer books in the spring than in the fall","Grade 4 read the same number of books in the fall and in the spring","Grade 4 read more books than Grade 3 in the spring","Grade 3 and Grade 4 read the same number of books in the fall"]', 'Grade 4 read the same number of books in the fall and in the spring', NULL, 'Grade 4 read 15 in both seasons. Grade 3 went up from 12 to 18, in the spring Grade 3 (18) beat Grade 4 (15), and in the fall they read 12 and 15.', 'checked', '{"lint":[],"solve":{"answer":"Grade 4 read the same number of books in the fall and in the spring","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spring: G4 15 < G3 18, so A false. G3 spring 18 > fall 12, B false. Fall 12 vs 15, C false. G4 15 fall and 15 spring: D true.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('267af21e-80b5-4db9-bd72-a8cd592922c7', 'NC26.4.RD.1', 3, 'numeric', 'Double bar graph: compare two data sets', 'A double bar graph compares sales of lemonade and cookies on three days. Lemonade: Friday 14, Saturday 22, Sunday 18. Cookies: Friday 9, Saturday 26, Sunday 15. What is the greatest difference between the two bars on any one day?', '[]', '5', '14-9', 'Differences: Friday $14 - 9 = 5$, Saturday $26 - 22 = 4$, Sunday $18 - 15 = 3$. The greatest is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Friday 14 - 9 = 5; Saturday 26 - 22 = 4; Sunday 18 - 15 = 3. Greatest 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
