INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73dac26c-b751-44eb-9d17-cd671c3e3092', 'NC26.4.RD.1', 3, 'choice', 'Range', 'The scores on a quiz have a range of 15. The lowest score is 78. What is the highest score?', '["63","15","93","78"]', '93', '78+15', 'Range = highest - lowest, so highest = lowest + range = $78 + 15 = 93$.', 'checked', '{"lint":[],"solve":{"answer":"93","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Highest = 78 + 15 = 93.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
