INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d6a2cf5-04ac-4520-824f-560911c7ab08', 'NC26.4.RD.1', 3, 'numeric', 'Range', 'Set A is 12, 18, 25 and 30. Set B is 5, 20, 22 and 40. How much greater is the range of Set B than the range of Set A?', '[]', '17', '(40-5)-(30-12)', 'Range of A: $30 - 12 = 18$. Range of B: $40 - 5 = 35$. The difference is $35 - 18 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 30 - 12 = 18. B: 40 - 5 = 35. 35 - 18 = 17.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
