INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c04c60fa-6c1c-4fd5-ad5e-860a77850ec0', 'NC26.4.RD.1', 3, 'numeric', 'Range', 'The numbers 8, 12, 15 and 11 have a range of 7. Jada adds one more number that is greater than all four, and the range becomes 12. What number did she add?', '[]', '20', '8+12', 'The least number is still 8, so the new greatest number is $8 + 12 = 20$. It is greater than 15, as the question says.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Least stays 8; new greatest x with x - 8 = 12, so x = 20 (greater than 15, consistent).","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
