INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3b4cfca-12f4-459d-976b-2be9cdff6865', 'NC26.4.RD.1', 3, 'numeric', 'Mode', 'The list 4, 7, 4, 9, 7, 4, 7 has two modes. What number could be added to the list so that the new list has just one mode, and that mode is 7?', '[]', '7', '7', 'Right now 4 and 7 each appear three times. Adding another 7 makes four 7s, so 7 is the only mode. Adding any other number would leave a tie or make a different number the mode.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 appears 3 times, 7 appears 3 times, 9 once. Adding 7 makes 7 appear 4 times, the only mode. Adding 4 gives mode 4; adding anything else leaves two modes. So 7 is the only answer.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d4c532a-092c-430e-b0b3-b8ca07de4626', 'NC26.4.RD.1', 3, 'numeric', 'Median', 'A line plot shows the number of pets owned by 11 students. There are 3 Xs above 0, 4 Xs above 1, 2 Xs above 2 and 2 Xs above 3. What is the median number of pets?', '[]', '1', '1', 'With 11 values, the median is the 6th value in order. The first 3 values are 0, the next 4 are 1 (values 4 to 7), so the 6th value is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered: 0,0,0,1,1,1,1,2,2,3,3. 11 values; the 6th is 1.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9553f43-b3af-4b0b-89e3-b61243c0be4c', 'NC26.4.RD.1', 3, 'numeric', 'Median', 'Eight children have shoe sizes 6, 4, 5, 3, 5, 7, 4 and 5. What is the median shoe size?', '[]', '5', '5', 'In order: 3, 4, 4, 5, 5, 5, 6, 7. The two middle values (fourth and fifth) are both 5, so the median is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order: 3, 4, 4, 5, 5, 5, 6, 7. Eight values; 4th and 5th are both 5, so the median is 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b89d5568-f3b5-47e0-bebe-e8ad3df4bcb2', 'NC26.4.RD.1', 3, 'numeric', 'Median', 'The median of five numbers is 12. Four of the numbers are 5, 9, 15 and 20. What is the fifth number?', '[]', '12', '12', 'The median is the middle number when the five are in order. With 5, 9, 15 and 20, the fifth number must sit between 9 and 15 to be the middle, so it is the median itself: 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 5, 9, 15, 20 and x: if x <= 9 the median is 9; if x >= 15 it is 15; if 9 < x < 15 the median is x. Median 12 forces x = 12.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a93c57a-fa45-4655-9d76-3e26b553145f', 'NC26.4.RD.1', 3, 'choice', 'Range, mode and median together', 'For the data 4, 6, 6, 7, 9, 12 and 6, which statement is true?', '["The mode is 6 and the median is 7","The range is 6","The mode and the median are both 6","The median is 9"]', 'The mode and the median are both 6', NULL, 'In order: 4, 6, 6, 6, 7, 9, 12. The mode is 6 (three times) and the middle value is 6. The range is $12 - 4 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"The mode and the median are both 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order: 4, 6, 6, 6, 7, 9, 12. Mode 6, median (4th) 6, range 8. Only ''both 6'' is true.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3a82b8e-8b54-4387-869b-59aba9880f11', 'NC26.4.RD.1', 3, 'numeric', 'Draw a conclusion from data', 'A line plot shows the hours students read last night. 0 hours: 2 Xs. 1 hour: 6 Xs. 2 hours: 9 Xs. 3 hours: 5 Xs. 4 hours: 2 Xs. How many more students read 2 hours or more than read fewer than 2 hours?', '[]', '8', '(9+5+2)-(2+6)', '2 hours or more: $9 + 5 + 2 = 16$ students. Fewer than 2 hours: $2 + 6 = 8$ students. The difference is $16 - 8 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 hours or more: 9 + 5 + 2 = 16. Fewer than 2: 2 + 6 = 8. 16 - 8 = 8.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea4babf3-0ba4-47a1-a4be-eea40e81eb02', 'NC26.4.RD.1', 3, 'choice', 'Draw a conclusion from data', 'Mia asked 10 students in the lunch line which subject they like best. Seven said math, so she says, "Most students in my school like math best." Why might her conclusion be wrong?', '["Seven is not more than half of ten","Math cannot be a favorite subject","A conclusion can only be drawn from a line plot","She asked only a few students in one place, so they may not stand for the whole school"]', 'She asked only a few students in one place, so they may not stand for the whole school', NULL, 'Seven out of ten is more than half, but only 10 students in one spot were asked. They may not match the whole school, so the conclusion is not well supported.', 'checked', '{"lint":[],"solve":{"answer":"She asked only a few students in one place, so they may not stand for the whole school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 students in one lunch line may not represent the whole school. Seven is more than half of ten, so option 3 is false.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f98959a0-e03f-4969-8a80-45d82e4ba3c7', 'NC26.4.RD.1', 3, 'choice', 'Draw a conclusion from data', 'Two classes made line plots of the books each student read. Class 1 read 3, 4, 4, 5, 5, 5 and 6 books. Class 2 read 1, 3, 5, 5, 5, 7 and 9 books. Which statement is true?', '["Both classes have the same mode and median, but Class 2 has the greater range","Class 1 has the greater range","Class 2 has the greater median","Class 1 has a mode of 4"]', 'Both classes have the same mode and median, but Class 2 has the greater range', NULL, 'Both lists have mode 5 and median 5. The range of Class 1 is $6 - 3 = 3$ and of Class 2 is $9 - 1 = 8$, so Class 2 has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Both classes have the same mode and median, but Class 2 has the greater range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 1: mode 5, median 5, range 3. Class 2: mode 5, median 5, range 8. So same mode and median, Class 2 greater range.","run_id":"claude-code","at":"2026-10-17T20:08:07.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e307d596-3d51-4b29-8380-7909233c78f5', 'NC26.5.ANR.1', 1, 'numeric', 'Order of operations: multiplication before addition', 'Find the value of $6 + 4 \times 3$.', '[]', '18', '6+4*3', 'Multiply first: $4 \times 3 = 12$. Then add: $6 + 12 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply first: 4 x 3 = 12. Then 6 + 12 = 18.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4e69b83-29bd-4342-b549-2381c3f3b24f', 'NC26.5.ANR.1', 1, 'choice', 'Order of operations: division before subtraction', 'What is the value of $30 - 12 \div 3$?', '["6","18","26","34"]', '26', '30-12/3', 'Divide first: $12 \div 3 = 4$. Then subtract: $30 - 4 = 26$. (Subtracting first would give 6, which is a common mistake.)', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide first: 12 / 3 = 4. Then 30 - 4 = 26.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
