INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3b129a-738e-4f32-bc8b-3a98de93adb3', 'NC26.5.ANR.1', 1, 'numeric', 'Associative property', 'What number goes in the box to make the equation true? $(4 + 7) + 3 = 4 + (\square + 3)$', '[]', '7', '(4+7)+3-4-3', 'Numbers can be grouped in different ways without changing the sum. On the left the numbers are 4, 7 and 3 in that order, so the box is 7. Both sides equal 14.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative property: (4 + 7) + 3 = 4 + (7 + 3); box = 7. Check 14 = 14.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
