VALUES ('56aa6bee-56c1-45e4-a1a8-bb53efa56d44', 'NC26.5.ANR.1', 1, 'choice', 'Connect an expression to a representation', 'An array has 4 rows with 6 dots in each row. Which expression gives the number of dots?', '["$4 + 6$","$6 \\div 4$","$4 \\times 6$","$6 - 4$"]', '$4 \times 6$', NULL, 'Equal rows of dots are multiplied: $4 \times 6 = 24$ dots.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy for Grade 5 (a Grade 3 array item); acceptable only as a warm-up.","work":"4 rows of 6 dots: 4 x 6 = 24.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
