INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a13c387-3715-416e-8b15-5910bff1116f', 'NC26.5.ANR.1', 1, 'choice', 'Connect an expression to a representation', 'A tape diagram has 3 equal parts of size 8 and one more part of size 5. Which expression gives the total length?', '["$3 + 8 + 5$","$3 \\times (8 + 5)$","$8 \\times 5 + 3$","$3 \\times 8 + 5$"]', '$3 \times 8 + 5$', NULL, 'The three equal parts give $3 \times 8 = 24$, and the extra part adds 5: $3 \times 8 + 5 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 8 + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 equal parts of 8 = 3 x 8, plus one part of 5: 3 x 8 + 5 = 29.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
