INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b59b8b9-2861-4570-85f3-78415056ccea', 'NC26.5.ANR.1', 2, 'numeric', 'Order of operations with parentheses', 'Tomas wrote $90 - (24 + 36)$ on the board. What is its value?', '[]', '30', '90-(24+36)', 'Do the parentheses first: $24 + 36 = 60$. Then subtract: $90 - 60 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 + 36 = 60; 90 - 60 = 30.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
