INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99cbc787-d1aa-42ce-a215-d13a6db99869', 'NC26.5.ANR.1', 2, 'choice', 'Order of operations with parentheses', 'What is the value of $96 \div (4 + 4)$?', '["28","24","104","12"]', '12', '96/(4+4)', 'Do the parentheses first: $4 + 4 = 8$. Then divide: $96 \div 8 = 12$. The choice 28 comes from dividing by 4 first and then adding 4, and 24 from dividing by only one 4.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 4 = 8; 96 / 8 = 12. (28 = 96/4 + 4.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
