INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50e717f6-5ce9-4c9e-a339-ed5a54a31ea4', 'NC26.5.ANR.1', 2, 'choice', 'Compare the values of expressions', 'Four expressions use the numbers 6, 2 and 3. Which one has the least value?', '["$6 + 2 \\times 3$","$(6 + 2) \\times 3$","$6 \\times 2 + 3$","$6 \\times (2 + 3)$"]', '$6 + 2 \times 3$', NULL, 'Find each value: $6 + 2 \times 3 = 12$; $(6 + 2) \times 3 = 24$; $6 \times 2 + 3 = 15$; $6 \times (2 + 3) = 30$. The least value is 12.', 'checked', '{"lint":[],"solve":{"answer":"$6 + 2 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2 + 3 = 15; 6 + 2 x 3 = 12; (6+2) x 3 = 24; 6 x (2+3) = 30. Least is 12.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77d812d2-b0a5-4979-a447-924a5c09b736', 'NC26.5.ANR.1', 2, 'choice', 'Compare the values of expressions', 'Which pair of expressions has the same value?', '["$2 + 3 \\times 4$ and $(2 + 3) \\times 4$","$2 + 3 \\times 4$ and $4 \\times 3 + 2$","$12 - 4 \\div 2$ and $(12 - 4) \\div 2$","$5 \\times 2 + 1$ and $5 \\times (2 + 1)$"]', '$2 + 3 \times 4$ and $4 \times 3 + 2$', NULL, '$2 + 3 \times 4 = 2 + 12 = 14$ and $4 \times 3 + 2 = 12 + 2 = 14$. In every other pair, the parentheses change the order of the steps and so change the value: 14 and 20, 10 and 4, 11 and 15.', 'checked', '{"lint":[],"solve":{"answer":"$2 + 3 \\times 4$ and $4 \\times 3 + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 vs 20; 12 - 2 = 10 vs 8/2 = 4; 11 vs 15; 2 + 12 = 14 vs 12 + 2 = 14. Only the last pair match.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf4938a5-b835-4a0b-a411-abbda901a2ca', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a described calculation', 'Which expression means "divide 36 by the sum of 5 and 4"?', '["$36 \\div 5 + 4$","$(36 + 5) \\div 4$","$36 \\div (5 + 4)$","$36 \\times (5 + 4)$"]', '$36 \div (5 + 4)$', NULL, '"The sum of 5 and 4" is $5 + 4$, and it must be worked out before the division, so it goes in parentheses: $36 \div (5 + 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$36 \\div (5 + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The sum of 5 and 4 is (5 + 4); 36 divided by it is 36 / (5 + 4).","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb75630d-578f-4230-b73a-eca3a0b7bddc', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a described calculation', 'Which expression means "6 less than the product of 8 and 5"?', '["$8 \\times 5 - 6$","$6 - 8 \\times 5$","$8 \\times (5 + 6)$","$8 \\times 5 + 6$"]', '$8 \times 5 - 6$', NULL, '"The product of 8 and 5" is $8 \times 5$, and "6 less than" that is $8 \times 5 - 6$.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times 5 - 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product of 8 and 5 is 8 x 5; 6 less than that is 8 x 5 - 6.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab43bf40-e205-493e-a7c5-623701208aad', 'NC26.5.ANR.1', 2, 'numeric', 'Write an expression for a described calculation', 'Multiply 7 by the difference between 12 and 5. What is the result?', '[]', '49', '7*(12-5)', 'The difference between 12 and 5 is $12 - 5 = 7$. Then $7 \times 7 = 49$. As an expression this is $7 \times (12 - 5)$.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference 12 - 5 = 7; 7 x 7 = 49.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e75affe-fa81-4dbc-8db0-1012fd8a6879', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a story', 'A shop sells pens in packs of 8. Dev buys 5 packs and then uses 12 pens. Which expression shows how many pens he has left?', '["$5 + 8 - 12$","$5 \\times 8 - 12$","$5 \\times (8 + 12)$","$8 \\times 12 - 5$"]', '$5 \times 8 - 12$', NULL, 'Dev buys $5 \times 8$ pens and uses 12 of them, so he has $5 \times 8 - 12$ pens left. That is $40 - 12 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 8 - 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 packs of 8 = 5 x 8 = 40; uses 12: 5 x 8 - 12 = 28.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a9a1dca-5f3d-4ba2-9da1-184f73c44d41', 'NC26.5.ANR.1', 2, 'numeric', 'Write an expression for a story', 'Nia buys 3 notebooks that cost 4 dollars each and 2 pens that cost 3 dollars each. How many dollars does she spend in all?', '[]', '18', '3*4+2*3', 'The notebooks cost $3 \times 4 = 12$ dollars and the pens cost $2 \times 3 = 6$ dollars. In all she spends $12 + 6 = 18$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Notebooks 3 x 4 = 12, pens 2 x 3 = 6; 12 + 6 = 18.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4a91fae-86fe-493c-abf4-a45920b2bfed', 'NC26.5.ANR.1', 2, 'choice', 'Write an expression for a story', 'Four friends share the cost of a 36 dollar game and a 12 dollar poster equally. Which expression shows how much each friend pays?', '["$36 + 12 \\div 4$","$36 \\div 4 + 12$","$(36 + 12) \\div 4$","$(36 + 12) \\times 4$"]', '$(36 + 12) \div 4$', NULL, 'The total cost is $36 + 12$, and it is shared among 4 friends, so each pays $(36 + 12) \div 4$. That is $48 \div 4 = 12$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"$(36 + 12) \\div 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total cost 36 + 12 = 48, shared by 4: (36 + 12) / 4 = 12.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd467941-0dec-4ba4-9077-b98afa0e3fef', 'NC26.5.ANR.1', 2, 'choice', 'Interpret an expression without calculating', 'Without finding its value, which statement is true about $5 \times (123 + 456)$?', '["It is 5 times as large as $123 + 456$","It is 5 more than $123 + 456$","It is 5 less than $123 + 456$","It is one fifth of $123 + 456$"]', 'It is 5 times as large as $123 + 456$', NULL, 'The sum $123 + 456$ is multiplied by 5, so the expression is 5 times as large as the sum.', 'checked', '{"lint":[],"solve":{"answer":"It is 5 times as large as $123 + 456$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x (123 + 456) is 5 groups of the sum, so 5 times as large as 123 + 456.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2852333b-1361-4684-9de5-766d14ae5b14', 'NC26.5.ANR.1', 2, 'choice', 'Interpret an expression without calculating', 'Maya uses $4 \times 6 + 2 \times 3$ for the cost of 4 notebooks at 6 dollars each and 2 pens at 3 dollars each. What does $2 \times 3$ stand for?', '["The cost of the 4 notebooks","The cost of the 2 pens","The cost of all the items","The number of items bought"]', 'The cost of the 2 pens', NULL, 'The part $2 \times 3$ is 2 pens at 3 dollars each, so it is the cost of the 2 pens.', 'checked', '{"lint":[],"solve":{"answer":"The cost of the 2 pens","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 pens at 3 dollars each: 2 x 3 is the cost of the 2 pens.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('771e2694-04e0-4d58-ae9b-f9eb78fd4330', 'NC26.5.ANR.1', 2, 'choice', 'Commutative property', 'Which pair of expressions are equal because of the commutative property?', '["$25 \\times 4$ and $4 \\times 25$","$25 - 4$ and $25 + 4$","$25 \\div 5$ and $5 \\div 25$","$25 + 4$ and $25 \\times 4$"]', '$25 \times 4$ and $4 \times 25$', NULL, 'Only addition and multiplication can be done in either order. $25 \times 4 = 4 \times 25 = 100$. Subtracting and dividing cannot: $25 - 4 = 21$ is not $25 + 4 = 29$, and $25 \div 5 = 5$ is not $5 \div 25$. Also $25 + 4 = 29$ is not $25 \times 4 = 100$.', 'checked', '{"lint":[],"solve":{"answer":"$25 \\times 4$ and $4 \\times 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 x 4 = 4 x 25 by the commutative property (both 100). The others are not equal.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c56a9155-ebe7-40cd-bfc3-8c101a5b54ad', 'NC26.5.ANR.1', 2, 'choice', 'Commutative property', 'Which equation is NOT true?', '["$12 + 5 = 5 + 12$","$12 \\times 5 = 5 \\times 12$","$12 + 0 = 0 + 12$","$12 \\div 4 = 4 \\div 12$"]', '$12 \div 4 = 4 \div 12$', NULL, 'Addition and multiplication can be done in either order. Division cannot: $12 \div 4 = 3$ but $4 \div 12$ is much less than 1.', 'checked', '{"lint":[],"solve":{"answer":"$12 \\div 4 = 4 \\div 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 0 = 0 + 12 true; 17 = 17 true; 60 = 60 true; 12 / 4 = 3 but 4 / 12 = 1/3, so the division one is not true.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f9d2224-630a-487e-aa84-f482a790d96e', 'NC26.5.ANR.1', 2, 'choice', 'Associative property', 'Which equation shows the associative property of multiplication?', '["$2 \\times 5 \\times 7 = 7 \\times 5 \\times 2$","$2 \\times (5 + 7) = 2 \\times 5 + 2 \\times 7$","$(2 \\times 5) \\times 7 = 2 \\times (5 \\times 7)$","$2 \\times 5 = 5 \\times 2$"]', '$(2 \times 5) \times 7 = 2 \times (5 \times 7)$', NULL, 'The associative property says that changing how factors are grouped does not change the product. Both sides keep the order 2, 5, 7 and only move the parentheses.', 'checked', '{"lint":[],"solve":{"answer":"$(2 \\times 5) \\times 7 = 2 \\times (5 \\times 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative property regroups: (2 x 5) x 7 = 2 x (5 x 7). A is distributive, B commutative, C reorders (commutative).","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8da3bba-1e26-4643-b524-dac46ebfdaa9', 'NC26.5.ANR.1', 2, 'numeric', 'Associative property', 'To find $4 \times (7 \times 25)$ in her head, Mina first groups $4 \times 25$. What is the value of the whole expression?', '[]', '700', '4*25*7', 'Regroup the factors: $4 \times 25 = 100$ and $100 \times 7 = 700$. So the value is 700.', 'checked', '{"lint":[],"solve":{"answer":"700","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 25 = 100; 100 x 7 = 700.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a5671a1-e6d4-4d9a-a533-4e259cc7a1bd', 'NC26.5.ANR.1', 2, 'choice', 'Distributive property', 'Which expression is equal to $9 \times (10 - 2)$?', '["$9 \\times 10 - 2$","$9 \\times 10 \\times 2$","$(9 \\times 10) - (2 \\times 10)$","$9 \\times 10 - 9 \\times 2$"]', '$9 \times 10 - 9 \times 2$', NULL, 'The 9 multiplies both numbers in the parentheses: $9 \times 10 - 9 \times 2 = 90 - 18 = 72$, the same as $9 \times 8$.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 10 - 9 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x (10 - 2) = 72 = 9 x 10 - 9 x 2 = 90 - 18. Others: 88, 70, 180.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c042d5b8-d4cd-4771-b48d-65d2a0acc513', 'NC26.5.ANR.1', 2, 'numeric', 'Distributive property', 'Sara finds $8 \times 49$ by thinking of it as $8 \times 50 - 8 \times 1$. What is the value?', '[]', '392', '8*50-8*1', '$8 \times 50 = 400$ and $8 \times 1 = 8$. Subtracting gives $400 - 8 = 392$.', 'checked', '{"lint":[],"solve":{"answer":"392","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 50 = 400; 8 x 1 = 8; 400 - 8 = 392.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4069dc8e-c037-44ad-9317-e85f4df9d74e', 'NC26.5.ANR.1', 2, 'choice', 'Distributive property', 'Which equation shows the distributive property?', '["$4 \\times (6 \\times 3) = (4 \\times 6) \\times 3$","$4 \\times (6 + 3) = 4 \\times 6 + 4 \\times 3$","$4 \\times 6 = 6 \\times 4$","$4 \\times 1 = 4$"]', '$4 \times (6 + 3) = 4 \times 6 + 4 \times 3$', NULL, 'The distributive property multiplies a number by each part of a sum: $4 \times (6 + 3) = 4 \times 6 + 4 \times 3$. The others show the associative, commutative and identity properties.', 'checked', '{"lint":[],"solve":{"answer":"$4 \\times (6 + 3) = 4 \\times 6 + 4 \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distributive: 4 x (6 + 3) = 4 x 6 + 4 x 3 (36 = 24 + 12). B associative, C commutative, D identity.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a9c2404-cfd7-41e5-b5e7-89cbd0b020d6', 'NC26.5.ANR.1', 2, 'choice', 'Identity and zero properties', 'Which equation shows the identity property of multiplication?', '["$9 \\times 0 = 0$","$9 \\times 1 = 9$","$9 + 0 = 9$","$9 \\times 3 = 3 \\times 9$"]', '$9 \times 1 = 9$', NULL, 'The identity property of multiplication says that a number times 1 stays the same: $9 \times 1 = 9$. The equation $9 + 0 = 9$ is the identity property of addition, $9 \times 0 = 0$ is the zero property and $9 \times 3 = 3 \times 9$ is the commutative property.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 1 = 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Identity property of multiplication: times 1 leaves the number unchanged, 9 x 1 = 9. 9 x 0 is the zero property, 9 + 0 additive identity, last commutative.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b32f92b2-8dcd-4b4c-b296-28c94f456481', 'NC26.5.ANR.1', 2, 'choice', 'Connect an expression to a representation', 'A rectangle is 9 units long and 6 units wide. It is cut into a rectangle that is 9 by 4 and a rectangle that is 9 by 2. Which expression gives the area of the large rectangle?', '["$9 \\times 4 + 2$","$9 \\times 4 + 9 \\times 2$","$9 + 4 \\times 2$","$(9 + 4) \\times 2$"]', '$9 \times 4 + 9 \times 2$', NULL, 'The area is the sum of the two parts: $9 \times 4 + 9 \times 2 = 36 + 18 = 54$. That is the same as $9 \times 6$.', 'checked', '{"lint":[],"solve":{"answer":"$9 \\times 4 + 9 \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 9 x 6 = 54 = 9 x 4 + 9 x 2 = 36 + 18. Others: 17, 38, 26.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee0a5e90-1530-42b7-ad1b-61807db626ae', 'NC26.5.ANR.1', 2, 'numeric', 'Connect an expression to a representation', 'An area model for 7 times 24 is split into a rectangle that is 7 by 20 and a rectangle that is 7 by 4. What is the total area?', '[]', '168', '7*20+7*4', 'The parts have areas $7 \times 20 = 140$ and $7 \times 4 = 28$. The total is $140 + 28 = 168$.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 20 = 140; 7 x 4 = 28; 140 + 28 = 168.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae0ca73f-ae63-4d53-afcb-fb92c955bd26', 'NC26.5.ANR.1', 2, 'numeric', 'Find the missing number or sign', 'What number makes the equation true? $5 + 3 \times \square = 29$', '[]', '8', '(29-5)/3', 'Multiplication comes first, so $3 \times \square$ must be $29 - 5 = 24$. Then the box is $24 \div 3 = 8$. Check: $5 + 3 \times 8 = 5 + 24 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 x box = 29, so 3 x box = 24, box = 8. Check 5 + 24 = 29.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f95d15f6-d0c8-4bae-b5d5-b2155fd7a4f8', 'NC26.5.ANR.1', 2, 'choice', 'Find the missing number or sign', 'Which sign goes in the box to make the equation true? $20 \ \square \ 4 \times 2 = 12$', '["$+$","$-$","$\\times$","$\\div$"]', '$-$', NULL, 'Multiplication comes first: $4 \times 2 = 8$. We need $20 \ \square \ 8 = 12$, and $20 - 8 = 12$. So the sign is minus. The other signs give 28, 160 and 10.', 'checked', '{"lint":[],"solve":{"answer":"$-$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 2 = 8 is done first, so 20 ? 8 = 12 needs minus. Check others: 20 x 4 x 2 = 160, 20 + 8 = 28, 20 / 4 x 2 = 10 (left to right). Only minus.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21665b95-b736-4a34-85f7-625440aa9a58', 'NC26.5.ANR.1', 2, 'choice', 'Find the mistake in an evaluation', 'Kofi says that $4 + 6 \times 5$ equals 50. What did he do?', '["He multiplied 4 and 6 first, then added 5","He multiplied 6 and 5 first, then subtracted 4","He added 4 and 6 first, then multiplied by 5","He added all three numbers"]', 'He added 4 and 6 first, then multiplied by 5', NULL, 'Adding first gives $(4 + 6) \times 5 = 50$, which is Kofi''s answer. The correct way is to multiply first: $6 \times 5 = 30$, then $4 + 30 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"He added 4 and 6 first, then multiplied by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct value 4 + 30 = 34. 50 = (4 + 6) x 5, so he added 4 and 6 first. B gives 29, C 26, D 15.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037a88e1-019e-482d-b4df-d3a8b1e0c3bc', 'NC26.5.ANR.1', 3, 'numeric', 'Evaluate an expression with parentheses and two other operations', 'Find the value of $2 \times (15 - 6) + 4 \times 3$.', '[]', '30', '2*(15-6)+4*3', 'Parentheses first: $15 - 6 = 9$. Then multiply: $2 \times 9 = 18$ and $4 \times 3 = 12$. Then add: $18 + 12 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 - 6 = 9; 2 x 9 = 18; 4 x 3 = 12; 18 + 12 = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e6bf441-28e3-45a9-8463-bd6fdc8d7d29', 'NC26.5.ANR.1', 3, 'choice', 'Compare the values of expressions', 'Which expression has the greatest value?', '["$24 \\div 4 + 2$","$24 \\div (4 + 2)$","$(24 - 4) \\times 2$","$24 - 4 \\times 2$"]', '$(24 - 4) \times 2$', NULL, '$24 \div 4 + 2 = 8$, $24 \div (4 + 2) = 4$, $24 - 4 \times 2 = 16$, and $(24 - 4) \times 2 = 40$. The greatest is $(24 - 4) \times 2$.', 'checked', '{"lint":[],"solve":{"answer":"$(24 - 4) \\times 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(24-4) x 2 = 40; 24/(4+2) = 4; 24 - 4x2 = 16; 24/4 + 2 = 8. Greatest is 40.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c2b990f-e1e9-4c7b-aba8-a56a1341fadb', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a situation', 'Each box holds 6 red pens and 4 blue pens. Which expression gives the number of pens in 3 boxes?', '["$3 \\times (6 + 4)$","$3 \\times 6 + 4$","$3 + 6 \\times 4$","$3 \\times 6 \\times 4$"]', '$3 \times (6 + 4)$', NULL, 'One box holds $6 + 4$ pens. Three boxes hold 3 times that: $3 \times (6 + 4) = 30$ pens. The other expressions multiply only one kind of pen by 3, or multiply all three numbers.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times (6 + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each box has 6 + 4 = 10 pens; 3 boxes: 3 x (6 + 4) = 30.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2db2f228-5704-49d1-ad40-007a5dd57a5c', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations without parentheses', 'What is the value of $3 \times 12 + 40 \div 8$?', '[]', '41', '3*12+40/8', 'Do the multiplication and the division first: $3 \times 12 = 36$ and $40 \div 8 = 5$. Then add: $36 + 5 = 41$.', 'checked', '{"lint":[],"solve":{"answer":"41","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 12 = 36 and 40 / 8 = 5; 36 + 5 = 41.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('958ecadb-cfca-459f-9df4-df74b0b78db2', 'NC26.5.ANR.1', 3, 'choice', 'Order of operations without parentheses', 'Which is the value of $90 \div 9 - 2 \times 4$?', '["2","32","18","8"]', '2', '90/9-2*4', 'Do the division and the multiplication first: $90 \div 9 = 10$ and $2 \times 4 = 8$. Then subtract: $10 - 8 = 2$. The choice 32 comes from working left to right ($8 \times 4$), 18 from adding 8 instead of subtracting, and 8 from taking away only 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 / 9 = 10 and 2 x 4 = 8; 10 - 8 = 2. (32 = (10 - 2) x 4.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ddbb4e8-06ea-4413-98b7-50fa53e2c672', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations without parentheses', 'Evaluate $7 \times 13 + 480 \div 12$.', '[]', '131', '7*13+480/12', 'Multiply and divide first: $7 \times 13 = 91$ and $480 \div 12 = 40$. Then add: $91 + 40 = 131$.', 'checked', '{"lint":[],"solve":{"answer":"131","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 13 = 91 and 480 / 12 = 40; 91 + 40 = 131.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88443329-bbc0-445c-8e8e-04581998f398', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations with parentheses', 'Evaluate $(14 - 6) \times (9 - 3)$.', '[]', '48', '(14-6)*(9-3)', 'Do each set of parentheses first: $14 - 6 = 8$ and $9 - 3 = 6$. Then multiply: $8 \times 6 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 - 6 = 8 and 9 - 3 = 6; 8 x 6 = 48.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c74850b-8cc6-4e27-817f-1526f1e1cf89', 'NC26.5.ANR.1', 3, 'choice', 'Order of operations with parentheses', 'Which is the value of $5 \times (24 \div 6 + 2)$?', '["22","30","15","20"]', '30', '5*(24/6+2)', 'Inside the parentheses, divide before adding: $24 \div 6 = 4$ and $4 + 2 = 6$. Then multiply: $5 \times 6 = 30$. The choice 22 comes from ignoring the parentheses ($5 \times 4 + 2$), 15 from computing $24 \div (6 + 2)$ first, and 20 from leaving out the $+ 2$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inside: 24 / 6 = 4, 4 + 2 = 6; 5 x 6 = 30. (22 = 5 x 4 + 2.)","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb9249f4-3ca1-498b-b4d3-252bfdd8f6e7', 'NC26.5.ANR.1', 3, 'numeric', 'Order of operations with parentheses', 'What is the value of $2 \times (50 - 3 \times 8)$?', '[]', '52', '2*(50-3*8)', 'Inside the parentheses, multiply before subtracting: $3 \times 8 = 24$ and $50 - 24 = 26$. Then multiply: $2 \times 26 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inside: 3 x 8 = 24, 50 - 24 = 26; 2 x 26 = 52.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('435f6c79-216c-487d-a6e5-5918041ecffd', 'NC26.5.ANR.1', 3, 'choice', 'Compare the values of expressions', 'Which statement is true?', '["$7 + 3 \\times 5 = (7 + 3) \\times 5$","$36 \\div 6 + 3 < 36 \\div (6 + 3)$","$20 - 3 \\times 4 < (20 - 3) \\times 4$","$4 \\times 5 - 2 = 4 \\times (5 - 2)$"]', '$20 - 3 \times 4 < (20 - 3) \times 4$', NULL, '$20 - 3 \times 4 = 8$ and $(20 - 3) \times 4 = 68$, and $8 < 68$ is true. The others are false: $7 + 3 \times 5 = 22$ but $(7 + 3) \times 5 = 50$; $36 \div 6 + 3 = 9$ but $36 \div (6 + 3) = 4$, and 9 is not less than 4; $4 \times 5 - 2 = 18$ but $4 \times (5 - 2) = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$20 - 3 \\times 4 < (20 - 3) \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 = 12? no. 22 = 50? no. 6 + 3 = 9 < 36/9 = 4? no. 20 - 12 = 8 < 17 x 4 = 68? yes. Only the last is true.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d17aa4a1-f364-4c67-a4f0-a38e3872c1f8', 'NC26.5.ANR.1', 3, 'numeric', 'Compare the values of expressions', 'Four expressions are listed: $4 + 5 \times 4$, $(4 + 5) \times 4$, $4 \times 5 + 4$ and $4 \times (5 + 4)$. How many of them have a value of 24?', '[]', '2', NULL, '$4 + 5 \times 4 = 4 + 20 = 24$; $(4 + 5) \times 4 = 36$; $4 \times 5 + 4 = 24$; $4 \times (5 + 4) = 36$. Two of the four have a value of 24.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 20 = 24 (yes); 9 x 4 = 36; 20 + 4 = 24 (yes); 4 x 9 = 36. Two of them.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e57d61ce-666e-47ee-a13b-b14443596f6e', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a described calculation', 'Which expression means "subtract 4 from twice the sum of 9 and 6"?', '["$2 \\times 9 + 6 - 4$","$2 \\times (9 + 6 - 4)$","$2 + (9 + 6) - 4$","$2 \\times (9 + 6) - 4$"]', '$2 \times (9 + 6) - 4$', NULL, '"The sum of 9 and 6" is $(9 + 6)$. "Twice" that is $2 \times (9 + 6)$. "Subtract 4 from" that gives $2 \times (9 + 6) - 4$.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times (9 + 6) - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice the sum of 9 and 6 is 2 x (9 + 6); subtract 4: 2 x (9 + 6) - 4.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('550d3dd4-6d91-4f0c-99d3-0d6f8dc3385e', 'NC26.5.ANR.1', 3, 'numeric', 'Write an expression for a described calculation', 'Divide 100 by the product of 5 and 4, then add 12. What number do you get?', '[]', '17', '100/(5*4)+12', 'The product of 5 and 4 is 20. Dividing gives $100 \div 20 = 5$. Adding 12 gives $5 + 12 = 17$. As an expression this is $100 \div (5 \times 4) + 12$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product 5 x 4 = 20; 100 / 20 = 5; 5 + 12 = 17.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98047e32-5c79-44d6-b8b6-3e25c50bbfe2', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a described calculation', 'Which expression means "add 10 to the quotient of 48 and 6, then multiply by 3"?', '["$10 + 48 \\div 6 \\times 3$","$(10 + 48 \\div 6) \\times 3$","$10 + 48 \\div (6 \\times 3)$","$(10 + 48) \\div 6 \\times 3$"]', '$(10 + 48 \div 6) \times 3$', NULL, 'The quotient of 48 and 6 is $48 \div 6$. Adding 10 gives $10 + 48 \div 6$, and this whole sum is then multiplied by 3, so it goes in parentheses: $(10 + 48 \div 6) \times 3$.', 'checked', '{"lint":[],"solve":{"answer":"$(10 + 48 \\div 6) \\times 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quotient 48 / 6; add 10: 10 + 48 / 6; then multiply that whole by 3: (10 + 48 / 6) x 3 = 18 x 3 = 54. Option B gives 10 + 24 = 34, so only A.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92b3f352-2012-4b10-894d-005d394fd1de', 'NC26.5.ANR.1', 3, 'numeric', 'Write an expression for a story', 'A baker makes 6 trays of 12 rolls. He sells 45 rolls in the morning and 15 more in the afternoon. How many rolls are left?', '[]', '12', '6*12-45-15', 'He bakes $6 \times 12 = 72$ rolls. He sells $45 + 15 = 60$. So $72 - 60 = 12$ rolls are left.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 12 = 72 rolls; sold 45 + 15 = 60; 72 - 60 = 12.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fcb198f-f864-452b-946c-a504a8664ffc', 'NC26.5.ANR.1', 3, 'choice', 'Write an expression for a story', 'A class collects 9 cans a day for 5 days. Then 5 cans are thrown away and the rest are divided equally among 4 bins. Which expression gives the number of cans in each bin?', '["$9 \\times 5 - 5 \\div 4$","$(9 + 5 - 5) \\div 4$","$9 \\times 5 \\div 4 - 5$","$(9 \\times 5 - 5) \\div 4$"]', '$(9 \times 5 - 5) \div 4$', NULL, 'The class collects $9 \times 5$ cans. After throwing 5 away, there are $9 \times 5 - 5$ cans, and this whole amount is divided by 4. So the expression is $(9 \times 5 - 5) \div 4$, which is $40 \div 4 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$(9 \\times 5 - 5) \\div 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Collected 9 x 5 = 45; minus 5 = 40; divided among 4 bins: (9 x 5 - 5) / 4 = 10.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee8bbce7-4101-4e0c-a2aa-857778281ac6', 'NC26.5.ANR.1', 3, 'numeric', 'Write an expression for a story', 'Priya earns 8 dollars each hour and works 5 hours. She spends 14 dollars on lunch and 6 dollars on a bus ticket. How many dollars does she have left?', '[]', '20', '8*5-14-6', 'She earns $8 \times 5 = 40$ dollars. She spends $14 + 6 = 20$ dollars. She has $40 - 20 = 20$ dollars left.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Earns 8 x 5 = 40; spends 14 + 6 = 20; 40 - 20 = 20.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0d98abe-c6e3-4e9b-baa1-bd53232ad440', 'NC26.5.ANR.1', 3, 'numeric', 'Interpret an expression without calculating', 'The value of $(23 + 17) \times 6$ is 240. What is the value of $(23 + 17) \times 12$? Do not add 23 and 17 again.', '[]', '480', '240*2', 'The second expression multiplies the same sum by 12 instead of 6, which is twice as much. So the value is $2 \times 240 = 480$.', 'checked', '{"lint":[],"solve":{"answer":"480","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check: 40 x 6 = 240. 12 is twice 6, so (23 + 17) x 12 = 2 x 240 = 480.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c317fcf-059b-43fb-9e4c-40dbd2dcacfd', 'NC26.5.ANR.1', 3, 'numeric', 'Interpret an expression without calculating', 'Alex knows that $14 \times 6$ equals 84. Using this, what is the value of $14 \times 7$?', '[]', '98', '84+14', '$14 \times 7$ is one more group of 14 than $14 \times 6$. So $14 \times 7 = 84 + 14 = 98$.', 'checked', '{"lint":[],"solve":{"answer":"98","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 7 = 14 x 6 + 14 = 84 + 14 = 98.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6a78495-33ee-42fa-aa83-00931bee75fc', 'NC26.5.ANR.1', 3, 'numeric', 'Associative property', 'What number goes in the box to make the equation true? $(9 \times 6) \times \square = 9 \times (6 \times 5)$', '[]', '5', '(9*6*5)/(9*6)', 'Both sides are the product of 9, 6 and 5 with different grouping. So the box is 5. Each side equals 270.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Associative: (9 x 6) x 5 = 9 x (6 x 5); box = 5. Check 54 x 5 = 270 = 9 x 30.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b070692-5513-45ca-bc4b-58e0229bbed7', 'NC26.5.ANR.1', 3, 'choice', 'Associative property', 'Which expression equals $(13 + 28) + 22$ and is the easiest to work out in your head?', '["$13 + (28 + 22)$","$(13 + 28) - 22$","$13 + 28 \\times 22$","$(28 - 13) + 22$"]', '$13 + (28 + 22)$', NULL, 'Regroup the addition as $13 + (28 + 22)$. Then $28 + 22 = 50$ and $13 + 50 = 63$, which equals $(13 + 28) + 22 = 41 + 22 = 63$.', 'checked', '{"lint":[],"solve":{"answer":"$13 + (28 + 22)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(13 + 28) + 22 = 63. 13 + (28 + 22) = 13 + 50 = 63, easy. (28 - 13) + 22 = 37; (13 + 28) - 22 = 19; 13 + 616 = 629. Only D equals.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a30efb0-2e27-46fd-b844-f04849084c68', 'NC26.5.ANR.1', 3, 'numeric', 'Distributive property', 'What is the value of $6 \times 34 + 6 \times 16$? Hint: both parts have a factor of 6.', '[]', '300', '6*34+6*16', 'Write it as $6 \times (34 + 16) = 6 \times 50 = 300$. Check: $6 \times 34 = 204$ and $6 \times 16 = 96$, and $204 + 96 = 300$.', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x (34 + 16) = 6 x 50 = 300. Check 204 + 96 = 300.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ab85301-58a6-4a30-b5c9-433232f0bf15', 'NC26.5.ANR.1', 3, 'choice', 'Distributive property', 'Which expression is equal to $12 \times 15$ if 12 is split into 10 and 2?', '["$10 \\times 15 + 2 \\times 15$","$10 \\times 15 + 2$","$10 + 2 \\times 15$","$10 \\times 2 \\times 15$"]', '$10 \times 15 + 2 \times 15$', NULL, 'Split 12 into $10 + 2$ and multiply each part by 15: $12 \times 15 = 10 \times 15 + 2 \times 15 = 150 + 30 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"$10 \\times 15 + 2 \\times 15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(10 + 2) x 15 = 10 x 15 + 2 x 15 = 150 + 30 = 180 = 12 x 15. Others: 300, 152, 40.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05e9a6f8-d6fb-4ea0-ac09-f9cc7abc1f72', 'NC26.5.ANR.1', 3, 'choice', 'Distributive property', 'Which expression is NOT equal to $7 \times 18$?', '["$7 \\times 20 - 7 \\times 2$","$7 \\times 9 \\times 2$","$70 + 56$","$7 \\times 10 + 8$"]', '$7 \times 10 + 8$', NULL, '$7 \times 18 = 126$. Also $7 \times 20 - 7 \times 2 = 140 - 14 = 126$, $7 \times 9 \times 2 = 63 \times 2 = 126$, and $70 + 56 = 126$. But $7 \times 10 + 8 = 78$, because the 7 was not multiplied by the 8.', 'checked', '{"lint":[],"solve":{"answer":"$7 \\times 10 + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 18 = 126. 7 x 9 x 2 = 126; 7 x 10 + 8 = 78 (not equal); 70 + 56 = 126; 140 - 14 = 126.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('406fc8f7-79c9-4275-bdbb-1fce0a782cd5', 'NC26.5.ANR.1', 3, 'numeric', 'Distributive property', 'A garden has 14 rows with 25 plants in each row. Using $14 \times 25$ equals $10 \times 25 + 4 \times 25$, how many plants are in the garden?', '[]', '350', '10*25+4*25', '$10 \times 25 = 250$ and $4 \times 25 = 100$. Adding gives $250 + 100 = 350$ plants.', 'checked', '{"lint":[],"solve":{"answer":"350","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 25 = 250; 4 x 25 = 100; 250 + 100 = 350.","run_id":"claude-code","at":"2026-10-17T19:23:26.690Z"}}', 'ai', NULL, NULL)
