INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4b13649-ffee-48e1-809f-8d1313e87734', 'NC26.5.ANR.2', 1, 'numeric', 'Compare the values of a digit in different places', 'The number 66 has two 6s. The value of the left 6 is how many times the value of the right 6?', '[]', '10', '60/6', 'The left 6 is in the tens place and is worth 60. The right 6 is in the ones place and is worth 6. Since $60 \div 6 = 10$, the left 6 is 10 times as great.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left 6 = 60, right 6 = 6; 60 / 6 = 10.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
