INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b83942c-290d-46d3-9f32-f1f3e054d573', 'NC26.5.ANR.2', 1, 'choice', 'Compare the values of a digit in different places', 'In $4.44$, the 4 in the ones place is how many times as great as the 4 in the tenths place?', '["$\\frac{1}{10}$","10","100","4"]', '10', NULL, 'The 4 in the ones place is worth 4 and the 4 in the tenths place is worth $0.4$. Since $4 \div 0.4 = 10$, the first is 10 times as great.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ones 4 = 4, tenths 4 = 0.4; 4 / 0.4 = 10.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
