INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('098edd49-8371-4490-9e8b-b5786ba836ee', 'NC26.5.ANR.2', 3, 'numeric', 'Value of a digit in a decimal to the thousandths', 'In $7.272$, what is the sum of the values of the two 7s?', '[]', '7.07', '7+7/100', 'One 7 is in the ones place and is worth 7. The other 7 is in the hundredths place and is worth $0.07$. Their sum is $7 + 0.07 = 7.07$.', 'checked', '{"lint":[],"solve":{"answer":"7.07","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.272: 7 ones = 7 and 7 hundredths = 0.07. Sum 7.07.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
