INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf3ddc0e-2fac-400a-a307-c059a1bf3a57', 'NC26.5.ANR.2', 3, 'numeric', 'Compare the values of a digit in different places', 'In $5{,}050.505$, how many times as great is the value of the leftmost 5 as the value of the rightmost 5?', '[]', '1000000', '5000/0.005', 'The leftmost 5 is in the thousands place and is worth 5,000. The rightmost 5 is in the thousandths place and is worth $0.005$. Since $5{,}000 \div 0.005 = 1{,}000{,}000$, the leftmost 5 is one million times as great.', 'checked', '{"lint":[],"solve":{"answer":"1000000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Demanding for Grade 5: the two 5s are six places apart, so the answer is a million; fine as a stretch item.","work":"5,050.505: leftmost 5 is 5 thousands = 5,000; rightmost 5 is 5 thousandths = 0.005. They are six places apart, so 10^6: 5,000 / 0.005 = 1,000,000.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
