INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77ee5641-5cc7-40a3-acd7-11d6f3a56403', 'NC26.5.ANR.2', 3, 'choice', 'Find the unknown in a power-of-ten pattern', 'Maria multiplied a number by 10 and then divided the result by 1,000. The answer was 0.052. What was her number?', '["52","0.52","5.2","0.0052"]', '5.2', '0.052*100', 'Multiplying by 10 and then dividing by 1,000 is the same as dividing by 100. To undo it, multiply 0.052 by 100: $0.052 \times 100 = 5.2$.', 'checked', '{"lint":[],"solve":{"answer":"5.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo: 0.052 x 1,000 = 52, then 52 / 10 = 5.2. Check 5.2 x 10 = 52, 52 / 1,000 = 0.052.","run_id":"claude-code","at":"2026-10-17T19:23:26.729Z"}}', 'ai', NULL, NULL)
