VALUES ('40cd37a0-5636-444f-a7d9-040dc9264c09', 'NC26.5.ANR.3', 1, 'choice', 'Find the quotient and remainder', 'What is $2{,}403 \div 4$? Give the quotient with its remainder.', '["600 R 3","60 R 3","603","600 R 4"]', '600 R 3', NULL, '$4 \times 600 = 2{,}400$, and $2{,}403 - 2{,}400 = 3$. So $2{,}403 \div 4 = 600$ with remainder 3.', 'checked', '{"lint":[],"solve":{"answer":"600 R 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 600 = 2,400; 2,403 - 2,400 = 3. So 600 R 3.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
