INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad7ffd15-1ca0-4d29-ae68-f13074d43e5e', 'NC26.5.ANR.3', 1, 'numeric', 'Find the quotient and remainder', 'A teacher has $1{,}608$ stickers and puts them in packs of 5. After making as many full packs as she can, how many stickers are left over?', '[]', '3', '1608-5*321', '$5 \times 321 = 1{,}605$, and $1{,}608 - 1{,}605 = 3$. Three stickers are left over.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 321 = 1,605; 1,608 - 1,605 = 3 left over.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
