INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26ce84cf-8ac6-4b85-8bde-a11bb130b9e0', 'NC26.5.ANR.3', 1, 'choice', 'Interpret a remainder in context', 'Each row in a stadium seats 9 fans. How many rows are needed to seat $1{,}000$ fans?', '["111","112","111 R 1","1"]', '112', '(1000-1)/9+1', '$1{,}000 \div 9 = 111$ with remainder 1. The last fan needs a seat too, so one more row is needed: $111 + 1 = 112$ rows.', 'checked', '{"lint":[],"solve":{"answer":"112","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000 / 9 = 111 R 1 (9 x 111 = 999). One fan still needs a seat, so 112 rows.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
