INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b5128f7-db37-4d66-8d59-51f932d12a4b', 'NC26.5.ANR.3', 1, 'numeric', 'Check and connect multiplication and division', 'Because $7 \times 1{,}250 = 8{,}750$, what is $8{,}750 \div 7$?', '[]', '1250', '8750/7', 'Division undoes multiplication. Since $7 \times 1{,}250 = 8{,}750$, we get $8{,}750 \div 7 = 1{,}250$.', 'checked', '{"lint":[],"solve":{"answer":"1250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Division undoes multiplication: 8,750 / 7 = 1,250.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
