VALUES ('959575f7-83b6-470a-981c-90f6a25c441b', 'NC26.5.ANR.3', 1, 'choice', 'Check and connect multiplication and division', 'Which multiplication can be used to check that $5{,}196 \div 6 = 866$?', '["$866 + 6$","$5{,}196 - 866$","$866 \\times 6$","$5{,}196 \\times 6$"]', '$866 \times 6$', NULL, 'To check a division, multiply the quotient by the divisor: $866 \times 6 = 5{,}196$, which is the number that was divided.', 'checked', '{"lint":[],"solve":{"answer":"$866 \\times 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quotient x divisor should equal the dividend: 866 x 6 = 5,196.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
