INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ea2a5cd-9033-4915-b8b9-91a283abfff0', 'NC26.5.ANR.3', 1, 'choice', 'Estimate a quotient', 'A grower picked $1{,}792$ pears and packed about the same number into each of 9 boxes. About how many pears are in each box?', '["20","2,000","200","180"]', '200', '1800/9', 'Round 1,792 to the nearby number 1,800, which is easy to divide by 9. $1800 \div 9 = 200$. So there are about 200 pears in each box. A box cannot hold about 20 or 2,000, because $9 \times 20$ is only 180 and $9 \times 2000$ is 18,000.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1792 is about 1800; 1800/9=200 (exact 199 r 1).","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
