INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7ffd44e-0011-4408-8662-6373f8b80f26', 'NC26.5.ANR.3', 2, 'choice', 'Multiply a three-digit number by a two-digit number', 'Dev multiplies 308 by 46. What product should he get?', '["3,080","1,748","14,068","14,168"]', '14,168', '308*46', '$308 \times 6 = 1{,}848$ and $308 \times 40 = 12{,}320$. Add: $1{,}848 + 12{,}320 = 14{,}168$.', 'checked', '{"lint":[],"solve":{"answer":"14,168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"308 x 46 = 308 x 40 + 308 x 6 = 12,320 + 1,848 = 14,168.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
