VALUES ('86180d54-60b0-4f68-a158-0d20472ee02d', 'NC26.5.ANR.3', 2, 'choice', 'Long division with a zero in the quotient', 'What is $6{,}030 \div 5$?', '["126","1,206","1,260","1,216"]', '1,206', '6030/5', '$6 \div 5 = 1$ r 1. Bring down 0: $10 \div 5 = 2$. Bring down 3: $3 \div 5 = 0$ r 3. Bring down 0: $30 \div 5 = 6$. The quotient is $1{,}206$. Check: $1{,}206 \times 5 = 6{,}030$.', 'checked', '{"lint":[],"solve":{"answer":"1,206","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,030 / 5 = 1,206 (5 x 1,206 = 6,030).","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
