VALUES ('a0e3cca0-8732-445f-8603-c6c6343c06d1', 'NC26.5.ANR.3', 2, 'choice', 'Find the quotient and remainder', 'Which division has a remainder of 6?', '["$4{,}325 \\div 7$","$4{,}325 \\div 4$","$4{,}325 \\div 5$","$4{,}325 \\div 6$"]', '$4{,}325 \div 7$', NULL, '$4{,}325 \div 7$: $7 \times 617 = 4{,}319$ and $4{,}325 - 4{,}319 = 6$. The others leave remainders of 1, 0 and 5.', 'checked', '{"lint":[],"solve":{"answer":"$4{,}325 \\div 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,325 / 7: 7 x 617 = 4,319, R 6. /4: 4,324 -> R 1. /6: 6 x 720 = 4,320, R 5. /5: R 0. Only divide by 7 has remainder 6.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
