INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4647e81-acd6-4027-82f2-23389914e81c', 'NC26.5.ANR.3', 2, 'numeric', 'Interpret a remainder in context', 'Each van seats 8 people. How many vans are needed to carry $2{,}050$ people?', '[]', '257', '(2050-2)/8+1', '$2{,}050 \div 8 = 256$ with remainder 2. Those 2 people need another van, so $256 + 1 = 257$ vans are needed.', 'checked', '{"lint":[],"solve":{"answer":"257","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,050 / 8 = 256 R 2 (8 x 256 = 2,048). 2 people left need another van: 257.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
