INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6c637a0-1ae2-46a9-b2b0-96dd046dfc5b', 'NC26.5.ANR.3', 2, 'numeric', 'Interpret a remainder in context', '$5{,}230$ beads are shared equally among 6 children. Each child gets as many beads as possible, and the leftover beads go in a jar. How many beads are in the jar?', '[]', '4', '5230-6*871', '$6 \times 871 = 5{,}226$, and $5{,}230 - 5{,}226 = 4$. Four beads go in the jar.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 871 = 5,226; 5,230 - 5,226 = 4 in the jar.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
