INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55be4caa-93f4-45f3-a1ed-1065b67b2ec1', 'NC26.5.ANR.3', 3, 'numeric', 'Multiply by multiples of ten and one hundred', 'A theme park sells 600 tickets each hour for 30 hours. Then it sells 400 tickets each hour for 20 hours. How many tickets does it sell in all?', '[]', '26000', '600*30+400*20', '$600 \times 30 = 18{,}000$ and $400 \times 20 = 8{,}000$. Add: $18{,}000 + 8{,}000 = 26{,}000$ tickets.', 'checked', '{"lint":[],"solve":{"answer":"26000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"600 x 30 = 18,000; 400 x 20 = 8,000; total 26,000.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
