VALUES ('01025d72-5b23-461f-a010-d7b81e84b263', 'NC26.5.ANR.3', 3, 'numeric', 'Divide a four-digit number by a one-digit number', 'A shipment of $9{,}576$ bolts is split equally into 8 crates. How many bolts go into each crate?', '[]', '1197', '9576/8', '$9{,}576 \div 8 = 1{,}197$ bolts. Check: $1{,}197 \times 8 = 9{,}576$.', 'checked', '{"lint":[],"solve":{"answer":"1197","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9,576 / 8 = 1,197 (8 x 1,200 = 9,600; 9,600 - 24 = 9,576, so 1,200 - 3 = 1,197).","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
