VALUES ('62a26da2-f93b-4bd9-8c03-3c8f88a94c75', 'NC26.5.ANR.3', 3, 'choice', 'Long division with a zero in the quotient', 'Which is the quotient when $6{,}036$ is divided by 6?', '["106","1,060","1,006","1,016"]', '1,006', '6036/6', '$6 \div 6 = 1$; $0 \div 6 = 0$; $3 \div 6 = 0$ (r 3); $36 \div 6 = 6$. The quotient is $1{,}006$. Check: $1{,}006 \times 6 = 6{,}036$.', 'checked', '{"lint":[],"solve":{"answer":"1,006","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,036 / 6 = 1,006 (6 x 1,006 = 6,036).","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
