INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8d943a0-40f5-4342-a4ac-6aa718a73cb7', 'NC26.5.ANR.3', 3, 'numeric', 'Find the quotient and remainder', 'When $8{,}004$ is divided by 9, what is the sum of the quotient and the remainder?', '[]', '892', '889+(8004-9*889)', '$9 \times 889 = 8{,}001$, so the quotient is 889 and the remainder is $8{,}004 - 8{,}001 = 3$. Their sum is $889 + 3 = 892$.', 'checked', '{"lint":[],"solve":{"answer":"892","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 889 = 8,001; 8,004 - 8,001 = 3. Quotient 889, remainder 3; sum 892.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
