INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99485694-9f69-450f-9717-e61090ab361d', 'NC26.5.ANR.3', 3, 'numeric', 'Find the quotient and remainder', 'Find the remainder when $6{,}000$ is divided by 7 and the remainder when $6{,}000$ is divided by 9. What is the sum of the two remainders?', '[]', '7', '(6000-7*857)+(6000-9*666)', '$7 \times 857 = 5{,}999$, so the first remainder is 1. $9 \times 666 = 5{,}994$, so the second remainder is 6. The sum is $1 + 6 = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 857 = 5,999, so 6,000 / 7 has R 1. 9 x 666 = 5,994, so 6,000 / 9 has R 6. Sum 1 + 6 = 7.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c89ec8b-10fa-4da8-9e82-6ab04a49e597', 'NC26.5.ANR.3', 3, 'choice', 'Find the quotient and remainder', 'Which division has the greatest remainder?', '["$2{,}000 \\div 3$","$2{,}000 \\div 9$","$2{,}000 \\div 6$","$2{,}000 \\div 7$"]', '$2{,}000 \div 7$', NULL, 'The remainders are: $2{,}000 \div 3$ leaves 2, $2{,}000 \div 7$ leaves 5, $2{,}000 \div 9$ leaves 2, and $2{,}000 \div 6$ leaves 2. The greatest is 5.', 'checked', '{"lint":[],"solve":{"answer":"$2{,}000 \\div 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,000 / 6: 6 x 333 = 1,998, R 2. /3: 3 x 666 = 1,998, R 2. /9: 9 x 222 = 1,998, R 2. /7: 7 x 285 = 1,995, R 5. Greatest remainder is with 7.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('495e11c7-f69d-48a1-8678-38bd45d8e3a3', 'NC26.5.ANR.3', 3, 'numeric', 'Interpret a remainder in context', 'Each van holds 7 people and costs 15 dollars to rent. How many dollars does it cost to rent enough vans for $1{,}000$ people?', '[]', '2145', '(142+1)*15', '$1{,}000 \div 7 = 142$ with remainder 6, so 143 vans are needed. $143 \times 15 = 1{,}430 + 715 = 2{,}145$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2145","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,000 / 7 = 142 R 6 (7 x 142 = 994), so 143 vans needed. 143 x 15 = 2,145 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
