INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4968133-66c1-4ca5-ab62-089a1e206ad2', 'NC26.5.ANR.3', 3, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A farmer picks 247 apples each day for 18 days and 164 apples each day for 12 days. How many apples does the farmer pick in all?', '[]', '6414', '247*18+164*12', '$247 \times 18 = 4{,}446$ and $164 \times 12 = 1{,}968$. Add: $4{,}446 + 1{,}968 = 6{,}414$ apples.', 'checked', '{"lint":[],"solve":{"answer":"6414","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"247 x 18 = 2,470 + 1,976 = 4,446; 164 x 12 = 1,968; total 4,446 + 1,968 = 6,414.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
