INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd5928fb-23a7-4196-b69c-01fe2aed2298', 'NC26.5.ANR.3', 3, 'choice', 'Solve a multi-step problem with multiplication and division', 'Each of 24 classes collects 126 cans. All of the cans are packed 6 to a box. How many boxes are needed?', '["504","3,024","21","150"]', '504', '24*126/6', '$24 \times 126 = 3{,}024$ cans in all. $3{,}024 \div 6 = 504$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"504","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 x 126 = 3,024 cans; 3,024 / 6 = 504 boxes.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
