INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82b9d872-8040-4a04-aebb-350722dd293f', 'NC26.5.ANR.3', 3, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A zoo had $1{,}284$ visitors on Saturday. On Sunday it had 3 times as many visitors as on Saturday. All the visitors from both days are put into groups of 6. How many groups are there?', '[]', '856', '(1284+3*1284)/6', 'Sunday: $3 \times 1{,}284 = 3{,}852$ visitors. Both days: $1{,}284 + 3{,}852 = 5{,}136$. Groups of 6: $5{,}136 \div 6 = 856$ groups.', 'checked', '{"lint":[],"solve":{"answer":"856","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sunday 3 x 1,284 = 3,852; total 1,284 + 3,852 = 5,136; 5,136 / 6 = 856 groups (6 x 856 = 5,136).","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
