INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8cc1aac-4da8-4ce4-bc02-cb753c021716', 'NC26.5.ANR.3', 3, 'choice', 'Solve a multi-step problem with multiplication and division', 'Play tickets cost 13 dollars each. On Friday 214 tickets were sold, and on Saturday 298 tickets were sold. How many dollars were paid for tickets in all?', '["2,782","3,874","525","6,656"]', '6,656', '(214+298)*13', 'Tickets sold: $214 + 298 = 512$. $512 \times 13 = 5{,}120 + 1{,}536 = 6{,}656$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"6,656","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"214 + 298 = 512 tickets; 512 x 13 = 5,120 + 1,536 = 6,656 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
