INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdb45552-48a1-4d19-b0bd-7fa4b8844c78', 'NC26.5.ANR.3', 3, 'numeric', 'Solve a multi-step problem with multiplication and division', 'A warehouse ships 125 boxes each day for 14 days and then has $1{,}250$ boxes left. How many boxes did it have at first?', '[]', '3000', '125*14+1250', 'Shipped: $125 \times 14 = 1{,}750$ boxes. At first it had the shipped boxes plus the boxes left: $1{,}750 + 1{,}250 = 3{,}000$ boxes.', 'checked', '{"lint":[],"solve":{"answer":"3000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 x 14 = 1,750 shipped; 1,750 + 1,250 = 3,000 at first.","run_id":"claude-code","at":"2026-10-17T20:08:27.927Z"}}', 'ai', NULL, NULL)
