VALUES ('f0b5bad8-c6ff-48c6-9718-2a792e08d1c9', 'NC26.5.ANR.4', 1, 'choice', 'Reason about decimal operations', 'Which equation is true?', '["$1.2 + 0.8 = 2$","$2.5 + 3.5 = 5.0$","$0.5 + 0.5 = 0.10$","$4.0 + 0.4 = 4.04$"]', '$1.2 + 0.8 = 2$', NULL, '$1.2 + 0.8 = 2.0$, which is 2. The others are false: $2.5 + 3.5 = 6.0$, $0.5 + 0.5 = 1.0$ and $4.0 + 0.4 = 4.4$.', 'checked', '{"lint":[],"solve":{"answer":"$1.2 + 0.8 = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.0 + 0.4 = 4.4 (not 4.04); 0.5 + 0.5 = 1.0 (not 0.10); 1.2 + 0.8 = 2.0 = 2 (true); 2.5 + 3.5 = 6.0 (not 5.0).","run_id":"claude-code","at":"2026-10-17T20:08:27.980Z"}}', 'ai', NULL, NULL)
