INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98643f64-8c9e-41b0-9f02-07a25b5ec2cd', 'NC26.5.ANR.5', 1, 'choice', 'Add fractions with unlike denominators', 'Add: $\frac{2}{5} + \frac{3}{10}$.', '["$\\frac{5}{15}$","$\\frac{5}{10}$","$\\frac{7}{10}$","$\\frac{1}{10}$"]', '$\frac{7}{10}$', NULL, 'Rename $\frac{2}{5}$ as $\frac{4}{10}$. Then $\frac{4}{10} + \frac{3}{10}$ = $\frac{7}{10}$. Adding the tops and the bottoms ($\frac{5}{15}$) is wrong, because the pieces are different sizes.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 = 4/10; 4/10 + 3/10 = 7/10. Other options: 1/10, 5/10, 5/15 are not equal to 7/10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
