INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4150488-c655-475e-9f4d-722470b6ea3a', 'NC26.5.ANR.5', 1, 'numeric', 'Add fractions with unlike denominators', 'A trail has two parts. The first part is $\frac{3}{10}$ mile long and the second part is $\frac{1}{5}$ mile long. How long is the whole trail, in miles?', '[]', '1/2', '3/10+1/5', 'Rename $\frac{1}{5}$ as $\frac{2}{10}$. Then $\frac{3}{10} + \frac{2}{10}$ = $\frac{5}{10}$, which is $\frac{1}{2}$ mile.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 = 2/10; 3/10 + 2/10 = 5/10 = 1/2 mile.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
