VALUES ('60ee944b-974e-4715-bede-66effeaa2d68', 'NC26.5.ANR.5', 1, 'numeric', 'Subtract fractions with unlike denominators', 'Subtract $\frac{1}{8}$ from $\frac{3}{4}$.', '[]', '5/8', '3/4-1/8', 'Rename $\frac{3}{4}$ as $\frac{6}{8}$. Then $\frac{6}{8} - \frac{1}{8}$ = $\frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 = 6/8; 6/8 - 1/8 = 5/8.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
