INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bff00857-1d3a-4365-b975-8d2a5eb3667f', 'NC26.5.ANR.5', 1, 'choice', 'Subtract fractions with unlike denominators', 'A jug has $\frac{2}{3}$ liter of juice. Sam drinks $\frac{1}{2}$ liter. How much juice is left, in liters?', '["$\\frac{7}{6}$","$\\frac{1}{1}$","$\\frac{1}{3}$","$\\frac{1}{6}$"]', '$\frac{1}{6}$', NULL, 'A common denominator is 6. $\frac{2}{3}$ = $\frac{4}{6}$ and $\frac{1}{2}$ = $\frac{3}{6}$. So $\frac{4}{6} - \frac{3}{6}$ = $\frac{1}{6}$ liter. The choice $\frac{7}{6}$ adds instead, and $\frac{1}{1}$ subtracts the tops and the bottoms.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 - 1/2 = 4/6 - 3/6 = 1/6 liter.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31a4ec0c-2ff5-4630-bacd-bd27e7e61f48', 'NC26.5.ANR.5', 1, 'numeric', 'Subtract fractions with unlike denominators', 'A rope is $\frac{7}{10}$ yard long. Ana cuts off $\frac{2}{5}$ yard. How long is the rope now, in yards?', '[]', '3/10', '7/10-2/5', 'Rename $\frac{2}{5}$ as $\frac{4}{10}$. Then $\frac{7}{10} - \frac{4}{10}$ = $\frac{3}{10}$ yard.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 = 4/10; 7/10 - 4/10 = 3/10 yard.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
