INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e0720f3-6d93-4e48-ba46-3aa8cc368df7', 'NC26.5.ANR.5', 1, 'numeric', 'Add and subtract mixed numbers with unlike denominators', 'Add the mixed numbers: $2\frac{1}{2} + 1\frac{1}{4}$.', '[]', '3 3/4', '2+1/2+1+1/4', 'Add the wholes: $2 + 1 = 3$. Add the fractions: $\frac{1}{2} + \frac{1}{4}$ = $\frac{2}{4} + \frac{1}{4}$ = $\frac{3}{4}$. The sum is $3\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3 3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 2+1 = 3; fractions 1/2+1/4 = 2/4+1/4 = 3/4. Sum 3 3/4.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
