INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22b43c97-40b7-4dc3-801c-6a95e147d154', 'NC26.5.ANR.5', 1, 'choice', 'Add and subtract mixed numbers with unlike denominators', 'Subtract the mixed numbers: $4\frac{3}{4} - 1\frac{1}{2}$.', '["$6\\frac{1}{4}$","$3\\frac{1}{2}$","$2\\frac{3}{4}$","$3\\frac{1}{4}$"]', '$3\frac{1}{4}$', NULL, 'Subtract the wholes: $4 - 1 = 3$. Subtract the fractions: $\frac{3}{4} - \frac{1}{2}$ = $\frac{3}{4} - \frac{2}{4}$ = $\frac{1}{4}$. The difference is $3\frac{1}{4}$. The choice $6\frac{1}{4}$ adds instead.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 4-1 = 3; fractions 3/4 - 1/2 = 3/4 - 2/4 = 1/4. Result 3 1/4.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
