INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('129578b2-19c1-44a9-9cee-6a10bbdc6d8e', 'NC26.5.ANR.5', 1, 'numeric', 'Add and subtract mixed numbers with unlike denominators', 'Rosa walked $1\frac{1}{3}$ miles on Saturday and $2\frac{1}{6}$ miles on Sunday. How many miles did she walk in all?', '[]', '3 1/2', '1+1/3+2+1/6', 'Add the wholes: $1 + 2 = 3$. Add the fractions: $\frac{1}{3} + \frac{1}{6}$ = $\frac{2}{6} + \frac{1}{6}$ = $\frac{3}{6}$ = $\frac{1}{2}$. The total is $3\frac{1}{2}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"3 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 1+2 = 3; fractions 1/3+1/6 = 2/6+1/6 = 3/6 = 1/2. Total 3 1/2 miles.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
