INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('629bd7e2-5a24-4bb5-b6c6-48aad135e239', 'NC26.5.ANR.5', 1, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Without finding the exact sum, which statement about $\frac{3}{8} + \frac{1}{2}$ is true?', '["It is exactly 1","It is more than 1 but less than 2","It is exactly 2","It is less than 1"]', 'It is less than 1', NULL, '$\frac{3}{8}$ is less than $\frac{1}{2}$, so the sum is less than $\frac{1}{2} + \frac{1}{2}$ = 1. (The exact sum is $\frac{7}{8}$.)', 'checked', '{"lint":[],"solve":{"answer":"It is less than 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 is less than 1/2, so 3/8 + 1/2 is less than 1/2 + 1/2 = 1. (Exact sum 7/8.)","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bbec31f-6326-4eb3-9745-2b6142b144b0', 'NC26.5.ANR.5', 1, 'numeric', 'Estimate and compare sums and differences using benchmark fractions', 'Mari estimates $\frac{7}{8} + \frac{1}{10}$ by rounding each fraction to the closest of 0, $\frac{1}{2}$ or 1. What is her estimate?', '[]', '1', '1+0', '$\frac{7}{8}$ is closest to 1, and $\frac{1}{10}$ is closest to 0. The estimate is $1 + 0 = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 is 1/8 from 1 and 3/8 from 1/2, so rounds to 1. 1/10 is 1/10 from 0 and 4/10 from 1/2, so rounds to 0. Estimate 1 + 0 = 1.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
