INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb400acc-6e5f-463c-b563-0cc8ee2f5fcf', 'NC26.5.ANR.5', 1, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Which is the best estimate of $\frac{9}{10} + \frac{11}{12}$?', '["2","1","3","$\\frac{1}{2}$"]', '2', '1+1', '$\frac{9}{10}$ is close to 1 and $\frac{11}{12}$ is close to 1, so the sum is close to $1 + 1 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/10 is close to 1 and 11/12 is close to 1, so the sum is about 2 (exact 109/60, about 1.82).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
