INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('edcc9ea1-f657-4f97-9b24-1a6e60d2a298', 'NC26.5.ANR.5', 1, 'choice', 'Scaling: how a product compares with the number multiplied', 'Without multiplying, which product is greater than 8?', '["$8 \\times \\frac{1}{2}$","$8 \\times 1$","$8 \\times \\frac{5}{4}$","$8 \\times \\frac{9}{10}$"]', '$8 \times \frac{5}{4}$', NULL, 'Multiplying by a number greater than 1 makes the product greater. $\frac{5}{4}$ is greater than 1, so $8 \times \frac{5}{4}$ is greater than 8. The others are 4, 8 and less than 8.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times \\frac{5}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying 8 by a factor greater than 1 gives more than 8. Only 5/4 > 1 (1/2 < 1, 1 = 1, 9/10 < 1).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc764632-b443-4f39-8f62-0e0a977dce83', 'NC26.5.ANR.5', 1, 'choice', 'Scaling: how a product compares with the number multiplied', 'Without multiplying, how does $\frac{2}{3} \times 5$ compare with 5?', '["It is less than 5","It is equal to 5","It is greater than 5","It is equal to $\\frac{2}{3}$"]', 'It is less than 5', NULL, '$\frac{2}{3}$ is less than 1, so taking $\frac{2}{3}$ of 5 gives less than 5. (The product is $3\frac{1}{3}$.)', 'checked', '{"lint":[],"solve":{"answer":"It is less than 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 is less than 1, so 2/3 × 5 is less than 5 (it is 10/3).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f532c5d-187d-4cc9-830c-3f52ed2d54f9', 'NC26.5.ANR.5', 1, 'numeric', 'Scaling: how a product compares with the number multiplied', 'A snail crawls 12 centimeters. A beetle crawls $\frac{1}{3}$ as far as the snail. How many centimeters does the beetle crawl?', '[]', '4', '12/3', '$\frac{1}{3}$ of 12 is $12 \div 3 = 4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 × 12 = 4 cm.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e87307b-9710-4add-b1bc-94add4359828', 'NC26.5.ANR.5', 1, 'numeric', 'Divide a unit fraction by a whole number', 'Divide $\frac{1}{2}$ by 3.', '[]', '1/6', '1/2/3', 'Split $\frac{1}{2}$ into 3 equal parts. Each part is $\frac{1}{6}$, since 6 of those parts make a whole. So $\frac{1}{2}$ $\div 3 = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 ÷ 3 = 1/2 × 1/3 = 1/6. Check: 3 × 1/6 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
