INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea4f0842-86af-4f2d-b247-08100ad8984c', 'NC26.5.ANR.5', 1, 'choice', 'Divide a unit fraction by a whole number', 'Half of a candy bar is cut into 2 equal pieces. What fraction of the whole bar is each piece?', '["$\\frac{1}{2}$","$\\frac{1}{3}$","$\\frac{1}{8}$","$\\frac{1}{4}$"]', '$\frac{1}{4}$', NULL, '$\frac{1}{2}$ $\div 2 = \frac{1}{4}$. Each piece is one fourth of the whole bar.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 ÷ 2 = 1/4 of the bar.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
