INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6fe5e77e-8953-4597-aef0-30a4294bee0c', 'NC26.5.ANR.5', 1, 'numeric', 'Divide a unit fraction by a whole number', 'Jo has $\frac{1}{4}$ of a pizza left. She splits it equally between 2 people. What fraction of the whole pizza does each person get?', '[]', '1/8', '1/4/2', '$\frac{1}{4}$ $\div 2 = \frac{1}{8}$. Cutting each fourth in half gives eighths.', 'checked', '{"lint":[],"solve":{"answer":"1/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 ÷ 2 = 1/8 of the pizza each.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
