INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('996ac266-28c9-4d18-84cc-6ee9cfa80069', 'NC26.5.ANR.5', 1, 'numeric', 'Divide a whole number by a unit fraction', 'Ali has 3 cups of rice. He measures it with a $\frac{1}{2}$-cup scoop. How many scoops does he need?', '[]', '6', '3/(1/2)', 'Each cup holds 2 half-cup scoops, so 3 cups hold $3 \times 2 = 6$ scoops. That is $3 \div \frac{1}{2} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 ÷ 1/2 = 6 scoops (2 per cup × 3 cups).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
