INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47f78da3-0617-4381-bb3a-33b1faf9c4b9', 'NC26.5.ANR.5', 1, 'choice', 'Divide a whole number by a unit fraction', 'How many fourths are in 2? Find $2 \div \frac{1}{4}$.', '["$\\frac{1}{2}$","6","8","4"]', '8', '2/(1/4)', 'Each whole has 4 fourths, so 2 wholes have $2 \times 4 = 8$ fourths. The choice $\frac{1}{2}$ multiplies $2 \times \frac{1}{4}$ instead.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each whole has 4 fourths, so 2 has 8: 2 ÷ 1/4 = 8.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
