VALUES ('540acabe-85e4-420b-a448-94cac1a286c7', 'NC26.5.ANR.5', 1, 'numeric', 'Divide a whole number by a unit fraction', '5 sandwiches are each cut into thirds. How many pieces are there?', '[]', '15', '5/(1/3)', 'Each sandwich makes 3 pieces, so 5 sandwiches make $5 \times 3 = 15$ pieces.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 ÷ 1/3 = 5 × 3 = 15 pieces.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
