VALUES ('cc6b9ec7-5756-486e-b6b4-70c540ede22d', 'NC26.5.ANR.5', 2, 'numeric', 'Multiply fractions', 'Find $\frac{2}{3} \times \frac{3}{4}$.', '[]', '1/2', '2/3*3/4', 'Multiply the numerators and the denominators: $\frac{2 \times 3}{3 \times 4} = \frac{6}{12} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 x 3/4 = 6/12 = 1/2.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
