INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7eaa047f-4abe-43a6-82ab-d603ab8096ef', 'NC26.5.ANR.5', 2, 'choice', 'Add fractions with unlike denominators', 'What is $\frac{2}{3} + \frac{1}{4}$?', '["11/12","3/7","3/12","5/12"]', '11/12', '2/3+1/4', 'Use a common denominator of 12: $\frac{8}{12} + \frac{3}{12} = \frac{11}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"11/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 8/12, 1/4 = 3/12; sum 11/12.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
