INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2915b4f5-9a8f-4adb-a777-a193eb9e9dc6', 'NC26.5.ANR.5', 2, 'choice', 'Scaling: multiplying by a fraction less than 1', 'Without finding the products, which expression is less than $\frac{5}{8}$?', '["$\\frac{5}{8} \\times \\frac{4}{3}$","$\\frac{5}{8} \\times \\frac{5}{5}$","$\\frac{5}{8} \\times \\frac{3}{4}$","$\\frac{5}{8} \\times 2$"]', '$\frac{5}{8} \times \frac{3}{4}$', NULL, 'Multiplying by a number less than 1 makes a number smaller. Only $\frac{3}{4}$ is less than 1. The factor $\frac{5}{5}$ equals 1 (no change), and $\frac{4}{3}$ and 2 are greater than 1 (larger).', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{8} \\times \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying by a fraction less than 1 gives a smaller product. 5/5 = 1 (equal), 2 and 4/3 are greater than 1, 3/4 < 1. So 5/8 x 3/4 < 5/8.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e657f54e-6909-4a3e-a023-1a344f242998', 'NC26.5.ANR.5', 2, 'choice', 'Add fractions with unlike denominators', 'Find the sum of $\frac{3}{4}$ and $\frac{1}{6}$.', '["$\\frac{11}{12}$","$\\frac{4}{10}$","$\\frac{10}{12}$","$\\frac{3}{24}$"]', '$\frac{11}{12}$', NULL, 'A common denominator is 12. $\frac{3}{4}$ = $\frac{9}{12}$ and $\frac{1}{6}$ = $\frac{2}{12}$. So $\frac{9}{12} + \frac{2}{12}$ = $\frac{11}{12}$. The choice $\frac{4}{10}$ adds tops and bottoms; $\frac{10}{12}$ forgets to rename $\frac{1}{6}$; $\frac{3}{24}$ multiplies.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{11}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 12: 3/4 = 9/12, 1/6 = 2/12; sum 11/12. 10/12 is not equal to 11/12.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66be6512-f669-42e9-a2e4-67488e0be5aa', 'NC26.5.ANR.5', 2, 'choice', 'Add fractions with unlike denominators', 'Luis walked $\frac{2}{3}$ mile to school and then $\frac{1}{5}$ mile to the library. How far did he walk in all, in miles?', '["$\\frac{3}{8}$","$\\frac{13}{15}$","$\\frac{3}{15}$","$\\frac{11}{15}$"]', '$\frac{13}{15}$', NULL, 'A common denominator is 15. $\frac{2}{3}$ = $\frac{10}{15}$ and $\frac{1}{5}$ = $\frac{3}{15}$. So $\frac{10}{15} + \frac{3}{15}$ = $\frac{13}{15}$ mile. The choice $\frac{3}{8}$ adds tops and bottoms, and $\frac{11}{15}$ forgets to rename $\frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{13}{15}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 15: 2/3 = 10/15, 1/5 = 3/15; sum 13/15.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b34d2131-cd31-45cc-ae6b-60926f12e458', 'NC26.5.ANR.5', 2, 'numeric', 'Add fractions with unlike denominators', 'In a bag of trail mix, $\frac{3}{10}$ of the weight is nuts and $\frac{2}{5}$ of the weight is raisins. What fraction of the weight is nuts and raisins together?', '[]', '7/10', '3/10+2/5', 'Rename $\frac{2}{5}$ as $\frac{4}{10}$. Then $\frac{3}{10} + \frac{4}{10}$ = $\frac{7}{10}$ of the weight.', 'checked', '{"lint":[],"solve":{"answer":"7/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 = 4/10; 3/10 + 4/10 = 7/10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0c20802-438b-4f23-9d2a-f1346dc18931', 'NC26.5.ANR.5', 2, 'choice', 'Subtract fractions with unlike denominators', 'Subtract $\frac{3}{8}$ from $\frac{5}{6}$.', '["$\\frac{2}{24}$","$\\frac{29}{24}$","$\\frac{11}{24}$","$\\frac{6}{24}$"]', '$\frac{11}{24}$', NULL, 'A common denominator is 24. $\frac{5}{6}$ = $\frac{20}{24}$ and $\frac{3}{8}$ = $\frac{9}{24}$. So $\frac{20}{24} - \frac{9}{24}$ = $\frac{11}{24}$. The choice $\frac{29}{24}$ adds instead.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{11}{24}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 24: 5/6 = 20/24, 3/8 = 9/24; 20/24 - 9/24 = 11/24.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14ad7c18-5971-4b5f-8253-2ddd10674c25', 'NC26.5.ANR.5', 2, 'choice', 'Subtract fractions with unlike denominators', 'Kim had $\frac{3}{4}$ of a tank of gas. After a trip she had $\frac{1}{5}$ of a tank left. What fraction of a tank did she use?', '["$\\frac{19}{20}$","$\\frac{11}{20}$","$\\frac{1}{2}$","$\\frac{4}{20}$"]', '$\frac{11}{20}$', NULL, 'A common denominator is 20. $\frac{3}{4}$ = $\frac{15}{20}$ and $\frac{1}{5}$ = $\frac{4}{20}$. She used $\frac{15}{20} - \frac{4}{20}$ = $\frac{11}{20}$ of a tank.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{11}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Used = 3/4 - 1/5 = 15/20 - 4/20 = 11/20.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97b677e9-3306-41c2-a63d-515cc17e5d80', 'NC26.5.ANR.5', 2, 'numeric', 'Subtract fractions with unlike denominators', 'A board is $\frac{11}{12}$ foot long. After a piece is cut off, $\frac{2}{3}$ foot is left. How long was the piece that was cut off, in feet?', '[]', '1/4', '11/12-2/3', 'Rename $\frac{2}{3}$ as $\frac{8}{12}$. The piece was $\frac{11}{12} - \frac{8}{12}$ = $\frac{3}{12}$, which is $\frac{1}{4}$ foot.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cut off = 11/12 - 2/3 = 11/12 - 8/12 = 3/12 = 1/4 foot.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a817df-5991-47a4-9fd7-51f7124d62d1', 'NC26.5.ANR.5', 2, 'choice', 'Add and subtract mixed numbers with unlike denominators', 'A baker used $3\frac{2}{3}$ cups of flour for bread and $2\frac{3}{4}$ cups of flour for rolls. How many cups of flour did the baker use in all?', '["$5\\frac{5}{7}$","$6\\frac{1}{12}$","$6\\frac{5}{12}$","$5\\frac{5}{12}$"]', '$6\frac{5}{12}$', NULL, 'Add the wholes: $3 + 2 = 5$. Add the fractions: $\frac{2}{3} + \frac{3}{4}$ = $\frac{8}{12} + \frac{9}{12}$ = $\frac{17}{12}$ = $1\frac{5}{12}$. Then $5 + 1$ and $\frac{5}{12}$ gives $6\frac{5}{12}$. The choice $5\frac{5}{12}$ forgets to carry the extra whole.', 'checked', '{"lint":[],"solve":{"answer":"$6\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 3+2 = 5; fractions 2/3+3/4 = 8/12+9/12 = 17/12 = 1 5/12. Total 6 5/12 cups.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74d9f20b-f3b2-4835-b469-2fa211ed9674', 'NC26.5.ANR.5', 2, 'choice', 'Add and subtract mixed numbers with unlike denominators', 'A board is $5\frac{3}{4}$ feet long. Maria cuts off $2\frac{1}{3}$ feet. How long is the board now, in feet?', '["$3\\frac{5}{12}$","$8\\frac{1}{12}$","$3\\frac{2}{3}$","$2\\frac{5}{12}$"]', '$3\frac{5}{12}$', NULL, 'Subtract the wholes: $5 - 2 = 3$. Subtract the fractions: $\frac{3}{4} - \frac{1}{3}$ = $\frac{9}{12} - \frac{4}{12}$ = $\frac{5}{12}$. The board is $3\frac{5}{12}$ feet long. The choice $8\frac{1}{12}$ adds instead.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 5-2 = 3; fractions 3/4 - 1/3 = 9/12 - 4/12 = 5/12. Result 3 5/12 feet.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7333a6a5-d4f0-4009-b1e4-b75396e093b5', 'NC26.5.ANR.5', 2, 'numeric', 'Add and subtract mixed numbers with unlike denominators', 'A pitcher holds $4\frac{5}{6}$ cups of lemonade. Sia pours out $1\frac{1}{2}$ cups. How many cups are left?', '[]', '3 1/3', '4+5/6-1-1/2', 'Subtract the wholes: $4 - 1 = 3$. Subtract the fractions: $\frac{5}{6} - \frac{1}{2}$ = $\frac{5}{6} - \frac{3}{6}$ = $\frac{2}{6}$ = $\frac{1}{3}$. $3\frac{1}{3}$ cups are left.', 'checked', '{"lint":[],"solve":{"answer":"3 1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wholes 4-1 = 3; fractions 5/6 - 1/2 = 5/6 - 3/6 = 2/6 = 1/3. Left 3 1/3 cups.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d0b7399-1dc9-4dfb-8335-cdf96182734f', 'NC26.5.ANR.5', 2, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Which of these sums is greater than 1?', '["$\\frac{1}{2} + \\frac{1}{3}$","$\\frac{3}{4} + \\frac{1}{6}$","$\\frac{2}{3} + \\frac{3}{8}$","$\\frac{1}{5} + \\frac{3}{4}$"]', '$\frac{2}{3} + \frac{3}{8}$', NULL, '$\frac{2}{3} + \frac{3}{8}$ = $\frac{16}{24} + \frac{9}{24}$ = $\frac{25}{24}$, which is more than 1. The other sums are $\frac{5}{6}$, $\frac{11}{12}$ and $\frac{19}{20}$, all less than 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3} + \\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3+3/8 = 16/24+9/24 = 25/24 > 1. 1/5+3/4 = 19/20. 3/4+1/6 = 11/12. 1/2+1/3 = 5/6. Only the first exceeds 1.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
