INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e707ff9e-8ff5-46a0-bb43-28c5b28fd4bf', 'NC26.5.ANR.5', 2, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Sam says $\frac{1}{2} + \frac{1}{3}$ is $\frac{2}{5}$ because $1 + 1 = 2$ and $2 + 3 = 5$. How can you tell without adding that he is wrong?', '["The sum must be a whole number","The sum must be more than $\\frac{1}{2}$, but $\\frac{2}{5}$ is less than $\\frac{1}{2}$","The sum must be exactly 1","The sum must be less than $\\frac{1}{3}$"]', 'The sum must be more than $\frac{1}{2}$, but $\frac{2}{5}$ is less than $\frac{1}{2}$', NULL, 'Adding $\frac{1}{3}$ to $\frac{1}{2}$ must make the amount bigger than $\frac{1}{2}$. But $\frac{2}{5}$ is smaller than $\frac{1}{2}$, so the answer cannot be right. (The sum is $\frac{5}{6}$.)', 'checked', '{"lint":[],"solve":{"answer":"The sum must be more than $\\frac{1}{2}$, but $\\frac{2}{5}$ is less than $\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 1/3 to 1/2 must give more than 1/2, but 2/5 is less than 1/2, so 2/5 cannot be right. (True sum 5/6.)","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4d92be8-97a3-464a-9089-d458f0df3c45', 'NC26.5.ANR.5', 2, 'numeric', 'Estimate and compare sums and differences using benchmark fractions', 'A recipe needs $\frac{7}{8}$ cup of flour and $\frac{4}{9}$ cup of oats. Round each amount to the closest of 0, $\frac{1}{2}$ or 1, and then add. What is the estimate, in cups?', '[]', '1 1/2', '1+1/2', '$\frac{7}{8}$ rounds to 1, and $\frac{4}{9}$ rounds to $\frac{1}{2}$. The estimate is $1 + \frac{1}{2} = \frac{3}{2}$, which is $1\frac{1}{2}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"1 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7/8 rounds to 1 (1/8 away). 4/9 is 1/18 from 1/2 and 4/9 from 0, so rounds to 1/2. Estimate 1 + 1/2 = 1 1/2 cups.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bef991ef-bd36-4c38-b77e-25150027887f', 'NC26.5.ANR.5', 2, 'numeric', 'Fractions as division', 'A ribbon 5 meters long is cut into 4 equal pieces. How long is each piece, in meters? Write your answer as a mixed number.', '[]', '1 1/4', '5/4', 'Each piece is $5 \div 4 = \frac{5}{4}$ meters, which is $1\frac{1}{4}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"1 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 ÷ 4 = 5/4 = 1 1/4 meters.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('637120a7-e6fb-486b-b0e7-1021506c0667', 'NC26.5.ANR.5', 2, 'choice', 'Fractions as division', 'Which is equal to $11 \div 4$?', '["$\\frac{4}{11}$","$2\\frac{3}{4}$","$2\\frac{3}{11}$","$2\\frac{1}{4}$"]', '$2\frac{3}{4}$', NULL, '$11 \div 4 = \frac{11}{4}$. Since $4 \times 2 = 8$, there are 2 wholes with 3 left over, and the 3 is split into fourths: $2\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 ÷ 4 = 2 remainder 3, so 2 3/4.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccbb93a0-01a1-4084-abf6-89538401330f', 'NC26.5.ANR.5', 2, 'numeric', 'Fractions as division', 'Ten people share 4 pizzas equally. What fraction of a pizza does each person get? Write it in simplest form.', '[]', '2/5', '4/10', 'Each person gets $4 \div 10 = \frac{4}{10}$ of a pizza, which is $\frac{2}{5}$ in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 ÷ 10 = 4/10 = 2/5 of a pizza.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2029d21-36e4-42db-ae82-4dc95e42c2ad', 'NC26.5.ANR.5', 2, 'choice', 'Multiply a whole number by a fraction', 'What is $\frac{3}{4}$ of 20?', '["5","60","15","17"]', '15', '3/4*20', '$\frac{1}{4}$ of 20 is $20 \div 4 = 5$, so $\frac{3}{4}$ of 20 is $3 \times 5 = 15$. The choice 5 is only one fourth, and 60 forgets to divide by 4.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 ÷ 4 = 5; 5 × 3 = 15.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('969187f0-8268-4b7e-b4c5-830274d9db67', 'NC26.5.ANR.5', 2, 'choice', 'Multiply a whole number by a fraction', 'A runner jogs $\frac{3}{8}$ mile each day. How far does she jog in 6 days, in miles?', '["$6\\frac{3}{8}$","$\\frac{1}{16}$","$1\\frac{1}{8}$","$2\\frac{1}{4}$"]', '$2\frac{1}{4}$', NULL, '$6 \times \frac{3}{8} = \frac{18}{8}$. Since $18 \div 8$ is 2 with 2 left over, $\frac{18}{8}$ = $2\frac{2}{8}$ = $2\frac{1}{4}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 × 3/8 = 18/8 = 9/4 = 2 1/4 miles.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a07cbd1-635e-4ca7-af91-e2623e8fc447', 'NC26.5.ANR.5', 2, 'choice', 'Multiply a whole number by a fraction', 'Which expression has the same value as $5 \times \frac{2}{3}$?', '["$\\frac{2}{5 \\times 3}$","$\\frac{5 \\times 2}{5 \\times 3}$","$\\frac{5 \\times 2}{3}$","$\\frac{5 + 2}{3}$"]', '$\frac{5 \times 2}{3}$', NULL, 'Multiplying a whole number by a fraction multiplies the top number: $5 \times \frac{2}{3} = \frac{5 \times 2}{3} = \frac{10}{3}$. The other choices have the values $\frac{2}{15}$, $\frac{2}{3}$ and $\frac{7}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5 \\times 2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 × 2/3 = (5 × 2)/3 = 10/3. (5×2)/(5×3) = 2/3, (5+2)/3 = 7/3, 2/(5×3) = 2/15 are not equal.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdce0c70-0352-4d45-a06d-68f0eeb1d593', 'NC26.5.ANR.5', 2, 'choice', 'Multiply a fraction by a fraction', 'Multiply the fractions: $\frac{3}{4} \times \frac{2}{9}$.', '["$\\frac{1}{6}$","$\\frac{5}{13}$","$\\frac{27}{8}$","$\\frac{6}{13}$"]', '$\frac{1}{6}$', NULL, '$\frac{3}{4} \times \frac{2}{9}$ = $\frac{6}{36}$, which is $\frac{1}{6}$ in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 × 2/9 = 6/36 = 1/6.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
