INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a57f33f-bbd1-4ae5-8add-c7b797ba4a9b', 'NC26.5.ANR.5', 2, 'choice', 'Multiply a fraction by a fraction', 'A rectangle is $\frac{2}{3}$ meter long and $\frac{3}{5}$ meter wide. What is its area, in square meters?', '["$\\frac{5}{8}$","$\\frac{6}{8}$","$\\frac{10}{9}$","$\\frac{2}{5}$"]', '$\frac{2}{5}$', NULL, 'Area is length times width: $\frac{2}{3} \times \frac{3}{5}$ = $\frac{6}{15}$ = $\frac{2}{5}$ square meter.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 2/3 × 3/5 = 6/15 = 2/5 square meter.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6673d3a4-40e3-4a42-9624-a776b17d084b', 'NC26.5.ANR.5', 2, 'choice', 'Scaling: how a product compares with the number multiplied', 'Maya says that $12 \times \frac{5}{3}$ is greater than 12. Is she right? Why?', '["Yes, because multiplying always makes a number greater","No, because multiplying by a fraction always makes a number smaller","Yes, because $\\frac{5}{3}$ is greater than 1","No, because $\\frac{5}{3}$ has a bottom number"]', 'Yes, because $\frac{5}{3}$ is greater than 1', NULL, 'Multiplying by a number greater than 1 makes the product greater than the starting number. $\frac{5}{3}$ is greater than 1, so the product is greater than 12 (it is 20). Multiplying by a number less than 1 makes it smaller, but that is not what happens here.', 'checked', '{"lint":[],"solve":{"answer":"Yes, because $\\frac{5}{3}$ is greater than 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/3 > 1, so 12 × 5/3 > 12 (it is 20). She is right.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46613f21-db70-4c16-90b7-c3930e0cb116', 'NC26.5.ANR.5', 2, 'choice', 'Scaling: how a product compares with the number multiplied', 'Without calculating, which list shows $\frac{2}{3} \times 10$, $1 \times 10$ and $\frac{5}{4} \times 10$ from least to greatest?', '["$\\frac{5}{4} \\times 10, \\ 1 \\times 10, \\ \\frac{2}{3} \\times 10$","$1 \\times 10, \\ \\frac{2}{3} \\times 10, \\ \\frac{5}{4} \\times 10$","$\\frac{2}{3} \\times 10, \\ \\frac{5}{4} \\times 10, \\ 1 \\times 10$","$\\frac{2}{3} \\times 10, \\ 1 \\times 10, \\ \\frac{5}{4} \\times 10$"]', '$\frac{2}{3} \times 10, \ 1 \times 10, \ \frac{5}{4} \times 10$', NULL, 'Compare the numbers multiplying 10: $\frac{2}{3}$ is less than 1, and $\frac{5}{4}$ is greater than 1. So the products go from smaller than 10, to exactly 10, to larger than 10.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3} \\times 10, \\ 1 \\times 10, \\ \\frac{5}{4} \\times 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 < 1 < 5/4, so 2/3 × 10 < 1 × 10 < 5/4 × 10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6c8b9ce-1e4d-4751-9116-2a180b872c50', 'NC26.5.ANR.5', 2, 'numeric', 'Scaling: how a product compares with the number multiplied', 'Last year a plant was 9 inches tall. Now it is $\frac{4}{3}$ times as tall. How tall is the plant now, in inches?', '[]', '12', '9*4/3', '$\frac{4}{3}$ of 9 is $9 \div 3 = 3$, and $4 \times 3 = 12$ inches. The plant is taller than before because $\frac{4}{3}$ is greater than 1.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/3 × 9 = 36/3 = 12 inches.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bb90de7-bc27-46f8-a860-7341a734c897', 'NC26.5.ANR.5', 2, 'choice', 'Divide a unit fraction by a whole number', 'What is $\frac{1}{5}$ $\div$ 4?', '["$\\frac{1}{20}$","$\\frac{4}{5}$","$\\frac{5}{4}$","$\\frac{1}{9}$"]', '$\frac{1}{20}$', NULL, '$\frac{1}{5}$ $\div 4 = \frac{1}{5} \times \frac{1}{4} = \frac{1}{20}$. Splitting one fifth into 4 equal parts makes twentieths.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 ÷ 4 = 1/20. Check: 4 × 1/20 = 4/20 = 1/5.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b768e2c-e45d-47de-b121-629f4e892ca1', 'NC26.5.ANR.5', 2, 'choice', 'Divide a unit fraction by a whole number', 'Which multiplication gives the same result as $\frac{1}{6}$ $\div$ 3?', '["$\\frac{1}{6} \\times 3$","$\\frac{1}{3} \\times 6$","$\\frac{1}{6} \\times \\frac{1}{3}$","$6 \\times 3$"]', '$\frac{1}{6} \times \frac{1}{3}$', NULL, 'Dividing by 3 is the same as taking one third. So $\frac{1}{6}$ $\div 3 = \frac{1}{6} \times \frac{1}{3} = \frac{1}{18}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6} \\times \\frac{1}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dividing by 3 is the same as multiplying by 1/3: 1/6 ÷ 3 = 1/6 × 1/3 = 1/18.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a44e90e3-9824-4345-85f4-943fcc8f1c46', 'NC26.5.ANR.5', 2, 'numeric', 'Divide a unit fraction by a whole number', 'A strip of ribbon is $\frac{1}{3}$ yard long. It is cut into 5 equal pieces. How long is each piece, in yards?', '[]', '1/15', '1/3/5', '$\frac{1}{3}$ $\div 5 = \frac{1}{15}$ yard. Each third is cut into 5 smaller parts, and 15 of those parts make a whole yard.', 'checked', '{"lint":[],"solve":{"answer":"1/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 ÷ 5 = 1/15 yard.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
