INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c6bc5d2-b311-4cf8-893d-109a81dff0a0', 'NC26.5.ANR.5', 2, 'choice', 'Divide a whole number by a unit fraction', 'Which expression shows the number of $\frac{1}{6}$-pound bags that can be filled from 5 pounds of rice?', '["$\\frac{1}{6} \\div 5$","$5 \\times \\frac{1}{6}$","$5 - \\frac{1}{6}$","$5 \\div \\frac{1}{6}$"]', '$5 \div \frac{1}{6}$', NULL, 'We want to know how many $\frac{1}{6}$s fit into 5, which is $5 \div \frac{1}{6}$. (It equals 30 bags.)', 'checked', '{"lint":[],"solve":{"answer":"$5 \\div \\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number of 1/6-pound bags in 5 pounds = 5 ÷ 1/6 (= 30).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
