INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e965c2b-3fb8-494c-a4a8-c69fae4a4ebf', 'NC26.5.ANR.5', 3, 'numeric', 'Add fractions with unlike denominators', 'Add $\frac{5}{6}$ and $\frac{3}{8}$. Write the sum as a mixed number.', '[]', '1 5/24', '5/6+3/8', 'A common denominator is 24. $\frac{5}{6}$ = $\frac{20}{24}$ and $\frac{3}{8}$ = $\frac{9}{24}$. The sum is $\frac{29}{24}$, which is $1\frac{5}{24}$.', 'checked', '{"lint":[],"solve":{"answer":"1 5/24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 24: 5/6 = 20/24, 3/8 = 9/24; sum 29/24 = 1 5/24.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b17b16b2-d22f-4471-9107-edfd65812ad0', 'NC26.5.ANR.5', 3, 'choice', 'Add fractions with unlike denominators', 'Which sum is equal to $\frac{7}{12}$?', '["$\\frac{1}{4} + \\frac{1}{6}$","$\\frac{1}{2} + \\frac{1}{5}$","$\\frac{1}{3} + \\frac{1}{8}$","$\\frac{1}{3} + \\frac{1}{4}$"]', '$\frac{1}{3} + \frac{1}{4}$', NULL, '$\frac{1}{3} + \frac{1}{4}$ = $\frac{4}{12} + \frac{3}{12}$ = $\frac{7}{12}$. The others are $\frac{5}{12}$, $\frac{7}{10}$ and $\frac{11}{24}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3} + \\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4+1/6 = 3/12+2/12 = 5/12. 1/2+1/5 = 7/10. 1/3+1/4 = 4/12+3/12 = 7/12. 1/3+1/8 = 8/24+3/24 = 11/24. Only 1/3+1/4.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f515015e-9932-47db-a4d8-8391de2acf0d', 'NC26.5.ANR.5', 3, 'numeric', 'Add fractions with unlike denominators', 'Priya spends $\frac{1}{2}$ hour on math, $\frac{1}{3}$ hour on reading and $\frac{1}{4}$ hour on art. How many hours is that in all? Write your answer as a mixed number.', '[]', '1 1/12', '1/2+1/3+1/4', 'A common denominator is 12: $\frac{6}{12} + \frac{4}{12} + \frac{3}{12} = \frac{13}{12}$, which is $1\frac{1}{12}$ hours.', 'checked', '{"lint":[],"solve":{"answer":"1 1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 12: 6/12 + 4/12 + 3/12 = 13/12 = 1 1/12 hours.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9e84ece-a5b9-4acf-bbf3-eddfced49d72', 'NC26.5.ANR.5', 3, 'numeric', 'Subtract fractions with unlike denominators', 'Work out $\frac{7}{9} - \frac{1}{6}$.', '[]', '11/18', '7/9-1/6', 'A common denominator is 18. $\frac{7}{9}$ = $\frac{14}{18}$ and $\frac{1}{6}$ = $\frac{3}{18}$. So $\frac{14}{18} - \frac{3}{18}$ = $\frac{11}{18}$.', 'checked', '{"lint":[],"solve":{"answer":"11/18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 18: 7/9 = 14/18, 1/6 = 3/18; 14/18 - 3/18 = 11/18.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0423f4a5-216e-4f2e-925e-cddcfc7e8f47', 'NC26.5.ANR.5', 3, 'choice', 'Subtract fractions with unlike denominators', 'Which difference is equal to $\frac{1}{12}$?', '["$\\frac{1}{3} - \\frac{1}{4}$","$\\frac{1}{2} - \\frac{1}{3}$","$\\frac{2}{3} - \\frac{1}{4}$","$\\frac{3}{4} - \\frac{1}{6}$"]', '$\frac{1}{3} - \frac{1}{4}$', NULL, '$\frac{1}{3} - \frac{1}{4}$ = $\frac{4}{12} - \frac{3}{12}$ = $\frac{1}{12}$. The others are $\frac{1}{6}$, $\frac{5}{12}$ and $\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{3} - \\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2-1/3 = 1/6. 3/4-1/6 = 9/12-2/12 = 7/12. 1/3-1/4 = 4/12-3/12 = 1/12. 2/3-1/4 = 8/12-3/12 = 5/12. Only 1/3-1/4.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd6121bb-2df5-46d7-8131-adf806f3357a', 'NC26.5.ANR.5', 3, 'numeric', 'Subtract fractions with unlike denominators', 'Noor baked one whole pan of brownies. She ate $\frac{1}{4}$ of the pan and gave $\frac{1}{3}$ of the pan to a neighbor. What fraction of the pan is left?', '[]', '5/12', '1-1/4-1/3', 'The whole pan is $\frac{12}{12}$. She used $\frac{3}{12} + \frac{4}{12}$ = $\frac{7}{12}$. What is left is $\frac{12}{12} - \frac{7}{12}$ = $\frac{5}{12}$ of the pan.', 'checked', '{"lint":[],"solve":{"answer":"5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eaten + given = 1/4 + 1/3 = 3/12 + 4/12 = 7/12. Left = 1 - 7/12 = 5/12.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('218ba23e-fd46-4dbf-a6aa-b2c84766aa7b', 'NC26.5.ANR.5', 3, 'numeric', 'Add and subtract mixed numbers with unlike denominators', 'Work out $5\frac{1}{4} - 2\frac{2}{3}$. Write the answer as a mixed number.', '[]', '2 7/12', '5+1/4-2-2/3', '$\frac{1}{4}$ is less than $\frac{2}{3}$, so regroup. $5\frac{1}{4}$ = $5\frac{3}{12}$ = $4\frac{15}{12}$, and $2\frac{2}{3}$ = $2\frac{8}{12}$. Now $4 - 2 = 2$ and $\frac{15}{12} - \frac{8}{12}$ = $\frac{7}{12}$. The difference is $2\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"2 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/4 = 21/4 = 63/12; 2 2/3 = 8/3 = 32/12. 63/12 - 32/12 = 31/12 = 2 7/12. (Check: regroup 5 3/12 = 4 15/12; 4 15/12 - 2 8/12 = 2 7/12.)","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06fc8e6b-a346-4d30-868a-642c4b272878', 'NC26.5.ANR.5', 3, 'choice', 'Add and subtract mixed numbers with unlike denominators', 'Tom added $2\frac{3}{4} + 1\frac{5}{6}$ and got $3\frac{8}{10}$. What mistake did he make?', '["He forgot to add the whole numbers","He added the tops of the fractions and also added the bottoms","He added the whole numbers incorrectly","He used 12 as the common denominator but added the tops incorrectly"]', 'He added the tops of the fractions and also added the bottoms', NULL, 'The whole numbers give $2 + 1 = 3$, which is correct. The fraction part $\frac{8}{10}$ came from $3 + 5 = 8$ on top and $4 + 6 = 10$ on the bottom. That is wrong: the fractions need a common denominator first. The right answer is $\frac{9}{12} + \frac{10}{12}$ = $\frac{19}{12}$, so the sum is $4\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"He added the tops of the fractions and also added the bottoms","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tom''s answer 3 8/10: wholes 2+1 = 3 (correct), 3+5 = 8 numerators, 4+6 = 10 denominators. He added numerators and denominators. Correct sum is 3 + 9/12 + 10/12 = 4 7/12. Option about using 12 is wrong since his denominator is 10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d9c8e26-3154-4974-97f1-5c35aece1893', 'NC26.5.ANR.5', 3, 'numeric', 'Add and subtract mixed numbers with unlike denominators', 'A hiker walks $3\frac{1}{2}$ miles, rests, and then walks $2\frac{3}{4}$ miles more. The whole trail is $8\frac{1}{3}$ miles long. How many miles of the trail are left?', '[]', '2 1/12', '8+1/3-(3+1/2+2+3/4)', 'The hiker has walked $3\frac{1}{2} + 2\frac{3}{4}$ = $5\frac{5}{4}$ = $6\frac{1}{4}$ miles. Left: $8\frac{1}{3} - 6\frac{1}{4}$ = $8\frac{4}{12} - 6\frac{3}{12}$ = $2\frac{1}{12}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"2 1/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walked 3 1/2 + 2 3/4 = 5 + 2/4 + 3/4 = 6 1/4. Left 8 1/3 - 6 1/4 = 2 + 4/12 - 3/12 = 2 1/12 miles.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27525b71-c71f-494b-824d-ad100ba16fb8', 'NC26.5.ANR.5', 3, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Which fraction can be added to $\frac{5}{8}$ to make a sum greater than 1?', '["$\\frac{1}{4}$","$\\frac{1}{3}$","$\\frac{3}{8}$","$\\frac{5}{12}$"]', '$\frac{5}{12}$', NULL, '$\frac{5}{8} + \frac{5}{12}$ = $\frac{15}{24} + \frac{10}{24}$ = $\frac{25}{24}$, which is more than 1. The sums with $\frac{1}{4}$ and $\frac{1}{3}$ are $\frac{7}{8}$ and $\frac{23}{24}$, less than 1. The sum with $\frac{3}{8}$ is exactly 1.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need an addend greater than 1 - 5/8 = 3/8 = 9/24. 1/3 = 8/24 (too small), 5/12 = 10/24 (works), 1/4 = 6/24 (too small), 3/8 gives exactly 1 (not greater).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('288a1d11-2e2f-4c6d-9adf-a8b5377f5cf9', 'NC26.5.ANR.5', 3, 'numeric', 'Estimate and compare sums and differences using benchmark fractions', 'How much more than 1 is the sum of $\frac{5}{6}$ and $\frac{3}{4}$?', '[]', '7/12', '5/6+3/4-1', '$\frac{5}{6} + \frac{3}{4}$ = $\frac{10}{12} + \frac{9}{12}$ = $\frac{19}{12}$. That is $\frac{19}{12} - \frac{12}{12}$ = $\frac{7}{12}$ more than 1.', 'checked', '{"lint":[],"solve":{"answer":"7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 + 3/4 = 10/12 + 9/12 = 19/12. 19/12 - 1 = 7/12.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e188470b-b39a-4425-88a2-ce762ddd3877', 'NC26.5.ANR.5', 3, 'choice', 'Estimate and compare sums and differences using benchmark fractions', 'Which is the best reason that $\frac{3}{8} + \frac{4}{9}$ is less than 1?', '["Each fraction is less than $\\frac{1}{2}$, and two halves make 1","Each fraction has a denominator that is less than 10","Fractions with different denominators always add to less than 1","Each fraction is more than $\\frac{1}{4}$, so the sum is less than 1"]', 'Each fraction is less than $\frac{1}{2}$, and two halves make 1', NULL, '$\frac{3}{8}$ is less than $\frac{1}{2}$ (because 3 is less than half of 8) and $\frac{4}{9}$ is less than $\frac{1}{2}$ (because 4 is less than half of 9). So the sum is less than $\frac{1}{2} + \frac{1}{2}$ = 1.', 'checked', '{"lint":[],"solve":{"answer":"Each fraction is less than $\\frac{1}{2}$, and two halves make 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 < 1/2 and 4/9 < 1/2 (4/9 < 4.5/9), so the sum is less than 1/2 + 1/2 = 1. Other options are invalid reasoning.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e86bbd0-318a-4ac7-86eb-7cc0a79a3861', 'NC26.5.ANR.5', 3, 'choice', 'Fractions as division', 'A group shared some pizzas equally. Each person got $\frac{2}{3}$ of a pizza. Which could be the group?', '["3 people sharing 2 pizzas","2 people sharing 3 pizzas","5 people sharing 2 pizzas","3 people sharing 5 pizzas"]', '3 people sharing 2 pizzas', NULL, 'Each share is the number of pizzas divided by the number of people. 2 pizzas shared by 3 people gives $2 \div 3 = \frac{2}{3}$. The others give $\frac{3}{2}$, $\frac{2}{5}$ and $\frac{5}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"3 people sharing 2 pizzas","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each share = pizzas ÷ people. 2 ÷ 3 = 2/3 (match). 5 ÷ 3 = 5/3, 3 ÷ 2 = 3/2, 2 ÷ 5 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('891a063d-8ca3-4f15-8618-a1143901a3ce', 'NC26.5.ANR.5', 3, 'choice', 'Fractions as division', 'A rope 13 feet long is cut into 5 equal pieces. How long is each piece, in feet?', '["$2\\frac{3}{13}$","$\\frac{5}{13}$","$2\\frac{2}{5}$","$2\\frac{3}{5}$"]', '$2\frac{3}{5}$', NULL, 'Each piece is $13 \div 5 = \frac{13}{5}$ feet, which is $2\frac{3}{5}$ feet. (5 goes into 13 two times with 3 left over, and the 3 is split into fifths.)', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{3}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"13 ÷ 5 = 2 remainder 3 = 2 3/5 feet.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('387337ca-3ef3-4222-bd46-9c234512ea02', 'NC26.5.ANR.5', 3, 'numeric', 'Fractions as division', '10 pounds of flour are shared equally among 4 bags. Then the flour in one bag is shared equally among 5 bowls. How many pounds of flour are in each bowl?', '[]', '1/2', '10/4/5', 'Each bag holds $10 \div 4 = \frac{10}{4}$ pounds. Sharing that among 5 bowls gives $\frac{10}{4} \div 5 = \frac{10}{20}$, which is $\frac{1}{2}$ pound in each bowl.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each bag: 10 ÷ 4 = 2 1/2 pounds. Each bowl: 2 1/2 ÷ 5 = 5/2 ÷ 5 = 1/2 pound. (Equivalently 10 pounds into 20 bowls = 1/2.)","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71986a76-2efe-4c52-b65d-e2760086678b', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a whole number by a fraction', 'One batch of dough needs $\frac{2}{3}$ cup of flour. How many cups of flour do 7 batches need? Write your answer as a mixed number.', '[]', '4 2/3', '7*2/3', '$7 \times \frac{2}{3} = \frac{14}{3}$. Since $14 \div 3$ is 4 with 2 left over, the answer is $4\frac{2}{3}$ cups.', 'checked', '{"lint":[],"solve":{"answer":"4 2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 × 2/3 = 14/3 = 4 2/3 cups.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a57da626-fbd5-499f-99a5-8c49282519c7', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a whole number by a fraction', 'A box holds 30 pencils. $\frac{2}{5}$ of the pencils are red and the rest are blue. How many pencils are blue?', '[]', '18', '30-2/5*30', 'Red pencils: $\frac{2}{5}$ of 30 is $2 \times (30 \div 5) = 2 \times 6 = 12$. Blue pencils: $30 - 12 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red = 2/5 × 30 = 12. Blue = 30 - 12 = 18 (or 3/5 × 30 = 18).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0286ec1f-4f70-47ce-88e9-1559358f3325', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a whole number by a fraction', 'Mia multiplied a whole number by $\frac{3}{4}$ and got 18. What whole number did she multiply?', '[]', '24', '18/(3/4)', '18 is 3 fourths of the number, so one fourth is $18 \div 3 = 6$. The whole number is 4 fourths: $4 \times 6 = 24$. Check: $\frac{3}{4}$ of 24 is 18.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n × 3/4 = 18, so 1/4 of n = 6 and n = 24. Check: 24 × 3/4 = 18.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0092327f-3e47-41e9-aa02-fce37b622051', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a fraction by a fraction', 'Multiply $\frac{5}{8} \times \frac{12}{25}$ and write the product in simplest form.', '[]', '3/10', '5/8*12/25', '$\frac{5}{8} \times \frac{12}{25}$ = $\frac{60}{200}$. Divide the top and bottom by 20 to get $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 × 12/25 = 60/200 = 3/10.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a848670-a6a0-4b96-847a-439a19f43daa', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a fraction by a fraction', 'A tank is $\frac{3}{4}$ full of water. Pablo uses $\frac{2}{3}$ of the water in the tank to wash a car. What fraction of the whole tank is full now?', '[]', '1/4', '3/4-2/3*3/4', 'Pablo uses $\frac{2}{3}$ of $\frac{3}{4}$, which is $\frac{6}{12}$ = $\frac{1}{2}$ of the tank. What is left is $\frac{3}{4} - \frac{1}{2}$ = $\frac{3}{4} - \frac{2}{4}$ = $\frac{1}{4}$ of the tank.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Water used = 2/3 × 3/4 = 1/2 tank. Left = 3/4 - 1/2 = 1/4 tank (or 1/3 of 3/4 = 1/4).","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('115ed0f2-7bd2-4f5a-856d-d4c1386d4ccb', 'NC26.5.ANR.5', 3, 'numeric', 'Multiply a fraction by a fraction', '$\frac{2}{3} \times \frac{n}{5} = \frac{4}{15}$. What whole number is n?', '[]', '2', '4/2', 'The product''s top is $2 \times n$, and it must equal 4, so $n = 2$. Check: $\frac{2}{3} \times \frac{2}{5}$ = $\frac{4}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 × n/5 = 2n/15 = 4/15, so 2n = 4 and n = 2.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
