INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('edee846a-7397-4603-8f22-343d266fcdc0', 'NC26.5.ANR.5', 3, 'numeric', 'Scaling: how a product compares with the number multiplied', 'A model of a bridge is $\frac{3}{20}$ as long as the real bridge. The real bridge is 200 meters long. How long is the model, in meters?', '[]', '30', '3/20*200', '$\frac{1}{20}$ of 200 is $200 \div 20 = 10$, so $\frac{3}{20}$ of 200 is $3 \times 10 = 30$ meters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/20 × 200 = 600/20 = 30 meters.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
