INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b10d8fc-f468-420c-a901-450a9bffca0f', 'NC26.5.ANR.5', 3, 'choice', 'Divide a unit fraction by a whole number', 'Which story matches $\frac{1}{3}$ $\div$ 4?', '["How many one thirds are in 4 pies","4 children share one third of a pie equally","4 pies are each cut into thirds and 1 piece is taken","A pie is cut into 4 pieces and 3 pieces are eaten"]', '4 children share one third of a pie equally', NULL, '$\frac{1}{3}$ $\div 4$ means splitting $\frac{1}{3}$ into 4 equal parts, as when 4 children share $\frac{1}{3}$ of a pie. Each child gets $\frac{1}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"4 children share one third of a pie equally","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 ÷ 4 means one third split into 4 equal shares: 4 children share one third of a pie. Others describe 4 × 1/3 pieces, 3/4 eaten, or 4 ÷ 1/3.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
