INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98cd494c-0807-4a47-bc6d-db7d77747bf6', 'NC26.5.ANR.5', 3, 'numeric', 'Divide a unit fraction by a whole number', '5 friends each get $\frac{1}{30}$ of a cake. What fraction of the cake did they share in all?', '[]', '1/6', '1/30*5', 'Each friend gets one thirtieth, and there are 5 friends: $5 \times \frac{1}{30} = \frac{5}{30} = \frac{1}{6}$ of the cake. Check: $\frac{1}{6}$ $\div 5 = \frac{1}{30}$.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 × 1/30 = 5/30 = 1/6 of the cake.","run_id":"claude-code","at":"2026-10-17T20:08:42.893Z"}}', 'ai', NULL, NULL)
