INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2b570f0-d678-406c-8f64-271501a69511', 'NC26.5.ANR.6', 1, 'choice', 'Find the rule of a pattern from its terms', 'Which rule makes the pattern 2, 6, 18, 54, ...?', '["Add 4","Multiply by 3","Add 16","Multiply by 2"]', 'Multiply by 3', NULL, '$2 \times 3 = 6$, $6 \times 3 = 18$, $18 \times 3 = 54$. The rule is "multiply by 3". Adding the same number does not work because the gaps (4, 12, 36) keep changing.', 'checked', '{"lint":[],"solve":{"answer":"Multiply by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 3 = 6, 6 x 3 = 18, 18 x 3 = 54. Multiply by 3. (Add 4 fails at 6 to 18; add 16 fails at 2 to 6.)","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
