INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b3a891-774f-40a1-8983-7681dcf2fe22', 'NC26.5.ANR.6', 1, 'numeric', 'Use the relationship between two patterns to find a term', 'Pattern A is 1, 2, 3, 4, ... Pattern B is 3, 6, 9, 12, ... Each number in B is 3 times the matching number in A. The 7th number in A is 7. What is the 7th number in B?', '[]', '21', '7*3', 'The 7th number in B is 3 times the 7th number in A: $7 \times 3 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7th in B = 3 x 7 = 21.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
