INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('751d2bf5-2c3d-4d2d-b8df-1de766643297', 'NC26.5.ANR.6', 2, 'choice', 'Generate a multiplying pattern from a rule', 'In a pattern, each number is 5 times the number before it. The first number is 2. Which list shows the first four numbers?', '["2, 10, 50, 250","2, 7, 12, 17","2, 10, 18, 26","5, 25, 125, 625"]', '2, 10, 50, 250', NULL, 'Multiply by 5 each time, starting at 2: 2, 10, 50, 250. The list (2, 7, 12, 17) adds 5 instead; the list (2, 10, 18, 26) adds 8; and the list (5, 25, 125, 625) starts at 5 instead of 2.', 'checked', '{"lint":[],"solve":{"answer":"2, 10, 50, 250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 2x5 = 10, 10x5 = 50, 50x5 = 250.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0475fc57-55c1-46bd-a93e-f61f5f534a36', 'NC26.5.ANR.6', 2, 'choice', 'Generate a multiplying pattern from a rule', 'Each number in a pattern is 10 times the number before it, and the first number is 1. What is the 6th number in the pattern?', '["$10{,}000$","$1{,}000{,}000$","$60$","$100{,}000$"]', '$100{,}000$', NULL, 'The pattern is 1, 10, 100, $1{,}000$, $10{,}000$, $100{,}000$. The 6th number is $100{,}000$ (one followed by five zeros). The choice $10{,}000$ is the 5th number and $60$ comes from adding 10 each time.', 'checked', '{"lint":[],"solve":{"answer":"$100{,}000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1, 10, 100, 1,000, 10,000, 100,000. The 6th number is 100,000.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb1d78ea-7b32-41ae-ade4-cb8132869044', 'NC26.5.ANR.6', 2, 'choice', 'Find a later term of an adding pattern', 'Theo reads 12 pages on the first night. Each night he reads 3 more pages than the night before. How many pages does he read on night 8?', '["33","36","30","96"]', '33', '12+7*3', 'Night 8 is 7 nights after night 1, so he reads $7 \times 3 = 21$ more pages than on night 1: $12 + 21 = 33$. The choice 36 counts 8 nights of extra pages, 30 is night 7, and 96 is $8 \times 12$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Night n: 12 + 3(n - 1). Night 8: 12 + 21 = 33. (12, 15, 18, 21, 24, 27, 30, 33.)","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75f67167-2628-4896-9155-934db37a25c8', 'NC26.5.ANR.6', 2, 'choice', 'Find a later term of an adding pattern', 'The top of the 1st step of a staircase is 9 inches above the floor. Each step after that is 6 inches higher than the step before it. How many inches above the floor is the top of the 10th step?', '["69","63","60","57"]', '63', '9+9*6', 'Going from the 1st step to the 10th takes 9 steps up of 6 inches, which adds $9 \times 6 = 54$ inches. So the 10th step is $9 + 54 = 63$ inches above the floor. The choice 69 uses 10 steps up, and 57 is the height of the 9th step.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Step n: 9 + 6(n - 1). Step 10: 9 + 54 = 63 inches.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97ad15da-ffdb-4cd5-b484-6ad50dbd5630', 'NC26.5.ANR.6', 2, 'numeric', 'Find a later term of an adding pattern', 'Kofi has 20 dollars in his jar at the end of week 1. Each week after that he puts in 15 more dollars. How many dollars are in the jar at the end of week 12?', '[]', '185', '20+11*15', 'Week 12 is 11 weeks after week 1, so he has added $11 \times 15 = 165$ dollars, and $20 + 165 = 185$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"185","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Week n: 20 + 15(n - 1). Week 12: 20 + 15 x 11 = 20 + 165 = 185 dollars.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1a1ca93-69da-449f-84a5-d639181f26bd', 'NC26.5.ANR.6', 2, 'numeric', 'Decide whether a number is in a pattern, and find its position', 'Ben saves 4 dollars in week 1. After that he saves 5 more dollars each week, so his savings are 4, 9, 14, 19, ... dollars. In which week will his savings be 54 dollars?', '[]', '11', '(54-4)/5+1', 'Each week after week 1 adds 5 dollars. From 4 to 54 is 50 dollars, which takes $50 \div 5 = 10$ more weeks. So 54 dollars is reached in week $1 + 10 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Week n: 4 + 5(n - 1) = 54, so 5(n - 1) = 50, n - 1 = 10, n = 11. Check: 4, 9, 14, 19, 24, 29, 34, 39, 44, 49, 54.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e9cbd7a9-0d7c-4134-8d11-a381d78e9e08', 'NC26.5.ANR.6', 2, 'choice', 'Decide whether a number is in a pattern, and find its position', 'A pattern starts at 3 and adds 6 each time. Which of these numbers will be in the pattern?', '["40","45","36","52"]', '45', '3+7*6', 'The pattern is 3, 9, 15, 21, 27, 33, 39, 45, ... The number 45 is the 8th number. To check, $45 - 3 = 42$ and $42 \div 6 = 7$ steps. The numbers 40, 36 and 52 are not 3 plus a multiple of 6.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbers are 3 + multiple of 6: 3, 9, 15, 21, 27, 33, 39, 45, 51. 45 - 3 = 42 = 6 x 7 yes. 40, 52, 36 give 37, 49, 33, not multiples of 6.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95b7b8f3-7e83-444d-a96e-52f43505e0c6', 'NC26.5.ANR.6', 2, 'numeric', 'Decide whether a number is in a pattern, and find its position', 'The multiples of 8 make the pattern 8, 16, 24, 32, ... In what position is the number 120?', '[]', '15', '120/8', 'The number in position n is $n \times 8$. Since $120 \div 8 = 15$, the number 120 is in position 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Position n holds 8n. 120 / 8 = 15, so position 15.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
