INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ca0de30-d95a-47d3-b80a-51ec7364e03a', 'NC26.5.ANR.6', 2, 'choice', 'Find the rule of a pattern from its terms', 'Which rule makes the pattern 6, 24, 96, 384, ...?', '["Add 18","Multiply by 2","Add 4","Multiply by 4"]', 'Multiply by 4', NULL, '$6 \times 4 = 24$, $24 \times 4 = 96$ and $96 \times 4 = 384$. Adding 18 gets from 6 to 24 but not from 24 to 96.', 'checked', '{"lint":[],"solve":{"answer":"Multiply by 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 = 24, 24 x 4 = 96, 96 x 4 = 384. Multiply by 4.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
