INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60ba384b-15af-414f-a00f-de72f502144d', 'NC26.5.ANR.6', 2, 'numeric', 'Find the rule of a pattern from its terms', 'The start of a pattern is 5, 5.5, 6, 6.5, ... How much is added each time?', '[]', '0.5', '5.5-5', '$5.5 - 5 = 0.5$, $6 - 5.5 = 0.5$ and $6.5 - 6 = 0.5$. The pattern adds 0.5 each time.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.5 - 5 = 0.5, 6 - 5.5 = 0.5, 6.5 - 6 = 0.5. Adds 0.5.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
