INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffd22dce-ccae-45a4-b0c7-7e113091b8b9', 'NC26.5.ANR.6', 2, 'choice', 'Generate two patterns from two rules', 'Pattern A starts at 2 and adds 3 each time. Pattern B starts at 5 and adds 3 each time. What is the sum of the 4th numbers in the two patterns?', '["22","28","11","25"]', '25', '(2+3*3)+(5+3*3)', 'Pattern A is 2, 5, 8, 11, so its 4th number is 11. Pattern B is 5, 8, 11, 14, so its 4th number is 14. The sum is $11 + 14 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2, 5, 8, 11. B: 5, 8, 11, 14. Sum of 4th numbers: 11 + 14 = 25.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
