INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d405c25-0990-4933-bda1-092ede6ba96f', 'NC26.5.ANR.6', 2, 'numeric', 'Describe the relationship between matching terms of two patterns', 'Pattern R starts at 0 and adds 5 each time. Pattern S starts at 0 and adds 20 each time. Each number in S is how many times the matching number in R?', '[]', '4', '20/5', 'Pattern R is 0, 5, 10, 15, ... and Pattern S is 0, 20, 40, 60, ... Each number in S is $20 \div 5 = 4$ times the matching number in R.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R: 0, 5, 10, 15. S: 0, 20, 40, 60. 20 = 4 x 5, 40 = 4 x 10, 60 = 4 x 15 (and 0 = 4 x 0). 4 times.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8e11e35-1a31-4f9a-8a92-2adea2ecf4a0', 'NC26.5.ANR.6', 2, 'choice', 'Describe the relationship between matching terms of two patterns', 'Pattern U is 3, 5, 7, 9. Pattern V is 6, 10, 14, 18. Which statement describes the matching numbers?', '["Each number in V is 3 more than the matching number in U","Each number in V is 2 times the matching number in U","Each number in V is 2 more than the matching number in U","Each number in V is 4 times the matching number in U"]', 'Each number in V is 2 times the matching number in U', NULL, 'Match them up: $3 \to 6$, $5 \to 10$, $7 \to 14$, $9 \to 18$. Each number in V is double the number in U. The differences (3, 5, 7, 9) keep changing, so it is not "more than".', 'checked', '{"lint":[],"solve":{"answer":"Each number in V is 2 times the matching number in U","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 2 x 3, 10 = 2 x 5, 14 = 2 x 7, 18 = 2 x 9. 2 times. (''3 more'' works only for the first pair.)","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('306ea962-d3f3-439d-89f2-e49279da292f', 'NC26.5.ANR.6', 2, 'choice', 'Describe the relationship between matching terms of two patterns', 'Which pair of patterns has matching numbers where one number is always 6 more than the other?', '["A: 2, 4, 6, 8 and B: 12, 24, 36, 48","A: 1, 3, 5, 7 and B: 6, 12, 18, 24","A: 3, 6, 9, 12 and B: 6, 12, 18, 24","A: 2, 4, 6, 8 and B: 8, 10, 12, 14"]', 'A: 2, 4, 6, 8 and B: 8, 10, 12, 14', NULL, 'In the correct pair, $8 - 2 = 6$, $10 - 4 = 6$, $12 - 6 = 6$ and $14 - 8 = 6$. Of the other pairs, one is 6 times as much, one has differences that keep changing (5, 9, 13, 17), and one is 2 times as much.', 'checked', '{"lint":[],"solve":{"answer":"A: 2, 4, 6, 8 and B: 8, 10, 12, 14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,4,6,8 vs 8,10,12,14: differences 6, 6, 6, 6. Others: 3,6,9,12 vs 6,12,18,24 differ 3,6,...; 2,4,6,8 vs 12,24,...; 1,3,5,7 vs 6,12,... not constant.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88ee3a0b-40d0-4dbd-b4b2-ec0cbd833665', 'NC26.5.ANR.6', 2, 'choice', 'Use the relationship between two patterns to find a term', 'Pattern A starts at 3 and adds 4 each time. Pattern B starts at 8 and adds 4 each time. The 9th number in Pattern A is 35. What is the 9th number in Pattern B?', '["35","40","39","45"]', '40', '35+5', 'Both patterns add 4, so the matching numbers always differ by $8 - 3 = 5$: each number in B is 5 more than the matching number in A. The 9th number in B is $35 + 5 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both add 4, B starts 5 higher, so B is always 5 more. 9th in B = 35 + 5 = 40. Check: 8 + 4 x 8 = 40.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4e4d4b0-f260-4688-86ef-93910e247dc7', 'NC26.5.ANR.6', 2, 'choice', 'Use the relationship between two patterns to find a term', 'Pattern C is 2, 4, 6, 8, ... Pattern D is 10, 12, 14, 16, ... The 20th number in Pattern C is 40. What is the 20th number in Pattern D?', '["42","50","38","48"]', '48', '40+8', 'Match them up: $2 \to 10$, $4 \to 12$, $6 \to 14$. Each number in D is 8 more than the matching number in C. So the 20th number in D is $40 + 8 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both add 2; D is always 8 more than C (10 - 2 = 8). 20th in D = 40 + 8 = 48. Check: 10 + 2 x 19 = 48.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e0356e7-57a9-411c-9e56-dc6bea02eb10', 'NC26.5.ANR.6', 2, 'numeric', 'Use the relationship between two patterns to find a term', 'Pattern E is 6, 12, 18, 24, ... Pattern F is 2, 4, 6, 8, ... The 15th number in Pattern E is 90. What is the 15th number in Pattern F?', '[]', '30', '90/3', 'Each number in E is 3 times the matching number in F ($6 \to 2$, $12 \to 4$). So the 15th number in F is $90 \div 3 = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each E number is 3 times the F number (6 = 3 x 2, ...). 15th in F = 90 / 3 = 30. Check: 2 x 15 = 30.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89397646-ca67-4843-a057-6a872abbe4e5', 'NC26.5.ANR.6', 2, 'choice', 'Patterns with two quantities in real situations', 'On day 1, Ben has 10 stickers and Cara has 4 stickers. Each day after that, each of them gets 2 more stickers. How many more stickers does Ben have than Cara on day 6?', '["2","12","6","20"]', '6', '10-4', 'Both get the same number of stickers each day, so the difference never changes: $10 - 4 = 6$. (On day 6 Ben has 20 and Cara has 14.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both gain 2 a day, so the gap stays 10 - 4 = 6. Day 6: Ben 20, Cara 14, difference 6.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb715a48-cc5a-4f1b-a6a4-4d540b157a6d', 'NC26.5.ANR.6', 2, 'choice', 'Patterns with two quantities in real situations', 'Gia saves 4 dollars each week. Her brother saves 12 dollars each week. They both start with nothing. After the same number of weeks, which statement is true?', '["Her brother always has 8 dollars more than Gia","Her brother always has 3 times as much as Gia","Her brother always has 12 times as much as Gia","Gia always has 3 times as much as her brother"]', 'Her brother always has 3 times as much as Gia', NULL, 'After 1 week: 4 and 12. After 2 weeks: 8 and 24. After 3 weeks: 12 and 36. Her brother always has $12 \div 4 = 3$ times as much. The difference (8, 16, 24) keeps growing, so "8 dollars more" is not always true.', 'checked', '{"lint":[],"solve":{"answer":"Her brother always has 3 times as much as Gia","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After w weeks: Gia 4w, brother 12w = 3 x 4w. Always 3 times. (''8 more'' holds only at week 1.)","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('441b252d-c469-4f32-ab00-405bee344897', 'NC26.5.ANR.6', 2, 'numeric', 'Patterns with two quantities in real situations', 'A bathtub already has 5 inches of water in it. The tap adds 3 inches of water each minute. How many inches of water are in the tub after 6 minutes?', '[]', '23', '5+6*3', 'The tap adds $6 \times 3 = 18$ inches in 6 minutes, so there are $5 + 18 = 23$ inches of water.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 + 3 x 6 = 5 + 18 = 23 inches.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92e27c08-425b-4b03-b97d-6faac094b00d', 'NC26.5.ANR.6', 2, 'numeric', 'Compare two patterns', 'Pattern A starts at 5 and adds 4 each time. Pattern B starts at 9 and adds 2 each time. In which position do the two patterns first have the same number? (Compare numbers in the same position.)', '[]', '3', '(9-5)/(4-2)+1', 'Pattern A: 5, 9, 13, 17. Pattern B: 9, 11, 13, 15. In position 3 both patterns have 13.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5, 9, 13, 17. B: 9, 11, 13, 15. Position 1: 5 vs 9; 2: 9 vs 11; 3: 13 vs 13. First equal at position 3.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06805da9-78e3-480a-8c1b-c03461a93ad2', 'NC26.5.ANR.6', 2, 'choice', 'Compare two patterns', 'Pattern A starts at 20 and adds 5 each time. Pattern B starts at 0 and adds 10 each time. In which position do both patterns have the same number?', '["4","5","6","40"]', '5', '(20-0)/(10-5)+1', 'Pattern A: 20, 25, 30, 35, 40, 45. Pattern B: 0, 10, 20, 30, 40, 50. In position 5 both patterns have 40. In position 4 the numbers are 35 and 30, and in position 6 they are 45 and 50. (The number 40 is the matching value, not the position.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 20, 25, 30, 35, 40. B: 0, 10, 20, 30, 40. Equal at position 5 (both 40). After that B grows faster, so only position 5.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a88ccea-36b0-4b4e-805d-8182e8765685', 'NC26.5.ANR.6', 2, 'choice', 'Compare two patterns', 'Pattern M starts at 1 and multiplies by 2 each time. Pattern N starts at 1 and adds 10 each time. How much greater is the 6th number in Pattern N than the 6th number in Pattern M?', '["19","83","29","9"]', '19', '(1+5*10)-(1*2^5)', 'Pattern M: 1, 2, 4, 8, 16, 32, so its 6th number is 32. Pattern N: 1, 11, 21, 31, 41, 51, so its 6th number is 51. The difference is $51 - 32 = 19$. The choice 83 adds the two numbers.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M: 1, 2, 4, 8, 16, 32. N: 1, 11, 21, 31, 41, 51. 51 - 32 = 19.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('794c0d76-4770-4d09-90df-1268b2fb7abd', 'NC26.5.ANR.6', 3, 'numeric', 'Use the relationship between two patterns, with division', 'Pattern A starts at 0 and adds 6. Pattern B starts at 0 and adds 2. The 8th number in Pattern A is 42. What is the 8th number in Pattern B?', '[]', '14', '42/3', 'Each number in A is 3 times the matching number in B, because 6 is 3 times 2. So the 8th number in B is $42 \div 3 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A''s 8th = 7 x 6 = 42 (matches). B''s 8th = 7 x 2 = 14; each B term is 1/3 of A''s: 42/3 = 14.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('116d7b4e-8b2e-4862-8cae-91f2382d3ca6', 'NC26.5.ANR.6', 3, 'choice', 'Choose rules that make a given relationship', 'Two patterns both start at 0. Each number in the second pattern must be twice the matching number in the first pattern. Which pair of rules does this?', '["First pattern: add 3. Second pattern: add 5.","First pattern: add 3. Second pattern: add 6.","First pattern: add 6. Second pattern: add 3.","First pattern: add 3. Second pattern: add 9."]', 'First pattern: add 3. Second pattern: add 6.', NULL, 'Both start at 0, so the second pattern''s step must be twice the first pattern''s step. With add 3 in the first pattern the second must add 6.', 'checked', '{"lint":[],"solve":{"answer":"First pattern: add 3. Second pattern: add 6.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both start at 0; if first adds 3 and second adds 6, terms are 3k and 6k, so second = 2 x first. Add 6/add 3 gives half; add 5 and add 9 give 5/3 and 3 times.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b35c6d-6ec3-4753-b270-60c44ea37c9a', 'NC26.5.ANR.6', 3, 'numeric', 'Work backward using the relationship between two patterns', 'Pattern X: 0, 5, 10, 15, ... Pattern Y: 0, 10, 20, 30, ... A number in Pattern Y is 90. What is the matching number in Pattern X?', '[]', '45', '90/2', 'Each number in Y is 2 times the matching number in X. So the matching number in X is $90 \div 2 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Y = 2 x X (10 = 2 x 5 etc.). 90 / 2 = 45. (Y: 90 is 10th term 9x10; X 10th = 45.)","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
