INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('525af0b7-b5d2-432e-8469-f84560a8e907', 'NC26.5.ANR.6', 3, 'numeric', 'Generate a multiplying pattern from a rule', 'A pattern multiplies by 3 each time. The 2nd number in the pattern is 12. What is the 5th number?', '[]', '324', '12*3*3*3', 'From the 2nd number, multiply by 3 three more times: $12 \times 3 = 36$, $36 \times 3 = 108$, $108 \times 3 = 324$. The 5th number is 324.', 'checked', '{"lint":[],"solve":{"answer":"324","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2nd = 12, 3rd = 36, 4th = 108, 5th = 324.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
