INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2a7af2d-368b-4f66-8cc4-ab384b4f9feb', 'NC26.5.ANR.6', 3, 'choice', 'Find a later term of an adding pattern', 'The 1st number in a pattern is 7. Each number after that is 9 more than the number before it. What is the 30th number?', '["277","261","270","268"]', '268', '7+29*9', 'The 30th number takes 29 steps of 9 from the start: $29 \times 9 = 261$, and $7 + 261 = 268$. The choice 277 uses 30 steps, 261 forgets the starting number, and 270 is $30 \times 9$.', 'checked', '{"lint":[],"solve":{"answer":"268","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30th = 7 + 9 x 29 = 7 + 261 = 268.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
