INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7499263d-c71a-4b9b-bcc8-87eb0120f770', 'NC26.5.ANR.6', 3, 'numeric', 'Find a later term of an adding pattern', 'A pattern starts at 2.5 and adds 1.5 each time. What is the 9th number in the pattern?', '[]', '14.5', '2.5+8*1.5', 'The 9th number takes 8 steps of 1.5 from the start: $8 \times 1.5 = 12$, and $2.5 + 12 = 14.5$.', 'checked', '{"lint":[],"solve":{"answer":"14.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9th = 2.5 + 1.5 x 8 = 2.5 + 12 = 14.5.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
