INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93a0de50-f437-4726-bed1-5e6db41aa693', 'NC26.5.ANR.6', 3, 'choice', 'Compare two patterns', 'Each of four patterns starts at 2. Which pattern has the greatest 4th number?', '["Multiply by 3 each time","Multiply by 2 each time","Add 10 each time","Add 20 each time"]', 'Add 20 each time', NULL, '4th numbers: add 20 gives 2, 22, 42, 62 (62); multiply by 3 gives 2, 6, 18, 54 (54); multiply by 2 gives 2, 4, 8, 16 (16); add 10 gives 2, 12, 22, 32 (32). The greatest is 62. (Multiplying grows faster later on, but not by the 4th number here.)', 'checked', '{"lint":[],"solve":{"answer":"Add 20 each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4th numbers from 2: x2: 2, 4, 8, 16. x3: 2, 6, 18, 54. +20: 2, 22, 42, 62. +10: 2, 12, 22, 32. Greatest is 62 (add 20).","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a80ca36f-1a4a-4145-8ff2-dbec29277dd7', 'NC26.5.ANR.6', 3, 'numeric', 'Compare two patterns', 'Pattern A starts at 2 and multiplies by 2 each time. Pattern B starts at 40 and adds 10 each time. In which position is Pattern A''s number first greater than Pattern B''s number in the same position?', '[]', '7', '7', 'Pattern A: 2, 4, 8, 16, 32, 64, 128. Pattern B: 40, 50, 60, 70, 80, 90, 100. In position 6 the numbers are 64 and 90, so A is still smaller. In position 7 the numbers are 128 and 100, so A is greater for the first time.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2, 4, 8, 16, 32, 64, 128. B: 40, 50, 60, 70, 80, 90, 100. Position 6: 64 < 90; position 7: 128 > 100. First at position 7.","run_id":"claude-code","at":"2026-10-17T20:08:42.947Z"}}', 'ai', NULL, NULL)
