INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46612a85-6c73-4d0f-99bc-85baa2b833ca', 'NC26.5.SGMR.1', 1, 'choice', 'Which category fits inside another', 'Which statement about rhombuses is true?', '["Every rhombus is a rectangle.","Every rhombus is a square.","A rhombus is not a quadrilateral.","Every rhombus is a parallelogram."]', 'Every rhombus is a parallelogram.', NULL, 'A rhombus has two pairs of parallel sides, so it is a parallelogram. It does not have to have right angles, so it is not always a rectangle or a square.', 'checked', '{"lint":[],"solve":{"answer":"Every rhombus is a parallelogram.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus has 4 equal sides and both pairs of opposite sides parallel, so it is always a parallelogram. It need not have right angles, so not always a rectangle or square; it is a quadrilateral.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
