INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34e0ef49-95d0-4226-9e8b-9679bd1c5d87', 'NC26.5.SGMR.1', 1, 'choice', 'Attributes carry down to subcategories', 'All parallelograms have opposite sides that are equal in length. A rectangle is a kind of parallelogram. What must be true of a rectangle?', '["All four of its sides are equal.","It has no right angles.","Its opposite sides are equal in length.","Its sides are all different lengths."]', 'Its opposite sides are equal in length.', NULL, 'What is true of every parallelogram is true of every rectangle, because a rectangle is a parallelogram. So a rectangle has opposite sides equal.', 'checked', '{"lint":[],"solve":{"answer":"Its opposite sides are equal in length.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Attribute of the parent group carries to the subgroup: a rectangle''s opposite sides are equal. It has right angles, and need not have 4 equal sides.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
