INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b29a97b8-ecb1-4536-a2ea-a3b0e5a6fa78', 'NC26.5.SGMR.1', 1, 'choice', 'Combine clues to identify a shape', 'Pia says her shape is a square. Which statement about her shape must be true?', '["Only its opposite sides are equal.","All its sides are equal and it has four right angles.","Exactly one pair of its sides is parallel.","It has no right angles."]', 'All its sides are equal and it has four right angles.', NULL, 'A square has both attributes together: four equal sides and four right angles.', 'checked', '{"lint":[],"solve":{"answer":"All its sides are equal and it has four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square has 4 equal sides and 4 right angles. Other options contradict that.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
