INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f87c886-7fd2-4b1e-8d65-4e9547c23cb9', 'NC26.5.SGMR.1', 2, 'choice', 'Name a quadrilateral from its properties', 'Which description fits a rhombus that is not a square?', '["Four equal sides and four right angles","Four equal sides and no right angles","Opposite sides equal and four right angles","Exactly one pair of parallel sides and no right angles"]', 'Four equal sides and no right angles', NULL, 'A rhombus has four equal sides. If it also had four right angles it would be a square, so a rhombus that is not a square has no right angles.', 'checked', '{"lint":[],"solve":{"answer":"Four equal sides and no right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus has 4 equal sides. If it is not a square it has no right angles (one right angle in a parallelogram forces all four). Option A is a trapezoid, C a rectangle, D a square.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
