INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1db13cf5-740e-4fe6-8a3c-7b3b65683259', 'NC26.5.SGMR.1', 2, 'numeric', 'Always, sometimes or never true', 'Amir tests the claim "Every rectangle is a square" with these rectangles, with side lengths in cm: 5 and 5, 8 and 3, 4 and 4, 10 and 2, 6 and 9. How many of these rectangles show that the claim is false?', '[]', '3', NULL, 'A rectangle shows the claim is false when its sides are not all equal. The rectangles 8 by 3, 10 by 2 and 6 by 9 do that. The 5 by 5 and 4 by 4 rectangles are squares. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-squares: 8 by 3, 10 by 2, 6 by 9. 5 by 5 and 4 by 4 are squares. Count 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bd4234b-831e-4513-8cf2-ffd9d6299a44', 'NC26.5.SGMR.1', 2, 'choice', 'Always, sometimes or never true', 'Which statement is NOT always true of a rectangle?', '["It has four right angles.","Its opposite sides are equal.","It has two pairs of parallel sides.","Its four sides are equal."]', 'Its four sides are equal.', NULL, 'A rectangle with sides of 5 cm and 3 cm has four right angles, equal opposite sides and two pairs of parallel sides, but its four sides are not all equal.', 'checked', '{"lint":[],"solve":{"answer":"Its four sides are equal.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles always have two pairs of parallel sides, 4 right angles and opposite sides equal; four equal sides only if it is a square.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
