INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e8ae757-f74a-4970-907a-10b3e8cd95d6', 'NC26.5.SGMR.1', 2, 'numeric', 'Count shapes that have an attribute', 'A teacher has shape cards. 4 cards show squares, 3 show rectangles that are not squares, 2 show rhombuses that are not squares, and 5 show parallelograms that are neither rectangles nor rhombuses. How many cards show a shape with four equal sides?', '[]', '6', '4+2', 'Squares and rhombuses have four equal sides. That is 4 + 2 = 6 cards. Rectangles that are not squares and the other parallelograms do not have four equal sides.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four equal sides: squares (4) and rhombuses that are not squares (2). 4 + 2 = 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
