INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a422b657-3bcf-436f-b4ed-35394604266a', 'NC26.5.SGMR.1', 2, 'numeric', 'Count shapes that have an attribute', 'Kim sorts cards for these shapes: square, rectangle, rhombus, trapezoid with exactly one pair of parallel sides, and quadrilateral. She puts a card in the "parallelogram" pile only if the shape is ALWAYS a parallelogram. How many cards go in that pile?', '[]', '3', NULL, 'Squares, rectangles and rhombuses are always parallelograms. A trapezoid with exactly one pair of parallel sides and a general quadrilateral are not. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square, rectangle, rhombus are always parallelograms. Trapezoid with one pair: never. Quadrilateral: not always. 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5038035d-7ab3-4ad7-96f9-c0ced69f88cc', 'NC26.5.SGMR.1', 2, 'numeric', 'Count shapes that have an attribute', 'Six quadrilaterals are described. A: sides 6, 6, 6, 6 cm; four right angles. B: sides 8, 3, 8, 3 cm; four right angles. C: sides 5, 5, 5, 5 cm; no right angles. D: sides 9, 4, 9, 4 cm; no right angles. E: sides 2, 2, 2, 2 cm; four right angles. F: exactly one pair of parallel sides. How many of the six are rectangles?', '[]', '3', NULL, 'A rectangle has four right angles. A, B and E have four right angles, so they are rectangles (A and E are squares). C and D have no right angles, and F has only one pair of parallel sides. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles need 4 right angles: A (square), B, E (square). C, D have no right angles; F is a trapezoid. 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
