INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3286bc0a-dc03-4905-acb8-ff06b18f7b79', 'NC26.5.SGMR.1', 2, 'choice', 'Tell two categories apart', 'Two quadrilaterals each have four right angles. Shape A has four equal sides. Shape B has sides of 5 cm, 3 cm, 5 cm and 3 cm. What are the most specific names for Shape A and Shape B?', '["A is a rectangle and B is a square.","A is a square and B is a rectangle.","A is a rhombus and B is a square.","A is a rectangle and B is a rhombus."]', 'A is a square and B is a rectangle.', NULL, 'Four right angles and four equal sides is a square. Four right angles with sides 5, 3, 5, 3 is a rectangle that is not a square.', 'checked', '{"lint":[],"solve":{"answer":"A is a square and B is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 4 right angles and 4 equal sides = square. B: 4 right angles, sides 5, 3, 5, 3 = rectangle (not square).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba01e2bd-a853-49cf-9e50-b49cdcadfd59', 'NC26.5.SGMR.1', 2, 'choice', 'Tell two categories apart', 'Sana''s mystery quadrilateral is either a rectangle with sides of 6 cm and 4 cm or a rhombus with no right angles. Which measurement would tell her it is the rhombus?', '["Two opposite sides are parallel.","Two opposite sides are equal in length.","One of its angles is not a right angle.","It has four sides."]', 'One of its angles is not a right angle.', NULL, 'Both shapes have four sides, parallel opposite sides and equal opposite sides. A rectangle has only right angles, so an angle that is not a right angle shows the shape is the rhombus.', 'checked', '{"lint":[],"solve":{"answer":"One of its angles is not a right angle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The rectangle has all right angles; the rhombus has none. Both have 4 sides, parallel and equal opposite sides. A non-right angle identifies the rhombus.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20d863f6-56cf-44d3-bf58-567503f8d60e', 'NC26.5.SGMR.1', 2, 'numeric', 'Tell two categories apart', 'A quadrilateral has four right angles. Its perimeter is 24 cm and one of its sides is 6 cm long. How long is a side next to the 6 cm side, in centimeters?', '[]', '6', '24/2-6', 'Half the perimeter is 24 divided by 2 = 12 cm, which is two side lengths added. The side next to the 6 cm side is 12 - 6 = 6 cm. So all four sides are 6 cm and the shape is a square.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four right angles = rectangle, opposite sides equal. Adjacent sides sum to 12; 12 - 6 = 6 cm (it is a square).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18c7743b-b9bf-4cfa-8970-541d620c9dd9', 'NC26.5.SGMR.1', 2, 'choice', 'Combine clues to identify a shape', 'Which shape fits all three clues? Clue 1: Both pairs of opposite sides are parallel. Clue 2: Opposite sides are equal, but sides next to each other have different lengths. Clue 3: Not every angle is a right angle.', '["A rectangle","A rhombus","A parallelogram that is not a rectangle","A square"]', 'A parallelogram that is not a rectangle', NULL, 'Clue 2 rules out a rhombus and a square (their sides are all equal). Clue 3 rules out a rectangle. A parallelogram with no right angles and unequal neighboring sides fits all three clues.', 'checked', '{"lint":[],"solve":{"answer":"A parallelogram that is not a rectangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: option B also includes non-square rhombuses, which fail clue 2; ''neither a rectangle nor a rhombus'' would be exact. Still the only defensible choice.","work":"Clue 1: parallelogram. Clue 2: adjacent sides differ, so not a rhombus/square. Clue 3: not a rectangle. Only B can fit.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7672a23-b413-45d2-be61-941b6a4e96d3', 'NC26.5.SGMR.1', 2, 'numeric', 'Combine clues to identify a shape', 'Shape A has 4 right angles and sides of 7 cm and 3 cm. Shape B has 4 equal sides, each the same length as the longer side of Shape A. How many centimeters longer is the perimeter of Shape B than the perimeter of Shape A?', '[]', '8', '4*7-2*(7+3)', 'Shape A is a rectangle with perimeter 2 x (7 + 3) = 20 cm. Shape B has four sides of 7 cm, so its perimeter is 4 x 7 = 28 cm. The difference is 28 - 20 = 8 cm.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: rectangle 7 by 3, perimeter 20. B: 4 sides of 7, perimeter 28. 28 - 20 = 8 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('339b4221-326f-46fc-b871-4a9e3d1c8aea', 'NC26.5.SGMR.1', 2, 'choice', 'Combine clues to identify a shape', 'Priya says her mystery quadrilateral is a rhombus and also a rectangle. What else can she be sure of?', '["It has exactly one pair of parallel sides.","It has no right angles.","Its sides are not all equal.","It is a square."]', 'It is a square.', NULL, 'Being a rhombus means four equal sides. Being a rectangle means four right angles. Together those describe a square.', 'checked', '{"lint":[],"solve":{"answer":"It is a square.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rhombus (4 equal sides) and rectangle (4 right angles) together = square.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('072a580e-1074-4009-b2cd-0b56d1e7669f', 'NC26.5.SGMR.1', 2, 'numeric', 'Count the names that fit a shape', 'Here are six names: quadrilateral, trapezoid with exactly one pair of parallel sides, parallelogram, rectangle, rhombus and square. How many of these six names always fit a square?', '[]', '5', NULL, 'A square is a quadrilateral, a parallelogram, a rectangle, a rhombus and a square, which is 5 names. It is not a trapezoid with exactly one pair of parallel sides, because a square has two pairs of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square is a quadrilateral, parallelogram, rectangle, rhombus and square (5). It has two pairs of parallel sides, so ''trapezoid with exactly one pair'' does not fit.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5f9fd6f-566e-47d2-9d30-1ad40d53d5a4', 'NC26.5.SGMR.1', 2, 'numeric', 'Sort shapes by an attribute', 'Mia describes six quadrilaterals: a square; a rectangle that is not a square; a rhombus that is not a square; a parallelogram with no right angles and sides that are not all equal; a trapezoid with exactly one pair of parallel sides; and a quadrilateral with no parallel sides. How many of the six are parallelograms?', '[]', '4', NULL, 'A parallelogram has two pairs of parallel sides. The square, the rectangle, the rhombus and the parallelogram all have them, so that is 4. The trapezoid has only one pair and the last shape has none.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelograms: square, rectangle, rhombus, the general parallelogram = 4. The trapezoid (exactly one pair) and the quadrilateral with no parallel sides are not.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ce4aa38-3ea6-4195-8415-e530074fccf8', 'NC26.5.SGMR.1', 2, 'choice', 'Reason from the hierarchy', 'Every rhombus has opposite sides that are parallel. Every square is a rhombus. Which conclusion must be true?', '["Every square has opposite sides that are parallel","Every rhombus has four right angles","Every rhombus is a square","Every shape with parallel opposite sides is a square"]', 'Every square has opposite sides that are parallel', NULL, 'A square is inside the group of rhombuses, so it has every attribute of a rhombus, including parallel opposite sides. The other statements go the wrong way: rhombuses are not all squares, and many shapes with parallel opposite sides are not squares.', 'checked', '{"lint":[],"solve":{"answer":"Every square has opposite sides that are parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares are rhombuses, rhombuses have parallel opposite sides, so every square does. The others reverse the inclusion.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37ae1ce6-3b88-44c9-bac2-c54f6e3256f8', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Which statement about the attributes of quadrilaterals is true?', '["Every attribute of a square is also an attribute of a rectangle.","Every attribute of a rhombus is also an attribute of a rectangle.","Every attribute of a square is also an attribute of a rhombus.","Every attribute of a rectangle is also an attribute of a square."]', 'Every attribute of a rectangle is also an attribute of a square.', NULL, 'A square is a kind of rectangle, so it has every attribute that rectangles have. The other statements fail: a square has four equal sides, which a rectangle does not always have, and a square has right angles, which a rhombus does not always have.', 'checked', '{"lint":[],"solve":{"answer":"Every attribute of a rectangle is also an attribute of a square.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A square is a special rectangle, so every property all rectangles have (4 right angles, opposite sides parallel and equal) holds for squares. Square->rectangle fails (equal sides), square->rhombus fails (right angles), rhombus->rectangle fails (right angles).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec246ab0-4628-49fb-9ddd-c22f02702e81', 'NC26.5.SGMR.1', 3, 'choice', 'Use a counterexample to test a claim', 'Sam says: "This shape has four sides of equal length, so it must be a square." Which shape shows that Sam is wrong?', '["A rhombus with angles of 60 degrees and 120 degrees","A rectangle with sides 4 centimeters and 6 centimeters","A square with sides of 4 centimeters","A parallelogram with sides 3 centimeters and 5 centimeters"]', 'A rhombus with angles of 60 degrees and 120 degrees', NULL, 'We need a shape with four equal sides that is not a square. A rhombus with no right angles is one. The other shapes either do not have four equal sides, or are squares.', 'checked', '{"lint":[],"solve":{"answer":"A rhombus with angles of 60 degrees and 120 degrees","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rhombus with 60 and 120 degree angles has four equal sides but no right angles, so it is not a square. Rectangle 4x6 and parallelogram 3x5 do not have equal sides; a square agrees with Sam.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41846ef8-51e4-4411-be2f-3a09140b4d51', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that always have an attribute', 'Look at these four shapes: square, rectangle, rhombus, parallelogram. How many of them ALWAYS have four sides of equal length?', '[]', '2', NULL, 'A square and a rhombus always have four equal sides. A rectangle and a parallelogram only have equal opposite sides, so they do not always have four equal sides. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Always four equal sides: square and rhombus. Rectangle and parallelogram not always. Count = 2.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c0d1f37-902e-41c1-8961-e50b2734573a', 'NC26.5.SGMR.1', 3, 'choice', 'Name a quadrilateral from its properties', 'Which of these four-sided shapes could NOT be called a parallelogram?', '["A rectangle with sides of 6 cm and 3 cm","A rhombus with 5 cm sides and no right angles","A square with 4 cm sides","A quadrilateral with exactly one pair of parallel sides"]', 'A quadrilateral with exactly one pair of parallel sides', NULL, 'A parallelogram needs two pairs of parallel sides. Rectangles, rhombuses and squares all have them. A shape with exactly one pair of parallel sides does not.', 'checked', '{"lint":[],"solve":{"answer":"A quadrilateral with exactly one pair of parallel sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangles, squares and rhombuses all have two pairs of parallel sides, so all are parallelograms. A quadrilateral with exactly one pair of parallel sides is not.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('757b0b45-e1e3-4981-911a-cd94c9ba47b6', 'NC26.5.SGMR.1', 3, 'choice', 'Name a quadrilateral from its properties', 'Which pair of clues is enough to be sure that a quadrilateral is a square?', '["It has 4 equal sides and 4 right angles","It has 4 equal sides and opposite sides parallel","It has 4 right angles and opposite sides equal","It has opposite sides parallel and opposite sides equal"]', 'It has 4 equal sides and 4 right angles', NULL, 'Four equal sides and four right angles together describe a square. The other pairs also fit shapes that are not squares: a rhombus, a rectangle and a parallelogram.', 'checked', '{"lint":[],"solve":{"answer":"It has 4 equal sides and 4 right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 4 equal sides + parallel = rhombus, maybe not square. B: 4 equal sides and 4 right angles = square. C: any parallelogram. D: rectangle, maybe not square. Answer B.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f9c5264-e4ac-429a-96cd-fdafb701a713', 'NC26.5.SGMR.1', 3, 'choice', 'Name a quadrilateral from its properties', 'A quadrilateral has 4 equal sides. Which extra clue would make it a square?', '["Its opposite sides are parallel","It has 4 right angles","Its opposite sides are equal","It has two pairs of equal sides"]', 'It has 4 right angles', NULL, 'Every shape with four equal sides is a rhombus, and a rhombus already has parallel opposite sides, equal opposite sides and two pairs of equal sides. Only four right angles make it a square.', 'checked', '{"lint":[],"solve":{"answer":"It has 4 right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides = rhombus. Opposite sides parallel/equal and two pairs of equal sides are already true of every rhombus. Adding 4 right angles makes it a square.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d07ad38-c9a2-43c4-a0c1-34d0ebea7d50', 'NC26.5.SGMR.1', 3, 'numeric', 'Name a quadrilateral from its properties', 'Five quadrilaterals are described. A has 4 right angles and sides of 5, 5, 5 and 5 cm. B has 4 right angles and sides of 6, 2, 6 and 2 cm. C has sides of 4, 4, 4 and 4 cm and no right angles. D has opposite sides parallel, sides of 7, 3, 7 and 3 cm, and no right angles. E has exactly one pair of parallel sides. How many of A, B, C, D and E are parallelograms?', '[]', '4', NULL, 'A is a square, B is a rectangle, C is a rhombus (four equal sides) and D has two pairs of parallel sides, so all four are parallelograms. E has only one pair of parallel sides. The answer is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: square, parallelogram. B: rectangle, parallelogram. C: 4 equal sides = rhombus, parallelogram. D: opposite sides parallel = parallelogram. E: exactly one pair = trapezoid, not. Count 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('891494be-9112-460d-a4d2-ff8e1bd87954', 'NC26.5.SGMR.1', 3, 'choice', 'Which category fits inside another', 'In a chart of quadrilaterals, the group of rhombuses and the group of rectangles overlap. Which kind of shape belongs to BOTH groups?', '["Parallelograms","Trapezoids","Quadrilaterals","Squares"]', 'Squares', NULL, 'Only a shape with four equal sides and four right angles is in both groups, and that is a square. Parallelograms and quadrilaterals are bigger groups, and a trapezoid is neither a rectangle nor a rhombus.', 'checked', '{"lint":[],"solve":{"answer":"Squares","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A shape that is both a rhombus (4 equal sides) and a rectangle (4 right angles) is a square. Parallelograms/quadrilaterals are larger groups, not all of which are in both.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d3c7254-fff0-408a-b0bf-eb87ccc88cdf', 'NC26.5.SGMR.1', 3, 'choice', 'Which category fits inside another', 'Which of these statements is NOT true?', '["Every parallelogram is a rectangle.","Some rectangles are squares.","Some parallelograms are rhombuses.","Some rhombuses are rectangles."]', 'Every parallelogram is a rectangle.', NULL, 'A parallelogram with sides of 7 cm and 4 cm and no right angles is not a rectangle, so "Every parallelogram is a rectangle" is false. The other three are true: squares are rectangles, some parallelograms have four equal sides, and squares are rhombuses that are rectangles.', 'checked', '{"lint":[],"solve":{"answer":"Every parallelogram is a rectangle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A parallelogram with no right angles is not a rectangle, so A is not true. B (squares), C (rhombuses), D (squares) are true.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a83f978-f414-4455-ba7f-6e73dea323a1', 'NC26.5.SGMR.1', 3, 'numeric', 'Which category fits inside another', 'Think about four kinds of shapes: squares, rectangles that are not squares, rhombuses that are not squares, and parallelograms that are neither rectangles nor rhombuses. How many of these four kinds are rectangles?', '[]', '2', NULL, 'Squares are rectangles, and so are the rectangles that are not squares. Rhombuses that are not squares have no right angles, and the last kind has none either. So 2 of the kinds are rectangles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares: rectangles (yes). Rectangles that are not squares: yes. Rhombuses that are not squares: no right angles, not rectangles. Other parallelograms: not rectangles. Count 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da200113-8493-4c24-947f-e967bda32f54', 'NC26.5.SGMR.1', 3, 'choice', 'Which category fits inside another', 'Rhombuses and rectangles are both groups inside the group of parallelograms. Which shape is a parallelogram but is in NEITHER the group of rhombuses nor the group of rectangles?', '["A square with sides of 4 cm","A parallelogram with sides of 8 cm and 5 cm and no right angles","A rectangle with sides of 9 cm and 2 cm","A rhombus with 6 cm sides and no right angles"]', 'A parallelogram with sides of 8 cm and 5 cm and no right angles', NULL, 'The first shape has sides that are not all equal (so it is not a rhombus) and no right angles (so it is not a rectangle). The other three are squares, rectangles or rhombuses.', 'checked', '{"lint":[],"solve":{"answer":"A parallelogram with sides of 8 cm and 5 cm and no right angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 by 2 rectangle: rectangle. Rhombus: rhombus. Square: both. 8 by 5 with no right angles: parallelogram, sides not all equal (not rhombus), no right angles (not rectangle).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9006134-2df6-4d3c-addc-cf6ea16b2921', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Tom says: "A square has four equal sides, and a square is a parallelogram, so every parallelogram has four equal sides." Which sentence explains his mistake?', '["A square is not a kind of parallelogram.","A square does not have four equal sides.","No parallelogram has any equal sides.","What is true of a smaller group is not always true of the bigger group around it."]', 'What is true of a smaller group is not always true of the bigger group around it.', NULL, 'Attributes carry down from a bigger group to a smaller group, not up. A parallelogram with sides of 7 cm and 4 cm shows that parallelograms do not all have four equal sides.', 'checked', '{"lint":[],"solve":{"answer":"What is true of a smaller group is not always true of the bigger group around it.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Attributes pass down to subgroups, not up. Squares are a smaller group inside parallelograms, so a square''s four equal sides need not hold for all parallelograms. Option C.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20237fa5-62df-4816-bcac-a7c410f84398', 'NC26.5.SGMR.1', 3, 'numeric', 'Attributes carry down to subcategories', 'A hierarchy chart lists each attribute only once, at the biggest group that has it. Parallelograms have 2 listed attributes: two pairs of parallel sides, and opposite sides equal. Rectangles have 1 more listed attribute: four right angles. Rhombuses have 1 more listed attribute: four equal sides. A square is a kind of rectangle and a kind of rhombus. How many attributes does a square have in all?', '[]', '4', '2+1+1', 'A square gets the 2 attributes of parallelograms, the extra attribute of rectangles and the extra attribute of rhombuses. That is 2 + 1 + 1 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''how many attributes in all'' would be tighter as ''how many of the listed attributes'', since a square has other attributes (4 sides) not in the chart described.","work":"Square inherits parallelogram''s 2 listed attributes, plus rectangle''s 1 (right angles) and rhombus''s 1 (equal sides): 2 + 1 + 1 = 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('235024df-b315-47f7-bed5-a6d7b09af2e1', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Every rhombus has opposite sides that are equal in length. This is because every rhombus is a kind of ____, and every ____ has opposite sides equal in length. Which word fills both blanks?', '["parallelogram","rectangle","square","trapezoid"]', 'parallelogram', NULL, 'Every rhombus is a parallelogram, and every parallelogram has opposite sides equal, so the attribute carries down to rhombuses. Not every rhombus is a rectangle or a square, and a trapezoid does not have to have opposite sides equal.', 'checked', '{"lint":[],"solve":{"answer":"parallelogram","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every rhombus is a parallelogram, and every parallelogram has opposite sides equal. Rhombus is not always a rectangle or square; trapezoid is wrong.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('779d450a-806a-4214-85cf-176e7d6eabca', 'NC26.5.SGMR.1', 3, 'choice', 'Attributes carry down to subcategories', 'Which list has only attributes that EVERY rhombus has?', '["Four equal sides; four right angles","Four equal sides; opposite sides parallel","Opposite sides parallel; four right angles","Four right angles; exactly one pair of parallel sides"]', 'Four equal sides; opposite sides parallel', NULL, 'Every rhombus has four equal sides and two pairs of parallel sides. A rhombus does not have to have right angles, and it never has exactly one pair of parallel sides.', 'checked', '{"lint":[],"solve":{"answer":"Four equal sides; opposite sides parallel","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every rhombus has 4 equal sides and opposite sides parallel. Right angles not required; exactly one pair parallel is false.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d9b0c7f-f69c-4676-bf33-be1c922ab581', 'NC26.5.SGMR.1', 3, 'choice', 'Always, sometimes or never true', 'Which of these claims can be proven false by finding just ONE shape that breaks it?', '["All rhombuses have four right angles.","Some squares are rhombuses.","All squares are rectangles.","Some rectangles are parallelograms."]', 'All rhombuses have four right angles.', NULL, 'A slanted rhombus with no right angles is a shape that breaks the first claim. The other claims are true, so no shape can break them.', 'checked', '{"lint":[],"solve":{"answer":"All rhombuses have four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only a false ''all'' claim is disproved by one counterexample. D is false: a rhombus with no right angles breaks it. A, B, C are true, so nothing breaks them.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87ea561a-bb56-433a-8662-137af51b3272', 'NC26.5.SGMR.1', 3, 'choice', 'Always, sometimes or never true', 'Tess draws a quadrilateral with 4 equal sides. Tess says it must have four right angles. Dev says it cannot have four right angles. Who is right?', '["Tess is right.","Neither: it might or might not have four right angles.","Dev is right.","Both are right."]', 'Neither: it might or might not have four right angles.', NULL, 'A shape with four equal sides is a rhombus. It is a square if it has four right angles, and a slanted rhombus if it does not, so both are possible.', 'checked', '{"lint":[],"solve":{"answer":"Neither: it might or might not have four right angles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 equal sides = rhombus; it may be a square (4 right angles) or not. So neither must nor cannot holds.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44675c15-ada2-415a-ba40-5777c3a3760d', 'NC26.5.SGMR.1', 3, 'numeric', 'Always, sometimes or never true', 'Read six sentences. (1) A rhombus has opposite sides parallel. (2) A rhombus has 4 right angles. (3) A rectangle has 4 equal sides. (4) A parallelogram has opposite sides equal. (5) A square has 4 equal sides. (6) A rectangle has 4 right angles. How many of the sentences are true for EVERY shape of that kind?', '[]', '4', NULL, 'Sentences 1, 4, 5 and 6 are always true. Sentence 2 is false for a slanted rhombus, and sentence 3 is false for a 5 by 3 rectangle. The answer is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) true. (2) false. (3) false. (4) true. (5) true. (6) true. Count 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64fc1cd0-9e1e-4679-8f53-8ce6200f2e9d', 'NC26.5.SGMR.1', 3, 'numeric', 'Always, sometimes or never true', 'Maria draws every rectangle whose sides are whole numbers of centimeters and whose perimeter is 16 cm. A 1 cm by 7 cm rectangle counts, and a 7 cm by 1 cm rectangle is the same rectangle. How many of her rectangles are NOT squares?', '[]', '3', NULL, 'The side pairs that add to 8 are 1 and 7, 2 and 6, 3 and 5, and 4 and 4. That is 4 rectangles. Only the 4 by 4 rectangle is a square, so 3 are not squares.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 16: length + width = 8. Whole-number pairs: 1x7, 2x6, 3x5, 4x4. Squares: 4x4. Not squares: 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff0be521-92e5-4235-b113-a9ad45e51ebe', 'NC26.5.SGMR.1', 3, 'numeric', 'Use attributes to find a measurement', 'A quadrilateral is both a rectangle and a rhombus. Its perimeter is 52 cm. How long is each side, in centimeters?', '[]', '13', '52/4', 'A shape that is both a rectangle and a rhombus has four right angles and four equal sides, so it is a square. Each side is 52 divided by 4 = 13 cm.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both rectangle and rhombus = square, 4 equal sides: 52 / 4 = 13 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0d1c35b-310b-4269-822d-43634aba223d', 'NC26.5.SGMR.1', 3, 'numeric', 'Use attributes to find a measurement', 'A parallelogram has a perimeter of 64 cm. One pair of opposite sides is 3 times as long as the other pair. How long is each of the longer sides, in centimeters?', '[]', '24', '64/8*3', 'If a shorter side is s, a longer side is 3s, and the perimeter is 2 x (s + 3s) = 8s. So 8s = 64 and s = 8. A longer side is 3 x 8 = 24 cm.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides equal: short + long = 32, long = 3 x short, so 4 x short = 32, short = 8, long = 24 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3afccef1-d5d6-425e-9860-2f0f29dada3b', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that have an attribute', 'A box holds 12 cutouts: 3 squares, 2 rectangles that are not squares, 4 rhombuses that are not squares, and 3 parallelograms that are neither rectangles nor rhombuses. How many of the cutouts are parallelograms that are NOT rectangles?', '[]', '7', '4+3', 'Every cutout is a parallelogram. The squares and the other rectangles (3 + 2 = 5) are rectangles. The rest are not: 4 rhombuses and 3 other parallelograms, which is 4 + 3 = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelograms that are not rectangles: rhombuses that are not squares (4) + other parallelograms (3) = 7. Squares and rectangles are rectangles.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6015cd71-a07f-49be-9d10-66c95640f9f7', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that have an attribute', 'Dara draws six quadrilaterals: a square, a rectangle with sides of 9 cm and 5 cm, a rhombus with 7 cm sides and no right angles, a parallelogram with sides of 8 cm and 3 cm and no right angles, a rectangle with sides of 6 cm and 6 cm, and a trapezoid with exactly one pair of parallel sides. How many of the six shapes are squares?', '[]', '2', NULL, 'A square has four equal sides and four right angles. The first shape is a square, and the rectangle with sides of 6 cm and 6 cm also has four equal sides and four right angles. The other four are not squares. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Squares: the square, and the 6 by 6 rectangle (4 right angles, 4 equal sides). The 9 by 5 rectangle, rhombus with no right angles, parallelogram and trapezoid are not. 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcae5b68-5df3-448c-b6c0-1b9493964c0b', 'NC26.5.SGMR.1', 3, 'numeric', 'Count shapes that have an attribute', 'A mosaic has 20 tiles: 5 squares, 7 rectangles that are not squares, 3 rhombuses that are not squares, and the rest are parallelograms that are neither rectangles nor rhombuses. How many tiles do NOT have four equal sides?', '[]', '12', '7+(20-5-7-3)', 'The rest are 20 - 5 - 7 - 3 = 5 tiles. Tiles without four equal sides are the 7 rectangles that are not squares and those 5 parallelograms. That is 7 + 5 = 12 tiles.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other parallelograms: 20 - 5 - 7 - 3 = 5. Four equal sides: squares 5 + rhombuses 3 = 8. Not: 20 - 8 = 12 (7 rectangles + 5 parallelograms).","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ecc094cf-394f-4cbc-9b05-93516fd9918e', 'NC26.5.SGMR.1', 3, 'choice', 'Tell two categories apart', 'Which single question separates squares from all other rectangles?', '["Does it have four right angles?","Are opposite sides parallel?","Are opposite sides equal in length?","Are all four sides equal in length?"]', 'Are all four sides equal in length?', NULL, 'Every rectangle has four right angles, parallel opposite sides and equal opposite sides. Only a square also has all four sides equal.', 'checked', '{"lint":[],"solve":{"answer":"Are all four sides equal in length?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All rectangles have right angles, equal and parallel opposite sides. Only squares have all four sides equal.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bf9468d-9a0e-435e-b483-f336b83a566b', 'NC26.5.SGMR.1', 3, 'choice', 'Tell two categories apart', 'Rectangles and rhombuses have some attributes in common. Which attribute do BOTH always have?', '["Two pairs of parallel sides","Four right angles","Four equal sides","Exactly one pair of parallel sides"]', 'Two pairs of parallel sides', NULL, 'Rectangles and rhombuses are both parallelograms, so both always have two pairs of parallel sides. Rectangles need not have equal sides, and rhombuses need not have right angles.', 'checked', '{"lint":[],"solve":{"answer":"Two pairs of parallel sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both are parallelograms: two pairs of parallel sides. Right angles only rectangles; equal sides only rhombuses.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4949998-c556-4a49-847d-d559d77e98e4', 'NC26.5.SGMR.1', 3, 'choice', 'Combine clues to identify a shape', 'Which shape fits all three clues? Clue 1: It is a rectangle. Clue 2: Its perimeter is 20 cm. Clue 3: Its length is 5 cm.', '["A square with sides of 5 cm","A rectangle with sides of 7 cm and 3 cm","A rectangle with sides of 5 cm and 3 cm","A rhombus with no right angles"]', 'A square with sides of 5 cm', NULL, 'A rectangle with perimeter 20 cm has length plus width equal to 10 cm. With length 5 cm the width is 5 cm too, so it is a square. The 7 by 3 rectangle has no 5 cm side, the 5 by 3 rectangle has perimeter 16 cm, and a rhombus with no right angles is not a rectangle.', 'checked', '{"lint":[],"solve":{"answer":"A square with sides of 5 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter 20, length 5: width 10 - 5 = 5, so it is a 5 by 5 square, which is a rectangle. A: perimeter 16. C: length 7. D: not a rectangle.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cb18da1-d2cd-495e-aa7f-36213532f4eb', 'NC26.5.SGMR.1', 3, 'numeric', 'Combine clues to identify a shape', 'A mystery shape is a rhombus. Its perimeter is 3 times the perimeter of a square with sides of 4 cm. How long is each side of the rhombus, in centimeters?', '[]', '12', '3*4*4/4', 'The square''s perimeter is 4 x 4 = 16 cm. The rhombus''s perimeter is 3 x 16 = 48 cm. A rhombus has four equal sides, so each side is 48 divided by 4 = 12 cm.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square perimeter 16; 3 x 16 = 48; rhombus 4 equal sides: 48 / 4 = 12 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fab1e35-05e0-4dd1-9fb8-1e694919eb3c', 'NC26.5.SGMR.1', 3, 'choice', 'Combine clues to identify a shape', 'A parallelogram has a perimeter of 36 cm, and its sides are not all equal. Which could be its side lengths?', '["Four sides of 9 cm","Two sides of 11 cm and two sides of 7 cm","Two sides of 11 cm and two sides of 8 cm","Three sides of 11 cm and one side of 3 cm"]', 'Two sides of 11 cm and two sides of 7 cm', NULL, 'Two sides of 11 cm and two of 7 cm have opposite sides equal and total 22 + 14 = 36 cm. Four sides of 9 cm are all equal. Two of 11 and two of 8 total 38 cm. Three sides of 11 and one of 3 total 36 cm but opposite sides are not equal.', 'checked', '{"lint":[],"solve":{"answer":"Two sides of 11 cm and two sides of 7 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides equal. A: not a parallelogram (three equal, one different). B: 38. C: all equal (excluded). D: 11 + 11 + 7 + 7 = 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.817Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b6f7fe1-de6a-48a5-bda9-fe6729529972', 'NC26.5.SGMR.1', 3, 'numeric', 'Combine clues to identify a shape', 'Opposite sides of a parallelogram are equal in length. A parallelogram-shaped garden bed has two neighboring sides that are each 12 feet long. What is the distance around the garden bed, in feet?', '[]', '48', '4*12', 'The other two sides are equal to these, so all four sides are 12 feet. The distance around is 4 x 12 = 48 feet. (The bed is a rhombus.)', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite sides equal and neighbouring sides 12 and 12, so all four sides are 12. Perimeter 4 x 12 = 48.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('598736a6-ea9c-4566-a968-66ca7c56dad8', 'NC26.5.SGMR.1', 3, 'choice', 'Reason from the hierarchy', 'Ravi says: "If a quadrilateral has four equal sides, its opposite sides must be parallel." Which response is correct?', '["Ravi is wrong, because only squares and rectangles have parallel opposite sides","Ravi is right, because a quadrilateral with four equal sides is always a square","Ravi is right, because a quadrilateral with four equal sides is a rhombus, and every rhombus is a parallelogram","Ravi is wrong, because a rhombus does not have any pair of parallel sides"]', 'Ravi is right, because a quadrilateral with four equal sides is a rhombus, and every rhombus is a parallelogram', NULL, 'A quadrilateral with four equal sides is a rhombus, and a rhombus is a kind of parallelogram, so its opposite sides are parallel. It is not always a square, because its angles do not have to be right angles.', 'checked', '{"lint":[],"solve":{"answer":"Ravi is right, because a quadrilateral with four equal sides is a rhombus, and every rhombus is a parallelogram","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Four equal sides is a rhombus; a rhombus is a parallelogram, so opposite sides are parallel. Option 1 is wrong reasoning (not always a square).","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1a61931-de52-41e2-9caf-faf4fade149b', 'NC26.5.SGMR.1', 3, 'numeric', 'Count with overlapping groups', 'A box holds 20 shape cards. Every card shows a rectangle, a rhombus, or both. Squares count as rectangles and as rhombuses. 14 cards show rectangles and 11 cards show rhombuses. How many cards show squares?', '[]', '5', '14+11-20', 'A shape that is both a rectangle and a rhombus has 4 right angles and 4 equal sides, so it is a square, and every square is both. Adding 14 + 11 = 25 counts each square twice. There are only 20 cards, so 25 - 20 = 5 cards were counted twice. Those 5 cards show squares.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Mostly an overlapping-sets count (14+11-20); the quadrilateral idea (square = rectangle and rhombus) is used but the main skill is inclusion-exclusion, which may be tricky for Grade 5.","work":"Every card is rectangle, rhombus or both; both = square. 14 + 11 - 20 = 5 cards counted twice, i.e. squares.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b58ea95c-a233-4e9c-9a1b-e0d150022a6c', 'NC26.5.SGMR.1', 3, 'choice', 'Combine clues to identify a shape', 'A quadrilateral is a parallelogram. Which extra clue is enough to be sure that it is a rectangle?', '["Two sides next to each other are equal in length","Its perimeter is 24 centimeters","One of its angles is a right angle","Its opposite sides are equal in length"]', 'One of its angles is a right angle', NULL, 'In a parallelogram, the angle next to a right angle is also a right angle, and then the other two angles must match them. So one right angle makes all four right angles, which is a rectangle. Two equal neighboring sides would make a rhombus. Every parallelogram already has equal opposite sides, and a perimeter alone says nothing about the angles.', 'checked', '{"lint":[],"solve":{"answer":"One of its angles is a right angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A parallelogram with one right angle has all angles right (opposite equal, consecutive supplementary), so it is a rectangle. Equal neighbours gives a rhombus; opposite sides equal is already true; perimeter tells nothing.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69d9bb6f-7785-478a-961d-db96ec54be59', 'NC26.5.SGMR.2', 1, 'numeric', 'Read a coordinate', 'The point $(5, 2)$ is plotted on a coordinate plane. How many units above the x-axis is the point?', '[]', '2', NULL, 'In $(5, 2)$ the first number says how far right and the second number says how far up. The point is 2 units above the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y-coordinate is 2, so 2 units above the x-axis.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fae19af-9245-473b-a3fa-0a9e9b768e01', 'NC26.5.SGMR.2', 1, 'choice', 'Name a point reached by moving from the origin', 'Starting at the origin $(0, 0)$, you move 3 units right and 6 units up. Which ordered pair names where you are?', '["$(6, 3)$","$(3, 6)$","$(3, 9)$","$(0, 9)$"]', '$(3, 6)$', NULL, 'The first number is the move right (3) and the second is the move up (6), so you are at $(3, 6)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right 3 gives x = 3, up 6 gives y = 6: (3, 6).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e346e8e5-7213-4297-b165-91bb09a23b99', 'NC26.5.SGMR.2', 1, 'choice', 'Points on an axis', 'Which point is on the y-axis?', '["$(0, 5)$","$(5, 0)$","$(5, 5)$","$(2, 3)$"]', '$(0, 5)$', NULL, 'A point on the y-axis is 0 units right of it, so its first number is 0. That is $(0, 5)$. The point $(5, 0)$ is on the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Points on the y-axis have x = 0: (0, 5).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
