INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('554c3154-eeea-437b-b438-bfd2bf0a1076', 'NC26.5.SGMR.2', 1, 'choice', 'Ordered pairs from a real situation', 'A rule says that y is 2 more than x. Which ordered pair follows the rule?', '["$(5, 7)$","$(5, 10)$","$(7, 5)$","$(5, 3)$"]', '$(5, 7)$', NULL, 'For the pair $(5, 7)$, y = 7 is 2 more than x = 5. The others do not follow the rule.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = x + 2: (5, 7). (5,3) and (7,5) have y 2 less; (5,10) is double.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
