INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c03f658b-4e4a-47fc-8aa0-f2246f1a0990', 'NC26.5.SGMR.2', 1, 'choice', 'Compare the locations of points', 'Which point is farthest to the right: $(2, 9)$, $(8, 1)$, $(5, 5)$ or $(7, 7)$?', '["$(2, 9)$","$(8, 1)$","$(5, 5)$","$(7, 7)$"]', '$(8, 1)$', NULL, 'The farther right a point is, the greater its x-coordinate. The x-coordinates are 2, 8, 5 and 7, and 8 is the greatest.', 'checked', '{"lint":[],"solve":{"answer":"$(8, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Largest x-coordinate is 8: (8, 1).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
