INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b44afa7-cd9a-4e9a-96d1-e17793d26c66', 'NC26.5.SGMR.2', 2, 'choice', 'Plot a point by moving from the origin', 'Zoe plots a point by starting at the origin, moving up 7 units, and then moving right 4 units. She writes $(7, 4)$. Which statement is correct?', '["The point is $(4, 7)$, not $(7, 4)$.","Her ordered pair is correct.","The point is $(11, 0)$.","The point is $(7, 11)$."]', 'The point is $(4, 7)$, not $(7, 4)$.', NULL, 'Moving right 4 makes the x-coordinate 4, and moving up 7 makes the y-coordinate 7. The ordered pair is (x, y), so the point is $(4, 7)$.', 'checked', '{"lint":[],"solve":{"answer":"The point is $(4, 7)$, not $(7, 4)$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Up 7 and right 4 means x = 4, y = 7: (4, 7). Zoe reversed them.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
