INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80298c7a-b4e8-44e1-9bad-154d5d13c200', 'NC26.5.SGMR.2', 2, 'numeric', 'Area and perimeter of rectangles on the plane', 'A rectangular pool has corners at $(2, 1)$, $(12, 1)$, $(12, 6)$ and $(2, 6)$ on a plane where each unit is 1 meter. What is the area of the pool, in square meters?', '[]', '50', '(12-2)*(6-1)', 'The pool is 12 - 2 = 10 meters long and 6 - 1 = 5 meters wide. The area is 10 x 5 = 50 square meters.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 12 - 2 = 10, width 6 - 1 = 5. Area 50.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
