INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14e554d4-6e96-4a47-9216-531e2bf9152b', 'NC26.5.SGMR.2', 2, 'choice', 'Find a missing corner of a shape', 'A square has its top-left corner at $(3, 9)$ and each side is 5 units long. What is its bottom-left corner?', '["$(3, 4)$","$(8, 9)$","$(8, 4)$","$(3, 14)$"]', '$(3, 4)$', NULL, 'The bottom-left corner is directly below the top-left corner. Going down 5 gives a y-coordinate of 9 - 5 = 4, so it is $(3, 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom-left is 5 below the top-left: (3, 9 - 5) = (3, 4).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c55af97c-352c-4ebf-8e38-ead07a2cb6c8', 'NC26.5.SGMR.2', 2, 'numeric', 'Find a missing corner of a shape', 'A rectangle has horizontal and vertical sides. Two opposite corners are $(1, 1)$ and $(7, 5)$. How many units is the top-left corner above the x-axis?', '[]', '5', '5', 'The other two corners are $(1, 5)$ and $(7, 1)$. The top-left corner is $(1, 5)$, which is 5 units above the x-axis.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corners (1,1), (7,1), (7,5), (1,5). Top-left (1, 5), 5 units above the x-axis.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
