INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc514010-7ed7-4470-bfda-f90f7911fefb', 'NC26.5.SGMR.2', 2, 'choice', 'Move a point and measure a path', 'A frog is at $(1, 2)$. It hops 4 units right, then 3 units up, then 2 units left. What is the sum of its x-coordinate and its y-coordinate now?', '["8","10","12","5"]', '8', '1+4-2+2+3', 'The x-coordinate is 1 + 4 - 2 = 3. The y-coordinate is 2 + 3 = 5. The frog is at $(3, 5)$, and 3 + 5 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,2) -> (5,2) -> (5,5) -> (3,5). 3 + 5 = 8.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
