INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4370d644-866b-4a93-9bb0-b93f8937c5ad', 'NC26.5.SGMR.2', 2, 'numeric', 'Move a point and measure a path', 'A snail crawls from $(1, 1)$ up to $(1, 5)$ and then right to $(6, 5)$. How many more units does it crawl on the second part than on the first part?', '[]', '1', '(6-1)-(5-1)', 'The first part is 5 - 1 = 4 units. The second part is 6 - 1 = 5 units. The second part is 5 - 4 = 1 unit longer.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First part 5 - 1 = 4; second part 6 - 1 = 5; 5 - 4 = 1.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
