INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0df0fbfb-a8d9-402a-b9f2-87ebcc66e65d', 'NC26.5.SGMR.2', 2, 'choice', 'Ordered pairs from two number patterns', 'A pattern of ordered pairs is $(1, 4)$, $(2, 5)$, $(3, 6)$, $(4, 7)$. Which rule describes how each y-coordinate is related to its x-coordinate?', '["y is 3 more than x","y is 3 times x","y is 4 more than x","y is 4 times x"]', 'y is 3 more than x', NULL, 'In every pair the y-coordinate is 3 greater than the x-coordinate: 1 + 3 = 4, 2 + 3 = 5, and so on.', 'checked', '{"lint":[],"solve":{"answer":"y is 3 more than x","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4-1 = 5-2 = 6-3 = 7-4 = 3: y is 3 more than x.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92c5cc22-0563-40dc-bc2a-13ea8e36ad88', 'NC26.5.SGMR.2', 2, 'numeric', 'Ordered pairs from two number patterns', 'Rule 1 starts at 2 and adds 3 each time: 2, 5, 8, 11. Rule 2 starts at 4 and adds 6 each time: 4, 10, 16, 22. Matching numbers make ordered pairs (Rule 1, Rule 2). What is the y-coordinate of the pair whose x-coordinate is 14?', '[]', '28', '2*14', 'Continue both rules. Rule 1: 2, 5, 8, 11, 14. Rule 2: 4, 10, 16, 22, 28. The pair is $(14, 28)$, so the y-coordinate is 28. (Each y-coordinate is twice its x-coordinate.)', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rule 1: 2, 5, 8, 11, 14 (5th). Rule 2: 4, 10, 16, 22, 28 (5th). y = 28.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af70ea2b-3320-4b89-8177-4df4f50d50d8', 'NC26.5.SGMR.2', 2, 'numeric', 'Ordered pairs from two number patterns', 'Pattern A starts at 0 and adds 4 each time. Pattern B starts at 0 and adds 10 each time. Matching numbers make ordered pairs (A, B). What is the sum of the x-coordinate and the y-coordinate of the 6th pair, counting $(0, 0)$ as the first pair?', '[]', '70', '5*4+5*10', 'The 6th pair comes after 5 steps. Pattern A is 5 x 4 = 20 and Pattern B is 5 x 10 = 50, so the pair is $(20, 50)$. The sum is 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6th pair is after 5 steps: A = 20, B = 50. 20 + 50 = 70.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('add5261e-0301-437d-bee5-ab253073ff4d', 'NC26.5.SGMR.2', 2, 'choice', 'Ordered pairs from a real situation', 'A car travels 40 miles each hour. A point (hours, miles) is plotted for each whole number of hours. Which point is on the graph?', '["$(3, 43)$","$(120, 3)$","$(3, 120)$","$(40, 3)$"]', '$(3, 120)$', NULL, 'In 3 hours the car travels 3 x 40 = 120 miles. With hours first, the point is $(3, 120)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 120)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 hours x 40 = 120 miles: (3, 120).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
