INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('483838df-e44c-4079-8011-d64eecaf9841', 'NC26.5.SGMR.2', 2, 'choice', 'Compare the locations of points', 'Four points are plotted: $(4, 6)$, $(9, 3)$, $(2, 8)$ and $(7, 5)$. Which point is the second closest to the x-axis?', '["$(9, 3)$","$(4, 6)$","$(7, 5)$","$(2, 8)$"]', '$(7, 5)$', NULL, 'The distance from the x-axis is the y-coordinate. In order from closest, the y-coordinates are 3, 5, 6 and 8. The second closest is the point with y-coordinate 5, which is $(7, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(7, 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance from x-axis is y: 6, 3, 8, 5. Closest (9,3), second closest (7,5).","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
