INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0149e4f-4057-4c0b-83d7-7aad84bd9d37', 'NC26.5.SGMR.2', 3, 'numeric', 'Distance along a horizontal or vertical line', 'On a plane where each unit is 1 mile, a runner goes from $(2, 4)$ right to $(10, 4)$. Then she turns around and runs 3 miles back to the left. How many miles from her starting point is she now?', '[]', '5', '10-2-3', 'She first goes 10 - 2 = 8 miles right of the start. Then she runs 3 miles back, so she is 8 - 3 = 5 miles from the start.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From x = 2 to x = 10 is 8 miles; back 3 to x = 7. Distance from start (2, 4) is 7 - 2 = 5.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
