INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8572752e-77fd-486c-be23-bd0a6007a735', 'NC26.5.SGMR.2', 3, 'choice', 'Ordered pairs from two number patterns', 'Pattern A starts at 0 and adds 1: 0, 1, 2, 3, 4. Pattern B starts at 1 and adds 2: 1, 3, 5, 7, 9. Matching numbers make ordered pairs (A, B). Which ordered pair is NOT one of them?', '["$(2, 5)$","$(4, 8)$","$(3, 7)$","$(1, 3)$"]', '$(4, 8)$', NULL, 'Matching the numbers gives $(0, 1)$, $(1, 3)$, $(2, 5)$, $(3, 7)$ and $(4, 9)$. The pair $(4, 8)$ is not on the list.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pairs: (0,1), (1,3), (2,5), (3,7), (4,9). (4, 8) is not one.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
