INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9942e5b2-ee20-4354-9d09-011b1798aa44', 'NC26.5.SGMR.2', 3, 'numeric', 'Ordered pairs from two number patterns', 'Pattern A starts at 0 and adds 3 each time. Pattern B starts at 0 and adds 12 each time. In every ordered pair (A, B) other than $(0, 0)$, how many times as large as the x-coordinate is the y-coordinate?', '[]', '4', '12/3', 'The pairs are $(3, 12)$, $(6, 24)$, $(9, 36)$ and so on. Each y-coordinate is 12 / 3 = 4 times the x-coordinate.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After n steps (3n, 12n); 12n / 3n = 4.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a610c957-b039-4382-9924-d87e4e388800', 'NC26.5.SGMR.2', 3, 'numeric', 'Ordered pairs from two number patterns', 'Pattern A starts at 0 and adds 5 each time. Pattern B starts at 0 and adds 15 each time. Matching numbers make ordered pairs (A, B). One of the pairs has a y-coordinate of 90. What is its x-coordinate?', '[]', '30', '90/15*5', 'Pattern B reaches 90 after 90 / 15 = 6 steps. In 6 steps Pattern A is 6 x 5 = 30. The pair is $(30, 90)$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 / 15 = 6 steps; x = 6 x 5 = 30.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
