INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6839ad29-93de-49f4-aa86-dc0972b8eb29', 'NC26.5.SGMR.2', 3, 'choice', 'Ordered pairs from two number patterns', 'Which two rules make the ordered pairs $(0, 0)$, $(2, 10)$, $(4, 20)$, $(6, 30)$?', '["x starts at 0 and adds 2; y starts at 0 and adds 5","x starts at 0 and adds 10; y starts at 0 and adds 2","x starts at 0 and adds 2; y starts at 0 and adds 10","x starts at 0 and adds 2; y starts at 0 and adds 8"]', 'x starts at 0 and adds 2; y starts at 0 and adds 10', NULL, 'The x-coordinates go 0, 2, 4, 6, so x adds 2. The y-coordinates go 0, 10, 20, 30, so y adds 10.', 'checked', '{"lint":[],"solve":{"answer":"x starts at 0 and adds 2; y starts at 0 and adds 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: 0, 2, 4, 6 adds 2; y: 0, 10, 20, 30 adds 10.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
