INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dc92521-8635-4c76-9391-261dffd7402f', 'NC26.5.SGMR.2', 3, 'numeric', 'Ordered pairs from two number patterns', 'Pattern A starts at 0 and adds 6 each time. Pattern B starts at 0 and adds 4 each time. Matching numbers make ordered pairs (A, B). What is the y-coordinate of the pair whose x-coordinate is 36?', '[]', '24', '36/6*4', 'Pattern A reaches 36 after 36 / 6 = 6 steps. In 6 steps Pattern B is 6 x 4 = 24. The pair is $(36, 24)$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 / 6 = 6 steps; y = 6 x 4 = 24.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
