INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a87678e-ed57-460a-88c9-17528a43b8cb', 'NC26.5.SGMR.2', 3, 'numeric', 'Ordered pairs from a real situation', 'Points (week, dollars saved) are plotted: $(1, 6)$, $(2, 12)$, $(3, 18)$. If the pattern continues, in which week do the savings first reach 96 dollars?', '[]', '16', '96/6', 'The savings grow by 6 dollars each week, so the amount is 6 times the week number. 96 / 6 = 16, so it is week 16.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Savings = 6 x week; 96 / 6 = 16. Week 15 is 90, so 16 is first.","run_id":"claude-code","at":"2026-10-17T20:08:07.973Z"}}', 'ai', NULL, NULL)
