INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3979da2-b6c8-4da9-ba89-59b94e713e6d', 'NC26.5.SGMR.3', 1, 'choice', 'Check that a conversion is reasonable', 'Sam changes 4 feet to inches. Will the number of inches be greater than 4 or less than 4?', '["Less than 4, because an inch is shorter than a foot","Greater than 4, because an inch is longer than a foot","Equal to 4, because both units measure length","Greater than 4, because an inch is shorter than a foot"]', 'Greater than 4, because an inch is shorter than a foot', NULL, 'An inch is shorter than a foot, so it takes more inches than feet to cover the same length. There will be more than 4 inches (in fact 48).', 'checked', '{"lint":[],"solve":{"answer":"Greater than 4, because an inch is shorter than a foot","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inches are smaller than feet, so it takes more of them: 4 ft = 48 in > 4. Only option 3 has the right result and the right reason.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
