INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f673ff8b-a308-475e-b312-056187247494', 'NC26.5.SGMR.3', 1, 'choice', 'Check that a conversion is reasonable', 'Which answer is reasonable for changing 5 meters to centimeters?', '["About 0.05 centimeters","About 500 centimeters","About 5 centimeters","About 50 centimeters"]', 'About 500 centimeters', NULL, 'A centimeter is much shorter than a meter (100 of them make a meter), so 5 meters is about $5 \times 100 = 500$ centimeters. The other answers are far too small.', 'checked', '{"lint":[],"solve":{"answer":"About 500 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 m x 100 cm/m = 500 cm. \"About 500\" is the reasonable one.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
