INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e30f5a4-f118-4713-a33e-b5fd9feac35c', 'NC26.5.SGMR.3', 1, 'choice', 'Check that a conversion is reasonable', 'Ivy changes 2 liters to milliliters and gets 0.002 milliliters. Why is her answer NOT reasonable?', '["A milliliter is much smaller than a liter, so there should be many more milliliters than liters","A liter is much smaller than a milliliter, so the answer should be even smaller","Liters cannot be changed to milliliters","Changing units never changes the number"]', 'A milliliter is much smaller than a liter, so there should be many more milliliters than liters', NULL, 'A milliliter is a tiny amount, so 2 liters must be a big number of milliliters (2,000). Ivy divided when she should have multiplied.', 'checked', '{"lint":[],"solve":{"answer":"A milliliter is much smaller than a liter, so there should be many more milliliters than liters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 L = 2,000 mL. A milliliter is smaller, so the number of mL must be larger than 2, not 0.002.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
