INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88669dc8-fbdf-4137-a487-abb9f7513d85', 'NC26.5.SGMR.3', 2, 'choice', 'Check that a conversion is reasonable', 'Zoe changes 120 inches to feet. She multiplies 120 by 12 and gets 1,440 feet. What should Zoe do instead? (1 foot = 12 inches)', '["Multiply 120 by 12, because there are 12 inches in a foot","Add 120 and 12, because she is combining the units","Subtract 12 from 120, because feet are smaller than inches","Divide 120 by 12, because a foot is longer than an inch, so there are fewer feet than inches"]', 'Divide 120 by 12, because a foot is longer than an inch, so there are fewer feet than inches', NULL, 'A foot is longer than an inch, so the number of feet must be smaller than 120. $120 \div 12 = 10$ feet.', 'checked', '{"lint":[],"solve":{"answer":"Divide 120 by 12, because a foot is longer than an inch, so there are fewer feet than inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Going to a larger unit means fewer of them: 120 / 12 = 10 ft. Option 2 says divide, with the right reason.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51773981-1987-4975-b2d4-41e208fba28b', 'NC26.5.SGMR.3', 2, 'choice', 'Check that a conversion is reasonable', 'Which statement does NOT make sense?', '["5 kilometers = 5,000 meters","3 pounds = 3 ounces","2 yards = 6 feet","4 liters = 4,000 milliliters"]', '3 pounds = 3 ounces', NULL, 'A pound is much heavier than an ounce (16 ounces make a pound), so 3 pounds must be more than 3 ounces: it is 48 ounces. The other three statements are correct.', 'checked', '{"lint":[],"solve":{"answer":"3 pounds = 3 ounces","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 L = 4,000 mL true; 3 lb = 48 oz, not 3 oz (false); 2 yd = 6 ft true; 5 km = 5,000 m true. The one that does not make sense is 3 lb = 3 oz.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('624f13b2-f8e6-4447-b564-f9100b812d72', 'NC26.5.SGMR.3', 2, 'numeric', 'Check that a conversion is reasonable', 'Nora changes 36 inches to feet and gets 432 feet. To check, she changes 432 feet back to inches. How many inches does she get? (1 foot = 12 inches)', '[]', '5184', '432*12', '$432 \times 12 = 5{,}184$ inches. That is not 36, so 432 feet is wrong. (The right answer is $36 \div 12 = 3$ feet.)', 'checked', '{"lint":[],"solve":{"answer":"5184","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"432 ft x 12 in/ft = 5,184 in, which is not 36, showing her answer was wrong.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
