INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbb6b91e-e182-4bb0-a929-c9e3f467577c', 'NC26.5.SGMR.3', 2, 'numeric', 'Check that a conversion is reasonable', 'A bottle of water holds 500 milliliters. Kim estimates that it holds about 5 liters. Her estimate is how many times as large as the real amount? (1 liter = 1,000 milliliters)', '[]', '10', '5*1000/500', '5 liters is $5 \times 1{,}000 = 5{,}000$ milliliters. Compare with 500 milliliters: $5{,}000 \div 500 = 10$, so her estimate is 10 times too large.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 L = 5,000 mL; 5,000 / 500 = 10 times as large.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
