INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86ec7c56-fb18-45ee-a62b-babaf5cd563c', 'NC26.5.SGMR.3', 3, 'choice', 'Check that a conversion is reasonable', 'Which statement is true?', '["The number of cups in a jug is greater than the number of fluid ounces in the same jug","The number of feet in a road is greater than the number of inches in the same road","The number of pints in a tank is greater than the number of gallons in the same tank","The number of grams in a bag is less than the number of kilograms in the same bag"]', 'The number of pints in a tank is greater than the number of gallons in the same tank', NULL, 'The smaller the unit, the greater the number of them. A pint is smaller than a gallon, so there are more pints. A cup is bigger than a fluid ounce, a foot is bigger than an inch, and a gram is smaller than a kilogram, so the other three statements are backwards.', 'checked', '{"lint":[],"solve":{"answer":"The number of pints in a tank is greater than the number of gallons in the same tank","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grams are smaller than kilograms, so more grams (A false); cups are larger than fl oz, so fewer cups (B false); feet are larger than inches, so fewer feet (C false); pints are smaller than gallons, so more pints (D true).","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('953a241f-9392-4a23-ab74-3075a757f052', 'NC26.5.SGMR.3', 3, 'numeric', 'Check that a conversion is reasonable', 'Ruth changes 8 kilograms to grams and gets 800 grams. By what number should she multiply her answer to correct it? (1 kilogram = 1,000 grams)', '[]', '10', '8*1000/800', 'The correct answer is $8 \times 1{,}000 = 8{,}000$ grams. Since $8{,}000 \div 800 = 10$, her answer must be multiplied by 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct: 8 x 1,000 = 8,000 g. 8,000 / 800 = 10, so multiply by 10.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64fa67e0-6c9b-4371-9aa8-04e19906e376', 'NC26.5.SGMR.3', 3, 'choice', 'Check that a conversion is reasonable', 'Dana changes 2 miles to feet and gets 10,560 feet. Marc changes 2 miles to feet and gets 2,640 feet. (1 mile = 5,280 feet) Whose answer is reasonable?', '["Marc''s, because 2 miles should be less than 5,280 feet","Both, because they used the same units","Neither, because miles cannot be changed to feet","Dana''s, because 2 miles should be more than 5,280 feet"]', 'Dana''s, because 2 miles should be more than 5,280 feet', NULL, 'One mile is 5,280 feet, so 2 miles must be more than 5,280 feet. Dana''s 10,560 feet is $2 \times 5{,}280$. Marc divided instead of multiplying.', 'checked', '{"lint":[],"solve":{"answer":"Dana''s, because 2 miles should be more than 5,280 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 mi = 2 x 5,280 = 10,560 ft. Dana is right; 2 miles must be more than 1 mile = 5,280 ft, so 2,640 is too small.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9c77d5b-1f60-4c55-9024-71bab96b3438', 'NC26.5.SGMR.3', 3, 'choice', 'Compare measurements in different units', 'Three boards are 2 yards, 5 feet and 70 inches long. Which list puts them in order from longest to shortest? (1 yard = 3 feet, 1 foot = 12 inches)', '["2 yards, 70 inches, 5 feet","70 inches, 2 yards, 5 feet","5 feet, 70 inches, 2 yards","2 yards, 5 feet, 70 inches"]', '2 yards, 70 inches, 5 feet', NULL, 'In inches the boards are $2 \times 36 = 72$, $5 \times 12 = 60$ and 70. From longest to shortest: 72 (2 yards), 70, 60 (5 feet).', 'checked', '{"lint":[],"solve":{"answer":"2 yards, 70 inches, 5 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 yd = 6 ft = 72 in; 5 ft = 60 in; 70 in. Longest to shortest: 72, 70, 60 = 2 yd, 70 in, 5 ft.","run_id":"claude-code","at":"2026-10-17T19:22:28.446Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
