INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cdf1b2b9-8a1a-4ad5-b064-0f3710bec686', 'NC26.5.SGMR.4', 1, 'choice', 'Volume from the area of the base and the height', 'The base of a prism has an area of $B$ square units, and the prism has a height of $h$ units. Which expression gives its volume?', '["$B + h$","$B \\div h$","$B \\times h$","$B - h$"]', '$B \times h$', NULL, 'The base area tells how many unit cubes make one layer, and the height tells how many layers there are, so the volume is $B \times h$.', 'checked', '{"lint":[],"solve":{"answer":"$B \\times h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = B x h.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
