VALUES ('ad85ccb4-27bb-4261-bbdd-73bc41c12d13', 'NC26.5.SGMR.4', 1, 'choice', 'Compare volumes and see how volume changes', 'Box A is 5 cm long, 2 cm wide and 2 cm tall. Box B is 3 cm long, 3 cm wide and 2 cm tall. Which box has the greater volume?', '["Box B","Box A","They have the same volume","There is not enough information"]', 'Box A', NULL, 'Box A: $5 \times 2 \times 2 = 20$ cubic centimeters. Box B: $3 \times 3 \times 2 = 18$. Box A is greater.', 'checked', '{"lint":[],"solve":{"answer":"Box A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5x2x2 = 20; B: 3x3x2 = 18. A is greater.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
