INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e00300f0-ed11-47f3-9052-2cb897a6bb61', 'NC26.5.SGMR.4', 2, 'choice', 'Understand volume and cubic units', 'Which statement correctly tells the difference between area and volume?', '["Area counts the unit cubes that fill a solid, and volume counts the unit squares that cover a flat shape","Area and volume both count unit squares","Area is measured in cubic units, and volume is measured in square units","Area counts the unit squares that cover a flat shape, and volume counts the unit cubes that fill a solid"]', 'Area counts the unit squares that cover a flat shape, and volume counts the unit cubes that fill a solid', NULL, 'Area is the number of unit squares that cover a flat shape (square units). Volume is the number of unit cubes that fill a solid (cubic units).', 'checked', '{"lint":[],"solve":{"answer":"Area counts the unit squares that cover a flat shape, and volume counts the unit cubes that fill a solid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area counts unit squares covering a flat shape; volume counts unit cubes filling a solid. Option D; option C swaps them.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
