INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c747611c-8248-4750-b8fb-aab63104cfd9', 'NC26.5.SGMR.4', 2, 'choice', 'Find a missing dimension from the volume', 'A box has a volume of 24 cubic feet and is 2 feet tall. Which could be its length and its width?', '["12 feet and 2 feet","6 feet and 4 feet","4 feet and 3 feet","3 feet and 3 feet"]', '4 feet and 3 feet', NULL, 'The base area must be $24 \div 2 = 12$ square feet. Only $4 \times 3 = 12$ works; the other pairs give base areas 24, 24 and 9.', 'checked', '{"lint":[],"solve":{"answer":"4 feet and 3 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area must be 24 / 2 = 12. 12x2 = 24, 6x4 = 24, 4x3 = 12, 3x3 = 9. Only 4 ft and 3 ft.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
