INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4b079a4-70aa-4dc9-ba49-e568fe88698e', 'NC26.5.SGMR.4', 2, 'numeric', 'Volume of a composite solid', 'A planter has two sections. One section is 10 inches long, 6 inches wide and 5 inches tall. The other section is 4 inches long, 6 inches wide and 5 inches tall. What is the volume of the whole planter, in cubic inches?', '[]', '420', '10*6*5+4*6*5', 'The first section is $10 \times 6 \times 5 = 300$ and the second is $4 \times 6 \times 5 = 120$. Together: $300 + 120 = 420$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"420","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x6x5 = 300; 4x6x5 = 120; total 420 cubic inches.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
