INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec4b5546-67ac-4c1e-a92d-ab6283b2839b', 'NC26.5.SGMR.4', 2, 'numeric', 'Volume of a composite solid', 'A solid is made by joining a cube and a slab. The cube has edges that are each 5 cm long. The slab is 5 cm long, 5 cm wide and 2 cm tall. What is the volume of the solid, in cubic centimeters?', '[]', '175', '5*5*5+5*5*2', 'The cube is $5 \times 5 \times 5 = 125$ and the slab is $5 \times 5 \times 2 = 50$. Together: $125 + 50 = 175$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"175","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 5x5x5 = 125; slab 5x5x2 = 50; total 175 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
