VALUES ('2d8e98e5-c858-401e-8a72-d03626bc1e6a', 'NC26.5.SGMR.4', 2, 'choice', 'Pack a box with unit cubes in layers', 'Which box can be filled exactly with 60 unit cubes? (length by width by height, in cubes)', '["5 by 4 by 4","5 by 4 by 3","6 by 5 by 3","4 by 4 by 3"]', '5 by 4 by 3', NULL, '$5 \times 4 \times 3 = 60$. The other boxes hold 80, 90 and 48 cubes.', 'checked', '{"lint":[],"solve":{"answer":"5 by 4 by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x4x3 = 60; 5x4x4 = 80; 6x5x3 = 90; 4x4x3 = 48. Answer 5 by 4 by 3.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
