INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf4ddee2-1c61-4d61-b890-291f1e3cd209', 'NC26.5.SGMR.4', 2, 'numeric', 'Compare volumes and see how volume changes', 'The volume of a rectangular prism is 18 cubic centimeters. A new prism has a length twice as long and a width twice as long as the first prism, with the same height. What is the volume of the new prism, in cubic centimeters?', '[]', '72', '18*2*2', 'Doubling the length doubles the volume, and doubling the width doubles it again: $18 \times 2 \times 2 = 72$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling length and width multiplies volume by 2 x 2 = 4: 18 x 4 = 72.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('360deb32-12f3-4d93-9ed8-830efc70e037', 'NC26.5.SGMR.4', 2, 'choice', 'Compare volumes and see how volume changes', 'The height of a box is made 3 times as tall. Its length and width stay the same. What happens to the volume of the box?', '["It stays the same","It is 9 times as great","It is 3 times as great","It is one third as great"]', 'It is 3 times as great', NULL, 'Each layer stays the same, but there are 3 times as many layers, so the volume is 3 times as great.', 'checked', '{"lint":[],"solve":{"answer":"It is 3 times as great","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = l x w x h; h x 3 makes V x 3.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9479be2c-ec9a-453d-90dd-85c10b47b37b', 'NC26.5.SGMR.4', 2, 'choice', 'Compare volumes and see how volume changes', 'Box A is 6 cm long, 4 cm wide and 3 cm tall. Box B is 5 cm long, 5 cm wide and 3 cm tall. How many more cubic centimeters does the larger box hold than the smaller box?', '["72","3","75","147"]', '3', '5*5*3-6*4*3', 'Box A holds $6 \times 4 \times 3 = 72$ and Box B holds $5 \times 5 \times 3 = 75$. The larger box holds $75 - 72 = 3$ more.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6x4x3 = 72; B: 5x5x3 = 75. 75 - 72 = 3.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b44c4541-fa7d-4464-baa7-bfa249d8bccf', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume of a composite solid', 'Two rectangular prisms are joined to make one solid. They touch along a face but do not overlap. One prism is 6 cm by 4 cm by 3 cm. The other is 5 cm by 2 cm by 3 cm. What is the volume of the whole solid, in cubic centimeters?', '[]', '102', '6*4*3+5*2*3', 'First prism: $6 \times 4 \times 3 = 72$. Second prism: $5 \times 2 \times 3 = 30$. Add the volumes: $72 + 30 = 102$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"102","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 3 = 72; 5 x 2 x 3 = 30; total 72 + 30 = 102 (no overlap).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d49dab1-86e0-4dd7-9029-194641b547f9', 'NC26.5.SGMR.4', 3, 'numeric', 'How volume changes when the edges are doubled', 'A cube has a volume of 27 cubic centimeters. A second cube has edges that are twice as long as the edges of the first cube. What is the volume of the second cube, in cubic centimeters?', '[]', '216', '(2*3)^3', 'The first cube has edges of 3 cm because $3 \times 3 \times 3 = 27$. The second cube has edges of 6 cm, so its volume is $6 \times 6 \times 6 = 216$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First cube edge 3 cm (3 x 3 x 3 = 27). Second edge 6 cm: 6 x 6 x 6 = 216.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c69cd36b-cdbd-43ed-93b2-0baf15f2864a', 'NC26.5.SGMR.4', 3, 'choice', 'Volume of a partly filled prism', 'A tank is 10 feet long, 6 feet wide and 4 feet tall. It is filled with water to a depth of 3 feet. How many cubic feet of water are in the tank?', '["240","60","72","180"]', '180', '10*6*3', 'The water forms a prism that is 10 feet by 6 feet by 3 feet. Its volume is $10 \times 6 \times 3 = 180$ cubic feet. (240 is the volume of the whole tank.)', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Water is 10 x 6 x 3 = 180 cubic feet (not full height 4).","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
