INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff02e970-d00b-44b1-9950-c71002e947b1', 'NC26.5.SGMR.4', 3, 'numeric', 'Understand volume and cubic units', 'A prism built from unit cubes is 6 cubes long, 5 cubes wide and 4 cubes tall. How many of its unit cubes are NOT in the top layer or the bottom layer?', '[]', '60', '6*5*2', 'Each layer has $6 \times 5 = 30$ cubes. Taking away the top and bottom layers leaves 2 layers: $2 \times 30 = 60$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each layer is 6 x 5 = 30 cubes; 4 layers. Excluding top and bottom leaves 2 layers: 2 x 30 = 60.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
