INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d00da9b8-4a91-424c-a45d-3345639ca83b', 'NC26.5.SGMR.4', 3, 'choice', 'Understand volume and cubic units', 'Which statement is true about the volume of a solid?', '["It is measured in cubic units, because it tells how many unit cubes fill the solid","It tells how many unit squares cover the outside of the solid","It is the distance around the bottom of the solid","It depends only on the height of the solid"]', 'It is measured in cubic units, because it tells how many unit cubes fill the solid', NULL, 'Volume is the amount of space inside a solid, counted in unit cubes (cubic units). Covering the outside is surface area, the distance around the bottom is perimeter, and volume depends on length, width and height.', 'checked', '{"lint":[],"solve":{"answer":"It is measured in cubic units, because it tells how many unit cubes fill the solid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume = number of unit cubes filling the solid, in cubic units. Others describe surface area, height only, perimeter.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f432b382-a9dc-48af-9ada-80a874f07c63', 'NC26.5.SGMR.4', 3, 'numeric', 'Understand volume and cubic units', 'A solid prism made of unit cubes has 3 layers. Each layer is 4 cubes by 6 cubes. Mark takes 7 cubes out of the solid. How many cubes are left?', '[]', '65', '3*4*6-7', 'There are $3 \times 4 \times 6 = 72$ cubes at first. After taking out 7, there are $72 - 7 = 65$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 6 = 24 per layer; 3 layers = 72; 72 - 7 = 65.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd6c5507-a5ef-4c4f-b3db-fd9b6be96df9', 'NC26.5.SGMR.4', 3, 'numeric', 'Understand volume and cubic units', 'A prism made of unit cubes is 3 cubes long and 3 cubes wide, and it has 4 layers. How many more cubes does Sara need to add to make it 6 layers tall?', '[]', '18', '3*3*2', 'Each layer has $3 \times 3 = 9$ cubes. Two more layers need $2 \times 9 = 18$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each layer 3 x 3 = 9; from 4 to 6 layers is 2 more layers: 2 x 9 = 18.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
