VALUES ('2d509a85-88d2-49fe-aefd-eddfdf0b6dd6', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume of a rectangular prism from length, width and height', 'A gift box measures 14 centimeters by 9 centimeters by 5 centimeters. What is its volume, in cubic centimeters?', '[]', '630', '14*9*5', '$14 \times 9 = 126$, and $126 \times 5 = 630$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"630","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 x 9 = 126; 126 x 5 = 630 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
