INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6c71d66-51c9-455b-90e2-43c919d16a6f', 'NC26.5.SGMR.4', 3, 'choice', 'Volume of a rectangular prism from length, width and height', 'Which rectangular prism has the greatest volume? (length by width by height, in centimeters)', '["10 by 4 by 3","6 by 5 by 5","8 by 8 by 2","9 by 4 by 4"]', '6 by 5 by 5', NULL, 'The volumes are $10 \times 4 \times 3 = 120$, $6 \times 5 \times 5 = 150$, $8 \times 8 \times 2 = 128$ and $9 \times 4 \times 4 = 144$. The greatest is 150.', 'checked', '{"lint":[],"solve":{"answer":"6 by 5 by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x8x2 = 128; 6x5x5 = 150; 10x4x3 = 120; 9x4x4 = 144. Greatest: 6 by 5 by 5.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
