INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b696dcc-ffa4-42ca-a1aa-68ce902839ae', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume from the area of the base and the height', 'A prism has a base area of 125 square centimeters and a height of 18 centimeters. What is its volume, in cubic centimeters?', '[]', '2250', '125*18', '$125 \times 18 = 125 \times 20 - 125 \times 2 = 2{,}500 - 250 = 2{,}250$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"2250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 x 18 = 2,250 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
