INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83ca920b-e955-4489-8d78-afde7d5c0dd3', 'NC26.5.SGMR.4', 3, 'choice', 'Volume from the area of the base and the height', 'A box has a base area of 24 square inches. A second box has the same height, but its base area is twice as large. How does the volume of the second box compare with the volume of the first box?', '["It is the same","It is twice as great","It is half as great","It is four times as great"]', 'It is twice as great', NULL, 'Volume is base area times height. With the same height, doubling the base area doubles the volume.', 'checked', '{"lint":[],"solve":{"answer":"It is twice as great","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = B x h; same h, B doubled, so V doubles: twice as great.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
