INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e270a49-c821-46c8-9b45-64eb6c05be7c', 'NC26.5.SGMR.4', 3, 'numeric', 'Find a missing dimension from the volume', 'Prism A is 12 centimeters long, 5 centimeters wide and 4 centimeters tall. Prism B has the same volume as Prism A. Prism B is 10 centimeters long and 6 centimeters wide. How tall is Prism B, in centimeters?', '[]', '4', '12*5*4/(10*6)', 'Prism A has volume $12 \times 5 \times 4 = 240$ cubic centimeters. For Prism B, $10 \times 6 \times h = 240$, so $h = 240 \div 60 = 4$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 12 x 5 x 4 = 240. B base 10 x 6 = 60; 240 / 60 = 4 cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
