INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f009b2d-0a7c-4aa9-aa96-5149a3bbf895', 'NC26.5.SGMR.4', 3, 'choice', 'Volume of a composite solid', 'A pool is 12 meters long, 8 meters wide and 2 meters deep. A block of concrete that is 3 meters long, 8 meters wide and 1 meter tall sits on the bottom of the pool. How many cubic meters of water fill the pool to the top?', '["192","168","24","216"]', '168', '12*8*2-3*8*1', 'The whole pool is $12 \times 8 \times 2 = 192$. The concrete takes up $3 \times 8 \times 1 = 24$ cubic meters, so the water is $192 - 24 = 168$ cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pool 12x8x2 = 192; block 3x8x1 = 24 (fits: 1 m < 2 m depth); water 192 - 24 = 168.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4016dde1-b287-48c2-be63-f8efe2ba813a', 'NC26.5.SGMR.4', 3, 'choice', 'Volume of a composite solid', 'Two prisms are joined without overlapping. Prism A is 8 cm by 6 cm by 3 cm. Prism B is 4 cm by 6 cm by 5 cm. What is the volume of the whole solid, in cubic centimeters?', '["17,280","144","120","264"]', '264', '8*6*3+4*6*5', 'Prism A is $8 \times 6 \times 3 = 144$ and Prism B is $4 \times 6 \times 5 = 120$. Together: $144 + 120 = 264$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"264","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 8x6x3 = 144; B 4x6x5 = 120; total 264.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
