INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aca52c1-1963-41d1-9423-29856b97ceae', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume of a composite solid', 'A tower is made of two prisms stacked together. The bottom prism is 10 cm long, 10 cm wide and 4 cm tall. The top prism is 6 cm long, 6 cm wide and 5 cm tall. What is the volume of the tower, in cubic centimeters?', '[]', '580', '10*10*4+6*6*5', 'The bottom prism is $10 \times 10 \times 4 = 400$ and the top prism is $6 \times 6 \times 5 = 180$. Together: $400 + 180 = 580$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"580","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom 10x10x4 = 400; top 6x6x5 = 180; total 580 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
