INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('daf87ed6-6b91-4965-961b-6872739e19b3', 'NC26.5.SGMR.4', 3, 'choice', 'Pack a box with unit cubes in layers', 'A box is 8 centimeters long, 6 centimeters wide and 4 centimeters tall. It is filled with cubes that each have edges 2 centimeters long. How many cubes fit in the box?', '["24","192","96","12"]', '24', '(8/2)*(6/2)*(4/2)', 'Along the length, 4 cubes fit; along the width, 3 fit; and in the height, 2 fit. So $4 \times 3 \times 2 = 24$ cubes. The number 192 would be 1-centimeter cubes, and 12 is only one layer.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8/2 = 4, 6/2 = 3, 4/2 = 2; 4 x 3 x 2 = 24 cubes (check 192 / 8 = 24).","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6e76996-cfa8-4227-87b9-bf7f04ec9b3f', 'NC26.5.SGMR.4', 3, 'choice', 'Pack a box with unit cubes in layers', 'Ravi fills a box with 1-inch cubes. The bottom layer has 7 rows of 9 cubes. He uses 315 cubes to fill the box to the top. How tall is the box, in inches?', '["63","5","16","45"]', '5', '315/(7*9)', 'One layer has $7 \times 9 = 63$ cubes. The number of layers is $315 \div 63 = 5$, so the box is 5 inches tall.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Layer 7 x 9 = 63; 315 / 63 = 5 layers = 5 inches tall.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cd014db-a74e-4f59-9a48-c762fad57cb0', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume in a real-world problem', 'An aquarium is 40 centimeters long, 25 centimeters wide and 30 centimeters tall. It has water in it to a depth of 20 centimeters. How many more cubic centimeters of water are needed to fill it to the top?', '[]', '10000', '40*25*(30-20)', 'The empty space is a prism 40 cm long, 25 cm wide and $30 - 20 = 10$ cm tall. Its volume is $40 \times 25 \times 10 = 10{,}000$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Empty height 30 - 20 = 10 cm; 40 x 25 x 10 = 10,000 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10694f9b-495b-4d7b-9c01-58dcfb61739a', 'NC26.5.SGMR.4', 3, 'choice', 'Volume in a real-world problem', 'A pit that is 9 meters long, 5 meters wide and 2 meters deep must be filled with soil. One truck carries 15 cubic meters of soil. How many truckloads fill the pit exactly?', '["3","16","6","1,350"]', '6', '9*5*2/15', 'The pit holds $9 \times 5 \times 2 = 90$ cubic meters. Then $90 \div 15 = 6$ truckloads. Using only the base area gives 3, and adding the measurements gives 16.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 x 5 x 2 = 90 cubic m; 90 / 15 = 6 truckloads.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1adbdf8a-2a40-4c85-9e1a-7fd3f2130f4f', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume in a real-world problem', 'A truck bed is 6 feet long, 4 feet wide and 3 feet tall. It is filled level to the top with gravel. Each cubic foot of gravel weighs 100 pounds. How many pounds does the gravel weigh?', '[]', '7200', '6*4*3*100', 'The truck bed holds $6 \times 4 \times 3 = 72$ cubic feet. Then $72 \times 100 = 7{,}200$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"7200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 3 = 72 cubic feet; 72 x 100 = 7,200 pounds.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cd5d704-017e-47b9-ad29-9b0352959e50', 'NC26.5.SGMR.4', 3, 'numeric', 'Volume in a real-world problem', 'A rectangular tank is 5 meters long and 4 meters wide. Water 2 meters deep is poured in, and then 10 more cubic meters of water are added. How deep is the water now, in meters?', '[]', '2.5', '(5*4*2+10)/(5*4)', 'The first water is $5 \times 4 \times 2 = 40$ cubic meters, so now there are $40 + 10 = 50$ cubic meters. The base area is $5 \times 4 = 20$ square meters, so the depth is $50 \div 20 = 2.5$ meters.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 5 x 4 = 20 sq m. Water 20 x 2 = 40, plus 10 = 50 cubic m. Depth 50 / 20 = 2.5 m (assuming the tank is tall enough; its height is not given).","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc225101-8c31-4dec-9df4-0b5106933068', 'NC26.5.SGMR.4', 3, 'numeric', 'Compare volumes and see how volume changes', 'Box X is 9 cm by 4 cm by 5 cm. Box Y is 6 cm by 5 cm by 4 cm. Box Z has a square base that is 10 cm by 10 cm. Box Z holds exactly as much as Box X and Box Y together. How tall is Box Z, in centimeters?', '[]', '3', '(9*4*5+6*5*4)/(10*10)', 'Box X holds $9 \times 4 \times 5 = 180$ and Box Y holds $6 \times 5 \times 4 = 120$, together 300 cubic centimeters. The base of Box Z is $10 \times 10 = 100$ square centimeters, so its height is $300 \div 100 = 3$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 9x4x5 = 180; Y: 6x5x4 = 120; total 300. Z base 10 x 10 = 100; height 300 / 100 = 3 cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbb8cb05-9d91-4675-ae1e-d497c0798286', 'NC26.5.SGMR.4', 3, 'choice', 'Compare volumes and see how volume changes', 'Prism X is 4 cm long, 5 cm wide and 6 cm tall. Prism Y is twice as long as Prism X, has the same width, and is half as tall. Compared with the volume of Prism X, the volume of Prism Y is...', '["twice as great","half as great","four times as great","the same"]', 'the same', NULL, 'Prism X: $4 \times 5 \times 6 = 120$. Prism Y: $8 \times 5 \times 3 = 120$. Doubling one measurement and halving another cancel out.', 'checked', '{"lint":[],"solve":{"answer":"the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 4x5x6 = 120. Y: 8 x 5 x 3 = 120. Same.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73b6aed9-ce11-4510-81a5-477a8ab7170f', 'NC26.5.SGMR.4', 3, 'numeric', 'Compare volumes and see how volume changes', 'A cube with edges 2 cm long is used as a building block. How many of these cubes are needed to fill a larger cube with edges 6 cm long?', '[]', '27', '(6/2)^3', 'Along each edge of the larger cube, $6 \div 2 = 3$ small cubes fit. So $3 \times 3 \times 3 = 27$ small cubes are needed.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/2 = 3 blocks per edge; 3 x 3 x 3 = 27 (216 / 8 = 27).","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('406b8165-765d-4e7d-b297-53201890ede4', 'NC26.5.SGMR.4', 3, 'choice', 'Compare volumes and see how volume changes', 'Which change makes the volume of a prism 6 times as great?', '["Multiply the length, the width and the height each by 2","Multiply the length by 3 and the width by 3","Multiply the length by 2 and the width by 3","Multiply the length by 6 and the width by 6"]', 'Multiply the length by 2 and the width by 3', NULL, '$2 \times 3 = 6$, so doubling the length and tripling the width gives 6 times the volume. The other changes give 8 times, 9 times and 36 times.', 'checked', '{"lint":[],"solve":{"answer":"Multiply the length by 2 and the width by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x6 and x6 gives x36; x2 and x3 gives x6; all x2 gives x8; x3 and x3 gives x9. Answer B.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ef7903f-8cb6-4841-9abf-abf682a15284', 'NC26.5.SGMR.4', 3, 'numeric', 'Compare volumes and see how volume changes', 'Prism X has a volume of 60 cubic centimeters. A new prism has a length 3 times as long as Prism X, a width half as wide, and the same height. What is the volume of the new prism, in cubic centimeters?', '[]', '90', '60*3/2', 'Tripling the length triples the volume and halving the width halves it: $60 \times 3 \div 2 = 90$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume scales by 3 x 1/2 x 1 = 3/2: 60 x 3/2 = 90 cubic cm.","run_id":"claude-code","at":"2026-10-17T19:22:28.485Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28d789b0-c561-4b27-b9e6-10966552bf4a', 'NC26.5.RD.1', 1, 'choice', 'Recognize a question about categorical data', 'Which question would give categorical data?', '["How many pencils are in your bag?","How many inches tall are you?","What is your favorite color?","How many minutes do you read each night?"]', 'What is your favorite color?', NULL, 'Categorical data sorts answers into groups, such as colors. The other questions ask for numbers that can be counted or measured.', 'checked', '{"lint":[],"solve":{"answer":"What is your favorite color?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Favorite color gives categories, not numbers; the others give numerical counts or measurements.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
