INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a28a3d3c-e81f-407e-9aa2-2bf24b752b7e', 'NC26.5.RD.1', 1, 'choice', 'Recognize categorical data and data over time', 'Which of these questions is about data that change over time?', '["How many books did the library lend each month this year?","What is your favorite color?","Which pet do you like best?","What kind of lunch do you like best?"]', 'How many books did the library lend each month this year?', NULL, 'The number of books lent is counted again each month, so it changes from month to month. The other questions ask for a favorite thing at one moment, which gives categories.', 'checked', '{"lint":[],"solve":{"answer":"How many books did the library lend each month this year?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Books lent each month this year is tracked across time; the others are favorites (categorical).","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
