INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('341a9aa5-3e5b-49be-98fd-5b0448e49a7b', 'NC26.5.RD.1', 1, 'choice', 'Plan and collect data', 'Which is a fair survey question to find out how students get to school?', '["Don''t you agree that riding the bus is the best way to get to school?","Do you like your school?","How old are you?","How do you get to school: bus, walk, car or bike?"]', 'How do you get to school: bus, walk, car or bike?', NULL, 'A fair question does not push people toward an answer and asks about what we want to learn. The first question gives clear choices about how students travel. The others lead the answer or ask about something else.', 'checked', '{"lint":[],"solve":{"answer":"How do you get to school: bus, walk, car or bike?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A fair question is neutral and on topic: ''How do you get to school: bus, walk, car or bike?'' The bus one is leading; the others are off topic.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62500b1b-ac0d-4d34-9b0b-18dd534e0864', 'NC26.5.RD.1', 1, 'numeric', 'Plan and collect data', 'A teacher makes one tally mark for each student who picks soccer. There are 3 groups of five tally marks and 2 more single marks. How many students picked soccer?', '[]', '17', '3*5+2', 'Each group of five tally marks stands for 5 students, so 3 groups are $3 \times 5 = 15$. Add the 2 single marks: $15 + 2 = 17$ students.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 groups of 5 = 15, plus 2 = 17.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('186a014d-19a2-427d-8ddd-86889c20acfc', 'NC26.5.RD.1', 1, 'choice', 'Plan and collect data', 'Which tool is best for keeping count of how many cars of each color go past the school?', '["A ruler","A tally chart","A calendar","A clock"]', 'A tally chart', NULL, 'A tally chart lets you make a mark each time you see a car of a color, and then count the marks. A ruler measures length, a calendar shows dates and a clock shows time.', 'checked', '{"lint":[],"solve":{"answer":"A tally chart","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counting cars of each color as they pass: a tally chart.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1446b605-fb15-49c5-966e-8dad0d9b12bb', 'NC26.5.RD.1', 1, 'choice', 'Choose the best graph for the data', 'Which graph is best for showing how the height of a plant changes each week?', '["A bar graph of favorite plants","A line plot of leaf lengths","A tally chart of plant colors","A line graph"]', 'A line graph', NULL, 'A line graph joins points in order of time, so it shows how something changes from week to week. The other displays show favorite plants, one set of lengths or counts of colors.', 'checked', '{"lint":[],"solve":{"answer":"A line graph","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change over time (weekly height) is shown with a line graph.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb5c44b6-3337-4562-8d0a-29910ed72493', 'NC26.5.RD.1', 1, 'choice', 'Choose the best graph for the data', 'Which graph is best for comparing the number of votes that four favorite pets received?', '["A line graph","A bar graph","A line plot","A number line"]', 'A bar graph', NULL, 'Each pet is a category with its own count, so a bar graph with one bar for each pet makes the votes easy to compare. A line graph is for change over time.', 'checked', '{"lint":[],"solve":{"answer":"A bar graph","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Comparing counts across categories: a bar graph.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
