INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99989da4-344a-4e17-adc1-ea7121152cf2', 'NC26.5.RD.1', 1, 'numeric', 'Choose the best graph for the data', 'A bar graph will show the favorite fruit of students. The choices are apple, banana, grape, orange and pear. How many bars will the graph have?', '[]', '5', '5', 'There is one bar for each choice. The choices are apple, banana, grape, orange and pear, so the graph has 5 bars.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One bar per fruit: apple, banana, grape, orange, pear = 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
