INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77b9aa35-11af-42f2-8f77-794434699240', 'NC26.5.RD.1', 1, 'choice', 'Read a line plot', 'On Dev''s line plot, the tallest stack of X marks is above the number 3. What does that tell you?', '["The number 3 is the greatest number in the data","The number 3 appears more often than any other number","There are exactly 3 data values","The number 3 is the least number in the data"]', 'The number 3 appears more often than any other number', NULL, 'The height of a stack shows how many times a number appears in the data. The tallest stack is the number that appears most often. It does not tell you the greatest or least number.', 'checked', '{"lint":[],"solve":{"answer":"The number 3 appears more often than any other number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tallest stack = most X marks = the value that appears most often.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
