INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa282ee7-a83a-42af-8fef-537ead5c8596', 'NC26.5.RD.1', 1, 'numeric', 'Read a line plot with fractional measurements', 'A line plot shows the lengths of 6 ribbons in meters: $\frac{1}{2}$, $\frac{1}{2}$, $\frac{1}{4}$, $\frac{3}{4}$, $\frac{1}{2}$, $\frac{1}{4}$. How many ribbons are $\frac{1}{2}$ meter long?', '[]', '3', NULL, 'The length $\frac{1}{2}$ appears 3 times in the list, so there are 3 X marks above $\frac{1}{2}$ and 3 ribbons are $\frac{1}{2}$ meter long.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 appears in positions 1, 2, 5 = 3 ribbons.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
