INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ade3ee78-ed7a-4e77-a7e6-a24c3b120c66', 'NC26.5.RD.1', 1, 'choice', 'Make a graph: scale, labels and plotting', 'Which should every graph have so that readers know what the numbers mean?', '["A different color for every bar","A picture beside the graph","A scale that counts by 1s","A title and labels on the axes"]', 'A title and labels on the axes', NULL, 'A title says what the graph is about and axis labels say what the numbers and categories mean. Colors, pictures and a particular scale do not tell the reader that.', 'checked', '{"lint":[],"solve":{"answer":"A title and labels on the axes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Readers need a title and axis labels to know what the numbers mean; the other features are not required.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
