INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb04d69b-307f-40f5-856e-a572890005e7', 'NC26.5.RD.1', 1, 'choice', 'Draw conclusions from data', 'A line graph shows the number of visitors to a zoo each month: March 200, April 400, May 600 and June 800. Which statement is supported by the data?', '["The number of visitors dropped each month","Fewer visitors came in June than in March","The number of visitors grew each month","The same number of visitors came each month"]', 'The number of visitors grew each month', NULL, 'Each month has more visitors than the month before (200, 400, 600, 800), so the number grew each month.', 'checked', '{"lint":[],"solve":{"answer":"The number of visitors grew each month","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200, 400, 600, 800: rises every month.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
