INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54c7b43d-06d9-4c25-829f-6a327ef7a855', 'NC26.5.RD.1', 1, 'choice', 'Make predictions from data over time', 'Ella''s total savings were 5, 10, 15 and 20 dollars at the end of Weeks 1 to 4. If the pattern continues, how many dollars will she have saved at the end of Week 5?', '["30","21","24","25"]', '25', '20+5', 'Her savings go up by 5 dollars each week, so at the end of Week 5 she will have $20 + 5 = 25$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Up 5 each week: 20 + 5 = 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
