INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2dacfb9-4e9e-4fb1-a718-09a57e1aa8e9', 'NC26.5.RD.1', 1, 'choice', 'Draw conclusions from data', 'A bar graph shows that 16 students chose pizza, 9 chose tacos and 5 chose salad. Which statement is supported by the data?', '["Tacos got the most votes","Pizza got more votes than any other food","Salad was the most popular choice","Pizza and tacos got the same number of votes"]', 'Pizza got more votes than any other food', NULL, 'Pizza has 16 votes, which is more than the 9 for tacos and the 5 for salad, so pizza got more votes than any other food. The other statements are false.', 'checked', '{"lint":[],"solve":{"answer":"Pizza got more votes than any other food","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 > 9 > 5: pizza most votes.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
