INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dedd725d-dc32-4080-9e22-bb322b130984', 'NC26.5.RD.1', 2, 'choice', 'Draw a conclusion from data over time', 'Maria measured a plant at the end of each month. Month 1: 10 cm. Month 2: 14 cm. Month 3: 18 cm. Month 4: 22 cm. Which statement is supported by the data?', '["The plant grew 22 cm in Month 4.","The plant grew faster in Month 4 than in Month 2.","The plant was shorter in Month 4 than in Month 3.","The plant grew 4 cm each month."]', 'The plant grew 4 cm each month.', NULL, 'The heights go up by 4 each month: $14 - 10 = 4$, $18 - 14 = 4$, $22 - 18 = 4$. The plant was 22 cm tall in Month 4, which is not the same as growing 22 cm.', 'checked', '{"lint":[],"solve":{"answer":"The plant grew 4 cm each month.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Changes: 14-10 = 4, 18-14 = 4, 22-18 = 4. Constant 4 cm per month. Not faster in Month 4; did not grow 22 cm; got taller.","run_id":"claude-code","at":"2026-10-17T18:36:14.367Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef89cc5d-2c56-48e2-af47-d0c0fea8ac98', 'NC26.5.RD.1', 2, 'choice', 'Recognize categorical data and data over time', 'Which set of data is categorical?', '["The height of each of 5 students in inches: 52, 55, 49, 58, 55","The age of each of 5 students in years: 10, 11, 10, 11, 12","The pet each of 5 students owns: dog, cat, fish, dog, bird","The number of books each of 5 students read: 3, 5, 2, 5, 4"]', 'The pet each of 5 students owns: dog, cat, fish, dog, bird', NULL, 'Categorical data put things into groups, such as kinds of pets. Heights, ages and numbers of books are measurements or counts, so those sets are numerical.', 'checked', '{"lint":[],"solve":{"answer":"The pet each of 5 students owns: dog, cat, fish, dog, bird","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pets (dog, cat, fish, bird) are categories; heights, book counts and ages are numbers.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2114f970-88b0-4e55-a07b-9183769e0f52', 'NC26.5.RD.1', 2, 'numeric', 'Recognize categorical data and data over time', 'A class survey has 8 questions. Questions 1, 3 and 6 ask for a favorite thing, such as a color or a food. The other questions ask for a number, such as an age or a height. How many of the questions give numerical data?', '[]', '5', '8-3', 'Questions 1, 3 and 6 give categorical data. The other $8 - 3 = 5$ questions ask for numbers, so they give numerical data.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 questions; 3 (Q1, Q3, Q6) ask for favorites; 8 - 3 = 5 ask for a number.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c9b7fae-9769-44f7-afc0-5576931654d3', 'NC26.5.RD.1', 2, 'choice', 'Recognize categorical data and data over time', 'Which of these data sets changes over time?', '["The favorite subject of each student in a class","The number of students absent each day in one school week","The shoe size of each student on one day","The color of each car in a parking lot at one moment"]', 'The number of students absent each day in one school week', NULL, 'The number of students absent is counted on day after day, so it can change from one day to the next. The other three sets are collected once, at one moment.', 'checked', '{"lint":[],"solve":{"answer":"The number of students absent each day in one school week","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Absences each day across a week is measured over time; the others are one-moment or categorical.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
