INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d017e8e-a9ce-4b99-baea-1b42363af891', 'NC26.5.RD.1', 2, 'choice', 'Plan and collect data', 'Maya wants to find out how the outdoor temperature changes during a school day. Which plan is best?', '["Record the temperature every hour from 8 a.m. to 3 p.m.","Record the temperature once at noon","Ask students whether it feels warm or cool","Record the temperature at 8 a.m. on five different days"]', 'Record the temperature every hour from 8 a.m. to 3 p.m.', NULL, 'To see a change during one day, she needs readings taken at many times in that day. One reading cannot show a change, opinions are not measurements, and five readings at 8 a.m. show different days, not one day.', 'checked', '{"lint":[],"solve":{"answer":"Record the temperature every hour from 8 a.m. to 3 p.m.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change during one school day needs repeated readings that day: every hour from 8 a.m. to 3 p.m.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a612aada-89b7-4ca2-9019-89e1d7b0d807', 'NC26.5.RD.1', 2, 'numeric', 'Plan and collect data', 'A class will read a thermometer at the start of every hour from 8 a.m. through 2 p.m. How many readings will they take?', '[]', '7', '5+2', 'The readings are at 8, 9, 10, 11 and 12, which is 5 readings, and then at 1 and 2, which is 2 more. That makes $5 + 2 = 7$ readings.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8, 9, 10, 11, 12, 1, 2 = 7 readings.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccb8249d-0f06-45e7-acd8-9d6225538d79', 'NC26.5.RD.1', 2, 'choice', 'Choose the best graph for the data', 'Mr. Park measured the length of each of 15 leaves to the nearest quarter inch. He wants to show each leaf as an X above a number line. Which display should he make?', '["A line graph","A bar graph","A line plot","A tally chart"]', 'A line plot', NULL, 'A line plot puts an X above a number line for each measurement, so it shows how many leaves have each length.', 'checked', '{"lint":[],"solve":{"answer":"A line plot","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An X above a number line for each measurement is a line plot.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
