INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dbd9c3ed-fdac-4cdf-9f77-ec4402689e95', 'NC26.5.RD.1', 2, 'choice', 'Choose the best graph for the data', 'Which data are best shown on a line graph?', '["The favorite color of each of 25 students","The number of students in each of 4 clubs","The kinds of pets owned by students in a class","The number of visitors to a park in each month of a year"]', 'The number of visitors to a park in each month of a year', NULL, 'Visitors counted month after month change over time, and a line graph shows that change. The other sets are categories, which a bar graph shows better.', 'checked', '{"lint":[],"solve":{"answer":"The number of visitors to a park in each month of a year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Visitors each month of a year change over time: line graph. The rest are categorical.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
