INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e046203-06ed-40f0-aebf-13d3bf3955f1', 'NC26.5.RD.1', 2, 'numeric', 'Read a bar graph', 'A bar graph shows how students get to school: bus 18, walk 7, car 11 and bike 4. Each student gets to school one way. How many students do NOT ride the bus?', '[]', '22', '7+11+4', 'The students who do not ride the bus walk, ride in a car or bike: $7 + 11 + 4 = 22$ students.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walk 7 + car 11 + bike 4 = 22.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
