INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ebe9d84-e80b-4a23-a620-9b73a33da118', 'NC26.5.RD.1', 2, 'choice', 'Read a line graph of data over time', 'A line graph shows Ben''s savings in dollars: January, 10; February, 25; March, 25; April, 40; May, 35. Between which two months is the line flat?', '["February and March","January and February","March and April","April and May"]', 'February and March', NULL, 'The line is flat when the value does not change. Ben had 25 dollars in both February and March. Between the other pairs of months, the amount went up or down.', 'checked', '{"lint":[],"solve":{"answer":"February and March","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"February 25 and March 25 are equal, so the line is flat there.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
