INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66d66988-2aef-471d-b654-1390ab47676b', 'NC26.5.RD.1', 3, 'choice', 'Read a bar graph', 'A bar graph shows the votes for favorite sports: soccer 16, basketball 12, tennis 8, swimming 20 and baseball 6. Which statement is true?', '["Tennis got 4 fewer votes than soccer","Swimming got 10 more votes than basketball","Baseball got 4 fewer votes than tennis","Basketball got 6 more votes than baseball"]', 'Basketball got 6 more votes than baseball', NULL, 'Basketball 12 and baseball 6 differ by 6, so "Basketball got 6 more votes than baseball" is true. Tennis (8) is 8 fewer than soccer (16), swimming (20) is 8 more than basketball (12), and baseball (6) is 2 fewer than tennis (8).', 'checked', '{"lint":[],"solve":{"answer":"Basketball got 6 more votes than baseball","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Basketball 12 - baseball 6 = 6, true. Swimming - basketball = 8 (not 10). Soccer - tennis = 8 (not 4). Tennis - baseball = 2 (not 4).","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
