INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b56a27f7-9e29-48ae-adec-19365161f892', 'NC26.5.RD.1', 3, 'numeric', 'Read a bar graph', 'A bar graph shows the number of students in four clubs. Chess has 14 students, art has 9 and drama has 11. Band has the rest. In all, 50 students are in these clubs, and each student is in one club. How many students are in band?', '[]', '16', '50-14-9-11', 'Chess, art and drama have $14 + 9 + 11 = 34$ students. Band has the rest: $50 - 34 = 16$ students.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 14 - 9 - 11 = 16.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
