INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02322695-8942-47df-807f-8ea086f9f38a', 'NC26.5.RD.1', 3, 'choice', 'Make a graph: scale, labels and plotting', 'Which scale puts every one of these values exactly on a labeled line: 50, 125, 200, 275 and 350?', '["0 to 350, counting by 50s","0 to 350, counting by 100s","0 to 350, counting by 20s","0 to 350, counting by 25s"]', '0 to 350, counting by 25s', NULL, 'Every value must be a multiple of the step. Each value is a multiple of 25. With steps of 50, the values 125 and 275 fall between lines. With steps of 100 and 20, many of the values do not land on a line either.', 'checked', '{"lint":[],"solve":{"answer":"0 to 350, counting by 25s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All values are multiples of 25 (50, 125, 200, 275, 350). 125 is not a multiple of 50 or 100; 50 not of 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
