INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('667f318c-ac09-467b-869f-0d6e0e395730', 'NC26.5.RD.1', 3, 'numeric', 'Make a graph: scale, labels and plotting', 'On a bar graph, each square stands for 4 votes. The bar for red is 6 squares tall, and the bar for blue is 3 squares taller than the bar for red. How many votes did blue get?', '[]', '36', '(6+3)*4', 'The blue bar is $6 + 3 = 9$ squares tall. Each square is 4 votes, so blue got $9 \times 4 = 36$ votes.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = 6 + 3 = 9 squares; 9 x 4 = 36 votes.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
