INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bb9c98d-b28e-4bac-bf46-1b0b2085c582', 'NC26.5.RD.1', 3, 'choice', 'Draw conclusions from data', 'Class A read 10, 12, 14 and 16 books in Weeks 1 to 4. Class B read 5, 10, 15 and 20 books in Weeks 1 to 4. Which conclusion is supported by the data?', '["Class B''s number of books went up by more each week than Class A''s","Class A read more books than Class B in every week","Class A read the same number of books as Class B in Week 4","Class A''s number of books went up by more each week than Class B''s"]', 'Class B''s number of books went up by more each week than Class A''s', NULL, 'Class A went up by 2 each week and Class B went up by 5 each week. In Week 3 Class B (15) read more than Class A (14), and in Week 4 they read 20 and 16, so the other statements are false.', 'checked', '{"lint":[],"solve":{"answer":"Class B''s number of books went up by more each week than Class A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rises 2 per week, B rises 5 per week. Week 4: A 16, B 20. Week 3: A 14 < B 15. So B rises more each week.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c714dceb-300b-49fa-8f3f-05cd4a7612eb', 'NC26.5.RD.1', 3, 'numeric', 'Draw conclusions from data', 'In April, three stores sold 120, 95 and 85 items. In May, each store sold 15 more items than in April. How many items did the three stores sell in May?', '[]', '345', '120+95+85+3*15', 'In April they sold $120 + 95 + 85 = 300$ items. Each of the 3 stores sold 15 more in May, which is $3 \times 15 = 45$ more. So in May they sold $300 + 45 = 345$ items.', 'checked', '{"lint":[],"solve":{"answer":"345","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"April total 120 + 95 + 85 = 300; May adds 3 x 15 = 45; 345.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e30db18-7ffb-412b-af9c-0adcbfc5565f', 'NC26.5.RD.1', 3, 'choice', 'Draw conclusions from data', 'On a bus survey, 10 of 25 students in Class 1, 14 of 25 in Class 2 and 9 of 25 in Class 3 ride the bus. Which conclusion is supported by the data?', '["More than half of these 75 students ride the bus","Class 1 has more bus riders than Class 2","Fewer than half of these 75 students ride the bus","Exactly 30 of these students ride the bus"]', 'Fewer than half of these 75 students ride the bus', NULL, 'The number of bus riders is $10 + 14 + 9 = 33$. Half of 75 is 37.5, and 33 is less than that. Class 2 has more riders (14) than Class 1 (10), and the total is 33, not 30.', 'checked', '{"lint":[],"solve":{"answer":"Fewer than half of these 75 students ride the bus","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Riders 10 + 14 + 9 = 33 of 75; half is 37.5, so fewer than half. Not 30; Class 1 (10) < Class 2 (14).","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e9d014b-313c-491e-9e67-35bf636ffd92', 'NC26.5.RD.1', 3, 'numeric', 'Make predictions from data over time', 'A video had 3 views on day 1, 6 views on day 2, 12 views on day 3 and 24 views on day 4. If the pattern continues, how many views will it have on day 6?', '[]', '96', '24*2*2', 'The number of views doubles each day. Day 5 will have $24 \times 2 = 48$ views and day 6 will have $48 \times 2 = 96$ views.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Views double each day: day 5 = 48, day 6 = 96.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
