INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e0f39199-79e4-4185-8bc2-0e43e04a09ab', 'NC26.5.RD.1', 3, 'numeric', 'Make predictions from data over time', 'Tara''s savings were 19, 26, 33 and 40 dollars at the end of Weeks 1 to 4. If the pattern continues, in which week will her savings first reach at least 60 dollars?', '[]', '7', '4+3', 'Her savings go up by 7 dollars each week. Week 5 is 47, Week 6 is 54 and Week 7 is 61. Week 6 is still under 60, so the first week with at least 60 dollars is Week 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Up 7 per week: W5 47, W6 54, W7 61 >= 60. Week 7.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
