INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f61dac54-32aa-41d9-a59f-43681d55e8de', 'NC26.5.RD.1', 3, 'choice', 'Make predictions from data over time', 'The number of visitors to a park was 300 in January, 350 in February, 400 in March and 450 in April. If the pattern continues, how many visitors will the park have in July?', '["600","550","500","650"]', '600', '450+3*50', 'The number of visitors goes up by 50 each month. From April to July is 3 more months, so there will be $450 + 3 \times 50 = 600$ visitors.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Up 50 per month: May 500, June 550, July 600.","run_id":"claude-code","at":"2026-10-17T20:03:27.744Z"}}', 'ai', NULL, NULL)
