INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c92c9a1d-1337-450f-9c2e-58b2d022b26b', 'NC26.6.RPR.1', 1, 'numeric', 'Equivalent ratios', 'The ratios $2 : 5$ and $6 : n$ are equivalent. What is the value of $n$?', '[]', '15', '6*5/2', 'To go from 2 to 6, multiply by 3. Multiply the 5 by 3 as well: $5 \times 3 = 15$. So $n = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2:5 = 6:n. 2 x 3 = 6, so n = 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8a4cf41-f2f0-4695-a7d5-f6a90b9662bf', 'NC26.6.RPR.1', 1, 'choice', 'Part-to-part ratio language', 'A drawer has 8 black socks and 6 white socks. What is the ratio of white socks to black socks?', '["$8 : 6$","$6 : 8$","$6 : 14$","$8 : 14$"]', '$6 : 8$', NULL, 'The ratio of white socks to black socks puts the white socks first: $6 : 8$. ($8 : 6$ has the order reversed, and $6 : 14$ and $8 : 14$ compare one color to all the socks.)', 'checked', '{"lint":[],"solve":{"answer":"$6 : 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"White to black = 6 : 8 (order as asked).","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
