INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25b1a2f8-78be-4345-8b07-384bdec65b3b', 'NC26.6.RPR.1', 1, 'choice', 'Part-to-part ratio language', 'Which sentence matches the ratio $3 : 5$ of pencils to pens?', '["For every 3 pencils there are 5 pens","For every 5 pencils there are 3 pens","For every 3 pencils there are 8 pens","There are 3 more pens than pencils"]', 'For every 3 pencils there are 5 pens', NULL, 'In the ratio of pencils to pens, the 3 goes with pencils and the 5 goes with pens: 3 pencils for every 5 pens.', 'checked', '{"lint":[],"solve":{"answer":"For every 3 pencils there are 5 pens","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pencils to pens 3 : 5 -> for every 3 pencils there are 5 pens.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
