INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f19308e-04bf-4e77-90b1-11b443461c5b', 'NC26.6.RPR.1', 1, 'numeric', 'Part-to-whole ratio language', 'A fruit basket holds 3 apples, 4 pears and 5 plums. The ratio of pears to all the fruit is 4 to what number?', '[]', '12', '3+4+5', 'The whole is all the fruit: $3 + 4 + 5 = 12$ pieces. So the ratio of pears to all the fruit is 4 to 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total fruit 3 + 4 + 5 = 12; pears to all = 4 to 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
