INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e952cc2-33b0-4841-a44d-e2d7ade7c80d', 'NC26.6.RPR.1', 1, 'choice', 'Moving between part-to-part and part-to-whole ratios', 'In a garden, the ratio of tulips to daisies is $3 : 4$. All the flowers are tulips or daisies. What is the ratio of daisies to all the flowers?', '["$4 : 3$","$3 : 7$","$7 : 4$","$4 : 7$"]', '$4 : 7$', NULL, 'For every 3 tulips there are 4 daisies, so there are $3 + 4 = 7$ flowers in all. The ratio of daisies to all the flowers is $4 : 7$.', 'checked', '{"lint":[],"solve":{"answer":"$4 : 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 4 = 7; daisies to all = 4 : 7.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3c933af-15a2-47c2-91e0-97096b6758d5', 'NC26.6.RPR.1', 1, 'choice', 'Writing a ratio in different notations', 'Which is another way to write the ratio $3 : 7$?', '["7 to 3","3 to 7","$\\frac{7}{3}$","3 out of 10"]', '3 to 7', NULL, 'The ratio $3 : 7$ can also be read "3 to 7" or written as the fraction $\frac{3}{7}$. The other choices reverse the order or compare 3 to the total, 10.', 'checked', '{"lint":[],"solve":{"answer":"3 to 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 : 7 = 3 to 7 = 3/7. 7/3 and 7 to 3 are reversed; 3 out of 10 is part to whole.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
