INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5ce21dd-7a27-4f42-866a-b3bafe639cd2', 'NC26.6.RPR.1', 1, 'numeric', 'Writing a ratio in different notations', 'The ratio of pens to markers is 2 to 5. Write this ratio as a fraction with the number of pens on top.', '[]', '2/5', '2/5', 'The first number is the top of the fraction and the second is the bottom, so 2 to 5 is the fraction $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pens on top: 2/5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
