INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49167be8-0722-4bad-bc1f-d55de0589bb9', 'NC26.6.RPR.1', 1, 'choice', 'Writing a ratio in different notations', 'A class has 12 boys and 10 girls. Which fraction shows the ratio of girls to boys?', '["$\\frac{12}{10}$","$\\frac{10}{22}$","$\\frac{10}{12}$","$\\frac{12}{22}$"]', '$\frac{10}{12}$', NULL, 'Girls to boys is $10 : 12$, so the fraction has 10 on top and 12 on the bottom. ($\frac{10}{22}$ compares the girls to all the students.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{10}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls to boys = 10/12.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
