INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdd41343-f69b-4426-9640-56ef8ad7ffca', 'NC26.6.RPR.1', 1, 'choice', 'Writing a ratio in lowest terms', 'A class has 6 boys and 9 girls. What is the ratio of boys to girls in lowest terms?', '["$3 : 2$","$2 : 3$","$2 : 5$","$1 : 3$"]', '$2 : 3$', NULL, 'Divide both 6 and 9 by 3 to get $2 : 3$. ($3 : 2$ reverses the order, and $2 : 5$ would compare the boys to all the students.)', 'checked', '{"lint":[],"solve":{"answer":"$2 : 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 : 9, divide by 3: 2 : 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
