INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9a27016-b0df-4e9f-8f94-6ac29ca2edc0', 'NC26.6.RPR.1', 2, 'choice', 'Part-to-part ratio language', 'On a team, the ratio of fifth graders to sixth graders is $4 : 3$. Which statement must be true?', '["There are exactly 4 fifth graders and exactly 3 sixth graders on the team","There are 7 players on the team","For every 4 fifth graders there are 3 sixth graders","There are more sixth graders than fifth graders"]', 'For every 4 fifth graders there are 3 sixth graders', NULL, 'A ratio compares the amounts: 4 fifth graders for every 3 sixth graders. The team could be 8 and 6, or 12 and 9, so the exact numbers and the total are not known. There are more fifth graders than sixth graders.', 'checked', '{"lint":[],"solve":{"answer":"For every 4 fifth graders there are 3 sixth graders","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A ratio gives relative amounts only: for every 4 fifth graders, 3 sixth graders. Totals need not be 7; there are more fifth graders.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d6280bf-0703-43ad-9201-3d23ef86862c', 'NC26.6.RPR.1', 2, 'numeric', 'Part-to-part ratio language', 'A class has 15 girls. The ratio of girls to boys is 5 to 4. How many boys are in the class?', '[]', '12', '15/5*4', '15 girls is $15 \div 5 = 3$ groups of 5 girls. Each group has 4 boys, so there are $3 \times 4 = 12$ boys.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 : 4 scaled by 3 gives 15 : 12. 12 boys.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f516d26-08f7-4279-ab91-2b44fc74b2f7', 'NC26.6.RPR.1', 2, 'choice', 'Part-to-part ratio language', 'A park has 9 dogs and 6 cats. Which statement correctly uses ratio language?', '["The ratio of cats to dogs is 9 to 6","The ratio of dogs to all animals is 9 to 6","The ratio of dogs to cats is 6 to 9","The ratio of dogs to cats is 9 to 6"]', 'The ratio of dogs to cats is 9 to 6', NULL, 'The first number goes with the animal named first. Dogs to cats is 9 to 6. Cats to dogs would be 6 to 9, and dogs to all the animals would be 9 to 15.', 'checked', '{"lint":[],"solve":{"answer":"The ratio of dogs to cats is 9 to 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs to cats = 9 to 6. Cats to dogs would be 6 to 9; dogs to all is 9 to 15.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef8e2684-1c8d-44e5-ac84-3bb205c75c89', 'NC26.6.RPR.1', 2, 'choice', 'Part-to-whole ratio language', 'A bag has 6 green marbles, 9 yellow marbles and 5 red marbles. What is the ratio of yellow marbles to all the marbles?', '["$9 : 11$","$9 : 14$","$9 : 20$","$20 : 9$"]', '$9 : 20$', NULL, 'All the marbles: $6 + 9 + 5 = 20$. The ratio of yellow to all is $9 : 20$. ($9 : 11$ compares yellow to the marbles that are not yellow, and $9 : 14$ leaves out the green marbles.)', 'checked', '{"lint":[],"solve":{"answer":"$9 : 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6 + 9 + 5 = 20; yellow to all = 9 : 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d62acba-3751-4f86-b6bc-e02ccd0b47c9', 'NC26.6.RPR.1', 2, 'numeric', 'Part-to-whole ratio language', 'A school band has 30 members and 12 of them play brass instruments. Write the ratio of brass players to all the members as a fraction.', '[]', '2/5', '12/30', 'The ratio of brass players to all members is $12 : 30$, which is the fraction $\frac{12}{30}$. In lowest terms, $\frac{12}{30} = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Brass to all = 12/30, which equals 2/5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8793182-0962-4520-9ec4-f903708d2f9b', 'NC26.6.RPR.1', 2, 'numeric', 'Part-to-whole ratio language', 'The ratio of students who bring lunch to all students in a school is 3 to 5. The school has 200 students. How many students bring lunch?', '[]', '120', '200/5*3', 'Split the 200 students into groups of 5: $200 \div 5 = 40$ groups. Each group has 3 students who bring lunch, so $40 \times 3 = 120$ students.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 of 200 = 120.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
