INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52fc65c9-30c8-4b25-a8b6-a7d99cee3101', 'NC26.6.RPR.1', 2, 'numeric', 'Moving between part-to-part and part-to-whole ratios', 'A shelf has fiction and nonfiction books in the ratio 7 to 5. There are 60 books in all. How many are nonfiction?', '[]', '25', '60/12*5', 'Each group has $7 + 5 = 12$ books. There are $60 \div 12 = 5$ groups. Each group has 5 nonfiction books, so there are $5 \times 5 = 25$ nonfiction books.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 parts = 60, 1 part = 5; nonfiction 5 x 5 = 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
