INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9645d82f-26df-4893-8934-0bfdfb60500b', 'NC26.6.RPR.1', 2, 'numeric', 'Writing a ratio in different notations', 'The ratio of wins to losses is written $\frac{9}{4}$. For every 4 losses, how many wins are there?', '[]', '9', '9', 'In the fraction, the top is the number of wins and the bottom is the number of losses. So there are 9 wins for every 4 losses.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wins/losses = 9/4: 9 wins for every 4 losses.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
