INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69b33f5d-7b6f-4fcc-a2db-e51139318506', 'NC26.6.RPR.1', 2, 'numeric', 'Finding a missing value in equivalent ratios', 'The ratio of boys to girls on a bus is 5 to 6. There are 30 boys on the bus. How many girls are on the bus?', '[]', '36', '30/5*6', '30 boys is $30 \div 5 = 6$ groups of 5. Each group has 6 girls, so there are $6 \times 6 = 36$ girls.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 boys = 5 x 6; girls 6 x 6 = 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
