INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7ae3c67-ba2b-40bb-8cc8-d281d900ac1c', 'NC26.6.RPR.1', 2, 'numeric', 'Finding a missing value in equivalent ratios', 'A mixture uses 18 scoops of cocoa with 24 scoops of milk. At the same ratio, how many scoops of cocoa go with 4 scoops of milk?', '[]', '3', '18/24*4', 'Divide both amounts by 6: 18 scoops of cocoa and 24 scoops of milk become 3 scoops of cocoa and 4 scoops of milk. So 3 scoops of cocoa go with 4 scoops of milk.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 : 24 = 3 : 4. 3 scoops cocoa with 4 milk.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
