INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b14529eb-e2cf-4f5d-a2c2-50ad6fa1f043', 'NC26.6.RPR.1', 2, 'numeric', 'Finding a missing value in equivalent ratios', 'A train travels 150 miles in 3 hours at a steady speed. How many miles does it travel in 5 hours?', '[]', '250', '150/3*5', 'In 1 hour the train travels $150 \div 3 = 50$ miles. In 5 hours it travels $5 \times 50 = 250$ miles.', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 / 3 = 50 miles per hour; 50 x 5 = 250.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1e1b8a5-860b-4ea6-87c7-e07d9d5bb373', 'NC26.6.RPR.1', 2, 'numeric', 'Recognizing and testing equivalent ratios', 'How many of these ratios are equivalent to $2 : 3$? $4 : 6$, $6 : 9$, $8 : 10$, $10 : 15$, $12 : 16$', '[]', '3', '3', '$4 : 6$ (times 2), $6 : 9$ (times 3) and $10 : 15$ (times 5) are equivalent to $2 : 3$. $8 : 10$ is $4 : 5$ and $12 : 16$ is $3 : 4$ in lowest terms. So 3 ratios are equivalent.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:6 yes, 6:9 yes, 8:10 = 4:5 no, 10:15 yes, 12:16 = 3:4 no. 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8cce1d6-3ef2-4974-ad78-e068523a0ea3', 'NC26.6.RPR.1', 2, 'choice', 'Recognizing and testing equivalent ratios', 'Tess says $5 : 7$ and $10 : 12$ are equivalent because both numbers went up by 5. Which statement is true?', '["They are not equivalent, because the second ratio was made by adding, not multiplying","They are equivalent, because both numbers went up by the same amount","They are equivalent, because the difference between the numbers is 2 in both","They are not equivalent, because $10 : 12$ is not a ratio"]', 'They are not equivalent, because the second ratio was made by adding, not multiplying', NULL, 'Equivalent ratios come from multiplying (or dividing) both numbers by the same number. Adding 5 to both does not keep the ratio: $5 : 7$ is not equal to $10 : 12$, since multiplying 5 by 2 gives 10 but 7 times 2 is 14.', 'checked', '{"lint":[],"solve":{"answer":"They are not equivalent, because the second ratio was made by adding, not multiplying","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/7 is not 10/12 (=5/6). Adding the same amount does not keep a ratio; multiplying does.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('074de4b3-75b6-4f3b-8eda-f2e6af750501', 'NC26.6.RPR.1', 2, 'choice', 'Recognizing and testing equivalent ratios', 'Which pair of ratios is equivalent?', '["$6 : 8$ and $8 : 10$","$6 : 8$ and $12 : 20$","$6 : 8$ and $9 : 12$","$6 : 8$ and $3 : 5$"]', '$6 : 8$ and $9 : 12$', NULL, '$6 : 8$ and $9 : 12$ are both $3 : 4$ in lowest terms. The other pairs are not: $8 : 10$ is $4 : 5$, $12 : 20$ is $3 : 5$ and $3 : 5$ is already lowest.', 'checked', '{"lint":[],"solve":{"answer":"$6 : 8$ and $9 : 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 : 8 = 3 : 4 = 9 : 12. 3:5, 12:20 = 3:5, 8:10 = 4:5 are not.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71373d27-0cf3-47f4-ad8f-3ec3626de98c', 'NC26.6.RPR.1', 2, 'numeric', 'Writing a ratio in lowest terms', 'A pond has 18 ducks and 30 geese. The ratio of ducks to geese in lowest terms is 3 to n. What is n?', '[]', '5', '30/6', 'Divide both numbers by 6: $18 : 30$ becomes $3 : 5$. So $n = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 : 30, divide by 6: 3 : 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('585f1062-3870-4ac7-add3-20fa07eeb177', 'NC26.6.RPR.1', 2, 'choice', 'Writing a ratio in lowest terms', 'Write the ratio of 24 minutes to 40 minutes in lowest terms.', '["$6 : 10$","$12 : 20$","$5 : 3$","$3 : 5$"]', '$3 : 5$', NULL, 'Both numbers can be divided by 8: $24 \div 8 = 3$ and $40 \div 8 = 5$. So the ratio is $3 : 5$. ($6 : 10$ and $12 : 20$ are equivalent but can still be simplified.)', 'checked', '{"lint":[],"solve":{"answer":"$3 : 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 : 40, divide by 8: 3 : 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0adfa2b2-048f-4d61-b399-117c56518a6a', 'NC26.6.RPR.1', 2, 'numeric', 'Writing a ratio in lowest terms', 'A farm has 28 cows and 20 pigs. Write the ratio of cows to pigs as a fraction in lowest terms.', '[]', '7/5', '28/20', 'Cows to pigs is $28 : 20$. Divide both by 4 to get $7 : 5$, which is the fraction $\frac{7}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"7/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28/20, divide by 4: 7/5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
