INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4583ae73-cb9f-4524-9976-2c7fc450877a', 'NC26.6.RPR.1', 2, 'choice', 'The two unit ratios of one relationship', 'A cyclist rides 18 miles in 3 hours. Which pair gives both unit ratios?', '["6 miles per 1 hour and 6 hours per 1 mile","$\\frac{1}{6}$ mile per 1 hour and 6 hours per 1 mile","6 miles per 1 hour and $\\frac{1}{6}$ hour per 1 mile","15 miles per 1 hour and $\\frac{1}{15}$ hour per 1 mile"]', '6 miles per 1 hour and $\frac{1}{6}$ hour per 1 mile', NULL, 'Miles per hour: $18 \div 3 = 6$. Hours per mile: $3 \div 18 = \frac{1}{6}$. The cyclist rides 6 miles in 1 hour, so 1 mile takes $\frac{1}{6}$ hour.', 'checked', '{"lint":[],"solve":{"answer":"6 miles per 1 hour and $\\frac{1}{6}$ hour per 1 mile","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 / 3 = 6 miles per hour; 3 / 18 = 1/6 hour per mile.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d7c98be-a258-44fe-a541-a9fce420a695', 'NC26.6.RPR.1', 2, 'numeric', 'The two unit ratios of one relationship', 'Dev paints 4 square meters in 6 minutes. How many minutes does it take him to paint 1 square meter?', '[]', '1.5', '6/4', 'Divide the time by the area: $6 \div 4 = 1.5$ minutes for 1 square meter.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / 4 = 3/2 = 1.5 minutes per square meter.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc5f1e2e-9c70-42bc-9157-f2591a76bc6e', 'NC26.6.RPR.1', 2, 'numeric', 'Ratios of three quantities and totals', 'In a school play, the ratio of actors to singers to dancers is $2 : 3 : 5$. There are 30 singers. How many dancers are there?', '[]', '50', '30/3*5', '30 singers is $30 \div 3 = 10$ groups of 3. Each group goes with 5 dancers, so there are $10 \times 5 = 50$ dancers.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Singers 3 parts = 30, part = 10; dancers 5 x 10 = 50.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16d5e4f3-f172-4b44-aad1-a50f10545f5b', 'NC26.6.RPR.1', 2, 'choice', 'Ratios of three quantities and totals', 'A paint mix has blue, white and yellow paint in the ratio $3 : 2 : 1$. Which statement is true?', '["There is twice as much blue as white","For every 1 part of yellow there are 3 parts of blue","Yellow is half of the mix","For every 1 part of yellow there are 2 parts of blue"]', 'For every 1 part of yellow there are 3 parts of blue', NULL, 'In the ratio $3 : 2 : 1$, blue is 3 parts when yellow is 1 part. Blue is $\frac{3}{2}$ times the white, not twice as much, and yellow is 1 part out of 6, not half.', 'checked', '{"lint":[],"solve":{"answer":"For every 1 part of yellow there are 3 parts of blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue 3, white 2, yellow 1. A false (3 blue per yellow); yellow is 1/6, not half; blue is 1.5 times white, not twice; D true.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4295dcf6-d368-4ab6-abab-210f0dba0221', 'NC26.6.RPR.1', 2, 'numeric', 'Ratios of three quantities and totals', 'A bag of 24 beads has red, green and blue beads in the ratio $1 : 2 : 3$. How many beads are blue?', '[]', '12', '24/6*3', 'One group has $1 + 2 + 3 = 6$ beads. There are $24 \div 6 = 4$ groups. Each group has 3 blue beads, so there are $4 \times 3 = 12$ blue beads.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 parts = 24, part = 4; blue 3 x 4 = 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3559f47-eba5-4764-a1e5-fed38bbe63ad', 'NC26.6.RPR.1', 3, 'choice', 'The two unit ratios in words', 'A school trip has 24 students and 8 teachers. Which statement is true?', '["There are 3 teachers for every 1 student.","There are 3 students for every 1 teacher.","There are 16 students for every 1 teacher.","There are 8 students for every 1 teacher."]', 'There are 3 students for every 1 teacher.', NULL, 'Divide: $24 \div 8 = 3$, so there are 3 students for every 1 teacher. (Equivalently, there is $\frac{1}{3}$ of a teacher for every student.) Subtracting 24 - 8 = 16 or using the number of teachers, 8, does not give a unit ratio.', 'checked', '{"lint":[],"solve":{"answer":"There are 3 students for every 1 teacher.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 students / 8 teachers = 3 students per teacher. Others: 16 per teacher (wrong), 3 teachers per student (reversed), 8 per teacher (wrong).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7da3662d-c042-434f-b85e-398bb6f6eab9', 'NC26.6.RPR.1', 3, 'numeric', 'Unit ratio that is a fraction', 'Mia reads 6 pages in 15 minutes at a steady pace. How many pages does she read in 1 minute?', '[]', '2/5', '6/15', 'Divide the pages by the minutes: $6 \div 15 = \frac{6}{15} = \frac{2}{5}$. She reads $\frac{2}{5}$ of a page in 1 minute.', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 pages / 15 minutes = 6/15 = 2/5 = 0.4 pages per minute.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bdd8a60-8b38-4023-9ba1-2666802f7bf1', 'NC26.6.RPR.1', 3, 'choice', 'Ratio language with three quantities', 'A garden has 6 roses, 4 tulips and 10 daisies. Which statement is true?', '["The ratio of roses to tulips is 4 to 6.","The ratio of roses to all of the flowers is 6 to 14.","The ratio of daisies to roses is 6 to 10.","The ratio of tulips to all of the flowers is 4 to 20."]', 'The ratio of tulips to all of the flowers is 4 to 20.', NULL, 'There are $6 + 4 + 10 = 20$ flowers in all, so tulips to all flowers is 4 to 20. The other statements are false: roses to tulips is 6 to 4, daisies to roses is 10 to 6, and roses to all flowers is 6 to 20.', 'checked', '{"lint":[],"solve":{"answer":"The ratio of tulips to all of the flowers is 4 to 20.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 6 + 4 + 10 = 20. Roses:tulips = 6:4 (option says 4:6, false). Tulips:all = 4:20 (true). Daisies:roses = 10:6 (option says 6:10, false). Roses:all = 6:20 (option says 6:14, false).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8df2d442-82b2-4b25-a65b-c0ff35e075a4', 'NC26.6.RPR.1', 3, 'choice', 'Part-to-part ratio language', 'The ratio of cats to dogs at a shelter is $5 : 2$. Which could be the number of cats and dogs at the shelter?', '["15 cats and 9 dogs","20 cats and 8 dogs","7 cats and 4 dogs","10 cats and 5 dogs"]', '20 cats and 8 dogs', NULL, 'The numbers must be 5 and 2 each multiplied by the same number. $20 : 8$ comes from multiplying both by 4. The others are $5 : 3$, $7 : 4$ and $2 : 1$ in simplest form.', 'checked', '{"lint":[],"solve":{"answer":"20 cats and 8 dogs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10:5 = 2:1; 7:4 no; 20:8 = 5:2 yes; 15:9 = 5:3.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('458454ab-0b9d-481d-acf8-823429140a43', 'NC26.6.RPR.1', 3, 'numeric', 'Part-to-part ratio language', 'The ratio of adults to children at a picnic is 3 to 7. There are 21 children. How many adults are at the picnic?', '[]', '9', '21/7*3', '21 children is $21 \div 7 = 3$ groups of 7 children. Each group goes with 3 adults, so there are $3 \times 3 = 9$ adults.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21 / 7 = 3; adults 3 x 3 = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5900a18-0020-4b2b-8816-d1dc989285cc', 'NC26.6.RPR.1', 3, 'choice', 'Part-to-part ratio language', 'The ratio of Ana''s stickers to Ben''s stickers is $4 : 1$. Which statement must be true?', '["Ana has 4 times as many stickers as Ben","Ana has exactly 4 stickers","Ana has 3 more stickers than Ben","Ben has 4 times as many stickers as Ana"]', 'Ana has 4 times as many stickers as Ben', NULL, 'The ratio $4 : 1$ means Ana has 4 stickers for every 1 that Ben has, so she has 4 times as many. The actual numbers could be 4 and 1, or 8 and 2, so the other statements need not be true.', 'checked', '{"lint":[],"solve":{"answer":"Ana has 4 times as many stickers as Ben","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 : 1 means Ana has 4 times as many as Ben. Exact counts and the difference are not fixed.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74917c35-fb17-49ac-9fc8-56781b6c3bbf', 'NC26.6.RPR.1', 3, 'choice', 'Part-to-whole ratio language', 'Which box could have a ratio of red pencils to all of its pencils of $1 : 4$?', '["5 red pencils and 20 pencils that are not red","5 red pencils and 15 pencils that are not red","4 red pencils and 20 pencils that are not red","20 red pencils and 5 pencils that are not red"]', '5 red pencils and 15 pencils that are not red', NULL, '5 red and 15 not red make $5 + 15 = 20$ pencils in all, and $5 : 20 = 1 : 4$. The others give $5 : 25$, $4 : 24$ and $20 : 25$, which are not $1 : 4$. (Compare red to not-red and you get $1 : 4$ for the second box, but that is a part-to-part ratio.)', 'checked', '{"lint":[],"solve":{"answer":"5 red pencils and 15 pencils that are not red","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red to all: A 5:25 = 1:5; B 4:24 = 1:6; C 20:25 = 4:5; D 5:20 = 1:4.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be1967ec-58f5-441b-b493-64e04a221d8f', 'NC26.6.RPR.1', 3, 'numeric', 'Part-to-whole ratio language', 'In a bag of 36 marbles, the ratio of blue marbles to all the marbles is 5 to 12. How many marbles are NOT blue?', '[]', '21', '36-36/12*5', 'Split the 36 marbles into groups of 12: $36 \div 12 = 3$ groups. Each group has 5 blue marbles, so there are $3 \times 5 = 15$ blue marbles. The rest are not blue: $36 - 15 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = 5/12 x 36 = 15; not blue = 36 - 15 = 21.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78a45cf9-d964-4028-ac78-3053e10dabee', 'NC26.6.RPR.1', 3, 'choice', 'Part-to-whole ratio language', 'Ravi says, "A class has 8 boys and 12 girls, so the ratio of girls to all the students is $12 : 8$." What mistake did Ravi make?', '["He wrote the number of girls first","He added the girls and boys to get 12","He should have compared boys to all the students","He compared girls to boys, not to all the students"]', 'He compared girls to boys, not to all the students', NULL, 'All the students are $8 + 12 = 20$, so the ratio of girls to all students is $12 : 20$. Ravi wrote $12 : 8$, which compares girls to boys. Putting the girls first was correct.', 'checked', '{"lint":[],"solve":{"answer":"He compared girls to boys, not to all the students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 : 8 is girls to boys; girls to all is 12 : 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ebd2d8f-df61-4ce8-bc63-465e20c8f508', 'NC26.6.RPR.1', 3, 'numeric', 'Moving between part-to-part and part-to-whole ratios', 'A jar has sweet and sour candies in the ratio 5 to 2. There are 42 candies in all. How many more sweet candies than sour candies are there?', '[]', '18', '42/7*(5-2)', 'Each group has $5 + 2 = 7$ candies, and there are $42 \div 7 = 6$ groups. That is $6 \times 5 = 30$ sweet and $6 \times 2 = 12$ sour candies. The difference is $30 - 12 = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 parts = 42, part = 6; sweet 30, sour 12; 30 - 12 = 18.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e2d4190-37ee-428c-8a85-8c9fe32af798', 'NC26.6.RPR.1', 3, 'choice', 'Moving between part-to-part and part-to-whole ratios', 'The ratio of apples to all the fruit in a bowl is $3 : 8$. What is the ratio of apples to the fruit that are not apples?', '["$3 : 5$","$3 : 8$","$5 : 3$","$8 : 5$"]', '$3 : 5$', NULL, 'Of every 8 pieces of fruit, 3 are apples, so $8 - 3 = 5$ are not apples. The ratio of apples to the other fruit is $3 : 5$.', 'checked', '{"lint":[],"solve":{"answer":"$3 : 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Apples 3 of 8, others 5; apples to non-apples = 3 : 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e07dae57-df20-478f-b691-924273babd04', 'NC26.6.RPR.1', 3, 'numeric', 'Moving between part-to-part and part-to-whole ratios', 'In a school, the ratio of students who ride the bus to all students is 3 to 8. There are 160 students. How many students do NOT ride the bus?', '[]', '100', '160-160/8*3', 'Groups of 8 students: $160 \div 8 = 20$ groups. Each group has 3 bus riders, so there are $20 \times 3 = 60$ bus riders. The others: $160 - 60 = 100$ students.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bus = 3/8 x 160 = 60; not bus = 100.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64e164ab-b071-4e39-a434-1ed878b3bf8f', 'NC26.6.RPR.1', 3, 'choice', 'Writing a ratio in different notations', 'The ratio of pens to pencils is written $\frac{6}{4}$. Which statement is true?', '["For every 6 pencils there are 4 pens","For every 6 pens there are 10 pencils","For every 4 pens there are 10 pencils","For every 6 pens there are 4 pencils"]', 'For every 6 pens there are 4 pencils', NULL, 'In the fraction, pens are on top and pencils are on the bottom, so there are 6 pens for every 4 pencils. The other statements reverse the order or add the 6 and 4 to get 10.', 'checked', '{"lint":[],"solve":{"answer":"For every 6 pens there are 4 pencils","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pens/pencils = 6/4: for every 6 pens there are 4 pencils.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('902648c3-879a-487d-9967-84bd83dc2a4b', 'NC26.6.RPR.1', 3, 'numeric', 'Writing a ratio in different notations', 'Dee writes the ratio of cats to dogs as $\frac{7}{3}$. How many dogs are there for every 14 cats?', '[]', '6', '14/7*3', 'The fraction $\frac{7}{3}$ means 7 cats for every 3 dogs. 14 cats is $14 \div 7 = 2$ groups of 7, so there are $2 \times 3 = 6$ dogs.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 : 3 doubled = 14 : 6. 6 dogs.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('035352be-1b48-4da9-b5a6-83a28b7766f5', 'NC26.6.RPR.1', 3, 'choice', 'Writing a ratio in different notations', 'The ratio of blue tiles to red tiles is 5 to 8. Which pair shows this ratio in two different ways?', '["$5 : 8$ and $\\frac{5}{8}$","$5 : 8$ and $\\frac{8}{5}$","5 to 8 and $8 : 5$","$5 : 13$ and $\\frac{5}{8}$"]', '$5 : 8$ and $\frac{5}{8}$', NULL, 'Blue is first, so the ratio is $5 : 8$, which can also be written $\frac{5}{8}$ or "5 to 8". The other pairs reverse the order in one of the two ways or use 13, the total number of tiles.', 'checked', '{"lint":[],"solve":{"answer":"$5 : 8$ and $\\frac{5}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue to red 5 to 8 = 5 : 8 = 5/8. Others reverse or use the total.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd604524-0e51-4419-91ae-10297cc2c5e0', 'NC26.6.RPR.1', 3, 'numeric', 'Finding a missing value in equivalent ratios', 'A ratio table has the columns $4 : 10$, $6 : 15$ and $10 : n$. What is $n$?', '[]', '25', '10/4*10', 'The columns $4 : 10$ and $6 : 15$ both equal $2 : 5$. For the first number to be 10, multiply $2 : 5$ by 5 to get $10 : 25$. So $n = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 : 10 = 2 : 5. 10 = 2 x 5, so n = 5 x 5 = 25. (6 : 15 also 2 : 5.)","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('861aeae0-12f9-4491-be30-f30794a89afc', 'NC26.6.RPR.1', 3, 'numeric', 'Finding a missing value in equivalent ratios', 'A school has 3 teachers for every 48 students. At the same ratio, how many teachers does a school with 336 students need?', '[]', '21', '336/48*3', '336 students is $336 \div 48 = 7$ groups of 48 students. Each group has 3 teachers, so the school needs $7 \times 3 = 21$ teachers.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 / 3 = 16 students per teacher; 336 / 16 = 21 teachers.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84746d21-a9e8-44a5-ad84-ec30d088d0d4', 'NC26.6.RPR.1', 3, 'choice', 'Finding a missing value in equivalent ratios', 'Which value of $n$ makes $8 : 12 = n : 15$ true?', '["11","10","20","12"]', '10', '8/12*15', 'The ratio $8 : 12$ is $2 : 3$ in lowest terms. For the second number to be 15, multiply by 5: $2 \times 5 = 10$ and $3 \times 5 = 15$. So $n = 10$. (11 comes from adding 3 to both numbers, which does not keep the ratio.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 : 12 = 2 : 3; 15 = 3 x 5, n = 2 x 5 = 10.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
