INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32b29eaf-3d17-42a3-9b9a-fe0c1b251513', 'NC26.6.RPR.1', 3, 'numeric', 'The two unit ratios of one relationship', 'Ahmed mows 3 lawns in $2\frac{1}{4}$ hours. How many lawns does he mow in 1 hour? Write your answer as a fraction or mixed number.', '[]', '1 1/3', '3/2.25', 'Divide the lawns by the hours: $3 \div 2\frac{1}{4} = 3 \div \frac{9}{4} = 3 \times \frac{4}{9} = \frac{12}{9} = 1\frac{1}{3}$ lawns in 1 hour.', 'checked', '{"lint":[],"solve":{"answer":"4/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 / (9/4) = 3 x 4/9 = 12/9 = 4/3 = 1 1/3 lawns per hour.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53a05eec-a147-45dd-a602-fe8509514fe4', 'NC26.6.RPR.1', 3, 'choice', 'The two unit ratios of one relationship', 'Tom says, "A car that goes 50 miles on 2 gallons goes 25 miles per gallon and uses 25 gallons per mile." What did Tom get wrong?', '["Gallons per mile should be $\\frac{1}{25}$, not 25","Miles per gallon should be 100","Miles per gallon should be 48","Tom made no mistake"]', 'Gallons per mile should be $\frac{1}{25}$, not 25', NULL, 'Miles per gallon: $50 \div 2 = 25$, which is right. Gallons per mile: $2 \div 50 = \frac{1}{25}$ gallon for every mile, not 25 gallons.', 'checked', '{"lint":[],"solve":{"answer":"Gallons per mile should be $\\frac{1}{25}$, not 25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 / 2 = 25 miles per gallon is right; gallons per mile = 2/50 = 1/25, not 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ad2c234-8827-4445-8926-76ff296913db', 'NC26.6.RPR.1', 3, 'choice', 'Ratios of three quantities and totals', 'A fruit salad has apples, grapes and berries in the ratio $4 : 3 : 5$. There are 36 pieces of fruit in all. How many pieces are berries?', '["15","9","12","20"]', '15', '36/12*5', 'One group has $4 + 3 + 5 = 12$ pieces. There are $36 \div 12 = 3$ groups. Each group has 5 berries, so there are $3 \times 5 = 15$ berries. (9 is the grapes and 12 is the apples.)', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 parts = 36, part = 3; berries 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12bb4b86-fe4c-4077-8e0c-221316b9a40b', 'NC26.6.RPR.1', 3, 'numeric', 'Ratios of three quantities and totals', 'At a camp, the ratio of adults to boys to girls is $2 : 5 : 7$. There are 70 boys. How many people are at the camp in all?', '[]', '196', '70/5*(2+5+7)', '70 boys is $70 \div 5 = 14$ groups of 5. Each group has $2 + 5 + 7 = 14$ people, so the camp has $14 \times 14 = 196$ people.', 'checked', '{"lint":[],"solve":{"answer":"196","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys 5 parts = 70, part = 14; total 14 parts x 14 = 196 (adults 28, girls 98).","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f054367f-0886-4203-967b-67fad9e8d86f', 'NC26.6.RPR.1', 3, 'choice', 'Ratios of three quantities and totals', 'Red, blue and green marbles are in a bag in the ratio $1 : 3 : 4$. Which could be the total number of marbles?', '["36","42","40","44"]', '40', '8*5', 'Each group has $1 + 3 + 4 = 8$ marbles, so the total must be a multiple of 8. Of the choices, only 40 is: $40 = 5 \times 8$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 + 3 + 4 = 8 parts; total must be a multiple of 8. Only 40.","run_id":"claude-code","at":"2026-10-17T20:03:27.781Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7d860cc-b932-47fe-ab36-27b79c76c3b7', 'NC26.6.RPR.2', 1, 'numeric', 'Ratio table (scaling)', 'A recipe uses 2 cups of rice for every 3 cups of water. How many cups of water are needed for 10 cups of rice?', '[]', '15', '10/2*3', '10 cups of rice is $10 \div 2 = 5$ times as much as 2 cups, so multiply the water by 5: $3 \times 5 = 15$ cups.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rice:water = 2:3. 10 cups rice = 5 x 2, so water = 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad96a58b-0e64-43fb-b621-2d019f736efd', 'NC26.6.RPR.2', 1, 'numeric', 'Percent of a quantity', 'What is 25% of 80?', '[]', '20', '25/100*80', '25% means 25 per 100, or $\frac{25}{100} = \frac{1}{4}$. One fourth of 80 is $80 \div 4 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% of 80 = 80 / 4 = 20.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7a2334c-ff9d-4b27-bbe3-bb89fd274ee9', 'NC26.6.RPR.2', 1, 'numeric', 'Finding a percent', 'Sam answered 9 out of 10 questions correctly on a quiz. What percent of the questions did Sam answer correctly?', '[]', '90', '9/10*100', '9 out of 10 is the same rate as 90 out of 100, so Sam answered 90% of the questions correctly.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/10 = 90/100 = 90%.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73fd2145-8856-4312-80aa-20697e517334', 'NC26.6.RPR.2', 1, 'numeric', 'Ratio table: finding a missing value', 'A ratio table compares cups of flour to cups of sugar. The first row is 2 and 5. The second row has 6 cups of flour. How many cups of sugar are in the second row?', '[]', '15', '5*6/2', 'Flour went from 2 cups to 6 cups, which is 3 times as much. The sugar must be 3 times as much too: $5 \times 3 = 15$ cups.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flour:sugar = 2:5. 6 flour is 2 x 3, so sugar = 5 x 3 = 15.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ec3c833-67cb-47eb-8b4a-4e907db818e5', 'NC26.6.RPR.2', 1, 'choice', 'Ratio table: finding a missing value', 'One row of a ratio table shows the numbers 4 and 10. Which pair of numbers could be another row of the same ratio table?', '["8 and 14","6 and 12","2 and 10","8 and 20"]', '8 and 20', NULL, 'Multiply both numbers by 2: $4 \times 2 = 8$ and $10 \times 2 = 20$. Adding the same number to both (8 and 14, or 6 and 12) or changing only one number (2 and 10) does not keep the ratio.', 'checked', '{"lint":[],"solve":{"answer":"8 and 20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4:10 = 2:5. 8:20 = 2:5 (x2). 6:12 = 1:2, 8:14 = 4:7, 2:10 = 1:5 are not equivalent.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d73b92a7-39fa-4611-a197-82e593389f8b', 'NC26.6.RPR.2', 1, 'numeric', 'Ratio table: finding a missing value', 'A ratio table shows that Mia walks 2 miles in 40 minutes. At the same pace, how many miles does she walk in 120 minutes?', '[]', '6', '2*120/40', '120 minutes is 3 times as long as 40 minutes, so she walks 3 times as far: $2 \times 3 = 6$ miles.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 min = 3 x 40 min, so miles = 3 x 2 = 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84d532e4-e9cf-4337-ba2a-af3e6e54b208', 'NC26.6.RPR.2', 1, 'numeric', 'Equivalent ratios in a context', 'A fruit punch uses 1 cup of lemonade for every 4 cups of iced tea. How many cups of iced tea are needed to go with 5 cups of lemonade?', '[]', '20', '4*5', 'For each cup of lemonade there are 4 cups of tea. With 5 cups of lemonade, use $5 \times 4 = 20$ cups of iced tea.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 lemonade : 4 tea. 5 lemonade -> 5 x 4 = 20 cups tea.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ad172a3-43a3-4f41-b876-802cdeea0cbc', 'NC26.6.RPR.2', 1, 'choice', 'Equivalent ratios in a context', 'The ratio of boys to girls in a club is 2 to 3. Which could be the numbers of boys and girls in the club?', '["4 boys and 6 girls","4 boys and 5 girls","5 boys and 6 girls","3 boys and 2 girls"]', '4 boys and 6 girls', NULL, 'Doubling both parts of 2 to 3 gives 4 to 6, so 4 boys and 6 girls. Adding 1 to the girls (4 and 5) or adding 3 to both parts (5 and 6) does not keep the ratio, and 3 boys and 2 girls reverses it.', 'checked', '{"lint":[],"solve":{"answer":"4 boys and 6 girls","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys:girls = 2:3. 4:6 = 2:3. 3:2 reversed, 5:6 and 4:5 not equivalent.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50441cd9-450f-494e-bf1b-918e160cb493', 'NC26.6.RPR.2', 1, 'choice', 'Double number line or graph of a ratio', 'On a double number line, the top marks 3, 6 and 9 are paired with the bottom marks 4, 8 and 12. What is the ratio of the top number to the bottom number, in simplest form?', '["4 to 3","1 to 4","3 to 4","3 to 7"]', '3 to 4', NULL, 'Each pair, such as 3 and 4, has the top number first. Since 3 and 4 have no common factor, the ratio of top to bottom is 3 to 4. (4 to 3 is bottom to top.)', 'checked', '{"lint":[],"solve":{"answer":"3 to 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top:bottom = 3:4 = 6:8 = 9:12; simplest form 3 to 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85003de6-a793-473f-9530-fd8f60eb5727', 'NC26.6.RPR.2', 1, 'numeric', 'Double number line or graph of a ratio', 'A double number line shows hours worked and dollars earned. The hours marks are 0, 2, 4 and 6, and the dollars marks directly below them are 0, 10, 20 and 30. If the number line is continued, how many dollars match 8 hours?', '[]', '40', '8/2*10', 'Each step of 2 hours adds 10 dollars. After 6 hours (30 dollars) the next mark is 8 hours, which is $30 + 10 = 40$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every 2 hours adds 10 dollars ($5/hour). 8 hours -> 40 dollars.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
