INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff629fac-1c00-42cf-92fe-3fdd87041f4b', 'NC26.6.RPR.2', 1, 'numeric', 'Double number line or graph of a ratio', 'Points on the graph of a ratio relationship are written as (hours, miles): (1, 3), (2, 6) and (3, 9). How many miles go with 5 hours on this graph?', '[]', '15', '5*3', 'The points show 3 miles for every 1 hour. So 5 hours go with $5 \times 3 = 15$ miles.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Miles = 3 x hours. 5 hours -> 15 miles.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
