INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a48f3291-c12c-45bf-91e3-032db05bb498', 'NC26.6.RPR.2', 1, 'numeric', 'Converting units with ratio reasoning', 'There are 100 centimeters in 1 meter. How many centimeters are in 3 meters?', '[]', '300', '3*100', 'Each meter is 100 centimeters, so 3 meters is $3 \times 100 = 300$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 100 = 300 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
