INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55a4e6c4-276c-470e-bbb9-fe37514332d9', 'NC26.6.RPR.2', 1, 'choice', 'Converting units with ratio reasoning', 'There are 12 inches in 1 foot. A board is 5 feet long. How many inches long is the board?', '["17","60","7","2.4"]', '60', '5*12', 'Each foot is 12 inches, so 5 feet is $5 \times 12 = 60$ inches. (17 adds instead of multiplying, 7 subtracts, and 2.4 divides 12 by 5.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 12 = 60 inches.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('120235cc-6130-4a1e-b564-f37c37908ae7', 'NC26.6.RPR.2', 1, 'numeric', 'Converting units with ratio reasoning', 'A bag of rice has a mass of 3000 grams. There are 1000 grams in 1 kilogram. What is the mass of the bag in kilograms?', '[]', '3', '3000/1000', 'Every 1000 grams make 1 kilogram, so $3000 \div 1000 = 3$ kilograms.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3000 / 1000 = 3 kg.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
