INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa443e9f-9454-4534-8ae6-8abaf291c96c', 'NC26.6.RPR.2', 1, 'choice', 'Independent and dependent variables', 'Ben earns 8 dollars for each hour he works. The amount he earns depends on the number of hours he works. Which quantity is the independent variable?', '["The amount of money Ben earns","The pay of 8 dollars per hour","Both are independent variables","The number of hours Ben works"]', 'The number of hours Ben works', NULL, 'The independent variable is the one that is chosen or changes on its own: the hours worked. The money earned depends on it, so it is the dependent variable. The 8 dollars per hour does not change.', 'checked', '{"lint":[],"solve":{"answer":"The number of hours Ben works","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Earnings depend on hours, so hours is the independent variable.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
