VALUES ('23126efa-e70d-478b-a06a-b43673b8174a', 'NC26.6.RPR.2', 1, 'choice', 'Percent as a rate per 100', 'Percent means "per 100." Which fraction is the same as 35%?', '["$\\frac{35}{100}$","$\\frac{100}{35}$","$\\frac{35}{10}$","$\\frac{3}{5}$"]', '$\frac{35}{100}$', NULL, '35% means 35 out of every 100, which is $\frac{35}{100}$. (The fraction $\frac{100}{35}$ is upside down, and $\frac{35}{10}$ has the wrong denominator.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{35}{100}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35% = 35 per 100 = 35/100.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
