INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40765156-74b9-4502-b766-5d39994428c0', 'NC26.6.RPR.2', 1, 'numeric', 'Finding a part: percent of a quantity', 'A tank holds 400 liters of water when full. It is 10% full. How many liters of water are in the tank?', '[]', '40', '400*10/100', '10% is one tenth, so the tank holds $400 \div 10 = 40$ liters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10% of 400 = 40 liters.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
