VALUES ('40c1af0c-1cc8-4e27-9e5f-e938362eba4d', 'NC26.6.RPR.2', 1, 'choice', 'Finding the percent from a part and a whole', 'In a class of 25 students, 5 wear glasses. What percent of the students wear glasses?', '["5%","25%","80%","20%"]', '20%', NULL, '$\frac{5}{25} = \frac{20}{100}$, so 20% of the students wear glasses. (80% is the part who do not.)', 'checked', '{"lint":[],"solve":{"answer":"20%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/25 = 20/100 = 20%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
