INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd2cb2a6-7f64-4c9d-9b9f-e2272499bba7', 'NC26.6.RPR.2', 2, 'choice', 'Finding the percent from a part and a whole', 'A basketball player made 18 of her 24 free throws. What percent of her free throws did she make?', '["25%","18%","75%","6%"]', '75%', NULL, '$\frac{18}{24} = \frac{3}{4} = \frac{75}{100}$, so she made 75%. (25% is the part she missed.)', 'checked', '{"lint":[],"solve":{"answer":"75%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/24 = 3/4 = 75%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0d9d29b-c1c4-45d6-843e-50cf2d1a36b5', 'NC26.6.RPR.2', 2, 'choice', 'Finding the percent from a part and a whole', 'A tank held 40 liters of water. After a day, 14 liters had been used. What percent of the water had been used?', '["65%","14%","26%","35%"]', '35%', NULL, '$\frac{14}{40} = \frac{35}{100}$, so 35% of the water had been used. (65% is the part left.)', 'checked', '{"lint":[],"solve":{"answer":"35%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/40 = 35/100 = 35%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39a30eaa-53d5-4dcc-804d-bccb55081fa1', 'NC26.6.RPR.2', 2, 'numeric', 'Finding the percent from a part and a whole', 'A town has 250 people, and 90 of them are children. What percent of the people in the town are children?', '[]', '36', '90/250*100', 'Since $250 \times 0.4 = 100$, multiply 90 by 0.4 too: $90 \times 0.4 = 36$. So $\frac{90}{250} = \frac{36}{100}$, and 36% of the people are children.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90/250 = 36/100 = 36%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4822fa5-8306-4d7d-9074-14dc310da33c', 'NC26.6.RPR.2', 3, 'numeric', 'Finding the whole from a part and a percent', 'Jordan has read 36 pages, which is 40% of a book. How many pages are in the whole book?', '[]', '90', '36/(40/100)', '40% of the book is 36 pages, so 10% is $36 \div 4 = 9$ pages. The whole book is 100%, which is $9 \times 10 = 90$ pages.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 40% of total. 10% = 9, so 100% = 90 pages. Check 0.4 x 90 = 36.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6b4c339-459b-4afd-b7db-42cd27cb26b7', 'NC26.6.RPR.2', 3, 'numeric', 'Rate and unit conversion', 'A cyclist rides at a steady speed of 12 miles per hour. How many miles does the cyclist ride in 45 minutes?', '[]', '9', '12*45/60', '45 minutes is $\frac{45}{60} = \frac{3}{4}$ of an hour. Then $\frac{3}{4} \times 12 = 9$ miles.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 minutes = 3/4 hour. 12 x 3/4 = 9 miles.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4af5c47-f25b-48e3-ace4-1bbc80891131', 'NC26.6.RPR.2', 3, 'numeric', 'Ratio problem with a total', 'Grape juice and apple juice are mixed in the ratio 3 to 5. A pitcher holds 40 cups of the mix. How many cups of the mix are grape juice?', '[]', '15', '40*3/8', 'Each batch of the mix has $3 + 5 = 8$ parts, and 3 of the 8 parts are grape. $40 \div 8 = 5$ cups per part, so grape juice is $3 \times 5 = 15$ cups.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 3:5, 8 parts total. 40 / 8 = 5 cups per part. Grape = 3 x 5 = 15 cups.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c27b49ed-d9b4-457d-96d9-14d79e154a54', 'NC26.6.RPR.2', 3, 'choice', 'Ratio table: finding a missing value', 'A ratio table shows that a car uses 6 gallons of gas to drive 156 miles. Using the same ratio, how many miles can the car drive on 15 gallons of gas?', '["182","2.5","390","2340"]', '390', '156*15/6', 'The car drives $156 \div 6 = 26$ miles on each gallon, so 15 gallons take it $15 \times 26 = 390$ miles. (182 adds 26 to 156, and 2340 multiplies 156 by 15 without dividing.)', 'checked', '{"lint":[],"solve":{"answer":"390","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"156/6 = 26 miles per gallon. 15 x 26 = 390.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a804386-7614-4230-9f50-89582927ba3c', 'NC26.6.RPR.2', 3, 'choice', 'Ratio table: finding a missing value', 'A ratio table has the rows 5 to 12 and 15 to 36. Which row could also be in this table?', '["10 to 17","10 to 24","20 to 27","25 to 32"]', '10 to 24', NULL, 'The second number is always $\frac{12}{5} = 2.4$ times the first. For 10 the partner is $10 \times 2.4 = 24$. The other rows add the same amount to both numbers, which does not keep the ratio.', 'checked', '{"lint":[],"solve":{"answer":"10 to 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5:12, 15:36 (x3). 10:24 (x2) fits. 25:32, 20:27, 10:17 do not (25 would need 60, 20 would need 48, 10 would need 24).","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f8fcda-ed91-4839-82b5-72d5c3486b15', 'NC26.6.RPR.2', 3, 'choice', 'Ratio table: finding a missing value', 'A ratio table shows that 6 muffins use 4 cups of flour. How many cups of flour are used to make 21 muffins?', '["14","19","31.5","126"]', '14', '4*21/6', '3 muffins use 2 cups, and 21 muffins is 7 groups of 3 muffins, so $7 \times 2 = 14$ cups. (19 adds 15 to both numbers, 31.5 inverts the ratio, and 126 multiplies 6 by 21.)', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 muffins : 4 cups = 3 : 2. 21 = 7 x 3, so 7 x 2 = 14 cups.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aeac73ce-cbe0-484a-a189-1b7f9e5afe31', 'NC26.6.RPR.2', 3, 'choice', 'Equivalent ratios in a context', 'The ratio of dogs to cats at a shelter is 5 to 3. There are 6 more dogs than cats. How many dogs are at the shelter?', '["9","6","30","15"]', '15', '6/(5-3)*5', 'Dogs are 5 parts and cats are 3 parts, so the difference is $5 - 3 = 2$ parts. 2 parts is 6 animals, so 1 part is 3. Dogs are $5 \times 3 = 15$ (and cats are 9).', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dogs - cats = 5 - 3 = 2 parts = 6, so 1 part = 3. Dogs = 5 x 3 = 15 (cats 9, difference 6).","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('738a5956-3278-4195-a7f1-84a5d837a5f7', 'NC26.6.RPR.2', 3, 'choice', 'Equivalent ratios in a context', 'Mix A uses 3 cups of juice for every 5 cups of water. Mix B uses 2 cups of juice for every 3 cups of water. Which statement is true?', '["Mix B tastes more strongly of juice than Mix A","Mix A tastes more strongly of juice than Mix B","The two mixes taste equally of juice","Mix A is stronger because 3 is greater than 2"]', 'Mix B tastes more strongly of juice than Mix A', NULL, 'Compare the juice for the same 15 cups of water. Mix A: 3 to 5 is 9 to 15. Mix B: 2 to 3 is 10 to 15. Mix B has more juice for the same water, so it is stronger.', 'checked', '{"lint":[],"solve":{"answer":"Mix B tastes more strongly of juice than Mix A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: juice per water 3/5 = 0.6 (juice fraction 3/8 = 0.375). B: 2/3 = 0.667 (2/5 = 0.4). B has more juice per cup of water, so B is stronger.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('286c7398-93d8-48f9-9c83-8428c42ffe13', 'NC26.6.RPR.2', 3, 'numeric', 'Equivalent ratios in a context', 'Red, blue and white paint are mixed in the ratio 2 to 3 to 5. A mix uses 8 cups of red paint. How many cups of paint are in the mix altogether?', '[]', '40', '8/2*(2+3+5)', '2 parts of red is 8 cups, so 1 part is 4 cups. The mix has $2 + 3 + 5 = 10$ parts, so it has $10 \times 4 = 40$ cups.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red 2 parts = 8, so 1 part = 4. Total parts 2+3+5 = 10, so 40 cups.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('895abccc-0bb2-4d52-bdb0-6e300f4e180f', 'NC26.6.RPR.2', 3, 'numeric', 'Double number line or graph of a ratio', 'On a double number line, the top line shows minutes and the bottom line shows pages read. The top marks 0, 10, 20 and 30 are paired with the bottom marks 0, 6, 12 and 18. How many minutes does it take to read 45 pages at this rate?', '[]', '75', '45*10/6', 'Reading 6 pages takes 10 minutes, so 1 page takes $\frac{10}{6} = \frac{5}{3}$ minutes. Then 45 pages take $45 \times \frac{5}{3} = 75$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 min : 6 pages = 5 : 3. 45 pages = 15 x 3, so 15 x 5 = 75 minutes.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c7f0854-b60d-482a-9b87-9122faf3b414', 'NC26.6.RPR.2', 3, 'numeric', 'Double number line or graph of a ratio', 'The graph of the relationship between gallons of gas and miles driven is a straight line through (0, 0) and (5, 120), where each point is (gallons, miles). How many gallons are needed to drive 288 miles?', '[]', '12', '288/120*5', 'The line shows $120 \div 5 = 24$ miles for each gallon. So 288 miles need $288 \div 24 = 12$ gallons.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120/5 = 24 miles per gallon. 288/24 = 12 gallons.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d4a2167-4858-46f6-bec9-10441102489b', 'NC26.6.RPR.2', 3, 'choice', 'Double number line or graph of a ratio', 'Each answer gives two points. Which pair of points CANNOT both be on the graph of one ratio relationship that passes through (0, 0)?', '["(2, 3) and (4, 6)","(1, 5) and (3, 15)","(2, 4) and (3, 9)","(2, 6) and (5, 15)"]', '(2, 4) and (3, 9)', NULL, 'On such a graph, the second number divided by the first is always the same. (2, 3) and (4, 6) give 1.5 and 1.5; (1, 5) and (3, 15) give 5 and 5; (2, 6) and (5, 15) give 3 and 3. But (2, 4) gives 2 and (3, 9) gives 3, so they do not match.', 'checked', '{"lint":[],"solve":{"answer":"(2, 4) and (3, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x: (1,5),(3,15): 5,5. (2,6),(5,15): 3,3. (2,3),(4,6): 1.5,1.5. (2,4),(3,9): 2 vs 3, not proportional.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4da71697-d672-4226-9955-899a8363575a', 'NC26.6.RPR.2', 3, 'numeric', 'Converting units with ratio reasoning', 'A leaky faucet loses 25 milliliters of water every minute. There are 1000 milliliters in 1 liter and 60 minutes in 1 hour. How many liters of water does it lose in 2 hours?', '[]', '3', '25*2*60/1000', '2 hours is $2 \times 60 = 120$ minutes, so the faucet loses $25 \times 120 = 3000$ milliliters. That is $3000 \div 1000 = 3$ liters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 h = 120 min. 25 x 120 = 3000 mL = 3 L.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4abf9a2-25e0-4519-a3e5-49c0490454bc', 'NC26.6.RPR.2', 3, 'choice', 'Converting units with ratio reasoning', 'There are 100 centimeters in 1 meter and 1000 meters in 1 kilometer. Which length is the longest?', '["5000 centimeters","0.06 kilometers","40 meters","0.045 kilometers"]', '0.06 kilometers', NULL, 'Change each to meters: 5000 centimeters is 50 meters; 40 meters is 40 meters; 0.06 kilometers is 60 meters; 0.045 kilometers is 45 meters. The longest is 60 meters, which is 0.06 kilometers.', 'checked', '{"lint":[],"solve":{"answer":"0.06 kilometers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5000 cm = 50 m; 0.06 km = 60 m; 0.045 km = 45 m; 40 m. Longest 60 m.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('760edbb5-9f18-4716-a8a8-03c2b9bc3fbc', 'NC26.6.RPR.2', 3, 'numeric', 'Converting units with ratio reasoning', 'A 3-pound bag of rice is split into servings of 6 ounces each. There are 16 ounces in 1 pound. How many servings are in the bag?', '[]', '8', '3*16/6', '3 pounds is $3 \times 16 = 48$ ounces. Each serving is 6 ounces, so there are $48 \div 6 = 8$ servings.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 lb = 48 oz. 48/6 = 8 servings.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('275e438d-ce3e-4ea1-b348-01ff1cb83cc8', 'NC26.6.RPR.2', 3, 'choice', 'Converting units with ratio reasoning', 'A runner runs at a steady 6 meters per second. There are 60 seconds in 1 minute and 1000 meters in 1 kilometer. How many kilometers does the runner run in 10 minutes?', '["36","3.6","0.36","360"]', '3.6', '6*10*60/1000', '10 minutes is $10 \times 60 = 600$ seconds, so the runner covers $6 \times 600 = 3600$ meters. That is $3600 \div 1000 = 3.6$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 min = 600 s. 6 x 600 = 3600 m = 3.6 km.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('360b289f-d9ea-401a-8230-7df1d405e91d', 'NC26.6.RPR.2', 3, 'choice', 'Independent and dependent variables', 'The equation $T = 60 + 12n$ gives the total savings $T$, in dollars, after $n$ weeks. After how many weeks will the total savings be 144 dollars?', '["7","12","84","17"]', '7', '(144-60)/12', 'Set $T = 144$: $60 + 12n = 144$, so $12n = 84$ and $n = 7$ weeks. (12 divides 144 by 12 without taking away the starting 60, and 84 stops one step early.)', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: solving 60 + 12n = 144 is a two-step equation (more grade 7), though the options can be checked by substitution.","work":"60 + 12n = 144 -> 12n = 84 -> n = 7. Check: 60 + 84 = 144.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c73f951a-0797-4e1e-b8da-3274eb78a13f', 'NC26.6.RPR.2', 3, 'choice', 'Independent and dependent variables', 'In which situation is the number of hours the dependent variable?', '["The money a tutor earns depends on the hours tutored","The miles a bus drives depend on the hours it drives","The hours needed to mow a lawn depend on the number of mowers","The pages a student reads depend on the hours of reading"]', 'The hours needed to mow a lawn depend on the number of mowers', NULL, 'In the first situation the number of hours depends on how many people mow, so hours is the dependent variable. In each of the others the hours are chosen first and the other quantity depends on them.', 'checked', '{"lint":[],"solve":{"answer":"The hours needed to mow a lawn depend on the number of mowers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mowing: hours depend on mowers, so hours is dependent. In the other three, hours is the independent variable.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6673b77b-cfad-4d40-af8a-25e4bd8bf17c', 'NC26.6.RPR.2', 3, 'numeric', 'Independent and dependent variables', 'A table shows values of $x$ and $y$. When $x$ is 2, $y$ is 11. When $x$ is 4, $y$ is 19. When $x$ is 6, $y$ is 27. Each time $x$ goes up by 2, $y$ goes up by the same amount. What is $y$ when $x$ is 10?', '[]', '43', '27+8+8', '$y$ goes up by 8 each time $x$ goes up by 2 ($11, 19, 27$). From $x = 6$ to $x = 10$ is two more steps: $27 + 8 + 8 = 43$.', 'checked', '{"lint":[],"solve":{"answer":"43","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: a non-proportional linear pattern, only loosely tied to ratio reasoning.","work":"y rises 8 per 2 in x. x=8 -> 35, x=10 -> 43. (y = 4x + 3.)","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17faac7f-27b6-4349-93a0-9e1ad62771ed', 'NC26.6.RPR.2', 3, 'choice', 'Percent as a rate per 100', 'Which of these is NOT equal to 15%?', '["0.15","$\\frac{3}{20}$","$\\frac{15}{100}$","1.5"]', '1.5', '15/10', '15% means $\frac{15}{100} = 0.15$, and $\frac{15}{100} = \frac{3}{20}$. The number 1.5 is 150%, so it is not equal to 15%.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15% = 0.15 = 15/100 = 3/20. 1.5 = 150%.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4a2331a-c5be-4d1a-bff6-f6a24355bb08', 'NC26.6.RPR.2', 3, 'numeric', 'Percent as a rate per 100', 'In Town A, 13 out of every 50 people ride bikes. In Town B, 24 out of every 100 people ride bikes. How many more people out of every 100 ride bikes in Town A than in Town B?', '[]', '2', '13*2-24', 'In Town A, 13 out of 50 is 26 out of 100. Town B has 24 out of 100. The difference is $26 - 24 = 2$ more people out of every 100.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Town A: 13/50 = 26/100. Town B: 24/100. 26 - 24 = 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
