INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8e21089-18a7-4bf4-8733-d040f8d0ee9d', 'NC26.6.RPR.2', 3, 'numeric', 'Finding a part: percent of a quantity', 'Of the 200 students in the sixth grade, 45% play a sport. How many of the sixth graders do not play a sport?', '[]', '110', '200-45*200/100', '45% of 200 is $0.45 \times 200 = 90$ students who play a sport. The others number $200 - 90 = 110$. (Or: 55% of 200 is 110.)', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100% - 45% = 55%. 55% of 200 = 110.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ab2b588-a6ca-4e07-b206-00a69ed7698d', 'NC26.6.RPR.2', 3, 'numeric', 'Finding a part: percent of a quantity', 'A class has 40 students. 60% of them are girls. 25% of the boys wear glasses. How many boys wear glasses?', '[]', '4', '40*(100-60)/100*25/100', 'The boys are $100\% - 60\% = 40\%$ of the class, which is $0.4 \times 40 = 16$ boys. 25% of 16 is $16 \div 4 = 4$ boys.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls 60% of 40 = 24, boys 16. 25% of 16 = 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c82c8bfc-d758-4977-8148-cbaec5a312b9', 'NC26.6.RPR.2', 3, 'numeric', 'Finding a part: percent of a quantity', 'A school has 400 students. 35% are in grade 6 and 40% are in grade 7. How many more students are in grade 7 than in grade 6?', '[]', '20', '400*40/100-400*35/100', 'Grade 7 has $0.40 \times 400 = 160$ students and grade 6 has $0.35 \times 400 = 140$. The difference is $160 - 140 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40% - 35% = 5% of 400 = 20. (160 - 140.)","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5ec569f-7c1a-445b-be2f-12ad2509e0a5', 'NC26.6.RPR.2', 3, 'choice', 'Finding a part: percent of a quantity', 'Which of these amounts is the greatest?', '["30% of 90","60% of 50","45% of 70","20% of 120"]', '45% of 70', NULL, '30% of 90 is 27; 45% of 70 is 31.5; 60% of 50 is 30; 20% of 120 is 24. The greatest is 45% of 70.', 'checked', '{"lint":[],"solve":{"answer":"45% of 70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45% of 70 = 31.5; 20% of 120 = 24; 30% of 90 = 27; 60% of 50 = 30. Greatest 31.5.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf2140ed-e244-416c-a579-7907944ac6ab', 'NC26.6.RPR.2', 3, 'numeric', 'Finding the whole from a part and a percent', 'The dough for a loaf of bread is 40% flour by weight. The flour weighs 150 grams. How many grams does all of the dough weigh?', '[]', '375', '150/40*100', '40% of the dough is 150 grams, so 10% is $150 \div 4 = 37.5$ grams. The whole dough is 100%, which is $37.5 \times 10 = 375$ grams.', 'checked', '{"lint":[],"solve":{"answer":"375","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 is 40%, so 10% = 37.5, 100% = 375 g.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83b9af1b-d52a-4791-bc2f-f69199de71fb', 'NC26.6.RPR.2', 3, 'choice', 'Finding the whole from a part and a percent', 'After Jo spent 35% of her savings, she had 78 dollars left. How many dollars did she have at first?', '["120","113","43","27.3"]', '120', '78/65*100', 'Jo has $100\% - 35\% = 65\%$ left, and that is 78 dollars. So 1% is $78 \div 65 = 1.2$ dollars and 100% is $1.2 \times 100 = 120$ dollars. (113 adds 35, 43 subtracts 35, and 27.3 is 35% of 78.)', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"78 is 65% of savings. 5% = 6, 100% = 120. Check 35% of 120 = 42; 120 - 42 = 78.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('085cd431-f94f-4ada-9a78-87c33abbbd97', 'NC26.6.RPR.2', 3, 'choice', 'Finding the whole from a part and a percent', 'Only 6% of the seats in a theater are empty. There are 9 empty seats. How many seats does the theater have?', '["54","1.5","15","150"]', '150', '9/6*100', '6% of the seats is 9, so 1% is $9 \div 6 = 1.5$ seats. All the seats, 100%, is $1.5 \times 100 = 150$.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 is 6%, so 1% = 1.5, 100% = 150.","run_id":"claude-code","at":"2026-10-17T20:03:27.670Z"}}', 'ai', NULL, NULL)
