INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2ada9f7-58b0-4dd2-bf38-a7eca420c162', 'NC26.6.ANR.1', 1, 'choice', 'Prime factorization in exponent form', 'Which is the prime factorization of 20 written with an exponent?', '["$2 \\times 10$","$4 \\times 5$","$2^2 \\times 5$","$2 \\times 5^2$"]', '$2^2 \times 5$', NULL, '$20 = 2 \times 2 \times 5 = 2^2 \times 5$. The options $2 \times 10$ and $4 \times 5$ use numbers that are not prime, and $2 \times 5^2$ equals 50.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 = 2 x 2 x 5 = 2^2 x 5. 4 x 5 and 2 x 10 are not prime factorizations; 2 x 5^2 = 50.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdda5851-3396-40f6-b4ed-b317fbab78d8', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'The factors of 8 are 1, 2, 4 and 8. The factors of 12 are 1, 2, 3, 4, 6 and 12. What is the greatest factor that 8 and 12 share?', '[]', '4', NULL, 'The factors in both lists are 1, 2 and 4. The greatest of them is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common factors of 8 and 12: 1, 2, 4. Greatest 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90640374-f42b-41b3-a86f-d8ecf0f7da01', 'NC26.6.ANR.1', 1, 'choice', 'Greatest common factor of two numbers', 'Which is the greatest common factor of 16 and 24?', '["4","8","2","48"]', '8', '8', 'The factors of 16 are 1, 2, 4, 8, 16 and the factors of 24 are 1, 2, 3, 4, 6, 8, 12, 24. The common factors are 1, 2, 4 and 8, and the greatest is 8. (4 and 2 are common factors but not the greatest, and 48 is a common multiple.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 = 2^4, 24 = 2^3 x 3. GCF = 8.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1505d3cb-e3ab-41e2-8e3a-2843cc43e002', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'What is the largest number that divides evenly into both 9 and 27?', '[]', '9', NULL, '9 divides evenly into 9 ($9 \div 9 = 1$) and into 27 ($27 \div 9 = 3$). No larger number divides 9 evenly, so the answer is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 divides 27, so GCF(9, 27) = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a85d3e5-ca60-4939-a415-a13cb38346a1', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor of two numbers', 'Find the greatest common factor of 20 and 30.', '[]', '10', NULL, 'The factors of 20 are 1, 2, 4, 5, 10, 20. The factors of 30 are 1, 2, 3, 5, 6, 10, 15, 30. The common factors are 1, 2, 5 and 10, so the greatest is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 = 2^2 x 5, 30 = 2 x 3 x 5. GCF = 10.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e72eb08b-1835-4c9c-92ab-9dc14da0b414', 'NC26.6.ANR.1', 1, 'numeric', 'Greatest common factor in a problem', 'Mia has 8 red beads and 12 blue beads. She makes identical bracelets using all of the beads, with the same number of red beads and the same number of blue beads on each bracelet. What is the greatest number of bracelets she can make?', '[]', '4', NULL, 'The number of bracelets must divide both 8 and 12, so it is a common factor. The greatest common factor of 8 and 12 is 4. With 4 bracelets, each has 2 red beads and 3 blue beads.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bracelets must divide 8 and 12; GCF = 4 (2 red, 3 blue each).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fdf97a06-f513-44e5-8390-f0efe054efc8', 'NC26.6.ANR.1', 1, 'choice', 'Greatest common factor in a problem', 'Two ribbons are 15 inches and 20 inches long. Dan cuts both ribbons into pieces that are all the same length, with no ribbon left over. What is the greatest possible length of each piece, in inches?', '["5","3","10","60"]', '5', '5', 'The piece length must divide both 15 and 20, so the greatest length is the greatest common factor, 5 inches. (3 divides only 15, 10 divides only 20, and 60 is a common multiple.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Piece length divides 15 and 20; GCF = 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63e62f3f-6e3f-47e6-93cf-2861eb89d9a0', 'NC26.6.ANR.1', 1, 'choice', 'Greatest common factor in a problem', 'A floor is 6 feet long and 9 feet wide. It is covered with square tiles that are all the same size, with no gaps and no cutting. What is the greatest possible side length of a tile, in feet?', '["1","2","3","54"]', '3', '3', 'The side length must divide both 6 and 9. The common factors are 1 and 3, so the greatest is 3 feet. (1 foot would work but is not the greatest, 2 does not divide 9, and 54 is $6 \times 9$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tile side divides 6 and 9; GCF = 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4f0c876-cff6-4249-b1c2-a3894857e3e3', 'NC26.6.ANR.1', 1, 'numeric', 'Least common multiple of two numbers', 'The first multiples of 3 are 3, 6, 9, 12, 15 and 18. The first multiples of 4 are 4, 8, 12, 16 and 20. What is the least number that is in both lists?', '[]', '12', NULL, 'The only number in both lists is 12, so the least common multiple of 3 and 4 is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common to both lists: 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35cff7a2-ed32-40e0-8dfa-16d1d0385993', 'NC26.6.ANR.1', 1, 'choice', 'Least common multiple of two numbers', 'Which is the least common multiple of 3 and 9?', '["27","18","3","9"]', '9', '9', '9 is a multiple of 3 ($3 \times 3 = 9$) and of 9, and no smaller number is a multiple of 9. So the least common multiple is 9. (27 and 18 are common multiples, but not the least. 3 is not a multiple of 9.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 is a multiple of 3, so LCM = 9.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf0b5201-6c87-4ab0-b771-4c2baaecab93', 'NC26.6.ANR.1', 1, 'choice', 'Least common multiple of two numbers', 'What is the least common multiple of 6 and 8?', '["48","24","14","2"]', '24', '24', 'Multiples of 6: 6, 12, 18, 24, 30, ... Multiples of 8: 8, 16, 24, 32, ... The first one in both lists is 24. (48 is also a common multiple but not the least; 14 is the sum; 2 is the greatest common factor.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 = 2 x 3, 8 = 2^3. LCM = 2^3 x 3 = 24.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48f11dae-17f2-427a-be67-b97bc0cd8469', 'NC26.6.ANR.1', 1, 'numeric', 'Least common multiple of two numbers', 'Find the least common multiple of 2 and 7.', '[]', '14', '2*7', 'Multiples of 7: 7, 14, 21, ... The first one that is also a multiple of 2 is 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 and 7 share no factor; LCM = 14.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
