INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf2348d8-b6da-4908-b6e5-27f6adabe446', 'NC26.6.ANR.1', 1, 'choice', 'Least common multiple in a problem', 'Paper cups come in packs of 4 and plates come in packs of 5. Pia wants exactly the same number of cups and plates. What is the least number of cups she can buy?', '["20","9","40","10"]', '20', '4*5', 'The number of cups is a multiple of 4 and of 5, so the least is the least common multiple of 4 and 5, which is 20 (5 packs of cups and 4 packs of plates).', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cups multiple of 4, plates multiple of 5; least common = LCM(4, 5) = 20 cups.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
