INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ded92287-f2a0-4ec1-a535-5b456e506467', 'NC26.6.ANR.1', 1, 'choice', 'Prime factorization in exponent form', 'Which of these is a prime factor of 30?', '["10","6","15","2"]', '2', NULL, 'A prime factor is a factor that is a prime number. 10, 6 and 15 are factors of 30, but each can be divided further ($10 = 2 \times 5$, $6 = 2 \times 3$, $15 = 3 \times 5$). Only 2 is prime.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 = 2 x 3 x 5. Only 2 among the options is prime.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42e14bee-7e97-40b5-9ff4-58d95fe2c580', 'NC26.6.ANR.1', 1, 'numeric', 'Prime factorization in exponent form', 'The prime factorization of 18 is written $2 \times 3^n$. What is $n$?', '[]', '2', NULL, '$18 = 2 \times 9 = 2 \times 3 \times 3 = 2 \times 3^2$, so $n = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 = 2 x 9 = 2 x 3^2, so n = 2.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
