INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50a20416-6541-4835-8759-17399651345c', 'NC26.6.ANR.1', 1, 'choice', 'Prime factorization in exponent form', 'Which shows 28 written as a product of prime numbers?', '["$4 \\times 7$","$2 \\times 14$","$2 \\times 2 \\times 7$","$1 \\times 28$"]', '$2 \times 2 \times 7$', NULL, '$2 \times 2 \times 7 = 28$ and 2 and 7 are both prime. The others use 4, 14, 1 or 28, which are not prime.', 'checked', '{"lint":[],"solve":{"answer":"$2 \\times 2 \\times 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 = 2 x 2 x 7, all prime. 14, 28 and 4 are not prime; 1 is not prime.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
