INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3475a0f-0658-4194-8dac-7d72dec3242d', 'NC26.6.ANR.1', 1, 'numeric', 'Prime factorization in exponent form', 'Ben splits 24 into 4 and 6 to start a factor tree. Then he splits 4 into 2 and 2, and 6 into 2 and 3. How many times does the prime 2 appear in the prime factorization of 24?', '[]', '3', NULL, 'The primes at the ends of the tree are 2, 2, 2 and 3. The prime 2 appears 3 times, so $24 = 2^3 \times 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 = 2 x 2 x 2 x 3; the prime 2 appears 3 times.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
