INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64589576-c40b-430b-975c-380277db1ed2', 'NC26.6.ANR.1', 1, 'choice', 'Reading and evaluating exponent form', 'Which expression is the same as $5^3$?', '["$5 \\times 3$","$5 \\times 5 \\times 5$","$3 \\times 3 \\times 3 \\times 3 \\times 3$","$5 + 5 + 5$"]', '$5 \times 5 \times 5$', NULL, 'The exponent 3 tells how many times the base 5 is used as a factor, so $5^3 = 5 \times 5 \times 5$.', 'checked', '{"lint":[],"solve":{"answer":"$5 \\times 5 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^3 = 5 x 5 x 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
