INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c48d4c10-3659-4d03-bc5e-5a6d952aad35', 'NC26.6.ANR.1', 1, 'numeric', 'Reading and evaluating exponent form', 'What is the value of $2 \times 5^2$?', '[]', '50', '2*5^2', 'Work out the exponent first: $5^2 = 25$. Then $2 \times 25 = 50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^2 = 25; 2 x 25 = 50.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
