INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bba48adf-d139-445d-8685-8f4c90b75c3a', 'NC26.6.ANR.1', 1, 'numeric', 'Using prime factorizations to find the GCF or LCM', 'The prime factorizations of 6 and 15 are $6 = 2 \times 3$ and $15 = 3 \times 5$. Which prime number is a factor of both 6 and 15?', '[]', '3', NULL, 'Compare the two lists of primes: 2 and 3 for 6, and 3 and 5 for 15. The only prime in both is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 3 is in both factorizations.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
