INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('682a125e-0abf-4340-a265-9720757cd8c2', 'NC26.6.ANR.1', 2, 'numeric', 'Greatest common factor in a problem', 'A floor is 14 feet long and 21 feet wide. It will be covered with square tiles that are all the same size, with no gaps and no cutting. What is the greatest possible side length of a tile, in feet?', '[]', '7', NULL, 'The side length must divide both 14 and 21. The greatest common factor of 14 and 21 is 7, so the tiles are 7 feet on a side.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(14, 21) = 7 feet.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
