INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('333fbfb5-356e-435d-bc30-4159c9ab281a', 'NC26.6.ANR.1', 2, 'numeric', 'Prime factorization in exponent form', 'How many different prime numbers appear in the prime factorization of 90?', '[]', '3', NULL, '$90 = 2 \times 3 \times 3 \times 5 = 2 \times 3^2 \times 5$. The different primes are 2, 3 and 5, so the answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 = 2 x 3^2 x 5: primes 2, 3, 5 -> 3 different.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
