VALUES ('eac7988e-bd45-4657-803f-ed142a34477c', 'NC26.6.ANR.1', 2, 'numeric', 'Reading and evaluating exponent form', 'Evaluate $2^3 \times 3^2$.', '[]', '72', '2^3*3^2', '$2^3 = 8$ and $3^2 = 9$, so $2^3 \times 3^2 = 8 \times 9 = 72$.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 9 = 72.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
