INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02518ec9-d7b0-42bf-9c4c-02a3f00e2cff', 'NC26.6.ANR.1', 2, 'choice', 'Reading and evaluating exponent form', 'Which comparison of $2^5$ and $5^2$ is true?', '["$2^5$ is equal to $5^2$","$2^5$ is less than $5^2$","$2^5$ is equal to 10","$2^5$ is greater than $5^2$"]', '$2^5$ is greater than $5^2$', NULL, '$2^5 = 2 \times 2 \times 2 \times 2 \times 2 = 32$ and $5^2 = 5 \times 5 = 25$. So $2^5$ is greater. Swapping the base and the exponent changes the value.', 'checked', '{"lint":[],"solve":{"answer":"$2^5$ is greater than $5^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^5 = 32, 5^2 = 25. 32 > 25.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51b499b7-9f2b-4d5c-8c31-036357700d08', 'NC26.6.ANR.1', 2, 'numeric', 'Using prime factorizations to find the GCF or LCM', '$24 = 2^3 \times 3$ and $60 = 2^2 \times 3 \times 5$. Use these prime factorizations to find the greatest common factor of 24 and 60.', '[]', '12', '2^2*3', 'Take each shared prime to the smaller power: $2^2$ (smaller of $2^3$ and $2^2$) and $3$. The greatest common factor is $2^2 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shared primes with lowest powers: 2^2 x 3 = 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b8f912c-7864-43b6-b901-abf8610d8ef3', 'NC26.6.ANR.1', 2, 'choice', 'Using prime factorizations to find the GCF or LCM', '$12 = 2^2 \times 3$ and $18 = 2 \times 3^2$. Which is the least common multiple of 12 and 18?', '["6","36","216","72"]', '36', '2^2*3^2', 'For the least common multiple, take each prime to the larger power: $2^2$ and $3^2$. So the LCM is $2^2 \times 3^2 = 4 \times 9 = 36$. (6 is the greatest common factor and 216 is the product.)', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Highest powers: 2^2 x 3^2 = 36.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28c1d5d3-aa9e-4c26-845d-7ad7b64773c0', 'NC26.6.ANR.1', 2, 'choice', 'Using prime factorizations to find the GCF or LCM', 'Which is the greatest common factor of $2^3 \times 5$ and $2^2 \times 5^2$?', '["$2^2 \\times 5$","$2^3 \\times 5^2$","$2 \\times 5$","$2^2 \\times 5^2$"]', '$2^2 \times 5$', NULL, 'For the greatest common factor, take each shared prime to the smaller power: $2^2$ (smaller of $2^3$ and $2^2$) and $5$ (smaller of $5^1$ and $5^2$). So the GCF is $2^2 \times 5 = 20$. ($2^3 \times 5^2$ is the least common multiple.)', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lowest powers of shared primes: 2^2 x 5 (= 20; numbers are 40 and 100).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae9a3ecc-6928-4a86-8c96-65c43a482123', 'NC26.6.ANR.1', 2, 'choice', 'Factoring a sum with the distributive property', 'Use the distributive property to rewrite $32 + 48$ as a product with the greatest common factor. Which is correct?', '["$8(4 + 6)$","$4(8 + 12)$","$16(2 + 3)$","$16(2 + 4)$"]', '$16(2 + 3)$', NULL, 'The greatest common factor of 32 and 48 is 16, so $32 + 48 = 16(2 + 3)$ because $32 = 16 \times 2$ and $48 = 16 \times 3$. The expressions with 8 and 4 are equal to the sum but do not use the greatest common factor, and $16(2 + 4) = 96$.', 'checked', '{"lint":[],"solve":{"answer":"$16(2 + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(32, 48) = 16. 32 + 48 = 16(2 + 3) = 80. 16(2+4) = 96 wrong; 8(4+6) and 4(8+12) equal 80 but do not use the GCF.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('464092e1-42c0-4fa8-bfe4-d020ed6736dc', 'NC26.6.ANR.1', 2, 'numeric', 'Factoring a sum with the distributive property', 'What number makes this true? $42 + 63 = 21(2 + ?)$', '[]', '3', '63/21', '$42 = 21 \times 2$ and $63 = 21 \times 3$, so the missing number is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"42 = 21 x 2, 63 = 21 x 3. ? = 3.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
