INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dedba20-335f-4ca3-9ce0-dd821b9b17fb', 'NC26.6.ANR.1', 2, 'numeric', 'Factoring a sum with the distributive property', 'The greatest common factor of 54 and 81 is 27, so $54 + 81 = 27(a + b)$. What is the value of $a + b$?', '[]', '5', '54/27+81/27', '$54 \div 27 = 2$ and $81 \div 27 = 3$, so $54 + 81 = 27(2 + 3)$ and $a + b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 = 27 x 2, 81 = 27 x 3. a + b = 5 (check 27 x 5 = 135 = 54 + 81).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
