INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dd01de7-b9c7-4427-acc4-841ac5cdf6cc', 'NC26.6.ANR.1', 2, 'choice', 'Factoring a sum with the distributive property', 'Which sum is equal to $9(4 + 7)$?', '["$36 + 7$","$13 + 16$","$4 + 63$","$36 + 63$"]', '$36 + 63$', NULL, 'The distributive property gives $9(4 + 7) = 9 \times 4 + 9 \times 7 = 36 + 63 = 99$. The others equal 43, 29 and 67.', 'checked', '{"lint":[],"solve":{"answer":"$36 + 63$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9(4 + 7) = 36 + 63 = 99.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
