INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e010614d-439c-4c45-a9e7-4f355236e347', 'NC26.6.ANR.1', 2, 'choice', 'Relating factors and multiples', 'Which number is a multiple of both 6 and 9 and is less than 30?', '["12","18","27","15"]', '18', '2*9', '18 is $6 \times 3$ and $9 \times 2$, so it is a multiple of both. 12 is a multiple of 6 only, 27 is a multiple of 9 only, and 15 is neither.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common multiples of 6 and 9 are multiples of 18; under 30 only 18. 12 not multiple of 9; 15, 27 not multiples of 6.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8dfdf1b-26eb-47cc-bd98-4603393538b5', 'NC26.6.ANR.1', 3, 'numeric', 'Greatest common factor in a problem', 'Ms. Cruz has 84 pencils and 126 erasers. She makes identical supply packs that use all of the pencils and all of the erasers. What is the greatest number of packs she can make?', '[]', '42', NULL, 'The number of packs must divide both 84 and 126, so it is their greatest common factor. $84 = 2^2 \times 3 \times 7$ and $126 = 2 \times 3^2 \times 7$. The shared factors are $2 \times 3 \times 7 = 42$, so she can make 42 packs.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 = 2^2 x 3 x 7, 126 = 2 x 3^2 x 7. GCF = 2 x 3 x 7 = 42 packs (2 pencils and 3 erasers each).","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eb07db1-d298-4654-b868-4cd474b7030c', 'NC26.6.ANR.1', 3, 'choice', 'Prime factorization in exponent form', 'Which is the prime factorization of 72 written with exponents?', '["$2^3 \\times 3$","$2^3 \\times 3^2$","$2^2 \\times 3^3$","$2^3 \\times 9$"]', '$2^3 \times 3^2$', NULL, '$72 = 8 \times 9 = 2^3 \times 3^2$. The option $2^3 \times 3$ equals 24, $2^2 \times 3^3$ equals 108, and $2^3 \times 9$ uses 9, which is not prime.', 'checked', '{"lint":[],"solve":{"answer":"$2^3 \\times 3^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 8 x 9 = 2^3 x 3^2. 2^3 x 9 is not fully prime; 2^3 x 3 = 24; 2^2 x 3^3 = 108.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e780a90-2960-4929-a8e4-57b34c413eba', 'NC26.6.ANR.1', 3, 'numeric', 'Value of a number written in exponent form', 'A number''s prime factorization is $2^3 \times 3 \times 5^2$. What is the number?', '[]', '600', '2^3*3*5^2', '$2^3 = 8$ and $5^2 = 25$, so the number is $8 \times 3 \times 25 = 600$.', 'checked', '{"lint":[],"solve":{"answer":"600","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 3 x 5^2 = 8 x 3 x 25 = 600.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83b5cf13-5aaf-438d-b558-7a9f05fe6a98', 'NC26.6.ANR.1', 3, 'numeric', 'Greatest common factor of two numbers', 'What is the greatest common factor of 84 and 108?', '[]', '12', NULL, '$84 = 2^2 \times 3 \times 7$ and $108 = 2^2 \times 3^3$. The shared primes are $2^2$ and $3$, so the GCF is $2^2 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 = 2^2 x 3 x 7, 108 = 2^2 x 3^3. GCF = 12.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39e36092-5681-4405-b68e-b5491eccda18', 'NC26.6.ANR.1', 3, 'choice', 'Greatest common factor of two numbers', 'The greatest common factor of two numbers is 9. One of the numbers is 63. Which could be the other number?', '["42","21","45","35"]', '45', NULL, '$63 = 9 \times 7$ and $45 = 9 \times 5$, and 7 and 5 share no factor other than 1, so the GCF of 63 and 45 is 9. The greatest common factors of 63 with 42, 21 and 35 are 21, 21 and 7.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF with 63: 21 -> 21; 35 -> 7; 45 -> 9; 42 -> 21.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed0d5fc8-76b6-4cff-9bfc-3268e9b944b3', 'NC26.6.ANR.1', 3, 'numeric', 'Greatest common factor of two numbers', 'The greatest common factor of a number and 36 is 12. The number is greater than 20 and less than 40. What is the number?', '[]', '24', NULL, 'The number must be a multiple of 12, and the multiples of 12 between 20 and 40 are 24 and 36. The GCF of 36 and 36 is 36, not 12, but the GCF of 24 and 36 is 12. So the number is 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The number is a multiple of 12 between 20 and 40: 24 or 36. GCF(24, 36) = 12; GCF(36, 36) = 36. Answer 24.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4d42759-1bfa-4872-9d86-98f88d7d27a4', 'NC26.6.ANR.1', 3, 'choice', 'Greatest common factor in a problem', 'A bakery has 48 muffins and 72 cookies to pack into identical boxes with nothing left over. Every box has the same number of muffins and the same number of cookies. The bakery makes as many boxes as possible. How many muffins and cookies are in each box altogether?', '["24","2","3","5"]', '5', '(48+72)/24', 'The most boxes is the greatest common factor of 48 and 72, which is 24. Each box has $48 \div 24 = 2$ muffins and $72 \div 24 = 3$ cookies, which is $2 + 3 = 5$ items. (24 is the number of boxes.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(48, 72) = 24 boxes. Each: 2 muffins + 3 cookies = 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df219e70-1bbe-43c7-a19c-9331841867e0', 'NC26.6.ANR.1', 3, 'numeric', 'Greatest common factor in a problem', 'A sheet of paper is 84 centimeters long and 60 centimeters wide. It is cut into squares that are all the same size, with no paper left over. The squares are as large as possible. How many squares are there?', '[]', '35', '(84/12)*(60/12)', 'The side of the largest square is the greatest common factor of 84 and 60, which is 12 centimeters. Along the length there are $84 \div 12 = 7$ squares, and along the width $60 \div 12 = 5$. In all there are $7 \times 5 = 35$ squares.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(84, 60) = 12 cm squares. 84/12 = 7, 60/12 = 5; 7 x 5 = 35 squares.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fded49e4-e94e-42b6-babc-bc09a58bf9e9', 'NC26.6.ANR.1', 3, 'choice', 'Greatest common factor in a problem', 'Mara has 56 candies and 42 stickers. She makes as many identical gift bags as she can, using every candy and every sticker, with the same number of each in every bag. How many candies are in each bag?', '["3","4","14","7"]', '4', '56/14', 'The most bags is the greatest common factor of 56 and 42, which is 14. Each bag then has $56 \div 14 = 4$ candies (and $42 \div 14 = 3$ stickers). (14 is the number of bags.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(56, 42) = 14 bags. Candies per bag 56/14 = 4 (stickers 3).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cc7e6bd-2bb6-4854-bd54-f8e8ae2b373a', 'NC26.6.ANR.1', 3, 'numeric', 'Least common multiple of two numbers', 'Find the least common multiple of 11 and 12.', '[]', '132', '11*12', '11 and 12 have no common factor other than 1, so their least common multiple is their product: $11 \times 12 = 132$.', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 and 12 share no factor; LCM = 132.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb4ff8b5-9439-4bc5-98a2-9b6115755b42', 'NC26.6.ANR.1', 3, 'choice', 'Least common multiple of two numbers', 'Which is the least common multiple of 10 and 12?', '["120","22","60","2"]', '60', '60', '$10 = 2 \times 5$ and $12 = 2^2 \times 3$. Take each prime to the larger power: $2^2 \times 3 \times 5 = 60$. (120 is the product, 22 is the sum, and 2 is the greatest common factor.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 = 2 x 5, 12 = 2^2 x 3. LCM = 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8d1d9d7-1063-4747-b0d4-175f8a5a4cb2', 'NC26.6.ANR.1', 3, 'numeric', 'Least common multiple of two numbers', 'The least common multiple of 6 and another whole number is 30. The other number is greater than 1 and less than 10. What is the other number?', '[]', '5', NULL, 'Check the numbers from 2 to 9: the least common multiples with 6 are 6, 6, 12, 30, 6, 42, 24, 18. Only 5 gives 30.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The other number must divide 30 and contain the factor 5: 5, 10, 15, 30. Between 1 and 10 only 5. LCM(6, 5) = 30.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c56fc870-1358-49df-aef6-dc7826cc0ec1', 'NC26.6.ANR.1', 3, 'choice', 'Least common multiple in a problem', 'A red light flashes every 4 seconds, a blue light every 6 seconds and a green light every 10 seconds. All three flash together now. In how many seconds will all three next flash together?', '["30","120","240","60"]', '60', '60', 'The answer is the least common multiple of 4, 6 and 10. $4 = 2^2$, $6 = 2 \times 3$ and $10 = 2 \times 5$, so the LCM is $2^2 \times 3 \times 5 = 60$. (30 is not a multiple of 4, 120 is a common multiple but not the least, and 240 is the product.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 = 2^2, 6 = 2 x 3, 10 = 2 x 5. LCM = 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbf7a8c5-5d01-405d-8a2a-9581921cdb38', 'NC26.6.ANR.1', 3, 'choice', 'Least common multiple in a problem', 'One row of a wall is built from bricks that are 15 centimeters long, and another row from blocks that are 20 centimeters long. Both rows start at the same left edge. What is the shortest length of wall, in centimeters, at which both rows end together?', '["60","300","5","35"]', '60', '60', 'The length must be a multiple of 15 and of 20. The least common multiple of 15 and 20 is 60 centimeters (4 bricks and 3 blocks). (300 is the product, 5 is the greatest common factor, and 35 is the sum.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(15, 20) = 60 cm.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3b91c06-591a-45b6-ab79-c1d8cd702437', 'NC26.6.ANR.1', 3, 'numeric', 'Least common multiple in a problem', 'Notebooks come in packs of 6 and pens come in packs of 8. Ms. Park wants exactly the same number of notebooks and pens, and she buys as few as possible. How many packs does she buy altogether?', '[]', '7', '24/6+24/8', 'The least number of each is the least common multiple of 6 and 8, which is 24. That is $24 \div 6 = 4$ packs of notebooks and $24 \div 8 = 3$ packs of pens, so $4 + 3 = 7$ packs.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(6, 8) = 24 of each: 24/6 = 4 notebook packs, 24/8 = 3 pen packs; 7 packs.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83c1084a-19da-486a-877d-9f018910e2c4', 'NC26.6.ANR.1', 3, 'numeric', 'Least common multiple in a problem', 'Two cyclists start together at the same point on a circular track. One cyclist takes 8 minutes for each lap and the other takes 12 minutes. How many laps has the faster cyclist ridden when they next meet at the starting point?', '[]', '3', '24/8', 'They meet again after the least common multiple of 8 and 12 minutes, which is 24 minutes. The faster cyclist, at 8 minutes a lap, has ridden $24 \div 8 = 3$ laps (and the other has ridden 2).', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM(8, 12) = 24 minutes. Faster (8 min/lap) has ridden 24/8 = 3 laps.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9352959e-32b9-4452-bcc0-157a329706d9', 'NC26.6.ANR.1', 3, 'choice', 'Prime factorization in exponent form', 'Which is the prime factorization of 180 written with exponents?', '["$2^2 \\times 3 \\times 5^2$","$2^2 \\times 3^2 \\times 5$","$2 \\times 3^2 \\times 5^2$","$2^3 \\times 3 \\times 5$"]', '$2^2 \times 3^2 \times 5$', NULL, '$180 = 2 \times 90 = 2 \times 2 \times 45 = 2 \times 2 \times 3 \times 3 \times 5 = 2^2 \times 3^2 \times 5$. The other expressions equal 300, 450 and 120.', 'checked', '{"lint":[],"solve":{"answer":"$2^2 \\times 3^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 = 4 x 45 = 2^2 x 3^2 x 5. Others: 450, 300, 120.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99774348-2535-460e-ad30-9030e985339c', 'NC26.6.ANR.1', 3, 'numeric', 'Prime factorization in exponent form', 'The prime factorization of 200 is $2^a \times 5^b$. What is the value of $a + b$?', '[]', '5', '3+2', '$200 = 2 \times 100 = 2 \times 2 \times 50 = 2 \times 2 \times 2 \times 25 = 2^3 \times 5^2$. So $a = 3$, $b = 2$ and $a + b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200 = 8 x 25 = 2^3 x 5^2. a + b = 5.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d31ee34-2e20-4041-8247-ffd4d3bfab52', 'NC26.6.ANR.1', 3, 'numeric', 'Prime factorization in exponent form', 'The prime factorization of 144 is written in exponent form. If it were written as a product of primes with no exponents, how many prime numbers would be multiplied? Count a repeated prime each time it appears.', '[]', '6', '4+2', '$144 = 12 \times 12 = (2 \times 2 \times 3) \times (2 \times 2 \times 3) = 2^4 \times 3^2$. Without exponents that is $2 \times 2 \times 2 \times 2 \times 3 \times 3$, which has $4 + 2 = 6$ primes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"144 = 2^4 x 3^2 = 2x2x2x2x3x3: 6 primes.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2f3d9c1-3030-4c0c-9f88-e72da832732b', 'NC26.6.ANR.1', 3, 'numeric', 'Reading and evaluating exponent form', 'One number is $2^4 \times 7$ and another number is $2^2 \times 7$. How many times as large as the second number is the first number?', '[]', '4', '2^2', 'The first number is $16 \times 7 = 112$ and the second is $4 \times 7 = 28$. Then $112 \div 28 = 4$. (The factor 7 is in both, and $2^4 \div 2^2 = 2^2 = 4$.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2^4 x 7)/(2^2 x 7) = 2^2 = 4. (112 / 28 = 4.)","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb79be59-90a6-4aaa-a851-6b44da673343', 'NC26.6.ANR.1', 3, 'choice', 'Reading and evaluating exponent form', 'Which of these numbers is the greatest?', '["$2^6$","$3^4$","$5^3$","$7^2$"]', '$5^3$', NULL, '$5^3 = 125$, $2^6 = 64$, $3^4 = 81$ and $7^2 = 49$. The greatest is $5^3$.', 'checked', '{"lint":[],"solve":{"answer":"$5^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: comparing powers tests exponents more than factors and multiples; only loosely aligned.","work":"5^3 = 125, 3^4 = 81, 2^6 = 64, 7^2 = 49. Greatest 125.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b862dd28-aeab-455c-bc1c-b95bc45e2550', 'NC26.6.ANR.1', 3, 'numeric', 'Using prime factorizations to find the GCF or LCM', '$2^3 \times 3 \times 5$ and $2^2 \times 3^2 \times 7$ are the prime factorizations of two numbers. What is the greatest common factor of the two numbers?', '[]', '12', '2^2*3', 'Take each prime that appears in both to its smaller power: $2^2$ and $3$ (the 5 and the 7 are in only one number). The GCF is $2^2 \times 3 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shared primes, lowest powers: 2^2 x 3 = 12. (120 and 252.)","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f13ef530-e92d-4295-98c9-bf6091e99d82', 'NC26.6.ANR.1', 3, 'choice', 'Using prime factorizations to find the GCF or LCM', 'The prime factorizations of two numbers are $2^3 \times 3^2$ and $2^2 \times 3 \times 5$. Which is the least common multiple of the two numbers?', '["$2^3 \\times 3^2 \\times 5$","$2^2 \\times 3$","$2^5 \\times 3^3 \\times 5$","$2^2 \\times 3^2 \\times 5$"]', '$2^3 \times 3^2 \times 5$', NULL, 'For the least common multiple, use every prime that appears, each to its larger power: $2^3$, $3^2$ and $5$. So the LCM is $2^3 \times 3^2 \times 5 = 360$. ($2^2 \times 3$ is the greatest common factor and $2^5 \times 3^3 \times 5$ is the product.)', 'checked', '{"lint":[],"solve":{"answer":"$2^3 \\times 3^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Highest powers: 2^3 x 3^2 x 5 (= 360).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
