INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3d4aa11-0e08-4df4-a365-2215a46c93c4', 'NC26.6.ANR.1', 3, 'numeric', 'Using prime factorizations to find the GCF or LCM', '$60 = 2^2 \times 3 \times 5$ and $84 = 2^2 \times 3 \times 7$. Use these prime factorizations to find the least common multiple of 60 and 84.', '[]', '420', '2^2*3*5*7', 'Use every prime that appears, each to its larger power: $2^2$, $3$, $5$ and $7$. The LCM is $2^2 \times 3 \times 5 \times 7 = 4 \times 105 = 420$.', 'checked', '{"lint":[],"solve":{"answer":"420","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCM = 2^2 x 3 x 5 x 7 = 420.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a01415c-29ac-4e00-bc74-2bac18256a2c', 'NC26.6.ANR.1', 3, 'choice', 'Using prime factorizations to find the GCF or LCM', 'Maria says that the greatest common factor of $2^2 \times 5^2$ and $2^3 \times 5$ is $2^3 \times 5^2$. Which statement is correct?', '["She is correct; the GCF is $2^3 \\times 5^2$","She found the least common multiple; the GCF is $2^3 \\times 5$","She found the least common multiple; the GCF is $2 \\times 5$","She found the least common multiple; the GCF is $2^2 \\times 5$"]', 'She found the least common multiple; the GCF is $2^2 \times 5$', NULL, 'The greatest common factor uses the smaller power of each shared prime: $2^2$ and $5^1$, so the GCF is $2^2 \times 5 = 20$. Maria used the larger powers, which gives the least common multiple, $2^3 \times 5^2 = 200$.', 'checked', '{"lint":[],"solve":{"answer":"She found the least common multiple; the GCF is $2^2 \\times 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 x 5^2 takes highest powers, the LCM (200). GCF takes lowest: 2^2 x 5 = 20.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93e10ecc-ffd5-4903-9326-bf550a08f7b3', 'NC26.6.ANR.1', 3, 'numeric', 'Factoring a sum with the distributive property', 'What is the greatest common factor that can be pulled out of $72 + 96$?', '[]', '24', NULL, 'The greatest common factor of 72 and 96 is 24, because $72 = 24 \times 3$ and $96 = 24 \times 4$. So $72 + 96 = 24(3 + 4)$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 2^3 x 3^2, 96 = 2^5 x 3. GCF = 24: 72 + 96 = 24(3 + 4).","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92dd7cb8-96aa-47ad-ba2c-529157b3dddd', 'NC26.6.ANR.1', 3, 'choice', 'Factoring a sum with the distributive property', 'Which sum has no common factor greater than 1 that can be pulled out?', '["$14 + 21$","$18 + 27$","$16 + 40$","$15 + 28$"]', '$15 + 28$', NULL, '15 and 28 share only the factor 1. The other pairs share 7, 9 and 8, so $14 + 21 = 7(2 + 3)$, $18 + 27 = 9(2 + 3)$ and $16 + 40 = 8(2 + 5)$.', 'checked', '{"lint":[],"solve":{"answer":"$15 + 28$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(15, 28) = 1; (18, 27) = 9; (16, 40) = 8; (14, 21) = 7.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41f63fa5-f1e6-4b23-9bdc-72623e28ec12', 'NC26.6.ANR.1', 3, 'choice', 'Factoring a sum with the distributive property', 'Which expression has the same value as $17 \times 6 + 17 \times 4$?', '["$17 \\times 24$","$17 \\times 10$","$34 \\times 10$","$17 \\times 2$"]', '$17 \times 10$', NULL, 'Both products have the factor 17, so $17 \times 6 + 17 \times 4 = 17(6 + 4) = 17 \times 10$. ($17 \times 24$ multiplies 6 and 4, and the other two change the 17 or subtract.)', 'checked', '{"lint":[],"solve":{"answer":"$17 \\times 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 x 6 + 17 x 4 = 17(6 + 4) = 17 x 10 = 170.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71b802d6-42dc-4dc0-877e-7e0eeb54e415', 'NC26.6.ANR.1', 3, 'choice', 'Factoring a sum with the distributive property', 'Which equation is true?', '["$45 + 60 = 15(3 + 4)$","$45 + 60 = 15(3 + 6)$","$45 + 60 = 5(9 + 10)$","$45 + 60 = 15 \\times 3 + 4$"]', '$45 + 60 = 15(3 + 4)$', NULL, '$45 = 15 \times 3$ and $60 = 15 \times 4$, so $45 + 60 = 15(3 + 4) = 105$. The others work out to 135, 95 and 49.', 'checked', '{"lint":[],"solve":{"answer":"$45 + 60 = 15(3 + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 + 60 = 105. 15(3 + 6) = 135; 15 x 3 + 4 = 49; 15(3 + 4) = 105; 5(9 + 10) = 95.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('646f8e1b-8126-458d-ad58-cd6e86edd9b4', 'NC26.6.ANR.1', 3, 'numeric', 'Relating factors and multiples', 'How many of the whole numbers from 2 to 9 are factors of 72?', '[]', '6', NULL, '72 divides evenly by 2, 3, 4, 6, 8 and 9 ($72 \div 2 = 36$, $\div 3 = 24$, $\div 4 = 18$, $\div 6 = 12$, $\div 8 = 9$, $\div 9 = 8$). It does not divide evenly by 5 or 7. So 6 of the numbers are factors.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 = 2^3 x 3^2. From 2-9: 2, 3, 4, 6, 8, 9 divide 72; 5, 7 do not. 6 numbers.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ed889ae-ab52-4d3a-b4e5-c20155112308', 'NC26.6.ANR.1', 3, 'choice', 'Relating factors and multiples', 'The number 14 is a factor of a whole number $n$. Which of these must also be a factor of $n$?', '["28","4","7","21"]', '7', NULL, 'Since $14 = 7 \times 2$, any multiple of 14 is also a multiple of 7. If $n = 14$, then 7 is a factor of $n$ but 28, 4 and 21 are not, so only 7 must be a factor.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 | n means 7 | n (7 divides 14). n = 14 shows 4, 21, 28 need not be factors.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037b2ebd-861d-4509-80c8-bfb8c59b91bb', 'NC26.6.ANR.1', 3, 'numeric', 'Relating factors and multiples', 'A whole number is a multiple of 12 and is also a factor of 60. It is greater than 12. What is the number?', '[]', '60', NULL, 'The factors of 60 are 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30 and 60. Of these, the multiples of 12 are 12 and 60, so the number greater than 12 is 60.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 12 above 12: 24, 36, 48, 60. Of these only 60 divides 60.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5d67380-78be-4bb9-a574-8728170f3eeb', 'NC26.6.ANR.1', 3, 'choice', 'Relating factors and multiples', 'Which number has exactly three factors?', '["8","10","12","9"]', '9', NULL, 'The factors of 9 are 1, 3 and 9 (three). The factors of 8 are 1, 2, 4, 8 (four), of 10 are 1, 2, 5, 10 (four) and of 12 are 1, 2, 3, 4, 6, 12 (six).', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9: 1, 3, 9 (three). 12 has 6, 10 has 4, 8 has 4.","run_id":"claude-code","at":"2026-10-17T20:03:27.707Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f363c4bd-e2c5-4926-8326-4e1024793717', 'NC26.6.ANR.2', 1, 'numeric', 'Adding fractions with unlike denominators', 'What is $\frac{2}{3} + \frac{1}{6}$?', '[]', '5/6', '2/3+1/6', 'Write $\frac{2}{3}$ as $\frac{4}{6}$. Then $\frac{4}{6} + \frac{1}{6} = \frac{5}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 4/6. 4/6 + 1/6 = 5/6.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
