INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('115ba224-c34d-4e74-9cad-7328cf4c1cf7', 'NC26.6.ANR.2', 1, 'numeric', 'Adding fractions and mixed numbers', 'What is $\frac{1}{4} + \frac{3}{8}$?', '[]', '5/8', '1/4+3/8', 'Rewrite $\frac{1}{4}$ as $\frac{2}{8}$. Then $\frac{2}{8} + \frac{3}{8} = \frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 2/8; 2/8 + 3/8 = 5/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
