INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81c3d961-7ed0-4e3c-9911-f94060ec9d0a', 'NC26.6.ANR.2', 1, 'choice', 'Adding fractions and mixed numbers', 'What is the sum of $\frac{1}{2}$ and $\frac{1}{3}$?', '["$\\frac{2}{5}$","$\\frac{2}{6}$","$\\frac{5}{6}$","$\\frac{1}{6}$"]', '$\frac{5}{6}$', NULL, 'Use sixths: $\frac{1}{2} = \frac{3}{6}$ and $\frac{1}{3} = \frac{2}{6}$. Then $\frac{3}{6} + \frac{2}{6} = \frac{5}{6}$. Adding the tops and the bottoms (to get $\frac{2}{5}$) is a common mistake.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 + 1/3 = 3/6 + 2/6 = 5/6.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b11fb84-a46e-4127-901b-5724d160dcf1', 'NC26.6.ANR.2', 1, 'numeric', 'Adding fractions and mixed numbers', 'What is $1\frac{1}{2} + 2\frac{1}{4}$?', '[]', '3 3/4', '1+1/2+2+1/4', 'Add the whole numbers: 1 + 2 = 3. Add the fractions: $\frac{1}{2} + \frac{1}{4} = \frac{2}{4} + \frac{1}{4} = \frac{3}{4}$. The sum is $3\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3 3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 + 2 = 3; 1/2 + 1/4 = 2/4 + 1/4 = 3/4; total 3 3/4.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('feb3310b-4177-418e-a6aa-8d4b36779080', 'NC26.6.ANR.2', 1, 'choice', 'Adding fractions and mixed numbers', 'Add $\frac{3}{10} + \frac{1}{5}$. Which is the sum?', '["$\\frac{1}{2}$","$\\frac{4}{15}$","$\\frac{4}{10}$","$\\frac{3}{50}$"]', '$\frac{1}{2}$', NULL, 'Write $\frac{1}{5}$ as $\frac{2}{10}$. Then $\frac{3}{10} + \frac{2}{10} = \frac{5}{10}$, which is $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/5 = 2/10; 3/10 + 2/10 = 5/10 = 1/2. Only 1/2 equals 5/10 among the options.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f522c47a-407b-43d8-b2db-dc1b996a7aaf', 'NC26.6.ANR.2', 1, 'numeric', 'Subtracting fractions and mixed numbers', 'What is $\frac{7}{8} - \frac{1}{4}$?', '[]', '5/8', '7/8-1/4', 'Write $\frac{1}{4}$ as $\frac{2}{8}$. Then $\frac{7}{8} - \frac{2}{8} = \frac{5}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 2/8; 7/8 - 2/8 = 5/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
