INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8bde09b9-9486-4f01-b5ba-63ca2e21d584', 'NC26.6.ANR.2', 1, 'numeric', 'Multiplying mixed numbers', 'Multiply: $1\frac{1}{2} \times 4$.', '[]', '6', '(1+1/2)*4', '$1\frac{1}{2}$ is $\frac{3}{2}$. Then $\frac{3}{2} \times 4 = \frac{12}{2} = 6$. Or: 4 groups of 1 is 4, and 4 halves is 2, so 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 1/2 = 3/2; 3/2 x 4 = 12/2 = 6.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
