INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1163e8ad-f67e-4734-a40c-2c5462f02475', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a whole number by a fraction', 'Mr. Lee has 4 pounds of rice and puts $\frac{1}{2}$ pound in each bag. How many bags can he fill?', '[]', '8', '4/(1/2)', 'Each pound fills 2 bags, so 4 pounds fill 4 x 2 = 8 bags. In symbols, $4 \div \frac{1}{2} = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 / (1/2) = 4 x 2 = 8 bags.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce93fbf7-7c30-4ca2-8999-8cca4cfdc0a0', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a whole number by a fraction', 'Divide: $6 \div \frac{1}{3}$.', '[]', '18', '6/(1/3)', 'There are 3 thirds in each whole, so 6 wholes hold 6 x 3 = 18 thirds. So $6 \div \frac{1}{3} = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / (1/3) = 6 x 3 = 18.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1d5c706-a2f7-44cc-82a8-8e3be6ccd863', 'NC26.6.ANR.2', 1, 'choice', 'Dividing a whole number by a fraction', 'A tank has 5 liters of juice. How many $\frac{1}{3}$-liter cups can be filled from it?', '["8","2","$\\frac{5}{3}$","15"]', '15', '5/(1/3)', 'Each liter fills 3 cups, so 5 liters fill 5 x 3 = 15 cups. That is $5 \div \frac{1}{3} = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 / (1/3) = 5 x 3 = 15 cups.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee237c5d-3824-45a3-bc3b-1d17caf5124f', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a fraction by a whole number', 'What is $\frac{6}{7} \div 3$?', '[]', '2/7', '(6/7)/3', 'Share 6 sevenths into 3 equal groups: 2 sevenths in each group. So $\frac{6}{7} \div 3 = \frac{2}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"2/7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/7 / 3 = 6/21 = 2/7.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
