INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b816aaea-b6f4-4ff7-be97-ac42d6ce039c', 'NC26.6.ANR.2', 1, 'choice', 'Dividing a fraction by a whole number', 'Divide $\frac{1}{2}$ by 4. Which is the quotient?', '["2","8","$\\frac{1}{8}$","$\\frac{1}{6}$"]', '$\frac{1}{8}$', NULL, 'Cut one half into 4 equal parts. Each part is $\frac{1}{8}$ of the whole, so $\frac{1}{2} \div 4 = \frac{1}{8}$. Multiplying by 4 gives 2, which is a mistake.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 / 4 = 1/2 x 1/4 = 1/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40040ae8-9b5c-4012-b2fb-cc9d54f8c548', 'NC26.6.ANR.2', 1, 'numeric', 'Dividing a fraction by a fraction', 'Find the quotient: $\frac{2}{3} \div \frac{1}{6}$.', '[]', '4', '(2/3)/(1/6)', '$\frac{2}{3} = \frac{4}{6}$. There are 4 sixths in 4 sixths, so the answer is 4: $\frac{2}{3} \div \frac{1}{6} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 / (1/6) = 2/3 x 6 = 12/3 = 4.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('928f775d-ca8f-4e86-a80f-3a3627305059', 'NC26.6.ANR.2', 1, 'choice', 'Dividing a fraction by a fraction', 'Which is the quotient $\frac{1}{2} \div \frac{1}{8}$?', '["$\\frac{1}{16}$","4","$\\frac{1}{4}$","$\\frac{5}{8}$"]', '4', '(1/2)/(1/8)', '$\frac{1}{2} = \frac{4}{8}$, and there are 4 eighths in 4 eighths. So $\frac{1}{2} \div \frac{1}{8} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 / (1/8) = 1/2 x 8 = 4.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
