INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95ce7592-e5ed-4e27-aab8-12135e353ee2', 'NC26.6.ANR.2', 1, 'choice', 'Interpreting a quotient', 'Dev has 2 pounds of nuts and puts $\frac{1}{4}$ pound in each bag. Which expression shows how many bags he can fill?', '["$2 \\div \\frac{1}{4}$","$\\frac{1}{4} \\div 2$","$2 \\times \\frac{1}{4}$","$2 - \\frac{1}{4}$"]', '$2 \div \frac{1}{4}$', NULL, 'The number of bags is how many $\frac{1}{4}$s fit in 2, which is $2 \div \frac{1}{4}$. (It equals 8 bags.)', 'checked', '{"lint":[],"solve":{"answer":"$2 \\div \\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"How many 1/4-pound groups are in 2 pounds: 2 / (1/4) (= 8).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd02418b-9bae-402c-91e8-baa0d0a0d471', 'NC26.6.ANR.2', 1, 'choice', 'Interpreting a quotient', 'Leo has $\frac{3}{4}$ of a pie and shares it equally among 3 people. Which expression gives each person''s share?', '["$3 \\div \\frac{3}{4}$","$\\frac{3}{4} \\times 3$","$\\frac{3}{4} + 3$","$\\frac{3}{4} \\div 3$"]', '$\frac{3}{4} \div 3$', NULL, 'Sharing equally among 3 people means dividing by 3, so each share is $\frac{3}{4} \div 3$ (which is $\frac{1}{4}$ of the pie).', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{4} \\div 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sharing 3/4 into 3 equal parts: 3/4 / 3 (= 1/4).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01d62d6f-238a-4754-8b7c-7f4c3f4af498', 'NC26.6.ANR.2', 1, 'choice', 'Interpreting a quotient', 'Think about $6 \div \frac{1}{2}$. Which statement is true?', '["The answer is less than 6, because halves are smaller than wholes","The answer is 3, because half of 6 is 3","The answer is greater than 6, because each whole holds 2 halves","The answer is 6, because the top number of $\\frac{1}{2}$ is 1"]', 'The answer is greater than 6, because each whole holds 2 halves', NULL, 'Each whole holds 2 halves, so 6 wholes hold 12 halves. $6 \div \frac{1}{2} = 12$, which is greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"The answer is greater than 6, because each whole holds 2 halves","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / (1/2) = 12, which is greater than 6 because each whole contains 2 halves. The other statements give 6, 3, or ''less than 6'', all false.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d385476-8d1e-46bd-be57-f94100490d68', 'NC26.6.ANR.2', 1, 'numeric', 'One-step fraction word problem', 'Sara walked $\frac{3}{4}$ mile in the morning and $\frac{1}{2}$ mile in the afternoon. How many miles did she walk in all?', '[]', '1 1/4', '3/4+1/2', '$\frac{3}{4} + \frac{2}{4} = \frac{5}{4}$, which is $1\frac{1}{4}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"1 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 + 1/2 = 3/4 + 2/4 = 5/4 = 1 1/4 miles.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
