INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('729b5180-5af7-4584-8b6d-8c4131d338be', 'NC26.6.ANR.2', 1, 'numeric', 'One-step fraction word problem', 'One serving of soup is $\frac{3}{4}$ cup. How many cups of soup are in 4 servings?', '[]', '3', '4*3/4', '4 servings of $\frac{3}{4}$ cup: $4 \times \frac{3}{4} = \frac{12}{4} = 3$ cups.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 3/4 = 12/4 = 3 cups.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
