INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f4415db-ac44-4630-b2f5-e004a72a6f02', 'NC26.6.ANR.2', 1, 'choice', 'Checking reasonableness by estimating', 'Which number is closest to the value of $\frac{7}{8} + \frac{11}{12}$?', '["1","2","3","$\\frac{1}{2}$"]', '2', NULL, '$\frac{7}{8}$ is close to 1 and $\frac{11}{12}$ is close to 1, so the sum is close to 1 + 1 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each fraction is close to 1, so the sum is close to 2. Exactly: 21/24 + 22/24 = 43/24 = about 1.79, nearest option 2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
