INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d6e030b-db47-4066-93d8-39a5a5f6a8ff', 'NC26.6.ANR.2', 1, 'choice', 'Checking reasonableness by estimating', 'Without multiplying, which product is greater than 6?', '["$6 \\times 1\\frac{1}{4}$","$6 \\times \\frac{1}{2}$","$6 \\times \\frac{3}{4}$","$6 \\times \\frac{5}{8}$"]', '$6 \times 1\frac{1}{4}$', NULL, 'Multiplying 6 by a number less than 1 gives less than 6. Only $1\frac{1}{4}$ is greater than 1, so $6 \times 1\frac{1}{4}$ is greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 1\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiplying 6 by a number greater than 1 gives more than 6; only 1 1/4 is greater than 1 (5/8, 1/2, 3/4 are less than 1).","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b8a6853-5768-4982-a0b6-158ce395e032', 'NC26.6.ANR.2', 1, 'numeric', 'Finding a missing number in a fraction equation', 'What is the value of n in $n + \frac{1}{6} = \frac{5}{6}$?', '[]', '2/3', '5/6-1/6', 'Take $\frac{1}{6}$ away from $\frac{5}{6}$: $n = \frac{5}{6} - \frac{1}{6} = \frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 5/6 - 1/6 = 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('732f1541-2b12-4274-a509-cf79febd403b', 'NC26.6.ANR.2', 1, 'choice', 'Finding a missing number in a fraction equation', 'Which fraction makes this true: $\frac{1}{2} + ? = \frac{7}{8}$?', '["$\\frac{5}{8}$","$\\frac{6}{8}$","$\\frac{3}{8}$","$\\frac{1}{4}$"]', '$\frac{3}{8}$', NULL, '$\frac{1}{2} = \frac{4}{8}$. The missing part is $\frac{7}{8} - \frac{4}{8} = \frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"? = 7/8 - 1/2 = 7/8 - 4/8 = 3/8.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cf65fef-80f1-4b1b-9ad9-93964ae06119', 'NC26.6.ANR.2', 2, 'numeric', 'Subtracting mixed numbers', 'What is $5\frac{1}{3} - 2\frac{3}{4}$? Give the answer as a mixed number.', '[]', '2 7/12', '16/3-11/4', 'Use twelfths: $5\frac{1}{3} = 5\frac{4}{12} = 4\frac{16}{12}$ and $2\frac{3}{4} = 2\frac{9}{12}$. Then $4\frac{16}{12} - 2\frac{9}{12} = 2\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"2 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/3 = 64/12, 2 3/4 = 33/12. 64/12 - 33/12 = 31/12 = 2 7/12.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1deb20a-21b4-4c70-a185-ffa0467aceb5', 'NC26.6.ANR.2', 2, 'numeric', 'Dividing a fraction by a fraction (how many fit)', 'How many $\frac{1}{8}$-cup scoops fit exactly into $\frac{3}{4}$ cup of flour?', '[]', '6', '(3/4)/(1/8)', '$\frac{3}{4} = \frac{6}{8}$, which is 6 eighths. So 6 scoops of $\frac{1}{8}$ cup fill $\frac{3}{4}$ cup. In symbols, $\frac{3}{4} \div \frac{1}{8} = \frac{3}{4} \times 8 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 / 1/8 = 3/4 x 8 = 6 scoops.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38ec236a-eea4-48d4-8fc9-15cfbb61f7e9', 'NC26.6.ANR.2', 2, 'choice', 'Interpreting a quotient', 'Which question can be answered by finding $4 \div \frac{1}{3}$?', '["What is one third of 4 cups of juice?","How much juice does each of 3 people get if they share 4 cups equally?","How many 4-cup jugs can be filled from one third of a cup of juice?","How many one-third-cup servings are in 4 cups of juice?"]', 'How many one-third-cup servings are in 4 cups of juice?', NULL, '$4 \div \frac{1}{3}$ asks how many groups of $\frac{1}{3}$ fit into 4, so the answer is 12 servings. One third of 4 is multiplication, the jug question is $\frac{1}{3} \div 4$, and sharing 4 cups among 3 people is $4 \div 3$.', 'checked', '{"lint":[],"solve":{"answer":"How many one-third-cup servings are in 4 cups of juice?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 / (1/3) asks how many groups of 1/3 are in 4: servings of one-third cup in 4 cups (= 12). One third of 4 is 4 x 1/3; sharing among 3 is 4 / 3; the jug option is (1/3) / 4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31670bbf-1d12-4688-9fb7-63e72614ce27', 'NC26.6.ANR.2', 2, 'numeric', 'Adding fractions and mixed numbers', 'What is $\frac{5}{6} + \frac{3}{4}$?', '[]', '1 7/12', '5/6+3/4', 'Use twelfths: $\frac{5}{6} = \frac{10}{12}$ and $\frac{3}{4} = \frac{9}{12}$. Then $\frac{10}{12} + \frac{9}{12} = \frac{19}{12} = 1\frac{7}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"1 7/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 + 3/4 = 10/12 + 9/12 = 19/12 = 1 7/12.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfe31ba1-dc21-4027-aa23-1f5889443760', 'NC26.6.ANR.2', 2, 'numeric', 'Adding fractions and mixed numbers', 'Find the sum: $2\frac{2}{3} + 1\frac{3}{4}$.', '[]', '4 5/12', '(2+2/3)+(1+3/4)', 'Whole numbers: 2 + 1 = 3. Fractions: $\frac{2}{3} = \frac{8}{12}$ and $\frac{3}{4} = \frac{9}{12}$, so $\frac{8}{12} + \frac{9}{12} = \frac{17}{12} = 1\frac{5}{12}$. The total is 3 + $1\frac{5}{12}$ = $4\frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"4 5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 1 = 3; 2/3 + 3/4 = 8/12 + 9/12 = 17/12 = 1 5/12; total 4 5/12.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
