INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b70a70fc-11fb-460b-9725-813fa768b2fb', 'NC26.6.ANR.2', 2, 'choice', 'Dividing mixed numbers', 'Which is the value of $3\frac{1}{3} \div 1\frac{2}{3}$?', '["$\\frac{1}{2}$","$5\\frac{5}{9}$","$1\\frac{2}{3}$","2"]', '2', '(3+1/3)/(1+2/3)', '$3\frac{1}{3} = \frac{10}{3}$ and $1\frac{2}{3} = \frac{5}{3}$. Then $\frac{10}{3} \div \frac{5}{3} = \frac{10}{3} \times \frac{3}{5} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 1/3 = 10/3, 1 2/3 = 5/3; 10/3 / 5/3 = 10/5 = 2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
