INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbfc2f6a-fea0-4a6b-929c-a37410f907ac', 'NC26.6.ANR.2', 2, 'numeric', 'Dividing mixed numbers', 'Divide $3\frac{3}{4}$ by $2\frac{1}{2}$. What is the quotient?', '[]', '1 1/2', '(3+3/4)/(2+1/2)', '$3\frac{3}{4} = \frac{15}{4}$ and $2\frac{1}{2} = \frac{5}{2}$. Then $\frac{15}{4} \times \frac{2}{5} = \frac{30}{20} = \frac{3}{2} = 1\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 3/4 = 15/4, 2 1/2 = 5/2; 15/4 x 2/5 = 30/20 = 3/2 = 1 1/2.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
