INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08093b59-dd7e-49b3-849c-61a2e3040200', 'NC26.6.ANR.2', 2, 'choice', 'One-step fraction word problem', 'A rope is $6\frac{1}{2}$ meters long. A piece $2\frac{3}{4}$ meters long is cut off. How long is the rest of the rope?', '["$3\\frac{3}{4}$","$4\\frac{1}{4}$","$9\\frac{1}{4}$","$3\\frac{1}{4}$"]', '$3\frac{3}{4}$', NULL, '$6\frac{1}{2} = \frac{26}{4}$ and $2\frac{3}{4} = \frac{11}{4}$. Then $\frac{26}{4} - \frac{11}{4} = \frac{15}{4} = 3\frac{3}{4}$ meters.', 'checked', '{"lint":[],"solve":{"answer":"$3\\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 1/2 = 6 2/4 = 5 6/4; 5 6/4 - 2 3/4 = 3 3/4 meters.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50b9a45d-a484-41d0-9360-f4d128cc14d0', 'NC26.6.ANR.2', 2, 'numeric', 'Multi-step fraction word problem', 'Dana has $5\frac{1}{4}$ meters of ribbon. She uses $1\frac{1}{2}$ meters for a gift and cuts the rest into pieces $\frac{3}{4}$ meter long. How many pieces does she cut?', '[]', '5', '((5+1/4)-(1+1/2))/(3/4)', 'Ribbon left: $5\frac{1}{4} - 1\frac{1}{2} = 3\frac{3}{4}$ meters. Pieces: $3\frac{3}{4} \div \frac{3}{4} = \frac{15}{4} \div \frac{3}{4} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 1/4 - 1 1/2 = 5 1/4 - 1 2/4 = 3 3/4 = 15/4 m. 15/4 / (3/4) = 5 pieces.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('672f1a9d-2346-473e-8c05-5e370a9ee8ea', 'NC26.6.ANR.2', 2, 'choice', 'Checking reasonableness by estimating', 'Which is the best estimate of $3\frac{7}{8} \times 4\frac{1}{10}$?', '["16","12","8","20"]', '16', NULL, '$3\frac{7}{8}$ is about 4 and $4\frac{1}{10}$ is about 4. Then 4 x 4 = 16.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 7/8 is about 4, 4 1/10 is about 4; 4 x 4 = 16. Exact 31/8 x 41/10 = 1271/80 = about 15.9.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98b67911-f9a6-4c5b-aa13-06e438005841', 'NC26.6.ANR.2', 2, 'choice', 'Checking reasonableness by estimating', 'Without calculating, which statement is true?', '["$6 \\div \\frac{3}{4}$ is less than 6","$6 \\times \\frac{3}{4}$ is less than 6","$6 \\times 1\\frac{1}{4}$ is less than 6","$6 \\div 1\\frac{1}{4}$ is greater than 6"]', '$6 \times \frac{3}{4}$ is less than 6', NULL, 'Multiplying by a number less than 1 makes 6 smaller, so $6 \times \frac{3}{4}$ is less than 6. Dividing by $\frac{3}{4}$ makes it bigger (8); multiplying by $1\frac{1}{4}$ makes it bigger; dividing by $1\frac{1}{4}$ makes it smaller.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times \\frac{3}{4}$ is less than 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 / 1 1/4 < 6 (divisor > 1), so A false. 6 / (3/4) > 6 (divisor < 1), B false. 6 x 1 1/4 > 6, C false. 6 x 3/4 < 6 (factor < 1), D true.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84b3c672-2a4e-40d7-a02e-d76c8b56cac7', 'NC26.6.ANR.2', 2, 'numeric', 'Finding a missing number in a fraction equation', 'What is the value of n in $n \times \frac{5}{6} = \frac{5}{9}$?', '[]', '2/3', '(5/9)/(5/6)', 'Undo the multiplication by dividing: $n = \frac{5}{9} \div \frac{5}{6} = \frac{5}{9} \times \frac{6}{5} = \frac{30}{45} = \frac{2}{3}$. Check: $\frac{2}{3} \times \frac{5}{6} = \frac{10}{18} = \frac{5}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 5/9 / (5/6) = 5/9 x 6/5 = 30/45 = 2/3. Check: 2/3 x 5/6 = 10/18 = 5/9.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d0af842-284b-419f-b238-8c1081de657a', 'NC26.6.ANR.2', 3, 'numeric', 'Multiplying mixed numbers in context', 'A recipe needs $2\frac{1}{2}$ cups of flour. Maya makes $1\frac{3}{5}$ times the recipe. How many cups of flour does she need?', '[]', '4', '5/2*8/5', 'Write the mixed numbers as fractions: $2\frac{1}{2} = \frac{5}{2}$ and $1\frac{3}{5} = \frac{8}{5}$. Then $\frac{5}{2} \times \frac{8}{5} = \frac{40}{10} = 4$ cups.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 1/2 x 1 3/5 = 5/2 x 8/5 = 40/10 = 4 cups.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
