INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0f90074-0785-48bd-9d22-671862b5afc6', 'NC26.6.ANR.2', 3, 'numeric', 'Subtracting fractions and mixed numbers', 'Evaluate $8\frac{1}{4} - 3\frac{5}{6}$.', '[]', '4 5/12', '(8+1/4)-(3+5/6)', '$8\frac{1}{4} = 8\frac{3}{12}$ and $3\frac{5}{6} = 3\frac{10}{12}$. Regroup: $8\frac{3}{12} = 7\frac{15}{12}$. Then $7\frac{15}{12} - 3\frac{10}{12} = 4\frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"4 5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 1/4 = 8 3/12 = 7 15/12; 3 5/6 = 3 10/12; 7 15/12 - 3 10/12 = 4 5/12.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
