INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db107e13-418e-49e9-a8aa-3347ea75436c', 'NC26.6.ANR.2', 3, 'numeric', 'Dividing mixed numbers', 'Calculate $6\frac{2}{3} \div 2\frac{1}{2}$.', '[]', '2 2/3', '(6+2/3)/(2+1/2)', '$6\frac{2}{3} = \frac{20}{3}$ and $2\frac{1}{2} = \frac{5}{2}$. Then $\frac{20}{3} \times \frac{2}{5} = \frac{40}{15} = \frac{8}{3} = 2\frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2 2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 2/3 = 20/3, 2 1/2 = 5/2; 20/3 x 2/5 = 40/15 = 8/3 = 2 2/3.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
