INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53140411-4357-411d-8bba-d38b6970242a', 'NC26.6.ANR.2', 3, 'choice', 'Dividing mixed numbers', 'Choose the quotient of $7\frac{1}{2}$ divided by $1\frac{7}{8}$.', '["4","$14\\frac{1}{16}$","$5\\frac{5}{8}$","$\\frac{1}{4}$"]', '4', '(7+1/2)/(1+7/8)', '$7\frac{1}{2} = \frac{15}{2}$ and $1\frac{7}{8} = \frac{15}{8}$. Then $\frac{15}{2} \times \frac{8}{15} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 1/2 = 15/2, 1 7/8 = 15/8; 15/2 x 8/15 = 8/2 = 4.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
