INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('277285f9-b6d9-47dd-b9e6-7f61b9a1ac2c', 'NC26.6.ANR.2', 3, 'choice', 'Checking reasonableness by estimating', 'Which is the only reasonable value for $4\frac{9}{10} \times 6\frac{1}{8}$?', '["$12\\frac{1}{40}$","$3\\frac{1}{80}$","$300\\frac{1}{80}$","$30\\frac{1}{80}$"]', '$30\frac{1}{80}$', NULL, '$4\frac{9}{10}$ is about 5 and $6\frac{1}{8}$ is about 6, so the product is near 30. (The exact value is $\frac{49}{10} \times \frac{49}{8} = \frac{2401}{80} = 30\frac{1}{80}$.)', 'checked', '{"lint":[],"solve":{"answer":"$30\\frac{1}{80}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"About 5 x 6 = 30. Exact 49/10 x 49/8 = 2401/80 = 30 1/80. Only 30 1/80 is near 30.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
