INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ab40b68-484c-4fc5-ab70-4e3c588c052a', 'NC26.6.ANR.2', 3, 'numeric', 'Finding a missing number in a fraction equation', 'What is the value of n in $n \div \frac{3}{8} = 6\frac{2}{3}$?', '[]', '2 1/2', '(6+2/3)*3/8', 'Undo the division by multiplying: $n = 6\frac{2}{3} \times \frac{3}{8} = \frac{20}{3} \times \frac{3}{8} = \frac{20}{8} = \frac{5}{2} = 2\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"2 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 6 2/3 x 3/8 = 20/3 x 3/8 = 60/24 = 5/2 = 2 1/2. Check: 5/2 / (3/8) = 5/2 x 8/3 = 40/6 = 6 2/3.","run_id":"claude-code","at":"2026-10-17T20:21:50.225Z"}}', 'ai', NULL, NULL)
