VALUES ('70c6e7db-4877-4568-89c7-cbb2e04ecb40', 'NC26.6.ANR.3', 3, 'numeric', 'One-step decimal word problem', 'A copper wire weighs 0.35 kilogram per meter. How many kilograms does a 2.64-meter piece of the wire weigh?', '[]', '0.924', '2.64*0.35', '$2.64 \times 0.35$: 264 x 35 = 9240, and there are 2 + 2 = 4 decimal places, so the answer is 0.9240, which is 0.924 kilogram.', 'checked', '{"lint":[],"solve":{"answer":"0.924","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.64 x 0.35: 264 x 35 = 9240, four decimal places: 0.9240 = 0.924 kg.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
