INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94babace-416b-47dc-8c48-37e40fedc32c', 'NC26.6.ANR.3', 3, 'numeric', 'Multi-step decimal word problem', 'A taxi charges 3.50 dollars to start plus 2.15 dollars for each mile. How many dollars does a 6-mile ride cost?', '[]', '16.4', '3.5+6*2.15', 'Miles: $6 \times 2.15 = 12.90$. Add the starting charge: $12.90 + 3.50 = 16.40$, which is 16.4 dollars.', 'checked', '{"lint":[],"solve":{"answer":"16.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2.15 = 12.90; 3.50 + 12.90 = 16.40 dollars.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
