INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be2fbdde-5f8c-44d2-8455-fab421b83b0c', 'NC26.6.ANR.3', 3, 'numeric', 'Multi-step decimal word problem', 'Lena buys 2.5 kilograms of apples at 1.80 dollars per kilogram and 0.75 kilogram of cheese at 12.40 dollars per kilogram. How many dollars does she spend in all?', '[]', '13.8', '2.5*1.8+0.75*12.4', 'Apples: $2.5 \times 1.80 = 4.50$. Cheese: $0.75 \times 12.40 = 9.30$. Total: $4.50 + 9.30 = 13.80$, which is 13.8 dollars.', 'checked', '{"lint":[],"solve":{"answer":"13.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5 x 1.80 = 4.50; 0.75 x 12.40 = 9.30; 4.50 + 9.30 = 13.80 dollars.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
