VALUES ('a35c8b46-ba88-4ad8-93e9-ab6a1925653f', 'NC26.6.ANR.3', 3, 'choice', 'Multi-step decimal word problem', 'Jordan has 40 dollars. A game costs 24.95 dollars and a case costs 6.80 dollars. How many dollars does Jordan have left after buying both?', '["15.05","8.35","8.25","71.75"]', '8.25', '40-24.95-6.8', 'Both items: $24.95 + 6.80 = 31.75$. Left: $40.00 - 31.75 = 8.25$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"8.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24.95 + 6.80 = 31.75; 40 - 31.75 = 8.25 dollars.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
