INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d34986d1-8693-4230-a41b-c6e83c713540', 'NC26.6.ANR.3', 3, 'choice', 'Multi-step decimal word problem', 'Eva runs 4.35 kilometers on each of 3 mornings and 2.8 kilometers on each of 2 evenings. She wants to run 25 kilometers this week. How many more kilometers does she need to run?', '["18.65","6.35","11.95","5.35"]', '6.35', '25-3*4.35-2*2.8', 'Mornings: $3 \times 4.35 = 13.05$. Evenings: $2 \times 2.8 = 5.6$. So far: $13.05 + 5.60 = 18.65$. Still to run: $25 - 18.65 = 6.35$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"6.35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 4.35 = 13.05; 2 x 2.8 = 5.6; 13.05 + 5.6 = 18.65 km run; 25 - 18.65 = 6.35 km more.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f965a71e-b0a0-4cb6-be07-3393fc070d63', 'NC26.6.ANR.3', 3, 'choice', 'Reasoning about decimal operations', 'Dev says $5.2 \div 0.4 = 1.3$, because $52 \div 4 = 13$. Which statement is true?', '["He should not move the decimal point in the quotient; $5.2 \\div 0.4 = 13$","He is right, because dividing by a number less than 1 gives a smaller answer","He should have moved it two places; $5.2 \\div 0.4 = 0.13$","He is right, because the decimal point moves one place left when dividing by tenths"]', 'He should not move the decimal point in the quotient; $5.2 \div 0.4 = 13$', NULL, 'Multiplying both numbers by 10 gives $52 \div 4 = 13$, and the quotient does not change when both numbers are multiplied by the same amount. So $5.2 \div 0.4 = 13$. Check: 0.4 x 13 = 5.2.', 'checked', '{"lint":[],"solve":{"answer":"He should not move the decimal point in the quotient; $5.2 \\div 0.4 = 13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.2 / 0.4 = 52 / 4 = 13 (multiply both by 10; quotient unchanged). 1.3 is wrong (dividing by < 1 gives more than 5.2); 0.13 wrong. So 13.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5479cc9a-6941-47f6-b98f-01602f8e980d', 'NC26.6.ANR.3', 3, 'choice', 'Reasoning about decimal operations', 'Without finding exact values, which expression has the greatest value?', '["$0.9 \\times 4.6$","$4.6 - 0.9$","$4.6 + 0.09$","$4.6 \\div 0.9$"]', '$4.6 \div 0.9$', NULL, 'Dividing 4.6 by 0.9, which is less than 1, gives more than 4.6 (about 5.1). The others are 4.14, 3.7 and 4.69, which are all less than 5.', 'checked', '{"lint":[],"solve":{"answer":"$4.6 \\div 0.9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.9 x 4.6 < 4.6 (4.14); 4.6 + 0.09 = 4.69; 4.6 - 0.9 = 3.7; 4.6 / 0.9 > 4.6 and about 5.11. Greatest: 4.6 / 0.9.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d154d72-5026-471f-a8ec-f4907de40c6a', 'NC26.6.ANR.3', 3, 'numeric', 'Finding a missing number in a decimal equation', 'What is the value of n in $n \times 0.35 = 2.8$?', '[]', '8', '2.8/0.35', 'Undo the multiplication by dividing: $n = 2.8 \div 0.35 = 280 \div 35 = 8$. Check: 8 x 0.35 = 2.8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 2.8 / 0.35 = 280 / 35 = 8.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
