INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c1ff81c-adf8-44c7-a85e-f0459dde07dd', 'NC26.6.ANR.3', 3, 'numeric', 'Finding a missing number in a decimal equation', 'A number is multiplied by 0.25, and then 1.5 is added. The result is 4.75. What is the number?', '[]', '13', '(4.75-1.5)/0.25', 'Work backward. Undo the addition: $4.75 - 1.5 = 3.25$. Undo the multiplication: $3.25 \div 0.25 = 13$. Check: 13 x 0.25 = 3.25, and 3.25 + 1.5 = 4.75.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.25n + 1.5 = 4.75; 0.25n = 3.25; n = 3.25 / 0.25 = 13. Check: 13 x 0.25 = 3.25, + 1.5 = 4.75.","run_id":"claude-code","at":"2026-10-17T20:21:50.263Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
