INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66671c5e-0dfe-49ff-93bc-871fc7e49d53', 'NC26.6.ANR.4', 1, 'choice', 'Zero pairs and chip models', 'Which collection of chips has a total value of 0?', '["6 positive chips and 5 negative chips","6 positive chips and 12 negative chips","12 positive chips and 6 negative chips","6 positive chips and 6 negative chips"]', '6 positive chips and 6 negative chips', NULL, 'The chips must pair off completely. Only 6 positive chips and 6 negative chips make 6 zero pairs with nothing left over. The other collections leave 1 negative chip, 6 negative chips or 6 positive chips.', 'checked', '{"lint":[],"solve":{"answer":"6 positive chips and 6 negative chips","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Totals: 12-6=6, 6-12=-6, 6-6=0, 6-5=1. Only 6 and 6 gives 0.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
