VALUES ('51e13b54-8384-4540-9400-c8e68feb868e', 'NC26.6.ANR.4', 1, 'choice', 'Dividing integers', 'Which statement about division is true?', '["A negative integer divided by a negative integer is negative.","A positive integer divided by a negative integer is positive.","A negative integer divided by a positive integer is negative.","Zero divided by a negative integer is negative."]', 'A negative integer divided by a positive integer is negative.', NULL, 'Numbers with different signs give a negative quotient. Numbers with the same sign give a positive quotient, and zero divided by any nonzero number is 0.', 'checked', '{"lint":[],"solve":{"answer":"A negative integer divided by a positive integer is negative.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"neg/neg is positive (false); 0/neg = 0, not negative (false); neg/pos is negative (true); pos/neg is negative (false).","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
