VALUES ('40a71146-7f76-4d50-a375-be566a9de3e0', 'NC26.6.ANR.4', 2, 'choice', 'Dividing integers', 'Which quotient is equal to $-4$?', '["$-20 \\div (-5)$","$20 \\div 5$","$-20 + 5$","$-20 \\div 5$"]', '$-20 \div 5$', NULL, '$-20 \div 5 = -4$ because the signs are different. The others equal 4, 4 and $-15$.', 'checked', '{"lint":[],"solve":{"answer":"$-20 \\div 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/5 = 4; -20/5 = -4; -20/(-5) = 4; -20+5 = -15. Only -20 / 5.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
