INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6883865b-84e1-4cdf-b4a4-2521c8b543fb', 'NC26.6.ANR.4', 2, 'choice', 'Models for integer operations (number line and groups)', 'Start at 3 on a number line and move 8 units to the left. Which expression shows this?', '["$3 + 8$","$-3 + 8$","$-3 + (-8)$","$3 + (-8)$"]', '$3 + (-8)$', NULL, 'You start at 3, and a move of 8 to the left is adding $-8$. So the expression is $3 + (-8)$, which equals $-5$.', 'checked', '{"lint":[],"solve":{"answer":"$3 + (-8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start at 3, move 8 left = add -8: 3 + (-8) = -5.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
