INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1b019bc-7c0c-44fd-be78-0cb65c331835', 'NC26.6.ANR.4', 2, 'numeric', 'Models for integer operations (number line and groups)', 'To find $-15 \div 3$, Mo shares 15 negative chips equally among 3 groups. What is the value of the chips in one group, as an integer?', '[]', '-5', '-15/3', 'Each group gets $15 \div 3 = 5$ negative chips, which is worth $-5$. So $-15 \div 3 = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 negative chips shared into 3 groups: 5 negative chips each, value -5.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
