INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d878ce4-60e0-4a4c-a010-e8adb6abbda0', 'NC26.6.ANR.4', 2, 'numeric', 'Checking reasonableness', 'To check $-19 + 11$, a student rounds each number to the nearest ten and adds. What is the estimate the student gets?', '[]', '-10', '-20+10', '$-19$ rounds to $-20$ and 11 rounds to 10. The estimate is $-20 + 10 = -10$. The exact answer is $-8$, which is close.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-19 rounds to -20; 11 rounds to 10. -20 + 10 = -10.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
