INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aed28e50-a224-4be0-9e28-2f8804f59574', 'NC26.6.ANR.4', 2, 'choice', 'Checking reasonableness', 'Sam says $-4 \times (-5)$ is about $-20$. Which statement checks his estimate?', '["His estimate has the wrong sign: the product should be about 20.","His estimate is reasonable, because both numbers are negative.","His estimate is the wrong size: it should be about 9.","His estimate has the wrong sign and the wrong size."]', 'His estimate has the wrong sign: the product should be about 20.', NULL, 'Two negative factors give a positive product, and $4 \times 5 = 20$. So the product is $20$, and his size is right but his sign is wrong.', 'checked', '{"lint":[],"solve":{"answer":"His estimate has the wrong sign: the product should be about 20.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-4)(-5) = 20 (neg x neg = pos). Size 20 is right, sign is wrong.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
