INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6c92a4d-530a-429b-82e3-360b7f568942', 'NC26.6.ANR.4', 3, 'choice', 'Subtraction as adding the opposite', 'Which expression does NOT have the same value as $9 - (-4)$?', '["$9 + (-4)$","$9 + 4$","$4 - (-9)$","$-4 - (-17)$"]', '$9 + (-4)$', NULL, '$9 - (-4) = 13$. The expressions $9 + 4$, $4 - (-9) = 13$ and $-4 - (-17) = 13$ all equal 13. But $9 + (-4) = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$9 + (-4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - (-4) = 13. 9+(-4) = 5; 4-(-9) = 13; 9+4 = 13; -4-(-17) = 13. Only 9 + (-4) differs.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
