INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2fd0cf5-a5af-416b-a86c-eef54647d530', 'NC26.6.ANR.4', 3, 'numeric', 'Subtraction as adding the opposite', 'Write $-5 - (-12) - 9$ as a sum of three integers, then find its value.', '[]', '-2', '-5+12-9', 'Subtracting $-12$ is adding 12, and subtracting 9 is adding $-9$. So the sum is $-5 + 12 + (-9) = 7 + (-9) = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5 + 12 + (-9): -5 + 12 = 7; 7 - 9 = -2.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
