INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53e03fbc-cea4-447b-ae43-42a831a8a896', 'NC26.6.ANR.4', 3, 'numeric', 'Subtraction as adding the opposite', 'For what integer $n$ is $-7 - n = -7 + 10$ true?', '[]', '-10', '-10', 'The right side is 3. For $-7 - n$ to equal $-7 + 10$, subtracting $n$ must be the same as adding 10, so $n$ is the opposite of 10, which is $-10$. Check: $-7 - (-10) = 3$.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-7 - n = -7 + (-n) must equal -7 + 10, so -n = 10, n = -10. Check: -7 - (-10) = 3 = -7 + 10.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
