VALUES ('5cba0282-70af-42fe-9f95-44d3a6b15bf3', 'NC26.6.ANR.4', 3, 'choice', 'Dividing integers', 'Which expression has the same value as $-18 \div 6$?', '["$-18 \\div (-6)$","$18 \\div 6$","$-18 + 6$","$18 \\div (-6)$"]', '$18 \div (-6)$', NULL, '$-18 \div 6 = -3$, and $18 \div (-6) = -3$ too. The others are $3$, $3$ and $-12$.', 'checked', '{"lint":[],"solve":{"answer":"$18 \\div (-6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-18 / 6 = -3. 18/6 = 3; -18/(-6) = 3; -18+6 = -12; 18/(-6) = -3.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
