VALUES ('4b22ce42-7981-491a-b708-3256b2a4c00b', 'NC26.6.ANR.4', 3, 'choice', 'Checking reasonableness', 'Exactly one of these equations is false. Which one?', '["$-13 + 5 = -8$","$-7 - 6 = -13$","$-12 \\div 4 = -3$","$-9 \\times 2 = 18$"]', '$-9 \times 2 = 18$', NULL, 'A negative times a positive must be negative, so $-9 \times 2 = -18$, not 18. The other three equations are correct.', 'checked', '{"lint":[],"solve":{"answer":"$-9 \\times 2 = 18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9 x 2 = -18, not 18 (false). -7 - 6 = -13 true; -12/4 = -3 true; -13 + 5 = -8 true.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
