INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f179a7b-d220-45fd-8184-ed8873b14686', 'NC26.6.ANR.4', 3, 'choice', 'Checking reasonableness', 'Without working out the values, which expression must be negative?', '["$(-4) \\times (-3) \\div 2$","$(-4) \\times (-3) \\div (-2)$","$(-4) \\times 2 \\div (-2)$","$(-4) \\div (-2) \\times (-1) \\times (-1)$"]', '$(-4) \times (-3) \div (-2)$', NULL, 'The first expression has three negative factors, so its value is negative ($-6$). The others have two, two and four negative numbers, so they are positive.', 'checked', '{"lint":[],"solve":{"answer":"$(-4) \\times (-3) \\div (-2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count negatives: A has 3 (odd) -> negative (12/-2 = -6). B has 2 -> positive (4). C has 2 -> positive (6). D has 4 -> positive (2).","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
