INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d374d81b-b48c-4d95-9a18-73cba2ea5ff2', 'NC26.6.ANR.4', 3, 'numeric', 'Integers in context', 'Anna''s account balance is 7 dollars. She spends 12 dollars, earns 5 dollars and then spends 9 dollars. What is her balance now, in dollars?', '[]', '-9', '7-12+5-9', '$7 - 12 = -5$, then $-5 + 5 = 0$, then $0 - 9 = -9$. She owes 9 dollars.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 - 12 = -5; -5 + 5 = 0; 0 - 9 = -9.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
