INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8ee4372-b611-42d3-b22a-879b56b85983', 'NC26.6.ANR.4', 3, 'numeric', 'Integers in context', 'The temperature was 4 degrees. Then it fell 3 degrees each hour for 5 hours. What was the temperature after 5 hours, in degrees?', '[]', '-11', '4+5*(-3)', 'The total change is $5 \times (-3) = -15$ degrees. Then $4 + (-15) = -11$.', 'checked', '{"lint":[],"solve":{"answer":"-11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change 5 x (-3) = -15; 4 + (-15) = -11.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
