INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa08356-7727-4ff9-9486-651c43e4ec3b', 'NC26.6.ANR.4', 3, 'numeric', 'Integers in context', 'In a game, each of 3 players loses 4 points, and a fourth player gains 7 points. What is the total change in points for all four players?', '[]', '-5', '3*(-4)+7', 'The three losses total $3 \times (-4) = -12$. Adding the gain of 7 gives $-12 + 7 = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x (-4) = -12; -12 + 7 = -5.","run_id":"claude-code","at":"2026-10-17T20:20:36.614Z"}}', 'ai', NULL, NULL)
