INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0edbd7b5-8fa6-4adc-a403-250a12d11f6a', 'NC26.6.ANR.5', 2, 'choice', 'Comparing two rational numbers', 'Select the true inequality.', '["$-0.3 < -0.1$","$\\frac{2}{3} > \\frac{3}{4}$","$0.4 > \\frac{1}{2}$","$-\\frac{1}{2} > -\\frac{1}{4}$"]', '$-0.3 < -0.1$', NULL, '$-0.3$ is left of $-0.1$, so $-0.3 < -0.1$ is true. The others are false: $\frac{2}{3} < \frac{3}{4}$, $0.4 < \frac{1}{2}$ and $-\frac{1}{2} < -\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$-0.3 < -0.1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-0.5 > -0.25 false; 0.667 > 0.75 false; -0.3 < -0.1 true (-0.3 is further left); 0.4 > 0.5 false.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('574888c8-fb4d-4510-b296-177be07f41cb', 'NC26.6.ANR.5', 2, 'numeric', 'Comparing two rational numbers', 'How many of the numbers 0.2, $\frac{1}{4}$, 0.3 and $\frac{1}{5}$ are less than $\frac{1}{4}$?', '[]', '2', '2', '$\frac{1}{4} = 0.25$ and $\frac{1}{5} = 0.2$. The numbers less than 0.25 are 0.2 and $\frac{1}{5}$. The number $\frac{1}{4}$ itself is not less than $\frac{1}{4}$, and 0.3 is greater. So there are 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 0.25. 0.2 < 0.25 yes; 1/4 is equal, not less; 0.3 no; 1/5 = 0.2 yes. Count = 2.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7ad8f78-bd97-4ce4-818a-ed1f0de77dec', 'NC26.6.ANR.5', 2, 'choice', 'Comparing two rational numbers', 'Which number is greater than $\frac{5}{6}$?', '["$\\frac{4}{5}$","$\\frac{3}{4}$","$\\frac{2}{3}$","$\\frac{7}{8}$"]', '$\frac{7}{8}$', NULL, 'Each fraction is a piece missing from one whole: $\frac{5}{6}$ is missing $\frac{1}{6}$, and $\frac{7}{8}$ is missing only $\frac{1}{8}$, which is smaller. So $\frac{7}{8}$ is greater. The others are missing $\frac{1}{5}$, $\frac{1}{4}$ and $\frac{1}{3}$, which are larger.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{7}{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/6 = 0.833. 2/3 = 0.667, 4/5 = 0.8, 7/8 = 0.875, 3/4 = 0.75. Only 7/8 is greater.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
