VALUES ('ac23e2a0-8909-488d-96c4-6754fc5d1f3c', 'NC26.6.ANR.5', 2, 'choice', 'Ordering rational numbers', 'Which list shows $1\frac{1}{4}$, $1.2$, $\frac{9}{8}$ and $1.3$ from least to greatest?', '["$1.2, \\frac{9}{8}, 1\\frac{1}{4}, 1.3$","$1.2, 1\\frac{1}{4}, \\frac{9}{8}, 1.3$","$\\frac{9}{8}, 1.2, 1.3, 1\\frac{1}{4}$","$\\frac{9}{8}, 1.2, 1\\frac{1}{4}, 1.3$"]', '$\frac{9}{8}, 1.2, 1\frac{1}{4}, 1.3$', NULL, 'As decimals the numbers are 1.25, 1.2, 1.125 and 1.3. From least to greatest: 1.125, 1.2, 1.25, 1.3, which is $\frac{9}{8}$, $1.2$, $1\frac{1}{4}$, $1.3$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{9}{8}, 1.2, 1\\frac{1}{4}, 1.3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 1/4 = 1.25, 9/8 = 1.125. Order: 1.125, 1.2, 1.25, 1.3.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d26e48c-6388-4287-bd23-bd73ebd975f2', 'NC26.6.ANR.5', 2, 'numeric', 'Ordering rational numbers', 'Four runners ran $2\frac{1}{2}$, 2.45, $2\frac{2}{5}$ and 2.6 kilometers. What is the second greatest distance, in kilometers, written as a decimal?', '[]', '2.5', '2+1/2', 'As decimals the distances are 2.5, 2.45, 2.4 and 2.6. From greatest to least: 2.6, 2.5, 2.45, 2.4. The second greatest is 2.5.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 1/2 = 2.5, 2 2/5 = 2.4. Values 2.5, 2.45, 2.4, 2.6. Greatest 2.6, second greatest 2.5.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
