INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91170d66-37d1-424c-ad1c-7d63896b22c6', 'NC26.6.ANR.5', 3, 'choice', 'Comparing two rational numbers', 'Which of these inequalities is true?', '["$2\\frac{1}{3} > 2.4$","$-2\\frac{1}{2} < -2.6$","$3.05 > 3\\frac{1}{5}$","$-1\\frac{3}{4} < -1.7$"]', '$-1\frac{3}{4} < -1.7$', NULL, '$-1\frac{3}{4} = -1.75$, which is left of $-1.7$, so it is less. The others are false: $2\frac{1}{3} < 2.4$, $-2.5 > -2.6$ and $3.05 < 3.2$.', 'checked', '{"lint":[],"solve":{"answer":"$-1\\frac{3}{4} < -1.7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2.5 < -2.6 false; 3.05 > 3.2 false; 2.333 > 2.4 false; -1.75 < -1.7 true.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
