INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ced1309-fe79-46e1-b71c-a7cd47f9b068', 'NC26.6.ANR.5', 3, 'numeric', 'Comparing two rational numbers', 'What is the greatest of the numbers $\frac{7}{10}$, 0.72, $\frac{3}{4}$ and 0.07? Give your answer as a decimal.', '[]', '0.75', '3/4', 'As decimals the numbers are 0.70, 0.72, 0.75 and 0.07. The greatest is 0.75, which is $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.70, 0.72, 0.75, 0.07: greatest 0.75.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
