INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6013dbfa-6b7a-4bf3-afb0-cba1a81097b2', 'NC26.6.ANR.5', 3, 'numeric', 'Comparing two rational numbers', 'Which is greater, $-\frac{2}{3}$ or $-\frac{3}{5}$? Enter the greater number as a fraction.', '[]', '-3/5', '-3/5', '$\frac{2}{3}$ is about 0.667 and $\frac{3}{5}$ is 0.6, so $-\frac{2}{3}$ is about $-0.667$ and $-\frac{3}{5}$ is $-0.6$. The one nearer to 0 is greater: $-\frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"-3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/3 = 10/15, 3/5 = 9/15. -10/15 < -9/15, so -3/5 is greater.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
