INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bd80e3f-1e20-47ff-9b08-32956c396c75', 'NC26.6.ANR.5', 3, 'choice', 'Comparing two rational numbers', 'Which number lies between $\frac{1}{3}$ and $\frac{1}{2}$?', '["$0.4$","$0.3$","$0.55$","$0.25$"]', '$0.4$', '0.4', '$\frac{1}{3}$ is about 0.333 and $\frac{1}{2}$ is 0.5. Only 0.4 is greater than 0.333 and less than 0.5.', 'checked', '{"lint":[],"solve":{"answer":"$0.4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/3 = 0.333, 1/2 = 0.5. 0.4 is between; 0.55, 0.25, 0.3 are not.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
