INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aae9fecc-1771-493c-8a70-5308616eced7', 'NC26.6.ANR.5', 3, 'numeric', 'Comparing two rational numbers', 'How many of the numbers $-\frac{3}{4}$, $-\frac{1}{3}$, 0, $-0.51$ and $\frac{1}{10}$ are greater than $-0.5$?', '[]', '3', '3', 'The numbers greater than $-0.5$ are $-\frac{1}{3}$ (about $-0.33$), 0 and $\frac{1}{10}$. The numbers $-\frac{3}{4}$ and $-0.51$ are less than $-0.5$. So there are 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-0.75 no; -0.333 yes; 0 yes; -0.51 no; 0.1 yes. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
