INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea4b604d-2794-429d-b1cf-95b376ac471a', 'NC26.6.ANR.5', 3, 'choice', 'Ordering rational numbers', 'Place $-\frac{3}{4}$, $-0.8$, $\frac{1}{5}$ and $-0.7$ on a number line from left to right. Which list gives the order?', '["$-0.8, -\\frac{3}{4}, -0.7, \\frac{1}{5}$","$-0.7, -\\frac{3}{4}, -0.8, \\frac{1}{5}$","$-\\frac{3}{4}, -0.8, -0.7, \\frac{1}{5}$","$\\frac{1}{5}, -0.7, -\\frac{3}{4}, -0.8$"]', '$-0.8, -\frac{3}{4}, -0.7, \frac{1}{5}$', NULL, 'As decimals the numbers are $-0.75$, $-0.8$, 0.2 and $-0.7$. From left to right (least to greatest): $-0.8$, $-0.75$, $-0.7$, 0.2.', 'checked', '{"lint":[],"solve":{"answer":"$-0.8, -\\frac{3}{4}, -0.7, \\frac{1}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3/4 = -0.75, 1/5 = 0.2. Left to right: -0.8, -0.75, -0.7, 0.2.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e329426-1704-4e05-868d-62d0cca35467', 'NC26.6.ANR.5', 3, 'numeric', 'Ordering rational numbers', 'When $-0.35$, $-\frac{2}{5}$ and $-\frac{1}{2}$ are ordered from least to greatest, which number is in the middle? Give it as a decimal.', '[]', '-0.4', '-2/5', 'As decimals they are $-0.35$, $-0.4$ and $-0.5$. From least to greatest: $-0.5$, $-0.4$, $-0.35$. The middle number is $-0.4$.', 'checked', '{"lint":[],"solve":{"answer":"-0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2/5 = -0.4, -1/2 = -0.5. Least to greatest: -0.5, -0.4, -0.35. Middle -0.4.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
