INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('906470fc-345b-41b3-9ff6-e47ed9bc59c0', 'NC26.6.ANR.5', 3, 'numeric', 'Ordering rational numbers', 'How many of the numbers 0.31, $\frac{3}{10}$, $\frac{1}{3}$, 0.299, $\frac{2}{7}$ and $\frac{3}{8}$ are greater than 0.3 and less than 0.4?', '[]', '3', '3', 'As decimals they are 0.31, 0.3, about 0.333, 0.299, about 0.286 and 0.375. Those between 0.3 and 0.4 are 0.31, $\frac{1}{3}$ and $\frac{3}{8}$. The number $\frac{3}{10}$ equals 0.3, so it is not greater than 0.3. So there are 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.31 yes; 3/10 = 0.3 not greater; 1/3 = 0.333 yes; 0.299 no; 2/7 = 0.2857 no; 3/8 = 0.375 yes. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64590d33-bf89-4cac-908b-421227a50535', 'NC26.6.ANR.5', 3, 'numeric', 'Ordering rational numbers', 'Order $\frac{4}{5}$, 0.81, $\frac{5}{6}$, 0.78 and $\frac{7}{9}$ from least to greatest. Which number is in the middle? Give your answer as a fraction.', '[]', '4/5', '4/5', 'As decimals the numbers are 0.8, 0.81, about 0.833, 0.78 and about 0.778. From least to greatest: $\frac{7}{9}$, 0.78, $\frac{4}{5}$, 0.81, $\frac{5}{6}$. The middle one is $\frac{4}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"4/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/5 = 0.8, 5/6 = 0.833, 7/9 = 0.777... Order: 7/9 (0.777), 0.78, 4/5 (0.80), 0.81, 5/6 (0.833). Middle is 4/5.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebc37b08-2bcf-4479-bdfe-fa0963a2dc4a', 'NC26.6.ANR.5', 3, 'choice', 'Ordering rational numbers', 'Which statement about $\frac{1}{3}$, $0.3$ and $\frac{3}{10}$ is true?', '["$\\frac{1}{3}$ is the least of the three.","$0.3$ and $\\frac{3}{10}$ are equal, and both are less than $\\frac{1}{3}$.","$0.3$ is greater than $\\frac{3}{10}$.","$\\frac{3}{10}$ is greater than $\\frac{1}{3}$."]', '$0.3$ and $\frac{3}{10}$ are equal, and both are less than $\frac{1}{3}$.', NULL, '$\frac{3}{10} = 0.3$, and $\frac{1}{3}$ is about 0.333, which is greater than 0.3. So 0.3 and $\frac{3}{10}$ are equal and both less than $\frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$0.3$ and $\\frac{3}{10}$ are equal, and both are less than $\\frac{1}{3}$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3 = 3/10, and 1/3 = 0.333 > 0.3. So the first statement is true; the rest are false.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5768fa8-58dc-4633-97ba-decd9b5e4373', 'NC26.6.ANR.5', 3, 'numeric', 'Rational numbers on the number line', 'On a number line, how many units apart are $-7$ and 5?', '[]', '12', '5-(-7)', 'From $-7$ to 0 is 7 units and from 0 to 5 is 5 more units. The distance is $7 + 5 = 12$ units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|5 - (-7)| = 7 + 5 = 12.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38f38646-cd88-4b10-ac2b-869dbf4ea52a', 'NC26.6.ANR.5', 3, 'choice', 'Rational numbers on the number line', 'A number line from 0 to 2 is divided into 8 equal parts. Point Q is 5 marks to the right of 0. Which number is point Q?', '["$\\frac{5}{8}$","$1\\frac{1}{8}$","$\\frac{5}{2}$","$1\\frac{1}{4}$"]', '$1\frac{1}{4}$', NULL, 'Each part is $2 \div 8 = \frac{1}{4}$. Five parts is $\frac{5}{4} = 1\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$1\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each part is 2/8 = 1/4. 5 parts = 5/4 = 1 1/4.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae99d20e-2bf4-4444-b26a-43c38596af93', 'NC26.6.ANR.5', 3, 'numeric', 'Rational numbers on the number line', 'A point is halfway between $-\frac{1}{2}$ and $\frac{3}{2}$ on a number line. What number is it?', '[]', '1/2', '(-1/2+3/2)/2', 'The halfway point is the average: $\left(-\frac{1}{2} + \frac{3}{2}\right) \div 2 = 1 \div 2 = \frac{1}{2}$. It is 1 unit from each end.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-1/2 + 3/2) / 2 = 1 / 2 = 1/2. Check: 1 unit from each end.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
