INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2b51d52-bc45-4d99-b7c7-d05172ccff31', 'NC26.6.ANR.5', 3, 'numeric', 'Rational numbers on the number line', 'Point M is at $-2.5$ on a number line. Point N is 1.5 units to the left of M. What number is at point N?', '[]', '-4', '-2.5-1.5', 'Moving left subtracts: $-2.5 - 1.5 = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2.5 - 1.5 = -4.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
