INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36a030fe-4d8d-4129-812a-35c7bc51fc36', 'NC26.6.ANR.5', 3, 'numeric', 'Absolute value', 'Find the value of $|3 - 11| + |-2|$.', '[]', '10', '8+2', '$3 - 11 = -8$, so $|3 - 11| = 8$. Also $|-2| = 2$. The total is $8 + 2 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 - 11 = -8, |-8| = 8; |-2| = 2; 8 + 2 = 10.","run_id":"claude-code","at":"2026-10-17T20:20:36.653Z"}}', 'ai', NULL, NULL)
