VALUES ('796759f5-ed8f-462a-aa59-0876f13df667', 'NC26.6.ANR.6', 1, 'numeric', 'Evaluating algebraic expressions', 'A rental company charges 5 dollars per hour. The cost of renting for $h$ hours is $5h$ dollars. How many dollars does it cost to rent for 6 hours?', '[]', '30', '5*6', 'Replace $h$ with 6: $5h = 5 \times 6 = 30$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 6 = 30.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
