VALUES ('d62a4943-45b4-4292-acf7-46dbcfc752df', 'NC26.6.ANR.6', 2, 'numeric', 'Evaluating an algebraic expression', 'What is the value of $3x + 5$ when $x = 4$?', '[]', '17', '3*4+5', 'Substitute 4 for $x$: $3 \times 4 + 5 = 12 + 5 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(4) + 5 = 12 + 5 = 17.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
