INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33df8e0d-8031-4145-b711-91ad89a39209', 'NC26.6.ANR.6', 2, 'choice', 'Whole-number exponents', 'Which of these is equal to $4^3$?', '["$12$","$64$","$81$","$16$"]', '$64$', '4^3', '$4^3 = 4 \times 4 \times 4 = 16 \times 4 = 64$. The value 12 is $4 \times 3$, 81 is $3^4$ and 16 is $4^2$.', 'checked', '{"lint":[],"solve":{"answer":"$64$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 4 x 4 = 64.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
