INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf95804c-95bb-4fcc-bc2c-dc7452ee8a78', 'NC26.6.ANR.6', 2, 'numeric', 'Whole-number exponents', 'Mia writes $6 \times 6 \times 6 \times 6$ as a power of 6 and then finds the value of that power. What value does she get?', '[]', '1296', '6^4', 'The product is $6^4$. Then $6 \times 6 = 36$, $36 \times 6 = 216$ and $216 \times 6 = 1{,}296$.', 'checked', '{"lint":[],"solve":{"answer":"1296","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6^4 = 36 x 36 = 1296.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
