INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39770c64-7c0e-4fc9-8a48-b201e57f02ed', 'NC26.6.ANR.6', 2, 'choice', 'Whole-number exponents', 'Which statement about $3^4$ and $4^3$ is true?', '["$4^3$ is greater; $4^3 = 64$ and $3^4 = 12$","They are equal; $3^4 = 12$ and $4^3 = 12$","$4^3$ is greater; $4^3 = 81$ and $3^4 = 64$","$3^4$ is greater; $3^4 = 81$ and $4^3 = 64$"]', '$3^4$ is greater; $3^4 = 81$ and $4^3 = 64$', NULL, '$3^4 = 3 \times 3 \times 3 \times 3 = 81$ and $4^3 = 4 \times 4 \times 4 = 64$. So $3^4$ is greater. Neither power is $3 \times 4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$3^4$ is greater; $3^4 = 81$ and $4^3 = 64$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^4 = 81, 4^3 = 64, so 3^4 is greater. Only option B states this with correct values.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57f3ee1d-5bd7-41ad-903b-e0406957d32f', 'NC26.6.ANR.6', 2, 'numeric', 'Whole-number exponents', 'The number of bacteria in a dish triples every hour. At the start there is 1 bacterium, so after 1 hour there are 3. How many bacteria are in the dish after 4 hours?', '[]', '81', '3^4', 'After 4 hours the number has been multiplied by 3 four times, which is $3^4 = 3 \times 3 \times 3 \times 3 = 81$. Check: 1, 3, 9, 27, 81.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"After h hours there are 3^h bacteria; 3^4 = 81.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
