INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e45a01b-6123-46fa-b3fb-19fda568dc21', 'NC26.6.ANR.6', 2, 'choice', 'Order of operations', 'Which expression has the greatest value?', '["$2 + 3 \\times 4$","$2 \\times 3 + 4$","$2 + 3 + 4$","$(2 + 3) \\times 4$"]', '$(2 + 3) \times 4$', NULL, '$2 + 3 \times 4 = 14$, $(2 + 3) \times 4 = 20$, $2 \times 3 + 4 = 10$ and $2 + 3 + 4 = 9$. The greatest value is 20, from $(2 + 3) \times 4$.', 'checked', '{"lint":[],"solve":{"answer":"$(2 + 3) \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 12 = 14; 2 + 3 + 4 = 9; 5 x 4 = 20; 6 + 4 = 10. Greatest: (2 + 3) x 4.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
