INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4109c083-3ceb-41fe-b332-11318b012ed4', 'NC26.6.ANR.6', 2, 'numeric', 'Translating words to expressions', 'The phrase "twice the sum of a number $n$ and 6" can be written as an expression. What is the value of that expression when $n = 4$?', '[]', '20', '2*(4+6)', 'The sum of $n$ and 6 is $n + 6$, and twice that is $2(n + 6)$. When $n = 4$ it is $2(4 + 6) = 2 \times 10 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(n + 6); at n = 4: 2 x 10 = 20.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
