VALUES ('dfc6b59a-4146-45fd-bbad-74a07a45bf00', 'NC26.6.ANR.6', 2, 'choice', 'Parts of an expression', 'Which two terms are like terms?', '["$4a$ and $9b$","$4a$ and $9a$","$4a$ and $9$","$4a$ and $4b$"]', '$4a$ and $9a$', NULL, 'Like terms have the same variable part. $4a$ and $9a$ both have the variable $a$. The other pairs have different variables, or no variable at all.', 'checked', '{"lint":[],"solve":{"answer":"$4a$ and $9a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Like terms share the same variable part: 4a and 9a.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
