VALUES ('5e4e9dd8-083f-47e9-bd3e-7938c23499fd', 'NC26.6.ANR.6', 2, 'choice', 'Evaluating algebraic expressions', 'What is the value of $2(n + 6)$ when $n = 4$?', '["$20$","$14$","$10$","$48$"]', '$20$', '2*(4+6)', 'Replace $n$ with 4 and work inside the parentheses first: $4 + 6 = 10$. Then $2 \times 10 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(4 + 6) = 2 x 10 = 20.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
