INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66058db5-2332-4934-b328-68eae540c5ef', 'NC26.6.ANR.6', 2, 'choice', 'Equivalent expressions and properties', 'Which expression is equivalent to $6x + 2x + 5$?', '["$8x^2 + 5$","$13x$","$8x + 5$","$12x + 5$"]', '$8x + 5$', NULL, 'Combine the like terms $6x$ and $2x$: $6x + 2x = 8x$. The constant 5 is not a like term, so it stays: $8x + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$8x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 2x = 8x; 8x + 5.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
