INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b37f671-e0ed-459e-905f-d49502948903', 'NC26.6.ANR.6', 2, 'numeric', 'Equivalent expressions and properties', 'Find the number $n$ that makes $4(x + 5)$ and $4x + n$ equivalent for every value of $x$.', '[]', '20', '4*5', 'By the distributive property, $4(x + 5) = 4x + 4 \times 5 = 4x + 20$. So $n = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 5) = 4x + 20; n = 20.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6116d02-4218-4303-9d78-9324d67c0e25', 'NC26.6.ANR.6', 2, 'choice', 'Equivalent expressions and properties', 'Which expression is NOT equivalent to $2(3 + x)$?', '["$6 + 2x$","$3 + 2x$","$2x + 6$","$x + x + 6$"]', '$3 + 2x$', NULL, '$2(3 + x) = 6 + 2x$. The expressions $6 + 2x$, $2x + 6$ and $x + x + 6$ all equal $6 + 2x$. But $3 + 2x$ is different: the 2 was not multiplied by the 3.', 'checked', '{"lint":[],"solve":{"answer":"$3 + 2x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3 + x) = 6 + 2x. 6 + 2x, x + x + 6, 2x + 6 are all equal to it; 3 + 2x is not.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4fba204-6a39-498d-ae67-6e283adaf63e', 'NC26.6.ANR.6', 2, 'choice', 'Equivalent expressions and properties', 'Which expression shows $12 + 20$ written with the greatest common factor factored out?', '["$2(6 + 10)$","$4(5 + 8)$","$4(3 + 5)$","$12(1 + 5)$"]', '$4(3 + 5)$', NULL, 'The greatest common factor of 12 and 20 is 4. Writing $12 = 4 \times 3$ and $20 = 4 \times 5$ gives $12 + 20 = 4(3 + 5)$. The expression $2(6 + 10)$ is also equal to 32, but 2 is not the greatest common factor.', 'checked', '{"lint":[],"solve":{"answer":"$4(3 + 5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF(12, 20) = 4; 12 + 20 = 4(3 + 5). 4(5 + 8) = 52, wrong; 2(6 + 10) uses 2, not the GCF; 12(1 + 5) = 72.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39e7a38e-4a24-49a1-95d9-1c8e8498af5d', 'NC26.6.ANR.6', 2, 'numeric', 'Equivalent expressions and properties', 'Aisha finds $6 \times 52$ by writing $6 \times 50 + 6 \times 2$. What is the product?', '[]', '312', '6*50+6*2', '$6 \times 50 = 300$ and $6 \times 2 = 12$. Then $300 + 12 = 312$.', 'checked', '{"lint":[],"solve":{"answer":"312","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 50 = 300, 6 x 2 = 12; 312.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bf48979-9d94-47c3-95e0-9946765f5b38', 'NC26.6.ANR.6', 3, 'numeric', 'Order of operations with exponents and parentheses', 'What is the value of $(9 - 3)^2 \div 4 + 2 \times 5$?', '[]', '19', '(9-3)^2/4+2*5', 'Parentheses first: $9 - 3 = 6$. Exponent: $6^2 = 36$. Then divide and multiply: $36 \div 4 = 9$ and $2 \times 5 = 10$. Finally add: $9 + 10 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9 - 3)^2 = 6^2 = 36. 36 / 4 = 9. 2 x 5 = 10. 9 + 10 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29509d45-72ad-48a8-8b23-045b7d1dd234', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating with two variables and an exponent', 'What is the value of $2a^2 - b$ when $a = 5$ and $b = 7$?', '[]', '43', '2*5^2-7', 'Substitute: $2 \times 5^2 - 7$. The exponent comes first: $5^2 = 25$. Then $2 \times 25 = 50$ and $50 - 7 = 43$.', 'checked', '{"lint":[],"solve":{"answer":"43","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5^2) - 7 = 2(25) - 7 = 50 - 7 = 43.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49bc9df5-2d5a-4450-8d16-31c3275731bd', 'NC26.6.ANR.6', 3, 'choice', 'Equivalent expressions (combining like terms)', 'Which expression is equivalent to $x + x + x + 4$?', '["$3x + 4$","$4x + 3$","$x^3 + 4$","$7x$"]', '$3x + 4$', NULL, 'Three $x$''s added together make $3x$, and the 4 stays separate, so the expression is $3x + 4$. Repeated addition is not an exponent ($x^3$ means $x \times x \times x$), and $3x$ and 4 are not like terms, so they cannot be combined.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x + x = 3x, so 3x + 4.","run_id":"claude-code","at":"2026-10-17T18:34:26.534Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddfff564-1553-4aab-bdac-38e188bab4ee', 'NC26.6.ANR.6', 3, 'numeric', 'Whole-number exponents', 'What whole number $n$ makes $2^n = 128$ true?', '[]', '7', '7', 'Keep doubling: $2^1 = 2$, $2^2 = 4$, $2^3 = 8$, $2^4 = 16$, $2^5 = 32$, $2^6 = 64$, $2^7 = 128$. So $n = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^7 = 128, so n = 7.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0802511-128e-4526-9c1b-238bab500563', 'NC26.6.ANR.6', 3, 'choice', 'Whole-number exponents', 'Which list shows $5^2$, $3^3$ and $2^5$ in order from least to greatest?', '["$2^5, 3^3, 5^2$","$3^3, 5^2, 2^5$","$5^2, 2^5, 3^3$","$5^2, 3^3, 2^5$"]', '$5^2, 3^3, 2^5$', NULL, '$5^2 = 25$, $3^3 = 27$ and $2^5 = 32$. From least to greatest the order is $5^2, 3^3, 2^5$.', 'checked', '{"lint":[],"solve":{"answer":"$5^2, 3^3, 2^5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^2 = 25, 3^3 = 27, 2^5 = 32; least to greatest 5^2, 3^3, 2^5.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c22606b-8fde-4234-94c6-7ebcb3b18e8d', 'NC26.6.ANR.6', 3, 'numeric', 'Whole-number exponents', 'Maya computes $2^3 \times 5^2 - 4^2$. What result does she get?', '[]', '184', '2^3*5^2-4^2', 'Evaluate each power first: $2^3 = 8$, $5^2 = 25$ and $4^2 = 16$. Then multiply, $8 \times 25 = 200$, and subtract, $200 - 16 = 184$.', 'checked', '{"lint":[],"solve":{"answer":"184","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8, 5^2 = 25, 4^2 = 16; 8 x 25 = 200; 200 - 16 = 184.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f3a4c21-daad-40dc-940e-8fa7e13e4a5f', 'NC26.6.ANR.6', 3, 'numeric', 'Whole-number exponents', 'A cube with edges 4 centimeters long has a volume of $4^3$ cubic centimeters. A smaller cube has edges 3 centimeters long. How many more cubic centimeters is the volume of the larger cube than the volume of the smaller cube?', '[]', '37', '4^3-3^3', 'The larger cube has volume $4^3 = 64$ and the smaller has volume $3^3 = 27$. The difference is $64 - 27 = 37$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^3 = 64, 3^3 = 27; 64 - 27 = 37.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6caae1ec-2c04-4fa6-8b5b-054919fb6b11', 'NC26.6.ANR.6', 3, 'choice', 'Whole-number exponents', 'Which of these is NOT equal to 64?', '["$8^2$","$4^3$","$6^4$","$2^6$"]', '$6^4$', NULL, '$8^2 = 64$, $4^3 = 64$ and $2^6 = 64$, but $6^4 = 6 \times 6 \times 6 \times 6 = 1{,}296$. So $6^4$ is the one that is not 64.', 'checked', '{"lint":[],"solve":{"answer":"$6^4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^6 = 64, 4^3 = 64, 8^2 = 64, 6^4 = 1296. Not 64: 6^4.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee3b2e17-0ae8-4a34-af7a-03ab6f611f0a', 'NC26.6.ANR.6', 3, 'numeric', 'Order of operations', 'Evaluate $3 \times (12 - 2^3) + 18 \div 6$.', '[]', '15', '3*(12-2^3)+18/6', 'Inside the parentheses, the exponent comes first: $2^3 = 8$, so $12 - 8 = 4$. Then $3 \times 4 = 12$ and $18 \div 6 = 3$. Finally $12 + 3 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8; 12 - 8 = 4; 3 x 4 = 12; 18 / 6 = 3; 12 + 3 = 15.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0834c95-3db4-476b-985d-43c8dc600569', 'NC26.6.ANR.6', 3, 'numeric', 'Order of operations', 'Evaluate $60 - (3 + 2)^2 \times 2$.', '[]', '10', '60-(3+2)^2*2', 'Parentheses first: $3 + 2 = 5$. Then the exponent: $5^2 = 25$. Then multiply: $25 \times 2 = 50$. Finally $60 - 50 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 + 2)^2 = 25; 25 x 2 = 50; 60 - 50 = 10.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6ee904e-26f4-4e51-9d1a-e26c4c816936', 'NC26.6.ANR.6', 3, 'choice', 'Order of operations', 'Parentheses can be placed in $6 + 4 \times 3 - 1$ to change its value. Which placement makes the value 29?', '["$(6 + 4) \\times 3 - 1$","$6 + 4 \\times (3 - 1)$","$6 + (4 \\times 3) - 1$","$(6 + 4) \\times (3 - 1)$"]', '$(6 + 4) \times 3 - 1$', NULL, '$(6 + 4) \times 3 - 1 = 10 \times 3 - 1 = 29$. The other placements give 14, 17 and 20.', 'checked', '{"lint":[],"solve":{"answer":"$(6 + 4) \\times 3 - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 6 + 12 - 1 = 17. B: 10 x 2 = 20. C: 10 x 3 - 1 = 29. D: 6 + 4 x 2 = 14. Only C gives 29.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
