INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b09f9935-c97a-46a1-8d20-ca4283b16bf3', 'NC26.6.ANR.6', 3, 'numeric', 'Order of operations', 'Pencil packs cost 3 dollars each and eraser packs cost 2 dollars each. Mona buys 5 pencil packs and 3 eraser packs and pays with a 50 dollar bill. How many dollars of change does she get?', '[]', '29', '50-(5*3+3*2)', 'The packs cost $5 \times 3 + 3 \times 2 = 15 + 6 = 21$ dollars. Her change is $50 - 21 = 29$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost 5 x 3 + 3 x 2 = 15 + 6 = 21; change 50 - 21 = 29.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10f31594-8560-4643-9851-fbdef31917af', 'NC26.6.ANR.6', 3, 'choice', 'Order of operations', 'Which expression has the same value as $2 + 3 \times 4^2$?', '["$5 \\times 16$","$2 + 3 \\times 16$","$2 + 12^2$","$(2 + 12)^2$"]', '$2 + 3 \times 16$', NULL, '$4^2 = 16$, so $2 + 3 \times 4^2 = 2 + 3 \times 16 = 2 + 48 = 50$. The other expressions equal 80, 146 and 196.', 'checked', '{"lint":[],"solve":{"answer":"$2 + 3 \\times 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 3 x 16 = 50. Options: 2 + 3 x 16 = 50; 5 x 16 = 80; 2 + 144 = 146; 14^2 = 196. Only the first matches.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac57ac61-15a6-42ee-8919-9893cfe2d2e4', 'NC26.6.ANR.6', 3, 'choice', 'Translating words to expressions', 'A gym charges a 25 dollar sign-up fee plus 18 dollars for each month. Maya has a coupon that takes 10 dollars off her total. Which expression gives what she pays, in dollars, for $m$ months?', '["$25 + 18m - 10$","$25 + 18 - 10m$","$(25 + 18)m - 10$","$25 + 18m + 10$"]', '$25 + 18m - 10$', NULL, 'She pays 25 once, 18 for each of the $m$ months ($18m$), and then 10 is taken off: $25 + 18m - 10$.', 'checked', '{"lint":[],"solve":{"answer":"$25 + 18m - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fee 25 + 18 per month (18m), minus coupon 10: 25 + 18m - 10.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a9a3242-74cf-468f-9b04-0d3e061f05d7', 'NC26.6.ANR.6', 3, 'choice', 'Translating words to expressions', 'Which expression means "3 less than the product of 4 and the sum of $a$ and $b$"?', '["$3 - 4(a + b)$","$4a + b - 3$","$4(a + b - 3)$","$4(a + b) - 3$"]', '$4(a + b) - 3$', NULL, 'The sum of $a$ and $b$ is $a + b$. The product of 4 and that sum is $4(a + b)$. "3 less than" that product is $4(a + b) - 3$.', 'checked', '{"lint":[],"solve":{"answer":"$4(a + b) - 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Product of 4 and (a + b) is 4(a + b); 3 less than that: 4(a + b) - 3.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d95cf57-2edd-4bef-b577-c87b295724d7', 'NC26.6.ANR.6', 3, 'numeric', 'Translating words to expressions', 'Write "half of the sum of a number and 6" as an expression. What is its value when the number is 14?', '[]', '10', '(14+6)/2', 'Let the number be $n$. The sum of the number and 6 is $n + 6$, and half of it is $\frac{n + 6}{2}$. When $n = 14$ this is $\frac{20}{2} = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 6)/2 with x = 14: 20/2 = 10.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c85e0ec-6afa-4470-aaed-e19b60278f03', 'NC26.6.ANR.6', 3, 'numeric', 'Translating words to expressions', 'A shop counts the wheels on $b$ bicycles (2 wheels each) and $t$ tricycles (3 wheels each). Write an expression for the total number of wheels, and use it to find the total when $b = 6$ and $t = 4$. How many wheels are there in all?', '[]', '24', '2*6+3*4', 'The bicycles have $2b$ wheels and the tricycles have $3t$ wheels, so the total is $2b + 3t$. With $b = 6$ and $t = 4$ it is $2 \times 6 + 3 \times 4 = 12 + 12 = 24$ wheels.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2b + 3t = 2(6) + 3(4) = 12 + 12 = 24.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('672b8033-a88b-49bb-b6fa-fe48bcfb7197', 'NC26.6.ANR.6', 3, 'choice', 'Translating words to expressions', 'A store sells notebooks for 4 dollars each and pens for 2 dollars each. Lena buys $n$ notebooks and $p$ pens and pays with a 50 dollar bill. Which expression gives her change, in dollars?', '["$4n + 2p - 50$","$50 - 4n - 2p$","$50 - 4n + 2p$","$50 - 6(n + p)$"]', '$50 - 4n - 2p$', NULL, 'The notebooks cost $4n$ and the pens cost $2p$, so she spends $4n + 2p$. Her change is $50 - (4n + 2p) = 50 - 4n - 2p$.', 'checked', '{"lint":[],"solve":{"answer":"$50 - 4n - 2p$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Spent 4n + 2p; change 50 - (4n + 2p) = 50 - 4n - 2p.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1badf814-cf0b-4620-adb2-39e65b52bb70', 'NC26.6.ANR.6', 3, 'numeric', 'Parts of an expression', 'What is the sum of the coefficients of the variables in $4 + 2n + 7m$?', '[]', '9', '2+7', 'The coefficient of $n$ is 2 and the coefficient of $m$ is 7. The 4 is a constant term, not a coefficient. So the sum is $2 + 7 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Coefficients of n and m: 2 and 7; sum 9.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74942cdc-55f9-4ee5-9fa0-6da760a1c5b4', 'NC26.6.ANR.6', 3, 'choice', 'Parts of an expression', 'Which expression has exactly three terms?', '["$2a + 3b - 4c$","$5ab + 9$","$7abc$","$a + b + c + d$"]', '$2a + 3b - 4c$', NULL, '$2a + 3b - 4c$ has the terms $2a$, $3b$ and $4c$: three terms. $5ab + 9$ has 2 terms, $7abc$ has 1 term and $a + b + c + d$ has 4 terms.', 'checked', '{"lint":[],"solve":{"answer":"$2a + 3b - 4c$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a + 3b - 4c: 3 terms. 7abc: 1. a + b + c + d: 4. 5ab + 9: 2.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdfa21e0-b363-4a7b-9d0b-b7acedb02703', 'NC26.6.ANR.6', 3, 'choice', 'Parts of an expression', 'Which expression is a quotient of the sum $x + 4$ and 3?', '["$x + \\frac{4}{3}$","$\\frac{x + 4}{3}$","$3(x + 4)$","$\\frac{3}{x + 4}$"]', '$\frac{x + 4}{3}$', NULL, 'A quotient of $x + 4$ and 3 means $x + 4$ is divided by 3, which is $\frac{x + 4}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{x + 4}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quotient of (x + 4) and 3: (x + 4)/3.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ff4d59e-d17a-4930-8afd-d91faa11dac7', 'NC26.6.ANR.6', 3, 'choice', 'Parts of an expression', 'Which expression is a sum of two products?', '["$5(a + 2b)$","$5a \\times 2b$","$\\frac{5a}{2b}$","$5a + 2b$"]', '$5a + 2b$', NULL, '$5a + 2b$ adds the product $5 \times a$ and the product $2 \times b$. The expression $5(a + 2b)$ is a product, $5a \times 2b$ is a product and $\frac{5a}{2b}$ is a quotient.', 'checked', '{"lint":[],"solve":{"answer":"$5a + 2b$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5a + 2b is the sum of the products 5 x a and 2 x b. Others are a product, a product of a number and a sum, and a quotient.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87ea0363-97e1-41a3-b884-b796d85b822d', 'NC26.6.ANR.6', 3, 'numeric', 'Parts of an expression', 'What is the product of the coefficient of $b$ and the constant term in $a + 6b + 10$?', '[]', '60', '6*10', 'The coefficient of $b$ is 6 and the constant term is 10. Their product is $6 \times 10 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Coefficient of b is 6, constant 10; 6 x 10 = 60.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
