INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a35808d-5954-43a3-a62b-1c446c2f3f2d', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating algebraic expressions', 'Find the value of $4x^2 - 3y$ when $x = 3$ and $y = 5$.', '[]', '21', '4*3^2-3*5', '$4x^2 = 4 \times 3^2 = 4 \times 9 = 36$ and $3y = 3 \times 5 = 15$. Then $36 - 15 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(3^2) - 3(5) = 4 x 9 - 15 = 36 - 15 = 21.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19b64458-0ced-4c85-8b83-e03929ce1a8a', 'NC26.6.ANR.6', 3, 'numeric', 'Evaluating algebraic expressions', 'Evaluate $\frac{3}{4}m + 5$ when $m = 12$.', '[]', '14', '3/4*12+5', '$\frac{3}{4} \times 12 = 9$. Then $9 + 5 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)(12) = 9; 9 + 5 = 14.","run_id":"claude-code","at":"2026-10-17T20:19:24.413Z"}}', 'ai', NULL, NULL)
