VALUES ('d5c6fabf-be81-4e6b-9e29-28e6f9457927', 'NC26.6.ANR.7', 1, 'choice', 'Checking a solution by substitution', 'Which number is a solution of $3m = 18$?', '["$15$","$21$","$6$","$54$"]', '$6$', '18/3', 'Try each number in place of $m$. Only $m = 6$ works, because $3 \times 6 = 18$. The others give $3 \times 15 = 45$, $3 \times 21 = 63$ and $3 \times 54 = 162$.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3m = 18 gives m = 6; check 3 x 6 = 18.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
