INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1547d543-e5d5-466a-94b0-ddae46b481ef', 'NC26.6.ANR.7', 1, 'numeric', 'Solutions and graphs of inequalities', 'How many of the numbers 2, 5, 8 and 11 are solutions of $x > 6$?', '[]', '2', '2', 'Only numbers greater than 6 are solutions. The numbers 8 and 11 are greater than 6, but 2 and 5 are not. So 2 of the numbers are solutions.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 and 11 are greater than 6; 2 and 5 are not. Two.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
