INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52abf183-2226-43a4-95af-39bfacb60cb8', 'NC26.6.ANR.7', 1, 'choice', 'Solutions and graphs of inequalities', 'How is the inequality $x > 9$ graphed on a number line?', '["A closed circle at 9 with an arrow pointing to the right","An open circle at 9 with an arrow pointing to the left","A closed circle at 9 with an arrow pointing to the left","An open circle at 9 with an arrow pointing to the right"]', 'An open circle at 9 with an arrow pointing to the right', NULL, 'The symbol $>$ does not include 9, so the circle is open. The solutions are greater than 9, so the arrow points to the right.', 'checked', '{"lint":[],"solve":{"answer":"An open circle at 9 with an arrow pointing to the right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strict: open circle at 9; greater: arrow right.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
