VALUES ('dc6e7d3c-2bbd-4e06-a62b-3d64f791686f', 'NC26.6.ANR.7', 2, 'choice', 'Solving addition and subtraction equations', 'Which equation has the solution $x = 14$?', '["$x + 6 = 8$","$x - 6 = 8$","$x - 8 = 14$","$x + 8 = 14$"]', '$x - 6 = 8$', NULL, 'Put 14 in place of $x$: $14 - 6 = 8$ is true. The others give $14 + 6 = 20$, $14 - 8 = 6$ and $14 + 8 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"$x - 6 = 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solutions: 6, 2, 22, 14. x - 6 = 8 gives 14.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
