INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dc64ed0-afce-4931-adc4-12e1f8119d19', 'NC26.6.ANR.7', 2, 'numeric', 'Writing and solving an equation from a story', 'A tank held some water. After 18 liters were used, 42 liters were left. How many liters did the tank hold at first?', '[]', '60', '42+18', 'Let $w$ be the starting amount. Then $w - 18 = 42$, so $w = 42 + 18 = 60$ liters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"w - 18 = 42, w = 60.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
