INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cb8bba3-5d13-4f8e-ad5c-83c3ee90f1c1', 'NC26.6.ANR.7', 2, 'choice', 'Writing an inequality from a situation', 'You must be at least 13 years old to join a club. Let $a$ be a person''s age in years. Which inequality shows the ages that may join?', '["$a > 13$","$a \\le 13$","$a \\ge 13$","$a < 13$"]', '$a \ge 13$', NULL, '"At least 13" means 13 or more, so 13 is allowed. That is $a \ge 13$.', 'checked', '{"lint":[],"solve":{"answer":"$a \\ge 13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least 13: a >= 13.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e61308de-0900-477c-bba1-45c4c07180d4', 'NC26.6.ANR.7', 2, 'choice', 'Writing an inequality from a situation', 'An elevator holds no more than 8 people. Let $p$ be the number of people on the elevator. Which inequality shows this?', '["$p \\le 8$","$p < 8$","$p \\ge 8$","$p > 8$"]', '$p \le 8$', NULL, '"No more than 8" means 8 or fewer. Eight people are allowed, so the symbol is $\le$: $p \le 8$.', 'checked', '{"lint":[],"solve":{"answer":"$p \\le 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No more than 8: p <= 8.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('320cd3dd-3ef0-4f57-bd54-a51e6b68388c', 'NC26.6.ANR.7', 2, 'choice', 'Writing an inequality from a situation', 'Which situation is described by the inequality $x < 20$?', '["A bag holds at least 20 marbles","A bag holds at most 20 marbles","A bag holds fewer than 20 marbles","A bag holds exactly 20 marbles"]', 'A bag holds fewer than 20 marbles', NULL, 'The symbol $<$ means "less than", so $x < 20$ describes a number of marbles that is fewer than 20. "At least" is $\ge$, "at most" is $\le$ and "exactly" is $=$.', 'checked', '{"lint":[],"solve":{"answer":"A bag holds fewer than 20 marbles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x < 20 is strictly fewer than 20.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7ad2a49-a2c3-4f5b-9756-ba1c4ea656e2', 'NC26.6.ANR.7', 2, 'numeric', 'Writing an inequality from a situation', 'To pass a quiz, a student must score at least 70 points. What is the smallest whole-number score that passes?', '[]', '70', '70', '"At least 70" means 70 or more, written $s \ge 70$. The smallest whole-number score that passes is 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s >= 70; smallest whole number is 70.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bd4f1a2-220c-44af-b325-cefccd03a283', 'NC26.6.ANR.7', 2, 'choice', 'Solutions and graphs of inequalities', 'A number line graph shows a closed circle at 12 and a shaded arrow pointing to the right, toward larger numbers. Which inequality does it show?', '["$x > 12$","$x \\ge 12$","$x \\le 12$","$x < 12$"]', '$x \ge 12$', NULL, 'The closed circle means 12 is included, and the arrow to the right means larger numbers are included. So the graph shows $x \ge 12$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Closed circle includes 12, shading right: x >= 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
