INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2994134b-5579-4f61-ba8e-2349af7a1a2b', 'NC26.6.ANR.7', 3, 'choice', 'Solving multiplication and division equations', 'Equation 1 is $4x = 60$ and Equation 2 is $\frac{y}{4} = 60$. Which statement about their solutions is true?', '["$x$ is 16 times as large as $y$","$x$ and $y$ are equal","$y$ is 16 times as large as $x$","$y$ is 4 times as large as $x$"]', '$y$ is 16 times as large as $x$', NULL, 'In Equation 1, $x = 60 \div 4 = 15$. In Equation 2, $y = 60 \times 4 = 240$. Since $240 = 16 \times 15$, $y$ is 16 times as large as $x$.', 'checked', '{"lint":[],"solve":{"answer":"$y$ is 16 times as large as $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 60 / 4 = 15; y = 60 x 4 = 240; 240 / 15 = 16, so y is 16 times x.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cde91486-51d1-4423-9232-0126d425f4f4', 'NC26.6.ANR.7', 3, 'numeric', 'Solving equations with decimals and fractions', 'Solve $m - 1\frac{3}{4} = 2\frac{1}{2}$.', '[]', '4 1/4', '(2+1/2)+(1+3/4)', 'Add $1\frac{3}{4}$ to both sides: $m = 2\frac{1}{2} + 1\frac{3}{4} = 2\frac{2}{4} + 1\frac{3}{4} = 3\frac{5}{4} = 4\frac{1}{4}$. Check: $4\frac{1}{4} - 1\frac{3}{4} = 2\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"4 1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"m = 2 1/2 + 1 3/4 = 2 2/4 + 1 3/4 = 3 5/4 = 4 1/4.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
