INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b13ff554-33a4-4596-b735-be6dd0d290e8', 'NC26.6.ANR.7', 3, 'numeric', 'Solving equations with decimals and fractions', 'Solve $\frac{3}{4}n = 9$.', '[]', '12', '9/(3/4)', 'Divide both sides by $\frac{3}{4}$: $n = 9 \div \frac{3}{4} = 9 \times \frac{4}{3} = 12$. Check: $\frac{3}{4} \times 12 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 9 x 4/3 = 12; check (3/4)(12) = 9.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
