INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18fa4c8a-09d4-4289-8116-feb9d001325b', 'NC26.6.ANR.7', 3, 'choice', 'Solving equations with decimals and fractions', 'What is the solution of $0.25n = 3$?', '["$0.75$","$75$","$3.25$","$12$"]', '$12$', '3/0.25', 'Divide both sides by 0.25: $n = 3 \div 0.25 = 12$. Check: $0.25 \times 12 = 3$ (a quarter of 12 is 3).', 'checked', '{"lint":[],"solve":{"answer":"$12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 3 / 0.25 = 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
