INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('648aae3d-f846-4530-8482-72650627d0c0', 'NC26.6.ANR.7', 3, 'numeric', 'Writing and solving an equation from a story', 'A rope is 7.5 meters long. A piece is cut off, and 2.75 meters of rope are left. How long was the piece that was cut off, in meters?', '[]', '4.75', '7.5-2.75', 'Let $x$ be the length of the piece. Then $x + 2.75 = 7.5$, so $x = 7.5 - 2.75 = 4.75$ meters.', 'checked', '{"lint":[],"solve":{"answer":"4.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2.75 = 7.5, x = 4.75.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4cc08401-62b4-4afe-a26a-ff5f76ffa683', 'NC26.6.ANR.7', 3, 'choice', 'Writing and solving an equation from a story', 'Four friends split a bill equally and each pays 13.50 dollars. Which equation and solution give the total bill $b$, in dollars?', '["$\\frac{b}{4} = 13.50$, so $b = 54$","$4b = 13.50$, so $b = 3.375$","$b + 4 = 13.50$, so $b = 9.50$","$b - 4 = 13.50$, so $b = 17.50$"]', '$\frac{b}{4} = 13.50$, so $b = 54$', NULL, 'The bill $b$ is divided among 4 friends, so each pays $\frac{b}{4} = 13.50$. Multiply both sides by 4: $b = 13.50 \times 4 = 54$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{b}{4} = 13.50$, so $b = 54$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each share is b/4 = 13.50, so b = 54.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e34b3a3a-df3a-4347-a922-a3fd9e35e37f', 'NC26.6.ANR.7', 3, 'numeric', 'Writing and solving an equation from a story', 'A recipe uses $\frac{2}{3}$ cup of flour for each batch of biscuits. Nina used 4 cups of flour in all. How many batches did she make?', '[]', '6', '4/(2/3)', 'Let $b$ be the number of batches. Then $\frac{2}{3}b = 4$, so $b = 4 \div \frac{2}{3} = 4 \times \frac{3}{2} = 6$. Check: 6 batches use $6 \times \frac{2}{3} = 4$ cups.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)b = 4, b = 4 x 3/2 = 6.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc227133-3425-48e0-9e4b-a554e1a27978', 'NC26.6.ANR.7', 3, 'choice', 'Writing an inequality from a situation', 'Maya has 48 dollars to spend on books that cost 8 dollars each. Let $b$ be the number of books she buys. Which inequality shows how many books she can afford?', '["$8b \\ge 48$","$8 + b \\le 48$","$\\frac{b}{8} \\le 48$","$8b \\le 48$"]', '$8b \le 48$', NULL, 'Buying $b$ books costs $8b$ dollars, and the cost can be at most 48 dollars (spending exactly 48 is fine). So $8b \le 48$.', 'checked', '{"lint":[],"solve":{"answer":"$8b \\le 48$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost 8b must not exceed 48: 8b <= 48.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31f0ae26-642d-4726-b0e4-a326fc49d2f5', 'NC26.6.ANR.7', 3, 'choice', 'Writing an inequality from a situation', 'A trampoline allows a maximum weight of 250 pounds. Let $w$ be a person''s weight in pounds. Which inequality shows the weights that are allowed?', '["$w \\ge 250$","$w \\le 250$","$w > 250$","$w = 250$"]', '$w \le 250$', NULL, 'A maximum of 250 pounds means 250 pounds or less is allowed, so $w \le 250$.', 'checked', '{"lint":[],"solve":{"answer":"$w \\le 250$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Maximum 250 allowed: w <= 250.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5092b30-330d-4f00-8676-18242c17f96b', 'NC26.6.ANR.7', 3, 'numeric', 'Writing an inequality from a situation', 'A game is only for players younger than 12 years old. What is the greatest whole number of years old that a player can be?', '[]', '11', '11', '"Younger than 12" means $a < 12$, and 12 itself is not allowed. The greatest whole-number age that is less than 12 is 11.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a < 12; greatest whole number is 11.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
