INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c853b0a-ab46-4a6f-91da-554a6c3add84', 'NC26.6.ANR.7', 3, 'choice', 'Writing an inequality from a situation', 'Which inequality says that 5 more than a number $x$ is greater than 20?', '["$5x > 20$","$x + 5 < 20$","$x - 5 > 20$","$x + 5 > 20$"]', '$x + 5 > 20$', NULL, '"5 more than $x$" is $x + 5$, and "is greater than 20" is $> 20$. Together: $x + 5 > 20$.', 'checked', '{"lint":[],"solve":{"answer":"$x + 5 > 20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 more than x is x + 5; greater than 20: x + 5 > 20.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d40110b-b08c-4315-8d38-fee28f48c325', 'NC26.6.ANR.7', 3, 'choice', 'Writing an inequality from a situation', 'Which inequality means the same as "$x$ is no less than 9"?', '["$x \\ge 9$","$x \\le 9$","$x > 9$","$x < 9$"]', '$x \ge 9$', NULL, '"No less than 9" means it cannot be less than 9, so $x$ is 9 or more: $x \ge 9$. The number 9 itself is allowed, so $x > 9$ is not correct.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No less than 9 means 9 or more: x >= 9.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ded2839b-4d6a-4727-a08e-dc648ad44d7b', 'NC26.6.ANR.7', 3, 'choice', 'Solutions and graphs of inequalities', 'Which statement is true about the inequality $x \ge 5$?', '["5 is not a solution, but every number greater than 5 is","5 is a solution, and so is every number less than 5","5 is the only solution","5 is a solution, and so is every number greater than 5"]', '5 is a solution, and so is every number greater than 5', NULL, 'The symbol $\ge$ means "greater than or equal to", so 5 and every number greater than 5 are solutions.', 'checked', '{"lint":[],"solve":{"answer":"5 is a solution, and so is every number greater than 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x >= 5 includes 5 and every number greater.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63b31791-71ff-469c-bb97-44975308920b', 'NC26.6.ANR.7', 3, 'numeric', 'Solutions and graphs of inequalities', 'What is the greatest whole number that is a solution of $x < 12.5$?', '[]', '12', '12', 'Solutions must be less than 12.5. The whole number 12 is less than 12.5, but 13 is not. So the greatest whole-number solution is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x < 12.5; greatest whole number is 12.","run_id":"claude-code","at":"2026-10-17T20:19:24.452Z"}}', 'ai', NULL, NULL)
