INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a900b53-ea77-4048-a399-f9df2ba9ece5', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a parallelogram from its base and height', 'A parallelogram-shaped sticker has a base of 8 centimeters and a height of 5 centimeters. What is the area of the sticker in square centimeters?', '[]', '40', '8*5', 'The area of a parallelogram is base times height: $8 \times 5 = 40$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = b x h = 8 x 5 = 40.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
