INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e067b84e-70dd-4810-947e-c0ebfb406a97', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a trapezoid', 'Two identical trapezoids are put together to make a parallelogram with a base of 10 centimeters and a height of 4 centimeters. What is the area of one trapezoid in square centimeters?', '["20","40","14","80"]', '20', '10*4/2', 'The parallelogram has area $10 \times 4 = 40$ square centimeters. It is made of two identical trapezoids, so one trapezoid has half of that, 20 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallelogram area 10 x 4 = 40; two identical trapezoids, each 40 / 2 = 20.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ad2b750-f0c5-42d1-a45f-a98ff99a7485', 'NC26.6.SGMR.1', 1, 'numeric', 'Area of a trapezoid', 'A trapezoid has parallel sides of 4 centimeters and 8 centimeters. The distance between the parallel sides is 5 centimeters. What is the area of the trapezoid in square centimeters?', '[]', '30', '1/2*(4+8)*5', 'Add the parallel sides: $4 + 8 = 12$. Area $= \frac{1}{2} \times 12 \times 5 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x (4 + 8) x 5 = 6 x 5 = 30.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97477861-e905-45f4-b127-0c20c1284d13', 'NC26.6.SGMR.1', 1, 'choice', 'Area of a trapezoid', 'Which expression gives the area of a trapezoid with parallel sides $a$ and $b$ and height $h$?', '["$a \\times b \\times h$","$\\frac{1}{2} \\times (a + b) \\times h$","$\\frac{1}{2} \\times a \\times b$","$(a + b) \\times h$"]', '$\frac{1}{2} \times (a + b) \times h$', NULL, 'Two copies of a trapezoid make a parallelogram with base $a + b$ and height $h$. One trapezoid is half of that, $\frac{1}{2} \times (a + b) \times h$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2} \\times (a + b) \\times h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two copies make a parallelogram with base a + b and height h; half of that: 1/2 x (a + b) x h.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
