INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('188b9cc4-cd35-4506-a63b-02549d190fe7', 'NC26.6.SGMR.1', 1, 'choice', 'Solving area problems in context', 'Which unit is best for measuring the area of a classroom floor?', '["Meters","Square meters","Cubic meters","Square millimeters"]', 'Square meters', NULL, 'Area is measured in square units. A classroom floor is large, so square meters fit. Meters measure length, cubic meters measure volume, and square millimeters are far too small.', 'checked', '{"lint":[],"solve":{"answer":"Square meters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area needs square units; a floor is meters-sized, so square meters.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6953475-3681-4942-8693-ca7fc302f459', 'NC26.6.SGMR.1', 1, 'numeric', 'Solving area problems in context', 'A wall has a patch shaped like a parallelogram that needs paint. The patch has a base of 5 feet and a height of 4 feet. One small can of paint covers 10 square feet. How many cans are needed?', '[]', '2', '5*4/10', 'The patch has area $5 \times 4 = 20$ square feet. One can covers 10 square feet, so $20 \div 10 = 2$ cans are needed.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 5 x 4 = 20; 20 / 10 = 2 cans.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
