INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29e9a5bc-46df-4143-9b33-9fb19edb0cd0', 'NC26.6.SGMR.1', 1, 'choice', 'How area changes when a measurement changes', 'A rectangle has a length of 6 centimeters and a width of 4 centimeters. The length is doubled and the width stays the same. What happens to the area?', '["It stays the same.","It doubles.","It becomes 4 times as large.","It increases by 6 square centimeters."]', 'It doubles.', NULL, 'The area goes from $6 \times 4 = 24$ to $12 \times 4 = 48$ square centimeters. Doubling one measurement doubles the area.', 'checked', '{"lint":[],"solve":{"answer":"It doubles.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old 6 x 4 = 24; new 12 x 4 = 48, which is double.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f1f25ed-36f1-40aa-8cec-91d37f8d6669', 'NC26.6.SGMR.1', 1, 'numeric', 'How area changes when a measurement changes', 'A parallelogram has a base of 6 inches and a height of 5 inches. The base is changed to 12 inches and the height stays 5 inches. What is the area of the new parallelogram in square inches?', '[]', '60', '12*5', 'The new area is base times height: $12 \times 5 = 60$ square inches. (The old area was 30, so the area doubled.)', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 5 = 60.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
