INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70acb23e-d684-4439-8841-0a967c0ee897', 'NC26.6.SGMR.1', 2, 'choice', 'Finding a missing base or height from the area', 'A triangle has an area of 60 square centimeters and a height of 8 centimeters. What is the length of its base in centimeters?', '["7.5","68","15","3.75"]', '15', '2*60/8', 'Base $\times$ height $= 2 \times 60 = 120$, so the base is $120 \div 8 = 15$ centimeters. A result of 7.5 forgets to double the area first.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = 1/2 x b x 8 = 4b, so b = 15.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
