INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63e5224d-f1b2-402a-ab2d-52788b16326d', 'NC26.6.SGMR.1', 2, 'numeric', 'Finding a missing base or height from the area', 'A triangular sail has an area of 33 square feet and a height of 6 feet. How long is its base in feet?', '[]', '11', '2*33/6', 'Twice the area is $2 \times 33 = 66$, which equals base times height. So the base is $66 \div 6 = 11$ feet.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"33 = 1/2 x b x 6 = 3b, so b = 11.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
