INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff2722a0-567d-4590-b899-c5c7e2699cfa', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a composite figure made of rectangles', 'An L-shaped room is made by taking a rectangle 12 meters long and 9 meters wide and cutting a rectangle 5 meters by 4 meters out of one corner. What is the area of the room in square meters?', '[]', '88', '12*9-5*4', 'The full rectangle has area $12 \times 9 = 108$. The corner that is cut out has area $5 \times 4 = 20$. The room has area $108 - 20 = 88$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 9 - 5 x 4 = 108 - 20 = 88.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
