INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('989f475b-d9fe-4457-a370-b32fa65043cb', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a composite figure made of rectangles', 'A shape is made of three rectangles that do not overlap. Their sizes are 6 by 3, 4 by 4 and 5 by 2 (all in centimeters). What is the total area of the shape in square centimeters?', '["34","44","28","24"]', '44', '6*3+4*4+5*2', 'The areas are $6 \times 3 = 18$, $4 \times 4 = 16$ and $5 \times 2 = 10$. The total is $18 + 16 + 10 = 44$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x3 + 4x4 + 5x2 = 18 + 16 + 10 = 44.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
