INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36651ae6-d538-4aa4-9029-78f39759615a', 'NC26.6.SGMR.1', 2, 'numeric', 'Area of a composite figure that includes triangles', 'A hexagon is made of a rectangle that is 10 centimeters long and 6 centimeters wide, with a triangle attached to each of its 6-centimeter ends. Each triangle has a base of 6 centimeters and a height of 3 centimeters. What is the area of the hexagon in square centimeters?', '[]', '78', '10*6+2*(1/2*6*3)', 'The rectangle has area $10 \times 6 = 60$. Each triangle has area $\frac{1}{2} \times 6 \times 3 = 9$, so the two triangles add 18. The total is $60 + 18 = 78$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"78","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 x 6 = 60; each triangle 1/2 x 6 x 3 = 9, two of them 18; total 78.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('359f53f3-a3cd-4ca9-b0b2-327a1ffadcbb', 'NC26.6.SGMR.1', 2, 'choice', 'Area of a composite figure that includes triangles', 'A rectangular sign is 10 inches wide and 8 inches tall. A triangle with a base of 4 inches and a height of 3 inches is cut out of its top edge. What is the area of the sign that is left, in square inches?', '["86","74","68","73"]', '74', '10*8-1/2*4*3', 'The sign has area $10 \times 8 = 80$. The triangle cut out has area $\frac{1}{2} \times 4 \times 3 = 6$. What is left is $80 - 6 = 74$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sign 10 x 8 = 80; cut-out triangle 1/2 x 4 x 3 = 6; 80 - 6 = 74.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
