INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59c18bb0-9556-499f-8980-2dfa5ebb43b9', 'NC26.6.SGMR.1', 2, 'numeric', 'Composing and decomposing shapes', 'A rectangle is 12 centimeters long and 5 centimeters wide. It is cut along a diagonal into two triangles. One of those triangles is then cut into two smaller triangles of equal area. What is the area of one of the smaller triangles in square centimeters?', '[]', '15', '12*5/2/2', 'The rectangle has area $12 \times 5 = 60$. Each big triangle has area $60 \div 2 = 30$. Cutting one into two equal parts gives $30 \div 2 = 15$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 60; each diagonal triangle 30; half of that 15.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
