INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('616edd2a-eb8f-4e13-8764-5a235dcce4bb', 'NC26.6.SGMR.1', 2, 'numeric', 'How area changes when a measurement changes', 'A triangle has a base of 12 centimeters and a height of 5 centimeters. The base is made 4 centimeters longer and the height stays the same. By how many square centimeters does the area increase?', '[]', '10', '1/2*(12+4)*5-1/2*12*5', 'The old area is $\frac{1}{2} \times 12 \times 5 = 30$. The new base is 16, so the new area is $\frac{1}{2} \times 16 \times 5 = 40$. The area increases by $40 - 30 = 10$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old 1/2 x 12 x 5 = 30; new 1/2 x 16 x 5 = 40; increase 10.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
