INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2784738e-95b2-4133-a0dd-e963a64af755', 'NC26.6.SGMR.1', 2, 'choice', 'Choosing the right measurements and checking an answer', 'A triangle has sides of 13 cm, 14 cm and 15 cm. The height drawn to the 14 cm side is 12 cm. What is the area of the triangle in square centimeters?', '["84","168","91","105"]', '84', '1/2*14*12', 'Use the 14 cm side as the base, since the 12 cm height goes to that side: $\frac{1}{2} \times 14 \times 12 = 84$ square centimeters. The other sides are slanted and are not heights.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 14, height 12: 1/2 x 14 x 12 = 84. The 13 and 15 sides are distractors.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
