INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ccc1b218-9e8c-4309-9d44-6f303fe8c1a8', 'NC26.6.SGMR.1', 2, 'choice', 'Choosing the right measurements and checking an answer', 'A right triangle has sides of 5 cm, 12 cm and 13 cm. The 13 cm side is the longest. What is the area of the triangle in square centimeters?', '["60","30","32.5","78"]', '30', '1/2*5*12', 'The two sides at the right angle are 5 and 12, so they are the base and the height: $\frac{1}{2} \times 5 \times 12 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 5 and 12 are perpendicular: 1/2 x 5 x 12 = 30.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
