INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('767e64a3-01f4-4356-b7b6-fa8970e5ca5e', 'NC26.6.SGMR.1', 2, 'numeric', 'Choosing the right measurements and checking an answer', 'A parallelogram has sides of 20 centimeters and 13 centimeters. The distance between the two 20-centimeter sides is 12 centimeters. What is the area of the parallelogram in square centimeters?', '[]', '240', '20*12', 'Use a 20 cm side as the base. The height is the distance between the two 20 cm sides, 12 cm. Area $= 20 \times 12 = 240$ square centimeters. The 13 cm side is slanted and is not used.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 20, height 12 (the 13 cm side is slanted): 20 x 12 = 240. Consistent since 12 <= 13.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
