INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41f8058c-e152-49e9-977e-6dedc3be1605', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a trapezoid', 'A trapezoid has an area of 54 square centimeters. Its parallel sides are 5 centimeters and 13 centimeters long. What is its height in centimeters?', '[]', '6', '54*2/(5+13)', 'Area $= \frac{1}{2} \times (5 + 13) \times h = 9h$. So $9h = 54$ and $h = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"54 = 1/2 x (5 + 13) x h = 9h, so h = 6.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
