INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80cd97bd-c57a-4d02-820c-6afd8a07db1c', 'NC26.6.SGMR.1', 3, 'numeric', 'Area of a trapezoid', 'A trapezoid has a top side of 6 centimeters. Its bottom side, which is parallel to the top, is twice as long as the top side. The height is 5 centimeters. What is the area of the trapezoid in square centimeters?', '[]', '45', '1/2*(6+2*6)*5', 'The bottom side is $2 \times 6 = 12$ centimeters. Area $= \frac{1}{2} \times (6 + 12) \times 5 = 9 \times 5 = 45$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom = 2 x 6 = 12. 1/2 x (6 + 12) x 5 = 9 x 5 = 45.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
