INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcd4b672-b093-40d1-b401-992b09e45811', 'NC26.6.SGMR.1', 3, 'numeric', 'Finding a missing base or height from the area', 'A triangle has an area of 36 square centimeters and a base of 9 centimeters. A parallelogram has the same height as the triangle and a base of 5 centimeters. What is the area of the parallelogram in square centimeters?', '[]', '40', '(2*36/9)*5', 'The triangle''s height is $2 \times 36 \div 9 = 8$ centimeters. The parallelogram has height 8 and base 5, so its area is $5 \times 8 = 40$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle: 36 = 1/2 x 9 x h, so h = 8. Parallelogram: 5 x 8 = 40.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
