INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50885ef1-cd21-4739-b4e6-bbd7c064403f', 'NC26.6.SGMR.1', 3, 'choice', 'Solving area problems in context', 'A field is shaped like a trapezoid. Its parallel sides are 70 meters and 50 meters long, and they are 40 meters apart. One bag of fertilizer covers 400 square meters. How many bags are needed to cover the whole field?', '["6","12","24","3"]', '6', '1/2*(70+50)*40/400', 'The field has area $\frac{1}{2} \times (70 + 50) \times 40 = 2400$ square meters. Each bag covers 400, so $2400 \div 400 = 6$ bags are needed.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 1/2 x (70 + 50) x 40 = 60 x 40 = 2400; 2400 / 400 = 6.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0abdb88-3d02-4a2f-9ef9-ae597af2ff59', 'NC26.6.SGMR.1', 3, 'numeric', 'How area changes when a measurement changes', 'A triangle has an area of 30 square inches. Its base is doubled and its height is tripled. What is the area of the new triangle in square inches?', '[]', '180', '30*2*3', 'Area is half of base times height, so doubling the base and tripling the height multiplies the area by $2 \times 3 = 6$. The new area is $30 \times 6 = 180$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area scales by 2 x 3 = 6: 30 x 6 = 180.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cdc8893-4c96-4ebd-a842-9935497c1a28', 'NC26.6.SGMR.1', 3, 'choice', 'How area changes when a measurement changes', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. Which change gives the triangle with the greatest area?', '["Increase both the base and the height by 2 cm","Increase the base by 4 cm","Increase the height by 3 cm","Increase the base by 5 cm and decrease the height by 1 cm"]', 'Increase both the base and the height by 2 cm', NULL, 'The new areas are 42 (base 14, height 6), 45 (base 10, height 9), 48 (base 12, height 8) and 37.5 (base 15, height 5) square centimeters. Increasing both by 2 gives the greatest, 48.', 'checked', '{"lint":[],"solve":{"answer":"Increase both the base and the height by 2 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original 30. Height +3: 1/2 x 10 x 9 = 45. Both +2: 1/2 x 12 x 8 = 48. Base +4: 1/2 x 14 x 6 = 42. Base +5, height -1: 1/2 x 15 x 5 = 37.5. Greatest 48.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44fec551-e69e-4655-8fde-4a0e044b347e', 'NC26.6.SGMR.1', 3, 'numeric', 'How area changes when a measurement changes', 'A parallelogram has a base of 10 centimeters and a height of 8 centimeters. The height is shortened by 3 centimeters. How many centimeters longer must the base be made to keep the area the same?', '[]', '6', '10*8/(8-3)-10', 'The area is $10 \times 8 = 80$. The new height is $8 - 3 = 5$, so the new base must be $80 \div 5 = 16$ centimeters. That is $16 - 10 = 6$ centimeters longer.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 10 x 8 = 80. New height 5; base must be 80 / 5 = 16, which is 6 cm longer.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdb4634b-8f4e-40f2-bfb6-6f668c55ca45', 'NC26.6.SGMR.1', 3, 'choice', 'Choosing the right measurements and checking an answer', 'Tara says the area of a triangle with a base of 12 meters and a height of 9 meters is 216 square meters. Which statement shows that her answer cannot be right?', '["The base, 12 m, is longer than the height, 9 m.","The area of a triangle is always less than its perimeter.","The triangle fits inside a 12 m by 9 m rectangle, which has an area of only 108 square meters.","The numbers 12 and 9 add up to only 21."]', 'The triangle fits inside a 12 m by 9 m rectangle, which has an area of only 108 square meters.', NULL, 'The triangle fits inside a rectangle with the same base and height, and that rectangle has area $12 \times 9 = 108$ square meters. A triangle inside it cannot have a larger area. The right answer is $\frac{1}{2} \times 108 = 54$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"The triangle fits inside a 12 m by 9 m rectangle, which has an area of only 108 square meters.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correct area is 54. A triangle with base 12 and height 9 fits inside a 12 by 9 rectangle of area 108, so 216 is impossible. The other statements are false or irrelevant.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6090ae6e-f9d8-4dfa-8c7e-1eb5855aa00d', 'NC26.6.SGMR.1', 3, 'numeric', 'Choosing the right measurements and checking an answer', 'A parallelogram has sides of 15 centimeters and 9 centimeters. The height to the 15-centimeter side is 6 centimeters. What is the height to the 9-centimeter side, in centimeters?', '[]', '10', '15*6/9', 'The area is $15 \times 6 = 90$ square centimeters. Using the 9 cm side as the base, base times height is also 90, so the height is $90 \div 9 = 10$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 15 x 6 = 90. Height to the 9 cm side = 90 / 9 = 10. Consistent: 10 <= 15 and 6 <= 9.","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d17d8210-d81d-4cb2-987f-06262b4033cc', 'NC26.6.SGMR.1', 3, 'choice', 'Choosing the right measurements and checking an answer', 'Which is the best estimate for the area of a triangle with a base of 19.8 meters and a height of 10.2 meters, in square meters?', '["200","30","50","100"]', '100', '1/2*20*10', 'Round to 20 and 10. Half of $20 \times 10$ is 100. The exact area is $\frac{1}{2} \times 19.8 \times 10.2 = 100.98$, so 100 is the best estimate. A value of 200 forgets to take half.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Round to base 20, height 10: 1/2 x 20 x 10 = 100. (Exact: 100.98.)","run_id":"claude-code","at":"2026-10-17T20:19:32.455Z"}}', 'ai', NULL, NULL)
