INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68093e88-e6c7-47ca-94bd-efd8850c121f', 'NC26.6.SGMR.1', 3, 'choice', 'Solving area problems in context', 'Anita wants a rectangular wall panel with the same area as 30 parallelogram-shaped stickers. Each sticker has a base of 6 centimeters and a height of 4 centimeters. The panel is 20 centimeters tall. How long is the panel, in centimeters?', '["36","15","18","720"]', '36', '30*6*4/20', 'One sticker has an area of $6 \times 4 = 24$ square centimeters, so 30 stickers have an area of 720 square centimeters. The panel has area length times 20, so the length is $720 \div 20 = 36$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each sticker 6 x 4 = 24 sq cm; 30 stickers = 720 sq cm. Length = 720 / 20 = 36 cm.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
