VALUES ('b444f128-4509-490a-95fc-1cf66a28b983', 'NC26.6.SGMR.2', 1, 'choice', 'Reading ordered pairs and plotting by moves', 'Which ordered pair names the point 2 units left of the y-axis and 7 units below the x-axis?', '["$(2, -7)$","$(-7, -2)$","$(-2, 7)$","$(-2, -7)$"]', '$(-2, -7)$', NULL, 'Left of the y-axis means a negative x-coordinate, $-2$. Below the x-axis means a negative y-coordinate, $-7$. The x-coordinate is written first.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, -7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 left: x = -2; 7 below: y = -7. (-2, -7).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
