INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a37e446-7a40-4263-b056-9049169e5b2d', 'NC26.6.SGMR.2', 1, 'choice', 'Reflections across both axes and what they preserve', 'A point in Quadrant I is reflected across the x-axis. In which quadrant is the new point? Quadrant I is where both coordinates are positive, and the quadrants are numbered I, II, III, IV going counterclockwise from there.', '["Quadrant IV","Quadrant I","Quadrant II","Quadrant III"]', 'Quadrant IV', NULL, 'A point in Quadrant I has positive x and positive y. Across the x-axis the y-coordinate becomes negative, so the new point has positive x and negative y, which is Quadrant IV.', 'checked', '{"lint":[],"solve":{"answer":"Quadrant IV","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(+,+) -> (+,-): Quadrant IV.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
