INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b05ce5d6-bfe7-4d9f-8506-93d45a331ffb', 'NC26.6.SGMR.2', 1, 'numeric', 'Finding a missing vertex or a point from conditions', 'Point $P$ is at $(-3, 5)$. Point $Q$ is directly below $P$, 8 units away. What is the y-coordinate of $Q$?', '[]', '-3', '5-8', 'Moving 8 units down subtracts 8 from the y-coordinate: $5 - 8 = -3$. So $Q$ is at $(-3, -3)$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 8 = -3.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
