INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfcee2fd-f4c7-4cf5-8c04-d097bb52adfa', 'NC26.6.SGMR.2', 2, 'numeric', 'Perimeter of a rectangle on the coordinate plane', 'A rectangle has vertices at $(1, 2)$, $(7, 2)$, $(7, -3)$ and $(1, -3)$. What is the perimeter of the rectangle in units?', '[]', '22', '2*(6+5)', 'The width is $7 - 1 = 6$ units. The height is $2 - (-3) = 5$ units. The perimeter is $2 \times (6 + 5) = 22$ units.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width from x = 1 to 7 is 6; height from y = -3 to 2 is 5. Perimeter = 2(6 + 5) = 22.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3b96504-02eb-4044-904d-26fa56b12a58', 'NC26.6.SGMR.2', 2, 'numeric', 'Naming the quadrant or axis of a point', 'Here are five points: $(2, 3)$, $(-1, 4)$, $(5, -2)$, $(6, 6)$ and $(-3, -3)$. How many of them are in Quadrant I?', '[]', '2', '2', 'Quadrant I needs both coordinates positive. Only $(2, 3)$ and $(6, 6)$ qualify, so the answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both coordinates positive: (2, 3) and (6, 6). Count 2.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
