INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9749eea0-278d-4944-b31e-3cbf1025c4a0', 'NC26.6.SGMR.2', 2, 'choice', 'Naming the quadrant or axis of a point', 'Exactly one of these points is not in the upper left part of the plane (Quadrant II). Which one is it?', '["$(3, 7)$","$(-2, 6)$","$(-9, 1)$","$(-1, 10)$"]', '$(3, 7)$', NULL, 'Quadrant II points have a negative x-coordinate and a positive y-coordinate. $(3, 7)$ has a positive x-coordinate, so it is in Quadrant I.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-1,10), (-2,6), (-9,1) all have x<0, y>0 (Quadrant II). (3, 7) has x>0, so it is in Quadrant I.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
