INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a523a1-568e-46c2-8eab-e42c5c5b03b6', 'NC26.6.SGMR.2', 2, 'choice', 'Reading ordered pairs and plotting by moves', 'Jo starts at the point $(3, -4)$ and moves 7 units left and 2 units up. Where does Jo stop?', '["$(-4, -2)$","$(10, -2)$","$(-4, -6)$","$(-2, -4)$"]', '$(-4, -2)$', NULL, 'Moving 7 left: $3 - 7 = -4$. Moving 2 up: $-4 + 2 = -2$. Jo stops at $(-4, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-4, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: 3 - 7 = -4; y: -4 + 2 = -2. (-4, -2).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
