INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb26278c-9a7e-4170-9cfb-9413a3332126', 'NC26.6.SGMR.2', 2, 'choice', 'Distance between points that share a coordinate', 'Point $P$ is at $(-5, 3)$ and point $Q$ is at $(-5, -4)$. How many units apart are they?', '["1","9","7","12"]', '7', '3+4', 'The points are on opposite sides of the x-axis. The distance from $P$ to the axis is 3 and from $Q$ to the axis is 4, so the distance is $3 + 4 = 7$ units.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x: |3| + |-4| = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
