INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f3ae23a-747a-44c0-90fe-d6092e70f8e5', 'NC26.6.SGMR.2', 2, 'numeric', 'Distance from a point to an axis', 'The point $(-9, -4)$ is some distance from the x-axis and some distance from the y-axis. What is the total of those two distances, in units?', '[]', '13', '9+4', 'The distance from the y-axis is $|-9| = 9$ and the distance from the x-axis is $|-4| = 4$. The total is $9 + 4 = 13$ units.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From x-axis |-4| = 4; from y-axis |-9| = 9. Total 13.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
