VALUES ('53974385-1515-4c5e-a323-48d0a2f2ba0f', 'NC26.6.SGMR.2', 2, 'choice', 'Distance from a point to an axis', 'A point is in Quadrant IV. It is 6 units from the x-axis and 2 units from the y-axis. What are its coordinates?', '["$(6, -2)$","$(-2, 6)$","$(2, 6)$","$(2, -6)$"]', '$(2, -6)$', NULL, 'Distance 2 from the y-axis means $x = 2$ or $-2$, and Quadrant IV makes x positive, so $x = 2$. Distance 6 from the x-axis means $y = 6$ or $-6$, and Quadrant IV makes y negative, so $y = -6$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, -6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrant IV: x > 0, y < 0. |y| = 6, |x| = 2: (2, -6).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0987499b-4690-481c-bb61-48c68213dd1d', 'NC26.6.SGMR.2', 2, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'A fence goes all the way around a rectangular yard. On a map grid, the corners of the yard are $(-4, 1)$, $(3, 1)$, $(3, -5)$ and $(-4, -5)$, and each grid unit is 1 meter. How many meters of fence are needed?', '[]', '26', '2*((3+4)+(1+5))', 'The yard is $3 - (-4) = 7$ meters wide and $1 - (-5) = 6$ meters tall. The fence is $2 \times (7 + 6) = 26$ meters long.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length 3 - (-4) = 7; width 1 - (-5) = 6. Perimeter 2 x (7 + 6) = 26.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d43a618-7a8d-4955-9da1-f56533bd4994', 'NC26.6.SGMR.2', 2, 'choice', 'Perimeter of a polygon on the coordinate plane', 'A triangle has vertices at $(-2, -1)$, $(1, -1)$ and $(1, 3)$. The side from $(-2, -1)$ to $(1, 3)$ is 5 units long. What is the perimeter of the triangle in units?', '["7","9","12","6"]', '12', '3+4+5', 'The horizontal side goes from $x = -2$ to $x = 1$, which is 3 units. The vertical side goes from $y = -1$ to $y = 3$, which is 4 units. The perimeter is $3 + 4 + 5 = 12$ units.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal side 1 - (-2) = 3; vertical side 3 - (-1) = 4; slanted side 5. Perimeter 12.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3582762f-053f-4f1a-819c-9abc23199c7d', 'NC26.6.SGMR.2', 2, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'One side of a square goes from $(-3, 2)$ to $(-3, -4)$. What is the perimeter of the square in units?', '[]', '24', '4*(2+4)', 'The side is vertical, and its length is $2 - (-4) = 6$ units. The perimeter is $4 \times 6 = 24$ units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 2 - (-4) = 6; perimeter 24.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fd4e4a2-7a6d-4df6-92cd-0fb9e853ac4f', 'NC26.6.SGMR.2', 2, 'numeric', 'Area of a rectangle or square on the coordinate plane', 'On a map grid, a rectangular park has corners at $(-6, -3)$, $(2, -3)$, $(2, 4)$ and $(-6, 4)$. What is the area of the park in square units?', '[]', '56', '(2+6)*(4+3)', 'The park is $2 - (-6) = 8$ units wide and $4 - (-3) = 7$ units tall. The area is $8 \times 7 = 56$ square units.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 2 - (-6) = 8; height 4 - (-3) = 7; area 56.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
