INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6785bc74-d07d-440f-8896-0090f38a3856', 'NC26.6.SGMR.2', 2, 'choice', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'Find the area, in square units, of the triangle whose corners are $(-4, -2)$, $(2, -2)$ and $(-1, 5)$.', '["21","42","15","13"]', '21', '1/2*6*7', 'The base from $(-4, -2)$ to $(2, -2)$ is 6 units. The top point is $5 - (-2) = 7$ units above the base. Area $= \frac{1}{2} \times 6 \times 7 = 21$ square units.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 2 - (-4) = 6 on y = -2; height 5 - (-2) = 7. Area 1/2 x 6 x 7 = 21.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
