INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57aee28e-92fd-4385-98ff-2448c1078a2e', 'NC26.6.SGMR.2', 2, 'numeric', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'A triangle is drawn with its three corners at $(-5, 3)$, $(4, 3)$ and $(1, -2)$. How many square units of area does it cover?', '[]', '22.5', '1/2*9*5', 'The base from $(-5, 3)$ to $(4, 3)$ is 9 units. The third vertex is $3 - (-2) = 5$ units below the base. Area $= \frac{1}{2} \times 9 \times 5 = 22.5$ square units.', 'checked', '{"lint":[],"solve":{"answer":"22.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 4 - (-5) = 9 on y = 3; height 3 - (-2) = 5. Area 1/2 x 9 x 5 = 22.5.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
