INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e73dade-e61b-4383-bd0a-e5d22696e5d2', 'NC26.6.SGMR.2', 2, 'numeric', 'Finding a missing vertex or a point from conditions', 'Two neighboring corners of a square are at $(2, -1)$ and $(2, 4)$. The square lies to the right of the line joining them. What is the x-coordinate of the other two corners?', '[]', '7', '2+5', 'The side joining the two corners is $4 - (-1) = 5$ units long, so the square is 5 units wide. Going 5 units right from $x = 2$ gives $x = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 4 - (-1) = 5; to the right: x = 2 + 5 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
