INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f264f890-7b27-4b7d-b8b2-85c7f6018ad6', 'NC26.6.SGMR.2', 3, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'A shape on the coordinate plane has vertices at $(0, 0)$, $(6, 0)$, $(6, 2)$, $(3, 2)$, $(3, 5)$ and $(0, 5)$, joined in that order and then back to $(0, 0)$. What is its perimeter in units?', '[]', '22', '6+2+3+3+3+5', 'The sides have lengths 6, 2, 3, 3, 3 and 5 units. Their sum is $6 + 2 + 3 + 3 + 3 + 5 = 22$ units.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides: 6, 2, 3, 3, 3, 5. Total 22.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
