INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eac37065-78d6-4cd8-97d3-6b718baf252d', 'NC26.6.SGMR.2', 3, 'choice', 'Perimeter of a polygon on the coordinate plane', 'Four rectangles have sides parallel to the axes and are given by two opposite corners. Which rectangle has the greatest perimeter?', '["Corners $(0, 0)$ and $(8, 3)$","Corners $(-2, -2)$ and $(3, 3)$","Corners $(-5, 1)$ and $(3, 5)$","Corners $(-10, 0)$ and $(2, 1)$"]', 'Corners $(-10, 0)$ and $(2, 1)$', NULL, 'The sizes are $12 \times 1$, $8 \times 3$, $5 \times 5$ and $8 \times 4$, with perimeters 26, 22, 20 and 24. The first, with corners $(-10, 0)$ and $(2, 1)$, is greatest.', 'checked', '{"lint":[],"solve":{"answer":"Corners $(-10, 0)$ and $(2, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x3: 22. 8x4: 24. 5x5: 20. 12x1: 26. Greatest 26.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2124607-1402-4f60-9a2f-d5ebfbed1e7f', 'NC26.6.SGMR.2', 3, 'numeric', 'Perimeter of a polygon on the coordinate plane', 'A rectangle has two vertices at $(-3, -1)$ and $(4, -1)$. Its perimeter is 30 units, and its other two vertices are above these two. What is the y-coordinate of the other two vertices?', '[]', '7', '-1+(30/2-7)', 'The known side is $4 - (-3) = 7$ units long. Half the perimeter is 15, so the other side is $15 - 7 = 8$ units. Going up 8 from $y = -1$ gives $y = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 4 - (-3) = 7. 2(7 + h) = 30, h = 8. y = -1 + 8 = 7.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93334619-d59b-49f6-a110-e71506c5047a', 'NC26.6.SGMR.2', 3, 'choice', 'Area of a rectangle or square on the coordinate plane', 'A square has two neighboring corners at $(-2, -5)$ and $(-2, 3)$. What is the area of the square in square units?', '["32","16","64","8"]', '64', '8*8', 'The two corners are joined by a side of length $3 - (-5) = 8$ units. The area is $8 \times 8 = 64$ square units.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side 3 - (-5) = 8; area 64.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e396230-1d9c-4fce-a8b3-f50c11e2514b', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a rectangle or square on the coordinate plane', 'A shape is made of two rectangles that share part of a side and do not overlap. The first has opposite corners at $(0, 0)$ and $(6, 4)$. The second has opposite corners at $(6, 0)$ and $(9, 2)$. What is the total area in square units?', '[]', '30', '6*4+3*2', 'The first rectangle is $6 \times 4 = 24$ square units. The second is $(9 - 6) \times (2 - 0) = 3 \times 2 = 6$ square units. The total is $24 + 6 = 30$ square units.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 6 x 4 = 24; second 3 x 2 = 6; total 30.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd72ad13-53fb-4397-a006-47116175cc4e', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a rectangle or square on the coordinate plane', 'A rectangle has its two bottom vertices at $(-3, 1)$ and $(2, 1)$ and an area of 60 square units. Its top vertices are above the bottom ones. What is the y-coordinate of the top vertices?', '[]', '13', '1+60/5', 'The bottom side is $2 - (-3) = 5$ units long, so the height is $60 \div 5 = 12$ units. Going up 12 from $y = 1$ gives $y = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 2 - (-3) = 5; height 60 / 5 = 12; y = 1 + 12 = 13.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c94330c1-2bae-4919-9c21-97d185c02a17', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'A parallelogram has vertices at $(-2, -1)$, $(-2, 4)$, $(3, 6)$ and $(3, 1)$. What is its area in square units?', '[]', '25', '5*5', 'Two sides are vertical: one from $y = -1$ to $y = 4$, which is 5 units long, and the other from $y = 1$ to $y = 6$. Use the first as the base. The distance between the vertical lines $x = -2$ and $x = 3$ is 5, so the height is 5. Area $= 5 \times 5 = 25$ square units.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical sides x = -2 (from -1 to 4) and x = 3 (from 1 to 6), each 5 long; they are 5 apart. Area 5 x 5 = 25.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('936ba130-f98f-4718-b951-d34363920b1b', 'NC26.6.SGMR.2', 3, 'numeric', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'A trapezoid has vertices at $(0, 0)$, $(8, 0)$, $(6, 4)$ and $(2, 4)$. What is its area in square units?', '[]', '24', '1/2*(8+4)*4', 'The parallel sides are the bottom, from $x = 0$ to $x = 8$ (8 units), and the top, from $x = 2$ to $x = 6$ (4 units). The height is 4. Area $= \frac{1}{2} \times (8 + 4) \times 4 = 24$ square units.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel sides 8 and 6 - 2 = 4; height 4. Area 1/2 x 12 x 4 = 24.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2be062b9-5cb5-4cb7-8413-596f0cd1ef94', 'NC26.6.SGMR.2', 3, 'choice', 'Area of a triangle, parallelogram or trapezoid from its vertices', 'A triangle has vertices at $(0, 6)$, $(0, -2)$ and $(5, 1)$. What is its area in square units?', '["40","20","4","13"]', '20', '1/2*8*5', 'The side from $(0, 6)$ to $(0, -2)$ is on the y-axis and is $6 + 2 = 8$ units long. The third point is 5 units from the y-axis. Area $= \frac{1}{2} \times 8 \times 5 = 20$ square units.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base on the y-axis 6 - (-2) = 8; height 5. Area 1/2 x 8 x 5 = 20.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e3b2900-7b6a-4f9f-85fa-4275d97ac341', 'NC26.6.SGMR.2', 3, 'choice', 'Finding a missing vertex or a point from conditions', 'A parallelogram has vertices $A(0, 0)$, $B(5, 0)$, $C(7, 3)$ and $D$, listed in order around the shape. What are the coordinates of $D$?', '["$(2, 3)$","$(12, 3)$","$(-2, 3)$","$(2, -3)$"]', '$(2, 3)$', NULL, 'Side $AB$ goes 5 units right, so the opposite side $DC$ must also go 5 units right. $D$ is 5 units left of $C$: $(7 - 5, 3) = (2, 3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(2, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB goes 5 right, so DC goes 5 right: D = (7 - 5, 3) = (2, 3).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41390257-08e3-4915-94e7-45cb1e584f93', 'NC26.6.SGMR.2', 3, 'numeric', 'Finding a missing vertex or a point from conditions', 'A square has sides parallel to the axes and a side length of 6. Its lower left corner is at $(-4, -3)$. What is the sum of the x-coordinate and the y-coordinate of its upper right corner?', '[]', '5', '-4+6-3+6', 'The upper right corner is 6 units right and 6 units up from the lower left: $(-4 + 6, -3 + 6) = (2, 3)$. The sum is $2 + 3 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Upper right = (-4 + 6, -3 + 6) = (2, 3). Sum 5.","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07d7cf5c-cc17-47f9-8fc5-db1d21790d61', 'NC26.6.SGMR.2', 3, 'choice', 'Finding a missing vertex or a point from conditions', 'Two vertices of a rectangle are at $(-2, 1)$ and $(4, 1)$. The rectangle has an area of 24 square units, and its other two vertices are below these. Which pair gives the other two vertices?', '["$(-2, 5)$ and $(4, 5)$","$(-2, -3)$ and $(4, -3)$","$(-2, -7)$ and $(4, -7)$","$(-2, -2)$ and $(4, -2)$"]', '$(-2, -3)$ and $(4, -3)$', NULL, 'The known side is $4 - (-2) = 6$ units long, so the height is $24 \div 6 = 4$. Going down 4 from $y = 1$ gives $y = -3$. The pair at $y = 5$ is above the side.', 'checked', '{"lint":[],"solve":{"answer":"$(-2, -3)$ and $(4, -3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 4 - (-2) = 6; height 24 / 6 = 4; below: y = 1 - 4 = -3. (-2,-3) and (4,-3).","run_id":"claude-code","at":"2026-10-17T20:19:32.493Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('593fbdcd-f8eb-4942-b356-847116cb7b65', 'NC26.6.SGMR.2', 3, 'numeric', 'Naming the quadrant or axis of a point', 'How many points with integer coordinates are in Quadrant II and have an $x$-coordinate of at least $-4$ and a $y$-coordinate of at most 3?', '[]', '12', '4*3', 'In Quadrant II, $x$ is negative and $y$ is positive. So $x$ can be $-4$, $-3$, $-2$ or $-1$, and $y$ can be 1, 2 or 3. That gives $4 \times 3 = 12$ points.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrant II: x<0, y>0. x in {-4,-3,-2,-1}, y in {1,2,3}: 4 x 3 = 12.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1850e5ec-9093-4167-a934-6e05c614cef1', 'NC26.6.SGMR.2', 3, 'numeric', 'Distance from a point to an axis', 'A point in Quadrant III is 7 units from the $y$-axis and 4 units from the $x$-axis. What is the sum of its $x$-coordinate and its $y$-coordinate?', '[]', '-11', '-7-4', 'In Quadrant III both coordinates are negative. A point 7 units from the $y$-axis has $x = -7$, and a point 4 units from the $x$-axis has $y = -4$. The sum is $-7 + (-4) = -11$.', 'checked', '{"lint":[],"solve":{"answer":"-11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Quadrant III: both negative. 7 from y-axis -> x=-7; 4 from x-axis -> y=-4. Sum -11.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
