INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f65b6265-8c37-4ec2-947b-0b7ddc44ca1a', 'NC26.6.SGMR.3', 1, 'numeric', 'Counting faces, edges and vertices of prisms and pyramids', 'A triangular prism has two triangle bases joined by rectangles. How many faces does it have in all?', '[]', '5', '2+3', 'The 2 triangle bases each have 3 sides, and each side is joined by one rectangle, so there are 3 rectangles. The solid has $2 + 3 = 5$ faces.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 triangles + 3 rectangles = 5 faces.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
