INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db83f6a8-9065-4421-be92-f545798134b7', 'NC26.6.SGMR.3', 1, 'choice', 'Counting faces, edges and vertices of prisms and pyramids', 'Which of these solids has exactly 6 faces?', '["Triangular pyramid","Triangular prism","Rectangular prism","Pentagonal prism"]', 'Rectangular prism', NULL, 'A rectangular prism has 2 bases and 4 rectangles, which is 6 faces. A triangular pyramid has 4 faces, a triangular prism has $2 + 3 = 5$ faces and a pentagonal prism has $2 + 5 = 7$ faces.', 'checked', '{"lint":[],"solve":{"answer":"Rectangular prism","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangular prism 6; triangular prism 5; triangular pyramid 4; pentagonal prism 7.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
