INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7ad8ea8-fd6b-4ae0-9a8f-e60c288b3c90', 'NC26.6.SGMR.3', 1, 'choice', 'Surface area of a rectangular prism', 'A rectangular prism is 5 inches long, 2 inches wide and 1 inch tall. Which expression gives its surface area in square inches?', '["$2(5 \\times 2) + 2(5 \\times 1) + 2(2 \\times 1)$","$5 \\times 2 \\times 1$","$(5 \\times 2) + (5 \\times 1) + (2 \\times 1)$","$2(5 + 2 + 1)$"]', '$2(5 \times 2) + 2(5 \times 1) + 2(2 \times 1)$', NULL, 'The prism has three kinds of faces, each appearing twice: $5 \times 2$, $5 \times 1$ and $2 \times 1$. Adding the areas of all 6 faces gives the first expression. The product $5 \times 2 \times 1$ is the volume, and the other two expressions leave out faces or do not multiply to find areas.', 'checked', '{"lint":[],"solve":{"answer":"$2(5 \\times 2) + 2(5 \\times 1) + 2(2 \\times 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SA = 2lw + 2lh + 2wh = 2(5x2) + 2(5x1) + 2(2x1) = 34. Other options: 16, 17, 10.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24c9246a-281d-41d6-9346-d8f6fcae8891', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a rectangular prism', 'A small box is 5 centimeters long, 3 centimeters wide and 2 centimeters tall. How many square centimeters of paper cover the whole box?', '[]', '62', '2*(5*3+5*2+3*2)', 'The faces are $5 \times 3 = 15$, $5 \times 2 = 10$ and $3 \times 2 = 6$ square centimeters, each twice. The surface area is $2 \times (15 + 10 + 6) = 2 \times 31 = 62$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5x3 + 5x2 + 3x2) = 2(15 + 10 + 6) = 62.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72aa0267-2cab-4757-bf5e-9024ed2366b7', 'NC26.6.SGMR.3', 1, 'numeric', 'Surface area of a rectangular prism', 'The top of a rectangular prism measures 6 centimeters by 3 centimeters. What is the combined area of the top and the bottom, in square centimeters?', '[]', '36', '2*6*3', 'The top and bottom are matching rectangles. Each has an area of $6 \times 3 = 18$ square centimeters, so together they cover $2 \times 18 = 36$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top = 6 x 3 = 18; bottom same; 36.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
