INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93df6b64-710f-46fc-a0ac-6b06db5b7602', 'NC26.6.SGMR.3', 1, 'choice', 'Volume of a rectangular prism with fractional edges', 'A rectangular prism is $2\frac{1}{2}$ inches long, 3 inches wide and 4 inches tall. Which expression gives its volume in cubic inches?', '["$2\\frac{1}{2} + 3 + 4$","$2\\frac{1}{2} \\times 3 \\times 4$","$2 \\times 3 \\times 4$","$2\\frac{1}{2} \\times 3 + 4$"]', '$2\frac{1}{2} \times 3 \times 4$', NULL, 'Volume is length times width times height, so multiply all three edges: $2\frac{1}{2} \times 3 \times 4$. Adding the edges does not find volume, dropping the $\frac{1}{2}$ changes the length, and adding the 4 at the end leaves out the height.', 'checked', '{"lint":[],"solve":{"answer":"$2\\frac{1}{2} \\times 3 \\times 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = l x w x h = 2 1/2 x 3 x 4 (= 30).","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35a21166-aa2e-4283-9fa7-72d1586703bc', 'NC26.6.SGMR.3', 1, 'numeric', 'Counting unit cubes with fractional edges that fill a prism', 'A cube with 1-inch edges is filled with smaller cubes. Each small cube has an edge of $\frac{1}{2}$ inch. How many small cubes fill the large cube?', '[]', '8', '2*2*2', 'Along each 1-inch edge, 2 small cubes of $\frac{1}{2}$ inch fit. So the large cube holds $2 \times 2 \times 2 = 8$ small cubes.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 per edge: 2 x 2 x 2 = 8.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84bf2683-39c3-4e8f-8ca2-75690bbc1b2f', 'NC26.6.SGMR.3', 1, 'choice', 'Counting unit cubes with fractional edges that fill a prism', 'A cube with edges of 1 foot is filled exactly with small cubes whose edges are each $\frac{1}{3}$ foot. How many small cubes are needed?', '["9","27","3","$\\frac{1}{27}$"]', '27', '3^3', 'Along each 1-foot edge, 3 small cubes fit. The large cube holds $3 \times 3 \times 3 = 27$ small cubes. The value 9 is one layer, 3 is one row, and $\frac{1}{27}$ is the volume of one small cube, not the number of cubes.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 per edge: 3^3 = 27.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96f0e507-5d03-4613-addf-1dd79a5fe2e8', 'NC26.6.SGMR.3', 1, 'choice', 'Choosing between surface area and volume, and their units', 'Mia wants to know how much wrapping paper she needs to cover a box. Which measure should she find?', '["The volume of the box","The perimeter of the top","The length of one edge","The surface area of the box"]', 'The surface area of the box', NULL, 'Wrapping paper covers the outside of the box, and the total area of all the faces is the surface area. Volume tells how much space is inside the box.', 'checked', '{"lint":[],"solve":{"answer":"The surface area of the box","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Covering = surface area.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47b13acd-9348-4ec6-af66-8dec79c0a7ba', 'NC26.6.SGMR.3', 1, 'choice', 'Choosing between surface area and volume, and their units', 'Which unit is best for measuring the volume of a rectangular prism?', '["Square centimeters","Centimeters","Cubic centimeters","Grams"]', 'Cubic centimeters', NULL, 'Volume counts the cubes that fill a solid, so it is measured in cubic units such as cubic centimeters. Square centimeters measure area and centimeters measure length.', 'checked', '{"lint":[],"solve":{"answer":"Cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume is in cubic units: cubic centimeters.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e214189-8a1c-4ffb-a917-2955857fadcc', 'NC26.6.SGMR.3', 1, 'choice', 'Choosing between surface area and volume, and their units', 'Which job needs a volume, not a surface area?', '["Finding how much paint covers the outside of a shed","Finding how much sand fills a sandbox","Finding how much paper wraps a present","Finding how much cloth covers a box"]', 'Finding how much sand fills a sandbox', NULL, 'Filling a sandbox takes the space inside, which is volume. Painting a shed, wrapping a present and covering a box all cover an outside surface, which is surface area.', 'checked', '{"lint":[],"solve":{"answer":"Finding how much sand fills a sandbox","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Filling a sandbox is volume; the others cover outsides (surface area).","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a550aa7-6eed-4a9f-a672-ed07fa0bd390', 'NC26.6.SGMR.3', 1, 'numeric', 'Volume of a prism with fractional edges', 'A small cube has edges that are each $\frac{1}{2}$ inch long. What is its volume in cubic inches?', '[]', '1/8', '1/2*1/2*1/2', 'Volume is length times width times height: $\frac{1}{2} \times \frac{1}{2} \times \frac{1}{2} = \frac{1}{8}$ cubic inch.', 'checked', '{"lint":[],"solve":{"answer":"1/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/2)^3 = 1/8 cubic inch.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8545dd84-38a4-43a9-8ed5-d66724c9f03d', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a rectangular prism', 'A rectangular prism is 6 centimeters long, 4 centimeters wide and 3 centimeters tall. What is its surface area in square centimeters?', '[]', '108', '2*(6*4+6*3+4*3)', 'There are three pairs of matching faces: $6 \times 4 = 24$, $6 \times 3 = 18$ and $4 \times 3 = 12$. Add them and double: $2 \times (24 + 18 + 12) = 108$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"108","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SA = 2(6x4 + 6x3 + 4x3) = 2(24 + 18 + 12) = 2 x 54 = 108.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2f1c5c7-4f77-4cb0-b696-cad923ac8891', 'NC26.6.SGMR.3', 2, 'numeric', 'Volume of a rectangular prism with fractional edges', 'A rectangular prism has a length of $2\frac{1}{2}$ feet, a width of $1\frac{1}{2}$ feet and a height of 2 feet. What is its volume in cubic feet?', '[]', '7 1/2', '5/2*3/2*2', 'Multiply the three edges: $\frac{5}{2} \times \frac{3}{2} \times 2 = \frac{30}{4} = 7\frac{1}{2}$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 5/2 x 3/2 x 2 = 30/4 = 15/2 = 7.5.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5139bf6d-f832-4887-838b-545a4068f61b', 'NC26.6.SGMR.3', 2, 'choice', 'Total area of the faces in a net', 'A net for a box has six rectangles: two that are 5 by 3, two that are 5 by 2 and two that are 3 by 2 (all measures in centimeters). What is the total area of the net in square centimeters?', '["$62$","$31$","$30$","$50$"]', '$62$', '2*(5*3+5*2+3*2)', 'Find the area of each kind of rectangle: $5 \times 3 = 15$, $5 \times 2 = 10$ and $3 \times 2 = 6$. There are two of each, so the total is $2 \times (15 + 10 + 6) = 62$ square centimeters. (31 counts each kind once, 30 is the volume, and 50 leaves out one pair of faces.)', 'checked', '{"lint":[],"solve":{"answer":"$62$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5x3) + 2(5x2) + 2(3x2) = 30 + 20 + 12 = 62.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f923b81a-87c0-4d47-8e78-0219bf913018', 'NC26.6.SGMR.3', 2, 'choice', 'Naming the solid a net folds into', 'Which set of shapes can be folded into a rectangular pyramid?', '["2 rectangles and 4 triangles","1 rectangle and 3 triangles","1 rectangle and 4 triangles","1 rectangle and 5 triangles"]', '1 rectangle and 4 triangles', NULL, 'A rectangular pyramid has one rectangular base. Each of the 4 sides of the base is joined to one triangle, so it has 4 triangles. That makes 1 rectangle and 4 triangles. Two rectangles would make a second base, and 3 or 5 triangles would not match the 4 sides.', 'checked', '{"lint":[],"solve":{"answer":"1 rectangle and 4 triangles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangular pyramid: 1 rectangular base + 1 triangle per side = 4 triangles.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f095c940-e3c0-4427-9e63-ff3db94f468b', 'NC26.6.SGMR.3', 2, 'choice', 'Naming the solid a net folds into', 'One solid has a square base and all its other faces are triangles that meet at one point. A second solid has two triangular bases joined by three rectangles. Which pair of names matches the two solids?', '["Square prism and triangular pyramid","Square pyramid and triangular pyramid","Square prism and triangular prism","Square pyramid and triangular prism"]', 'Square pyramid and triangular prism', NULL, 'A solid with one base and triangles meeting at a point is a pyramid, and its base is a square, so the first solid is a square pyramid. A solid with two matching triangle bases joined by rectangles is a triangular prism.', 'checked', '{"lint":[],"solve":{"answer":"Square pyramid and triangular prism","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square base with triangles meeting at a point = square pyramid; 2 triangular bases + 3 rectangles = triangular prism.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da4bbc3c-585a-441a-975e-a7144e28827f', 'NC26.6.SGMR.3', 2, 'choice', 'Naming the solid a net folds into', 'A net is made of 1 pentagon and 5 triangles. What is the name of the solid it makes?', '["Pentagonal prism","Pentagonal pyramid","Hexagonal pyramid","Square pyramid"]', 'Pentagonal pyramid', NULL, 'One base with triangles around it makes a pyramid. The base is a pentagon, which has 5 sides, and there is one triangle for each side. So the solid is a pentagonal pyramid.', 'checked', '{"lint":[],"solve":{"answer":"Pentagonal pyramid","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 pentagon base + 5 triangles = pentagonal pyramid.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f699b32-4763-43bb-976e-c8748cf92853', 'NC26.6.SGMR.3', 2, 'choice', 'Counting faces, edges and vertices of prisms and pyramids', 'Which statement about a pyramid is true?', '["It has two bases that match","Every face except the base is a triangle","Its side faces are rectangles","It has as many faces as its base has sides"]', 'Every face except the base is a triangle', NULL, 'A pyramid has one base, and its other faces are triangles that meet at one point. The two bases that match belong to a prism, whose side faces are rectangles. A pyramid has one more face than its base has sides, because the base is a face too.', 'checked', '{"lint":[],"solve":{"answer":"Every face except the base is a triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pyramid: one base, lateral faces are triangles meeting at apex. True: every face except the base is a triangle. Others false (one base; sides not rectangles; faces = sides + 1).","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f89b4b71-aede-4074-936e-37d67b095c12', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a cube', 'A cube-shaped storage box has edges that are each 12 inches long. How many square inches of plastic does it take to cover its whole outside surface?', '[]', '864', '6*12^2', 'One face is $12 \times 12 = 144$ square inches. The box has 6 faces, so the plastic covers $6 \times 144 = 864$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"864","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 12 x 12 = 6 x 144 = 864.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('212dce95-f54f-49e3-b795-977501654fbd', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a cube', 'A large cube-shaped box has edges of 2.5 meters. What is its surface area, in square meters?', '["25","15.625","15","37.5"]', '37.5', '6*2.5^2', 'One face has an area of $2.5 \times 2.5 = 6.25$ square meters. There are 6 faces, so the surface area is $6 \times 6.25 = 37.5$ square meters. The number 15.625 is the volume, 25 uses only 4 faces and 15 is $6 \times 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"37.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 2.5^2 = 6 x 6.25 = 37.5.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0df8d953-0e84-4904-9682-47085b688180', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a rectangular prism', 'A gift box is 12 inches long, 8 inches wide and 4 inches tall. How many square inches of wrapping paper are needed to cover the whole box with no overlap?', '[]', '352', '2*(12*8+12*4+8*4)', 'The faces are $12 \times 8 = 96$, $12 \times 4 = 48$ and $8 \times 4 = 32$ square inches, each twice. The paper needed is $2 \times (96 + 48 + 32) = 2 \times 176 = 352$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"352","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12x8 + 12x4 + 8x4) = 2(96 + 48 + 32) = 2 x 176 = 352.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ccd7bf3-682b-4b35-b625-d09139a18ce5', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'Ben finds the surface area of a box that is 7 centimeters long, 4 centimeters wide and 3 centimeters tall. He gets 84 square centimeters. What mistake did Ben make?', '["He found the area of only the top and bottom","He found the volume instead of the surface area","He found the area of only the four side faces","He added the length, width and height"]', 'He found the volume instead of the surface area', NULL, 'Ben multiplied $7 \times 4 \times 3 = 84$, which is the volume. The surface area is $2 \times (28 + 21 + 12) = 122$ square centimeters. The top and bottom alone give 56, the four sides alone give 66, and adding the three edges gives 14, so none of those match his 84.', 'checked', '{"lint":[],"solve":{"answer":"He found the volume instead of the surface area","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 4 x 3 = 84 = volume. True SA = 2(28+21+12) = 122; top+bottom 56; four sides 66; sum of dimensions 14. So he found the volume.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0418a2ab-43c3-441d-bbea-7596e5bf3049', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A classroom is 8 meters long, 6 meters wide and 3 meters tall. The four walls will be painted. What is the total area of the walls, in square meters? (Ignore doors and windows.)', '["132","180","84","42"]', '84', NULL, 'Two walls are $8 \times 3 = 24$ square meters each and two walls are $6 \times 3 = 18$ square meters each. The total is $2 \times 24 + 2 \times 18 = 48 + 36 = 84$ square meters. The number 132 also counts the ceiling, 180 counts all six faces, and 42 counts only one wall of each size.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Walls: 2(8x3) + 2(6x3) = 48 + 36 = 84.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b9881a2-56b7-4fea-b8de-2d48e68d52bb', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A rectangular prism is 8 centimeters long, 3 centimeters wide and 2 centimeters tall. What is its surface area, in square centimeters?', '["92","46","48","44"]', '92', '2*(8*3+8*2+3*2)', 'The faces are $8 \times 3 = 24$, $8 \times 2 = 16$ and $3 \times 2 = 6$ square centimeters, each twice. The surface area is $2 \times (24 + 16 + 6) = 2 \times 46 = 92$ square centimeters. The value 46 counts each pair once, 48 is the volume, and 44 leaves out the top and bottom.', 'checked', '{"lint":[],"solve":{"answer":"92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(8x3 + 8x2 + 3x2) = 2(24 + 16 + 6) = 92.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae69864f-0dd1-43c7-a503-c3c9bce6394c', 'NC26.6.SGMR.3', 2, 'choice', 'Total area of the faces in a net', 'The net of a triangular prism has two right triangles with legs of 6 centimeters and 8 centimeters. It also has three rectangles that measure 6 by 12, 8 by 12 and 10 by 12 centimeters. What is the total area of the net, in square centimeters?', '["312","336","384","288"]', '336', '2*(6*8/2)+6*12+8*12+10*12', 'Each triangle has an area of $\frac{1}{2} \times 6 \times 8 = 24$ square centimeters, so the two triangles total 48. The rectangles are 72, 96 and 120, which total 288. The net has a total area of $48 + 288 = 336$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"336","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangles 2 x (1/2 x 6 x 8) = 48; rectangles 72 + 96 + 120 = 288; total 336.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a35acb7-0c76-411d-9272-419932d534cd', 'NC26.6.SGMR.3', 2, 'choice', 'Total area of the faces in a net', 'A net is made of 2 squares with sides of 3 centimeters and 4 rectangles that are each 3 centimeters by 7 centimeters. What is the total area of the net, in square centimeters?', '["93","84","102","60"]', '102', '2*3*3+4*3*7', 'Each square has an area of $3 \times 3 = 9$, so the two squares total 18. Each rectangle has an area of $3 \times 7 = 21$, so the four rectangles total 84. The net''s area is $18 + 84 = 102$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"102","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 9 = 18; 4 x 21 = 84; total 102.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('490957a6-3eea-43ba-af4f-1a41eb3b133b', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a triangular prism', 'A tent is shaped like a triangular prism. Each triangular end has a base of 6 feet, a height of 4 feet and two slanted sides of 5 feet each. The tent is 9 feet long. How many square feet of fabric cover all five faces, including the floor?', '[]', '168', '2*(6*4/2)+2*(5*9)+6*9', 'Each triangular end has an area of $\frac{1}{2} \times 6 \times 4 = 12$ square feet, so the two ends total 24. Each slanted side is $5 \times 9 = 45$ square feet, so the two total 90. The floor is $6 \times 9 = 54$ square feet. The fabric needed is $24 + 90 + 54 = 168$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 6 x 4) = 24; floor 6x9 = 54; slanted sides 2 x 5x9 = 90; total 168. (3-4-5 checks.)","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
