INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7f0420d-defb-4d76-a4df-601c203f8241', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a triangular prism', 'A triangular prism has triangle ends with a base of 8 inches, a height of 3 inches and two other sides of 5 inches each. The prism is 10 inches long. What is its surface area, in square inches?', '["204","180","192","228"]', '204', '2*(8*3/2)+(8+5+5)*10', 'Each triangle has an area of $\frac{1}{2} \times 8 \times 3 = 12$ square inches, so the two triangles total 24. The three rectangles have a total area of $(8 + 5 + 5) \times 10 = 180$. The surface area is $24 + 180 = 204$ square inches. The value 180 leaves out the triangles, 192 counts only one triangle and 228 forgets the half in the triangle area.', 'checked', '{"lint":[],"solve":{"answer":"204","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 8 x 3) = 24; rectangles (8+5+5) x 10 = 180; total 204. (half-base 4, height 3, side 5: consistent.)","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62bc9fbd-de66-4db5-acc2-adccb432f514', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a triangular prism', 'A box shaped like a triangular prism has right-triangle ends with legs of 5 centimeters and 12 centimeters and a longest side of 13 centimeters. The box is 20 centimeters long. What is the surface area of the box, in square centimeters?', '["600","630","720","660"]', '660', '2*(5*12/2)+(5+12+13)*20', 'Each triangle has an area of $\frac{1}{2} \times 5 \times 12 = 30$ square centimeters, so the two triangles total 60. The three rectangles have a total area of $(5 + 12 + 13) \times 20 = 600$. The surface area is $60 + 600 = 660$ square centimeters. The value 600 leaves out the triangles, 630 counts one triangle, and 720 forgets the half in the triangle area.', 'checked', '{"lint":[],"solve":{"answer":"660","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 5 x 12) = 60; rectangles (5+12+13) x 20 = 600; total 660.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b421f9d-1a0e-41c5-95c4-fcafd230eb93', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a pyramid', 'A square pyramid has a base with sides of 8 centimeters. Each of its four triangular faces has a base of 8 centimeters and a height of 5 centimeters. What is the surface area of the pyramid, in square centimeters?', '["80","224","84","144"]', '144', '8*8+4*(8*5/2)', 'The base has an area of $8 \times 8 = 64$ square centimeters. Each triangle has an area of $\frac{1}{2} \times 8 \times 5 = 20$, so the four triangles total 80. The surface area is $64 + 80 = 144$ square centimeters. The value 80 leaves out the base, 224 forgets the half in the triangle area and 84 counts only one triangle.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 8x8 = 64; triangles 4 x (1/2 x 8 x 5) = 80; total 144.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da9af884-d865-4c45-b059-4a00bebe1b0c', 'NC26.6.SGMR.3', 2, 'numeric', 'Surface area of a pyramid', 'The roof of a gazebo is shaped like a square pyramid with no base. Each of its 4 triangular faces has a base of 10 feet and a height of 7 feet. What is the area of the roof, in square feet?', '[]', '140', '4*(10*7/2)', 'Each triangular face has an area of $\frac{1}{2} \times 10 \times 7 = 35$ square feet. The roof has 4 of them, so its area is $4 \times 35 = 140$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2 x 10 x 7) = 4 x 35 = 140.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ddfb663-92c7-4c52-b0c9-07f15f33e477', 'NC26.6.SGMR.3', 2, 'numeric', 'Volume of a rectangular prism with whole-number edges', 'A moving box is 50 centimeters long, 30 centimeters wide and 40 centimeters tall. What is its volume, in cubic centimeters?', '[]', '60000', '50*30*40', 'Volume is length times width times height: $50 \times 30 \times 40 = 1500 \times 40 = 60{,}000$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 x 30 x 40 = 60,000.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
