INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27cd37de-2423-4f9a-bd3e-995407a99b27', 'NC26.6.SGMR.3', 2, 'choice', 'Volume of a rectangular prism with fractional edges', 'A box is $\frac{1}{2}$ foot long, $\frac{1}{3}$ foot wide and 3 feet tall. What is its volume, in cubic feet?', '["$\\frac{1}{6}$","$\\frac{3}{2}$","$3\\frac{5}{6}$","$\\frac{1}{2}$"]', '$\frac{1}{2}$', NULL, 'Multiply the edges: $\frac{1}{2} \times \frac{1}{3} \times 3 = \frac{1}{6} \times 3 = \frac{1}{2}$ cubic foot. The value $\frac{1}{6}$ leaves out the height, $\frac{3}{2}$ leaves out the width, and $3\frac{5}{6}$ adds the edges.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 1/3 x 3 = 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
