INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b018833-b422-4c69-a798-3a1eb6f9b2ba', 'NC26.6.SGMR.3', 2, 'numeric', 'Volume of a rectangular prism with fractional edges', 'A carton is 1.2 meters long, 0.5 meter wide and 0.5 meter tall. What is its volume, in cubic meters?', '[]', '0.3', '1.2*0.5*0.5', 'Multiply the three edges: $1.2 \times 0.5 = 0.6$, and then $0.6 \times 0.5 = 0.3$ cubic meter.', 'checked', '{"lint":[],"solve":{"answer":"0.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2 x 0.5 x 0.5 = 1.2 x 0.25 = 0.3.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
