INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e186290b-a903-482e-9d38-865a44c00be6', 'NC26.6.SGMR.3', 2, 'numeric', 'Counting unit cubes with fractional edges that fill a prism', 'A rectangular prism is 2 inches long, 1 inch wide and $\frac{3}{4}$ inch tall. It is filled exactly with cubes that have edges of $\frac{1}{4}$ inch. How many cubes fill it?', '[]', '96', '(2*4)*(1*4)*3', 'Each $\frac{1}{4}$-inch cube fits 4 times in one inch. Along the length there are $2 \times 4 = 8$ cubes and along the width there are $1 \times 4 = 4$. The height of $\frac{3}{4}$ inch is 3 cubes. The number of cubes is $8 \times 4 \times 3 = 96$.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Per dimension: 2/(1/4) = 8, 1/(1/4) = 4, (3/4)/(1/4) = 3. 8 x 4 x 3 = 96.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f05ca9ab-89b1-422d-85c8-17c95b2f75d1', 'NC26.6.SGMR.3', 2, 'numeric', 'Counting unit cubes with fractional edges that fill a prism', 'A box is 3 feet long, 2 feet wide and 1 foot tall. How many cubes with edges of $\frac{1}{2}$ foot fit in the box exactly?', '[]', '48', '(3*2)*(2*2)*(1*2)', 'Each foot holds 2 cubes of $\frac{1}{2}$ foot. The box holds $3 \times 2 = 6$ cubes along the length, $2 \times 2 = 4$ across the width and $1 \times 2 = 2$ up the height. That is $6 \times 4 \times 2 = 48$ cubes.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 2 = 48.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9487df3f-93d7-45d9-b759-9af5e26f11e6', 'NC26.6.SGMR.3', 2, 'numeric', 'Finding a missing edge from a volume or surface area', 'A rectangular prism has a volume of 90 cubic inches. It is 6 inches long and 5 inches wide. How tall is it, in inches?', '[]', '3', '90/(6*5)', 'Volume is length times width times height. The base has an area of $6 \times 5 = 30$ square inches, so the height is $90 \div 30 = 3$ inches.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 / (6 x 5) = 3.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3570821a-3aa6-47f5-b64f-f72e0c832cd3', 'NC26.6.SGMR.3', 2, 'choice', 'Finding a missing edge from a volume or surface area', 'The surface area of a cube is 96 square inches. How long is each edge, in inches?', '["4","16","24","48"]', '4', NULL, 'A cube has 6 equal faces, so one face has an area of $96 \div 6 = 16$ square inches. A square with an area of 16 has sides of 4 inches, because $4 \times 4 = 16$. The value 16 is the area of one face, not the edge.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"96 / 6 = 16 per face; edge 4.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9330b5b0-4cdc-41fa-87dc-1fc7633bdaa3', 'NC26.6.SGMR.3', 2, 'choice', 'Choosing between surface area and volume, and their units', 'Which tells how much paint is needed to cover the outside of a cube-shaped box, and in what units?', '["Volume, in cubic units","Surface area, in cubic units","Surface area, in square units","Volume, in square units"]', 'Surface area, in square units', NULL, 'Paint covers the outside faces, so the measure is surface area. Area is measured in square units. Volume is measured in cubic units and tells how much space is inside.', 'checked', '{"lint":[],"solve":{"answer":"Surface area, in square units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Covering the outside = surface area, square units.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1f95c4c-7262-4ea9-8dd4-86ba00bc135e', 'NC26.6.SGMR.3', 2, 'choice', 'Comparing the surface areas or volumes of two solids', 'Prism A is 4 centimeters by 4 centimeters by 1 centimeter. Prism B is 2 centimeters by 4 centimeters by 2 centimeters. Which statement is true?', '["The prisms have the same surface area because their volumes are equal","Prism B has the greater surface area","Prism A has the greater volume","Prism A has the greater surface area"]', 'Prism A has the greater surface area', NULL, 'Both volumes are 16 cubic centimeters. Prism A has a surface area of $2 \times (16 + 4 + 4) = 48$ square centimeters. Prism B has $2 \times (8 + 4 + 8) = 40$ square centimeters. So the volumes are equal, but Prism A has the greater surface area.', 'checked', '{"lint":[],"solve":{"answer":"Prism A has the greater surface area","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: V 16, SA 2(16+4+4) = 48. B: V 16, SA 2(8+4+8) = 40. A has greater SA; volumes equal.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0907239f-9236-4d9d-a316-323d3ee0f445', 'NC26.6.SGMR.3', 2, 'choice', 'Surface area of a rectangular prism', 'A closed box has a square base that measures 4 centimeters on each side. The box is 9 centimeters tall. What is its surface area in square centimeters?', '["144","176","160","104"]', '176', '4*4*2+4*4*9', 'The top and bottom are each $4 \times 4 = 16$, together 32. The four sides are each $4 \times 9 = 36$, together 144. The total is $32 + 144 = 176$ square centimeters. Leaving out the top and bottom gives 144, and counting only one of them gives 160.', 'checked', '{"lint":[],"solve":{"answer":"176","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two square faces: 2 x 16 = 32. Four side faces 4 x 9 = 36 each: 144. Total 176.","run_id":"claude-code","at":"2026-10-18T03:30:03.757Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69c8db82-1a0c-48c7-be83-e01e50ed9ef2', 'NC26.6.SGMR.3', 3, 'numeric', 'Surface area of a triangular prism', 'A triangular prism has two identical right-triangle bases with legs of 3 centimeters and 4 centimeters and a longest side of 5 centimeters. The prism is 10 centimeters long. What is its surface area in square centimeters?', '[]', '132', '2*(1/2*3*4)+(3+4+5)*10', 'The two triangular bases have area $2 \times \left(\frac{1}{2} \times 3 \times 4\right) = 12$. The three rectangular faces are $3 \times 10 = 30$, $4 \times 10 = 40$ and $5 \times 10 = 50$, which total $120$. The surface area is $12 + 120 = 132$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangles: 2 x (1/2 x 3 x 4) = 12. Three rectangles: 3x10 + 4x10 + 5x10 = 120. Total 132.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba7aebf3-45d4-4784-927b-021fb4d47dbb', 'NC26.6.SGMR.3', 3, 'numeric', 'Counting unit cubes with fractional edges that fill a prism', 'A box is 2 inches long, $1\frac{1}{2}$ inches wide and 1 inch tall. It is filled exactly with small cubes whose edges are each $\frac{1}{2}$ inch long. How many small cubes fill the box?', '[]', '24', '(2*2)*(3/2*2)*(1*2)', 'Count the cubes along each edge: $2 \div \frac{1}{2} = 4$ along the length, $1\frac{1}{2} \div \frac{1}{2} = 3$ along the width and $1 \div \frac{1}{2} = 2$ along the height. The number of cubes is $4 \times 3 \times 2 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cubes along each edge: 2 / (1/2) = 4, (3/2) / (1/2) = 3, 1 / (1/2) = 2. Count = 4 x 3 x 2 = 24. Check: volume 3 / (1/8) = 24.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c25007fe-5c7e-436b-981d-f0062128fb21', 'NC26.6.SGMR.3', 3, 'choice', 'Surface area of a square pyramid from its faces', 'A square pyramid has a square base with sides of 6 centimeters. Its four triangular faces each have a base of 6 centimeters and a height of 5 centimeters. What is the surface area of the pyramid in square centimeters?', '["$60$","$66$","$96$","$156$"]', '$96$', '6*6+4*(1/2*6*5)', 'The base is $6 \times 6 = 36$. Each triangle is $\frac{1}{2} \times 6 \times 5 = 15$, so the four triangles are $60$. The total is $36 + 60 = 96$ square centimeters. (60 leaves out the base, 66 uses only one triangle, and 156 forgets the one half.)', 'checked', '{"lint":[],"solve":{"answer":"$96$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 6 x 6 = 36. Each triangle 1/2 x 6 x 5 = 15; four = 60. Total 96.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b1e0e08-91f1-4830-8e07-f0ca98da5855', 'NC26.6.SGMR.3', 3, 'choice', 'Naming the solid a net folds into', 'The net of a prism has 8 faces in all. What shape are the two bases of the prism?', '["Hexagon","Square","Pentagon","Octagon"]', 'Hexagon', NULL, 'A prism has 2 bases, and every other face is a rectangle joining one side of a base. So the number of rectangles equals the number of sides of a base. $8 - 2 = 6$ rectangles, so each base has 6 sides and is a hexagon.', 'checked', '{"lint":[],"solve":{"answer":"Hexagon","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prism faces = 2 bases + n rectangles. 2 + n = 8 so n = 6: hexagon.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a068239-4570-410f-a132-da3e06ad10a9', 'NC26.6.SGMR.3', 3, 'numeric', 'Counting faces, edges and vertices of prisms and pyramids', 'A prism has 10 faces in all. How many sides does each of its two bases have?', '[]', '8', '10-2', 'A prism has 2 bases, and every other face is a rectangle joining one side of a base. The other $10 - 2 = 8$ faces are rectangles, so each base has 8 sides.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 faces - 2 bases = 8 rectangles, so each base has 8 sides.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab94c9f-9f3c-4415-b60c-111f6751b461', 'NC26.6.SGMR.3', 3, 'numeric', 'Surface area of a cube', 'A cube-shaped tank has no lid. Each edge is 3 meters long. How many square meters of glass are needed for its bottom and four sides?', '[]', '45', '5*3^2', 'Each face is $3 \times 3 = 9$ square meters. The bottom and four sides make 5 faces, so the glass needed is $5 \times 9 = 45$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom + 4 sides = 5 faces x 9 = 45.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
