INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f8d1464-244e-43ee-ac8b-c0bfd9cc19be', 'NC26.6.SGMR.3', 3, 'numeric', 'Volume of a rectangular prism with fractional edges', 'An aquarium is shaped like a rectangular prism. It is $2\frac{1}{4}$ feet long, $1\frac{1}{3}$ feet wide and $1\frac{1}{2}$ feet tall. What is its volume, in cubic feet?', '[]', '4 1/2', '9/4*4/3*3/2', 'Write each edge as a fraction: $\frac{9}{4}$, $\frac{4}{3}$ and $\frac{3}{2}$. The volume is $\frac{9}{4} \times \frac{4}{3} \times \frac{3}{2} = 3 \times \frac{3}{2} = \frac{9}{2} = 4\frac{1}{2}$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"4 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/4 x 4/3 x 3/2 = 3 x 3/2 = 9/2 = 4 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.092Z"}}', 'ai', NULL, NULL)
