INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('235ab340-3112-4e3c-a862-2572eece54a2', 'NC26.6.RD.1', 1, 'choice', 'Describing likelihood with probability words', 'A fair coin is tossed once. Which statement is true?', '["Heads and tails are equally likely","Heads is certain","Heads is impossible","Heads is unlikely"]', 'Heads and tails are equally likely', NULL, 'A fair coin has two sides with the same chance of landing face up. So heads and tails are equally likely. Heads is neither certain nor impossible.', 'checked', '{"lint":[],"solve":{"answer":"Heads and tails are equally likely","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fair coin: P(H) = P(T) = 1/2, equally likely.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
