INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a350e802-6c90-45ef-ab9e-4f04bba55c70', 'NC26.6.RD.1', 1, 'choice', 'Describing likelihood with probability words', 'A fair six-sided die has faces numbered 1 to 6. It is rolled once. Which event is impossible?', '["Rolling a 1","Rolling an odd number","Rolling a 7","Rolling a number less than 7"]', 'Rolling a 7', NULL, 'No face of the die shows a 7, so rolling a 7 can never happen. The other three events can happen. Rolling a number less than 7 is actually certain.', 'checked', '{"lint":[],"solve":{"answer":"Rolling a 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No face shows 7: P = 0, impossible. Less than 7 is certain; odd 1/2; a 1 is 1/6.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
