INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('137eff06-a3f6-4623-97bc-b268a7b4006c', 'NC26.6.RD.1', 1, 'choice', 'Describing likelihood with probability words', 'A jar has only green and yellow candies. One candy is picked without looking. Which event is certain?', '["The candy is green","The candy is green or yellow","The candy is yellow","The candy is red"]', 'The candy is green or yellow', NULL, 'Every candy in the jar is green or yellow, so the picked candy will always be one of those two colors. Picking a green candy or a yellow candy alone might not happen, and a red candy is impossible.', 'checked', '{"lint":[],"solve":{"answer":"The candy is green or yellow","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only green and yellow, so ''green or yellow'' has P = 1.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
