INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c804ffd2-9213-47f5-80c8-8060d2af87a0', 'NC26.6.RD.1', 1, 'numeric', 'Theoretical probability from equally likely outcomes', 'A fruit bowl has 3 apples, 2 bananas and 5 oranges. One piece of fruit is chosen at random. What is the probability that it is a banana? Give your answer as a fraction.', '[]', '1/5', '2/10', 'There are $3 + 2 + 5 = 10$ pieces of fruit, and 2 are bananas. The probability is $\frac{2}{10} = \frac{1}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 bananas of 10 fruits: 2/10 = 1/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
