INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a715db24-cd30-472f-81bd-13b79c9b7c6f', 'NC26.6.RD.1', 1, 'choice', 'Theoretical probability from equally likely outcomes', 'Ten cards are labeled with the letters A through J, one letter on each card. One card is picked at random. What is the probability that it shows a vowel? (The vowels are A, E, I, O and U.)', '["$\\frac{3}{7}$","$\\frac{3}{10}$","$\\frac{7}{10}$","$\\frac{1}{10}$"]', '$\frac{3}{10}$', NULL, 'Among the letters A through J, the vowels are A, E and I, which is 3 cards out of 10. The probability is $\frac{3}{10}$. The value $\frac{3}{7}$ compares vowels with consonants, and $\frac{7}{10}$ is the probability of a consonant.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A-J: vowels A, E, I = 3 of 10: 3/10.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b21e3edd-8224-48fd-b2d8-4e43d6ec0b79', 'NC26.6.RD.1', 1, 'numeric', 'Theoretical probability from equally likely outcomes', 'A class has 11 girls and 14 boys. One student is chosen at random. What is the probability that the student is a girl? Give your answer as a fraction.', '[]', '11/25', '11/25', 'There are $11 + 14 = 25$ students, and 11 are girls. The probability is $\frac{11}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"11/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11 girls of 25: 11/25.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
