INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7ce8cee-d2b2-41bf-ba1e-4828788359a8', 'NC26.6.RD.1', 1, 'numeric', 'Writing a probability as a fraction, decimal or percent', 'The probability of an event is $\frac{1}{4}$. Write this probability as a decimal.', '[]', '0.25', '1/4', '$\frac{1}{4} = 1 \div 4 = 0.25$.', 'checked', '{"lint":[],"solve":{"answer":"0.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 = 0.25.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
