INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74886b8f-2b8d-49b6-b6c5-ef5bd05bb378', 'NC26.6.RD.1', 1, 'numeric', 'Experimental probability from results', 'Jada tossed a coin 20 times. It landed heads up 12 times. What is the experimental probability of heads? Give your answer as a fraction.', '[]', '3/5', '12/20', 'The experimental probability is the number of heads divided by the number of tosses: $\frac{12}{20} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/20 = 3/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
