INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a810092a-a5d3-4faa-aa05-4fe522a1e0d6', 'NC26.6.RD.1', 2, 'choice', 'Experimental probability from results', 'Ming draws a marble from a bag, records its color and puts it back. After 50 draws, 30 were red and the rest were blue. What is the experimental probability of drawing a blue marble?', '["$\\frac{3}{5}$","$\\frac{2}{3}$","$\\frac{2}{5}$","$\\frac{1}{2}$"]', '$\frac{2}{5}$', NULL, 'Blue was drawn $50 - 30 = 20$ times out of 50, so the experimental probability is $\frac{20}{50} = \frac{2}{5}$. The value $\frac{3}{5}$ is for red, and $\frac{2}{3}$ compares blue with red.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue = 50 - 30 = 20. 20/50 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
