INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b22deaf6-4ec0-4b2d-b22b-6daf05c16042', 'NC26.6.RD.1', 2, 'numeric', 'Experimental probability from results', 'A die was rolled 100 times. The results were: 1 came up 14 times, 2 came up 18 times, 3 came up 15 times, 4 came up 20 times, 5 came up 16 times and 6 came up 17 times. What is the experimental probability of rolling an even number? Give your answer as a decimal.', '[]', '0.55', '(18+20+17)/100', 'The even numbers are 2, 4 and 6, which came up $18 + 20 + 17 = 55$ times out of 100 rolls. The experimental probability is $\frac{55}{100} = 0.55$.', 'checked', '{"lint":[],"solve":{"answer":"0.55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even: 2 (18) + 4 (20) + 6 (17) = 55 of 100 = 0.55. (Counts total 100: 14+18+15+20+16+17.)","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
