INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37dedb8e-1292-4ba8-bf65-7e261ade8ef4', 'NC26.6.RD.1', 2, 'numeric', 'Predicting how many times an event will happen', 'A factory finds that the probability a light bulb is defective is 0.04. In a box of 250 bulbs, about how many bulbs would you expect to be defective?', '[]', '10', '0.04*250', 'Multiply the probability by the number of bulbs: $0.04 \times 250 = 10$ bulbs.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.04 x 250 = 10.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
