INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('552a1568-34de-4c1b-b7f0-abc673dfd926', 'NC26.6.RD.1', 2, 'numeric', 'Comparing experimental and theoretical probability', 'A fair coin is tossed 50 times and lands heads up 29 times. What is the experimental probability of heads minus the theoretical probability of heads? Give your answer as a decimal.', '[]', '0.08', '29/50-1/2', 'The experimental probability is $\frac{29}{50} = 0.58$. The theoretical probability is $\frac{1}{2} = 0.5$. The difference is $0.58 - 0.5 = 0.08$.', 'checked', '{"lint":[],"solve":{"answer":"0.08","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"29/50 = 0.58; 0.58 - 0.5 = 0.08.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
