INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3d9b73d-869d-4880-b594-c48bcbd0c26e', 'NC26.6.RD.1', 2, 'choice', 'Comparing experimental and theoretical probability', 'A spinner has 4 equal sections: red, blue, green and yellow. It was spun 40 times. It landed on red 8 times, blue 14 times, green 10 times and yellow 8 times. For which color is the experimental probability greater than the theoretical probability?', '["Blue","Red","Green","Yellow"]', 'Blue', NULL, 'The theoretical probability of each color is $\frac{1}{4}$, which is 10 spins out of 40. Blue came up 14 times, which is more than 10. Green came up exactly 10 times, so it is equal, and red and yellow came up 8 times, which is fewer.', 'checked', '{"lint":[],"solve":{"answer":"Blue","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Theoretical 1/4 = 10 of 40. Red 8, blue 14, green 10, yellow 8. Only blue is above.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fae2dc9d-2ba1-4ee3-ab68-51f4f6fb47ad', 'NC26.6.RD.1', 2, 'choice', 'What a probability does and does not tell us', 'A fair coin has landed on heads 4 times in a row. What is true about the next toss?', '["The chance of heads is still $\\frac{1}{2}$, because every toss has the same chances","Tails is more likely, because it is due","Heads is more likely, because it is on a streak","Heads is impossible, because the streak has to end"]', 'The chance of heads is still $\frac{1}{2}$, because every toss has the same chances', NULL, 'A fair coin does not remember earlier tosses. Each toss has the same chance of heads, $\frac{1}{2}$, no matter what came before.', 'checked', '{"lint":[],"solve":{"answer":"The chance of heads is still $\\frac{1}{2}$, because every toss has the same chances","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tosses are independent; P(H) stays 1/2.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebf9cfc1-c696-4a23-9f98-cdc3069bce23', 'NC26.6.RD.1', 2, 'choice', 'What a probability does and does not tell us', 'The weather report says the probability of rain on Tuesday is 0.7. Which statement is the best way to say what this means?', '["It will rain for 70% of the day","It will definitely rain on Tuesday","Rain is likely on Tuesday, but it might not happen","Rain is unlikely on Tuesday"]', 'Rain is likely on Tuesday, but it might not happen', NULL, 'A probability of 0.7 is greater than $\frac{1}{2}$ but less than 1, so rain is likely but not certain. The probability does not say how long it will rain.', 'checked', '{"lint":[],"solve":{"answer":"Rain is likely on Tuesday, but it might not happen","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.7 is likely but not certain.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc3f4d75-66d8-409f-8c92-b32856c4edb7', 'NC26.6.RD.1', 2, 'numeric', 'Finding a number of outcomes from a probability', 'The probability of picking a red marble from a bag at random is $\frac{2}{5}$. The bag holds 30 marbles. How many marbles are red?', '[]', '12', '2/5*30', 'Red marbles are $\frac{2}{5}$ of the 30 marbles: $\frac{2}{5} \times 30 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/5 x 30 = 12.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
