INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54553a8e-2619-4199-84c5-b46e642252b8', 'NC26.6.RD.1', 2, 'choice', 'Finding a number of outcomes from a probability', 'A box holds 24 raffle tickets. The probability of picking a winning ticket at random is $\frac{1}{6}$. How many of the tickets are NOT winning tickets?', '["20","4","6","18"]', '20', '24-24/6', 'Winning tickets are $\frac{1}{6}$ of 24, which is 4 tickets. The tickets that are not winners number $24 - 4 = 20$. The value 4 is the number of winners.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Winning: 1/6 x 24 = 4; not winning: 20.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
