INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80c4ed99-6552-49d8-9c80-17ed60b3e232', 'NC26.6.RD.1', 2, 'choice', 'How adding or removing items changes a probability', 'A bag has 3 red marbles and 5 blue marbles. One more red marble is added. What happens to the probability of picking a red marble at random?', '["It decreases","It stays the same","It becomes $\\frac{1}{2}$","It increases"]', 'It increases', NULL, 'Before, the probability of red is $\frac{3}{8} = 0.375$. After adding a red marble it is $\frac{4}{9}$, about 0.44. The probability goes up, but it is still less than $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"It increases","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 = 0.375 becomes 4/9 ~ 0.444: increases (not 1/2).","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
