INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1306ec42-066a-4ab9-a33d-1cef0f4926c0', 'NC26.6.RD.1', 2, 'choice', 'Comparing the probabilities of two events', 'Four spinners each have equal sections. Which spinner has the greatest probability of landing on blue?', '["1 blue section out of 4","3 blue sections out of 10","3 blue sections out of 8","2 blue sections out of 5"]', '2 blue sections out of 5', NULL, 'Write each as a decimal: $\frac{1}{4} = 0.25$, $\frac{3}{10} = 0.3$, $\frac{2}{5} = 0.4$ and $\frac{3}{8} = 0.375$. The greatest is 0.4, which is 2 blue sections out of 5.', 'checked', '{"lint":[],"solve":{"answer":"2 blue sections out of 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3, 0.4, 0.25, 0.375. Greatest: 2 out of 5.","run_id":"claude-code","at":"2026-10-17T20:31:37.131Z"}}', 'ai', NULL, NULL)
