INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ea40534-701b-46e7-b1e8-d784fc9ca088', 'NC26.6.RD.2', 1, 'numeric', 'Organizing data in a frequency table', 'A tally chart shows how many books each student borrowed this week: 0 books, 3 students; 1 book, 7 students; 2 books, 6 students; 3 books, 4 students. How many students are in the survey in all?', '[]', '20', '3+7+6+4', 'Add the number of students in every row: $3 + 7 + 6 + 4 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 7 + 6 + 4 = 20 students.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
