INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8f639cd-9ccc-49bb-9810-e0ddeab4e6da', 'NC26.6.RD.2', 1, 'numeric', 'Organizing survey results as fractions and percents', 'In a survey of 20 students, 5 chose swimming as their favorite activity. What fraction of the students chose swimming? Write your answer as a fraction.', '[]', '1/4', '5/20', '5 of the 20 students chose swimming. $\frac{5}{20} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/20 = 1/4.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a74eb86-d5e5-45d1-9178-e52b6397bb03', 'NC26.6.RD.2', 1, 'numeric', 'Organizing survey results as fractions and percents', 'Out of 50 students surveyed, 30 ride the bus. What percent of the students ride the bus?', '[]', '60', '30/50*100', '$\frac{30}{50} = \frac{60}{100}$, which is 60%.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/50 = 60/100 = 60%.","run_id":"claude-code","at":"2026-10-17T20:06:49.927Z"}}', 'ai', NULL, NULL)
