INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45e1a8d9-db2a-4742-b667-f4c3d4d935c3', 'NC26.6.RD.3', 1, 'choice', 'Constructing a dot plot from a list of data', 'Raj measured the heights of his plants. The heights run from 12 cm to 20 cm, and each one is a whole number of centimeters. He will make a dot plot. Which number line is the best choice?', '["Marks from 0 to 100, with one mark for every 20 centimeters","Marks from 12 to 20, with one mark for every 4 centimeters","Marks from 12 to 20, with one mark for each centimeter","Marks from 0 to 12, with one mark for each centimeter"]', 'Marks from 12 to 20, with one mark for each centimeter', NULL, 'The number line must cover every height from 12 to 20 and have a mark for each whole centimeter, so that every plant gets its own place. The other lines are too coarse to show each height, or they do not reach the tallest plants.', 'checked', '{"lint":[],"solve":{"answer":"Marks from 12 to 20, with one mark for each centimeter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole-cm data from 12 to 20 need marks covering 12-20 at every centimeter. Every 4 cm cannot place 13, 14, etc.; 0-12 misses data; 0-100 by 20s is too coarse.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ff4d446-55a4-4bdb-b15e-867e67501bd6', 'NC26.6.RD.3', 1, 'numeric', 'Reading bar heights and totals in a histogram', 'A histogram shows how many minutes 30 students read last night. The bars are: 0 to 9 minutes, 4 students; 10 to 19 minutes, 11 students; 20 to 29 minutes, 9 students; 30 to 39 minutes, 6 students. How many students read for 20 to 29 minutes?', '[]', '9', '9', 'The height of the bar for 20 to 29 minutes is 9, so 9 students read for 20 to 29 minutes.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 20-29 bar holds 9 students. Total 4+11+9+6 = 30 checks.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33cc7f56-d75c-4e1f-a8f0-ec7c9e74b37d', 'NC26.6.RD.3', 1, 'choice', 'Reading bar heights and totals in a histogram', 'In a histogram, what does the height of a bar show?', '["How many values are in that bar''s interval","The most common value in the interval","How wide the interval is","The total of all the values in the interval"]', 'How many values are in that bar''s interval', NULL, 'Each bar covers an interval of values, and its height counts how many data values fall in that interval. It does not show the most common value, the width of the interval, or the total of the values.', 'checked', '{"lint":[],"solve":{"answer":"How many values are in that bar''s interval","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A histogram bar height is the frequency: how many values fall in that interval.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71cdd0bd-e053-47c6-8965-5d4bf3ab35ec', 'NC26.6.RD.3', 1, 'numeric', 'Reading bar heights and totals in a histogram', 'A histogram of the ages of people at a library has these bars: 0 to 4 years, 7 people; 5 to 9 years, 12 people; 10 to 14 years, 9 people; 15 to 19 years, 4 people. How many people are in the data set?', '[]', '32', '7+12+9+4', 'Every person is counted in exactly one bar, so add the bars: $7 + 12 + 9 + 4 = 32$ people.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7+12+9+4 = 32.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
