INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6acc231e-10a6-49d9-a7bf-1caa5bbaecf3', 'NC26.6.RD.3', 1, 'choice', 'Placing values in histogram intervals', 'A histogram of the minutes students spend on homework uses the intervals 0 to 9, 10 to 19, 20 to 29 and 30 to 39. In which interval is a time of 20 minutes counted?', '["20 to 29","10 to 19","0 to 9","30 to 39"]', '20 to 29', NULL, 'The interval 20 to 29 starts at 20, so a time of exactly 20 minutes goes in that bar. The interval 10 to 19 stops at 19.', 'checked', '{"lint":[],"solve":{"answer":"20 to 29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 lies in 20 to 29.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
