INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a212881c-a782-4416-b6b0-79f7f06bf84a', 'NC26.6.RD.3', 1, 'numeric', 'Placing values in histogram intervals', 'Dan''s data are 3, 7, 12, 8, 15, 4, 9, 11. He makes a histogram with the intervals 0 to 4, 5 to 9, 10 to 14 and 15 to 19. How many values are in the interval 5 to 9?', '[]', '3', '3', 'The values from 5 to 9 are 7, 8 and 9. That is 3 values.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values 5-9: 7, 8, 9 -> 3. (0-4: 3,4; 10-14: 12,11; 15-19: 15.)","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
