INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bae605f-0451-430a-bd9d-0d5105dd49d8', 'NC26.6.RD.3', 1, 'numeric', 'Finding the median from a display', 'A dot plot of the number of pets owned by 9 students has these stacks of dots: 1 pet, 3 dots; 2 pets, 5 dots; 3 pets, 1 dot. What is the median number of pets?', '[]', '2', '2', 'List the 9 values in order: 1, 1, 1, 2, 2, 2, 2, 2, 3. The median is the 5th value, which is 2 pets.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 values: 1,1,1,2,2,2,2,2,3. 5th value = 2.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
