INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f4adcc2-d840-4e4c-9e14-8a0b549a1fa5', 'NC26.6.RD.3', 1, 'choice', 'Finding the five key values of a data set', 'Which list gives the five key values of a box plot in order from least to greatest?', '["Minimum, median, first quartile, third quartile, maximum","Minimum, first quartile, third quartile, median, maximum","Minimum, first quartile, median, third quartile, maximum","First quartile, minimum, median, maximum, third quartile"]', 'Minimum, first quartile, median, third quartile, maximum', NULL, 'The minimum is the least value and the maximum is the greatest. In between come the first quartile, the median and the third quartile, in that order, because the median is in the middle of the data.', 'checked', '{"lint":[],"solve":{"answer":"Minimum, first quartile, median, third quartile, maximum","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Five-number summary in order: minimum, Q1, median, Q3, maximum.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
