INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53c30566-9993-45c7-a56e-e6a0ca0777c6', 'NC26.6.RD.3', 1, 'numeric', 'Finding the five key values of a data set', 'The 8 ordered values of a data set are 2, 4, 6, 8, 10, 12, 14, 16. The median is 9. What is the median of the lower half of the data, which is the first quartile?', '[]', '5', '(4+6)/2', 'The lower half is the first 4 values: 2, 4, 6, 8. Its median is halfway between 4 and 6, which is $(4 + 6) \div 2 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower half 2, 4, 6, 8: median (4+6)/2 = 5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
