INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('005ee6d7-1483-40fc-9894-b73714af9ec6', 'NC26.6.RD.3', 2, 'choice', 'Placing values in histogram intervals', 'A histogram of lengths in centimeters uses the intervals 0 up to 5, 5 up to 10 and 10 up to 15. Each interval includes its left end but not its right end. A length of exactly 10 cm is counted in which bar?', '["5 up to 10","0 up to 5","10 up to 15","It is not counted in any bar"]', '10 up to 15', NULL, 'The interval 5 up to 10 does not include 10, because it leaves out its right end. The interval 10 up to 15 includes its left end, 10, so a length of exactly 10 cm goes in that bar.', 'checked', '{"lint":[],"solve":{"answer":"10 up to 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intervals include the left end: 10 is in [10, 15), not in [5, 10).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52d8ca0b-5d39-4128-a6d1-c90525567532', 'NC26.6.RD.3', 2, 'numeric', 'Placing values in histogram intervals', 'A teacher''s quiz scores run from 21 to 58. She makes a histogram with equal intervals of width 10 that start at 20: 20 to 29, 30 to 39, and so on. How many bars does the histogram need?', '[]', '4', '4', 'The scores need the intervals 20 to 29, 30 to 39, 40 to 49 and 50 to 59. The lowest score, 21, is in the first and the highest, 58, is in the last, so 4 bars are needed.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bars 20-29, 30-39, 40-49, 50-59 cover 21 to 58: 4 bars.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8af43b9-27a8-46f7-8410-05e830bb9e32', 'NC26.6.RD.3', 2, 'choice', 'Describing the shape and spread of a histogram', 'A histogram has five bars. Their heights, from left to right, are 2, 4, 6, 9 and 12, and the smallest values are on the left. Which statement describes it?', '["Skewed to the right, because the bars get taller toward the right","Skewed to the left: most values are large, with a tail toward smaller values","Symmetric, because the bars are in order","It has a gap in the middle"]', 'Skewed to the left: most values are large, with a tail toward smaller values', NULL, 'The tallest bar is on the far right, so most of the values are large, and the bars thin out toward the left. The tail points to the left, toward smaller values, so it is skewed to the left. Skew is named for the direction of the tail, not the tall bars.', 'checked', '{"lint":[],"solve":{"answer":"Skewed to the left: most values are large, with a tail toward smaller values","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights rise to the right (peak at large values), so the tail is toward smaller values: skewed left. Option 3 is the common misconception; no gap; not symmetric.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79b046bc-7f00-4d89-b5fb-0ae710858293', 'NC26.6.RD.3', 2, 'choice', 'Describing the shape and spread of a histogram', 'Which set of bar heights, from left to right, makes a histogram that is skewed to the right?', '["2, 5, 9, 5, 2","10, 7, 4, 2, 1","1, 2, 4, 7, 10","6, 6, 6, 6, 6"]', '10, 7, 4, 2, 1', NULL, 'A histogram skewed to the right has its tall bars on the left and a tail toward the right. Heights 10, 7, 4, 2, 1 fall off to the right. The set 2, 5, 9, 5, 2 is symmetric, 1, 2, 4, 7, 10 is skewed to the left, and 6, 6, 6, 6, 6 is flat.', 'checked', '{"lint":[],"solve":{"answer":"10, 7, 4, 2, 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10,7,4,2,1: peak on the left, tail to the right = skewed right. 1,2,4,7,10 is skewed left; 2,5,9,5,2 symmetric; 6s flat.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afb8113d-7297-42a1-9dd2-bcd00d406373', 'NC26.6.RD.3', 2, 'choice', 'Describing the shape and spread of a histogram', 'A histogram of 24 values has these bars: 0 to 9, 6 values; 10 to 19, 9 values; 20 to 29, 0 values; 30 to 39, 0 values; 40 to 49, 9 values. Which statement describes the data?', '["There is one cluster and no gaps","All of the values are between 20 and 39","There are two clusters, separated by a gap from 20 to 39","The 9 values in the bar for 40 to 49 are an outlier"]', 'There are two clusters, separated by a gap from 20 to 39', NULL, 'Most of the values are in two groups: 0 to 19 and 40 to 49. The bars for 20 to 29 and 30 to 39 are empty, so there is a gap from 20 to 39. Nine values is far too many to be a single outlier.', 'checked', '{"lint":[],"solve":{"answer":"There are two clusters, separated by a gap from 20 to 39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6+9+0+0+9 = 24. Values in 0-19 and 40-49 with empty bars 20-39: two clusters with a gap from 20 to 39. Nine values are a cluster, not an outlier.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd7210e4-6d31-4a1a-b6ab-1d1314696433', 'NC26.6.RD.3', 2, 'numeric', 'Finding the median from a display', 'A dot plot shows the minutes that 10 students spent on a puzzle. The stacks of dots are: 4 minutes, 2 dots; 5 minutes, 3 dots; 6 minutes, 3 dots; 7 minutes, 2 dots. What is the median number of minutes?', '[]', '5.5', '(5+6)/2', 'List the 10 values in order: 4, 4, 5, 5, 5, 6, 6, 6, 7, 7. With 10 values, the median is halfway between the 5th and 6th values, 5 and 6. The median is $(5 + 6) \div 2 = 5.5$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"5.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 values: 4,4,5,5,5,6,6,6,7,7. 5th = 5, 6th = 6, median (5+6)/2 = 5.5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0947c324-8ff2-4bf4-8758-34b8846cce88', 'NC26.6.RD.3', 2, 'numeric', 'Finding the median from a display', 'A histogram shows 41 values. When the values are listed in order from least to greatest, the median is the value in which position? Count the smallest value as position 1.', '[]', '21', '(41+1)/2', 'With an odd number of values, the median is the middle one. There are 20 values below it and 20 above it, so it is in position $20 + 1 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"41 values: (41+1)/2 = 21st position, 20 on each side.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('945e1206-fd84-4092-848b-532970762327', 'NC26.6.RD.3', 2, 'numeric', 'Finding the median from a display', 'A box plot is made from 60 different times, in minutes, and its median is 52. How many of the times are less than 52 minutes?', '[]', '30', '60/2', 'The median splits the ordered data in half. Half of the 60 times are below it, and the times are all different, so $60 \div 2 = 30$ times are less than 52 minutes.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 distinct values: median is the mean of the 30th and 31st, which differ, so 52 lies strictly between them. 30 values are below 52.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b60e652-edbc-4645-a922-fb5f9421211e', 'NC26.6.RD.3', 2, 'numeric', 'Finding the five key values of a data set', 'The 12 ordered values of a data set are 3, 5, 6, 8, 9, 11, 12, 14, 15, 17, 18, 21. What is the third quartile?', '[]', '16', '(15+17)/2', 'The upper half is the last 6 values: 12, 14, 15, 17, 18, 21. Its median is halfway between the 3rd and 4th of these, 15 and 17, so the third quartile is $(15 + 17) \div 2 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Upper half (values 7-12): 12, 14, 15, 17, 18, 21. Median (15+17)/2 = 16.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d2bb433-ec5b-4521-b9e5-52191e844e7e', 'NC26.6.RD.3', 2, 'choice', 'Finding the five key values of a data set', 'A park ranger counts the birds seen on 10 days: 28, 15, 22, 35, 18, 40, 25, 31, 20, 27. Which list gives the minimum, first quartile, median, third quartile and maximum, in that order?', '["15, 20, 26, 31, 40","15, 20, 25, 31, 40","15, 22, 26, 35, 40","15, 18, 26, 35, 40"]', '15, 20, 26, 31, 40', NULL, 'Order the data: 15, 18, 20, 22, 25, 27, 28, 31, 35, 40. The median is halfway between 25 and 27, which is 26. The lower half 15, 18, 20, 22, 25 has median 20, and the upper half 27, 28, 31, 35, 40 has median 31. With the minimum 15 and the maximum 40, the list is 15, 20, 26, 31, 40.', 'checked', '{"lint":[],"solve":{"answer":"15, 20, 26, 31, 40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered: 15,18,20,22,25,27,28,31,35,40. Median (25+27)/2 = 26. Lower half 15..25 -> Q1 = 20; upper half 27..40 -> Q3 = 31. 15, 20, 26, 31, 40.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbe6c355-a54b-41d5-8544-bd0f000961e9', 'NC26.6.RD.3', 2, 'numeric', 'Finding the five key values of a data set', 'Eight students scored 17, 9, 23, 12, 30, 15, 26, 20 on a quiz. What is the interquartile range (IQR) of the scores?', '[]', '11', '(23+26)/2-(12+15)/2', 'Order the scores: 9, 12, 15, 17, 20, 23, 26, 30. The lower half is 9, 12, 15, 17, with median $(12 + 15) \div 2 = 13.5$. The upper half is 20, 23, 26, 30, with median $(23 + 26) \div 2 = 24.5$. The IQR is $24.5 - 13.5 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered 9,12,15,17,20,23,26,30. Q1 = (12+15)/2 = 13.5, Q3 = (23+26)/2 = 24.5. IQR = 11.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18fa683f-2823-417e-9a73-59c47bb00e2f', 'NC26.6.RD.3', 2, 'numeric', 'Reading range and IQR from a box plot', 'A box plot has a minimum of 5, a first quartile of 18, a median of 25, a third quartile of 29 and a maximum of 47. How much greater is the range than the interquartile range?', '[]', '31', '(47-5)-(29-18)', 'The range is $47 - 5 = 42$. The IQR is $29 - 18 = 11$. The range is $42 - 11 = 31$ greater than the IQR.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range 47-5 = 42; IQR 29-18 = 11; 42-11 = 31.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce5b26ae-7975-4397-8b55-71b4b777bb32', 'NC26.6.RD.3', 2, 'choice', 'Reading range and IQR from a box plot', 'A box plot of the number of visitors to a museum each day has a minimum of 30, a first quartile of 45, a median of 50, a third quartile of 70 and a maximum of 72. Which statement is true?', '["The interquartile range is 42","The range is 25","The median is 70","The interquartile range is 25"]', 'The interquartile range is 25', NULL, 'The IQR is $70 - 45 = 25$, so the statement that the IQR is 25 is true. The range is $72 - 30 = 42$, not 25, the IQR is not 42, and the median is 50, not 70.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range is 25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = 70-45 = 25; range = 72-30 = 42; median 50. Only \"IQR is 25\" is true.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8085ff67-8c15-4737-8562-10e68f5c46d7', 'NC26.6.RD.3', 2, 'numeric', 'Share of the data in a part of a box plot', 'A box plot is made from the scores of 80 students. The four parts of a box plot are minimum to first quartile, first quartile to median, median to third quartile, and third quartile to maximum. Each part holds one quarter of the scores. How many scores are between the median and the third quartile?', '[]', '20', '80/4', 'One quarter of the 80 scores are between the median and the third quartile: $80 \div 4 = 20$ scores.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One quarter of 80 = 20.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d62943e7-4b30-4f4d-b16f-5c16216ebf36', 'NC26.6.RD.3', 2, 'numeric', 'Share of the data in a part of a box plot', 'A data set has 36 different values, and its first quartile is 40. How many of the values are less than 40?', '[]', '9', '36/4', 'One quarter of the values are below the first quartile: $36 \div 4 = 9$ values.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 distinct values; lower half is 18 values; Q1 is the mean of the 9th and 10th, which differ, so 40 lies strictly between them: 9 values below 40 (one quarter of 36).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55fe8884-3cb0-4848-bec8-cd0a9f729c16', 'NC26.6.RD.3', 2, 'choice', 'Comparing the center and spread of two displays', 'Team A''s race times have a median of 12 minutes and a range of 8 minutes. Team B''s race times have a median of 15 minutes and a range of 5 minutes. Which statement is true?', '["Team B''s typical time is greater, and its times are more spread out","Team A''s typical time is greater, and its times are less spread out","The two teams'' times are equally spread out","Team B''s typical time is greater, but its times are less spread out"]', 'Team B''s typical time is greater, but its times are less spread out', NULL, 'The median shows the center: 15 is greater than 12, so Team B''s typical time is greater. The range shows the spread: 5 is less than 8, so Team B''s times are less spread out.', 'checked', '{"lint":[],"solve":{"answer":"Team B''s typical time is greater, but its times are less spread out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B median 15 > A median 12 (typical time greater); B range 5 < A range 8 (less spread out).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3021fcb1-849a-4219-9fba-3ee6ca08d292', 'NC26.6.RD.3', 2, 'numeric', 'Comparing the center and spread of two displays', 'Set X is 12, 15, 18, 21, 24. Set Y is 10, 17, 18, 19, 26. Both sets have a median of 18. How much greater is the range of Set Y than the range of Set X?', '[]', '4', '(26-10)-(24-12)', 'The range of Set X is $24 - 12 = 12$. The range of Set Y is $26 - 10 = 16$. Set Y''s range is $16 - 12 = 4$ greater.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range X = 24-12 = 12; range Y = 26-10 = 16; 16-12 = 4.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71737caf-7d17-48ec-8bf9-6154650540e8', 'NC26.6.RD.3', 2, 'numeric', 'Reading displays with unusual scales or layouts', 'A box plot is drawn standing up, so that larger values are higher on the page. The bottom whisker ends at 14, the bottom of the box is at 22, the line in the box is at 30, the top of the box is at 41 and the top whisker ends at 58. What is the interquartile range?', '[]', '19', '41-22', 'The box runs from the first quartile, 22, to the third quartile, 41. The IQR is $41 - 22 = 19$. Turning the box plot to stand up does not change how it is read.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Box from Q1 = 22 to Q3 = 41: IQR = 19.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fe3e4c2-65c1-4e59-a83f-8f3fedea736f', 'NC26.6.RD.3', 2, 'numeric', 'Reading displays with unusual scales or layouts', 'A dot plot has a number line labeled 0, 10, 20, 30 and 40, with one tick midway between each pair of labels. The stacks of dots are above the ticks for 15 (3 dots), 20 (2 dots) and 35 (1 dot). What is the range of the data?', '[]', '20', '35-15', 'The tick midway between 10 and 20 is 15, and the tick midway between 30 and 40 is 35. The smallest value is 15 and the largest is 35, so the range is $35 - 15 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Midway ticks are 5, 15, 25, 35. Data from 15 to 35: range 20.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03800d7f-71c6-4494-96cd-1e5387941435', 'NC26.6.RD.3', 2, 'choice', 'Choosing a display and knowing what it shows', 'Which question can a histogram answer that a box plot cannot?', '["What is the median?","How many values are in the interval 20 to 29?","What is the third quartile?","What is the interquartile range?"]', 'How many values are in the interval 20 to 29?', NULL, 'The height of a histogram bar tells how many values are in its interval. A box plot shows the median, the quartiles and the IQR, but not how many values fall in a particular interval.', 'checked', '{"lint":[],"solve":{"answer":"How many values are in the interval 20 to 29?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A box plot shows Q3, the median and the IQR, but not counts in an interval; a histogram with that interval does.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e579c22-2bfa-42fa-b0b5-3510532a9470', 'NC26.6.RD.3', 3, 'numeric', 'Comparing the spread of two box plots', 'Class A''s test scores have these five key values: smallest 50, first quartile 62, median 70, third quartile 78, largest 90. Class B''s have: smallest 40, first quartile 60, median 70, third quartile 84, largest 100. How much greater is Class B''s IQR than Class A''s IQR?', '[]', '8', '(84-60)-(78-62)', 'Class A''s IQR is $78 - 62 = 16$. Class B''s IQR is $84 - 60 = 24$. The difference is $24 - 16 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class A IQR = 78 - 62 = 16. Class B IQR = 84 - 60 = 24. Difference 24 - 16 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61b66ccf-52bd-4910-a2d8-1330d75f63e7', 'NC26.6.RD.3', 3, 'numeric', 'Counting the values in the tallest bar when building a histogram', 'Thirteen quiz scores are: 47, 52, 58, 61, 63, 65, 68, 72, 75, 79, 83, 88, 91. Jin makes a histogram with the bins 40 to 49, 50 to 59, 60 to 69, 70 to 79, 80 to 89 and 90 to 99. How many scores are in the tallest bar?', '[]', '4', NULL, 'Count the scores in each bin: 40 to 49 has 1, 50 to 59 has 2, 60 to 69 has 4 (61, 63, 65, 68), 70 to 79 has 3, 80 to 89 has 2 and 90 to 99 has 1. The tallest bar is 60 to 69, with 4 scores.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-49: 47 (1). 50-59: 52, 58 (2). 60-69: 61, 63, 65, 68 (4). 70-79: 72, 75, 79 (3). 80-89: 83, 88 (2). 90-99: 91 (1). Total 13. Tallest bar has 4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c78cf3c-05bf-4cd9-a7fc-2410ebfa7d0b', 'NC26.6.RD.3', 3, 'choice', 'Comparing center and spread of two dot plots', 'Plot A shows the values 5, 5, 6, 6, 6, 7, 7. Plot B shows the values 2, 4, 6, 6, 6, 8, 10. Which statement is true?', '["Plot A has a greater median than Plot B","The two plots have the same range","Both have a median of 6, but Plot B is more spread out","Plot A is more spread out than Plot B"]', 'Both have a median of 6, but Plot B is more spread out', NULL, 'Both sets have 7 values and the middle (4th) value is 6, so both medians are 6. Plot A has a range of $7 - 5 = 2$ and Plot B has a range of $10 - 2 = 8$, so Plot B is more spread out.', 'checked', '{"lint":[],"solve":{"answer":"Both have a median of 6, but Plot B is more spread out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: median 6 (4th of 7), range 7 - 5 = 2. B: median 6, range 10 - 2 = 8. Same median, B more spread out. Other options false.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fab876e7-93e8-4a2e-a16e-343e215d9c51', 'NC26.6.RD.3', 3, 'numeric', 'Reading counts and totals from a dot plot', 'A dot plot shows the ages of 20 campers: 9 years, 2 dots; 10 years, 4 dots; 11 years, 6 dots; 12 years, 5 dots; 13 years, 3 dots. What percent of the campers are at least 12 years old?', '[]', '40', '(5+3)/20*100', '"At least 12" means the stacks at 12 and 13 years: $5 + 3 = 8$ campers. Then $\frac{8}{20} = \frac{40}{100} = 40\%$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 2+4+6+5+3 = 20. At least 12: 12 and 13 -> 5+3 = 8. 8/20 = 40%.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('168e790d-4762-4e08-bda1-e226064ba1ab', 'NC26.6.RD.3', 3, 'numeric', 'Reading counts and totals from a dot plot', 'A dot plot shows how many hours of television 25 students watched yesterday. The stacks that can be read are: 0 hours, 4 dots; 1 hour, 7 dots; 3 hours, 6 dots; 4 hours, 3 dots. The stack above 2 hours is hidden, but the plot has 25 dots in all. How many dots are in the hidden stack?', '[]', '5', '25-(4+7+6+3)', 'The stacks that can be read hold $4 + 7 + 6 + 3 = 20$ dots. The plot has 25 dots in all, so the hidden stack has $25 - 20 = 5$ dots.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Visible: 4+7+6+3 = 20. Hidden = 25-20 = 5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d582a02e-60d9-476a-85f3-7fa439fe41d3', 'NC26.6.RD.3', 3, 'choice', 'Clusters, gaps, peaks and outliers in a dot plot', 'A dot plot has one cluster of dots from 20 to 24, a gap from 25 to 29, and a second cluster from 30 to 32. Which list of values could it show?', '["20, 21, 22, 23, 24, 26, 27, 28, 30, 31, 32, 32","20, 21, 21, 22, 23, 24, 24, 30, 30, 31, 32, 32","20, 21, 21, 22, 23, 24, 24, 40, 41, 41, 42, 42","20, 21, 21, 22, 23, 24, 24, 25, 26, 27, 28, 29"]', '20, 21, 21, 22, 23, 24, 24, 30, 30, 31, 32, 32', NULL, 'All of the values must be 20 to 24 or 30 to 32, with none from 25 to 29. Only one list does that. One of the other lists has values at 26, 27 and 28, in the gap. Another has its second cluster at 40 to 42. The last has no values from 30 to 32 at all.', 'checked', '{"lint":[],"solve":{"answer":"20, 21, 21, 22, 23, 24, 24, 30, 30, 31, 32, 32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Option 1: values 20-24, none 25-29, then 30-32. Option 2 second cluster is at 40-42; option 3 has 26-28 in the gap; option 4 has no second cluster.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fc7eedb-a411-4ef5-b1d7-ee7332703f99', 'NC26.6.RD.3', 3, 'choice', 'Clusters, gaps, peaks and outliers in a dot plot', 'A dot plot shows these 8 values, with one dot for each: 4, 5, 5, 6, 7, 7, 7, 9. Which new dot, added to the plot, would leave the range of the data unchanged?', '["A dot at 8","A dot at 3","A dot at 10","A dot at 12"]', 'A dot at 8', NULL, 'The range now is $9 - 4 = 5$. A dot at 8 lies between the smallest value, 4, and the largest, 9, so the range stays 5. A dot at 3 or at 10 or 12 would make the data stretch further, and the range would grow.', 'checked', '{"lint":[],"solve":{"answer":"A dot at 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = 9-4 = 5. A dot at 8 stays inside 4..9, range 5. Dots at 10, 3, 12 give ranges 6, 6, 8.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('759809b5-7fcb-444a-a7d5-2d8582acc8db', 'NC26.6.RD.3', 3, 'numeric', 'Constructing a dot plot from a list of data', 'A teacher lists the scores of 18 students on a 10-point quiz: 7, 9, 8, 7, 10, 9, 7, 6, 8, 9, 7, 10, 8, 9, 7, 5, 9, 8. She makes a dot plot with one dot for each student. For how many different scores will the dot plot have a stack of 3 or more dots?', '[]', '3', '3', 'Count each score: 5 appears once, 6 once, 7 five times, 8 four times, 9 five times and 10 twice. The scores 7, 8 and 9 each have 3 or more dots, so the answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts: 5:1, 6:1, 7:5 (pos 1,4,7,11,15), 8:4 (pos 3,9,13,18), 9:5 (pos 2,6,10,14,17), 10:2. Total 18. Scores with 3+ dots: 7, 8, 9 -> 3.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31705ca0-cd3f-473a-82e8-9b024af4339e', 'NC26.6.RD.3', 3, 'choice', 'Constructing a dot plot from a list of data', 'A dot plot has these stacks of dots: 2, 2 dots; 3, 3 dots; 5, 1 dot; 6, 2 dots. Which list of values could NOT have been used to make this dot plot?', '["3, 6, 2, 3, 5, 2, 3, 6","6, 3, 3, 2, 5, 3, 6, 2","2, 3, 3, 6, 6, 5, 3, 2","3, 2, 6, 3, 4, 2, 6, 3"]', '3, 2, 6, 3, 4, 2, 6, 3', NULL, 'The plot needs two 2s, three 3s, one 5 and two 6s, which is 8 values and no others. The list 3, 2, 6, 3, 4, 2, 6, 3 has a 4 and no 5, so it cannot make this plot. The other three lists have exactly the right numbers of 2s, 3s, 5s and 6s.', 'checked', '{"lint":[],"solve":{"answer":"3, 2, 6, 3, 4, 2, 6, 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Plot: 2x2, 3x3, 5x1, 6x2. Option 1 has a 4 and no 5, so it could NOT make the plot. Options 2, 3, 4 each have two 2s, three 3s, one 5, two 6s.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24f89940-bfdf-476e-a019-91b8a9ad261e', 'NC26.6.RD.3', 3, 'numeric', 'Reading bar heights and totals in a histogram', 'A histogram of 25 test scores has these bars: 70 to 79, 6 scores; 80 to 89, 10 scores; 90 to 99, 9 scores. All scores are whole numbers. What is the smallest number of scores that could be above 85?', '[]', '9', '9', 'All 9 scores in the bar for 90 to 99 are above 85. The 10 scores in the bar for 80 to 89 could all be 85 or lower, since the histogram does not say exactly which values they are. So at least 9 scores are above 85, and 9 is the smallest possible number.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All 9 scores in 90-99 are above 85. The 10 scores in 80-89 could all be 80-85, so none of them need be above 85. Smallest = 9.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1e147e0-62d6-47fd-9c88-0a79155e8c4e', 'NC26.6.RD.3', 3, 'numeric', 'Reading bar heights and totals in a histogram', 'A histogram of 34 values has five bars. The three tallest bars hold 10, 8 and 6 values. The other two bars are the same height. How many values are in each of the other two bars?', '[]', '5', '(34-10-8-6)/2', 'The three tallest bars hold $10 + 8 + 6 = 24$ values. That leaves $34 - 24 = 10$ values for the other two bars, which are equal, so each holds $10 \div 2 = 5$ values. This is shorter than the 6 of the third tallest bar, as it should be.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"34-(10+8+6) = 10, split equally: 5 each (less than 6, so consistent with the three tallest).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84385392-a71d-48d8-8f75-6195d6dc3a5d', 'NC26.6.RD.3', 3, 'numeric', 'Placing values in histogram intervals', 'Twenty students recorded the minutes they walked to school: 14, 22, 5, 31, 18, 27, 9, 36, 12, 24, 3, 19, 28, 41, 16, 25, 7, 33, 21, 11. A histogram uses the intervals 0 to 9, 10 to 19, 20 to 29, 30 to 39 and 40 to 49. How many more values are in the tallest bar than in the shortest bar?', '[]', '5', '6-1', 'Sort the times into the intervals. 0 to 9 has 4 values, 10 to 19 has 6, 20 to 29 has 6, 30 to 39 has 3 and 40 to 49 has 1. The tallest bar has 6 values and the shortest has 1, so the difference is $6 - 1 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor wording: two bars (10-19 and 20-29) tie as tallest at 6, so \"the tallest bar\" is not unique; the difference 6-1 = 5 is unaffected.","work":"0-9: 5,9,3,7 = 4. 10-19: 14,18,12,19,16,11 = 6. 20-29: 22,27,24,28,25,21 = 6. 30-39: 31,36,33 = 3. 40-49: 41 = 1. Total 20. Tallest 6, shortest 1: 6-1 = 5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6044957-08e0-4432-b2d9-cd96f46723b8', 'NC26.6.RD.3', 3, 'choice', 'Placing values in histogram intervals', 'These 12 values are put in a histogram with the intervals 0 to 4, 5 to 9, 10 to 14 and 15 to 19: 2, 8, 14, 9, 3, 11, 5, 17, 9, 12, 6, 10. Which list gives the bar heights, from the first interval to the last?', '["2, 5, 4, 1","3, 5, 3, 1","2, 4, 4, 1","2, 6, 3, 1"]', '2, 5, 4, 1', NULL, 'Sort each value into its interval. 0 to 4: 2 and 3. 5 to 9: 8, 9, 5, 9 and 6. 10 to 14: 14, 11, 12 and 10. 15 to 19: 17. The heights are 2, 5, 4 and 1, which add to 12. The other lists do not count every value, or put a value in the wrong bar.', 'checked', '{"lint":[],"solve":{"answer":"2, 5, 4, 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0-4: 2,3 = 2. 5-9: 8,9,5,9,6 = 5. 10-14: 14,11,12,10 = 4. 15-19: 17 = 1. Total 12. Heights 2, 5, 4, 1.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de4fe228-7507-4cb4-a63a-520c6b89dfb8', 'NC26.6.RD.3', 3, 'choice', 'Describing the shape and spread of a histogram', 'A histogram of 20 ages has these bars: 0 to 9, 2; 10 to 19, 9; 20 to 29, 6; 30 to 39, 2; 40 to 49, 1. Which statement is true?', '["It is skewed to the right, and 15 of the 20 ages are from 10 to 29","It is skewed to the left, and 15 of the 20 ages are from 10 to 29","It is skewed to the right, and 9 of the 20 ages are from 10 to 29","It is symmetric, and 15 of the 20 ages are from 10 to 29"]', 'It is skewed to the right, and 15 of the 20 ages are from 10 to 29', NULL, 'The bars for 10 to 19 and 20 to 29 hold $9 + 6 = 15$ ages. The peak is in the second bar and the bars thin out to the right (6, 2, 1) much more slowly than to the left (2), so the long tail is on the right: skewed to the right.', 'checked', '{"lint":[],"solve":{"answer":"It is skewed to the right, and 15 of the 20 ages are from 10 to 29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 2+9+6+2+1 = 20. Peak at 10-19, tail 6,2,1 to the right: skewed right. 10-29: 9+6 = 15. Option 1.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7da1e05b-3810-46b9-ac01-11d96ef7a2f9', 'NC26.6.RD.3', 3, 'numeric', 'Describing the shape and spread of a histogram', 'A histogram of exam scores uses the intervals 40 to 49, 50 to 59, 60 to 69, 70 to 79, 80 to 89 and 90 to 99. The first bar that holds any scores is 50 to 59, and the last bar that holds any scores is 80 to 89. All scores are whole numbers. What is the greatest possible range of the scores?', '[]', '39', '89-50', 'The range is largest when the lowest score is as low as possible, 50, and the highest score is as high as possible, 89. The greatest possible range is $89 - 50 = 39$.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Smallest possible score 50, largest possible 89: range 89-50 = 39.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29b9d5d7-8d70-4034-a22e-eff1ee177e49', 'NC26.6.RD.3', 3, 'numeric', 'Describing the shape and spread of a histogram', 'A histogram has these bars: 0 to 9, 0 values; 10 to 19, 3 values; 20 to 29, 9 values; 30 to 39, 8 values; 40 to 49, 0 values. All the values are whole numbers. What is the least possible range of the data?', '[]', '11', '30-19', 'The smallest value is in the bar for 10 to 19, and the largest is in the bar for 30 to 39. The range is smallest when the lowest value is as high as possible, 19, and the highest value is as low as possible, 30. The least possible range is $30 - 19 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Minimum is in 10-19 (at most 19), maximum is in 30-39 (at least 30). Least range = 30-19 = 11.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77b519bb-a184-4f29-8b0b-25ec65da7c35', 'NC26.6.RD.3', 3, 'numeric', 'Finding the median from a display', 'A dot plot of the number of visitors to a library each hour, over 24 hours, has these stacks of dots: 0 visitors, 4 dots; 1 visitor, 8 dots; 2 visitors, 4 dots; 3 visitors, 4 dots; 4 visitors, 3 dots; 5 visitors, 1 dot. What is the median number of visitors?', '[]', '1.5', '(1+2)/2', 'There are 24 values, so the median is halfway between the 12th and 13th values. The stacks hold 4 values at 0 and then 8 at 1, so the first 12 values are 0s and 1s and the 12th value is 1. The 13th value is the first one at 2. The median is $(1 + 2) \div 2 = 1.5$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 4+8+4+4+3+1 = 24. Positions: 0 -> 1-4, 1 -> 5-12, 2 -> 13-16. Median = mean of 12th (1) and 13th (2) = 1.5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29b66f16-8c90-46f0-8714-e4c78da469ae', 'NC26.6.RD.3', 3, 'choice', 'Finding the median from a display', 'A histogram of 29 values has these bars: 0 to 9, 12 values; 10 to 19, 5 values; 20 to 29, 4 values; 30 to 39, 4 values; 40 to 49, 4 values. Dana says the median must be in the tallest bar. Which statement is correct?', '["Dana is right: the median is in 0 to 9, which is the tallest bar","Dana is wrong: the median is in 20 to 29, the middle bar","Dana is right, because the median is the value that occurs most often","Dana is wrong: the tallest bar is 0 to 9, but the median is in 10 to 19"]', 'Dana is wrong: the tallest bar is 0 to 9, but the median is in 10 to 19', NULL, 'With 29 values, the median is the 15th value in order. The bar for 0 to 9 holds the first 12 values, and the bar for 10 to 19 holds values 13 to 17, so the 15th value is in 10 to 19. The tallest bar is 0 to 9, so Dana is wrong. The median is the middle value, not the most common one.', 'checked', '{"lint":[],"solve":{"answer":"Dana is wrong: the tallest bar is 0 to 9, but the median is in 10 to 19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 12+5+4+4+4 = 29; median is the 15th value. 0-9 holds positions 1-12, 10-19 holds 13-17, so the median is in 10-19, not the tallest bar 0-9.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce5f0a05-5574-4719-9ad5-890fbdfa2946', 'NC26.6.RD.3', 3, 'numeric', 'Finding the five key values of a data set', 'Here are 15 numbers of minutes, in the order they were collected: 21, 6, 15, 28, 9, 13, 19, 4, 25, 10, 16, 7, 23, 12, 18. When finding the quartiles, leave the median out and use the 7 values below it and the 7 values above it. What is the interquartile range (IQR)?', '[]', '12', '21-9', 'Order the data: 4, 6, 7, 9, 10, 12, 13, 15, 16, 18, 19, 21, 23, 25, 28. The median is the 8th value, 15. The 7 values below it are 4, 6, 7, 9, 10, 12, 13, with middle value 9, so the first quartile is 9. The 7 values above it are 16, 18, 19, 21, 23, 25, 28, with middle value 21, so the third quartile is 21. The IQR is $21 - 9 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered: 4,6,7,9,10,12,13,15,16,18,19,21,23,25,28. Median 15. Lower 7: 4,6,7,9,10,12,13 -> Q1 = 9. Upper 7: 16,18,19,21,23,25,28 -> Q3 = 21. IQR = 12.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f648bfa7-5b72-4bb7-9d90-58d2341342ed', 'NC26.6.RD.3', 3, 'choice', 'Finding the five key values of a data set', 'Sixteen runners finished a race in these ordered times, in minutes: 12, 14, 15, 16, 18, 19, 20, 22, 24, 25, 27, 28, 30, 33, 35, 40. Which list gives the minimum, first quartile, median, third quartile and maximum, in that order?', '["12, 16, 22, 28, 40","12, 18, 24, 30, 40","12, 19, 26, 33, 40","12, 17, 23, 29, 40"]', '12, 17, 23, 29, 40', NULL, 'The median is halfway between the 8th and 9th values, 22 and 24, so it is 23. The lower half has 8 values, and its median is halfway between 16 and 18, which is 17. The upper half has 8 values, and its median is halfway between 28 and 30, which is 29. With the minimum 12 and the maximum 40, the list is 12, 17, 23, 29, 40.', 'checked', '{"lint":[],"solve":{"answer":"12, 17, 23, 29, 40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median (22+24)/2 = 23. Lower 8: 12..22 -> Q1 = (16+18)/2 = 17. Upper 8: 24..40 -> Q3 = (28+30)/2 = 29. 12, 17, 23, 29, 40.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6834f38d-9e8d-40ab-bee1-a960210c1d93', 'NC26.6.RD.3', 3, 'numeric', 'Finding the five key values of a data set', 'The ordered scores of 8 players are 5, 8, 10, a missing score, 16, 19, 22 and 30. The median score is 14. What is the missing score?', '[]', '12', '2*14-16', 'With 8 scores, the median is halfway between the 4th and 5th scores, which are the missing score and 16. So the missing score plus 16 is $2 \times 14 = 28$, and the missing score is $28 - 16 = 12$. This fits, since 12 is between 10 and 16.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median = (missing + 16)/2 = 14, so missing = 12, which fits between 10 and 16.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd003541-7a18-4356-a8ae-1d20eca6cb1a', 'NC26.6.RD.3', 3, 'numeric', 'Reading range and IQR from a box plot', 'A box plot has an interquartile range of 14. Its first quartile is 31, its median is 37, and its whiskers run from 22 to 60. What is the third quartile?', '[]', '45', '31+14', 'The IQR is the third quartile minus the first quartile, so the third quartile is the first quartile plus the IQR: $31 + 14 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q3 = Q1 + IQR = 31 + 14 = 45 (between median 37 and max 60).","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4545ff91-917f-43b1-8ae8-5212339693d7', 'NC26.6.RD.3', 3, 'choice', 'Reading range and IQR from a box plot', 'A data set has 12 values. Its largest value is changed from 50 to 80, and it is still the largest value. Which of these changes?', '["The median","The first quartile","The range","The interquartile range"]', 'The range', NULL, 'The range is the largest value minus the smallest, so it grows by 30. The median is found from the 6th and 7th values, and the quartiles from the middle values of each half: the 3rd and 4th values, and the 9th and 10th values. None of those is the largest value, so the median, the quartiles and the IQR stay the same.', 'checked', '{"lint":[],"solve":{"answer":"The range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 12 values, Q1 uses 3rd/4th, median 6th/7th, Q3 9th/10th; the 12th value only affects the maximum, so only the range changes.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173beaeb-ddd6-457b-a0e7-aba9e2649230', 'NC26.6.RD.3', 3, 'numeric', 'Share of the data in a part of a box plot', 'A box plot is made from 52 different values. How many of the values are greater than the first quartile?', '[]', '39', '52*3/4', 'One quarter of the values, $52 \div 4 = 13$, are less than the first quartile. The other three quarters are greater: $52 - 13 = 39$ values.', 'checked', '{"lint":[],"solve":{"answer":"39","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 distinct values; lower half 26; Q1 is the mean of the 13th and 14th, strictly between them. 13 values are below Q1, so 52-13 = 39 are greater.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f18d9392-58fe-425c-99e2-ba7fbe874d77', 'NC26.6.RD.3', 3, 'choice', 'Share of the data in a part of a box plot', 'In a box plot, the first quartile is 20, the median is 24 and the third quartile is 40. Which statement is true?', '["More values lie from 24 to 40 than from 20 to 24","The values from 24 to 40 are more spread out than the values from 20 to 24","Half of the values lie from 20 to 24","The median is halfway between the two quartiles"]', 'The values from 24 to 40 are more spread out than the values from 20 to 24', NULL, 'The part of the box from 20 to 24 and the part from 24 to 40 each hold one quarter of the values. The second part is 16 units long and the first is only 4 units long, so the same number of values is spread over a longer stretch. The median, 24, is closer to 20 than to 40, so it is not halfway between them.', 'checked', '{"lint":[],"solve":{"answer":"The values from 24 to 40 are more spread out than the values from 20 to 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each of 20-24 and 24-40 holds about a quarter of the values, but 24-40 is wider (16 vs 4), so those values are more spread out. Not half in 20-24; not more values; halfway would be 30.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b0c489a-5619-4f68-bf2f-dcc713150b9e', 'NC26.6.RD.3', 3, 'numeric', 'Share of the data in a part of a box plot', 'In a box plot, exactly one quarter of the values are above the third quartile. Kayla counts 15 values above the third quartile. How many values are in the data set?', '[]', '60', '15*4', 'The 15 values are one quarter of the data, so the whole data set is 4 times as large: $15 \times 4 = 60$ values.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 is one quarter, so the total is 15 x 4 = 60.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b40ea5f-9e07-4859-82a2-b10756966052', 'NC26.6.RD.3', 3, 'choice', 'Comparing the center and spread of two displays', 'Class A''s scores have a minimum of 60, a first quartile of 70, a median of 75, a third quartile of 80 and a maximum of 90. Class B''s scores have a minimum of 40, a first quartile of 65, a median of 75, a third quartile of 78 and a maximum of 95. Which statement is true?', '["Class A''s scores are more spread out, with a greater range and a greater IQR","The classes have the same spread because they have the same median","Class B''s scores are more spread out, with a greater range and a greater IQR","Class B''s scores are less spread out because its maximum is greater"]', 'Class B''s scores are more spread out, with a greater range and a greater IQR', NULL, 'Class A''s range is $90 - 60 = 30$ and its IQR is $80 - 70 = 10$. Class B''s range is $95 - 40 = 55$ and its IQR is $78 - 65 = 13$. Class B has both the greater range and the greater IQR, so its scores are more spread out. The same median only means the same center.', 'checked', '{"lint":[],"solve":{"answer":"Class B''s scores are more spread out, with a greater range and a greater IQR","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: range 90-60 = 30, IQR 80-70 = 10. B: range 95-40 = 55, IQR 78-65 = 13. B is more spread on both.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25a384ed-8055-49bd-9a4b-d6b7fbe41226', 'NC26.6.RD.3', 3, 'numeric', 'Comparing the center and spread of two displays', 'Dot plot X has one dot at each of these values: 10, 12, 14, 14, 16, 18, 19. Dot plot Y has one dot at each of these values: 7, 8, 9, 10, 11, 12. How much greater is the median of X than the median of Y?', '[]', '4.5', '14-(9+10)/2', 'X has 7 values, so its median is the 4th value, 14. Y has 6 values, so its median is halfway between the 3rd and 4th values, 9 and 10, which is 9.5. The difference is $14 - 9.5 = 4.5$.', 'checked', '{"lint":[],"solve":{"answer":"4.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X (7 values) median = 4th = 14. Y (6 values) median = (9+10)/2 = 9.5. 14-9.5 = 4.5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07ee4024-f594-4e16-bee6-8d2f0ab798d8', 'NC26.6.RD.3', 3, 'choice', 'Comparing the center and spread of two displays', 'Two histograms use the same five intervals, and each shows 20 values. Histogram P has bar heights 2, 5, 6, 5 and 2, from left to right. Histogram Q has bar heights 8, 2, 0, 2 and 8. Which statement is true?', '["P is more spread out, because its bars are taller in the middle","Q is more spread out, because more of its values are in the outer bars","P and Q have the same spread, because they have the same intervals","Q is less spread out, because its middle bar is empty"]', 'Q is more spread out, because more of its values are in the outer bars', NULL, 'In P, 12 of the 20 values are in the three middle bars and only 4 are in the two outer bars. In Q, 16 of the 20 values are in the outer bars, so many values are far from the middle. That makes Q more spread out. Having the same intervals does not make the spread the same.', 'checked', '{"lint":[],"solve":{"answer":"Q is more spread out, because more of its values are in the outer bars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P (2,5,6,5,2) piles values in the middle; Q (8,2,0,2,8) puts 16 of 20 in the outer bars, far from the centre, so Q is more spread out.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e53e78da-eaa1-45a7-adfe-b3db8245efe4', 'NC26.6.RD.3', 3, 'numeric', 'Comparing the center and spread of two displays', 'Box plot A has a minimum of 10, a first quartile of 18, a median of 25, a third quartile of 33 and a maximum of 40. Box plot B has a first quartile of 14 and an interquartile range twice as large as A''s. What is B''s third quartile?', '[]', '44', '14+2*(33-18)', 'A''s IQR is $33 - 18 = 15$. B''s IQR is twice that, $2 \times 15 = 30$. B''s third quartile is its first quartile plus its IQR: $14 + 30 = 44$.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR of A = 33-18 = 15; B IQR = 30; Q3 of B = 14+30 = 44.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93662322-df81-4a1e-88d6-f1a5b97d27d6', 'NC26.6.RD.3', 3, 'numeric', 'Reading displays with unusual scales or layouts', 'A line plot of the lengths of 11 leaves, in centimeters, uses a number line marked every 0.5. The stacks of dots are: 2.5 cm, 1 dot; 3 cm, 2 dots; 3.5 cm, 4 dots; 4 cm, 3 dots; 6.5 cm, 1 dot. What is the median length, in centimeters?', '[]', '3.5', '3.5', 'With 11 values, the median is the 6th value in order. The first stack gives value 1 (2.5 cm), the next stack gives values 2 and 3 (3 cm), and the next gives values 4 to 7 (3.5 cm). So the 6th value is 3.5 cm.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 1+2+4+3+1 = 11; median = 6th value. 2.5 -> 1st, 3 -> 2nd-3rd, 3.5 -> 4th-7th. Median 3.5.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aea9ac38-ffb4-4111-bb5c-5071ee1ec0ae', 'NC26.6.RD.3', 3, 'numeric', 'Reading displays with unusual scales or layouts', 'A histogram of the weights of 80 puppies has a vertical scale labeled "percent of puppies" instead of a count. The four bars read 10%, 25%, 40% and 25%. How many more puppies are in the tallest bar than in the shortest bar?', '[]', '24', '(0.4-0.1)*80', 'The tallest bar is 40% of 80 puppies, which is $0.4 \times 80 = 32$ puppies. The shortest bar is 10% of 80, which is $0.1 \times 80 = 8$ puppies. The difference is $32 - 8 = 24$ puppies.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bars sum to 100%. Tallest 40% = 32 puppies, shortest 10% = 8; 32-8 = 24.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c9c9bdd-1b75-40a7-9c2b-a6adec6ca68d', 'NC26.6.RD.3', 3, 'choice', 'Choosing a display and knowing what it shows', 'A box plot has a minimum of 12, a first quartile of 20, a median of 25, a third quartile of 31 and a maximum of 40. Which of these can NOT be found from the box plot alone?', '["The range","The interquartile range","The number of values in the data set","The median"]', 'The number of values in the data set', NULL, 'The range is $40 - 12 = 28$, the IQR is $31 - 20 = 11$, and the median is 25. A box plot shows only five key values, and data sets of different sizes can have the same five key values, so it does not show how many values there are.', 'checked', '{"lint":[],"solve":{"answer":"The number of values in the data set","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The five-number summary gives range (28), median (25), IQR (11), but not how many values there are.","run_id":"claude-code","at":"2026-10-17T20:16:55.531Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98148096-a60c-40e1-96d4-d326364fa2b7', 'NC26.6.RD.4', 1, 'numeric', 'Finding a mean', 'What is the mean of the numbers 4, 6, 8, 10 and 12?', '[]', '8', '(4+6+8+10+12)/5', 'Add the numbers: $4 + 6 + 8 + 10 + 12 = 40$. Divide by how many there are: $40 \div 5 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 4+6+8+10+12 = 40; 40 / 5 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1cd0f6bf-25b6-4a7e-b9db-5b6eb2e37064', 'NC26.6.RD.4', 1, 'choice', 'Finding a median of an unordered list', 'What is the median of the numbers 9, 3, 12, 5 and 6?', '["$7$","$6$","$12$","$9$"]', '$6$', '6', 'Put the numbers in order: 3, 5, 6, 9, 12. The middle number is 6. (7 is the mean, 12 is the middle of the unordered list, and 9 is the range.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 3, 5, 6, 9, 12. Middle value 6.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e4cb29b-6c7d-413a-9183-8402f3037fcd', 'NC26.6.RD.4', 1, 'numeric', 'The mean as a fair share', 'Four friends have 3, 5, 6 and 10 stickers. They put all the stickers together and share them equally. How many stickers does each friend get?', '[]', '6', '(3+5+6+10)/4', 'There are $3 + 5 + 6 + 10 = 24$ stickers in all. Shared equally among 4 friends, each gets $24 \div 4 = 6$ stickers. This is the mean.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 3 + 5 + 6 + 10 = 24; 24 / 4 = 6 each (the mean as fair share).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f70b1040-865f-4544-8147-961f9b2d57cc', 'NC26.6.RD.4', 1, 'numeric', 'The mean as a balance point or fair share', 'Three baskets hold 4, 7 and 10 apples. Apples are moved from basket to basket until every basket holds the same number. How many apples are in each basket?', '[]', '7', '(4+7+10)/3', 'Together there are $4 + 7 + 10 = 21$ apples. Shared equally among 3 baskets, each holds $21 \div 3 = 7$ apples. This equal share is the mean.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 4+7+10 = 21 apples; shared over 3 baskets: 21/3 = 7.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0990908b-760d-41cf-bdc0-21020237dd1c', 'NC26.6.RD.4', 1, 'choice', 'The mean as a balance point or fair share', 'Which statement describes the mean of a data set as its balance point?', '["The mean is the value that appears most often in the data set","The mean is the middle value when the data are put in order","The total distance of the values above the mean equals the total distance of the values below the mean","The mean is the distance from the least value to the greatest value"]', 'The total distance of the values above the mean equals the total distance of the values below the mean', NULL, 'If the data were weights on a see-saw, the mean is the point where it balances: the distances of the values above it add up to the same total as the distances of the values below it. The value that appears most often is the mode, the middle value is the median, and the distance from the least to the greatest value is the range.', 'checked', '{"lint":[],"solve":{"answer":"The total distance of the values above the mean equals the total distance of the values below the mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The balance-point view: the sum of distances above the mean equals the sum of distances below it. The others describe median, mode, range.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b7054fd-8670-46e9-8c4c-0933156e6152', 'NC26.6.RD.4', 1, 'numeric', 'The mean as a balance point or fair share', 'Four stacks of 1, 3, 5 and 7 cubes are leveled so that every stack is the same height. How many cubes are in each stack?', '[]', '4', '(1+3+5+7)/4', 'There are $1 + 3 + 5 + 7 = 16$ cubes in all. Four equal stacks hold $16 \div 4 = 4$ cubes each.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+3+5+7 = 16 cubes; 16/4 = 4 per stack.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10017ade-7bb7-44be-b5e6-fdde655c6666', 'NC26.6.RD.4', 1, 'numeric', 'The mean as a balance point or fair share', 'A data set has a mean of 8. One value in the set is 5. How many units below the mean is that value?', '[]', '3', '8-5', 'The value 5 is $8 - 5 = 3$ units below the mean of 8.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 - 5 = 3 units below the mean.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('068f4518-a46b-43f6-99d8-59c94825d889', 'NC26.6.RD.4', 1, 'choice', 'The mean as a balance point or fair share', 'A data set has the values 2, 6 and 10, and its mean is 6. Which statement is true?', '["The 2 is 4 below the mean and the 10 is 6 above it, so they balance each other","The 2 is 4 below the mean and the 10 is 4 above it, so they balance each other","The 2 is 6 below the mean and the 10 is 4 above it, so they balance each other","The 2 and the 10 are both 4 above the mean, so they balance each other"]', 'The 2 is 4 below the mean and the 10 is 4 above it, so they balance each other', NULL, '$6 - 2 = 4$, so the 2 is 4 below the mean. $10 - 6 = 4$, so the 10 is 4 above the mean. Equal distances on the two sides balance each other. The 6 itself is exactly at the mean.', 'checked', '{"lint":[],"solve":{"answer":"The 2 is 4 below the mean and the 10 is 4 above it, so they balance each other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 is 6-2 = 4 below; 10 is 10-6 = 4 above; they balance. Third option.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4600d90-a911-4cc1-8a9a-c7f007357d21', 'NC26.6.RD.4', 1, 'numeric', 'Finding a mean', 'Find the mean of the numbers 3, 8, 4 and 9.', '[]', '6', '(3+8+4+9)/4', 'Add the numbers: $3 + 8 + 4 + 9 = 24$. Divide by how many numbers there are: $24 \div 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+8+4+9 = 24; 24/4 = 6.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('091aa4f3-1949-4412-b3ff-52a160e1f201', 'NC26.6.RD.4', 1, 'numeric', 'Finding a mean', 'Rosa read 12, 15 and 18 pages on three nights. What was the mean number of pages she read per night?', '[]', '15', '(12+15+18)/3', 'She read $12 + 15 + 18 = 45$ pages in 3 nights. The mean is $45 \div 3 = 15$ pages per night.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12+15+18 = 45; 45/3 = 15.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2115676c-d8af-412f-bcda-4e68d95e4b96', 'NC26.6.RD.4', 1, 'choice', 'Finding a mean', 'Which expression gives the mean of 6, 10 and 14?', '["$\\frac{6+10+14}{3}$","$\\frac{6+10+14}{4}$","$6+10+14$","$\\frac{6+14}{3}$"]', '$\frac{6+10+14}{3}$', NULL, 'To find a mean, add all the values and divide by how many values there are. There are 3 values, so the mean is $\frac{6+10+14}{3} = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{6+10+14}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean = sum of the 3 values divided by 3: (6+10+14)/3.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
