INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ea55e0e-6b53-4c33-9a77-61fc17231313', 'NC26.6.RD.4', 1, 'numeric', 'Using a mean to find a missing value or a total', 'The mean of 3 numbers is 10. Two of the numbers are 8 and 12. What is the third number?', '[]', '10', '3*10-8-12', 'Three numbers with a mean of 10 add up to $3 \times 10 = 30$. The two known numbers add up to $8 + 12 = 20$, so the third is $30 - 20 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 30; 30-8-12 = 10.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
