VALUES ('374400a7-fbf8-4c9f-a4d6-f01d9301c69e', 'NC26.6.RD.4', 1, 'numeric', 'Using a mean to find a missing value or a total', 'Four friends have a mean of 6 stickers each. How many stickers do they have in all?', '[]', '24', '4*6', 'Mean $\times$ number of friends gives the total: $4 \times 6 = 24$ stickers.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*6 = 24.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
