INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c989fcb-cc6d-483c-9c26-cae1226d274e', 'NC26.6.RD.4', 1, 'numeric', 'Comparing the variability of two data sets', 'The tallest tree in a park is 31 feet high and the shortest is 12 feet high. What is the range of the tree heights, in feet?', '[]', '19', '31-12', 'The range is the greatest value minus the least value: $31 - 12 = 19$ feet.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31 - 12 = 19.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
