INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35c2a5dd-9958-4aec-9eef-12c65af9fe49', 'NC26.6.RD.4', 1, 'choice', 'Choosing the best measure of center', 'Aiden''s test scores are 80, 82, 84, 85 and 86. None of the scores is unusually high or low. Which statement is true?', '["Only the median can describe a typical score","Only the mean can describe a typical score","Neither the mean nor the median can describe a typical score","Both the mean and the median describe a typical score well"]', 'Both the mean and the median describe a typical score well', NULL, 'The scores are close together, with no unusual value, so the mean (83.4) and the median (84) are close and both describe a typical score well.', 'checked', '{"lint":[],"solve":{"answer":"Both the mean and the median describe a typical score well","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 417/5 = 83.4, median 84; no outlier, so both describe a typical score well.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('598f8bf1-971f-4d9c-a34c-4dde92e5c069', 'NC26.6.RD.4', 1, 'choice', 'Choosing the best measure of center', 'Five students get weekly allowances, in dollars, of 5, 6, 6, 7 and 40. Which measure of center better describes a typical allowance, and why?', '["The median, because the 40 is much greater than the other values and pulls the mean up","The mean, because every value counts and the 40 shows what is typical","The mean, because it is the middle value of the data","The median, because it is the average of all the values"]', 'The median, because the 40 is much greater than the other values and pulls the mean up', NULL, 'The median is 6, which is close to most allowances. The mean is 12.8, pulled up by the single value 40, so it describes none of the students well. The median is the middle value; the mean is the average of all the values.', 'checked', '{"lint":[],"solve":{"answer":"The median, because the 40 is much greater than the other values and pulls the mean up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 64/5 = 12.8, pulled up by 40; median 6 is typical. Second option.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d08ec48-fffd-4c28-b177-48411241c25a', 'NC26.6.RD.4', 1, 'choice', 'Choosing the best measure of center', 'Which of these is changed the least when one extremely large value is added to a data set?', '["The mean","The median","The total of all the values","The range"]', 'The median', NULL, 'One extremely large value adds a lot to the total, so it moves the mean and the range a lot. The median is only the middle value, so it moves very little.', 'checked', '{"lint":[],"solve":{"answer":"The median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An extreme value changes range, mean and total a lot; the median shifts at most by half a step between neighbours.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb92249b-d2d1-4e43-9968-7ac4b2f808b4', 'NC26.6.RD.4', 1, 'choice', 'Choosing the best measure of center', 'Which of these is the middle value of a data set when the values are put in order?', '["The mean","The range","The median","The least value"]', 'The median', NULL, 'The median is the middle value when the data are in order. The mean is the total divided by the number of values, and the range is the greatest value minus the least.', 'checked', '{"lint":[],"solve":{"answer":"The median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Definition of the median.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c7ed238-6fb9-4068-acc0-9cc3df8b5632', 'NC26.6.RD.4', 2, 'numeric', 'Median of an even number of values', 'What is the median of the numbers 25, 12, 30, 18, 15 and 20?', '[]', '19', '(18+20)/2', 'Put the numbers in order: 12, 15, 18, 20, 25, 30. With six numbers, the median is halfway between the two middle ones: $(18 + 20) \div 2 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 12, 15, 18, 20, 25, 30. Median = (18 + 20) / 2 = 19.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
