INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('245fd1c4-db55-46b2-bdb2-bb49748b604b', 'NC26.6.RD.4', 2, 'numeric', 'The mean as a balance point or fair share', 'A data set of four values has a mean of 20. Three of the values are 13, 17 and 26. How many units above the mean is the fourth value?', '[]', '4', '(4*20-13-17-26)-20', 'Four values with a mean of 20 add up to $4 \times 20 = 80$. The three known values add up to $13 + 17 + 26 = 56$, so the fourth value is $80 - 56 = 24$. That is $24 - 20 = 4$ units above the mean.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 4*20 = 80. 13+17+26 = 56. Fourth = 24, which is 24-20 = 4 above the mean. (Check deviations: -7, -3, +6, +4 sum to 0.)","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcc48529-bd45-4fb1-bf1b-608901fca9f1', 'NC26.6.RD.4', 2, 'choice', 'The mean as a balance point or fair share', 'Jada''s four test scores are 70, 80, 90 and 100, and their mean is 85. Which statement is true?', '["The scores above 85 are 25 points away from 85 in all, and the scores below 85 are 15 points away in all","The scores above 85 are 10 points away from 85 in all, and the scores below 85 are 30 points away in all","The scores above 85 are 20 points away from 85 in all, and the scores below 85 are 30 points away in all","The scores above 85 are 20 points away from 85 in all, and the scores below 85 are also 20 points away in all"]', 'The scores above 85 are 20 points away from 85 in all, and the scores below 85 are also 20 points away in all', NULL, 'The scores above 85 are 90 and 100, which are $5 + 15 = 20$ points away. The scores below 85 are 70 and 80, which are $15 + 5 = 20$ points away. The mean is the balance point, so the two totals are equal.', 'checked', '{"lint":[],"solve":{"answer":"The scores above 85 are 20 points away from 85 in all, and the scores below 85 are also 20 points away in all","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Above 85: 90 (5) + 100 (15) = 20. Below: 80 (5) + 70 (15) = 20. Both 20.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1492693-0606-4d78-9d0b-3c13880ef448', 'NC26.6.RD.4', 2, 'numeric', 'The mean as a balance point or fair share', 'Six students scored 3, 4, 4, 5, 6 and 8 points in a game. All of the points are pooled and then shared equally by the six students. How many points does each student get?', '[]', '5', '(3+4+4+5+6+8)/6', 'The pool holds $3 + 4 + 4 + 5 + 6 + 8 = 30$ points. Shared equally among 6 students, each gets $30 \div 6 = 5$ points.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4+4+5+6+8 = 30; 30/6 = 5.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2657547d-54af-46cc-9197-15f14b4bf362', 'NC26.6.RD.4', 2, 'choice', 'The mean as a balance point or fair share', 'Four plants are 6, 7, 8 and 15 centimeters tall. Suppose the plants all had the same height and the total of their heights stayed the same. How many centimeters tall would each plant be?', '["9","7.5","15","36"]', '9', '(6+7+8+15)/4', 'The total height is $6 + 7 + 8 + 15 = 36$ centimeters. Shared equally by 4 plants, each is $36 \div 4 = 9$ centimeters tall. (7.5 is the median, 15 is the tallest plant and 36 is the total.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6+7+8+15 = 36; 36/4 = 9.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9d2ef77-7441-41be-86ae-e99a70b2df46', 'NC26.6.RD.4', 2, 'numeric', 'The mean as a balance point or fair share', 'A data set with five values has a mean of 12. The values that are below 12 are a total of 9 units away from 12. In all, how many units away from 12 are the values that are above 12?', '[]', '9', '9', 'The mean is the balance point, so the total distance of the values above it equals the total distance of the values below it. The values above 12 are a total of 9 units away.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At the mean, total distance above equals total distance below, so 9.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b27fc8e-dd7d-4530-a71b-30870f105332', 'NC26.6.RD.4', 2, 'choice', 'Finding a mean', 'Students were asked how many pets they have. Three students have 1 pet, 4 students have 2 pets, 2 students have 3 pets and 1 student has 4 pets. What is the mean number of pets per student?', '["2.5","21","2.1","2"]', '2.1', '(3*1+4*2+2*3+1*4)/10', 'The number of students is $3 + 4 + 2 + 1 = 10$. The total number of pets is $3 \times 1 + 4 \times 2 + 2 \times 3 + 1 \times 4 = 3 + 8 + 6 + 4 = 21$. The mean is $21 \div 10 = 2.1$ pets per student.', 'checked', '{"lint":[],"solve":{"answer":"2.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students 3+4+2+1 = 10. Pets 3*1+4*2+2*3+1*4 = 3+8+6+4 = 21. Mean 21/10 = 2.1.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b42ca903-b48f-4487-ba09-28a071ad3610', 'NC26.6.RD.4', 2, 'numeric', 'Finding a mean', 'Four hikes were 1.5, 2, 3.5 and 5 miles long. What is the mean length of the hikes, in miles?', '[]', '3', '(1.5+2+3.5+5)/4', 'The lengths add up to $1.5 + 2 + 3.5 + 5 = 12$ miles. Dividing by 4 hikes gives $12 \div 4 = 3$ miles.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5+2+3.5+5 = 12; 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
