INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3da6e068-4fc3-4239-b12a-f17e8d6711a1', 'NC26.6.RD.4', 2, 'numeric', 'Finding a median', 'The data are in order: 3, 5, x, 11 and 14. The median is 9. What is the value of x?', '[]', '9', '9', 'With 5 values, the median is the 3rd value, which is x. The median is 9, so x = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 ordered values, median is the 3rd, so x = 9 (and 5 <= 9 <= 11).","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
