INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('478ef43a-67e4-45e1-bf67-9c80fdeac2e1', 'NC26.6.RD.4', 2, 'numeric', 'Comparing the variability of two data sets', 'Data set P is 14, 18, 22, 25, 31. Data set Q is 20, 22, 25, 27, 29. How many units greater is the range of P than the range of Q?', '[]', '8', '(31-14)-(29-20)', 'The range of P is $31 - 14 = 17$. The range of Q is $29 - 20 = 9$. The difference is $17 - 9 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range P = 31-14 = 17; range Q = 29-20 = 9; difference 8.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a80bffd-98a6-4b19-a907-1fc62d23a9bd', 'NC26.6.RD.4', 2, 'choice', 'Comparing the variability of two data sets', 'Over five days, Route 1 took 24, 25, 25, 26 and 25 minutes. Over the same five days, Route 2 took 15, 35, 22, 30 and 23 minutes. Which statement is supported by the data?', '["The two routes have the same mean time, but Route 1''s times vary more","The two routes have the same mean time, but Route 2''s times vary more","Route 2 has the greater mean time and the times vary less","Route 1 has the greater mean time and the times vary more"]', 'The two routes have the same mean time, but Route 2''s times vary more', NULL, 'Both routes have a mean of 25 minutes ($125 \div 5$). Route 1''s times are close together (range 2), and Route 2''s are spread out (range 20), so Route 2 varies more.', 'checked', '{"lint":[],"solve":{"answer":"The two routes have the same mean time, but Route 2''s times vary more","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Route 1 total 125, mean 25, values 24-26. Route 2: 15+35+22+30+23 = 125, mean 25, range 20. Same mean, Route 2 varies more.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c6feea9-9cdd-4082-8535-1bcf9035b292', 'NC26.6.RD.4', 2, 'numeric', 'Comparing the variability of two data sets', 'Data set A has a range of 12. Data set B has a range twice as large as the range of A. The least value in B is 5. What is the greatest value in B?', '[]', '29', '5+2*12', 'The range of B is $2 \times 12 = 24$. The greatest value is the least value plus the range: $5 + 24 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range of B = 24; greatest = 5 + 24 = 29.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d52d2f5-5f12-4841-942a-27e60e5f3f63', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'The yearly pay of seven workers at a shop, in thousands of dollars, is 28, 30, 30, 32, 33, 35 and 150. The mean is about 48 and the median is 32. Which statement is best?', '["The median is better, because the 150 pulls the mean far above the pay of most workers","The mean is better, because it uses every value and is the greater number","The mean and the median describe a typical pay equally well","Neither is useful, because the seven pay values are different"]', 'The median is better, because the 150 pulls the mean far above the pay of most workers', NULL, 'Six of the seven workers earn between 28 and 35 thousand dollars, so a typical pay is about 32. The one pay of 150 pulls the mean up to about 48, which is higher than what any of those six earn.', 'checked', '{"lint":[],"solve":{"answer":"The median is better, because the 150 pulls the mean far above the pay of most workers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 338/7 = 48.3 (about 48); median 32. The 150 is an outlier pulling the mean above 6 of 7 workers, so the median is better.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3c4b93-7a11-41dd-a0a6-516ac2a0a8ce', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'For which data set is the median a better description of the center than the mean?', '["10, 11, 12, 13, 14","5, 6, 7, 8, 9","3, 4, 4, 5, 90","21, 22, 22, 23, 24"]', '3, 4, 4, 5, 90', NULL, 'In the first set the value 90 is far from the others, so the mean (21.2) is higher than four of the five values, while the median (4) is typical. The other sets have values close together, so the mean and the median agree.', 'checked', '{"lint":[],"solve":{"answer":"3, 4, 4, 5, 90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 3, 4, 4, 5, 90 has an outlier (mean 21.2 vs median 4). Others are symmetric, mean = median.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('298ad5ba-8db5-4a54-947d-8d6edd84a70a', 'NC26.6.RD.4', 2, 'choice', 'Choosing the best measure of center', 'A student''s five math quiz scores are 40, 78, 80, 82 and 85. The mean is 73 and the median is 80. Which measure better describes this student''s typical score, and why?', '["The mean of 73, because it is the middle score when the scores are in order","The median of 80, because the one very low score of 40 pulls the mean below the other four scores","The median of 80, because it is the total of all five scores divided by 5","The mean of 73, because it is higher than most of the five scores"]', 'The median of 80, because the one very low score of 40 pulls the mean below the other four scores', NULL, 'Four of the five scores are between 78 and 85, so a typical score is about 80. The very low score of 40 pulls the mean down to 73, which is below four of the five scores. The median is the middle score; the mean is the total divided by 5.', 'checked', '{"lint":[],"solve":{"answer":"The median of 80, because the one very low score of 40 pulls the mean below the other four scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 365/5 = 73, median 80. Outlier 40 pulls mean below the other four scores (78,80,82,85); median is typical.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3312d8f3-1946-4d39-8266-ba5d03423090', 'NC26.6.RD.4', 3, 'numeric', 'How adding a value changes a mean', 'The mean of 5 numbers is 20. A sixth number, 32, is added to the set. What is the mean of all 6 numbers?', '[]', '22', '(5*20+32)/6', 'The first 5 numbers add to $5 \times 20 = 100$. With 32 added the total is $132$ for 6 numbers, and $132 \div 6 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of 5 = 100. Add 32: 132. Mean = 132 / 6 = 22.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1524faa6-be56-41e4-9b6e-37a7c2098710', 'NC26.6.RD.4', 3, 'numeric', 'How an outlier changes the mean', 'A data set is 4, 5, 6, 7 and 8. The 8 is changed to 38. By how much does the mean increase?', '[]', '6', '(4+5+6+7+38)/5-(4+5+6+7+8)/5', 'The original total is $30$, so the mean is $30 \div 5 = 6$. The new total is $60$, so the new mean is $60 \div 5 = 12$. The mean increases by $12 - 6 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum rises by 38 - 8 = 30; mean rises by 30 / 5 = 6 (from 6 to 12).","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f174fcfc-0ec6-4670-bf94-864497c47c36', 'NC26.6.RD.4', 3, 'choice', 'Building a data set with a given mean and median', 'Which set of numbers has a mean of 10 and a median of 8?', '["$8, 8, 9, 12, 13$","$5, 8, 10, 13, 14$","$4, 6, 8, 9, 10$","$6, 8, 8, 12, 16$"]', '$6, 8, 8, 12, 16$', NULL, 'For $6, 8, 8, 12, 16$: the total is 50, so the mean is $50 \div 5 = 10$, and the middle number is 8. The set $8, 8, 9, 12, 13$ has mean 10 but median 9; $5, 8, 10, 13, 14$ has mean 10 but median 10; and $4, 6, 8, 9, 10$ has median 8 but a mean of 7.4.', 'checked', '{"lint":[],"solve":{"answer":"$6, 8, 8, 12, 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 50, mean 10, median 9. B: sum 50, mean 10, median 10. C: sum 37, mean 7.4. D: 6+8+8+12+16 = 50, mean 10, median 8. Only D.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82292d27-c853-4295-8a87-b82946b37249', 'NC26.6.RD.4', 3, 'choice', 'The mean as a balance point or fair share', 'Five values have a mean of 30. Four of them are 4 below the mean, 7 below the mean, 6 above the mean and 3 above the mean. Where is the fifth value?', '["2 below the mean","At the mean","2 above the mean","9 above the mean"]', '2 above the mean', NULL, 'The distances must balance. Below the mean: $4 + 7 = 11$. Above the mean so far: $6 + 3 = 9$. The fifth value must add $11 - 9 = 2$ more on the above side, so it is 2 above the mean (the value 32).', 'checked', '{"lint":[],"solve":{"answer":"2 above the mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations must sum to 0: -4 -7 +6 +3 = -2, so the fifth deviation is +2: 2 above the mean (value 32).","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23eb264d-e600-4f6a-9bd2-1a35c1b54eb2', 'NC26.6.RD.4', 3, 'choice', 'The mean as a balance point or fair share', 'Which data set has a mean of 6?', '["3, 5, 6, 7, 10","2, 4, 6, 8, 12","4, 5, 6, 6, 8","3, 5, 6, 7, 9"]', '3, 5, 6, 7, 9', NULL, 'The mean is the total divided by the number of values. $3+5+6+7+9 = 30$ and $30 \div 5 = 6$. The other sets add up to 31, 32 and 29, so their means are 6.2, 6.4 and 5.8. All four sets have a median of 6, but only one has a mean of 6.', 'checked', '{"lint":[],"solve":{"answer":"3, 5, 6, 7, 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 29, 32, 30, 31. Only 30/5 = 6, i.e. 3, 5, 6, 7, 9.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddaaa0d3-b96e-4a18-9334-06cc262d7f2c', 'NC26.6.RD.4', 3, 'choice', 'The mean as a balance point or fair share', 'Ali levels five stacks of 3, 4, 9, 2 and 7 cubes by moving cubes from taller stacks onto shorter ones until all five stacks are the same height. What is the fewest number of cubes he has to move?', '["4","6","5","25"]', '6', '(9-5)+(7-5)', 'There are $3+4+9+2+7 = 25$ cubes, so each stack ends with $25 \div 5 = 5$ cubes. The stack of 9 gives away $9 - 5 = 4$ cubes and the stack of 7 gives away $7 - 5 = 2$ cubes, so $4 + 2 = 6$ cubes move.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 3+4+9+2+7 = 25; level height 5. Excess above 5: 9 has 4, 7 has 2; total 6 cubes must move (each moved cube leaves a tall stack). Fewest = 6.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bbada67-a12f-42f3-89dd-200bb86a903c', 'NC26.6.RD.4', 3, 'numeric', 'The mean as a balance point or fair share', 'Six friends share their trading cards equally, and each ends up with 14 cards. Before sharing, five of them had 9, 12, 20, 15 and 8 cards. How many cards did the sixth friend have before sharing?', '[]', '20', '6*14-9-12-20-15-8', 'Six friends with 14 cards each have $6 \times 14 = 84$ cards in all. The five known friends had $9 + 12 + 20 + 15 + 8 = 64$ cards, so the sixth had $84 - 64 = 20$ cards.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 6*14 = 84. 9+12+20+15+8 = 64. Sixth = 84-64 = 20.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00db0187-13a2-4409-b258-78625e11c1e7', 'NC26.6.RD.4', 3, 'choice', 'Finding a mean', 'A shop sold 36, 42, 29, 51 and 38 sandwiches on five days. What is the mean number of sandwiches sold per day?', '["38","39.2","49","196"]', '39.2', '(36+42+29+51+38)/5', 'The sales add up to $36 + 42 + 29 + 51 + 38 = 196$. Dividing by 5 days gives $196 \div 5 = 39.2$. The number 38 is the median, 49 comes from dividing by 4, and 196 is the total.', 'checked', '{"lint":[],"solve":{"answer":"39.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36+42+29+51+38 = 196; 196/5 = 39.2.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b177400-d174-4b4e-9d51-d41c6f25441d', 'NC26.6.RD.4', 3, 'choice', 'Finding a mean', 'On a quiz scored out of 10, 2 students scored 6, 3 students scored 7, 4 students scored 8 and 1 student scored 9. What is the mean score?', '["7.5","7.4","8","74"]', '7.4', '(2*6+3*7+4*8+1*9)/10', 'There are $2 + 3 + 4 + 1 = 10$ students. The total of the scores is $2 \times 6 + 3 \times 7 + 4 \times 8 + 1 \times 9 = 12 + 21 + 32 + 9 = 74$, so the mean is $74 \div 10 = 7.4$. The number 7.5 is the mean of 6, 7, 8 and 9, and 8 is the score that most students got.', 'checked', '{"lint":[],"solve":{"answer":"7.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 students. Total 2*6+3*7+4*8+1*9 = 12+21+32+9 = 74. 74/10 = 7.4.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38ef8f52-6424-4c71-94b5-5801297a2080', 'NC26.6.RD.4', 3, 'numeric', 'Finding a mean', 'Find the mean of the six numbers 98, 103, 101, 97, 99 and 102.', '[]', '100', '(98+103+101+97+99+102)/6', 'The numbers add up to $98 + 103 + 101 + 97 + 99 + 102 = 600$, and $600 \div 6 = 100$. A shortcut: each number is a small step from 100 (-2, +3, +1, -3, -1, +2), and those steps add up to 0.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations from 100: -2,+3,+1,-3,-1,+2 = 0, so mean 100 (sum 600/6).","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb02d388-5cb9-47db-b31d-fe3f86a6d9a2', 'NC26.6.RD.4', 3, 'numeric', 'Finding a mean', 'The rainfall on five days, in centimeters, was 0.4, 1.2, 0.8, 2 and 0.6. What was the mean rainfall per day, in centimeters?', '[]', '1', '(0.4+1.2+0.8+2+0.6)/5', 'The rainfall adds up to $0.4 + 1.2 + 0.8 + 2 + 0.6 = 5$ centimeters. Dividing by 5 days gives $5 \div 5 = 1$ centimeter per day.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4+1.2+0.8+2+0.6 = 5.0; 5/5 = 1.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bb9a751-2aa4-4646-9ea1-68eeeea8145e', 'NC26.6.RD.4', 3, 'choice', 'Finding a mean', 'Which number is the mean of 1.5, 2.5, 4 and 8?', '["3.25","16","3.2","4"]', '4', '(1.5+2.5+4+8)/4', 'The numbers add up to $1.5 + 2.5 + 4 + 8 = 16$, and $16 \div 4 = 4$. The number 3.25 is the median, 16 is the total, and 3.2 comes from dividing by 5.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5+2.5+4+8 = 16; 16/4 = 4.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6146cee-67e2-483e-84fd-b88ece511d03', 'NC26.6.RD.4', 3, 'choice', 'Finding a median', 'A data set has 10 values. When they are put in order, the 5th value is 14 and the 6th value is 19. What is the median?', '["14","16.5","19","33"]', '16.5', '(14+19)/2', 'With 10 values, the median is halfway between the 5th and 6th values: $(14 + 19) \div 2 = 16.5$.', 'checked', '{"lint":[],"solve":{"answer":"16.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median = (14+19)/2 = 16.5.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbbcd412-a3a4-4750-a008-1cbdf0621ae0', 'NC26.6.RD.4', 3, 'choice', 'Finding a median', 'Which data set has a median of 12?', '["5, 9, 11, 13, 20, 24","6, 9, 14, 15, 30","12, 12, 12, 13, 25, 40","3, 12, 13, 14, 18"]', '5, 9, 11, 13, 20, 24', NULL, 'For the first set there are 6 values, so the median is halfway between the 3rd and 4th: $(11 + 13) \div 2 = 12$. The other sets have medians 14, 12.5 and 13, even though some of them contain a 12.', 'checked', '{"lint":[],"solve":{"answer":"5, 9, 11, 13, 20, 24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians: 13; (11+13)/2 = 12; 14; (12+13)/2 = 12.5. Only 5, 9, 11, 13, 20, 24.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7decb1ad-66f7-4a37-8151-2f97c6898145', 'NC26.6.RD.4', 3, 'numeric', 'Finding a median', 'The four numbers 5, 8, n and 20 are in order, so n is between 8 and 20. Their median is 11. What is n?', '[]', '14', '11*2-8', 'With 4 values, the median is halfway between the 2nd and 3rd values: $(8 + n) \div 2 = 11$. So $8 + n = 22$ and $n = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median = (8+n)/2 = 11, so n = 14 (between 8 and 20).","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcdde0b1-27a8-418c-90dc-c9cb9680005f', 'NC26.6.RD.4', 3, 'numeric', 'Finding a median', 'A survey of 25 students asked how many siblings each has. Six students have 0 siblings, 9 students have 1 sibling, 7 students have 2 siblings and 3 students have 3 siblings. What is the median number of siblings?', '[]', '1', '1', 'With 25 values in order, the median is the 13th value. The first 6 values are 0, and the next 9 values (the 7th to 15th) are 1, so the 13th value is 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6+9+7+3 = 25; median is the 13th. Values 0 occupy 1-6, value 1 occupies 7-15. 13th = 1.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
