INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1e0f728-39c0-45f4-b1fc-cd1b75bef971', 'NC26.6.RD.4', 3, 'choice', 'Finding a median', 'A set of 9 numbers has a median of 25. Which statement must be true?', '["When the numbers are put in order, the 4th number is 25","The 9 numbers add up to 225","When the numbers are put in order, the 5th number is 25","The number 25 appears more than once"]', 'When the numbers are put in order, the 5th number is 25', NULL, 'With 9 values, the median is the 5th value when they are in order, so the 5th number must be 25. The others need not be true: the numbers could add up to anything, and 25 could appear only once.', 'checked', '{"lint":[],"solve":{"answer":"When the numbers are put in order, the 5th number is 25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 9 ordered values the median is the 5th, so the 5th is 25. Sum 225 would need mean 25, not required; repetition not required.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5915c6f7-088f-46bb-8b87-dc3864e173ca', 'NC26.6.RD.4', 3, 'choice', 'Using a mean to find a missing value or a total', 'The mean of 6 numbers is 9. When a seventh number is added, the mean of the 7 numbers is 10. What is the seventh number?', '["10","16","19","70"]', '16', '7*10-6*9', 'The first 6 numbers add up to $6 \times 9 = 54$. All 7 numbers add up to $7 \times 10 = 70$. The seventh number is $70 - 54 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old total 54, new total 70; seventh = 16.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2991651-3429-4a1e-beda-9fccd62e76c8', 'NC26.6.RD.4', 3, 'choice', 'Using a mean to find a missing value or a total', 'The mean of 8 numbers is 12. One number is removed, and the mean of the remaining 7 numbers is 11. What number was removed?', '["1","11","19","77"]', '19', '8*12-7*11', 'The 8 numbers add up to $8 \times 12 = 96$. The remaining 7 numbers add up to $7 \times 11 = 77$. The number removed is $96 - 77 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old total 96, remaining 77; removed = 19.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab1382d6-b4e8-4ddc-ac28-06df20c07b69', 'NC26.6.RD.4', 3, 'choice', 'Using a mean to find a missing value or a total', 'After four quizzes, Omar''s mean score is 82. What score does he need on the fifth quiz to raise his mean to 84?', '["84","92","420","83"]', '92', '5*84-4*82', 'After four quizzes, his scores add up to $4 \times 82 = 328$. For a mean of 84 after five quizzes, they must add up to $5 \times 84 = 420$. He needs $420 - 328 = 92$ on the fifth quiz.', 'checked', '{"lint":[],"solve":{"answer":"92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Current total 4*82 = 328; needed total 5*84 = 420; fifth = 92.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bb0d4a4-359a-4706-a888-2b980ed23912', 'NC26.6.RD.4', 3, 'choice', 'Using a mean to find a missing value or a total', 'A class of 10 students has a mean score of 70 on a test. A second class of 15 students has a mean score of 80 on the same test. What is the mean score of all 25 students together?', '["76","75","1900","150"]', '76', '(10*70+15*80)/25', 'The first class''s scores add up to $10 \times 70 = 700$ and the second class''s to $15 \times 80 = 1200$. Together, $700 + 1200 = 1900$ over 25 students gives $1900 \div 25 = 76$. It is not 75, because the larger class counts for more.', 'checked', '{"lint":[],"solve":{"answer":"76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10*70 = 700, 15*80 = 1200; total 1900; 1900/25 = 76.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa2babdb-0f91-4d5d-a326-104bdbc7c5ee', 'NC26.6.RD.4', 3, 'choice', 'How adding, removing or changing a value affects the mean and median', 'The mean weight of 6 puppies is 15 pounds. The heaviest puppy, which weighs 25 pounds, is sold. What is the mean weight, in pounds, of the 5 puppies that are left?', '["15","13","10","65"]', '13', '(6*15-25)/5', 'The 6 puppies weigh $6 \times 15 = 90$ pounds in all. Without the 25-pound puppy, the other 5 weigh $90 - 25 = 65$ pounds, so their mean is $65 \div 5 = 13$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6*15 = 90; minus 25 = 65; 65/5 = 13.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d539a917-a5d2-4cb3-bb25-fdc4a4997247', 'NC26.6.RD.4', 3, 'choice', 'How adding, removing or changing a value affects the mean and median', 'The data set is 2, 4, 6, 8 and 10. Which change leaves the median the same but raises the mean?', '["Change the 2 to 0","Change the 6 to 9","Change the 8 to 3","Change the 10 to 30"]', 'Change the 10 to 30', NULL, 'Changing 10 to 30 leaves 6 in the middle, so the median is still 6, and the total rises from 30 to 50, so the mean rises. Changing 2 to 0 keeps the median but lowers the mean. Changing 6 to 9 makes the median 8, and changing 8 to 3 makes the median 4.', 'checked', '{"lint":[],"solve":{"answer":"Change the 10 to 30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10->30: median 6, mean 10 (up). 6->9: median 8. 2->0: mean down. 8->3: median 4. Only the first.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa943a6e-bf1c-41b5-8a68-e3423a6514ca', 'NC26.6.RD.4', 3, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'The mean of a data set is 5. Every value is multiplied by 3, and then 2 is added to every result. What is the mean of the new data set?', '[]', '17', '3*5+2', 'Multiplying every value by 3 multiplies the mean by 3, giving 15. Adding 2 to every value adds 2 to the mean. The new mean is $3 \times 5 + 2 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean becomes 3*5 + 2 = 17.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd77f02c-133b-4fcf-84d5-1f5fe860ad36', 'NC26.6.RD.4', 3, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'Five numbers have a mean of 20. Two of them, 8 and 12, are replaced by 15 and 25. What is the mean of the new set of five numbers?', '[]', '24', '(5*20-8-12+15+25)/5', 'The original total is $5 \times 20 = 100$. Taking out $8 + 12 = 20$ and putting in $15 + 25 = 40$ makes the total $100 - 20 + 40 = 120$. The new mean is $120 \div 5 = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 100. Remove 8+12 = 20, add 15+25 = 40: total 120; 120/5 = 24.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ce86ac0-87cb-4d74-ab43-8071f6913234', 'NC26.6.RD.4', 3, 'numeric', 'How adding, removing or changing a value affects the mean and median', 'The mean of four numbers is 10. A fifth number is added to the set, and the mean of the five numbers is still 10. What is the fifth number?', '[]', '10', '5*10-4*10', 'The four numbers add up to $4 \times 10 = 40$. Five numbers with a mean of 10 add up to $5 \times 10 = 50$. The fifth number is $50 - 40 = 10$: a new value equal to the mean leaves the mean unchanged.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 40, new total 50; fifth = 10.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2c3672a-98f3-4ee9-b0ce-fb577f4f53f3', 'NC26.6.RD.4', 3, 'numeric', 'Comparing the variability of two data sets', 'The data are 3, 5, 6, 8, 9, 11, 12 and 15. The first quartile is the median of the lower half of the data, and the third quartile is the median of the upper half. What is the interquartile range (IQR), which is the third quartile minus the first quartile?', '[]', '6', '11.5-5.5', 'The lower half is 3, 5, 6, 8, with median $(5 + 6) \div 2 = 5.5$. The upper half is 9, 11, 12, 15, with median $(11 + 12) \div 2 = 11.5$. The IQR is $11.5 - 5.5 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower half 3,5,6,8: Q1 = 5.5. Upper half 9,11,12,15: Q3 = 11.5. IQR = 6.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8685a72-8672-4493-92cc-9347453cd623', 'NC26.6.RD.4', 3, 'choice', 'Comparing the variability of two data sets', 'Set X is 2, 6, 10, 14, 18. Set Y is 6, 8, 10, 12, 14. Which statement is true?', '["Set Y is more spread out: its range is 8, compared with 16 for Set X","The sets are equally spread out, because both have a mean of 10 and a median of 10","Set X is more spread out, because its median is greater than the median of Set Y","Set X is more spread out: its range is 16, compared with 8 for Set Y"]', 'Set X is more spread out: its range is 16, compared with 8 for Set Y', NULL, 'Both sets have a mean of 10 and a median of 10, so their centers are the same. The range of X is $18 - 2 = 16$ and the range of Y is $14 - 6 = 8$, so X varies more.', 'checked', '{"lint":[],"solve":{"answer":"Set X is more spread out: its range is 16, compared with 8 for Set Y","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range X = 16, range Y = 8; both have mean and median 10. X is more spread out.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0936791b-7dcf-4bc4-911d-0b6b933c2dd9', 'NC26.6.RD.4', 3, 'choice', 'Comparing the variability of two data sets', 'A data set is 15, 18, 20, 22 and 25. A new value, 30, is added to the set. By how many units does the range increase?', '["5","15","10","30"]', '5', '(30-15)-(25-15)', 'Before, the range is $25 - 15 = 10$. After adding 30, the range is $30 - 15 = 15$. It increases by $15 - 10 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old range 25-15 = 10; new 30-15 = 15; increase 5.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14cf1f08-672d-4187-9f06-41cbe799d7fd', 'NC26.6.RD.4', 3, 'numeric', 'Comparing the variability of two data sets', 'The 11 values 4, 6, 7, 9, 10, 12, 13, 15, 16, 18 and 21 are in order. The first quartile is the median of the lower half (not counting the middle value), and the third quartile is the median of the upper half (not counting the middle value). What is the interquartile range, which is the third quartile minus the first quartile?', '[]', '9', '16-7', 'The middle value is the 6th, which is 12. The lower half is 4, 6, 7, 9, 10, with median 7. The upper half is 13, 15, 16, 18, 21, with median 16. The IQR is $16 - 7 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median 12 (6th). Lower 4,6,7,9,10: Q1 = 7. Upper 13,15,16,18,21: Q3 = 16. IQR = 9.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3026ffc1-60f7-4d82-af3c-ed89e0547eff', 'NC26.6.RD.4', 3, 'numeric', 'Choosing the best measure of center', 'Kara has the data 2, 3, 3, 4, 4 and 5. She adds the value 40. Because 40 is so much greater than the other values, she decides that the median is the better measure of center. What is the median of the seven values?', '[]', '4', '4', 'In order, the seven values are 2, 3, 3, 4, 4, 5, 40. The median is the 4th value, which is 4. (The mean would be about 8.7, higher than six of the seven values.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,3,3,4,4,5,40: 7 values, 4th = 4.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5af4495-4fc2-4787-bb1d-c0884d492b20', 'NC26.6.RD.4', 3, 'choice', 'Choosing the best measure of center', 'In one year, 9 students had 0, 0, 0, 0, 1, 1, 2, 2 and 12 absences. The mean is 2 and the median is 1. A parent says a typical student misses about 2 days. Which response is best?', '["The mean of 2 is more typical, because it uses every value and the 12 is part of the data","The mean of 2 is more typical, because it is the middle value of the data","The median of 1 is more typical, because it is the greatest value that most students have","The median of 1 is more typical, because the 12 raises the mean above what most students have"]', 'The median of 1 is more typical, because the 12 raises the mean above what most students have', NULL, 'Eight of the nine students have 2 or fewer absences, and half of them have 0 or 1. The one student with 12 pulls the mean up to 2. The median, the middle value, is 1, so it is the better description of a typical student.', 'checked', '{"lint":[],"solve":{"answer":"The median of 1 is more typical, because the 12 raises the mean above what most students have","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 18/9 = 2; median 5th value = 1. Seven of nine students have fewer than 2 absences; the 12 pulls the mean up. Second option (first gives a false reason).","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ac346e1-c982-4ed8-bc77-da1c546bd183', 'NC26.6.RD.4', 3, 'choice', 'Choosing the best measure of center', 'Which situation is best summarized by the mean rather than the median?', '["Finding the typical house price on a street where one house costs ten times as much as the others","Finding what each of 4 siblings gets when they pool all of their savings and share it equally","Finding the typical age at a party where one guest is 70 and everyone else is about 10","Finding the typical pay at a company where the owner earns far more than everyone else"]', 'Finding what each of 4 siblings gets when they pool all of their savings and share it equally', NULL, 'Sharing a total equally is exactly what the mean does: total divided by the number of people. In the other situations, one unusual value would pull the mean far from the typical value, so the median is the better summary.', 'checked', '{"lint":[],"solve":{"answer":"Finding what each of 4 siblings gets when they pool all of their savings and share it equally","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pooling and sharing equally is exactly the mean (fair share). The other three have outliers, favouring the median.","run_id":"claude-code","at":"2026-10-17T20:24:21.827Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e38bcd8-2018-4ca0-887e-f8ee7042ba25', 'NC26.6.RD.5', 1, 'choice', 'What a comparison of means does and does not show', 'Two classes took the same quiz. The mean score in Class 1 was 18 and the mean score in Class 2 was 15. Which statement does this information support?', '["On average, Class 1 scored higher than Class 2","Every student in Class 1 scored higher than every student in Class 2","Class 1 had a smaller range of scores than Class 2","Class 1 had more students than Class 2"]', 'On average, Class 1 scored higher than Class 2', NULL, 'A higher mean tells us that, on average, Class 1 scored higher. It does not tell us about every student, the spread of the scores or the number of students.', 'checked', '{"lint":[],"solve":{"answer":"On average, Class 1 scored higher than Class 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means compare averages only; they say nothing about every individual, range, or class size.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60e249f6-06c4-481c-b973-829d1e200d0d', 'NC26.6.RD.5', 1, 'numeric', 'Describing spread with the range', 'A student recorded the hours of sleep that 10 classmates got last night: 7, 8, 8, 9, 9, 9, 9, 10, 10, 11. What is the range of the data in hours?', '[]', '4', '11-7', 'The range is the greatest value minus the least value: $11 - 7 = 4$ hours.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = 11 - 7 = 4.","run_id":"claude-code","at":"2026-10-17T18:34:35.292Z"}}', 'ai', NULL, NULL)
