INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22cce4ea-ac40-49c3-86e5-3846692323b9', 'NC26.6.RD.5', 1, 'numeric', 'Drawing an inference from the center of a data set', 'The mean cost of a lunch at the school cafeteria is 4 dollars. About how many dollars would 25 lunches cost in all?', '[]', '100', '25*4', 'If the mean cost is 4 dollars, 25 lunches cost about $25 \times 4 = 100$ dollars in all.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 * 4 = 100.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
