VALUES ('99638021-169b-42fe-87c5-ba4b7cf375ab', 'NC26.6.RD.5', 1, 'numeric', 'Communicating findings that the data support', 'In a survey of 40 students, 22 chose cats, 14 chose dogs and 4 chose fish as their favorite pet. How many more students chose cats than chose dogs?', '[]', '8', '22-14', '$22 - 14 = 8$, so 8 more students chose cats than dogs.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22 - 14 = 8.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
