INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12c6952f-c1c4-4879-a314-e45fb3073960', 'NC26.6.RD.5', 1, 'choice', 'Reflecting on the question and the methods of an investigation', 'A class wants to choose 20 students from the whole school to answer a survey. Which is the fairest way to choose them?', '["Put every student''s name in a hat and draw 20 names","Choose the 20 students who sit closest to the teacher","Choose the first 20 students who arrive at school","Choose the 20 students who are the class''s best friends"]', 'Put every student''s name in a hat and draw 20 names', NULL, 'Drawing names from a hat gives every student the same chance of being chosen. The other ways favor certain students, such as early arrivals or friends, and so can give a biased sample.', 'checked', '{"lint":[],"solve":{"answer":"Put every student''s name in a hat and draw 20 names","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawing names from a hat gives every student an equal chance.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
