INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('351df69b-7639-4a4a-b2ad-b4b23a6f8f40', 'NC26.6.RD.5', 1, 'numeric', 'Calculating the summary an investigation needs', 'A survey recorded the favorite color of some students: 6 chose red, 9 chose blue and 5 chose green. How many students were surveyed?', '[]', '20', '6+9+5', 'Add the counts: $6 + 9 + 5 = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 9 + 5 = 20.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
