INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74ab2ac5-7dc4-43f1-b48e-58af6ccc0b1f', 'NC26.6.RD.5', 1, 'numeric', 'Calculating the summary an investigation needs', 'Seven students slept 7, 8, 8, 9, 9, 9 and 10 hours last night. How many of them slept 9 hours or more?', '[]', '4', '3+1', 'Three students slept 9 hours and one slept 10 hours, so $3 + 1 = 4$ students slept 9 hours or more.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9, 9, 9, 10: 4 students.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
