INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b28f0d67-a86a-429d-9568-b05398125c26', 'NC26.6.RD.5', 1, 'numeric', 'Calculating the summary an investigation needs', 'Here are 12 values: 2, 3, 4, 4, 5, 5, 6, 7, 7, 8, 9 and 10. What fraction of the values are less than 5?', '[]', '1/3', '4/12', 'The values less than 5 are 2, 3, 4 and 4, which is 4 values out of 12. The fraction is $\frac{4}{12} = \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Less than 5: 2, 3, 4, 4 = 4 of 12 = 1/3.","run_id":"claude-code","at":"2026-10-17T20:24:21.867Z"}}', 'ai', NULL, NULL)
