INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee46237c-862b-494d-b6f1-f4705a117791', 'NC26.7.RPR.1', 1, 'choice', 'Test whether a relationship is proportional', 'Which taxi price shows a proportional relationship between the cost of a ride and the number of miles?', '["5 dollars to start, plus 3 dollars for each mile","3 dollars for each mile and no other charge","4 dollars for the first mile and 2 dollars for each mile after that","12 dollars for any ride up to 6 miles"]', '3 dollars for each mile and no other charge', NULL, 'A proportional relationship has a constant cost per mile and costs 0 for 0 miles. Only "3 dollars for each mile" does: 1 mile costs 3, 2 miles cost 6, 3 miles cost 9. The others have a starting fee, a changing price per mile, or a flat price.', 'checked', '{"lint":[],"solve":{"answer":"3 dollars for each mile and no other charge","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Proportional needs cost = k x miles with 0 cost at 0 miles and a constant rate. Only 3 dollars per mile with no other charge (c = 3m).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01b82f56-0da7-4fe5-85a2-a456843d02fd', 'NC26.7.RPR.1', 1, 'choice', 'Test whether a relationship is proportional', 'A table shows the pairs $(x, y)$: $(1, 4)$, $(2, 8)$, $(3, 12)$ and $(4, 16)$. Is $y$ proportional to $x$?', '["No, because $y$ is not equal to $x$","No, because $y$ keeps getting larger","Yes, because $y \\div x$ is 4 for every pair","No, because the table has no pair with $x = 0$"]', 'Yes, because $y \div x$ is 4 for every pair', NULL, '$4 \div 1$, $8 \div 2$, $12 \div 3$ and $16 \div 4$ are all 4, so $y = 4x$ and the relationship is proportional. A proportional relationship does not need $y = x$, may increase, and the table need not list $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"Yes, because $y \\div x$ is 4 for every pair","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/1 = 8/2 = 12/3 = 16/4 = 4, so y = 4x: proportional.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('304bf09a-e031-4a2e-86f2-be799832e358', 'NC26.7.RPR.1', 1, 'numeric', 'Test whether a relationship is proportional', 'Four pairs are listed: $(2, 6)$, $(3, 9)$, $(5, 14)$ and $(6, 18)$. Three follow one proportional relationship and one does not. What is the $x$-value of the pair that does not follow it?', '[]', '5', NULL, '$6 \div 2 = 3$, $9 \div 3 = 3$ and $18 \div 6 = 3$, so the relationship is $y = 3x$. But $14 \div 5 = 2.8$, not 3. The pair that does not fit is $(5, 14)$, so the $x$-value is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/2 = 9/3 = 18/6 = 3, but 14/5 = 2.8. The odd pair has x = 5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('577b8994-96af-43e1-a4a3-c6652c09ef7e', 'NC26.7.RPR.1', 1, 'numeric', 'Test whether a relationship is proportional', 'The graph of every proportional relationship passes through the point $(0, y)$. What is the value of $y$?', '[]', '0', NULL, 'In a proportional relationship $y = kx$. When $x = 0$, $y = k \times 0 = 0$. So every proportional relationship contains the point $(0, 0)$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = kx at x = 0 gives y = 0; the graph passes through the origin.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd8c53d2-5866-4690-8154-c859e7f0a1e2', 'NC26.7.RPR.1', 1, 'choice', 'Write and use an equation y = kx', 'Each ticket to a school play costs 7 dollars. Which equation gives the total cost $y$, in dollars, of $x$ tickets?', '["$y = x + 7$","$y = \\frac{x}{7}$","$x = 7y$","$y = 7x$"]', '$y = 7x$', NULL, 'The total cost is 7 dollars times the number of tickets: $y = 7x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 7x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total = 7 x number of tickets: y = 7x.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
