INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16979bbb-21da-4788-87d0-472fda85569b', 'NC26.7.RPR.1', 1, 'choice', 'Compare proportional relationships', 'At Store A, 4 apples cost 2 dollars. At Store B, 5 apples cost 3 dollars. Which store charges less for each apple, and how much is it?', '["Store B, 0.60 dollar","Store A, 2 dollars","Store B, 3 dollars","Store A, 0.50 dollar"]', 'Store A, 0.50 dollar', NULL, 'Store A: $2 \div 4 = 0.50$ dollar per apple. Store B: $3 \div 5 = 0.60$ dollar per apple. Store A charges less, 0.50 dollar for each apple.', 'checked', '{"lint":[],"solve":{"answer":"Store A, 0.50 dollar","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2/4 = 0.50 per apple. B: 3/5 = 0.60 per apple. Store A is cheaper at 0.50 dollar each.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
