INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90ee4e3d-74c2-437d-901b-be641138c7c1', 'NC26.7.RPR.1', 1, 'numeric', 'Compare proportional relationships', 'Car A travels 120 miles in 2 hours. Car B travels 150 miles in 3 hours. Each car goes at a constant speed. How many more miles per hour does Car A travel than Car B?', '[]', '10', '120/2-150/3', 'Car A: $120 \div 2 = 60$ miles per hour. Car B: $150 \div 3 = 50$ miles per hour. Car A is $60 - 50 = 10$ miles per hour faster.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 120/2 = 60 mph. B: 150/3 = 50 mph. 60 - 50 = 10.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
