INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94a8fcd0-13d5-4e74-94bd-d0f682147099', 'NC26.7.RPR.1', 1, 'choice', 'Compare proportional relationships', 'Runner P runs 30 meters in 5 seconds. Runner Q runs 35 meters in 7 seconds. Both run at constant speeds. Which statement is true?', '["Q is faster: 7 meters per second compared with 5 meters per second","P and Q run at the same speed","Q is faster, because 35 meters is more than 30 meters","P is faster: 6 meters per second compared with 5 meters per second"]', 'P is faster: 6 meters per second compared with 5 meters per second', NULL, 'P runs $30 \div 5 = 6$ meters each second. Q runs $35 \div 7 = 5$ meters each second. P is faster. Q runs farther in total but takes longer.', 'checked', '{"lint":[],"solve":{"answer":"P is faster: 6 meters per second compared with 5 meters per second","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 30/5 = 6 m/s. Q: 35/7 = 5 m/s. P faster.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
