INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9cd8a27-18bb-4050-83ba-426d762bc4d4', 'NC26.7.RPR.1', 1, 'numeric', 'Compare proportional relationships', 'Relationship A is $y = 5x$. In Relationship B, $y = 18$ when $x = 3$. Both relationships are proportional. What is the greater of the two constants of proportionality?', '[]', '6', '18/3', 'For A the constant is 5. For B it is $18 \div 3 = 6$. The greater constant is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: k = 5. B: k = 18/3 = 6. Greater is 6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
