INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0adceb1f-9c5c-4256-8e75-8325972d1fba', 'NC26.7.RPR.1', 1, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(3, 12)$ is on the graph of a proportional relationship between the hours $x$ Kim works and the dollars $y$ she earns. What does the point mean?', '["In 12 hours, Kim earns 3 dollars","In 3 hours, Kim earns 12 dollars","Kim earns 12 dollars each hour","Kim earns 3 dollars each hour"]', 'In 3 hours, Kim earns 12 dollars', NULL, 'A point $(x, y)$ means $x$ hours go with $y$ dollars, so $(3, 12)$ means 3 hours earn 12 dollars. That is $12 \div 3 = 4$ dollars for each hour.', 'checked', '{"lint":[],"solve":{"answer":"In 3 hours, Kim earns 12 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) = (3 hours, 12 dollars): in 3 hours she earns 12 dollars (rate 4 per hour, so the 3 and 12 per hour options are wrong).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
