INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17999180-15fa-4e93-ad72-c0218c2a48e8', 'NC26.7.RPR.1', 1, 'numeric', 'Interpret a point of a proportional relationship in context', 'The graph of a proportional relationship between the pounds of grapes $x$ and the cost $y$ in dollars passes through the point $(1, 3.25)$. What is the cost, in dollars, of 4 pounds of grapes?', '[]', '13', '3.25*4', 'The point $(1, 3.25)$ says 1 pound costs 3.25 dollars. For 4 pounds the cost is $3.25 \times 4 = 13$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unit rate 3.25 dollars per pound; 4 x 3.25 = 13.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
