INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('305e16da-6226-40c8-98e0-1367fc1e7c49', 'NC26.7.RPR.1', 1, 'choice', 'Interpret a point of a proportional relationship in context', 'The graph of a proportional relationship between the hours $x$ spent walking and the miles $y$ walked passes through the point $(0, 0)$. What does that point mean?', '["After 0 hours, 0 miles have been walked","The walker walks 0 miles every hour","The walk lasts 0 hours","The walker is 0 miles from home at all times"]', 'After 0 hours, 0 miles have been walked', NULL, 'The point $(0, 0)$ means that when $x = 0$ hours, $y = 0$ miles. Before any time has passed, no distance has been walked.', 'checked', '{"lint":[],"solve":{"answer":"After 0 hours, 0 miles have been walked","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0, 0) = 0 hours, 0 miles: before any walking, no distance covered.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
