INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3c8a014-c334-497f-a6bc-f1b43c7a52b8', 'NC26.7.RPR.1', 1, 'numeric', 'Interpret a point of a proportional relationship in context', 'A proportional relationship between the number of packs $x$ and the number of pens $y$ includes the point $(2, 14)$. How many pens are in 5 packs?', '[]', '35', '14/2*5', 'The point $(2, 14)$ says 2 packs have 14 pens, so 1 pack has $14 \div 2 = 7$ pens. Five packs have $7 \times 5 = 35$ pens.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14/2 = 7 pens per pack; 5 x 7 = 35.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
