INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dccbf4f-af2e-4f2a-877e-b8d7500719fb', 'NC26.7.RPR.1', 2, 'choice', 'Unit rate with fractions', 'A machine fills $\frac{1}{2}$ of a tank in 3 minutes. How many minutes does it take to fill 1 whole tank at this rate?', '["$1.5$","$3.5$","$\\frac{1}{6}$","$6$"]', '$6$', '3/(1/2)', 'A whole tank is twice as much as half a tank, so it takes twice as long: $3 \div \frac{1}{2} = 6$ minutes. ($\frac{1}{6}$ is the fraction of a tank filled each minute.)', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Half a tank in 3 min, so a whole tank in 3 / (1/2) = 6 min.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d14a19d3-3287-4913-ab2d-aa530fbea898', 'NC26.7.RPR.1', 2, 'numeric', 'Unit rate with fractions', 'A bamboo plant grows $\frac{3}{8}$ inch in $\frac{1}{4}$ of a day. How many inches does it grow in 1 day?', '[]', '3/2', '(3/8)/(1/4)', '$\frac{3}{8} \div \frac{1}{4} = \frac{3}{8} \times 4 = \frac{12}{8} = \frac{3}{2}$ inches, which is $1\frac{1}{2}$ inches.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/8) / (1/4) = 3/2 = 1.5 inches per day.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ddfe7ec-237d-4a47-9abd-7eb8a94dca28', 'NC26.7.RPR.1', 2, 'choice', 'Test whether a relationship is proportional', 'Which equation represents a proportional relationship?', '["$y = 0.75x$","$y = 0.75 + x$","$y = 2x + 3$","$y = 8 - x$"]', '$y = 0.75x$', NULL, 'A proportional relationship has the form $y = kx$: $y$ is a constant times $x$ with nothing added or subtracted. Only $y = 0.75x$ has that form.', 'checked', '{"lint":[],"solve":{"answer":"$y = 0.75x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only y = 0.75x has the form y = kx; the others have a constant added or subtracted.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4e1b64d-cf9a-4b87-a133-ebac510b5010', 'NC26.7.RPR.1', 2, 'choice', 'Test whether a relationship is proportional', 'Which description of a graph shows a proportional relationship?', '["A straight line that crosses the $y$-axis at $(0, 3)$","A straight line that passes through the origin","A curve that passes through the origin","A straight line that passes through $(1, 0)$"]', 'A straight line that passes through the origin', NULL, 'The graph of a proportional relationship is a straight line through the origin $(0, 0)$. A line crossing the $y$-axis at $(0, 3)$ or passing through $(1, 0)$ does not go through the origin, and a curve is not a straight line.', 'checked', '{"lint":[],"solve":{"answer":"A straight line that passes through the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A proportional graph is a straight line through the origin. (0,3) and (1,0) lines miss the origin; a curve is not proportional.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f9c1a16-4da0-45ec-b89d-db267c3bc110', 'NC26.7.RPR.1', 2, 'choice', 'Test whether a relationship is proportional', 'Only one of these sets of three points lies on the graph of a proportional relationship. Which set is it?', '["$(0.5, 3)$, $(2, 4.5)$, $(3.5, 6)$","$(0.5, 3)$, $(2, 12)$, $(3.5, 20)$","$(0.5, 3)$, $(2, 12)$, $(3.5, 21)$","$(0.5, 4)$, $(2, 13)$, $(3.5, 22)$"]', '$(0.5, 3)$, $(2, 12)$, $(3.5, 21)$', NULL, 'In the first set $y \div x$ is 6 each time: $3 \div 0.5$, $12 \div 2$ and $21 \div 3.5$. In the others the quotient changes: the second set follows $y = x + 2.5$, the third ends with $20 \div 3.5$, which is not 6, and the fourth follows $y = 6x + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$(0.5, 3)$, $(2, 12)$, $(3.5, 21)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Check y/x. A: 6, 2.25 no. B: 6, 6, 20/3.5 = 5.71 no. C: 8, 6.5 no. D: 3/0.5 = 6, 12/2 = 6, 21/3.5 = 6 yes.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8109ebce-ea99-48a3-b41d-91e2896c8ab1', 'NC26.7.RPR.1', 2, 'numeric', 'Test whether a relationship is proportional', 'For a proportional relationship, the pairs $(2, 7)$, $(4, 14)$ and $(6, c)$ must have the same $y \div x$. What is $c$?', '[]', '21', '7/2*6', '$y \div x = 7 \div 2 = 3.5$ for the first pair (and $14 \div 4 = 3.5$). So $c = 3.5 \times 6 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 7/2 = 3.5; c = 3.5 x 6 = 21.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4d70ff1-1e29-49c7-8515-4a4c3d55b8e4', 'NC26.7.RPR.1', 2, 'numeric', 'Test whether a relationship is proportional', 'The five pairs $(2, 5)$, $(4, 10)$, $(6, 14)$, $(8, 20)$ and $(10, 24)$ are tested against the rule $y = 2.5x$. How many of the pairs follow the rule?', '[]', '3', NULL, 'Compute $2.5x$ for each: $2.5 \times 2 = 5$ (yes), $2.5 \times 4 = 10$ (yes), $2.5 \times 6 = 15$ but $y = 14$ (no), $2.5 \times 8 = 20$ (yes), $2.5 \times 10 = 25$ but $y = 24$ (no). Three pairs follow the rule.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5x gives 5, 10, 15, 20, 25. Matches: (2,5), (4,10), (8,20). (6,14) and (10,24) fail. 3 pairs.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b840dd87-61e3-49db-af56-d8a1cccd322c', 'NC26.7.RPR.1', 2, 'choice', 'Write and use an equation y = kx', 'In a proportional relationship, $y = 2$ when $x = 3$, $y = 4$ when $x = 6$ and $y = 6$ when $x = 9$. Which equation matches?', '["$y = \\frac{3}{2}x$","$y = x - 1$","$y = \\frac{2}{3}x$","$y = 2x$"]', '$y = \frac{2}{3}x$', NULL, '$k = y \div x = 2 \div 3 = \frac{2}{3}$, and $4 \div 6$ and $6 \div 9$ agree. So $y = \frac{2}{3}x$. ($y = \frac{3}{2}x$ has the constant upside down.)', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{2}{3}x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 2/3 = 4/6 = 6/9 = 2/3, so y = (2/3)x. y = x - 1 fits (3,2) only.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066c93c7-64d3-4af2-a71a-84fdec2f37af', 'NC26.7.RPR.1', 2, 'numeric', 'Write and use an equation y = kx', 'A canoe rental costs the same amount for each hour. The cost $c$, in dollars, for $h$ hours is $c = 6.5h$. Jo pays 52 dollars. For how many hours does Jo rent the canoe?', '[]', '8', '52/6.5', 'Put $c = 52$ into the equation: $52 = 6.5h$, so $h = 52 \div 6.5 = 8$ hours.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 = 6.5h, h = 8.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55ca7978-6c07-43e2-b5d6-0bf594f37688', 'NC26.7.RPR.1', 2, 'choice', 'Write and use an equation y = kx', 'A recipe uses 3 cups of flour for every 2 cups of sugar. Which equation gives the cups of flour $f$ needed for $s$ cups of sugar?', '["$f = \\frac{2}{3}s$","$f = s + 1$","$f = \\frac{3}{2}s$","$s = \\frac{3}{2}f$"]', '$f = \frac{3}{2}s$', NULL, 'There are $\frac{3}{2}$ cups of flour for each cup of sugar, so $f = \frac{3}{2}s$. ($f = \frac{2}{3}s$ and $s = \frac{3}{2}f$ have the quantities the wrong way round.)', 'checked', '{"lint":[],"solve":{"answer":"$f = \\frac{3}{2}s$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f/s = 3/2, so f = (3/2)s. Check s = 2: f = 3.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8fd05a2-7d6a-4d1a-a6bd-54b81d03b47b', 'NC26.7.RPR.1', 2, 'numeric', 'Write and use an equation y = kx', 'The equation $y = kx$ fits a table where $y = 5.4$ when $x = 3$, $y = 9$ when $x = 5$ and $y = 14.4$ when $x = 8$. What is $y$ when $x = 12$?', '[]', '21.6', '5.4/3*12', '$k = 5.4 \div 3 = 1.8$ (check: $9 \div 5 = 1.8$ and $14.4 \div 8 = 1.8$). So $y = 1.8x$ and when $x = 12$, $y = 1.8 \times 12 = 21.6$.', 'checked', '{"lint":[],"solve":{"answer":"21.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 5.4/3 = 9/5 = 14.4/8 = 1.8; y = 1.8 x 12 = 21.6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2630073-e102-4207-898e-9effd6a03e56', 'NC26.7.RPR.1', 2, 'choice', 'Compare proportional relationships', 'Machine A fills $y$ liters in $x$ minutes, where $y = 2.4x$. Machine B fills 11 liters in 5 minutes. Both work at constant rates. Which statement is true?', '["Machine A fills 0.2 liter more each minute than Machine B","Machine B fills 0.2 liter more each minute than Machine A","Machine A fills 1 liter more each minute than Machine B","The two machines fill at the same rate"]', 'Machine A fills 0.2 liter more each minute than Machine B', NULL, 'Machine A fills 2.4 liters each minute. Machine B fills $11 \div 5 = 2.2$ liters each minute. A fills $2.4 - 2.2 = 0.2$ liter more each minute. (In 5 minutes A fills 12 liters, 1 more than B, but that is not the amount per minute.)', 'checked', '{"lint":[],"solve":{"answer":"Machine A fills 0.2 liter more each minute than Machine B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2.4 L/min. B: 11/5 = 2.2 L/min. A fills 0.2 L more each minute.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50b94145-d41f-46d6-b7be-851f5be2d30f', 'NC26.7.RPR.1', 2, 'numeric', 'Compare proportional relationships', 'A car travels at a constant speed given by $d = 48t$, where $d$ is miles and $t$ is hours. A truck travels 135 miles in 3 hours at a constant speed. In 5 hours, how many more miles does the car travel than the truck?', '[]', '15', '48*5-135/3*5', 'In 5 hours the car travels $48 \times 5 = 240$ miles. The truck goes $135 \div 3 = 45$ miles each hour, so $45 \times 5 = 225$ miles. The car goes $240 - 225 = 15$ miles farther.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Car 48 mph; truck 135/3 = 45 mph. In 5 h: 240 - 225 = 15 miles.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09c4edf2-4426-4aa5-8aed-4978be69dab0', 'NC26.7.RPR.1', 2, 'choice', 'Compare proportional relationships', 'Plant A grows 12 cm in 4 weeks. Plant B grows $h$ cm in $w$ weeks, where $h = 2.5w$. Plant C grows 7 cm in 2 weeks. All grow at constant rates. Which plant grows the least each week?', '["Plant A","Plant B","Plant C","All three grow equally fast"]', 'Plant B', NULL, 'Plant A grows $12 \div 4 = 3$ cm a week, Plant B grows 2.5 cm a week and Plant C grows $7 \div 2 = 3.5$ cm a week. Plant B grows the least.', 'checked', '{"lint":[],"solve":{"answer":"Plant B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 12/4 = 3 cm/wk. B: 2.5 cm/wk. C: 7/2 = 3.5 cm/wk. Least is B.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96319077-6cf4-4c17-8a95-356d2de9d0db', 'NC26.7.RPR.1', 2, 'choice', 'Interpret a point of a proportional relationship in context', 'The graph of a proportional relationship between the cups of flour $x$ and the loaves of bread $y$ has the equation $y = 1.5x$. Which point on the graph shows the number of loaves made from 1 cup of flour?', '["$(1.5, 1)$","$(2, 3)$","$(0, 1.5)$","$(1, 1.5)$"]', '$(1, 1.5)$', NULL, 'The point for 1 cup of flour has $x = 1$, and then $y = 1.5 \times 1 = 1.5$. So the point is $(1, 1.5)$. The point $(2, 3)$ is on the graph but shows 2 cups, and $(1.5, 1)$ and $(0, 1.5)$ are not on the graph.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 1.5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 1 cup gives y = 1.5 loaves: point (1, 1.5).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('349f059b-2337-4fb2-8a26-deba7324d856', 'NC26.7.RPR.1', 2, 'numeric', 'Interpret a point of a proportional relationship in context', 'The point $(4, 10)$ is on the graph of a proportional relationship between the miles $x$ a bus travels and the minutes $y$ it takes. How many minutes does the bus take to travel 6.4 miles?', '[]', '16', '10/4*6.4', '$(4, 10)$ says 4 miles take 10 minutes, so 1 mile takes $10 \div 4 = 2.5$ minutes. For 6.4 miles: $2.5 \times 6.4 = 16$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 10/4 = 2.5 minutes per mile; 6.4 x 2.5 = 16 minutes.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7f8ae0c-c68f-4ba3-a043-db8ece35a7ba', 'NC26.7.RPR.1', 2, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(8, 6)$ is on the graph of a proportional relationship between the laps $x$ a runner completes and the minutes $y$ it takes. Which statement is true?', '["Each lap takes $\\frac{3}{4}$ minute","Each lap takes $\\frac{4}{3}$ minutes","The runner completes $\\frac{3}{4}$ lap each minute","Each lap takes 2 minutes"]', 'Each lap takes $\frac{3}{4}$ minute', NULL, '8 laps take 6 minutes, so one lap takes $6 \div 8 = \frac{3}{4}$ minute. (The runner completes $8 \div 6 = \frac{4}{3}$ laps each minute.)', 'checked', '{"lint":[],"solve":{"answer":"Each lap takes $\\frac{3}{4}$ minute","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 laps take 6 minutes: 6/8 = 3/4 minute per lap. Laps per minute = 8/6 = 4/3, so the 3/4 lap per minute option is false, as are 4/3 and 2 minutes per lap.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('617585a6-2c30-4b27-81c4-3040f179da67', 'NC26.7.RPR.1', 2, 'numeric', 'Interpret a point of a proportional relationship in context', 'The points $(2, 7)$ and $(a, 24.5)$ are both on the graph of the same proportional relationship. What is $a$?', '[]', '7', '24.5/(7/2)', '$k = 7 \div 2 = 3.5$, so $y = 3.5x$. For $y = 24.5$: $x = 24.5 \div 3.5 = 7$, so $a = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 7/2 = 3.5; a = 24.5/3.5 = 7.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26b75ed9-46b2-489c-985a-cd8593c0fd07', 'NC26.7.RPR.1', 3, 'choice', 'Compare a unit rate from a description with one from an equation', 'Store A sells 3 pounds of apples for 7.50 dollars. At Store B, the cost $y$ in dollars of $x$ pounds is given by $y = 2.4x$. Which statement is true?', '["Store A costs 0.10 dollars less per pound.","Store B costs 0.10 dollars less per pound.","Store B costs 5.10 dollars less per pound.","The two stores charge the same price per pound."]', 'Store B costs 0.10 dollars less per pound.', NULL, 'Store A: $7.50 \div 3 = 2.50$ dollars per pound. Store B: $k = 2.4$ dollars per pound. Store B is cheaper by $2.50 - 2.40 = 0.10$ dollars per pound.', 'checked', '{"lint":[],"solve":{"answer":"Store B costs 0.10 dollars less per pound.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Store A: 7.50/3 = 2.50 dollars per pound. Store B: 2.40 per pound. B is cheaper by 2.50 - 2.40 = 0.10 dollars per pound.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dac47a5f-0ed4-4df6-a92c-37151c086f20', 'NC26.7.RPR.1', 3, 'numeric', 'Use a unit rate with decimals to find a missing value', 'A paint covers an area proportional to the amount used. 3.5 liters of paint cover 5.6 square meters. At this rate, how many square meters can 8 liters of paint cover?', '[]', '12.8', '5.6/3.5*8', 'One liter covers $5.6 \div 3.5 = 1.6$ square meters. So 8 liters cover $1.6 \times 8 = 12.8$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"12.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate = 5.6/3.5 = 1.6 square meters per liter. 8 x 1.6 = 12.8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d03f10eb-fe2c-4bee-ab4d-7ec1938ecc78', 'NC26.7.RPR.1', 3, 'choice', 'Find another point on a proportional relationship', 'A proportional relationship includes the point $(6, 15)$. Which point is also on this relationship?', '["$(10, 19)$","$(4, 13)$","$(4, 10)$","$(5, 2)$"]', '$(4, 10)$', NULL, 'The constant of proportionality is $15 \div 6 = 2.5$, so $y = 2.5x$. For $x = 4$, $y = 2.5 \times 4 = 10$, so $(4, 10)$ is on it. The other points do not have $y \div x = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 10)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 15/6 = 2.5. Check: (5,2): 0.4 no; (10,19): 1.9 no; (4,13): 3.25 no; (4,10): 2.5 yes.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f28c94c-2733-4cfd-af69-6b46d603ab9c', 'NC26.7.RPR.1', 3, 'choice', 'What stays constant in a proportional relationship', 'A proportional relationship has the pairs $(2, 5)$, $(4, 10)$ and $(6, 15)$. Which statement about it is NOT true?', '["$y - x$ is the same for every pair","$y \\div x$ is 2.5 for every pair","$y$ is 2.5 times as large as $x$","When $x$ goes up by 2, $y$ goes up by 5"]', '$y - x$ is the same for every pair', NULL, 'The differences $y - x$ are 3, 6 and 9, so they are not the same. The other statements are true: $5 \div 2$, $10 \div 4$ and $15 \div 6$ are all 2.5, and each time $x$ goes up by 2, $y$ goes up by 5.', 'checked', '{"lint":[],"solve":{"answer":"$y - x$ is the same for every pair","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 5/2 = 10/4 = 15/6 = 2.5 (true). y - x = 3, 6, 9: not the same, so that statement is NOT true. x up 2 gives y up 5 (true). y = 2.5x (true).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26b7f9d2-74a2-4394-830c-a7f0e51b89b5', 'NC26.7.RPR.1', 3, 'numeric', 'What stays constant in a proportional relationship', 'In a proportional relationship, $y = 1.5$ when $x = 0.4$. What is $y$ when $x = 2.4$?', '[]', '9', '1.5/0.4*2.4', '$2.4$ is 6 times $0.4$ ($0.4 \times 6 = 2.4$), so $y$ is 6 times $1.5$: $1.5 \times 6 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4/0.4 = 6, so y = 1.5 x 6 = 9. (k = 3.75; 3.75 x 2.4 = 9.)","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('607cc695-c34d-441d-9002-bfdc522e678b', 'NC26.7.RPR.1', 3, 'choice', 'What stays constant in a proportional relationship', 'The ratio $y : x$ is always $3 : 4$ in a proportional relationship. Which pair could be $(x, y)$?', '["$(9, 12)$","$(12, 11)$","$(12, 9)$","$(4, 7)$"]', '$(12, 9)$', NULL, 'The ratio $y : x$ is $3 : 4$, so $y$ is $\frac{3}{4}$ of $x$. For $(12, 9)$, $9 : 12 = 3 : 4$. The pair $(9, 12)$ has the numbers reversed, and $(12, 11)$ and $(4, 7)$ come from subtracting or adding instead of using the ratio.', 'checked', '{"lint":[],"solve":{"answer":"$(12, 9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 3/4. (4,7): 7/4 no. (12,11): no. (9,12): 12/9 = 4/3 no. (12,9): 9/12 = 3/4 yes.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f935153-eb38-4038-a457-16a0fcd92f26', 'NC26.7.RPR.1', 3, 'numeric', 'What stays constant in a proportional relationship', 'The cost is proportional to the number of items bought. 5 items cost 12 dollars. How many items can be bought for 28.8 dollars?', '[]', '12', '28.8/(12/5)', 'One item costs $12 \div 5 = 2.4$ dollars. The number of items for 28.8 dollars is $28.8 \div 2.4 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/5 = 2.4 dollars per item; 28.8/2.4 = 12 items.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b12a2922-ff5e-4bdc-acf4-2f200149ab26', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'In a proportional relationship, $y = 2.4$ when $x = 0.6$. What is the constant of proportionality $k$ in $y = kx$?', '[]', '4', '2.4/0.6', '$k = y \div x = 2.4 \div 0.6 = 4$. (Multiply both by 10 to get $24 \div 6 = 4$.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 2.4/0.6 = 4.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04282769-46d8-432a-af30-84eea38b747b', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A table for a proportional relationship lists $y = 11.2$ when $x = 2$, $y = 28$ when $x = 5$ and $y = 44.8$ when $x = 8$. What is the constant of proportionality?', '[]', '5.6', '11.2/2', '$k = 11.2 \div 2 = 5.6$. Check: $28 \div 5 = 5.6$ and $44.8 \div 8 = 5.6$.', 'checked', '{"lint":[],"solve":{"answer":"5.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11.2/2 = 5.6, 28/5 = 5.6, 44.8/8 = 5.6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc306e3a-0993-4aa3-9853-c3d4412c3297', 'NC26.7.RPR.1', 3, 'numeric', 'Constant of proportionality from a table or ordered pairs', 'A proportional relationship has the pairs $(\frac{1}{3}, \frac{5}{6})$, $(\frac{2}{3}, \frac{5}{3})$ and $(1, \frac{5}{2})$. What is the constant of proportionality?', '[]', '5/2', '(5/6)/(1/3)', '$k = y \div x$. For the first pair, $\frac{5}{6} \div \frac{1}{3} = \frac{5}{6} \times 3 = \frac{5}{2}$. The last pair gives $\frac{5}{2} \div 1 = \frac{5}{2}$ as well.', 'checked', '{"lint":[],"solve":{"answer":"5/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5/6)/(1/3) = 5/2; (5/3)/(2/3) = 5/2; (5/2)/1 = 5/2.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46e9a4f9-c7a8-409d-9451-f5b455876d40', 'NC26.7.RPR.1', 3, 'choice', 'Constant of proportionality from a table or ordered pairs', 'In the proportional relationship $y = 2.5x$, $x$ can also be written as a multiple of $y$: $x = ky$. What is $k$?', '["2.5","1.5","0.4","0.25"]', '0.4', '1/2.5', 'Divide both sides of $y = 2.5x$ by 2.5 to get $x = \frac{1}{2.5}y = 0.4y$. So $k = 0.4$. (2.5 is the constant the other way around, and the others do not come from $1 \div 2.5$.)', 'checked', '{"lint":[],"solve":{"answer":"0.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = y/2.5 = 0.4y, so k = 0.4.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d921df74-acd8-4a34-a3ce-61a30fc7cc26', 'NC26.7.RPR.1', 3, 'numeric', 'Unit rate with fractions', 'Lena walks $\frac{3}{4}$ mile in 15 minutes at a steady pace. At this rate, how many miles does she walk in 1 hour?', '[]', '3', '(3/4)/(15/60)', '15 minutes is $\frac{1}{4}$ of an hour. Miles per hour = $\frac{3}{4} \div \frac{1}{4} = 3$ miles. (Or: 1 hour is 4 times 15 minutes, so $\frac{3}{4} \times 4 = 3$.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 hour = 60 min = 4 x 15 min; 4 x 3/4 = 3 miles.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6562b913-e80c-4db8-b092-4246f64d9ec4', 'NC26.7.RPR.1', 3, 'numeric', 'Unit rate with fractions', 'A tap fills $1\frac{1}{2}$ liters in $\frac{3}{8}$ of a minute. At this rate, how many liters does it fill in $2\frac{1}{2}$ minutes?', '[]', '10', '1.5/(3/8)*2.5', 'Liters per minute = $1\frac{1}{2} \div \frac{3}{8} = \frac{3}{2} \times \frac{8}{3} = 4$. In $2\frac{1}{2}$ minutes the tap fills $4 \times 2.5 = 10$ liters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate = (3/2) / (3/8) = 4 liters per minute; 4 x 5/2 = 10 liters.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bba91a6d-b8d1-4953-a2b8-a28a3f045198', 'NC26.7.RPR.1', 3, 'choice', 'Unit rate with fractions', 'A car uses $\frac{3}{5}$ gallon of gas to travel 12 miles. Which statement is correct?', '["The car travels $\\frac{1}{20}$ mile on 1 gallon","The car travels 7.2 miles on 1 gallon","The car travels 20 miles on 1 gallon","The car travels 12 miles on 1 gallon"]', 'The car travels 20 miles on 1 gallon', NULL, 'Miles per gallon = $12 \div \frac{3}{5} = 12 \times \frac{5}{3} = 20$. ($\frac{1}{20}$ is gallons per mile, and 7.2 is $12 \times \frac{3}{5}$.)', 'checked', '{"lint":[],"solve":{"answer":"The car travels 20 miles on 1 gallon","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 / (3/5) = 20 miles per gallon.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75f59001-8d86-4309-8906-b0d0ae68b632', 'NC26.7.RPR.1', 3, 'choice', 'Unit rate with fractions', 'Which rate is the same as walking $\frac{2}{3}$ mile in $\frac{1}{4}$ hour?', '["$\\frac{1}{6}$ mile in 1 hour","$\\frac{3}{8}$ mile in 1 hour","$\\frac{2}{3}$ mile in 1 hour","4 miles in $1\\frac{1}{2}$ hours"]', '4 miles in $1\frac{1}{2}$ hours', NULL, 'The speed is $\frac{2}{3} \div \frac{1}{4} = \frac{8}{3}$ miles per hour. For 4 miles in $1\frac{1}{2}$ hours, $4 \div \frac{3}{2} = \frac{8}{3}$ as well. The others are $\frac{1}{6}$, $\frac{3}{8}$ and $\frac{2}{3}$ miles per hour.', 'checked', '{"lint":[],"solve":{"answer":"4 miles in $1\\frac{1}{2}$ hours","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)/(1/4) = 8/3 mi per hour. A: 2/3. B: 4/(3/2) = 8/3 yes. C: 3/8. D: 1/6.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d90811d5-310a-4dd4-bc92-1dcdd7b42d23', 'NC26.7.RPR.1', 3, 'numeric', 'Unit rate with fractions', 'Pat reads $\frac{1}{6}$ of a book in $\frac{1}{4}$ of an hour. At this rate, how many hours will it take Pat to read the whole book?', '[]', '3/2', '(1/4)/(1/6)', 'The whole book is 6 times $\frac{1}{6}$ of the book, so it takes 6 times as long: $6 \times \frac{1}{4} = \frac{3}{2}$ hours, which is $1\frac{1}{2}$ hours.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole book = 6 sixths; 6 x 1/4 = 3/2 = 1.5 hours. (Rate 2/3 book per hour; 1 / (2/3) = 1.5.)","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a71297c-03f1-48cd-95a9-1d5123c2e134', 'NC26.7.RPR.1', 3, 'choice', 'Test whether a relationship is proportional', 'Maria looks at the pairs $(1, 5)$, $(2, 9)$, $(3, 13)$ and $(4, 17)$. She says $y$ is proportional to $x$ because $y$ goes up by the same amount, 4, each time $x$ goes up by 1. Which is correct?', '["She is right, because the change in $y$ is always the same","She is wrong, because $y$ must stay the same when $x$ goes up","She is right, because $y$ is always greater than $x$","She is wrong, because $y \\div x$ is not the same for every pair"]', 'She is wrong, because $y \div x$ is not the same for every pair', NULL, '$y \div x$ is $5$, $4.5$, $\frac{13}{3}$ and $4.25$, which are not equal. The relationship is $y = 4x + 1$, a straight line that does not pass through the origin. A constant change in $y$ alone does not make a relationship proportional.', 'checked', '{"lint":[],"solve":{"answer":"She is wrong, because $y \\div x$ is not the same for every pair","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y/x = 5, 4.5, 13/3, 4.25: not constant (y = 4x + 1, not through origin). She is wrong for that reason.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a83a22f-f33e-48e3-948a-8e0ca7ce937c', 'NC26.7.RPR.1', 3, 'choice', 'Test whether a relationship is proportional', 'The pairs $(6, 4)$, $(9, 6)$ and $(15, 10)$ are given. Which statement, true for every pair, shows that $y$ is proportional to $x$?', '["$y \\div x$ equals $\\frac{2}{3}$","$y$ is larger when $x$ is larger","$x - y$ is the same","$x$ is a multiple of 3"]', '$y \div x$ equals $\frac{2}{3}$', NULL, '$4 \div 6$, $6 \div 9$ and $10 \div 15$ all equal $\frac{2}{3}$, which is what proportional means. The other statements do not show it: $x - y$ is 2, 3 and 5 (not the same), and "larger $x$ gives larger $y$" and "$x$ is a multiple of 3" do not show a constant ratio.', 'checked', '{"lint":[],"solve":{"answer":"$y \\div x$ equals $\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/6 = 6/9 = 10/15 = 2/3, constant, which shows proportionality. x - y = 2, 3, 5 not same. ''x multiple of 3'' and ''y larger when x larger'' are true but do not show proportionality.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c00b1e32-4d43-4539-8c9e-f8fff91c714b', 'NC26.7.RPR.1', 3, 'numeric', 'Test whether a relationship is proportional', 'A table has the pairs $(0.4, 1)$, $(1.2, 3)$ and $(x, 7.5)$. If $y$ is proportional to $x$, what is $x$?', '[]', '3', '7.5/(1/0.4)', '$y \div x = 1 \div 0.4 = 2.5$ (and $3 \div 1.2 = 2.5$). So $7.5 = 2.5x$ and $x = 7.5 \div 2.5 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 1/0.4 = 3/1.2 = 2.5; x = 7.5/2.5 = 3.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('693bc279-94a4-4bef-9e90-3e9138473a9d', 'NC26.7.RPR.1', 3, 'numeric', 'Test whether a relationship is proportional', 'The pairs $(2, 9)$, $(4, 17)$ and $(6, 25)$ are not proportional. If $y$ were proportional to $x$ and passed through $(2, 9)$, its $y$ at $x = 6$ would be greater than 25. By how much?', '[]', '2', '9/2*6-25', 'If $y$ were proportional through $(2, 9)$, then $y \div x = 4.5$ and at $x = 6$ we would get $y = 4.5 \times 6 = 27$. That is $27 - 25 = 2$ more than 25.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Through (2,9): k = 4.5; at x = 6, y = 27. 27 - 25 = 2.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df217bd6-f941-49b3-af38-72c3013b0c7b', 'NC26.7.RPR.1', 3, 'choice', 'Test whether a relationship is proportional', 'Which equation does NOT represent a proportional relationship?', '["$y = \\frac{x + 2}{3}$","$y = \\frac{x}{3}$","$y = 1.2x$","$y = \\frac{2x}{5}$"]', '$y = \frac{x + 2}{3}$', NULL, '$y = \frac{x + 2}{3}$ is the same as $y = \frac{1}{3}x + \frac{2}{3}$, which has $\frac{2}{3}$ added, so $y = \frac{2}{3}$ when $x = 0$ and $y \div x$ is not constant. The others are $y = kx$ with $k = \frac{1}{3}$, $1.2$ and $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{x + 2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2x, 2x/5 = 0.4x, x/3 are all kx. (x + 2)/3 = x/3 + 2/3 has a constant term: not proportional.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f0b37c4-586d-439f-a90f-db7743df8285', 'NC26.7.RPR.1', 3, 'choice', 'Write and use an equation y = kx', 'The graph of a proportional relationship passes through the point $(5, 12)$. Which equation represents the relationship?', '["$y = \\frac{5}{12}x$","$y = 2.4x$","$y = 7x$","$y = 60x$"]', '$y = 2.4x$', NULL, '$k = y \div x = 12 \div 5 = 2.4$, so $y = 2.4x$. Check with the point: $2.4 \times 5 = 12$. ($y = 7x$ uses the difference $12 - 5$ as the constant.)', 'checked', '{"lint":[],"solve":{"answer":"$y = 2.4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 12/5 = 2.4, so y = 2.4x.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d5d548d-9a70-45a3-ae1a-fa769ace9b71', 'NC26.7.RPR.1', 3, 'numeric', 'Write and use an equation y = kx', 'A proportional relationship is given by $y = \frac{5}{8}x$. What is $x$ when $y = 15$?', '[]', '24', '15/(5/8)', 'Put $y = 15$ into the equation: $15 = \frac{5}{8}x$. Multiply both sides by $\frac{8}{5}$: $x = 15 \times \frac{8}{5} = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 = (5/8)x, x = 15 x 8/5 = 24.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('824c6e65-a9c5-4c4b-b46f-af88403492d6', 'NC26.7.RPR.1', 3, 'choice', 'Write and use an equation y = kx', 'A pool fills at 12 gallons per minute, so the gallons $g$ in the pool after $m$ minutes is $g = 12m$. Which equation gives the minutes $m$ in terms of the gallons $g$?', '["$m = \\frac{g}{12}$","$m = 12g$","$m = g - 12$","$m = \\frac{12}{g}$"]', '$m = \frac{g}{12}$', NULL, 'Divide both sides of $g = 12m$ by 12 to get $m = \frac{g}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$m = \\frac{g}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g = 12m, so m = g/12.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba35d294-500d-48ac-a467-5fc224703483', 'NC26.7.RPR.1', 3, 'numeric', 'Write and use an equation y = kx', 'The price $p$, in dollars, of $n$ pencils is $p = 0.35n$. How many more dollars do 12 pencils cost than 8 pencils?', '[]', '1.4', '0.35*12-0.35*8', '12 pencils cost $0.35 \times 12 = 4.20$ dollars and 8 pencils cost $0.35 \times 8 = 2.80$ dollars. The difference is $4.20 - 2.80 = 1.40$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"1.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 0.35 = 4.20, 8 x 0.35 = 2.80; difference 1.40 (= 4 x 0.35).","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48cfd2da-4ccb-482c-888f-f7c5c1a17629', 'NC26.7.RPR.1', 3, 'numeric', 'Compare proportional relationships', 'Tap A fills $2\frac{1}{2}$ liters in $\frac{1}{2}$ of a minute. Tap B fills $4\frac{1}{2}$ liters in $\frac{3}{4}$ of a minute. How many more liters per minute does the faster tap fill than the slower tap?', '[]', '1', '4.5/(3/4)-2.5/(1/2)', 'Tap A: $2\frac{1}{2} \div \frac{1}{2} = 5$ liters per minute. Tap B: $4\frac{1}{2} \div \frac{3}{4} = \frac{9}{2} \times \frac{4}{3} = 6$ liters per minute. Tap B is faster, by $6 - 5 = 1$ liter per minute.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: (5/2)/(1/2) = 5 L/min. B: (9/2)/(3/4) = 6 L/min. 6 - 5 = 1.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088f4b2c-c4c2-4eda-8d14-0b8a6ca8549a', 'NC26.7.RPR.1', 3, 'choice', 'Compare proportional relationships', 'Runner P runs $d$ kilometers in $m$ minutes, where $d = 0.15m$. Runner Q runs 2.4 kilometers in 15 minutes. Runner R runs 3.5 kilometers in 25 minutes. All run at constant speeds. Who runs the most kilometers each minute?', '["Runner P","Runner R","Runner Q","Runners P and Q tie"]', 'Runner Q', NULL, 'P runs 0.15 kilometer each minute. Q runs $2.4 \div 15 = 0.16$ kilometer each minute. R runs $3.5 \div 25 = 0.14$ kilometer each minute. Q is the fastest.', 'checked', '{"lint":[],"solve":{"answer":"Runner Q","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 0.15 km/min. Q: 2.4/15 = 0.16. R: 3.5/25 = 0.14. Q is fastest.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6cca3a8-2bf7-40bc-a8aa-7fa0bb10d3fd', 'NC26.7.RPR.1', 3, 'choice', 'Compare proportional relationships', 'The graph of Line 1 passes through the origin and $(4, 10)$. The graph of Line 2 passes through the origin and $(10, 24)$. Which statement is true?', '["Line 2 has the greater constant of proportionality, 24 compared with 10","The two lines have the same constant of proportionality","Line 1 has the greater constant of proportionality, 2.5 compared with 2.4","Line 2 has the greater constant of proportionality, 10 compared with 4"]', 'Line 1 has the greater constant of proportionality, 2.5 compared with 2.4', NULL, 'Line 1: $k = 10 \div 4 = 2.5$. Line 2: $k = 24 \div 10 = 2.4$. Line 1 has the greater constant of proportionality. Comparing the points'' numbers directly does not compare the constants.', 'checked', '{"lint":[],"solve":{"answer":"Line 1 has the greater constant of proportionality, 2.5 compared with 2.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line 1: k = 10/4 = 2.5. Line 2: k = 24/10 = 2.4. Line 1 greater.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('989a81ae-7ce4-40ca-a2b4-6f2ba1928c2c', 'NC26.7.RPR.1', 3, 'numeric', 'Compare proportional relationships', 'Plan A charges 0.07 dollar for each text message. Plan B charges 3 dollars for every 50 messages. Tina sends 500 messages. How many dollars cheaper is Plan B than Plan A?', '[]', '5', '0.07*500-3/50*500', 'Plan A: $0.07 \times 500 = 35$ dollars. Plan B: $3 \div 50 = 0.06$ dollar per message, so $0.06 \times 500 = 30$ dollars. Plan B is $35 - 30 = 5$ dollars cheaper.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 500 x 0.07 = 35. B: 500/50 = 10 groups x 3 = 30. 35 - 30 = 5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('037ef9e9-9410-47f5-a8eb-9055ac151f21', 'NC26.7.RPR.1', 3, 'choice', 'Interpret a point of a proportional relationship in context', 'The point $(1.5, 9)$ is on the graph of a proportional relationship between the hours $x$ and the gallons $y$ of water a pump moves. Which statement is true?', '["The pump moves 9 gallons each hour","The pump moves 13.5 gallons each hour","The pump moves 6 gallons each hour","The pump moves 1.5 gallons each hour"]', 'The pump moves 6 gallons each hour', NULL, '1.5 hours move 9 gallons, so each hour the pump moves $9 \div 1.5 = 6$ gallons. (13.5 is $1.5 \times 9$.)', 'checked', '{"lint":[],"solve":{"answer":"The pump moves 6 gallons each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/1.5 = 6 gallons per hour.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1aacc9e-813b-41cb-af08-371f6f6b4513', 'NC26.7.RPR.1', 3, 'numeric', 'Interpret a point of a proportional relationship in context', 'The point $(\frac{2}{3}, 5)$ is on the graph of a proportional relationship. What is the value of $y$ when $x = 1$?', '[]', '7.5', '5/(2/3)', '$k = y \div x = 5 \div \frac{2}{3} = 5 \times \frac{3}{2} = 7.5$. When $x = 1$, $y = 7.5 \times 1 = 7.5$.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 5 / (2/3) = 15/2 = 7.5; at x = 1, y = 7.5.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22ea0768-07d5-4891-bb02-ee4120b8941a', 'NC26.7.RPR.1', 3, 'choice', 'Interpret a point of a proportional relationship in context', 'Which pair of points can both be on the graph of one proportional relationship?', '["$(4, 6)$ and $(14, 16)$","$(4, 6)$ and $(6, 4)$","$(4, 6)$ and $(10, 14)$","$(4, 6)$ and $(14, 21)$"]', '$(4, 6)$ and $(14, 21)$', NULL, 'Both points must have the same $y \div x$. For $(4, 6)$ it is $1.5$, and for $(14, 21)$ it is $21 \div 14 = 1.5$. The others have $y \div x$ of $\frac{8}{7}$ (adding 2 to both), $\frac{2}{3}$ (the numbers swapped) and $1.4$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 6)$ and $(14, 21)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,6): y/x = 1.5. (14,21): 1.5 yes. (14,16): 8/7 no. (10,14): 1.4 no. (6,4): 2/3 no.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b35d5d8-8451-4e4b-b30e-9bea26301e5e', 'NC26.7.RPR.1', 3, 'numeric', 'Interpret a point of a proportional relationship in context', 'The point $(12, 7.2)$ is on the graph of a proportional relationship between the ounces $x$ of cheese and the cost $y$ in dollars. What is the cost of 25 ounces of the cheese?', '[]', '15', '7.2/12*25', '$12$ ounces cost 7.2 dollars, so 1 ounce costs $7.2 \div 12 = 0.6$ dollar. For 25 ounces: $0.6 \times 25 = 15$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 7.2/12 = 0.6 dollars per ounce; 25 x 0.6 = 15.","run_id":"claude-code","at":"2026-10-17T20:21:42.589Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
