INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d67abb92-aaed-420d-a799-60acc5669468', 'NC26.7.RPR.2', 1, 'numeric', 'Find an actual size from a scale drawing', 'A drawing of a playground uses the scale 1 cm : 2 m. The slide is 4 cm long on the drawing. How long is the real slide, in meters?', '[]', '8', '4*2', 'Each centimeter on the drawing stands for 2 meters, so the slide is $4 \times 2 = 8$ meters long.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 2 = 8 m.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
