INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('335d217a-d5c9-4ff4-bc8b-788a5a126be9', 'NC26.7.RPR.2', 2, 'numeric', 'Convert measurement units', 'A snail crawls 90 centimeters each minute. How many meters does it crawl in 1 hour? (1 meter = 100 centimeters)', '[]', '54', '90*60/100', 'In 60 minutes the snail crawls $90 \times 60 = 5400$ centimeters. Divide by 100 to change to meters: $5400 \div 100 = 54$ meters.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 x 60 = 5400 cm per hour = 54 m.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
