INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5121b622-3697-4fa5-b69f-c3e0858ac699', 'NC26.7.RPR.2', 2, 'numeric', 'Convert measurement units', 'A bag of rice has a mass of 2.5 pounds and costs 6 dollars. There are 16 ounces in 1 pound. How many dollars does 1 ounce of the rice cost?', '[]', '0.15', '6/(2.5*16)', '2.5 pounds is $2.5 \times 16 = 40$ ounces. The cost of 1 ounce is $6 \div 40 = 0.15$ dollar.', 'checked', '{"lint":[],"solve":{"answer":"0.15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5 x 16 = 40 ounces; 6/40 = 0.15 dollar per ounce.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ad559d6-d424-4f20-8548-de65386adab6', 'NC26.7.RPR.2', 2, 'choice', 'Convert measurement units', 'Which of these is the fastest speed?', '["700 meters per minute","40 kilometers per hour","12 meters per second","0.5 kilometer per minute"]', '12 meters per second', NULL, 'Change each speed to meters per minute. 12 meters per second is $12 \times 60 = 720$ meters per minute. 700 stays 700. 40 kilometers per hour is $40000 \div 60 \approx 667$ meters per minute. 0.5 kilometer per minute is 500 meters per minute. The fastest is 12 meters per second.', 'checked', '{"lint":[],"solve":{"answer":"12 meters per second","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In m/min: 700; 40 km/h = 40000/60 = 666.7; 0.5 km/min = 500; 12 m/s = 720. Fastest is 12 m/s.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84321293-ed90-4913-8142-c80ccd599360', 'NC26.7.RPR.2', 2, 'choice', 'Convert measurement units', 'Which expression changes 15 meters per second into meters per minute?', '["$15 \\div 60$","$15 \\times 60$","$15 \\times 100$","$15 + 60$"]', '$15 \times 60$', NULL, 'There are 60 seconds in a minute, so the object goes 60 times as far in a minute: $15 \times 60 = 900$ meters per minute.', 'checked', '{"lint":[],"solve":{"answer":"$15 \\times 60$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 seconds in a minute, so 15 m/s = 15 x 60 = 900 m/min.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa5d9560-757b-46ba-8fb7-0b194c80c145', 'NC26.7.RPR.2', 2, 'numeric', 'Find an actual size from a scale drawing', 'A scale drawing uses $\frac{1}{2}$ inch for every 6 feet. A wall is 3 inches long on the drawing. How long is the real wall, in feet?', '[]', '36', '3/(1/2)*6', '3 inches is $3 \div \frac{1}{2} = 6$ halves of an inch. Each half inch stands for 6 feet, so the wall is $6 \times 6 = 36$ feet long.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 inches = 6 half-inches; 6 x 6 = 36 feet. (12 ft per inch x 3.)","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
