INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8fa5c8e-8ff4-40e9-81db-96682c5937ac', 'NC26.7.RPR.2', 2, 'choice', 'Find an actual size from a scale drawing', 'On a map, 3 centimeters stand for 45 kilometers. Two lakes are 8 centimeters apart on the map. How many kilometers apart are the lakes?', '["120","360","135","15"]', '120', '45/3*8', '1 centimeter stands for $45 \div 3 = 15$ kilometers. So 8 centimeters stand for $15 \times 8 = 120$ kilometers. (360 multiplies 45 by 8, and 15 is only the kilometers for 1 centimeter.)', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45/3 = 15 km per cm; 8 x 15 = 120 km.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
