INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93bb964a-b9dd-45f6-8933-af83e419ce0d', 'NC26.7.RPR.2', 2, 'numeric', 'Find an actual size from a scale drawing', 'A model airplane is built to a scale of 1 : 48. Its wingspan is 25 centimeters. What is the real wingspan, in meters? (1 meter = 100 centimeters)', '[]', '12', '25*48/100', 'The real wingspan is $25 \times 48 = 1200$ centimeters. Divide by 100 to change to meters: $1200 \div 100 = 12$ meters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 x 48 = 1200 cm = 12 m.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
