INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca32635c-8382-4ccd-862d-542e6fc200b6', 'NC26.7.RPR.2', 2, 'choice', 'Construct a scale drawing or find a scale', 'A drawing uses the scale 2 cm : 10 m. Which scale is equivalent to it?', '["1 cm : 20 m","1 cm : 5 m","4 cm : 5 m","5 cm : 1 m"]', '1 cm : 5 m', NULL, 'Divide both parts of $2 : 10$ by 2 to get $1 : 5$, so 1 cm stands for 5 m. The others stand for 20 m, 1.25 m and 0.2 m for each centimeter.', 'checked', '{"lint":[],"solve":{"answer":"1 cm : 5 m","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 cm : 10 m = 1 cm : 5 m (divide both by 2). Others: 5 cm:1 m, 1 cm:20 m, 4 cm:5 m differ.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
