INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5c9f93f-6e16-4696-8c72-64e697513b4b', 'NC26.7.RPR.2', 2, 'choice', 'Sales tax and tip', 'Which tip is greater: 15% of a 40 dollar meal, or 20% of a 28 dollar meal?', '["The 20% tip, which is 5.60 dollars","The 20% tip, because 20% is more than 15%","The two tips are equal","The 15% tip, which is 6 dollars"]', 'The 15% tip, which is 6 dollars', NULL, '15% of 40 is $40 \times 0.15 = 6$ dollars. 20% of 28 is $28 \times 0.20 = 5.60$ dollars. The 15% tip is greater, because it is a percent of a bigger meal.', 'checked', '{"lint":[],"solve":{"answer":"The 15% tip, which is 6 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.15 x 40 = 6; 0.20 x 28 = 5.60. The 15% tip is greater.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c2c77e9-5aa3-49ed-a2b8-3627f10a222e', 'NC26.7.RPR.2', 2, 'numeric', 'Markup and discount', 'A store pays 36 dollars for a backpack and sells it for 45 dollars. The markup is what percent of the store''s cost?', '[]', '25', '(45-36)/36*100', 'The markup is $45 - 36 = 9$ dollars. As a fraction of the cost it is $9 \div 36 = 0.25$, which is 25%.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Markup 45 - 36 = 9; 9/36 = 25%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
