INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6147dd3-8876-4252-92d0-c93ff13519fa', 'NC26.7.RPR.2', 2, 'choice', 'Markup and discount', 'Three stores sell the same game. Store A: 50 dollars with 20% off. Store B: 45 dollars with 10% off. Store C: 38 dollars with no discount. Which store has the lowest final price?', '["Store C","Store A","Store B","Stores A and B tie"]', 'Store C', NULL, 'Store A: $50 - 10 = 40$ dollars. Store B: $45 - 4.50 = 40.50$ dollars. Store C: 38 dollars. Store C is the lowest.', 'checked', '{"lint":[],"solve":{"answer":"Store C","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 50 x 0.8 = 40. B: 45 x 0.9 = 40.50. C: 38. Lowest is C.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
