INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('487d5b5b-343a-49bf-97a9-9b2884fd5a6e', 'NC26.7.RPR.2', 2, 'choice', 'Commission', 'A salesperson earns a 7.5% commission on sales of 2400 dollars. How many dollars is the commission?', '["180","18","1800","7.5"]', '180', '2400*0.075', '7.5% is 0.075, so the commission is $2400 \times 0.075 = 180$ dollars. (1800 would be 75%.)', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.075 x 2400 = 180.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
