INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('900ff406-32d2-46b6-ab2a-521048ad961b', 'NC26.7.RPR.2', 2, 'numeric', 'Commission', 'Dev earns a 6% commission, and his commission one month is 330 dollars. What were his total sales that month, in dollars?', '[]', '5500', '330/0.06', '6% of his sales is 330 dollars, so his sales are $330 \div 0.06 = 5500$ dollars. Check: 6% of 5500 is 330.', 'checked', '{"lint":[],"solve":{"answer":"5500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.06s = 330, s = 5500.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
