INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec2a0b77-f595-4448-9406-b8b650a02860', 'NC26.7.RPR.2', 2, 'choice', 'Percent increase and decrease', 'A value changes from 50 to 35. Which statement describes the change?', '["A 15% decrease","A 43% decrease","A 30% decrease","A 30% increase"]', 'A 30% decrease', NULL, 'The value goes down by $50 - 35 = 15$. As a fraction of the original 50 it is $15 \div 50 = 0.3$, a 30% decrease. (43% comes from dividing by the new value, 35.)', 'checked', '{"lint":[],"solve":{"answer":"A 30% decrease","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change -15; 15/50 = 30% decrease. (43% is 15/35, the wrong base.)","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bf16309-97fe-43a5-980c-02b19ee68a98', 'NC26.7.RPR.2', 2, 'numeric', 'Percent increase and decrease', 'A stock price rose from 80 dollars to 92 dollars. What is the percent increase?', '[]', '15', '(92-80)/80*100', 'The increase is $92 - 80 = 12$ dollars. As a fraction of the original 80 it is $12 \div 80 = 0.15$, which is 15%.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 12; 12/80 = 0.15 = 15%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5bd2c4d-fe7e-41bd-b5b7-67f01179c708', 'NC26.7.RPR.2', 2, 'choice', 'Percent increase and decrease', 'A car is worth 12,000 dollars. Its value falls by 15% in one year. What is the value of the car after one year, in dollars?', '["1,800","10,200","13,800","11,985"]', '10,200', '12000-12000*0.15', '15% of 12,000 is $12000 \times 0.15 = 1800$ dollars. The new value is $12000 - 1800 = 10200$ dollars. (1,800 is only the decrease.)', 'checked', '{"lint":[],"solve":{"answer":"10,200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12000 x 0.85 = 10200.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
