INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51f4c527-4500-4bd4-b49f-69d1e78f2f0a', 'NC26.7.RPR.2', 3, 'choice', 'Convert measurement units', 'Which length is the same as 2 yards 6 inches? (1 yard = 36 inches)', '["72 inches","30 inches","78 inches","42 inches"]', '78 inches', NULL, '2 yards is $2 \times 36 = 72$ inches. Adding the 6 inches gives $72 + 6 = 78$ inches. (30 uses 12 inches for a yard, and 42 counts only 1 yard.)', 'checked', '{"lint":[],"solve":{"answer":"78 inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 36 + 6 = 78 inches.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78ab1b37-fa39-455d-8de2-f07f24c98563', 'NC26.7.RPR.2', 3, 'numeric', 'Find an actual size from a scale drawing', 'On a map, 1.5 centimeters stand for 20 kilometers. Two towns are 6.3 centimeters apart on the map. How many kilometers apart are the towns?', '[]', '84', '20/1.5*6.3', '6.3 centimeters is $6.3 \div 1.5 = 4.2$ times 1.5 centimeters. So the real distance is $4.2 \times 20 = 84$ kilometers.', 'checked', '{"lint":[],"solve":{"answer":"84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.3/1.5 = 4.2 units; 4.2 x 20 = 84 km.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
