INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8483d62b-3f5e-4d56-b971-e72f395c30f2', 'NC26.7.RPR.2', 3, 'choice', 'Find an actual size from a scale drawing', 'A scale drawing uses the scale 1 inch : 8 feet. Which statement is true?', '["A line 3.5 inches long on the drawing stands for 11.5 feet","A line 3.5 inches long on the drawing stands for 28 feet","A line 40 feet long is drawn 4 inches long","A line 16 feet long is drawn 128 inches long"]', 'A line 3.5 inches long on the drawing stands for 28 feet', NULL, 'Each inch stands for 8 feet, so 3.5 inches stand for $3.5 \times 8 = 28$ feet. A 40-foot line is $40 \div 8 = 5$ inches long on the drawing, and a 16-foot line is $16 \div 8 = 2$ inches long.', 'checked', '{"lint":[],"solve":{"answer":"A line 3.5 inches long on the drawing stands for 28 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 in = 8 ft. 40 ft -> 5 in (A false). 3.5 in -> 28 ft (B false, C true). 16 ft -> 2 in (D false).","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eda2b8b0-540a-45e8-8e0a-4cceaa9a846a', 'NC26.7.RPR.2', 3, 'numeric', 'Construct a scale drawing or find a scale', 'A real fence is 17.5 feet long. A scale drawing uses the scale 1.5 inches : 5 feet. How long is the fence on the drawing, in inches?', '[]', '5.25', '17.5/5*1.5', '17.5 feet is $17.5 \div 5 = 3.5$ times 5 feet. So the fence is $3.5 \times 1.5 = 5.25$ inches long on the drawing.', 'checked', '{"lint":[],"solve":{"answer":"5.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17.5/5 = 3.5; 3.5 x 1.5 = 5.25 inches.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
