INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59408889-68ac-49d9-9ce9-a49a51070395', 'NC26.7.RPR.2', 3, 'choice', 'Construct a scale drawing or find a scale', 'On Map A, 1 cm stands for 8 km. On Map B, 1 cm stands for 2 km. Two towns are 3 cm apart on Map A. How many centimeters apart are the towns on Map B?', '["0.75","6","12","24"]', '12', '3*8/2', 'On Map A the real distance is $3 \times 8 = 24$ km. On Map B each centimeter stands for 2 km, so the towns are $24 \div 2 = 12$ cm apart. (24 is the real distance, and 6 and 0.75 mix the scales up.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Real = 3 x 8 = 24 km. On Map B: 24/2 = 12 cm.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
