INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e133c738-3a77-47c6-86bb-86bf675d10c8', 'NC26.7.RPR.2', 3, 'numeric', 'Construct a scale drawing or find a scale', 'A rectangular field is 45 meters long and 30 meters wide. On a scale drawing of the field, the length is 9 centimeters. How wide is the field on the drawing, in centimeters?', '[]', '6', '9/45*30', 'The 45 meters are shown by 9 centimeters, so 1 centimeter stands for $45 \div 9 = 5$ meters. The width of 30 meters is $30 \div 5 = 6$ centimeters on the drawing.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 m -> 9 cm, so 1 cm : 5 m. 30/5 = 6 cm.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
