INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f919cd22-a032-46bd-844a-b1bb8c2e96ea', 'NC26.7.RPR.2', 3, 'numeric', 'How a scale changes area', 'A map uses the scale 1 cm : 4 km. A lake covers 6.5 square centimeters on the map. What is the real area of the lake, in square kilometers?', '[]', '104', '6.5*4^2', 'Each square centimeter on the map stands for $4 \times 4 = 16$ square kilometers. The lake is $6.5 \times 16 = 104$ square kilometers.', 'checked', '{"lint":[],"solve":{"answer":"104","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 sq cm = 4 x 4 = 16 sq km; 6.5 x 16 = 104.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
