INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c63c4afd-d2e7-42c5-b35d-6e0e019bf03c', 'NC26.7.RPR.2', 3, 'numeric', 'How a scale changes area', 'A real garden has an area of 360 square meters. A scale drawing uses the scale 1 cm : 6 m. What is the area of the garden on the drawing, in square centimeters?', '[]', '10', '360/6^2', 'Each square centimeter on the drawing stands for $6 \times 6 = 36$ square meters. So the drawing has an area of $360 \div 36 = 10$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 sq cm = 6 x 6 = 36 sq m; 360/36 = 10 sq cm.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
