INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7980a0e5-58a8-443b-8a81-4b6dfadca322', 'NC26.7.RPR.2', 3, 'choice', 'How a scale changes area', 'A designer shrinks a rectangle so that every side is $\frac{1}{3}$ as long as before. The new area is what fraction of the old area?', '["$\\frac{1}{9}$","$\\frac{1}{3}$","$\\frac{1}{6}$","$\\frac{2}{3}$"]', '$\frac{1}{9}$', NULL, 'Both the length and the width are multiplied by $\frac{1}{3}$, so the area is multiplied by $\frac{1}{3} \times \frac{1}{3} = \frac{1}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/3)(1/3) = 1/9.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebe61f0a-ac31-4470-8d02-8fb933455e4f', 'NC26.7.RPR.2', 3, 'choice', 'How a scale changes area', 'On a scale drawing, a room has an area of 8 square inches. The real room has an area of 288 square feet. What is the scale of the drawing?', '["1 inch : 36 feet","1 inch : 280 feet","1 inch : 6 feet","1 inch : 18 feet"]', '1 inch : 6 feet', NULL, '288 square feet is shown by 8 square inches, so 1 square inch stands for $288 \div 8 = 36$ square feet. A square that is 1 inch on each side stands for a square that is 6 feet on each side, because $6 \times 6 = 36$. The scale is 1 inch : 6 feet.', 'checked', '{"lint":[],"solve":{"answer":"1 inch : 6 feet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"288/8 = 36 sq ft per sq in, so 1 inch stands for 6 ft (6 x 6 = 36).","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdd48b2f-7c9e-4da4-9196-6dbda41de89c', 'NC26.7.RPR.2', 3, 'numeric', 'Sales tax and tip', 'Mia''s meal costs 36 dollars before tax. The sales tax is 7.5%, and she leaves a tip of 15% of the cost before tax. What is the total she pays, in dollars?', '[]', '44.1', '36+36*0.075+36*0.15', 'The tax is $36 \times 0.075 = 2.70$ dollars. The tip is $36 \times 0.15 = 5.40$ dollars. The total is $36 + 2.70 + 5.40 = 44.10$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"44.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tax 0.075 x 36 = 2.70; tip 0.15 x 36 = 5.40; total 36 + 2.70 + 5.40 = 44.10.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bceef1cb-af14-400b-8409-ad425bf41b5c', 'NC26.7.RPR.2', 3, 'numeric', 'Sales tax and tip', 'A jacket''s total price, including 8% sales tax, is 54 dollars. What was the price of the jacket before tax, in dollars?', '[]', '50', '54/1.08', 'The total is 108% of the price before tax, so the price is $54 \div 1.08 = 50$ dollars. Check: 8% of 50 is 4, and $50 + 4 = 54$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.08p = 54, p = 50.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3ec7e3a-481d-4267-817a-ebe70a0fdab0', 'NC26.7.RPR.2', 3, 'choice', 'Sales tax and tip', 'A group''s bill is 64 dollars before tax. The sales tax is 7%, and the tip is 20% of the cost before tax. Four friends split the total equally. How many dollars does each friend pay?', '["81.28","20.32","17.12","19.20"]', '20.32', '(64+64*0.07+64*0.2)/4', 'The tax is $64 \times 0.07 = 4.48$ and the tip is $64 \times 0.20 = 12.80$. The total is $64 + 4.48 + 12.80 = 81.28$ dollars. Each friend pays $81.28 \div 4 = 20.32$ dollars. (81.28 is the whole bill, 17.12 leaves out the tip and 19.20 leaves out the tax.)', 'checked', '{"lint":[],"solve":{"answer":"20.32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tax 0.07 x 64 = 4.48; tip 0.20 x 64 = 12.80; total 81.28; /4 = 20.32.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d31cc8d-6d14-489f-a68a-9552147e4932', 'NC26.7.RPR.2', 3, 'numeric', 'Markup and discount', 'A store marks up the cost of a chair by 35% and sells it for 81 dollars. What did the store pay for the chair, in dollars?', '[]', '60', '81/1.35', 'The selling price is 135% of the cost, so the cost is $81 \div 1.35 = 60$ dollars. Check: 35% of 60 is 21, and $60 + 21 = 81$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.35c = 81, c = 60.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
