INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c04f46ec-ed72-4cad-88ef-96654590c23f', 'NC26.7.RPR.2', 3, 'numeric', 'Markup and discount', 'After a 15% discount, a scooter sells for 68 dollars. What was the price before the discount, in dollars?', '[]', '80', '68/0.85', 'The sale price is 85% of the original price, so the original price is $68 \div 0.85 = 80$ dollars. Check: 15% of 80 is 12, and $80 - 12 = 68$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.85p = 68, p = 80.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
