INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1ed12bf-7adf-4983-a7d6-ad6633c6695c', 'NC26.7.RPR.2', 3, 'choice', 'Markup and discount', 'A 50 dollar item is discounted by 20%. Then the new price is discounted by a further 10%. What is the final price, in dollars?', '["35","40","36","45"]', '36', '50*0.8*0.9', 'After 20% off, the price is $50 \times 0.8 = 40$ dollars. The further 10% off 40 dollars is 4 dollars, so the final price is $40 - 4 = 36$ dollars. (35 adds the discounts to make 30% off.)', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 x 0.8 = 40; 40 x 0.9 = 36.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('084911cc-6294-4ab3-a609-b29ad28c2d55', 'NC26.7.RPR.2', 3, 'choice', 'Markup and discount', 'A store marks up an item by 50% of its cost. Later it sells the item at 50% off that marked-up price. Compared with what the store paid, the final price is...', '["the same as the cost","25% less than the cost","25% more than the cost","50% less than the cost"]', '25% less than the cost', NULL, 'With a cost of 100, the marked-up price is 150. Half off is 75. Compared with the cost of 100, 75 is 25% less.', 'checked', '{"lint":[],"solve":{"answer":"25% less than the cost","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost c: marked up to 1.5c, then 0.5 x 1.5c = 0.75c, which is 25% less than the cost.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('018ebbd5-0d61-48da-9b3b-0bbaf143e9ed', 'NC26.7.RPR.2', 3, 'choice', 'Commission', 'Plan A pays a commission of 8% of sales. Plan B pays 150 dollars plus a commission of 3% of sales. Jin''s sales are 2000 dollars. How many more dollars would Plan B pay than Plan A?', '["160","210","60","50"]', '50', '150+2000*0.03-2000*0.08', 'Plan A pays 8% of 2000, which is 160 dollars. Plan B pays $150 + 0.03 \times 2000 = 150 + 60 = 210$ dollars. Plan B pays $210 - 160 = 50$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0.08 x 2000 = 160. B: 150 + 0.03 x 2000 = 210. B pays 50 more.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad71a0f6-8399-479f-b593-24e483353cba', 'NC26.7.RPR.2', 3, 'numeric', 'Commission', 'Maya is paid 120 dollars a week plus a commission of 4% of her sales. How many dollars of sales does she need in a week to earn 200 dollars in all?', '[]', '2000', '(200-120)/0.04', 'She needs $200 - 120 = 80$ dollars from commission. 4% of her sales must be 80 dollars, so her sales are $80 \div 0.04 = 2000$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Needs 200 - 120 = 80 commission; 80/0.04 = 2000 dollars of sales.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9cc6ed09-a12a-4c2a-9953-703bd7be99f1', 'NC26.7.RPR.2', 3, 'choice', 'Commission', 'A salesperson earns 5% commission on the first 1000 dollars of sales in a week and 8% on all sales over 1000 dollars. In one week the sales are 1500 dollars. How many dollars is the commission?', '["75","120","90","105"]', '90', '1000*0.05+500*0.08', 'On the first 1000 dollars: $1000 \times 0.05 = 50$ dollars. On the other 500 dollars: $500 \times 0.08 = 40$ dollars. The total is $50 + 40 = 90$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.05 x 1000 = 50; 0.08 x 500 = 40; total 90.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bf9a729-d5b2-4e90-829c-6e26f659dcf1', 'NC26.7.RPR.2', 3, 'numeric', 'Percent increase and decrease', 'A town''s population grew from 2500 to 3150. What is the percent increase?', '[]', '26', '(3150-2500)/2500*100', 'The increase is $3150 - 2500 = 650$ people. As a fraction of the original 2500 it is $650 \div 2500 = 0.26$, which is 26%.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Increase 650; 650/2500 = 0.26 = 26%.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
