INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b79956df-8c13-41f2-99b8-96d75c6f0f32', 'NC26.7.RPR.2', 3, 'choice', 'Percent increase and decrease', 'A price goes up by 20%, and then the new price goes down by 20%. Compared with the starting price, the final price is...', '["the same as the starting price","4% less than the starting price","4% more than the starting price","20% more than the starting price"]', '4% less than the starting price', NULL, 'Start with 100. Up 20% gives 120. Down 20% of 120 is 24, which gives 96. Compared with 100, 96 is 4% less.', 'checked', '{"lint":[],"solve":{"answer":"4% less than the starting price","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2 x 0.8 = 0.96: 4% less than the start.","run_id":"claude-code","at":"2026-10-17T20:21:42.627Z"}}', 'ai', NULL, NULL)
