INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a447f7da-f3d1-4474-9c1c-4156aacd9e6f', 'NC26.7.RPR.3', 1, 'choice', 'Use a circle graph sector to find the whole', 'A sector that is 25% of a circle graph stands for 15 students. How many students are in the graph altogether?', '["40","3.75","60","375"]', '60', '15/0.25', '25% is $\frac{1}{4}$ of the whole, so the whole is $15 \times 4 = 60$ students.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25% = 1/4 stands for 15, so whole = 15 x 4 = 60.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
