INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8da59f59-cffb-46f0-bf4d-72375374213d', 'NC26.7.RPR.3', 1, 'choice', 'Find a missing sector of a circle graph', 'Three sectors of a circle graph have angles of 100 degrees, 120 degrees and an unknown number of degrees. What is the unknown angle, in degrees?', '["140","220","240","260"]', '140', '360-100-120', 'The angles make 360 degrees. $100 + 120 = 220$, so the missing angle is $360 - 220 = 140$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360 - 100 - 120 = 140 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
