VALUES ('fa6ca3ec-db27-4198-9825-3db5002ac2c4', 'NC26.7.RPR.3', 2, 'numeric', 'Convert degrees to a percent or fraction of a circle graph', 'A circle graph has a sector of 135 degrees. What fraction of the whole circle is that sector? Write it in simplest form.', '[]', '3/8', '135/360', '$\frac{135}{360}$: both numbers divide by 45, giving $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"135/360: divide by 45 -> 3/8.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
