VALUES ('25bddd9e-a984-4c78-9499-3cddba4e241e', 'NC26.7.RPR.3', 2, 'choice', 'Use a circle graph sector to find a count', 'In a circle graph of 250 library books, the sector for mysteries is 28% of the circle. How many of the books are mysteries?', '["28","70","7","222"]', '70', '0.28*250', '28% of 250 is $0.28 \times 250 = 70$ books.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.28 x 250 = 70 books.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
