VALUES ('45bcd588-e47c-4bd2-b655-502cc49730e3', 'NC26.7.RPR.3', 2, 'choice', 'Use a circle graph sector to find the whole', 'In a circle graph, 35% of the circle stands for 28 tickets sold online. How many tickets were sold altogether?', '["63","9.8","980","80"]', '80', '28/0.35', '$28 \div 0.35 = 80$ tickets. (Check: 35% of 80 is 28.)', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"28 / 0.35 = 80 tickets.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
