VALUES ('f4f3fc60-1c66-401d-b433-7d81c511ac28', 'NC26.7.RPR.3', 2, 'choice', 'Find circumference from diameter', 'A round pizza has a diameter of 14 inches. Use 3.14 for $\pi$. What is the circumference of the pizza, in inches?', '["43.96","21.98","153.86","17.14"]', '43.96', '3.14*14', '$3.14 \times 14 = 43.96$ inches. (21.98 uses the radius; 153.86 is $3.14 \times 14 \times 14$ divided by 4, an area calculation; 17.14 adds.)', 'checked', '{"lint":[],"solve":{"answer":"43.96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 14 = 43.96 in.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
