INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d984dffc-4d3e-4f65-bde1-80a0b1d93308', 'NC26.7.RPR.3', 2, 'numeric', 'Solve a problem using circumference', 'A wheel has a diameter of 50 centimeters. Use 3.14 for $\pi$. How far does the wheel roll in 20 full turns, in centimeters?', '[]', '3140', '3.14*50*20', 'One turn is the circumference, $3.14 \times 50 = 157$ centimeters. 20 turns is $157 \times 20 = 3140$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 50 = 157 cm; 20 turns = 157 x 20 = 3140 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ee15c1f-5d3d-4dac-b0a5-16503842f03d', 'NC26.7.RPR.3', 3, 'numeric', 'Use a circle graph sector to find a count', 'In a survey of 240 students, a circle graph shows their favorite sports. The sector for soccer measures 75 degrees. How many of the students chose soccer?', '[]', '50', '75/360*240', 'Soccer is $\frac{75}{360}$ of the circle, so $\frac{75}{360} \times 240 = 50$ students.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fraction = 75/360 = 5/24. 240 x 5/24 = 50 students.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2b68e76-8532-4f30-8059-cdca479fa76d', 'NC26.7.RPR.3', 3, 'numeric', 'Use circumference to count turns of a wheel', 'A wheel has a diameter of 60 centimeters. Use 3.14 for $\pi$. How many complete turns does the wheel make while rolling 1884 centimeters in a straight line?', '[]', '10', '1884/(3.14*60)', 'One turn moves the wheel one circumference: $3.14 \times 60 = 188.4$ centimeters. The number of turns is $1884 \div 188.4 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = circumference = 3.14 x 60 = 188.4 cm. 1884/188.4 = 10 complete turns.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3266fc4f-f427-4441-9d1e-2789405cc385', 'NC26.7.RPR.3', 3, 'choice', 'Find radius from circumference', 'The circumference of a circle is 18.84 centimeters. Use 3.14 for $\pi$. What is the radius, in centimeters?', '["3","6","59.16","9.42"]', '3', '18.84/(2*3.14)', '$C = 2\pi r$, so $r = C \div (2 \times 3.14) = 18.84 \div 6.28 = 3$ centimeters. (6 is the diameter.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 18.84/3.14 = 6, r = d/2 = 3 cm.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4cb2ae3-e48d-4bbb-a5cf-de4ffd8f5601', 'NC26.7.RPR.3', 3, 'numeric', 'Convert a percent or fraction to degrees in a circle graph', 'In a circle graph, the rent sector is 35% of the circle and the food sector is 20% of the circle. What is the sum of the two angles, in degrees?', '[]', '198', '(0.35+0.2)*360', 'Together the sectors are $35\% + 20\% = 55\%$ of the circle. $0.55 \times 360 = 198$ degrees. (Separately: 126 degrees and 72 degrees.)', 'checked', '{"lint":[],"solve":{"answer":"198","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"35% + 20% = 55%; 0.55 x 360 = 198 degrees (126 + 72).","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d2a7257-a714-42a2-a252-a3e6e0802093', 'NC26.7.RPR.3', 3, 'choice', 'Convert a percent or fraction to degrees in a circle graph', 'A circle graph of a farm shows that corn takes up $\frac{3}{8}$ of the whole farm. How many degrees is the corn sector?', '["37.5","135","45","960"]', '135', '3/8*360', '$\frac{3}{8}$ of 360 is $360 \div 8 \times 3 = 45 \times 3 = 135$ degrees. (37.5 is the percent, 45 is only $\frac{1}{8}$, and 960 divides by the fraction.)', 'checked', '{"lint":[],"solve":{"answer":"135","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/8 x 360 = 3 x 45 = 135 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72f06015-c2d9-43dc-9b36-53b98fecbee8', 'NC26.7.RPR.3', 3, 'choice', 'Convert a percent or fraction to degrees in a circle graph', 'One category in a circle graph is 7% of the data. What is the angle of that sector, in degrees?', '["2.52","25.2","252","7"]', '25.2', '0.07*360', '$0.07 \times 360 = 25.2$ degrees. (2.52 and 252 misplace the decimal point, and 7 treats the percent as degrees.)', 'checked', '{"lint":[],"solve":{"answer":"25.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.07 x 360 = 25.2 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
