INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6439ab41-faeb-4c51-8f0e-09976f287669', 'NC26.7.RPR.3', 3, 'choice', 'Find diameter or radius from circumference', 'A circle has a circumference of 21.98 centimeters. Use 3.14 for $\pi$. What is its radius, in centimeters?', '["7","3.5","14","15.7"]', '3.5', '21.98/(2*3.14)', 'Diameter $= 21.98 \div 3.14 = 7$ centimeters, so the radius is $7 \div 2 = 3.5$ centimeters. (7 is the diameter.)', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 21.98 / 3.14 = 7 cm; r = 3.5 cm.","run_id":"claude-code","at":"2026-10-17T20:20:09.605Z"}}', 'ai', NULL, NULL)
