VALUES ('2d9d01b1-b8e4-4b6f-8374-4ce707e8e6f3', 'NC26.7.ANR.1', 1, 'numeric', 'Use the order of operations with rational numbers', 'Evaluate $3 + 4 \times (-2)$.', '[]', '-5', '3+4*(-2)', 'Multiply first: $4 \times (-2) = -8$. Then $3 + (-8) = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply first: 4 x (-2) = -8; 3 + (-8) = -5.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
