VALUES ('84b62458-814f-4ea3-8fab-39ea9688ec94', 'NC26.7.ANR.1', 1, 'choice', 'Use the order of operations with rational numbers', 'What is the value of $(-6 + 2) \times 5$?', '["4","20","-20","-4"]', '-20', '(-6+2)*5', 'Work inside the parentheses first: $-6 + 2 = -4$. Then $-4 \times 5 = -20$. (4 ignores the parentheses, and -4 stops after them.)', 'checked', '{"lint":[],"solve":{"answer":"-20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-6 + 2) = -4; -4 x 5 = -20.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
