INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2daff399-0be2-4cca-ae2c-6548afc26613', 'NC26.7.ANR.1', 1, 'numeric', 'Solve a problem with rational numbers', 'At 6 a.m. the temperature was $-3$ degrees. It rose 2.5 degrees every hour for 4 hours. What was the temperature after those 4 hours, in degrees?', '[]', '7', '-3+2.5*4', 'The rise is $2.5 \times 4 = 10$ degrees. Then $-3 + 10 = 7$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise = 2.5 x 4 = 10; -3 + 10 = 7 degrees.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
