INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('616148df-4e31-4c8c-b236-23fbb88f9f61', 'NC26.7.ANR.1', 2, 'choice', 'Add and subtract integers', 'Which expression has the same value as $-6 - 9$?', '["$-6 + (-9)$","$-6 - (-9)$","$6 - 9$","$9 - 6$"]', '$-6 + (-9)$', NULL, 'Subtracting 9 is the same as adding $-9$, so $-6 - 9 = -6 + (-9) = -15$. The other expressions have the values 3, $-3$ and 3.', 'checked', '{"lint":[],"solve":{"answer":"$-6 + (-9)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6 - 9 = -15. Options: 6 - 9 = -3; -6 + (-9) = -15; -6 - (-9) = 3; 9 - 6 = 3. Only -6 + (-9) matches.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
