VALUES ('a42ad768-8c51-4573-9019-7b6002621f48', 'NC26.7.ANR.1', 2, 'numeric', 'Convert a fraction to a decimal', 'Use long division to write $\frac{5}{16}$ as a decimal.', '[]', '0.3125', '5/16', '$5 \div 16 = 0.3125$.', 'checked', '{"lint":[],"solve":{"answer":"0.3125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 / 16: 50/16 = 3 r2; 20/16 = 1 r4; 40/16 = 2 r8; 80/16 = 5 r0 -> 0.3125.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
