INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63085ff8-85db-4fcf-b84b-fc7119049dbe', 'NC26.7.ANR.1', 2, 'choice', 'Tell terminating decimals from repeating decimals', 'Which decimal is equal to $\frac{5}{12}$?', '["$0.\\overline{416}$","$0.41\\overline{6}$","$0.416$","$0.\\overline{41}$"]', '$0.41\overline{6}$', NULL, '$5 \div 12 = 0.41666\ldots$ Only the 6 repeats, so the decimal is $0.41\overline{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$0.41\\overline{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/12 = 0.41666... : 50/12 = 4 r2, 20/12 = 1 r8, 80/12 = 6 r8, ... so only the 6 repeats: 0.41(6 repeating).","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
