INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('def56e50-7fb9-4b91-84e2-047f1811f6a4', 'NC26.7.ANR.1', 2, 'numeric', 'Write a rational number as a quotient of integers', 'Write the decimal 0.375 as a fraction in simplest form.', '[]', '3/8', '0.375', '$0.375 = \frac{375}{1000}$. Dividing the top and bottom by 125 gives $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.375 = 375/1000 = 3/8.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
