INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59cfb543-44df-4b93-a1b9-45e32c87dce6', 'NC26.7.ANR.1', 2, 'choice', 'Write a rational number as a quotient of integers', 'Which fraction in simplest form is equal to $-9 \div 12$?', '["-4/3","3/4","-1/3","-3/4"]', '-3/4', '-9/12', '$-9 \div 12 = \frac{-9}{12}$, and dividing the top and bottom by 3 gives $-\frac{3}{4}$. (-4/3 turns the fraction upside down, and 3/4 loses the sign.)', 'checked', '{"lint":[],"solve":{"answer":"-3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9/12 = -3/4.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
