INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42c042cd-ea93-4acd-9cb2-fd6c3377866a', 'NC26.7.ANR.1', 3, 'numeric', 'Multiply and divide integers', 'The product of two integers is $-72$. One of the integers is $-9$. What is the other integer?', '[]', '8', '-72/-9', 'The other integer is $-72 \div (-9) = 8$. Check: $-9 \times 8 = -72$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9 x n = -72, n = -72 / -9 = 8.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
