VALUES ('9b0d6c83-5b94-42e9-b360-3ae595d458d2', 'NC26.7.ANR.1', 3, 'choice', 'Multiply and divide integers', 'Which value of $n$ makes $-3 \times n = 54$ true?', '["18","-51","-18","57"]', '-18', '54/(-3)', '$n = 54 \div (-3) = -18$. Check: $-3 \times (-18) = 54$. (18 loses the sign, and $-51$ and 57 add or subtract 3.)', 'checked', '{"lint":[],"solve":{"answer":"-18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = 54 / (-3) = -18. Check: -3 x -18 = 54.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
