VALUES ('b0e6ab4c-e7a9-4396-a442-206d6dc8711a', 'NC26.7.ANR.1', 3, 'numeric', 'Add and subtract fractions and mixed numbers', 'Evaluate $\frac{7}{10} - \frac{5}{6} - \frac{2}{15}$.', '[]', '-4/15', '7/10-5/6-2/15', 'Use 30 as the common denominator: $\frac{21}{30} - \frac{25}{30} - \frac{4}{30} = -\frac{8}{30} = -\frac{4}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"-4/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LCD 30: 21/30 - 25/30 - 4/30 = -8/30 = -4/15.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
