INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9bdba9a-abed-46a0-996b-0482ab710576', 'NC26.7.ANR.1', 3, 'choice', 'Add and subtract fractions and mixed numbers', 'What is the value of $-2\frac{1}{4} - \left(-\frac{5}{6}\right)$?', '["-3 1/12","-1 5/12","1 5/12","-1 7/12"]', '-1 5/12', '-9/4+5/6', 'Subtracting $-\frac{5}{6}$ is adding $\frac{5}{6}$: $-\frac{27}{12} + \frac{10}{12} = -\frac{17}{12} = -1\frac{5}{12}$. (-3 1/12 subtracts $\frac{5}{6}$ instead.)', 'checked', '{"lint":[],"solve":{"answer":"-1 5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-9/4 + 5/6 = -27/12 + 10/12 = -17/12 = -1 5/12.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
