VALUES ('64ab93ee-afc2-4f0d-ab6f-65b27592ce73', 'NC26.7.ANR.1', 3, 'numeric', 'Multiply and divide fractions and mixed numbers', 'What is the quotient $-3\frac{1}{3} \div 1\frac{2}{3}$?', '[]', '-2', '-10/3/(5/3)', '$-\frac{10}{3} \div \frac{5}{3} = -\frac{10}{3} \times \frac{3}{5} = -\frac{30}{15} = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-10/3 / (5/3) = -10/3 x 3/5 = -2.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
