INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3252e5be-dc30-46e9-8f4f-47772b56eaac', 'NC26.7.ANR.1', 3, 'choice', 'Add and subtract decimals', 'Which expression has the same value as $-4.3 - (-2.8)$?', '["$-4.3 - 2.8$","$-4.3 + 2.8$","$4.3 - 2.8$","$2.8 - (-4.3)$"]', '$-4.3 + 2.8$', NULL, 'Subtracting $-2.8$ is the same as adding 2.8, so $-4.3 - (-2.8) = -4.3 + 2.8 = -1.5$. The other three have the values $-7.1$, $1.5$ and $7.1$.', 'checked', '{"lint":[],"solve":{"answer":"$-4.3 + 2.8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4.3 - (-2.8) = -4.3 + 2.8 = -1.5. Others: -7.1, 1.5, 7.1.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
