INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee857f0c-47d2-4079-81fc-128d736f8c94', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'A student calculates $-48.3 \div 6.9$ and gets $-70$. Which is the best way to see that this answer is not reasonable?', '["A negative divided by a positive is positive.","48 divided by 7 is about 7, so the answer should be about $-7$.","48 divided by 7 is about 70, so the answer is close.","The answer should be positive because 48.3 is greater than 6.9."]', '48 divided by 7 is about 7, so the answer should be about $-7$.', NULL, 'Round to $-48 \div 7$, which is a little less than 7 in size, and the sign is negative. So the answer should be about $-7$, not $-70$. (The exact value is $-7$.)', 'checked', '{"lint":[],"solve":{"answer":"48 divided by 7 is about 7, so the answer should be about $-7$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48.3 / 6.9 ~ 48 / 7 ~ 7 (exact 7), and negative / positive is negative, so about -7, not -70. Option A is false (48/7 is not 70); B and C state wrong sign rules.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9a2dbf2-d0f0-461e-a68f-1aa84f1853e5', 'NC26.7.ANR.1', 3, 'numeric', 'Check reasonableness by estimating', 'Mia estimates $\frac{29.7 \times 4.1}{5.9}$ by rounding 29.7 to 30, 4.1 to 4 and 5.9 to 6. What is her estimate?', '[]', '20', '30*4/6', '$\frac{30 \times 4}{6} = \frac{120}{6} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 x 4 / 6 = 120 / 6 = 20.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7290cb5d-5af0-4e79-a1ec-ddd499fdf909', 'NC26.7.ANR.1', 3, 'choice', 'Check reasonableness by estimating', 'Which expression gives the best estimate of $-\frac{15}{16} \div 0.51$?', '["$-1 \\div 0.5$","$-1 \\div 5$","$1 \\div 0.5$","$-15 \\div 0.5$"]', '$-1 \div 0.5$', NULL, '$-\frac{15}{16}$ is close to $-1$ and 0.51 is close to 0.5, so the estimate is $-1 \div 0.5 = -2$. The other expressions change the size or the sign.', 'checked', '{"lint":[],"solve":{"answer":"$-1 \\div 0.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-15/16 ~ -1 and 0.51 ~ 0.5, so -1 / 0.5 (= -2; exact about -1.84). -15 / 0.5 is far too big, 1 / 0.5 has the wrong sign, -1 / 5 uses the wrong divisor.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acbee50f-b5a9-4642-aa1f-5125e8c244cd', 'NC26.7.ANR.1', 3, 'choice', 'Use the order of operations with rational numbers', 'What is the value of $2.5 - 1.5 \times (4 - 6.4)$?', '["6.1","-2.4","-9.9","-1.1"]', '6.1', '2.5-1.5*(4-6.4)', 'Parentheses first: $4 - 6.4 = -2.4$. Then multiply: $1.5 \times (-2.4) = -3.6$. Finally $2.5 - (-3.6) = 6.1$.', 'checked', '{"lint":[],"solve":{"answer":"6.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 - 6.4 = -2.4; 1.5 x (-2.4) = -3.6; 2.5 - (-3.6) = 6.1.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f8826f0-958a-4bc0-b0ec-04e726c3fe70', 'NC26.7.ANR.1', 3, 'numeric', 'Use the order of operations with rational numbers', 'Evaluate $\left(-\frac{3}{4}\right)^2 \div \frac{9}{8} - 1$.', '[]', '-1/2', '(-3/4)^2/(9/8)-1', '$\left(-\frac{3}{4}\right)^2 = \frac{9}{16}$. Then $\frac{9}{16} \div \frac{9}{8} = \frac{9}{16} \times \frac{8}{9} = \frac{1}{2}$. Finally $\frac{1}{2} - 1 = -\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"-1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3/4)^2 = 9/16; 9/16 / (9/8) = 9/16 x 8/9 = 1/2; 1/2 - 1 = -1/2.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8de7552-b986-43d5-be39-9831fd3cc195', 'NC26.7.ANR.1', 3, 'numeric', 'Use the order of operations with rational numbers', 'Evaluate $\frac{-2.4 + 0.6 \times 5}{-0.3}$.', '[]', '-2', '(-2.4+0.6*5)/(-0.3)', 'In the top, multiply first: $0.6 \times 5 = 3$, so the top is $-2.4 + 3 = 0.6$. Then $0.6 \div (-0.3) = -2$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerator: 0.6 x 5 = 3; -2.4 + 3 = 0.6. 0.6 / (-0.3) = -2.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1251c8f-3322-466a-9dcd-4dfd5273ba94', 'NC26.7.ANR.1', 3, 'choice', 'Solve a problem with rational numbers', 'A tank is $\frac{5}{6}$ full. Jo uses $\frac{1}{4}$ of the water in the tank. What fraction of the whole tank is now full?', '["7/12","5/24","5/8","1/12"]', '5/8', '5/6*(1-1/4)', 'What is left is $1 - \frac{1}{4} = \frac{3}{4}$ of the water, so $\frac{3}{4} \times \frac{5}{6} = \frac{15}{24} = \frac{5}{8}$ of the tank. (7/12 takes $\frac{1}{4}$ of the tank, and 5/24 is the amount used.)', 'checked', '{"lint":[],"solve":{"answer":"5/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She uses 1/4 of the water, leaving 3/4 of it: 3/4 x 5/6 = 15/24 = 5/8 of the tank.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a357227-68a6-4c5e-a758-1f7ac2aa7755', 'NC26.7.ANR.1', 3, 'choice', 'Solve a problem with rational numbers', 'A 9.5-meter ribbon is cut into pieces that are each 1.2 meters long. After as many whole pieces as possible are cut, how many meters of ribbon are left over?', '["8.4","7","1.1","0.9"]', '1.1', '9.5-7*1.2', '$9.5 \div 1.2$ is about 7.9, so 7 whole pieces can be cut. They use $7 \times 1.2 = 8.4$ meters, leaving $9.5 - 8.4 = 1.1$ meters. (8.4 is the ribbon used, 7 is the number of pieces, and 0.9 reads the decimal part of 7.9 as meters.)', 'checked', '{"lint":[],"solve":{"answer":"1.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9.5 / 1.2 = 7.9..., so 7 whole pieces use 7 x 1.2 = 8.4 m; left over 9.5 - 8.4 = 1.1 m.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f4e1f03-231b-404f-ad26-07b2a2fd2bf4', 'NC26.7.ANR.1', 3, 'numeric', 'Solve a problem with rational numbers', 'A hiker walks $2\frac{1}{2}$ miles in $\frac{3}{4}$ of an hour. At the same steady speed, how many miles does she walk in 1 hour?', '[]', '3 1/3', '5/2/(3/4)', '$2\frac{1}{2} \div \frac{3}{4} = \frac{5}{2} \times \frac{4}{3} = \frac{20}{6} = 3\frac{1}{3}$ miles.', 'checked', '{"lint":[],"solve":{"answer":"3 1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Speed = 2 1/2 / (3/4) = 5/2 x 4/3 = 20/6 = 10/3 = 3 1/3 miles per hour.","run_id":"claude-code","at":"2026-10-17T20:20:09.641Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbd83b50-7a18-4409-8a6f-810a53034d43', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which expression is equivalent to $4x + 7 + 2x - 3$?', '["$6x + 4$","$13x$","$6x + 10$","$6x - 4$"]', '$6x + 4$', NULL, 'Combine the $x$ terms: $4x + 2x = 6x$. Combine the numbers: $7 - 3 = 4$. The result is $6x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 2x = 6x; 7 - 3 = 4. So 6x + 4.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b65b4f4-55c6-495b-bbea-b17f29480c0a', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'The expression $3(x + 4)$ is equivalent to $3x + k$. What is the value of $k$?', '[]', '12', '3*4', 'Distribute: $3(x + 4) = 3x + 3 \times 4 = 3x + 12$, so $k = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 4) = 3x + 12, so k = 12.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bf151c3-713f-4b6d-9f40-1921aadeb945', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $6x + 9$?', '["$6(x + 3)$","$3(2x + 9)$","$3(x + 3)$","$3(2x + 3)$"]', '$3(2x + 3)$', NULL, '6 and 9 have the common factor 3. $6x \div 3 = 2x$ and $9 \div 3 = 3$, so $6x + 9 = 3(2x + 3)$. Multiplying back gives $6x + 9$.', 'checked', '{"lint":[],"solve":{"answer":"$3(2x + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+3) = 3x+9 no; 3(2x+9) = 6x+27 no; 3(2x+3) = 6x+9 yes; 6(x+3) = 6x+18 no.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d554de3a-0085-4f85-80fe-4cb9fe7c9a7c', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which expression is equivalent to $7x + 2x$?', '["$9x$","$14x$","$5x$","$9x^2$"]', '$9x$', NULL, '$7x$ and $2x$ are like terms, so add their coefficients: 7 + 2 = 9. The result is $9x$. (14x multiplies the coefficients, 5x subtracts them, and 9x^2 wrongly changes the exponent.)', 'checked', '{"lint":[],"solve":{"answer":"$9x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x + 2x = (7+2)x = 9x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be082eec-cf8f-4e24-b51a-5d68e822dfa8', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'Mia writes $6n + 8 - 2n$ in simplest form as $an + 8$. What is the value of $a$?', '[]', '4', '6-2', 'Combine the like terms $6n$ and $-2n$: 6 - 2 = 4. So $6n + 8 - 2n = 4n + 8$ and a = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6n - 2n = 4n, so 6n + 8 - 2n = 4n + 8; a = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1a6a96c-0e06-4cde-9e7f-ff96d8904ef8', 'NC26.7.ANR.2', 1, 'choice', 'Combine like terms', 'Which two terms are like terms?', '["$3x$ and $5$","$3x$ and $5x$","$3x$ and $3y$","$3x$ and $3x^2$"]', '$3x$ and $5x$', NULL, 'Like terms have exactly the same variable part. $3x$ and $5x$ both have $x$, so they are like terms and can be combined. A number alone, a different letter, or $x^2$ is a different kind of term.', 'checked', '{"lint":[],"solve":{"answer":"$3x$ and $5x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Like terms have the same variable to the same power: 3x and 5x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c534e05d-8472-4a71-a65f-0d105fc1523c', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'What is the coefficient of $y$ in the simplified form of $10y - 4y + 3$?', '[]', '6', '10-4', '$10y - 4y = 6y$, so the simplified form is $6y + 3$. The coefficient of $y$ is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10y - 4y + 3 = 6y + 3; coefficient 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10a7e9dc-50c1-4418-90af-d831f516b62c', 'NC26.7.ANR.2', 1, 'numeric', 'Combine like terms', 'A square has sides that each measure $x$ units. Its perimeter is $x + x + x + x$, which is equivalent to $kx$. What is the value of $k$?', '[]', '4', '1+1+1+1', 'Adding $x$ four times gives 4 groups of $x$, which is $4x$. So k = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x + x + x = 4x; k = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd302a88-b18c-4bc3-825f-4efa6a1d81cd', 'NC26.7.ANR.2', 1, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $4(n + 3)$?', '["$4n + 3$","$n + 12$","$4n + 7$","$4n + 12$"]', '$4n + 12$', NULL, 'Multiply 4 by each term inside the parentheses: 4 times $n$ is $4n$ and 4 times 3 is 12. The result is $4n + 12$. (4n + 3 forgets to multiply the 3.)', 'checked', '{"lint":[],"solve":{"answer":"$4n + 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(n + 3) = 4n + 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('220da562-c828-4a49-b2d6-74242357a9bc', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'In the equation $5(x + 3) = 5x + k$, the number $k$ makes both sides equal for every value of $x$. What is $k$?', '[]', '15', '5*3', 'By the distributive property, $5(x + 3) = 5x + 5 \times 3 = 5x + 15$. So k = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x + 3) = 5x + 15, so k = 15.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('694868cd-60aa-4f58-b647-0aa7c500777a', 'NC26.7.ANR.2', 1, 'choice', 'Expand with the distributive property', 'A rectangle is 6 units wide and $(y + 2)$ units long. Which expression, written without parentheses, gives its area in square units?', '["$6y + 2$","$y + 12$","$6y + 12$","$6y + 8$"]', '$6y + 12$', NULL, 'Area is width times length: $6(y + 2)$. Distribute the 6: 6 times $y$ is $6y$ and 6 times 2 is 12, so the area is $6y + 12$.', 'checked', '{"lint":[],"solve":{"answer":"$6y + 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 6(y + 2) = 6y + 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cae6892-7dc3-44fa-ae8d-18619c50a6fe', 'NC26.7.ANR.2', 1, 'numeric', 'Expand with the distributive property', 'Using the distributive property, $2(x + 9)$ can be written as $ax + b$. What is the value of $a + b$?', '[]', '20', '2+2*9', '$2(x + 9) = 2x + 18$, so a = 2 and b = 18. Then a + b = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x + 9) = 2x + 18; a = 2, b = 18; a + b = 20.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d298040c-480d-4b10-920f-d41f56bc4f49', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $5x + 10$?', '["$5(x + 10)$","$10(x + 5)$","$x(5 + 10)$","$5(x + 2)$"]', '$5(x + 2)$', NULL, 'Both terms have a factor of 5: $5x = 5 \times x$ and $10 = 5 \times 2$. So $5x + 10 = 5(x + 2)$. Check by distributing: $5(x + 2) = 5x + 10$.', 'checked', '{"lint":[],"solve":{"answer":"$5(x + 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x + 2) = 5x + 10. Others: 5x+50, 15x, 10x+50.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c0c3e3-ff01-43af-8ce5-37c0174da0dc', 'NC26.7.ANR.2', 1, 'numeric', 'Factor out a common factor', 'To factor $12x + 20$, Lena first looks for the greatest common factor of 12 and 20. What is it?', '[]', '4', NULL, 'The factors of 12 are 1, 2, 3, 4, 6, 12 and the factors of 20 are 1, 2, 4, 5, 10, 20. The greatest factor in both lists is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 12: 1,2,3,4,6,12; of 20: 1,2,4,5,10,20. GCF = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d109f3ab-960a-4ec3-ad85-47c40d923c92', 'NC26.7.ANR.2', 1, 'numeric', 'Factor out a common factor', 'Fill in the missing number: $4x + 20 = 4(x + k)$. What is the value of $k$?', '[]', '5', '20/4', 'Since 4 times k must equal 20, k = 20 / 4 = 5. Check: $4(x + 5) = 4x + 20$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + k) = 4x + 4k = 4x + 20, so 4k = 20, k = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c70c362-897b-4ffe-9b36-c3aaad655006', 'NC26.7.ANR.2', 1, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $3a + 3b$?', '["$3ab$","$6(a + b)$","$3(a + b)$","$a + b + 3$"]', '$3(a + b)$', NULL, 'Both terms have a factor of 3, so $3a + 3b = 3(a + b)$. (3ab multiplies instead of adding, and 6(a + b) = 6a + 6b.)', 'checked', '{"lint":[],"solve":{"answer":"$3(a + b)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3a + 3b = 3(a + b).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('785b4bca-ca54-481c-8b34-4ca2666cb4c9', 'NC26.7.ANR.2', 1, 'numeric', 'Factor out a common factor', 'Fill in the missing number so that $10 + 5y = 5(k + y)$ for every value of $y$. What is $k$?', '[]', '2', '10/5', 'The number 10 is 5 times 2, so $10 + 5y = 5(2 + y)$ and k = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(k + y) = 5k + 5y = 10 + 5y, so 5k = 10, k = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65a20628-8b99-47c5-a45d-a9b97fe9769b', 'NC26.7.ANR.2', 1, 'choice', 'Decide whether two expressions are equivalent', 'Which expression is NOT equivalent to $2x + 6$?', '["$8x$","$2(x + 3)$","$6 + 2x$","$x + x + 6$"]', '$8x$', NULL, '$2(x + 3) = 2x + 6$, $6 + 2x$ is the same sum in a different order, and $x + x + 6 = 2x + 6$. But $2x + 6$ cannot be combined into $8x$, because $2x$ and 6 are not like terms. The answer is $8x$.', 'checked', '{"lint":[],"solve":{"answer":"$8x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 2x (commutative), 2(x+3) = 2x+6, x+x+6 = 2x+6 are equivalent; 8x is not (unlike terms cannot combine).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bc236d1-6b3e-4ddd-8955-0c499c58951a', 'NC26.7.ANR.2', 1, 'choice', 'Decide whether two expressions are equivalent', 'Ana, Ben and Cy each simplify $3x + 4x$. Ana gets $7x$, Ben gets $12x$ and Cy gets $7x^2$. Who is correct?', '["Ben","Ana","Cy","Ana and Ben"]', 'Ana', NULL, 'Like terms are combined by adding their coefficients: 3 + 4 = 7, and the variable part stays $x$. So $3x + 4x = 7x$ and only Ana is correct.', 'checked', '{"lint":[],"solve":{"answer":"Ana","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 4x = 7x. Ana is right; Ben multiplied, Cy multiplied the variables.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed2f43c2-9d4e-45fa-8d38-27c68b6e3071', 'NC26.7.ANR.2', 1, 'numeric', 'Decide whether two expressions are equivalent', 'Both $4(x + 2)$ and $4x + 8$ have the same value for every number $x$. What is that value when $x = 3$?', '[]', '20', '4*(3+2)', 'Using the first form, $4(3 + 2) = 4 \times 5 = 20$. Using the second, $4 \times 3 + 8 = 12 + 8 = 20$. The values match.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(3 + 2) = 20; 4(3) + 8 = 20.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96560063-efae-4196-80e9-0dc216329340', 'NC26.7.ANR.2', 1, 'choice', 'Decide whether two expressions are equivalent', 'Which equation is true for every value of $x$?', '["$3(x + 1) = 3x + 3$","$3(x + 1) = 3x + 1$","$3(x + 1) = x + 3$","$3(x + 1) = 3x + x + 1$"]', '$3(x + 1) = 3x + 3$', NULL, 'Distribute the 3 on the left: $3(x + 1) = 3x + 3$, which matches the right side exactly. In the other equations the two sides differ for most values of $x$ (try x = 2).', 'checked', '{"lint":[],"solve":{"answer":"$3(x + 1) = 3x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 1) = 3x + 3 for every x. Others fail, e.g. x = 1: 6 vs 4, 6 vs 5, 6 vs 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a44d5a9f-6cf3-4366-aadf-0b890082ea1d', 'NC26.7.ANR.2', 1, 'choice', 'Expressions with fraction or decimal coefficients', 'Which expression is equivalent to $0.5x + 0.5x$?', '["$0.25x$","$x$","$0.5x$","$1.5x$"]', '$x$', NULL, 'Add the coefficients: 0.5 + 0.5 = 1, so the sum is 1 group of $x$, which is $x$.', 'checked', '{"lint":[],"solve":{"answer":"$x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5x + 0.5x = 1x = x.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ecc5adc-6c17-45c8-a7a4-dd2f0505d7ea', 'NC26.7.ANR.2', 1, 'numeric', 'Expressions with fraction or decimal coefficients', 'Simplify $\frac{1}{4}y + \frac{3}{4}y$. The result can be written as $ky$. What is the value of $k$?', '[]', '1', '1/4+3/4', 'Add the coefficients: $\frac{1}{4} + \frac{3}{4} = \frac{4}{4} = 1$. So the sum is $1y$, which is $y$, and k = 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 + 3/4 = 1, so the sum is 1y; k = 1.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c03f13a0-a085-4e6f-988f-da100a469959', 'NC26.7.ANR.2', 1, 'numeric', 'Expressions with fraction or decimal coefficients', 'Combine the like terms: $0.3x + 0.2x$ is the same as $kx$. What is the value of $k$?', '[]', '0.5', '0.3+0.2', 'Add the coefficients: 0.3 + 0.2 = 0.5. So k = 0.5.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3 + 0.2 = 0.5; k = 0.5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4cf6196-a154-4cff-8c09-039c84cf2ce2', 'NC26.7.ANR.2', 1, 'choice', 'Write an expression for a situation', 'Sam buys 3 notebooks that cost $n$ dollars each and one pen that costs 2 dollars. Which expression shows the total cost in dollars?', '["$3(n + 2)$","$5n$","$3n + 2$","$n + 3 + 2$"]', '$3n + 2$', NULL, 'The notebooks cost $3 \times n = 3n$ dollars and the pen costs 2 dollars, so the total is $3n + 2$. (3(n + 2) would mean 3 pens as well.)', 'checked', '{"lint":[],"solve":{"answer":"$3n + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 notebooks at n dollars = 3n, plus 2 for the pen: 3n + 2. 3(n + 2) would add 2 per notebook.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7bc9470-9150-4e83-a6a6-0e5e96a2fdcb', 'NC26.7.ANR.2', 1, 'choice', 'Write an expression for a situation', 'Which expression shows ''five less than twice a number $n$''?', '["$5 - 2n$","$2(n - 5)$","$2n + 5$","$2n - 5$"]', '$2n - 5$', NULL, 'Twice the number is $2n$. Five less than that is $2n - 5$. (5 - 2n subtracts in the wrong order, and 2(n - 5) subtracts 5 before doubling.)', 'checked', '{"lint":[],"solve":{"answer":"$2n - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice n is 2n; five less than that is 2n - 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f0d4715-550a-452c-957f-d35571d301b0', 'NC26.7.ANR.2', 1, 'choice', 'What an equivalent form shows in context', 'A ticket booth sells $x$ tickets at 4 dollars each and adds a 6 dollar fee. The total cost is $4x + 6$ dollars. What does the 6 stand for?', '["The price of one ticket, in dollars","The number of tickets sold","The total cost, in dollars","The one-time fee, in dollars"]', 'The one-time fee, in dollars', NULL, 'The term $4x$ is the cost of the tickets (4 dollars each for $x$ tickets). The 6 does not change with the number of tickets, so it is the one-time fee.', 'checked', '{"lint":[],"solve":{"answer":"The one-time fee, in dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x is the ticket cost (4 dollars times x tickets); the added 6 is the one-time fee.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf7881ac-2b35-407e-9342-002b406b570d', 'NC26.7.ANR.2', 1, 'numeric', 'What an equivalent form shows in context', 'A school trip has 3 buses. Each bus carries $x$ students and 2 teachers. The total number of people is $3x + 6$. How many teachers are on the trip?', '[]', '6', '3*2', 'The term $3x$ counts the students. The 6 counts the teachers: 3 buses with 2 teachers each is $3 \times 2 = 6$ teachers.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 buses x 2 teachers = 6; this is the 6 in 3(x + 2) = 3x + 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18f155d2-2624-40b9-89a1-321d2073e63d', 'NC26.7.ANR.2', 1, 'choice', 'Name the property of operations', 'Which property is shown by $3 + x = x + 3$?', '["Commutative property of addition","Associative property of addition","Distributive property","Identity property of addition"]', 'Commutative property of addition', NULL, 'The order of the two numbers being added was swapped and the sum stayed the same. That is the commutative property of addition.', 'checked', '{"lint":[],"solve":{"answer":"Commutative property of addition","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order of the addends is swapped: commutative property of addition.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c32768e-498a-4c7f-99ca-0a34fdc18668', 'NC26.7.ANR.2', 1, 'choice', 'Name the property of operations', 'Which property lets you rewrite $2(x + 5)$ as $2x + 10$?', '["Commutative property of multiplication","Associative property of addition","Distributive property","Identity property of multiplication"]', 'Distributive property', NULL, 'Multiplying 2 by each term inside the parentheses, $2 \times x$ and $2 \times 5$, is the distributive property.', 'checked', '{"lint":[],"solve":{"answer":"Distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x + 5) = 2x + 10 multiplies 2 across the sum: distributive property.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1895a8d6-7d56-4457-852a-6c7d789d53fa', 'NC26.7.ANR.2', 1, 'choice', 'Add and subtract linear expressions', 'What is the sum of $2x + 3$ and $4x + 1$?', '["$6x + 2$","$6x + 4$","$8x + 4$","$6x^2 + 4$"]', '$6x + 4$', NULL, 'Add the $x$ terms: 2x + 4x = 6x. Add the numbers: 3 + 1 = 4. The sum is $6x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x + 4x) + (3 + 1) = 6x + 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07177cda-9476-4ef5-8fc1-4f865881f8b6', 'NC26.7.ANR.2', 1, 'numeric', 'Distribute and combine like terms', 'The expression $2(x + 1) + 3x$ simplifies to $ax + 2$. What is the value of $a$?', '[]', '5', '2+3', 'Distribute: $2(x + 1) = 2x + 2$. Then $2x + 2 + 3x = 5x + 2$. So a = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 2 + 3x = 5x + 2; a = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05109b40-938f-4079-bb8e-b2de35c310c0', 'NC26.7.ANR.2', 1, 'numeric', 'Use the distributive property to write an equivalent expression', 'The expression $3(x + 4)$ is equivalent to $3x + \square$. What number goes in the box?', '[]', '12', '3*4', 'Multiply each part inside the parentheses by 3: $3(x + 4) = 3 \times x + 3 \times 4 = 3x + 12$. The number in the box is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x+4)=3x+12.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80fc6ada-e220-4b6b-bd9c-16a84c850639', 'NC26.7.ANR.2', 2, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $2(3x - 4) + 5x$?', '["$11x - 4$","$11x - 8$","$11x + 8$","$x - 8$"]', '$11x - 8$', NULL, 'Distribute: $2(3x - 4) = 6x - 8$. Add $5x$: $6x + 5x - 8 = 11x - 8$.', 'checked', '{"lint":[],"solve":{"answer":"$11x - 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(3x - 4) = 6x - 8; plus 5x gives 11x - 8.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d65d561-3dfe-493d-8cb4-b02ac3332335', 'NC26.7.ANR.2', 2, 'numeric', 'Distribute a negative factor', 'The expression $-2(x - 3) + 4x$ is equivalent to $2x + k$. What is the value of $k$?', '[]', '6', '(-2)*(-3)', 'Distribute: $-2(x - 3) = -2x + 6$. Then $-2x + 6 + 4x = 2x + 6$, so $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2(x - 3) = -2x + 6; plus 4x gives 2x + 6, so k = 6.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f843ccb6-cea1-470c-8557-c47d31625ddb', 'NC26.7.ANR.2', 2, 'numeric', 'Factor a linear expression and read the factors', 'The expression $12x + 18$ can be written as $6(ax + b)$. What is the value of $a + b$?', '[]', '5', '12/6+18/6', '$12x \div 6 = 2x$ and $18 \div 6 = 3$, so $12x + 18 = 6(2x + 3)$. Then $a = 2$, $b = 3$ and $a + b = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(ax + b) = 6ax + 6b = 12x + 18, so a = 2, b = 3 (unique). a + b = 5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c0d937c-651e-4f82-afa2-6cf0b2b307d6', 'NC26.7.ANR.2', 2, 'numeric', 'Combine like terms', 'How many terms does the simplest form of $3x + 2 + 5x - 2$ have?', '[]', '1', NULL, 'Combine the $x$ terms: 3x + 5x = 8x. Combine the numbers: 2 - 2 = 0. The simplest form is $8x$, which has just 1 term.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 5x = 8x; 2 - 2 = 0. Simplest form 8x has 1 term.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abb29681-c7fd-404b-b7ca-f5d73c35b1b7', 'NC26.7.ANR.2', 2, 'choice', 'Combine like terms', 'Which expression is equivalent to $4a - 7 + 3a + 10$?', '["$7a - 3$","$7a + 17$","$7a - 17$","$7a + 3$"]', '$7a + 3$', NULL, 'Combine the $a$ terms: 4a + 3a = 7a. Combine the numbers: -7 + 10 = 3. The result is $7a + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$7a + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4a + 3a = 7a; -7 + 10 = 3: 7a + 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92f9df2b-433f-4497-a926-51f13da944c3', 'NC26.7.ANR.2', 2, 'numeric', 'Combine like terms', 'The expression $9x - 4 - 6x - 5$ is equivalent to $ax + b$. What is the value of $b$?', '[]', '-9', '-4-5', 'The numbers are -4 and -5, which combine to -9. (The $x$ terms give 9x - 6x = 3x.) So $9x - 4 - 6x - 5 = 3x - 9$ and b = -9.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9x - 6x = 3x; -4 - 5 = -9: 3x - 9, b = -9.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8221185e-5d2e-471e-813b-14ea4bed8654', 'NC26.7.ANR.2', 2, 'choice', 'Combine like terms', 'Which expression is equivalent to $5x + 3y - 2x + y$?', '["$3x + 4y$","$3x + 2y$","$7x + 4y$","$3x + 3y$"]', '$3x + 4y$', NULL, 'Combine the $x$ terms: 5x - 2x = 3x. Combine the $y$ terms: 3y + y = 4y (remember $y$ means 1y). The result is $3x + 4y$.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 4y$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 2x = 3x; 3y + y = 4y: 3x + 4y.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('674f6224-fae8-45bd-ba30-a99559a92a06', 'NC26.7.ANR.2', 2, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $-3(x + 4)$?', '["$-3x + 12$","$3x - 12$","$-3x - 12$","$-3x + 4$"]', '$-3x - 12$', NULL, 'Multiply -3 by each term: (-3)(x) = -3x and (-3)(4) = -12. The result is $-3x - 12$.', 'checked', '{"lint":[],"solve":{"answer":"$-3x - 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3(x) + (-3)(4) = -3x - 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
