INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('883a0e9a-b6bc-48d7-bdcb-e1a5e75c7ded', 'NC26.7.ANR.2', 3, 'choice', 'Expand with the distributive property', 'Which expression is equivalent to $-\frac{1}{2}(8x - 6)$?', '["$-4x - 3$","$4x - 3$","$-4x + 6$","$-4x + 3$"]', '$-4x + 3$', NULL, 'Multiply each term by -1/2: (-1/2)(8x) = -4x and (-1/2)(-6) = +3. The result is $-4x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$-4x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1/2(8x) = -4x; -1/2(-6) = 3: -4x + 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
