INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6768c8f-fa56-4443-9e3f-f744ef2fa90d', 'NC26.7.ANR.2', 3, 'numeric', 'Distribute and combine like terms', 'After $5(2x + 1) - 3(x + 4)$ is simplified, what is the constant term (the number with no variable)?', '[]', '-7', '5*1-3*4', 'Distribute: $5(2x + 1) = 10x + 5$ and $-3(x + 4) = -3x - 12$. Together, $10x + 5 - 3x - 12 = 7x - 7$. The constant term is 5 - 12 = -7.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x + 5 - 3x - 12 = 7x - 7; constant -7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
