INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42c79a51-e37f-465b-9eca-c8bcbac70412', 'NC26.7.ANR.2', 3, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $2(3x + 4) - 5(x - 1) + 6$?', '["$x + 9$","$11x + 19$","$x + 19$","$x + 13$"]', '$x + 19$', NULL, 'Distribute: $2(3x + 4) = 6x + 8$ and $-5(x - 1) = -5x + 5$. Then $6x + 8 - 5x + 5 + 6 = x + 19$. (x + 9 forgets that -5 times -1 is +5.)', 'checked', '{"lint":[],"solve":{"answer":"$x + 19$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 8 - 5x + 5 + 6 = x + 19.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46d7ebb6-fea2-49d9-9aef-63a3e2a9a64c', 'NC26.7.ANR.2', 3, 'numeric', 'Distribute and combine like terms', 'The expression $-3(x - 4) + 2(2x + 1)$ is equivalent to $x + k$. What is the value of $k$?', '[]', '14', '(-3)*(-4)+2*1', 'Distribute: $-3(x - 4) = -3x + 12$ and $2(2x + 1) = 4x + 2$. Then $-3x + 12 + 4x + 2 = x + 14$, so k = 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x + 12 + 4x + 2 = x + 14; k = 14.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cff14491-f9ff-478b-8fb5-4648a1c3ab12', 'NC26.7.ANR.2', 3, 'choice', 'Distribute and combine like terms', 'Which expression is equivalent to $\frac{1}{2}(4x - 8) - (x - 3)$?', '["$x - 7$","$x + 1$","$3x - 7$","$x - 1$"]', '$x - 1$', NULL, 'Half of the first group is $2x - 4$. The minus sign changes both terms of the second group: $-(x - 3) = -x + 3$. Then $2x - 4 - x + 3 = x - 1$.', 'checked', '{"lint":[],"solve":{"answer":"$x - 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 4 - x + 3 = x - 1.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65db60af-1ad2-4b4c-8917-8b3ef58430a8', 'NC26.7.ANR.2', 3, 'choice', 'Factor out a common factor', 'Factor -3 out of $-6x - 9$. Which expression is the result?', '["$-3(2x - 3)$","$-3(2x + 3)$","$3(2x + 3)$","$-3(2x + 9)$"]', '$-3(2x + 3)$', NULL, 'Factor out -3: (-6x) / (-3) = 2x and (-9) / (-3) = 3. So $-6x - 9 = -3(2x + 3)$. Check: $-3(2x + 3) = -6x - 9$.', 'checked', '{"lint":[],"solve":{"answer":"$-3(2x + 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6x - 9 = -3(2x) + (-3)(3) = -3(2x + 3).","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f41dd5f-ee4a-4bfb-81a0-45f6877665bc', 'NC26.7.ANR.2', 3, 'numeric', 'Factor out a common factor', 'The expression $18x - 45$ can be written as $9(ax - b)$, where a and b are positive whole numbers. What is the value of $a + b$?', '[]', '7', '18/9+45/9', 'Divide each term by 9: 18x / 9 = 2x and 45 / 9 = 5. So $18x - 45 = 9(2x - 5)$, a = 2, b = 5 and a + b = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18x - 45 = 9(2x - 5); a = 2, b = 5; sum 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a20712be-7d82-4eae-9e4f-b1df31657290', 'NC26.7.ANR.2', 3, 'choice', 'Factor out a common factor', 'Which expression is NOT a way to write $12x + 30$?', '["$12(x + 30)$","$6(2x + 5)$","$3(4x + 10)$","$2(6x + 15)$"]', '$12(x + 30)$', NULL, '$6(2x + 5) = 12x + 30$, $3(4x + 10) = 12x + 30$ and $2(6x + 15) = 12x + 30$. But $12(x + 30) = 12x + 360$, so it is the one that is not equal.', 'checked', '{"lint":[],"solve":{"answer":"$12(x + 30)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(2x+5), 3(4x+10), 2(6x+15) all give 12x + 30; 12(x + 30) = 12x + 360.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71c6e653-f692-4f9b-a65e-23786d977aab', 'NC26.7.ANR.2', 3, 'numeric', 'Factor out a common factor', 'The expression $\frac{3}{4}x + \frac{3}{2}$ can be written as $\frac{3}{4}(x + k)$. What is the value of $k$?', '[]', '2', '(3/2)/(3/4)', 'Factor out 3/4. The first term gives $x$. For the second term, $\frac{3}{4} \times k = \frac{3}{2}$, so k = (3/2) / (3/4) = 2. Check: $\frac{3}{4}(x + 2) = \frac{3}{4}x + \frac{3}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)k = 3/2, k = (3/2)(4/3) = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4838e900-853f-4599-a96a-1f56d71d77a3', 'NC26.7.ANR.2', 3, 'choice', 'Factor out a common factor', 'Which expression is equivalent to $15x + 20y$?', '["$5(3x + 20y)$","$5(x + y)$","$5(3x + 4y)$","$15(x + 20y)$"]', '$5(3x + 4y)$', NULL, 'The greatest common factor of 15 and 20 is 5. Divide each term by 5: 15x / 5 = 3x and 20y / 5 = 4y. So $15x + 20y = 5(3x + 4y)$.', 'checked', '{"lint":[],"solve":{"answer":"$5(3x + 4y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GCF 5: 15x + 20y = 5(3x + 4y). Others expand to 15x+300y, 5x+5y, 15x+100y.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('abef06f6-841b-47db-859a-dce6d75f9c60', 'NC26.7.ANR.2', 3, 'choice', 'Decide whether two expressions are equivalent', 'Leo tests $x = 1$: both $4(x + 1)$ and $3x + 5$ equal 8. Leo says the two expressions are equivalent. Which statement is true?', '["They are equivalent: both give 8 when $x = 1$","They are equivalent: one test value is enough to prove it","They are equivalent, because $4(x + 1)$ means $4x + 1$","They are not equivalent: when $x = 2$, the first gives 12 and the second gives 11"]', 'They are not equivalent: when $x = 2$, the first gives 12 and the second gives 11', NULL, 'Equivalent expressions must have the same value for every $x$. When $x = 2$, $4(2 + 1) = 12$ but $3 \times 2 + 5 = 11$, so they are not equivalent. Matching at one value (here $x = 1$) does not prove equivalence, and $4(x + 1) = 4x + 4$.', 'checked', '{"lint":[],"solve":{"answer":"They are not equivalent: when $x = 2$, the first gives 12 and the second gives 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 1) = 4x + 4, 3x + 5 differ. x = 2: 4(3) = 12, 3(2) + 5 = 11. So not equivalent; the third statement is true.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6beb3214-f0dc-49d1-8946-07a644b06d3f', 'NC26.7.ANR.2', 3, 'numeric', 'Decide whether two expressions are equivalent', 'For what value of $k$ are $4(x + k)$ and $4x - 28$ equivalent?', '[]', '-7', '-28/4', 'Distribute: $4(x + k) = 4x + 4k$. For this to equal $4x - 28$, 4k = -28, so k = -7.', 'checked', '{"lint":[],"solve":{"answer":"-7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + k) = 4x + 4k = 4x - 28, so k = -7.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9df2b81f-e617-42f4-bab4-87ef303627af', 'NC26.7.ANR.2', 3, 'choice', 'Decide whether two expressions are equivalent', 'Which statement about $x + x$ and $x^2$ is true?', '["They have the same value when $x = 2$, but they are not equivalent","They are equivalent, because they have the same value when $x = 2$","They are equivalent, because $x + x$ means $x$ times $x$","They are not equivalent, because they have different values when $x = 0$"]', 'They have the same value when $x = 2$, but they are not equivalent', NULL, '$x + x = 2x$, not $x^2$. When $x = 2$, both are 4, but when $x = 3$, $x + x = 6$ and $x^2 = 9$. Equivalent expressions must match for every value, so they are not equivalent. (When $x = 0$ both are 0.)', 'checked', '{"lint":[],"solve":{"answer":"They have the same value when $x = 2$, but they are not equivalent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x = 2x. At x = 2: 4 and 4 (same). At x = 0: 0 and 0 (same, so option A''s reason is false). At x = 1: 2 vs 1, so not equivalent. Option D is true.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51720886-ba2d-42f7-ae90-42d5d4a1d35e', 'NC26.7.ANR.2', 3, 'numeric', 'Expressions with fraction or decimal coefficients', 'The expression $0.4(5x - 10) + 1.5x$ is equivalent to $ax + b$. What is the value of $a + b$?', '[]', '-0.5', '3.5-4', 'Distribute: $0.4(5x - 10) = 2x - 4$. Then $2x - 4 + 1.5x = 3.5x - 4$, so a = 3.5 and b = -4. Then a + b = -0.5.', 'checked', '{"lint":[],"solve":{"answer":"-0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4(5x) = 2x; 0.4(-10) = -4; 2x - 4 + 1.5x = 3.5x - 4; a + b = -0.5.","run_id":"claude-code","at":"2026-10-17T20:22:53.533Z"}}', 'ai', NULL, NULL)
