INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0284d377-fca5-4ad9-a396-d9a06385b196', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation', 'What value of $x$ makes $2x + 7 = 19$ true?', '[]', '6', '(19-7)/2', 'Subtract 7 from both sides: $2x = 12$. Divide both sides by 2: $x = 6$. Check: $2 \times 6 + 7 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x = 19 - 7 = 12; x = 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
