INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7fadc33f-a24c-4c89-aa9c-e0341fd35e7b', 'NC26.7.ANR.3', 1, 'choice', 'Solve a two-step equation', 'Which value of $x$ is the solution of $4x + 1 = 17$?', '["4.5","4.25","4","16"]', '4', '(17-1)/4', 'Subtract 1 from both sides: $4x = 16$. Divide by 4: $x = 4$. (4.5 comes from adding 1 instead of subtracting it, 4.25 from forgetting to subtract 1, and 16 from forgetting to divide by 4.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x = 16; x = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
