INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de18e029-f0c3-4e09-a3c0-ceb6951b2ef0', 'NC26.7.ANR.3', 1, 'numeric', 'Solve a two-step equation', 'Find the value of $x$ if $\frac{x}{3} + 2 = 6$.', '[]', '12', '(6-2)*3', 'Subtract 2 from both sides: $\frac{x}{3} = 4$. Multiply both sides by 3: $x = 12$. Check: $\frac{12}{3} + 2 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/3 = 4; x = 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
