INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('792733ea-2b57-4ee0-bfcd-ee8ebafaf9ba', 'NC26.7.ANR.3', 1, 'choice', 'Solve an equation with parentheses', 'Which equation do you get by using the distributive property on the left side of $5(x + 2) = 30$?', '["$5x + 2 = 30$","$x + 10 = 30$","$5x + 7 = 30$","$5x + 10 = 30$"]', '$5x + 10 = 30$', NULL, 'Multiply 5 by each term in the parentheses: $5 \times x = 5x$ and $5 \times 2 = 10$. The equation becomes $5x + 10 = 30$. (5x + 2 forgets to multiply the 2.)', 'checked', '{"lint":[],"solve":{"answer":"$5x + 10 = 30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x + 2) = 5x + 10, so 5x + 10 = 30.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
