VALUES ('d3c499e8-c5d8-47b0-aa6c-c7dbaa0d8a7c', 'NC26.7.ANR.3', 1, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'What is the value of $x$ if $x + 2.5 = 6$?', '[]', '3.5', '6-2.5', 'Subtract 2.5 from both sides: $x = 6 - 2.5 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 6 - 2.5 = 3.5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
