VALUES ('36121f36-f05a-4d0f-97b7-cce7e6bf1048', 'NC26.7.ANR.3', 1, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Solve for $x$: $-3x = 12$.', '[]', '-4', '12/(-3)', 'Divide both sides by -3: $x = -4$. Check: $-3 \times (-4) = 12$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 12 / (-3) = -4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
