INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0918a8c-ffe6-4719-a62f-6abfef0cb9af', 'NC26.7.ANR.3', 1, 'choice', 'Write and solve an equation from a situation', 'A number $n$ is multiplied by 4, and then 3 is added. The result is 19. Which equation matches this?', '["$4(n + 3) = 19$","$4n + 3 = 19$","$4n - 3 = 19$","$n + 7 = 19$"]', '$4n + 3 = 19$', NULL, 'Multiplying $n$ by 4 gives $4n$, and adding 3 gives $4n + 3$. The equation is $4n + 3 = 19$. (4(n + 3) adds 3 first, then multiplies.)', 'checked', '{"lint":[],"solve":{"answer":"$4n + 3 = 19$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4n, then + 3: 4n + 3 = 19.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59d4ab8c-d43e-443f-afa7-a06928b5e436', 'NC26.7.ANR.3', 1, 'numeric', 'Write and solve an equation from a situation', 'Maria buys 4 pencils that each cost the same and an eraser that costs 2 dollars. She pays 10 dollars in all. How many dollars does one pencil cost?', '[]', '2', '(10-2)/4', 'Let $p$ be the price of one pencil. Then $4p + 2 = 10$. Subtract 2: $4p = 8$. Divide by 4: $p = 2$. One pencil costs 2 dollars.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4p + 2 = 10; 4p = 8; p = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
