INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c8d3578-fc68-47e4-bf4d-9d8065cb33f7', 'NC26.7.ANR.3', 1, 'numeric', 'Write and solve an equation from a situation', 'A phone plan costs 12 dollars a month plus 4 dollars for each extra gigabyte. One month the bill was 32 dollars. How many extra gigabytes were used?', '[]', '5', '(32-12)/4', 'Let $g$ be the extra gigabytes. Then $12 + 4g = 32$. Subtract 12: $4g = 20$. Divide by 4: $g = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 4g = 32; 4g = 20; g = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('761e9cb6-eaee-4e86-a122-dd5965ce2a1d', 'NC26.7.ANR.3', 1, 'choice', 'Write and solve an equation from a situation', 'Which equation matches the sentence "The sum of twice a number $n$ and 9 is 21"?', '["$2n + 9 = 21$","$2(n + 9) = 21$","$2 + n + 9 = 21$","$2n - 9 = 21$"]', '$2n + 9 = 21$', NULL, 'Twice the number is $2n$. The sum of $2n$ and 9 is $2n + 9$, and it is equal to 21. (2(n + 9) would double the sum.)', 'checked', '{"lint":[],"solve":{"answer":"$2n + 9 = 21$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice n is 2n; sum with 9: 2n + 9 = 21.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88ac1bef-15b3-408d-82c3-bc899d5f26e6', 'NC26.7.ANR.3', 1, 'choice', 'Solve an inequality', 'Which inequality shows all the solutions of $x - 3 > 5$?', '["$x > 8$","$x < 8$","$x > 2$","$x < 2$"]', '$x > 8$', NULL, 'Add 3 to both sides: $x > 8$. The direction of the sign does not change. (x > 2 subtracts 3 instead of adding it.)', 'checked', '{"lint":[],"solve":{"answer":"$x > 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add 3: x > 8.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56548ebc-ba47-4b6a-81d8-ea06fc849e44', 'NC26.7.ANR.3', 1, 'choice', 'Solve an inequality', 'What are all the solutions of $3x < 12$?', '["$x > 4$","$x < 9$","$x < 4$","$x < 15$"]', '$x < 4$', NULL, 'Divide both sides by 3: $x < 4$. (x < 9 subtracts 3, and x < 15 adds 3.)', 'checked', '{"lint":[],"solve":{"answer":"$x < 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by 3: x < 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
