INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6edf888e-ae24-4461-a701-1ffe1a932aa4', 'NC26.7.ANR.3', 1, 'numeric', 'Solve an inequality', 'What is the greatest whole number that is a solution of $x + 2 < 9$?', '[]', '6', NULL, 'Subtract 2 from both sides: $x < 7$. The whole numbers less than 7 are 0, 1, ..., 6, so the greatest is 6. (7 is not a solution because 7 + 2 = 9, which is not less than 9.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x < 7; greatest whole number is 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67dd75f4-ff75-4af8-a0b0-17e4d4a455b4', 'NC26.7.ANR.3', 1, 'numeric', 'Solve an inequality', 'What is the smallest whole number that is a solution of $x - 2 \ge 3$?', '[]', '5', NULL, 'Add 2 to both sides: $x \ge 5$. Because of the "or equal to", 5 itself is a solution, so the smallest whole number is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x >= 5; smallest whole number is 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
