INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a2ff965-b863-4e02-96a3-17d0ce5d631d', 'NC26.7.ANR.3', 1, 'choice', 'Solve an inequality', 'Which inequality has the same solutions as $\frac{x}{2} > 3$?', '["$x < 6$","$x > 1.5$","$x > 5$","$x > 6$"]', '$x > 6$', NULL, 'Multiply both sides by 2: $x > 6$. (x > 1.5 divides by 2 instead of multiplying, and x > 5 adds 2.)', 'checked', '{"lint":[],"solve":{"answer":"$x > 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply by 2: x > 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
