INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ae81e33-cdb4-4537-864b-b2d92d2514ae', 'NC26.7.ANR.3', 1, 'choice', 'Write an inequality from a situation', 'A roller coaster ride requires riders to be at least 12 years old. Which inequality shows the ages $a$ that may ride?', '["$a \\le 12$","$a \\ge 12$","$a > 12$","$a < 12$"]', '$a \ge 12$', NULL, '"At least 12" means 12 or older, so $a \ge 12$. (a > 12 leaves out 12-year-olds.)', 'checked', '{"lint":[],"solve":{"answer":"$a \\ge 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least 12 means 12 or older: a >= 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
