INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bbdffde-e471-4e10-90a6-337b7dea0179', 'NC26.7.ANR.3', 1, 'choice', 'Write an inequality from a situation', 'Each book weighs $w$ pounds. A box can hold no more than 25 pounds. Which inequality shows that 3 books fit in the box?', '["$3w \\ge 25$","$w + 3 \\le 25$","$3w \\le 25$","$3w > 25$"]', '$3w \le 25$', NULL, 'Three books weigh $3 \times w = 3w$ pounds. The total must be no more than 25, so $3w \le 25$. (w + 3 adds 3 pounds instead of multiplying.)', 'checked', '{"lint":[],"solve":{"answer":"$3w \\le 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 books weigh 3w; no more than 25: 3w <= 25.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2acb5c2-787a-4868-a58e-50e2bae6a40c', 'NC26.7.ANR.3', 1, 'numeric', 'Interpret the solution of an inequality in context', 'Ben has 10 dollars to spend on pencils that cost 2 dollars each. The inequality $2p \le 10$ shows how many pencils $p$ he can buy. What is the greatest number of pencils he can buy?', '[]', '5', NULL, 'Divide both sides by 2: $p \le 5$. The greatest number of pencils is 5, which costs exactly 10 dollars.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2p <= 10; p <= 5; greatest is 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a53835e7-7ecc-4848-b34b-20ca980c57ff', 'NC26.7.ANR.3', 1, 'choice', 'Graph an inequality on a number line', 'On a number line, a graph has an open circle at $3$, and the part of the line to the right of $3$ is shaded. Which inequality does the graph show?', '["$x < 3$","$x \\ge 3$","$x \\le 3$","$x > 3$"]', '$x > 3$', NULL, 'An open circle means the number itself is not included, and shading to the right means larger numbers. So the graph shows $x > 3$.', 'checked', '{"lint":[],"solve":{"answer":"$x > 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Open circle: 3 not included; shaded right: greater. x > 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4da33233-479f-45c7-9bf2-5a9b371c7227', 'NC26.7.ANR.3', 1, 'choice', 'Graph an inequality on a number line', 'A graph on a number line has a closed circle at $-2$, with the line shaded to the left of the circle. Which inequality is graphed?', '["$x \\le -2$","$x \\ge -2$","$x < -2$","$x > -2$"]', '$x \le -2$', NULL, 'A closed circle means $-2$ is included, and shading to the left means smaller numbers. So the graph shows $x \le -2$.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le -2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Closed circle: -2 included; shaded left: less. x <= -2.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
