INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a69bbd2-3016-4b64-a1e0-f3dab020ff3f', 'NC26.7.ANR.3', 1, 'choice', 'Graph an inequality on a number line', 'Which description matches the graph of $x \ge 5$ on a number line?', '["An open circle at $5$ with the line shaded to the right","A closed circle at $5$ with the line shaded to the right","A closed circle at $5$ with the line shaded to the left","An open circle at $5$ with the line shaded to the left"]', 'A closed circle at $5$ with the line shaded to the right', NULL, 'The sign is "greater than or equal to", so 5 is included (closed circle) and the solutions are larger numbers (shading to the right).', 'checked', '{"lint":[],"solve":{"answer":"A closed circle at $5$ with the line shaded to the right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x >= 5 includes 5 (closed) and greater values (right).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
