INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dc945d6-f39b-4701-a3c7-f3b51aec772e', 'NC26.7.ANR.3', 1, 'numeric', 'Graph an inequality on a number line', 'The graph of an inequality on a number line has an open circle at $7$, and the line to the left of $7$ is shaded. What is the greatest whole number that is a solution?', '[]', '6', NULL, 'The graph shows $x < 7$. The open circle means 7 is not a solution, so the greatest whole number is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Graph is x < 7; greatest whole number is 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
