INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8462331b-2b56-49a3-bc2d-695ed2e1995b', 'NC26.7.ANR.3', 2, 'numeric', 'Solve a two-step equation', 'What is the solution of $7x - 12 = 23$?', '[]', '5', '(23+12)/7', 'Add 12 to both sides: $7x = 35$. Divide by 7: $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x = 35; x = 5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
