VALUES ('be532b55-c831-47d2-a3e6-976b597f3337', 'NC26.7.ANR.3', 2, 'numeric', 'Solve a two-step equation', 'Solve for $x$: $-2x + 5 = 17$.', '[]', '-6', '(17-5)/(-2)', 'Subtract 5 from both sides: $-2x = 12$. Divide both sides by -2: $x = -6$. Check: $-2 \times (-6) + 5 = 17$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x = 12; x = -6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
