VALUES ('7c5711b7-5a0c-4a76-ad47-8a1109e9b7a3', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with parentheses', 'What value of $x$ makes $5(x + 4) = 15$ true?', '[]', '-1', '15/5-4', 'Divide both sides by 5: $x + 4 = 3$. Subtract 4: $x = -1$. Check: $5(-1 + 4) = 5 \times 3 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 4 = 3; x = -1.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
