VALUES ('1a01b0a9-015f-49ce-87dc-cc8fe221c53f', 'NC26.7.ANR.3', 2, 'choice', 'Solve an equation with parentheses', 'Which value is the solution of $2(x - 5) = 14$?', '["12","7","9","19"]', '12', '14/2+5', 'Divide both sides by 2: $x - 5 = 7$. Add 5: $x = 12$. (7 forgets to add 5, and 19 adds 5 to 14 without dividing by 2.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 5 = 7; x = 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
