INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43cc6634-d796-43fc-8262-8107c892f952', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with parentheses', 'Find the solution of $4(2x + 1) = 36$.', '[]', '4', '(36/4-1)/2', 'Divide both sides by 4: $2x + 1 = 9$. Subtract 1: $2x = 8$. Divide by 2: $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 1 = 9; 2x = 8; x = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
