INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d859667d-6917-4c5b-bdf5-cc3dfc0bdff9', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Solve for $x$: $0.5x + 2 = 7$.', '[]', '10', '(7-2)/0.5', 'Subtract 2 from both sides: $0.5x = 5$. Divide by 0.5 (the same as multiplying by 2): $x = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5x = 5; x = 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
