INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a2d6976-0465-4191-9a30-8fe00710bedf', 'NC26.7.ANR.3', 2, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Find the value of $x$ if $\frac{1}{2}x - \frac{3}{4} = \frac{1}{4}$.', '[]', '2', '(1/4+3/4)/(1/2)', 'Add 3/4 to both sides: $\frac{1}{2}x = 1$. Multiply both sides by 2: $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2 = 1/4 + 3/4 = 1; x = 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
