INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ed5631d-23d8-42ea-b8cb-440e4d85479f', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Solve for $x$: $\frac{3}{4}x + \frac{1}{2} = 5$.', '[]', '6', '(5-1/2)/(3/4)', 'Subtract 1/2 from both sides: $\frac{3}{4}x = \frac{9}{2}$. Multiply both sides by 4/3: $x = \frac{9}{2} \times \frac{4}{3} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3/4)x = 4.5; x = 4.5 x 4/3 = 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
