INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c7ee270-dfbf-4999-9934-ea17958c7baf', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Solve for $x$: $-2.5x + 4 = -6$.', '[]', '4', '(-6-4)/(-2.5)', 'Subtract 4 from both sides: $-2.5x = -10$. Divide by -2.5: $x = 4$. Check: $-2.5 \times 4 + 4 = -10 + 4 = -6$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2.5x = -10; x = 4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
