INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e797f17-e8af-4607-b9cf-5dba7235e815', 'NC26.7.ANR.3', 3, 'choice', 'Solve an equation with fractions, decimals or negatives', 'Which value is the solution of $\frac{1}{3}(x + 6) = 5$?', '["15","21","-1","9"]', '9', '5*3-6', 'Multiply both sides by 3: $x + 6 = 15$. Subtract 6: $x = 9$. (15 forgets to subtract 6, 21 adds 6, and -1 ignores the one third.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 6 = 15; x = 9.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
