INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95e08d05-52e8-46e6-a312-c75d89ae5736', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an equation with fractions, decimals or negatives', 'Find the value of $x$ if $\frac{x}{2} - \frac{1}{3} = \frac{7}{6}$.', '[]', '3', '(7/6+1/3)*2', 'Add 1/3 to both sides: $\frac{x}{2} = \frac{7}{6} + \frac{2}{6} = \frac{9}{6} = \frac{3}{2}$. Multiply both sides by 2: $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2 = 7/6 + 2/6 = 9/6 = 3/2; x = 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
