INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7714b056-330c-46c3-888a-d6f5a720bc89', 'NC26.7.ANR.3', 3, 'numeric', 'Write and solve an equation from a situation', 'Nora''s age is 4 less than 3 times her brother''s age. Nora is 14 years old. How old is her brother?', '[]', '6', '(14+4)/3', 'Let $b$ be her brother''s age. Nora''s age is $3b - 4$, so $3b - 4 = 14$. Add 4: $3b = 18$. Divide by 3: $b = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3b - 4 = 14; 3b = 18; b = 6.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd3b6e29-e430-4a61-a761-2a013e0960b2', 'NC26.7.ANR.3', 3, 'numeric', 'Write and solve an equation from a situation', 'A tank holds 120 liters of water. Water drains out at 7.5 liters per minute. After how many minutes will 45 liters be left in the tank?', '[]', '10', '(120-45)/7.5', 'After $m$ minutes the tank holds $120 - 7.5m$ liters. Solve $120 - 7.5m = 45$: subtract 120 to get $-7.5m = -75$, then divide by -7.5: $m = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 - 7.5m = 45; 7.5m = 75; m = 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('662945aa-33f8-4d05-9624-30cff4db2298', 'NC26.7.ANR.3', 3, 'numeric', 'Write and solve an equation from a situation', 'Three friends split a restaurant bill equally. Each friend also pays 2 dollars toward a tip, and each friend paid 14 dollars in all. How many dollars was the bill?', '[]', '36', '(14-2)*3', 'Let $b$ be the bill. Each friend pays $\frac{b}{3} + 2$ dollars, so $\frac{b}{3} + 2 = 14$. Subtract 2: $\frac{b}{3} = 12$. Multiply by 3: $b = 36$. The bill was 36 dollars.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b/3 + 2 = 14; b/3 = 12; b = 36.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c69f7ac-70a1-49e6-8138-5490b044df55', 'NC26.7.ANR.3', 3, 'choice', 'Solve an inequality', 'Which inequality shows all the solutions of $4(x - 2) < 6$?', '["$x < 2$","$x < 3.5$","$x < 1.5$","$x > 3.5$"]', '$x < 3.5$', NULL, 'Divide both sides by 4: $x - 2 < 1.5$. Add 2: $x < 3.5$. (x < 2 forgets to multiply the 2 by 4, and x < 1.5 forgets to add 2.)', 'checked', '{"lint":[],"solve":{"answer":"$x < 3.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 2 < 1.5; x < 3.5.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a318d487-0f3f-45b4-b539-598eac159ba5', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an inequality', 'What is the least whole number that is a solution of $2.5x - 4 > 11$?', '[]', '7', NULL, 'Add 4 to both sides: $2.5x > 15$. Divide by 2.5: $x > 6$. Six is not a solution (it makes both sides equal), so the least whole number is 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5x > 15; x > 6; least whole number 7.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36d9bbb1-ff89-432a-a277-645fd76caff3', 'NC26.7.ANR.3', 3, 'choice', 'Write an inequality from a situation', 'A recipe uses 2.5 cups of flour for each batch. Dana has 12 cups of flour and wants to keep at least 2 cups for later. Which inequality can she use to find the number of batches $b$ she can make?', '["$2.5b + 2 \\ge 12$","$2.5b - 2 \\le 12$","$2.5(b + 2) \\le 12$","$2.5b + 2 \\le 12$"]', '$2.5b + 2 \le 12$', NULL, 'The batches use $2.5b$ cups and at least 2 cups must be left, so the flour used plus 2 must be at most 12: $2.5b + 2 \le 12$.', 'checked', '{"lint":[],"solve":{"answer":"$2.5b + 2 \\le 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flour used 2.5b plus 2 kept must not exceed 12: 2.5b + 2 <= 12.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e87f89b-4651-4e36-bfea-59212ed6e377', 'NC26.7.ANR.3', 3, 'choice', 'Write an inequality from a situation', 'Lena wants to read at least 150 pages this week. She has already read 42 pages and will read $p$ pages on each of the last 4 days. Which inequality shows her goal?', '["$42 + 4p \\ge 150$","$42 + 4p \\le 150$","$42p + 4 \\ge 150$","$4(p + 42) \\ge 150$"]', '$42 + 4p \ge 150$', NULL, 'She will read $4p$ more pages, so the total is $42 + 4p$. "At least 150" gives $42 + 4p \ge 150$.', 'checked', '{"lint":[],"solve":{"answer":"$42 + 4p \\ge 150$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"42 read + 4p more, at least 150: 42 + 4p >= 150.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb5f1109-b461-41ef-9497-80bd2af0148a', 'NC26.7.ANR.3', 3, 'numeric', 'Interpret the solution of an inequality in context', 'A club has 240 dollars. It buys a banner for 60 dollars and spends the rest on T-shirts that cost 7.50 dollars each. What is the greatest number of T-shirts it can buy?', '[]', '24', NULL, 'The cost is $7.5s + 60 \le 240$. Subtract 60: $7.5s \le 180$. Divide by 7.5: $s \le 24$. The greatest number is 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 + 7.5t <= 240; 7.5t <= 180; t <= 24. Greatest 24.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d76275e5-d724-40b1-8a0a-9c3c2be322c9', 'NC26.7.ANR.3', 3, 'choice', 'Interpret the solution of an inequality in context', 'Which statement describes all the solutions of $3x + 12 < 6$?', '["Every number greater than $-2$ is a solution","Every number less than $-2$ is a solution, but $-2$ is not","Every number less than $-2$ is a solution, and so is $-2$","The number $-2$ is the only solution"]', 'Every number less than $-2$ is a solution, but $-2$ is not', NULL, 'Subtract 12: $3x < -6$. Divide by 3: $x < -2$. So every number less than -2 is a solution, and -2 itself is not (it makes both sides equal).', 'checked', '{"lint":[],"solve":{"answer":"Every number less than $-2$ is a solution, but $-2$ is not","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x < -6; x < -2; -2 itself gives 6 < 6, false.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a4ba697-ef83-416a-a097-25f00fe3413b', 'NC26.7.ANR.3', 3, 'numeric', 'Interpret the solution of an inequality in context', 'A truck weighs 1200 pounds when it is empty. The truck and its load together may weigh at most 2000 pounds. Each box weighs 35 pounds. What is the greatest number of boxes the truck can carry?', '[]', '22', NULL, 'The weight is $1200 + 35b \le 2000$. Subtract 1200: $35b \le 800$. Divide by 35: $b \le \frac{800}{35}$, which is about 22.9. Only whole boxes can be loaded, so the greatest number is 22.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1200 + 35b <= 2000; 35b <= 800; b <= 22.86. Greatest 22 (22 x 35 = 770; 23 x 35 = 805 too many).","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7213932-c14a-4634-a7a5-7c8afb2be79c', 'NC26.7.ANR.3', 3, 'numeric', 'Interpret the solution of an inequality in context', 'A group needs at least 130 dollars for a trip. It already has 45 dollars and earns 8.50 dollars from each car wash. What is the fewest number of car washes that will get the group to its goal?', '[]', '10', NULL, 'The money is $45 + 8.5c \ge 130$. Subtract 45: $8.5c \ge 85$. Divide by 8.5: $c \ge 10$. Ten car washes give exactly 130 dollars, so the fewest is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"45 + 8.5c >= 130; 8.5c >= 85; c >= 10. Fewest 10.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df4e644b-972d-4d5f-a94b-dd0d38da3a3c', 'NC26.7.ANR.3', 3, 'choice', 'Graph an inequality on a number line', 'The solution of $4(x - 1) \ge 10$ is graphed on a number line. Which description matches the graph?', '["An open circle at $3.5$ with the line shaded to the right","A closed circle at $3.5$ with the line shaded to the left","A closed circle at $3.5$ with the line shaded to the right","A closed circle at $1.5$ with the line shaded to the right"]', 'A closed circle at $3.5$ with the line shaded to the right', NULL, 'Divide by 4: $x - 1 \ge 2.5$. Add 1: $x \ge 3.5$. The circle is closed at 3.5 and the shading is to the right.', 'checked', '{"lint":[],"solve":{"answer":"A closed circle at $3.5$ with the line shaded to the right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 1 >= 2.5; x >= 3.5: closed circle at 3.5, shaded right.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a2b2479-a477-4182-8b69-c64fb85a34bc', 'NC26.7.ANR.3', 3, 'numeric', 'Graph an inequality on a number line', 'The solution of $5x + 9 < -1$ is graphed on a number line with a circle at its boundary. At what number is the circle drawn?', '[]', '-2', '(-1-9)/5', 'Subtract 9: $5x < -10$. Divide by 5: $x < -2$. The boundary of the graph is at -2 (an open circle, with shading to the left).', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x < -10; x < -2. Boundary circle at -2.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f306f257-aeea-490d-8955-b26363abc603', 'NC26.7.ANR.3', 3, 'choice', 'Decide whether a value is a solution', 'Which inequality does NOT have $x = 3$ as a solution?', '["$2x - 1 > 4$","$4x - 9 < 2$","$5 - x \\le 2$","$3x + 1 \\ge 10$"]', '$4x - 9 < 2$', NULL, 'Substitute 3 for $x$. $2 \times 3 - 1 = 5 > 4$ is true, $5 - 3 = 2 \le 2$ is true, and $3 \times 3 + 1 = 10 \ge 10$ is true. But $4 \times 3 - 9 = 3$, and 3 is not less than 2, so $4x - 9 < 2$ is the one that is not true.', 'checked', '{"lint":[],"solve":{"answer":"$4x - 9 < 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 3: 5 > 4 true; 10 >= 10 true; 12 - 9 = 3 < 2 false; 5 - 3 = 2 <= 2 true.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b7ece06-8db7-40e9-bac8-dbd7835e3363', 'NC26.7.ANR.3', 3, 'choice', 'Choose an equation or an inequality', 'Rae has 60 dollars and wants to buy $s$ shirts that cost 12 dollars each. Which statement is correct?', '["Use $12s = 60$ to find how many shirts cost exactly 60 dollars","Use $12s \\ge 60$ to find how many shirts she can afford","Use $12s < 60$ to find how many shirts cost exactly 60 dollars","Use $12 + s = 60$ to find how many shirts she can afford"]', 'Use $12s = 60$ to find how many shirts cost exactly 60 dollars', NULL, '$s$ shirts cost $12s$ dollars. To find the number that cost exactly 60 dollars, set the cost equal to 60: $12s = 60$. To find how many she can afford, the cost must be at most 60, which needs $12s \le 60$, not "at least" and not a sum.', 'checked', '{"lint":[],"solve":{"answer":"Use $12s = 60$ to find how many shirts cost exactly 60 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12s = 60 gives s = 5, the number of shirts costing exactly 60: true. Affording needs 12s <= 60, not >=; < cannot give exactly 60; 12 + s is wrong.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2db44fec-b30f-41c6-9c13-8772731a13b2', 'NC26.7.ANR.3', 3, 'choice', 'Choose an equation or an inequality', 'Which situation is modeled by $4n + 5 \ge 33$?', '["Each of $n$ boxes holds 4 books, 5 more books are loose, and the total is at most 33","Each of $n$ boxes holds 5 books, 4 more books are loose, and the total is at least 33","Each of $n$ boxes holds 4 books, 5 more books are loose, and the total is at least 33","Each of $n$ boxes holds 4 books, then 5 books are given away, and at least 33 are left"]', 'Each of $n$ boxes holds 4 books, 5 more books are loose, and the total is at least 33', NULL, 'In $4n + 5 \ge 33$, $4n$ is the books in $n$ boxes of 4, the 5 is 5 more books, and the sign means the total is at least 33. The other situations change the amounts, the direction of the sign, or the extra 5.', 'checked', '{"lint":[],"solve":{"answer":"Each of $n$ boxes holds 4 books, 5 more books are loose, and the total is at least 33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4n = 4 books in each of n boxes, + 5 loose, >= 33 at least.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3a27d01-82b3-4797-8c86-1c8e745b9a67', 'NC26.7.ANR.3', 3, 'choice', 'Solve an inequality with a negative coefficient', 'Which inequality shows all the solutions of $-2x + 3 > 11$?', '["$x > -4$","$x < 4$","$x > 4$","$x < -4$"]', '$x < -4$', NULL, 'Subtract 3: $-2x > 8$. Divide both sides by -2, and reverse the inequality sign because you divided by a negative number: $x < -4$. Check with x = -5: $-2 \times (-5) + 3 = 13 > 11$.', 'checked', '{"lint":[],"solve":{"answer":"$x < -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x > 8; divide by -2 and reverse: x < -4.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a31f875-c6e3-4029-a8e0-28aec0626498', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an inequality with a negative coefficient', 'What is the least integer that is a solution of $-3x < 12$?', '[]', '-3', NULL, 'Divide both sides by -3 and reverse the sign: $x > -4$. The integers greater than -4 are -3, -2, -1, ..., so the least is -3.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Divide by -3 and reverse: x > -4. Least integer -3.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd44fc17-4c56-491b-97a5-13631787347d', 'NC26.7.ANR.3', 3, 'choice', 'Solve an inequality with a negative coefficient', 'Which inequality shows all the solutions of $5 - 3x \ge -4$?', '["$x \\ge 3$","$x \\le -3$","$x \\le 3$","$x \\ge -3$"]', '$x \le 3$', NULL, 'Subtract 5: $-3x \ge -9$. Divide by -3 and reverse the sign: $x \le 3$. Check with x = 0: $5 - 0 = 5 \ge -4$ is true.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x >= -9; x <= 3.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a50cf693-5387-4788-b40e-74036728dfc2', 'NC26.7.ANR.3', 3, 'numeric', 'Solve an inequality with a negative coefficient', 'What is the greatest integer that is a solution of $7 - 2x > 1$?', '[]', '2', NULL, 'Subtract 7: $-2x > -6$. Divide by -2 and reverse the sign: $x < 3$. The greatest integer less than 3 is 2. Check: $7 - 2 \times 2 = 3 > 1$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x > -6; x < 3. Greatest integer 2.","run_id":"claude-code","at":"2026-10-17T20:22:53.572Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c6386e2-123a-4248-b64f-10a57ba7bbbb', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a triangle', 'A triangle has a base of 10 centimeters and a height of 6 centimeters. What is its area, in square centimeters?', '[]', '30', '10*6/2', 'Area of a triangle $= \frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 10 \times 6 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (1/2)(10)(6) = 30.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a2a6051-d35f-40ce-a628-db0de21bc846', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a circle from the radius', 'A circle has a radius of 5 centimeters. Use 3.14 for $\pi$. What is its area, in square centimeters?', '[]', '78.5', '3.14*5^2', 'Area $= \pi r^2 = 3.14 \times 5 \times 5 = 78.5$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"78.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 3.14 x 25 = 78.5.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
