INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('600cdb3e-fb72-409a-80d2-5dcfeb5e6e75', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle from the diameter', 'A circle has a diameter of 8 centimeters. Use 3.14 for $\pi$. What is its area, in square centimeters?', '["200.96","25.12","50.24","12.56"]', '50.24', '3.14*4^2', 'The radius is half the diameter: $8 \div 2 = 4$. Area $= 3.14 \times 4^2 = 3.14 \times 16 = 50.24$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"50.24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 4, A = 3.14 x 16 = 50.24.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cdd4c30b-dc44-4974-9ad4-e23f14e705ac', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a triangle', 'A triangular sail on a toy boat has a base of 8 feet and a height of 5 feet. How many square feet of cloth does the sail use?', '["20","40","13","10"]', '20', '1/2*8*5', 'The area of a triangle is half of the base times the height: $\frac{1}{2} \times 8 \times 5 = 20$ square feet.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 x 8 x 5 = 20 square feet.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
