INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('561b5a0d-5ab8-43d1-95bf-47e46ac885bb', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a triangle', 'A triangular flag is 12 centimeters wide at its base and 7 centimeters tall. What is the area of the flag, in square centimeters?', '["84","19","21","42"]', '42', '1/2*12*7', 'Area = $\frac{1}{2} \times$ base $\times$ height = $\frac{1}{2} \times 12 \times 7 = 42$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = 1/2 x 12 x 7 = 42 square cm.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
