INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52381c49-b81a-4bd4-b8af-69086b8aacc0', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a triangle', 'A right triangle has two shorter sides (legs) that meet at a right angle. They are 6 centimeters and 9 centimeters long. What is the area of the triangle, in square centimeters?', '[]', '27', '1/2*6*9', 'The two legs can be used as the base and the height. Area = $\frac{1}{2} \times 6 \times 9 = 27$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs are base and height: 1/2 x 6 x 9 = 27.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
