INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eee4aad-e219-4861-b042-bcc755fa3b8d', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a parallelogram or trapezoid', 'A trapezoid has parallel sides of lengths $a$ and $b$ and a height of $h$. Which expression gives its area?', '["$(a + b) \\times h$","$\\frac{1}{2}(a + b) \\times h$","$\\frac{1}{2} \\times a \\times b \\times h$","$\\frac{1}{2}(a + b) + h$"]', '$\frac{1}{2}(a + b) \times h$', NULL, 'The area of a trapezoid is half of the sum of the parallel sides, times the height: $\frac{1}{2}(a + b) \times h$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}(a + b) \\times h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trapezoid area = average of the parallel sides times height = 1/2 (a + b) h.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6b5abe5-b0d0-45e8-8d27-0e8a33b8cb8c', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a parallelogram or trapezoid', 'A flower bed is shaped like a trapezoid. Its two parallel sides are 4 meters and 8 meters long, and they are 3 meters apart. What is the area of the bed, in square meters?', '[]', '18', '1/2*(4+8)*3', 'Area = $\frac{1}{2} \times (4 + 8) \times 3 = \frac{1}{2} \times 12 \times 3 = 18$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x (4 + 8) x 3 = 6 x 3 = 18.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fca6a183-156e-4868-8405-02a9a443fa1f', 'NC26.7.SGMR.1', 1, 'choice', 'Circumference of a circle', 'A round table has a diameter of 6 feet. Use 3.14 for $\pi$. How far is it around the edge of the table, in feet?', '["28.26","18.84","9.42","37.68"]', '18.84', '3.14*6', 'Circumference = $\pi \times$ diameter = $3.14 \times 6 = 18.84$ feet.', 'checked', '{"lint":[],"solve":{"answer":"18.84","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = pi d = 3.14 x 6 = 18.84.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de1580c1-de99-47ea-b0c0-ef04586758fa', 'NC26.7.SGMR.1', 1, 'numeric', 'Circumference of a circle', 'The wheel of a toy cart has a radius of 10 centimeters. Use 3.14 for $\pi$. How far does the cart roll in one full turn of the wheel, in centimeters?', '[]', '62.8', '2*3.14*10', 'In one full turn the wheel rolls its circumference: $2 \times 3.14 \times 10 = 62.8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = circumference = 2 x 3.14 x 10 = 62.8.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73b83f57-09cf-47c7-83a6-21a06b89f4c1', 'NC26.7.SGMR.1', 1, 'choice', 'Circumference of a circle', 'Which formula gives the circumference of a circle with radius $r$?', '["$C = \\pi r^2$","$C = \\pi r$","$C = 2\\pi r^2$","$C = 2\\pi r$"]', '$C = 2\pi r$', NULL, 'The circumference is $\pi$ times the diameter, and the diameter is $2r$, so $C = 2\pi r$. The formula $\pi r^2$ is for the area.', 'checked', '{"lint":[],"solve":{"answer":"$C = 2\\pi r$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 pi r.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('550b708e-a971-470a-94b1-7b30d4d67b44', 'NC26.7.SGMR.1', 1, 'choice', 'Pi as the ratio of circumference to diameter', 'Which statement describes the number $\pi$?', '["The diameter of any circle divided by its circumference","The circumference of any circle divided by its diameter","The circumference of any circle divided by its radius","The area of any circle divided by its diameter"]', 'The circumference of any circle divided by its diameter', NULL, 'For every circle, the distance around (circumference) divided by the distance across (diameter) is the same number, about 3.14. That number is $\pi$.', 'checked', '{"lint":[],"solve":{"answer":"The circumference of any circle divided by its diameter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi = C / d for every circle.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f227bc48-8b39-408c-9744-b77cae660c91', 'NC26.7.SGMR.1', 1, 'numeric', 'Pi as the ratio of circumference to diameter', 'Mia measures a round lid. The distance around the lid (its circumference) is 31.4 centimeters and its diameter is 10 centimeters. What is the circumference divided by the diameter?', '[]', '3.14', '31.4/10', '31.4 $\div$ 10 = 3.14. This is close to the number $\pi$.', 'checked', '{"lint":[],"solve":{"answer":"3.14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"31.4 / 10 = 3.14.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da63915a-7e65-4498-93e6-b706eba3b893', 'NC26.7.SGMR.1', 1, 'choice', 'Pi as the ratio of circumference to diameter', 'Compared with its diameter, how long is the distance around any circle?', '["A little more than 3 times as long","Exactly 3 times as long","About 2 times as long","About 6 times as long"]', 'A little more than 3 times as long', NULL, 'The circumference is $\pi$ times the diameter, and $\pi$ is about 3.14. So the distance around is a little more than 3 times the distance across.', 'checked', '{"lint":[],"solve":{"answer":"A little more than 3 times as long","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = pi d, pi is about 3.14, a little more than 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2596c384-2d5b-4e76-86cf-82fc6d930a9b', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A round trampoline has a radius of 3 meters. Use 3.14 for $\pi$. What is the area of its jumping surface, in square meters?', '["18.84","9.42","113.04","28.26"]', '28.26', '3.14*3^2', 'Area = $\pi r^2 = 3.14 \times 3 \times 3 = 28.26$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"28.26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 3.14 x 3^2 = 3.14 x 9 = 28.26.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('180e6a0e-261c-43d9-9360-1f335dcd3570', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A circle has a radius of 6 centimeters. Which expression gives its area, in square centimeters?', '["$2 \\times \\pi \\times 6$","$\\pi \\times 6^2$","$\\pi \\times 12^2$","$\\pi \\times 6$"]', '$\pi \times 6^2$', NULL, 'The area of a circle is $\pi r^2$. With $r = 6$ this is $\pi \times 6^2$.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi \\times 6^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = pi r^2 = pi x 6^2.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15c4bc6d-c055-41aa-97ed-a24825ea0453', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a circle', 'A round pond has a diameter of 20 meters. Use 3.14 for $\pi$. What is the area of the water''s surface, in square meters?', '["314","1256","62.8","31.4"]', '314', '3.14*(20/2)^2', 'The radius is half the diameter: 20 $\div$ 2 = 10 meters. Area = $3.14 \times 10 \times 10 = 314$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"314","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 10. A = 3.14 x 100 = 314.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22bff88d-2519-4bb5-adde-3e156230154d', 'NC26.7.SGMR.1', 1, 'numeric', 'Relate circumference, radius and area', 'Circle X has a radius of 3 centimeters. Circle Y has a radius of 6 centimeters. The distance around circle Y is how many times the distance around circle X?', '[]', '2', '6/3', 'The circumference is proportional to the radius. 6 $\div$ 3 = 2, so the distance around Y is 2 times the distance around X.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Circumference is proportional to radius: 2 pi 6 / (2 pi 3) = 2.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9c5ae62-8a0e-4808-af6a-8f831cfd12d2', 'NC26.7.SGMR.1', 1, 'choice', 'Relate circumference, radius and area', 'Which measurement of a circle do you find by multiplying its diameter by $\pi$?', '["The area of the circle","The radius of the circle","The distance across the circle","The distance around the circle"]', 'The distance around the circle', NULL, 'The circumference (the distance around) is $\pi$ times the diameter.', 'checked', '{"lint":[],"solve":{"answer":"The distance around the circle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi x d = circumference, the distance around.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21ae3278-f477-40a6-a70b-af7f352f4228', 'NC26.7.SGMR.1', 1, 'choice', 'Relate circumference, radius and area', 'The radius of a circle is doubled. What happens to the distance around the circle?', '["It becomes twice as long","It stays the same length","It becomes 4 times as long","It becomes half as long"]', 'It becomes twice as long', NULL, 'The circumference is $2\pi r$. If $r$ doubles, the circumference doubles. (It is the area that becomes 4 times as large.)', 'checked', '{"lint":[],"solve":{"answer":"It becomes twice as long","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 pi r is proportional to r, so doubling r doubles C.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee77e693-5e2a-4e7d-8b2a-fb557915126e', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a composite figure by adding parts', 'An L-shaped patio is made of two rectangles that do not overlap. One rectangle is 8 meters by 3 meters. The other is 4 meters by 2 meters. What is the area of the patio, in square meters?', '[]', '32', '8*3 + 4*2', 'Add the areas of the two rectangles: 8 $\times$ 3 = 24 and 4 $\times$ 2 = 8. Total = 32 square meters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 x 3 + 4 x 2 = 24 + 8 = 32.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c63b33f-343a-4605-b1cf-b2414cf17c47', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a composite figure by adding parts', 'A sign is shaped like a house. It is a rectangle that is 6 feet wide and 4 feet tall, with a triangle on top. The triangle has a base of 6 feet and a height of 2 feet. What is the area of the whole sign, in square feet?', '[]', '30', '6*4 + 1/2*6*2', 'Rectangle: 6 $\times$ 4 = 24. Triangle: $\frac{1}{2} \times 6 \times 2 = 6$. Total = 30 square feet.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 6 x 4 = 24; triangle 1/2 x 6 x 2 = 6. Total 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0a1d3ae-f3be-45f4-b8e1-d37a04704828', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a composite figure by adding parts', 'A banner is a 7-inch by 4-inch rectangle with a triangle attached along one 7-inch side. The triangle has a base of 7 inches and a height of 3 inches. What is the total area of the banner, in square inches?', '["49","38.5","24.5","31"]', '38.5', '7*4 + 1/2*7*3', 'Rectangle: 7 $\times$ 4 = 28. Triangle: $\frac{1}{2} \times 7 \times 3 = 10.5$. Total = 38.5 square inches.', 'checked', '{"lint":[],"solve":{"answer":"38.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 7 x 4 = 28; triangle 1/2 x 7 x 3 = 10.5. Total 38.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3e555fb-0051-4f9a-876f-16d9be5c7f3b', 'NC26.7.SGMR.1', 1, 'choice', 'Area of a figure with a part removed', 'A poster is 20 centimeters by 15 centimeters. A square hole with sides of 4 centimeters is cut out of it. What is the area of the poster that is left, in square centimeters?', '["316","296","284","16"]', '284', '20*15 - 4*4', 'Whole poster: 20 $\times$ 15 = 300. Hole: 4 $\times$ 4 = 16. Left: 300 $-$ 16 = 284 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"284","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 x 15 = 300; hole 16; left 284.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
