INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26019e5a-3df7-47a2-a12c-4d74477fd4a7', 'NC26.7.SGMR.1', 1, 'numeric', 'Area of a figure with a part removed', 'A square sheet of paper has sides of 10 inches. A 6-inch by 3-inch rectangle is cut from one corner. What is the area of the paper that is left, in square inches?', '[]', '82', '10*10 - 6*3', 'Whole sheet: 10 $\times$ 10 = 100. Piece cut off: 6 $\times$ 3 = 18. Left: 100 $-$ 18 = 82 square inches.', 'checked', '{"lint":[],"solve":{"answer":"82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 - 6 x 3 = 100 - 18 = 82.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
