INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4415af11-a454-47b0-a0e2-511c4e196265', 'NC26.7.SGMR.1', 1, 'numeric', 'Perimeter of a composite figure', 'An L-shaped garden has six straight sides of 8 m, 3 m, 4 m, 5 m, 4 m and 8 m. How many meters of fence go all the way around it?', '[]', '32', '8+3+4+5+4+8', 'Add all six sides: 8 + 3 + 4 + 5 + 4 + 8 = 32 meters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 3 + 4 + 5 + 4 + 8 = 32 (consistent L: 8 = 4 + 4 and 8 = 3 + 5).","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
