INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f98a124a-ee78-4ad8-b8ea-87006b3d47d9', 'NC26.7.SGMR.1', 1, 'numeric', 'Perimeter of a composite figure', 'A rectangular pen uses a barn wall as one of its long sides. Fence is needed for only the other three sides: two sides of 6 meters and one side of 11 meters. How many meters of fence are needed?', '[]', '23', '6+6+11', 'Add the three fenced sides: 6 + 6 + 11 = 23 meters.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 6 + 11 = 23.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
