INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42ee2e20-1303-4102-8507-093479db3f3b', 'NC26.7.SGMR.1', 1, 'choice', 'Area problems in context: covering and cost', 'Square floor tiles have sides of 2 feet. How many tiles are needed to cover a floor that is 10 feet by 6 feet, with no gaps?', '["60","30","15","32"]', '15', '10*6/(2*2)', 'Floor: 10 $\times$ 6 = 60 square feet. One tile: 2 $\times$ 2 = 4 square feet. Tiles: 60 $\div$ 4 = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Floor 60; tile 4; 60 / 4 = 15 (5 by 3 grid).","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e26dba8-14e6-4a4d-87dd-11dc43736fec', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a trapezoid', 'A trapezoid has parallel sides of 6 centimeters and 10 centimeters, and a height of 4 centimeters. What is its area, in square centimeters?', '[]', '32', '(6+10)/2*4', 'Area $= \frac{1}{2}(b_1 + b_2) \times h = \frac{1}{2}(6 + 10) \times 4 = 8 \times 4 = 32$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = (6 + 10)/2 x 4 = 8 x 4 = 32.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01311a2b-8c50-417a-9273-c34f374ab49e', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a composite figure by subtraction', 'A rectangular garden is 12 meters long and 9 meters wide. A rectangular pond that is 4 meters by 3 meters sits inside the garden. How many square meters of the garden are not covered by the pond?', '[]', '96', '12*9-4*3', 'Garden: $12 \times 9 = 108$ square meters. Pond: $4 \times 3 = 12$ square meters. Not covered: $108 - 12 = 96$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Garden 12 x 9 = 108; pond 4 x 3 = 12. 108 - 12 = 96.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e55d7485-41db-4951-848b-9735273a443f', 'NC26.7.SGMR.1', 2, 'numeric', 'Relate circumference, radius and area', 'The circumference of a circle is 37.68 centimeters. Use 3.14 for $\pi$. What is the area of the circle, in square centimeters?', '[]', '113.04', '3.14*(37.68/(2*3.14))^2', 'First find the radius from $C = 2\pi r$: $r = 37.68 \div (2 \times 3.14) = 37.68 \div 6.28 = 6$ centimeters. Then area $= 3.14 \times 6^2 = 3.14 \times 36 = 113.04$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"113.04","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 37.68/3.14 = 12, r = 6. A = 3.14 x 36 = 113.04.","run_id":"claude-code","at":"2026-10-17T18:33:49.503Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5bb1341-13b5-42a8-9350-b455e6cbde54', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a triangle', 'A triangle has an area of 36 square centimeters and a base of 9 centimeters. How tall is the triangle, in centimeters?', '[]', '8', '2*36/9', 'Area = $\frac{1}{2} \times$ base $\times$ height, so height = $2 \times$ area $\div$ base = $2 \times 36 \div 9 = 8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 = 1/2 x 9 x h, so h = 72/9 = 8.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c6674c8-b10b-4e75-8ee3-03e1aba0a879', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a triangle', 'Ana cuts a triangle out of felt. The base of the triangle is 7.5 inches and its height is 4 inches. How many square inches of felt does the triangle cover?', '["30","11.5","15","5.75"]', '15', '1/2*7.5*4', 'Area = $\frac{1}{2} \times 7.5 \times 4 = 15$ square inches.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x 7.5 x 4 = 15 square inches.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
