INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4bac7e0-cebf-49bd-9899-ba0375b9a928', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a parallelogram or trapezoid', 'The top of a small table is a trapezoid. Its parallel edges are 1.2 meters and 0.8 meters long, and the distance between them is 0.5 meters. What is the area of the top, in square meters?', '[]', '0.5', '1/2*(1.2+0.8)*0.5', 'Area = $\frac{1}{2} \times (1.2 + 0.8) \times 0.5 = \frac{1}{2} \times 2 \times 0.5 = 0.5$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2 x (1.2 + 0.8) x 0.5 = 1/2 x 2 x 0.5 = 0.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54fe666e-a857-4856-895b-3de82380bf5f', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a parallelogram or trapezoid', 'A parallelogram has an area of 84 square centimeters and a base of 12 centimeters. How tall is it, in centimeters?', '["1008","72","7","14"]', '7', '84/12', 'Area = base $\times$ height, so height = 84 $\div$ 12 = 7 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 84 / 12 = 7.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('718c51c6-9813-43b0-8fd8-f09c31db8325', 'NC26.7.SGMR.1', 2, 'choice', 'Circumference of a circle', 'A circular running track has a diameter of 50 meters. Nira jogs once all the way around it. Use 3.14 for $\pi$. How many meters does she jog?', '["157","314","78.5","1962.5"]', '157', '3.14*50', 'Distance around = $\pi \times$ diameter = $3.14 \times 50 = 157$ meters.', 'checked', '{"lint":[],"solve":{"answer":"157","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3.14 x 50 = 157.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee7b56e1-d542-415f-9b1a-ca5ac93ffe89', 'NC26.7.SGMR.1', 2, 'choice', 'Circumference of a circle', 'A circular pond has a radius of 7 meters. Use $\frac{22}{7}$ for $\pi$. How long is the edge of the pond, in meters?', '["22","154","88","44"]', '44', '2*(22/7)*7', 'Circumference = $2 \times \pi \times r = 2 \times \frac{22}{7} \times 7 = 44$ meters.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 22/7 x 7 = 44.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b8604d9-90e4-4e49-87d2-13fe2196c2ed', 'NC26.7.SGMR.1', 2, 'numeric', 'Circumference of a circle', 'A circular rug has a radius of 1.5 meters. Fringe is sewn all the way around its edge. Use 3.14 for $\pi$. How many meters of fringe are needed?', '[]', '9.42', '2*3.14*1.5', 'The fringe goes around the circumference: $2 \times 3.14 \times 1.5 = 9.42$ meters.', 'checked', '{"lint":[],"solve":{"answer":"9.42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 1.5 = 9.42.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
