INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bf76e41-02a9-4130-bf98-9ad11f0e712a', 'NC26.7.SGMR.1', 2, 'numeric', 'Pi as the ratio of circumference to diameter', 'The distance around a circular pool is 47.1 meters. Use 3.14 for $\pi$. What is the diameter of the pool, in meters?', '[]', '15', '47.1/3.14', 'Circumference = $\pi \times$ diameter, so diameter = 47.1 $\div$ 3.14 = 15 meters.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 47.1 / 3.14 = 15.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
