INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81af6ee9-73cc-4d7d-ac53-bf895675afa8', 'NC26.7.SGMR.1', 2, 'choice', 'Relate circumference, radius and area', 'The radius of a circle is tripled. Which statement is true?', '["Its area becomes 3 times as large","Its area becomes 6 times as large","Its area stays the same","Its area becomes 9 times as large"]', 'Its area becomes 9 times as large', NULL, 'The area is $\pi r^2$. If $r$ becomes $3r$, the area is $\pi (3r)^2 = 9\pi r^2$, which is 9 times as large.', 'checked', '{"lint":[],"solve":{"answer":"Its area becomes 9 times as large","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = pi r^2; (3r)^2 = 9 r^2, so 9 times.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e202afe7-4676-4a8d-9100-00471dd328e3', 'NC26.7.SGMR.1', 2, 'numeric', 'Relate circumference, radius and area', 'A circular garden has a fence around it that is 18.84 meters long. Use 3.14 for $\pi$. What is the area of the garden, in square meters?', '[]', '28.26', '3.14*(18.84/(2*3.14))^2', 'The fence is the circumference, so the radius is 18.84 $\div$ (2 $\times$ 3.14) = 3 meters. Area = $3.14 \times 3^2 = 28.26$ square meters.', 'checked', '{"lint":[],"solve":{"answer":"28.26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d = 18.84 / 3.14 = 6, r = 3. A = 3.14 x 9 = 28.26.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77ed21ed-3c8f-4e20-b055-594ec9996346', 'NC26.7.SGMR.1', 2, 'numeric', 'Relate circumference, radius and area', 'A circle has a radius of 6 centimeters. Its radius is cut in half. Use 3.14 for $\pi$. By how many square centimeters does the area of the circle decrease?', '[]', '84.78', '3.14*6^2 - 3.14*(6/2)^2', 'Before: $3.14 \times 6^2 = 113.04$. After: radius 3, so $3.14 \times 3^2 = 28.26$. The area decreases by 84.78 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"84.78","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 6: 3.14 x 36 = 113.04. r = 3: 3.14 x 9 = 28.26. Decrease 84.78.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('875e5e12-d017-4198-bc43-aa90b1e2afdb', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a composite figure by adding parts', 'A rectangle is 12 centimeters long and 5 centimeters wide. A right triangle is attached to each of the two 5-centimeter ends. Each triangle has a base of 5 centimeters (along the end of the rectangle) and a height of 3 centimeters. What is the area of the whole figure, in square centimeters?', '["75","60","67.5","90"]', '75', '12*5 + 2*(1/2*5*3)', 'Rectangle: 12 $\times$ 5 = 60. Each triangle: $\frac{1}{2} \times 5 \times 3 = 7.5$, and there are two of them, so 15. Total = 75 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 12 x 5 = 60; each triangle 1/2 x 5 x 3 = 7.5; two = 15. Total 75.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77681571-f205-4432-9515-ce5de754dba8', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a composite figure by adding parts', 'A stage is a rectangle 10 meters wide and 6 meters deep, with a half circle added on one of the 10-meter sides. The diameter of the half circle is that 10-meter side. Use 3.14 for $\pi$. What is the area of the stage, in square meters?', '["138.5","99.25","217","75.7"]', '99.25', '10*6 + 1/2*3.14*(10/2)^2', 'Rectangle: 10 $\times$ 6 = 60. The half circle has radius 5, so its area is $\frac{1}{2} \times 3.14 \times 5^2 = 39.25$. Total = 99.25 square meters.', 'checked', '{"lint":[],"solve":{"answer":"99.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 10 x 6 = 60. Half circle r = 5: 1/2 x 3.14 x 25 = 39.25. Total 99.25.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ea79ad9-3ff9-42e3-b538-6c885b8794e9', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a composite figure by adding parts', 'A U-shaped path is made of three rectangles that do not overlap. The two side pieces are each 9 meters long and 2 meters wide. The bottom piece joins them and is 5 meters long and 2 meters wide. What is the total area of the path, in square meters?', '[]', '46', '2*9*2 + 5*2', 'Each side piece: 9 $\times$ 2 = 18, so the two sides are 36. Bottom piece: 5 $\times$ 2 = 10. Total = 46 square meters.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides: 2 x (9 x 2) = 36. Bottom 5 x 2 = 10. Total 46.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c300280-2c5e-4497-ac41-737e78423f67', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a figure with a part removed', 'A metal washer is a circle with a radius of 10 millimeters, with a circle of radius 4 millimeters cut out of its center. Use 3.14 for $\pi$. What is the area of the metal, in square millimeters?', '["263.76","113.04","364.24","50.24"]', '263.76', '3.14*10^2 - 3.14*4^2', 'Big circle: $3.14 \times 10^2 = 314$. Hole: $3.14 \times 4^2 = 50.24$. Metal: 314 $-$ 50.24 = 263.76 square millimeters.', 'checked', '{"lint":[],"solve":{"answer":"263.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.14 x (100 - 16) = 3.14 x 84 = 263.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('670a1d2e-f030-4cc7-90b6-9acb40ed0e73', 'NC26.7.SGMR.1', 2, 'choice', 'Area of a figure with a part removed', 'A rectangular piece of cardboard is 20 centimeters by 12 centimeters. Four circles, each with a radius of 2 centimeters, are cut out of it. Use 3.14 for $\pi$. What is the area of the cardboard that is left, in square centimeters?', '["227.44","39.04","189.76","50.24"]', '189.76', '20*12 - 4*3.14*2^2', 'Cardboard: 20 $\times$ 12 = 240. Each circle: $3.14 \times 2^2 = 12.56$; four circles: 50.24. Left: 240 $-$ 50.24 = 189.76 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"189.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"240 - 4 x (3.14 x 4) = 240 - 50.24 = 189.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a538d2fd-8cbb-4755-8dce-e9605d1637d8', 'NC26.7.SGMR.1', 2, 'numeric', 'Area of a figure with a part removed', 'A square room has sides of 10 feet. A round rug with a diameter of 8 feet lies flat on the floor. Use 3.14 for $\pi$. How many square feet of the floor are not covered by the rug?', '[]', '49.76', '10*10 - 3.14*(8/2)^2', 'Floor: 10 $\times$ 10 = 100. The rug has radius 4, so its area is $3.14 \times 4^2 = 50.24$. Not covered: 100 $-$ 50.24 = 49.76 square feet.', 'checked', '{"lint":[],"solve":{"answer":"49.76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Floor 100. Rug r = 4: 3.14 x 16 = 50.24. Uncovered 49.76.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c482c6fb-d94c-4992-b2fe-8aa47eb1f661', 'NC26.7.SGMR.1', 2, 'choice', 'Perimeter of a composite figure', 'A square with sides of 6 centimeters has an equilateral triangle (all sides 6 centimeters) attached to its top side. What is the distance around the whole figure, in centimeters?', '["42","24","36","30"]', '30', '3*6 + 2*6', 'The side where the triangle is attached is inside the figure. Around the outside there are 3 sides of the square and 2 sides of the triangle: 5 sides of 6 cm, so 30 cm.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shared side is inside. Outer edges: 3 square sides + 2 triangle sides = 5 x 6 = 30.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('420e7567-a399-41f8-9b46-83c6ef19acd8', 'NC26.7.SGMR.1', 2, 'numeric', 'Perimeter of a composite figure', 'A rectangle is 9 centimeters long and 5 centimeters wide. A square with sides of 5 centimeters is attached to one of its 5-centimeter ends, so the two shapes share a full side. What is the distance around the new figure, in centimeters?', '[]', '38', '2*((9+5)+5)', 'The joined figure is a rectangle 14 cm long and 5 cm wide. Distance around = $2 \times (14 + 5) = 38$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Combined shape is a 14 x 5 rectangle: 2(14 + 5) = 38.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d285403-28be-4bbc-a397-d36d8195c11e', 'NC26.7.SGMR.1', 2, 'numeric', 'Perimeter of a composite figure', 'A garden bed is a rectangle 10 meters long and 4 meters wide, with a half circle added to one of the 4-meter ends. The diameter of the half circle is that 4-meter end. Use 3.14 for $\pi$. A fence runs all the way around the outside of the bed. How many meters of fence are needed?', '[]', '30.28', '10 + 10 + 4 + 1/2*3.14*4', 'The fence has two sides of 10 m, one straight end of 4 m, and the curved end. The curve is half a circle: $\frac{1}{2} \times 3.14 \times 4 = 6.28$ m. Total = 10 + 10 + 4 + 6.28 = 30.28 meters.', 'checked', '{"lint":[],"solve":{"answer":"30.28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Straight edges: 10 + 10 + 4 = 24. Half circle arc: 1/2 x 3.14 x 4 = 6.28. Total 30.28.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2145baf-7e1e-4a7b-bab1-75aa31a4f368', 'NC26.7.SGMR.1', 2, 'numeric', 'Area problems in context: covering and cost', 'A round patio has a radius of 3 meters. Paving costs 4 dollars per square meter. Use 3.14 for $\pi$. How many dollars does it cost to pave the patio?', '[]', '113.04', '3.14*3^2*4', 'Area = $3.14 \times 3^2 = 28.26$ square meters. Cost = 28.26 $\times$ 4 = 113.04 dollars.', 'checked', '{"lint":[],"solve":{"answer":"113.04","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 3.14 x 9 = 28.26. Cost 28.26 x 4 = 113.04.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
