INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bb5ed99-408f-41fc-b6cb-5bf0779abff9', 'NC26.7.SGMR.1', 3, 'numeric', 'Circumference of a circle', 'A wheel has a diameter of 0.5 meter. Use 3.14 for $\pi$. How many full turns does the wheel make to roll exactly 7.85 meters?', '[]', '5', '7.85/(3.14*0.5)', 'One turn covers $3.14 \times 0.5 = 1.57$ meters. Number of turns = 7.85 $\div$ 1.57 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = 3.14 x 0.5 = 1.57 m. 7.85 / 1.57 = 5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
