INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71b86a06-164c-4566-8600-095d259e6c96', 'NC26.7.SGMR.1', 3, 'numeric', 'Pi as the ratio of circumference to diameter', 'A string that is 31.4 centimeters long fits exactly once around a can. Use 3.14 for $\pi$. A second can is 3 centimeters wider across (in diameter) than the first. How long a string fits exactly once around the second can, in centimeters?', '[]', '40.82', '3.14*(31.4/3.14+3)', 'Diameter of the first can = 31.4 $\div$ 3.14 = 10 cm. The second can has a diameter of 10 + 3 = 13 cm, so its circumference is $3.14 \times 13 = 40.82$ cm.', 'checked', '{"lint":[],"solve":{"answer":"40.82","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First can d = 31.4 / 3.14 = 10. Second d = 13. C = 3.14 x 13 = 40.82.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a854c2a-20d0-41f0-bd1d-f96833ce2a78', 'NC26.7.SGMR.1', 3, 'choice', 'Pi as the ratio of circumference to diameter', 'A bicycle wheel is 20 inches across (its diameter). Which is the best estimate of the distance around the tire?', '["About 40 inches","About 120 inches","About 60 inches","About 400 inches"]', 'About 60 inches', NULL, 'The distance around is about 3.14 times the diameter: $3.14 \times 20 = 62.8$, which is close to 60 inches.', 'checked', '{"lint":[],"solve":{"answer":"About 60 inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = pi x 20, about 62.8, so about 60 inches.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ec86b1a-14d0-44e6-a296-07df3038dcf2', 'NC26.7.SGMR.1', 3, 'choice', 'Area of a circle', 'A circle has a diameter of 18 centimeters. What is its area, in square centimeters, in terms of $\pi$?', '["$324\\pi$","$18\\pi$","$81\\pi$","$9\\pi$"]', '$81\pi$', NULL, 'The radius is 18 $\div$ 2 = 9 cm. Area = $\pi \times 9^2 = 81\pi$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$81\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 9. A = 81 pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48de45f3-a32a-4f0f-8d74-ee4f19ad7e40', 'NC26.7.SGMR.1', 3, 'choice', 'Area of a circle', 'A patio is shaped like a half circle. Its straight edge is 16 feet long. Use 3.14 for $\pi$. What is the area of the patio, in square feet?', '["200.96","100.48","401.92","12.56"]', '100.48', '1/2*3.14*(16/2)^2', 'The straight edge is the diameter, so the radius is 16 $\div$ 2 = 8 feet. A full circle would have area $3.14 \times 8^2 = 200.96$ square feet. The half circle has area 100.48 square feet.', 'checked', '{"lint":[],"solve":{"answer":"100.48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Straight edge is the diameter 16, r = 8. Full circle 3.14 x 64 = 200.96; half = 100.48.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b2c0166-3a9a-4532-8d0b-2ba1f2fa0e27', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a circle', 'A circle has a diameter of 20 centimeters. A smaller circle has half that diameter. Use 3.14 for $\pi$. How many square centimeters greater is the area of the larger circle than the area of the smaller circle?', '[]', '235.5', '3.14*(20/2)^2 - 3.14*(20/4)^2', 'Larger circle: radius 10 cm, area $3.14 \times 10^2 = 314$. Smaller circle: radius 5 cm, area $3.14 \times 5^2 = 78.5$. The difference is 235.5 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"235.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Large r = 10: 314. Small d = 10, r = 5: 3.14 x 25 = 78.5. Difference 235.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e260b73a-5baa-4da9-8d63-61269427c772', 'NC26.7.SGMR.1', 3, 'numeric', 'Relate circumference, radius and area', 'The area of a circle is 12.56 square centimeters. A bigger circle has a radius 5 times as long. What is the area of the bigger circle, in square centimeters?', '[]', '314', '12.56*5^2', 'If the radius is multiplied by 5, the area is multiplied by 5 $\times$ 5 = 25. So the new area is 12.56 $\times$ 25 = 314 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"314","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radius x5 means area x25: 12.56 x 25 = 314.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b97417fe-099d-485f-b52b-ad9f54e71c91', 'NC26.7.SGMR.1', 3, 'choice', 'Relate circumference, radius and area', 'A circle has a circumference of $12\pi$ centimeters. What is its area, in square centimeters?', '["$144\\pi$","$12\\pi$","$36\\pi$","$6\\pi$"]', '$36\pi$', NULL, 'Circumference = $2\pi r = 12\pi$, so $r = 6$ cm. Area = $\pi r^2 = \pi \times 6^2 = 36\pi$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$36\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 pi r = 12 pi, r = 6. A = 36 pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53e319ff-9bfd-4aad-9822-6cdf8f84b242', 'NC26.7.SGMR.1', 3, 'numeric', 'Relate circumference, radius and area', 'A square has sides of 15.7 centimeters. A circle has the same distance around as the square. Use 3.14 for $\pi$. What is the diameter of the circle, in centimeters?', '[]', '20', '4*15.7/3.14', 'The square''s perimeter is $4 \times 15.7 = 62.8$ cm, which is the circle''s circumference. Diameter = 62.8 $\div$ 3.14 = 20 cm.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square perimeter = 4 x 15.7 = 62.8. d = 62.8 / 3.14 = 20.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
