INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('442f6533-bed8-411c-a93f-c0c94c45580b', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a composite figure by adding parts', 'Two strips of tape cross to make a plus sign. One strip is 10 centimeters long and 2 centimeters wide. The other is 6 centimeters long and 2 centimeters wide. They overlap in a 2-centimeter by 2-centimeter square. What is the area covered by the tape, in square centimeters?', '[]', '28', '10*2 + 6*2 - 2*2', 'Adding the two strips counts the overlap twice. 10 $\times$ 2 = 20 and 6 $\times$ 2 = 12. Subtract the overlap once: 20 + 12 $-$ 4 = 28 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 x 2 + 6 x 2 - 2 x 2 = 20 + 12 - 4 = 28.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71c7b9ee-050e-4a39-b783-41f32650b351', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a composite figure by adding parts', 'A field is a rectangle 20 meters long and 8 meters wide, with a half circle added at each of the two 8-meter ends. Use 3.14 for $\pi$. What is the area of the field, in square meters?', '[]', '210.24', '20*8 + 3.14*(8/2)^2', 'Rectangle: 20 $\times$ 8 = 160. The two half circles together make one circle of radius 4: $3.14 \times 4^2 = 50.24$. Total = 210.24 square meters.', 'checked', '{"lint":[],"solve":{"answer":"210.24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 20 x 8 = 160. Two half circles of diameter 8 make one full circle r = 4: 3.14 x 16 = 50.24. Total 210.24.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d38fc9cd-3502-4894-9111-2c59ade768af', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a composite figure by adding parts', 'A figure is made of a rectangle and a triangle. The rectangle is 8 centimeters by 7 centimeters. The triangle has a base of 8 centimeters and sits on one 8-centimeter side of the rectangle. The whole figure has an area of 70 square centimeters. What is the height of the triangle, in centimeters?', '[]', '3.5', '2*(70 - 8*7)/8', 'Rectangle: 8 $\times$ 7 = 56. The triangle''s area is 70 $-$ 56 = 14. Height = $2 \times 14 \div 8 = 3.5$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle 56. Triangle = 70 - 56 = 14 = 1/2 x 8 x h, h = 3.5.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44eb40c9-1ea7-420f-9169-767981388740', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a figure with a part removed', 'A rectangular metal plate is 16 centimeters long and 10 centimeters wide. A half-circle notch is cut out of one long edge. The straight side of the notch is 8 centimeters long. Use 3.14 for $\pi$. What is the area of the plate that is left, in square centimeters?', '[]', '134.88', '16*10 - 1/2*3.14*(8/2)^2', 'Plate: 16 $\times$ 10 = 160. The notch has radius 4, so its area is $\frac{1}{2} \times 3.14 \times 4^2 = 25.12$. Left: 160 $-$ 25.12 = 134.88 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"134.88","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Plate 160. Notch r = 4: 1/2 x 3.14 x 16 = 25.12. Left 134.88.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84ccac2e-a7be-4806-9f86-6f962b1c1934', 'NC26.7.SGMR.1', 3, 'choice', 'Area of a figure with a part removed', 'A photo that is 16 centimeters by 10 centimeters sits in a frame that is 3 centimeters wide on all four sides. What is the area of the frame itself (not the photo), in square centimeters?', '["192","352","160","87"]', '192', '(16+2*3)*(10+2*3) - 16*10', 'With the frame, the outside measures 22 cm by 16 cm, so the whole area is 352. The photo is 16 $\times$ 10 = 160. Frame: 352 $-$ 160 = 192 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"192","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outer 22 x 16 = 352. Photo 160. Frame 192.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddf9ceec-1328-40db-b384-7c760caff7aa', 'NC26.7.SGMR.1', 3, 'numeric', 'Area of a figure with a part removed', 'A rectangular hole 4 centimeters wide is cut in a square plate with sides of 10 centimeters. After the hole is cut, 64 square centimeters of the plate remain. How long is the hole, in centimeters?', '[]', '9', '(10*10 - 64)/4', 'The plate is 10 $\times$ 10 = 100 square centimeters, so the hole has area 100 $-$ 64 = 36. Length = 36 $\div$ 4 = 9 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hole area 100 - 64 = 36. Length 36 / 4 = 9.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d9ffa0f-79d3-47aa-aef1-a20ab94add97', 'NC26.7.SGMR.1', 3, 'choice', 'Perimeter of a composite figure', 'A running track has two straight sides, each 40 meters long, joined at the ends by two half circles. Each half circle has a diameter of 20 meters. Use 3.14 for $\pi$. How far is it once around the track, in meters?', '["205.6","111.4","102.8","142.8"]', '142.8', '2*40 + 3.14*20', 'The two half circles together make one full circle with diameter 20 m: $3.14 \times 20 = 62.8$ m. Add the two straight sides: 80 + 62.8 = 142.8 meters.', 'checked', '{"lint":[],"solve":{"answer":"142.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Straights 80. Two half circles = one circle d = 20: 62.8. Total 142.8.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('457617be-cfcb-4b73-904b-5fb5991a38f3', 'NC26.7.SGMR.1', 3, 'numeric', 'Perimeter of a composite figure', 'An L-shaped room is a 12-foot by 9-foot rectangle with a 5-foot by 4-foot rectangle cut out of one corner. How many feet of baseboard go along all the walls of the room, all the way around?', '[]', '42', '2*(12+9)', 'Cutting a rectangle out of a corner does not change the distance around: the walls still total the same as the original rectangle. $2 \times (12 + 9) = 42$ feet.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cutting a corner rectangle leaves the perimeter equal to the full rectangle''s: sides 12, 9, 7, 5, 5, 4 (sum 42) = 2(12 + 9) = 42.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89ce18b3-712f-47d9-bcc2-2e0f339d7f14', 'NC26.7.SGMR.1', 3, 'numeric', 'Perimeter of a composite figure', 'A flower bed is shaped like a quarter of a circle. Its two straight edges are each 10 feet long (the radius of the circle), and its curved edge is one fourth of the circle''s circumference. Use 3.14 for $\pi$. How many feet of edging go along all three edges?', '[]', '35.7', '10 + 10 + 1/4*2*3.14*10', 'Curved edge = $\frac{1}{4} \times 2 \times 3.14 \times 10 = 15.7$ feet. Total = 10 + 10 + 15.7 = 35.7 feet.', 'checked', '{"lint":[],"solve":{"answer":"35.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two radii 20. Arc = 1/4 x 2 x 3.14 x 10 = 15.7. Total 35.7.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2df7c22-d850-4b5a-b4da-70458d74b908', 'NC26.7.SGMR.1', 3, 'numeric', 'Area problems in context: covering and cost', 'A pizza has a radius of 5 inches and costs 7.85 dollars. Use 3.14 for $\pi$. How many dollars does the pizza cost for each square inch of pizza?', '[]', '0.1', '7.85/(3.14*5^2)', 'Area = $3.14 \times 5^2 = 78.5$ square inches. Cost per square inch = 7.85 $\div$ 78.5 = 0.1 dollars.', 'checked', '{"lint":[],"solve":{"answer":"0.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area 3.14 x 25 = 78.5. 7.85 / 78.5 = 0.1 dollars per sq in.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
