INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b78c19be-31db-40ad-a66d-8e3e959e1514', 'NC26.7.SGMR.1', 3, 'numeric', 'Area problems in context: covering and cost', 'A rectangular yard is 20 meters long and 15 meters wide. A circular pond with a radius of 5 meters is in the yard. Grass seed is spread on everything except the pond and costs 2 dollars per square meter. Use 3.14 for $\pi$. How many dollars does the grass seed cost?', '[]', '443', '(20*15 - 3.14*5^2)*2', 'Yard: 20 $\times$ 15 = 300. Pond: $3.14 \times 5^2 = 78.5$. Seeded area: 300 $-$ 78.5 = 221.5. Cost: 221.5 $\times$ 2 = 443 dollars.', 'checked', '{"lint":[],"solve":{"answer":"443","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Yard 300 - pond 3.14 x 25 = 78.5 gives 221.5. Cost 221.5 x 2 = 443.","run_id":"claude-code","at":"2026-10-17T20:23:34.933Z"}}', 'ai', NULL, NULL)
