INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc933bb3-20e1-4f15-a2cc-1044203a45d9', 'NC26.7.SGMR.2', 1, 'choice', 'Volume of a rectangular prism', 'A cube-shaped box has edges that are each 4 inches long. What is the volume of the box, in cubic inches?', '["12","16","96","64"]', '64', '4^3', 'Volume = edge $\times$ edge $\times$ edge = 4 $\times$ 4 $\times$ 4 = 64 cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 4^3 = 64.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
