INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b30e33d7-0091-4cdb-a427-482edb5585ba', 'NC26.7.SGMR.2', 1, 'numeric', 'Volume of a rectangular prism', 'A block of wood is 6 centimeters long, 4 centimeters wide and 3 centimeters tall. What is its volume, in cubic centimeters?', '[]', '72', '6*4*3', 'Volume = length $\times$ width $\times$ height = 6 $\times$ 4 $\times$ 3 = 72 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 x 4 x 3 = 72.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
