INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efa23d83-3f91-4ca0-81f0-6b1d490396be', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a rectangular prism or cube', 'The faces of a rectangular box come in three matching pairs. The top and bottom are each 12 square inches, the front and back are each 8 square inches, and the two sides are each 6 square inches. What is the total surface area of the box, in square inches?', '["26","52","576","40"]', '52', '2*12+2*8+2*6', 'Add all six faces: 2 $\times$ 12 + 2 $\times$ 8 + 2 $\times$ 6 = 24 + 16 + 12 = 52 square inches.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(12 + 8 + 6) = 52. (Consistent with a 4 x 3 x 2 box.)","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20d43f73-4c41-4fda-8a5f-9939435162a7', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area of a rectangular prism or cube', 'A box is 6 cm long, 2 cm wide and 3 cm high. Which expression gives its total surface area, in square centimeters?', '["$6 \\times 2 \\times 3$","$6 \\times 2 + 6 \\times 3 + 2 \\times 3$","$2(6 + 2 + 3)$","$2(6 \\times 2) + 2(6 \\times 3) + 2(2 \\times 3)$"]', '$2(6 \times 2) + 2(6 \times 3) + 2(2 \times 3)$', NULL, 'The box has three pairs of faces: $6 \times 2$, $6 \times 3$ and $2 \times 3$. Surface area is the sum of all six faces, so each product is counted twice.', 'checked', '{"lint":[],"solve":{"answer":"$2(6 \\times 2) + 2(6 \\times 3) + 2(2 \\times 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three pairs of faces: 2(lw) + 2(lh) + 2(wh).","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('764564fc-6814-4762-a495-20d1b64ca732', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area as the sum of the faces (nets and triangular prisms)', 'The net of a closed box is made of six rectangles: two that are 5 cm by 3 cm, two that are 5 cm by 2 cm, and two that are 3 cm by 2 cm. What is the total area of the net, in square centimeters?', '["62","31","30","124"]', '62', '2*5*3+2*5*2+2*3*2', 'Add the areas of all six rectangles: 2 $\times$ 15 + 2 $\times$ 10 + 2 $\times$ 6 = 30 + 20 + 12 = 62 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(15) + 2(10) + 2(6) = 62.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
