INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc42ae7c-b81c-43ba-b823-7bf4fe425d91', 'NC26.7.SGMR.2', 1, 'choice', 'Surface area as the sum of the faces (nets and triangular prisms)', 'Which list shows all of the faces of a triangular prism?', '["3 triangles and 2 rectangles","2 triangles and 4 rectangles","2 triangles and 3 rectangles","1 triangle and 3 rectangles"]', '2 triangles and 3 rectangles', NULL, 'A triangular prism has two triangular ends. Each of the 3 sides of the triangle gives one rectangular face, so there are 3 rectangles.', 'checked', '{"lint":[],"solve":{"answer":"2 triangles and 3 rectangles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two triangular ends and three rectangular sides.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
