INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6787298-8f0b-4115-b456-3752c0caab72', 'NC26.7.SGMR.2', 1, 'numeric', 'Surface area as the sum of the faces (nets and triangular prisms)', 'A triangular prism has two triangular faces that each have an area of 6 square centimeters. Its three rectangular faces have areas of 20, 16 and 12 square centimeters. What is the total surface area of the prism, in square centimeters?', '[]', '60', '2*6 + 20 + 16 + 12', 'Triangles: 2 $\times$ 6 = 12. Rectangles: 20 + 16 + 12 = 48. Total = 60 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 x 6 + 20 + 16 + 12 = 60.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
