INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88503e7f-0fa1-4cf5-a19b-1cdc4086c808', 'NC26.7.SGMR.2', 1, 'choice', 'Unknown dimension from volume or surface area', 'A rectangular box has a volume of 72 cubic centimeters. It is 4 cm wide and 3 cm high. How long is the box, in centimeters?', '["6","18","24","864"]', '6', '72/(4*3)', 'Volume = length $\times$ width $\times$ height, so length = 72 $\div$ (4 $\times$ 3) = 72 $\div$ 12 = 6 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"72 / (4 x 3) = 6.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
