INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59facc9f-a69c-4313-84f5-89d499be8337', 'NC26.7.SGMR.2', 1, 'choice', 'Volume of a composite solid', 'A toy is made of two rectangular blocks joined together. Block A is 4 cm by 3 cm by 2 cm. Block B is 5 cm by 3 cm by 2 cm. What is the volume of the whole toy, in cubic centimeters?', '["24","30","720","54"]', '54', '4*3*2+5*3*2', 'Block A: 4 $\times$ 3 $\times$ 2 = 24. Block B: 5 $\times$ 3 $\times$ 2 = 30. Whole toy: 24 + 30 = 54 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24 + 30 = 54.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
