INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e82d0ce8-7d89-4e37-9b28-7c5c4d1b5718', 'NC26.7.SGMR.2', 1, 'choice', 'Volume of a composite solid', 'A small cube with edges of 2 cm sits on top of a large cube with edges of 6 cm. What is the volume of the whole solid, in cubic centimeters?', '["216","224","512","8"]', '224', '6^3+2^3', 'Large cube: 6 $\times$ 6 $\times$ 6 = 216. Small cube: 2 $\times$ 2 $\times$ 2 = 8. Together: 216 + 8 = 224 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"224","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + 216 = 224.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
