INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d3c3214-ffc8-4f44-8155-70be33fdc8a1', 'NC26.7.SGMR.2', 1, 'numeric', 'Surface area of a composite solid', 'Two identical boxes each have a surface area of 52 square centimeters. They are glued together so that a face of 6 square centimeters on each box is hidden. What is the surface area of the glued solid, in square centimeters?', '[]', '92', '2*52 - 2*6', 'Together the boxes have 52 + 52 = 104 square centimeters of surface. The two hidden faces take away 6 + 6 = 12. Surface area = 104 $-$ 12 = 92 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52 + 52 - 6 - 6 = 92.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
