INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6875f6fb-e0cf-4474-88d4-69ab08815529', 'NC26.7.SGMR.2', 1, 'choice', 'How changing dimensions changes volume', 'Every edge of a cube is made twice as long. The volume of the new cube is how many times the volume of the old cube?', '["2","4","8","6"]', '8', '2^3', 'Volume uses three lengths multiplied together, and each one doubles: 2 $\times$ 2 $\times$ 2 = 8. The new volume is 8 times the old volume.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 = 8.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
