INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c4463c0-fec6-4d6c-a723-2cf390ac9544', 'NC26.7.SGMR.2', 1, 'numeric', 'How changing dimensions changes volume', 'A box is 5 cm long, 3 cm wide and 2 cm high. Its height is doubled, and its length and width stay the same. What is the volume of the new box, in cubic centimeters?', '[]', '60', '5*3*2*2', 'The new height is 2 $\times$ 2 = 4 cm. Volume = 5 $\times$ 3 $\times$ 4 = 60 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 3 x 4 = 60.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
