INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6268b5d-96a0-4812-a68f-43f6c5d43c34', 'NC26.7.SGMR.2', 1, 'choice', 'How changing dimensions changes volume', 'The base of a prism stays the same, but its height is tripled. What happens to the volume?', '["It becomes 9 times as large","It stays the same","It increases by 3 cubic units","It becomes 3 times as large"]', 'It becomes 3 times as large', NULL, 'Volume = base area $\times$ height. The base area does not change and the height is multiplied by 3, so the volume is multiplied by 3.', 'checked', '{"lint":[],"solve":{"answer":"It becomes 3 times as large","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = B h; tripling h triples V.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
