INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf1910e5-f330-44ce-979e-57690260a1d0', 'NC26.7.SGMR.2', 2, 'choice', 'Volume as layers of the base', 'A hallway floor is 12 meters long and 2 meters wide. It is covered with a layer of sand 0.1 meter deep. How many cubic meters of sand are on the floor?', '["24","0.24","14.1","2.4"]', '2.4', '12*2*0.1', 'Base area = 12 $\times$ 2 = 24 square meters. Volume of sand = 24 $\times$ 0.1 = 2.4 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"2.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 x 2 x 0.1 = 2.4.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
