INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30801294-b8d6-4c5e-8608-277ecee3def3', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume as layers of the base', 'A prism is built from layers of 1-centimeter cubes. Each layer has 25 cubes, and the prism holds 150 cubic centimeters in all. How tall is the prism, in centimeters?', '[]', '6', '150/25', 'Each layer is 1 cm tall and holds 25 cubic centimeters. The number of layers is 150 $\div$ 25 = 6, so the prism is 6 centimeters tall.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"150 / 25 = 6 layers, each 1 cm, so 6 cm.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
