INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e61b3cef-6fd3-4275-9e68-bb76afec8828', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a triangular or trapezoidal prism', 'The end of a water trough is a trapezoid. Its parallel sides are 6 feet and 10 feet long, and they are 4 feet apart. The trough is 15 feet long. How many cubic feet of water does the trough hold when it is full?', '["960","240","32","480"]', '480', '1/2*(6+10)*4*15', 'Area of the trapezoid end = $\frac{1}{2} \times (6 + 10) \times 4 = 32$ square feet. Volume = 32 $\times$ 15 = 480 cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"480","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"End area 1/2 x (6 + 10) x 4 = 32; V = 32 x 15 = 480.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
