INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b89f0187-d045-4d27-a98e-7f3208a8b34e', 'NC26.7.SGMR.2', 2, 'choice', 'Volume of a cylinder', 'A soup can has a diameter of 8 centimeters and a height of 10 centimeters. Use 3.14 for $\pi$. What is its volume, in cubic centimeters?', '["2009.6","502.4","251.2","125.6"]', '502.4', '3.14*(8/2)^2*10', 'The radius is 8 $\div$ 2 = 4 cm. Volume = $3.14 \times 4 \times 4 \times 10 = 502.4$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"502.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 4. 3.14 x 16 x 10 = 502.4.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
