INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d51bba44-7b80-4c0a-a914-235032097de6', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume of a cylinder', 'A cylindrical tank has a radius of 3 meters and a height of 5 meters. It is half full of water. Use 3.14 for $\pi$. How many cubic meters of water are in the tank?', '[]', '70.65', '1/2*3.14*3^2*5', 'Volume of the whole tank = $3.14 \times 3^2 \times 5 = 141.3$ cubic meters. Half of that is 70.65 cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"70.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Full: 3.14 x 9 x 5 = 141.3. Half: 70.65.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
