INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6aee1d9-b678-48b0-8fa7-dcd8c468bda3', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a rectangular prism or cube', 'A room is 5 meters long, 4 meters wide and 3 meters high. A painter paints the four walls only (not the floor or the ceiling). What is the area to be painted, in square meters?', '["54","94","27","60"]', '54', '2*(5*3+4*3)', 'Two walls are 5 $\times$ 3 = 15 each, and two walls are 4 $\times$ 3 = 12 each. Total = 2 $\times$ 15 + 2 $\times$ 12 = 54 square meters.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(5 x 3) + 2(4 x 3) = 30 + 24 = 54.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
