INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7417b8cd-ab07-4487-9e3f-638ecd2e3a70', 'NC26.7.SGMR.2', 2, 'numeric', 'Surface area as the sum of the faces (nets and triangular prisms)', 'The ends of a prism are right triangles with sides of 6 cm, 8 cm and 10 cm. The prism is 5 cm long. What is its total surface area, in square centimeters?', '[]', '168', '2*(1/2*6*8) + (6+8+10)*5', 'Two triangular ends: 2 $\times$ $\frac{1}{2} \times 6 \times 8$ = 48. Three rectangles together: (6 + 8 + 10) $\times$ 5 = 24 $\times$ 5 = 120. Total = 48 + 120 = 168 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"168","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x (1/2 x 6 x 8) = 48. Sides (6 + 8 + 10) x 5 = 120. Total 168.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
