INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1e36b0e-b5e4-4110-bc5f-cfa933307230', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a cylinder', 'A closed cylinder has a radius of 3 cm and a height of 8 cm. Use 3.14 for $\pi$. What is its total surface area, in square centimeters?', '["207.24","150.72","56.52","178.98"]', '207.24', '2*3.14*3^2+2*3.14*3*8', 'Two circular ends: 2 $\times$ 3.14 $\times$ $3^2$ = 56.52. Curved side: 2 $\times$ 3.14 $\times$ 3 $\times$ 8 = 150.72. Total = 207.24 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"207.24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ends 2 x 3.14 x 9 = 56.52. Side 2 x 3.14 x 3 x 8 = 150.72. Total 207.24.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
