INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9035b3d6-21a9-430b-a8a0-43f9e2c212e3', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a cylinder', 'A cylinder-shaped can has no lid. Its radius is 5 cm and its height is 12 cm. Use 3.14 for $\pi$. How many square centimeters of material form the bottom and the curved side?', '["533.8","376.8","455.3","157"]', '455.3', '3.14*5^2+2*3.14*5*12', 'Bottom: 3.14 $\times$ $5^2$ = 78.5. Curved side: 2 $\times$ 3.14 $\times$ 5 $\times$ 12 = 376.8. Total = 455.3 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"455.3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bottom 3.14 x 25 = 78.5. Side 2 x 3.14 x 5 x 12 = 376.8. Total 455.3.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
