INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ee26666-362e-42b5-8cbb-0d813cad1f6c', 'NC26.7.SGMR.2', 2, 'numeric', 'Unknown dimension from volume or surface area', 'A cylinder has a radius of 5 centimeters and a volume of 1570 cubic centimeters. Use 3.14 for $\pi$. How tall is the cylinder, in centimeters?', '[]', '20', '1570/(3.14*5^2)', 'Base area = $3.14 \times 5^2 = 78.5$ square centimeters. Height = 1570 $\div$ 78.5 = 20 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 3.14 x 25 = 78.5. h = 1570 / 78.5 = 20.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
