INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('612cc277-ba43-483c-999e-f3f68ea9b6bc', 'NC26.7.SGMR.2', 2, 'choice', 'Unknown dimension from volume or surface area', 'A triangular prism has a volume of 120 cubic centimeters and is 10 cm long. What is the area of one of its triangular ends, in square centimeters?', '["1200","110","6","12"]', '12', '120/10', 'Volume = area of the end $\times$ length, so the area of the end is 120 $\div$ 10 = 12 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 / 10 = 12.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
