INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b47da22c-66c4-49b4-81c3-8b6adccbffaa', 'NC26.7.SGMR.2', 2, 'numeric', 'Volume of a composite solid', 'The base of a prism is an L-shape made from a 10 cm by 4 cm rectangle and a 6 cm by 3 cm rectangle that touch along an edge and do not overlap. The prism is 5 cm tall. What is its volume, in cubic centimeters?', '[]', '290', '(10*4 + 6*3)*5', 'Area of the L-shaped base = 10 $\times$ 4 + 6 $\times$ 3 = 40 + 18 = 58. Volume = 58 $\times$ 5 = 290 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"290","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base area 40 + 18 = 58. V = 58 x 5 = 290.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
