INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bdec067-de26-4ede-b2db-878c0df3edf0', 'NC26.7.SGMR.2', 2, 'choice', 'Surface area of a composite solid', 'A cube with edges of 3 cm is glued to the end of a rectangular box that is 3 cm by 3 cm by 6 cm, so that the 3 cm by 3 cm faces match exactly. What is the surface area of the new solid, in square centimeters?', '["126","144","90","54"]', '126', '2*(3*3+3*9+3*9)', 'The new solid is a box 3 cm by 3 cm by 9 cm. Surface area = 2(3 $\times$ 3 + 3 $\times$ 9 + 3 $\times$ 9) = 2(9 + 27 + 27) = 126 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"126","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Makes a 3 x 3 x 9 box: 2(9 + 27 + 27) = 126.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
