INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d9debfa-628c-4417-ad39-774b62ee591b', 'NC26.7.SGMR.2', 2, 'numeric', 'Surface area of a composite solid', 'A cylinder with a radius of 2 cm and a height of 5 cm stands on the top face of a cube with edges of 6 cm. Use 3.14 for $\pi$. What is the surface area of the combined solid, including the bottom of the cube, in square centimeters?', '[]', '278.8', '6*6^2 + 2*3.14*2*5', 'The circle where the cylinder touches the cube is hidden, but the top of the cylinder is a circle of the same size, so the flat surfaces total the same as the cube alone: 6 $\times$ $6^2$ = 216. The curved side of the cylinder adds 2 $\times$ 3.14 $\times$ 2 $\times$ 5 = 62.8. Total = 278.8 square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"278.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube 6 x 36 = 216 (the circle hidden on its top is replaced by the cylinder''s top). Add cylinder side 2 x 3.14 x 2 x 5 = 62.8. Total 278.8.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f201d222-14c7-4499-82a9-7ced93b00bf0', 'NC26.7.SGMR.2', 2, 'numeric', 'How changing dimensions changes volume', 'A cylinder has a volume of 50 cubic centimeters. Its radius is doubled and its height stays the same. What is the volume of the new cylinder, in cubic centimeters?', '[]', '200', '50*4', 'Volume = $\pi r^2 h$. Doubling $r$ multiplies $r^2$ by 2 $\times$ 2 = 4, so the volume is multiplied by 4: 50 $\times$ 4 = 200 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling r multiplies r^2 by 4: 50 x 4 = 200.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107276a0-2944-4f20-816c-cb701f10560a', 'NC26.7.SGMR.2', 2, 'choice', 'How changing dimensions changes volume', 'A cube has a volume of 8 cubic centimeters. Every edge is made 3 times as long. What is the volume of the new cube, in cubic centimeters?', '["216","72","24","35"]', '216', '8*27', 'Each of the three lengths is multiplied by 3, so the volume is multiplied by 3 $\times$ 3 $\times$ 3 = 27. New volume = 8 $\times$ 27 = 216 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edge 2 becomes 6; 6^3 = 216 (or 8 x 27).","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('216befba-31b1-4172-b4a0-1f851ea67c3c', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a composite solid', 'A solid is made by placing a rectangular prism that is 5 centimeters by 6 centimeters by 3 centimeters on top of a larger rectangular prism that is 10 centimeters by 6 centimeters by 4 centimeters. What is the volume of the whole solid in cubic centimeters?', '[]', '330', '5*6*3+10*6*4', 'Top prism: $5 \times 6 \times 3 = 90$. Bottom prism: $10 \times 6 \times 4 = 240$. Whole solid: $90 + 240 = 330$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"330","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Top: 5 x 6 x 3 = 90. Bottom: 10 x 6 x 4 = 240. Total 330 (volume does not depend on orientation).","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45a06e81-e039-4902-9e6d-57b3d2a8ef1f', 'NC26.7.SGMR.2', 3, 'numeric', 'Surface area of a closed cylinder', 'A closed cylinder (it has a top and a bottom) has a radius of 2 centimeters and a height of 5 centimeters. Use 3.14 for $\pi$. What is its surface area in square centimeters?', '[]', '87.92', '2*3.14*2^2+2*3.14*2*5', 'The top and bottom are two circles: $2 \times 3.14 \times 2^2 = 25.12$. The side unrolls into a rectangle as wide as the distance around the circle ($2 \times 3.14 \times 2 = 12.56$) and 5 tall: $12.56 \times 5 = 62.8$. Total = $25.12 + 62.8 = 87.92$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"87.92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two circles: 2 x 3.14 x 4 = 25.12. Curved side: 2 x 3.14 x 2 x 5 = 62.8. Total 87.92.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e59c5cb3-e072-456e-adfa-361fe0200cac', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a solid with a hole', 'A solid block is a rectangular prism that is 8 centimeters by 6 centimeters by 5 centimeters. A square hole 2 centimeters by 2 centimeters is cut all the way through the 5-centimeter thickness. What is the volume of the solid that is left, in cubic centimeters?', '[]', '220', '8*6*5-2*2*5', 'The full block has volume $8 \times 6 \times 5 = 240$. The hole removes a prism $2 \times 2 \times 5 = 20$. What is left: $240 - 20 = 220$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"220","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Block 8 x 6 x 5 = 240. Hole 2 x 2 x 5 = 20. Left 240 - 20 = 220.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a14edc9-8a26-4932-8b49-f06e7964c099', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a rectangular prism', 'A rectangular tank has a base that is 40 cm by 25 cm and contains some water. A rock is dropped in and is completely covered, and the water level rises by 3 cm. What is the volume of the rock, in cubic centimeters?', '[]', '3000', '40*25*3', 'The rock pushes aside water in a layer 3 cm deep over the whole base. Volume of the rock = 40 $\times$ 25 $\times$ 3 = 3000 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Displaced water = 40 x 25 x 3 = 3000.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4400b9d-a37f-4a8b-a045-c40a0ded31c1', 'NC26.7.SGMR.2', 3, 'choice', 'Volume of a rectangular prism', 'A rectangular prism has a volume of 120 cubic centimeters. Which could be its length, width and height?', '["10 cm by 6 cm by 4 cm","7 cm by 5 cm by 4 cm","8 cm by 5 cm by 3 cm","6 cm by 5 cm by 5 cm"]', '8 cm by 5 cm by 3 cm', NULL, '$8 \times 5 \times 3 = 120$. The others give $10 \times 6 \times 4 = 240$, $7 \times 5 \times 4 = 140$ and $6 \times 5 \times 5 = 150$.', 'checked', '{"lint":[],"solve":{"answer":"8 cm by 5 cm by 3 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x5x4 = 140; 8x5x3 = 120; 6x5x5 = 150; 10x6x4 = 240. Only 8 by 5 by 3.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7dd445e5-c415-4bb0-8018-c10977be3c83', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume as layers of the base', 'A solid is built from layers of unit cubes. The bottom 3 layers have 40 cubes each, and the top 2 layers have 28 cubes each. How many cubes are in the solid?', '[]', '176', '40*3 + 28*2', 'Bottom layers: 40 $\times$ 3 = 120. Top layers: 28 $\times$ 2 = 56. Total = 120 + 56 = 176 cubes.', 'checked', '{"lint":[],"solve":{"answer":"176","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 40 + 2 x 28 = 120 + 56 = 176.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
