INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a5a5bc9-c309-4dbe-b317-496610c0dcce', 'NC26.7.SGMR.2', 3, 'choice', 'Volume as layers of the base', 'Prism A has a base area of 18 square centimeters and a height of 10 centimeters. Prism B has a base area of 24 square centimeters and a height of 8 centimeters. Which prism has the greater volume, and by how much?', '["Prism A, by 12 cubic centimeters","Prism B, by 6 cubic centimeters","Prism A, by 2 cubic centimeters","Prism B, by 12 cubic centimeters"]', 'Prism B, by 12 cubic centimeters', NULL, 'Prism A: 18 $\times$ 10 = 180. Prism B: 24 $\times$ 8 = 192. Prism B is greater by 12 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"Prism B, by 12 cubic centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 18 x 10 = 180. B: 24 x 8 = 192. B greater by 12.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9601faa7-f34a-49c9-9b4b-d9e69b34308e', 'NC26.7.SGMR.2', 3, 'choice', 'Volume of a triangular or trapezoidal prism', 'The ends of a prism are right triangles with sides of 9 cm, 12 cm and 15 cm. The 15 cm side is the longest. The prism is 10 cm long. What is its volume, in cubic centimeters?', '["540","1080","270","1620"]', '540', '1/2*9*12*10', 'The two shorter sides meet at the right angle, so they are the base and the height of the triangle: $\frac{1}{2} \times 9 \times 12 = 54$ square centimeters. Volume = 54 $\times$ 10 = 540 cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"540","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 9 and 12: end area 54; V = 54 x 10 = 540.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
