INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('361fcc39-cfd3-4203-b32c-e1976bfa2011', 'NC26.7.SGMR.2', 3, 'numeric', 'Volume of a triangular or trapezoidal prism', 'A triangular prism has a volume of 252 cubic centimeters. Each triangular end has a base of 8 centimeters and a height of 9 centimeters. How long is the prism, in centimeters?', '[]', '7', '252/(1/2*8*9)', 'Area of a triangular end = $\frac{1}{2} \times 8 \times 9 = 36$ square centimeters. Length = 252 $\div$ 36 = 7 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"End area 1/2 x 8 x 9 = 36; length 252 / 36 = 7.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
