INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5fd4922-d926-4cc0-825d-50d597f4aea4', 'NC26.7.SGMR.2', 3, 'choice', 'Volume of a cylinder', 'A cylinder has a diameter of 10 centimeters and a height of 9 centimeters. What is its volume, in cubic centimeters, in terms of $\pi$?', '["$900\\pi$","$90\\pi$","$450\\pi$","$225\\pi$"]', '$225\pi$', NULL, 'The radius is 5 cm. Volume = $\pi \times 5^2 \times 9 = \pi \times 25 \times 9 = 225\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$225\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 5. V = pi x 25 x 9 = 225 pi.","run_id":"claude-code","at":"2026-10-17T20:23:34.973Z"}}', 'ai', NULL, NULL)
