INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b3bfc5c-6b2e-456e-a5cc-538dd5063491', 'NC26.7.SGMR.3', 1, 'numeric', 'Complementary angles: find the missing angle', 'Angle $P$ and angle $Q$ are complementary, which means that together they make a right angle. Angle $P$ measures $28^\circ$. How many degrees is angle $Q$?', '[]', '62', '90-28', 'Complementary angles add up to $90^\circ$. So angle $Q$ is $90 - 28 = 62$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complementary: P + Q = 90. Q = 90 - 28 = 62.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4af28b0-bdd7-4f3e-b272-8c9f5d80b916', 'NC26.7.SGMR.3', 1, 'choice', 'Complementary angles: find the missing angle', 'What is the measure, in degrees, of the complement of an angle that measures $71^\circ$?', '["109","161","45","19"]', '19', '90-71', 'The complement is the angle that adds with $71^\circ$ to make $90^\circ$: $90 - 71 = 19$. The choice 109 is the supplement ($180 - 71$), 161 adds $90 + 71$, and 45 assumes the two angles are equal.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement of 71 = 90 - 71 = 19.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c2c9c77-6d10-43d8-b734-8125ccae3f7e', 'NC26.7.SGMR.3', 1, 'numeric', 'Complementary angles: find the missing angle', 'A wooden shelf bracket is fixed in a square corner of a wall (a right angle). It splits the corner into two angles. One of the angles is $40^\circ$. What is the other angle, in degrees?', '[]', '50', '90-40', 'A square corner is $90^\circ$, so the two parts add up to $90^\circ$. The other angle is $90 - 40 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The two angles fill a right angle: 90 - 40 = 50.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e737354-5147-4906-a28b-90ebaf0a4a78', 'NC26.7.SGMR.3', 1, 'choice', 'Complementary angles: find the missing angle', 'Which statement about complementary angles is true?', '["Their measures add up to $180^\\circ$.","Their measures are always equal.","Their measures add up to $90^\\circ$.","Their measures add up to $360^\\circ$."]', 'Their measures add up to $90^\circ$.', NULL, 'Complementary angles are two angles whose measures add up to $90^\circ$, a right angle. Angles that add up to $180^\circ$ are supplementary. Complementary angles need not be equal (for example $30^\circ$ and $60^\circ$).', 'checked', '{"lint":[],"solve":{"answer":"Their measures add up to $90^\\circ$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complementary angles sum to 90 degrees by definition. 180 is supplementary; 360 is a full turn; they need not be equal.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbb7fcd1-e65c-47d1-8d02-e0e830c9f4d8', 'NC26.7.SGMR.3', 1, 'numeric', 'Supplementary angles: find the missing angle', 'Angle $M$ and angle $N$ are supplementary, which means that together they make a straight angle. Angle $M$ measures $125^\circ$. How many degrees is angle $N$?', '[]', '55', '180-125', 'Supplementary angles add up to $180^\circ$. So angle $N$ is $180 - 125 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M + N = 180, N = 180 - 125 = 55.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b6a36e9-9024-4e01-8914-78a0d13b30f7', 'NC26.7.SGMR.3', 1, 'choice', 'Supplementary angles: find the missing angle', 'What is the measure, in degrees, of the supplement of a $73^\circ$ angle?', '["107","17","253","287"]', '107', '180-73', 'The supplement is the angle that adds with $73^\circ$ to make $180^\circ$: $180 - 73 = 107$. The choice 17 is $90 - 73$ (the complement), 253 is $180 + 73$, and 287 is $360 - 73$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 73 = 107.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
