INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f6ae1db-45de-4add-8040-c9d40a10cd60', 'NC26.7.SGMR.3', 1, 'numeric', 'Supplementary angles: find the missing angle', 'A straight road meets a side street. The side street makes a $65^\circ$ angle with one side of the road. What angle does it make with the other side of the road, in degrees?', '[]', '115', '180-65', 'The two angles are next to each other along the straight road, so they add up to $180^\circ$. The other angle is $180 - 65 = 115$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"115","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The two angles on either side of the street lie on the straight road, so they are supplementary: 180 - 65 = 115.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53d4a5ef-e1c9-47f8-9a30-019515aa7876', 'NC26.7.SGMR.3', 1, 'choice', 'Supplementary angles: find the missing angle', 'Two supplementary angles sit next to each other and share a side. What do they make together?', '["a right angle","a straight angle","a full turn","an acute angle"]', 'a straight angle', NULL, 'Supplementary angles add up to $180^\circ$. Two of them side by side make a straight angle, which looks like a straight line.', 'checked', '{"lint":[],"solve":{"answer":"a straight angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent supplementary angles (a linear pair) sum to 180 and their outer sides form a straight line: a straight angle.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
