INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11b8d39f-1475-4381-9e16-43322307442a', 'NC26.7.SGMR.3', 1, 'numeric', 'Vertical angles: find the measure', 'Angle 1 and angle 3 are vertical angles. Angle 1 measures $48^\circ$. How many degrees is angle 3?', '[]', '48', '48', 'Vertical angles are across from each other where two lines cross, and they have equal measures. Angle 3 is $48^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are equal: 48.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('836195fa-cffb-4806-8026-b91881f4bf98', 'NC26.7.SGMR.3', 1, 'choice', 'Vertical angles: find the measure', 'Two lines cross. Which statement is always true about a pair of vertical angles?', '["They have equal measures to each other.","Their measures add up to $180^\\circ$.","Their measures add up to $90^\\circ$.","One is twice as large as the other."]', 'They have equal measures to each other.', NULL, 'Vertical angles are the angles directly across from each other at a crossing. They always have equal measures.', 'checked', '{"lint":[],"solve":{"answer":"They have equal measures to each other.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are always equal. Summing to 180 is true of adjacent angles; 90 only when perpendicular-related; not double.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f08f3f3-74e6-4475-a239-7612e5a39e49', 'NC26.7.SGMR.3', 1, 'numeric', 'Vertical angles: find the measure', 'Two straight sticks cross to make an X. One angle at the crossing is $110^\circ$. What is the measure, in degrees, of the angle directly opposite it?', '[]', '110', '110', 'The angle directly opposite is its vertical angle. Vertical angles are equal, so it is $110^\circ$ too.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The opposite angle is the vertical angle, equal: 110.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88796847-f604-4d7a-aa03-42a649381300', 'NC26.7.SGMR.3', 1, 'choice', 'Vertical angles: find the measure', 'Two lines cross, and the four angles around the crossing are numbered 1, 2, 3 and 4 in order. Which pair of angles are vertical angles?', '["angle 1 and angle 2","angle 2 and angle 3","angle 1 and angle 3","angle 3 and angle 4"]', 'angle 1 and angle 3', NULL, 'Vertical angles are across from each other, not next to each other. Going around in order, angle 1 is across from angle 3 (and angle 2 is across from angle 4). The other pairs are next to each other.', 'checked', '{"lint":[],"solve":{"answer":"angle 1 and angle 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numbered in order around the crossing, angles 1 and 3 are opposite (as are 2 and 4); consecutive pairs are adjacent. Only 1 and 3 is offered.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1b2cf3b-d1fc-4bec-a532-c77f187c4082', 'NC26.7.SGMR.3', 1, 'choice', 'Adjacent angles along a straight line (sum 180)', 'Two angles sit side by side along a straight line. One measures $145^\circ$. What is the measure, in degrees, of the other?', '["35","55","215","145"]', '35', '180-145', 'Angles along a straight line add up to $180^\circ$: $180 - 145 = 35$. The choice 55 is $145 - 90$, 215 is $360 - 145$, and 145 repeats the given angle.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles side by side on a straight line sum to 180: 180 - 145 = 35.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c9811ff-4422-4150-823c-d2f20cf694fd', 'NC26.7.SGMR.3', 1, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'A ray splits a straight angle into two angles. One of them is a right angle. What is the measure of the other angle in degrees?', '[]', '90', '180-90', 'A straight angle is $180^\circ$ and a right angle is $90^\circ$, so the other angle is $180 - 90 = 90$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 90 = 90.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
