INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69e9e4f9-d6e1-496e-93ff-76adbfa923dc', 'NC26.7.SGMR.3', 1, 'choice', 'Adjacent angles along a straight line (sum 180)', 'Angle $ABC$ is a straight angle. Ray $BD$ splits it into angle $ABD$ and angle $DBC$. Angle $ABD$ measures $41^\circ$. What is the measure of angle $DBC$ in degrees?', '["49","319","41","139"]', '139', '180-41', 'A straight angle is $180^\circ$, so angle $DBC$ is $180 - 41 = 139$ degrees. The choice 49 is $90 - 41$, 319 is $360 - 41$, and 41 repeats the given angle.', 'checked', '{"lint":[],"solve":{"answer":"139","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABD + DBC = 180, DBC = 180 - 41 = 139.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
