INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fa33ec2-869d-417e-8ccb-e87b88e21265', 'NC26.7.SGMR.3', 1, 'numeric', 'Adjacent angles that make up a larger angle', 'Angle $AOB$ measures $30^\circ$ and the angle next to it, angle $BOC$, measures $45^\circ$. They share ray $OB$ and do not overlap. What is the measure of angle $AOC$ in degrees?', '[]', '75', '30+45', 'The two adjacent angles together make angle $AOC$, so $30 + 45 = 75$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent, non-overlapping: AOC = 30 + 45 = 75.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efa7cc4b-ba19-4979-9065-cc30ac44e791', 'NC26.7.SGMR.3', 1, 'choice', 'Adjacent angles that make up a larger angle', 'Angle $XYZ$ measures $120^\circ$. Ray $YW$ lies inside it and splits it into angle $XYW$ and angle $WYZ$. Angle $XYW$ measures $75^\circ$. What is the measure of angle $WYZ$ in degrees?', '["195","105","15","45"]', '45', '120-75', 'The two parts add up to the whole angle: $75 + WYZ = 120$, so angle $WYZ$ is $120 - 75 = 45$ degrees. The choice 195 adds, 105 is $180 - 75$, and 15 is $90 - 75$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120 - 75 = 45.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a91b5f11-9478-498d-9744-7e63d4bb3e18', 'NC26.7.SGMR.3', 1, 'choice', 'Name and compare angle relationships', 'Two angles measure $50^\circ$ and $130^\circ$. Which word describes this pair of angles?', '["supplementary","complementary","vertical","equal"]', 'supplementary', NULL, '$50 + 130 = 180$, so the angles are supplementary. They are not complementary (which would add to 90), and they are not vertical or equal because $50$ is not $130$.', 'checked', '{"lint":[],"solve":{"answer":"supplementary","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 + 130 = 180: supplementary. Not equal, not 90, and vertical angles would be equal.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d084058-a3e7-4342-ac7e-6658a2daff28', 'NC26.7.SGMR.3', 1, 'choice', 'Name and compare angle relationships', 'Which pair of angles always have equal measures?', '["supplementary angles","complementary angles","vertical angles","adjacent angles"]', 'vertical angles', NULL, 'Vertical angles, the angles across from each other where two lines cross, always have equal measures. Supplementary angles, complementary angles and adjacent angles are equal only in special cases.', 'checked', '{"lint":[],"solve":{"answer":"vertical angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are always equal; the others are equal only in special cases.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60a3a81c-4d46-46b0-833f-a7163c96e40e', 'NC26.7.SGMR.3', 1, 'choice', 'Name and compare angle relationships', 'Two angles share a vertex and one side, and they do not overlap. What are these angles called?', '["vertical angles","adjacent angles","complementary angles","supplementary angles"]', 'adjacent angles', NULL, 'Angles that share a vertex and a side and do not overlap are adjacent angles. Whether they are also complementary or supplementary depends on their measures, not on how they are placed.', 'checked', '{"lint":[],"solve":{"answer":"adjacent angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common vertex, common side, no overlap is the definition of adjacent angles.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6df2475-c186-4a10-8855-d27118c5d76b', 'NC26.7.SGMR.3', 1, 'numeric', 'Complementary angles with expressions (equation)', 'Two angles are complementary. One measures $(x + 20)^\circ$ and the other measures $50^\circ$. What is $x$?', '[]', '20', '90-50-20', 'Complementary angles add up to 90: $(x + 20) + 50 = 90$. So $x + 70 = 90$ and $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 20 + 50 = 90, x = 20.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f1b9cd9-2aaa-470d-b550-e09c61c5ad61', 'NC26.7.SGMR.3', 1, 'numeric', 'Supplementary angles and straight lines with expressions (equation)', 'Two angles sit side by side along a straight line. They measure $(x + 30)^\circ$ and $100^\circ$. What is $x$?', '[]', '50', '180-100-30', 'Angles along a straight line add up to 180: $(x + 30) + 100 = 180$. So $x + 130 = 180$ and $x = 50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 30 + 100 = 180, x = 50.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
