INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da27ef1b-ec37-4be2-ba5c-d9916a2a9fcf', 'NC26.7.SGMR.3', 2, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Two rays are drawn from a point on a straight line, making three angles along the line. The first angle is $25^\circ$. The second angle is $15^\circ$ more than the first angle. What is the measure of the third angle in degrees?', '[]', '115', '180-25-(25+15)', 'The second angle is $25 + 15 = 40$ degrees. The three angles add up to $180^\circ$, so the third angle is $180 - 25 - 40 = 115$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"115","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 25, second 25 + 15 = 40. Third = 180 - 65 = 115.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
