INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('babb47fc-b765-47ad-90e8-d83eb78229b0', 'NC26.7.SGMR.3', 2, 'choice', 'Adjacent angles along a straight line (sum 180)', 'Angles 1, 2 and 3 lie side by side along a straight line. Angle 1 is $52^\circ$ and angle 3 is $71^\circ$. What is the measure of angle 2 in degrees?', '["128","57","109","123"]', '57', '180-52-71', 'The three angles add up to $180^\circ$. So angle 2 is $180 - 52 - 71 = 57$ degrees. The choice 128 only subtracts 52, 109 only subtracts 71, and 123 adds the two known angles.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 52 - 71 = 57.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
