INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbb5c1f7-68f8-4c53-9958-1f6f2de7f18a', 'NC26.7.SGMR.3', 2, 'choice', 'Name and compare angle relationships', 'Lines $AB$ and $CD$ cross at point $O$, which lies between $A$ and $B$ and between $C$ and $D$. Which angle is vertical to angle $AOC$?', '["angle $COB$","angle $AOD$","angle $AOB$","angle $BOD$"]', 'angle $BOD$', NULL, 'Vertical angles are across from each other. Ray $OB$ is opposite ray $OA$, and ray $OD$ is opposite ray $OC$, so the angle across from angle $AOC$ is angle $BOD$. Angles $COB$ and $AOD$ are next to angle $AOC$, and angle $AOB$ is a straight angle.', 'checked', '{"lint":[],"solve":{"answer":"angle $BOD$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOC uses rays OA and OC; the opposite rays are OB and OD, so the vertical angle is BOD. AOB is a straight angle; COB and AOD are adjacent to AOC.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e939ddf2-3901-434f-a952-6c43a79d6f38', 'NC26.7.SGMR.3', 2, 'choice', 'Name and compare angle relationships', 'Angle $P$ and angle $Q$ are supplementary. Angle $Q$ and angle $R$ are supplementary. Which statement must be true?', '["Angle $P$ and angle $R$ have equal measures.","Angle $P$ and angle $R$ are supplementary.","Angle $P$ and angle $R$ are complementary.","Angle $P$ is larger than angle $R$."]', 'Angle $P$ and angle $R$ have equal measures.', NULL, 'Angle $P = 180 - Q$ and angle $R = 180 - Q$, so angles $P$ and $R$ are equal. They add up to $2(180 - Q)$, which need not be 180 or 90, and neither one has to be larger.', 'checked', '{"lint":[],"solve":{"answer":"Angle $P$ and angle $R$ have equal measures.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P = 180 - Q and R = 180 - Q, so P = R. Complementary/supplementary would need specific values; P larger is false.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fc014dd-af40-49a8-85dc-d49a4b8ba8e6', 'NC26.7.SGMR.3', 2, 'choice', 'Name and compare angle relationships', 'Which of these could be the measures of a pair of vertical angles?', '["$85^\\circ$ and $95^\\circ$","$85^\\circ$ and $5^\\circ$","$85^\\circ$ and $275^\\circ$","$85^\\circ$ and $85^\\circ$"]', '$85^\circ$ and $85^\circ$', NULL, 'Vertical angles are equal, so only $85^\circ$ and $85^\circ$ can be a pair. The pair $85^\circ$ and $95^\circ$ adds to 180, and $85^\circ$ and $5^\circ$ adds to 90.', 'checked', '{"lint":[],"solve":{"answer":"$85^\\circ$ and $85^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are equal: only 85 and 85.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58ae7b4e-98ca-4f21-ac66-fbce05603875', 'NC26.7.SGMR.3', 2, 'numeric', 'Complementary angles with expressions (equation)', 'Two complementary angles measure $(4x + 10)^\circ$ and $(2x + 8)^\circ$. What is the measure of the smaller angle in degrees?', '[]', '32', '2*12+8', 'The angles add up to 90: $(4x + 10) + (2x + 8) = 90$, so $6x + 18 = 90$, $6x = 72$ and $x = 12$. The angles are $4 \times 12 + 10 = 58$ and $2 \times 12 + 8 = 32$ degrees. The smaller is 32.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 18 = 90, x = 12. Angles 58 and 32. Smaller = 32.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4352318e-2105-4afd-bf75-cf8cc6f42f91', 'NC26.7.SGMR.3', 2, 'choice', 'Complementary angles with expressions (equation)', 'Angle $A$ measures $(2x + 5)^\circ$ and its complement, angle $B$, measures $(x - 5)^\circ$. What is the measure of angle $A$ in degrees?', '["25","65","30","60"]', '65', '2*30+5', 'The angles add up to 90: $(2x + 5) + (x - 5) = 90$, so $3x = 90$ and $x = 30$. Angle $A$ is $2 \times 30 + 5 = 65$ degrees. The choice 25 is angle $B$, 30 is $x$, and 60 is $2x$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x + 5) + (x - 5) = 90, 3x = 90, x = 30. A = 65, B = 25.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('272d4b09-32d4-4f2e-a6a4-d98dfbc48661', 'NC26.7.SGMR.3', 2, 'numeric', 'Complementary angles with expressions (equation)', 'A right angle is split into three adjacent angles that measure $x^\circ$, $(x + 15)^\circ$ and $(2x + 15)^\circ$. What is the measure of the largest of the three angles in degrees?', '[]', '45', '2*15+15', 'The three angles add up to 90: $x + (x + 15) + (2x + 15) = 90$, so $4x + 30 = 90$, $4x = 60$ and $x = 15$. The angles are 15, 30 and 45 degrees. The largest is 45.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x + 15 + 2x + 15 = 90, 4x + 30 = 90, x = 15. Angles 15, 30, 45. Largest 45.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9db0865-5546-4271-bfe3-f2b5dcabc6a1', 'NC26.7.SGMR.3', 2, 'numeric', 'Supplementary angles and straight lines with expressions (equation)', 'Two supplementary angles measure $(7x - 5)^\circ$ and $(3x + 15)^\circ$. What is the measure of the larger angle in degrees?', '[]', '114', '7*17-5', 'The angles add up to 180: $(7x - 5) + (3x + 15) = 180$, so $10x + 10 = 180$, $10x = 170$ and $x = 17$. The angles are $7 \times 17 - 5 = 114$ and $3 \times 17 + 15 = 66$ degrees. The larger is 114.', 'checked', '{"lint":[],"solve":{"answer":"114","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10x + 10 = 180, x = 17. Angles 114 and 66. Larger 114.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e3f302a-0926-42ed-ba5d-4a80405fc959', 'NC26.7.SGMR.3', 2, 'choice', 'Supplementary angles and straight lines with expressions (equation)', 'Points $A$, $B$ and $C$ lie on a straight line with $B$ between $A$ and $C$, and $D$ is a point off the line. Angle $ABD$ measures $(4x + 10)^\circ$ and angle $DBC$ measures $(2x + 20)^\circ$. What is $x$?', '["25","10","30","55"]', '25', '(180-30)/6', 'The two angles make a straight angle, so $(4x + 10) + (2x + 20) = 180$. Then $6x + 30 = 180$, $6x = 150$ and $x = 25$. The choice 10 uses 90 instead of 180, 30 ignores the added numbers, and 55 uses 360.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"ABD and DBC form a linear pair: 6x + 30 = 180, x = 25 (angles 110 and 70).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01dcc5ef-2ec9-4121-b9eb-ee4091c109a6', 'NC26.7.SGMR.3', 2, 'numeric', 'Supplementary angles and straight lines with expressions (equation)', 'An angle measures $(2x + 6)^\circ$ and its supplement measures $(4x - 18)^\circ$. What is the measure of the angle in degrees?', '[]', '70', '2*32+6', 'The angles add up to 180: $(2x + 6) + (4x - 18) = 180$, so $6x - 12 = 180$, $6x = 192$ and $x = 32$. The angle is $2 \times 32 + 6 = 70$ degrees (and its supplement is 110).', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 12 = 180, x = 32. Angle = 2(32) + 6 = 70 (supplement 110).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
