INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc65c5b1-29dc-430f-9bda-c09fef20918b', 'NC26.7.SGMR.3', 2, 'choice', 'Vertical angles with expressions (equation)', 'Two lines cross. The angles across from each other measure $(x + 40)^\circ$ and $(3x - 10)^\circ$. What is the value of $x$?', '["25","15","50","20"]', '25', '(40+10)/2', 'Vertical angles are equal: $x + 40 = 3x - 10$, so $50 = 2x$ and $x = 25$. The choice 15 comes from a sign error, 50 forgets to divide by 2, and 20 ignores the $-10$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across = vertical, equal: x + 40 = 3x - 10, 2x = 50, x = 25 (angles 65).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
