INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26258bf5-a7d3-40e9-b957-55ee0a5ccc40', 'NC26.7.SGMR.3', 2, 'choice', 'Choose the equation for an unknown angle', 'An angle measures $x^\circ$. Its supplement measures $20^\circ$ more than the angle. Which equation can be used to find $x$?', '["$x + (x + 20) = 90$","$x + 20 = 180$","$x + (x - 20) = 180$","$x + (x + 20) = 180$"]', '$x + (x + 20) = 180$', NULL, 'The supplement measures $x + 20$, and an angle and its supplement add up to 180. So $x + (x + 20) = 180$. The equation with 90 is for a complement, and $x + (x - 20) = 180$ subtracts 20 instead of adding.', 'checked', '{"lint":[],"solve":{"answer":"$x + (x + 20) = 180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Supplement = x + 20, and angle + supplement = 180: x + (x + 20) = 180.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1277938b-bbd7-485a-a746-09462d5f22c5', 'NC26.7.SGMR.3', 2, 'choice', 'Choose the equation for an unknown angle', 'The complement of an angle is three times the angle. If the angle measures $x^\circ$, which equation can be used to find $x$?', '["$x + 3x = 180$","$3x = 90$","$x + 3x = 90$","$x + 3 = 90$"]', '$x + 3x = 90$', NULL, 'The complement measures $3x$, and an angle and its complement add up to 90. So $x + 3x = 90$.', 'checked', '{"lint":[],"solve":{"answer":"$x + 3x = 90$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement = 3x, angle + complement = 90: x + 3x = 90 (x = 22.5).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6d9e737-0c2e-48e9-be3c-3ed6191989ab', 'NC26.7.SGMR.3', 2, 'numeric', 'Intersecting lines: several angles, several steps', 'Two lines cross and form four angles. One angle measures $138^\circ$. What is the sum of the measures of the other three angles in degrees?', '[]', '222', '360-138', 'The four angles around a crossing add up to $360^\circ$, so the other three add up to $360 - 138 = 222$ degrees. (They are $138$, $42$ and $42$.)', 'checked', '{"lint":[],"solve":{"answer":"222","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total around point 360: 360 - 138 = 222 (138 + 42 + 42).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4aeb6c5-27d5-43d7-abc0-e4559fc0f620', 'NC26.7.SGMR.3', 2, 'numeric', 'Intersecting lines: several angles, several steps', 'Lines $AB$ and $CD$ cross at point $O$, which lies between $A$ and $B$ and between $C$ and $D$. Angle $AOC$ measures $64^\circ$. What is the measure of angle $AOD$ minus the measure of angle $BOD$, in degrees?', '[]', '52', '(180-64)-64', 'Angle $AOD$ is next to angle $AOC$, so it is $180 - 64 = 116$ degrees. Angle $BOD$ is vertical to angle $AOC$, so it is $64$ degrees. The difference is $116 - 64 = 52$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOD is adjacent to AOC: 180 - 64 = 116. BOD is vertical to AOC: 64. 116 - 64 = 52.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f169890-39bf-467b-a6fc-df749c970e90', 'NC26.7.SGMR.3', 2, 'choice', 'Intersecting lines: several angles, several steps', 'Two lines cross and one angle measures $70^\circ$. Going around the crossing point in order, which list gives the measures of the four angles?', '["$70^\\circ$, $70^\\circ$, $110^\\circ$, $110^\\circ$","$70^\\circ$, $110^\\circ$, $110^\\circ$, $70^\\circ$","$70^\\circ$, $110^\\circ$, $70^\\circ$, $110^\\circ$","$70^\\circ$, $20^\\circ$, $70^\\circ$, $20^\\circ$"]', '$70^\circ$, $110^\circ$, $70^\circ$, $110^\circ$', NULL, 'Angles next to each other add up to 180 and angles across from each other are equal. So the order around the point is $70, 110, 70, 110$. The other lists put two equal angles next to each other, which would not make a straight line, or use the complement 20.', 'checked', '{"lint":[],"solve":{"answer":"$70^\\circ$, $110^\\circ$, $70^\\circ$, $110^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Opposite angles equal, neighbours sum to 180: in order 70, 110, 70, 110. The list 70,110,110,70 would put two 110s and two 70s next to each other.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8fa9f6b-7fed-4450-ba89-2b531901f67b', 'NC26.7.SGMR.3', 2, 'choice', 'An angle compared with its complement or supplement', 'An angle is twice as large as its complement. What is the measure of the angle in degrees?', '["30","45","120","60"]', '60', '180/3', 'Let the angle be $x$. Its complement is $90 - x$, so $x = 2(90 - x)$. Then $3x = 180$ and $x = 60$. (Its complement is 30.) The choice 30 is the complement, 45 is the angle if they were equal, and 120 is twice the answer.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 2(90 - x), 3x = 180, x = 60 (complement 30).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c53c4b3d-00c6-4790-a42b-09cf55236cb8', 'NC26.7.SGMR.3', 2, 'numeric', 'An angle compared with its complement or supplement', 'An angle is $40^\circ$ more than its complement. What is the measure of the angle in degrees?', '[]', '65', '(90+40)/2', 'Let the angle be $x$. Its complement is $90 - x$, so $x = (90 - x) + 40$. Then $2x = 130$ and $x = 65$. (Its complement is 25, and $65 - 25 = 40$.)', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = (90 - x) + 40, 2x = 130, x = 65 (complement 25).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e33d8aaf-1383-4e03-9149-300c7399dec9', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles in a ratio', 'Two lines cross. One of the angles formed is 4 times as large as an angle next to it. What is the measure of the smaller angle in degrees?', '[]', '36', '180/(1+4)', 'Two angles next to each other where lines cross add to $180^\circ$. If the smaller angle is $x$, the larger is $4x$, so $x + 4x = 180$. Then $5x = 180$ and $x = 36$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles at a crossing are supplementary: x + 4x = 180, x = 36 (other is 144).","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a4fc3cf-e92a-4728-939c-11fd0eead808', 'NC26.7.SGMR.3', 3, 'numeric', 'Supplement and complement together', 'The supplement of an angle is $20^\circ$ more than twice the angle''s complement. What is the measure of the angle in degrees?', '[]', '20', '(2*90+20)-180', 'Let the angle be $x$. Its supplement is $180 - x$ and its complement is $90 - x$. So $180 - x = 2(90 - x) + 20 = 200 - 2x$. Adding $2x$ to both sides: $180 + x = 200$, so $x = 20$. Check: supplement 160, complement 70, and $2 \times 70 + 20 = 160$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - x = 2(90 - x) + 20 = 200 - 2x, so x = 20. Check: supplement 160, complement 70, 2 x 70 + 20 = 160.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5162135-d0e0-4b37-a9c8-a0d8cd42ee54', 'NC26.7.SGMR.3', 3, 'numeric', 'Unknown angle at an intersection', 'Lines $AB$ and $CD$ cross at point $O$. Angle $AOC$ measures $(3x + 10)^\circ$ and angle $COB$ measures $(2x + 20)^\circ$. What is the measure of angle $AOD$ in degrees?', '[]', '80', '180-(3*((180-30)/5)+10)', 'Angles $AOC$ and $COB$ are next to each other along the straight line $AB$, so they add to 180: $3x + 10 + 2x + 20 = 180$. Then $5x = 150$ and $x = 30$, so angle $AOC$ is $3 \times 30 + 10 = 100$ degrees. Angle $AOD$ is next to angle $AOC$ along the straight line $CD$, so it measures $180 - 100 = 80$ degrees. (It is also the vertical angle of $COB$, which is $2 \times 30 + 20 = 80$.)', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AOC and COB form straight angle AOB: 3x + 10 + 2x + 20 = 180, x = 30. AOC = 100, COB = 80. AOD is vertical to COB (OA opposite OB, OD opposite OC), so AOD = 80 (also 180 - AOC).","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4069659-4c05-4e62-b3e0-60fd8e1db9f9', 'NC26.7.SGMR.3', 3, 'numeric', 'Complementary angles: find the missing angle', 'Angle $P$ is complementary to angle $Q$, and angle $Q$ is complementary to angle $R$. Angle $P$ measures $31^\circ$. What is the measure of angle $R$ in degrees?', '[]', '31', '90-(90-31)', 'Angle $Q$ is $90 - 31 = 59$ degrees. Angle $R$ is $90 - 59 = 31$ degrees. Two angles that are complementary to the same angle have equal measures.', 'checked', '{"lint":[],"solve":{"answer":"31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P + Q = 90 so Q = 59. Q + R = 90 so R = 31 (R equals P).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b47e75b9-c3ea-49ae-8372-4fdbb646d0cf', 'NC26.7.SGMR.3', 3, 'numeric', 'Complementary angles: find the missing angle', 'An angle measures $64^\circ$. Find its complement. Then find the supplement of that complement. What is the final measure in degrees?', '[]', '154', '180-(90-64)', 'The complement of $64^\circ$ is $90 - 64 = 26$ degrees. The supplement of $26^\circ$ is $180 - 26 = 154$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"154","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Complement of 64 = 26. Supplement of 26 = 180 - 26 = 154.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d774a70-4d99-46a9-9fb8-268118339743', 'NC26.7.SGMR.3', 3, 'numeric', 'Supplementary angles: find the missing angle', 'An angle measures $116^\circ$. A ray splits its supplement into two equal angles. What is the measure of each of the two equal angles in degrees?', '[]', '32', '(180-116)/2', 'The supplement of $116^\circ$ is $180 - 116 = 64$ degrees. Splitting it into two equal angles gives $64 \div 2 = 32$ degrees each.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Supplement = 180 - 116 = 64. Split in two equal parts: 32.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('205a6418-5b66-494c-8052-c36c680ddbe6', 'NC26.7.SGMR.3', 3, 'choice', 'Supplementary angles: find the missing angle', 'Angle $A$ and angle $B$ are supplementary, and angle $A$ is an acute angle. Which statement must be true about angle $B$?', '["Angle $B$ is an acute angle.","Angle $B$ is a right angle.","Angle $B$ is smaller than angle $A$.","Angle $B$ is an obtuse angle."]', 'Angle $B$ is an obtuse angle.', NULL, 'Angle $A$ is less than $90^\circ$, so angle $B = 180 - A$ is greater than $90^\circ$ and less than $180^\circ$. That makes it obtuse. It is larger than $A$, and it is a right angle only if $A$ is $90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Angle $B$ is an obtuse angle.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 < A < 90, B = 180 - A, so 90 < B < 180: B is obtuse. B is larger than A, not smaller; not acute; not right.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1901c4ee-ce31-4b2b-9b15-119524c42204', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles: find the measure', 'Two lines cross. One pair of vertical angles has a sum of $146^\circ$. What is the measure, in degrees, of each of the other two angles?', '["73","107","34","214"]', '107', '180-146/2', 'Each angle of the first pair is $146 \div 2 = 73$ degrees. An angle next to it is $180 - 73 = 107$ degrees, and the other pair are vertical angles with the same measure. The choice 73 is one of the first pair, 34 is $180 - 146$, and 214 is $360 - 146$.', 'checked', '{"lint":[],"solve":{"answer":"107","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical pair equal, each 146/2 = 73. Each of the other two = 180 - 73 = 107.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b657eb9-3e18-4170-afb1-2b84de80201a', 'NC26.7.SGMR.3', 3, 'choice', 'Vertical angles: find the measure', 'Two lines cross. One pair of vertical angles measures $d^\circ$ in all (the two angles together). Which expression gives the measure of each of the other two angles?', '["$180 - d$","$\\frac{d}{2}$","$180 - \\frac{d}{2}$","$360 - d$"]', '$180 - \frac{d}{2}$', NULL, 'Each angle of the first pair measures $\frac{d}{2}$. An angle next to it is $180 - \frac{d}{2}$, and the other pair are vertical angles with that measure. The expression $360 - d$ is the total of the other two angles, not each one.', 'checked', '{"lint":[],"solve":{"answer":"$180 - \\frac{d}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each of the pair = d/2. Each other angle = 180 - d/2 (equivalently (360 - d)/2).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97a3a124-3c6b-4b9d-8290-70697a916677', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Four angles lie side by side along a straight line. Each angle is $10^\circ$ larger than the angle before it. What is the measure of the largest angle in degrees?', '[]', '60', '(180-60)/4+30', 'Call the smallest angle $a$. The angles are $a$, $a + 10$, $a + 20$ and $a + 30$, and they add up to $180$. So $4a + 60 = 180$, $4a = 120$ and $a = 30$. The largest angle is $30 + 30 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + (a+10) + (a+20) + (a+30) = 180, 4a + 60 = 180, a = 30. Largest = 60.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61888406-14be-44d2-b943-7904ef4c1cfb', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles along a straight line (sum 180)', 'Rays split a straight angle into three angles. The second angle is twice the first, and the third angle is three times the first. What is the measure of the third angle in degrees?', '[]', '90', '180/6*3', 'If the first angle is $x$, the angles are $x$, $2x$ and $3x$, which add up to $6x = 180$. So $x = 30$, and the third angle is $3 \times 30 = 90$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 180, x = 30. Third = 3x = 90.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65b9bd85-3d19-4b89-89c5-b7330c38e138', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles that make up a larger angle', 'Angle $AOD$ measures $126^\circ$. Rays $OB$ and $OC$ lie inside it, in that order from $OA$. Angle $AOB$ measures $30^\circ$, and angle $BOC$ is $12^\circ$ larger than angle $AOB$. What is the measure of angle $COD$ in degrees?', '[]', '54', '126-30-(30+12)', 'Angle $BOC$ is $30 + 12 = 42$ degrees. The three angles add up to angle $AOD$, so angle $COD$ is $126 - 30 - 42 = 54$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"BOC = 30 + 12 = 42. COD = 126 - 30 - 42 = 54.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5947aaf9-41a4-4177-85f2-6d76c21b8d60', 'NC26.7.SGMR.3', 3, 'numeric', 'Adjacent angles that make up a larger angle', 'Angle $AOC$ measures $84^\circ$ and ray $OB$ lies inside it. Angle $AOB$ is $12^\circ$ more than twice angle $BOC$. What is the measure of angle $AOB$ in degrees?', '[]', '60', '(84-12)/3*2+12', 'Let angle $BOC$ be $y$. Then angle $AOB$ is $2y + 12$, and $y + 2y + 12 = 84$. So $3y = 72$ and $y = 24$. Angle $AOB$ is $2 \times 24 + 12 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Let BOC = y, AOB = 2y + 12. 3y + 12 = 84, y = 24. AOB = 60.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c5b61d4-bd01-4638-8402-6878af07a5e3', 'NC26.7.SGMR.3', 3, 'choice', 'Name and compare angle relationships', 'Two lines cross and make four angles. Which statement is always true?', '["All four angles are equal.","Two angles that are next to each other are equal.","Two angles that are next to each other add up to $180^\\circ$.","Two angles that are across from each other add up to $180^\\circ$."]', 'Two angles that are next to each other add up to $180^\circ$.', NULL, 'Angles next to each other along one of the lines make a straight angle, so they add up to $180^\circ$. The four angles are all equal only when the lines are perpendicular, and angles across from each other are equal (so they add up to 180 only if each is 90).', 'checked', '{"lint":[],"solve":{"answer":"Two angles that are next to each other add up to $180^\\circ$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles at a crossing form a linear pair: always 180. Opposite angles sum to 180 only if each is 90; all equal only when perpendicular; adjacent equal only when perpendicular.","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca1760e1-c998-43c6-ad5d-b6f2304f1c2e', 'NC26.7.SGMR.3', 3, 'choice', 'Name and compare angle relationships', 'Which of these is impossible?', '["two complementary angles that are both obtuse","two supplementary angles that are both right angles","two vertical angles that are both obtuse","two complementary angles that are each $45^\\circ$"]', 'two complementary angles that are both obtuse', NULL, 'Obtuse angles are greater than $90^\circ$, so two of them add up to more than 180 and cannot be complementary (which needs a sum of 90). Two right angles are supplementary, vertical angles of $120^\circ$ are both obtuse, and $45 + 45 = 90$.', 'checked', '{"lint":[],"solve":{"answer":"two complementary angles that are both obtuse","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two obtuse angles sum to more than 180, so cannot sum to 90: impossible. 90+90 = 180 possible; 45+45 = 90 possible; vertical angles both obtuse possible (e.g., 120 and 120).","run_id":"claude-code","at":"2026-10-17T20:25:00.084Z"}}', 'ai', NULL, NULL)
