INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc85ac34-7ee8-4bd6-956f-77dbdede3ccb', 'NC26.7.RD.1', 2, 'choice', 'Counting the outcomes of a compound event', 'A code has 2 letters chosen from A, B, C, D and E, followed by 1 digit from 0 to 9. A letter may be used twice. How many different codes are possible?', '["100","250","20","50"]', '250', '5*5*10', 'There are 5 choices for the first letter, 5 for the second and 10 for the digit. The number of codes is $5 \times 5 \times 10 = 250$. (20 adds the choices, and 50 uses only one letter.)', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 5 letters (repetition allowed) x 10 digits = 250.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7e48322-c534-4a26-832f-93526033fe28', 'NC26.7.RD.1', 2, 'choice', 'Counting the outcomes of a compound event', 'A game spinner has 3 equal sections: red, yellow and blue. It is spun 3 times in a row, and the colors are recorded in order. How many outcomes are in the sample space?', '["9","81","27","6"]', '27', '3*3*3', 'Each spin has 3 possible colors, so the number of outcomes is $3 \times 3 \times 3 = 27$. (9 uses only two spins, 81 uses four spins, and 6 is $3 + 3$.)', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 3 x 3 = 27 ordered outcomes.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f03a9fcc-0a12-4183-8dd8-3cff2f493d7e', 'NC26.7.RD.1', 2, 'numeric', 'Listing a sample space', 'Three friends each toss a fair coin once, and the three results are recorded. What is the probability that at least two of the coins land heads? Write your answer as a fraction.', '[]', '1/2', '4/8', 'List the 8 equally likely outcomes: HHH, HHT, HTH, HTT, THH, THT, TTH, TTT. Two or more heads happen in HHH, HHT, HTH and THH, which is 4 outcomes. The probability is $\frac{4}{8} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 outcomes. At least 2 heads: HHT, HTH, THH, HHH = 4. 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
