INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb3ef483-5030-47fe-b278-3fc118523016', 'NC26.7.RD.1', 2, 'numeric', 'Using a table of outcomes', 'Two fair six-sided dice are rolled. What is the probability that the two numbers differ by exactly 3? Write your answer as a fraction.', '[]', '1/6', '6/36', 'The pairs that differ by 3 are (1, 4), (2, 5), (3, 6), (4, 1), (5, 2) and (6, 3), which is 6 of the 36 outcomes. The probability is $\frac{6}{36} = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"1/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differ by 3: (1,4), (2,5), (3,6) and reversed = 6 of 36 = 1/6.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c18310d0-512f-4e3b-b773-54899335a364', 'NC26.7.RD.1', 2, 'numeric', 'Using a tree diagram', 'A game has two rounds. Zack wins each round with probability $\frac{3}{4}$, and the rounds do not affect each other. A tree diagram shows win or lose for each round. What is the probability that he wins both rounds? Write your answer as a fraction.', '[]', '9/16', '3/4*3/4', 'On the path win, then win, multiply the branch probabilities: $\frac{3}{4} \times \frac{3}{4} = \frac{9}{16}$.', 'checked', '{"lint":[],"solve":{"answer":"9/16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4 x 3/4 = 9/16.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ac733786-a69c-4acb-82f9-9a05350e8da5', 'NC26.7.RD.1', 2, 'choice', 'Using a tree diagram', 'Ray makes a tree diagram for flipping a fair coin three times. How many of its complete paths have exactly two heads?', '["3","2","4","6"]', '3', '3', 'The paths with exactly two heads are HHT, HTH and THH, so there are 3. (2 forgets that the tail can come in different places.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 paths; exactly two heads: HHT, HTH, THH = 3.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8b9b847-65f4-41fd-a79b-4773e81496e9', 'NC26.7.RD.1', 2, 'numeric', 'Compound events with replacement', 'Lena has a jar with 4 red, 3 green and 3 yellow buttons. She picks one button at random, puts it back, and then picks a second button at random. What is the probability that the first button is red and the second button is green? Write your answer as a fraction.', '[]', '3/25', '4/10*3/10', 'Because the first button is put back, there are 10 buttons both times. The probability is $\frac{4}{10} \times \frac{3}{10} = \frac{12}{100} = \frac{3}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"3/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 buttons, with replacement: 4/10 x 3/10 = 12/100 = 3/25.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5867a4e9-93cd-4c03-a7cf-71093351f543', 'NC26.7.RD.1', 2, 'choice', 'Compound events with replacement', 'A box has 10 cards numbered 1 to 10. A card is drawn and put back, and then a second card is drawn. What is the probability that the first card is even and the second card is greater than 7?', '["4/5","3/10","1/20","3/20"]', '3/20', '5/10*3/10', 'The first card is even with probability $\frac{5}{10}$. The second card is 8, 9 or 10 with probability $\frac{3}{10}$. Multiply: $\frac{5}{10} \times \frac{3}{10} = \frac{15}{100} = \frac{3}{20}$. (4/5 adds the probabilities instead of multiplying.)', 'checked', '{"lint":[],"solve":{"answer":"3/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(even) = 5/10; P(>7) = 3/10 (8, 9, 10). 5/10 x 3/10 = 15/100 = 3/20.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02e394d7-6722-4a51-ae01-25a329e50829', 'NC26.7.RD.1', 2, 'numeric', 'Compound events without replacement', 'A basket holds 4 apples and 2 pears. Pia takes two pieces of fruit, one after the other, without looking and without putting the first one back. What is the probability that both are pears? Write your answer as a fraction.', '[]', '1/15', '2/6*1/5', 'The first piece is a pear with probability $\frac{2}{6}$. Then 1 pear is left among 5 pieces, so the second is a pear with probability $\frac{1}{5}$. Both pears: $\frac{2}{6} \times \frac{1}{5} = \frac{2}{30} = \frac{1}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"1/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 fruits, 2 pears: 2/6 x 1/5 = 2/30 = 1/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e785f14d-2997-4e32-874f-86774c23079b', 'NC26.7.RD.1', 2, 'choice', 'Compound events without replacement', 'A drawer holds 4 black socks and 3 white socks. Two socks are pulled out one after the other without looking, and the first sock is not put back. What is the probability that both socks are black?', '["16/49","2/7","1/7","12/49"]', '2/7', '4/7*3/6', 'The first sock is black with probability $\frac{4}{7}$. Then 3 black socks remain among 6, so the second is black with probability $\frac{3}{6}$. Both black: $\frac{4}{7} \times \frac{3}{6} = \frac{12}{42} = \frac{2}{7}$. (16/49 puts the first sock back, and 12/49 keeps all 7 socks for the second draw.)', 'checked', '{"lint":[],"solve":{"answer":"2/7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/7 x 3/6 = 12/42 = 2/7.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('adb4af64-ac13-4b79-af65-9a1a5d5e7930', 'NC26.7.RD.1', 2, 'numeric', 'Compound events without replacement', 'A class has 6 girls and 4 boys. The teacher picks two different students at random, one after the other, to be helpers. What is the probability that both helpers are boys? Write your answer as a fraction.', '[]', '2/15', '4/10*3/9', 'The first helper is a boy with probability $\frac{4}{10}$. Then 3 boys remain among 9 students, so the second is a boy with probability $\frac{3}{9}$. Both boys: $\frac{4}{10} \times \frac{3}{9} = \frac{12}{90} = \frac{2}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"2/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/10 x 3/9 = 12/90 = 2/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6c9c12a-92d4-4ec9-9f4e-b1f708134a45', 'NC26.7.RD.1', 2, 'numeric', 'Designing a simulation', 'A fair 12-sided die has faces numbered 1 to 12. To simulate an event with probability $\frac{1}{4}$, how many of the faces should stand for the event happening?', '[]', '3', '12/4', 'Each face has a $\frac{1}{12}$ chance. To get $\frac{1}{4}$, use $\frac{1}{4} \times 12 = 3$ faces, since $\frac{3}{12} = \frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 x 12 = 3 faces.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f47fa7a1-b9cd-4258-ac58-b3a8e056b842', 'NC26.7.RD.1', 2, 'choice', 'Designing a simulation', 'A cereal box contains one of 4 different toys, and each toy is equally likely. Which of these is a fair way to simulate buying one box?', '["Roll a fair six-sided die and use the number rolled as the toy","Flip a fair coin 3 times and use the number of heads plus 1 as the toy","Flip a fair coin once; heads is toy 1 and tails is toy 2","Spin a spinner with 4 equal sections, one for each toy"]', 'Spin a spinner with 4 equal sections, one for each toy', NULL, 'A spinner with 4 equal sections makes each of the 4 toys equally likely. A die has 6 results, not 4. The number of heads in 3 flips is not equally likely (1 head is three times as likely as 0 heads). A single coin can only model 2 toys.', 'checked', '{"lint":[],"solve":{"answer":"Spin a spinner with 4 equal sections, one for each toy","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Coin once gives only 2 toys; die has 6 outcomes (5, 6 not toys); heads+1 over 3 flips gives 1-4 with probabilities 1/8, 3/8, 3/8, 1/8 (unequal). A 4-section equal spinner gives each toy 1/4.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f45ccdc-76a7-4a07-80a0-02031694735a', 'NC26.7.RD.1', 2, 'numeric', 'Experimental probability from trials and simulations', 'Dee simulated a quiz with 3 true-or-false questions that she guessed on. In each trial she flipped a coin three times, and each H meant a correct guess. Her six trials gave HHT, THT, HHH, TTH, HHT and THH. Based on these trials, what is the experimental probability of getting at least 2 questions correct? Write your answer as a fraction.', '[]', '2/3', '4/6', 'Count the trials with at least 2 H''s: HHT, HHH, HHT and THH. That is 4 of the 6 trials, so the experimental probability is $\frac{4}{6} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"2/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heads counts: HHT 2, THT 1, HHH 3, TTH 1, HHT 2, THH 2. At least 2 in 4 of 6 trials: 4/6 = 2/3.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2541351d-9494-4f66-87c0-17ff28a5fe7e', 'NC26.7.RD.1', 2, 'choice', 'Experimental probability from trials and simulations', 'Jo flips a fair coin 50 times and gets 28 heads. Which statement is correct?', '["The experimental probability of heads is 1/2 and the theoretical probability is 14/25","The experimental and theoretical probabilities of heads are both 14/25","The experimental probability of heads is 14/25 and the theoretical probability is 1/2","The experimental probability of heads is 28/22 and the theoretical probability is 1/2"]', 'The experimental probability of heads is 14/25 and the theoretical probability is 1/2', NULL, 'The experimental probability comes from what happened: $\frac{28}{50} = \frac{14}{25}$. The theoretical probability comes from the coin being fair: $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"The experimental probability of heads is 14/25 and the theoretical probability is 1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Experimental 28/50 = 14/25; theoretical for a fair coin 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90eed963-0416-43f7-99fc-bacab7c73513', 'NC26.7.RD.1', 2, 'numeric', 'Experimental probability from trials and simulations', 'A student uses random digits to simulate rainy days. The digits 0, 1, 2 and 3 stand for a rainy day, and the other digits stand for a dry day. The ten digits drawn are 3, 8, 1, 0, 6, 2, 7, 9, 5, 3. Based on these ten digits, what is the experimental probability of rain? Write your answer as a fraction.', '[]', '1/2', '5/10', 'The rainy digits (0 to 3) in the list are 3, 1, 0, 2 and 3, which is 5 of the 10 digits. The experimental probability is $\frac{5}{10} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits 3, 8, 1, 0, 6, 2, 7, 9, 5, 3. Rainy (0-3): 3, 1, 0, 2, 3 = 5 of 10 = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f48f429-a553-4957-bda9-de194d47eec0', 'NC26.7.RD.1', 2, 'numeric', 'Expected results and the effect of more trials', 'On a spinner, the probability of landing on green is $\frac{3}{10}$. If the spinner is spun 250 times, about how many times would you expect it to land on green?', '[]', '75', '3/10*250', 'The expected number is the probability times the number of spins: $\frac{3}{10} \times 250 = 75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/10 x 250 = 75.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a15b01f-0355-4b4c-b992-50cf87428cb8', 'NC26.7.RD.1', 2, 'choice', 'Expected results and the effect of more trials', 'A fair coin lands on tails 8 times in 10 flips. Rhea says, "Heads is due on the next flip." Which response is best?', '["Rhea is wrong: the next flip is still equally likely to land heads or tails","Rhea is right: heads is more likely, to balance the earlier tails","Rhea is wrong: tails is more likely, because it is on a streak","Rhea is right: the next flip must be heads"]', 'Rhea is wrong: the next flip is still equally likely to land heads or tails', NULL, 'Each flip of a fair coin is independent of the earlier flips. The probability of heads on the next flip is still $\frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"Rhea is wrong: the next flip is still equally likely to land heads or tails","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Flips are independent; a fair coin remains 1/2 heads, 1/2 tails regardless of past results.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('616a0c5e-a403-4527-850d-295e4ad7307d', 'NC26.7.RD.1', 2, 'numeric', 'Expected results and the effect of more trials', 'Dev made 36 of his 48 free throws this season. Using this experimental probability, about how many of his next 60 free throws would you expect him to make?', '[]', '45', '36/48*60', 'His experimental probability of making a free throw is $\frac{36}{48} = \frac{3}{4}$. In 60 free throws you would expect $\frac{3}{4} \times 60 = 45$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36/48 = 3/4; 3/4 x 60 = 45.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3cc4411-0726-45bc-94a0-f9bc52b9c2b4', 'NC26.7.RD.1', 3, 'numeric', 'Compound event without replacement', 'A bag has 3 red marbles and 2 blue marbles. Two marbles are drawn at random, one after the other, and the first is NOT put back. What is the probability that both marbles are red? Write your answer as a fraction.', '[]', '3/10', '3/5*2/4', 'The first marble is red with probability $\frac{3}{5}$. Then 2 red marbles remain among 4, so the second is red with probability $\frac{2}{4}$. Both red: $\frac{3}{5} \times \frac{2}{4} = \frac{6}{20} = \frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/5 x 2/4 = 6/20 = 3/10.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1bce1a22-b1a6-4e61-b7cb-357ba686f096', 'NC26.7.RD.1', 3, 'choice', 'Compound event with unequal outcomes', 'A spinner lands on red with probability $\frac{1}{2}$, on blue with probability $\frac{1}{3}$ and on green with probability $\frac{1}{6}$. A fair coin is flipped and the spinner is spun. What is the probability of getting tails and a spinner color that is not red?', '["1/2","1/4","1/6","1/12"]', '1/4', '1/2*(1/3+1/6)', 'The chance of tails is $\frac{1}{2}$. The chance the spinner is not red is $\frac{1}{3} + \frac{1}{6} = \frac{1}{2}$. Both together: $\frac{1}{2} \times \frac{1}{2} = \frac{1}{4}$. (1/6 leaves out green, and 1/12 leaves out blue.)', 'checked', '{"lint":[],"solve":{"answer":"1/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(tails) = 1/2. P(not red) = 1/3 + 1/6 = 1/2. Independent: 1/2 x 1/2 = 1/4.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67a3e9c9-3687-471c-b6cc-13e36552c807', 'NC26.7.RD.1', 3, 'choice', 'Design a simulation', 'A basketball player makes 70% of her free throws. Sam uses random digits from 0 to 9, each equally likely, to simulate one shot. Which rule matches the player?', '["Digits 0 to 7 are a made shot, and 8 and 9 are a miss","Digits 0 to 3 are a made shot, and 4 to 9 are a miss","Digits 7 to 9 are a made shot, and 0 to 6 are a miss","Digits 0 to 6 are a made shot, and 7 to 9 are a miss"]', 'Digits 0 to 6 are a made shot, and 7 to 9 are a miss', NULL, 'Of the 10 digits, 70% is 7 digits. The digits 0 to 6 are seven digits, so they stand for a made shot and the other three stand for a miss. The other rules give 80%, 40% and 30%.', 'checked', '{"lint":[],"solve":{"answer":"Digits 0 to 6 are a made shot, and 7 to 9 are a miss","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70% needs 7 of 10 digits as makes: 0-6 is 7 digits. 0-3 is 40%, 7-9 is 30%, 0-7 is 80%.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74fd4125-7845-4c2b-9f44-51484ed6f1b9', 'NC26.7.RD.1', 3, 'numeric', 'Theoretical probability of a single event', 'The 26 letters of the alphabet are written on 26 tiles, one letter per tile, and one tile is drawn at random. What is the probability that the letter is a vowel (A, E, I, O or U) or one of the letters in the word MATH? Write your answer as a fraction.', '[]', '4/13', '8/26', 'The vowels are A, E, I, O, U (5 letters). The letters of MATH are M, A, T, H (4 letters), but A is in both lists, so it must be counted once. Together there are $5 + 4 - 1 = 8$ different letters. The probability is $\frac{8}{26} = \frac{4}{13}$.', 'checked', '{"lint":[],"solve":{"answer":"4/13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vowels A, E, I, O, U; MATH adds M, T, H (A already counted). 8 letters of 26: 8/26 = 4/13.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81ae3936-036d-4ec4-bf3f-6f3dc65977a8', 'NC26.7.RD.1', 3, 'choice', 'Theoretical probability of a single event', 'A number from 1 to 40 is chosen at random. What is the probability that the number is a multiple of 3 or a multiple of 5?', '["21/40","19/40","13/40","1/5"]', '19/40', '19/40', 'There are 13 multiples of 3 (3 to 39) and 8 multiples of 5 (5 to 40). Two numbers, 15 and 30, are multiples of both, so $13 + 8 - 2 = 19$ numbers work. The probability is $\frac{19}{40}$. (21/40 counts 15 and 30 twice; 13/40 and 1/5 count only one of the two kinds.)', 'checked', '{"lint":[],"solve":{"answer":"19/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 3 in 1-40: 13. Multiples of 5: 8. Both (15, 30): 2. 13 + 8 - 2 = 19. 19/40.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8457d527-9bfc-4bb7-aad0-3511b04ba057', 'NC26.7.RD.1', 3, 'numeric', 'Theoretical probability of a single event', 'A bag has 4 red marbles and 6 blue marbles. How many red marbles must be added to the bag so that the probability of drawing a red marble is $\frac{2}{3}$?', '[]', '8', '(2*10-3*4)/(3-2)', 'If $x$ red marbles are added, the bag has $4 + x$ red marbles out of $10 + x$ in all. For $\frac{4 + x}{10 + x} = \frac{2}{3}$, try $x = 8$: $\frac{12}{18} = \frac{2}{3}$. So 8 red marbles must be added.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4 + x)/(10 + x) = 2/3 -> 12 + 3x = 20 + 2x -> x = 8. Check 12/18 = 2/3.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c17bc486-4814-4498-9fe1-bafa14b1ee0f', 'NC26.7.RD.1', 3, 'numeric', 'Probability when outcomes are not equally likely', 'A bag has red, blue and green marbles. The probability of drawing a red marble is $\frac{1}{4}$ and the probability of drawing a blue marble is $\frac{1}{2}$. There are 12 green marbles. How many marbles are in the bag?', '[]', '48', '12/(1-1/4-1/2)', 'The probability of green is $1 - \frac{1}{4} - \frac{1}{2} = \frac{1}{4}$. So 12 marbles are $\frac{1}{4}$ of the bag, and the bag holds $12 \times 4 = 48$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(green) = 1 - 1/4 - 1/2 = 1/4. 12 = 1/4 of total, total = 48.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c13b800-11a4-482f-9b75-9778ea7a3969', 'NC26.7.RD.1', 3, 'choice', 'Probability when outcomes are not equally likely', 'The probabilities of the three outcomes of a spinner are $x$, $2x$ and $3x$. What is the probability of the most likely outcome?', '["1/2","1/3","1/6","1/4"]', '1/2', '3/6', 'The probabilities add to 1, so $x + 2x + 3x = 6x = 1$ and $x = \frac{1}{6}$. The most likely outcome has probability $3x = \frac{3}{6} = \frac{1}{2}$. (1/6 is $x$ and 1/3 is $2x$.)', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 1, x = 1/6. Largest 3x = 1/2.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f6ed2e9-b4cd-4c38-bed1-baab6698ae4c', 'NC26.7.RD.1', 3, 'numeric', 'Probability when outcomes are not equally likely', 'A weighted die lands on 6 with probability $\frac{1}{3}$. The other five faces are equally likely to come up. What is the probability of rolling a 2? Write your answer as a fraction.', '[]', '2/15', '(1-1/3)/5', 'The five other faces share the remaining probability $1 - \frac{1}{3} = \frac{2}{3}$ equally. Each gets $\frac{2}{3} \div 5 = \frac{2}{15}$.', 'checked', '{"lint":[],"solve":{"answer":"2/15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other five faces share 1 - 1/3 = 2/3; each 2/3 / 5 = 2/15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ee91eb8-29b9-430d-b66e-239b1a1bb7c8', 'NC26.7.RD.1', 3, 'numeric', 'Counting the outcomes of a compound event', 'A 4-digit code uses the digits 0 to 9, and a digit can be used more than once. The first digit cannot be 0. How many different codes are possible?', '[]', '9000', '9*10*10*10', 'The first digit has 9 choices (1 to 9). Each of the other three digits has 10 choices. The number of codes is $9 \times 10 \times 10 \times 10 = 9{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"9000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 choices (1-9) x 10 x 10 x 10 = 9000.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e91ef1a-c61b-4d67-bae9-c5ea609e843e', 'NC26.7.RD.1', 3, 'choice', 'Counting the outcomes of a compound event', 'A fair coin is flipped 6 times. How many of the possible outcomes have heads on both the first flip and the last flip?', '["8","32","64","16"]', '16', '2^4', 'The first and last flips are fixed as heads. Each of the 4 flips in the middle can be heads or tails, so there are $2 \times 2 \times 2 \times 2 = 16$ outcomes. (The whole sample space has $2^6 = 64$ outcomes.)', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First and last fixed as H; middle 4 flips free: 2^4 = 16.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2f5f8fe-12b9-4029-b486-d7b8f1d4d057', 'NC26.7.RD.1', 3, 'numeric', 'Listing a sample space', 'A fair coin is flipped 4 times. What is the probability of getting at least 3 heads? Write your answer as a fraction.', '[]', '5/16', '5/16', 'There are $2^4 = 16$ equally likely outcomes. Exactly 3 heads happens in HHHT, HHTH, HTHH and THHH (4 outcomes), and 4 heads happens in HHHH (1 outcome). That is 5 outcomes, so the probability is $\frac{5}{16}$.', 'checked', '{"lint":[],"solve":{"answer":"5/16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 outcomes. Exactly 3 heads: 4; exactly 4: 1. 5/16.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6af39935-c557-4c82-ba7b-ed9f3972f712', 'NC26.7.RD.1', 3, 'choice', 'Listing a sample space', 'Four fair coins are tossed at once. Which of these events is the MOST likely?', '["Exactly 1 coin lands heads","Exactly 3 coins land heads","Exactly 2 coins land heads","All 4 coins land heads"]', 'Exactly 2 coins land heads', NULL, 'Of the 16 equally likely outcomes, exactly 2 heads happens 6 times (HHTT, HTHT, HTTH, THHT, THTH, TTHH). Exactly 1 head and exactly 3 heads each happen 4 times, and 4 heads happens once.', 'checked', '{"lint":[],"solve":{"answer":"Exactly 2 coins land heads","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Out of 16: 4 heads 1, 3 heads 4, 2 heads 6, 1 head 4. Exactly 2 heads is most likely.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e782065e-7f2f-4e95-a6ac-b95d7a91fea3', 'NC26.7.RD.1', 3, 'numeric', 'Listing a sample space', 'Spinner A has three equal sections numbered 1, 2 and 3. Spinner B has three equal sections numbered 2, 4 and 6. Both are spun and the two numbers are multiplied. What is the probability that the product is greater than 8? Write your answer as a fraction.', '[]', '1/3', '3/9', 'There are $3 \times 3 = 9$ outcomes. The products are 2, 4, 6 (with 1), 4, 8, 12 (with 2) and 6, 12, 18 (with 3). Products greater than 8 are 12, 12 and 18, which is 3 outcomes. The probability is $\frac{3}{9} = \frac{1}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"1/3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Products: 1x(2,4,6)=2,4,6; 2x=4,8,12; 3x=6,12,18. Greater than 8: 12, 12, 18 = 3 of 9 = 1/3 (8 itself not counted).","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44756db6-31fe-4581-b08b-d039a799b6e3', 'NC26.7.RD.1', 3, 'choice', 'Using a table of outcomes', 'Two fair six-sided dice are rolled and the numbers are added. What is the probability that the sum is a prime number?', '["5/11","5/12","1/3","1/2"]', '5/12', '15/36', 'The prime sums are 2, 3, 5, 7 and 11. In the table of 36 outcomes they appear 1, 2, 4, 6 and 2 times, which is 15 outcomes. The probability is $\frac{15}{36} = \frac{5}{12}$. (5/11 wrongly treats the 11 sums as equally likely.)', 'checked', '{"lint":[],"solve":{"answer":"5/12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prime sums: 2 (1 way), 3 (2), 5 (4), 7 (6), 11 (2) = 15 of 36 = 5/12.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55dca5ce-a9a4-4589-94ef-98ef27db928e', 'NC26.7.RD.1', 3, 'choice', 'Using a table of outcomes', 'Two fair six-sided dice are rolled and the numbers are multiplied. What is the probability that the product is even?', '["1/2","3/4","1/4","2/3"]', '3/4', '27/36', 'A product is odd only when both numbers are odd, which happens in $3 \times 3 = 9$ of the 36 outcomes. So $36 - 9 = 27$ outcomes have an even product, and the probability is $\frac{27}{36} = \frac{3}{4}$. (1/4 is the chance of an odd product.)', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd product only if both odd: 1/2 x 1/2 = 1/4. Even: 1 - 1/4 = 3/4.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eec3b10e-60bf-4c16-aba9-41641482fa6e', 'NC26.7.RD.1', 3, 'numeric', 'Using a tree diagram', 'Priya shoots two free throws. She makes each one with probability $\frac{2}{3}$, and the shots do not affect each other. A tree diagram shows all four outcomes. What is the probability that she makes exactly one of the two shots? Write your answer as a fraction.', '[]', '4/9', '2*2/3*1/3', 'Make then miss: $\frac{2}{3} \times \frac{1}{3} = \frac{2}{9}$. Miss then make: $\frac{1}{3} \times \frac{2}{3} = \frac{2}{9}$. Exactly one shot is made on either of these two paths, so add: $\frac{2}{9} + \frac{2}{9} = \frac{4}{9}$.', 'checked', '{"lint":[],"solve":{"answer":"4/9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Make-miss 2/3 x 1/3 = 2/9; miss-make 1/3 x 2/3 = 2/9. Total 4/9.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f24bc126-817f-4b4e-a477-f1e767700697', 'NC26.7.RD.1', 3, 'choice', 'Using a tree diagram', 'Sam makes a tree diagram. He rolls a fair six-sided die. If the number is odd, he stops. If the number is even, he also flips a fair coin. How many different outcomes are on the tree?', '["9","12","6","5"]', '9', '3+3*2', 'The odd numbers 1, 3 and 5 each end the tree, giving 3 outcomes. The even numbers 2, 4 and 6 each continue to heads or tails, giving $3 \times 2 = 6$ outcomes. The total is $3 + 6 = 9$. (12 would be right only if the coin were always flipped.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Odd rolls 1, 3, 5 end: 3 outcomes. Even rolls 2, 4, 6 each split H/T: 6 outcomes. Total 9.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('278a0b06-2467-45dd-8ec7-a1367c4620e4', 'NC26.7.RD.1', 3, 'numeric', 'Using a tree diagram', 'The probability of rain tomorrow is 0.3. If it rains, a soccer game is canceled with probability 0.8. If it does not rain, the game is canceled with probability 0.1. A tree diagram has these probabilities on its branches. What is the probability that the game is canceled? Write your answer as a decimal.', '[]', '0.31', '0.3*0.8+0.7*0.1', 'There are two paths to a canceled game. Rain, then canceled: $0.3 \times 0.8 = 0.24$. No rain, then canceled: $0.7 \times 0.1 = 0.07$. Add the two paths: $0.24 + 0.07 = 0.31$.', 'checked', '{"lint":[],"solve":{"answer":"0.31","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rain and cancel 0.3 x 0.8 = 0.24; no rain and cancel 0.7 x 0.1 = 0.07. Total 0.31.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83d038c9-aeea-4f2d-82e8-f87e00bb1b18', 'NC26.7.RD.1', 3, 'numeric', 'Compound events with replacement', 'Sam guesses the answer to each of 3 multiple-choice questions. Each question has 4 choices, and exactly one choice is correct. What is the probability that Sam gets none of the three questions right? Write your answer as a fraction.', '[]', '27/64', '3/4*3/4*3/4', 'On each question, the probability of a wrong guess is $\frac{3}{4}$. The questions do not affect each other, so multiply: $\frac{3}{4} \times \frac{3}{4} \times \frac{3}{4} = \frac{27}{64}$.', 'checked', '{"lint":[],"solve":{"answer":"27/64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wrong on each: 3/4. (3/4)^3 = 27/64.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7aa34efd-c3bd-463f-ba31-f63019e7b4f7', 'NC26.7.RD.1', 3, 'choice', 'Compound events with replacement', 'A spinner lands on red with probability 0.5, on blue with probability 0.3 and on green with probability 0.2. It is spun two times. What is the probability that it lands on the same color both times?', '["0.62","0.19","0.25","0.38"]', '0.38', '0.5*0.5+0.3*0.3+0.2*0.2', 'Same color means red-red, blue-blue or green-green. Red-red: $0.5 \times 0.5 = 0.25$. Blue-blue: $0.3 \times 0.3 = 0.09$. Green-green: $0.2 \times 0.2 = 0.04$. Add: $0.25 + 0.09 + 0.04 = 0.38$. (0.25 counts only red-red, and 0.62 is the chance of two different colors.)', 'checked', '{"lint":[],"solve":{"answer":"0.38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5^2 + 0.3^2 + 0.2^2 = 0.25 + 0.09 + 0.04 = 0.38.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25f2aee6-7687-4805-ae5a-1de54ad9fd2f', 'NC26.7.RD.1', 3, 'numeric', 'Compound events with replacement', 'A bag has marbles of several colors, and some of them are red. One marble is drawn at random and put back, and then a second marble is drawn. The probability that both marbles are red is $\frac{9}{49}$. What is the probability that a single marble drawn from the bag is red? Write your answer as a fraction.', '[]', '3/7', '3/7', 'Both draws have the same probability $p$ of red, so $p \times p = \frac{9}{49}$. Since $3 \times 3 = 9$ and $7 \times 7 = 49$, $p = \frac{3}{7}$.', 'checked', '{"lint":[],"solve":{"answer":"3/7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With replacement p x p = 9/49, so p = 3/7.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2cac59d-44de-41f3-87e9-60dfd27003c9', 'NC26.7.RD.1', 3, 'numeric', 'Compound events without replacement', 'A box holds 5 green pens and 3 black pens. Two pens are drawn one after the other without putting the first one back. What is the probability that the two pens are different colors? Write your answer as a fraction.', '[]', '15/28', '5/8*3/7+3/8*5/7', 'Green then black: $\frac{5}{8} \times \frac{3}{7} = \frac{15}{56}$. Black then green: $\frac{3}{8} \times \frac{5}{7} = \frac{15}{56}$. Add the two ways: $\frac{15}{56} + \frac{15}{56} = \frac{30}{56} = \frac{15}{28}$.', 'checked', '{"lint":[],"solve":{"answer":"15/28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"GB: 5/8 x 3/7 = 15/56; BG: 3/8 x 5/7 = 15/56. Total 30/56 = 15/28.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41ae50dc-b8d3-4687-adce-69e7a92019a3', 'NC26.7.RD.1', 3, 'choice', 'Compound events without replacement', 'Five cards are numbered 1, 2, 3, 4 and 5. Two cards are drawn one after the other, and the first card is not put back. What is the probability that the sum of the two numbers is 7?', '["4/25","1/4","1/5","1/10"]', '1/5', '4/20', 'There are $5 \times 4 = 20$ ordered outcomes. The sum is 7 for (2, 5), (5, 2), (3, 4) and (4, 3), which is 4 outcomes. The probability is $\frac{4}{20} = \frac{1}{5}$. (4/25 wrongly allows the same card to be drawn twice.)', 'checked', '{"lint":[],"solve":{"answer":"1/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered pairs without replacement: 5 x 4 = 20. Sum 7: (2,5), (5,2), (3,4), (4,3) = 4. 4/20 = 1/5.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('24810d15-5398-476f-a3cd-6a658c6571d2', 'NC26.7.RD.1', 3, 'numeric', 'Compound events without replacement', 'A bag has 5 white tiles and 3 black tiles. Three tiles are drawn one after another without putting any back. What is the probability that all three are white? Write your answer as a fraction.', '[]', '5/28', '5/8*4/7*3/6', 'The first tile is white with probability $\frac{5}{8}$, the second with $\frac{4}{7}$ and the third with $\frac{3}{6}$. Multiply: $\frac{5}{8} \times \frac{4}{7} \times \frac{3}{6} = \frac{60}{336} = \frac{5}{28}$.', 'checked', '{"lint":[],"solve":{"answer":"5/28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5/8 x 4/7 x 3/6 = 60/336 = 5/28.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5392653-478d-47ac-8cdb-30bcf82144e7', 'NC26.7.RD.1', 3, 'choice', 'Designing a simulation', 'A game is won with probability 0.12. A student uses two-digit random numbers from 00 to 99, each equally likely, to simulate one play. Which rule matches the game?', '["00 to 12 is a win; 13 to 99 is a loss","00 to 11 is a win; 12 to 99 is a loss","01 to 11 is a win; 00 and 12 to 99 are a loss","12 to 99 is a win; 00 to 11 is a loss"]', '00 to 11 is a win; 12 to 99 is a loss', NULL, 'There are 100 two-digit numbers, and 12% of 100 is 12. The numbers 00 to 11 are exactly 12 numbers. The rule using 00 to 12 has 13 numbers (13%), the rule using 01 to 11 has 11 numbers (11%), and the rule using 12 to 99 as a win has 88 numbers (88%).', 'checked', '{"lint":[],"solve":{"answer":"00 to 11 is a win; 12 to 99 is a loss","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 12 of 100 numbers. 00-11 is 12 numbers (0.12). 00-12 is 13; 01-11 is 11; 12-99 is 88.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('496ccdc1-6cbb-4fa6-b0af-e3b118dbb4f3', 'NC26.7.RD.1', 3, 'choice', 'Designing a simulation', 'Maya makes 50% of her free throws. A student wants to estimate the probability that she makes all 3 of her next 3 free throws. He uses a fair coin, with heads for a made shot. What is one trial of his simulation?', '["Flip the coin once and record heads or tails","Flip the coin 3 times and record the number of tails","Flip the coin 3 times and record whether all three flips are heads","Flip the coin until a head comes up"]', 'Flip the coin 3 times and record whether all three flips are heads', NULL, 'One trial must copy the whole event: 3 shots in a row. So the coin is flipped 3 times, and the trial is a success only if all 3 flips are heads. Repeating many trials and finding the fraction of successes estimates the probability.', 'checked', '{"lint":[],"solve":{"answer":"Flip the coin 3 times and record whether all three flips are heads","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One trial models 3 shots: flip 3 times and record whether all three are heads.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78ccca40-9012-4c7e-9d7a-99b308a08757', 'NC26.7.RD.1', 3, 'numeric', 'Experimental probability from trials and simulations', 'Ana ran a simulation and got 18 successes in 30 trials. Ben ran the same simulation and got 42 successes in 70 trials. If all of their trials are combined, what is the experimental probability of a success? Write your answer as a fraction.', '[]', '3/5', '(18+42)/(30+70)', 'Together there are $18 + 42 = 60$ successes in $30 + 70 = 100$ trials. The experimental probability is $\frac{60}{100} = \frac{3}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"3/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(18 + 42)/(30 + 70) = 60/100 = 3/5.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7b15f7c-644a-47b7-90f3-c899dc6e9f59', 'NC26.7.RD.1', 3, 'choice', 'Experimental probability from trials and simulations', 'A student simulates a family with 3 children using a fair coin, with heads for a girl. The number of girls in each of 10 trials is 1, 2, 3, 1, 0, 2, 2, 1, 2, 3. Based on this simulation, what is the experimental probability that a family has exactly 2 girls?', '["3/8","1/5","1/3","2/5"]', '2/5', '4/10', 'Exactly 2 girls occurred in 4 of the 10 trials, so the experimental probability is $\frac{4}{10} = \frac{2}{5}$. (3/8 is the theoretical probability, not what this simulation shows.)', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values 1, 2, 3, 1, 0, 2, 2, 1, 2, 3: exactly 2 girls in 4 trials. 4/10 = 2/5.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e53b0797-8e59-4027-8ad9-b9df18b95908', 'NC26.7.RD.1', 3, 'numeric', 'Experimental probability from trials and simulations', 'In a simulation, 6 of the first 20 trials were successes. How many successes are needed in the next 30 trials for the experimental probability of success over all 50 trials to be exactly 0.4?', '[]', '14', '0.4*50-6', 'For an experimental probability of 0.4 over 50 trials, there must be $0.4 \times 50 = 20$ successes in all. There were already 6, so the next 30 trials need $20 - 6 = 14$ successes.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.4 x 50 = 20 successes needed in total; 20 - 6 = 14.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9ccd6ca-e89d-4d79-9e4b-b340ffa813fc', 'NC26.7.RD.1', 3, 'numeric', 'Expected results and the effect of more trials', 'A fair six-sided die is rolled 90 times. A 5 or a 6 comes up on 24 of the rolls. How many fewer times than expected did a 5 or a 6 come up?', '[]', '6', '90*2/6-24', 'The probability of a 5 or a 6 is $\frac{2}{6} = \frac{1}{3}$, so about $\frac{1}{3} \times 90 = 30$ rolls are expected. It came up 24 times, which is $30 - 24 = 6$ fewer than expected.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(5 or 6) = 2/6 = 1/3; expected 90/3 = 30. 30 - 24 = 6 fewer.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc1a76b4-adc9-4419-9f29-95a64e5abf99', 'NC26.7.RD.1', 3, 'choice', 'Expected results and the effect of more trials', 'Ali rolls a fair six-sided die 12 times and Bea rolls one 120 times. Each records the fraction of their rolls that were sixes. Which statement is most likely true?', '["Bea''s fraction is likely to be closer to 1/6 than Ali''s fraction","Ali''s fraction is likely to be closer to 1/6 than Bea''s fraction","Both fractions will be exactly 1/6","Bea will roll exactly 20 sixes"]', 'Bea''s fraction is likely to be closer to 1/6 than Ali''s fraction', NULL, 'With more trials, the experimental probability tends to get closer to the theoretical probability of $\frac{1}{6}$. Bea has ten times as many rolls as Ali. Nothing guarantees an exact fraction or exactly 20 sixes.', 'checked', '{"lint":[],"solve":{"answer":"Bea''s fraction is likely to be closer to 1/6 than Ali''s fraction","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger samples tend to give experimental probabilities closer to the theoretical 1/6; exact equality is not guaranteed.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('771ca4d7-5f19-4d61-8f4e-7c1d9e3aea21', 'NC26.7.RD.1', 3, 'numeric', 'Expected results and the effect of more trials', 'Kai draws a marble from a bag, records its color and puts it back. He does this 80 times and draws a red marble 20 times. The bag has 60 marbles in all. Based on Kai''s results, about how many marbles in the bag are red?', '[]', '15', '20/80*60', 'Red came up in $\frac{20}{80} = \frac{1}{4}$ of the draws, so about $\frac{1}{4}$ of the marbles are red. $\frac{1}{4} \times 60 = 15$ marbles.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/80 = 1/4 red; 1/4 x 60 = 15.","run_id":"claude-code","at":"2026-10-17T19:09:02.169Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a67f78b-91c0-433d-b8fd-82b371094ae9', 'NC26.7.RD.2', 1, 'choice', 'Recognize a statistical question', 'Which of these is a statistical question?', '["How many pets does each student in our class have?","How tall is the school flagpole?","How many pets does Ava have?","How many students are in Room 12 today?"]', 'How many pets does each student in our class have?', NULL, 'A statistical question expects answers that vary, so you need to collect data from many people or things. Each student in the class may have a different number of pets. The other questions each have a single answer.', 'checked', '{"lint":[],"solve":{"answer":"How many pets does each student in our class have?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question expects variability in the answers; only ''each student in our class'' gathers varied data. The others have one answer.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('772169f9-456c-4dcf-9234-b9b4fcdd04a7', 'NC26.7.RD.2', 1, 'choice', 'Choose a representative sample', 'A school has 400 students. Which is the best way to choose 40 students to find out the favorite sport of all the students?', '["Ask the 40 students on the basketball team","Ask 40 students watching a soccer game","Choose 40 names at random from the list of all students","Ask 40 of the survey writer''s friends"]', 'Choose 40 names at random from the list of all students', NULL, 'A random sample gives every student the same chance of being chosen, so it is likely to look like the whole school. The other groups are likely to favor one sport.', 'checked', '{"lint":[],"solve":{"answer":"Choose 40 names at random from the list of all students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A simple random sample from the whole list is representative; the others are biased toward sports or friends.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4c75670-5aca-4e18-b7a9-8ea6cb888517', 'NC26.7.RD.2', 1, 'numeric', 'Proportion in a sample', 'In a random sample of 50 students, 20 said math is their favorite subject. What fraction of the sample said math is their favorite subject? Write your answer as a fraction.', '[]', '2/5', '20/50', 'The fraction is $\frac{20}{50}$. Dividing the top and bottom by 10 gives $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Accepting 20/50 as well as 2/5 would be fair, since the stem only asks for a fraction.","work":"20/50 = 2/5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d6fc161-d0f6-434d-bb45-e345024d0f46', 'NC26.7.RD.2', 1, 'choice', 'Recognize a statistical question', 'Mr. Gill wants to learn about the students in his class. Which question is a statistical question?', '["How many minutes does each student spend on homework each night?","How many minutes did Mr. Gill spend grading papers last night?","How many desks and chairs are in this classroom right now?","On what date is the class trip to the science museum?"]', 'How many minutes does each student spend on homework each night?', NULL, 'A statistical question expects the answers to vary, so you must collect data from a group. Students in the class may spend different amounts of time on homework. The other questions each have just one answer.', 'checked', '{"lint":[],"solve":{"answer":"How many minutes does each student spend on homework each night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question expects variable answers. Homework minutes vary from student to student. Desks/chairs, Mr. Gill''s own grading time and the trip date each have one answer.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebc2992a-f47f-4725-ab52-62302cbcdc6a', 'NC26.7.RD.2', 1, 'choice', 'Recognize a statistical question', 'Which of these is NOT a statistical question?', '["How tall are the trees in the park?","How many hours do students sleep on school nights?","How far do students at our school live from school?","What is the height of the flagpole in the park?"]', 'What is the height of the flagpole in the park?', NULL, 'The flagpole has one height, so the question has a single answer. The other questions ask about many trees or many students, whose answers can differ, so they are statistical questions.', 'checked', '{"lint":[],"solve":{"answer":"What is the height of the flagpole in the park?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The flagpole has a single height: not statistical. Distances, sleep hours and tree heights vary.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10d5e5a6-2376-4db6-ba51-900518c4a085', 'NC26.7.RD.2', 1, 'choice', 'Recognize a statistical question', 'Why is the question "How many pets do the students in our class have?" a statistical question?', '["It has only one correct answer for everyone.","It asks about only one student in the class.","The answers can differ from student to student.","It can be answered without collecting any data."]', 'The answers can differ from student to student.', NULL, 'A statistical question is one where we expect the answers to vary. Different students may have different numbers of pets, so we collect data from the whole class.', 'checked', '{"lint":[],"solve":{"answer":"The answers can differ from student to student.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"It is statistical because answers vary across students.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb2c3355-bed2-4bda-aa36-b1d73a6c8f40', 'NC26.7.RD.2', 1, 'choice', 'Recognize a statistical question', 'An animal shelter has 20 cats. Which question about the cats is a statistical question?', '["How much does the shelter''s oldest cat weigh?","How much does each cat at the shelter weigh?","Is the shelter open on Monday?","How many cats are at the shelter today?"]', 'How much does each cat at the shelter weigh?', NULL, 'The cats probably have different weights, so asking about every cat gives data that vary. The oldest cat has one weight, and the other questions each have a single answer.', 'checked', '{"lint":[],"solve":{"answer":"How much does each cat at the shelter weigh?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Weights of all 20 cats vary: statistical. Count today, opening day and the oldest cat''s weight each have one answer.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0556a0c3-e214-4048-8f3f-1e33424b526b', 'NC26.7.RD.2', 1, 'choice', 'Write or choose a question that compares two groups', 'Ana wants to compare how long seventh graders and eighth graders read each week. Which question compares these two groups?', '["How many minutes did Ana spend reading during the last week?","How many minutes does a typical seventh grader read in one week?","Do seventh graders read more minutes each week than eighth graders?","What is the title of the longest book that an eighth grader has read?"]', 'Do seventh graders read more minutes each week than eighth graders?', NULL, 'A comparison question names both groups and the same measurement for each. Only the first question asks about reading time for both seventh graders and eighth graders.', 'checked', '{"lint":[],"solve":{"answer":"Do seventh graders read more minutes each week than eighth graders?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only ''Do seventh graders read more minutes each week than eighth graders?'' involves both groups and compares them.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f53cc2-abde-42bd-aae0-c8f99c689624', 'NC26.7.RD.2', 1, 'choice', 'Write or choose a question that compares two groups', 'Which question compares two groups?', '["Are soccer team members taller, on average, than swim team members?","How tall is the person who coaches the soccer team at our school?","How many students are on the swim team and on the soccer team?","What is the typical height of the students on the soccer team?"]', 'Are soccer team members taller, on average, than swim team members?', NULL, 'The correct question measures the same thing (height) for two groups and asks how they compare. The question about the typical height of the soccer team asks about one group only.', 'checked', '{"lint":[],"solve":{"answer":"Are soccer team members taller, on average, than swim team members?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Comparing heights of soccer vs swim team members compares two groups. Counting members of both is a total, not a comparison of a variable.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da0c5a8c-65b1-4f4c-bd27-2ead541980ee', 'NC26.7.RD.2', 1, 'choice', 'Population and sample', 'A principal asks 30 of the 600 students in a school which lunch they like best. What is the population in this survey?', '["all 600 students in the school","the 30 students who were asked","the principal who asked the question","the different lunches on the menu"]', 'all 600 students in the school', NULL, 'The population is the whole group we want to learn about: all 600 students. The 30 students who were asked are the sample.', 'checked', '{"lint":[],"solve":{"answer":"all 600 students in the school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Population = the whole group of interest: all 600 students. The 30 are the sample.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3595f2d-d037-4a1d-9689-3da56f9be3cb', 'NC26.7.RD.2', 1, 'numeric', 'Population and sample', 'A town has 4,500 households. A researcher asks 90 of the households about recycling. How many households are in the sample?', '[]', '90', '90', 'The sample is the part of the population that is asked. Here 90 households are asked, so the sample has 90 households.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sample = the 90 households asked.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
