INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8e2ec61e-9fd3-4d52-8bc1-0f2929e4c9fb', 'NC26.7.RD.2', 1, 'choice', 'Population and sample', 'Which statement describes a sample?', '["Every single member of the whole population that is being studied","The question that is asked of the people in a survey","A part of the population that is studied to learn about the whole","The most common answer that the people in a survey give"]', 'A part of the population that is studied to learn about the whole', NULL, 'A sample is a smaller part of the population. We study it to learn about the whole population.', 'checked', '{"lint":[],"solve":{"answer":"A part of the population that is studied to learn about the whole","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sample is a part of the population studied to learn about the whole.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
