INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8722a8f-66e1-4743-99f3-54f5c15d1dae', 'NC26.7.RD.2', 1, 'numeric', 'Population and sample', 'A school has 480 students. A sample of 48 students is asked about a new bike rack. What fraction of the population is in the sample? Write your answer as a fraction.', '[]', '1/10', '48/480', 'The fraction is $\frac{48}{480}$. Dividing the top and bottom by 48 gives $\frac{1}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"1/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48/480 = 1/10.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
