INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df8beb64-ac17-41b3-91ed-18ce8a435de8', 'NC26.7.RD.2', 1, 'choice', 'Spot and explain bias in a sample', 'A school wants to find out how many hours of sleep its students get. Which sample is most likely to be biased?', '["Students whose names are drawn from a hat that holds all names","Students picked by a computer from the full school list","Students chosen with a spinner that has a section for each student","The students who are on the school''s early-morning running team"]', 'The students who are on the school''s early-morning running team', NULL, 'A runner who trains early may sleep differently from other students, so the team does not represent everyone. The other samples give every student the same chance of being chosen.', 'checked', '{"lint":[],"solve":{"answer":"The students who are on the school''s early-morning running team","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Early-morning runners likely have different sleep habits than other students: biased. The other three are random from the full list.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa3b4bec-48de-495f-aa9f-ae2bb8ca1268', 'NC26.7.RD.2', 1, 'choice', 'Spot and explain bias in a sample', 'A survey about favorite fruit is given only to students who are waiting in the fruit line at lunch. Why is this sample biased?', '["Lunch time is too short for students to finish a survey.","Students in the fruit line are likely to like fruit more than others.","Students who stand in a line are not allowed to answer surveys.","Fruit is a healthy food, so the survey asks about the wrong kind of thing."]', 'Students in the fruit line are likely to like fruit more than others.', NULL, 'The students were chosen because they were getting fruit, so they probably like fruit more than students who were not in that line. The sample favors one kind of answer, which is bias.', 'checked', '{"lint":[],"solve":{"answer":"Students in the fruit line are likely to like fruit more than others.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students choosing fruit likely like fruit more, so the sample over-represents fruit lovers.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c5f71b4-4244-479f-8df3-897bc11508ca', 'NC26.7.RD.2', 1, 'choice', 'Spot and explain bias in a sample', 'Mr. Lin asks his own 25 students whether they like homework, to find out what all 800 students in the school think. What is wrong with this sample?', '["It uses students from only one class, so it may not fit the whole school.","The number 25 is an odd number, so the sample cannot be random.","He should have asked the teachers in his school instead of the students.","Homework is not a good topic to ask students about in a survey."]', 'It uses students from only one class, so it may not fit the whole school.', NULL, 'One class may be different from the rest of the school, so its answers may not match what all 800 students think. A sample should be chosen from the whole population.', 'checked', '{"lint":[],"solve":{"answer":"It uses students from only one class, so it may not fit the whole school.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One class may not represent all 800 students (convenience sample).","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d84511c7-eef5-4551-9006-0afcc2a97366', 'NC26.7.RD.2', 1, 'choice', 'Choose a random sampling method', 'A teacher wants a random sample of 5 students from her class of 25. Which method gives every student the same chance of being chosen?', '["Pick the 5 students who are sitting nearest to the front","Pick the first 5 students who raise their hands in class","Write each name on a card, mix the cards well, and draw 5","Pick the 5 students that she likes best in the class"]', 'Write each name on a card, mix the cards well, and draw 5', NULL, 'Drawing names from a well-mixed pile gives every student the same chance. The other methods favor certain students.', 'checked', '{"lint":[],"solve":{"answer":"Write each name on a card, mix the cards well, and draw 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shuffled name cards give each student an equal chance; the others depend on seat, hand-raising or preference.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82c65c7a-e329-44b6-a140-1477290dcafe', 'NC26.7.RD.2', 1, 'choice', 'Choose a random sampling method', 'Which of these gives a random sample of a school''s 300 students?', '["Take the first 30 students who arrive at school today","Take 30 students who are all in the same classroom","Take 30 students from the school''s honor roll list","Use a computer to pick 30 student ID numbers at random"]', 'Use a computer to pick 30 student ID numbers at random', NULL, 'A computer choosing ID numbers at random gives every student the same chance. The other groups are made of students who are alike in some way.', 'checked', '{"lint":[],"solve":{"answer":"Use a computer to pick 30 student ID numbers at random","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random selection of ID numbers by computer is random; the others are convenience or restricted groups.","run_id":"claude-code","at":"2026-10-17T20:25:00.132Z"}}', 'ai', NULL, NULL)
