INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f957b71-ecca-4d3f-8359-8d2eaec95d6b', 'NC26.7.RD.3', 1, 'choice', 'Compare the spread of two distributions', 'A dot plot of Class A''s quiz scores has dots only at 7, 8 and 9. A dot plot of Class B''s quiz scores has dots from 3 all the way to 10. Which statement is correct?', '["Class A''s scores are more spread out than Class B''s scores.","The scores of the two classes are equally spread out.","Class B''s scores are more spread out than Class A''s scores.","The spread cannot be compared unless the two means are known."]', 'Class B''s scores are more spread out than Class A''s scores.', NULL, 'Class A''s dots cover only 9 - 7 = 2 units, while Class B''s dots cover 10 - 3 = 7 units. The wider the dots stretch, the greater the spread, and this can be seen without knowing the means.', 'checked', '{"lint":[],"solve":{"answer":"Class B''s scores are more spread out than Class A''s scores.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class A spans 7-9 (range 2); Class B spans 3-10 (range 7). B more spread out. Spread does not need means.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bec72865-e054-48cd-b3d6-2b506605d5f0', 'NC26.7.RD.3', 1, 'numeric', 'Compare the spread of two distributions', 'On one number line, the dots of Plot A go from 12 to 20, and the dots of Plot B go from 5 to 30. How much greater is the range of Plot B than the range of Plot A?', '[]', '17', '(30-5)-(20-12)', 'The range of A is 20 - 12 = 8. The range of B is 30 - 5 = 25. The difference is 25 - 8 = 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A 20-12=8; range B 30-5=25; 25-8=17.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a516800d-e782-47c3-8f20-50754cf7b487', 'NC26.7.RD.3', 1, 'numeric', 'Compare the spread of two distributions', 'Monday''s temperatures, in degrees, at five times of the day were 55, 58, 61, 66, 70. Tuesday''s were 52, 57, 60, 64, 65. How much greater is Monday''s range than Tuesday''s range?', '[]', '2', '(70-55)-(65-52)', 'Monday''s range is 70 - 55 = 15 degrees. Tuesday''s range is 65 - 52 = 13 degrees. The difference is 15 - 13 = 2 degrees.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Monday 70-55=15; Tuesday 65-52=13; 15-13=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77b14d26-871f-4995-87b9-6e6fae449195', 'NC26.7.RD.3', 1, 'choice', 'Compare the spread of two distributions', 'Which of these describes a data set with a small spread?', '["The values are all large numbers.","The values are all close together.","The values are listed in order from least to greatest.","The data set has only a few values."]', 'The values are all close together.', NULL, 'Spread tells how far apart the values are. A small spread means the values are close together. Having large values, being in order, or having few values says nothing about spread.', 'checked', '{"lint":[],"solve":{"answer":"The values are all close together.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Small spread means values are close together.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('784636a7-f680-4710-a2cf-510a7c542cab', 'NC26.7.RD.3', 1, 'choice', 'Describe the shape of a distribution', 'A dot plot has 1 dot at 1, 2 dots at 2, 4 dots at 3, 2 dots at 4 and 1 dot at 5. Which describes its shape?', '["Skewed to the right, with its peak at 1","Symmetric, with its peak at 3","Flat, with the same number of dots at each value","Symmetric, with its peak at 4"]', 'Symmetric, with its peak at 3', NULL, 'The counts 1, 2, 4, 2, 1 go up to the tallest stack at 3 and then come back down in the same way, so the shape is symmetric about 3, where the peak is.', 'checked', '{"lint":[],"solve":{"answer":"Symmetric, with its peak at 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 1,2,4,2,1 mirror around 3 with tallest at 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acaf3a10-0e6b-4135-8405-70499370a4c5', 'NC26.7.RD.3', 1, 'choice', 'Describe the shape of a distribution', 'A dot plot has 3 dots at 2, 4 dots at 3, no dots at 4 or 5, 5 dots at 6 and 3 dots at 7. Which statement describes it?', '["There is one cluster, with an outlier at 7.","The shape is flat, with no gaps.","There is a gap between 2 and 3.","There are two clusters, with a gap between 3 and 6."]', 'There are two clusters, with a gap between 3 and 6.', NULL, 'The dots at 2 and 3 form one cluster and the dots at 6 and 7 form another. Nothing is at 4 or 5, so there is a gap between 3 and 6.', 'checked', '{"lint":[],"solve":{"answer":"There are two clusters, with a gap between 3 and 6.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dots at 2,3 and at 6,7 with none at 4,5: two clusters separated by a gap between 3 and 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54d7973a-93cb-45ef-b1c0-637f7a287754', 'NC26.7.RD.3', 1, 'numeric', 'Describe the shape of a distribution', 'A dot plot of the number of brothers and sisters students have shows 4 dots at 0, 9 dots at 1, 6 dots at 2, 3 dots at 3 and 1 dot at 4. At which number is the peak, the tallest stack of dots?', '[]', '1', '1', 'The stacks have 4, 9, 6, 3 and 1 dots. The tallest stack, with 9 dots, is at 1, so the peak is at 1.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Stacks 4,9,6,3,1; tallest (9) at 1.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
