INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f6c4b68-3684-4607-8842-d21d4a5ecdc8', 'NC26.7.RD.3', 1, 'choice', 'Judge the overlap of two distributions', 'On the same number line, all the dots of Plot A are from 10 to 20, and all the dots of Plot B are from 30 to 40. Which statement is correct?', '["The plots overlap completely.","The plots overlap between 20 and 30.","The plots do not overlap: every value in Plot B is greater than every value in Plot A.","The plots overlap from 10 to 40."]', 'The plots do not overlap: every value in Plot B is greater than every value in Plot A.', NULL, 'A overlaps B only if some part of the number line is covered by both. A ends at 20 and B starts at 30, so no part is covered by both. The gap between 20 and 30 has no dots from either plot.', 'checked', '{"lint":[],"solve":{"answer":"The plots do not overlap: every value in Plot B is greater than every value in Plot A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A in [10,20], B in [30,40]; no overlap, all B values > all A values.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee96ce9f-aa75-4a9b-84a3-90221f414d28', 'NC26.7.RD.3', 1, 'numeric', 'Judge the overlap of two distributions', 'On one number line, the dots of Set A go from 4 to 12 and the dots of Set B go from 9 to 20. The sets overlap where both cover the same part of the number line. How long is the overlapping part?', '[]', '3', '12-9', 'Both sets cover the part of the number line from 9 (where B starts) to 12 (where A ends). Its length is 12 - 9 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Overlap [9,12], length 12-9=3.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8d9b890-d147-4b9b-bf7c-3bd8042287bf', 'NC26.7.RD.3', 1, 'numeric', 'Plot two distributions on one number line', 'Class A''s scores are 12, 15, 18 and 20. Class B''s scores are 14, 16, 22 and 25. You will draw both dot plots on one number line. How many units must the number line cover, from the least score to the greatest score?', '[]', '13', '25-12', 'The least score is 12 (Class A) and the greatest is 25 (Class B). The number line must cover at least 25 - 12 = 13 units.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Least 12, greatest 25; 25-12=13.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
