INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0700ab9d-6219-44b9-8656-f4b9c0079160', 'NC26.7.RD.3', 1, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the number of seconds students took to run a lap. The row for stem 3 has leaves 0, 2, 5. The row for stem 4 has leaves 1, 1, 7, 9. The row for stem 5 has leaves 2, 6. How many students are shown?', '[]', '9', '3+4+2', 'Each leaf is one student. Stem 3 has 3 leaves, stem 4 has 4 leaves and stem 5 has 2 leaves, so 3 + 4 + 2 = 9 students.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leaves 3+4+2=9.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
