INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca867a8a-0a37-4339-8371-8e8a433bb994', 'NC26.7.RD.3', 1, 'choice', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot of lengths has the key 3 | 1 means 3.1 meters. One row is: 3 | 1 2 8. Which list shows the lengths in that row?', '["3.1, 3.2, 3.8","31, 32, 38","3.1, 2.8","0.31, 0.32, 0.38"]', '3.1, 3.2, 3.8', NULL, 'The stem is the ones digit and each leaf is the tenths digit. The row 3 | 1 2 8 stands for 3.1, 3.2 and 3.8 meters.', 'checked', '{"lint":[],"solve":{"answer":"3.1, 3.2, 3.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Key 3|1 = 3.1, so 3|1 2 8 = 3.1, 3.2, 3.8.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
