INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e63f17f5-1f62-48b7-b03d-30c248f7ae5d', 'NC26.7.RD.3', 1, 'numeric', 'Read a histogram or grouped frequency table', 'A histogram shows the ages of people at a library event. The bars are 0 to 9 years: 6 people; 10 to 19 years: 11 people; 20 to 29 years: 4 people; 30 to 39 years: 3 people. How many people are younger than 20?', '[]', '17', '6+11', 'People younger than 20 are in the first two bars: 6 + 11 = 17 people.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0-9: 6, 10-19: 11; 6+11=17.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
