INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e110f47-f5b8-416c-8976-04730e89dae1', 'NC26.7.RD.3', 1, 'choice', 'Read a box plot from its five-number summary', 'About what fraction of the values in a data set lie inside the box of its box plot, between the first quartile and the third quartile?', '["About one quarter","About three quarters","About one half","All of them"]', 'About one half', NULL, 'The quartiles split the data into four parts with about the same number of values. The box holds the middle two parts, which is about one half of the values.', 'checked', '{"lint":[],"solve":{"answer":"About one half","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Box from Q1 to Q3 holds the middle half.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
