INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85574c4a-0f28-48a5-9a2f-56326166a9e8', 'NC26.7.RD.3', 1, 'choice', 'Draw a conclusion the data support', 'In a school race, the runners in Group A had a median time of 25 minutes. The runners in Group B had a median time of 30 minutes. The two groups had about the same spread. Which conclusion is best supported?', '["Group B''s times were typically greater than Group A''s times.","Every runner in Group B was slower than every runner in Group A.","Group A''s times were more spread out than Group B''s times.","Group A''s times were typically greater than Group B''s times."]', 'Group B''s times were typically greater than Group A''s times.', NULL, 'Group B''s median is 5 minutes greater, so its times are typically greater. A median does not show that every runner in B was slower, and the spreads were about the same.', 'checked', '{"lint":[],"solve":{"answer":"Group B''s times were typically greater than Group A''s times.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Similar spread, B median 30 > A 25: B''s times typically greater. ''Every runner'' not supported.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bf71f10-aadc-40e2-aa7d-3dd6c4e2ae89', 'NC26.7.RD.3', 1, 'choice', 'Draw a conclusion the data support', 'A stand sold these cups of lemonade on five sunny days: 18, 20, 21, 22, 24. It sold these on five cloudy days: 14, 15, 17, 18, 19. Which statement does the data support?', '["The stand sold more cups on every sunny day than on every cloudy day.","The sales on cloudy days had the greater range.","The stand typically sold more cups on sunny days.","The median number of cups was greater on cloudy days."]', 'The stand typically sold more cups on sunny days.', NULL, 'The sunny-day median is 21 and the cloudy-day median is 17, so sunny days typically had more sales. But 18 cups were sold on a sunny day and also on a cloudy day, so it is not true for every day. The sunny days had the greater range (6 compared with 5).', 'checked', '{"lint":[],"solve":{"answer":"The stand typically sold more cups on sunny days.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sunny median 21, range 6; cloudy median 17, range 5. Sunny typically more. Not every day: cloudy 19 > sunny 18.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ee7d7a7-1188-4eb1-aaae-0c135ce66b52', 'NC26.7.RD.3', 1, 'numeric', 'Compare two dot plots', 'Two dot plots share one number line. Plot A has dots at 2, 3, 3, 5, 8 and 9. Plot B has dots at 4, 6, 6, 7, 9 and 9. How many more dots does Plot B have than Plot A at values greater than 5?', '[]', '3', '5-2', 'Plot B has dots at 6, 6, 7, 9 and 9 above 5, which is 5 dots. Plot A has dots at 8 and 9 above 5, which is 2 dots. The difference is $5 - 2 = 3$ dots.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A >5: 8, 9 = 2 dots. B >5: 6, 6, 7, 9, 9 = 5 dots. 5-2=3.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
