INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3164b8fa-a4fc-4ced-808d-7b7d8c38e499', 'NC26.7.RD.3', 2, 'choice', 'Plot two distributions on one number line', 'Why should two dot plots that are being compared be drawn on the same number line, with the same scale?', '["So both plots will have the same number of dots.","So both plots will have the same mean.","So both plots will have the same range.","So the positions of the dots can be compared directly."]', 'So the positions of the dots can be compared directly.', NULL, 'Only when both plots use the same scale does a dot that is farther right mean a greater value in either plot. The number of dots, the mean and the range depend on the data, not on how the line is drawn.', 'checked', '{"lint":[],"solve":{"answer":"So the positions of the dots can be compared directly.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same scale lets dot positions be compared directly; it does not change means, ranges or counts.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78ff1744-92a9-4a6a-9515-ac1bc5d8510f', 'NC26.7.RD.3', 2, 'choice', 'Plot two distributions on one number line', 'Group A''s heights run from 140 to 185 centimeters. Group B''s heights run from 152 to 190 centimeters. Which is the best number line for drawing both dot plots?', '["From 0 to 200, with a mark every 50 centimeters","From 150 to 200, with a mark every 10 centimeters","From 140 to 190, with a mark every 5 centimeters","From 140 to 185, with a mark every 5 centimeters"]', 'From 140 to 190, with a mark every 5 centimeters', NULL, 'The line must reach from the least value, 140, to the greatest value, 190, and marks every 5 centimeters make it easy to place the dots. From 0 to 200 with marks every 50 is too coarse, and the other two lines cut off the heights from 140 to 149 or the heights above 185.', 'checked', '{"lint":[],"solve":{"answer":"From 140 to 190, with a mark every 5 centimeters","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 140 to 190. 150-200 misses 140-149; 140-185 misses 186-190; 0-200 by 50s too coarse. Best: 140-190 by 5s.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dfc0738-67fb-4f86-82ee-e11edeb0b6a5', 'NC26.7.RD.3', 2, 'numeric', 'Plot two distributions on one number line', 'Plot A has dots at 2, 4, 4, 6. Plot B has dots at 3, 4, 5, 5, 9. The two plots are drawn together on one number line, so there are 9 dots in all. What is the median of the 9 values?', '[]', '4', '4', 'Put all 9 values in order: 2, 3, 4, 4, 4, 5, 5, 6, 9. The middle (5th) value is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Combined sorted 2,3,4,4,4,5,5,6,9; median 5th value = 4.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5729725b-5056-42d9-97e1-244eb4e140cb', 'NC26.7.RD.3', 2, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the weights of ten dogs in pounds. Stem 5 has leaves 2, 4, 7. Stem 6 has leaves 0, 1, 5, 5, 8. Stem 7 has leaves 3, 6. A stem of 5 and a leaf of 2 means 52. What is the median weight?', '[]', '63', '(61+65)/2', 'The ten weights in order are 52, 54, 57, 60, 61, 65, 65, 68, 73, 76. With 10 values, the median is the mean of the 5th and 6th: (61 + 65) / 2 = 63.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"52,54,57,60,61,65,65,68,73,76 (10 values). Median (61+65)/2=63.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba2a0ccb-957d-4a07-868d-992d3c03aa84', 'NC26.7.RD.3', 2, 'numeric', 'Read a stem-and-leaf plot', 'Two classes took a quiz. Class A: stem 6 has leaves 5, 8; stem 7 has leaves 0, 2, 4, 6; stem 8 has leaves 1, 5. Class B: stem 6 has leaves 0, 2; stem 7 has leaves 3, 5, 5; stem 8 has leaves 0, 2, 7, 9. A stem of 8 and a leaf of 1 means 81. How many more students in Class B than in Class A scored 80 or above?', '[]', '2', '4-2', 'Class A has two scores of 80 or above (81 and 85). Class B has four (80, 82, 87 and 89). The difference is 4 - 2 = 2 students.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 80+: 81,85 = 2. B 80+: 80,82,87,89 = 4. 4-2=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffad579d-345d-4b6b-8529-bba4c4663297', 'NC26.7.RD.3', 2, 'choice', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot has these rows: stem 2 with leaves 1, 3, 3, 8; stem 3 with leaves 0, 4, 5; stem 4 with leaf 2. A stem of 2 and a leaf of 1 means 21. Which statement is true?', '["Exactly half of the values are in the 20s.","The median is 30.","The range is 31.","The mode is 3."]', 'Exactly half of the values are in the 20s.', NULL, 'The values are 21, 23, 23, 28, 30, 34, 35, 42. Four of the eight are in the 20s, which is half. The median is (28 + 30) / 2 = 29, the range is 42 - 21 = 21, and the mode is 23 (the leaf 3 appears twice, but the value is 23).', 'checked', '{"lint":[],"solve":{"answer":"Exactly half of the values are in the 20s.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values 21,23,23,28,30,34,35,42 (8). In 20s: 4 of 8 = half (true). Mode 23 not 3; range 21 not 31; median (28+30)/2=29 not 30.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c5bbeb5-d887-41ca-9cb1-087f7a263b2c', 'NC26.7.RD.3', 2, 'numeric', 'Read a histogram or grouped frequency table', 'A histogram shows the minutes 25 students spent on homework. The bars are 0 to 9 minutes: 3 students; 10 to 19 minutes: 7 students; 20 to 29 minutes: 9 students; 30 to 39 minutes: 4 students; 40 to 49 minutes: 2 students. How many students spent at least 20 minutes but fewer than 40 minutes?', '[]', '13', '9+4', 'The intervals from 20 up to (not including) 40 are 20 to 29 and 30 to 39. They hold 9 + 4 = 13 students.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20-29: 9, 30-39: 4; 9+4=13.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be9e7b98-1754-49cf-b787-c44945437986', 'NC26.7.RD.3', 2, 'choice', 'Read a histogram or grouped frequency table', 'A histogram of 40 quiz scores has these bars: 0 to 9: 7 scores; 10 to 19: 12 scores; 20 to 29: 10 scores; 30 to 39: 11 scores. In which interval is the median score?', '["10 to 19","30 to 39","20 to 29","0 to 9"]', '20 to 29', NULL, 'With 40 scores the median is between the 20th and 21st scores. Counting up from the left: 7 scores are in the first bar and 7 + 12 = 19 by the end of the second. The 20th and 21st scores are in the third bar, 20 to 29. (The tallest bar, 10 to 19, does not hold the middle.)', 'checked', '{"lint":[],"solve":{"answer":"20 to 29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 scores, median between 20th and 21st. Cumulative 7, 19, 29, 40: both in 20-29.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b777330-9260-44e2-9d6d-664d3e1dd66d', 'NC26.7.RD.3', 2, 'numeric', 'Read a histogram or grouped frequency table', 'A histogram shows the heights of 20 bean plants. The bars are 10 to 19 centimeters: 3 plants; 20 to 29 centimeters: 8 plants; 30 to 39 centimeters: 6 plants; 40 to 49 centimeters: 3 plants. What fraction of the plants are at least 30 centimeters tall?', '[]', '9/20', '(6+3)/20', 'The plants that are at least 30 centimeters tall are in the last two bars: 6 + 3 = 9 plants. That is 9 out of 20, or 9/20.', 'checked', '{"lint":[],"solve":{"answer":"9/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At least 30: 6+3=9 of 20 = 9/20.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('563d0d8d-f829-4a39-be32-7d3d1480b64e', 'NC26.7.RD.3', 2, 'numeric', 'Read a box plot from its five-number summary', 'Box plot A has a first quartile of 20 and a third quartile of 30. Box plot B has a first quartile of 25 and a third quartile of 55. The box of plot B is how many times as long as the box of plot A?', '[]', '3', '(55-25)/(30-20)', 'The box of A has length 30 - 20 = 10. The box of B has length 55 - 25 = 30. Since 30 / 10 = 3, the box of B is 3 times as long.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A box 30-20=10; B box 55-25=30; 30/10=3.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7752977-f0e8-43d4-ae56-749e06d51e6a', 'NC26.7.RD.3', 2, 'choice', 'Read a box plot from its five-number summary', 'Each box plot is summarized by its minimum, first quartile, median, third quartile and maximum. Plot P: 12, 20, 25, 30, 40. Plot Q: 22, 26, 30, 34, 38. Which statement is correct?', '["Plot P''s median is greater, and Plot P is more spread out by both its range and its IQR.","Plot Q''s median is greater, and Plot Q is more spread out by both its range and its IQR.","Plot Q''s median is greater, but Plot Q has the greater range.","Plot Q''s median is greater, but Plot P is more spread out by both its range and its IQR."]', 'Plot Q''s median is greater, but Plot P is more spread out by both its range and its IQR.', NULL, 'The medians are 25 and 30, so Q''s is greater. Plot P has a range of 40 - 12 = 28 and an IQR of 30 - 20 = 10. Plot Q has a range of 38 - 22 = 16 and an IQR of 34 - 26 = 8. P is more spread out by both measures.', 'checked', '{"lint":[],"solve":{"answer":"Plot Q''s median is greater, but Plot P is more spread out by both its range and its IQR.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: median 25, range 28, IQR 10. Q: median 30, range 16, IQR 8. Q''s median greater; P more spread by both.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b06186f0-3750-425d-8bb4-fd36a6a38dcf', 'NC26.7.RD.3', 2, 'numeric', 'Read a box plot from its five-number summary', 'A box plot shows the finishing times of 60 runners. The third quartile is 14 minutes. About how many runners had a time greater than 14 minutes?', '[]', '15', '60/4', 'One quarter of the values lie above the third quartile. One quarter of 60 is 60 / 4 = 15 runners.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"About a quarter of values exceed Q3: 60/4=15.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c3882ebc-cd9c-4e33-91ba-b3ef23a6bf59', 'NC26.7.RD.3', 2, 'choice', 'Draw a conclusion the data support', 'Commute times in minutes for five people in Town A were 10, 12, 15, 18, 20. For five people in Town B they were 8, 14, 16, 22, 40. Which statement is NOT supported by the data?', '["Town B has the greater range of commute times.","Town A''s commute times are more spread out than Town B''s.","Town B''s median commute time is greater than Town A''s.","Town B''s longest commute is longer than Town A''s longest commute."]', 'Town A''s commute times are more spread out than Town B''s.', NULL, 'Town A''s range is 20 - 10 = 10 minutes and Town B''s range is 40 - 8 = 32 minutes, so Town B is the more spread out. The other three statements are true: B''s range is greater, B''s median (16) is greater than A''s (15), and 40 is greater than 20.', 'checked', '{"lint":[],"solve":{"answer":"Town A''s commute times are more spread out than Town B''s.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: range 10, median 15. B: range 32, median 16, max 40. A more spread out is false.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c78a5d5-7e3c-4d18-886f-e6d91e9e3bcb', 'NC26.7.RD.3', 2, 'choice', 'Draw a conclusion the data support', 'Tara scored 8, 9, 10, 11, 12 points in five games. Uri scored 2, 6, 10, 14, 18 points in five games. Both have a mean of 10 points. Which statement is best supported by the data?', '["Uri was more consistent, because his scores vary more.","Neither was more consistent, because their means are equal.","Tara was more consistent, because her scores vary less.","Uri was more consistent, because he had the greatest score."]', 'Tara was more consistent, because her scores vary less.', NULL, 'Tara''s scores stay within 4 points of each other and Uri''s differ by 16, so Tara''s scores vary less: she was more consistent. Equal means do not make equal consistency, and one high score does not make a player consistent.', 'checked', '{"lint":[],"solve":{"answer":"Tara was more consistent, because her scores vary less.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Tara range 4, Uri range 16: Tara varies less, more consistent.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a72d6f5-9723-4e70-932d-3936258980b8', 'NC26.7.RD.3', 2, 'choice', 'Draw a conclusion the data support', 'Group A walked between 4 and 12 thousand steps a day, with a median of 8. Group B walked between 5 and 13 thousand steps a day, with a median of 9. A student says, "Every person in Group B walks more than every person in Group A." Which reply is best?', '["No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.","Yes: Group B has the greater median, 9, so all of its values are greater.","Yes: Group B''s greatest value, 13, is greater than Group A''s greatest value, 12.","No: both groups have a range of 8, so the two groups must be identical."]', 'No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.', NULL, 'The claim is about every person, so one counterexample is enough. Group A has a value of 12, which is more than Group B''s least value of 5. So some person in Group A walks more than some person in Group B, and the claim is not supported. A greater median or a greater maximum does not mean every value is greater, and equal ranges do not make two groups identical.', 'checked', '{"lint":[],"solve":{"answer":"No: Group A''s greatest value, 12, is greater than Group B''s least value, 5.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges overlap (A up to 12, B from 5), so someone in A may walk more than someone in B. The correct reply cites that overlap.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8f77338-927b-42d6-b5f6-4efe3ebc0037', 'NC26.7.RD.3', 3, 'choice', 'Compare mean and median of two sets', 'Data set P has the values 18, 19, 20, 21, 22. Data set Q has the values 18, 19, 20, 21, 42. Which statement is true?', '["The means are equal, but Q has the greater median","The medians are equal, but Q has the greater mean","The medians and the means are both equal","Q has both the greater median and the greater mean"]', 'The medians are equal, but Q has the greater mean', NULL, 'Both sets have a middle value of 20, so the medians are equal. The mean of P is $100 \div 5 = 20$. The mean of Q is $120 \div 5 = 24$. The large value 42 pulls the mean of Q up but does not change its median.', 'checked', '{"lint":[],"solve":{"answer":"The medians are equal, but Q has the greater mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both medians 20. Mean P = 100/5 = 20; mean Q = 120/5 = 24.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('938333c1-6a65-4cbe-a090-dab9b2231197', 'NC26.7.RD.3', 3, 'numeric', 'Compare medians of sets with an even count', 'Set A has the values 14, 9, 21, 12, 17, 15. Set B has the values 22, 30, 25, 28, 27, 24. How much greater is the median of Set B than the median of Set A?', '[]', '11.5', '(25+27)/2-(14+15)/2', 'Order Set A: 9, 12, 14, 15, 17, 21. With 6 values, the median is the mean of the middle two: $(14 + 15) \div 2 = 14.5$. Order Set B: 22, 24, 25, 27, 28, 30. Its median is $(25 + 27) \div 2 = 26$. The difference is $26 - 14.5 = 11.5$.', 'checked', '{"lint":[],"solve":{"answer":"11.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted: 9, 12, 14, 15, 17, 21; median 14.5. B sorted: 22, 24, 25, 27, 28, 30; median 26. Difference 11.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e137ca13-7113-4de0-aa6b-42b2ef189252', 'NC26.7.RD.3', 3, 'numeric', 'Read two distributions plotted together', 'Two dot plots share one number line, and both have a mean of 5. Plot X has 1 dot at 3, 2 dots at 4, 6 dots at 5, 2 dots at 6 and 1 dot at 7. Plot Y has 4 dots at 2, 4 dots at 5 and 4 dots at 8. In all, how many dots (from both plots) are 2 or more units away from 5?', '[]', '10', '1+1+4+4', 'Dots 2 or more units from 5 are at values 3 or less, or 7 or more. In plot X, that is 1 dot at 3 and 1 dot at 7, which is 2 dots. In plot Y, the 4 dots at 2 and the 4 dots at 8 qualify, which is 8 dots. In all, $2 + 8 = 10$ dots.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: dots at 3 and 7 are 2 away: 1 + 1 = 2. Y: dots at 2 and 8 are 3 away: 4 + 4 = 8. Total 10. (Means check: X 60/12 = 5, Y 60/12 = 5.)","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f83649f-6593-484d-996c-0998f7ea3bb7', 'NC26.7.RD.3', 3, 'numeric', 'Compare the centers of two distributions', 'Set P is 8, 10, 12, 14, 16. Set Q has five values. Four of them are 10, 12, 15 and 17. The mean of Set Q is 4 greater than the mean of Set P. What is the fifth value of Set Q?', '[]', '26', '((8+10+12+14+16)/5+4)*5-(10+12+15+17)', 'The mean of Set P is 60 / 5 = 12, so the mean of Set Q is 16. Five values with a mean of 16 add to 16 x 5 = 80. The four known values add to 54, so the fifth value is 80 - 54 = 26.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P sum 8+10+12+14+16=60, mean 12. Q mean 16, sum 5*16=80. Known four 10+12+15+17=54. Fifth 80-54=26.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d420fdc-c712-4db9-9e4a-e82dcffcbf1b', 'NC26.7.RD.3', 3, 'numeric', 'Compare the centers of two distributions', 'Jo''s steps on 8 days, in hundreds of steps, were 31, 28, 35, 30, 34, 29, 36, 37. Kai''s steps on 7 days, in hundreds of steps, were 40, 38, 45, 42, 37, 44, 41. By how many hundreds of steps is the median of Kai''s days greater than the median of Jo''s days?', '[]', '8.5', '41-(31+34)/2', 'Jo in order: 28, 29, 30, 31, 34, 35, 36, 37. With 8 values the median is the mean of the 4th and 5th: (31 + 34) / 2 = 32.5. Kai in order: 37, 38, 40, 41, 42, 44, 45. The middle (4th) value is 41. The difference is 41 - 32.5 = 8.5.', 'checked', '{"lint":[],"solve":{"answer":"8.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Jo sorted 28,29,30,31,34,35,36,37 (8 values), median (31+34)/2=32.5. Kai sorted 37,38,40,41,42,44,45 (7 values), median 41. 41-32.5=8.5.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0568f81b-53aa-4063-94cf-70c3f23bd3f5', 'NC26.7.RD.3', 3, 'choice', 'Compare the centers of two distributions', 'Each choice shows two small data sets, A and B. In which choice is the median of B exactly 3 greater than the median of A?', '["A: 2, 5, 11 and B: 3, 6, 18","A: 1, 6, 8 and B: 2, 4, 11","A: 6, 2, 9 and B: 4, 5, 8","A: 2, 5, 9 and B: 3, 8, 9"]', 'A: 2, 5, 9 and B: 3, 8, 9', NULL, 'For A: 2, 5, 9 and B: 3, 8, 9 the medians are 5 and 8, which differ by 3. For A: 2, 5, 11 and B: 3, 6, 18 the means differ by 3 (6 and 9), but the medians are 5 and 6. For A: 1, 6, 8 and B: 2, 4, 11 the greatest values differ by 3, but the medians are 6 and 4. For A: 6, 2, 9 and B: 4, 5, 8 the lists are not in order; the true medians are 6 and 5.', 'checked', '{"lint":[],"solve":{"answer":"A: 2, 5, 9 and B: 3, 8, 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: medians 5 and 8, diff 3. B: 6 and 4. C: A sorted 2,6,9 median 6; B 4,5,8 median 5. D: 5 and 6. Only first choice works.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4d9e12d-2192-40d5-b786-d785bc3ec113', 'NC26.7.RD.3', 3, 'numeric', 'Compare the centers of two distributions', 'Set A has 8 values that add to 168. Set B also has 8 values, and the mean of Set B is 6 greater than the mean of Set A. What is the sum of the values in Set B?', '[]', '216', '(168/8+6)*8', 'The mean of Set A is 168 / 8 = 21. The mean of Set B is 21 + 6 = 27. Eight values with a mean of 27 add to 27 x 8 = 216. (Check: the sum rises by 6 for each of the 8 values, 48, and 168 + 48 = 216.)', 'checked', '{"lint":[],"solve":{"answer":"216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean A = 168/8 = 21. Mean B = 27. Sum B = 8*27 = 216.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77068a21-c467-4c6a-9b40-5b9a65a0c52d', 'NC26.7.RD.3', 3, 'numeric', 'Compare the spread of two distributions', 'Set A is 12, 15, 19, 22, 27, 30. Set B has the same least value as Set A, and its range is 7 greater than the range of Set A. What is the greatest value in Set B?', '[]', '37', '12+(30-12)+7', 'The range of A is 30 - 12 = 18. The range of B is 18 + 7 = 25. B starts at 12, so its greatest value is 12 + 25 = 37.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A 30-12=18. Range B 25. Least 12, greatest 12+25=37.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22f3b8fb-b4d8-4fdb-9168-248cd718098a', 'NC26.7.RD.3', 3, 'numeric', 'Compare the spread of two distributions', 'Eight students in Group A solved a puzzle in 22, 14, 30, 18, 26, 16, 34, 20 minutes. Eight students in Group B solved it in 19, 25, 21, 23, 27, 20, 24, 22 minutes. How much greater is the interquartile range of Group A''s times than that of Group B''s times?', '[]', '7', '((26+30)/2-(16+18)/2)-((24+25)/2-(20+21)/2)', 'Group A in order: 14, 16, 18, 20, 22, 26, 30, 34. Q1 = (16 + 18) / 2 = 17 and Q3 = (26 + 30) / 2 = 28, so IQR = 11. Group B in order: 19, 20, 21, 22, 23, 24, 25, 27. Q1 = (20 + 21) / 2 = 20.5 and Q3 = (24 + 25) / 2 = 24.5, so IQR = 4. The difference is 11 - 4 = 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted 14,16,18,20 | 22,26,30,34: Q1=17, Q3=28, IQR 11. B sorted 19,20,21,22 | 23,24,25,27: Q1=20.5, Q3=24.5, IQR 4. 11-4=7.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c39ac7fc-def0-4e2d-b20c-3844d9c53828', 'NC26.7.RD.3', 3, 'choice', 'Compare the spread of two distributions', 'Every value in a data set is increased by 5. How do the mean and the range of the data change?', '["The mean increases by 5, and the range increases by 5.","The mean stays the same, and the range increases by 5.","The mean increases by 5, and the range stays the same.","The mean and the range both stay the same."]', 'The mean increases by 5, and the range stays the same.', NULL, 'Adding 5 to every value slides the whole data set 5 units to the right, so the mean (and median) go up by 5. The distances between the values do not change, so the range is the same. Try 2, 4, 6: the range is 4 and the mean is 4; after adding 5 they are 7, 9, 11 with range 4 and mean 9.', 'checked', '{"lint":[],"solve":{"answer":"The mean increases by 5, and the range stays the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding 5 shifts mean by 5; max-min unchanged so range same.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9cee219-b174-42ee-99f4-efc2dab79ba0', 'NC26.7.RD.3', 3, 'choice', 'Compare the spread of two distributions', 'Plot A has 2 dots at 10 and 2 dots at 30. Plot B has 4 dots at 20. Which statement is correct?', '["Both plots have a mean of 20, but Plot A is more spread out.","Plot B has the greater mean, because its dots are stacked.","The plots have the same spread, because they have the same mean.","Both plots have a mean of 20, but Plot B is more spread out."]', 'Both plots have a mean of 20, but Plot A is more spread out.', NULL, 'Plot A: (10 + 10 + 30 + 30) / 4 = 20. Plot B: (20 + 20 + 20 + 20) / 4 = 20. The means are equal. Plot A has a range of 20 and Plot B has a range of 0, so A is more spread out. Equal means do not mean equal spread.', 'checked', '{"lint":[],"solve":{"answer":"Both plots have a mean of 20, but Plot A is more spread out.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A mean (10+10+30+30)/4=20, B mean 20. A spread 20, B spread 0. A more spread out.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8034359f-4ecb-450e-8a95-406f1d1bd576', 'NC26.7.RD.3', 3, 'choice', 'Describe the shape of a distribution', 'A dot plot has dots at 1, 1, 2, 2, 3, 3, 4, 5, 12, so most dots are at low values and one dot is far to the right. Which statement is true?', '["The mean is less than the median, because of the dot at 12.","The mean and the median are equal, because the plot is balanced.","The median is greater than 5, because of the dot at 12.","The mean is greater than the median, because of the dot at 12."]', 'The mean is greater than the median, because of the dot at 12.', NULL, 'The sum is 33, so the mean is 33 / 9, about 3.7. The middle (5th) value is 3, so the median is 3. A long tail of high values pulls the mean up toward the tail, but it barely moves the median.', 'checked', '{"lint":[],"solve":{"answer":"The mean is greater than the median, because of the dot at 12.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 1+1+2+2+3+3+4+5+12=33, mean 33/9 ~ 3.67. Median 5th of 9 = 3. Mean > median, pulled up by 12.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8816d175-9c87-44ab-b5b9-bc6f0d5005fc', 'NC26.7.RD.3', 3, 'numeric', 'Describe the shape of a distribution', 'A symmetric dot plot has 1 dot at 2, 2 dots at 3, 3 dots at 4, 6 dots at 5, 3 dots at 6, 2 dots at 7 and 1 dot at 8. How many dots are within 1 unit of the peak, counting the dots at the peak itself?', '[]', '12', '3+6+3', 'The peak is at 5, the tallest stack. Within 1 unit of 5 are the values 4, 5 and 6, which have 3 + 6 + 3 = 12 dots.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Peak at 5 (6 dots). Within 1 unit: values 4,5,6 -> 3+6+3=12.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d7cc52e-dad8-4c7e-b855-561ba9c9190b', 'NC26.7.RD.3', 3, 'choice', 'Describe the shape of a distribution', 'A dot plot has dots at 14, 15, 15, 16, 16, 16, 17, 17, 18, 31. The dot at 31 is far from all the others. What happens when that one dot is removed?', '["The mean decreases from 17.5 to 16, and the median stays at 16.","The mean decreases from 17.5 to 16, and the median decreases to 15.","The mean stays at 17.5, and the median decreases to 15.","The mean and the median both stay the same."]', 'The mean decreases from 17.5 to 16, and the median stays at 16.', NULL, 'With all 10 values the sum is 175, so the mean is 17.5, and the median is (16 + 16) / 2 = 16. Without 31, the sum is 144 and the mean is 144 / 9 = 16. The middle (5th) of the 9 remaining values is still 16. The extreme value changed the mean, not the median.', 'checked', '{"lint":[],"solve":{"answer":"The mean decreases from 17.5 to 16, and the median stays at 16.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 14+15+15+16+16+16+17+17+18+31=175, mean 17.5; median (16+16)/2=16. Without 31: sum 144, 9 values, mean 16; median 5th of 14,15,15,16,16,16,17,17,18 = 16.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14af8042-6676-4fec-b06e-fa883450c3c0', 'NC26.7.RD.3', 3, 'choice', 'Judge the overlap of two distributions', 'Set A is 40, 42, 45, 47, 50, 52. Set B is 51, 53, 55, 56, 58, 60. Which statement is correct?', '["Every value in Set B is greater than every value in Set A.","The sets overlap heavily, and their centers are about equal.","The sets overlap only between 51 and 52, and Set A''s center is much greater.","The sets overlap only between 51 and 52, and Set B''s center is much greater."]', 'The sets overlap only between 51 and 52, and Set B''s center is much greater.', NULL, 'A''s greatest value is 52 and B''s least value is 51, so the sets share only the stretch from 51 to 52. That is almost no overlap, but not none: 52 is not less than 51. The medians are 46 and 55.5, so B''s center is 9.5 greater.', 'checked', '{"lint":[],"solve":{"answer":"The sets overlap only between 51 and 52, and Set B''s center is much greater.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 40-52, median 46; B 51-60, median 55.5. Overlap only 51-52 (B''s 51 < A''s 52, so ''every value'' false). B''s center ~9.5 greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61dbd2b3-de2f-406a-a598-0bb2ca61c043', 'NC26.7.RD.3', 3, 'numeric', 'Judge the overlap of two distributions', 'Set A has a mean of 30 and a mean absolute deviation (MAD) of 4. Set B has a mean of 42 and a MAD of 4. The difference between the means is how many times the MAD?', '[]', '3', '(42-30)/4', 'The difference between the means is 42 - 30 = 12. Since the MAD is 4, the difference is 12 / 4 = 3 times the MAD. The bigger this number is, the less the two sets overlap.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(42-30)/4 = 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a551bd5a-dbdf-4092-ac01-a2f733e58f95', 'NC26.7.RD.3', 3, 'choice', 'Judge the overlap of two distributions', 'Pair P is two data sets with means of 40 and 52, each with a MAD of 3. Pair Q is two data sets with means of 40 and 52, each with a MAD of 10. Which statement is correct?', '["The two sets in Pair Q overlap less, because their MADs are greater.","The two sets in Pair P overlap less than the two sets in Pair Q.","The two pairs overlap equally, because the means are the same.","The two sets in Pair P overlap more, because their MADs are smaller."]', 'The two sets in Pair P overlap less than the two sets in Pair Q.', NULL, 'The means are 12 apart in both pairs. In Pair P the values typically stay within about 3 of their mean, so the two sets barely touch (12 is 4 times the MAD). In Pair Q the values stray about 10 from their mean, so the sets overlap a lot (12 is only 1.2 times the MAD).', 'checked', '{"lint":[],"solve":{"answer":"The two sets in Pair P overlap less than the two sets in Pair Q.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same mean gap 12. Small MAD (3) means tight sets so Pair P overlaps less; MAD 10 sets overlap more.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76a8f804-814a-430e-8b07-98666a5e8338', 'NC26.7.RD.3', 3, 'numeric', 'Plot two distributions on one number line', 'Class 1''s 5 scores have a mean of 8. Class 2''s 3 scores have a mean of 12. When all 8 scores are put on one number line, what is the mean of all of them?', '[]', '9.5', '(5*8+3*12)/8', 'Class 1 adds to 5 x 8 = 40 and Class 2 adds to 3 x 12 = 36. All 8 scores add to 76, so the mean is 76 / 8 = 9.5. (It is not 10, the mean of 8 and 12, because Class 1 has more scores.)', 'checked', '{"lint":[],"solve":{"answer":"9.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total (5*8)+(3*12)=40+36=76; 76/8=9.5.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ae016ff-a04f-4d33-b8c8-0ede74fc0ea7', 'NC26.7.RD.3', 3, 'choice', 'Plot two distributions on one number line', 'Set A has values from 0.2 to 1.4. Set B has values from 0.5 to 2.6. Which number line, with the marks shown, can display every value from both sets?', '["From 0.2 to 1.4, with a mark every 0.2","From 0 to 3, with a mark every 0.5","From 0 to 2, with a mark every 0.5","From 0.5 to 2.6, with a mark every 0.5"]', 'From 0 to 3, with a mark every 0.5', NULL, 'The values run from 0.2 up to 2.6. A number line from 0 to 3 covers all of them. The line ending at 1.4 and the line ending at 2 cut off the greater values of Set B, and the line starting at 0.5 cuts off 0.2.', 'checked', '{"lint":[],"solve":{"answer":"From 0 to 3, with a mark every 0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 0.2 to 2.6. 0.2-1.4 and 0-2 miss 2.6; 0.5-2.6 misses 0.2. 0 to 3 covers all.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b5f9f5b-3b01-4265-9b14-61f5825d60e2', 'NC26.7.RD.3', 3, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the masses of 11 rocks in kilograms. The key is 1 | 8 means 1.8 kilograms. Stem 1 has leaves 2, 5, 8, 8. Stem 2 has leaves 0, 1, 4, 4, 7. Stem 3 has leaves 3, 6. What is the median mass in kilograms?', '[]', '2.1', '21/10', 'The 11 masses in order are 1.2, 1.5, 1.8, 1.8, 2.0, 2.1, 2.4, 2.4, 2.7, 3.3, 3.6. The middle value is the 6th, which is 2.1 kilograms.', 'checked', '{"lint":[],"solve":{"answer":"2.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2,1.5,1.8,1.8,2.0,2.1,2.4,2.4,2.7,3.3,3.6 (11). Median 6th = 2.1.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4927b7b1-0473-43a1-91b0-153c71beb3d5', 'NC26.7.RD.3', 3, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows the number of cups of juice a shop sold each day. The key is 12 | 3 means 123. Stem 12 has leaves 3, 8. Stem 13 has leaves 0, 4, 4, 9. Stem 14 has leaves 2, 5, 6. Stem 15 has leaf 1. What is the range of the sales?', '[]', '28', '151-123', 'The least value is 123 (stem 12, leaf 3) and the greatest is 151 (stem 15, leaf 1). The range is 151 - 123 = 28 cups.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Least 123, greatest 151; 151-123=28.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0815b226-e008-4721-a586-ec4fef019561', 'NC26.7.RD.3', 3, 'choice', 'Read a stem-and-leaf plot', 'Two teams'' points in nine games are shown in a back-to-back stem-and-leaf plot. Team X: stem 3 has leaves 2, 6, 8; stem 4 has leaves 0, 1, 5, 5, 7; stem 5 has leaf 2. Team Y: stem 3 has leaf 1; stem 4 has leaves 4, 6; stem 5 has leaves 0, 3, 5, 7, 8, 9. A stem of 3 and a leaf of 2 means 32. Which statement is true?', '["Team X''s median is 12 greater than Team Y''s median.","Team Y''s median is 12 greater than Team X''s median.","Team X has the greater range of the two teams.","Both teams have the same median."]', 'Team Y''s median is 12 greater than Team X''s median.', NULL, 'Team X''s scores in order: 32, 36, 38, 40, 41, 45, 45, 47, 52, so the median is 41 and the range is 20. Team Y''s: 31, 44, 46, 50, 53, 55, 57, 58, 59, so the median is 53 and the range is 28. Y''s median is 53 - 41 = 12 greater, and Y has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Team Y''s median is 12 greater than Team X''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: 32,36,38,40,41,45,45,47,52, median 41, range 20. Y: 31,44,46,50,53,55,57,58,59, median 53, range 28. Y median 12 greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef5a8816-1ed8-4e9f-a4de-f21237054c27', 'NC26.7.RD.3', 3, 'numeric', 'Read a stem-and-leaf plot', 'A stem-and-leaf plot shows six ages. Stem 2 has leaves 1, 4. Stem 3 has leaves 0, 5, 8. Stem 4 has leaf 4. A stem of 2 and a leaf of 1 means 21. What is the mean age?', '[]', '32', '(21+24+30+35+38+44)/6', 'The ages are 21, 24, 30, 35, 38 and 44. They add to 192, and 192 / 6 = 32.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"21+24+30+35+38+44=192; 192/6=32.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7353bd93-c250-4743-abd1-ac847d25937b', 'NC26.7.RD.3', 3, 'numeric', 'Read a histogram or grouped frequency table', 'Two histograms use the same scores. Class A: 40 to 49: 2 students; 50 to 59: 6 students; 60 to 69: 9 students; 70 to 79: 3 students. Class B: 40 to 49: 1 student; 50 to 59: 3 students; 60 to 69: 8 students; 70 to 79: 8 students. How many more students in Class B than in Class A scored 60 or higher?', '[]', '4', '(8+8)-(9+3)', 'Class A: 9 + 3 = 12 students scored 60 or higher. Class B: 8 + 8 = 16 students. The difference is 16 - 12 = 4 students.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 60+: 9+3=12. B 60+: 8+8=16. 16-12=4.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cbcf711-ffea-4e7e-b193-29c3e1883d2e', 'NC26.7.RD.3', 3, 'choice', 'Read a histogram or grouped frequency table', 'Class A has 20 students and Class B has 40 students. In the histogram of Class A, the bar for scores of 80 to 89 shows 5 students. In the histogram of Class B, the bar for 80 to 89 shows 8 students. Which statement is correct?', '["A greater fraction of Class A scored 80 to 89, because 5 out of 20 is greater than 8 out of 40.","A greater fraction of Class B scored 80 to 89, because 8 students is more than 5 students.","The two classes had the same fraction score 80 to 89, because both bars are tall.","The two classes cannot be compared, because they have different numbers of students."]', 'A greater fraction of Class A scored 80 to 89, because 5 out of 20 is greater than 8 out of 40.', NULL, 'Compare fractions of each class, not counts. Class A: 5/20 = 1/4 = 25%. Class B: 8/40 = 1/5 = 20%. So a greater fraction of Class A scored 80 to 89, even though Class B has more such students.', 'checked', '{"lint":[],"solve":{"answer":"A greater fraction of Class A scored 80 to 89, because 5 out of 20 is greater than 8 out of 40.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5/20=1/4=0.25. B: 8/40=1/5=0.2. A greater fraction.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6406c93-d4d7-48df-9989-09b676a288de', 'NC26.7.RD.3', 3, 'choice', 'Read a box plot from its five-number summary', 'A box plot has a minimum of 10, a first quartile of 14, a median of 16, a third quartile of 28 and a maximum of 60. Which describes the data?', '["The data are skewed toward the low values.","The data are skewed toward the high values.","The data are symmetric, because the median is inside the box.","The data are evenly spread across the whole range."]', 'The data are skewed toward the high values.', NULL, 'The lower part of the box (14 to 16) is short and the upper part (16 to 28) is long. The upper whisker (28 to 60) is much longer than the lower whisker (10 to 14). The long tail is on the high side, so the data are skewed toward high values.', 'checked', '{"lint":[],"solve":{"answer":"The data are skewed toward the high values.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: ''skewed toward the high values'' vs ''toward the low values'' can be misread (most data ARE toward the low values). Clearer: ''skewed right, with a long tail toward the high values''.","work":"Left whisker 4, left box half 2, right box half 12, right whisker 32: long tail to the high side, i.e. skewed right.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f829a2df-22c6-4349-bf7a-7c9134ea5ed8', 'NC26.7.RD.3', 3, 'numeric', 'Read a box plot from its five-number summary', 'Box plot A has a median of 36 and an interquartile range of 8. Box plot B has a median of 52 and an interquartile range of 8. The difference between the medians is how many times the interquartile range?', '[]', '2', '(52-36)/8', 'The difference between the medians is 52 - 36 = 16. Since the interquartile range is 8, the difference is 16 / 8 = 2 times the IQR.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(52-36)/8 = 16/8 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf82799c-c1be-4732-b672-986e52f870bd', 'NC26.7.RD.3', 3, 'choice', 'Read a box plot from its five-number summary', 'A box plot has a minimum of 3, a first quartile of 9, a median of 14, a third quartile of 21 and a maximum of 38. Which statement is true?', '["Half of the values are greater than 21.","Three quarters of the values are less than 14.","A quarter of the values are between 9 and 21.","Half of the values are between 9 and 21."]', 'Half of the values are between 9 and 21.', NULL, 'The box, from the first quartile (9) to the third quartile (21), holds the middle half of the values. Only a quarter of the values are greater than 21, and half of the values are less than 14.', 'checked', '{"lint":[],"solve":{"answer":"Half of the values are between 9 and 21.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Middle half lies between Q1=9 and Q3=21. Others: quarter (wrong), half > 21 (only a quarter), 3/4 < 14 (only half).","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19913241-3a11-4839-adaa-4c015c39c9ef', 'NC26.7.RD.3', 3, 'numeric', 'Read a box plot from its five-number summary', 'In a box plot, the first quartile is 22, the median is 30, and the interquartile range is 16. What is the third quartile?', '[]', '38', '22+16', 'The interquartile range is the third quartile minus the first quartile, so the third quartile is 22 + 16 = 38.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q3 = Q1 + IQR = 22+16 = 38.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6dbeb479-a7d2-459a-ac55-16b89cfddaea', 'NC26.7.RD.3', 3, 'choice', 'Draw a conclusion the data support', 'A dot plot of the heights of 20 people at a youth center shows one cluster of dots from 50 to 56 inches and a second cluster from 66 to 72 inches, with no dots between 57 and 65 inches. Which is the most reasonable conclusion?', '["The data must contain mistakes, because heights should form one cluster.","The people probably come from two groups, such as children and adults, with different typical heights.","Most of the people are about 61 inches tall, the middle of the plot.","The people are all about the same height, because the dots are close together."]', 'The people probably come from two groups, such as children and adults, with different typical heights.', NULL, 'Two separate clusters with a gap between them suggest two different groups mixed together. Nobody is about 61 inches tall, since there are no dots there, and the dots are not all close together.', 'checked', '{"lint":[],"solve":{"answer":"The people probably come from two groups, such as children and adults, with different typical heights.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two separated clusters suggest two groups (e.g. children and adults) with different typical heights.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca0be6f7-979d-4439-84a8-291cbf3b6b49', 'NC26.7.RD.3', 3, 'choice', 'Draw a conclusion the data support', 'Set 1 is 10, 20, 20, 20, 20, 30. Set 2 is 10, 10, 10, 30, 30, 30. Maia says, "Both sets have a range of 20 and a mean of 20, so they are spread out in the same way." Which reply is correct?', '["She is not right: most of Set 1''s values are at the center, but every value of Set 2 is far from the center.","She is right: sets with the same range and mean must be spread out in the same way.","She is not right: Set 1 has the greater range.","She is not right: the two sets have different means."]', 'She is not right: most of Set 1''s values are at the center, but every value of Set 2 is far from the center.', NULL, 'Both sets have a range of 20 and a mean of 20. But four of Set 1''s six values equal 20, while every value of Set 2 is 10 away from 20. Set 2''s values are typically much farther from the mean, so Set 2 is more spread out.', 'checked', '{"lint":[],"solve":{"answer":"She is not right: most of Set 1''s values are at the center, but every value of Set 2 is far from the center.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 1 sum 120, mean 20, range 20; Set 2 sum 120, mean 20, range 20. Set 1 mostly at 20; Set 2 every value 10 from 20. Distributions differ.","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15d980f6-c67a-4c5f-8107-f65a86e63874', 'NC26.7.RD.3', 3, 'choice', 'Draw a conclusion the data support', 'Box plot X has a minimum of 30, a first quartile of 52, a median of 60, a third quartile of 70 and a maximum of 80. Box plot Y has a minimum of 20, a first quartile of 35, a median of 50, a third quartile of 55 and a maximum of 65. Which statement is true?', '["Every value in Plot X is greater than Plot Y''s median.","Plot Y''s median is greater than Plot X''s first quartile.","Half of Plot Y''s values are greater than Plot X''s median.","At least three quarters of Plot X''s values are greater than Plot Y''s median."]', 'At least three quarters of Plot X''s values are greater than Plot Y''s median.', NULL, 'Plot Y''s median is 50 and Plot X''s first quartile is 52, so at least three quarters of X''s values are above 50. But X''s minimum is 30, so not every value is. 50 is less than 52, so Plot Y''s median is not greater than Plot X''s first quartile. Y''s third quartile is 55, below X''s median of 60, so fewer than a quarter of Y''s values are above 60.', 'checked', '{"lint":[],"solve":{"answer":"At least three quarters of Plot X''s values are greater than Plot Y''s median.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Y median 50. X Q1=52>50, so at least 75% of X values >50. Others: Y Q3 55 < X median 60 (false); 50<52 (false); X min 30<50 (false).","run_id":"claude-code","at":"2026-10-17T20:26:48.180Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b30f388-6b93-430b-8029-3a3cb382e94a', 'NC26.7.RD.3', 3, 'numeric', 'Compare two distributions on one number line', 'Dot plots of two classes'' quiz scores share one number line. Class X has scores 52, 55, 58, 60, 63 and 70, and its median is 59. Class Y has scores 48, 61, 62, 66, 71 and 73. How many more of Class Y''s scores than of Class X''s scores are greater than 59?', '[]', '2', '5-3', 'In Class X, the scores greater than 59 are 60, 63 and 70, which is 3 scores. In Class Y, the scores greater than 59 are 61, 62, 66, 71 and 73, which is 5 scores. The difference is $5 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X median (58+60)/2=59 checks. X above 59: 60, 63, 70 = 3. Y above 59: 61, 62, 66, 71, 73 = 5. 5-3=2.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9284fc1b-3e01-400e-813a-b87eb9032c5c', 'NC26.7.RD.4', 1, 'numeric', 'Range', 'A set of data is 12, 7, 15, 9, 20, 11. What is the range?', '[]', '13', '20-7', 'The range is the greatest value minus the least value: $20 - 7 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Max 20, min 7; range 13.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
