INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c531e2e3-ea80-403e-9c65-991366905efc', 'NC26.7.RD.4', 1, 'numeric', 'Find the range of a data set', 'The heights of five bean plants, in centimeters, are 14, 9, 21, 17 and 12. What is the range of the heights?', '[]', '12', '21-9', 'The range is the greatest value minus the least value: 21 - 9 = 12 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 21, least 9: 21-9=12.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
