INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c013b02e-26f4-485e-aae2-4eaef85d4cb2', 'NC26.7.RD.4', 1, 'numeric', 'Find the range of a data set', 'The oldest member of a hiking club is 68 years old and the youngest member is 23 years old. What is the range of the members'' ages in years?', '[]', '45', '68-23', 'The range is the greatest value minus the least value: 68 - 23 = 45 years.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"68-23=45.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
