INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae4ad8ed-50ba-4710-a1aa-be51e3f916ac', 'NC26.7.RD.4', 1, 'choice', 'Find the range of a data set', 'Which data set has a range of 9?', '["9, 14, 6","7, 9, 20","15, 6, 9","2, 9, 4"]', '15, 6, 9', NULL, 'The range of 15, 6, 9 is 15 - 6 = 9. The others have ranges of 14 - 6 = 8, 20 - 7 = 13 and 9 - 2 = 7. Each of those contains the number 9, but the range is the greatest minus the least value.', 'checked', '{"lint":[],"solve":{"answer":"15, 6, 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7,9,20 -> 13; 2,9,4 -> 7; 15,6,9 -> 15-6=9; 9,14,6 -> 8.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
