INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7855869-5898-4a78-af84-039597bd5b45', 'NC26.7.RD.4', 1, 'numeric', 'Find the range of a data set', 'In seven soccer games, a team scored 3, 0, 4, 1, 4, 2 and 6 goals. What is the range of the numbers of goals?', '[]', '6', '6-0', 'The greatest number of goals is 6 and the least is 0, so the range is 6 - 0 = 6 goals.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 6, least 0: 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
