INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87e903ed-410b-4203-91bb-2ebf8697047d', 'NC26.7.RD.4', 1, 'choice', 'Find the range of a data set', 'Which calculation gives the range of a data set?', '["greatest value - least value","greatest value + least value","greatest value / least value","(greatest value + least value) / 2"]', 'greatest value - least value', NULL, 'The range tells how far apart the ends of the data are, so it is the greatest value minus the least value.', 'checked', '{"lint":[],"solve":{"answer":"greatest value - least value","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = greatest - least.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
