INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5cea6a9-7890-4051-b4e4-02bccfdcbffa', 'NC26.7.RD.4', 1, 'numeric', 'Find the interquartile range', 'A summary of test scores gives a least score of 41, a first quartile of 58, a median of 67, a third quartile of 79 and a greatest score of 96. What is the interquartile range?', '[]', '21', '79-58', 'The interquartile range (IQR) is the third quartile minus the first quartile: 79 - 58 = 21. (The other numbers are not needed.)', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = Q3-Q1 = 79-58 = 21.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93797897-3929-41b2-8c90-652b976abe28', 'NC26.7.RD.4', 1, 'choice', 'Find the interquartile range', 'What does the interquartile range (IQR) of a data set measure?', '["The difference between the greatest and least values","How far the values are from the mean on average","The value in the middle of the data set","How spread out the middle half of the values is"]', 'How spread out the middle half of the values is', NULL, 'The IQR is the third quartile minus the first quartile, which is the length of the interval holding the middle half of the values. The difference between the greatest and least is the range, the average distance from the mean is the MAD, and the middle value is the median.', 'checked', '{"lint":[],"solve":{"answer":"How spread out the middle half of the values is","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = Q3-Q1, spread of the middle half.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ca57a5d-1c2b-4e69-9740-91f27a930c90', 'NC26.7.RD.4', 1, 'numeric', 'Find the interquartile range', 'Find the interquartile range of the data 3, 5, 7, 9, 11 and 13.', '[]', '6', '(11)-(5)', 'The lower half is 3, 5, 7 with median 5, so Q1 = 5. The upper half is 9, 11, 13 with median 11, so Q3 = 11. The IQR is 11 - 5 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,5,7 | 9,11,13: Q1=5, Q3=11, IQR 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18debec1-7fef-4be2-a8fd-957f38873649', 'NC26.7.RD.4', 1, 'numeric', 'Find the mean absolute deviation', 'The mean of the data 3, 5, 9, 11 is 7. What is the mean absolute deviation (MAD) of the data?', '[]', '3', '(16+8+8+16)/16', 'The distances from the mean 7 are 4, 2, 2 and 4. Their mean is (4 + 2 + 2 + 4) / 4 = 12 / 4 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 7: 4,2,2,4, sum 12; 12/4=3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43f2a748-f8d2-4ff6-bb25-d3c5c55ab74d', 'NC26.7.RD.4', 1, 'numeric', 'Find the mean absolute deviation', 'Five values have distances from their mean of 2, 0, 3, 1 and 4 units. What is the mean absolute deviation (MAD) of the five values?', '[]', '2', '(2+0+3+1+4)/5', 'The MAD is the mean of the distances from the mean: (2 + 0 + 3 + 1 + 4) / 5 = 10 / 5 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2+0+3+1+4)/5 = 10/5 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed5d67da-8d8c-4628-a539-be2807d9721a', 'NC26.7.RD.4', 1, 'choice', 'Find the mean absolute deviation', 'What is the first step in finding the mean absolute deviation of a data set?', '["Find the median of the data","Put the values in order from least to greatest","Square each value","Find the mean of the data"]', 'Find the mean of the data', NULL, 'The MAD measures the distances of the values from the MEAN, so the mean must be found first. Then find each value''s distance from it, and take the mean of those distances.', 'checked', '{"lint":[],"solve":{"answer":"Find the mean of the data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD needs distances from the mean, so first find the mean.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb9f4b9c-d3b8-4162-b553-3c23ed067ef3', 'NC26.7.RD.4', 1, 'choice', 'Interpret range, IQR and MAD', 'Class A''s quiz scores have a MAD of 1.5 points. Class B''s quiz scores have a MAD of 4 points. Which class''s scores are closer to their mean on average?', '["Class A","Class B","Both classes are the same","It cannot be told from the MAD"]', 'Class A', NULL, 'The MAD is the average distance of the values from the mean. A smaller MAD means the scores are closer to the mean, so Class A''s scores are.', 'checked', '{"lint":[],"solve":{"answer":"Class A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Smaller MAD means closer to the mean on average: Class A (1.5).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
