INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('daf3781b-7fbb-49de-80ca-877d678bd376', 'NC26.7.RD.4', 1, 'choice', 'Interpret range, IQR and MAD', 'The IQR of Data Set P is much larger than the IQR of Data Set Q. What does this tell you?', '["The values of P are greater than the values of Q.","Data Set P has more values than Data Set Q.","The middle half of the values of P is more spread out than the middle half of Q.","The median of P is greater than the median of Q."]', 'The middle half of the values of P is more spread out than the middle half of Q.', NULL, 'The IQR measures how spread out the middle half of the values is, so a larger IQR means more spread. It does not say how large the values are, how many there are, or where the median is.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of the values of P is more spread out than the middle half of Q.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR measures spread of the middle half; says nothing of count, median or size of values.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54289413-c561-4aaf-9ec0-460206126606', 'NC26.7.RD.4', 1, 'choice', 'Interpret range, IQR and MAD', 'In one town the range of the daily high temperatures last month was 8 degrees. In another town it was 20 degrees. Which statement is correct?', '["The temperatures varied more in the first town.","The temperatures varied more in the second town.","The second town was warmer.","The temperatures varied the same amount in both towns."]', 'The temperatures varied more in the second town.', NULL, 'The range tells how far apart the greatest and least values are. A range of 20 is greater than a range of 8, so the temperatures varied more in the second town. The range says nothing about which town was warmer.', 'checked', '{"lint":[],"solve":{"answer":"The temperatures varied more in the second town.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger range (20 vs 8) means more variation in the second town; warmth not implied.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa5f48d7-171e-419a-8bbe-c492f7dfc8de', 'NC26.7.RD.4', 1, 'numeric', 'Interpret range, IQR and MAD', 'The scores on a quiz have a mean of 70 and a MAD of 6. On average, how many points are the scores away from the mean of 70?', '[]', '6', '6', 'The MAD is the average distance of the values from the mean, so the scores are on average 6 points away from 70.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD is the average distance from the mean: 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed0e7ae8-67b2-4070-a3a6-c6e67f2a0f7f', 'NC26.7.RD.4', 1, 'choice', 'Choose measures of center and spread', 'A data set is symmetric and has no extreme values. Which pair of measures is usually used to describe its center and spread?', '["The mean and the interquartile range","The mean and the MAD","The median and the mean absolute deviation","The mode and the range"]', 'The mean and the MAD', NULL, 'For symmetric data without extreme values, the mean is a good center, and the MAD (which measures distance from the mean) goes with it. The median and the IQR are used together when the data are skewed or have extreme values.', 'checked', '{"lint":[],"solve":{"answer":"The mean and the MAD","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Symmetric, no outliers: mean with MAD.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddedff48-4a27-47ee-83ce-4d81f654f714', 'NC26.7.RD.4', 1, 'choice', 'Choose measures of center and spread', 'Five houses on a street sold for 150, 155, 160, 162 and 900 thousand dollars. Which measure best describes a typical sale price?', '["The median, 160 thousand dollars","The mean, 305.4 thousand dollars","The range, 750 thousand dollars","The greatest price, 900 thousand dollars"]', 'The median, 160 thousand dollars', NULL, 'One very high price (900) pulls the mean up to 305.4, which is higher than four of the five prices. The median, 160, is not affected by that extreme value, so it describes a typical price better. The range is a measure of spread, not of a typical price.', 'checked', '{"lint":[],"solve":{"answer":"The median, 160 thousand dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean (150+155+160+162+900)/5=305.4 is pulled by 900; median 160 is typical.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d58bd860-5c89-41b8-824d-06d129f2328e', 'NC26.7.RD.4', 1, 'choice', 'Choose measures of center and spread', 'A teacher wants to describe how spread out the middle half of her students'' scores is. Which measure should she use?', '["The range","The mean","The greatest score","The interquartile range"]', 'The interquartile range', NULL, 'The interquartile range is the length of the interval holding the middle half of the values. The range uses the extreme scores, and the mean and the greatest score are not measures of spread.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Middle half spread = IQR.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39b45941-8dad-4ec1-8021-022726501bac', 'NC26.7.RD.4', 1, 'choice', 'Compare two data sets using center and spread', 'Bakery X puts a median of 12 cookies in a box, with an IQR of 1. Bakery Y also puts a median of 12 cookies in a box, with an IQR of 3. Which bakery''s boxes are more consistent?', '["Bakery X''s, because their IQR is smaller","Bakery Y''s, because their IQR is larger","They are equally consistent, because the medians are equal","Bakery X''s, because its median is smaller"]', 'Bakery X''s, because their IQR is smaller', NULL, 'The medians are equal, so the centers are the same. The IQR of X is smaller, so the middle half of its box counts are closer together: X''s boxes are more consistent.', 'checked', '{"lint":[],"solve":{"answer":"Bakery X''s, because their IQR is smaller","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same median; smaller IQR (1) means less variation: Bakery X.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7283fd13-735c-4ca3-95e0-2938c28fe2fe', 'NC26.7.RD.4', 1, 'numeric', 'Compare two data sets using center and spread', 'Set P is 4, 7, 9, 12. Set Q is 5, 6, 9, 10. How much greater is the range of Set P than the range of Set Q?', '[]', '3', '(12-4)-(10-5)', 'The range of P is 12 - 4 = 8. The range of Q is 10 - 5 = 5. The difference is 8 - 5 = 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 12-4=8. Q: 10-5=5. 8-5=3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55b8272b-47a2-4156-8c7a-bdf41a94de11', 'NC26.7.RD.4', 1, 'choice', 'Compare two data sets using center and spread', 'Set P is 3, 8, 10, 11, 14. Set Q is 6, 9, 9, 10, 11. Which statement is correct?', '["Set P has the greater median and the smaller range.","Set P has the greater median and the greater range.","Set Q has the greater median and the greater range.","Set Q has the greater median and the smaller range."]', 'Set P has the greater median and the greater range.', NULL, 'Median of P = 10 and median of Q = 9, so P has the greater median. Range of P = 14 - 3 = 11 and range of Q = 11 - 6 = 5, so P has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Set P has the greater median and the greater range.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: median 10, range 11. Q: median 9, range 5. P greater on both.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('135040fa-41c4-456e-9d06-00c6dea459d2', 'NC26.7.RD.4', 1, 'numeric', 'Describe the effect of an extreme value', 'The data set 10, 12, 13, 15 has a range of 5. A new value, 40, is added. What is the range of the data set now?', '[]', '30', '40-10', 'The new value is the greatest, so the range is 40 - 10 = 30. One extreme value raised the range from 5 to 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-10 = 30.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3945cc1d-cef9-41b4-b644-551bced7c704', 'NC26.7.RD.4', 1, 'choice', 'Describe the effect of an extreme value', 'The greatest value in a data set of nine values is replaced by a much greater value. Which measure stays the same?', '["The mean","The range","The mean absolute deviation","The median"]', 'The median', NULL, 'The median depends on the middle of the ordered list, and the replaced value is at the very end, so it stays the same. The mean, the range and the MAD all use the value that changed.', 'checked', '{"lint":[],"solve":{"answer":"The median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 9 values the median is the 5th value, unchanged when the greatest grows. Range, mean and MAD all grow.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('019a2c74-39c9-47c9-bfd0-1482a9381d7f', 'NC26.7.RD.4', 1, 'numeric', 'Describe the effect of an extreme value', 'The data set 22, 25, 27, 30, 31, 78 has an extreme value, 78. By how much does the range decrease if 78 is removed?', '[]', '47', '(78-22)-(31-22)', 'With 78 the range is 78 - 22 = 56. Without it the greatest value is 31, so the range is 31 - 22 = 9. The range decreases by 56 - 9 = 47.', 'checked', '{"lint":[],"solve":{"answer":"47","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With 78: 78-22=56. Without: 31-22=9. Decrease 47.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bf5dd03-aa27-43c3-830a-078c43e8d4d3', 'NC26.7.RD.4', 1, 'numeric', 'Find a missing value from a measure', 'A data set has a range of 15 and a least value of 9. What is its greatest value?', '[]', '24', '9+15', 'The range is the greatest value minus the least value, so the greatest value is the least value plus the range: 9 + 15 = 24.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9+15 = 24.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a190c95b-84fe-40ab-ad5a-8a3d9bc3b564', 'NC26.7.RD.4', 1, 'numeric', 'Find a measure from a frequency table or dot plot', 'A table shows how many pets students have. 0 pets: 6 students. 1 pet: 9 students. 2 pets: 5 students. 3 pets: 3 students. 5 pets: 1 student. What is the range of the number of pets?', '[]', '5', '5-0', 'The least number of pets is 0 and the greatest is 5, so the range is 5 - 0 = 5. (The counts of students do not matter for the range.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 5, least 0: 5.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97635a9f-60f3-40ee-b432-398640f6d9e0', 'NC26.7.RD.4', 1, 'numeric', 'Find a measure from a frequency table or dot plot', 'A dot plot of the ages of children at a party has 2 dots at 9, 5 dots at 10, 4 dots at 11 and 1 dot at 15. What is the range of the ages?', '[]', '6', '15-9', 'The leftmost dot is at 9 and the rightmost dot is at 15, so the range is 15 - 9 = 6 years.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15-9 = 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a15ab44e-886c-4f1b-bf9e-07f8ba76492b', 'NC26.7.RD.4', 1, 'numeric', 'Find a measure from a frequency table or dot plot', 'A dot plot has 3 dots at 2, 4 dots at 3 and 2 dots at 5. What is the median of the 9 values?', '[]', '3', '3', 'There are 9 dots, so the median is the 5th value in order. The first 3 dots are at 2, and the next 4 dots (the 4th to 7th) are at 3, so the 5th value is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,2,2,3,3,3,3,5,5: 5th value 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf78c9b8-5380-4417-bb4a-64a0c3f961a5', 'NC26.7.RD.4', 1, 'choice', 'Find a measure from a frequency table or dot plot', 'A table shows the number of books students read: 2 books for 3 students, 4 books for 3 students, 5 books for 2 students and 7 books for 2 students. What is the mean number of books?', '["4.5","42","4.2","5.25"]', '4.2', '(2*3+4*3+5*2+7*2)/10', 'The total number of books is 2 x 3 + 4 x 3 + 5 x 2 + 7 x 2 = 6 + 12 + 10 + 14 = 42. There are 3 + 3 + 2 + 2 = 10 students, so the mean is 42 / 10 = 4.2 books. (4.5 is the mean of 2, 4, 5 and 7, which ignores how many students read each amount; 42 is the total; 5.25 divides by 8.)', 'checked', '{"lint":[],"solve":{"answer":"4.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*3+4*3+5*2+7*2 = 6+12+10+14 = 42 over 10 students: 4.2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54d87094-d998-444c-ba82-55655605e516', 'NC26.7.RD.4', 1, 'choice', 'Find a measure from a frequency table or dot plot', 'Which measure can be read directly from the leftmost and rightmost dots of a dot plot?', '["The mean absolute deviation","The interquartile range","The mean","The range"]', 'The range', NULL, 'The leftmost dot is the least value and the rightmost dot is the greatest value, and their difference is the range. The IQR, MAD and mean all need more of the data.', 'checked', '{"lint":[],"solve":{"answer":"The range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range = rightmost - leftmost.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bff3730-512f-4c37-a9a7-65c03e4b0cb0', 'NC26.7.RD.4', 2, 'numeric', 'Mean absolute deviation', 'Find the mean absolute deviation (MAD) of the data set 2, 5, 5, 8.', '[]', '1.5', '(3+0+0+3)/4', 'The mean is $(2 + 5 + 5 + 8) \div 4 = 5$. The distances from 5 are 3, 0, 0 and 3. The mean of these distances is $6 \div 4 = 1.5$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean 20/4 = 5. Distances 3, 0, 0, 3; MAD = 6/4 = 1.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed90802c-f78a-4673-bf7d-ce8e019a38b9', 'NC26.7.RD.4', 2, 'numeric', 'Interquartile range from raw data', 'Find the interquartile range of the data set 13, 3, 8, 5, 11, 2, 9, 6.', '[]', '6', '(9+11)/2-(3+5)/2', 'Put the values in order: 2, 3, 5, 6, 8, 9, 11, 13. The lower half is 2, 3, 5, 6, so the first quartile is $(3 + 5) \div 2 = 4$. The upper half is 8, 9, 11, 13, so the third quartile is $(9 + 11) \div 2 = 10$. The IQR is $10 - 4 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted: 2, 3, 5, 6, 8, 9, 11, 13. Lower half 2, 3, 5, 6: Q1 = 4. Upper half 8, 9, 11, 13: Q3 = 10. IQR = 6.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82c81912-d71f-4b63-b746-72ee69ec35bc', 'NC26.7.RD.4', 2, 'choice', 'Which measure resists extreme values', 'Which of these is least affected by one very extreme value in a data set?', '["Interquartile range","Range","Mean absolute deviation","Mean"]', 'Interquartile range', NULL, 'The range uses the extreme values directly, and the mean and the MAD both use every value, so an extreme value changes them. The interquartile range uses only the middle half of the data, so one extreme value barely affects it.', 'checked', '{"lint":[],"solve":{"answer":"Interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR uses only the middle half, so one extreme value barely moves it; mean, range and MAD all use every value.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b2b0db7-9763-4706-a2d5-8718889ce49f', 'NC26.7.RD.4', 2, 'numeric', 'Find the range of a data set', 'The temperatures at noon on five winter days were $-3$, 2, $-8$, 0 and 5 degrees. What is the range of the temperatures?', '[]', '13', '5-(-8)', 'The greatest temperature is 5 and the least is -8. The range is 5 - (-8) = 5 + 8 = 13 degrees.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 5, least -8: 5-(-8)=13.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8ef9009-778c-490b-85eb-e1caafb3e80e', 'NC26.7.RD.4', 2, 'numeric', 'Find the range of a data set', 'Six apples have masses of 1.2, 0.9, 1.5, 1.1, 0.7, 1.3 kilograms. What is the range of the masses, in kilograms?', '[]', '0.8', '1.5-0.7', 'The greatest mass is 1.5 and the least is 0.7. The range is 1.5 - 0.7 = 0.8 kilograms.', 'checked', '{"lint":[],"solve":{"answer":"0.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest 1.5, least 0.7: 0.8.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('639a8230-15da-44a4-8f1f-2afeb5364f27', 'NC26.7.RD.4', 2, 'choice', 'Find the range of a data set', 'The data set 12, 15, 19, 24, 30 has a range of 18. One more value will be added. Which new value would NOT change the range?', '["10","20","35","8"]', '20', '20', 'The range is set by the least and greatest values, 12 and 30. A new value of 20 lies between them, so the range stays 18. A new value of 10 or 8 would be the new least value (range 20 or 22), and 35 would be the new greatest value (range 23).', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range stays 18 only if new value is within 12..30: 20. 10, 8 lower the least; 35 raises the greatest.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a07cef10-fe30-4523-9b6b-adab680ee990', 'NC26.7.RD.4', 2, 'numeric', 'Find the interquartile range', 'Eight students recorded how many minutes they read: 7, 12, 15, 9, 20, 16, 11, 22. What is the interquartile range of the reading times?', '[]', '8', '((16+20)/2)-((9+11)/2)', 'Put the values in order: 7, 9, 11, 12, 15, 16, 20, 22. The lower half is 7, 9, 11, 12, so Q1 = (9 + 11) / 2 = 10. The upper half is 15, 16, 20, 22, so Q3 = (16 + 20) / 2 = 18. The IQR is 18 - 10 = 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 7,9,11,12 | 15,16,20,22: Q1=(9+11)/2=10, Q3=(16+20)/2=18. IQR 8.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eedefff5-3389-449c-bfa7-e6086bc0d47e', 'NC26.7.RD.4', 2, 'numeric', 'Find the interquartile range', 'The number of points a player scored in ten games was 18, 5, 12, 3, 9, 15, 13, 20, 6, 8. What is the interquartile range of the scores?', '[]', '9', '(15)-(6)', 'In order: 3, 5, 6, 8, 9, 12, 13, 15, 18, 20. There are 10 values, so each half has 5. The lower half 3, 5, 6, 8, 9 has median 6 (Q1). The upper half 12, 13, 15, 18, 20 has median 15 (Q3). The IQR is 15 - 6 = 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 3,5,6,8,9 | 12,13,15,18,20: Q1=6, Q3=15, IQR 9.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ba38a15-c2c2-414b-aabd-59350a4bc42b', 'NC26.7.RD.4', 2, 'choice', 'Find the interquartile range', 'The data set 6, 8, 9, 12, 14, 17, 19, 25 is in order. What are its first and third quartiles?', '["8 and 17","9 and 17","6 and 25","8.5 and 18"]', '8.5 and 18', NULL, 'There are 8 values, so each half has 4. The lower half 6, 8, 9, 12 has median (8 + 9) / 2 = 8.5, which is Q1. The upper half 14, 17, 19, 25 has median (17 + 19) / 2 = 18, which is Q3. (6 and 25 are the least and greatest values.)', 'checked', '{"lint":[],"solve":{"answer":"8.5 and 18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,8,9,12 | 14,17,19,25: Q1=(8+9)/2=8.5, Q3=(17+19)/2=18.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('badf2cea-8dcb-4101-8e7d-3ccd40a3380c', 'NC26.7.RD.4', 2, 'numeric', 'Find the interquartile range', 'A shop sold the following numbers of sandwiches on twelve days: 24, 5, 13, 8, 27, 10, 18, 22, 7, 15, 12, 20. What is the interquartile range?', '[]', '12', '((20+22)/2)-((8+10)/2)', 'In order: 5, 7, 8, 10, 12, 13, 15, 18, 20, 22, 24, 27. Each half has 6 values. The lower half has median (8 + 10) / 2 = 9 (Q1). The upper half has median (20 + 22) / 2 = 21 (Q3). The IQR is 21 - 9 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 5,7,8,10,12,13 | 15,18,20,22,24,27: Q1=(8+10)/2=9, Q3=(20+22)/2=21. IQR 12.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a32dc39-6311-4262-8841-06e02aa53b8e', 'NC26.7.RD.4', 2, 'choice', 'Find the interquartile range', 'To find the interquartile range of the data 1, 3, 4, 8, 9, 12, a student calculates 12 - 1 = 11. What did the student actually find?', '["The IQR. The student is correct.","The median. The IQR is 6.","The range. The IQR is 6.","The range. The IQR is 8."]', 'The range. The IQR is 6.', NULL, '12 - 1 is the greatest value minus the least value, which is the range. For the IQR: the lower half 1, 3, 4 has median 3 (Q1) and the upper half 8, 9, 12 has median 9 (Q3), so IQR = 9 - 3 = 6.', 'checked', '{"lint":[],"solve":{"answer":"The range. The IQR is 6.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12-1 is the range. 1,3,4 | 8,9,12: Q1=3, Q3=9, IQR 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c66872a-d916-45d6-af96-18e7b1914dfa', 'NC26.7.RD.4', 2, 'numeric', 'Find the mean absolute deviation', 'Find the mean absolute deviation (MAD) of the data 12, 15, 9, 18 and 6.', '[]', '3.6', '(0+15+15+30+30)/25', 'The mean is 60 / 5 = 12. The distances from 12 are 0, 3, 3, 6 and 6, which add to 18. The MAD is 18 / 5 = 3.6.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 60, mean 12. Distances 0,3,3,6,6 = 18; 18/5 = 3.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
