INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8489a4f-855b-4df1-a815-ca4498a9e6f9', 'NC26.7.RD.4', 2, 'numeric', 'Find the mean absolute deviation', 'Six friends are 20, 24, 18, 26, 22, 22 years old. Find the mean absolute deviation (MAD) of their ages.', '[]', '2', '(12+12+24+24+0+0)/36', 'The mean is 132 / 6 = 22. The distances from 22 are 2, 2, 4, 4, 0 and 0, which add to 12. The MAD is 12 / 6 = 2 years.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 132, mean 22. Distances 2,2,4,4,0,0 = 12; 12/6 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
