INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('23b90afc-2276-42a6-b14f-607691661d6f', 'NC26.7.RD.4', 2, 'choice', 'Interpret range, IQR and MAD', 'A set of test scores has a mean of 80 and a mean absolute deviation (MAD) of 2. Which statement is correct?', '["Every score is between 78 and 82.","The range of the scores is 2.","The middle score is 2 points above 80.","The scores are typically about 2 points away from 80."]', 'The scores are typically about 2 points away from 80.', NULL, 'A MAD of 2 means the scores are 2 points from the mean on average. Some scores can be farther away, so not every score has to be between 78 and 82, and the MAD is not the range.', 'checked', '{"lint":[],"solve":{"answer":"The scores are typically about 2 points away from 80.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD 2 means scores are typically about 2 points from 80; it does not bound every score or give the range.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d535e8b3-01a7-4d08-baec-f4da58278c0a', 'NC26.7.RD.4', 2, 'choice', 'Interpret range, IQR and MAD', 'Which of these measures of spread uses every value in the data set?', '["The mean absolute deviation","The range","The interquartile range","The greatest value"]', 'The mean absolute deviation', NULL, 'The MAD finds the distance of every value from the mean. The range uses only the greatest and least values, and the IQR uses only the quartiles. (The greatest value is not a measure of spread.)', 'checked', '{"lint":[],"solve":{"answer":"The mean absolute deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD averages every value''s distance from the mean; range uses only extremes; IQR only quartiles.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0badaef-9169-45d4-b2f7-de71834552fd', 'NC26.7.RD.4', 2, 'numeric', 'Interpret range, IQR and MAD', 'The times of a group of runners have a mean of 40 seconds and a MAD of 5 seconds. One runner took 47 seconds. How many seconds farther from the mean than the average distance is this runner''s time?', '[]', '2', '(47-40)-5', 'This runner is 47 - 40 = 7 seconds from the mean. The average distance is the MAD, 5 seconds. So 7 - 5 = 2 seconds farther than average.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Runner''s distance 47-40=7; average distance (MAD) 5; 7-5=2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3f41df5-50cd-42ed-8d8b-4676b562f4a5', 'NC26.7.RD.4', 2, 'choice', 'Choose measures of center and spread', 'A data set is 12, 13, 13, 14, 15, 15, 16, 48. Which measure of spread is least affected by the value 48?', '["The range","The interquartile range","The mean absolute deviation","All three are affected equally"]', 'The interquartile range', NULL, 'The range jumps to 36 because of the 48, and the mean (18.25) is pulled up, which raises the MAD. The IQR uses only the middle half of the values: Q1 = 13 and Q3 = 15.5, so IQR = 2.5, and it hardly notices the 48.', 'checked', '{"lint":[],"solve":{"answer":"The interquartile range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q1=(13+13)/2=13, Q3=(15+15)/2=15; IQR does not depend on 48''s size. Range and MAD do.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b975a1b-00e4-4b81-9cc5-57fb862f5ea3', 'NC26.7.RD.4', 2, 'choice', 'Choose measures of center and spread', 'A coach wants to know how far, on average, her players'' sprint times are from the team''s mean time. Which measure should she use?', '["The range","The interquartile range","The mean absolute deviation","The median"]', 'The mean absolute deviation', NULL, 'The MAD is, by definition, the average distance of the values from the mean. The range and the IQR describe the spread of the ends and of the middle half, and the median is a measure of center.', 'checked', '{"lint":[],"solve":{"answer":"The mean absolute deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Average distance from the mean = MAD.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0dcaf6a8-aefb-4699-a478-c52c361f226f', 'NC26.7.RD.4', 2, 'choice', 'Choose measures of center and spread', 'For which situation are the median and the interquartile range the better choice to describe the data?', '["The heights of 25 same-age students, which cluster evenly around the average","The number of minutes a train arrives early or late, which is balanced around zero","The weights of 30 identical bags of rice, which are all very close to the labeled weight","The ages of guests at a party where most are 8 to 12 years old and two are grandparents aged 70"]', 'The ages of guests at a party where most are 8 to 12 years old and two are grandparents aged 70', NULL, 'The median and IQR are used when data are skewed or have extreme values. The two grandparents are extreme values that would distort the mean and the MAD. The other three situations are roughly symmetric without extreme values, so the mean and the MAD describe them well.', 'checked', '{"lint":[],"solve":{"answer":"The ages of guests at a party where most are 8 to 12 years old and two are grandparents aged 70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Party ages are skewed by two 70-year-olds: median and IQR resist extremes. Others are symmetric.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfbc1292-8b80-43ab-b7ee-a85a26158659', 'NC26.7.RD.4', 2, 'numeric', 'Compare two data sets using center and spread', 'Two machines fill boxes. The weights, in ounces, of five boxes from Machine A are 18, 21, 24, 27, 30, and from Machine B are 22, 23, 24, 25, 26. Both sets have a mean of 24. The MAD of Machine A''s weights is how many times the MAD of Machine B''s weights?', '[]', '3', '((30+15+0+15+30)/25)/((10+5+0+5+10)/25)', 'Machine A: distances from 24 are 6, 3, 0, 3, 6, which add to 18, so MAD = 18 / 5 = 3.6. Machine B: distances are 2, 1, 0, 1, 2, which add to 6, so MAD = 6 / 5 = 1.2. Since 3.6 / 1.2 = 3, A''s MAD is 3 times B''s MAD.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A distances 6,3,0,3,6 = 18, MAD 3.6. B distances 2,1,0,1,2 = 6, MAD 1.2. 3.6/1.2 = 3.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0718805a-2ee8-48b3-a0bf-866281c60873', 'NC26.7.RD.4', 2, 'choice', 'Compare two data sets using center and spread', 'Class 1''s test scores have a median of 78 and an IQR of 6. Class 2''s test scores have a median of 82 and an IQR of 16. Which statement is correct?', '["Class 2''s scores are typically higher, and they vary less.","Class 1''s scores are typically higher, and they vary more.","Class 1''s scores are typically higher, but they vary less.","Class 2''s scores are typically higher, but they vary more."]', 'Class 2''s scores are typically higher, but they vary more.', NULL, 'The median of Class 2 (82) is greater than that of Class 1 (78), so its scores are typically higher. The IQR of Class 2 (16) is greater than that of Class 1 (6), so its middle half is more spread out: its scores vary more.', 'checked', '{"lint":[],"solve":{"answer":"Class 2''s scores are typically higher, but they vary more.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 2 median 82 > 78 (typically higher) and IQR 16 > 6 (varies more).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('392d0fba-e741-409b-9a37-d1e54b7d7e26', 'NC26.7.RD.4', 2, 'numeric', 'Compare two data sets using center and spread', 'Tomato plants in Garden A produced 10, 12, 15, 19, 22, 30 tomatoes. Tomato plants in Garden B produced 14, 16, 17, 20, 21, 23 tomatoes. The IQR of Garden A is how many times the IQR of Garden B?', '[]', '2', '((22)-(12))/((21)-(16))', 'Garden A in order: Q1 = 12 and Q3 = 22, so IQR = 10. Garden B in order: Q1 = 16 and Q3 = 21, so IQR = 5. Since 10 / 5 = 2, the IQR of A is 2 times the IQR of B.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 10,12,15 | 19,22,30: Q1 12, Q3 22, IQR 10. B: 14,16,17 | 20,21,23: Q1 16, Q3 21, IQR 5. 10/5 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7523f028-5ee2-4f11-b2c1-c224f51c637b', 'NC26.7.RD.4', 2, 'choice', 'Describe the effect of an extreme value', 'The mean of five values is 20. A sixth value, 50, is added. What is the mean of all six values?', '["35","25","30","150"]', '25', '(5*20+50)/6', 'The five values add to 5 x 20 = 100. With 50 the total is 150. The mean of six values is 150 / 6 = 25. The one extreme value raised the mean by 5. (35 is the mean of 20 and 50, which ignores that there are five values at around 20, and 150 is the total.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 5*20=100, +50 = 150; 150/6 = 25.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bbae04b-c016-42ca-b8ff-4ebb811d8f8a', 'NC26.7.RD.4', 2, 'numeric', 'Describe the effect of an extreme value', 'The median of the data 4, 6, 7, 9, 10 is 7. A sixth value, 100, is added. What is the median of the six values?', '[]', '8', '(7+9)/2', 'The six values in order are 4, 6, 7, 9, 10, 100. The median is the mean of the 3rd and 4th values: (7 + 9) / 2 = 8. Even a value as extreme as 100 moved the median by only 1.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,6,7,9,10,100: median (7+9)/2 = 8.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
