INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c89641bb-93e8-4c11-94a5-2c2451723254', 'NC26.7.RD.4', 2, 'numeric', 'Find a missing value from a measure', 'The range of five values is 18. Four of the values are 23, 31, 27 and 35, and the fifth value is the least. What is the fifth value?', '[]', '17', '35-18', 'The greatest value is 35. The range is 18, so the least value is 35 - 18 = 17. Check: 17 is less than the other four values, and 35 - 17 = 18.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest of the five is 35 (fifth is least). Least = 35-18 = 17 (below 23, consistent).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee403412-aded-4afb-92c7-e00377eb4487', 'NC26.7.RD.4', 2, 'numeric', 'Find a missing value from a measure', 'A data set has a least value of 8 and a range of 12. A new value is added that is greater than every other value, and the range becomes 20. What is the new value?', '[]', '28', '8+20', 'The new value is the new greatest value, and the least value is still 8. The range is 20, so the new value is 8 + 20 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old greatest 8+12=20. New value is new greatest: 8+20 = 28.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ba08298-4cb6-4bf4-bb44-e8cfc34514e9', 'NC26.7.RD.4', 2, 'numeric', 'Find a measure from a frequency table or dot plot', 'A frequency table shows the number of points scored in eight games: 3 points 2 times, 5 points 1 time, 7 points 2 times, 9 points 1 time and 11 points 2 times. What is the interquartile range of the scores?', '[]', '6', '((9+11)/2)-((3+5)/2)', 'List all 8 scores in order: 3, 3, 5, 7, 7, 9, 11, 11. The lower half 3, 3, 5, 7 has median (3 + 5) / 2 = 4 (Q1). The upper half 7, 9, 11, 11 has median (9 + 11) / 2 = 10 (Q3). The IQR is 10 - 4 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values 3,3,5,7 | 7,9,11,11: Q1 (3+5)/2=4, Q3 (9+11)/2=10, IQR 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63bca8f0-17a9-40f6-abe0-1970216ced79', 'NC26.7.RD.4', 2, 'choice', 'Find a measure from a frequency table or dot plot', 'A dot plot has 1 dot at 1, 2 dots at 3, 4 dots at 5, 2 dots at 7 and 1 dot at 9. The mean of the 10 values is 5. What is the mean absolute deviation (MAD)?', '["2.4","1.6","3.2","16"]', '1.6', '(40+20+20+0+0+0+0+20+20+40)/100', 'The distances from 5 are: 4 (one dot), 2 (two dots at 3), 0 (four dots), 2 (two dots at 7) and 4 (one dot). They add to 4 + 2 x 2 + 0 + 2 x 2 + 4 = 16. The MAD is 16 / 10 = 1.6. (2.4 ignores how many dots are at each value, 3.2 divides the 16 by 5 instead of 10, and 16 is the total before dividing.)', 'checked', '{"lint":[],"solve":{"answer":"1.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances: 1*4 + 2*2 + 4*0 + 2*2 + 1*4 = 16; 16/10 = 1.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4bca99d-30cd-4c18-91c7-f081809b36c9', 'NC26.7.RD.4', 2, 'choice', 'Find a measure from a frequency table or dot plot', 'Plot P has 3 dots at each of 4, 6 and 8. Plot Q has 2 dots at 4, 5 dots at 6 and 2 dots at 8. Both plots have a mean of 6 and a range of 4. Which plot has the greater MAD?', '["Plot P, because more of its dots are far from the mean.","Plot Q, because it has the tallest stack of dots.","Neither: they have the same MAD, because the mean and the range are the same.","Plot Q, because it has more dots at the mean."]', 'Plot P, because more of its dots are far from the mean.', NULL, 'Plot P: the distances from 6 are 2 (three dots), 0 (three dots) and 2 (three dots), which add to 12, so MAD = 12 / 9 = 4/3. Plot Q: 2 (two dots), 0 (five dots) and 2 (two dots) add to 8, so MAD = 8 / 9. P has the greater MAD. Equal means and ranges do not make equal MADs.', 'checked', '{"lint":[],"solve":{"answer":"Plot P, because more of its dots are far from the mean.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 3*2 + 0 + 3*2 = 12, MAD 12/9 ~ 1.33. Q: 2*2 + 0 + 2*2 = 8, MAD 8/9 ~ 0.89. P greater.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17e6d444-ec08-4608-97cf-aef1f039dc9b', 'NC26.7.RD.4', 3, 'choice', 'Effect of an extreme value', 'The value 30 is added to the data set 4, 5, 6, 7, 8. Which statement is true?', '["The median increases a lot, but the range changes only a little","Neither the range nor the median changes","The range increases a lot, but the median changes only a little","The range and the median increase by the same amount"]', 'The range increases a lot, but the median changes only a little', NULL, 'Before: the range is $8 - 4 = 4$ and the median is 6. After adding 30 the data are 4, 5, 6, 7, 8, 30. The range is $30 - 4 = 26$, an increase of 22. The median is $(6 + 7) \div 2 = 6.5$, an increase of only 0.5.', 'checked', '{"lint":[],"solve":{"answer":"The range increases a lot, but the median changes only a little","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Before: range 4, median 6. After: 4, 5, 6, 7, 8, 30: range 26, median 6.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b00d53e-1c8d-4729-9b5e-5de29c8146be', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using MAD', 'Set A is 6, 8, 10, 12, 14. Set B is 2, 6, 10, 14, 18. Both sets have a mean of 10. The MAD of Set B is how many times the MAD of Set A?', '[]', '2', '((8+4+0+4+8)/5)/((4+2+0+2+4)/5)', 'Set A: the distances from 10 are 4, 2, 0, 2, 4. Their mean is $12 \div 5 = 2.4$. Set B: the distances from 10 are 8, 4, 0, 4, 8. Their mean is $24 \div 5 = 4.8$. Since $4.8 \div 2.4 = 2$, the MAD of B is 2 times the MAD of A.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: distances 4, 2, 0, 2, 4; MAD 12/5 = 2.4. B: 8, 4, 0, 4, 8; MAD 24/5 = 4.8. Ratio 2.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0baf79a5-681b-49ef-8d0f-9740724297c7', 'NC26.7.RD.4', 3, 'numeric', 'Compare two sets using IQR', 'Set X is 3, 5, 6, 8, 9, 12, 14, 17. Set Y is 10, 11, 12, 13, 14, 15, 16, 17. How much greater is the interquartile range of Set X than the interquartile range of Set Y?', '[]', '3.5', '((12+14)/2-(5+6)/2)-((15+16)/2-(11+12)/2)', 'Set X: the lower half is 3, 5, 6, 8 with first quartile $(5 + 6) \div 2 = 5.5$. The upper half is 9, 12, 14, 17 with third quartile $(12 + 14) \div 2 = 13$. IQR = $13 - 5.5 = 7.5$. Set Y: the lower half is 10, 11, 12, 13 with first quartile 11.5. The upper half is 14, 15, 16, 17 with third quartile 15.5. IQR = $15.5 - 11.5 = 4$. The difference is $7.5 - 4 = 3.5$.', 'checked', '{"lint":[],"solve":{"answer":"3.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: lower 3, 5, 6, 8 -> Q1 5.5; upper 9, 12, 14, 17 -> Q3 13; IQR 7.5. Y: lower 10-13 -> 11.5; upper 14-17 -> 15.5; IQR 4. Difference 3.5.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d91afd68-b639-4c69-bee6-7498d41ff098', 'NC26.7.RD.4', 3, 'numeric', 'Find the range of a data set', 'Set A has a range of 14 and a least value of 6. Set B has a least value of 10 and a greatest value of 31. All the values of both sets are put together. What is the range of the combined values?', '[]', '25', '31-6', 'The greatest value of Set A is 6 + 14 = 20, which is less than 31. So the combined greatest value is 31 and the combined least value is 6. The range is 31 - 6 = 25.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: least 6, greatest 6+14=20. B: 10 to 31. Combined 6 to 31: 25.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('211945f3-db14-4744-b1c7-5ade31f3b8fb', 'NC26.7.RD.4', 3, 'numeric', 'Find the range of a data set', 'Six values have a range of 9, and their least value is 11. A seventh value, 23, is added. What is the range of the seven values?', '[]', '12', '23-11', 'The greatest of the six values is 11 + 9 = 20. The new value, 23, is greater than 20, so it is the new greatest value. The range is 23 - 11 = 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Six values run 11 to 20. Adding 23: 23-11=12.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e97fb085-52e5-469f-bb61-bcc84e6a4ea9', 'NC26.7.RD.4', 3, 'numeric', 'Find the interquartile range', 'Ten students finished a puzzle in the following numbers of seconds: 45, 38, 52, 41, 60, 47, 55, 36, 49, 58. What is the interquartile range of the times?', '[]', '14', '(55)-(41)', 'In order: 36, 38, 41, 45, 47, 49, 52, 55, 58, 60. The lower half 36, 38, 41, 45, 47 has median 41 (Q1). The upper half 49, 52, 55, 58, 60 has median 55 (Q3). The IQR is 55 - 41 = 14.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 36,38,41,45,47 | 49,52,55,58,60: Q1=41, Q3=55, IQR 14.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9ccf8c-988d-4dd7-ae51-a8dfc115c090', 'NC26.7.RD.4', 3, 'choice', 'Find the interquartile range', 'The interquartile range of a data set is 12 and its range is 30. The IQR is what fraction of the range?', '["5/2","2/5","3/5","2/7"]', '2/5', NULL, 'The fraction is IQR / range = 12 / 30, which simplifies to 2/5. (5/2 turns it upside down, 3/5 is (30 - 12) / 30, and 2/7 is 12 / (30 + 12).)', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/30 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6141298-0589-43d7-9fcc-846555754f2c', 'NC26.7.RD.4', 3, 'choice', 'Find the interquartile range', 'Data Set A has an interquartile range of 10. Data Set B has an interquartile range of 6. Which statement must be true?', '["The middle half of the values covers a wider interval in Set A than in Set B.","Set A has the greater range.","Set A has the greater median.","Set A has more values than Set B."]', 'The middle half of the values covers a wider interval in Set A than in Set B.', NULL, 'The IQR is the length of the interval holding the middle half of the values, so Set A''s middle half is wider. Nothing is known about the extremes (range), the median, or how many values there are.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of the values covers a wider interval in Set A than in Set B.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR is the width of the interval holding the middle half; 10 > 6. Median, count and range not determined.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a4897e6-ca06-4040-962c-e4e9232ffe9c', 'NC26.7.RD.4', 3, 'numeric', 'Find the interquartile range', 'Find the interquartile range of the data set 6, 9, 10, 14, 16, 21, 25, 40. Then remove the least and greatest values, leaving six values, and find the IQR again. By how much does the IQR decrease?', '[]', '2.5', '((((21+25)/2)-((9+10)/2))-((21)-(10)))', 'All 8 values: Q1 = (9 + 10) / 2 = 9.5 and Q3 = (21 + 25) / 2 = 23, so IQR = 13.5. The six values 9, 10, 14, 16, 21, 25: Q1 = 10 and Q3 = 21, so IQR = 11. The IQR decreases by 13.5 - 11 = 2.5.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6,9,10,14 | 16,21,25,40: Q1=9.5, Q3=23, IQR 13.5. Without 6 and 40: 9,10,14 | 16,21,25: Q1=10, Q3=21, IQR 11. Decrease 13.5-11=2.5.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea964b29-6411-4fe0-a362-dcb13596ae3e', 'NC26.7.RD.4', 3, 'choice', 'Find the mean absolute deviation', 'The temperatures at eight times of a night were $-6$, 2, $-1$, 4, 0, $-2$, 1 and 2 degrees. What is the mean absolute deviation (MAD) of the temperatures?', '["2.25","0","18","4.5"]', '2.25', '(48+16+8+32+0+16+8+16)/64', 'The values add to 0, so the mean is 0. The distances from 0 are 6, 2, 1, 4, 0, 2, 1 and 2, which add to 18. The MAD is 18 / 8 = 2.25 degrees. (0 comes from averaging the signed values, which cancel; 18 is the total distance before dividing; 4.5 divides by 4.)', 'checked', '{"lint":[],"solve":{"answer":"2.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum -6+2-1+4+0-2+1+2 = 0, mean 0. Distances 6,2,1,4,0,2,1,2 = 18; 18/8 = 2.25.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62170a8c-239b-40d8-b651-2a07ae612025', 'NC26.7.RD.4', 3, 'numeric', 'Find the mean absolute deviation', 'A toy car rolled down a ramp five times, in 1.2, 1.8, 1.5, 2.1 and 1.4 seconds. Find the mean absolute deviation (MAD) of the times, in seconds.', '[]', '0.28', '(20+10+5+25+10)/25/10', 'The mean is 8.0 / 5 = 1.6 seconds. The distances from 1.6 are 0.4, 0.2, 0.1, 0.5 and 0.2, which add to 1.4. The MAD is 1.4 / 5 = 0.28 seconds.', 'checked', '{"lint":[],"solve":{"answer":"0.28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 8.0, mean 1.6. Distances 0.4,0.2,0.1,0.5,0.2 = 1.4; 1.4/5 = 0.28.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b14867b-e38a-4947-8e7b-40a738dbf61e', 'NC26.7.RD.4', 3, 'choice', 'Find the mean absolute deviation', 'Ten students counted the following numbers of jumps in a minute: 34, 41, 38, 45, 29, 52, 36, 40, 47, 38. What is the mean absolute deviation (MAD) of the numbers of jumps?', '["50","5","40","10"]', '5', '(60+10+20+50+110+120+40+0+70+20)/100', 'The values add to 400, so the mean is 40. The distances from 40 are 6, 1, 2, 5, 11, 12, 4, 0, 7 and 2, which add to 50. The MAD is 50 / 10 = 5. (50 is the total distance before dividing, and 40 is the mean.)', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 400, mean 40. Distances 6,1,2,5,11,12,4,0,7,2 = 50; 50/10 = 5.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c52dc3ec-973d-4fe0-b3fc-64df62ec04e7', 'NC26.7.RD.4', 3, 'choice', 'Find the mean absolute deviation', 'Every value in a data set is increased by 10. What happens to the mean absolute deviation (MAD)?', '["It increases by 10.","It is multiplied by 10.","It decreases by 10.","It stays the same."]', 'It stays the same.', NULL, 'Adding 10 to every value also adds 10 to the mean, so every value stays the same distance from the mean. The distances, and so the MAD, do not change. (Example: 2, 4, 6 has mean 4 and MAD 4/3; after adding 10, 12, 14, 16 has mean 14 and the same MAD.)', 'checked', '{"lint":[],"solve":{"answer":"It stays the same.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shifting all values and the mean by 10 leaves each distance unchanged.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('978fc373-01dc-4779-a33c-45f7ab475448', 'NC26.7.RD.4', 3, 'choice', 'Interpret range, IQR and MAD', 'Which of these CANNOT be true for a data set?', '["A range of 10 and a MAD of 3","A range of 20 and a MAD of 2","A range of 6 and a MAD of 9","A range of 8 and a MAD of 4"]', 'A range of 6 and a MAD of 9', NULL, 'Every value lies between the least and the greatest value, so no value can be farther from the mean than the range. The average distance (the MAD) cannot be greater than the range. A range of 6 and a MAD of 9 is impossible. (For a range of 8 and a MAD of 4, take 0, 0, 8, 8.)', 'checked', '{"lint":[],"solve":{"answer":"A range of 6 and a MAD of 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every distance from the mean is at most the range, so MAD <= range; MAD 9 > range 6 impossible. Range 8, MAD 4 is possible (0,0,8,8); others fine.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1435001d-51d8-48b1-bbc5-5c4a86c546a5', 'NC26.7.RD.4', 3, 'choice', 'Choose measures of center and spread', 'A data set is 2, 3, 3, 4, 4, 5, 5, 6, 6, 60, and the value 60 is much greater than the others. Which pair of measures best describes its center and spread?', '["Mean 9.8 and IQR 3","Median 4.5 and range 58","Median 4.5 and IQR 3","Mean 9.8 and range 58"]', 'Median 4.5 and IQR 3', NULL, 'With an extreme value, use the median and the IQR. The median is (4 + 5) / 2 = 4.5. The IQR is 6 - 3 = 3. The mean (9.8) is pulled far above nine of the ten values, and the range (58) is created almost entirely by the 60.', 'checked', '{"lint":[],"solve":{"answer":"Median 4.5 and IQR 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median (4+5)/2=4.5. 2,3,3,4,4 | 5,5,6,6,60: Q1=3, Q3=6, IQR 3. Mean 98/10=9.8, range 58. Extreme 60 -> median and IQR.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e16eeb13-a2f5-4177-97e2-e6697e2ef8db', 'NC26.7.RD.4', 3, 'choice', 'Choose measures of center and spread', 'Which statement about choosing measures for a data set is correct?', '["Use the mean and the range when the data have extreme values.","Use the mean and the MAD when the data are roughly symmetric with no extreme values.","Use the median and the MAD when the data are symmetric.","Use the mean and the IQR when the data are skewed."]', 'Use the mean and the MAD when the data are roughly symmetric with no extreme values.', NULL, 'Measures are chosen in matching pairs. The mean goes with the MAD for symmetric data without extreme values; the median goes with the IQR for skewed data or data with extreme values. The range is not a good choice when there are extreme values, because they set it.', 'checked', '{"lint":[],"solve":{"answer":"Use the mean and the MAD when the data are roughly symmetric with no extreme values.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean & MAD for roughly symmetric data without extremes; median & IQR otherwise.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34c8b99f-2acc-440f-9efe-64e769245e48', 'NC26.7.RD.4', 3, 'numeric', 'Choose measures of center and spread', 'The center of the data set 5, 6, 6, 7, 8, 9, 55 can be described by its mean or by its median. One value is much greater than the others. Which measure better describes a typical value? Give the value of that measure.', '[]', '7', '7', 'The value 55 is far greater than the others, so the mean (96 / 7, about 13.7) is pulled up and is greater than six of the seven values. The median, the 4th value in order, is 7. Choose the median, 7.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sorted 5,6,6,7,8,9,55; median 7. Mean 96/7 ~ 13.7 pulled by 55. Median 7 better.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cb066c6-98a5-476e-9654-52d3c6630870', 'NC26.7.RD.4', 3, 'choice', 'Choose measures of center and spread', 'The mean of a data set is much greater than its median. Which is most likely, and which measures would you then choose?', '["The data are skewed to the high values; use the median and the IQR.","The data are symmetric; use the mean and the MAD.","The data are skewed to the low values; use the mean and the MAD.","The data are skewed to the high values; use the mean and the range."]', 'The data are skewed to the high values; use the median and the IQR.', NULL, 'A few very high values pull the mean above the median, so the data are skewed toward the high values. For such data, the median and the IQR are the better pair, because they are not pulled by those few values.', 'checked', '{"lint":[],"solve":{"answer":"The data are skewed to the high values; use the median and the IQR.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean pulled far above median by high values: skewed to the high values (right); use median and IQR.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b0c4d9f-a2c7-4e47-b2e4-30a59d570061', 'NC26.7.RD.4', 3, 'choice', 'Compare two data sets using center and spread', 'Data Set X has a range of 40 and a MAD of 5. Data Set Y has a range of 25 and a MAD of 8. Which statement is correct?', '["Set X''s values are typically farther from their mean, because its range is greater.","Set Y has the greater range, because its MAD is greater.","Set X has the greater range, but Set Y''s values are typically farther from their mean.","Set X is more spread out by both the range and the MAD."]', 'Set X has the greater range, but Set Y''s values are typically farther from their mean.', NULL, 'Range 40 is greater than 25, so X has the greater range. MAD 8 is greater than 5, so Y''s values are typically farther from their mean. X''s large range can come from one or two far-away values, while the MAD looks at every value.', 'checked', '{"lint":[],"solve":{"answer":"Set X has the greater range, but Set Y''s values are typically farther from their mean.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X range 40 > 25; Y MAD 8 > 5, so Y''s values typically farther from their mean.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ffa4bd0-d0d7-4bbe-8318-8c05d5f6a415', 'NC26.7.RD.4', 3, 'choice', 'Compare two data sets using center and spread', 'Set A is 25, 28, 30, 32, 35. Set B is 18, 24, 30, 36, 42. Both sets have a mean of 30. How much greater is the MAD of Set B than the MAD of Set A?', '["4.4","7.2","2.8","22"]', '4.4', '((60+30+0+30+60)/25)-((25+10+0+10+25)/25)', 'Set A: distances from 30 are 5, 2, 0, 2, 5, which add to 14, so MAD = 14 / 5 = 2.8. Set B: distances are 12, 6, 0, 6, 12, which add to 36, so MAD = 36 / 5 = 7.2. The difference is 7.2 - 2.8 = 4.4. (7.2 and 2.8 are the two MADs themselves, and 22 is the difference of the totals, 36 - 14, before dividing.)', 'checked', '{"lint":[],"solve":{"answer":"4.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A distances 5,2,0,2,5 = 14, MAD 2.8. B distances 12,6,0,6,12 = 36, MAD 7.2. 7.2-2.8 = 4.4.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38846d7a-c373-419e-b449-75ae3a092b29', 'NC26.7.RD.4', 3, 'choice', 'Compare two data sets using center and spread', 'Box plot A has a least value of 10, a first quartile of 20, a median of 30, a third quartile of 40 and a greatest value of 50. Box plot B has a least value of 10, a first quartile of 25, a median of 30, a third quartile of 35 and a greatest value of 50. Which statement is correct?', '["The two plots have the same median and IQR, but Plot A has the greater range.","The two plots have the same median, range and IQR.","The two plots have the same median and range, but Plot A has the greater IQR.","The two plots have the same range and IQR, but Plot A has the greater median."]', 'The two plots have the same median and range, but Plot A has the greater IQR.', NULL, 'Both plots have a median of 30 and a range of 50 - 10 = 40. Plot A has IQR 40 - 20 = 20, and Plot B has IQR 35 - 25 = 10. So A has the greater IQR.', 'checked', '{"lint":[],"solve":{"answer":"The two plots have the same median and range, but Plot A has the greater IQR.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: median 30, range 40, IQR 20. B: median 30, range 40, IQR 10. Same median and range, A greater IQR.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('093da897-6232-4f79-829e-427b8391b539', 'NC26.7.RD.4', 3, 'numeric', 'Compare two data sets using center and spread', 'Plot R has 2 dots at 3, 6 dots at 5 and 2 dots at 7. Plot S has 4 dots at 3, 2 dots at 5 and 4 dots at 7. Both plots have a mean of 5. The MAD of Plot S is how many times the MAD of Plot R?', '[]', '2', '((20+20+20+20+0+0+20+20+20+20)/100)/((20+20+0+0+0+0+0+0+20+20)/100)', 'Plot R: the distances from 5 are 2 (twice), 0 (six times) and 2 (twice), which add to 8, so MAD = 8 / 10 = 0.8. Plot S: 2 (four times), 0 (twice) and 2 (four times), which add to 16, so MAD = 16 / 10 = 1.6. Since 1.6 / 0.8 = 2, the MAD of S is 2 times the MAD of R.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R: distances 2*2 + 6*0 + 2*2 = 8, MAD 0.8. S: 4*2 + 2*0 + 4*2 = 16, MAD 1.6. 1.6/0.8 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80692ba1-4a6b-415c-b026-2c521c6e5bbe', 'NC26.7.RD.4', 3, 'numeric', 'Describe the effect of an extreme value', 'The mean of six values is 15. When one value is removed, the mean of the remaining five values is 12. What value was removed?', '[]', '30', '6*15-5*12', 'The six values add to 6 x 15 = 90. The remaining five add to 5 x 12 = 60. The removed value was 90 - 60 = 30.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 6*15=90; remaining 5*12=60; removed 90-60=30.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd69d656-1532-4bcd-8be2-1c35146df18f', 'NC26.7.RD.4', 3, 'numeric', 'Describe the effect of an extreme value', 'The data set 10, 12, 14, 16, 18 has a mean of 14. The value 18 is replaced by 38, so the new data set is 10, 12, 14, 16, 38. By how much does the mean absolute deviation (MAD) increase?', '[]', '5.6', '((40+30+20+10+100)/25)-((20+10+0+10+20)/25)', 'Original: distances from 14 are 4, 2, 0, 2 and 4, which add to 12, so MAD = 12 / 5 = 2.4. New: the mean is 90 / 5 = 18; distances from 18 are 8, 6, 4, 2 and 20, which add to 40, so MAD = 40 / 5 = 8. The MAD increases by 8 - 2.4 = 5.6.', 'checked', '{"lint":[],"solve":{"answer":"5.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Old: distances 4,2,0,2,4 = 12, MAD 2.4. New 10,12,14,16,38: sum 90, mean 18; distances 8,6,4,2,20 = 40, MAD 8. Increase 8-2.4 = 5.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0da3c344-98fe-46c2-a4d8-0874e0fd4e93', 'NC26.7.RD.4', 3, 'choice', 'Describe the effect of an extreme value', 'The data set 2, 4, 6, 8 has a mean of 5 and a MAD of 2. A fifth value, 5, equal to the mean, is added. What happens?', '["The mean stays 5, and the MAD decreases to 1.6.","The mean stays 5, and the MAD stays 2.","The mean decreases, and the MAD decreases.","The mean stays 5, and the MAD increases."]', 'The mean stays 5, and the MAD decreases to 1.6.', NULL, 'The five values add to 25, so the mean is still 5. The new value is 0 away from the mean, so the distances still add to 3 + 1 + 1 + 3 + 0 = 8, but they are now shared among 5 values: 8 / 5 = 1.6, which is less than 2.', 'checked', '{"lint":[],"solve":{"answer":"The mean stays 5, and the MAD decreases to 1.6.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,4,5,6,8: mean 25/5 = 5. Distances 3,1,0,1,3 = 8; MAD 8/5 = 1.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48068aaf-9c30-427c-bfba-04d7b08d2aa3', 'NC26.7.RD.4', 3, 'numeric', 'Describe the effect of an extreme value', 'The data set 4, 6, 8, 10, 12, 14 has an IQR of 6. Two extreme values, 50 and 60, are added. By how much does the IQR increase?', '[]', '19', '(((14+50)/2)-((6+8)/2))-((12)-(6))', 'With 8 values in order: 4, 6, 8, 10, 12, 14, 50, 60, the lower half 4, 6, 8, 10 has median 7 (Q1) and the upper half 12, 14, 50, 60 has median (14 + 50) / 2 = 32 (Q3). The IQR is 32 - 7 = 25. It increases by 25 - 6 = 19. (Two extreme values are enough to move the quartiles.)', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Arithmetic is sound (19), but adding two extremes to six values moves Q3 a lot, which cuts against the usual ''IQR resists extreme values'' lesson this standard teaches; worth checking the key is 19, not a smaller intended value.","work":"Before: 4,6,8 | 10,12,14: Q1 6, Q3 12, IQR 6. After 4,6,8,10 | 12,14,50,60: Q1 (6+8)/2=7, Q3 (14+50)/2=32, IQR 25. Increase 25-6=19.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af798471-0ef5-4f59-a966-513a43cd601b', 'NC26.7.RD.4', 3, 'choice', 'Find a missing value from a measure', 'The six values 4, 7, 10, 14, e, 25 are in order and have an interquartile range of 12. What is the value of e?', '["22","16","19","5"]', '19', '7+12', 'The lower half 4, 7, 10 has median 7, so Q1 = 7. The upper half is 14, e, 25, whose median is e, so Q3 = e. The IQR is e - 7 = 12, so e = 19. Check: 14 < 19 < 25. (22 would come from Q1 = 10, 16 from Q1 = 4, and 5 from 12 - 7.)', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,7,10 | 14,e,25: Q1 = 7, Q3 = e. e-7 = 12, e = 19 (between 14 and 25).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36e79f31-8cf1-4c61-9924-cc6c00a36b57', 'NC26.7.RD.4', 3, 'numeric', 'Find a missing value from a measure', 'The five values 12, 15, 18, 21 and x have a mean of 18. What is the mean absolute deviation (MAD) of the five values?', '[]', '3.6', '(30+15+0+15+30)/25', 'The five values add to 5 x 18 = 90, so x = 90 - (12 + 15 + 18 + 21) = 24. The distances from 18 are 6, 3, 0, 3 and 6, which add to 18. The MAD is 18 / 5 = 3.6.', 'checked', '{"lint":[],"solve":{"answer":"3.6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"66+x = 90, x = 24. Distances from 18: 6,3,0,3,6 = 18; 18/5 = 3.6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e68fa0e2-ecd1-4dea-b5d4-ced7971e7e13', 'NC26.7.RD.4', 3, 'numeric', 'Find a missing value from a measure', 'A data set has a range of 24, and its greatest value is 3 times its least value. All the values are positive. What is the least value?', '[]', '12', '24/(3-1)', 'Let the least value be L. The greatest is 3L, so the range is 3L - L = 2L = 24, and L = 12. Check: the greatest value is 36, and 36 - 12 = 24.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3L - L = 24, L = 12 (greatest 36).","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50e1188f-cf70-4a5b-a309-d305c7f79870', 'NC26.7.RD.4', 3, 'choice', 'Find a missing value from a measure', 'A data set has a range of 30. After 4 is added to every value, the greatest value is 52. What was the least value before 4 was added?', '["22","18","26","14"]', '18', '52-4-30', 'Adding 4 to every value does not change the range, which is still 30. Before adding, the greatest value was 52 - 4 = 48. So the least value was 48 - 30 = 18. (22 forgets to take off the 4, 26 adds the 4 instead, and 14 takes it off twice.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range unchanged by +4. Original greatest 52-4 = 48; least 48-30 = 18.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89a39ebf-5783-461e-9c1d-708f402d0acb', 'NC26.7.RD.4', 3, 'numeric', 'Find a measure from a frequency table or dot plot', 'A table shows the number of minutes 10 students spent on a project: 20 minutes for 3 students, 25 minutes for 2 students, 30 minutes for 1 student and 35 minutes for 4 students. Find the mean absolute deviation (MAD) of the times.', '[]', '6', '(80+80+80+30+30+20+70+70+70+70)/100', 'The total is 3 x 20 + 2 x 25 + 30 + 4 x 35 = 280, so the mean is 280 / 10 = 28. The distances from 28 are 8 (three students), 3 (two students), 2 (one student) and 7 (four students). They add to 24 + 6 + 2 + 28 = 60. The MAD is 60 / 10 = 6 minutes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 3*20+2*25+30+4*35 = 280, mean 28. Distances 3*8 + 2*3 + 1*2 + 4*7 = 24+6+2+28 = 60; 60/10 = 6.","run_id":"claude-code","at":"2026-10-17T20:26:48.219Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('150c7bd7-fe51-4c13-b584-448a5a6a8ed3', 'NC26.7.RD.4', 3, 'numeric', 'Find a missing value from a measure', 'Eight values in order are 3, 5, 8, 10, 14, $x$, 22 and 26. The interquartile range is 12. What is the value of $x$?', '[]', '15', '2*(12+(5+8)/2)-22', 'The lower half is 3, 5, 8, 10, so the first quartile is $(5 + 8) \div 2 = 6.5$. The IQR is 12, so the third quartile is $6.5 + 12 = 18.5$. The upper half is 14, $x$, 22, 26, so the third quartile is $(x + 22) \div 2 = 18.5$. Then $x + 22 = 37$ and $x = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower half 3,5,8,10: Q1=6.5. IQR 12 gives Q3=18.5 = median of upper half 14, x, 22, 26 = (x+22)/2 when 14<=x<=22. x+22=37, x=15 (in range).","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63db31ac-f699-404e-bd18-11c228181252', 'NC26.7.RD.4', 3, 'numeric', 'Find a measure from a frequency table or dot plot', 'A team played 12 games. It scored 0 goals in 3 games, 1 goal in 4 games, 2 goals in 2 games, 3 goals in 1 game and 5 goals in 2 games. What is the interquartile range of the number of goals per game?', '[]', '2', '2.5-0.5', 'In order the 12 numbers of goals are 0, 0, 0, 1, 1, 1, 1, 2, 2, 3, 5, 5. The lower half is 0, 0, 0, 1, 1, 1, so the first quartile is $(0 + 1) \div 2 = 0.5$. The upper half is 1, 2, 2, 3, 5, 5, so the third quartile is $(2 + 3) \div 2 = 2.5$. The IQR is $2.5 - 0.5 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered 12 values: 0,0,0,1,1,1,1,2,2,3,5,5. Lower half 0,0,0,1,1,1: Q1=0.5. Upper half 1,2,2,3,5,5: Q3=2.5. IQR 2.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a696698b-3cff-4a61-8143-0662ef4b586b', 'NC26.7.RD.5', 1, 'choice', 'Compare two groups by their medians', 'The median reading time of Group A is 24 minutes and the median reading time of Group B is 30 minutes. Which statement is best supported by these medians?', '["A typical student in Group B read longer than a typical student in Group A","Every student in Group B read longer than every student in Group A","A typical student in Group A read longer than a typical student in Group B","Both groups read for about the same amount of time"]', 'A typical student in Group B read longer than a typical student in Group A', NULL, 'The median describes a typical value. Group B''s median is greater, so a typical student in Group B read longer. The medians do not tell us that every student in B read longer than every student in A.', 'checked', '{"lint":[],"solve":{"answer":"A typical student in Group B read longer than a typical student in Group A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median B 30 > median A 24, so a typical B student read longer. Medians say nothing about every student.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20c09b8c-d0fa-47ee-b3d5-0ab127f01c71', 'NC26.7.RD.5', 1, 'numeric', 'Compare two groups by their means', 'Group A read for 20, 25, 30 and 35 minutes. Group B read for 12, 14, 18 and 22 minutes. How many more minutes did Group A read than Group B, on average (using the mean)?', '[]', '11', '(20+25+30+35)/4-(12+14+18+22)/4', 'Mean of A: $110 \div 4 = 27.5$ minutes. Mean of B: $66 \div 4 = 16.5$ minutes. The difference is $27.5 - 16.5 = 11$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 110/4 = 27.5. B: 66/4 = 16.5. Difference 11.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b147a346-8b2f-4b35-8e58-649b2bafb8c3', 'NC26.7.RD.5', 1, 'choice', 'Plan an investigation of two groups', 'A student wants to compare how many books sixth graders and seventh graders read in a month. Which plan is best?', '["Ask 20 students who are checking out books at the library","Ask 20 sixth graders and 20 seventh graders, each chosen at random, how many books they read this month","Ask 20 seventh graders and use the answers for both grades","Ask 20 sixth graders and 20 seventh graders which grade reads more"]', 'Ask 20 sixth graders and 20 seventh graders, each chosen at random, how many books they read this month', NULL, 'To compare two groups we need numerical data from a random sample of each group. Library visitors are likely to read more than other students, using only one grade says nothing about the other, and asking which grade reads more gathers opinions instead of counts.', 'checked', '{"lint":[],"solve":{"answer":"Ask 20 sixth graders and 20 seventh graders, each chosen at random, how many books they read this month","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random samples from both groups, asking the numeric question, is the sound comparison.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
