INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5905a95e-c330-429c-8679-412f31149873', 'NC26.7.RD.5', 1, 'numeric', 'Compare the means of two groups', 'On four days, Rosa walked 3, 5, 4 and 4 kilometers. On the same four days, Eli walked 2, 3, 3 and 4 kilometers. How many kilometers greater is Rosa''s mean daily distance than Eli''s mean daily distance?', '[]', '1', '((3+5+4+4)/4)-((2+3+3+4)/4)', 'Rosa''s mean is (3 + 5 + 4 + 4) divided by 4, which is 4. Eli''s mean is (2 + 3 + 3 + 4) divided by 4, which is 3. The difference is 4 - 3 = 1 kilometer.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rosa: 3+5+4+4=16, mean 4. Eli: 2+3+3+4=12, mean 3. 4-3=1.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ef3e32b-0587-4791-9113-c47df2b018dd', 'NC26.7.RD.5', 1, 'numeric', 'Compare the means of two groups', 'Each of two teams played 5 games. Team A scored a mean of 18 points per game and Team B scored a mean of 14 points per game. How many more points did Team A score than Team B in all 5 games?', '[]', '20', '5*18-5*14', 'A mean of 18 over 5 games means 5 x 18 = 90 points in all for Team A. Team B scored 5 x 14 = 70 points. The difference is 90 - 70 = 20 points.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Team A total 18*5=90; Team B total 14*5=70; 90-70=20.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('301d46ce-9601-4c1a-9293-c8b4a8972df7', 'NC26.7.RD.5', 1, 'numeric', 'Compare the medians of two groups', 'Seven students in Room 1 own 0, 1, 1, 2, 3, 3 and 5 pets. Seven students in Room 2 own 1, 2, 2, 4, 4, 5 and 6 pets. (Both lists are in order.) How many more pets does the median student in Room 2 own than the median student in Room 1?', '[]', '2', '4-2', 'With 7 values the median is the 4th one. Room 1: the 4th value is 2. Room 2: the 4th value is 4. The difference is 4 - 2 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Room 1 median = 4th of 7 = 2. Room 2 median = 4th = 4. 4-2=2.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63ade2bc-1cf5-472f-b15c-e74e9d222486', 'NC26.7.RD.5', 1, 'choice', 'Compare the medians of two groups', 'Lila''s group has the values 3, 5, 6, 9 and 12. Marco''s group has the values 2, 7, 8, 10 and 11. (Both lists are in order.) What are the medians of the two groups?', '["Lila: 6, Marco: 8","Lila: 7, Marco: 7.6","Lila: 5, Marco: 7","Lila: 12, Marco: 11"]', 'Lila: 6, Marco: 8', NULL, 'With 5 values in order, the median is the middle (3rd) value: 6 for Lila and 8 for Marco. (7 and 7.6 are the means, 5 and 7 are the 2nd values, and 12 and 11 are the greatest values.)', 'checked', '{"lint":[],"solve":{"answer":"Lila: 6, Marco: 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lila middle (3rd) value 6; Marco middle value 8.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cede98b-f531-40cb-8300-0239cd47a1da', 'NC26.7.RD.5', 1, 'numeric', 'Compare the ranges of two groups', 'Over a season, Team X scored as few as 10 points and as many as 30 points in a game. Team Y scored as few as 12 points and as many as 22 points. How much greater is the range of Team X''s scores than the range of Team Y''s scores?', '[]', '10', '(30-10)-(22-12)', 'The range is the greatest value minus the least value. Team X: 30 - 10 = 20. Team Y: 22 - 12 = 10. The range of Team X is 20 - 10 = 10 points greater.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X range 30-10=20; Y range 22-12=10; 20-10=10.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cb42c57-7714-4706-bc69-6d963a7eb802', 'NC26.7.RD.5', 1, 'choice', 'Compare the ranges of two groups', 'Group A has the values 5, 9, 12 and 20. Group B has the values 7, 10, 11 and 13. Which group has the greater range?', '["Group B, whose range is 13","Group A, whose range is 15","Group A, whose range is 20","Group B, whose range is 6"]', 'Group A, whose range is 15', NULL, 'Range = greatest value - least value. Group A: 20 - 5 = 15. Group B: 13 - 7 = 6. Group A has the greater range, 15. (13 and 20 are greatest values, not ranges, and 6 is the range of the other group.)', 'checked', '{"lint":[],"solve":{"answer":"Group A, whose range is 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A range 20-5=15; B range 13-7=6. A greater, range 15.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6884fb5-f74a-46c4-8017-880fb5e37cc9', 'NC26.7.RD.5', 1, 'numeric', 'Compare the IQRs of two groups', 'Group 1 has a first quartile of 12 and a third quartile of 20. Group 2 has a first quartile of 14 and a third quartile of 18. How much greater is the IQR of Group 1 than the IQR of Group 2?', '[]', '4', '(20-12)-(18-14)', 'The IQR is the third quartile minus the first quartile. Group 1: 20 - 12 = 8. Group 2: 18 - 14 = 4. The IQR of Group 1 is 8 - 4 = 4 greater.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR1 = 20-12 = 8; IQR2 = 18-14 = 4; 8-4=4.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f953a86-767d-4d42-a7e8-ea5ff5321ee5', 'NC26.7.RD.5', 1, 'choice', 'Compare the IQRs of two groups', 'Group A has an IQR of 6 and Group B has an IQR of 11. Which statement must be true?', '["The middle half of Group A''s values is more spread out than the middle half of Group B''s","The median of Group B is 5 greater than the median of Group A","Group B has 5 more values than Group A","The middle half of Group B''s values is more spread out than the middle half of Group A''s"]', 'The middle half of Group B''s values is more spread out than the middle half of Group A''s', NULL, 'The IQR measures how spread out the middle half of the data is. A larger IQR means more spread, so the middle half of Group B (IQR 11) is more spread out than that of Group A (IQR 6). The IQR says nothing about the medians or the number of values.', 'checked', '{"lint":[],"solve":{"answer":"The middle half of Group B''s values is more spread out than the middle half of Group A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR measures the spread of the middle half; 11>6 so B''s middle half is more spread. Says nothing about count or median.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8843533-456a-42ad-b4b1-8cf99f74c285', 'NC26.7.RD.5', 1, 'numeric', 'Compare the mean absolute deviations of two groups', 'The values 7, 9, 11 and 13 have a mean of 10. What is their mean absolute deviation (MAD)?', '[]', '2', '(3+1+1+3)/4', 'The distances from the mean of 10 are 3, 1, 1 and 3. The MAD is the mean of these distances: (3 + 1 + 1 + 3) / 4 = 8 / 4 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 10: 3,1,1,3; sum 8; 8/4=2.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2798fd9-ee89-40cc-98b7-75b462fbb1e3', 'NC26.7.RD.5', 1, 'choice', 'Compare the mean absolute deviations of two groups', 'What does the mean absolute deviation (MAD) of a data set tell you?', '["How far the values are from the mean, on average","The value in the middle of the data","The difference between the greatest and least values","How many values are in the data set"]', 'How far the values are from the mean, on average', NULL, 'The MAD is the mean of the distances between each value and the mean, so it describes how spread out the values are around the mean. The middle value is the median, and the difference between the greatest and least values is the range.', 'checked', '{"lint":[],"solve":{"answer":"How far the values are from the mean, on average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"MAD is the mean of the distances from the mean.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('238ca4a7-fd13-4c03-bc29-0f30742857b2', 'NC26.7.RD.5', 1, 'choice', 'Describe the centre and spread together', 'Ana scored 10, 10, 10 and 10 points in four games. Ben scored 2, 8, 12 and 18 points in four games. Which statement is true?', '["The means are equal, but Ana''s scores vary more than Ben''s","Ana''s mean is greater, because she never scored below 10","Ben''s mean is greater, because he scored 18 in one game","The means are equal, but Ben''s scores vary more than Ana''s"]', 'The means are equal, but Ben''s scores vary more than Ana''s', NULL, 'Both means are 40 / 4 = 10. Ana scored exactly 10 every game, so her scores do not vary at all. Ben''s scores range from 2 to 18, so they vary much more.', 'checked', '{"lint":[],"solve":{"answer":"The means are equal, but Ben''s scores vary more than Ana''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ana mean 10; Ben 2+8+12+18=40, mean 10. Equal means; Ben''s vary more (Ana''s not at all).","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
