INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4831973-bb11-425f-a8df-aadd76116ea5', 'NC26.7.RD.5', 1, 'numeric', 'Compare a difference in centres with the variability', 'Two groups each have a MAD of 5. The mean of one group is 20 and the mean of the other is 30. How many MADs apart are the two means?', '[]', '2', '(30-20)/5', 'The means are 30 - 20 = 10 apart. Each MAD is 5, so the means are 10 / 5 = 2 MADs apart.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30-20=10; 10/5=2 MADs.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
