INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11a795d8-e6a7-4bda-8e9a-83bb9760369b', 'NC26.7.RD.5', 1, 'choice', 'Choose the better measure of centre', 'Five houses on Oak Street cost 150, 155, 160, 165 and 900 thousand dollars. Which measure better describes the price of a typical house on this street?', '["The mean, because it uses every value, so it is always the best choice","The range, because it shows how far apart the prices are","The greatest price, because it is the most important","The median, because one very high price pulls the mean far above the others"]', 'The median, because one very high price pulls the mean far above the others', NULL, 'The median is 160 thousand dollars, which is close to four of the five prices. The mean is 306 thousand dollars, which is pulled far up by the one house that costs 900 thousand and is higher than four of the five prices. So the median describes a typical house better.', 'checked', '{"lint":[],"solve":{"answer":"The median, because one very high price pulls the mean far above the others","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean = 1530/5 = 306, far above four of five prices; median 160 is typical.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31eb8040-cb06-46f9-9c8f-ff34968452a7', 'NC26.7.RD.5', 1, 'numeric', 'Choose the better measure of centre', 'The weights of five backpacks, in pounds, are 8, 9, 9, 10 and 24. Because 24 is much heavier than the rest, the median describes a typical backpack better than the mean does. What is the median weight?', '[]', '9', '9', 'The weights are already in order, and the middle (3rd) one is 9 pounds. The mean would be 60 / 5 = 12 pounds, which is higher than 4 of the 5 backpacks.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered 8,9,9,10,24; middle value 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
