INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36575f79-bd09-4125-883a-4f9e96bdc920', 'NC26.7.RD.5', 1, 'numeric', 'Effect of an outlier on the mean and median', 'The five values 4, 6, 7, 9 and 10 have a median of 7. The 10 is changed to 100. What is the new median?', '[]', '7', NULL, 'In order the values are now 4, 6, 7, 9, 100. The middle (3rd) value is still 7. Changing the greatest value does not change the median.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,6,7,9,100: middle value still 7.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
