INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bde0479c-4f87-40da-9b45-6688a7cc1d7b', 'NC26.7.RD.5', 1, 'numeric', 'Describe the shape of a distribution', 'The data are 3, 10, 11, 12, 12, 13, 14, 30. Most of the values form a cluster from 10 to 14. How many values are in this cluster?', '[]', '6', NULL, 'The values from 10 to 14 are 10, 11, 12, 12, 13 and 14, which is 6 values. The values 3 and 30 are outside the cluster.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values from 10 to 14: 10,11,12,12,13,14 = 6.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
