INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d871723-1e08-4913-bfca-d7b45bdd29d9', 'NC26.7.RD.5', 1, 'numeric', 'Compare the share of each group above a cutoff', 'At the Lakeside club, 6 of the 8 members ran more than 5 kilometers. What percent of the members ran more than 5 kilometers?', '[]', '75', '6/8*100', '6 out of 8 is 6 / 8 = 0.75, which is 75 percent.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Weakly aligned: a one-group percent (6.RP-level) with no comparison; serves only as a step toward comparing groups.","work":"6/8 = 0.75 = 75%.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
