INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db469af1-5d64-4979-ada3-a70d0a76e08f', 'NC26.7.RD.5', 1, 'numeric', 'Compare the share of each group above a cutoff', 'Of the 10 players on Team A, 7 scored at least 12 points. Of the 20 players on Team B, 10 scored at least 12 points. How many percentage points greater is the percent of Team A players who scored at least 12 than the percent of Team B players who did?', '[]', '20', '7/10*100-10/20*100', 'Team A: 7 of 10 is 70 percent. Team B: 10 of 20 is 50 percent. The difference is 70 - 50 = 20 percentage points.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 7/10=70%. B: 10/20=50%. 70-50=20.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
