INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7523a38-a917-49f2-aa5f-5721365bc40a', 'NC26.7.RD.5', 2, 'numeric', 'Use samples to compare two populations', 'A random sample of 40 students at North School found that 12 ride a bike to school. A random sample of 50 students at South School found that 20 ride a bike. North School has 500 students and South School has 600. Based on the samples, about how many more students ride a bike at South School than at North School?', '[]', '90', '(20/50)*600-(12/40)*500', 'North: 12 / 40 = 30 percent, and 30 percent of 500 is 150 students. South: 20 / 50 = 40 percent, and 40 percent of 600 is 240 students. The estimated difference is 240 - 150 = 90 students.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"North: 12/40=0.3, 0.3*500=150. South: 20/50=0.4, 0.4*600=240. 240-150=90.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('302fb59f-891b-4989-8939-f3f8c36ea4b9', 'NC26.7.RD.5', 3, 'choice', 'Communicate a comparison of two groups', 'Plants in the sun had a median height of 24 cm and an IQR of 4 cm. Plants in the shade had a median height of 15 cm and an IQR of 5 cm. Which statement best summarizes the comparison?', '["Sun plants were typically 9 cm taller, and varied much more than shade plants","Sun plants were typically 9 cm taller, and both groups varied by a similar amount","Shade plants were typically 9 cm taller, and both groups varied by a similar amount","The groups were typically the same height, but shade plants varied more"]', 'Sun plants were typically 9 cm taller, and both groups varied by a similar amount', NULL, 'The medians differ by $24 - 15 = 9$ cm, with the sun plants taller. The IQRs, 4 cm and 5 cm, are close compared with a 9 cm difference, so the spread is similar. Only "Sun plants were typically 9 cm taller, and both groups varied by a similar amount" reports both correctly.', 'checked', '{"lint":[],"solve":{"answer":"Sun plants were typically 9 cm taller, and both groups varied by a similar amount","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sun median 24 vs shade 15: sun 9 cm taller. IQRs 4 and 5: similar spread.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b61172c-72c9-42e0-9e40-a4e62aadb6dd', 'NC26.7.RD.5', 3, 'numeric', 'Difference of means in units of MAD', 'Group A has the values 8, 10 and 12. Group B has the values 12, 14 and 16. The difference between the two means is how many times the mean absolute deviation (MAD) of Group A?', '[]', '3', '(14-10)/((2+0+2)/3)', 'Mean of A is 10 and mean of B is 14, so the difference is 4. The distances of A''s values from 10 are 2, 0 and 2, so the MAD of A is $4 \div 3 = \frac{4}{3}$. Then $4 \div \frac{4}{3} = 3$, so the difference is 3 times the MAD.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means 10 and 14; difference 4. MAD A: distances 2, 0, 2; 4/3. 4 / (4/3) = 3.","run_id":"claude-code","at":"2026-10-17T18:34:52.776Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efbd67df-b751-42ba-bcb1-99d1025b621a', 'NC26.7.RD.5', 3, 'numeric', 'Compare the means of two groups', 'Group A has 4 students with a mean score of 70 points. Group B has 6 students with a mean score of 80 points. What is the mean score of all 10 students together?', '[]', '76', '(4*70+6*80)/10', 'Group A scored 4 x 70 = 280 points in total and Group B scored 6 x 80 = 480 points. Together that is 760 points for 10 students, so the mean is 760 / 10 = 76 points. (It is not 75, because Group B has more students.)', 'checked', '{"lint":[],"solve":{"answer":"76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4*70=280, 6*80=480, total 760, 760/10=76.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af46e886-56b6-4255-a905-4178acb159cb', 'NC26.7.RD.5', 3, 'numeric', 'Compare the medians of two groups', 'Group P has the values 4, 7, 10, 12, 15 and 21. Group Q has seven values in order: 5, 8, 10, $x$, 14, 16 and 20. The two groups have the same median. What is the value of $x$?', '[]', '11', '(10+12)/2', 'Group P has 6 values, so its median is the mean of the 3rd and 4th values: (10 + 12) / 2 = 11. Group Q has 7 values, so its median is the 4th value, which is $x$. For the medians to match, $x$ = 11. (11 fits between 10 and 14, so the list stays in order.)', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P median (6 values) = (10+12)/2 = 11. Q median is the 4th value x, so x=11 (fits 10<=11<=14).","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('289f2582-5f9f-48dc-ab3c-ce258a37f944', 'NC26.7.RD.5', 3, 'numeric', 'Compare the medians of two groups', 'A group has 11 values listed from least to greatest, and the median is 30. At least how many of the 11 values are 30 or greater?', '[]', '6', '(11+1)/2', 'With 11 values in order, the median is the 6th value. So the 6th value is 30, and the 7th through 11th values are at least 30. That makes at least 6 values (the 6th to the 11th) that are 30 or greater.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median of 11 ordered values is the 6th, =30. The 6th through 11th values are all >=30: 6 values guaranteed.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b47a922-29ba-4289-b822-78af51f47275', 'NC26.7.RD.5', 3, 'numeric', 'Compare the ranges of two groups', 'Data set 1 has a least value of 13 and a range of 24. Data set 2 has the same greatest value as data set 1, but its range is only 9. What is the least value of data set 2?', '[]', '28', '13+24-9', 'The greatest value of data set 1 is 13 + 24 = 37. Data set 2 also has a greatest value of 37, and its range is 9, so its least value is 37 - 9 = 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Set 1 greatest = 13+24 = 37. Set 2 least = 37-9 = 28.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f999a890-0a8c-4d47-ae6a-023e01093c46', 'NC26.7.RD.5', 3, 'numeric', 'Compare the IQRs of two groups', 'Both lists have 9 values and are in order. Group P: 3, 6, 7, 9, 12, 14, 15, 18, 22. Group Q: 5, 7, 8, 9, 10, 11, 12, 13, 16. To find the quartiles, leave out the median, then take the median of the 4 values below it and of the 4 values above it. By how much does the IQR of Group P exceed the IQR of Group Q?', '[]', '5', '((15+18)/2-(6+7)/2)-((12+13)/2-(7+8)/2)', 'Group P: the median is 12. Lower four values 3, 6, 7, 9 have median 6.5; upper four values 14, 15, 18, 22 have median 16.5; IQR = 16.5 - 6.5 = 10. Group Q: the median is 10. Lower four values 5, 7, 8, 9 have median 7.5; upper four values 11, 12, 13, 16 have median 12.5; IQR = 12.5 - 7.5 = 5. The difference is 10 - 5 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: median 12; lower 3,6,7,9 -> 6.5; upper 14,15,18,22 -> 16.5; IQR 10. Q: median 10; lower 5,7,8,9 -> 7.5; upper 11,12,13,16 -> 12.5; IQR 5. 10-5=5.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('642ae2dd-79e1-4dc0-8c53-176ff8ff3818', 'NC26.7.RD.5', 3, 'numeric', 'Compare the IQRs of two groups', 'Group S has an IQR of 18 and a first quartile of 42. Group T has an IQR of 12 and a third quartile of 70. How much greater is the third quartile of Group T than the third quartile of Group S?', '[]', '10', '70-(42+18)', 'The third quartile equals the first quartile plus the IQR. For Group S: 42 + 18 = 60. Group T''s third quartile is 70. The difference is 70 - 60 = 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S: Q3 = 42+18 = 60. T: Q3 = 70. 70-60=10.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f0e6b27-fcfd-4274-8bf6-6025ddc07a74', 'NC26.7.RD.5', 3, 'numeric', 'Compare the mean absolute deviations of two groups', 'A group has four values and a mean of 20. Three of the values are 14, 18 and 24. What is the MAD of the group?', '[]', '4', '(6+2+4+4)/4', 'The four values add to 4 x 20 = 80. The three known values add to 56, so the fourth value is 80 - 56 = 24. The distances from the mean of 20 are 6, 2, 4 and 4. The MAD is (6 + 2 + 4 + 4) / 4 = 16 / 4 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 4*20=80; fourth value 80-14-18-24=24. Deviations 6,2,4,4 = 16; MAD 16/4=4.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd71cfae-5a71-4861-b79b-694b815605aa', 'NC26.7.RD.5', 3, 'choice', 'Compare the mean absolute deviations of two groups', 'Every value in a data set is increased by 5. What happens to the mean and to the MAD of the data set?', '["The mean increases by 5 and the MAD stays the same","The mean and the MAD both increase by 5","The mean stays the same and the MAD increases by 5","The mean and the MAD both stay the same"]', 'The mean increases by 5 and the MAD stays the same', NULL, 'Adding 5 to every value moves the whole data set up by 5, so the mean goes up by 5. But every value is still the same distance from the mean as before, so the MAD does not change. Example: 4, 8, 9, 15 has mean 9 and MAD 3; 9, 13, 14, 20 has mean 14 and MAD 3.', 'checked', '{"lint":[],"solve":{"answer":"The mean increases by 5 and the MAD stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shifting every value by 5 shifts the mean by 5; distances from the mean are unchanged, so MAD unchanged.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1e3e2b0b-807d-4820-a8ba-789f35b1defe', 'NC26.7.RD.5', 3, 'choice', 'Describe the centre and spread together', 'Group A has a median of 20 and an IQR of 6. Group B has a median of 24 and an IQR of 14. Which statement is true?', '["Group A has the higher median, but its middle half is more than twice as spread out as Group B''s","Group B has the higher median, but its middle half is more than twice as spread out as Group A''s","Group B has the higher median, and its middle half is less spread out than Group A''s","Group A has the higher median, and its middle half is less spread out than Group B''s"]', 'Group B has the higher median, but its middle half is more than twice as spread out as Group A''s', NULL, 'Group B''s median (24) is higher than Group A''s (20). Group B''s IQR is 14 and Group A''s is 6, so B''s middle half is more spread out; 14 is more than 2 x 6 = 12, so it is more than twice as spread out.', 'checked', '{"lint":[],"solve":{"answer":"Group B has the higher median, but its middle half is more than twice as spread out as Group A''s","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B median 24 > 20. B IQR 14 > 2*6=12, so more than twice as spread.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9336d545-db80-4e79-a0dc-dda166f20031', 'NC26.7.RD.5', 3, 'choice', 'Describe the centre and spread together', 'Which pair of groups has the same center (median) but different spread (IQR)?', '["Group 1: median 15, IQR 4; Group 2: median 15, IQR 9","Group 1: median 15, IQR 4; Group 2: median 19, IQR 4","Group 1: median 15, IQR 4; Group 2: median 19, IQR 9","Group 1: median 15, IQR 4; Group 2: median 4, IQR 15"]', 'Group 1: median 15, IQR 4; Group 2: median 15, IQR 9', NULL, 'Same median and different IQR is needed. Only the first pair has two medians of 15 with IQRs of 4 and 9. The other pairs have different medians.', 'checked', '{"lint":[],"solve":{"answer":"Group 1: median 15, IQR 4; Group 2: median 15, IQR 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need equal medians, different IQRs: median 15 both, IQR 4 vs 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c87bb22-aa21-4b6c-9ba3-10d6604438cc', 'NC26.7.RD.5', 3, 'numeric', 'Compare a difference in centres with the variability', 'Group A has the values 20, 22, 26 and 28. Group B has a mean of 36 and the same MAD as Group A. The means of the two groups are how many MADs apart?', '[]', '4', '(36-((20+22+26+28)/4))/((4+2+2+4)/4)', 'Group A''s mean is 96 / 4 = 24. Its distances from 24 are 4, 2, 2 and 4, so its MAD is 12 / 4 = 3. Group B has the same MAD, 3. The means are 36 - 24 = 12 apart, which is 12 / 3 = 4 MADs.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 96, mean 24; deviations 4,2,2,4 =12; MAD 3. Means 36-24=12; 12/3=4.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ff58233-33d7-4b30-b961-04beb135d4b2', 'NC26.7.RD.5', 3, 'numeric', 'Compare a difference in centres with the variability', 'Two groups have the same MAD. Their means are 25 and 40, and that is exactly 3 MADs apart. What is the MAD?', '[]', '5', '(40-25)/3', 'The means are 40 - 25 = 15 apart. That equals 3 MADs, so one MAD is 15 / 3 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40-25=15 = 3*MAD, MAD=5.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f80737c8-e90d-42ec-8671-125a67adc28d', 'NC26.7.RD.5', 3, 'choice', 'Choose the better measure of centre', 'Group A has the values 48, 49, 50, 51, 52. Group B has the values 40, 44, 45, 46, 75. Both groups have a mean of 50. Which statement is true?', '["The mean describes a typical value equally well in both groups, because the means are equal","The median of Group B is greater than the median of Group A","The mean describes a typical value less well in Group B than in Group A","The range of Group B is smaller than the range of Group A"]', 'The mean describes a typical value less well in Group B than in Group A', NULL, 'Group A''s median is 50, matching its mean. Group B''s median is 45, and four of its five values are 46 or less, so the mean of 50 is pulled up by the value 75 and is not typical. Group B has the lower median and the greater range (35 compared with 4).', 'checked', '{"lint":[],"solve":{"answer":"The mean describes a typical value less well in Group B than in Group A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B: sum 250, mean 50, median 45, range 35. A: median 50, range 4. B''s mean 50 is above four of its five values, so it describes B less well. Other options false.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fc6619fb-8c44-4fbf-af4c-6547a3d62804', 'NC26.7.RD.5', 3, 'numeric', 'Effect of an outlier on the mean and median', 'A group has the values 12, 14, 15, 16, 18 and 45. By how much does the mean decrease when the value 45 is removed?', '[]', '5', '((12+14+15+16+18+45)/6)-((12+14+15+16+18)/5)', 'With 45: the total is 120 and the mean is 120 / 6 = 20. Without 45: the total is 75 and the mean is 75 / 5 = 15. The mean decreases by 20 - 15 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 120, mean 20. Without 45: 75/5=15. Decrease 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3fb85002-d91d-454b-ae5d-f1b959528bb8', 'NC26.7.RD.5', 3, 'choice', 'Effect of an outlier on the mean and median', 'A data set has the values 8, 10, 11, 12, 14, 15, 20. The greatest value, 20, is changed to 50. Which measure does NOT change?', '["The median","The mean","The range","The MAD"]', 'The median', NULL, 'The median is the 4th value, 12, before and after, since the changed value is still the greatest. The mean rises (from 12.9 to about 17.1), the range rises (from 12 to 42), and the MAD also changes because the mean and the greatest distance both change.', 'checked', '{"lint":[],"solve":{"answer":"The median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median is the 4th value, 12, unchanged. Mean (90/7 -> 120/7), MAD and range (12 -> 42) all change.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5bc3adcb-200f-44ae-b407-f0f43bdd92e7', 'NC26.7.RD.5', 3, 'choice', 'Describe the shape of a distribution', 'Group A has the values 10, 11, 12, 12, 13, 14. Group B has the values 1, 2, 3, 30, 31, 32. Which statement is true?', '["Group A has two clusters with a gap between them","Group B has two clusters with a gap, and its mean and median fall in the gap","Group B has one cluster, and its mean and median lie within it","Group A has the greater range"]', 'Group B has two clusters with a gap, and its mean and median fall in the gap', NULL, 'Group B''s values form two clusters (1 to 3 and 30 to 32) with a large gap between them. Its mean is 99 / 6 = 16.5 and its median is (3 + 30) / 2 = 16.5, and both fall in the gap, where there are no data. Group A forms one tight cluster, and its range (4) is far less than Group B''s (31).', 'checked', '{"lint":[],"solve":{"answer":"Group B has two clusters with a gap, and its mean and median fall in the gap","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: one cluster, range 4. B: clusters 1-3 and 30-32; mean 99/6=16.5, median (3+30)/2=16.5, both in the gap.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47538e50-98ac-4e30-bc14-ac22023c3edd', 'NC26.7.RD.5', 3, 'numeric', 'Describe the shape of a distribution', 'The data 1, 2, 3, 3, 4, 4, 11 are skewed to the right. How much greater is the mean than the median?', '[]', '1', '((1+2+3+3+4+4+11)/7)-3', 'The mean is 28 / 7 = 4. The median (4th value) is 3. The mean is 4 - 3 = 1 greater than the median, as is usual when a few large values pull the mean toward the right.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 28, mean 4. Median = 4th value = 3. 4-3=1.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21591c47-f62f-4978-95db-d9b245d2af84', 'NC26.7.RD.5', 3, 'numeric', 'Compare the share of each group above a cutoff', 'In Group A, 40 students took a test and 45 percent scored above 70. In Group B, 80 students took the test and 30 percent scored above 70. How many more students in Group B than in Group A scored above 70?', '[]', '6', '0.3*80-0.45*40', 'Group A: 45 percent of 40 is 0.45 x 40 = 18 students. Group B: 30 percent of 80 is 0.30 x 80 = 24 students. Group B has 24 - 18 = 6 more students above 70, even though a smaller percent of Group B scored above 70.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 0.45*40=18. B: 0.30*80=24. 24-18=6.","run_id":"claude-code","at":"2026-10-17T20:27:47.565Z"}}', 'ai', NULL, NULL)
