INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74ebc0e1-51f4-40c9-91b5-240d541a3846', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation that needs the distributive property', 'Find the value of $x$ that solves $3x = 2(x + 7)$.', '[]', '14', '(14)/(1)', 'Simplify each side: $3x = 2x + 14$. Move the $x$ terms to one side and the numbers to the other: $x = 14$. Check: with $x = 14$ both sides equal $42$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 2x + 14 -> x = 14. Check: 42 = 42.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('031686c6-8c13-4962-9c3b-c1a77711db45', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an equation that needs the distributive property', 'Which equation is the result of using the distributive property on the left side of $4(2x - 3) = x + 5$?', '["$8x - 3 = x + 5$","$8x + 12 = x + 5$","$8x - 12 = x + 5$","$2x - 12 = x + 5$"]', '$8x - 12 = x + 5$', NULL, 'The 4 multiplies both terms inside the parentheses: $4(2x - 3) = 4 \cdot 2x - 4 \cdot 3 = 8x - 12$. So the equation becomes $8x - 12 = x + 5$. The other choices multiply only one of the terms, change a sign, or multiply the wrong term.', 'checked', '{"lint":[],"solve":{"answer":"$8x - 12 = x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2x - 3) = 8x - 12; right side unchanged.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2ff4b0b-c913-4b78-a2d4-78201e475b43', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation after combining like terms', 'Solve for $x$: $6x - 2x + 7 = x + 19$', '[]', '4', '(12)/(3)', 'Simplify each side: $4x + 7 = x + 19$. Move the $x$ terms to one side and the numbers to the other: $3x = 12$. Divide both sides by $3$: $x = 4$. Check: with $x = 4$ both sides equal $23$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 7 = x + 19 -> 3x = 12 -> x = 4. Check: 23 = 23.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('151adf9a-61d4-45db-93d1-7c39d1e4e510', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an equation after combining like terms', 'What is the left side of $7x + 3 - 2x - 8 = 4x + 1$ after combining like terms?', '["$9x - 5$","$5x - 5$","$5x + 5$","$5x - 11$"]', '$5x - 5$', NULL, 'Combine the $x$ terms: $7x - 2x = 5x$. Combine the numbers: $3 - 8 = -5$. So the left side is $5x - 5$. The other choices add $7x$ and $2x$, get the sign of the numbers wrong, or add 3 and 8.', 'checked', '{"lint":[],"solve":{"answer":"$5x - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x - 2x = 5x; 3 - 8 = -5. Left side 5x - 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6faf173d-b791-4585-bcfe-2f312d516a9c', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve for $x$: $0.5x + 4 = 0.3x + 6$', '[]', '10', '(2)/(1/5)', 'Move the $x$ terms to one side and the numbers to the other: $0.2x = 2$. Divide both sides by $0.2$: $x = 10$. Check: with $x = 10$ both sides equal $9$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.2x = 2 -> x = 10. Check: 9 = 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
