INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67e2f9d3-8051-4bd2-8de1-95d8210768ba', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'What value of $x$ solves $\frac{x}{2} + 3 = x - 1$?', '[]', '8', '((0-4))/((0-1/2))', 'Simplify each side: $\frac{1}{2}x + 3 = x - 1$. Move the $x$ terms to one side and the numbers to the other: $-\frac{1}{2}x = -4$. Divide both sides by $-\frac{1}{2}$: $x = 8$. Check: with $x = 8$ both sides equal $7$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 = x - x/2 = x/2 -> x = 8. Check: 7 = 7.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63f0fc71-3a96-45eb-9bce-2ba71406ad7d', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an equation with fraction or decimal coefficients', 'What is the smallest whole number you can multiply both sides of $\frac{x}{3} + 2 = \frac{x}{2}$ by to clear all of the fractions?', '["$5$","$3$","$12$","$6$"]', '$6$', '2*3', 'The denominators are 3 and 2. The smallest number that both 3 and 2 divide into is 6. Multiplying by 6 gives $2x + 12 = 3x$, with no fractions. Multiplying by 3 leaves $\frac{3x}{2}$, and 12 works but is not the smallest.', 'checked', '{"lint":[],"solve":{"answer":"$6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Denominators 3 and 2; least common multiple 6.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42385871-560e-4afe-88e2-7003333a47c5', 'NC26.8.ANFR.1', 1, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'How many solutions does $2x + 5 = 2x + 9$ have?', '["Exactly one solution","Infinitely many solutions","No solution","Exactly two solutions"]', 'No solution', NULL, 'Move the $x$ terms to one side and the numbers to the other: $0 = 4$. The $x$ terms cancel and what is left is never true, so there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Subtract 2x: 5 = 9, false, so no solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7055295-bc6a-45d0-b17d-8a8acd06f325', 'NC26.8.ANFR.1', 1, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Which statement about $6x - 4 = 6x - 4$ is true?', '["It is true for exactly one value of $x$","It is true for every value of $x$","It is true for no value of $x$","It is true for exactly two values of $x$"]', 'It is true for every value of $x$', NULL, 'Move the $x$ terms to one side and the numbers to the other: $0 = 0$. The $x$ terms cancel and what is left is always true, so every number is a solution.', 'checked', '{"lint":[],"solve":{"answer":"It is true for every value of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both sides identical, so true for every x.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97c6f9cd-3432-498e-b7a1-bcf9ee8315c0', 'NC26.8.ANFR.1', 1, 'numeric', 'Find the value that gives no or infinitely many solutions', 'The equation $2x + 7 = 2x + k$ has infinitely many solutions. What is the value of $k$?', '[]', '7', '7', 'For infinitely many solutions, both sides must be the same expression. The $x$ terms already match, so the numbers must match: $k = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same x-coefficient; infinitely many requires constants equal: k = 7.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8e5b888-381e-4cf0-93c6-085a59842c69', 'NC26.8.ANFR.1', 1, 'choice', 'Write an equation for a situation', 'Three times a number, decreased by 4, equals the number increased by 10. Which equation represents this, where $n$ is the number?', '["$3(n - 4) = n + 10$","$3n - 4 = n + 10$","$3n + 4 = n + 10$","$3n - 4 = 10n$"]', '$3n - 4 = n + 10$', NULL, '"Three times a number" is $3n$, "decreased by 4" is $3n - 4$, and "the number increased by 10" is $n + 10$. Setting them equal gives $3n - 4 = n + 10$. The other choices put the 4 inside the multiplication, use plus instead of minus, or multiply the number by 10.', 'checked', '{"lint":[],"solve":{"answer":"$3n - 4 = n + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three times n, decreased by 4: 3n - 4. Number increased by 10: n + 10.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('329a11ae-5466-47ff-b2dc-44192b980c60', 'NC26.8.ANFR.1', 1, 'choice', 'Write an equation for a situation', 'One taxi charges 3 dollars plus 2 dollars per mile. Another taxi charges 1 dollar plus 3 dollars per mile. Let $m$ be the number of miles. Which equation says that the two charges are equal?', '["$3 + 2m = 1 + 3m$","$2 + 3m = 3 + m$","$3 + 2m = 3m$","$3 + 2m = 1 + 2m$"]', '$3 + 2m = 1 + 3m$', NULL, 'The first charge is 3 plus 2 for each mile: $3 + 2m$. The second is 1 plus 3 for each mile: $1 + 3m$. Equal charges give $3 + 2m = 1 + 3m$. The other choices swap the fixed fee and the rate, leave out the 1, or use the wrong rate.', 'checked', '{"lint":[],"solve":{"answer":"$3 + 2m = 1 + 3m$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First 3 + 2m, second 1 + 3m.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('753bf769-d102-4794-95b7-bb278f0f7acf', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve a problem with an equation', 'Five times a number plus 8 equals nine times the number minus 12. What is the number?', '[]', '5', '((0-20))/((0-4))', 'Let $n$ be the number: $5n + 8 = 9n - 12$. Subtract $5n$ from both sides: $8 = 4n - 12$. Add 12 to both sides: $20 = 4n$. Divide by 4: $n = 5$. Check: $5(5) + 8 = 33$ and $9(5) - 12 = 33$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5n + 8 = 9n - 12 -> 20 = 4n -> n = 5. Check: 33 = 33.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d102dc4-e752-4455-84fe-a03b2c0eee9b', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve a problem with an equation', 'A tank holds 50 liters and loses 4 liters every minute. A second tank holds 10 liters and gains 6 liters every minute. After how many minutes will the two tanks hold the same amount?', '[]', '4', '((0-40))/((0-10))', 'After $m$ minutes the first tank holds $50 - 4m$ liters and the second holds $10 + 6m$ liters. Set them equal: $50 - 4m = 10 + 6m$. Then $40 = 10m$, so $m = 4$. Check: $50 - 16 = 34$ and $10 + 24 = 34$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50 - 4t = 10 + 6t -> 40 = 10t -> t = 4. Both hold 34 L.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('baa6148e-6ce8-4976-a31b-1a19a98c316b', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an inequality with the variable on both sides', 'Which inequality shows all of the solutions of $5x + 2 > 2x + 11$?', '["$x < 3$","$x > 3$","$x > 9$","$x > \\frac{9}{7}$"]', '$x > 3$', NULL, 'Move the $x$ terms to one side and the numbers to the other: $3x > 9$. Divide both sides by $3$: $x > 3$. The other choices reverse the sign, forget to divide by 3, or add the $x$ terms instead of subtracting.', 'checked', '{"lint":[],"solve":{"answer":"$x > 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x > 9 -> x > 3.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c1f959c-4d0a-42a5-972c-cda76cfc3571', 'NC26.8.ANFR.1', 1, 'numeric', 'Solve an inequality with the variable on both sides', 'What is the least whole number $x$ that makes $6x - 3 > 2x + 9$ true?', '[]', '4', '12/4+1', 'Move the $x$ terms to one side and the numbers to the other: $4x > 12$. Divide both sides by $4$: $x > 3$. Since $x$ must be greater than 3, the least whole number is 4. (Check: $6(4) - 3 = 21 > 2(4) + 9 = 17$.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x > 12 -> x > 3; least whole number 4 (x = 3 gives 15 > 15, false).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('699c7a9b-ab97-4565-9a37-8178a025530f', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an inequality with the variable on both sides', 'Which value of $x$ is a solution of $3x + 1 < x + 9$?', '["$3$","$4$","$5$","$8$"]', '$3$', '3', 'Move the $x$ terms to one side and the numbers to the other: $2x < 8$. Divide both sides by $2$: $x < 4$. Only 3 is less than 4. (At $x = 4$ both sides equal 13, so 4 is not a solution.)', 'checked', '{"lint":[],"solve":{"answer":"$3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x < 8 -> x < 4. Of 3, 4, 8, 5 only 3.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9148f93b-6ba9-4c8c-a154-50dbc454af1e', 'NC26.8.ANFR.1', 1, 'choice', 'Solve an inequality that needs a sign reversal', 'Which inequality shows all of the solutions of $-2x > 8$?', '["$x < -4$","$x > -4$","$x < 4$","$x > 4$"]', '$x < -4$', NULL, 'Divide both sides by $-2$. Dividing by a negative number reverses the inequality, so $>$ becomes $<$: $x < -4$. (Check: $x = -5$ gives $-2(-5) = 10 > 8$.)', 'checked', '{"lint":[],"solve":{"answer":"$x < -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Only one side has a variable; not an equation/inequality with the variable on both sides, though it tests the sign-reversal property used in this standard.","work":"Divide by -2, reverse: x < -4.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17c023ad-9e6f-4e86-b0dd-41b421ae60c1', 'NC26.8.ANFR.1', 1, 'choice', 'Write an inequality for a situation', 'Club A charges 10 dollars to join plus 3 dollars per visit. Club B charges 4 dollars to join plus 5 dollars per visit. Let $h$ be the number of visits. Which inequality says that Club A costs less than Club B?', '["$10 + 3h > 4 + 5h$","$3 + 10h < 5 + 4h$","$10 + 3h < 5h$","$10 + 3h < 4 + 5h$"]', '$10 + 3h < 4 + 5h$', NULL, 'Club A costs $10 + 3h$ and Club B costs $4 + 5h$. "Costs less than" means $<$, so the inequality is $10 + 3h < 4 + 5h$. The other choices use the wrong sign, swap the joining fees and the rates, or leave out the 4.', 'checked', '{"lint":[],"solve":{"answer":"$10 + 3h < 4 + 5h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 10 + 3h, B: 4 + 5h; A less: 10 + 3h < 4 + 5h.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('920619bb-42f0-4f10-b335-e4bda0367cca', 'NC26.8.ANFR.1', 1, 'choice', 'Write an inequality for a situation', 'Four times a number, plus 3, is at most twice the number minus 9. Which inequality represents this, where $n$ is the number?', '["$4n + 3 \\ge 2n - 9$","$4n + 3 \\le 2n - 9$","$4n + 3 < 2n - 9$","$4(n + 3) \\le 2n - 9$"]', '$4n + 3 \le 2n - 9$', NULL, '"At most" means less than or equal to, so the symbol is $\le$. "Four times a number, plus 3" is $4n + 3$ and "twice the number minus 9" is $2n - 9$. The other choices use $\ge$ (at least), $<$ (which leaves out equal), or put the 3 inside the multiplication.', 'checked', '{"lint":[],"solve":{"answer":"$4n + 3 \\le 2n - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4n + 3 is at most 2n - 9: 4n + 3 <= 2n - 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb1588c4-a21c-4f75-ad83-105c6a7a54a2', 'NC26.8.ANFR.1', 1, 'numeric', 'Name or count the whole numbers that satisfy an inequality', 'How many whole numbers $x$ (0, 1, 2, 3, ...) make $3x + 2 < x + 10$ true?', '[]', '4', '4', 'Move the $x$ terms to one side and the numbers to the other: $2x < 8$. Divide both sides by $2$: $x < 4$. The whole numbers less than 4 are 0, 1, 2 and 3, which is 4 numbers.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x < 8 -> x < 4; whole numbers 0, 1, 2, 3: four.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('632e2d53-8dbe-45f1-89e9-2d04f28a2772', 'NC26.8.ANFR.1', 1, 'numeric', 'Name or count the whole numbers that satisfy an inequality', 'What is the least integer that makes $6x + 1 \ge 2x + 21$ true?', '[]', '5', '20/4', 'Move the $x$ terms to one side and the numbers to the other: $4x \ge 20$. Divide both sides by $4$: $x \ge 5$. So $x$ is 5 or greater, and the least integer is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x >= 20 -> x >= 5; least integer 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28a0573e-d4be-4982-abae-d966ac4f149f', 'NC26.8.ANFR.1', 1, 'choice', 'Find the error in a solution', 'A student solving $3x + 5 = x + 13$ wrote $4x + 5 = 13$ as her first step. What is wrong with this step?', '["Nothing is wrong with this step","She should have divided both sides by 3 first","She added $x$ on the left but subtracted $x$ on the right; $x$ should be subtracted from both sides","She should have subtracted 5 from the left side only"]', 'She added $x$ on the left but subtracted $x$ on the right; $x$ should be subtracted from both sides', NULL, 'To move $x$ off the right side, subtract $x$ from both sides: $3x - x + 5 = 13$, which is $2x + 5 = 13$. The student added $x$ on the left ($3x + x = 4x$) but subtracted $x$ on the right, so the two sides were not changed in the same way.', 'checked', '{"lint":[],"solve":{"answer":"She added $x$ on the left but subtracted $x$ on the right; $x$ should be subtracted from both sides","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"From 3x + 5 = x + 13, removing x from the right but adding to the left gives 4x; correct is subtract x from both: 2x + 5 = 13.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c82eca3-297c-428e-b58d-fb4a71fc5273', 'NC26.8.ANFR.1', 1, 'choice', 'Check a solution and justify the steps', 'Is $x = 4$ a solution of $3x - 2 = 2x + 2$?', '["Yes, because both sides equal 10","No, because the left side is 10 and the right side is 12","Yes, because both sides equal 14","No, because the left side is 14 and the right side is 10"]', 'Yes, because both sides equal 10', NULL, 'Substitute $x = 4$. Left side: $3(4) - 2 = 12 - 2 = 10$. Right side: $2(4) + 2 = 8 + 2 = 10$. The sides are equal, so $x = 4$ is a solution.', 'checked', '{"lint":[],"solve":{"answer":"Yes, because both sides equal 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left 3(4) - 2 = 10; right 2(4) + 2 = 10. Yes.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27635e2b-73a1-40d2-bf43-e9e3aacaeb94', 'NC26.8.ANFR.1', 1, 'numeric', 'Check a solution and justify the steps', 'When $x = 5$, both sides of $4x - 3 = 2x + 7$ have the same value. What is that value?', '[]', '17', '4*5-3', 'Left side: $4(5) - 3 = 20 - 3 = 17$. Right side: $2(5) + 7 = 10 + 7 = 17$. Each side equals 17.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(5) - 3 = 17; 2(5) + 7 = 17.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b02d8e1e-e415-42a8-9894-990ef1b2db96', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation that needs the distributive property', 'Solve for $x$: $4(x - 2) = 2x + 6$', '[]', '7', '(6+8)/(4-2)', 'Distribute: $4x - 8 = 2x + 6$. Subtract $2x$: $2x - 8 = 6$. Add 8: $2x = 14$. Divide by 2: $x = 7$. Check: $4(7 - 2) = 20$ and $2(7) + 6 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 8 = 2x + 6 -> 2x = 14 -> x = 7. Check: 4(5) = 20 = 14 + 6.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb299894-ce21-4e7d-918e-ac884fba4a43', 'NC26.8.ANFR.1', 2, 'choice', 'Recognise an equation with infinitely many solutions', 'How many solutions does the equation $3(x + 2) = 3x + 6$ have?', '["Infinitely many solutions","No solution","Exactly one solution, $x = 0$","Exactly one solution, $x = 6$"]', 'Infinitely many solutions', NULL, 'Distribute on the left: $3x + 6 = 3x + 6$. Both sides are exactly the same expression, so the equation is true for every value of $x$. It has infinitely many solutions.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many solutions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 2) = 3x + 6, identical to the right side, so every x works: infinitely many solutions.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94684697-319e-4880-8eaa-82608bd61087', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an inequality where dividing by a negative reverses the sign', 'Which inequality shows all the solutions of $5 - 2x \ge x - 7$?', '["$x \\ge 4$","$x \\ge -4$","$x \\le 4$","$x \\le 12$"]', '$x \le 4$', NULL, 'Add $2x$ to both sides: $5 \ge 3x - 7$. Add 7: $12 \ge 3x$. Divide by 3: $4 \ge x$, which is the same as $x \le 4$. Check: $x = 0$ gives $5 \ge -7$, which is true.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 2x >= x - 7 -> 12 >= 3x -> x <= 4. Check x=4: -3 >= -3 true; x=5: -5 >= -2 false.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a620aa30-69d4-4505-91f3-985891d3faff', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation with the variable on both sides', 'Solve: $-4x + 14 = 2x - 22$', '[]', '6', '((0-36))/((0-6))', 'Move the $x$ terms to one side and the numbers to the other: $-6x = -36$. Divide both sides by $-6$: $x = 6$. Check: with $x = 6$ both sides equal $-10$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 + 22 = 2x + 4x -> 36 = 6x -> x = 6. Check: -10 = -10.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca81d7f3-5461-45dc-84c4-6e5ac43d6b77', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an equation with the variable on both sides', 'Which equation has the solution $x = 6$?', '["$3x - 4 = x + 8$","$3x + 4 = x + 8$","$3x - 4 = x - 8$","$4x - 3 = 2x + 8$"]', '$3x - 4 = x + 8$', NULL, 'Put $x = 6$ into each equation. In $3x - 4 = x + 8$ the left side is $3(6) - 4 = 14$ and the right side is $6 + 8 = 14$, so it works. In $3x + 4 = x + 8$ the sides are 22 and 14. In $3x - 4 = x - 8$ they are 14 and $-2$. In $4x - 3 = 2x + 8$ they are 21 and 20.', 'checked', '{"lint":[],"solve":{"answer":"$3x - 4 = x + 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=6: (a) 22 vs 14; (b) 14 vs -2; (c) 14 vs 14 true; (d) 21 vs 20. Only (c).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9685a6c-b28a-4d73-999c-91d74ae34599', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation that needs the distributive property', 'Solve for $x$: $4(2x - 1) = 3(x + 2)$', '[]', '2', '(10)/(5)', 'Simplify each side: $8x - 4 = 3x + 6$. Move the $x$ terms to one side and the numbers to the other: $5x = 10$. Divide both sides by $5$: $x = 2$. Check: with $x = 2$ both sides equal $12$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x - 4 = 3x + 6 -> 5x = 10 -> x = 2. Check: 12 = 12.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32f525a7-3fb6-48ac-baf0-d0ae968a8d48', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation that needs the distributive property', 'What value of $x$ makes this equation true? $-2(x - 5) = 3x + 15$', '[]', '-1', '(5)/((0-5))', 'Simplify each side: $-2x + 10 = 3x + 15$. Move the $x$ terms to one side and the numbers to the other: $-5x = 5$. Divide both sides by $-5$: $x = -1$. Check: with $x = -1$ both sides equal $12$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x + 10 = 3x + 15 -> -5 = 5x -> x = -1. Check: 12 = 12.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
