INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b04fd79e-c902-4be9-ae9f-4c27668cf150', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an equation after combining like terms', 'Which equation is equivalent to $4x + 5 - x = 2x - 9 + 6x$ after combining like terms on each side?', '["$3x + 5 = 8x - 9$","$5x + 5 = 8x - 9$","$3x + 5 = 8x + 9$","$4x + 5 = 8x - 9$"]', '$3x + 5 = 8x - 9$', NULL, 'Left side: $4x - x = 3x$, so it is $3x + 5$. Right side: $2x + 6x = 8x$, so it is $8x - 9$. The equation is $3x + 5 = 8x - 9$. The other choices add $4x$ and $x$, change the sign of 9, or leave out the $-x$.', 'checked', '{"lint":[],"solve":{"answer":"$3x + 5 = 8x - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left: 4x - x + 5 = 3x + 5. Right: 2x + 6x - 9 = 8x - 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d2897ff-118d-48a9-8c03-af024c2be779', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve: $\frac{2}{3}x - 4 = \frac{1}{6}x + 5$', '[]', '18', '(9)/(1/2)', 'Move the $x$ terms to one side and the numbers to the other: $\frac{1}{2}x = 9$. Divide both sides by $\frac{1}{2}$: $x = 18$. Check: with $x = 18$ both sides equal $8$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3 - 1/6)x = 9 -> (1/2)x = 9 -> x = 18. Check: 12 - 4 = 8; 3 + 5 = 8.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
