INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e58cc75b-c339-470a-aaa2-1293c260a740', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an equation with fraction or decimal coefficients', 'Which equation is equivalent to $\frac{x}{4} + \frac{1}{2} = \frac{x}{2} - 1$ and has no fractions?', '["$x + 2 = 2x - 1$","$x + 1 = 2x - 4$","$x + 2 = 2x - 4$","$x + 2 = x - 4$"]', '$x + 2 = 2x - 4$', NULL, 'Multiply every term on both sides by 4: $4 \cdot \frac{x}{4} = x$, $4 \cdot \frac{1}{2} = 2$, $4 \cdot \frac{x}{2} = 2x$ and $4 \cdot (-1) = -4$. The result is $x + 2 = 2x - 4$. The other choices forget to multiply a term by 4 or multiply a term by the wrong amount.', 'checked', '{"lint":[],"solve":{"answer":"$x + 2 = 2x - 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply by 4: x + 2 = 2x - 4.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64e48150-1813-46b6-8842-06c56067a09c', 'NC26.8.ANFR.1', 2, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Solve $2(x + 3) = 2x + 5$ and decide how many solutions it has.', '["Exactly one solution","Infinitely many solutions","Exactly two solutions","No solution"]', 'No solution', NULL, 'Simplify each side: $2x + 6 = 2x + 5$. Move the $x$ terms to one side and the numbers to the other: $0 = -1$. The $x$ terms cancel and what is left is never true, so there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 6 = 2x + 5 -> 6 = 5, false: no solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffc830de-791f-4f09-9740-752c0a769380', 'NC26.8.ANFR.1', 2, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Which statement about $4x + 8 = 4(x + 2)$ is true?', '["It is true for every value of $x$","It is true for exactly one value of $x$","It is true for no value of $x$","It is true for exactly two values of $x$"]', 'It is true for every value of $x$', NULL, 'Simplify each side: $4x + 8 = 4x + 8$. Move the $x$ terms to one side and the numbers to the other: $0 = 0$. The $x$ terms cancel and what is left is always true, so every number is a solution.', 'checked', '{"lint":[],"solve":{"answer":"It is true for every value of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(x + 2) = 4x + 8, identical: every value.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b600dbe7-aff1-4297-91b8-3f221440fbf2', 'NC26.8.ANFR.1', 2, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'How many solutions does the equation $7x + 2 = 5x + 2$ have?', '["No solution","Infinitely many solutions","Exactly two solutions","Exactly one solution"]', 'Exactly one solution', NULL, 'Move the $x$ terms to one side and the numbers to the other: $2x = 0$. Divide both sides by $2$: $x = 0$. Check: with $x = 0$ both sides equal $2$. The only solution is $x = 0$, so there is exactly one solution (the constants match, but the $x$ terms do not).', 'checked', '{"lint":[],"solve":{"answer":"Exactly one solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x = 0 -> x = 0: exactly one solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f98fca26-1354-44b5-bdbd-b8e22f896a30', 'NC26.8.ANFR.1', 2, 'numeric', 'Find the value that gives no or infinitely many solutions', 'For what value of $k$ does $5x + k = 5(x - 3)$ have infinitely many solutions?', '[]', '-15', '5*(0-3)', 'Expand the right side: $5(x - 3) = 5x - 15$. The equation $5x + k = 5x - 15$ is true for every $x$ exactly when $k = -15$.', 'checked', '{"lint":[],"solve":{"answer":"-15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5(x - 3) = 5x - 15, so k = -15.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b54a4c58-38c5-4333-9d63-06b7e93d8a5e', 'NC26.8.ANFR.1', 2, 'choice', 'Find the value that gives no or infinitely many solutions', 'The equation $4x - 9 = 4x + m$ has infinitely many solutions. What is the value of $m$?', '["$9$","$0$","$-9$","$4$"]', '$-9$', '0-9', 'Both sides have $4x$. For the equation to be true for every $x$, the numbers must match too, so $m = -9$. With any other value of $m$ the equation has no solution.', 'checked', '{"lint":[],"solve":{"answer":"$-9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Constants must match: m = -9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffdce7bd-6083-4cd8-8d34-9f17632a31c4', 'NC26.8.ANFR.1', 2, 'choice', 'Write an equation for a situation', 'A rectangle has length $x + 6$ and width 3. A square has side length $x$. Which equation says that the rectangle and the square have the same perimeter?', '["$3(x + 6) = 4x$","$x + 6 + 3 = 4x$","$2(x + 6) + 3 = 4x$","$2(x + 6) + 2(3) = 4x$"]', '$2(x + 6) + 2(3) = 4x$', NULL, 'The perimeter of the rectangle is twice the length plus twice the width: $2(x + 6) + 2(3)$. The perimeter of the square is $4x$. So the equation is $2(x + 6) + 2(3) = 4x$. The other choices find an area, add each side once, or count the width only once.', 'checked', '{"lint":[],"solve":{"answer":"$2(x + 6) + 2(3) = 4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle perimeter 2(x + 6) + 2(3); square 4x.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a9335ef-06a7-4401-8b3e-256a79a10b62', 'NC26.8.ANFR.1', 2, 'choice', 'Write an equation for a situation', 'A candle 20 cm tall burns down 2 cm each hour. A second candle 15 cm tall burns down 1 cm each hour. Let $h$ be the number of hours. Which equation says that the two candles are the same height?', '["$20 - 2h = 15 - h$","$20 + 2h = 15 + h$","$20 - 2h = 15 + h$","$20 - 2h = 15$"]', '$20 - 2h = 15 - h$', NULL, 'After $h$ hours the first candle is $20 - 2h$ cm tall and the second is $15 - h$ cm tall. Setting them equal gives $20 - 2h = 15 - h$. The candles get shorter, so the terms with $h$ are subtracted.', 'checked', '{"lint":[],"solve":{"answer":"$20 - 2h = 15 - h$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights 20 - 2h and 15 - h.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('391cc9c0-5a3b-4cc4-9250-374e0277381d', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve a problem with an equation', 'Plan A costs 15 dollars a month plus 0.10 dollars for each text. Plan B costs 5 dollars a month plus 0.20 dollars for each text. For how many texts in a month do the two plans cost the same?', '[]', '100', '((0-10))/((0-1/10))', 'For $t$ texts, Plan A costs $15 + 0.10t$ dollars and Plan B costs $5 + 0.20t$ dollars. Set them equal: $15 + 0.10t = 5 + 0.20t$. Then $10 = 0.10t$, so $t = 100$. Check: $15 + 10 = 25$ and $5 + 20 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 0.10t = 5 + 0.20t -> 10 = 0.10t -> t = 100. Both cost $25.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
