INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('517eca9f-c1ff-4c28-9fcf-9834fbb7dd7f', 'NC26.8.ANFR.1', 2, 'choice', 'Solve a problem with an equation', 'Pool X has 100 liters and is filled at 20 liters per minute. Pool Y has 300 liters and is filled at 10 liters per minute. After how many minutes do the two pools hold the same amount?', '["$10$","$30$","$40$","$20$"]', '$20$', '(300-100)/(20-10)', 'After $m$ minutes the pools hold $100 + 20m$ and $300 + 10m$ liters. Setting them equal: $10m = 200$, so $m = 20$ minutes. Check: $100 + 400 = 500$ and $300 + 200 = 500$.', 'checked', '{"lint":[],"solve":{"answer":"$20$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 + 20t = 300 + 10t -> 10t = 200 -> t = 20. Both 500 L.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48389a4e-9da7-4388-912a-ec8ba567884c', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an inequality with the variable on both sides', 'Which inequality is equivalent to $8x - 5 \ge 3x + 20$?', '["$x \\le 5$","$x \\ge 3$","$x \\ge 5$","$x \\ge \\frac{25}{11}$"]', '$x \ge 5$', NULL, 'Move the $x$ terms to one side and the numbers to the other: $5x \ge 25$. Divide both sides by $5$: $x \ge 5$. The other choices reverse the sign, move the 5 the wrong way, or add the $x$ terms.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x >= 25 -> x >= 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d39ea7e9-9458-4e89-a5f0-dc7a0c7c7eee', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an inequality with the variable on both sides', 'What is the smallest integer $x$ that satisfies $9 + 5x > 2x - 6$?', '[]', '-4', '(0-6-9)/3+1', 'Simplify each side: $5x + 9 > 2x - 6$. Move the $x$ terms to one side and the numbers to the other: $3x > -15$. Divide both sides by $3$: $x > -5$. Since $x$ must be greater than $-5$, the smallest integer is $-4$. (Check: $9 + 5(-4) = -11 > 2(-4) - 6 = -14$.)', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x > -15 -> x > -5; smallest integer -4.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c0c4762-f727-4b24-a8b7-cfb655bcca6b', 'NC26.8.ANFR.1', 2, 'numeric', 'Solve an inequality that needs a sign reversal', 'What is the least integer $x$ that satisfies $4 - 3x < 2x + 19$?', '[]', '-2', '0-15/5+1', 'Simplify each side: $-3x + 4 < 2x + 19$. Move the $x$ terms to one side and the numbers to the other: $-5x < 15$. Divide both sides by $-5$. Dividing by a negative number reverses the inequality: $x > -3$. Since $x$ must be greater than $-3$, the least integer is $-2$. (Check: $4 - 3(-2) = 10 < 2(-2) + 19 = 15$.)', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 - 19 < 5x -> -15 < 5x -> x > -3; least integer -2.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f3f7799-2684-461d-a932-0dc8aa5857fd', 'NC26.8.ANFR.1', 2, 'choice', 'Solve an inequality that needs a sign reversal', 'Which inequality shows all of the solutions of $10 - 4x \le 6x - 20$?', '["$x \\le 3$","$x \\ge 3$","$x \\ge -3$","$x \\le -3$"]', '$x \ge 3$', NULL, 'Simplify each side: $-4x + 10 \le 6x - 20$. Move the $x$ terms to one side and the numbers to the other: $-10x \le -30$. Divide both sides by $-10$. Dividing by a negative number reverses the inequality: $x \ge 3$. The other choices forget to reverse the sign or make a sign error with the numbers.', 'checked', '{"lint":[],"solve":{"answer":"$x \\ge 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30 <= 10x -> x >= 3.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29da59f1-1d93-4bd7-ac08-b98efb14175a', 'NC26.8.ANFR.1', 2, 'choice', 'Write an inequality for a situation', 'Ava has 100 dollars and spends 6 dollars each week. Ben has 40 dollars and saves 4 dollars each week. Let $w$ be the number of weeks. Which inequality says that Ava still has more money than Ben?', '["$100 + 6w > 40 - 4w$","$100 - 6w < 40 + 4w$","$100 - 6w > 40 + 4w$","$100 - 6w > 40 - 4w$"]', '$100 - 6w > 40 + 4w$', NULL, 'After $w$ weeks Ava has $100 - 6w$ dollars (she spends) and Ben has $40 + 4w$ dollars (he saves). "More than" means $>$. The other choices mix up who spends and who saves, or use the wrong sign.', 'checked', '{"lint":[],"solve":{"answer":"$100 - 6w > 40 + 4w$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ava 100 - 6w, Ben 40 + 4w; Ava more: 100 - 6w > 40 + 4w.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('972992b4-5ea9-412c-a78d-5844637f9f01', 'NC26.8.ANFR.1', 2, 'choice', 'Write an inequality for a situation', 'Which sentence matches the inequality $2n - 7 > n + 4$?', '["7 more than twice a number is greater than 4 more than the number","7 less than twice a number is greater than 4 less than the number","7 less than twice a number is less than 4 more than the number","7 less than twice a number is greater than 4 more than the number"]', '7 less than twice a number is greater than 4 more than the number', NULL, '$2n - 7$ is 7 less than twice a number, $n + 4$ is 4 more than the number, and $>$ means "is greater than". The other choices change "less" to "more", change "more" to "less", or reverse the comparison.', 'checked', '{"lint":[],"solve":{"answer":"7 less than twice a number is greater than 4 more than the number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2n - 7 is 7 less than twice n; n + 4 is 4 more than n; > is greater than.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca9f1e0c-111f-48ca-b39d-1496a8a94aba', 'NC26.8.ANFR.1', 2, 'numeric', 'Name or count the whole numbers that satisfy an inequality', 'How many integers from $-5$ to $5$, including both $-5$ and $5$, satisfy $2x + 1 > 4x - 5$?', '[]', '8', '8', 'Move the $x$ terms to one side and the numbers to the other: $-2x > -6$. Divide both sides by $-2$. Dividing by a negative number reverses the inequality: $x < 3$. The integers from $-5$ to $5$ that are less than 3 are $-5, -4, -3, -2, -1, 0, 1, 2$, which is 8 integers.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 > 2x -> x < 3. Integers -5..2: 8 values.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97666d2e-f706-49a6-86ca-f32bae602cdf', 'NC26.8.ANFR.1', 2, 'numeric', 'Name or count the whole numbers that satisfy an inequality', 'What is the sum of all of the positive integers that satisfy $3x + 4 \le 2x + 9$?', '[]', '15', '1+2+3+4+5', 'Move the $x$ terms to one side and the numbers to the other: $x \le 5$. The positive integers that are 5 or less are 1, 2, 3, 4 and 5, and their sum is 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x <= 5; positive integers 1..5; sum 15.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
