INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d4d1280f-bf5f-454b-90f4-0f55f508a04b', 'NC26.8.ANFR.1', 2, 'choice', 'Find the error in a solution', 'Li solved $2(x - 4) = x + 3$. Step 1: $2x - 4 = x + 3$. Step 2: $x = 7$. Where is her first mistake?', '["Step 1; the 4 was not multiplied by 2","Step 2; $x$ should have been subtracted from the right side only","There is no mistake","Step 1; 2 should have been added to $x - 4$"]', 'Step 1; the 4 was not multiplied by 2', NULL, 'In Step 1 the 2 must multiply both terms in the parentheses: $2(x - 4) = 2x - 8$, not $2x - 4$. The correct work is $2x - 8 = x + 3$, so $x = 11$. Step 2 is correct for the equation she wrote, but that equation was wrong.', 'checked', '{"lint":[],"solve":{"answer":"Step 1; the 4 was not multiplied by 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x - 4) = 2x - 8, not 2x - 4. Step 1 is the first mistake (correct x = 11).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c3f72d2-75f8-4d61-9659-788c838ea3bf', 'NC26.8.ANFR.1', 2, 'choice', 'Find the error in a solution', 'Omar solved $-3x + 4 < 10$. Step 1: $-3x < 6$. Step 2: $x < -2$. What mistake did he make?', '["In Step 1, he should have added 4 to both sides","In Step 2, he should have written $x < 2$","There is no mistake","In Step 2, he did not reverse the inequality sign when dividing by $-3$"]', 'In Step 2, he did not reverse the inequality sign when dividing by $-3$', NULL, 'Step 1 is correct (subtract 4 from both sides). In Step 2 he divided both sides by $-3$, which reverses the inequality, so the answer is $x > -2$. (Check: $x = 0$ gives $4 < 10$, which is true, and $0 > -2$.)', 'checked', '{"lint":[],"solve":{"answer":"In Step 2, he did not reverse the inequality sign when dividing by $-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Step 1 correct: -3x < 6. Dividing by -3 must reverse: x > -2. He kept <.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a26c0a01-6af0-4ef3-8ae0-87293c6d1595', 'NC26.8.ANFR.1', 2, 'choice', 'Check a solution and justify the steps', 'Which property justifies the step from $3(x + 2) = 9$ to $3x + 6 = 9$?', '["The commutative property of addition","The associative property of multiplication","The distributive property","The identity property of addition"]', 'The distributive property', NULL, 'The 3 outside the parentheses is multiplied by each term inside: $3(x + 2) = 3 \cdot x + 3 \cdot 2 = 3x + 6$. That is the distributive property.', 'checked', '{"lint":[],"solve":{"answer":"The distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(x + 2) = 3x + 6 is the distributive property.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e26f99e-67b3-4ea4-8885-9455f67ae762', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation with fraction coefficients on both sides', 'Solve for $x$: $\frac{1}{2}x + 3 = \frac{1}{4}x + 8$', '[]', '20', '(8-3)/(1/2-1/4)', 'Subtract $\frac{1}{4}x$ from both sides: $\frac{1}{4}x + 3 = 8$. Subtract 3: $\frac{1}{4}x = 5$. Multiply by 4: $x = 20$. Check: $\frac{1}{2}(20) + 3 = 13$ and $\frac{1}{4}(20) + 8 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)x - (1/4)x = 8 - 3 -> (1/4)x = 5 -> x = 20. Check: 10 + 3 = 13 = 5 + 8.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96a68c46-383c-4294-86e1-3d0eaa5c7660', 'NC26.8.ANFR.1', 3, 'choice', 'Find the constant that gives infinitely many solutions', 'The equation $3(2x - 4) = 6x + k$ has infinitely many solutions. What is the value of $k$?', '["$12$","$-4$","$0$","$-12$"]', '$-12$', '0-12', 'Distribute on the left: $6x - 12 = 6x + k$. The $x$ terms already match. The equation is true for every $x$ only when the constants match too, so $k = -12$.', 'checked', '{"lint":[],"solve":{"answer":"$-12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2x - 4) = 6x - 12. For infinitely many solutions 6x - 12 = 6x + k for all x, so k = -12. Any other k gives no solution.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1010f3ba-a88f-4542-8bfb-ad60b98ff79b', 'NC26.8.ANFR.1', 3, 'numeric', 'Use an equation with the variable on both sides to solve a problem', 'Gym A charges 20 dollars to join plus 8 dollars for each visit. Gym B charges 50 dollars to join plus 5 dollars for each visit. After how many visits is the total cost the same at both gyms?', '[]', '10', '(50-20)/(8-5)', 'Let $v$ be the number of visits. Gym A costs $20 + 8v$ and Gym B costs $50 + 5v$. Set them equal: $20 + 8v = 50 + 5v$. Subtract $5v$: $20 + 3v = 50$. Subtract 20: $3v = 30$. So $v = 10$. Check: both cost 100 dollars.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 8v = 50 + 5v -> 3v = 30 -> v = 10. Check: 20 + 80 = 100; 50 + 50 = 100.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bdef931-d435-4985-b5bc-c209191d95d2', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation with the variable on both sides', 'Solve for $x$: $7x - 3 = 2x + 4$', '[]', '7/5', '(7)/(5)', 'Move the $x$ terms to one side and the numbers to the other: $5x = 7$. Divide both sides by $5$: $x = \frac{7}{5}$. Check: with $x = \frac{7}{5}$ both sides equal $\frac{34}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"7/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x = 7 -> x = 7/5. Check: 49/5 - 15/5 = 34/5; 14/5 + 20/5 = 34/5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
