INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab7c43b6-83ca-4666-a399-e3cd60682980', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation that needs the distributive property', 'Solve: $3(2x - 1) - 5 = 2(x + 6) + 4$', '[]', '6', '(24)/(4)', 'Simplify each side: $6x - 8 = 2x + 16$. Move the $x$ terms to one side and the numbers to the other: $4x = 24$. Divide both sides by $4$: $x = 6$. Check: with $x = 6$ both sides equal $28$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 3 - 5 = 2x + 12 + 4 -> 6x - 8 = 2x + 16 -> 4x = 24 -> x = 6. Check: 28 = 28.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
