INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a55b440-762b-4b78-b196-13a9fe46b8d4', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation that needs the distributive property', 'Find the solution of $-3(2x + 1) = 4(x - 2) - 5$.', '[]', '1', '((0-10))/((0-10))', 'Simplify each side: $-6x - 3 = 4x - 13$. Move the $x$ terms to one side and the numbers to the other: $-10x = -10$. Divide both sides by $-10$: $x = 1$. Check: with $x = 1$ both sides equal $-9$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-6x - 3 = 4x - 8 - 5 = 4x - 13 -> 10 = 10x -> x = 1. Check: -9 = -9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
