INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d2d29ca-bda7-4e8c-8f91-84ec5a55387c', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation after combining like terms', 'Find the value of $x$: $4x - 9 + 3x - 2x = 15 - 3x + 6$', '[]', '15/4', '(30)/(8)', 'Simplify each side: $5x - 9 = -3x + 21$. Move the $x$ terms to one side and the numbers to the other: $8x = 30$. Divide both sides by $8$: $x = \frac{15}{4}$. Check: with $x = \frac{15}{4}$ both sides equal $\frac{39}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"15/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left 4x + 3x - 2x - 9 = 5x - 9. Right 21 - 3x. 8x = 30 -> x = 15/4. Check: 75/4 - 36/4 = 39/4; 84/4 - 45/4 = 39/4.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
