INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02621f40-d1a5-4939-b6f1-44c2b51912d5', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an equation with fraction or decimal coefficients', 'Solve: $0.25(x + 8) = 0.5x - 1$', '[]', '12', '((0-3))/((0-1/4))', 'Simplify each side: $0.25x + 2 = 0.5x - 1$. Move the $x$ terms to one side and the numbers to the other: $-0.25x = -3$. Divide both sides by $-0.25$: $x = 12$. Check: with $x = 12$ both sides equal $5$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.25x + 2 = 0.5x - 1 -> 3 = 0.25x -> x = 12. Check: 5 = 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c2deb35-f7a2-4722-b772-026f388a2998', 'NC26.8.ANFR.1', 3, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Which statement about $3(2x - 4) = 2(3x - 6)$ is true?', '["It is true for exactly one value of $x$","It is true for no value of $x$","It is true for every value of $x$","It is true for exactly two values of $x$"]', 'It is true for every value of $x$', NULL, 'Simplify each side: $6x - 12 = 6x - 12$. Move the $x$ terms to one side and the numbers to the other: $0 = 0$. The $x$ terms cancel and what is left is always true, so every number is a solution.', 'checked', '{"lint":[],"solve":{"answer":"It is true for every value of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 12 = 6x - 12: identity, every value.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c697bf0-2e00-4466-9300-f0bf7b9e4285', 'NC26.8.ANFR.1', 3, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'After simplifying, how many solutions does $5(x - 2) + 3 = 5x - 6$ have?', '["No solution","Exactly one solution","Infinitely many solutions","Exactly two solutions"]', 'No solution', NULL, 'Simplify each side: $5x - 7 = 5x - 6$. Move the $x$ terms to one side and the numbers to the other: $0 = 1$. The $x$ terms cancel and what is left is never true, so there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 10 + 3 = 5x - 7; 5x - 7 = 5x - 6 -> -7 = -6 false: no solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8409c9e4-5447-47ab-adbb-fa280f649da5', 'NC26.8.ANFR.1', 3, 'choice', 'Decide whether an equation has one, no or infinitely many solutions', 'Which of these equations has no solution?', '["$2x + 6 = 2(x + 3)$","$2x + 6 = 2(x + 4)$","$2x + 6 = 3x + 6$","$2x + 6 = 6 - 2x$"]', '$2x + 6 = 2(x + 4)$', NULL, '$2x + 6 = 2(x + 4)$ simplifies to $2x + 6 = 2x + 8$, which is never true, so it has no solution. $2x + 6 = 2(x + 3)$ is always true, $2x + 6 = 3x + 6$ gives $x = 0$, and $2x + 6 = 6 - 2x$ also gives $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"$2x + 6 = 2(x + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a) identity; (b) x = 0; (c) 2x + 6 = 2x + 8 -> 6 = 8, no solution; (d) 4x = 0, x = 0.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0cd14783-3abd-4fc2-80bc-36bbdb36b40f', 'NC26.8.ANFR.1', 3, 'numeric', 'Find the value that gives no or infinitely many solutions', 'For what value of $a$ does $ax + 5 = 3x - 2$ have no solution?', '[]', '3', '3', 'No solution happens when the $x$ terms cancel and the leftover numbers are different. If $a = 3$, the equation becomes $3x + 5 = 3x - 2$, which simplifies to $5 = -2$, never true. For any other $a$ there is exactly one solution.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"No solution needs equal x-coefficients and different constants: a = 3 gives 5 = -2, false.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3a981b2-b63f-4104-8b52-4eee5c7185ca', 'NC26.8.ANFR.1', 3, 'numeric', 'Find the value that gives no or infinitely many solutions', 'The equation $a(x + 2) = 5x + 10$ has infinitely many solutions. What is the value of $a$?', '[]', '5', '10/2', 'Expand the left side: $a(x + 2) = ax + 2a$. To match $5x + 10$ exactly, $a = 5$ and $2a = 10$. Both are true when $a = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 10 = 5(x + 2), so a = 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd7305ef-932a-43e3-92b6-610acba4b3d0', 'NC26.8.ANFR.1', 3, 'numeric', 'Find the value that gives no or infinitely many solutions', 'The equation $2(3x + k) = ax + 14$ has infinitely many solutions. What is the value of $a + k$?', '[]', '13', '6+14/2', 'Expand the left side: $2(3x + k) = 6x + 2k$. To match $ax + 14$ exactly, $a = 6$ and $2k = 14$, so $k = 7$. Then $a + k = 6 + 7 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 2k = ax + 14 for all x: a = 6, 2k = 14 so k = 7; a + k = 13.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb060ce5-14d6-4d9e-86d7-4940180db36b', 'NC26.8.ANFR.1', 3, 'choice', 'Write an equation for a situation', 'Jon is $j$ years old. His uncle is 20 years older than Jon. In 4 years, the uncle''s age will be three times Jon''s age at that time. Which equation represents this?', '["$j + 20 = 3(j + 4)$","$j + 20 + 4 = 3(j + 4)$","$j + 20 + 4 = 3j + 4$","$j + 20 + 4 = 3j$"]', '$j + 20 + 4 = 3(j + 4)$', NULL, 'In 4 years the uncle will be $j + 20 + 4$ years old and Jon will be $j + 4$. The uncle''s age is three times Jon''s, so $j + 20 + 4 = 3(j + 4)$. The other choices forget that the uncle ages 4 years, forget that Jon ages 4 years, or ignore Jon''s age entirely on the right.', 'checked', '{"lint":[],"solve":{"answer":"$j + 20 + 4 = 3(j + 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Uncle now j + 20, in 4 years j + 24; Jon then j + 4. j + 20 + 4 = 3(j + 4).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01eb7680-9ee9-4c19-8a62-5b8ab5cca175', 'NC26.8.ANFR.1', 3, 'choice', 'Write an equation for a situation', 'Three consecutive integers have a sum that is 9 less than five times the smallest integer. Let $n$ be the smallest integer. Which equation represents this?', '["$n + (n + 1) + (n + 2) = 5n + 9$","$n + (n + 1) + (n + 2) = 9 - 5n$","$n + (n + 1) + (n + 2) = 5n - 9$","$n + (n + 1) + (n + 2) = 5(n - 9)$"]', '$n + (n + 1) + (n + 2) = 5n - 9$', NULL, 'The three integers are $n$, $n + 1$ and $n + 2$. Their sum is $n + (n + 1) + (n + 2)$. "9 less than five times the smallest" is $5n - 9$. So the equation is $n + (n + 1) + (n + 2) = 5n - 9$. The other choices add 9, subtract $5n$ from 9, or subtract 9 before multiplying.', 'checked', '{"lint":[],"solve":{"answer":"$n + (n + 1) + (n + 2) = 5n - 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum n + (n+1) + (n+2); 9 less than five times the smallest: 5n - 9.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a551794-bb92-4768-bae1-2b362d2ca493', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve a problem with an equation', 'A shop rents bikes for 12 dollars plus 4 dollars per hour. A second shop rents bikes for 5 dollars plus 6 dollars per hour. The two shops charge the same amount for a certain number of hours. What is that amount, in dollars?', '[]', '26', '12+4*(((0-7))/((0-2)))', 'For $h$ hours the shops charge $12 + 4h$ and $5 + 6h$. Set them equal: $7 = 2h$, so $h = 3.5$ hours. The charge is $12 + 4(3.5) = 26$ dollars, and $5 + 6(3.5) = 26$ dollars too.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 4h = 5 + 6h -> 7 = 2h -> h = 3.5. Cost 12 + 4(3.5) = 26; check 5 + 21 = 26.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f187d0c-1f12-4590-a3b1-ae1f9bdc3911', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve a problem with an equation', 'Jar A holds 3 times as many marbles as Jar B. After 10 marbles are taken out of Jar A and 6 marbles are put into Jar B, the two jars hold the same number of marbles. How many marbles did Jar A hold at the start?', '[]', '24', '3*((16)/(2))', 'Let Jar B start with $b$ marbles, so Jar A starts with $3b$. After the change: $3b - 10 = b + 6$. Then $2b = 16$, so $b = 8$ and Jar A started with $3 \cdot 8 = 24$ marbles. Check: $24 - 10 = 14$ and $8 + 6 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A = 3B. 3B - 10 = B + 6 -> 2B = 16 -> B = 8, A = 24. Check: 14 = 14.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('771c2702-0369-4b8d-8096-5854d5efe396', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve a problem with an equation', 'A square has sides of length $2x + 1$. An equilateral triangle has sides of length $3x - 4$. The square and the triangle have the same perimeter. What is the perimeter of the square?', '[]', '132', '4*(2*(((0-16))/((0-1)))+1)', 'The square''s perimeter is $4(2x + 1)$ and the triangle''s is $3(3x - 4)$. Set them equal: $8x + 4 = 9x - 12$, so $x = 16$. The square''s sides are $2(16) + 1 = 33$, so its perimeter is $4 \cdot 33 = 132$. (The triangle''s sides are $3(16) - 4 = 44$ and $3 \cdot 44 = 132$.)', 'checked', '{"lint":[],"solve":{"answer":"132","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2x + 1) = 3(3x - 4) -> 8x + 4 = 9x - 12 -> x = 16. Square side 33, perimeter 132 (triangle side 44, 132).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c01335af-f01e-4873-b3f9-cc509dfb1ece', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve a problem with an equation', 'A rectangle has a length that is 3 more than twice its width. If the width is increased by 5 and the length is decreased by 4, the new rectangle is a square. What is the width of the original rectangle?', '[]', '6', '((0-6))/((0-1))', 'Let the width be $w$. The length is $2w + 3$. The new width is $w + 5$ and the new length is $2w + 3 - 4$. A square has equal sides: $w + 5 = 2w + 3 - 4$, which gives $w + 5 = 2w - 1$ and $w = 6$. Check: the length was 15, the new sides are $11$ and $11$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 2w + 3. w + 5 = L - 4 = 2w - 1 -> w = 6. L = 15; new 11 by 11.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47ce8613-8d10-4b50-8f01-6cb8ebb83ba0', 'NC26.8.ANFR.1', 3, 'choice', 'Solve an inequality with the variable on both sides', 'Which inequality is equivalent to $2(3x - 1) \le 4x + 10$?', '["$x \\le 4$","$x \\ge 6$","$x \\ge -11$","$x \\le 6$"]', '$x \le 6$', NULL, 'Simplify each side: $6x - 2 \le 4x + 10$. Move the $x$ terms to one side and the numbers to the other: $2x \le 12$. Divide both sides by $2$: $x \le 6$. The other choices change the sign of the 2, reverse the inequality, or forget to multiply $3x$ by 2.', 'checked', '{"lint":[],"solve":{"answer":"$x \\le 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 2 <= 4x + 10 -> 2x <= 12 -> x <= 6.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f8e9d3e-aa7a-4538-8018-50779f08556b', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an inequality with the variable on both sides', 'What is the least integer that satisfies $\frac{x}{2} + 3 \ge \frac{x}{4} + 5$?', '[]', '8', '2/(1/4)', 'Simplify each side: $\frac{1}{2}x + 3 \ge \frac{1}{4}x + 5$. Move the $x$ terms to one side and the numbers to the other: $\frac{1}{4}x \ge 2$. Divide both sides by $\frac{1}{4}$: $x \ge 8$. So $x$ is 8 or greater, and the least integer is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x/2 - x/4 >= 2 -> x/4 >= 2 -> x >= 8; least integer 8.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a948bb-84d6-4d55-a814-5b8645e51ff0', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an inequality that needs a sign reversal', 'What is the greatest integer $x$ that satisfies $3(2 - x) > 5x + 38$?', '[]', '-5', '0-32/8-1', 'Simplify each side: $-3x + 6 > 5x + 38$. Move the $x$ terms to one side and the numbers to the other: $-8x > 32$. Divide both sides by $-8$. Dividing by a negative number reverses the inequality: $x < -4$. Since $x$ must be less than $-4$, the greatest integer is $-5$. (Check: $3(2 - (-5)) = 33 > 5(-5) + 38 = 13$.)', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 - 3x > 5x + 38 -> -32 > 8x -> x < -4; greatest integer -5. Check x=-5: 21 > -2 true; x=-4: 18 > 18 false.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('14052b93-a9ac-4c8d-aee4-f8bb27a547d8', 'NC26.8.ANFR.1', 3, 'choice', 'Solve an inequality that needs a sign reversal', 'Which inequality shows all of the solutions of $-\frac{1}{2}x + 3 < x - 6$?', '["$x < 6$","$x > -6$","$x > 6$","$x < -18$"]', '$x > 6$', NULL, 'Move the $x$ terms to one side and the numbers to the other: $-\frac{3}{2}x < -9$. Divide both sides by $-\frac{3}{2}$. Dividing by a negative number reverses the inequality: $x > 6$. The other choices forget to reverse the sign, divide incorrectly, or combine the $x$ terms with the wrong sign.', 'checked', '{"lint":[],"solve":{"answer":"$x > 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 < x + x/2 = 1.5x -> x > 6.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba24d99c-f1a4-499f-9138-2bdaf188f819', 'NC26.8.ANFR.1', 3, 'numeric', 'Solve an inequality that needs a sign reversal', 'The solutions of $7 - 5x > 3(x - 3) + 4$ are all of the values of $x$ that are less than a certain number. What is that number?', '[]', '3/2', '12/8', 'Simplify each side: $-5x + 7 > 3x - 5$. Move the $x$ terms to one side and the numbers to the other: $-8x > -12$. Divide both sides by $-8$. Dividing by a negative number reverses the inequality: $x < \frac{3}{2}$. So $x$ is less than $\frac{3}{2}$, and the number is $\frac{3}{2}$, or 1.5.', 'checked', '{"lint":[],"solve":{"answer":"3/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 - 5x > 3x - 9 + 4 = 3x - 5 -> 12 > 8x -> x < 3/2.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e96eed8-eda4-4fc1-84c1-be526442d581', 'NC26.8.ANFR.1', 3, 'choice', 'Write an inequality for a situation', 'A rectangle has length $3x$ and width 5. A square has side length $x + 6$. Which inequality says that the rectangle''s perimeter is greater than the square''s perimeter?', '["$2(3x) + 2(5) > 4(x + 6)$","$3x + 5 > x + 6$","$2(3x + 5) > 4x + 6$","$2(3x) + 5 > 4(x + 6)$"]', '$2(3x) + 2(5) > 4(x + 6)$', NULL, 'The rectangle''s perimeter is $2(3x) + 2(5)$. The square''s perimeter is $4(x + 6)$. "Greater than" means $>$. The other choices add each side only once, forget to multiply the 6 by 4, or count the width only once.', 'checked', '{"lint":[],"solve":{"answer":"$2(3x) + 2(5) > 4(x + 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle perimeter 2(3x) + 2(5); square 4(x + 6).","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcc2d65e-02ba-4fff-8f01-d93321592020', 'NC26.8.ANFR.1', 3, 'choice', 'Name or count the whole numbers that satisfy an inequality', 'Which value of $x$ is NOT a solution of $2(x + 3) \le 5x - 9$?', '["$5$","$4$","$6$","$10$"]', '$4$', '4', 'Simplify each side: $2x + 6 \le 5x - 9$. Move the $x$ terms to one side and the numbers to the other: $-3x \le -15$. Divide both sides by $-3$. Dividing by a negative number reverses the inequality: $x \ge 5$. So the solutions are 5 and greater. The value 4 is not a solution, since $2(4 + 3) = 14$ is not less than or equal to $5(4) - 9 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"$4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 6 <= 5x - 9 -> 15 <= 3x -> x >= 5. 4 is not a solution (14 <= 11 false); 5, 6, 10 are.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdcc4e61-4581-4740-bea7-378282bf2ce8', 'NC26.8.ANFR.1', 3, 'choice', 'Find the error in a solution', 'Four students solved $4(x - 1) = 2x + 6$. Whose work is completely correct?', '["$4x - 1 = 2x + 6$, so $2x = 7$ and $x = \\frac{7}{2}$","$4x - 4 = 2x + 6$, so $6x = 10$ and $x = \\frac{5}{3}$","$4x - 4 = 2x + 6$, so $2x = 2$ and $x = 1$","$4x - 4 = 2x + 6$, so $2x = 10$ and $x = 5$"]', '$4x - 4 = 2x + 6$, so $2x = 10$ and $x = 5$', NULL, 'Distribute: $4(x - 1) = 4x - 4$. Subtract $2x$ from both sides: $2x - 4 = 6$. Add 4: $2x = 10$, so $x = 5$. Check: $4(5 - 1) = 16$ and $2(5) + 6 = 16$. The other students forgot to multiply the 1 by 4, added the $x$ terms, or subtracted 4 instead of adding it.', 'checked', '{"lint":[],"solve":{"answer":"$4x - 4 = 2x + 6$, so $2x = 10$ and $x = 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 4 = 2x + 6 -> 2x = 10 -> x = 5. Check: 16 = 16.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16288997-004e-47c0-ae6a-dd1b31f7d5c2', 'NC26.8.ANFR.1', 3, 'choice', 'Find the error in a solution', 'A student solves $2(x + 4) = 2x + 3$ and gets $8 = 3$. She writes "$x = 5$" because $8 - 3 = 5$. What should she conclude instead?', '["$x = 5$ is the solution","The equation has no solution, because $8 = 3$ is never true","Every number is a solution","$x = 0$ is the solution"]', 'The equation has no solution, because $8 = 3$ is never true', NULL, 'Distributing gives $2x + 8 = 2x + 3$. Subtracting $2x$ from both sides leaves $8 = 3$, which is false no matter what $x$ is. So no value of $x$ works: the equation has no solution. The number 5 is just the difference of 8 and 3, not a solution.', 'checked', '{"lint":[],"solve":{"answer":"The equation has no solution, because $8 = 3$ is never true","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 8 = 2x + 3 -> 8 = 3, a false statement: no solution.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8462d6e1-7faa-4b2d-acfc-dc5b6589d509', 'NC26.8.ANFR.1', 3, 'choice', 'Check a solution and justify the steps', 'Which set of steps solves $7x - 9 = 4x + 6$ correctly?', '["Add $4x$ to both sides, subtract 9 from both sides, then divide both sides by 11","Subtract $4x$ from both sides, subtract 9 from both sides, then divide both sides by 3","Subtract $4x$ from both sides, add 9 to both sides, then divide both sides by 11","Subtract $4x$ from both sides, add 9 to both sides, then divide both sides by 3"]', 'Subtract $4x$ from both sides, add 9 to both sides, then divide both sides by 3', NULL, 'Subtract $4x$: $3x - 9 = 6$. Add 9: $3x = 15$. Divide by 3: $x = 5$. The other choices add $4x$ (which gives $11x - 9 = 8x + 6$), subtract 9 when it should be added, or divide by 11 when the coefficient of $x$ is 3.', 'checked', '{"lint":[],"solve":{"answer":"Subtract $4x$ from both sides, add 9 to both sides, then divide both sides by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7x - 4x - 9 = 6 -> 3x - 9 = 6 -> add 9: 3x = 15 -> divide by 3: x = 5.","run_id":"claude-code","at":"2026-10-17T20:27:47.608Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfd7cd33-6da2-4b25-81af-1266d1442291', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a set of input-output pairs is a function', 'Each pair below is written as (input, output). Which set of pairs is a function?', '["(1, 4), (1, 5), (2, 6), (3, 7)","(2, 3), (3, 4), (2, 5), (4, 6)","(5, 1), (6, 2), (7, 3), (5, 4)","(1, 4), (2, 5), (3, 6), (4, 7)"]', '(1, 4), (2, 5), (3, 6), (4, 7)', NULL, 'A function gives exactly one output for each input. In the first set every input appears once. In the other sets an input is repeated with two different outputs: 1 gives 4 and 5, 2 gives 3 and 5, and 5 gives 1 and 4.', 'checked', '{"lint":[],"solve":{"answer":"(1, 4), (2, 5), (3, 6), (4, 7)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A repeats input 2 with outputs 3 and 5; B repeats input 1; D repeats input 5. C has inputs 1,2,3,4 each once, so it is a function.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e503e807-2094-4fc7-be51-942303181737', 'NC26.8.ANFR.2', 1, 'numeric', 'Use a function rule to find an output', 'A function''s rule is: the output is 3 more than twice the input. What is the output when the input is 5?', '[]', '13', '2*5+3', 'Twice the input is $2 \times 5 = 10$. Three more than that is $10 + 3 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Output = 2(5) + 3 = 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82f8f8cc-1e93-4490-8a0f-40ed1465a29f', 'NC26.8.ANFR.2', 1, 'choice', 'Describe how a quantity changes as time passes', 'A candle is measured at 0, 1, 2 and 3 hours. Its heights are 20, 17, 14 and 11 centimeters. Which statement describes the height as time goes on?', '["The height increases by 3 centimeters each hour","The height decreases by 20 centimeters each hour","The height decreases by 3 centimeters each hour","The height decreases by 11 centimeters each hour"]', 'The height decreases by 3 centimeters each hour', NULL, 'Each hour the height goes from 20 to 17 to 14 to 11. It drops by 3 centimeters every hour, so the function is decreasing.', 'checked', '{"lint":[],"solve":{"answer":"The height decreases by 3 centimeters each hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 -> 17 -> 14 -> 11: each hour the height drops by 3 cm.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04f5242a-f8d7-4304-acb0-23d8c822b6b3', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a set of pairs is a function', 'Lena wrote four lists of (input, output) pairs. Only one of the lists is a function. Which one is it?', '["$(1, 2), (1, 3), (4, 5)$","$(2, 6), (3, 8), (2, 9)$","$(1, 7), (2, 7), (3, 7)$","$(5, 1), (6, 2), (5, 3)$"]', '$(1, 7), (2, 7), (3, 7)$', NULL, 'A function gives every input exactly one output. In the list $(1, 7), (2, 7), (3, 7)$ the inputs 1, 2 and 3 each have one output; it does not matter that the output 7 is used three times. In each other list one input has two outputs: 1 goes to 2 and 3, 2 goes to 6 and 9, and 5 goes to 1 and 3.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 7), (2, 7), (3, 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: input 5 has outputs 1 and 3, not a function. B: inputs 1,2,3 each once (same output 7 is allowed), function. C: input 1 -> 2 and 3, not. D: input 2 -> 6 and 9, not. Only B.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f96b010-00cd-463b-9447-cebbd31c0173', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a set of pairs is a function', 'A table shows an input $x$ and an output $y$. When $x$ is 1, $y$ is 3. When $x$ is 2, $y$ is 5. When $x$ is 2, $y$ is 6. Why is this table not a function?', '["The input 2 is paired with two different outputs","The outputs 3, 5 and 6 are all different from each other","The input 1 is paired with only one output","The output 5 is smaller than the output 6"]', 'The input 2 is paired with two different outputs', NULL, 'In a function each input has exactly one output. Here the input 2 has both 5 and 6, so the table is not a function. The other statements are true, but they do not break the rule.', 'checked', '{"lint":[],"solve":{"answer":"The input 2 is paired with two different outputs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Input 2 is paired with both 5 and 6, so the table fails the one-output-per-input rule. The other reasons are irrelevant.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f958bfe0-35e7-46be-885d-7dad897d585f', 'NC26.8.ANFR.2', 1, 'numeric', 'Tell whether a set of pairs is a function', 'Sam wrote three relations as (input, output) pairs. Relation A: $(1, 2), (2, 3), (3, 4)$. Relation B: $(1, 2), (1, 3), (2, 4)$. Relation C: $(5, 0), (6, 0), (7, 0)$. How many of the three relations are functions?', '[]', '2', '1+0+1', 'Relation A is a function: each input has one output. Relation B is not, because the input 1 has the outputs 2 and 3. Relation C is a function: each input has the output 0, and repeating an output is allowed. So 2 of the relations are functions.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: inputs 1,2,3 distinct, function. B: input 1 -> 2 and 3, not. C: inputs 5,6,7 distinct (repeated output 0 is fine), function. 2 functions.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4dfe94c1-f162-4dcf-8d6c-ada043fbfef0', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a set of pairs is a function', 'A set of (input, output) pairs is a function. Which statement must be true?', '["No output is used more than once","No input is paired with two different outputs","Every output is greater than its input","The inputs are listed from least to greatest"]', 'No input is paired with two different outputs', NULL, 'The rule for a function is that each input has exactly one output. Outputs may repeat, they need not be larger than the inputs, and the pairs need not be in order.', 'checked', '{"lint":[],"solve":{"answer":"No input is paired with two different outputs","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Definition of a function: each input has exactly one output, so no input is paired with two different outputs. Order, repeated outputs and size are not required.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba5daaf9-ef85-4151-b919-6aff06cf30e1', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a situation or rule is a function', 'Which of these relationships is a function from the first quantity to the second?', '["Input: a student. Output: that student''s date of birth.","Input: a school. Output: a student at that school.","Input: a state. Output: a city in that state.","Input: a month. Output: a student born in that month."]', 'Input: a student. Output: that student''s date of birth.', NULL, 'Every student has exactly one date of birth, so each input has one output. A school has many students, a state has many cities, and many students can be born in the same month, so those are not functions.', 'checked', '{"lint":[],"solve":{"answer":"Input: a student. Output: that student''s date of birth.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A state has many cities; a month has many students born in it; a school has many students. A student has exactly one date of birth, so student -> date of birth is a function.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eee71b78-30de-4775-9e2c-576d999ba9d9', 'NC26.8.ANFR.2', 1, 'numeric', 'Tell whether a situation or rule is a function', 'A bakery sells muffins for 2 dollars each. A table shows that 1 muffin costs 2 dollars, 2 muffins cost 4 dollars and 3 muffins cost 6 dollars. For the input 3 muffins, how many different prices (outputs) are there?', '[]', '1', '1', 'Three muffins cost 6 dollars and no other price, so the input 3 has exactly 1 output. That is what makes the cost a function of the number of muffins.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy for grade 8, but correct and on the function idea.","work":"The muffin price is a function: 3 muffins cost 3 x 2 = 6 dollars, a single price. Number of different outputs for input 3 is 1.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1fe95c2-18cb-473a-b0a1-ad8c406f60b4', 'NC26.8.ANFR.2', 1, 'choice', 'Tell whether a situation or rule is a function', 'In which pair is the second quantity a function of the first?', '["First: a person''s age. Second: that person''s height.","First: a team name. Second: a player on that team.","First: a color. Second: a car of that color.","First: the number of tickets bought at 6 dollars each. Second: the total cost."]', 'First: the number of tickets bought at 6 dollars each. Second: the total cost.', NULL, 'Each number of tickets gives exactly one total cost, so the cost is a function of the number of tickets. People of the same age can have different heights, a team has many players, and many cars can share a color.', 'checked', '{"lint":[],"solve":{"answer":"First: the number of tickets bought at 6 dollars each. Second: the total cost.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Team -> player: many players. Age -> height: people of the same age have different heights. Colour -> car: many cars. Tickets -> total cost: cost = 6 x tickets, exactly one value. Answer C.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e581cbc-4a82-4441-92bf-8fac981d2d3b', 'NC26.8.ANFR.2', 1, 'numeric', 'Use a function rule to find an output or an input', 'A function machine takes a number, multiplies it by 4 and gives the result. What does it output for the input 7?', '[]', '28', '4*7', 'The machine multiplies by 4: $4 \times 7 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 4 = 28.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
