INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0d19929-a441-4e93-aae1-92568cedceae', 'NC26.8.ANFR.2', 1, 'choice', 'Tell linear from non-linear using pairs or a table', 'A function has the inputs 1, 2, 3 and 4. Which list of outputs makes it a linear function?', '["2, 4, 8, 16","2, 4, 6, 8","1, 4, 9, 16","5, 6, 8, 11"]', '2, 4, 6, 8', NULL, 'A linear function changes by the same amount for every step of 1 in the input. The outputs 2, 4, 6, 8 go up by 2 each time. The other lists go up by 2, 4, 8; by 3, 5, 7; and by 1, 2, 3.', 'checked', '{"lint":[],"solve":{"answer":"2, 4, 6, 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,4,8,16: differences 2,4,8. 1,4,9,16: 3,5,7. 2,4,6,8: 2,2,2 constant, linear. 5,6,8,11: 1,2,3.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfc54226-1138-4178-9b3b-f81026cd63f2', 'NC26.8.ANFR.2', 1, 'choice', 'Tell linear from non-linear using an equation or a description', 'Which of these equations has a straight-line graph?', '["$y = x^2$","$y = 2^x$","$y = x^3 - 1$","$y = 2x + 3$"]', '$y = 2x + 3$', NULL, 'An equation of the form $y = mx + b$ has a straight-line graph, so $y = 2x + 3$ is linear. The equations with $x^2$, $2^x$ and $x^3$ have curved graphs.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^3 - 1, 2^x and x^2 are curves; y = 2x + 3 is linear.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7399657-a0a6-4014-8112-a368c7b2018f', 'NC26.8.ANFR.2', 1, 'choice', 'Tell linear from non-linear using an equation or a description', 'Which situation is described by a linear function?', '["A bank balance doubles every year","The area of a square as its side length grows","A tree grows exactly 3 inches every year","The height of a ball thrown into the air"]', 'A tree grows exactly 3 inches every year', NULL, 'A linear function changes by the same amount for each step. The tree''s height goes up by 3 inches every year. A doubling balance, a growing square''s area and the height of a thrown ball do not change by a constant amount.', 'checked', '{"lint":[],"solve":{"answer":"A tree grows exactly 3 inches every year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Thrown ball: rises then falls (curve). Doubling balance: exponential. Square area: s^2. A tree growing exactly 3 inches each year: constant rate, linear.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c56f154-c0f2-4579-932b-771276dda9cc', 'NC26.8.ANFR.2', 1, 'numeric', 'Tell linear from non-linear using an equation or a description', 'The graph of $y = 6x - 1$ is a straight line. By how much does $y$ increase when $x$ increases by 1?', '[]', '6', '6', 'In $y = mx + b$, the output changes by $m$ for each increase of 1 in $x$. Here $m = 6$, so $y$ increases by 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 6: y increases by 6 for each 1 in x.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4fe751a-8cc7-4129-be9a-71486b1ba5c4', 'NC26.8.ANFR.2', 1, 'choice', 'Match a real situation to the shape of its graph', 'Water is poured into a bucket at a steady rate. Imagine the graph of the depth of the water against time. Which describes the graph?', '["A straight line that goes down from left to right","A horizontal line","A curve that goes up and then comes down","A straight line that goes up from left to right"]', 'A straight line that goes up from left to right', NULL, 'The depth increases by the same amount every second, so the graph is a straight line that rises as time goes on.', 'checked', '{"lint":[],"solve":{"answer":"A straight line that goes up from left to right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Steady rate: depth rises by equal amounts per unit time, a straight line rising left to right.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
