INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7951d67-4821-40a5-8a14-4ca12ea0bf2b', 'NC26.8.ANFR.2', 1, 'choice', 'Match a real situation to the shape of its graph', 'A car is parked for two hours. Imagine the graph of its distance from home against time during those two hours. Which describes the graph?', '["A horizontal line","A straight line that goes up from left to right","A straight line that goes down from left to right","A curve that goes up and then comes down"]', 'A horizontal line', NULL, 'A parked car does not move, so its distance from home does not change. The graph stays at the same height: a horizontal line.', 'checked', '{"lint":[],"solve":{"answer":"A horizontal line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parked: distance from home does not change, horizontal line.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
