INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06b4f292-0d93-44e6-8cfa-9ef1e0efb08b', 'NC26.8.ANFR.2', 1, 'choice', 'Match a real situation to the shape of its graph', 'A bathtub is filled, stays full while someone bathes, and is then drained. Imagine the graph of the depth of the water against time. Which describes the graph, from left to right?', '["It falls, stays flat, then rises","It rises, stays flat, then falls","It rises, falls, then stays flat","It stays flat, rises, then falls"]', 'It rises, stays flat, then falls', NULL, 'Filling makes the depth rise, bathing keeps it level, and draining makes it fall, in that order.', 'checked', '{"lint":[],"solve":{"answer":"It rises, stays flat, then falls","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Filling: rises; full: flat; draining: falls.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
