INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df7f5550-7acb-4117-bcc4-170e998ebc24', 'NC26.8.ANFR.2', 2, 'choice', 'Tell whether a situation or rule is a function', 'For positive whole number inputs, which rule gives every input exactly one output?', '["The output is the number of digits in the input","The output is a multiple of the input","The output is a number larger than the input","The output is a factor of the input"]', 'The output is the number of digits in the input', NULL, 'A number has exactly one count of digits, so the first rule gives one output per input. An input such as 6 has many multiples (6, 12, 18, ...), many larger numbers, and several factors (1, 2, 3, 6).', 'checked', '{"lint":[],"solve":{"answer":"The output is the number of digits in the input","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples, larger numbers and factors each give many possible outputs (e.g. input 6 has factors 1,2,3,6). The number of digits of a positive whole number is a single value. Answer B.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d27662d3-3a5d-48e8-8491-24ac8cffc005', 'NC26.8.ANFR.2', 2, 'numeric', 'Use a function rule to find an output or an input', 'A taxi charges 3 dollars to start and then 2 dollars for each mile. The cost in dollars of a ride of $m$ miles is $C = 3 + 2m$. What is the cost, in dollars, of a 9-mile ride?', '[]', '21', '3+2*9', 'Put $m = 9$ into the rule: $C = 3 + 2 \times 9 = 3 + 18 = 21$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 3 + 2(9) = 3 + 18 = 21.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d008b32d-6d28-4b55-a1c9-c516957f813c', 'NC26.8.ANFR.2', 2, 'numeric', 'Use a function rule to find an output or an input', 'The rule for a function is $y = 4x - 5$. For what input $x$ is the output 27?', '[]', '8', '(27+5)/4', 'Set $4x - 5 = 27$. Add 5: $4x = 32$. Divide by 4: $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 = 27, 4x = 32, x = 8.","run_id":"claude-code","at":"2026-10-17T20:25:51.985Z"}}', 'ai', NULL, NULL)
