INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f139e5e-26b3-417f-98a9-35216e3ce227', 'NC26.8.ANFR.3', 1, 'numeric', 'Write the equation of a line in slope-intercept form', 'A line has a slope of 3 and a $y$-intercept of 5. What is the value of $y$ on this line when $x = 2$?', '[]', '11', '3*2+5', 'The equation is $y = 3x + 5$. When $x = 2$, $y = 3 \times 2 + 5 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 3x + 5; at x = 2, y = 11.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3001538c-fc0b-4d85-ae9d-716cc4273732', 'NC26.8.ANFR.3', 1, 'choice', 'Write the equation of a line in slope-intercept form', 'A taxi charges a starting fee of 4 dollars plus 3 dollars for each mile. Which equation gives the cost $C$, in dollars, of a ride of $m$ miles?', '["$C = 4m + 3$","$C = 7m$","$C = 3m + 4$","$C = 3m - 4$"]', '$C = 3m + 4$', NULL, 'The cost grows by 3 dollars per mile, so 3 multiplies $m$. The starting fee of 4 dollars is added once. So $C = 3m + 4$.', 'checked', '{"lint":[],"solve":{"answer":"$C = 3m + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Starting fee 4 is the intercept, 3 per mile the slope: C = 3m + 4.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f70214c-6887-4872-a732-73f7c886106f', 'NC26.8.ANFR.3', 1, 'choice', 'Write the equation of a line in slope-intercept form', 'A line crosses the $y$-axis at $(0, 6)$ and goes down 2 units for every 1 unit it goes to the right. Which equation is the equation of the line?', '["$y = -2x + 6$","$y = 2x + 6$","$y = 6x - 2$","$y = -2x - 6$"]', '$y = -2x + 6$', NULL, 'Going down 2 for every 1 to the right means a slope of $-2$. The line crosses the $y$-axis at 6, so the $y$-intercept is 6. The equation is $y = -2x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -2x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Intercept 6, slope -2/1 = -2: y = -2x + 6.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67bcebf0-ce78-4792-93a3-322fd62c4f4b', 'NC26.8.ANFR.3', 1, 'numeric', 'Find the slope of a line from points or a table', 'A line rises 6 units for every 2 units it runs to the right. What is its slope?', '[]', '3', '6/2', 'Slope is rise over run: $\frac{6}{2} = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise/run = 6/2 = 3.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('718666de-2f04-4083-83ba-e70dc47628a5', 'NC26.8.ANFR.3', 1, 'choice', 'Find the slope of a line from points or a table', 'A road rises 15 meters over a horizontal distance of 60 meters. What is the slope of the road?', '["4","0.25","45","75"]', '0.25', '15/60', 'Slope is rise divided by run: $\frac{15}{60} = \frac{1}{4} = 0.25$. The number 4 comes from dividing run by rise.', 'checked', '{"lint":[],"solve":{"answer":"0.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/60 = 0.25.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
