INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6c13184-1890-4736-be1f-5e6059c23b04', 'NC26.8.ANFR.3', 1, 'choice', 'Interpret the slope and y-intercept in a situation', 'A pool already holds 200 liters of water and is filled at 15 liters per minute. The amount of water is $y = 15x + 200$ liters after $x$ minutes. What does the 200 tell us?', '["The liters added each minute","The number of minutes the pool is filled","The amount of water in the pool at the start","The amount of water when the pool is full"]', 'The amount of water in the pool at the start', NULL, 'The 200 is the value of $y$ when $x = 0$, the starting amount. The 15 is the rate, the liters added each minute.', 'checked', '{"lint":[],"solve":{"answer":"The amount of water in the pool at the start","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At x = 0, y = 200: the starting amount.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
