INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('904807ec-4893-486c-a12b-53c129facb91', 'NC26.8.ANFR.3', 1, 'numeric', 'Interpret the slope and y-intercept in a situation', 'The cost, in dollars, of renting a bike for $x$ hours is $y = 6x + 10$. What is the cost, in dollars, of renting it for 3 hours?', '[]', '28', '6*3+10', 'Put $x = 3$ into the equation: $y = 6 \times 3 + 10 = 28$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6(3) + 10 = 28.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
