INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c33620f-4384-4cd6-a6f5-8c57c43409b6', 'NC26.8.ANFR.3', 1, 'choice', 'Graph a line: points, intercepts and steepness', 'The line $y = 3x$ passes through the origin. Which point is also on this line?', '["$(12, 4)$","$(4, 12)$","$(4, 7)$","$(4, 3)$"]', '$(4, 12)$', NULL, 'When $x = 4$, $y = 3 \times 4 = 12$, so $(4, 12)$ is on the line. The point $(12, 4)$ has its coordinates the wrong way round.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 12)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 3(4) = 12: (4, 12).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
