INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('878ecee4-46cd-4087-94af-0aa279e69563', 'NC26.8.ANFR.3', 1, 'choice', 'Compare two linear functions shown in different ways', 'Function A is $y = 4x + 1$. Function B has the $(x, y)$ pairs $(0, 2)$, $(1, 5)$ and $(2, 8)$. Which statement is true?', '["Function B has the greater slope","The two functions have the same slope","Function A has the greater $y$-intercept","Function A has the greater slope"]', 'Function A has the greater slope', NULL, 'The slope of A is 4. For B, $y$ goes up by 3 each time $x$ goes up by 1, so its slope is 3. The $y$-intercepts are 1 for A and 2 for B (the value at $x = 0$), so B has the greater $y$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"Function A has the greater slope","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: slope 4, intercept 1. B: slope 3, intercept 2. A has the greater slope; B the greater intercept.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef4ab75f-27ff-4382-bdca-6c47cf069996', 'NC26.8.ANFR.3', 1, 'numeric', 'Compare two linear functions shown in different ways', 'Function A is $y = 3x + 2$. Function B has a slope of 5 and a $y$-intercept of $-1$. How much greater is the slope of Function B than the slope of Function A?', '[]', '2', '5-3', 'The slope of A is 3 and the slope of B is 5, so B''s slope is $5 - 3 = 2$ greater.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 - 3 = 2.","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
