INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddd6c1e2-69e6-481d-bf0a-89d9e6c47b8b', 'NC26.8.ANFR.3', 1, 'choice', 'Compare two linear functions shown in different ways', 'Function A is $y = 2x - 3$. Function B is the line through $(0, 1)$ with a slope of $-2$. Which statement is true?', '["Both are increasing","Both are decreasing","A is increasing and B is decreasing","A is decreasing and B is increasing"]', 'A is increasing and B is decreasing', NULL, 'Function A has a slope of 2, which is positive, so it is increasing. Function B has a slope of $-2$, which is negative, so it is decreasing.', 'checked', '{"lint":[],"solve":{"answer":"A is increasing and B is decreasing","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A slope 2 (increasing), B slope -2 (decreasing).","run_id":"claude-code","at":"2026-10-17T20:25:52.027Z"}}', 'ai', NULL, NULL)
