INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46e488a3-6273-4901-bbb4-c6385cdd069a', 'NC26.8.ANFR.4', 1, 'choice', 'Classify a number within the real numbers', 'Which of these numbers is a whole number?', '["$-3$","$\\frac{1}{2}$","$0$","$2.5$"]', '$0$', NULL, 'The whole numbers are $0, 1, 2, 3, \ldots$ Only $0$ is on that list. $-3$ is negative, and $\frac{1}{2}$ and $2.5$ are not whole.', 'checked', '{"lint":[],"solve":{"answer":"$0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole numbers are 0, 1, 2, ... ; -3 is negative, 2.5 and 1/2 are not integers. Only 0 is whole.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25ee6c7c-ae56-4fd3-bc35-d46dbcecd02b', 'NC26.8.ANFR.4', 1, 'choice', 'Classify a number within the real numbers', 'Which number is an integer but not a whole number?', '["$0$","$-4$","$4$","$\\frac{4}{5}$"]', '$-4$', NULL, 'Integers include negative numbers, but whole numbers start at $0$. So $-4$ is an integer that is not a whole number. $0$ and $4$ are whole numbers, and $\frac{4}{5}$ is not an integer.', 'checked', '{"lint":[],"solve":{"answer":"$-4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Integer but not whole means a negative integer. -4 qualifies; 0 and 4 are whole; 4/5 is not an integer.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9152e350-237d-440d-9857-8514f8db1dc0', 'NC26.8.ANFR.4', 1, 'numeric', 'Classify a number within the real numbers', 'The natural numbers are $1, 2, 3, \ldots$ How many of the numbers $3$, $-2$, $0$ and $7$ are natural numbers?', '[]', '2', NULL, '$3$ and $7$ are counting numbers. $-2$ is negative and $0$ is not a counting number. So 2 of them are natural numbers.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Natural numbers 1, 2, 3, ... : 3 yes, -2 no, 0 no, 7 yes. Count = 2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f27adb14-5355-4d61-bef3-b3480e2e4b22', 'NC26.8.ANFR.4', 1, 'choice', 'Classify a number within the real numbers', 'Which of these numbers can be written as a fraction $\frac{a}{b}$ where $a$ and $b$ are integers and $b \ne 0$?', '["$\\sqrt{3}$","$\\pi$","$\\sqrt{15}$","$\\sqrt{16}$"]', '$\sqrt{16}$', NULL, '$\sqrt{16} = 4 = \frac{4}{1}$, so it can be written as a fraction of integers. $\sqrt{3}$, $\sqrt{15}$ and $\pi$ are irrational, so they cannot.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{16}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(16) = 4 = 4/1, rational. sqrt(15), sqrt(3) are not perfect-square roots (irrational); pi is irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfa0fe2b-4928-4381-99ed-da907b038e0e', 'NC26.8.ANFR.4', 1, 'choice', 'Recognise an irrational number', 'Which of these numbers is NOT a rational number?', '["$\\sqrt{26}$","$-0.6$","$\\frac{2}{7}$","$\\sqrt{25}$"]', '$\sqrt{26}$', NULL, '$\sqrt{25} = 5$, $-0.6 = -\frac{6}{10}$ and $\frac{2}{7}$ are all fractions of integers. 26 is not a perfect square, so $\sqrt{26}$ is irrational.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{26}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2/7 and -0.6 are rational; sqrt(25) = 5 rational; 26 is not a perfect square so sqrt(26) is irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d911f92d-705c-4e62-8d3f-9cb76dc49812', 'NC26.8.ANFR.4', 1, 'choice', 'Recognise an irrational number', 'Which description of $\pi$ is correct?', '["It is a rational number","It is exactly equal to $3.14$","It is exactly equal to $\\frac{22}{7}$","It is an irrational number"]', 'It is an irrational number', NULL, '$\pi$ is irrational: its decimal never ends and never repeats. $3.14$ and $\frac{22}{7}$ are only close approximations of it.', 'checked', '{"lint":[],"solve":{"answer":"It is an irrational number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi is irrational; 3.14 and 22/7 are only approximations.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2273b669-a085-42d6-975a-a4254ae98a85', 'NC26.8.ANFR.4', 1, 'numeric', 'Recognise an irrational number', 'How many of the numbers $\sqrt{4}$, $\sqrt{5}$, $\sqrt{9}$ and $\sqrt{10}$ are irrational?', '[]', '2', NULL, '$\sqrt{4} = 2$ and $\sqrt{9} = 3$ are rational. 5 and 10 are not perfect squares, so $\sqrt{5}$ and $\sqrt{10}$ are irrational. That is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(4) = 2, sqrt(9) = 3 rational; sqrt(5), sqrt(10) irrational. Count = 2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6542b2cb-5661-437d-b5c2-67e4fe46b8af', 'NC26.8.ANFR.4', 1, 'choice', 'Recognise an irrational number', 'A square has an area of 7 square units, so its side length is $\sqrt{7}$ units. What kind of number is the side length?', '["Rational, because 7 is a whole number","Rational, because every square root can be written as a fraction","Irrational, because 7 is not a perfect square","Irrational, because every square root is irrational"]', 'Irrational, because 7 is not a perfect square', NULL, 'The square root of a whole number is rational only when the whole number is a perfect square. 7 is not, so $\sqrt{7}$ is irrational. (Not every square root is irrational: $\sqrt{4} = 2$.)', 'checked', '{"lint":[],"solve":{"answer":"Irrational, because 7 is not a perfect square","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 is not a perfect square, so sqrt(7) is irrational. Not every square root is irrational (sqrt(4) = 2), so the first option''s reason is wrong.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcda2279-1c1d-4a30-8725-5d8cb32cac5d', 'NC26.8.ANFR.4', 1, 'choice', 'Use a decimal expansion to tell rational from irrational', 'A decimal goes on forever and never repeats. What kind of number is it?', '["An irrational number","A rational number","An integer","A whole number"]', 'An irrational number', NULL, 'Rational numbers have decimals that end or repeat. A decimal that never ends and never repeats is irrational.', 'checked', '{"lint":[],"solve":{"answer":"An irrational number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rational numbers have decimals that end or repeat; a non-ending, non-repeating decimal is irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52deccca-2ac2-4e72-b5f2-091afef9f47b', 'NC26.8.ANFR.4', 1, 'choice', 'Use a decimal expansion to tell rational from irrational', 'Which decimal is a rational number?', '["$0.1010010001\\ldots$ (one more 0 each time)","$0.\\overline{45}$","$0.12345678910\\ldots$ (the counting numbers in order)","$0.7071067811\\ldots$ (never ends or repeats)"]', '$0.\overline{45}$', NULL, '$0.\overline{45} = 0.454545\ldots$ repeats, so it is rational. The other three go on forever without repeating, so they are irrational.', 'checked', '{"lint":[],"solve":{"answer":"$0.\\overline{45}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.454545... repeats, = 45/99 = 5/11, rational. The other three never end or repeat (the 0.1010010001... and counting-number decimals have no fixed repeating block).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3547e7f0-7841-479b-a6f6-f2b3062a096b', 'NC26.8.ANFR.4', 1, 'numeric', 'Use a decimal expansion to tell rational from irrational', 'How many of these decimals are rational numbers: $0.6$, $0.\overline{27}$, $0.1010010001\ldots$ (one more 0 each time) and $0.75$?', '[]', '3', NULL, '$0.6$ and $0.75$ end, and $0.\overline{27}$ repeats, so those three are rational. The decimal with one more 0 each time never repeats, so it is irrational. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.6 ends, 0.2727... repeats, 0.75 ends: rational. 0.1010010001... never repeats: irrational. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd190080-2ab1-47d0-891b-389774fab2d9', 'NC26.8.ANFR.4', 1, 'choice', 'Describe how the subsets of the real numbers relate', 'Which statement about sets of numbers is true?', '["Every integer is a whole number","Every rational number is an integer","Every whole number is an integer","Every irrational number is a fraction"]', 'Every whole number is an integer', NULL, 'The whole numbers $0, 1, 2, \ldots$ are all integers. But $-1$ is an integer that is not whole, and $\frac{1}{2}$ is rational but not an integer. Irrational numbers cannot be written as fractions of integers.', 'checked', '{"lint":[],"solve":{"answer":"Every whole number is an integer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-1 is an integer, not whole (A false). 1/2 rational not integer (B false). Whole numbers 0,1,2,... are integers (C true). Irrationals cannot be fractions (D false).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aaa23b33-0d98-4f63-acba-475bcfe3cc30', 'NC26.8.ANFR.4', 1, 'choice', 'Describe how the subsets of the real numbers relate', 'Every integer is also a member of which set of numbers?', '["The rational numbers","The natural numbers","The whole numbers","The irrational numbers"]', 'The rational numbers', NULL, 'Any integer $n$ can be written as the fraction $\frac{n}{1}$, so every integer is a rational number.', 'checked', '{"lint":[],"solve":{"answer":"The rational numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Every integer n = n/1 is rational. Negative integers are not whole or natural; integers are not irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8dea83ef-f1c6-4516-a591-957155b84fbf', 'NC26.8.ANFR.4', 1, 'numeric', 'Describe how the subsets of the real numbers relate', 'The sets of numbers are: natural numbers $(1, 2, 3, \ldots)$, whole numbers $(0, 1, 2, \ldots)$, integers, rational numbers and irrational numbers. To how many of these five sets does the number $5$ belong?', '[]', '4', NULL, '$5$ is a natural number, a whole number, an integer and a rational number ($\frac{5}{1}$). It is not irrational. That is 4 sets.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 is natural, whole, an integer and rational; not irrational. Count = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7726b839-c53b-4f28-9102-f9bea428fefb', 'NC26.8.ANFR.4', 1, 'choice', 'Place a square or cube root between whole numbers', 'Between which two consecutive whole numbers does $\sqrt{40}$ lie?', '["5 and 6","7 and 8","6 and 7","20 and 21"]', '6 and 7', NULL, '$6^2 = 36$ and $7^2 = 49$. Since 40 is between 36 and 49, $\sqrt{40}$ is between 6 and 7.', 'checked', '{"lint":[],"solve":{"answer":"6 and 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36 < 40 < 49, so 6 < sqrt(40) < 7.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b25da68-f7d3-4414-9016-32506cc9a8fc', 'NC26.8.ANFR.4', 1, 'numeric', 'Place a square or cube root between whole numbers', 'What is the least whole number that is greater than $\sqrt{70}$?', '[]', '9', '9', '$8^2 = 64$ and $9^2 = 81$. Since 70 is between 64 and 81, $\sqrt{70}$ is between 8 and 9. The least whole number greater than it is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"64 < 70 < 81, so 8 < sqrt(70) < 9. Least whole number greater is 9.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c8c939-1284-44f9-ab81-75521a65391a', 'NC26.8.ANFR.4', 1, 'numeric', 'Place a square or cube root between whole numbers', 'The number 47 is not a perfect square. What perfect square is closest to 47?', '[]', '49', '7^2', 'The perfect squares near 47 are $36$ and $49$. 47 is 2 away from 49 but 11 away from 36, so the closest is 49.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Nearby squares 36 (11 away) and 49 (2 away). Closest is 49.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b222fb44-c07d-40cf-8d3e-c096518a1b7f', 'NC26.8.ANFR.4', 1, 'choice', 'Place a square or cube root between whole numbers', 'Which of these numbers lies between 7 and 8?', '["$\\sqrt{40}$","$\\sqrt{70}$","$\\sqrt{64}$","$\\sqrt{52}$"]', '$\sqrt{52}$', NULL, '$7^2 = 49$ and $8^2 = 64$, so a number between 7 and 8 has a square between 49 and 64. $\sqrt{52}$ qualifies. $\sqrt{40}$ is about 6.3, $\sqrt{70}$ is about 8.4, and $\sqrt{64} = 8$ exactly.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{52}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 49 < n < 64. sqrt(70) > 8, sqrt(40) < 7, sqrt(64) = 8 exactly (not strictly between). sqrt(52) is between 7 and 8.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93cc405c-6d87-48ca-ab58-0ae4a116000c', 'NC26.8.ANFR.4', 1, 'choice', 'Estimate an irrational number to the nearest tenth', 'Which decimal is closest to $\sqrt{17}$?', '["4.7","8.5","1.7","4.1"]', '4.1', NULL, '$4^2 = 16$ and $5^2 = 25$. 17 is just above 16, so $\sqrt{17}$ is just above 4. Check: $4.1^2 = 16.81$, which is very close to 17.', 'checked', '{"lint":[],"solve":{"answer":"4.1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 < 17 < 25 and 17 is just above 16; 4.1^2 = 16.81, 4.2^2 = 17.64, so sqrt(17) is about 4.12. Closest option 4.1.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dcb61e3-1e90-494f-aad0-bda833f8cdbb', 'NC26.8.ANFR.4', 1, 'numeric', 'Estimate an irrational number to the nearest tenth', 'A calculator shows $\sqrt{2} = 1.41421\ldots$ What is $\sqrt{2}$ rounded to the nearest tenth?', '[]', '1.4', NULL, 'The digit after the tenths place is 1, which is less than 5, so round down: $1.4$.', 'checked', '{"lint":[],"solve":{"answer":"1.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.41421... to the nearest tenth: hundredths digit 1 < 5, so 1.4.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
