INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d51dad04-8ff1-4bfa-b861-0a793d11edf0', 'NC26.8.ANFR.4', 1, 'choice', 'Estimate an irrational number to the nearest tenth', 'Since $3.1^2 = 9.61$ and $3.2^2 = 10.24$, between which two numbers does $\sqrt{10}$ lie?', '["3.0 and 3.1","3.2 and 3.3","3.1 and 3.2","9.6 and 10.2"]', '3.1 and 3.2', NULL, '10 is between $9.61$ and $10.24$, so $\sqrt{10}$ is between 3.1 and 3.2.', 'checked', '{"lint":[],"solve":{"answer":"3.1 and 3.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9.61 < 10 < 10.24, so 3.1 < sqrt(10) < 3.2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
