INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cba4bf2-32cd-4378-837f-8165f7007bc8', 'NC26.8.ANFR.4', 1, 'choice', 'Compare and order real numbers', 'Which comparison is correct?', '["$\\sqrt{30} < 5$","$\\sqrt{30} > 5$","$\\sqrt{30} = 15$","$\\sqrt{30} = 5$"]', '$\sqrt{30} > 5$', NULL, '$5^2 = 25$, which is less than 30, so $\sqrt{30}$ is greater than 5. (It is about 5.5.)', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{30} > 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^2 = 25 < 30, so sqrt(30) > 5 (about 5.48).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
