INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cfa46e7d-a898-4966-b900-b53bfd9b3d7e', 'NC26.8.ANFR.4', 1, 'choice', 'Compare and order real numbers', 'Which of these numbers is the least?', '["$7$","$\\sqrt{50}$","$7.5$","$8$"]', '$7$', NULL, '$\sqrt{50}$ is a little more than 7, because $7^2 = 49$. So $7 < \sqrt{50} < 7.5 < 8$, and the least is 7.', 'checked', '{"lint":[],"solve":{"answer":"$7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(50) is just above 7 (about 7.07). Order: 7 < sqrt(50) < 7.5 < 8. Least is 7.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
