VALUES ('544a41fa-eda9-467c-adb5-021629805648', 'NC26.8.ANFR.4', 1, 'numeric', 'Approximate an expression with pi', 'A circle has a radius of 10 centimeters. Use 3.14 for $\pi$ in the formula $C = 2\pi r$. What is the circumference, in centimeters?', '[]', '62.8', '2*3.14*10', '$C = 2 \times 3.14 \times 10 = 62.8$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"62.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 x 3.14 x 10 = 62.8.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
