VALUES ('734caa53-62b4-40e5-b81f-6c537e45d43a', 'NC26.8.ANFR.4', 1, 'numeric', 'Approximate an expression with pi', 'Use $\frac{22}{7}$ for $\pi$. What is the value of $7\pi$?', '[]', '22', '22/7*7', '$7 \times \frac{22}{7} = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 x 22/7 = 22.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
