INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66fecb67-9e49-430b-843b-a73d2446954b', 'NC26.8.ANFR.4', 2, 'choice', 'Classify a number within the real numbers', 'Which statement about the number $\frac{12}{4}$ is true?', '["It is a rational number and an integer","It is a rational number but not an integer","It is an irrational number","It is an integer but not a rational number"]', 'It is a rational number and an integer', NULL, '$\frac{12}{4} = 3$. It is a fraction of integers, so it is rational, and it equals the integer $3$.', 'checked', '{"lint":[],"solve":{"answer":"It is a rational number and an integer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/4 = 3, an integer, and every integer is rational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
