INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18cf6157-b245-4243-a96b-e2df7655bf7d', 'NC26.8.ANFR.4', 2, 'choice', 'Classify a number within the real numbers', 'Which list contains only integers?', '["$-7,\\ 0.3,\\ 12$","$-7,\\ 0,\\ 12$","$-7,\\ \\frac{1}{4},\\ 12$","$-7,\\ \\sqrt{12},\\ 12$"]', '$-7,\ 0,\ 12$', NULL, '$-7$, $0$ and $12$ are all integers. The other lists each contain a number that is not an integer: $0.3$, $\frac{1}{4}$ or $\sqrt{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$-7,\\ 0,\\ 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.3, 1/4 and sqrt(12) are not integers. -7, 0, 12 are all integers.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
