INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21e7b69f-dd97-496c-9bea-53df4ae8e0d3', 'NC26.8.ANFR.4', 2, 'numeric', 'Classify a number within the real numbers', 'How many of the numbers $-4$, $\frac{8}{2}$, $0.5$, $\sqrt{25}$ and $6$ are integers?', '[]', '4', NULL, '$\frac{8}{2} = 4$ and $\sqrt{25} = 5$, so $-4$, $4$, $5$ and $6$ are integers. $0.5$ is not. That is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4 integer; 8/2 = 4 integer; 0.5 not; sqrt(25) = 5 integer; 6 integer. Count = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
