INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0da6a50-6ec1-44e6-9b28-a81e8b8045be', 'NC26.8.ANFR.4', 2, 'choice', 'Recognise an irrational number', 'Which cube root is an irrational number?', '["$\\sqrt[3]{30}$","$\\sqrt[3]{8}$","$\\sqrt[3]{27}$","$\\sqrt[3]{125}$"]', '$\sqrt[3]{30}$', NULL, '$\sqrt[3]{8} = 2$, $\sqrt[3]{27} = 3$ and $\sqrt[3]{125} = 5$ are rational. 30 is not a perfect cube, so $\sqrt[3]{30}$ is irrational.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt[3]{30}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"125 = 5^3, 8 = 2^3, 27 = 3^3; 30 is not a perfect cube, so its cube root is irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
