INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('587d808d-aede-4218-a9dd-32310eb38d03', 'NC26.8.ANFR.4', 2, 'choice', 'Use a decimal expansion to tell rational from irrational', 'Which decimal is the decimal form of an irrational number?', '["$0.272727\\ldots$ (the block 27 repeats forever)","$0.375$ (the decimal stops)","$0.8333\\ldots$ (the digit 3 repeats forever)","$0.101001000100001\\ldots$ (one more 0 between the 1s each time, forever)"]', '$0.101001000100001\ldots$ (one more 0 between the 1s each time, forever)', NULL, 'A decimal that stops or repeats a block forever is rational: 0.375 is $\frac{3}{8}$, 0.2727... is $\frac{3}{11}$ and 0.8333... is $\frac{5}{6}$. The last decimal goes on forever without ever repeating a block, so it cannot be written as a fraction and is irrational.', 'checked', '{"lint":[],"solve":{"answer":"$0.101001000100001\\ldots$ (one more 0 between the 1s each time, forever)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-terminating, non-repeating decimal is irrational: 0.101001000100001...; others terminate or repeat.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99e12b4b-4b4d-4b0a-8c65-972725a5008f', 'NC26.8.ANFR.4', 2, 'choice', 'Compare and order real numbers', 'Which list is in order from least to greatest?', '["$5.4,\\ \\sqrt{29},\\ \\sqrt{30},\\ 5.5$","$\\sqrt{29},\\ 5.4,\\ 5.5,\\ \\sqrt{30}$","$\\sqrt{29},\\ 5.4,\\ \\sqrt{30},\\ 5.5$","$\\sqrt{29},\\ \\sqrt{30},\\ 5.4,\\ 5.5$"]', '$\sqrt{29},\ 5.4,\ \sqrt{30},\ 5.5$', NULL, 'Square the decimals: $5.4^2 = 29.16$ and $5.5^2 = 30.25$. Since $29 < 29.16 < 30 < 30.25$, we get $\sqrt{29} < 5.4 < \sqrt{30} < 5.5$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{29},\\ 5.4,\\ \\sqrt{30},\\ 5.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.4^2=29.16 so sqrt29<5.4<sqrt30 (since 29.16<30); 5.5^2=30.25 so sqrt30<5.5. Order sqrt29, 5.4, sqrt30, 5.5.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba9310d9-71b8-4bbf-90e7-5f807fff6091', 'NC26.8.ANFR.4', 3, 'numeric', 'Approximate a square root to the nearest tenth', 'What is $\sqrt{60}$, rounded to the nearest tenth?', '[]', '7.7', NULL, 'Since $7.7^2 = 59.29$ and $7.8^2 = 60.84$, $\sqrt{60}$ is between 7.7 and 7.8. The halfway point is 7.75, and $7.75^2 = 60.0625$, which is more than 60, so $\sqrt{60}$ is below 7.75. Rounded to the nearest tenth, $\sqrt{60} \approx 7.7$.', 'checked', '{"lint":[],"solve":{"answer":"7.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.7^2 = 59.29, 7.8^2 = 60.84; 7.75^2 = 60.0625 > 60, so sqrt(60) is between 7.7 and 7.75 (about 7.746). Rounds to 7.7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('654cb301-5089-450a-82e2-caafc0a3bca6', 'NC26.8.ANFR.4', 3, 'choice', 'Find a number that is irrational and lies in a given interval', 'Which number is irrational and lies between 5 and 6?', '["$\\sqrt{28}$","$\\sqrt{25}$","$\\frac{16}{3}$","$\\sqrt{40}$"]', '$\sqrt{28}$', NULL, '$\sqrt{28}$ is between $\sqrt{25} = 5$ and $\sqrt{36} = 6$, and 28 is not a perfect square, so it is irrational. $\sqrt{25} = 5$ is rational and not between 5 and 6. $\frac{16}{3} \approx 5.33$ is between 5 and 6 but rational. $\sqrt{40} \approx 6.3$ is irrational but greater than 6.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{28}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Between 5 and 6 means between sqrt(25) and sqrt(36). sqrt(40) > 6; sqrt(25) = 5 rational; 16/3 = 5.33 rational. sqrt(28) is about 5.29 and irrational.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22e4eed2-5ceb-4faf-ada7-4291dd07f0d9', 'NC26.8.ANFR.4', 3, 'choice', 'Order rational and irrational numbers', 'Which list puts $3$, $\pi$, $\sqrt{10}$ and $3.2$ in order from least to greatest?', '["$3, \\sqrt{10}, \\pi, 3.2$","$\\pi, 3, \\sqrt{10}, 3.2$","$3, \\pi, \\sqrt{10}, 3.2$","$3, \\pi, 3.2, \\sqrt{10}$"]', '$3, \pi, \sqrt{10}, 3.2$', NULL, 'Approximate each number: $\pi \approx 3.14$, $\sqrt{10} \approx 3.16$ (because $3.16^2 \approx 9.99$), and 3.2 and 3 are given. In order: $3 < 3.14 < 3.16 < 3.2$, that is $3, \pi, \sqrt{10}, 3.2$.', 'checked', '{"lint":[],"solve":{"answer":"$3, \\pi, \\sqrt{10}, 3.2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3; pi = 3.14159...; sqrt(10) = 3.1623 (3.16^2 = 9.9856, 3.17^2 = 10.0489); 3.2. Order: 3, pi, sqrt(10), 3.2.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30773af1-50cf-4fe6-b60b-ce3091162fd7', 'NC26.8.ANFR.4', 3, 'choice', 'Classify a number within the real numbers', 'A number is rational and is an integer, but it is not a whole number. Which number could it be?', '["$\\frac{10}{5}$","$-\\frac{5}{10}$","$\\frac{5}{10}$","$-\\frac{10}{5}$"]', '$-\frac{10}{5}$', NULL, '$-\frac{10}{5} = -2$ is a negative integer, so it is rational and an integer but not whole. $\frac{10}{5} = 2$ is whole, and $-\frac{5}{10} = -\frac{1}{2}$ and $\frac{5}{10} = \frac{1}{2}$ are not integers.', 'checked', '{"lint":[],"solve":{"answer":"$-\\frac{10}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Integer but not whole means a negative integer. 10/5 = 2 (whole), 5/10 = 0.5 and -5/10 = -0.5 (not integers), -10/5 = -2 (negative integer).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ae395a1-4af2-4b47-8f3b-060f17e45e12', 'NC26.8.ANFR.4', 3, 'choice', 'Classify a number within the real numbers', 'Which number is a rational number that is not an integer?', '["$\\sqrt{49}$","$-\\frac{18}{6}$","$\\sqrt{\\frac{9}{4}}$","$\\frac{0}{5}$"]', '$\sqrt{\frac{9}{4}}$', NULL, '$\sqrt{\frac{9}{4}} = \frac{3}{2}$, a fraction that is not a whole amount. The others simplify to integers: $\sqrt{49} = 7$, $-\frac{18}{6} = -3$ and $\frac{0}{5} = 0$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{\\frac{9}{4}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(9/4) = 3/2 = 1.5, rational, not an integer. sqrt(49) = 7, 0/5 = 0, -18/6 = -3 are integers.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c46616ec-100c-4f30-bb24-57b6ef776bed', 'NC26.8.ANFR.4', 3, 'numeric', 'Classify a number within the real numbers', 'How many of the numbers $\frac{3}{4}$, $-2.5$, $\sqrt{16}$, $\frac{14}{7}$, $\sqrt{5}$ and $0.\overline{3}$ are rational numbers that are not integers?', '[]', '3', NULL, '$\sqrt{16} = 4$ and $\frac{14}{7} = 2$ are integers. $\sqrt{5}$ is irrational. The rational non-integers are $\frac{3}{4}$, $-2.5$ and $0.\overline{3}$, so 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/4: rational non-integer (yes). -2.5: yes. sqrt(16) = 4: integer (no). 14/7 = 2: integer (no). sqrt(5): irrational (no). 0.333... = 1/3: yes. Count = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af1dfa09-77ef-4741-9225-d6cc7525179d', 'NC26.8.ANFR.4', 3, 'choice', 'Recognise an irrational number', 'Exactly one of these numbers is irrational. Which one is it?', '["$\\sqrt{\\frac{4}{25}}$","$\\sqrt{0.09}$","$\\sqrt{0.9}$","$\\sqrt{\\frac{49}{16}}$"]', '$\sqrt{0.9}$', NULL, '$\sqrt{\frac{4}{25}} = \frac{2}{5}$, $\sqrt{0.09} = 0.3$ and $\sqrt{\frac{49}{16}} = \frac{7}{4}$ are rational. $0.9 = \frac{9}{10}$ and 10 is not a perfect square, so $\sqrt{0.9}$ is irrational.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{0.9}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(0.09) = 0.3; sqrt(4/25) = 2/5; sqrt(49/16) = 7/4. sqrt(0.9) = sqrt(9/10) = 3/sqrt(10), irrational (0.9 is not the square of a rational: 0.3^2 = 0.09, 0.9^2 = 0.81).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6c38f64-a339-4162-bf32-a6cfa7d3d8bc', 'NC26.8.ANFR.4', 3, 'choice', 'Recognise an irrational number', 'Which statement about $\sqrt{50}$ is true?', '["It is rational and lies between 7 and 8","It is irrational and lies between 6 and 7","It is rational and lies between 25 and 26","It is irrational and lies between 7 and 8"]', 'It is irrational and lies between 7 and 8', NULL, '50 is not a perfect square, so $\sqrt{50}$ is irrational. Since $7^2 = 49$ and $8^2 = 64$, it lies between 7 and 8.', 'checked', '{"lint":[],"solve":{"answer":"It is irrational and lies between 7 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"49 < 50 < 64, so 7 < sqrt(50) < 8; 50 is not a perfect square, so irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27ea2c16-5e79-469d-89bc-b567d76a9737', 'NC26.8.ANFR.4', 3, 'numeric', 'Recognise an irrational number', 'How many whole numbers $n$ from 1 to 40 have an irrational square root?', '[]', '34', NULL, 'The perfect squares from 1 to 40 are 1, 4, 9, 16, 25 and 36, which is 6 numbers with a rational root. The other $40 - 6 = 34$ numbers have an irrational square root.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perfect squares from 1 to 40: 1, 4, 9, 16, 25, 36 (6 of them). The other 40 - 6 = 34 have irrational square roots.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
