INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b69f3a35-d3d7-41d2-b0a5-426bfe9ad640', 'NC26.8.ANFR.4', 3, 'numeric', 'Recognise an irrational number', 'How many whole numbers $n$ from 1 to 100 have a rational cube root?', '[]', '4', '4', 'A whole number has a rational cube root only if it is a perfect cube. From 1 to 100 the perfect cubes are $1^3 = 1$, $2^3 = 8$, $3^3 = 27$ and $4^3 = 64$. That is 4 numbers.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perfect cubes from 1 to 100: 1, 8, 27, 64 (125 too big). Count = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ecc8da1-9f0c-409c-aa71-45936639fb13', 'NC26.8.ANFR.4', 3, 'choice', 'Use a decimal expansion to tell rational from irrational', 'Which of these decimals is irrational?', '["$2.16666\\ldots$ (the 6 repeats forever)","$1.01001000100001\\ldots$ (one more 0 between the 1s each time)","$0.\\overline{1234}$","$3.14$"]', '$1.01001000100001\ldots$ (one more 0 between the 1s each time)', NULL, '$2.1\overline{6}$ and $0.\overline{1234}$ repeat, and $3.14$ ends, so all three are rational. The decimal with one more 0 between the 1s each time never repeats and never ends, so it is irrational.', 'checked', '{"lint":[],"solve":{"answer":"$1.01001000100001\\ldots$ (one more 0 between the 1s each time)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.1666... repeats, 0.12341234... repeats, 3.14 ends: all rational. 1.0100100010000 1... has growing runs of 0s, never repeats: irrational.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db1cbdfc-35f1-418c-b373-e30f0c5bc5e9', 'NC26.8.ANFR.4', 3, 'choice', 'Use a decimal expansion to tell rational from irrational', 'Jo says: "The decimal $0.24681012\ldots$, which writes the even numbers one after another, has a pattern, so it repeats and is rational." Which statement is correct?', '["Jo is right: a pattern means the decimal repeats","Jo is wrong: it is rational because it never ends","Jo is wrong: it never ends and never repeats, so it is irrational","Jo is right: every decimal that never ends is rational"]', 'Jo is wrong: it never ends and never repeats, so it is irrational', NULL, 'The pattern is that the numbers keep getting longer, so no block of digits repeats forever. A decimal that never ends and never repeats is irrational.', 'checked', '{"lint":[],"solve":{"answer":"Jo is wrong: it never ends and never repeats, so it is irrational","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.24681012141618... has a pattern but no block of digits that repeats forever (the even numbers get longer), so it never ends and never repeats: irrational. Jo is wrong.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82d23114-5b22-44c5-8180-422b68a96b32', 'NC26.8.ANFR.4', 3, 'numeric', 'Use a decimal expansion to tell rational from irrational', 'How many digits are to the right of the decimal point when $\frac{3}{16}$ is written as a decimal?', '[]', '4', NULL, '$\frac{3}{16} = 0.1875$, which has 4 digits after the decimal point.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Mostly a fraction-to-decimal conversion; only weakly about the number system (it does touch on terminating decimals).","work":"3/16 = 0.1875 (3 x 625 = 1875, 16 x 625 = 10000). 4 digits after the decimal point.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9bce7108-2301-496a-becb-f5cc511b7159', 'NC26.8.ANFR.4', 3, 'choice', 'Describe how the subsets of the real numbers relate', 'Which pair of sets has no number in common?', '["Integers and rational numbers","Whole numbers and integers","Rational numbers and real numbers","Rational numbers and irrational numbers"]', 'Rational numbers and irrational numbers', NULL, 'A real number is either rational or irrational, never both. The other pairs overlap: the integers are inside the rationals, the whole numbers are inside the integers, and the rationals are inside the reals.', 'checked', '{"lint":[],"solve":{"answer":"Rational numbers and irrational numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A number cannot be both rational and irrational. The other pairs overlap (e.g. 1).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d49388a4-a5a4-44ab-b407-3e0d1af1cdb6', 'NC26.8.ANFR.4', 3, 'choice', 'Describe how the subsets of the real numbers relate', 'Which list puts the sets of numbers in order so that each set is completely inside the next one?', '["whole, natural, integers, rational, real","natural, whole, integers, rational, real","natural, integers, whole, rational, real","natural, whole, rational, integers, real"]', 'natural, whole, integers, rational, real', NULL, 'The natural numbers are inside the whole numbers, which are inside the integers, which are inside the rational numbers, which are inside the real numbers.', 'checked', '{"lint":[],"solve":{"answer":"natural, whole, integers, rational, real","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"natural (1,2,...) inside whole (0,1,...) inside integers inside rational inside real.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9168071d-8fb7-406d-b0ce-8dc900f4f08f', 'NC26.8.ANFR.4', 3, 'numeric', 'Describe how the subsets of the real numbers relate', 'How many of these five statements are true? (1) Every natural number is an integer. (2) Every integer is a whole number. (3) Every whole number is a rational number. (4) Every rational number is a real number. (5) Some irrational numbers are rational numbers.', '[]', '3', NULL, '(1) is true. (2) is false, since $-3$ is an integer that is not whole. (3) is true. (4) is true. (5) is false, since no number is both. That is 3 true statements.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) true. (2) false (-1). (3) true. (4) true. (5) false (no number is both). Count = 3.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1b2a12f-f702-4d33-a41e-475633a89d2e', 'NC26.8.ANFR.4', 3, 'numeric', 'Place a square or cube root between whole numbers', 'How many whole numbers are greater than $\sqrt{20}$ and less than $\sqrt{110}$?', '[]', '6', NULL, '$\sqrt{20}$ is between 4 and 5 (about 4.5), and $\sqrt{110}$ is between 10 and 11 (about 10.5). The whole numbers in between are 5, 6, 7, 8, 9 and 10, which is 6 numbers.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(20) is about 4.47 (16 < 20 < 25); sqrt(110) is about 10.49 (100 < 110 < 121). Whole numbers 5, 6, 7, 8, 9, 10: count 6.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('715eb27b-6305-4fdd-8e6d-a58c389390c2', 'NC26.8.ANFR.4', 3, 'choice', 'Place a square or cube root between whole numbers', 'Which number is greater than 4 and less than 5?', '["$\\sqrt[3]{100}$","$\\sqrt{30}$","$\\sqrt[3]{50}$","$\\sqrt{15}$"]', '$\sqrt[3]{100}$', NULL, '$4^3 = 64$ and $5^3 = 125$, and 100 is between them, so $\sqrt[3]{100}$ is between 4 and 5. The others: $\sqrt{30}$ is about 5.5, $\sqrt[3]{50}$ is about 3.7 and $\sqrt{15}$ is about 3.9.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt[3]{100}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(30) about 5.48 (no). Cube root of 50: 27 < 50 < 64, about 3.68 (no). sqrt(15) about 3.87 (no). Cube root of 100: 64 < 100 < 125, so between 4 and 5 (yes).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9a077c6-1256-4087-9391-1caf72f30f36', 'NC26.8.ANFR.4', 3, 'choice', 'Place a square or cube root between whole numbers', 'Which pair of consecutive whole numbers has $\sqrt{200} - 3$ between them?', '["14 and 15","11 and 12","10 and 11","197 and 198"]', '11 and 12', NULL, '$14^2 = 196$ and $15^2 = 225$, so $\sqrt{200}$ is between 14 and 15 (about 14.1). Subtracting 3 gives a number between 11 and 12.', 'checked', '{"lint":[],"solve":{"answer":"11 and 12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"196 < 200 < 225, so 14 < sqrt(200) < 15 (about 14.14). Minus 3: about 11.14, between 11 and 12.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce31aec9-2e32-44c9-bdc5-10156944ae8d', 'NC26.8.ANFR.4', 3, 'choice', 'Estimate an irrational number to the nearest tenth', 'Round $\sqrt{150}$ to the nearest tenth. Which choice is correct?', '["12.2","12.3","12.5","75"]', '12.2', NULL, '$12^2 = 144$ and $13^2 = 169$. $12.2^2 = 148.84$ and $12.3^2 = 151.29$. The halfway point is $12.25$, and $12.25^2 = 150.0625$ is a little more than 150, so $\sqrt{150}$ is below 12.25 and rounds to $12.2$.', 'checked', '{"lint":[],"solve":{"answer":"12.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12.2^2 = 148.84, 12.3^2 = 151.29; 12.25^2 = 150.0625 > 150, so sqrt(150) is about 12.247, below the midpoint: rounds to 12.2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03a2954b-c016-48bb-9849-25ab241fcf92', 'NC26.8.ANFR.4', 3, 'numeric', 'Estimate an irrational number to the nearest tenth', 'Which whole number $n$ has a square root closest to 6.7?', '[]', '45', NULL, '$6.7^2 = 44.89$, which is closest to the whole number 45. Check: $\sqrt{45} \approx 6.708$, while $\sqrt{44} \approx 6.633$.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6.7^2 = 44.89. sqrt(45) is about 6.708 (0.008 off); sqrt(44) is about 6.633 (0.067 off). n = 45.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4018ed7-33b5-494b-b09a-ad2374e1a59b', 'NC26.8.ANFR.4', 3, 'numeric', 'Estimate an irrational number to the nearest tenth', 'Two square tiles, each with a side length of $\sqrt{3}$ inches, are placed side by side to make a rectangle. Use 1.73 for $\sqrt{3}$. What is the perimeter of the rectangle, in inches?', '[]', '10.38', '6*1.73', 'The rectangle is $2\sqrt{3}$ inches long and $\sqrt{3}$ inches wide. The perimeter is $2(2\sqrt{3} + \sqrt{3}) = 6\sqrt{3} \approx 6 \times 1.73 = 10.38$ inches.', 'checked', '{"lint":[],"solve":{"answer":"10.38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rectangle is 2 sqrt(3) by sqrt(3). Perimeter = 2(2 sqrt(3) + sqrt(3)) = 6 sqrt(3) = 6 x 1.73 = 10.38.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('44b9d3cf-4b59-4177-90d7-39c19fc4725d', 'NC26.8.ANFR.4', 3, 'numeric', 'Estimate an irrational number to the nearest tenth', 'A square has an area of 28 square meters. To the nearest whole meter, what is its perimeter?', '[]', '21', NULL, 'The side is $\sqrt{28}$, which is about 5.29 since $5.3^2 = 28.09$. The perimeter is about $4 \times 5.29 = 21.2$, which rounds to 21 meters.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Side = sqrt(28), about 5.29 (5.3^2 = 28.09). Perimeter = 4 x 5.29 = about 21.17, rounds to 21.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab61fd37-7728-42fd-a943-994033b9e7c7', 'NC26.8.ANFR.4', 3, 'choice', 'Compare and order real numbers', 'Four numbers are $\pi$, $\sqrt{10}$, $3.14$ and $\frac{22}{7}$. Which list puts them in order from greatest to least?', '["$\\sqrt{10},\\ \\pi,\\ \\frac{22}{7},\\ 3.14$","$\\frac{22}{7},\\ \\sqrt{10},\\ \\pi,\\ 3.14$","$\\sqrt{10},\\ \\frac{22}{7},\\ \\pi,\\ 3.14$","$\\sqrt{10},\\ \\frac{22}{7},\\ 3.14,\\ \\pi$"]', '$\sqrt{10},\ \frac{22}{7},\ \pi,\ 3.14$', NULL, '$\sqrt{10} \approx 3.1623$, $\frac{22}{7} \approx 3.1429$, $\pi \approx 3.1416$ and $3.14$. From greatest to least: $\sqrt{10},\ \frac{22}{7},\ \pi,\ 3.14$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{10},\\ \\frac{22}{7},\\ \\pi,\\ 3.14$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(10) about 3.1623; 22/7 = 3.142857...; pi = 3.14159...; 3.14. Greatest to least: sqrt(10), 22/7, pi, 3.14.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7b89327-2ba5-4337-b5dd-151bc2fe6bed', 'NC26.8.ANFR.4', 3, 'choice', 'Compare and order real numbers', 'Which number is between $\sqrt{18}$ and $\sqrt{26}$?', '["$4.1$","$4.5$","$5.2$","$\\sqrt{16}$"]', '$4.5$', NULL, '$\sqrt{18}$ is about $4.24$ and $\sqrt{26}$ is about $5.10$. Only $4.5$ is between them: $4.1$ and $\sqrt{16} = 4$ are too small and $5.2$ is too big.', 'checked', '{"lint":[],"solve":{"answer":"$4.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(18) about 4.24, sqrt(26) about 5.10. 5.2 too big; sqrt(16) = 4 too small; 4.1 too small (4.1^2 = 16.81 < 18); 4.5 (4.5^2 = 20.25) is between.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4e8d6c6-fb9e-4057-869e-6749fc388ae3', 'NC26.8.ANFR.4', 3, 'numeric', 'Compare and order real numbers', 'How many whole numbers are greater than $\sqrt[3]{50}$ and less than $\sqrt{50}$?', '[]', '4', '7-4+1', '$\sqrt[3]{50}$ is between 3 and 4 (since $3^3 = 27$ and $4^3 = 64$), and $\sqrt{50}$ is between 7 and 8. The whole numbers in between are 4, 5, 6 and 7, which is 4 numbers.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube root of 50 is between 3 and 4 (27 < 50 < 64); sqrt(50) between 7 and 8 (about 7.07). Whole numbers 4, 5, 6, 7: count 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('afe0b5c6-c4df-4505-92ce-73ef46a8b6e0', 'NC26.8.ANFR.4', 3, 'numeric', 'Compare and order real numbers', 'What is the sum of all the integers that are greater than $-\sqrt{30}$ and less than $\sqrt{10}$?', '[]', '-9', '-5-4', '$-\sqrt{30}$ is between $-6$ and $-5$, and $\sqrt{10}$ is between 3 and 4. The integers are $-5, -4, -3, -2, -1, 0, 1, 2, 3$. The pairs from $-3$ to $3$ cancel, leaving $-5 + (-4) = -9$.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-sqrt(30) about -5.48; sqrt(10) about 3.16. Integers -5 to 3. Sum = (-5-4-3-2-1) + 0 + (1+2+3) = -15 + 6 = -9.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90b51096-1006-4bea-ac1d-6952ec1efde4', 'NC26.8.ANFR.4', 3, 'numeric', 'Approximate an expression with pi', 'A bicycle wheel has a diameter of 26 inches. Use 3.14 for $\pi$. How many inches does the bicycle travel when the wheel turns 10 times?', '[]', '816.4', '3.14*26*10', 'One turn is one circumference: $3.14 \times 26 = 81.64$ inches. Ten turns is $81.64 \times 10 = 816.4$ inches.', 'checked', '{"lint":[],"solve":{"answer":"816.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One turn = 3.14 x 26 = 81.64 in. Ten turns = 816.4 in.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b29f4110-e825-4679-bd25-8c971e5bae2b', 'NC26.8.ANFR.4', 3, 'numeric', 'Approximate an expression with pi', 'Use $\frac{22}{7}$ for $\pi$. A circle has a circumference of 44 centimeters. What is its radius, in centimeters?', '[]', '7', '44/(2*22/7)', '$C = 2\pi r$, so $r = \frac{C}{2\pi} = \frac{44}{2 \times \frac{22}{7}} = \frac{44}{\frac{44}{7}} = 7$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 2 pi r: 44 = 2 x 22/7 x r = (44/7) r, so r = 7.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f0d6f2d-1b59-43a6-8692-b3b99abe36bb', 'NC26.8.ANFR.4', 3, 'choice', 'Approximate an expression with pi', 'The value of $\pi$ is $3.14159\ldots$ Which statement is true?', '["$\\frac{22}{7}$ is equal to $\\pi$","$3.14$ is greater than $\\pi$","$\\frac{22}{7}$ is greater than $\\pi$","$3.14$ is equal to $\\pi$"]', '$\frac{22}{7}$ is greater than $\pi$', NULL, '$\frac{22}{7} = 3.142857\ldots$, which is greater than $3.14159\ldots$ And $3.14$ is a little less than $\pi$. Neither is exactly equal to $\pi$, because $\pi$ is irrational.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{22}{7}$ is greater than $\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"22/7 = 3.142857... > 3.14159...; 3.14 < pi. Only ''greater'' for 22/7 is true.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22cec013-70c1-4b1b-8b89-b93043456aa6', 'NC26.8.ANFR.4', 3, 'choice', 'Approximate an expression with pi', 'Which expression has a value closest to 10?', '["$3\\pi$","$\\pi^2$","$\\pi + 6$","$4\\pi$"]', '$\pi^2$', NULL, 'With $\pi \approx 3.14$: $\pi^2 \approx 9.86$, $3\pi \approx 9.42$, $\pi + 6 \approx 9.14$ and $4\pi \approx 12.56$. The closest to 10 is $\pi^2$.', 'checked', '{"lint":[],"solve":{"answer":"$\\pi^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"pi^2 about 9.87 (0.13 off); 4 pi about 12.57 (2.57 off); 3 pi about 9.42 (0.58 off); pi + 6 about 9.14 (0.86 off). Closest: pi^2.","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
