INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('097855fc-d3f0-4219-b481-599670ae5cec', 'NC26.8.ANFR.4', 3, 'numeric', 'Approximate an expression with pi', 'Use 3.14 for $\pi$. A pizza shop sells a 12-inch pizza and a 16-inch pizza, where each size is the diameter. How many more square inches of pizza are in the larger one?', '[]', '87.92', '3.14*(8^2-6^2)', 'The radii are 6 and 8 inches. The areas are $3.14 \times 6^2 = 113.04$ and $3.14 \times 8^2 = 200.96$ square inches. The difference is $200.96 - 113.04 = 87.92$.', 'checked', '{"lint":[],"solve":{"answer":"87.92","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Radii 6 and 8. Areas 3.14 x 36 = 113.04 and 3.14 x 64 = 200.96. Difference = 87.92 (= 3.14 x 28).","run_id":"claude-code","at":"2026-10-17T20:26:58.568Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('483f3011-eb3a-436d-a287-c55276da3729', 'NC26.8.ANFR.4', 3, 'numeric', 'Place a square or cube root between whole numbers', 'How many whole numbers $n$ have a cube root that is greater than 3 and less than 4?', '[]', '36', '63-28+1', '$3^3 = 27$ and $4^3 = 64$. A number has a cube root greater than 3 and less than 4 exactly when it is greater than 27 and less than 64. The whole numbers from 28 to 63 are $63 - 28 + 1 = 36$ numbers.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^3=27, 4^3=64; need 27<n<64, n=28..63: 63-28+1=36.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb113841-778f-4507-af75-9c6502ebca62', 'NC26.8.ANFR.5', 1, 'choice', 'Multiply powers with the same base', 'Which expression is equal to $5^4 \times 5^3$?', '["$5^{12}$","$25^7$","$5^{1}$","$5^7$"]', '$5^7$', NULL, 'When you multiply powers with the same base, add the exponents: $5^4 \times 5^3 = 5^{4+3} = 5^7$.', 'checked', '{"lint":[],"solve":{"answer":"$5^7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same base: add exponents, 5^(4+3) = 5^7.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
