INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c25db415-ae21-4cde-8d86-869462638abb', 'NC26.8.ANFR.5', 1, 'numeric', 'Convert between scientific notation and standard form', '$38{,}000 = 3.8 \times 10^{n}$. What is the value of $n$?', '[]', '4', NULL, 'Moving the decimal point 4 places left turns 38,000 into 3.8, so $n = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"38,000 = 3.8 x 10,000 = 3.8 x 10^4, n = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
