INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7d8be00-370b-4728-9ea8-165f3f8c81fe', 'NC26.8.ANFR.5', 1, 'numeric', 'Compare numbers in scientific notation', 'How many times as large as $10^{5}$ is $10^{8}$?', '[]', '1000', '10^8/10^5', 'Divide: $\frac{10^8}{10^5} = 10^3 = 1000$.', 'checked', '{"lint":[],"solve":{"answer":"1000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10^8 / 10^5 = 10^3 = 1000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
