INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2e27802-ffbd-4e91-8728-c0309fae356b', 'NC26.8.ANFR.5', 2, 'choice', 'Evaluate a square root or cube root', 'Find $\sqrt[3]{-27}$. Which choice is correct?', '["$3$","$-9$","$27$","$-3$"]', '$-3$', NULL, '$(-3) \times (-3) \times (-3) = -27$, so $\sqrt[3]{-27} = -3$. (A cube root of a negative number is negative.)', 'checked', '{"lint":[],"solve":{"answer":"$-3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3) x (-3) x (-3) = -27, so the cube root of -27 is -3.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
