INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4b9adb4-2141-45e3-841b-2bd355940284', 'NC26.8.ANFR.5', 2, 'choice', 'Evaluate a square root or cube root', 'What is the sum of $\sqrt{49}$ and $\sqrt[3]{8}$?', '["$5$","$9$","$11$","$\\sqrt{57}$"]', '$9$', NULL, '$\sqrt{49} = 7$ and $\sqrt[3]{8} = 2$, so the sum is $7 + 2 = 9$. (Do not add the numbers under the roots.)', 'checked', '{"lint":[],"solve":{"answer":"$9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(49) = 7, cube root of 8 = 2; 7 + 2 = 9.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3a08b226-b797-4791-ae62-c4eed431083a', 'NC26.8.ANFR.5', 2, 'choice', 'Solve x squared or x cubed equals a number', 'Solve $x^2 = \frac{4}{9}$.', '["$x = \\frac{2}{3}$ only","$x = \\frac{2}{9}$ or $x = -\\frac{2}{9}$","$x = \\frac{2}{3}$ or $x = -\\frac{2}{3}$","$x = \\frac{16}{81}$ or $x = -\\frac{16}{81}$"]', '$x = \frac{2}{3}$ or $x = -\frac{2}{3}$', NULL, 'Take the square root of both sides: $x = \pm\sqrt{\frac{4}{9}} = \pm\frac{2}{3}$. There are two solutions, positive and negative.', 'checked', '{"lint":[],"solve":{"answer":"$x = \\frac{2}{3}$ or $x = -\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = +/- sqrt(4/9) = +/- 2/3.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('925576cb-8269-4948-83d5-83d17f03b6bf', 'NC26.8.ANFR.5', 2, 'choice', 'Solve x squared or x cubed equals a number', 'Solve $x^3 = -8$.', '["$x = -2$","$x = 2$","$x = -4$","$x = 2$ or $x = -2$"]', '$x = -2$', NULL, '$(-2) \times (-2) \times (-2) = -8$, so $x = -2$. A cube has just one real solution, so there is no second answer.', 'checked', '{"lint":[],"solve":{"answer":"$x = -2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2)^3 = -8; 2^3 = 8, so only x = -2.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
