INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d1d214f-69bd-42c6-84f1-03fbe43260cc', 'NC26.8.ANFR.5', 2, 'numeric', 'Solve x squared or x cubed equals a number', 'What is the positive solution of $x^2 = 0.25$?', '[]', '0.5', NULL, '$0.5 \times 0.5 = 0.25$, so the positive solution is $0.5$.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5^2 = 0.25, so the positive solution is 0.5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
