INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c94232a-11f4-49ad-9db5-780a2b35c7a8', 'NC26.8.ANFR.5', 2, 'choice', 'Solve x squared or x cubed equals a number', 'Which equation has no real number solution?', '["$x^2 = 9$","$x^3 = 9$","$x^3 = -9$","$x^2 = -9$"]', '$x^2 = -9$', NULL, 'A square is never negative, so $x^2 = -9$ has no real solution. The others do: $x = \pm 3$, $x = \sqrt[3]{9}$ and $x = \sqrt[3]{-9}$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 = -9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A real number squared is never negative, so x^2 = -9 has no real solution. Cube equations always have one real solution; x^2 = 9 has +/-3.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e7707b8-8840-4894-afb3-cab8cd8a94f6', 'NC26.8.ANFR.5', 2, 'choice', 'Use square and cube roots in a measurement problem', 'A square garden has an area of 144 square meters. How many meters of fence go all the way around it?', '["36","24","48","72"]', '48', '4*12', 'Each side is $\sqrt{144} = 12$ meters. The fence goes around all four sides: $4 \times 12 = 48$ meters.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"side = sqrt(144) = 12 m; perimeter = 4 x 12 = 48 m.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
