INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12a73a02-35dc-4399-b1f5-4f9e241f5101', 'NC26.8.ANFR.5', 2, 'choice', 'Convert between scientific notation and standard form', 'A speck of dust has a mass of $0.0000032$ gram. Which choice shows this mass in scientific notation?', '["$3.2 \\times 10^{-5}$","$3.2 \\times 10^{-6}$","$3.2 \\times 10^{6}$","$3.2 \\times 10^{-7}$"]', '$3.2 \times 10^{-6}$', NULL, 'Move the decimal point 6 places right to get $3.2$. Because the original number is small, the exponent is negative: $3.2 \times 10^{-6}$.', 'checked', '{"lint":[],"solve":{"answer":"$3.2 \\times 10^{-6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.0000032: move the point 6 places right to get 3.2, so 3.2 x 10^-6.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
