INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2263d69-e301-4ed4-815f-dac36e4cb76e', 'NC26.8.ANFR.5', 2, 'choice', 'Compare numbers in scientific notation', 'Which list is in order from least to greatest?', '["$2.0 \\times 10^{-1},\\ 3.4 \\times 10^{-2},\\ 5.1 \\times 10^{-3}$","$3.4 \\times 10^{-2},\\ 5.1 \\times 10^{-3},\\ 2.0 \\times 10^{-1}$","$5.1 \\times 10^{-3},\\ 3.4 \\times 10^{-2},\\ 2.0 \\times 10^{-1}$","$2.0 \\times 10^{-1},\\ 5.1 \\times 10^{-3},\\ 3.4 \\times 10^{-2}$"]', '$5.1 \times 10^{-3},\ 3.4 \times 10^{-2},\ 2.0 \times 10^{-1}$', NULL, 'Written as decimals: $5.1 \times 10^{-3} = 0.0051$, $3.4 \times 10^{-2} = 0.034$ and $2.0 \times 10^{-1} = 0.2$. The order from least to greatest is $0.0051,\ 0.034,\ 0.2$.', 'checked', '{"lint":[],"solve":{"answer":"$5.1 \\times 10^{-3},\\ 3.4 \\times 10^{-2},\\ 2.0 \\times 10^{-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5.1 x 10^-3 = 0.0051; 3.4 x 10^-2 = 0.034; 2.0 x 10^-1 = 0.2. Least to greatest: 0.0051, 0.034, 0.2.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b315924-c3d2-4257-83b6-82f271d1fd26', 'NC26.8.ANFR.5', 2, 'numeric', 'Compare numbers in scientific notation', 'How many times as large as $3 \times 10^{4}$ is $6 \times 10^{7}$?', '[]', '2000', '6*10^7/(3*10^4)', 'Divide: $\frac{6 \times 10^7}{3 \times 10^4} = 2 \times 10^3 = 2000$.', 'checked', '{"lint":[],"solve":{"answer":"2000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6/3) x 10^(7-4) = 2 x 10^3 = 2000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('025e608a-3c00-4376-9b38-6dca159928c1', 'NC26.8.ANFR.5', 2, 'numeric', 'Compute with numbers in scientific notation', 'What is $\frac{8 \times 10^{9}}{2 \times 10^{4}}$ as a whole number?', '[]', '400000', '8*10^9/(2*10^4)', 'Divide the numbers: $8 \div 2 = 4$. Subtract the exponents: $9 - 4 = 5$. The result is $4 \times 10^5 = 400{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"400000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8/2) x 10^(9-4) = 4 x 10^5 = 400,000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f46ad181-7d40-404d-b168-c96de9557cf8', 'NC26.8.ANFR.5', 2, 'choice', 'Compute with numbers in scientific notation', 'A cell is $2 \times 10^{-5}$ meter wide. A row has $4 \times 10^{3}$ of these cells touching side by side. How long is the row, in meters?', '["$8 \\times 10^{-8}$","$8 \\times 10^{-15}$","$8 \\times 10^{-2}$","$6 \\times 10^{-2}$"]', '$8 \times 10^{-2}$', NULL, 'Multiply the numbers: $2 \times 4 = 8$. Add the exponents: $-5 + 3 = -2$. The row is $8 \times 10^{-2}$ meter long.', 'checked', '{"lint":[],"solve":{"answer":"$8 \\times 10^{-2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2 x 4) x 10^(-5+3) = 8 x 10^-2 m.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b620394f-638b-43b1-b6b5-02f213d5231c', 'NC26.8.ANFR.5', 3, 'choice', 'Multiply numbers in scientific notation', 'Which choice shows $(3 \times 10^4) \times (2 \times 10^3)$ in scientific notation?', '["$6 \\times 10^{12}$","$6 \\times 10^{7}$","$5 \\times 10^{7}$","$6 \\times 10^{1}$"]', '$6 \times 10^{7}$', NULL, 'Multiply the numbers in front: $3 \times 2 = 6$. Add the exponents of 10: $10^4 \times 10^3 = 10^7$. The product is $6 \times 10^7$.', 'checked', '{"lint":[],"solve":{"answer":"$6 \\times 10^{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 x 2) x 10^(4+3) = 6 x 10^7, already in scientific notation.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d84171de-31de-4d2a-a981-3eaaf3ff6c94', 'NC26.8.ANFR.5', 3, 'numeric', 'Combine exponent properties', 'What is the value of $\frac{(3^2)^3}{3^4}$?', '[]', '9', '(3^2)^3/3^4', 'A power of a power multiplies the exponents: $(3^2)^3 = 3^6$. Dividing powers of the same base subtracts the exponents: $\frac{3^6}{3^4} = 3^2 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3^2)^3 = 3^6; 3^6 / 3^4 = 3^2 = 9.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66d0979f-d561-4ada-a9be-4903ea6c822b', 'NC26.8.ANFR.5', 3, 'numeric', 'Divide numbers in scientific notation in a problem', 'A signal travels $3 \times 10^8$ meters each second. How many seconds does it take to travel $6 \times 10^{10}$ meters?', '[]', '200', '(6*10^10)/(3*10^8)', 'Time = distance $\div$ speed $= \frac{6 \times 10^{10}}{3 \times 10^8}$. Divide the numbers in front: $6 \div 3 = 2$. Subtract the exponents: $10^{10} \div 10^8 = 10^2$. So the time is $2 \times 10^2 = 200$ seconds.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Time = (6 x 10^10)/(3 x 10^8) = 2 x 10^2 = 200 seconds.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebd71b1e-3255-4cba-8674-1b4f01690b33', 'NC26.8.ANFR.5', 3, 'choice', 'Multiply powers with the same base', 'Which expression is equal to $5^{-2} \times 5^{6}$?', '["$5^{-12}$","$5^{8}$","$5^{4}$","$5^{3}$"]', '$5^{4}$', NULL, 'Add the exponents, including the negative one: $-2 + 6 = 4$, so the product is $5^4$.', 'checked', '{"lint":[],"solve":{"answer":"$5^{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^(-2+6) = 5^4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b3e6bc7-e0e3-40ce-af99-deef2698bdc8', 'NC26.8.ANFR.5', 3, 'numeric', 'Multiply powers with the same base', '$3^a \times 3^{2a} = 3^{12}$. What is the value of $a$?', '[]', '4', '12/3', 'Adding the exponents gives $a + 2a = 3a$, so $3a = 12$ and $a = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^(a + 2a) = 3^(3a) = 3^12, so 3a = 12, a = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('683b5300-19ec-43ae-9df9-693b8442db23', 'NC26.8.ANFR.5', 3, 'choice', 'Divide powers with the same base', 'Which expression is NOT equal to $\frac{2^{10}}{2^4}$?', '["$2^{6}$","$64$","$2^3 \\times 2^3$","$2^{14}$"]', '$2^{14}$', NULL, '$\frac{2^{10}}{2^4} = 2^6 = 64$, and $2^3 \times 2^3 = 2^6$ too. Only $2^{14}$ is different (that is what you get by adding the exponents).', 'checked', '{"lint":[],"solve":{"answer":"$2^{14}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^10 / 2^4 = 2^6 = 64 = 2^3 x 2^3. 2^14 is not equal.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46ab7c1b-af32-4779-91ea-0184f70feb67', 'NC26.8.ANFR.5', 3, 'numeric', 'Divide powers with the same base', 'Simplify $\frac{2^3}{2^8}$ and write the result as a fraction in simplest form.', '[]', '1/32', '2^3/2^8', '$\frac{2^3}{2^8} = 2^{-5} = \frac{1}{2^5} = \frac{1}{32}$.', 'checked', '{"lint":[],"solve":{"answer":"1/32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^(3-8) = 2^-5 = 1/32 (check 8/256 = 1/32).","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('931ebdad-c857-4b68-a57f-45f2f7fa02f1', 'NC26.8.ANFR.5', 3, 'choice', 'Raise a power to a power', 'Which expression is equal to $(4a^3)^2$?', '["$8a^{6}$","$16a^{6}$","$16a^{5}$","$4a^{6}$"]', '$16a^{6}$', NULL, 'Square each factor: $4^2 = 16$ and $(a^3)^2 = a^6$. So $(4a^3)^2 = 16a^6$.', 'checked', '{"lint":[],"solve":{"answer":"$16a^{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4a^3)^2 = 4^2 x (a^3)^2 = 16a^6.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
