INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('136039bf-6189-4b03-b821-d4adf8f13f60', 'NC26.8.ANFR.5', 3, 'choice', 'Use zero and negative exponents', 'Which value is the greatest?', '["$2^{-1}$","$2^{0}$","$2^{-3}$","$\\left(\\frac{1}{2}\\right)^{-1}$"]', '$\left(\frac{1}{2}\right)^{-1}$', NULL, '$2^{-1} = \frac{1}{2}$, $2^0 = 1$, $2^{-3} = \frac{1}{8}$ and $\left(\frac{1}{2}\right)^{-1} = 2$. The greatest is 2.', 'checked', '{"lint":[],"solve":{"answer":"$\\left(\\frac{1}{2}\\right)^{-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^-3 = 1/8; (1/2)^-1 = 2; 2^-1 = 1/2; 2^0 = 1. Greatest is (1/2)^-1 = 2.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0013c9-49a8-47da-93df-3afeea0fe792', 'NC26.8.ANFR.5', 3, 'numeric', 'Use zero and negative exponents', 'Add $2^{-2} + 2^{-1}$. Write the sum as a fraction.', '[]', '3/4', '2^-2+2^-1', '$2^{-2} = \frac{1}{4}$ and $2^{-1} = \frac{1}{2} = \frac{2}{4}$. The sum is $\frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"3/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^-2 + 2^-1 = 1/4 + 1/2 = 1/4 + 2/4 = 3/4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cc473b89-77c4-4fc1-8560-3dde98df6f53', 'NC26.8.ANFR.5', 3, 'numeric', 'Combine exponent properties', 'Find the value of $\frac{5^{-2} \times 5^{6}}{5^{2}}$.', '[]', '25', '5^-2*5^6/5^2', 'Add the exponents on top: $-2 + 6 = 4$, so the top is $5^4$. Then $\frac{5^4}{5^2} = 5^2 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5^(-2+6-2) = 5^2 = 25.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a600e345-64ed-4822-8499-d4ca1be00edf', 'NC26.8.ANFR.5', 3, 'choice', 'Combine exponent properties', 'Simplify $\frac{(a^3)^4}{a^5 \cdot a^2}$. Which power of $a$ is the result?', '["$a^{0}$","$a^{19}$","$a^{-5}$","$a^{5}$"]', '$a^{5}$', NULL, 'The top is $(a^3)^4 = a^{12}$. The bottom is $a^5 \cdot a^2 = a^7$. Then $\frac{a^{12}}{a^7} = a^5$.', 'checked', '{"lint":[],"solve":{"answer":"$a^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a^3)^4 = a^12; a^5 x a^2 = a^7; a^(12-7) = a^5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bd90c54-490a-4550-9af3-ee66d5977476', 'NC26.8.ANFR.5', 3, 'numeric', 'Combine exponent properties', 'Rewrite $4^2$ as a power of 2, then find $\frac{2^{4} \times 4^{2}}{2^{3}}$.', '[]', '32', '2^4*4^2/2^3', 'Write $4 = 2^2$, so $4^2 = 2^4$. The top is $2^4 \times 2^4 = 2^8$. Then $\frac{2^8}{2^3} = 2^5 = 32$. (Check: $16 \times 16 \div 8 = 32$.)', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^2 = (2^2)^2 = 2^4. (2^4 x 2^4) / 2^3 = 2^(8-3) = 2^5 = 32. Check: 16 x 16 / 8 = 32.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3107be63-1aec-4d83-9ceb-2aedcd64b0b6', 'NC26.8.ANFR.5', 3, 'choice', 'Combine exponent properties', 'Which choice equals $\left(\frac{2^{3}}{2^{-1}}\right)^{2}$?', '["$2^{2}$","$2^{4}$","$2^{8}$","$2^{6}$"]', '$2^{8}$', NULL, 'Inside the brackets: $\frac{2^3}{2^{-1}} = 2^{3-(-1)} = 2^4$. Then $(2^4)^2 = 2^8$.', 'checked', '{"lint":[],"solve":{"answer":"$2^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^3 / 2^-1 = 2^(3-(-1)) = 2^4; (2^4)^2 = 2^8.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55d1d7d6-cbf7-4f16-bc61-6a136355ca0e', 'NC26.8.ANFR.5', 3, 'numeric', 'Evaluate a square root or cube root', 'What is the value of $\sqrt{64} \times \sqrt[3]{125} - \sqrt{25}$?', '[]', '35', '8*5-5', '$\sqrt{64} = 8$, $\sqrt[3]{125} = 5$ and $\sqrt{25} = 5$. So $8 \times 5 - 5 = 40 - 5 = 35$.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(64) = 8, cube root of 125 = 5, sqrt(25) = 5. 8 x 5 - 5 = 40 - 5 = 35.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('11413a6c-c347-410c-a5a9-38e5bfb97b32', 'NC26.8.ANFR.5', 3, 'choice', 'Evaluate a square root or cube root', 'Which choice equals $\sqrt[3]{\frac{8}{125}}$?', '["$\\frac{2}{5}$","$\\frac{2}{125}$","$\\frac{8}{5}$","$\\frac{4}{25}$"]', '$\frac{2}{5}$', NULL, 'Take the cube root of the top and of the bottom: $\sqrt[3]{8} = 2$ and $\sqrt[3]{125} = 5$, so the value is $\frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cube root of 8/125 = (cube root 8)/(cube root 125) = 2/5. Check (2/5)^3 = 8/125.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1437ae5e-3999-4edb-9c69-5429ec9f4c4e', 'NC26.8.ANFR.5', 3, 'numeric', 'Solve x squared or x cubed equals a number', 'The equation $x^2 + 5 = 86$ has two solutions. What is the positive one?', '[]', '9', NULL, 'Subtract 5: $x^2 = 81$. The positive solution is $x = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = 86 - 5 = 81, x = +/-9. Positive one: 9.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
