VALUES ('bdf5fa19-7828-473d-9596-890cee0e5141', 'NC26.8.ANFR.5', 3, 'numeric', 'Solve x squared or x cubed equals a number', 'Solve $2x^3 = 250$. What is $x$?', '[]', '5', NULL, 'Divide by 2: $x^3 = 125$. Then $x = \sqrt[3]{125} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^3 = 125, x = 5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
