VALUES ('72213b64-2b43-4ae7-bccf-8e69d98a1ff2', 'NC26.8.ANFR.5', 3, 'choice', 'Solve x squared or x cubed equals a number', 'Solve $3x^2 = 75$.', '["$x = 5$ only","$x = 5$ or $x = -5$","$x = 25$ or $x = -25$","$x = 5$ or $x = 25$"]', '$x = 5$ or $x = -5$', NULL, 'Divide by 3: $x^2 = 25$. Then $x = 5$ or $x = -5$.', 'checked', '{"lint":[],"solve":{"answer":"$x = 5$ or $x = -5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = 75/3 = 25, x = 5 or -5.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
