INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5efd2754-6539-4c94-af9e-6c1f0695f6ee', 'NC26.8.ANFR.5', 3, 'numeric', 'Solve x squared or x cubed equals a number', 'A number $n$ satisfies $n^3 = 8^2$. What is $n$?', '[]', '4', NULL, '$8^2 = 64$, so $n^3 = 64$ and $n = \sqrt[3]{64} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8^2 = 64; n^3 = 64, n = 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
