INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('22bcdce1-74ed-42fd-a59f-4e063d52a401', 'NC26.8.ANFR.5', 3, 'numeric', 'Use square and cube roots in a measurement problem', 'A cube has a surface area of 150 square inches. What is its volume, in cubic inches?', '[]', '125', '5^3', 'A cube has 6 equal faces, so one face has area $150 \div 6 = 25$ square inches. Each edge is $\sqrt{25} = 5$ inches, and the volume is $5^3 = 125$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 faces: 6s^2 = 150, s^2 = 25, s = 5. Volume = 5^3 = 125.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
