INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13e7c20e-1d56-4c8c-8e0a-bfe851804231', 'NC26.8.ANFR.5', 3, 'numeric', 'Use square and cube roots in a measurement problem', 'A square room has a floor area of 81 square feet. Edging costs 6 dollars for each foot and goes along all four walls. What is the total cost of the edging, in dollars?', '[]', '216', '4*9*6', 'Each wall is $\sqrt{81} = 9$ feet long, so the edging is $4 \times 9 = 36$ feet. At 6 dollars a foot it costs $36 \times 6 = 216$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"216","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"side = sqrt(81) = 9 ft; perimeter = 36 ft; cost = 36 x 6 = 216 dollars.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cd0671d0-888a-4950-a0d1-a16ce06e92e7', 'NC26.8.ANFR.5', 3, 'choice', 'Use square and cube roots in a measurement problem', 'A cube has a volume of 8 cubic inches. A second cube has edges twice as long. What is the volume of the second cube, in cubic inches?', '["64","16","32","24"]', '64', '(2*2)^3', 'The first cube has edge $\sqrt[3]{8} = 2$ inches. The second has edge $2 \times 2 = 4$ inches, so its volume is $4^3 = 64$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"64","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Edge = cube root of 8 = 2 in. New edge 4 in, volume 4^3 = 64.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('107c5fc7-6ea0-4fc5-9426-e68de6687bcb', 'NC26.8.ANFR.5', 3, 'numeric', 'Convert between scientific notation and standard form', 'How many zeros are between the decimal point and the first nonzero digit when $4.7 \times 10^{-6}$ is written as a decimal?', '[]', '5', NULL, '$4.7 \times 10^{-6} = 0.0000047$. There are 5 zeros after the decimal point before the 4.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4.7 x 10^-6 = 0.0000047. Digits after the point: 0 0 0 0 0 4 7, so 5 zeros before the 4.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4a96191-0b57-45d0-8352-e1d089709d6a', 'NC26.8.ANFR.5', 3, 'choice', 'Convert between scientific notation and standard form', 'Which number is NOT equal to $3.2 \times 10^{4}$?', '["$32{,}000$","$32 \\times 10^{3}$","$320 \\times 10^{2}$","$3200$"]', '$3200$', NULL, '$3.2 \times 10^4 = 32{,}000$. Also $32 \times 10^3 = 32{,}000$ and $320 \times 10^2 = 32{,}000$. Only $3200$ is different.', 'checked', '{"lint":[],"solve":{"answer":"$3200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3.2 x 10^4 = 32,000. 32 x 10^3 = 32,000; 320 x 10^2 = 32,000; 3200 is not equal.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28bf107b-f8d8-467b-9301-c107678878fa', 'NC26.8.ANFR.5', 3, 'choice', 'Compare numbers in scientific notation', 'Which statement is true?', '["$7.2 \\times 10^{5}$ is less than $6.8 \\times 10^{6}$","$2.5 \\times 10^{-4}$ is greater than $1.9 \\times 10^{-3}$","$9 \\times 10^{4}$ is greater than $1 \\times 10^{5}$","$3 \\times 10^{-2}$ is less than $9 \\times 10^{-3}$"]', '$7.2 \times 10^{5}$ is less than $6.8 \times 10^{6}$', NULL, '$7.2 \times 10^5 = 720{,}000$ and $6.8 \times 10^6 = 6{,}800{,}000$, so the first is less. In the others: $0.00025 < 0.0019$, $90{,}000 < 100{,}000$ and $0.03 > 0.009$, so each of those statements is false.', 'checked', '{"lint":[],"solve":{"answer":"$7.2 \\times 10^{5}$ is less than $6.8 \\times 10^{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"720,000 < 6,800,000: true. 0.03 < 0.009: false. 0.00025 > 0.0019: false. 90,000 > 100,000: false.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b71dc61-f434-4367-85eb-ae5699b50c58', 'NC26.8.ANFR.5', 3, 'numeric', 'Compare numbers in scientific notation', 'A planet is $1.5 \times 10^{8}$ kilometers from its sun. One of its moons is $3 \times 10^{5}$ kilometers from the planet. How many times as far is the planet from its sun as the moon is from the planet?', '[]', '500', '1.5*10^8/(3*10^5)', 'Divide: $\frac{1.5 \times 10^8}{3 \times 10^5} = 0.5 \times 10^3 = 500$.', 'checked', '{"lint":[],"solve":{"answer":"500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1.5 x 10^8)/(3 x 10^5) = 0.5 x 10^3 = 500.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e069598-2747-44ac-8175-136c00e78ba2', 'NC26.8.ANFR.5', 3, 'choice', 'Compute with numbers in scientific notation', 'A factory fills $6 \times 10^{4}$ boxes, and each box holds $5 \times 10^{3}$ marbles. Which choice shows the total number of marbles in scientific notation?', '["$3 \\times 10^{7}$","$3 \\times 10^{12}$","$1.1 \\times 10^{8}$","$3 \\times 10^{8}$"]', '$3 \times 10^{8}$', NULL, 'Multiply the numbers: $6 \times 5 = 30$. Add the exponents: $4 + 3 = 7$. So the product is $30 \times 10^7$, which is $3 \times 10^8$ in scientific notation.', 'checked', '{"lint":[],"solve":{"answer":"$3 \\times 10^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6 x 5) x 10^(4+3) = 30 x 10^7 = 3 x 10^8.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab40a063-4a49-4068-88d8-b00dda9ae37a', 'NC26.8.ANFR.5', 3, 'numeric', 'Compute with numbers in scientific notation', 'Multiply $3 \times 10^{-2}$ by $4 \times 10^{5}$ and write the product as a whole number.', '[]', '12000', '3*10^-2*4*10^5', 'Multiply the numbers: $3 \times 4 = 12$. Add the exponents: $-2 + 5 = 3$. So the product is $12 \times 10^3 = 12{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"12000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 x 4) x 10^(-2+5) = 12 x 10^3 = 12,000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00668dd1-f136-48e9-87bf-5eb8311cf08d', 'NC26.8.ANFR.5', 3, 'numeric', 'Compute with numbers in scientific notation', 'One building holds $4 \times 10^{5}$ books and another holds $3 \times 10^{4}$ books. How many books are in the two buildings together?', '[]', '430000', '4*10^5+3*10^4', '$4 \times 10^5 = 400{,}000$ and $3 \times 10^4 = 30{,}000$. The sum is $430{,}000$.', 'checked', '{"lint":[],"solve":{"answer":"430000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"400,000 + 30,000 = 430,000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
