INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12054cb2-dfea-4352-b4cc-5a433aa357cd', 'NC26.8.ANFR.5', 3, 'numeric', 'Compute with numbers in scientific notation', 'A printer prints $2.4 \times 10^{6}$ pages in $8 \times 10^{2}$ minutes. How many pages does it print each minute?', '[]', '3000', '2.4*10^6/(8*10^2)', 'Divide: $\frac{2.4 \times 10^6}{8 \times 10^2} = 0.3 \times 10^4 = 3000$ pages each minute.', 'checked', '{"lint":[],"solve":{"answer":"3000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2.4/8) x 10^(6-2) = 0.3 x 10^4 = 3000.","run_id":"claude-code","at":"2026-10-17T20:26:58.606Z"}}', 'ai', NULL, NULL)
