INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93e258a8-e7e6-4b81-84cc-5dc8eb3d649d', 'NC26.8.SGMR.1', 1, 'choice', 'Translate a point', 'A drone starts at (-2, 3) and flies 6 units up and 2 units to the right. Where is the drone now?', '["(4, 5)","(-4, 9)","(0, 9)","(0, -3)"]', '(0, 9)', NULL, 'Right 2 adds 2 to $x$: $-2 + 2 = 0$. Up 6 adds 6 to $y$: $3 + 6 = 9$. The drone is at (0, 9).', 'checked', '{"lint":[],"solve":{"answer":"(0, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2, 3): right 2 gives x = 0; up 6 gives y = 9. New point (0, 9).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
