INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2ed9573-4f62-4ef9-869f-bfc739f59bd3', 'NC26.8.SGMR.1', 1, 'numeric', 'Properties kept by rigid transformations', 'A triangle has angles of $35^\circ$ and $85^\circ$. It is rotated $90^\circ$ about the origin. What is the measure of the third angle of the image, in degrees?', '[]', '60', '180-35-85', 'The angles of a triangle add to $180^\circ$, and a rotation keeps every angle. The third angle is $180 - 35 - 85 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"The rotation plays no role; this mostly tests the triangle angle sum. Fine but weakly aligned.","work":"Third angle = 180 - 35 - 85 = 60; rotation keeps angles, so 60.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94bed62a-a10f-4f58-88ab-59fa5174320e', 'NC26.8.SGMR.1', 1, 'choice', 'Read and write coordinate rules', 'Which rule describes a reflection across the $y$-axis?', '["$(x, y) \\to (-x, y)$","$(x, y) \\to (x, -y)$","$(x, y) \\to (-x, -y)$","$(x, y) \\to (y, x)$"]', '$(x, y) \to (-x, y)$', NULL, 'A reflection across the $y$-axis changes the sign of $x$ and keeps $y$. The rule is $(x, y) \to (-x, y)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x, y) \\to (-x, y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis: x negated, y kept: (-x, y).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7c59b14-6f35-403b-8b26-727ca6a188cb', 'NC26.8.SGMR.1', 1, 'choice', 'Read and write coordinate rules', 'A transformation follows the rule $(x, y) \to (x, -y)$. Which of these describes it?', '["A reflection across the $y$-axis","A rotation of $90^\\circ$ counterclockwise about the origin","A translation of 1 unit down","A reflection across the $x$-axis"]', 'A reflection across the $x$-axis', NULL, 'The $x$-coordinate stays the same and the $y$-coordinate changes sign. That is a reflection across the $x$-axis.', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $x$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, -y): x kept, y negated = reflection across x-axis.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d812996-fbc2-407b-9e57-86739c015f1a', 'NC26.8.SGMR.1', 1, 'numeric', 'Work backwards from the image', 'After a point is moved 3 units to the right, it is at (7, 2). What was its $x$-coordinate before the move?', '[]', '4', '7-3', 'Undo the move: 3 units to the left of $x = 7$ is $7 - 3 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 3 back: 7 - 3 = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d10ee45-9a58-4fa4-9ff8-1326e6b2e4b8', 'NC26.8.SGMR.1', 1, 'numeric', 'Find a missing value from a transformation', 'The point $(k, 4)$ is reflected across the $y$-axis. Its image is $(-6, 4)$. What is the value of $k$?', '[]', '6', '6', 'A reflection across the $y$-axis changes the sign of the $x$-coordinate. The image has $x = -6$, so the original had $x = 6$. Therefore $k = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(k, 4) -> (-k, 4) = (-6, 4), so k = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45eefdbd-03e7-4893-9b08-492f1ef6a558', 'NC26.8.SGMR.1', 1, 'choice', 'Properties kept by rigid transformations', 'A triangle is turned $90^\circ$ about the origin. Which statement is true about the new triangle compared with the original triangle?', '["Every side keeps its length, but the angles become larger","Every vertex keeps the same coordinates as before","Every angle keeps its size, but the sides become longer","Every side keeps its length and every angle keeps its size"]', 'Every side keeps its length and every angle keeps its size', NULL, 'A turn is a rigid transformation, so it moves the figure without changing its size or shape. The sides and the angles stay the same. The vertices move to new places, so their coordinates change.', 'checked', '{"lint":[],"solve":{"answer":"Every side keeps its length and every angle keeps its size","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rotation is a rigid motion: lengths and angles preserved (coordinates change).","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28936f7b-f356-4219-8273-b2bd48d38dd2', 'NC26.8.SGMR.1', 2, 'choice', 'Rotate a point 90 degrees about the origin', 'Point P is at (3, 1). It is rotated $90^\circ$ counterclockwise about the origin. What are the coordinates of its image?', '["(-1, 3)","(1, -3)","(-3, -1)","(1, 3)"]', '(-1, 3)', NULL, 'A $90^\circ$ counterclockwise rotation about the origin takes $(x, y)$ to $(-y, x)$. So (3, 1) goes to (-1, 3).', 'checked', '{"lint":[],"solve":{"answer":"(-1, 3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 degrees counterclockwise about origin: (x, y) -> (-y, x). (3, 1) -> (-1, 3).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d00d06b-93a9-4a17-928f-d06c9d760e00', 'NC26.8.SGMR.1', 2, 'choice', 'Combine a translation and a reflection', 'Point Q is at (1, 2). It is first moved 4 units to the left and 1 unit up, and then reflected across the $x$-axis. What are the coordinates of its final image?', '["(-3, 3)","(3, 3)","(5, -3)","(-3, -3)"]', '(-3, -3)', NULL, 'Moving 4 left and 1 up takes (1, 2) to (-3, 3). Reflecting across the $x$-axis changes the sign of the $y$-coordinate, giving (-3, -3).', 'checked', '{"lint":[],"solve":{"answer":"(-3, -3)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1, 2) -> (1 - 4, 2 + 1) = (-3, 3). Reflect across x-axis: (-3, -3).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4038bd36-8532-4f2a-b98a-483db4a68d9a', 'NC26.8.SGMR.1', 2, 'choice', 'Name the transformation that maps a triangle onto its image', 'Triangle ABC has vertices A(2, 3), B(5, 3) and C(2, 7). Its image has vertices A''(2, -3), B''(5, -3) and C''(2, -7). Which transformation moved the triangle?', '["A reflection across the $y$-axis","A reflection across the $x$-axis","A translation 6 units down","A rotation of $90^\\circ$ clockwise about the origin"]', 'A reflection across the $x$-axis', NULL, 'Every vertex keeps its $x$-coordinate and has the sign of its $y$-coordinate changed, which is a reflection across the $x$-axis. A translation 6 units down would take C(2, 7) to (2, 1), not (2, -7).', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $x$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each (x, y) -> (x, -y): reflection across the x-axis. Translation 6 down would send C(2,7) to (2,1), not (2,-7). Rotation 90 cw sends A to (3,-2). y-axis reflection changes x.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c956930-7cce-44b8-b5bb-36a83fd2119d', 'NC26.8.SGMR.1', 2, 'choice', 'Translate a point', 'Point Q is at (-5, 2). It is translated 9 units to the right and 6 units down. What are the coordinates of its image?', '["(-14, -4)","(4, 8)","(1, -7)","(4, -4)"]', '(4, -4)', NULL, 'Right 9 gives $x = -5 + 9 = 4$. Down 6 gives $y = 2 - 6 = -4$. The image is (4, -4).', 'checked', '{"lint":[],"solve":{"answer":"(4, -4)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right 9: -5 + 9 = 4. Down 6: 2 - 6 = -4. Image (4, -4).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2303a48-e299-4851-a21b-4c230c19c918', 'NC26.8.SGMR.1', 2, 'choice', 'Combine two translations', 'Point D is at (1, 1). It is translated 4 units to the right and 3 units up, and then translated 6 units to the left and 5 units up. Where is D now?', '["(11, 9)","(-1, 9)","(-5, 6)","(-1, -1)"]', '(-1, 9)', NULL, 'Add up the moves. Horizontally: $+4$ then $-6$ gives $-2$, so $x = 1 - 2 = -1$. Vertically: $+3$ then $+5$ gives $+8$, so $y = 1 + 8 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"(-1, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,1) -> (1+4, 1+3) = (5, 4) -> (5-6, 4+5) = (-1, 9).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d1b5239-c56a-4134-a77d-0448f00b7046', 'NC26.8.SGMR.1', 2, 'numeric', 'Combine two translations', 'A robot starts at (3, -4). It moves 9 units up and 2 units left. Then it moves 3 units down and 8 units right. What is the $y$-coordinate of its final position?', '[]', '2', '-4+9-3', 'Only the up and down moves change $y$: $-4 + 9 - 3 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,-4): up 9, left 2 -> (1, 5); down 3, right 8 -> (9, 2). y = 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
