INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('19083be2-f2a0-4f49-b775-8de30d46fb25', 'NC26.8.SGMR.1', 2, 'choice', 'Translate a polygon', 'Parallelogram PQRS has vertices P(-2, 1), Q(2, 1), R(4, 4) and S(0, 4). It is translated 3 units to the left and 2 units down. Which point is the image of R?', '["(7, 2)","(1, 6)","(1, 2)","(7, 6)"]', '(1, 2)', NULL, 'R is at (4, 4). Left 3 gives $x = 4 - 3 = 1$. Down 2 gives $y = 4 - 2 = 2$. So R'' is (1, 2).', 'checked', '{"lint":[],"solve":{"answer":"(1, 2)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R(4, 4) -> (4-3, 4-2) = (1, 2).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
