INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74eecb47-06bd-48bc-9b9c-ccbd67d88b59', 'NC26.8.SGMR.1', 2, 'choice', 'Properties kept by rigid transformations', 'A triangle is translated. Which statement about the image is true?', '["The side lengths stay the same, but the angles change.","Each side is parallel to the matching side of the original and has the same length.","The angles stay the same, but the side lengths change.","The perimeter grows by the number of units the triangle moved."]', 'Each side is parallel to the matching side of the original and has the same length.', NULL, 'A translation slides every point the same distance in the same direction. Each side stays parallel to where it was, and all lengths and angles are kept.', 'checked', '{"lint":[],"solve":{"answer":"Each side is parallel to the matching side of the original and has the same length.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A translation moves every point the same way, so each image side is a parallel copy of the original side with the same length; angles and perimeter unchanged. Others are false.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74b0555e-33c4-48eb-9181-6afa6083190f', 'NC26.8.SGMR.1', 2, 'choice', 'Find the image after two transformations', 'The point (3, 2) is reflected across the $y$-axis and then translated 5 units up. Where is the final image?', '["(-3, 7)","(3, 7)","(-3, -3)","(-3, 2)"]', '(-3, 7)', NULL, 'Reflecting across the $y$-axis gives (-3, 2). Moving 5 units up gives (-3, 7).', 'checked', '{"lint":[],"solve":{"answer":"(-3, 7)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3, 2) -> across y-axis (-3, 2) -> up 5 (-3, 7).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a7f85696-cdff-47ac-b25a-c96b2ac1bba8', 'NC26.8.SGMR.1', 2, 'numeric', 'Find the image after two transformations', 'The point (-4, 6) is translated 2 units to the right and 8 units down. It is then reflected across the $x$-axis. What is the $y$-coordinate of the final image?', '[]', '2', '-(6-8)', 'The translation gives (-2, -2). Reflecting across the $x$-axis changes the sign of $y$: (-2, 2). The $y$-coordinate is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-4, 6) -> (-2, -2) -> across x-axis (-2, 2). y = 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
