INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8855241-80ac-41b4-bc74-c65367a83feb', 'NC26.8.SGMR.1', 2, 'choice', 'Find the image after two transformations', 'The point (1, -3) is rotated $90^\circ$ counterclockwise about the origin and then reflected across the $y$-axis. What are the coordinates of the final image?', '["(3, 1)","(3, -1)","(-3, -1)","(-3, 1)"]', '(-3, 1)', NULL, 'The rotation uses $(x, y) \to (-y, x)$ and gives (3, 1). The reflection across the $y$-axis changes the sign of $x$ and gives (-3, 1).', 'checked', '{"lint":[],"solve":{"answer":"(-3, 1)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1, -3) -> 90 CCW (-y, x) = (3, 1) -> across y-axis (-3, 1).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
