INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a83d5f67-d76b-44f0-803c-29b411897af3', 'NC26.8.SGMR.1', 2, 'choice', 'Describe a sequence of two transformations', 'Triangle PQR has vertices P(1, 1), Q(4, 1) and R(1, 3). Its image has vertices P''(4, 1), Q''(1, 1) and R''(4, 3). Which sequence of transformations maps PQR onto P''Q''R''?', '["A translation of 5 units to the right, then a reflection across the $y$-axis","A reflection across the $x$-axis, then a translation of 5 units to the right","A reflection across the $y$-axis, then a translation of 5 units to the right","A rotation of $90^\\circ$ counterclockwise about the origin, then a translation of 5 units to the right"]', 'A reflection across the $y$-axis, then a translation of 5 units to the right', NULL, 'Reflect across the $y$-axis first: (-1, 1), (-4, 1), (-1, 3). Then move 5 units right: (4, 1), (1, 1), (4, 3). Doing the translation first would give a different result.', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $y$-axis, then a translation of 5 units to the right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis then 5 right: P(1,1)->(-1,1)->(4,1); Q(4,1)->(-4,1)->(1,1); R(1,3)->(-1,3)->(4,3). Matches. Option A gives P -> (-6,1); B gives P -> (6,-1); D gives Q -> (-1,4)->(4,4), no.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b05e0a4-6903-4e7b-a47c-3e3518f8f489', 'NC26.8.SGMR.1', 2, 'choice', 'Describe a sequence of two transformations', 'A triangle with vertices (2, 0), (5, 0) and (2, 2) is moved in two steps and ends up with vertices (0, -2), (0, 1), (-2, -2). Which pair of steps, in this order, does that?', '["A rotation of $90^\\circ$ counterclockwise about the origin, then a translation of 4 units down","A rotation of $90^\\circ$ clockwise about the origin, then a translation of 4 units down","A translation of 4 units down, then a rotation of $90^\\circ$ counterclockwise about the origin","A reflection across the $y$-axis, then a translation of 4 units down"]', 'A rotation of $90^\circ$ counterclockwise about the origin, then a translation of 4 units down', NULL, 'Rotate $90^\circ$ counterclockwise with $(x, y) \to (-y, x)$: (0, 2), (0, 5), (-2, 2). Then move 4 units down: (0, -2), (0, 1), (-2, -2).', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ counterclockwise about the origin, then a translation of 4 units down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 CCW (-y, x): (2,0)->(0,2), (5,0)->(0,5), (2,2)->(-2,2); 4 down: (0,-2), (0,1), (-2,-2). Matches. 90 CW first gives (0,-2)->(0,-6); translating first then CCW gives (4,2)...; reflecting gives (-2,-4).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42d283c0-46dd-41b3-86b1-3208f76c09a9', 'NC26.8.SGMR.1', 2, 'choice', 'Read and write coordinate rules', 'Which rule describes a rotation of $90^\circ$ counterclockwise about the origin?', '["$(x, y) \\to (y, -x)$","$(x, y) \\to (-y, x)$","$(x, y) \\to (-x, -y)$","$(x, y) \\to (-y, -x)$"]', '$(x, y) \to (-y, x)$', NULL, 'Test the point (1, 0). A counterclockwise quarter turn takes it to (0, 1). Only $(x, y) \to (-y, x)$ does that.', 'checked', '{"lint":[],"solve":{"answer":"$(x, y) \\to (-y, x)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1, 0) goes to (0, 1) under 90 CCW; (-y, x) does that. Rule (-y, x).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('70c1a9b9-d332-4bc2-9c60-7555970d7e03', 'NC26.8.SGMR.1', 2, 'numeric', 'Read and write coordinate rules', 'A rotation follows the rule $(x, y) \to (y, -x)$. What is the sum of the coordinates of the image of (-3, 8)?', '[]', '11', '8+3', 'Replace $x = -3$ and $y = 8$: $(y, -x) = (8, 3)$. The sum is $8 + 3 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(y, -x) on (-3, 8) = (8, 3). Sum 11.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
