INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e401d5bd-95c9-4251-8ba5-358b7422bd9e', 'NC26.8.SGMR.1', 2, 'choice', 'Work backwards from the image', 'After being reflected across the $x$-axis, a point is at (-4, -9). Where was the point before the reflection?', '["(-4, 9)","(4, -9)","(4, 9)","(-4, -9)"]', '(-4, 9)', NULL, 'Reflecting again across the $x$-axis undoes the reflection: (-4, -9) goes back to (-4, 9).', 'checked', '{"lint":[],"solve":{"answer":"(-4, 9)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect (-4, -9) back across x-axis: (-4, 9). Check: (-4, 9) -> (-4, -9).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
