INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7922f63-0e28-4930-a0a2-480225fd9619', 'NC26.8.SGMR.1', 2, 'numeric', 'Work backwards from the image', 'A point is rotated $90^\circ$ counterclockwise about the origin. Its image is (-3, -8). What was the $x$-coordinate of the original point?', '[]', '-8', '-8', 'The rotation sends $(x, y)$ to $(-y, x)$. So the image''s $y$-coordinate, -8, is the original $x$, and the image''s $x$-coordinate, -3, is $-y$, so $y = 3$. The original point is (-8, 3).', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"CCW: (x, y) -> (-y, x) = (-3, -8), so x = -8 (and y = 3). Check: (-8, 3) -> (-3, -8).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('690ec3e7-e2c9-452b-a723-5d6979f26018', 'NC26.8.SGMR.1', 2, 'numeric', 'Find a missing value from a transformation', 'A point at (-2, 5) is translated $a$ units to the right and $b$ units down. It ends at (4, -1). What is the value of $a + b$?', '[]', '12', '(4-(-2))+(5-(-1))', 'Horizontally, $-2 + a = 4$, so $a = 6$. Vertically, $5 - b = -1$, so $b = 6$. Then $a + b = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2 + a = 4 so a = 6; 5 - b = -1 so b = 6. a + b = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aff3ed8f-afe3-438b-b71b-e6f9084a4b3c', 'NC26.8.SGMR.1', 3, 'numeric', 'Combine a rotation and a translation', 'Point R is at (-2, 6). It is rotated $90^\circ$ clockwise about the origin and then moved 3 units to the left. What is the $x$-coordinate of its final image?', '[]', '3', '6-3', 'A $90^\circ$ clockwise rotation about the origin takes $(x, y)$ to $(y, -x)$, so (-2, 6) goes to (6, 2). Moving 3 units left subtracts 3 from $x$: (3, 2). The $x$-coordinate is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 degrees clockwise: (x, y) -> (y, -x). (-2, 6) -> (6, 2). Left 3: (3, 2). x-coordinate 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('959de84a-8848-4c94-900f-07e128803bda', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image of a vertex from a given translation', 'A triangle has vertices (1, 1), (4, 1) and (1, 5). It is translated so that the vertex (4, 1) moves to (-2, 6). What is the $y$-coordinate of the image of the vertex (1, 5)?', '[]', '10', '5+(6-1)', 'The vertex (4, 1) moves to (-2, 6), which is 6 units left and 5 units up. Every point moves the same way, so (1, 5) moves to (-5, 10). Its $y$-coordinate is 10.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translation vector: (-2 - 4, 6 - 1) = (-6, 5). (1, 5) -> (-5, 10). y-coordinate 10.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e0d1f98-14cb-444b-9414-e3adc8974983', 'NC26.8.SGMR.1', 3, 'choice', 'Describe a sequence of two transformations', 'Triangle ABC has vertices A(1, 2), B(3, 2) and C(1, 5). Its image has vertices A''(-1, -2), B''(-3, -2) and C''(-1, -5). Which sequence of transformations maps the triangle onto its image?', '["A reflection across the $x$-axis, then a translation 2 units left","A reflection across the $y$-axis only","A reflection across the $x$-axis, then a reflection across the $y$-axis","A rotation of $90^\\circ$ clockwise about the origin"]', 'A reflection across the $x$-axis, then a reflection across the $y$-axis', NULL, 'Reflecting across the $x$-axis takes A(1, 2) to (1, -2), B to (3, -2) and C to (1, -5). Reflecting that across the $y$-axis gives (-1, -2), (-3, -2) and (-1, -5), which match the image. The translation option works for A but takes B to (1, -2), not (-3, -2).', 'checked', '{"lint":[],"solve":{"answer":"A reflection across the $x$-axis, then a reflection across the $y$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Map is (x, y) -> (-x, -y). Reflect over x-axis (x,-y) then y-axis (-x,-y): matches all three. Rotation 90 cw: A -> (2,-1), no. x-reflection then 2 left: B(3,2) -> (1,-2), not (-3,-2). y-reflection only: A -> (-1,2), no.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd2e3c91-38f2-4ee2-9368-3f28f731a73a', 'NC26.8.SGMR.1', 3, 'choice', 'Combine two translations', 'Two translations are applied one after the other. The first moves a figure 5 units to the right and 2 units down. The second moves it 9 units to the left and 6 units down. Which single translation has the same effect?', '["A translation of 4 units to the right and 8 units down","A translation of 14 units to the left and 8 units down","A translation of 4 units to the left and 8 units down","A translation of 4 units to the left and 4 units down"]', 'A translation of 4 units to the left and 8 units down', NULL, 'Horizontally: $+5$ and $-9$ combine to $-4$ (4 units left). Vertically: $-2$ and $-6$ combine to $-8$ (8 units down).', 'checked', '{"lint":[],"solve":{"answer":"A translation of 4 units to the left and 8 units down","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal: +5 - 9 = -4 (4 left). Vertical: -2 - 6 = -8 (8 down). Single translation 4 left, 8 down.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3247d5-88c2-424c-a101-56d47d4b8d7e', 'NC26.8.SGMR.1', 3, 'numeric', 'Combine two translations', 'A point at (3, -2) is translated 2 units left and 6 units up. It is then translated 5 units left and some number of units up, and it ends at (-4, 9). How many units up was the second translation?', '[]', '5', '9-(-2+6)', 'After the first translation the point is at (1, 4). The second translation moves it 5 left, to $x = -4$ (this matches), and up to $y = 9$. That is $9 - 4 = 5$ units up.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,-2) -> (1, 4). Then 5 left: x = 1 - 5 = -4 (matches). y: 4 + u = 9, so u = 5.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
