INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('453573a2-6eaa-446d-9583-e06b6a9f9a20', 'NC26.8.SGMR.1', 3, 'numeric', 'Find the image after two transformations', 'A triangle has vertices (1, 1), (4, 1) and (1, 3). It is reflected across the $y$-axis and then translated 6 units to the right. What is the sum of the $x$-coordinates of the three vertices of the final image?', '[]', '12', '(-1+6)+(-4+6)+(-1+6)', 'The reflection gives (-1, 1), (-4, 1), (-1, 3). Moving 6 units right gives (5, 1), (2, 1), (5, 3). The $x$-coordinates 5, 2, 5 add to 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis x-values: -1, -4, -1; then +6: 5, 2, 5. Sum 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36e69808-d711-4310-a1e9-6d716abaf884', 'NC26.8.SGMR.1', 3, 'choice', 'Describe a sequence of two transformations', 'After two transformations, the triangle with corners (2, 1), (5, 1) and (2, 4) lands on the triangle with corners (-1, 1), (2, 1), (-1, -2). Which description of the two transformations is correct?', '["A reflection across the $x$-axis, then a translation of 3 units to the left and 2 units down","A translation of 3 units to the left and 2 units up, then a reflection across the $x$-axis","A translation of 3 units to the left and 2 units down, then a reflection across the $y$-axis","A translation of 3 units to the left and 2 units down, then a reflection across the $x$-axis"]', 'A translation of 3 units to the left and 2 units down, then a reflection across the $x$-axis', NULL, 'Translate 3 units to the left and 2 units down: (-1, -1), (2, -1), (-1, 2). Then reflect across the $x$-axis: (-1, 1), (2, 1), (-1, -2).', 'checked', '{"lint":[],"solve":{"answer":"A translation of 3 units to the left and 2 units down, then a reflection across the $x$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3, -2) then across x-axis: (2,1)->(-1,-1)->(-1,1); (5,1)->(2,-1)->(2,1); (2,4)->(-1,2)->(-1,-2). Matches. Others: A gives (1,-1); B gives (-1,-3); C gives (-1,-3).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f24f0beb-9c6e-4c81-97b6-ef5ed9604eb9', 'NC26.8.SGMR.1', 3, 'choice', 'Describe a sequence of two transformations', 'Triangle JKL has vertices J(1, 2), K(3, 2) and L(1, 5). Two transformations are applied one after the other, and the final triangle has vertices (-2, -1), (-2, -3), (-5, -1). Which of these was applied?', '["A rotation of $90^\\circ$ counterclockwise about the origin, then a reflection across the $y$-axis","A rotation of $90^\\circ$ clockwise about the origin, then a reflection across the $y$-axis","A reflection across the $y$-axis, then a rotation of $90^\\circ$ clockwise about the origin","A rotation of $90^\\circ$ clockwise about the origin, then a reflection across the $x$-axis"]', 'A rotation of $90^\circ$ clockwise about the origin, then a reflection across the $y$-axis', NULL, 'Rotate $90^\circ$ clockwise with $(x, y) \to (y, -x)$: (2, -1), (2, -3), (5, -1). Then reflect across the $y$-axis: (-2, -1), (-2, -3), (-5, -1).', 'checked', '{"lint":[],"solve":{"answer":"A rotation of $90^\\circ$ clockwise about the origin, then a reflection across the $y$-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 CW (y, -x) then across y-axis: J(1,2)->(2,-1)->(-2,-1); K(3,2)->(2,-3)->(-2,-3); L(1,5)->(5,-1)->(-5,-1). Matches. B gives (2,1); C gives (2,1); D gives J->(-1,2)->(2,1). None match.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d86f0111-8657-4c60-9623-b68424585ba4', 'NC26.8.SGMR.1', 3, 'numeric', 'Describe a sequence of two transformations', 'The point (2, 5) is reflected across the $y$-axis and then translated. Its final position is (-7, 1). The translation moved it some units to the left and some units down. What is the total of those two numbers of units?', '[]', '9', '(-2-(-7))+(5-1)', 'The reflection gives (-2, 5). To reach (-7, 1), the point moves $-2 - (-7) = 5$ units left and $5 - 1 = 4$ units down. The total is $5 + 4 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2, 5) -> across y-axis (-2, 5). To (-7, 1): 5 left and 4 down. Total 9.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
