INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6f22e27-dc79-4563-85cc-0dd2ed7120f4', 'NC26.8.SGMR.1', 3, 'choice', 'Describe a sequence of two transformations', 'The triangle with vertices (1, 1), (4, 1) and (1, 3) is sent through two transformations, one after the other. The final image has vertices (-4, 3), (-4, 6), (-6, 3). Which sequence did this?', '["A rotation of $90^\\circ$ counterclockwise about the origin, then a translation of 2 units to the right and 3 units up","A translation of 3 units to the right and 2 units up, then a rotation of $90^\\circ$ counterclockwise about the origin","A translation of 2 units to the right and 3 units up, then a rotation of $90^\\circ$ counterclockwise about the origin","A translation of 2 units to the right and 3 units up, then a rotation of $90^\\circ$ clockwise about the origin"]', 'A translation of 2 units to the right and 3 units up, then a rotation of $90^\circ$ counterclockwise about the origin', NULL, 'Translate 2 units to the right and 3 units up: (3, 4), (6, 4), (3, 6). Then rotate $90^\circ$ counterclockwise with $(x, y) \to (-y, x)$: (-4, 3), (-4, 6), (-6, 3).', 'checked', '{"lint":[],"solve":{"answer":"A translation of 2 units to the right and 3 units up, then a rotation of $90^\\circ$ counterclockwise about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translate (+2, +3): (3,4), (6,4), (3,6); 90 CCW (-y, x): (-4,3), (-4,6), (-6,3). Matches. B gives (1,4)...; C gives (4,-3)...; D gives (-3,4)...","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
