INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('402a4090-d177-4e2d-9295-10cb5e27b4c2', 'NC26.8.SGMR.1', 3, 'choice', 'Read and write coordinate rules', 'A reflection across the $y$-axis is followed by a translation of 3 units to the right. Which rule describes the two steps together?', '["$(x, y) \\to (-x - 3, y)$","$(x, y) \\to (x + 3, -y)$","$(x, y) \\to (-x + 3, y)$","$(x, y) \\to (-x + 3, -y)$"]', '$(x, y) \to (-x + 3, y)$', NULL, 'The reflection sends $(x, y)$ to $(-x, y)$. Moving 3 units right adds 3 to the $x$-coordinate: $(-x + 3, y)$.', 'checked', '{"lint":[],"solve":{"answer":"$(x, y) \\to (-x + 3, y)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Across y-axis: (-x, y); then 3 right: (-x + 3, y).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5d8803d-a986-49f7-8be3-14aec8c6a365', 'NC26.8.SGMR.1', 3, 'numeric', 'Read and write coordinate rules', 'A transformation follows the rule $(x, y) \to (x + 4, -y)$. What is the sum of the coordinates of the image of (-1, 6)?', '[]', '-3', '(-1+4)+(-6)', 'Replace $x = -1$ and $y = 6$: $(x + 4, -y) = (3, -6)$. The sum is $3 + (-6) = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-1, 6) -> (-1 + 4, -6) = (3, -6). Sum -3.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6f648458-d7f5-45b0-8865-aa3a076701a6', 'NC26.8.SGMR.1', 3, 'numeric', 'Work backwards from the image', 'A point is translated 5 units to the left and 2 units up, and then reflected across the $y$-axis. It ends at (3, 1). What was the $x$-coordinate of the original point?', '[]', '2', '-3+5', 'Work backwards. Before the reflection the point was (-3, 1). Before the translation it was 5 units to the right and 2 units down from there: (2, -1). The original $x$-coordinate is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) -> (x - 5, y + 2) -> (-(x - 5), y + 2) = (3, 1). So 5 - x = 3, x = 2. Check: (2, -1) -> (-3, 1) -> (3, 1).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('034d3e13-f524-48b2-8768-6b6278b026fc', 'NC26.8.SGMR.1', 3, 'choice', 'Work backwards from the image', 'A point is rotated $90^\circ$ clockwise about the origin and then moved 3 units down. It ends at (-2, -5). What was the original point?', '["(-2, 2)","(5, -2)","(8, -2)","(2, -2)"]', '(2, -2)', NULL, 'Undo the move: up 3 from (-2, -5) gives (-2, -2). That is the point after rotating, so rotate back $90^\circ$ counterclockwise with $(x, y) \to (-y, x)$: (2, -2). Check: rotating (2, -2) clockwise gives (-2, -2), and moving 3 down gives (-2, -5).', 'checked', '{"lint":[],"solve":{"answer":"(2, -2)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo 3 down: (-2, -2). CW (y, -x) = (-2, -2): y = -2, x = 2. Original (2, -2). Check: (2,-2) -> (-2,-2) -> (-2,-5).","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('553782a8-96c5-42ef-a6fe-3dd3358fc1d8', 'NC26.8.SGMR.1', 3, 'numeric', 'Work backwards from the image', 'Triangle ABC was reflected across the $x$-axis and then translated 6 units to the left and 1 unit down. The image of vertex B is at (-2, -4). What was the $y$-coordinate of B before the changes?', '[]', '3', '-(-4+1)', 'Undo the translation: move 6 right and 1 up from (-2, -4) to get (4, -3). Undo the reflection by changing the sign of $y$: (4, 3). The original $y$-coordinate is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B(x, y) -> (x, -y) -> (x - 6, -y - 1) = (-2, -4). -y - 1 = -4, y = 3.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1431be4a-a058-4b4c-99c7-b27c862f61df', 'NC26.8.SGMR.1', 3, 'choice', 'Why the order of two transformations matters', 'Maya reflects the point (4, 2) across the $y$-axis and then translates it 6 units to the right. Jon starts with the same point, first translates it 6 units to the right, and then reflects it across the $y$-axis. Which statement is true?', '["Both points end at (2, 2).","Maya''s point ends at (2, 2) and Jon''s point ends at (-10, 2).","Maya''s point ends at (-10, 2) and Jon''s point ends at (2, 2).","Both points end at (-10, 2)."]', 'Maya''s point ends at (2, 2) and Jon''s point ends at (-10, 2).', NULL, 'Maya: reflecting gives (-4, 2), then moving 6 right gives (2, 2). Jon: moving 6 right gives (10, 2), then reflecting gives (-10, 2). The order changes the result.', 'checked', '{"lint":[],"solve":{"answer":"Maya''s point ends at (2, 2) and Jon''s point ends at (-10, 2).","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Maya: (4,2) -> (-4,2) -> (2,2). Jon: (4,2) -> (10,2) -> (-10,2). Different results.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b3677a2-62db-42b7-b47f-a8baed750177', 'NC26.8.SGMR.1', 3, 'numeric', 'Why the order of two transformations matters', 'The point (5, 1) goes through two steps in two different orders. Order 1: rotate $90^\circ$ counterclockwise about the origin, then translate 3 units to the left and 3 units up. Order 2: translate 3 units to the left and 3 units up, then rotate $90^\circ$ counterclockwise about the origin. How many units apart are the two final points?', '[]', '6', '8-2', 'Order 1: the rotation gives (-1, 5), then the translation gives (-4, 8). Order 2: the translation gives (2, 4), then the rotation gives (-4, 2). The points share $x = -4$ and differ in $y$ by $8 - 2 = 6$ units.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Order 1: (5,1) -> CCW (-1,5) -> (-4,8). Order 2: (5,1) -> (2,4) -> CCW (-4,2). Same x, distance 8 - 2 = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f40c14-d6fe-47e2-8244-7f458fab3efd', 'NC26.8.SGMR.1', 3, 'numeric', 'Find a missing value from a transformation', 'A translation follows the rule $(x, y) \to (x + a, y - 2a)$. It moves the point (3, 5) to the point (7, -3). What is the value of $a$?', '[]', '4', '7-3', 'Look at the $x$-coordinate: $3 + a = 7$, so $a = 4$. Check the $y$-coordinate: $5 - 2(4) = -3$. It matches.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + a = 7 gives a = 4; check 5 - 2(4) = -3. a = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.358Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a51b780a-32ea-4843-9b48-0a786495689d', 'NC26.8.SGMR.2', 1, 'choice', 'Dilate a point about the origin', 'Point A is at (3, 4). It is dilated about the origin with a scale factor of 2. What are the coordinates of its image?', '["(5, 6)","(6, 8)","(1.5, 2)","(6, 4)"]', '(6, 8)', NULL, 'A dilation about the origin with scale factor $k$ takes $(x, y)$ to $(kx, ky)$. With $k = 2$, (3, 4) goes to (6, 8).', 'checked', '{"lint":[],"solve":{"answer":"(6, 8)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiply both coordinates by 2: (6, 8).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e532b6d-33cd-49e0-b580-66e3aac685c0', 'NC26.8.SGMR.2', 1, 'numeric', 'Find a scale factor from two lengths', 'A dilation changes a segment of length 4 centimeters into a segment of length 12 centimeters. What is the scale factor?', '[]', '3', '12/4', 'The scale factor is the new length divided by the old length: $12 \div 4 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor = 12/4 = 3.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
