INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('200ba8e0-aee8-469e-be7c-b7444412643a', 'NC26.8.SGMR.2', 1, 'numeric', 'Dilate a polygon about the origin', 'A rectangle has corners at (0, 0), (2, 0), (2, 3) and (0, 3). It is dilated about the origin with a scale factor of 4. What is the $y$-coordinate of the image of the corner (2, 3)?', '[]', '12', '3*4', 'The corner (2, 3) goes to $(2 \times 4, 3 \times 4) = (8, 12)$. The $y$-coordinate is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2, 3) * 4 = (8, 12). y = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
