INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b41b165-4b08-4a8b-8fa0-31c4be2e052f', 'NC26.8.SGMR.2', 1, 'choice', 'Tell an enlargement from a reduction', 'A dilation has a scale factor of $\frac{2}{5}$. What does this dilation do to a figure?', '["It makes the figure larger.","It leaves the figure the same size.","It turns the figure without changing its size.","It makes the figure smaller."]', 'It makes the figure smaller.', NULL, 'A scale factor between 0 and 1 shrinks a figure. $\frac{2}{5}$ is less than 1, so the image is smaller.', 'checked', '{"lint":[],"solve":{"answer":"It makes the figure smaller.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0 < 2/5 < 1, so the figure shrinks.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88fc89ab-a49f-4e8a-af1c-ba04e50e4d27', 'NC26.8.SGMR.2', 1, 'choice', 'Tell an enlargement from a reduction', 'Which scale factor makes a figure larger?', '["0.6","1.2","1/4","1"]', '1.2', '1.2', 'A scale factor greater than 1 makes a figure larger. Of the choices, only 1.2 is greater than 1. A scale factor of 1 leaves the size the same, and the others shrink it.', 'checked', '{"lint":[],"solve":{"answer":"1.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A factor greater than 1 enlarges: 1.2. (0.6 and 1/4 shrink; 1 keeps size.)","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cee4326a-c872-488c-aeb0-b22096198e31', 'NC26.8.SGMR.2', 1, 'numeric', 'Tell an enlargement from a reduction', 'A dilation has a scale factor of 1. A segment is 7 units long. How long is its image, in units?', '[]', '7', '7*1', 'A scale factor of 1 leaves every length the same, so the image is $7 \times 1 = 7$ units long.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 1 leaves lengths unchanged: 7.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c191b56-ab12-4a5d-9540-ae986dd5c12d', 'NC26.8.SGMR.2', 1, 'choice', 'What a dilation keeps and what it changes', 'Sides AB and DC of a quadrilateral are parallel. The quadrilateral is dilated with a scale factor of 3. Which statement about the image sides A''B'' and D''C'' is true?', '["A''B'' and D''C'' are perpendicular.","A''B'' and D''C'' meet at a point.","A''B'' and D''C'' are parallel only if the scale factor is 1.","A''B'' and D''C'' are parallel."]', 'A''B'' and D''C'' are parallel.', NULL, 'A dilation keeps angles, so parallel lines stay parallel, whatever the scale factor is.', 'checked', '{"lint":[],"solve":{"answer":"A''B'' and D''C'' are parallel.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilations take lines to parallel lines, so parallel sides stay parallel for any scale factor.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b209e15d-4c9c-4c82-a426-2e279ef0f0c6', 'NC26.8.SGMR.2', 1, 'choice', 'What a dilation keeps and what it changes', 'A triangle is dilated with a scale factor of 2. Which of these is the same in the triangle and its image?', '["The length of each side","The measure of each angle","The perimeter","The area"]', 'The measure of each angle', NULL, 'A dilation changes lengths, so the sides, the perimeter and the area all change. The angle measures stay the same.', 'checked', '{"lint":[],"solve":{"answer":"The measure of each angle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dilation keeps angle measures; perimeter doubles, sides double, area quadruples.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
