INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76f7847b-e540-4b70-99d5-b3667a88d1d8', 'NC26.8.SGMR.2', 1, 'choice', 'What a dilation keeps and what it changes', 'A triangle is dilated about the origin with a scale factor of 3. Which statement about the image is true?', '["Its side lengths and its angle measures are both 3 times as great.","Its side lengths are unchanged, and its angle measures are 3 times as great.","Its side lengths are 3 times as long, and its angle measures are unchanged.","Its side lengths are 3 units longer, and its angle measures are unchanged."]', 'Its side lengths are 3 times as long, and its angle measures are unchanged.', NULL, 'A dilation multiplies every length by the scale factor but keeps every angle the same size.', 'checked', '{"lint":[],"solve":{"answer":"Its side lengths are 3 times as long, and its angle measures are unchanged.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lengths multiply by 3, angles unchanged.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ddeb2b1-70b0-44c1-b7f6-9616bdcb8bb4', 'NC26.8.SGMR.2', 1, 'numeric', 'Perimeter of a dilated figure', 'A triangle has a perimeter of 14 inches. It is dilated with a scale factor of 3. What is the perimeter of the image, in inches?', '[]', '42', '14*3', 'Every side is multiplied by 3, so the perimeter is too: $14 \times 3 = 42$ inches.', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perimeter scales by 3: 14 * 3 = 42.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
