INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec36228f-cf7a-4b83-920b-b313285f79c6', 'NC26.8.SGMR.2', 1, 'numeric', 'Find an unknown side using the scale factor', 'A rectangle is 4 cm wide and 7 cm long. It is dilated with a scale factor of 2. How long is the longer side of the image, in centimeters?', '[]', '14', '7*2', 'Every length doubles. The long side becomes $7 \times 2 = 14$ cm.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Longer side 7 * 2 = 14.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
