INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('484056ef-9b44-4816-88fe-425f83292ae0', 'NC26.8.SGMR.2', 1, 'numeric', 'Dilation from a center', 'Point P is 4 cm from the center of a dilation. The scale factor is 3. How far from the center is the image of P, in centimeters?', '[]', '12', '4*3', 'A dilation multiplies every distance from the center by the scale factor: $4 \times 3 = 12$ cm.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance scales: 4 * 3 = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
