INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('888e641e-f40e-45c4-b4c3-5f67db0c155f', 'NC26.8.SGMR.2', 1, 'choice', 'Dilation from a center', 'Point O is the center of a dilation, and A is another point. The dilation takes A to A''. Which statement is true?', '["A'' is always the same distance from O as A is.","Line OA'' is always perpendicular to line OA.","O, A and A'' lie on one straight line.","A'' is always exactly halfway between O and A."]', 'O, A and A'' lie on one straight line.', NULL, 'A dilation moves each point along the ray from the center through that point, closer or farther depending on the scale factor. So the center, the point and its image are always in a line.', 'checked', '{"lint":[],"solve":{"answer":"O, A and A'' lie on one straight line.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A dilation sends A along ray OA, so O, A, A'' are collinear. Distance changes unless k = 1; halfway only if k = 1/2; never perpendicular.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42d21629-4610-4aae-8ff6-abe91cdc9e95', 'NC26.8.SGMR.2', 1, 'numeric', 'Dilation from a center', 'A point is 10 cm from the center of a dilation. The scale factor is $\frac{1}{2}$. How far from the center is its image, in centimeters?', '[]', '5', '10/2', 'Multiply the distance by the scale factor: $10 \times \frac{1}{2} = 5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10 * 1/2 = 5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
