INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c62e96ba-ad36-41cd-b882-131bfed773a7', 'NC26.8.SGMR.2', 2, 'numeric', 'Dilate a point by a scale factor less than 1', 'The point (-8, 20) is dilated about the origin with a scale factor of $\frac{3}{4}$. What is the sum of the coordinates of the image?', '[]', '9', '3/4*(-8)+3/4*20', 'The image is $\left(-8 \times \frac{3}{4}, 20 \times \frac{3}{4}\right) = (-6, 15)$. The sum is $-6 + 15 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-8, 20) * 3/4 = (-6, 15). Sum 9.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
