INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73c41909-b712-40b4-a568-7327b2cb1dc3', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate a point by a scale factor less than 1', 'Point D is at (9, -12). It is dilated about the origin with a scale factor of $\frac{2}{3}$. What are the coordinates of the image of D?', '["(3, -4)","(6, -8)","(13.5, -18)","(6, -12)"]', '(6, -8)', NULL, 'Multiply each coordinate by $\frac{2}{3}$: $9 \times \frac{2}{3} = 6$ and $-12 \times \frac{2}{3} = -8$. The image is (6, -8).', 'checked', '{"lint":[],"solve":{"answer":"(6, -8)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9, -12) * 2/3 = (6, -8).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
