INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f22777e-6877-4dbd-a179-d2e20548bd74', 'NC26.8.SGMR.2', 2, 'numeric', 'Dilate a polygon about the origin', 'A rectangle has vertices (-6, 3), (6, 3), (6, -9) and (-6, -9). It is dilated about the origin with a scale factor of $\frac{1}{3}$. What is the sum of the coordinates of the image of the vertex (6, -9)?', '[]', '-1', '(6-9)/3', 'The vertex (6, -9) goes to $\left(6 \times \frac{1}{3}, -9 \times \frac{1}{3}\right) = (2, -3)$. The sum is $2 + (-3) = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6, -9) * 1/3 = (2, -3). Sum -1.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
