INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('945e133d-033b-48da-8a28-6f9a9a7c16af', 'NC26.8.SGMR.2', 2, 'choice', 'Tell an enlargement from a reduction', 'One triangle is dilated with a scale factor of 0.8. A second triangle is dilated with a scale factor of 1.25. Which statement is true?', '["Both images are larger than their originals.","Both images are smaller than their originals.","The first image is smaller than its original and the second image is larger than its original.","The first image is larger than its original and the second image is smaller than its original."]', 'The first image is smaller than its original and the second image is larger than its original.', NULL, 'A scale factor below 1 (0.8) shrinks a figure. A scale factor above 1 (1.25) enlarges it.', 'checked', '{"lint":[],"solve":{"answer":"The first image is smaller than its original and the second image is larger than its original.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8 < 1 shrinks, 1.25 > 1 enlarges.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4df774d4-650a-4ad6-806f-bc7a5c77bd39', 'NC26.8.SGMR.2', 2, 'numeric', 'What a dilation keeps and what it changes', 'Triangle ABC has angles $A = 40^\circ$ and $B = 75^\circ$. It is dilated with a scale factor of $\frac{1}{2}$ to give triangle A''B''C''. What is the measure of angle C'', in degrees?', '[]', '65', '180-40-75', 'A dilation keeps angle measures, so angle C'' equals angle C. The angles of a triangle add to $180^\circ$: $180 - 40 - 75 = 65$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C = 180 - 40 - 75 = 65; dilation keeps angles, so C'' = 65.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2f976e1-5777-43a3-ba8f-5ce66b9a243a', 'NC26.8.SGMR.2', 2, 'choice', 'Perimeter of a dilated figure', 'A rectangle is 6 cm wide and 10 cm long. It is dilated with a scale factor of $\frac{1}{2}$. What is the perimeter of the image, in centimeters?', '["32","8","64","16"]', '16', '(6+10)*2*(1/2)', 'The image is 3 cm by 5 cm, so its perimeter is $2(3 + 5) = 16$ cm. (Or: the original perimeter is 32 cm, and half of 32 is 16.)', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image 3 by 5: perimeter 2(3 + 5) = 16. (Original 32, halved.)","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1039b35-e71c-4d6a-bb75-c0b06fa81d7e', 'NC26.8.SGMR.2', 2, 'choice', 'Perimeter of a dilated figure', 'A dilation takes triangle ABC, with a perimeter of 30 cm, to triangle A''B''C'', with a perimeter of 45 cm. Side AB is 8 cm long. How long is side A''B'', in centimeters?', '["23","12","15","16"]', '12', '8*45/30', 'The scale factor is $45 \div 30 = 1.5$. So A''B'' is $8 \times 1.5 = 12$ cm.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 45/30 = 1.5; A''B'' = 8 * 1.5 = 12.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd27de79-86ea-43c5-b9df-99b8f1f7eace', 'NC26.8.SGMR.2', 2, 'choice', 'Area of a dilated figure', 'A rectangle has vertices (0, 0), (3, 0), (3, 2) and (0, 2). It is dilated about the origin with a scale factor of 3. What is the area of the image, in square units?', '["18","27","54","6"]', '54', '(3*3)*(2*3)', 'The image has corners (0, 0), (9, 0), (9, 6) and (0, 6). Its area is $9 \times 6 = 54$ square units. (Tripling the sides makes the area 9 times as large, not 3 times.)', 'checked', '{"lint":[],"solve":{"answer":"54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image 9 by 6: area 54 (= 6 * 3^2).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c01a108-e700-498e-a4bf-1267b3919e8f', 'NC26.8.SGMR.2', 2, 'choice', 'Find an unknown side using the scale factor', 'In triangle ABC, AB = 6, BC = 9 and AC = 12. Triangle A''B''C'' is a dilation of ABC, and A''B'' = 8. What is the length of B''C''?', '["11","13.5","16","12"]', '12', '9*8/6', 'The scale factor is $8 \div 6 = \frac{4}{3}$. Then $B''C'' = 9 \times \frac{4}{3} = 12$. (Adding 2 to every side would not be a dilation.)', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 8/6 = 4/3; B''C'' = 9 * 4/3 = 12. (A''C'' = 16.)","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e9566ff-e329-4c6b-aff7-21d0d015c03a', 'NC26.8.SGMR.2', 2, 'numeric', 'Find an unknown side using the scale factor', 'A photo is 10 cm wide and 15 cm tall. It is dilated to make a poster whose width is 40 cm. How tall is the poster, in centimeters?', '[]', '60', '15*40/10', 'The scale factor is $40 \div 10 = 4$. The poster is $15 \times 4 = 60$ cm tall.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 40/10 = 4; height 15 * 4 = 60.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9ece0e2-7520-4ecf-9166-bc1c14f1add4', 'NC26.8.SGMR.2', 2, 'numeric', 'Find an unknown side using the scale factor', 'A triangle has sides of 5 cm, 12 cm and 13 cm. A dilation of it has two sides of 7.5 cm and 18 cm. How long is the third side of the image, in centimeters?', '[]', '19.5', '13*7.5/5', 'The scale factor is $7.5 \div 5 = 1.5$ (and $18 \div 12 = 1.5$). The third side is $13 \times 1.5 = 19.5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"19.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.5/5 = 1.5 and 18/12 = 1.5 (no other pairing gives a common factor). Third side 13 * 1.5 = 19.5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f70b933-1c95-4a5f-9cda-afcab8308900', 'NC26.8.SGMR.2', 2, 'choice', 'Dilation from a center', 'Point Q is 6 cm from the center of a dilation, and its image Q'' is 15 cm from the center on the same ray. What is the scale factor?', '["2.5","9","90","0.4"]', '2.5', '15/6', 'The scale factor is the new distance divided by the old distance: $15 \div 6 = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15/6 = 2.5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
