INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a21add6-8344-4ac2-b274-f636ecf07f6f', 'NC26.8.SGMR.2', 2, 'numeric', 'Dilation from a center', 'The center of a dilation is point O. Point R is 10 cm from O, and its image R'' is 4 cm from O. What is the scale factor? Give your answer as a fraction.', '[]', '2/5', '4/10', 'New distance divided by old distance: $4 \div 10 = \frac{2}{5}$.', 'checked', '{"lint":[],"solve":{"answer":"2/5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4/10 = 2/5.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
