INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50055532-e5cc-4e76-82a0-23169203aefe', 'NC26.8.SGMR.2', 2, 'choice', 'Dilate a segment', 'The segment with endpoints (2, 1) and (2, 7) is dilated about the origin with a scale factor of 4. How long is the image segment, in units?', '["6","28","10","24"]', '24', '(7-1)*4', 'The image has endpoints (8, 4) and (8, 28). Its length is $28 - 4 = 24$ units. (The original is 6 units long, and 6 times 4 is 24.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original length 7 - 1 = 6; image (8,4)-(8,28), length 24.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
