INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ebb25e8-7cd1-45c2-bb6c-a9828c16849d', 'NC26.8.SGMR.2', 3, 'choice', 'Describe a dilation', 'A dilation about the origin takes the point (6, 4) to the point (9, 6). Which description is correct?', '["An enlargement with a scale factor of $\\frac{3}{2}$","A reduction with a scale factor of $\\frac{2}{3}$","An enlargement with a scale factor of 3","A reduction with a scale factor of $\\frac{3}{2}$"]', 'An enlargement with a scale factor of $\frac{3}{2}$', NULL, 'The scale factor is $9 \div 6 = \frac{3}{2}$ (and $6 \div 4 = \frac{3}{2}$). It is greater than 1, so the figure gets larger: an enlargement.', 'checked', '{"lint":[],"solve":{"answer":"An enlargement with a scale factor of $\\frac{3}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9/6 = 6/4 = 3/2 > 1: enlargement, factor 3/2.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('91122b8d-5038-487b-be10-4fc1aa043e92', 'NC26.8.SGMR.2', 3, 'numeric', 'Work backwards to the original figure', 'A dilation about the origin takes triangle ABC to triangle A''B''C''. Vertex A is at (2, 4) and A'' is at (3, 6). Vertex B'' is at (9, 3). What is the $x$-coordinate of B?', '[]', '6', '9/(3/2)', 'The scale factor is $3 \div 2 = \frac{3}{2}$ (and $6 \div 4 = \frac{3}{2}$). To undo it, divide B'' by $\frac{3}{2}$: $9 \div \frac{3}{2} = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 3/2 = 6/4 = 1.5. B = B''/1.5 = (6, 2). x = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee1182a9-12d1-433a-b798-df595266b984', 'NC26.8.SGMR.2', 3, 'numeric', 'Work backwards to the original figure', 'A triangle was dilated with a scale factor of 2.5. The image has sides of 7.5 cm, 10 cm and 12.5 cm. What is the perimeter of the original triangle, in centimeters?', '[]', '12', '(7.5+10+12.5)/2.5', 'The image perimeter is $7.5 + 10 + 12.5 = 30$ cm. The original perimeter is $30 \div 2.5 = 12$ cm.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Image perimeter 30; original 30 / 2.5 = 12. (Sides 3, 4, 5.)","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fec200da-ecf8-4d6d-84ff-e36131f87920', 'NC26.8.SGMR.2', 3, 'choice', 'Dilate twice in a row', 'A segment is 12 cm long. It is dilated with a scale factor of $\frac{2}{3}$. The image is dilated with a scale factor of $\frac{3}{4}$. How long is the final segment, in centimeters?', '["6","8","9","12"]', '6', '12*2/3*3/4', 'After the first dilation: $12 \times \frac{2}{3} = 8$ cm. After the second: $8 \times \frac{3}{4} = 6$ cm.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 * 2/3 = 8; 8 * 3/4 = 6.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fde318ec-b5c6-4e66-abfc-8c3939d9aada', 'NC26.8.SGMR.2', 3, 'choice', 'Dilate twice in a row', 'A triangle is dilated about the origin with a scale factor of 4. The image is then dilated about the origin with a scale factor of $\frac{1}{2}$. Which single dilation gives the same result?', '["A scale factor of 4.5","A scale factor of 8","A scale factor of $\\frac{1}{8}$","A scale factor of 2"]', 'A scale factor of 2', NULL, 'The scale factors multiply: $4 \times \frac{1}{2} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"A scale factor of 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 * 1/2 = 2.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ff83e9f-ccca-475c-94f6-3c06e7881818', 'NC26.8.SGMR.2', 3, 'numeric', 'Dilate twice in a row', 'A triangle has an area of 10 square units. It is dilated with a scale factor of 2, and the image is dilated with a scale factor of 3. What is the area of the final triangle, in square units?', '[]', '360', '10*(2*3)^2', 'The two scale factors multiply to $2 \times 3 = 6$. Area is multiplied by the square of the scale factor: $10 \times 6^2 = 360$ square units.', 'checked', '{"lint":[],"solve":{"answer":"360","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total factor 2 * 3 = 6; area scales by 36: 10 * 36 = 360.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0fa49cc5-d2eb-47e2-81b6-91448db2ee74', 'NC26.8.SGMR.2', 3, 'choice', 'Recognize a dilation', 'Triangle ABC has vertices A(1, 2), B(3, 2) and C(1, 5). Which set of points could be the vertices of its image after a dilation about the origin?', '["(2, 4), (6, 4), (2, 5)","(2, 2), (6, 2), (2, 5)","(3, 4), (5, 4), (3, 7)","(2, 4), (6, 4), (2, 10)"]', '(2, 4), (6, 4), (2, 10)', NULL, 'A dilation multiplies every coordinate by the same number. Only (2, 4), (6, 4), (2, 10) comes from multiplying all the coordinates by 2. The others multiply only some coordinates or add instead of multiply.', 'checked', '{"lint":[],"solve":{"answer":"(2, 4), (6, 4), (2, 10)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1,2),(3,2),(1,5) times 2 = (2,4),(6,4),(2,10). Others: A and B scale x and y differently; C is a translation by (2,2).","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97f78d40-bc95-45b4-9dc4-402f467f758b', 'NC26.8.SGMR.2', 3, 'numeric', 'Find a missing value in a dilation', 'A dilation about the origin takes the point $(6, m)$ to the point $(15, 10)$. What is the value of $m$?', '[]', '4', '10/(15/6)', 'The scale factor is $15 \div 6 = 2.5$. Then $m \times 2.5 = 10$, so $m = 10 \div 2.5 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 15/6 = 2.5; m = 10/2.5 = 4.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bccec2fd-ecc2-4d4e-95ae-d348f2870f33', 'NC26.8.SGMR.2', 3, 'numeric', 'Find a missing value in a dilation', 'A dilation about the origin takes (4, -6) to (10, -15). The same dilation takes (6, $h$) to (15, 20). What is the value of $h$?', '[]', '8', '20/(10/4)', 'The scale factor is $10 \div 4 = 2.5$ (and $15 \div 6 = 2.5$). Then $h \times 2.5 = 20$, so $h = 20 \div 2.5 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scale factor 10/4 = -15/-6 = 2.5. 6 * 2.5 = 15 checks; h = 20 / 2.5 = 8.","run_id":"claude-code","at":"2026-10-17T20:28:40.399Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5f6508d0-6a39-47c4-95a1-305f948c1a52', 'NC26.8.SGMR.2', 3, 'numeric', 'Find a missing value in a dilation', 'A right triangle has vertices $(0, 0)$, $(8, 0)$ and $(0, c)$, where $c$ is greater than 0. It is dilated about the origin with a scale factor of 3, and the image has an area of 108 square units. What is the value of $c$?', '[]', '3', '108/9/4', 'The image has vertices $(0, 0)$, $(24, 0)$ and $(0, 3c)$. Its area is $\frac{1}{2} \times 24 \times 3c = 36c$. Setting $36c = 108$ gives $c = 3$. Check: the original area is $\frac{1}{2} \times 8 \times 3 = 12$, and $12 \times 3^2 = 108$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Original area 8c/2=4c. Scale 3 multiplies area by 9: 36c=108, c=3.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dec18ce-a043-4363-9e5d-096cdee9f20f', 'NC26.8.SGMR.3', 1, 'choice', 'Use the side-length condition for a triangle', 'Which three lengths, in centimeters, can be the sides of a triangle?', '["3, 4, 8","2, 3, 5","4, 4, 9","5, 6, 10"]', '5, 6, 10', NULL, 'The two shorter sides must add up to more than the longest side. $5 + 6 = 11 > 10$ works. $3 + 4 = 7 < 8$, $2 + 3 = 5$ (equal, not more), and $4 + 4 = 8 < 9$ all fail.', 'checked', '{"lint":[],"solve":{"answer":"5, 6, 10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4=7 < 8 no; 2+3=5 = 5 no (flat); 4+4=8 < 9 no; 5+6=11 > 10 yes (and 5+10>6, 6+10>5).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aacc70fd-a01f-4757-a08f-edfa2349c019', 'NC26.8.SGMR.3', 1, 'numeric', 'Use the angle sum of a triangle', 'Two angles of a triangle measure $48^\circ$ and $75^\circ$. What is the measure of the third angle, in degrees?', '[]', '57', '180-48-75', 'The angles of a triangle add up to $180^\circ$. The first two add to $48 + 75 = 123$, so the third is $180 - 123 = 57$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"57","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 48 - 75 = 57.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a408a89a-d652-4335-927a-c82949b4bf94', 'NC26.8.SGMR.3', 1, 'choice', 'Tell which sets of three angles can form a triangle', 'Which three angle measures can be the angles of a triangle?', '["$35^\\circ, 55^\\circ, 80^\\circ$","$40^\\circ, 60^\\circ, 80^\\circ$","$50^\\circ, 60^\\circ, 80^\\circ$","$70^\\circ, 70^\\circ, 60^\\circ$"]', '$40^\circ, 60^\circ, 80^\circ$', NULL, 'The angles of a triangle must add to $180^\circ$. $40 + 60 + 80 = 180$ works. The other sets add to 170, 190 and 200.', 'checked', '{"lint":[],"solve":{"answer":"$40^\\circ, 60^\\circ, 80^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 200, 190, 180, 170. Only 40, 60, 80 sums to 180.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2293ecc-a154-4be3-8ac4-6c33ab15f2a5', 'NC26.8.SGMR.3', 1, 'choice', 'Side lengths: can they form a triangle?', 'A craft kit has straws of many lengths, in inches. Which three straws can be joined end to end to make a triangle?', '["4, 5, 6","3, 4, 7","2, 3, 7","1, 4, 6"]', '4, 5, 6', NULL, 'Two shorter sides must add to MORE than the longest side. $4 + 5 = 9$, which is more than 6, so 4, 5, 6 works. In 3, 4, 7 the sum is exactly 7, so the straws would lie flat. In 2, 3, 7 the sum is 5, and in 1, 4, 6 the sum is 5: too short.', 'checked', '{"lint":[],"solve":{"answer":"4, 5, 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle needs the two shorter sides to sum to more than the longest. 3+4=7 (not >7) no; 2+3=5<7 no; 4+5=9>6 yes; 1+4=5<6 no. Only 4, 5, 6.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40d19b63-15b0-4cf6-a50d-75b2c93c1056', 'NC26.8.SGMR.3', 1, 'numeric', 'Side lengths: can they form a triangle?', 'Three sets of side lengths, in centimeters, are listed. Set A: 2, 3, 4. Set B: 1, 1, 5. Set C: 5, 5, 5. How many of these sets can be the sides of a triangle?', '[]', '2', NULL, 'Set A: $2 + 3 = 5 > 4$, so it works. Set B: $1 + 1 = 2$, which is not more than 5, so it does not. Set C: $5 + 5 = 10 > 5$, so it works. Two sets work.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 2+3=5>4 yes. B: 1+1=2<5 no. C: 5+5=10>5 yes. Two sets.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37a0efb6-1baa-43c0-ad15-8de3df6c4ecf', 'NC26.8.SGMR.3', 1, 'choice', 'Side lengths: can they form a triangle?', 'Three of these sets of lengths, in centimeters, can be the sides of a triangle. Which set cannot?', '["6, 7, 8","2, 4, 7","5, 5, 9","4, 6, 9"]', '2, 4, 7', NULL, 'Check that the two shorter sides add to more than the longest. 6, 7, 8: $13 > 8$. 5, 5, 9: $10 > 9$. 4, 6, 9: $10 > 9$. 2, 4, 7: $2 + 4 = 6$, which is less than 7, so this set cannot be a triangle.', 'checked', '{"lint":[],"solve":{"answer":"2, 4, 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5+5=10>9 yes; 4+6=10>9 yes; 6+7=13>8 yes; 2+4=6<7 no. The set that cannot is 2, 4, 7.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b4e5096-d310-48aa-8739-a9b25179d006', 'NC26.8.SGMR.3', 1, 'choice', 'Side lengths: can they form a triangle?', 'A farmer wants a triangular pen. Which set of fence lengths, in meters, can be the three sides of the pen?', '["3, 4, 8","5, 5, 10","6, 8, 9","2, 9, 12"]', '6, 8, 9', NULL, '$6 + 8 = 14 > 9$, so 6, 8, 9 works. For 3, 4, 8 the two short sides add to 7, less than 8. For 5, 5, 10 they add to exactly 10, so the fence would be flat. For 2, 9, 12 they add to 11, less than 12.', 'checked', '{"lint":[],"solve":{"answer":"6, 8, 9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4=7<8 no; 2+9=11<12 no; 6+8=14>9 yes; 5+5=10, not >10 no. Only 6, 8, 9.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7a84381-19ab-4a12-8a9a-5971a420caa7', 'NC26.8.SGMR.3', 1, 'numeric', 'Side lengths: can they form a triangle?', 'Five sets of side lengths, in inches, are listed: 3, 3, 3; 2, 5, 9; 4, 4, 9; 6, 7, 12; 5, 5, 10. How many of the sets cannot be the sides of a triangle?', '[]', '3', NULL, '3, 3, 3: $6 > 3$ works. 2, 5, 9: $7 < 9$ fails. 4, 4, 9: $8 < 9$ fails. 6, 7, 12: $13 > 12$ works. 5, 5, 10: $10$ is not more than 10, so it fails. Three sets fail.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,3,3: 6>3 ok. 2,5,9: 7<9 cannot. 4,4,9: 8<9 cannot. 6,7,12: 13>12 ok. 5,5,10: 10=10 cannot. Three sets cannot.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2769243-16a1-49e8-8409-afc531fbc9dd', 'NC26.8.SGMR.3', 1, 'choice', 'Range of the third side', 'Two sticks are 3 cm and 4 cm long. A third stick will be added to make a triangle. Which length can the third stick be?', '["1","5","7","8"]', '5', NULL, 'The third side must be less than $3 + 4 = 7$ and more than $4 - 3 = 1$. Only 5 is between 1 and 7. A 1 cm or a 7 cm stick would make the sticks lie flat.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side must be between 4-3=1 and 4+3=7, strictly. 8 too long, 1 and 7 give flat figures. 5 works.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6782475-daed-444a-874c-4560f6cd4afa', 'NC26.8.SGMR.3', 1, 'numeric', 'Range of the third side', 'A triangular flag has two sides of 6 feet and 3 feet. The third side is a whole number of feet. What is the longest it can be, in feet?', '[]', '8', '6+3-1', 'The third side must be less than $6 + 3 = 9$. The greatest whole number less than 9 is 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side < 6+3 = 9 and > 6-3 = 3. Largest whole number below 9 is 8.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06181f5d-9a46-422c-bf36-7383bec92a25', 'NC26.8.SGMR.3', 1, 'numeric', 'Range of the third side', 'Two sides of a triangle are both 4 cm long. The third side is a whole number of centimeters. What is the shortest it can be, in centimeters?', '[]', '1', '4-4+1', 'The third side must be more than $4 - 4 = 0$. The least whole number more than 0 is 1. (A triangle with sides 4, 4 and 1 works, since $4 + 1 > 4$.)', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side > 4-4 = 0 and < 8. Smallest whole number is 1 (4,4,1: 5>4 ok).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a969673-d4cd-4a9b-a47f-7fd6c760e0f0', 'NC26.8.SGMR.3', 1, 'choice', 'Range of the third side', 'A triangle has two sides of 5 cm and 6 cm. Which length can NOT be the third side, in centimeters?', '["2","6","10","11"]', '11', NULL, 'The third side must be less than $5 + 6 = 11$ and more than $6 - 5 = 1$. So 2, 6 and 10 can all work, but 11 would make the sides lie flat.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side must satisfy 1 < x < 11. 2, 6, 10 all fit; 11 = 5+6 gives a flat figure. Cannot be 11.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4018f07-4dbb-4d37-aa26-7acebe8070aa', 'NC26.8.SGMR.3', 1, 'choice', 'Isosceles triangles and the side condition', 'An isosceles triangle has two equal sides of 5 cm. Which could be the length of the third side, in centimeters?', '["8","10","12","15"]', '8', NULL, 'The third side must be less than $5 + 5 = 10$. Only 8 is less than 10. A 10 cm side would make the two 5 cm sides lie flat along it.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side must be less than 5+5 = 10 (and more than 0). 10, 12, 15 fail; 8 works (5+5=10>8).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
