INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51208a4d-b76d-4fe3-97b4-b44e80e09240', 'NC26.8.SGMR.3', 1, 'numeric', 'Missing angle from the 180 degree sum', 'A triangle has one angle of $90^\circ$ and another of $35^\circ$. What is the measure of the third angle, in degrees?', '[]', '55', '180-90-35', 'The angles add to $180^\circ$: $180 - 90 - 35 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 90 - 35 = 55.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
