INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72ab66ee-b5ea-4b92-9678-b5ce3ee8fd35', 'NC26.8.SGMR.3', 1, 'numeric', 'Missing angle from the 180 degree sum', 'A triangular sail has corners of $45^\circ$ and $85^\circ$. How many degrees is the third corner?', '[]', '50', '180-45-85', '$45 + 85 = 130$ and $180 - 130 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 45 - 85 = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
