INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b038f655-2522-4bfa-ad60-1929cfb833fa', 'NC26.8.SGMR.3', 1, 'choice', 'Missing angle from the 180 degree sum', 'An isosceles triangle has two equal angles of $50^\circ$ each. What is the measure of the third angle, in degrees?', '["130","100","80","40"]', '80', '180-50-50', 'The two equal angles add to $50 + 50 = 100$, so the third angle is $180 - 100 = 80$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 50 - 50 = 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
