INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53e988c0-5014-4cb5-a268-712ec82e5183', 'NC26.8.SGMR.3', 1, 'numeric', 'Missing angle from the 180 degree sum', 'All three angles of an equilateral triangle have the same measure. What is the measure of one angle, in degrees?', '[]', '60', '180/3', 'The three equal angles add to $180^\circ$, so each is $180 \div 3 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 equal angles sum to 180, so each is 180/3 = 60.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
