INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe6f0bd8-38c2-46d7-958f-1a1812cb9f64', 'NC26.8.SGMR.3', 1, 'numeric', 'Angle sum with algebra or ratios', 'The angles of a triangle measure $x^\circ$, $x^\circ$ and $80^\circ$. What is the value of $x$?', '[]', '50', '(180-80)/2', 'The angles add to 180: $2x + 80 = 180$, so $2x = 100$ and $x = 50$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 80 = 180, 2x = 100, x = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
