INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4fdd002-8819-4414-a802-4b8d4ffc1914', 'NC26.8.SGMR.3', 1, 'choice', 'Which angle measures can form a triangle', 'A student measures the three corners of a triangular sign. Which set of measures, in degrees, could be correct?', '["60, 60, 60","40, 60, 70","50, 60, 80","30, 40, 100"]', '60, 60, 60', NULL, 'The three angles of a triangle add to 180. $60 + 60 + 60 = 180$. The other sets add to 170, 190 and 170.', 'checked', '{"lint":[],"solve":{"answer":"60, 60, 60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 30+40+100=170; 60+60+60=180; 40+60+70=170; 50+60+80=190. Only 60, 60, 60 sums to 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
