INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b96e7c-1957-40d3-b4b2-fbd2bc24913f', 'NC26.8.SGMR.3', 1, 'numeric', 'Which angle measures can form a triangle', 'Three sets of angle measures, in degrees, are listed: 40, 60, 80; 50, 50, 90; 30, 60, 90. How many of the sets could be the three angles of a triangle?', '[]', '2', NULL, 'Each set must add to 180. $40 + 60 + 80 = 180$ works. $50 + 50 + 90 = 190$ does not. $30 + 60 + 90 = 180$ works. Two sets work.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40+60+80=180 yes; 50+50+90=190 no; 30+60+90=180 yes. Two sets.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
