INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fa2f3cd-02e1-4b80-9c93-13cd979264d7', 'NC26.8.SGMR.3', 1, 'choice', 'Which angle measures can form a triangle', 'A triangle has a $90^\circ$ angle. Which could be the measure of another angle of this triangle, in degrees?', '["120","100","90","45"]', '45', NULL, 'The other two angles must add to $180 - 90 = 90$ degrees, so each is less than 90. Only 45 is less than 90.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The other two angles sum to 90, so each is between 0 and 90. 90, 100, 120 are too big; 45 works (45, 45, 90).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
