INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21e185d2-f880-42ba-9118-0a26f352c71a', 'NC26.8.SGMR.3', 1, 'numeric', 'How many triangles fit the given measures', 'Rosa has three straws that are 5 cm, 6 cm and 7 cm long. Triangles that match exactly in size and shape count as the same triangle. How many different triangles can she make with the three straws as sides?', '[]', '1', NULL, 'Since $5 + 6 = 11 > 7$, a triangle can be made. Three side lengths can be joined in only one way (up to size and shape), so there is exactly 1 triangle.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5+6=11>7, so a triangle forms, and three given side lengths fix the triangle (SSS): any arrangement is congruent. One triangle.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d12b13f6-13d3-445b-953c-63d34013002b', 'NC26.8.SGMR.3', 1, 'numeric', 'How many triangles fit the given measures', 'A triangle is to have sides of 2 cm, 3 cm and 9 cm. How many different triangles can be built with these side lengths?', '[]', '0', NULL, '$2 + 3 = 5$, which is less than 9. The two short sides cannot reach across the long one, so no triangle can be built: 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+3 = 5 < 9, so no triangle can be built. 0.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc7dd8db-8c5d-4ee0-9f16-8a650e47ef5d', 'NC26.8.SGMR.3', 1, 'choice', 'How many triangles fit the given measures', 'Four friends each give directions for drawing a triangle. Which directions lead to exactly one triangle?', '["The three angles are $40^\\circ$, $60^\\circ$ and $80^\\circ$","Two of the sides are 6 cm and 7 cm","The three sides are 6 cm, 7 cm and 8 cm","One side is 6 cm and one angle is $60^\\circ$"]', 'The three sides are 6 cm, 7 cm and 8 cm', NULL, 'Three side lengths that form a triangle can be put together in only one way. Three angles allow triangles of many sizes. Two sides alone, or one side and one angle, leave other measures free.', 'checked', '{"lint":[],"solve":{"answer":"The three sides are 6 cm, 7 cm and 8 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three sides 6,7,8 (6+7>8) fix exactly one triangle. One side and one angle, or two sides alone, allow many; three angles fix shape but not size, so many.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fc014d4-6303-4a0a-a382-bc780602ec33', 'NC26.8.SGMR.3', 1, 'numeric', 'How many triangles fit the given measures', 'How many different triangles have angles of $30^\circ$, $40^\circ$ and $50^\circ$?', '[]', '0', NULL, 'The angles of a triangle must add to $180^\circ$, but $30 + 40 + 50 = 120$. So there is no such triangle: 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30+40+50 = 120, not 180, so no triangle has these angles. 0.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f27db28d-ca35-4208-9ed0-078f724393f4', 'NC26.8.SGMR.3', 1, 'choice', 'How many triangles fit the given measures', 'A triangle has angles of $50^\circ$, $60^\circ$ and $70^\circ$. How many triangles have these three angles?', '["Many triangles, of different sizes","None","Exactly one","Exactly two"]', 'Many triangles, of different sizes', NULL, '$50 + 60 + 70 = 180$, so such a triangle exists. Making the triangle bigger or smaller keeps all three angles, so there are many triangles of different sizes.', 'checked', '{"lint":[],"solve":{"answer":"Many triangles, of different sizes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50+60+70 = 180, so such triangles exist; the angles fix the shape but not the size, so there are many, of different sizes.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b913eb2-d762-4e98-85ea-5e2487e9eeac', 'NC26.8.SGMR.3', 1, 'choice', 'Reason with a model, a rule or a claim', 'Kofi says, "Any three sticks can be joined to make a triangle." Which set of sticks, in centimeters, shows that Kofi is wrong?', '["2, 2, 5","5, 6, 7","4, 4, 4","3, 4, 5"]', '2, 2, 5', NULL, '$2 + 2 = 4$, which is less than 5, so the sticks 2, 2, 5 cannot make a triangle. The other three sets all work.', 'checked', '{"lint":[],"solve":{"answer":"2, 2, 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2+2 = 4 < 5, so 2, 2, 5 makes no triangle: a counterexample. The other sets all make triangles.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9961d647-8b2a-4f7a-9618-ea7bf62826df', 'NC26.8.SGMR.3', 1, 'choice', 'Reason with a model, a rule or a claim', 'Ben says that a triangle cannot have angles of $100^\circ$ and $90^\circ$. Which reason is correct?', '["The two angles together are less than $180^\\circ$","The two angles together are more than $180^\\circ$","A triangle cannot have a right angle","The two angles are different sizes"]', 'The two angles together are more than $180^\circ$', NULL, '$100 + 90 = 190$, which is more than the $180^\circ$ that all three angles share. So no third angle is possible. Triangles can have a right angle, and the angles may be different sizes.', 'checked', '{"lint":[],"solve":{"answer":"The two angles together are more than $180^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 + 90 = 190 > 180, leaving no room for a third angle. The reason: together more than 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4afbd0e-1f87-4630-bf91-04c937f0568c', 'NC26.8.SGMR.3', 1, 'choice', 'Reason with a model, a rule or a claim', 'Mia tries to make a triangle from sticks of 4 cm, 4 cm and 8 cm. What happens?', '["They form a tall, thin triangle","They form an equilateral triangle","The two short sticks lie along the long stick, so no triangle forms","They form a right triangle"]', 'The two short sticks lie along the long stick, so no triangle forms', NULL, '$4 + 4 = 8$. The two short sticks are only just long enough to reach the ends of the long stick, so they lie flat along it. No triangle forms.', 'checked', '{"lint":[],"solve":{"answer":"The two short sticks lie along the long stick, so no triangle forms","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 4 = 8, equal to the long stick, so the short sticks lie flat along it; no triangle.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5fc1c88-bc2d-48bc-9468-5a5090c59bc6', 'NC26.8.SGMR.3', 1, 'numeric', 'Reason with a model, a rule or a claim', 'Maya cuts the three corners off a paper triangle and fits them together side by side along a straight line. The three corners exactly fill the line with no gaps and no overlaps. What is the total measure of the three corners, in degrees?', '[]', '180', NULL, 'The corners fill a straight line, which is a straight angle of $180^\circ$. This shows that the three angles of a triangle add to 180 degrees.', 'checked', '{"lint":[],"solve":{"answer":"180","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The three corners fill a straight angle exactly, which is 180 degrees: the angle sum of a triangle.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea7b4b40-3511-44aa-adb4-b92b6d739e25', 'NC26.8.SGMR.3', 1, 'choice', 'Reason with a model, a rule or a claim', 'Which rule must be true for three sticks to make a triangle?', '["The two shorter sticks must add up to less than the longest stick","All three sticks must be the same length","The longest stick must be exactly twice as long as the shortest","The two shorter sticks must add up to more than the longest stick"]', 'The two shorter sticks must add up to more than the longest stick', NULL, 'If the two shorter sticks are too short, they cannot meet over the long stick. They must add to MORE than the longest. The sticks do not need to match in length.', 'checked', '{"lint":[],"solve":{"answer":"The two shorter sticks must add up to more than the longest stick","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Triangle inequality: the two shorter sides must sum to more than the longest.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8c47a85-1c41-44f7-9d37-dfe2ae60d230', 'NC26.8.SGMR.3', 2, 'numeric', 'Find the greatest possible third side', 'Two sides of a triangle are 5 cm and 9 cm long. The third side is a whole number of centimeters. What is the greatest possible length of the third side, in centimeters?', '[]', '13', '5+9-1', 'The third side must be less than the sum of the other two: less than $5 + 9 = 14$. The greatest whole number less than 14 is 13. (Check: $5 + 13 > 9$ and $9 + 13 > 5$.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9 - 5 < s < 9 + 5 -> 4 < s < 14. Greatest whole number is 13.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bac3dfb6-721a-4763-af47-7da44d183099', 'NC26.8.SGMR.3', 2, 'numeric', 'Use the angle sum in a right triangle', 'In a right triangle, one acute angle is 4 times as large as the other acute angle. What is the measure of the smaller acute angle, in degrees?', '[]', '18', '90/5', 'The two acute angles of a right triangle add to $90^\circ$ (since the right angle uses 90 of the 180). If the smaller is $x$, then $x + 4x = 90$, so $5x = 90$ and $x = 18$.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Acute angles sum to 90: x + 4x = 90 -> x = 18. Angles 18 and 72.","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8ded595-424e-4d00-8563-8c589ee932ed', 'NC26.8.SGMR.3', 2, 'choice', 'Tell which information fixes exactly one triangle', 'Which information is enough to build exactly one triangle, so that every triangle that fits it has the same size and shape?', '["Side lengths of 4 cm, 6 cm and 9 cm","Angles of $40^\\circ$, $60^\\circ$ and $80^\\circ$","Two side lengths, 5 cm and 7 cm","One side of 6 cm and one angle of $50^\\circ$"]', 'Side lengths of 4 cm, 6 cm and 9 cm', NULL, 'Three side lengths that satisfy the triangle condition ($4 + 6 > 9$) give one triangle. Three angles fix only the shape, so triangles of any size fit. Two sides, or one side and one angle, leave other measures free.', 'checked', '{"lint":[],"solve":{"answer":"Side lengths of 4 cm, 6 cm and 9 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"One side and one angle: many triangles. Two sides alone: many. Three angles: same shape, any size. Three sides 4, 6, 9 (4+6=10>9, valid): exactly one triangle (SSS).","run_id":"claude-code","at":"2026-10-17T18:35:20.783Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b9f9519-56d4-4cd6-ab3f-355e498d144c', 'NC26.8.SGMR.3', 2, 'choice', 'Side lengths: can they form a triangle?', 'Which set of lengths, in meters, can be the sides of a triangle?', '["1.5, 2, 4","3, 3, 6.5","0.8, 1.1, 2.2","2.5, 3, 5"]', '2.5, 3, 5', NULL, '$2.5 + 3 = 5.5 > 5$, so 2.5, 3, 5 works. In 1.5, 2, 4 the short sides add to 3.5. In 3, 3, 6.5 they add to 6. In 0.8, 1.1, 2.2 they add to 1.9. Each of those is less than the longest side.', 'checked', '{"lint":[],"solve":{"answer":"2.5, 3, 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.8+1.1=1.9<2.2 no; 2.5+3=5.5>5 yes; 1.5+2=3.5<4 no; 3+3=6<6.5 no. Only 2.5, 3, 5.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77cbcddf-96ed-49ff-af4b-c78b209029c8', 'NC26.8.SGMR.3', 2, 'numeric', 'Side lengths: can they form a triangle?', 'Four sets of whole-number side lengths are tested: 7, 10, 18; 12, 13, 26; 9, 9, 18; 5, 11, 15. How many of the sets can form a triangle?', '[]', '1', NULL, '7, 10, 18: $17 < 18$ fails. 12, 13, 26: $25 < 26$ fails. 9, 9, 18: $18$ is not more than 18, fails. 5, 11, 15: $5 + 11 = 16 > 15$ works. Only one set works.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7+10=17<18 no; 12+13=25<26 no; 9+9=18=18 no; 5+11=16>15 yes. One set.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
