INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('416a2185-c34f-49fc-9b34-6012a1502f65', 'NC26.8.SGMR.3', 2, 'choice', 'Side lengths: can they form a triangle?', 'Which set of lengths, in feet, can NOT be the sides of a triangle?', '["$\\frac{1}{4}, \\frac{1}{2}, \\frac{3}{4}$","$\\frac{1}{2}, \\frac{2}{3}, \\frac{3}{4}$","$\\frac{1}{3}, \\frac{1}{2}, \\frac{2}{3}$","$\\frac{3}{4}, \\frac{3}{4}, \\frac{1}{2}$"]', '$\frac{1}{4}, \frac{1}{2}, \frac{3}{4}$', NULL, 'For $\frac{1}{4}, \frac{1}{2}, \frac{3}{4}$: $\frac{1}{4} + \frac{1}{2} = \frac{3}{4}$, which is not MORE than $\frac{3}{4}$, so no triangle. The other three sets each have two short sides that add to more than the longest: $\frac{7}{6} > \frac{3}{4}$, $\frac{5}{6} > \frac{2}{3}$ and $\frac{5}{4} > \frac{3}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}, \\frac{1}{2}, \\frac{3}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/2+2/3=7/6>3/4 ok. 1/3+1/2=5/6>2/3 ok. 1/2+3/4=5/4>3/4 ok. 1/4+1/2=3/4, equal to the longest, not greater: cannot. Answer 1/4, 1/2, 3/4.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('68df20af-a019-4b0b-8047-33c443316673', 'NC26.8.SGMR.3', 2, 'numeric', 'Side lengths: can they form a triangle?', 'Ana has sticks that are 4, 5, 9 and 11 centimeters long. She picks three of the four sticks. How many different groups of three sticks can she join into a triangle?', '[]', '2', NULL, 'The groups are: 4, 5, 9 ($9$ is not more than 9, fails); 4, 5, 11 ($9 < 11$, fails); 4, 9, 11 ($13 > 11$, works); 5, 9, 11 ($14 > 11$, works). Two groups work.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Groups of three from 4,5,9,11: {4,5,9}: 9=9 no. {4,5,11}: 9<11 no. {4,9,11}: 13>11 yes. {5,9,11}: 14>11 yes. Two groups.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a69cd2c-c536-4770-b071-11ced050d75a', 'NC26.8.SGMR.3', 2, 'choice', 'Side lengths: can they form a triangle?', 'Set P has side lengths 7, 8 and 15. Set Q has side lengths 7, 8 and 14. Which statement is true?', '["Only set P can be the sides of a triangle","Only set Q can be the sides of a triangle","Both sets can be the sides of a triangle","Neither set can be the sides of a triangle"]', 'Only set Q can be the sides of a triangle', NULL, 'Set P: $7 + 8 = 15$, which is not more than 15, so P is not a triangle. Set Q: $7 + 8 = 15 > 14$, so Q is a triangle.', 'checked', '{"lint":[],"solve":{"answer":"Only set Q can be the sides of a triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 7+8=15, equal to 15, not greater: no triangle. Q: 7+8=15>14: triangle. Only set Q.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03b0ce82-778d-414d-be18-e5a24deb5018', 'NC26.8.SGMR.3', 2, 'numeric', 'Range of the third side', 'Two sides of a triangle are 8 inches and 3 inches. The third side is a whole number of inches. What is the shortest length it can have, in inches?', '[]', '6', '8-3+1', 'The third side must be more than $8 - 3 = 5$. The least whole number more than 5 is 6. Check: $3 + 6 = 9 > 8$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side > 8-3 = 5 and < 11. Shortest whole number is 6 (3+6=9>8).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bd7d2c3-3499-4820-95dc-5d426d6f3902', 'NC26.8.SGMR.3', 2, 'choice', 'Range of the third side', 'Two sides of a triangle are 6 cm and 10 cm. The third side is $x$ cm. Which describes every possible value of $x$?', '["$4 < x < 16$","$0 < x < 16$","$4 \\le x \\le 16$","$6 < x < 10$"]', '$4 < x < 16$', NULL, '$x$ must be less than $6 + 10 = 16$ and more than $10 - 6 = 4$, with neither end allowed (those would lie flat). So $4 < x < 16$.', 'checked', '{"lint":[],"solve":{"answer":"$4 < x < 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need x < 6+10 = 16 and x > 10-6 = 4, strictly (equality gives a flat figure). So 4 < x < 16.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d0148d9-ee56-4f02-913f-3864389e48be', 'NC26.8.SGMR.3', 2, 'numeric', 'Range of the third side', 'Two sides of a triangle are 7 cm and 12 cm. The third side is a whole number of centimeters. What is the greatest possible perimeter of the triangle, in centimeters?', '[]', '37', '7+12+(7+12-1)', 'The third side must be less than $7 + 12 = 19$, so at most 18. The greatest perimeter is $7 + 12 + 18 = 37$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"37","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side < 7+12 = 19, so at most 18 (and 18 > 5). Greatest perimeter 7+12+18 = 37.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7c4ac128-bd83-493b-a296-f6a632f616ce', 'NC26.8.SGMR.3', 2, 'choice', 'Range of the third side', 'A triangle has sides of 15 cm and 6 cm. Which could be the length of the third side, in centimeters?', '["8","9","12","21"]', '12', NULL, 'The third side must be more than $15 - 6 = 9$ and less than $15 + 6 = 21$. Only 12 is between 9 and 21. A 9 cm side gives $6 + 9 = 15$ and a 21 cm side gives $15 + 6 = 21$: both lie flat.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side between 15-6=9 and 15+6=21, strictly. 8 too short, 9 and 21 flat. 12 works.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c78cf50f-7231-46d7-ba04-b10b6d31b18b', 'NC26.8.SGMR.3', 2, 'numeric', 'Range of the third side', 'Two sides of a triangle are 4 cm and 8 cm. The third side could be 2, 5, 9 or 13 cm long. How many of these four lengths could really be the third side?', '[]', '2', NULL, 'The third side must be more than $8 - 4 = 4$ and less than $4 + 8 = 12$. Of 2, 5, 9 and 13, only 5 and 9 are between 4 and 12. So 2 of the lengths work.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third side must be between 8-4=4 and 8+4=12. 2 no, 5 yes, 9 yes, 13 no. Two lengths.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a196104f-e795-4cac-a1c9-f9d72f0ba445', 'NC26.8.SGMR.3', 2, 'numeric', 'Isosceles triangles and the side condition', 'An isosceles triangle has one side of 3 cm and one side of 7 cm. What is its perimeter, in centimeters?', '[]', '17', '7+7+3', 'The third side equals one of the two. If it were 3, the sides 3, 3, 7 would fail, since $3 + 3 = 6 < 7$. So the third side is 7, and the sides are 7, 7, 3. The perimeter is $7 + 7 + 3 = 17$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Either 3,3,7 (3+3=6<7, impossible) or 3,7,7 (3+7=10>7, works). Perimeter 3+7+7 = 17.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aff693b8-883b-4590-b7ce-e47086b19927', 'NC26.8.SGMR.3', 2, 'choice', 'Isosceles triangles and the side condition', 'Which set of side lengths, in centimeters, can be the sides of an isosceles triangle?', '["3, 3, 6","6, 6, 11","5, 5, 11","4, 4, 9"]', '6, 6, 11', NULL, '$6 + 6 = 12 > 11$, so 6, 6, 11 works. For 3, 3, 6 the sum is exactly 6. For 5, 5, 11 it is 10 and for 4, 4, 9 it is 8: both less than the third side.', 'checked', '{"lint":[],"solve":{"answer":"6, 6, 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5+5=10<11 no; 6+6=12>11 yes; 3+3=6=6 no; 4+4=8<9 no. Only 6, 6, 11.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5726496f-7e36-44b7-a7b1-1604b20fb148', 'NC26.8.SGMR.3', 2, 'numeric', 'Isosceles triangles and the side condition', 'An isosceles triangle has a base of 4 cm. Its two equal sides are each a whole number of centimeters. What is the shortest each of the equal sides can be, in centimeters?', '[]', '3', '4/2+1', 'Two equal sides must add to more than the base: they must be more than $4 \div 2 = 2$ each. The least whole number more than 2 is 3. Check: $3 + 3 = 6 > 4$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal sides s with base 4: need s+s > 4, so s > 2. Shortest whole number s = 3 (3,3,4: 6>4).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4497b013-a0f7-4d1a-b6d6-28193a2030de', 'NC26.8.SGMR.3', 2, 'numeric', 'Missing angle from the 180 degree sum', 'A triangle has an angle of $120^\circ$ and an angle of $25^\circ$. What is the measure of the third angle, in degrees?', '[]', '35', '180-120-25', '$120 + 25 = 145$ and $180 - 145 = 35$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 120 - 25 = 35.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
