INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0aaa3ef-7ab9-4401-99e1-ffb10ea834ba', 'NC26.8.SGMR.3', 2, 'numeric', 'Angle sum with algebra or ratios', 'The angles of a triangle are in the ratio $3:4:5$. What is the measure of the smallest angle, in degrees?', '[]', '45', '180/(3+4+5)*3', 'There are $3 + 4 + 5 = 12$ equal parts in $180^\circ$, so one part is $180 \div 12 = 15$ degrees. The smallest angle is $3 \times 15 = 45$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+4+5 = 12 parts = 180, one part 15. Smallest 3 x 15 = 45.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('05fe1bd7-4bb7-4790-b885-4e0806a1505a', 'NC26.8.SGMR.3', 2, 'choice', 'Angle sum with algebra or ratios', 'The angles of a triangle measure $(x+20)^\circ$, $(x+30)^\circ$ and $(x+40)^\circ$. Which equation can be used to find $x$?', '["$(x+20)+(x+30)+(x+40)=360$","$x+20+30+40=180$","$(x+20)(x+30)(x+40)=180$","$(x+20)+(x+30)+(x+40)=180$"]', '$(x+20)+(x+30)+(x+40)=180$', NULL, 'The three angles of a triangle ADD to $180^\circ$, so $(x+20)+(x+30)+(x+40)=180$. The second equation uses the wrong total, the third forgets that $x$ is in every angle, and the fourth multiplies instead of adding.', 'checked', '{"lint":[],"solve":{"answer":"$(x+20)+(x+30)+(x+40)=180$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle sum of a triangle is 180, so (x+20)+(x+30)+(x+40)=180. The 360 option uses the wrong total, the product is wrong, and x+20+30+40 drops two x''s.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('52deefeb-2ae3-4c0f-81c9-2542f3245703', 'NC26.8.SGMR.3', 2, 'choice', 'Angle sum with algebra or ratios', 'The angles of a triangle are in the ratio $1:1:4$. What is the measure of the largest angle, in degrees?', '["30","45","120","144"]', '120', '180/(1+1+4)*4', 'There are $1 + 1 + 4 = 6$ parts, so one part is $180 \div 6 = 30$ degrees. The largest angle is $4 \times 30 = 120$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1+1+4 = 6 parts = 180, one part 30. Largest 4 x 30 = 120.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12c97ef9-c827-4cdc-907d-a059c12fd945', 'NC26.8.SGMR.3', 2, 'choice', 'Which angle measures can form a triangle', 'Which set of angle measures, in degrees, can NOT be the angles of a triangle?', '["100, 45, 45","100, 40, 40","35, 55, 90","60, 60, 60"]', '100, 45, 45', NULL, '$100 + 45 + 45 = 190$, which is more than 180, so these cannot be the angles of a triangle. The other sets add to 180.', 'checked', '{"lint":[],"solve":{"answer":"100, 45, 45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60+60+60=180 ok; 35+55+90=180 ok; 100+45+45=190 cannot; 100+40+40=180 ok. Answer 100, 45, 45.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5a66a7f-5f76-42e6-8569-de32d4921f63', 'NC26.8.SGMR.3', 2, 'numeric', 'Which angle measures can form a triangle', 'Dan measures the three angles of a paper triangle and gets $71^\circ$, $54^\circ$ and $63^\circ$. The angles of a triangle should add to $180^\circ$. By how many degrees is Dan''s total off?', '[]', '8', '71+54+63-180', '$71 + 54 + 63 = 188$, and $188 - 180 = 8$ degrees too much.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"71+54+63 = 188. 188 - 180 = 8 degrees off.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
