INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85ebb32b-d3d6-4eb6-b010-b5aa8137de5c', 'NC26.8.SGMR.3', 3, 'choice', 'Missing angle from the 180 degree sum', 'Two angles of a triangle measure $38^\circ$ and $52^\circ$. Which kind of triangle is it?', '["It is an acute triangle","It is an obtuse triangle","It is a right triangle","The angles alone cannot tell"]', 'It is a right triangle', NULL, '$38 + 52 = 90$, so the third angle is $180 - 90 = 90$ degrees. A triangle with a $90^\circ$ angle is a right triangle.', 'checked', '{"lint":[],"solve":{"answer":"It is a right triangle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third angle = 180 - 38 - 52 = 90. It has a right angle: right triangle.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1e4ed2a-e482-4167-b494-0b7e9c47c9b9', 'NC26.8.SGMR.3', 3, 'numeric', 'Angle sum with algebra or ratios', 'The angles of a triangle measure $(3x-5)^\circ$, $(2x+15)^\circ$ and $(x+20)^\circ$. What is the measure of the largest angle, in degrees?', '[]', '70', '3*25-5', '$(3x-5)+(2x+15)+(x+20)=6x+30=180$, so $6x=150$ and $x=25$. The angles are $70^\circ$, $65^\circ$ and $45^\circ$, so the largest is 70 degrees.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x-5)+(2x+15)+(x+20) = 6x+30 = 180, x = 25. Angles 70, 65, 45 (sum 180). Largest 70.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3748757c-2c11-45e7-8545-3e604b69d586', 'NC26.8.SGMR.3', 3, 'numeric', 'Angle sum with algebra or ratios', 'In a triangle, one angle is 4 times the smallest angle, and the third angle is $30^\circ$ larger than the smallest angle. What is the measure of the largest angle, in degrees?', '[]', '100', '4*(180-30)/6', 'Let the smallest angle be $s$. Then $s + 4s + (s+30) = 180$, so $6s = 150$ and $s = 25$. The angles are 25, 100 and 55 degrees, so the largest is 100 degrees.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Smallest s; others 4s and s+30. 6s+30 = 180, s = 25. Angles 25, 100, 55; 25 is indeed smallest. Largest 100.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1dd26d74-2bbc-4d17-a1a4-b670098643eb', 'NC26.8.SGMR.3', 3, 'choice', 'Angle sum with algebra or ratios', 'In a triangle, the largest angle is 3 times the smallest angle, and the middle angle is $20^\circ$ larger than the smallest angle. What is the measure of the middle angle, in degrees?', '["32","52","64","96"]', '52', '(180-20)/5+20', 'Let the smallest angle be $s$. Then $s + (s+20) + 3s = 180$, so $5s = 160$ and $s = 32$. The middle angle is $32 + 20 = 52$ degrees. (The angles are 32, 52 and 96.)', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Smallest s, middle s+20, largest 3s. 5s+20 = 180, s = 32. Angles 32, 52, 96 (sum 180). Middle 52.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ecd940a-c3fe-4244-aa89-84d8b5ebc0a5', 'NC26.8.SGMR.3', 3, 'numeric', 'Angle sum with algebra or ratios', 'An isosceles triangle has two equal base angles of $(2x+5)^\circ$ each and a top angle of $(x+10)^\circ$. What is the measure of the top angle, in degrees?', '[]', '42', '(180-20)/5+10', '$2(2x+5)+(x+10)=5x+20=180$, so $5x=160$ and $x=32$. The top angle is $32+10=42$ degrees. (The base angles are $69^\circ$ each.)', 'checked', '{"lint":[],"solve":{"answer":"42","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(2x+5) + (x+10) = 5x+20 = 180, x = 32. Top angle x+10 = 42; base angles 69 each; 69+69+42 = 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab1c8666-6830-4f80-8d1f-238f1de16776', 'NC26.8.SGMR.3', 3, 'choice', 'Which angle measures can form a triangle', 'Two angles of a triangle measure $100^\circ$ and $x^\circ$, where $x$ is a whole number. Which of these can NOT be the value of $x$?', '["20","40","79","80"]', '80', '180-100', 'The third angle is $180 - 100 - x = 80 - x$, and it must be more than 0. So $x$ must be less than 80. If $x = 80$ the third angle would be $0^\circ$. The values 20, 40 and 79 leave a third angle of 60, 40 and 1 degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Third angle = 80 - x must be > 0, so x < 80. 20, 40, 79 work (third 60, 40, 1). x = 80 leaves 0: cannot.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83b52b7e-faff-4eb6-832b-6ebfb5388325', 'NC26.8.SGMR.3', 3, 'numeric', 'Which angle measures can form a triangle', 'Two angles of a triangle are each less than $40^\circ$, and all three angles are whole numbers of degrees. What is the smallest possible measure of the third angle, in degrees?', '[]', '102', '180-39-39', 'Each of the two angles is at most 39 degrees, so together they are at most $39 + 39 = 78$. The third angle is at least $180 - 78 = 102$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"102","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two whole-number angles each less than 40 are at most 39 each, total at most 78. Third angle at least 180 - 78 = 102 (39, 39, 102).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb6e7605-32cb-40d2-afa9-c9453262bacc', 'NC26.8.SGMR.3', 3, 'numeric', 'How many triangles fit the given measures', 'In triangle $ABC$, angle $A$ is $110^\circ$, side $AB$ is 8 cm and side $BC$ is 5 cm. (Side $BC$ is the side opposite angle $A$.) How many different triangles fit this description?', '[]', '0', NULL, 'The longest side of a triangle is opposite its largest angle. With an obtuse angle at $A$, side $BC$ would have to be the longest side, but $5 < 8$. If you try to swing a 5 cm side from $B$, it cannot reach the other arm of the $110^\circ$ angle. So there are 0 triangles.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle A = 110 is obtuse, so the side opposite it (BC) must be the longest side. But BC = 5 < AB = 8. No triangle: 0.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d83e827-0e85-45b2-83dc-ee01dc71e14b', 'NC26.8.SGMR.3', 3, 'numeric', 'How many triangles fit the given measures', 'In triangle $ABC$, angle $A$ is $30^\circ$, side $AB$ is 10 cm and side $BC$ is 6 cm. The shortest distance from point $B$ to the line that contains side $AC$ is 5 cm. How many different triangles fit this description?', '[]', '2', NULL, 'Swing a 6 cm side from $B$. It is longer than the 5 cm shortest distance, so it reaches the line in two places, one on each side of the foot of the perpendicular. The foot is about 8.7 cm from $A$ and each point is about 3.3 cm from the foot, so both points lie on the ray from $A$ (about 5.4 cm and 12.0 cm from $A$). Two different triangles fit.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C lies on the ray from A at 30 degrees to AB, and BC = 6. The distance from B to that line is 5 (= 10 x 1/2). Since 5 < 6, the circle of radius 6 about B meets the line at two points; since 6 < AB = 10, A is outside that circle, so both points lie on the same side of A (foot at 10cos30 = 8.66 from A, crossings at 8.66 +/- sqrt(11) = 5.34 and 11.98, both positive). Two triangles.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d197e728-f5bd-4a21-8fd0-27c988e4df6b', 'NC26.8.SGMR.3', 3, 'choice', 'How many triangles fit the given measures', 'Which information could give MORE than one triangle?', '["Sides of 6 cm, 7 cm and 9 cm","Sides of 6 cm and 9 cm, and the $40^\\circ$ angle between them","Angles of $40^\\circ$ and $60^\\circ$, and the 9 cm side between them","Sides of 9 cm and 7 cm, and a $40^\\circ$ angle opposite the 7 cm side"]', 'Sides of 9 cm and 7 cm, and a $40^\circ$ angle opposite the 7 cm side', NULL, 'Three sides, two sides with the angle between them, and two angles with the side between them each fix exactly one triangle. Two sides and an angle NOT between them can fit two triangles: the 7 cm side can swing to two places on the other arm of the $40^\circ$ angle.', 'checked', '{"lint":[],"solve":{"answer":"Sides of 9 cm and 7 cm, and a $40^\\circ$ angle opposite the 7 cm side","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SSS, ASA and SAS each fix one triangle. 9 and 7 with 40 degrees opposite 7 (SSA): the height from the vertex is 9 sin 40 = 5.79 < 7 < 9, so two triangles are possible. This option can give more than one.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f28c3f01-ff7a-42ba-9b91-95204d74becd', 'NC26.8.SGMR.3', 3, 'numeric', 'How many triangles fit the given measures', 'A triangle has angles of $55^\circ$, $65^\circ$ and $60^\circ$. One of its sides is 10 cm long, but it is not said which one. Triangles with the same size and shape count as one. How many different triangles fit?', '[]', '3', NULL, 'The 10 cm side could be opposite the $55^\circ$ angle, opposite the $65^\circ$ angle, or opposite the $60^\circ$ angle. Each choice gives a triangle of a different size. So there are 3 different triangles.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All three angles differ, so all three sides differ. The 10 cm side can be opposite 55, 60 or 65, giving three different-sized triangles. 3.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dff0777f-371e-4acd-b3dc-ebd0d2794b1b', 'NC26.8.SGMR.3', 3, 'numeric', 'How many triangles fit the given measures', 'A triangle has angles of $40^\circ$, $70^\circ$ and $70^\circ$. One of its sides is 6 cm long, but it is not said which one. Triangles with the same size and shape count as one. How many different triangles fit?', '[]', '2', NULL, 'The 6 cm side could be opposite the $40^\circ$ angle, or opposite one of the $70^\circ$ angles. The two $70^\circ$ angles are alike, so putting the 6 cm side opposite either one gives the same triangle. That is 2 different triangles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Isosceles: the two sides opposite the 70 angles are equal. The 6 cm side is either the base (opposite 40) or one of the equal sides (opposite 70). Two different triangles.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c79112e9-2eaf-4465-b0f8-e63a99f3ff80', 'NC26.8.SGMR.3', 3, 'numeric', 'Reason with a model, a rule or a claim', 'A triangle has one obtuse angle of $130^\circ$. All three angles are whole numbers of degrees. What is the greatest possible measure of the largest of the other two angles, in degrees?', '[]', '49', '180-130-1', 'The other two angles add to $180 - 130 = 50$ degrees, and each is at least 1 degree. The larger one is greatest when the smaller is 1: $50 - 1 = 49$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"49","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other two angles sum to 180 - 130 = 50, each a whole number at least 1. Largest of them at most 49 (49 and 1).","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8987b303-992e-4540-8eb1-c32e97a7236c', 'NC26.8.SGMR.3', 3, 'choice', 'Reason with a model, a rule or a claim', 'Ivy says, "Two triangles with the same three angles must be exactly the same triangle." Which pair shows that Ivy is wrong?', '["Triangle P has sides 3 cm, 4 cm, 5 cm. Triangle Q has sides 4 cm, 3 cm, 5 cm","Triangle P has sides 5 cm, 5 cm, 5 cm. Triangle Q has sides 5 cm, 5 cm, 5 cm","Triangle P has sides 3 cm, 4 cm, 5 cm. Triangle Q has sides 3 cm, 4 cm, 6 cm","Triangle P has sides 3 cm, 4 cm, 5 cm. Triangle Q is P made twice as big, with sides 6 cm, 8 cm, 10 cm"]', 'Triangle P has sides 3 cm, 4 cm, 5 cm. Triangle Q is P made twice as big, with sides 6 cm, 8 cm, 10 cm', NULL, 'A counterexample needs two triangles with the same angles that are NOT the same size and shape. Making a triangle twice as big keeps every angle but changes the size. The pairs with matching sides are the same triangle, and sides 3, 4, 6 give different angles from 3, 4, 5.', 'checked', '{"lint":[],"solve":{"answer":"Triangle P has sides 3 cm, 4 cm, 5 cm. Triangle Q is P made twice as big, with sides 6 cm, 8 cm, 10 cm","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,4,5 and 6,8,10 are similar (same angles) but different sizes, so they are not the same triangle. 3,4,5 vs 4,3,5 are the same triangle; equal equilaterals are the same; 3,4,6 has different angles.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1520921e-5830-4e22-9aa1-327921272882', 'NC26.8.SGMR.3', 3, 'choice', 'Reason with a model, a rule or a claim', 'Why is it enough to check only that the two shortest sides add up to more than the longest side?', '["The other two sums each include the longest side, so they are certain to be larger than the remaining side","The other two sums always come out equal to the first sum","The shortest side is always longer than half of the longest side","Only the longest side matters, so the others can be any length"]', 'The other two sums each include the longest side, so they are certain to be larger than the remaining side', NULL, 'The other two checks add the longest side to one of the others, and compare with the third side, which is no longer than the longest. So those sums are certain to be bigger. Only the first check can fail.', 'checked', '{"lint":[],"solve":{"answer":"The other two sums each include the longest side, so they are certain to be larger than the remaining side","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With a <= b <= c: a + c > b and b + c > a hold automatically because c alone is at least as long as either other side and the added side is positive. Only a + b > c needs checking.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a42fbd8b-0d5a-4562-9154-c21e09fcfbb8', 'NC26.8.SGMR.3', 3, 'numeric', 'Reason with a model, a rule or a claim', 'A 12 cm piece of wire is cut into three pieces, each a whole number of centimeters long, and the pieces are used as the three sides of a triangle. Triangles with the same three side lengths count as one. How many different triangles can be made?', '[]', '3', NULL, 'The longest piece must be less than half of 12, so it is at most 5. The sets of three whole numbers adding to 12 with longest at most 5 are 4, 4, 4; 3, 4, 5; and 2, 5, 5. Each satisfies the side rule ($2 + 5 = 7 > 5$). So 3 triangles can be made.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a <= b <= c, a+b+c = 12, a+b > c so c < 6, and c >= 4. c=4: 4,4,4. c=5: a+b=7 with b<=5: 2,5,5 and 3,4,5. Three triangles.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8653453-baaf-4c89-9555-01b7712f87ad', 'NC26.8.SGMR.3', 3, 'choice', 'Reason with a model, a rule or a claim', 'Which statement is true for every triangle?', '["The longest side is longer than half of the perimeter","The longest side is shorter than half of the perimeter","The shortest side is longer than one third of the perimeter","The two shorter sides together are shorter than the longest side"]', 'The longest side is shorter than half of the perimeter', NULL, 'The longest side is less than the sum of the other two, so twice the longest side is less than the whole perimeter. That means the longest side is less than half the perimeter. For sides 3, 4, 5 the shortest side (3) is less than one third of 12 (which is 4).', 'checked', '{"lint":[],"solve":{"answer":"The longest side is shorter than half of the perimeter","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Longest c < a + b, so 2c < a+b+c = P, c < P/2: always true. Longest > P/2 is false; shortest <= P/3 always, so the one-third statement is false; shorter two sum to more, not less.","run_id":"claude-code","at":"2026-10-17T20:29:29.793Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8aa8497-7af7-42c0-af68-d784e80e0109', 'NC26.8.SGMR.4', 1, 'numeric', 'Angle sum of a triangle', 'Two angles of a triangle measure $48^\circ$ and $67^\circ$. What is the measure of the third angle, in degrees?', '[]', '65', '180-48-67', 'The three angles of a triangle add up to $180^\circ$. First, $48 + 67 = 115$. Then $180 - 115 = 65$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 48 - 67 = 65.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88ae32a1-302a-4128-9f2f-4d910519ae16', 'NC26.8.SGMR.4', 1, 'choice', 'Corresponding angles and parallel lines', 'Two parallel lines are cut by a transversal. Angle 1 and angle 2 are corresponding angles. Angle 1 measures $110^\circ$. What is the measure of angle 2, in degrees?', '["70","110","55","250"]', '110', '110', 'When two parallel lines are cut by a transversal, corresponding angles are equal. So angle 2 also measures $110^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles formed by parallel lines and a transversal are congruent, so angle 2 = 110.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4997cbef-2039-4292-9200-935b5620c79f', 'NC26.8.SGMR.4', 1, 'numeric', 'Exterior angle of a triangle', 'One side of a triangle is extended to form an exterior angle. The two interior angles that are not next to the exterior angle measure $40^\circ$ and $55^\circ$. What is the measure of the exterior angle, in degrees?', '[]', '95', '40+55', 'An exterior angle of a triangle equals the sum of the two interior angles that are not next to it. $40 + 55 = 95$. Check: the third interior angle is $180 - 95 = 85$, and $40 + 55 + 85 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle = sum of the two remote interior angles = 40 + 55 = 95.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8740576d-0819-4ffb-a9c3-0d4d9c9ccb3a', 'NC26.8.SGMR.4', 1, 'choice', 'Angle sum of a triangle', 'Triangle $PQR$ has angle $P = 72^\circ$ and angle $Q = 38^\circ$. What is the measure of angle $R$, in degrees?', '["70","108","110","142"]', '70', '180-72-38', 'The angles of a triangle add to $180^\circ$. $72 + 38 = 110$, and $180 - 110 = 70$. The number 110 is only the sum of the two angles, 108 is $180 - 72$, and 142 is $180 - 38$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"R = 180 - 72 - 38 = 70.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('72a9b55f-6ed2-4e93-8e68-22cb10832e83', 'NC26.8.SGMR.4', 1, 'choice', 'Angle sum of a triangle', 'Two angles of a triangle measure $25^\circ$ and $65^\circ$. What is the measure of the third angle, in degrees?', '["40","90","115","155"]', '90', '180-25-65', '$25 + 65 = 90$, and $180 - 90 = 90$. So the third angle is a right angle. The number 40 is $65 - 25$, 115 is $180 - 65$, and 155 is $180 - 25$.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 25 - 65 = 90.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
