INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90517ffb-630d-4faa-abbd-dad86beebaf7', 'NC26.8.SGMR.4', 1, 'numeric', 'Angle sum of a triangle', 'In a right triangle, one of the acute angles is $28^\circ$. What is the measure of the other acute angle, in degrees?', '[]', '62', '90-28', 'The right angle is $90^\circ$, so the two acute angles add to $180 - 90 = 90$ degrees. The other acute angle is $90 - 28 = 62$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"62","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Acute angles of a right triangle sum to 90: 90 - 28 = 62.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4c19c677-d1b3-4c0c-a95e-cdbcebab0394', 'NC26.8.SGMR.4', 1, 'choice', 'Angle sum of a triangle', 'An isosceles triangle has a vertex angle of $80^\circ$ between its two equal sides. What is the measure of each base angle, in degrees?', '["100","80","50","40"]', '50', '(180-80)/2', 'The two base angles are equal and share $180 - 80 = 100$ degrees, so each is $100 \div 2 = 50$ degrees. The number 100 forgets to split the sum between the two angles.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base angles are equal: (180 - 80)/2 = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93de7f4d-1afc-414e-a7da-68bcf629b1df', 'NC26.8.SGMR.4', 1, 'numeric', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $x^\circ$, $(x+20)^\circ$ and $(x+40)^\circ$. What is the value of $x$?', '[]', '40', '(180-20-40)/3', '$x + (x+20) + (x+40) = 180$, so $3x + 60 = 180$ and $3x = 120$. Then $x = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (x+20) + (x+40) = 3x + 60 = 180, x = 40. Angles 40, 60, 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b821976-9cee-4bc2-aba2-d0c0a64fc121', 'NC26.8.SGMR.4', 1, 'numeric', 'Exterior angle from the two far interior angles', 'In triangle $ABC$, side $AC$ is extended past $C$ to a point $D$. Angle $A$ measures $35^\circ$ and angle $B$ measures $70^\circ$. What is the measure of the exterior angle $BCD$, in degrees?', '[]', '105', '35+70', 'An exterior angle equals the sum of the two interior angles that are not next to it. Angle $BCD$ is next to angle $C$, so $BCD = A + B = 35 + 70 = 105$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle BCD = sum of the remote interior angles A + B = 35 + 70 = 105.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('85af88d7-42df-4de1-8dfa-b24e01e71fbb', 'NC26.8.SGMR.4', 1, 'choice', 'Exterior angle from the two far interior angles', 'A triangle has interior angles of $50^\circ$, $60^\circ$ and $70^\circ$. One side is extended to make an exterior angle at the vertex of the $70^\circ$ angle. What is the measure of that exterior angle, in degrees?', '["70","110","120","130"]', '110', '50+60', 'The exterior angle equals the sum of the two interior angles not next to it: $50 + 60 = 110$ degrees. (It also equals $180 - 70 = 110$.) The number 70 is the interior angle itself.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle at the 70 vertex = 180 - 70 = 110 (= 50 + 60).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7154c0d3-3175-457a-aaba-942c1a929bb5', 'NC26.8.SGMR.4', 1, 'numeric', 'Exterior angle from the two far interior angles', 'Two interior angles of a triangle measure $40^\circ$ and $80^\circ$. What is the measure of the exterior angle at the third vertex, in degrees?', '[]', '120', '40+80', 'The exterior angle at the third vertex equals the sum of the other two interior angles: $40 + 80 = 120$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle at third vertex = 40 + 80 = 120 (interior there is 60).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
