INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a73ae98-7913-4083-a1e2-3e352ddcd3f2', 'NC26.8.SGMR.4', 1, 'numeric', 'Interior angle from an exterior angle', 'In triangle $ABC$, the exterior angle at $C$ measures $110^\circ$ and angle $A$ measures $45^\circ$. What is the measure of angle $B$, in degrees?', '[]', '65', '110-45', 'The exterior angle at $C$ equals $A + B$. So $B = 110 - 45 = 65$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior at C = A + B: 110 = 45 + B, B = 65.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
