INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b39ff52-9ae2-4ca4-8c66-63ddb370d1d5', 'NC26.8.SGMR.4', 1, 'choice', 'Interior angle from an exterior angle', 'An exterior angle of a triangle measures $120^\circ$. What is the measure of the interior angle at the same vertex, in degrees?', '["240","120","60","30"]', '60', '180-120', 'The exterior angle and the interior angle at the same vertex make a straight line, so they add to $180^\circ$. The interior angle is $180 - 120 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior and adjacent interior angles form a linear pair: 180 - 120 = 60.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
