INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a366ce5a-12e5-4c36-960b-babcfe37e38f', 'NC26.8.SGMR.4', 1, 'numeric', 'Exterior angles with algebra', 'An exterior angle of a triangle measures $(2x+10)^\circ$. The two interior angles not next to it measure $50^\circ$ and $70^\circ$. What is the value of $x$?', '[]', '55', '(50+70-10)/2', 'The exterior angle equals the sum of the two far interior angles: $2x + 10 = 50 + 70 = 120$. So $2x = 110$ and $x = 55$.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 10 = 50 + 70 = 120, 2x = 110, x = 55.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
