INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b12dcc48-31b3-4c23-8515-ecad997ee3af', 'NC26.8.SGMR.4', 1, 'numeric', 'Linear pairs and vertical angles', 'Two lines cross. One of the four angles formed measures $65^\circ$. What is the measure of the angle directly opposite it, in degrees?', '[]', '65', NULL, 'Angles directly opposite each other where two lines cross (vertical angles) are equal. So the answer is 65 degrees.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles are equal: 65.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
