INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e036cce7-0322-406f-b535-cf50a67b463c', 'NC26.8.SGMR.4', 1, 'numeric', 'Linear pairs and vertical angles', 'Two angles form a linear pair. One of them measures $110^\circ$. What is the measure of the other, in degrees?', '[]', '70', '180-110', 'A linear pair makes a straight line, so the angles add to $180^\circ$. The other angle is $180 - 110 = 70$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Linear pair sums to 180: 180 - 110 = 70.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
