INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdc63bdd-2cd6-4140-9ae5-3847e4061ed4', 'NC26.8.SGMR.4', 1, 'choice', 'Linear pairs and vertical angles', 'Two lines cross, forming four angles. Which pair of these angles must be equal in measure?', '["Two angles directly opposite each other","Two angles side by side on a straight line","Any two of the four angles","Two angles that add to $180^\\circ$"]', 'Two angles directly opposite each other', NULL, 'Angles directly opposite each other (vertical angles) are always equal. Two angles side by side on a line add to $180^\circ$ but are equal only when each is $90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Two angles directly opposite each other","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical (opposite) angles are always equal. Adjacent angles add to 180 and are equal only if both are 90.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
