INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd34cb62-5d92-4a12-8df0-b0db59028bc0', 'NC26.8.SGMR.4', 1, 'choice', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate interior angles measure $(x+20)^\circ$ and $55^\circ$. What is the value of $x$?', '["35","55","75","125"]', '35', '55-20', 'Alternate interior angles are equal, so $x + 20 = 55$ and $x = 35$. The number 75 comes from adding 20 instead of subtracting.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 20 = 55, x = 35.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
