INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3df6f5cc-c520-4e2f-81a6-dd443ac6bfff', 'NC26.8.SGMR.4', 1, 'choice', 'Same-side interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Which pair of angles is NOT always equal in measure?', '["Same-side interior angles","Corresponding angles","Alternate interior angles","Alternate exterior angles"]', 'Same-side interior angles', NULL, 'Corresponding, alternate interior and alternate exterior angles are equal when the lines are parallel. Same-side interior angles add to $180^\circ$, so they are equal only when each is $90^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"Same-side interior angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior, corresponding and alternate exterior angles are equal; same-side interior angles are supplementary, equal only when both are 90.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
