INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e794afc-8d3e-4724-86f1-9b7a743c10d0', 'NC26.8.SGMR.4', 1, 'choice', 'Multi-step angle problems in triangles and around points', 'Four angles fit together around a point. Three of them measure $90^\circ$, $120^\circ$ and $75^\circ$. What is the measure of the fourth angle, in degrees?', '["285","165","150","75"]', '75', '360-90-120-75', 'Angles around a point add to $360^\circ$. $90 + 120 + 75 = 285$, and $360 - 285 = 75$ degrees. The number 285 is the sum of the three angles.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles around a point sum to 360: 360 - 90 - 120 - 75 = 75.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5546ac1-c07d-4d8b-aa38-6bf7c394b146', 'NC26.8.SGMR.4', 2, 'numeric', 'Unknown angles in a triangle (algebra)', 'The angles of a triangle measure $(x+10)^\circ$, $(2x)^\circ$ and $(x+30)^\circ$. What is the measure of the largest angle, in degrees?', '[]', '70', '2*(180-40)/4', 'The angles add up to $180$: $(x+10) + 2x + (x+30) = 4x + 40 = 180$, so $4x = 140$ and $x = 35$. The angles are $45^\circ$, $70^\circ$ and $65^\circ$. The largest is $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+10) + 2x + (x+30) = 180 -> 4x + 40 = 180 -> x = 35. Angles: 45, 70, 65. Largest = 70.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8aa47413-92fe-4336-b197-26e143899abc', 'NC26.8.SGMR.4', 2, 'numeric', 'Alternate interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Two alternate interior angles measure $(3x+5)^\circ$ and $65^\circ$. What is the value of $x$?', '[]', '20', '(65-5)/3', 'Alternate interior angles are equal when the lines are parallel. So $3x + 5 = 65$. Subtract 5: $3x = 60$. Divide by 3: $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Alternate interior angles are congruent: 3x + 5 = 65 -> 3x = 60 -> x = 20.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06f64e13-493f-4479-a52c-24a49bbcc5ec', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Two parallel lines are cut by a transversal. Two angles on the same side of the transversal and between the parallel lines measure $(2x+10)^\circ$ and $(x+20)^\circ$. What is the value of $x$?', '["10","50","60","70"]', '50', '(180-30)/3', 'Same-side interior angles add up to $180^\circ$ when the lines are parallel. So $(2x+10) + (x+20) = 180$, which gives $3x + 30 = 180$. Then $3x = 150$ and $x = 50$. The angles are $110^\circ$ and $70^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angles are supplementary: (2x+10) + (x+20) = 180 -> 3x + 30 = 180 -> x = 50. Check: 110 + 70 = 180.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a27984ce-20f3-434c-b082-37cc793029b9', 'NC26.8.SGMR.4', 2, 'numeric', 'Angle sum of a triangle', 'In triangle $ABC$, angle $C$ measures $60^\circ$ and angle $A$ is twice as large as angle $B$. What is the measure of angle $A$, in degrees?', '[]', '80', '(180-60)/3*2', 'Angles $A$ and $B$ share $180 - 60 = 120$ degrees. Since $A$ is twice $B$, they are 3 equal parts: $B = 120 \div 3 = 40$ degrees and $A = 2 \times 40 = 80$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A + B = 180 - 60 = 120 with A = 2B: 3B = 120, B = 40, A = 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f586d33-a1b4-4dd8-a13f-162f4fe8fe53', 'NC26.8.SGMR.4', 2, 'choice', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $(2x)^\circ$, $(3x)^\circ$ and $(4x)^\circ$. What is the measure of the smallest angle, in degrees?', '["20","40","60","80"]', '40', '2*180/9', '$2x + 3x + 4x = 9x = 180$, so $x = 20$. The smallest angle is $2x = 40$ degrees. The number 20 is the value of $x$, and 60 and 80 are the other two angles.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 3x + 4x = 9x = 180, x = 20. Smallest angle 2x = 40 (angles 40, 60, 80).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eecb2c27-bc61-460e-8861-3d4a40ff7ecd', 'NC26.8.SGMR.4', 2, 'numeric', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $(x+15)^\circ$, $(2x-5)^\circ$ and $(3x+2)^\circ$. What is the measure of the largest angle, in degrees?', '[]', '86', '3*28+2', '$(x+15) + (2x-5) + (3x+2) = 6x + 12 = 180$, so $6x = 168$ and $x = 28$. The angles are $43^\circ$, $51^\circ$ and $86^\circ$, so the largest is 86 degrees.', 'checked', '{"lint":[],"solve":{"answer":"86","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x+15)+(2x-5)+(3x+2) = 6x + 12 = 180, x = 28. Angles 43, 51, 86 (sum 180). Largest 86.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a86159e-14f2-4d45-86f7-a9e05a3090f5', 'NC26.8.SGMR.4', 2, 'choice', 'Exterior angle from the two far interior angles', 'In triangle $PQR$, side $QR$ is extended past $R$ to a point $S$. Angle $P$ measures $58^\circ$ and angle $Q$ measures $47^\circ$. What is the measure of angle $PRS$, in degrees?', '["75","105","122","133"]', '105', '58+47', 'Angle $PRS$ is the exterior angle at $R$, so it equals $P + Q = 58 + 47 = 105$ degrees. The number 75 is the interior angle $R$ ($180 - 105$), 122 is $180 - 58$ and 133 is $180 - 47$.', 'checked', '{"lint":[],"solve":{"answer":"105","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"PRS is the exterior angle at R: P + Q = 58 + 47 = 105.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e50c730e-b3cf-4a33-8c6c-9a359fe70e91', 'NC26.8.SGMR.4', 2, 'numeric', 'Exterior angle from the two far interior angles', 'A triangle has angles of $64^\circ$, $57^\circ$ and $59^\circ$. A side is extended to make an exterior angle at the vertex of the $59^\circ$ angle. What is the measure of that exterior angle, in degrees?', '[]', '121', '64+57', 'The exterior angle equals the sum of the two interior angles not next to it: $64 + 57 = 121$ degrees. Check: $180 - 59 = 121$.', 'checked', '{"lint":[],"solve":{"answer":"121","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180 - 59 = 121 (= 64 + 57).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f7ccc79-f8f4-43dc-96f7-3a6662d90004', 'NC26.8.SGMR.4', 2, 'choice', 'Exterior angle from the two far interior angles', 'Which statement about an exterior angle of a triangle is always true?', '["It is always an obtuse angle","It always equals the interior angle next to it","It is always smaller than each interior angle that is not next to it","It equals the sum of the two interior angles that are not next to it"]', 'It equals the sum of the two interior angles that are not next to it', NULL, 'The exterior angle and the interior angle next to it form a straight line, so the exterior angle is $180^\circ$ minus that interior angle, which equals the other two interior angles added together. It can be acute, it is not equal to its neighbour in general, and it is larger than each of the two far angles.', 'checked', '{"lint":[],"solve":{"answer":"It equals the sum of the two interior angles that are not next to it","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle theorem: it equals the sum of the two remote interior angles. It is acute when the interior angle is obtuse, it is supplementary (not equal) to the adjacent interior angle, and it is larger than each remote angle.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a6e25f4-e322-4b0c-b2b0-e0eeee822f81', 'NC26.8.SGMR.4', 2, 'numeric', 'Interior angle from an exterior angle', 'A triangle has an exterior angle of $140^\circ$. One of the two interior angles not next to it measures $90^\circ$. What is the measure of the other one, in degrees?', '[]', '50', '140-90', 'The exterior angle equals the sum of the two interior angles not next to it. So the other angle is $140 - 90 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior = sum of the two remote interior angles: 140 - 90 = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a90064d0-d1ff-48a9-ac86-32b7418239d4', 'NC26.8.SGMR.4', 2, 'choice', 'Interior angle from an exterior angle', 'In triangle $ABC$, the exterior angle at $A$ measures $100^\circ$ and angle $B$ measures $30^\circ$. What is the measure of angle $C$, in degrees?', '["50","70","80","130"]', '70', '100-30', 'The exterior angle at $A$ equals $B + C$, so $C = 100 - 30 = 70$ degrees. (Check: the interior angle at $A$ is $80^\circ$, and $80 + 30 + 70 = 180$.)', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior at A = B + C: 100 = 30 + C, C = 70. Check: interior A = 80, 80+30+70 = 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7355aab-b037-43de-bf27-f937627e19de', 'NC26.8.SGMR.4', 2, 'choice', 'Exterior angles with algebra', 'The exterior angle of a triangle measures $(3x+15)^\circ$. The two interior angles not next to it measure $(x+20)^\circ$ and $(x+45)^\circ$. What is the measure of the exterior angle, in degrees?', '["165","70","50","15"]', '165', '3*50+15', '$3x + 15 = (x+20) + (x+45) = 2x + 65$, so $x = 50$. The exterior angle is $3 \times 50 + 15 = 165$ degrees. The number 50 is only $x$, and 70 is one of the far angles.', 'checked', '{"lint":[],"solve":{"answer":"165","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 15 = (x+20) + (x+45) = 2x + 65, x = 50. Exterior = 3(50) + 15 = 165 (remote angles 70 and 95).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa90d7f6-8753-4751-bb88-7ea06862f6ea', 'NC26.8.SGMR.4', 2, 'choice', 'Linear pairs and vertical angles', 'Two lines cross. One angle measures $(3x)^\circ$ and the angle directly opposite it measures $(x+50)^\circ$. What is the value of $x$?', '["25","50","75","130"]', '25', '50/2', 'Opposite angles are equal, so $3x = x + 50$. Then $2x = 50$ and $x = 25$. (The angle itself is $75^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vertical angles equal: 3x = x + 50, 2x = 50, x = 25 (both 75).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3cf2fdf8-2c82-40c1-964b-453a1476cc9c', 'NC26.8.SGMR.4', 2, 'choice', 'Linear pairs and vertical angles', 'Two lines cross, forming four angles. One angle is 4 times as large as an angle next to it. What is the measure of the smaller of these two angles, in degrees?', '["144","72","45","36"]', '36', '180/5', 'Angles next to each other where two lines cross add to $180^\circ$. With parts of 1 and 4, that is 5 equal parts: $180 \div 5 = 36$ degrees. The larger angle is $4 \times 36 = 144$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adjacent angles form a linear pair: x + 4x = 180, x = 36 (other 144). Smaller 36.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('370d6118-c34b-47b5-80b2-df78edb9559a', 'NC26.8.SGMR.4', 2, 'choice', 'Corresponding angles and parallel lines', 'Two parallel lines are crossed by a transversal. Two corresponding angles measure $(4x-15)^\circ$ and $(2x+25)^\circ$. What is the value of $x$?', '["10","20","40","65"]', '20', '(25+15)/2', 'Corresponding angles are equal: $4x - 15 = 2x + 25$, so $2x = 40$ and $x = 20$. (Each angle is $65^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 15 = 2x + 25, 2x = 40, x = 20 (both 65).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f93a12f-825c-4b5c-8ff8-c5979ae3a00d', 'NC26.8.SGMR.4', 2, 'numeric', 'Corresponding angles and parallel lines', 'Parallel lines are crossed by a transversal. An angle of $64^\circ$ at the upper line has a corresponding angle at the lower line. Angle $z$ forms a linear pair with that corresponding angle. What is the measure of angle $z$, in degrees?', '[]', '116', '180-64', 'The corresponding angle at the lower line is also $64^\circ$. A linear pair adds to $180^\circ$, so angle $z$ is $180 - 64 = 116$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"116","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angle at the lower line is 64; z forms a linear pair with it: 180 - 64 = 116.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ce6cb0d-cff5-4069-9023-b771fb97f7ce', 'NC26.8.SGMR.4', 2, 'choice', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate interior angles measure $(2x+14)^\circ$ and $(4x-26)^\circ$. What is the value of $x$?', '["10","20","32","40"]', '20', '(14+26)/2', 'Alternate interior angles are equal: $2x + 14 = 4x - 26$, so $2x = 40$ and $x = 20$. The number 32 would come from wrongly adding the angles to $180^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 14 = 4x - 26, 2x = 40, x = 20 (both 54).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
