INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87dbae6b-76ca-4779-be7a-7f3f009cee06', 'NC26.8.SGMR.4', 2, 'numeric', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate exterior angles measure $(5x-8)^\circ$ and $(3x+16)^\circ$. What is the measure of each of these angles, in degrees?', '[]', '52', '5*12-8', 'Alternate exterior angles are equal: $5x - 8 = 3x + 16$, so $2x = 24$ and $x = 12$. Each angle is $5 \times 12 - 8 = 52$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 8 = 3x + 16, 2x = 24, x = 12. Each angle 5(12) - 8 = 52.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c7326e4-4c08-47e4-85d3-32508dfd2523', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two same-side interior angles measure $(3x+10)^\circ$ and $(2x+20)^\circ$. What is the measure of the larger of the two angles, in degrees?', '["30","40","80","100"]', '100', '3*30+10', 'Same-side interior angles add to $180^\circ$: $(3x+10) + (2x+20) = 5x + 30 = 180$, so $x = 30$. The angles are $100^\circ$ and $80^\circ$, and the larger is 100. (If they were set equal, $x$ would be 10 and each angle 40: wrong.)', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+10) + (2x+20) = 5x + 30 = 180, x = 30. Angles 100 and 80. Larger 100.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bd37854-0c27-4c70-bbc9-f9a9018c16d6', 'NC26.8.SGMR.4', 2, 'choice', 'Same-side interior angles and parallel lines', 'Two same-side interior angles formed by parallel lines and a transversal differ by $20^\circ$. What is the measure of the smaller angle, in degrees?', '["80","90","100","160"]', '80', '(180-20)/2', 'The two angles add to $180^\circ$ and differ by 20. Taking 20 off the total leaves $160^\circ$ shared equally, so the smaller is $160 \div 2 = 80$ degrees and the larger is 100.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a + b = 180, a - b = 20: b = 80 (a = 100). Smaller 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7b27ebae-5c4b-47d3-bc28-104ebd4290ae', 'NC26.8.SGMR.4', 2, 'choice', 'Choose the angle relationship from the positions', 'Parallel lines $\ell$ (the upper line) and $m$ (the lower line) are crossed by a transversal $t$. Angle $p$ is at $\ell$, below $\ell$ and to the left of $t$. Angle $q$ is at $m$, above $m$ and to the right of $t$. Angle $p$ measures $(3x-5)^\circ$ and angle $q$ measures $(x+35)^\circ$. What is the measure of angle $p$, in degrees?', '["20","55","125","160"]', '55', '3*20-5', 'Both angles are between the parallel lines and on opposite sides of the transversal, so they are alternate interior angles and are equal: $3x - 5 = x + 35$, so $x = 20$. Angle $p$ is $3 \times 20 - 5 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p is below l (interior) left of t; q is above m (interior) right of t: alternate interior angles, equal. 3x - 5 = x + 35, x = 20. p = 55.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
