INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8750e179-07a6-4182-9e81-d0dc5b175af6', 'NC26.8.SGMR.4', 2, 'numeric', 'Choose the angle relationship from the positions', 'Parallel lines $\ell$ (the upper line) and $m$ (the lower line) are crossed by a transversal $t$. Angle $p$ is at $\ell$, below $\ell$ and to the left of $t$. Angle $q$ is at $m$, above $m$ and to the left of $t$. Angle $p$ measures $(2x+20)^\circ$ and angle $q$ measures $(x+40)^\circ$. What is the measure of the smaller of the two angles, in degrees?', '[]', '80', '40+40', 'Both angles are between the parallel lines and on the same side of the transversal, so they are same-side interior angles and add to $180^\circ$: $(2x+20) + (x+40) = 3x + 60 = 180$, so $x = 40$. The angles are $100^\circ$ and $80^\circ$, and the smaller is 80.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"p below l and q above m are both between the lines, both left of t: same-side interior, supplementary. (2x+20) + (x+40) = 3x + 60 = 180, x = 40. p = 100, q = 80. Smaller 80.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('862bed0b-6d00-4e38-b51c-2cb7543d996d', 'NC26.8.SGMR.4', 2, 'choice', 'Tell whether lines are parallel from angle measures', 'Lines $a$ and $b$ are crossed by a transversal. Which pair of angle measures shows that $a$ and $b$ are parallel?', '["Alternate interior angles of $70^\\circ$ and $110^\\circ$","Same-side interior angles of $70^\\circ$ and $70^\\circ$","Corresponding angles of $70^\\circ$ and $110^\\circ$","Alternate interior angles of $70^\\circ$ and $70^\\circ$"]', 'Alternate interior angles of $70^\circ$ and $70^\circ$', NULL, 'Lines are parallel when alternate interior (or corresponding) angles are equal, or when same-side interior angles add to $180^\circ$. Only alternate interior angles of $70^\circ$ and $70^\circ$ meet one of these tests. Same-side angles of 70 and 70 add to 140.', 'checked', '{"lint":[],"solve":{"answer":"Alternate interior angles of $70^\\circ$ and $70^\\circ$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal alternate interior angles prove the lines parallel. Same-side interior 70 + 70 = 140 is not 180; corresponding 70 and 110 are unequal; alternate interior 70 and 110 are unequal.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdb2b520-0747-4437-bd96-66612a543b3b', 'NC26.8.SGMR.4', 2, 'numeric', 'Tell whether lines are parallel from angle measures', 'Lines $\ell$ and $m$ are crossed by a transversal. A pair of alternate interior angles measure $(5x-9)^\circ$ and $(3x+17)^\circ$. For what value of $x$ are the lines $\ell$ and $m$ parallel?', '[]', '13', '(17+9)/2', 'The lines are parallel when alternate interior angles are equal: $5x - 9 = 3x + 17$, so $2x = 26$ and $x = 13$. (Each angle is $56^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel when alternate interior angles are equal: 5x - 9 = 3x + 17, 2x = 26, x = 13 (both 56).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('851a4e47-5e10-4bab-b4fb-9628f1a29d08', 'NC26.8.SGMR.4', 2, 'numeric', 'Multi-step angle problems with parallel lines', 'A transversal crosses two parallel lines. At one crossing, one angle is 3 times as large as an angle next to it, and the two angles form a linear pair. What is the measure of the smaller of the two angles, in degrees?', '[]', '45', '180/4', 'A linear pair adds to $180^\circ$. With parts 1 and 3, there are 4 equal parts: $180 \div 4 = 45$ degrees. The smaller angle is 45 degrees (and the larger is 135).', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Linear pair: x + 3x = 180, x = 45 (other 135).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('78508744-569b-4ce1-afcd-c4432342a433', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems with parallel lines', 'Parallel lines $\ell$ and $m$ are crossed by a transversal. Angle 1 is at $\ell$ and measures $52^\circ$. Angle 2 is the corresponding angle of angle 1, at $m$. Angle 3 forms a linear pair with angle 2. What is the measure of angle 3, in degrees?', '["38","52","128","142"]', '128', '180-52', 'Corresponding angles are equal, so angle 2 is $52^\circ$. Angle 3 forms a linear pair with angle 2, so it is $180 - 52 = 128$ degrees. The number 52 stops after the first step.', 'checked', '{"lint":[],"solve":{"answer":"128","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle 2 = 52 (corresponding). Angle 3 = 180 - 52 = 128.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ca61266-ce5a-4a14-ad33-dce76721b989', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems with parallel lines', 'A line is drawn through vertex $A$ of triangle $ABC$, parallel to side $BC$. On this line, the angle between the line and side $AB$ measures $48^\circ$ on one side of $A$, and the angle between the line and side $AC$ measures $65^\circ$ on the other side of $A$. Both of these angles lie outside the triangle. What is the measure of angle $BAC$, in degrees?', '["48","65","67","113"]', '67', '180-48-65', 'The two outside angles and angle $BAC$ fit together along the straight line through $A$, so they add to $180^\circ$. Angle $BAC$ is $180 - 48 - 65 = 67$ degrees. (Check: by alternate interior angles, $B = 48^\circ$ and $C = 65^\circ$, and $48 + 65 + 67 = 180$.) The number 113 is only $48 + 65$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The line through A is parallel to BC, so the 48 angle at AB equals angle B and the 65 angle at AC equals angle C (alternate interior). The three angles at A along the line sum to 180: BAC = 180 - 48 - 65 = 67.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67cd3cd7-4df0-4391-ae0e-7e54991892fa', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems with parallel lines', 'Parallel lines are crossed by a transversal. Angle $a$ is an interior angle at the upper line and measures $75^\circ$. Which angle must measure $105^\circ$?', '["The same-side interior angle of angle $a$","The angle vertical to angle $a$","The alternate interior angle of angle $a$","The corresponding angle of angle $a$"]', 'The same-side interior angle of angle $a$', NULL, 'Vertical, alternate interior and corresponding angles of angle $a$ are all equal to $75^\circ$ when the lines are parallel. The same-side interior angle is supplementary to angle $a$: $180 - 75 = 105$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"The same-side interior angle of angle $a$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same-side interior angle is supplementary: 180 - 75 = 105. Corresponding, vertical and alternate interior angles are all 75.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c81ca848-4d40-4fb4-a5d8-e64fa90c9b07', 'NC26.8.SGMR.4', 2, 'numeric', 'Multi-step angle problems with parallel lines', 'In triangle $ABC$, point $D$ is on side $AB$ and point $E$ is on side $AC$, and $DE$ is parallel to $BC$. Angle $ADE$ measures $62^\circ$ and angle $C$ measures $48^\circ$. What is the measure of angle $A$, in degrees?', '[]', '70', '180-62-48', 'Since $DE$ is parallel to $BC$, angle $ADE$ and angle $B$ are corresponding angles, so $B = 62^\circ$. Then $A = 180 - 62 - 48 = 70$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"DE parallel to BC, so angle ADE = angle B = 62 (corresponding). A = 180 - 62 - 48 = 70.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9919ecdf-ec2f-464a-9650-588dd43aeaa2', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems in triangles and around points', 'In triangle $ABC$, the exterior angle at $A$ measures $140^\circ$ and angles $B$ and $C$ are equal. What is the measure of angle $B$, in degrees?', '["20","40","70","140"]', '70', '140/2', 'The exterior angle at $A$ equals $B + C$. Since $B = C$, each is $140 \div 2 = 70$ degrees. (Check: angle $A$ is $180 - 140 = 40^\circ$, and $40 + 70 + 70 = 180$.)', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior at A = B + C = 140, B = C, so B = 70 (interior A = 40).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6f3efe3-59e9-4114-aa23-e74bdd96e082', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems in triangles and around points', 'In triangle $ABC$, angle $A$ measures $35^\circ$ and angle $B$ measures $85^\circ$. Side $AB$ is extended past $B$ to a point $D$. What is the measure of angle $CBD$, in degrees?', '["120","95","85","60"]', '95', '180-85', 'Angle $CBD$ is the exterior angle at $B$, so it equals $A + C$. Angle $C = 180 - 35 - 85 = 60$, so $CBD = 35 + 60 = 95$ degrees. (Also $180 - 85 = 95$.)', 'checked', '{"lint":[],"solve":{"answer":"95","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"CBD is the exterior angle at B: 180 - 85 = 95 (= A + C = 35 + 60).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7478343c-bbbd-4986-a0ac-0522bab94da6', 'NC26.8.SGMR.4', 2, 'choice', 'Multi-step angle problems in triangles and around points', 'A right triangle has an exterior angle of $115^\circ$ at the vertex of one of its acute angles. What is the measure of the other acute angle, in degrees?', '["25","65","90","115"]', '25', '90-(180-115)', 'The interior angle at that vertex is $180 - 115 = 65$ degrees. The acute angles of a right triangle add to $90^\circ$, so the other acute angle is $90 - 65 = 25$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior at an acute vertex = sum of the remote angles = 90 + other acute angle: 115 - 90 = 25. (Interior there is 65; 65 + 25 = 90.)","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c233f69c-ffc2-41c5-a43a-adff202fffe6', 'NC26.8.SGMR.4', 2, 'numeric', 'Multi-step angle problems in triangles and around points', 'In a triangle, the exterior angles at two of the vertices measure $130^\circ$ and $110^\circ$. What is the measure of the interior angle at the third vertex, in degrees?', '[]', '60', '180-(180-130)-(180-110)', 'The interior angles at those two vertices are $180 - 130 = 50$ degrees and $180 - 110 = 70$ degrees. The third interior angle is $180 - 50 - 70 = 60$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Interior angles at those vertices: 180 - 130 = 50 and 180 - 110 = 70. Third: 180 - 50 - 70 = 60.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('949c46c2-de6a-4c64-a2ed-f78efc709385', 'NC26.8.SGMR.4', 3, 'numeric', 'Exterior angle used to find an interior angle', 'In triangle $ABC$, angle $A$ measures $50^\circ$. The exterior angle at vertex $B$ (formed by extending a side of the triangle past $B$) measures $115^\circ$. What is the measure of angle $C$, in degrees?', '[]', '65', '115-50', 'The exterior angle at $B$ equals the sum of the two interior angles that are not next to it, angles $A$ and $C$. So $50 + C = 115$ and $C = 65$. Check: angle $B$ is $180 - 115 = 65$, and $50 + 65 + 65 = 180$.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle at B = A + C, so C = 115 - 50 = 65. Check: B = 180 - 115 = 65; 50 + 65 + 65 = 180.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3386c128-bccf-47a5-8f91-77f90f9a8a90', 'NC26.8.SGMR.4', 3, 'choice', 'Exterior angle with algebra', 'A triangle has an exterior angle that measures $(4x-10)^\circ$. The two interior angles that are not next to it measure $(x+20)^\circ$ and $(x+30)^\circ$. What is the measure of the exterior angle, in degrees?', '["30","70","110","120"]', '110', '4*30-10', 'The exterior angle equals the sum of the two far interior angles: $4x - 10 = (x+20) + (x+30) = 2x + 50$. So $2x = 60$ and $x = 30$. The exterior angle is $4(30) - 10 = 110^\circ$. Check: $50 + 60 = 110$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exterior angle = sum of remote interiors: 4x - 10 = (x+20) + (x+30) = 2x + 50 -> 2x = 60 -> x = 30. Exterior = 4(30) - 10 = 110 (remote interiors 50 and 60).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e59dc14-f6f3-4f76-af4a-c73b5312bdba', 'NC26.8.SGMR.4', 3, 'numeric', 'Multi-step angle problem with parallel lines', 'Two parallel lines are cut by a transversal. Two corresponding angles measure $(5x-12)^\circ$ and $(3x+18)^\circ$. What is the measure, in degrees, of an angle that forms a linear pair with the angle measuring $(5x-12)^\circ$?', '[]', '117', '180-(5*15-12)', 'Corresponding angles are equal, so $5x - 12 = 3x + 18$. Then $2x = 30$ and $x = 15$. The angle is $5(15) - 12 = 63^\circ$. A linear pair adds up to $180^\circ$, so the other angle is $180 - 63 = 117^\circ$.', 'checked', '{"lint":[],"solve":{"answer":"117","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corresponding angles equal: 5x - 12 = 3x + 18 -> 2x = 30 -> x = 15. Angle = 5(15) - 12 = 63. Linear pair: 180 - 63 = 117.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d090c423-90eb-4b06-a009-525940f69a41', 'NC26.8.SGMR.4', 3, 'numeric', 'Angle sum of a triangle', 'In triangle $ABC$, angle $C$ is a right angle and angle $A$ is $14^\circ$ larger than angle $B$. What is the measure of angle $B$, in degrees?', '[]', '38', '(90-14)/2', 'Angles $A$ and $B$ add to $90^\circ$. If $B = b$, then $b + (b + 14) = 90$, so $2b = 76$ and $b = 38$ degrees. (Then $A = 52^\circ$.)', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A + B = 90 and A = B + 14: 2B + 14 = 90, B = 38 (A = 52).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7aacc5e3-69d4-4cf5-be2a-58be26429d09', 'NC26.8.SGMR.4', 3, 'choice', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $(5x-10)^\circ$, $(3x+6)^\circ$ and $(2x+4)^\circ$. What is the measure of the smallest angle, in degrees?', '["80","60","40","18"]', '40', '2*18+4', '$(5x-10) + (3x+6) + (2x+4) = 10x = 180$, so $x = 18$. The angles are $80^\circ$, $60^\circ$ and $40^\circ$. The smallest is 40 degrees; 18 is only the value of $x$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5x-10)+(3x+6)+(2x+4) = 10x = 180, x = 18. Angles 80, 60, 40. Smallest 40.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c335f8d-6f3f-4db7-9a07-7796e7ee30d0', 'NC26.8.SGMR.4', 3, 'choice', 'Angle sum of a triangle with algebra', 'The angles of a triangle measure $x^\circ$, $(2x-15)^\circ$ and $(x+35)^\circ$. What is the measure of the largest angle, in degrees?', '["40","65","75","115"]', '75', '40+35', '$x + (2x-15) + (x+35) = 4x + 20 = 180$, so $4x = 160$ and $x = 40$. The angles are $40^\circ$, $65^\circ$ and $75^\circ$, so the largest is 75 degrees.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + (2x-15) + (x+35) = 4x + 20 = 180, x = 40. Angles 40, 65, 75. Largest 75.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('15299ddf-0610-462b-b231-2c2f59645018', 'NC26.8.SGMR.4', 3, 'numeric', 'Angle sum of a triangle with algebra', 'A right triangle has acute angles of $(3x+4)^\circ$ and $(2x+6)^\circ$. What is the measure of the larger acute angle, in degrees?', '[]', '52', '3*16+4', 'The acute angles of a right triangle add to $90^\circ$: $(3x+4) + (2x+6) = 5x + 10 = 90$, so $x = 16$. The angles are $52^\circ$ and $38^\circ$, and the larger is 52 degrees.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x+4) + (2x+6) = 5x + 10 = 90, x = 16. Angles 52 and 38. Larger 52.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61742964-3903-4ae4-9768-8c4b07e74398', 'NC26.8.SGMR.4', 3, 'numeric', 'Exterior angle from the two far interior angles', 'In triangle $ABC$, angle $A$ measures $35^\circ$ and angle $B$ is $15^\circ$ larger than angle $A$. Side $AC$ is extended past $C$ to a point $D$. What is the measure of angle $BCD$, in degrees?', '[]', '85', '35+(35+15)', 'Angle $B$ is $35 + 15 = 50$ degrees. The exterior angle $BCD$ equals $A + B = 35 + 50 = 85$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"85","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B = 35 + 15 = 50. Exterior angle BCD = A + B = 35 + 50 = 85.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1a865bd-4887-4ed3-abca-9e38fba16480', 'NC26.8.SGMR.4', 3, 'choice', 'Interior angle from an exterior angle', 'An exterior angle of a triangle measures $112^\circ$. The two interior angles that are not next to it are in the ratio $3:5$. What is the measure of the larger of these two angles, in degrees?', '["42","56","68","70"]', '70', '112/8*5', 'The two angles add to $112^\circ$ and are in 8 equal parts. One part is $112 \div 8 = 14$, so the angles are $3 \times 14 = 42$ and $5 \times 14 = 70$ degrees. The larger is 70.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remote angles sum to 112 in ratio 3:5: 8 parts, 14 each. Larger 5 x 14 = 70 (smaller 42).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae0c9cf2-415c-4873-8946-fb6421c834f6', 'NC26.8.SGMR.4', 3, 'numeric', 'Interior angle from an exterior angle', 'In isosceles triangle $ABC$ with $AB = AC$, side $CB$ is extended past $B$ to a point $D$. Angle $ABD$ measures $115^\circ$. What is the measure of angle $A$, in degrees?', '[]', '50', '180-2*(180-115)', 'Angle $ABD$ is the exterior angle at $B$, so the interior angle $B$ is $180 - 115 = 65$ degrees. Since $AB = AC$, angle $C$ is also $65^\circ$. Then angle $A = 180 - 65 - 65 = 50$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle ABD is exterior at B, so interior angle ABC = 180 - 115 = 65. AB = AC makes angles B and C equal: C = 65. A = 180 - 65 - 65 = 50.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a29f9464-ae75-433d-acb7-d79eab4221c6', 'NC26.8.SGMR.4', 3, 'choice', 'Exterior angles with algebra', 'In triangle $ABC$, the exterior angle at $C$ measures $(5x-20)^\circ$, angle $A$ measures $(2x)^\circ$ and angle $B$ measures $(x+10)^\circ$. What is the measure of the interior angle at $C$, in degrees?', '["15","30","55","125"]', '125', '180-(5*15-20)', '$5x - 20 = 2x + (x+10)$, so $2x = 30$ and $x = 15$. The exterior angle is $5 \times 15 - 20 = 55$ degrees, so the interior angle at $C$ is $180 - 55 = 125$ degrees. (Check: $30 + 25 + 125 = 180$.)', 'checked', '{"lint":[],"solve":{"answer":"125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 20 = 2x + (x+10) = 3x + 10, 2x = 30, x = 15. Exterior at C = 55, so interior C = 180 - 55 = 125. Check A = 30, B = 25: 30+25+125 = 180.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b50223a6-1c63-4fe7-8b17-2b6cb25575c4', 'NC26.8.SGMR.4', 3, 'choice', 'Exterior angles with algebra', 'An exterior angle of a triangle measures $(6x-4)^\circ$. The two interior angles not next to it measure $(2x+10)^\circ$ and $(3x-6)^\circ$. What is the measure of the larger of those two interior angles, in degrees?', '["136","44","26","18"]', '26', '2*8+10', '$6x - 4 = (2x+10) + (3x-6) = 5x + 4$, so $x = 8$. The two interior angles are $2 \times 8 + 10 = 26$ and $3 \times 8 - 6 = 18$ degrees, so the larger is 26. The exterior angle is 44 degrees.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 4 = (2x+10) + (3x-6) = 5x + 4, x = 8. Interior angles 26 and 18 (exterior 44). Larger 26.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e48e1204-cf79-42f1-bf18-0e2df27facea', 'NC26.8.SGMR.4', 3, 'numeric', 'Exterior angles with algebra', 'The angles of a triangle measure $x^\circ$, $(2x)^\circ$ and $(3x)^\circ$. One exterior angle is drawn at each vertex. What is the measure of the largest of these exterior angles, in degrees?', '[]', '150', '180-180/6', '$x + 2x + 3x = 180$, so $x = 30$ and the angles are $30^\circ$, $60^\circ$ and $90^\circ$. Each exterior angle is $180^\circ$ minus its interior angle: 150, 120 and 90 degrees. The largest is 150.', 'checked', '{"lint":[],"solve":{"answer":"150","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2x + 3x = 180, x = 30: angles 30, 60, 90. Exterior angles 150, 120, 90. Largest 150.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4ce6fde-de6f-42fa-a068-4f957440be44', 'NC26.8.SGMR.4', 3, 'numeric', 'Linear pairs and vertical angles', 'Two lines cross. Two angles that form a linear pair measure $(4x+20)^\circ$ and $(2x+10)^\circ$. What is the measure of the smaller of the two angles, in degrees?', '[]', '60', '2*25+10', '$(4x+20) + (2x+10) = 6x + 30 = 180$, so $x = 25$. The angles are $120^\circ$ and $60^\circ$, and the smaller is 60 degrees.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4x+20) + (2x+10) = 6x + 30 = 180, x = 25. Angles 120 and 60. Smaller 60.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
