INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47fc5457-bdbf-47dc-b0fa-7334b7bd2f8d', 'NC26.8.SGMR.4', 3, 'choice', 'Corresponding angles and parallel lines', 'Parallel lines $\ell$ and $m$ are crossed by a transversal. Two corresponding angles measure $(3x+7)^\circ$ and $(5x-33)^\circ$. What is the measure of each of these angles, in degrees?', '["133","113","67","20"]', '67', '3*20+7', 'Corresponding angles are equal: $3x + 7 = 5x - 33$, so $2x = 40$ and $x = 20$. Each angle is $3 \times 20 + 7 = 67$ degrees. The number 20 is only $x$.', 'checked', '{"lint":[],"solve":{"answer":"67","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 7 = 5x - 33, 2x = 40, x = 20. Each angle 3(20) + 7 = 67.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddadb9ac-5ddd-4348-948a-294891780bc1', 'NC26.8.SGMR.4', 3, 'choice', 'Alternate interior and exterior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two alternate interior angles measure $(6x-14)^\circ$ and $(4x+16)^\circ$. What is the measure of an angle that forms a linear pair with either of them, in degrees?', '["15","76","104","165"]', '104', '180-(6*15-14)', 'Alternate interior angles are equal: $6x - 14 = 4x + 16$, so $x = 15$. Each of these angles is $6 \times 15 - 14 = 76$ degrees, and an angle forming a linear pair with it is $180 - 76 = 104$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"104","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x - 14 = 4x + 16, x = 15. Each is 76. Linear pair: 180 - 76 = 104.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
