INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28447c43-98f6-428c-92a4-521857671f8b', 'NC26.8.SGMR.4', 3, 'numeric', 'Alternate interior and exterior angles and parallel lines', 'Angle 1 and angle 2 are alternate interior angles formed by parallel lines and a transversal. Angle 3 is vertical to angle 2. Angle 1 measures $(2x+31)^\circ$ and angle 3 measures $(5x-5)^\circ$. What is the measure of angle 3, in degrees?', '[]', '55', '5*12-5', 'Angle 1 equals angle 2 (alternate interior), and angle 2 equals angle 3 (vertical). So $2x + 31 = 5x - 5$, which gives $3x = 36$ and $x = 12$. Angle 3 is $5 \times 12 - 5 = 55$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angle 3 = angle 2 (vertical) = angle 1 (alternate interior). 2x + 31 = 5x - 5, 3x = 36, x = 12. Angle 3 = 5(12) - 5 = 55 (angle 1 = 55).","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7573cfee-ac24-4d0a-901f-a2fd63298b97', 'NC26.8.SGMR.4', 3, 'numeric', 'Same-side interior angles and parallel lines', 'Parallel lines are crossed by a transversal. Two same-side interior angles are in the ratio $2:7$. What is the measure of the larger angle, in degrees?', '[]', '140', '180/9*7', 'The angles add to $180^\circ$ and make $2 + 7 = 9$ equal parts. One part is $180 \div 9 = 20$ degrees. The larger angle is $7 \times 20 = 140$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"140","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2 + 7 = 9 parts = 180, 20 each. Larger 7 x 20 = 140.","run_id":"claude-code","at":"2026-10-17T20:29:29.830Z"}}', 'ai', NULL, NULL)
