INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37c4540b-b632-4cd5-ad9c-a9fa03cb13e5', 'NC26.8.SGMR.5', 1, 'choice', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 10 cm and one leg of 6 cm. Which is the length of the other leg, in centimeters?', '["4","8","16","64"]', '8', NULL, 'Subtract the square of the known leg from the square of the hypotenuse: $10^2 - 6^2 = 100 - 36 = 64$, and $\sqrt{64} = 8$. The other leg is 8 cm.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 100 - 36 = 64, b = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6cdbf137-be36-452e-b795-939792c3593d', 'NC26.8.SGMR.5', 1, 'choice', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 15 inches and one leg of 12 inches. Which is the length of the other leg, in inches?', '["81","27","9","3"]', '9', NULL, '$15^2 - 12^2 = 225 - 144 = 81$, and $\sqrt{81} = 9$. The other leg is 9 inches.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 225 - 144 = 81, b = 9.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a335d35-7c61-47b6-a4d1-886aa39281f7', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a leg (exact number)', 'A wire 25 meters long runs from the top of a straight pole to the ground, 15 meters from the base of the pole. The ground is level. How tall is the pole, in meters?', '[]', '20', NULL, 'The pole, the ground and the wire form a right triangle, and the wire is the hypotenuse. $25^2 - 15^2 = 625 - 225 = 400$, and $\sqrt{400} = 20$ meters.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Says ''straight pole'' rather than ''upright/vertical pole''; the right angle depends on the pole being vertical. Minor; intended reading is clear.","work":"Pole (assumed upright) and ground form the right angle; wire is hypotenuse. h^2 = 625 - 225 = 400, h = 20 m.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b264c495-c2d7-444b-978f-0eb0c99fea4b', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 26 cm and one leg of 10 cm. How long is the other leg, in centimeters?', '[]', '24', NULL, '$26^2 - 10^2 = 676 - 100 = 576$, and $\sqrt{576} = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 676 - 100 = 576, b = 24.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
