INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0681c7d2-de39-4895-a838-8d302c9ec73e', 'NC26.8.SGMR.5', 1, 'choice', 'Find a side as a square root or a rounded decimal', 'The two shorter sides of a right triangle measure 2 inches and 3 inches. What is the length of the longest side?', '["$\\sqrt{13}$ inches","5 inches","13 inches","$\\sqrt{5}$ inches"]', '$\sqrt{13}$ inches', NULL, 'The longest side is the hypotenuse. $c^2 = 2^2 + 3^2 = 4 + 9 = 13$, so $c = \sqrt{13}$ inches. (5 comes from adding the sides; 13 is $c^2$.)', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{13}$ inches","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 4 + 9 = 13, c = sqrt(13) inches.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7d210cd4-11e8-42c2-8087-69c40a3838fe', 'NC26.8.SGMR.5', 1, 'numeric', 'Find a side as a square root or a rounded decimal', 'The hypotenuse of a right triangle is 7 cm and one leg is 4 cm. What is the square of the length of the other leg, in square centimeters?', '[]', '33', '7^2-4^2', '$7^2 = 4^2 + b^2$, so $b^2 = 49 - 16 = 33$.', 'checked', '{"lint":[],"solve":{"answer":"33","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 49 - 16 = 33.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('481fa5c2-a065-4334-ab44-a065f4206e0c', 'NC26.8.SGMR.5', 1, 'choice', 'Converse: is the triangle a right triangle?', 'Which set of three side lengths forms a right triangle?', '["5, 6, 7","4, 6, 8","9, 12, 21","9, 12, 15"]', '9, 12, 15', NULL, 'Test the largest number as the hypotenuse. $9^2 + 12^2 = 81 + 144 = 225 = 15^2$, so 9, 12, 15 is a right triangle. For 5, 6, 7: $25 + 36 = 61$, not 49. For 4, 6, 8: $16 + 36 = 52$, not 64. For 9, 12, 21: $81 + 144 = 225$, not 441.', 'checked', '{"lint":[],"solve":{"answer":"9, 12, 15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4,6,8: 16+36=52 vs 64 no. 9,12,15: 81+144=225=15^2 yes. 9,12,21: 9+12=21 degenerate, and 225 vs 441 no. 5,6,7: 61 vs 49 no.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
