INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('013c8eb8-6aeb-40aa-835a-b602e7a2282e', 'NC26.8.SGMR.5', 1, 'numeric', 'Converse: is the triangle a right triangle?', 'A triangle has side lengths 15 cm, 20 cm and $x$ cm, where $x$ is the longest side. For what value of $x$ is the triangle a right triangle?', '[]', '25', NULL, 'For a right triangle $15^2 + 20^2 = x^2$. $225 + 400 = 625$, and $\sqrt{625} = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 = 225 + 400 = 625, x = 25.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03d42e42-40cd-47c5-ad03-ea39636f076e', 'NC26.8.SGMR.5', 1, 'choice', 'Converse: is the triangle a right triangle?', 'Does a triangle with side lengths 4 cm, 5 cm and 6 cm have a right angle?', '["No, because $4^2 + 5^2 = 41$, which is not $6^2 = 36$","Yes, because $4^2 + 5^2 = 6^2$","Yes, because $4 + 5 > 6$","Yes, because the three lengths are consecutive numbers"]', 'No, because $4^2 + 5^2 = 41$, which is not $6^2 = 36$', NULL, 'A triangle is a right triangle only if the squares of the two shorter sides add to the square of the longest side. $4^2 + 5^2 = 16 + 25 = 41$, but $6^2 = 36$. They are not equal, so there is no right angle.', 'checked', '{"lint":[],"solve":{"answer":"No, because $4^2 + 5^2 = 41$, which is not $6^2 = 36$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"16 + 25 = 41, 6^2 = 36; 41 is not 36 so by the converse there is no right angle.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae8334bc-a0f9-4a73-9b17-53fbefc78ef2', 'NC26.8.SGMR.5', 1, 'numeric', 'Distance on the coordinate plane', 'On a coordinate plane, point $A$ is at $(0, 0)$ and point $B$ is at $(6, 8)$. What is the distance from $A$ to $B$, in units?', '[]', '10', NULL, 'Go 6 units across and 8 units up to form a right triangle with legs 6 and 8. $6^2 + 8^2 = 36 + 64 = 100$, so the distance is $\sqrt{100} = 10$ units.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 6 and 8: d^2 = 36 + 64 = 100, d = 10.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7e7b036-444c-49ad-9e48-55a357cf0138', 'NC26.8.SGMR.5', 1, 'numeric', 'Distance on the coordinate plane', 'A right triangle on a coordinate plane has corners at $(1, 1)$, $(4, 1)$ and $(4, 5)$. How long is the side from $(1, 1)$ to $(4, 5)$, in units?', '[]', '5', NULL, 'The legs run from $(1, 1)$ to $(4, 1)$, which is 3 units, and from $(4, 1)$ to $(4, 5)$, which is 4 units. The side asked about is the hypotenuse: $3^2 + 4^2 = 25$, so its length is 5 units.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs: (1,1)-(4,1) is 3, (4,1)-(4,5) is 4. Hypotenuse = sqrt(9+16) = 5.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e3084b6-b9d4-464a-982f-4b696e800553', 'NC26.8.SGMR.5', 1, 'choice', 'Distance on the coordinate plane', 'To find the distance between $(2, 3)$ and $(8, 11)$, Kim draws a right triangle with one horizontal leg and one vertical leg. What are the lengths of the two legs?', '["10 and 14","2 and 3","8 and 11","6 and 8"]', '6 and 8', NULL, 'The horizontal leg is the change in $x$: $8 - 2 = 6$. The vertical leg is the change in $y$: $11 - 3 = 8$. Subtract the coordinates; do not add them.', 'checked', '{"lint":[],"solve":{"answer":"6 and 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Horizontal leg 8 - 2 = 6, vertical leg 11 - 3 = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9064b6e7-ceb9-4b5d-afba-d3ff1c1b93ec', 'NC26.8.SGMR.5', 1, 'choice', 'Distance on the coordinate plane', 'Which equation can be used to find the distance $d$ between $(0, 0)$ and $(5, 12)$?', '["$d^2 = 5^2 + 12^2$","$d = 5 + 12$","$d^2 = 12^2 - 5^2$","$d = 5^2 + 12^2$"]', '$d^2 = 5^2 + 12^2$', NULL, 'The legs of the right triangle are 5 and 12, and the distance $d$ is the hypotenuse. So $d^2 = 5^2 + 12^2$.', 'checked', '{"lint":[],"solve":{"answer":"$d^2 = 5^2 + 12^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 5 and 12, so d^2 = 5^2 + 12^2 (d = 13).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('667377a5-8a71-4007-a23c-5413472c696d', 'NC26.8.SGMR.5', 1, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A rectangular computer screen is 12 inches wide and 9 inches tall. How long is its diagonal, in inches?', '[]', '15', NULL, 'The width, height and diagonal form a right triangle. $12^2 + 9^2 = 144 + 81 = 225$, and $\sqrt{225} = 15$ inches.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 144 + 81 = 225, d = 15.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35d4ad0c-80e5-4242-b793-55cb932f3130', 'NC26.8.SGMR.5', 1, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A ramp rises 5 feet while it covers a horizontal distance of 12 feet. How long is the sloping surface of the ramp, in feet?', '[]', '13', NULL, 'The rise and the horizontal distance are the legs of a right triangle, and the ramp surface is the hypotenuse. $5^2 + 12^2 = 25 + 144 = 169$, and $\sqrt{169} = 13$ feet.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rise and run perpendicular: s^2 = 25 + 144 = 169, s = 13.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98c8408c-a88c-4e75-b747-8f1656996e9d', 'NC26.8.SGMR.5', 1, 'choice', 'Pythagorean Theorem in a real-world problem', 'A rectangular field is 24 meters long and 7 meters wide. How long is its diagonal, in meters?', '["17","25","31","625"]', '25', NULL, 'The length, width and diagonal form a right triangle. $24^2 + 7^2 = 576 + 49 = 625$, and $\sqrt{625} = 25$ meters.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 576 + 49 = 625, d = 25.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddca15ec-5dd1-4ba8-8c4e-e63f82b69f50', 'NC26.8.SGMR.5', 1, 'numeric', 'Pythagorean Theorem in a real-world problem', 'A treehouse floor is 15 feet above level ground. A rope ladder is pulled tight from the edge of the floor to a stake in the ground that is 8 feet from the base of the tree. How long is the rope ladder, in feet?', '[]', '17', NULL, 'The tree height and the distance to the stake are the legs, and the rope ladder is the hypotenuse. $15^2 + 8^2 = 225 + 64 = 289$, and $\sqrt{289} = 17$ feet.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"The 8 ft is measured from the tree''s base, but the ladder starts at the floor''s edge, which is not over the trunk; strictly the horizontal leg is unknown. Better: ''a stake 8 feet from the point directly below the edge of the floor''.","work":"Height 15 and ground distance 8 as legs: L^2 = 225 + 64 = 289, L = 17.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f57e3e74-3b05-42e0-aef6-cc90961fdc4b', 'NC26.8.SGMR.5', 1, 'numeric', 'Multi-step problems with right triangles', 'The legs of a right triangle are 5 cm and 12 cm. What is the perimeter of the triangle, in centimeters?', '[]', '30', '5+12+13', 'First find the hypotenuse: $5^2 + 12^2 = 169$, so it is 13 cm. The perimeter is $5 + 12 + 13 = 30$ cm.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hypotenuse sqrt(25+144) = 13. Perimeter 5 + 12 + 13 = 30.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3568dd8d-1ee6-4e54-bac2-644507e6d536', 'NC26.8.SGMR.5', 1, 'numeric', 'Multi-step problems with right triangles', 'A right triangle has a hypotenuse of 13 cm and one leg of 12 cm. What is the area of the triangle, in square centimeters?', '[]', '30', '12*5/2', 'The other leg is $\sqrt{13^2 - 12^2} = \sqrt{25} = 5$ cm. The two legs are the base and the height, so the area is $\frac{1}{2} \times 12 \times 5 = 30$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other leg sqrt(169 - 144) = 5. Area = (5 x 12)/2 = 30.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('289d0be1-06ce-4b23-a212-bbd388a9dd19', 'NC26.8.SGMR.5', 2, 'choice', 'Find the hypotenuse (square root answer)', 'The legs of a right triangle are 5 cm and 7 cm long. What is the length of the hypotenuse, in centimeters?', '["$74$","$12$","$\\sqrt{74}$","$\\sqrt{24}$"]', '$\sqrt{74}$', NULL, '$c^2 = 5^2 + 7^2 = 25 + 49 = 74$, so $c = \sqrt{74}$. (Adding the legs, $5 + 7 = 12$, is not the hypotenuse, and $74$ is $c^2$, not $c$.)', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{74}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 5^2 + 7^2 = 25 + 49 = 74, so c = sqrt(74).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6659e1c-20c9-4a0b-8bda-abf893a89600', 'NC26.8.SGMR.5', 2, 'numeric', 'Distance on the coordinate plane', 'Point $A$ is at $(1, 2)$ and point $B$ is at $(6, 14)$ on a coordinate plane. What is the distance from $A$ to $B$, in units?', '[]', '13', '(5^2+12^2)/13', 'The horizontal change is $6 - 1 = 5$ and the vertical change is $14 - 2 = 12$. These are the legs of a right triangle, so the distance is $\sqrt{5^2 + 12^2} = \sqrt{169} = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 6 - 1 = 5, dy = 14 - 2 = 12. d = sqrt(25 + 144) = sqrt(169) = 13.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('988f2dbc-3f69-4b15-ab84-cd5c118cfc91', 'NC26.8.SGMR.5', 2, 'choice', 'Converse of the Pythagorean Theorem', 'A triangle has side lengths 8 cm, 15 cm and 17 cm. Which statement is correct?', '["It is a right triangle, because $8^2+15^2=17^2$","It is not a right triangle, because $8+15\\ne 17$","It is not a right triangle, because $8^2+17^2\\ne 15^2$","It is not a right triangle, because its three sides are all different lengths"]', 'It is a right triangle, because $8^2+15^2=17^2$', NULL, 'Test the converse with the longest side as the hypotenuse: $8^2 + 15^2 = 64 + 225 = 289$ and $17^2 = 289$. The two are equal, so the triangle is a right triangle.', 'checked', '{"lint":[],"solve":{"answer":"It is a right triangle, because $8^2+15^2=17^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8^2 + 15^2 = 64 + 225 = 289 = 17^2, so by the converse it is a right triangle.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d0b028a-847d-43ba-ad63-a42f985fc4a7', 'NC26.8.SGMR.5', 2, 'choice', 'Choose or write the Pythagorean equation', 'A right triangle has hypotenuse $c$ and legs $a$ and $b$. Which expression is equal to $b^2$?', '["$a^2 - c^2$","$c^2 + a^2$","$c^2 - a^2$","$(c - a)^2$"]', '$c^2 - a^2$', NULL, 'Start from $a^2 + b^2 = c^2$ and subtract $a^2$ from both sides: $b^2 = c^2 - a^2$.', 'checked', '{"lint":[],"solve":{"answer":"$c^2 - a^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2 + b^2 = c^2 gives b^2 = c^2 - a^2.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00f87519-d686-4522-b50e-d3921c610d16', 'NC26.8.SGMR.5', 2, 'choice', 'Choose or write the Pythagorean equation', 'A 17-foot ladder leans against a house with its base 8 feet from the house. The top of the ladder reaches $h$ feet up the wall. Which equation can be used to find $h$?', '["$h^2 + 17^2 = 8^2$","$h + 8 = 17$","$h^2 = 17^2 + 8^2$","$h^2 + 8^2 = 17^2$"]', '$h^2 + 8^2 = 17^2$', NULL, 'The ladder is the hypotenuse (17 feet). The wall height $h$ and the distance 8 feet are the legs. So $h^2 + 8^2 = 17^2$.', 'checked', '{"lint":[],"solve":{"answer":"$h^2 + 8^2 = 17^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Wall height h and base 8 are legs, ladder 17 is hypotenuse: h^2 + 8^2 = 17^2 (h = 15).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a06bc51f-dafe-48bd-9cc7-406ac8c234cd', 'NC26.8.SGMR.5', 2, 'choice', 'Choose or write the Pythagorean equation', 'Which statement is NOT true for every right triangle with legs $a$ and $b$ and hypotenuse $c$?', '["$a + b = c$","$c$ is the longest side","$a^2 + b^2 = c^2$","$c^2 - a^2 = b^2$"]', '$a + b = c$', NULL, 'The squares add up, not the lengths: $a^2 + b^2 = c^2$. For example, the legs 3 and 4 give a hypotenuse of 5, and $3 + 4 = 7$, not 5. The other three statements are true for every right triangle.', 'checked', '{"lint":[],"solve":{"answer":"$a + b = c$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2+b^2=c^2, c longest, c^2-a^2=b^2 always true. a + b = c is never true (triangle inequality).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b3e61ee-efed-4189-bcba-161da73732e9', 'NC26.8.SGMR.5', 2, 'numeric', 'Verify the theorem and squares on the sides', 'Squares are drawn on the three sides of a right triangle. The squares on the two legs have side lengths 7 cm and 24 cm. What is the area of the square on the hypotenuse, in square centimeters?', '[]', '625', '7^2+24^2', 'The areas of the leg squares are $7^2 = 49$ and $24^2 = 576$. The square on the hypotenuse has area $49 + 576 = 625$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7^2 + 24^2 = 49 + 576 = 625.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2b707c94-efff-4f86-847a-939bd5baf2ab', 'NC26.8.SGMR.5', 2, 'numeric', 'Verify the theorem and squares on the sides', 'The square built on the hypotenuse of a right triangle has an area of 169 square centimeters. The square built on one leg has an area of 25 square centimeters. What is the side length of the square built on the other leg, in centimeters?', '[]', '12', NULL, 'The area of the square on the other leg is $169 - 25 = 144$ square centimeters. Its side length is $\sqrt{144} = 12$ cm.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area on other leg = 169 - 25 = 144, side = 12.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7a53b1d-dd20-4b1d-aef7-88df32510feb', 'NC26.8.SGMR.5', 2, 'choice', 'Converse: is the triangle a right triangle?', 'The squares built on the three sides of a triangle have areas of 18, 24 and 42 square centimeters. Which statement is correct?', '["It is not a right triangle, because the areas are not equal","It is a right triangle, because $18 + 24 = 42$","It is not a right triangle, because $18 + 24 \\ne 42$","It is not a right triangle, because $18 \\times 24 \\ne 42$"]', 'It is a right triangle, because $18 + 24 = 42$', NULL, 'If the squares on the two shorter sides add up to the square on the longest side, the triangle is a right triangle (the converse of the Pythagorean Theorem). $18 + 24 = 42$, so it is a right triangle.', 'checked', '{"lint":[],"solve":{"answer":"It is a right triangle, because $18 + 24 = 42$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18 + 24 = 42, so the squares of the two shorter sides sum to the square of the longest; by the converse it is a right triangle.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c12b234d-2519-45d1-98a3-c2ecacc3a853', 'NC26.8.SGMR.5', 2, 'choice', 'Converse: is the triangle a right triangle?', 'Which list gives the side lengths, in centimeters, of a right triangle?', '["20, 21, 30","11, 60, 62","20, 21, 29","10, 24, 27"]', '20, 21, 29', NULL, 'Test the longest side as the hypotenuse. $20^2 + 21^2 = 400 + 441 = 841 = 29^2$, so 20, 21, 29 works. The others do not: $20^2 + 21^2 = 841$, not $30^2 = 900$; $11^2 + 60^2 = 3721$, not $62^2 = 3844$; $10^2 + 24^2 = 676$, not $27^2 = 729$.', 'checked', '{"lint":[],"solve":{"answer":"20, 21, 29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10,24,27: 676 vs 729 no. 20,21,29: 400+441=841=29^2 yes. 20,21,30: 841 vs 900 no. 11,60,62: 3721 vs 3844 no.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fbb215a0-8699-472d-b904-5dc82ab327f0', 'NC26.8.SGMR.5', 2, 'numeric', 'Converse: is the triangle a right triangle?', 'Four triangles have these side lengths, in centimeters: (9, 12, 15), (7, 10, 12), (12, 35, 37) and (6, 7, 9). How many of the four are right triangles?', '[]', '2', NULL, 'Check each: $9^2 + 12^2 = 225 = 15^2$ (right). $7^2 + 10^2 = 149$, not $12^2 = 144$ (not right). $12^2 + 35^2 = 1369 = 37^2$ (right). $6^2 + 7^2 = 85$, not $9^2 = 81$ (not right). Two are right triangles.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(9,12,15): 225=225 yes. (7,10,12): 149 vs 144 no. (12,35,37): 144+1225=1369=37^2 yes. (6,7,9): 85 vs 81 no. Two.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
