INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1270e1c8-e6ec-471f-bef1-16ac33b93c26', 'NC26.8.SGMR.5', 2, 'choice', 'Converse: is the triangle a right triangle?', 'Marcus says a triangle with sides of 11 cm, 12 cm and 16 cm is a right triangle. Which response is correct?', '["He is right, because $11 + 12 > 16$","He is right, because 16 cm is the longest side","He is wrong, because no triangle has sides of 11, 12 and 16","He is wrong, because $11^2 + 12^2 = 265$, which is not $16^2 = 256$"]', 'He is wrong, because $11^2 + 12^2 = 265$, which is not $16^2 = 256$', NULL, 'For a right triangle the squares of the two shorter sides must add to the square of the longest side. $11^2 + 12^2 = 121 + 144 = 265$ but $16^2 = 256$. These are not equal, so it is not a right triangle.', 'checked', '{"lint":[],"solve":{"answer":"He is wrong, because $11^2 + 12^2 = 265$, which is not $16^2 = 256$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"121 + 144 = 265, 16^2 = 256, not equal, so not right.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('091d1183-ce02-4d2d-8dcd-cf11d5c5192e', 'NC26.8.SGMR.5', 2, 'numeric', 'Find the hypotenuse (exact number)', 'The legs of a right triangle are 1.2 m and 0.9 m long. How long is the hypotenuse, in meters?', '[]', '1.5', NULL, '$1.2^2 + 0.9^2 = 1.44 + 0.81 = 2.25$, and $\sqrt{2.25} = 1.5$ meters.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 1.44 + 0.81 = 2.25, c = 1.5.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5591cbf-249b-4781-bd44-9440d208069f', 'NC26.8.SGMR.5', 2, 'choice', 'Find the hypotenuse (exact number)', 'A right triangle has legs of 28 cm and 45 cm. Which is the length of its hypotenuse, in centimeters?', '["17","53","73","2809"]', '53', NULL, '$28^2 + 45^2 = 784 + 2025 = 2809$, and $\sqrt{2809} = 53$ cm. (73 is the sum of the legs; 2809 is the square of the hypotenuse.)', 'checked', '{"lint":[],"solve":{"answer":"53","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 784 + 2025 = 2809, c = 53.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcba4d54-7702-453e-97f6-bde4851b69e3', 'NC26.8.SGMR.5', 2, 'numeric', 'Find the hypotenuse (exact number)', 'A rectangle is 33 cm long and 56 cm wide. How long is a diagonal of the rectangle, in centimeters?', '[]', '65', NULL, 'A diagonal cuts the rectangle into two right triangles, with the diagonal as the hypotenuse. $33^2 + 56^2 = 1089 + 3136 = 4225$, and $\sqrt{4225} = 65$ cm.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d^2 = 1089 + 3136 = 4225, d = 65.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
