INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55588c75-31fa-4dcd-a6e4-1bba4f3cea58', 'NC26.8.SGMR.5', 2, 'numeric', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 65 cm and one leg of 16 cm. How long is the other leg, in centimeters?', '[]', '63', NULL, '$65^2 - 16^2 = 4225 - 256 = 3969$, and $\sqrt{3969} = 63$ cm.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 4225 - 256 = 3969, b = 63.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
