INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('108870cc-847b-4f3b-8941-28276dc2fce7', 'NC26.8.SGMR.5', 2, 'numeric', 'Find a side as a square root or a rounded decimal', 'The legs of a right triangle are 8 cm and 5 cm long. What is the length of the hypotenuse, to the nearest tenth of a centimeter?', '[]', '9.4', NULL, '$8^2 + 5^2 = 64 + 25 = 89$, so the hypotenuse is $\sqrt{89} \approx 9.43$, which is 9.4 cm to the nearest tenth.', 'checked', '{"lint":[],"solve":{"answer":"9.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 64 + 25 = 89, sqrt(89) = 9.434..., 9.4.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
