INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a1e4276-57c8-4d91-9bf3-0bcb61d6d852', 'NC26.8.SGMR.5', 2, 'choice', 'Find a side as a square root or a rounded decimal', 'A right triangle has a hypotenuse of 9 cm and one leg of 6 cm. What is the exact length of the other leg, in centimeters?', '["3","$\\sqrt{117}$","45","$\\sqrt{45}$"]', '$\sqrt{45}$', NULL, '$9^2 - 6^2 = 81 - 36 = 45$, so the other leg is $\sqrt{45}$ cm. (3 is the difference of the sides; $\sqrt{117}$ adds the squares instead of subtracting; 45 is the square of the leg.)', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{45}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 81 - 36 = 45, b = sqrt(45).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
