INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da45b8e4-4acd-445d-8ff0-e7d1ce0416a4', 'NC26.8.SGMR.5', 2, 'numeric', 'Find a side as a square root or a rounded decimal', 'A right triangle has a hypotenuse of 12 cm and one leg of 7 cm. To the nearest whole centimeter, how long is the other leg?', '[]', '10', NULL, '$12^2 - 7^2 = 144 - 49 = 95$, so the other leg is $\sqrt{95}$. Since $9^2 = 81$ and $10^2 = 100$, and 95 is closer to 100, $\sqrt{95} \approx 9.7$, which rounds to 10 cm.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 144 - 49 = 95, sqrt(95) = 9.75, nearest whole 10.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
