INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c945c876-5b79-49ce-9e40-93d825b6d1d1', 'NC26.8.SGMR.5', 2, 'numeric', 'Multi-step problems with right triangles', 'Eli can walk along two sides of a rectangular park, 60 meters and then 80 meters, or he can take the straight diagonal path across the park. How many meters shorter is the diagonal path?', '[]', '40', '60+80-100', 'The diagonal is the hypotenuse: $60^2 + 80^2 = 3600 + 6400 = 10000$, so it is 100 m. Walking the two sides is $60 + 80 = 140$ m. The diagonal saves $140 - 100 = 40$ meters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Diagonal sqrt(3600 + 6400) = 100. Along sides 140. 140 - 100 = 40 m shorter.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03c8d3e8-ae4b-48c4-a2d4-1df8a94fd6e6', 'NC26.8.SGMR.5', 2, 'numeric', 'Multi-step problems with right triangles', 'The diagonal of a rectangle is 17 cm and one side is 15 cm. What is the perimeter of the rectangle, in centimeters?', '[]', '46', '2*(15+8)', 'The other side is $\sqrt{17^2 - 15^2} = \sqrt{289 - 225} = \sqrt{64} = 8$ cm. The perimeter is $2 \times (15 + 8) = 46$ cm.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Other side sqrt(289 - 225) = 8. Perimeter 2(15 + 8) = 46.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d68baa91-ed4c-448e-bfe4-5e03111d8e3a', 'NC26.8.SGMR.5', 2, 'numeric', 'Multi-step problems with right triangles', 'A rectangle has a diagonal of 26 cm and a width of 10 cm. What is the area of the rectangle, in square centimeters?', '[]', '240', '10*24', 'The length is $\sqrt{26^2 - 10^2} = \sqrt{676 - 100} = \sqrt{576} = 24$ cm. The area is $10 \times 24 = 240$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Length sqrt(676 - 100) = 24. Area 24 x 10 = 240.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
