INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2637e58b-8633-4cf1-831d-a8d89a82597c', 'NC26.8.SGMR.5', 3, 'numeric', 'Distance between points with negative coordinates', 'Point $A$ is at $(-5, -2)$ and point $B$ is at $(2, 22)$ on a coordinate plane. What is the distance from $A$ to $B$, in units?', '[]', '25', '(7^2+24^2)/25', 'The horizontal change is $2 - (-5) = 7$ and the vertical change is $22 - (-2) = 24$. The distance is $\sqrt{7^2 + 24^2} = \sqrt{49 + 576} = \sqrt{625} = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 2 - (-5) = 7, dy = 22 - (-2) = 24. d = sqrt(49 + 576) = sqrt(625) = 25.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c10e86d-7d0b-4286-af0f-0818ce1e473c', 'NC26.8.SGMR.5', 3, 'choice', 'Distance on the coordinate plane (square root answer)', 'Point $P$ is at $(-2, 5)$ and point $Q$ is at $(3, -1)$ on a coordinate plane. What is the distance from $P$ to $Q$, in units?', '["$11$","$\\sqrt{61}$","$\\sqrt{17}$","$\\sqrt{11}$"]', '$\sqrt{61}$', NULL, 'The horizontal change is $3 - (-2) = 5$ and the vertical change is $5 - (-1) = 6$. The distance is $\sqrt{5^2 + 6^2} = \sqrt{25 + 36} = \sqrt{61}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\sqrt{61}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"dx = 3 - (-2) = 5, dy = -1 - 5 = -6. d = sqrt(25 + 36) = sqrt(61).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('778704a0-e33c-4792-b511-90236eb8c1f0', 'NC26.8.SGMR.5', 3, 'numeric', 'Pythagorean Theorem in an isosceles triangle', 'An isosceles triangle has two sides that are each 17 cm long and a base that is 16 cm long. What is the height of the triangle from the base to the opposite corner, in centimeters?', '[]', '15', '(17^2-8^2)/15', 'The height cuts the base into two halves of 8 cm and makes a right triangle with hypotenuse 17 cm. So $h^2 + 8^2 = 17^2$, which gives $h^2 = 289 - 64 = 225$ and $h = 15$ cm.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The height bisects the base: half-base 8, side 17. h = sqrt(17^2 - 8^2) = sqrt(289 - 64) = sqrt(225) = 15.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a5bfd88-b213-401f-bf12-a930405f6d82', 'NC26.8.SGMR.5', 3, 'choice', 'Choose or write the Pythagorean equation', 'The legs of a right triangle are $x$ and $x + 1$, and its hypotenuse is 5. Which equation is true?', '["$x^2 + x + 1 = 5^2$","$x + (x + 1) = 5$","$x^2 + (x + 1)^2 = 5$","$x^2 + (x + 1)^2 = 5^2$"]', '$x^2 + (x + 1)^2 = 5^2$', NULL, 'The sum of the squares of the two legs equals the square of the hypotenuse: $x^2 + (x + 1)^2 = 5^2$. Be careful to square the whole quantity $x + 1$ and to square the 5 as well.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 + (x + 1)^2 = 5^2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum of squares of legs equals square of hypotenuse: x^2 + (x+1)^2 = 5^2 (x = 3).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('de8e1cf2-68cb-472c-9dab-bbdd822aba04', 'NC26.8.SGMR.5', 3, 'choice', 'Choose or write the Pythagorean equation', 'Each leg of a right triangle is made 3 times as long. What happens to the length of the hypotenuse?', '["It is also multiplied by 3","It is multiplied by 9","It is increased by 3","It is multiplied by 6"]', 'It is also multiplied by 3', NULL, 'If the legs are $3a$ and $3b$, the hypotenuse squared is $9a^2 + 9b^2 = 9c^2$, so the new hypotenuse is $\sqrt{9c^2} = 3c$. For example, a 3-4-5 triangle becomes a 9-12-15 triangle.', 'checked', '{"lint":[],"solve":{"answer":"It is also multiplied by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3a)^2 + (3b)^2 = 9c^2, so new hypotenuse = 3c.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('381b47da-d139-49c4-b7b6-5f927412be30', 'NC26.8.SGMR.5', 3, 'numeric', 'Verify the theorem and squares on the sides', 'Squares are built on all three sides of a right triangle. The areas of the three squares add up to 450 square centimeters. What is the area of the square built on the hypotenuse, in square centimeters?', '[]', '225', '450/2', 'The squares on the legs add up to the square on the hypotenuse, so the three areas add to twice the hypotenuse square. $450 \div 2 = 225$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"225","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2 + b^2 = c^2, so total = 2c^2 = 450, c^2 = 225.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59cdd653-a1ab-449c-8805-4bd8c1dab9ae', 'NC26.8.SGMR.5', 3, 'choice', 'Verify the theorem and squares on the sides', 'Squares are drawn on the legs of a right triangle. Their areas are 144 square centimeters and 256 square centimeters. What is the perimeter of the triangle, in centimeters?', '["20","28","48","400"]', '48', '12+16+20', 'The legs are $\sqrt{144} = 12$ cm and $\sqrt{256} = 16$ cm. The hypotenuse squared is $144 + 256 = 400$, so the hypotenuse is 20 cm. The perimeter is $12 + 16 + 20 = 48$ cm.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs 12 and 16; hypotenuse area 400, side 20. Perimeter 12 + 16 + 20 = 48.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fecda2c6-1719-4d4e-879d-53a2f16dca0b', 'NC26.8.SGMR.5', 3, 'numeric', 'Verify the theorem and squares on the sides', 'A right triangle has legs of 9 cm and 40 cm. Squares are drawn on all three sides. How much greater is the area of the square on the hypotenuse than the area of the square on the longer leg, in square centimeters?', '[]', '81', '41^2-40^2', 'The hypotenuse is $\sqrt{9^2 + 40^2} = \sqrt{1681} = 41$ cm. The areas are $41^2 = 1681$ and $40^2 = 1600$, and the difference is $1681 - 1600 = 81$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Square on hypotenuse = 81 + 1600 = 1681; minus 1600 = 81 (the square on the shorter leg).","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0278dc84-99b0-4982-8e9b-32d62b9c424e', 'NC26.8.SGMR.5', 3, 'numeric', 'Find the hypotenuse (exact number)', 'The legs of a right triangle are 3.5 cm and 12 cm long. How long is the hypotenuse, in centimeters?', '[]', '12.5', NULL, '$3.5^2 + 12^2 = 12.25 + 144 = 156.25$, and $\sqrt{156.25} = 12.5$ cm.', 'checked', '{"lint":[],"solve":{"answer":"12.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 12.25 + 144 = 156.25, c = 12.5.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5180149a-a3e2-4130-b6fa-b0bbe636f75b', 'NC26.8.SGMR.5', 3, 'choice', 'Find the hypotenuse (exact number)', 'The legs of a right triangle are $\frac{3}{4}$ foot and 1 foot long. How long is the hypotenuse, in feet?', '["$\\frac{7}{4}$","$\\frac{25}{16}$","$\\frac{1}{4}$","$\\frac{5}{4}$"]', '$\frac{5}{4}$', NULL, '$\left(\frac{3}{4}\right)^2 + 1^2 = \frac{9}{16} + \frac{16}{16} = \frac{25}{16}$, and $\sqrt{\frac{25}{16}} = \frac{5}{4}$ foot. ($\frac{7}{4}$ adds the legs; $\frac{25}{16}$ is the square of the hypotenuse.)', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 9/16 + 1 = 25/16, c = 5/4.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('38f43c4a-1fb6-401f-8516-1b41750d613a', 'NC26.8.SGMR.5', 3, 'numeric', 'Find a leg (exact number)', 'The diagonal of a rectangle is 4.1 m and its shorter side is 0.9 m. How long is the longer side, in meters?', '[]', '4', NULL, '$4.1^2 - 0.9^2 = 16.81 - 0.81 = 16$, and $\sqrt{16} = 4$ meters.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L^2 = 16.81 - 0.81 = 16, L = 4.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2a12dad-4264-4785-a1dd-e428f7ca99a3', 'NC26.8.SGMR.5', 3, 'choice', 'Find a leg (exact number)', 'A right triangle has a hypotenuse of 50 cm and one leg of 14 cm. Which is the length of the other leg, in centimeters?', '["36","48","64","2304"]', '48', NULL, '$50^2 - 14^2 = 2500 - 196 = 2304$, and $\sqrt{2304} = 48$ cm. (36 subtracts the lengths; 64 adds them; 2304 is the square of the leg.)', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 2500 - 196 = 2304, b = 48.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2015a85c-44a5-41b5-99a0-3f3b883124e3', 'NC26.8.SGMR.5', 3, 'numeric', 'Find a side as a square root or a rounded decimal', 'The legs of a right triangle are 7 cm and 9 cm long. What is the length of the hypotenuse, to the nearest tenth of a centimeter?', '[]', '11.4', NULL, '$7^2 + 9^2 = 49 + 81 = 130$, and $\sqrt{130} \approx 11.40$, which is 11.4 cm to the nearest tenth.', 'checked', '{"lint":[],"solve":{"answer":"11.4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"c^2 = 49 + 81 = 130, sqrt(130) = 11.40..., 11.4.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5266f1c0-8a68-4d43-8ab9-8b25b26d5629', 'NC26.8.SGMR.5', 3, 'numeric', 'Find a side as a square root or a rounded decimal', 'A right triangle has a hypotenuse of 15 inches and one leg of 11 inches. To the nearest tenth of an inch, how long is the other leg?', '[]', '10.2', NULL, '$15^2 - 11^2 = 225 - 121 = 104$, and $\sqrt{104} \approx 10.20$, which is 10.2 inches to the nearest tenth.', 'checked', '{"lint":[],"solve":{"answer":"10.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b^2 = 225 - 121 = 104, sqrt(104) = 10.198..., 10.2.","run_id":"claude-code","at":"2026-10-18T01:02:43.712Z"}}', 'ai', NULL, NULL)
