INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3c83669-7e48-43fc-9270-a864bf7387b8', 'NC26.8.SGMR.6', 1, 'choice', 'Volume of a pyramid', 'Which formula gives the volume of a pyramid with base area $B$ and height $h$?', '["$V = \\frac{1}{3}Bh$","$V = Bh$","$V = \\frac{1}{2}Bh$","$V = 3Bh$"]', '$V = \frac{1}{3}Bh$', NULL, 'A pyramid holds one third as much as a prism with the same base and height. A prism has volume $Bh$, so the pyramid has $V = \frac{1}{3}Bh$.', 'checked', '{"lint":[],"solve":{"answer":"$V = \\frac{1}{3}Bh$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pyramid volume is one third of the prism with the same base and height: V = (1/3)Bh.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
