INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e72d6e35-5dd1-4ab5-aba6-afc15644d9ca', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a cone', 'The base of a cone has an area of $12\pi$ square centimeters and the cone is 9 centimeters tall. Its volume is $k\pi$ cubic centimeters. What is the value of $k$?', '[]', '36', '12*9/3', 'The volume is $\frac{1}{3} \times (\text{base area}) \times (\text{height}) = \frac{1}{3} \times 12\pi \times 9 = 36\pi$. So $k = 36$.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(12pi)(9) = 36pi, k = 36.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
