INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6c9ed07-cec1-4b78-8036-8ad89d9aecca', 'NC26.8.SGMR.6', 1, 'choice', 'Volume of a sphere', 'Which formula gives the volume of a sphere with radius $r$?', '["$V = \\frac{4}{3}\\pi r^2$","$V = 4\\pi r^2$","$V = \\frac{4}{3}\\pi r^3$","$V = \\frac{1}{3}\\pi r^3$"]', '$V = \frac{4}{3}\pi r^3$', NULL, 'The volume of a sphere is $\frac{4}{3}\pi r^3$. ($4\pi r^2$ is the surface area, not the volume.)', 'checked', '{"lint":[],"solve":{"answer":"$V = \\frac{4}{3}\\pi r^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)pi r^3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
