INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82cdfd62-fc22-4468-80e4-55a61580c578', 'NC26.8.SGMR.6', 1, 'choice', 'Volume of a sphere', 'What is the volume of a sphere with a radius of 6 inches, in cubic inches?', '["$72\\pi$","$216\\pi$","$144\\pi$","$288\\pi$"]', '$288\pi$', NULL, '$V = \frac{4}{3}\pi r^3 = \frac{4}{3}\pi (6^3) = \frac{4}{3} \times 216 \times \pi = 288\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$288\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)pi(216) = 288pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
