INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43f02a35-f88e-4de1-b80a-7139394a60aa', 'NC26.8.SGMR.6', 1, 'numeric', 'Surface area of a pyramid', 'A triangular face of a square pyramid has a base of 10 cm and a height (the slant height of the pyramid) of 8 cm. What is the area of that face, in square centimeters?', '[]', '40', '10*8/2', 'The area of a triangle is $\frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 10 \times 8 = 40$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Area = (1/2)(10)(8) = 40.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
