INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3dc678c1-4335-45e1-acd0-1d8c2a1173f2', 'NC26.8.SGMR.6', 1, 'choice', 'Surface area of a pyramid', 'Which is the correct way to find the total surface area of a square pyramid?', '["Add the area of the base and the areas of the four triangular faces","Find the area of the base only","Add the areas of the four triangular faces only","Multiply the area of the base by the slant height"]', 'Add the area of the base and the areas of the four triangular faces', NULL, 'The surface of a square pyramid is made of one square base and four triangular faces. The total surface area is the sum of all five areas.', 'checked', '{"lint":[],"solve":{"answer":"Add the area of the base and the areas of the four triangular faces","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total surface area = base + all four lateral triangles.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('437bde0e-20cb-4d69-8c34-eb501967529b', 'NC26.8.SGMR.6', 1, 'numeric', 'Surface area of a pyramid', 'A square pyramid has a base edge of 6 cm and a slant height of 5 cm. What is the combined area of its four triangular faces, in square centimeters?', '[]', '60', '4*6*5/2', 'Each triangular face has a base of 6 cm and a height (the slant height) of 5 cm, so its area is $\frac{1}{2} \times 6 \times 5 = 15$ square centimeters. Four faces: $4 \times 15 = 60$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2)(6)(5) = 60.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90a8503b-a989-4255-bc35-9eea300541c8', 'NC26.8.SGMR.6', 1, 'numeric', 'Compare a cone or pyramid with a cylinder or prism', 'A cone and a cylinder have the same base and the same height. The cone has a volume of 15 cubic centimeters. What is the volume of the cylinder, in cubic centimeters?', '[]', '45', '15*3', 'A cone is one third of the cylinder with the same base and height, so the cylinder holds 3 times as much: $15 \times 3 = 45$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder = 3 x cone = 3 x 15 = 45.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1acd469-8f25-4bda-abe8-c82b53810b10', 'NC26.8.SGMR.6', 1, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A pyramid and a prism have the same base and the same height. How does the pyramid''s volume compare with the prism''s volume?', '["It is $\\frac{1}{2}$ of the prism''s volume","It is $\\frac{1}{3}$ of the prism''s volume","It is equal to the prism''s volume","It is 3 times the prism''s volume"]', 'It is $\frac{1}{3}$ of the prism''s volume', NULL, 'A pyramid takes up exactly one third of the volume of a prism with the same base and height.', 'checked', '{"lint":[],"solve":{"answer":"It is $\\frac{1}{3}$ of the prism''s volume","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V_pyramid = (1/3)Bh = (1/3)V_prism.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d00b4ab6-c28c-4d59-9d92-851199a0fa6b', 'NC26.8.SGMR.6', 1, 'numeric', 'Compare a cone or pyramid with a cylinder or prism', 'A cone-shaped paper cup is filled with sand. The sand is poured into a cylinder with the same radius and the same height as the cup. The cup is filled again and poured in again, and so on. How many full cups of sand are needed to fill the cylinder?', '[]', '3', NULL, 'The cone has one third of the cylinder''s volume, so it takes 3 full cones to fill the cylinder.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone is 1/3 of the cylinder with same base and height, so 3 cups.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('299eabe7-98bf-4554-b590-9c10d60f572f', 'NC26.8.SGMR.6', 1, 'numeric', 'Find a missing dimension from a volume', 'A pyramid has a volume of 60 cubic centimeters and a base area of 20 square centimeters. What is its height, in centimeters?', '[]', '9', '60*3/20', 'Use $V = \frac{1}{3}Bh$: $60 = \frac{1}{3} \times 20 \times h$. Multiply both sides by 3: $180 = 20h$, so $h = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60 = (1/3)(20)h -> h = 9.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c03721f-e26b-43b0-a234-67534c425b75', 'NC26.8.SGMR.6', 1, 'numeric', 'Find a missing dimension from a volume', 'A cone has a volume of $27\pi$ cubic centimeters and a base area of $9\pi$ square centimeters. What is its height, in centimeters?', '[]', '9', '27*3/9', 'Use $V = \frac{1}{3}Bh$: $27\pi = \frac{1}{3} \times 9\pi \times h$. Multiply both sides by 3: $81\pi = 9\pi h$, so $h = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27pi = (1/3)(9pi)h = 3pi h -> h = 9.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aafb343a-51bc-4f08-bfa1-029ff0c095ec', 'NC26.8.SGMR.6', 1, 'choice', 'Find a missing dimension from a volume', 'A pyramid has a volume of 48 cubic centimeters and a height of 6 centimeters. What is the area of its base, in square centimeters?', '["8","12","24","144"]', '24', '48*3/6', 'Use $V = \frac{1}{3}Bh$: $48 = \frac{1}{3} \times B \times 6 = 2B$, so $B = 24$ square centimeters. (8 forgets the one third.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48 = (1/3)B(6) = 2B -> B = 24.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
