INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9582bd8-db29-487a-99be-34e69be649d8', 'NC26.8.SGMR.6', 1, 'choice', 'Volume problems in context', 'A funnel is shaped like a cone with a radius of 2 inches and a height of 9 inches. When full, how many cubic inches of water does it hold?', '["$36\\pi$","$6\\pi$","$18\\pi$","$12\\pi$"]', '$12\pi$', NULL, '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (2^2)(9) = \frac{1}{3} \times 4 \times 9 \times \pi = 12\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$12\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi(4)(9) = 12pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
