INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1179a326-28af-4854-aead-fff13ef665f7', 'NC26.8.SGMR.6', 1, 'numeric', 'Volume of a composite solid', 'A solid is a cylinder with a cone attached on top. The cone has the same radius and the same height as the cylinder. The cylinder has a volume of 24 cubic centimeters. What is the volume of the whole solid, in cubic centimeters?', '[]', '32', '24+24/3', 'The cone has one third of the cylinder''s volume: $24 \div 3 = 8$ cubic centimeters. The whole solid is $24 + 8 = 32$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone = 24/3 = 8; total 24 + 8 = 32.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
