INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3024b948-8e6f-445d-8a22-cc0fc76ed7b8', 'NC26.8.SGMR.6', 1, 'numeric', 'Surface area of a pyramid', 'A pyramid has a base that is a regular hexagon. How many triangular faces does the pyramid have?', '[]', '6', NULL, 'A hexagon has 6 sides, and each side of the base meets one triangular face. So the pyramid has 6 triangular faces (and 7 faces in all, counting the base).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hexagon has 6 edges, so 6 triangular faces meet at the apex.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
