INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('956276ca-4920-44ab-924b-bb780feab61e', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a pyramid', 'A glass paperweight is shaped like a square pyramid. Its base edge is 9 cm and its height is 12 cm. How much glass is in it, in cubic centimeters?', '["108","324","486","972"]', '324', '9*9*12/3', 'The base area is $9 \times 9 = 81$ square centimeters. The volume is $\frac{1}{3} \times 81 \times 12 = 324$ cubic centimeters. (972 forgets the one third; 486 uses one half; 108 uses a base area of 9.)', 'checked', '{"lint":[],"solve":{"answer":"324","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(81)(12) = 324.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
