INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4339507-c550-480a-bbad-8e1dcf39c59f', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a cone', 'A cone has a base with a diameter of 10 cm and a height of 6 cm. What is its volume, in cubic centimeters?', '["$200\\pi$","$150\\pi$","$10\\pi$","$50\\pi$"]', '$50\pi$', NULL, 'The radius is half the diameter: $10 \div 2 = 5$ cm. $V = \frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (5^2)(6) = 50\pi$ cubic centimeters. (200 uses the diameter as the radius.)', 'checked', '{"lint":[],"solve":{"answer":"$50\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 5; V = (1/3)pi(25)(6) = 50pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('314dc427-148a-4232-9824-97bd246e73e8', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a cone', 'A cone has a radius of 4 cm and a height of 9 cm. Use 3.14 for $\pi$. What is the volume of the cone, in cubic centimeters?', '[]', '150.72', '3.14*16*9/3', '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3} \times 3.14 \times 16 \times 9 = 3.14 \times 48 = 150.72$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"150.72","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(3.14)(16)(9) = 3.14 x 48 = 150.72.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5deb16e-547d-4dec-a64e-87b18fd9eae5', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a cone', 'A cone has a radius of 7 cm and a height of 6 cm. Use $\frac{22}{7}$ for $\pi$. What is the volume of the cone, in cubic centimeters?', '[]', '308', '22/7*49*6/3', '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3} \times \frac{22}{7} \times 49 \times 6$. Since $\frac{22}{7} \times 49 = 154$, this is $\frac{1}{3} \times 154 \times 6 = 308$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"308","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(22/7)(49)(6) = (22/7)(98) = 308.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1bc6453-b9a9-4f53-ac9c-694866984a51', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a cone', 'The circular base of a cone has a circumference of $12\pi$ cm, and the cone is 5 cm tall. What is its volume, in cubic centimeters?', '["$60\\pi$","$240\\pi$","$180\\pi$","$30\\pi$"]', '$60\pi$', NULL, 'The circumference is $2\pi r = 12\pi$, so the radius is 6 cm. $V = \frac{1}{3}\pi (6^2)(5) = \frac{1}{3} \times 36 \times 5 \times \pi = 60\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$60\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2pi r = 12pi -> r = 6; V = (1/3)pi(36)(5) = 60pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db7ee3d1-7478-4a78-96bd-9bd09accf976', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a sphere', 'A sphere has a diameter of 18 cm. What is its volume, in cubic centimeters?', '["$7776\\pi$","$108\\pi$","$243\\pi$","$972\\pi$"]', '$972\pi$', NULL, 'The radius is $18 \div 2 = 9$ cm. $V = \frac{4}{3}\pi (9^3) = \frac{4}{3} \times 729 \times \pi = 972\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$972\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 9; V = (4/3)pi(729) = 972pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5af7b86-c1ea-4310-b4fb-5e95b3376d26', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a sphere', 'A marble is a sphere with a radius of 1.5 cm. Use 3.14 for $\pi$. What is the volume of the marble, in cubic centimeters?', '[]', '14.13', '4/3*3.14*1.5^3', '$V = \frac{4}{3}\pi r^3 = \frac{4}{3} \times 3.14 \times 1.5^3 = \frac{4}{3} \times 3.14 \times 3.375 = 3.14 \times 4.5 = 14.13$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"14.13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (4/3)(3.14)(1.5^3) = (4/3)(3.14)(3.375) = 3.14 x 4.5 = 14.13.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c52d071-e481-446a-9c9a-a1a484501ecd', 'NC26.8.SGMR.6', 2, 'choice', 'Volume of a sphere', 'Which expression gives the volume of a sphere with a diameter of 8 cm?', '["$\\frac{4}{3}\\pi(4)^3$","$\\frac{4}{3}\\pi(8)^3$","$\\frac{4}{3}\\pi(4)^2$","$\\frac{1}{3}\\pi(4)^3$"]', '$\frac{4}{3}\pi(4)^3$', NULL, 'The radius is half of the diameter, so $r = 4$ cm. The volume is $\frac{4}{3}\pi r^3 = \frac{4}{3}\pi(4)^3$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{4}{3}\\pi(4)^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r = 4; V = (4/3)pi(4)^3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ab4530f-70b3-4da8-b0ec-8c132cdbe3cd', 'NC26.8.SGMR.6', 2, 'numeric', 'Surface area of a pyramid', 'A model of a square pyramid is covered in paper on all five faces, including the bottom. The base edge is 12 cm and the slant height is 10 cm. How many square centimeters of paper are needed? (Ignore any overlap.)', '[]', '384', '12*12+4*12*10/2', 'The base is $12 \times 12 = 144$ square centimeters. Each triangular face is $\frac{1}{2} \times 12 \times 10 = 60$ square centimeters, so the four faces are $240$. The total is $144 + 240 = 384$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"384","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 144 + 4 x (1/2)(12)(10) = 144 + 240 = 384.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ae03fed-0f56-4752-83e4-4086bb17944b', 'NC26.8.SGMR.6', 2, 'choice', 'Surface area of a pyramid', 'A square pyramid has a base edge of 14 m and a slant height of 9 m. What is the combined area of its four triangular faces (not counting the base), in square meters?', '["63","252","448","504"]', '252', '4*14*9/2', 'Each triangular face is $\frac{1}{2} \times 14 \times 9 = 63$ square meters, so four faces are $4 \times 63 = 252$ square meters. (63 is one face; 504 forgets the one half; 448 adds the base.)', 'checked', '{"lint":[],"solve":{"answer":"252","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2)(14)(9) = 252.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2ff1757f-e37f-4f85-8637-5a22945b5cbf', 'NC26.8.SGMR.6', 2, 'choice', 'Surface area of a pyramid', 'Which expression gives the total surface area of a square pyramid with a base edge of 8 m and a slant height of 6 m?', '["$8^2 + \\frac{1}{2}(8)(6)$","$4 \\cdot \\frac{1}{2}(8)(6)$","$8^2 + 4 \\cdot \\frac{1}{2}(8)(6)$","$8^2 + 4(8)(6)$"]', '$8^2 + 4 \cdot \frac{1}{2}(8)(6)$', NULL, 'The base is a square with area $8^2$. Each of the 4 triangular faces has area $\frac{1}{2}(8)(6)$. The total is $8^2 + 4 \cdot \frac{1}{2}(8)(6)$.', 'checked', '{"lint":[],"solve":{"answer":"$8^2 + 4 \\cdot \\frac{1}{2}(8)(6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 8^2 plus four triangles 4 x (1/2)(8)(6).","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('21adabd0-4742-4d3f-a425-0a2b6acbc1f2', 'NC26.8.SGMR.6', 2, 'numeric', 'Surface area of a pyramid', 'A pyramid with a triangular base has four faces (including the base) that are all identical triangles. Each triangle has a base of 6 cm and a height of 5 cm. What is the total surface area of the pyramid, in square centimeters?', '[]', '60', '4*6*5/2', 'Each face has area $\frac{1}{2} \times 6 \times 5 = 15$ square centimeters. There are 4 identical faces, so the total is $4 \times 15 = 60$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x (1/2)(6)(5) = 60. (Consistent: isosceles 6, sqrt34, sqrt34 is acute, so a tetrahedron with four such faces exists.)","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
