INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0605c9bd-bb48-4d38-9210-1c76ce5c0164', 'NC26.8.SGMR.6', 2, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A cylinder with a radius of 5 cm and a height of 12 cm has a volume of $300\pi$ cubic centimeters. A cone has the same radius and the same height. What is the volume of the cone, in cubic centimeters?', '["$900\\pi$","$150\\pi$","$300\\pi$","$100\\pi$"]', '$100\pi$', NULL, 'A cone has one third of the volume of a cylinder with the same radius and height: $300\pi \div 3 = 100\pi$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"$100\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cone = 300pi / 3 = 100pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
