INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d5679fd-1826-4f10-ae83-db8e4ac84ed1', 'NC26.8.SGMR.6', 2, 'choice', 'Compare a cone or pyramid with a cylinder or prism', 'A prism and a pyramid both have a base area of 36 square centimeters and a height of 10 centimeters. How many cubic centimeters more volume does the prism have than the pyramid?', '["120","180","240","360"]', '240', '36*10-36*10/3', 'The prism has volume $36 \times 10 = 360$ and the pyramid has $\frac{1}{3} \times 360 = 120$. The difference is $360 - 120 = 240$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"240","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prism 360, pyramid 120; difference 240.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
