INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('58f3cda7-7c98-4374-9c5e-a31e2e46ad28', 'NC26.8.SGMR.6', 2, 'numeric', 'Compare a cone or pyramid with a cylinder or prism', 'A pyramid is 15 cm tall and has a volume of 100 cubic centimeters. A prism has the same base as the pyramid and is 6 cm tall. What is the volume of the prism, in cubic centimeters?', '[]', '120', '100*3/15*6', 'From $100 = \frac{1}{3} \times B \times 15 = 5B$, the base area is $B = 20$ square centimeters. The prism has volume $B \times 6 = 20 \times 6 = 120$ cubic centimeters.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 = (1/3)B(15) = 5B -> B = 20. Prism 20 x 6 = 120.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53ceabe1-bab9-48be-8bf0-19833d981943', 'NC26.8.SGMR.6', 2, 'choice', 'Compare a sphere, a cone and a cylinder', 'A cylinder has radius $r$ and height $2r$. A sphere has radius $r$. What fraction of the cylinder''s volume is the sphere''s volume?', '["$\\frac{2}{3}$","$\\frac{1}{3}$","$\\frac{1}{2}$","$\\frac{3}{4}$"]', '$\frac{2}{3}$', NULL, 'The cylinder''s volume is $\pi r^2 (2r) = 2\pi r^3$. The sphere''s volume is $\frac{4}{3}\pi r^3$. The ratio is $\frac{4/3}{2} = \frac{2}{3}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sphere (4/3)pi r^3, cylinder pi r^2(2r) = 2pi r^3. Ratio (4/3)/2 = 2/3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a31f227-02e3-4ebf-be13-248d83415d45', 'NC26.8.SGMR.6', 2, 'choice', 'Find a missing dimension from a volume', 'A cone has a radius of 5 cm and a volume of $100\pi$ cubic centimeters. What is its height, in centimeters?', '["4","12","20","60"]', '12', '100*3/25', 'Use $V = \frac{1}{3}\pi r^2 h$: $100\pi = \frac{1}{3}\pi (25) h$. So $300 = 25h$ and $h = 12$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100pi = (1/3)pi(25)h -> h = 12.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f14e8adf-674c-485b-9858-188a2e64606e', 'NC26.8.SGMR.6', 2, 'numeric', 'Find a missing dimension from a volume', 'A square pyramid has a volume of 96 cubic centimeters and a height of 8 centimeters. What is the length of one edge of its base, in centimeters?', '[]', '6', NULL, 'Use $V = \frac{1}{3}Bh$: $96 = \frac{1}{3} \times B \times 8$, so $B = 96 \times 3 \div 8 = 36$ square centimeters. The base is a square with area 36, so each edge is $\sqrt{36} = 6$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"96 = (1/3)s^2(8) -> s^2 = 36 -> s = 6.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31148311-be4a-4261-8571-cc013a3d8f33', 'NC26.8.SGMR.6', 2, 'choice', 'Find a missing dimension from a volume', 'A sphere has a volume of $36\pi$ cubic inches. What is its radius, in inches?', '["27","9","6","3"]', '3', NULL, 'Set $\frac{4}{3}\pi r^3 = 36\pi$. Then $\frac{4}{3}r^3 = 36$, so $r^3 = 27$ and $r = 3$ inches.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"36pi = (4/3)pi r^3 -> r^3 = 27 -> r = 3.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5af14d8a-a105-475f-ac58-61bf494b3106', 'NC26.8.SGMR.6', 2, 'numeric', 'Find a missing dimension from a volume', 'A pyramid has a rectangular base that is 6 m by 10 m. Its volume is 160 cubic meters. What is its height, in meters?', '[]', '8', '160*3/(6*10)', 'The base area is $6 \times 10 = 60$ square meters. From $160 = \frac{1}{3} \times 60 \times h = 20h$, $h = 8$ meters.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"160 = (1/3)(60)h = 20h -> h = 8.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d83985dd-21dc-43c3-8b80-5be3e17a5181', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume problems in context', 'A pile of gravel is shaped like a cone. It is 6 feet tall and its base has a radius of 5 feet. Use 3.14 for $\pi$. How many cubic feet of gravel are in the pile?', '[]', '157', '3.14*25*6/3', '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3} \times 3.14 \times 25 \times 6 = 3.14 \times 50 = 157$ cubic feet.', 'checked', '{"lint":[],"solve":{"answer":"157","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)(3.14)(25)(6) = 3.14 x 50 = 157.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
