INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('33578371-71ce-47a4-989d-e63247ee642f', 'NC26.8.SGMR.6', 2, 'choice', 'Volume problems in context', 'A paper cone for roasted nuts is 9 inches tall, and its opening has a radius of 5 inches. When it is filled to the top, how many cubic inches does it hold?', '["$75\\pi$","$225\\pi$","$300\\pi$","$15\\pi$"]', '$75\pi$', NULL, '$V = \frac{1}{3}\pi r^2 h = \frac{1}{3}\pi (5^2)(9) = \frac{1}{3} \times 25 \times 9 \times \pi = 75\pi$ cubic inches.', 'checked', '{"lint":[],"solve":{"answer":"$75\\pi$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = (1/3)pi(25)(9) = 75pi.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
