INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45de4111-b000-4e01-8bae-745a7d55e9b5', 'NC26.8.SGMR.6', 2, 'numeric', 'Volume of a composite solid', 'A storage bin is a cylinder with a cone-shaped roof. The cylinder has a radius of 3 m and a height of 5 m. The cone has the same radius and a height of 3 m. Use 3.14 for $\pi$. What is the total volume of the bin, in cubic meters?', '[]', '169.56', '3.14*9*5+3.14*9*3/3', 'Cylinder: $3.14 \times 3^2 \times 5 = 141.3$. Cone: $\frac{1}{3} \times 3.14 \times 3^2 \times 3 = 28.26$. Total: $141.3 + 28.26 = 169.56$ cubic meters.', 'checked', '{"lint":[],"solve":{"answer":"169.56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cylinder pi(9)(5) = 45pi; cone (1/3)pi(9)(3) = 9pi; total 54pi = 54 x 3.14 = 169.56.","run_id":"claude-code","at":"2026-10-18T01:02:43.750Z"}}', 'ai', NULL, NULL)
