INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ce81bb0b-c61c-4358-b301-be947628661d', 'NC26.8.RD.1', 1, 'choice', 'Tell mutually exclusive events from inclusive events', 'One day of the week is chosen at random. Which pair of events is NOT mutually exclusive?', '["The day is a Monday; the day is a Friday","The day is a Tuesday; the day is a Thursday","The day is a Sunday; the day is a Wednesday","The day is on a weekend; the day is a Saturday"]', 'The day is on a weekend; the day is a Saturday', NULL, 'Saturday is a weekend day, so both events happen when Saturday is chosen. The other pairs name two different days, so they cannot happen together.', 'checked', '{"lint":[],"solve":{"answer":"The day is on a weekend; the day is a Saturday","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A Saturday is a weekend day, so \"weekend\" and \"Saturday\" can both happen. The other pairs are different single days.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f68e596-d96a-4f0d-9c27-3a066eef86c1', 'NC26.8.RD.1', 1, 'numeric', 'Tell mutually exclusive events from inclusive events', 'Events A and B are mutually exclusive. The probability of A is 0.3 and the probability of B is 0.5. What is the probability that A and B both happen on the same trial?', '[]', '0', '0', 'Mutually exclusive events cannot both happen on the same trial, so the probability that both happen is 0.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mutually exclusive events cannot both happen, so P(A and B) = 0.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a00aa9b4-47c7-46d3-bb4d-1a6e2dbdd3e4', 'NC26.8.RD.1', 1, 'numeric', 'Add probabilities of mutually exclusive events', 'A fruit bowl holds 5 apples, 3 pears and 2 oranges. One piece of fruit is picked at random. What is the probability that it is a pear or an orange?', '[]', '1/2', '(3+2)/(5+3+2)', 'A piece of fruit cannot be a pear and an orange at once, so add the counts: 3 pears + 2 oranges = 5 pieces out of 10. The probability is 5/10 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pear or orange: 3 + 2 = 5 of 10 pieces. P = 5/10 = 1/2.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c69eaca8-b879-45de-8939-b4d1e6abf661', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'The probability that Dana walks to school is 0.4 and the probability that she rides the bus is 0.35. She does only one of these on any day. What is the probability that she walks or rides the bus?', '["0.05","0.14","0.25","0.75"]', '0.75', '0.4+0.35', 'She cannot walk and ride the bus on the same day, so add: 0.4 + 0.35 = 0.75.', 'checked', '{"lint":[],"solve":{"answer":"0.75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She does only one per day, so the events are mutually exclusive: 0.4 + 0.35 = 0.75.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba6cc70a-7361-4a80-a54d-2ad00f0da319', 'NC26.8.RD.1', 1, 'numeric', 'Add probabilities of mutually exclusive events', 'A spinner has 8 equal sections: 3 are red, 2 are blue, 2 are green and 1 is yellow. What is the probability that the spinner lands on blue or yellow?', '[]', '3/8', '(2+1)/8', 'Blue and yellow sections are different sections. There are 2 + 1 = 3 of them among 8 equal sections, so the probability is 3/8.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue 2 sections + yellow 1 section = 3 of 8 equal sections: 3/8.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43152640-30ea-4359-8463-30b95f948e77', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'The 8 letters of the word TRIANGLE are written on 8 tiles, one letter on each tile. One tile is drawn at random. What is the probability that it is a vowel or the letter L?', '["$\\frac{3}{8}$","$\\frac{1}{8}$","$\\frac{1}{2}$","$\\frac{3}{64}$"]', '$\frac{1}{2}$', NULL, 'The vowels are I, A and E (3 tiles). The letter L is 1 more tile, and L is not a vowel. So 3 + 1 = 4 tiles out of 8 give 4/8 = 1/2.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"TRIANGLE: T,R,I,A,N,G,L,E. Vowels I, A, E = 3 tiles; L = 1 tile; no overlap. 4/8 = 1/2.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab6e7a06-45e5-4dc7-9c5a-096507856c1e', 'NC26.8.RD.1', 1, 'numeric', 'Add probabilities of mutually exclusive events', 'In a survey, each student chose one favorite lunch. 30% chose pizza, 25% chose pasta, and the rest chose other foods. What percent of the students chose pizza or pasta?', '[]', '55', '30+25', 'Each student chose only one lunch, so the groups do not overlap. Add: 30% + 25% = 55%.', 'checked', '{"lint":[],"solve":{"answer":"55","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each student chose one lunch, so the choices are mutually exclusive: 30% + 25% = 55%.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('705a2379-e0ba-4abe-be98-e92926a4b34c', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'A spinner lands on blue with probability $\frac{1}{4}$ and on green with probability $\frac{1}{6}$. It cannot land on both at once. What is the probability that it lands on blue or green?', '["$\\frac{1}{5}$","$\\frac{5}{12}$","$\\frac{1}{24}$","$\\frac{1}{12}$"]', '$\frac{5}{12}$', NULL, 'The events are mutually exclusive, so add: $\frac{1}{4}$ + $\frac{1}{6}$ = $\frac{3}{12}$ + $\frac{2}{12}$ = $\frac{5}{12}$. Adding the tops and the bottoms separately, or multiplying, is a mistake.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1/4 + 1/6 = 3/12 + 2/12 = 5/12.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a07e1d3-a82a-436b-b9e2-ac2fbcfd0951', 'NC26.8.RD.1', 1, 'choice', 'Add probabilities of mutually exclusive events', 'Events A and B are mutually exclusive. Which expression gives the probability that A or B happens?', '["$P(A) + P(B)$","$P(A) \\times P(B)$","$P(A) - P(B)$","$P(A) \\div P(B)$"]', '$P(A) + P(B)$', NULL, 'For mutually exclusive events, no outcome is counted in both, so the probability that A or B happens is found by adding: P(A) + P(B).', 'checked', '{"lint":[],"solve":{"answer":"$P(A) + P(B)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"For mutually exclusive events P(A or B) = P(A) + P(B).","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89a6f082-a9c1-40ab-8f5c-b987b2f60a2f', 'NC26.8.RD.1', 1, 'choice', 'Probability of A or B when the events overlap', 'A fair number cube is rolled once. What is the probability of rolling an even number or a number greater than 4?', '["$\\frac{5}{6}$","$\\frac{1}{6}$","$\\frac{1}{3}$","$\\frac{2}{3}$"]', '$\frac{2}{3}$', NULL, 'Even numbers: 2, 4, 6. Numbers greater than 4: 5, 6. Together the outcomes are 2, 4, 5, 6, which is 4 different outcomes (6 is in both lists and is counted once). The probability is 4/6 = 2/3.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{2}{3}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Even {2,4,6}, greater than 4 {5,6}. Union {2,4,5,6} = 4 outcomes. 4/6 = 2/3. (Check: 3/6 + 2/6 - 1/6 = 4/6.)","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74a9a75d-309f-415a-8fe1-933b9d64e4eb', 'NC26.8.RD.1', 1, 'numeric', 'Probability of A or B when the events overlap', 'In a class of 25 students, 15 have a brother, 10 have a sister, and 5 have both a brother and a sister. How many students have a brother or a sister (or both)?', '[]', '20', '15+10-5', 'Adding 15 and 10 counts the 5 students who have both twice. Subtract them once: 15 + 10 - 5 = 20 students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Brother or sister = 15 + 10 - 5 = 20.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa03d5e4-c1e7-46ac-b1e1-ee7be01599e5', 'NC26.8.RD.1', 1, 'choice', 'Probability of A or B when the events overlap', 'Events A and B can happen at the same time. Which expression gives the probability that A or B happens?', '["$P(A) + P(B)$","$P(A) + P(B) + P(A \\text{ and } B)$","$P(A) + P(B) - P(A \\text{ and } B)$","$P(A) \\times P(B)$"]', '$P(A) + P(B) - P(A \text{ and } B)$', NULL, 'Outcomes in both events are counted once in P(A) and again in P(B). Subtract P(A and B) one time so that they are counted only once.', 'checked', '{"lint":[],"solve":{"answer":"$P(A) + P(B) - P(A \\text{ and } B)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Addition rule for overlapping events: P(A) + P(B) - P(A and B).","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b875cbcf-93cc-4936-8212-4d9848a5bacc', 'NC26.8.RD.1', 1, 'numeric', 'Probability that an event, or neither event, does not happen', 'Kai holds 1 of the 25 raffle tickets. One ticket is drawn at random. What is the probability that Kai''s ticket is not drawn?', '[]', '24/25', '1-1/25', 'The probability that Kai''s ticket is drawn is 1/25. The probability that it is not drawn is 1 - 1/25 = 24/25.', 'checked', '{"lint":[],"solve":{"answer":"24/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Drawn and not drawn are mutually exclusive and cover everything. P(drawn) = 1/25, so P(not drawn) = 1 - 1/25 = 24/25.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d45ac9c6-4566-45f7-8b52-c6fb68abae52', 'NC26.8.RD.1', 1, 'numeric', 'Probability that an event, or neither event, does not happen', 'A basketball player makes a free throw with probability 0.8. What is the probability that the player does not make the next free throw?', '[]', '0.2', '1-0.8', 'Making it and missing it cannot both happen, and one of them must happen. So the probability of missing is 1 - 0.8 = 0.2.', 'checked', '{"lint":[],"solve":{"answer":"0.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Make and miss are mutually exclusive and exhaustive: 1 - 0.8 = 0.2.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('325c93ff-edb1-4a85-be49-99616f2d25d7', 'NC26.8.RD.1', 1, 'choice', 'Probability that an event, or neither event, does not happen', 'A spinner has red, blue and green sections. The probability of landing on red is $\frac{1}{5}$ and the probability of landing on blue is $\frac{1}{2}$. What is the probability of landing on green?', '["$\\frac{3}{10}$","$\\frac{7}{10}$","$\\frac{1}{2}$","$\\frac{4}{5}$"]', '$\frac{3}{10}$', NULL, 'Red, blue and green together make probability 1. Red or blue is $\frac{1}{5}$ + $\frac{1}{2}$ = $\frac{7}{10}$, so green is 1 - $\frac{7}{10}$ = $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{10}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Red, blue, green are the only outcomes and mutually exclusive: 1 - 1/5 - 1/2 = 10/10 - 2/10 - 5/10 = 3/10.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('54a1d047-2a97-4559-9c5c-6394bc025bf8', 'NC26.8.RD.1', 1, 'numeric', 'Probability that an event, or neither event, does not happen', 'The forecast says there is a 35% chance of snow tomorrow. What is the chance, as a percent, that it does not snow?', '[]', '65', '100-35', 'Snowing and not snowing together make 100%. So the chance of no snow is 100% - 35% = 65%.', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Snow and no snow are complementary: 100% - 35% = 65%.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f3116ae1-eeb3-4b1a-b036-6ee237d070b4', 'NC26.8.RD.1', 1, 'numeric', 'Find a missing probability using the addition rule', 'Events A and B are mutually exclusive. P(A) = 0.3 and P(A or B) = 0.8. What is P(B)?', '[]', '0.5', '0.8-0.3', 'For mutually exclusive events, P(A or B) = P(A) + P(B). So P(B) = 0.8 - 0.3 = 0.5.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(A or B) = P(A) + P(B) for mutually exclusive events: 0.8 = 0.3 + P(B), so P(B) = 0.5.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffb2a720-e496-48f8-81ed-768901537b73', 'NC26.8.RD.1', 1, 'numeric', 'Find a missing probability using the addition rule', 'A spinner cannot land on red and blue at once. The probability of landing on red or blue is $\frac{1}{2}$ and the probability of landing on red is $\frac{1}{8}$. What is the probability of landing on blue?', '[]', '3/8', '1/2-1/8', 'Red and blue are mutually exclusive, so P(red or blue) = P(red) + P(blue). Then P(blue) = $\frac{1}{2}$ - $\frac{1}{8}$ = $\frac{4}{8}$ - $\frac{1}{8}$ = $\frac{3}{8}$.', 'checked', '{"lint":[],"solve":{"answer":"3/8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(red or blue) = P(red) + P(blue): 1/2 = 1/8 + P(blue), P(blue) = 4/8 - 1/8 = 3/8.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ef1686a-fc92-4f71-bffd-049010abcb85', 'NC26.8.RD.1', 1, 'choice', 'Justify a probability with a model', 'A spinner has four equal sections: red, blue, green and yellow. Tom says that the probability of red or blue is $\frac{1}{4} + \frac{1}{4} = \frac{1}{2}$. Which statement explains why adding is correct?', '["Red and blue are the biggest sections on the spinner","Two of the four equal sections are red or blue, and no section is both","The spinner can land on red and blue at the same time","There are four colors, so each color has probability $\\frac{1}{2}$"]', 'Two of the four equal sections are red or blue, and no section is both', NULL, 'The sections are equal and no section is both red and blue. So 2 of the 4 sections are red or blue, and 2 out of 4 is 1/2, which is the same as adding 1/4 + 1/4.', 'checked', '{"lint":[],"solve":{"answer":"Two of the four equal sections are red or blue, and no section is both","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding is justified because red and blue cannot both happen (no section is both) and they cover 2 of 4 equal sections. Option 3.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81e156af-d338-48aa-a01b-8196d8bfe24a', 'NC26.8.RD.1', 1, 'choice', 'Justify a probability with a model', 'In a Venn diagram model of two events, the circle for event A and the circle for event B do not overlap at all. What does this show?', '["Events A and B are inclusive","Events A and B have the same probability","Events A and B are the same event","Events A and B are mutually exclusive"]', 'Events A and B are mutually exclusive', NULL, 'Overlapping circles would hold outcomes that are in both events. Circles that do not overlap mean no outcome is in both, so the events are mutually exclusive.', 'checked', '{"lint":[],"solve":{"answer":"Events A and B are mutually exclusive","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-overlapping circles means no outcome is in both events: mutually exclusive.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae166388-33e9-4021-86d2-45bf21db43b2', 'NC26.8.RD.1', 1, 'numeric', 'Probabilities from a table or Venn counts', 'In a group of 30 people, 12 speak only Spanish, 10 speak only French, 3 speak both languages and 5 speak neither. One person is chosen at random. What is the probability that the person speaks Spanish or French (or both)?', '[]', '5/6', '(12+10+3)/30', 'People who speak Spanish or French (or both) are the three groups: 12 + 10 + 3 = 25. The probability is 25/30 = 5/6.', 'checked', '{"lint":[],"solve":{"answer":"5/6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 10 + 3 + 5 = 30, consistent. Spanish or French (or both) = 12 + 10 + 3 = 25. P = 25/30 = 5/6.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ebe548f-c9cd-412e-acfe-de6fcfc77f22', 'NC26.8.RD.1', 1, 'numeric', 'Probabilities from a table or Venn counts', 'The 40 members of a club are in three grades: 10 are in 6th grade, 14 are in 7th grade and 16 are in 8th grade. One member is chosen at random. What is the probability that the member is in 6th grade or in 8th grade?', '[]', '13/20', '(10+16)/40', 'A member is in only one grade, so add: 10 + 16 = 26 members out of 40. The probability is 26/40 = 13/20.', 'checked', '{"lint":[],"solve":{"answer":"13/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A member is in exactly one grade, so 6th and 8th are mutually exclusive: (10 + 16)/40 = 26/40 = 13/20.","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81350462-ffbf-4203-a106-9ef2edfd70a2', 'NC26.8.RD.1', 1, 'choice', 'Probabilities from a table or Venn counts', 'In a group of 40 students, 18 play chess, 14 play checkers and 6 play both games. One student is chosen at random. What is the probability that the student plays both chess and checkers?', '["$\\frac{3}{20}$","$\\frac{13}{20}$","$\\frac{4}{5}$","$\\frac{1}{3}$"]', '$\frac{3}{20}$', NULL, 'The number of students who play both games is 6 out of 40 students. The probability is 6/40 = 3/20.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3}{20}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both = 6 of 40: 6/40 = 3/20. (Data consistent: union 18+14-6 = 26 <= 40.)","run_id":"claude-code","at":"2026-10-18T01:07:55.246Z"}}', 'ai', NULL, NULL)
