INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed9739c7-281e-4572-a22d-c957b074fbba', 'NC26.8.RD.2', 1, 'numeric', 'Estimate a probability from simulation results', 'A simulation of 80 trials shows a student who walks to school in 24 of the trials. What percent of the trials show a student who walks?', '[]', '30', '24/80*100', '24 out of 80 trials is 24/80 = 0.3 = 30%.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"24/80 = 0.3 = 30%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
