INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca41689d-3806-462d-bcf9-9609a4007749', 'NC26.8.RD.2', 1, 'numeric', 'Estimate a probability from simulation results', 'A student runs a simulation of 20 random samples of 10 students each. In 3 of the 20 samples, at least 4 of the students are left-handed. What fraction of the samples have at least 4 left-handed students?', '[]', '3/20', '3/20', '3 of the 20 samples had at least 4 left-handed students, so the fraction is 3/20.', 'checked', '{"lint":[],"solve":{"answer":"3/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 of 20 samples: 3/20.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
