VALUES ('ba5ea139-db12-4608-8af2-31badfe48e3a', 'NC26.8.RD.2', 1, 'numeric', 'Judge whether a sample is valid for several populations', 'A researcher takes a random sample of 30 students from each of four schools. How many students are in the sample altogether?', '[]', '120', '30*4', '30 students from each of 4 schools is 30 x 4 = 120 students.', 'checked', '{"lint":[],"solve":{"answer":"120","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy arithmetic (30 x 4) for Grade 8.","work":"30 x 4 = 120 students.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
