VALUES ('8b2fb465-b4de-4e03-9d97-9d8326b824dc', 'NC26.8.RD.2', 1, 'numeric', 'Use random samples to predict for populations', 'In a random sample of 80 students, 20 said they take the bus to school. What percent of the sample takes the bus?', '[]', '25', '20/80*100', '20 / 80 = 0.25 = 25%.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20/80 = 0.25 = 25%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
