INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb826119-d88f-466e-9a53-0e9724573bf6', 'NC26.8.RD.2', 1, 'numeric', 'Use random samples to predict for populations', 'A random sample of 200 light bulbs from a factory found 6 that were defective. The factory made 10,000 bulbs. About how many of the 10,000 bulbs would you predict are defective?', '[]', '300', '6/200*10000', '6 out of 200 is 3%. Predict 3% of 10,000 bulbs: 0.03 x 10,000 = 300 bulbs.', 'checked', '{"lint":[],"solve":{"answer":"300","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6/200 = 0.03. 0.03 x 10,000 = 300.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
