INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('daa42f6c-cf62-4d87-96d2-b9b41a0fcad7', 'NC26.8.RD.2', 1, 'choice', 'Recognize a statistical question', 'A student wants to investigate sleep at three middle schools. Which is a statistical question for her investigation?', '["How many middle schools are in the district that includes the three schools in the study?","How many hours do the students at each of the three schools sleep on school nights?","What is the name of the principal who currently runs each of the three schools?","In what year was each of the three schools built and first opened to students?"]', 'How many hours do the students at each of the three schools sleep on school nights?', NULL, 'The answers to a statistical question vary across the people being studied. Hours of sleep differ from student to student. The other questions each have a single fixed answer for each school.', 'checked', '{"lint":[],"solve":{"answer":"How many hours do the students at each of the three schools sleep on school nights?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only hours of sleep varies across students and is answered with data; principal name, build year and district count are single facts.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f33de87b-4907-49fd-8101-5e51cd646c09', 'NC26.8.RD.2', 1, 'choice', 'Write a question that compares several populations', 'Tia wants to compare how much time students in grades 5, 6, 7 and 8 spend reading. Which question should she ask?', '["Do the students in grades 5, 6, 7 and 8 like to read books for fun at school?","Who is the best reader among all of the students in grades 5, 6, 7 and 8 at the school this year?","How many books are in the library that the students of grades 5, 6, 7 and 8 use?","How many minutes per day do the students in each of grades 5, 6, 7 and 8 spend reading?"]', 'How many minutes per day do the students in each of grades 5, 6, 7 and 8 spend reading?', NULL, 'A good question names the four groups to be compared and the measurement to collect: minutes of reading per day. The other questions do not collect that data from each grade.', 'checked', '{"lint":[],"solve":{"answer":"How many minutes per day do the students in each of grades 5, 6, 7 and 8 spend reading?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Comparing time spent reading needs a measured quantity per grade: minutes per day per grade. Books in library, best reader and liking reading do not measure time.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c5e5e58-0854-4c70-bed1-820522d07e47', 'NC26.8.RD.2', 1, 'choice', 'Spot a biased or unclear survey question', 'Which survey question is biased, meaning it pushes people toward an answer?', '["Which lunch do you like best: pizza, tacos, salad or something else?","How many days a week do you buy school lunch, from zero days to five days?","What is your favorite lunch that the cafeteria serves on a school day?","Don''t you agree that pizza is the best lunch the cafeteria serves?"]', 'Don''t you agree that pizza is the best lunch the cafeteria serves?', NULL, 'The words "Don''t you agree" and "the best" push people to say pizza. The other questions let each person answer honestly.', 'checked', '{"lint":[],"solve":{"answer":"Don''t you agree that pizza is the best lunch the cafeteria serves?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Don''t you agree that pizza is the best...'' leads the respondent; the others are neutral.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3d1c4a1-6eba-4d25-a976-34fc532ae2a9', 'NC26.8.RD.2', 1, 'choice', 'Spot a biased or unclear survey question', 'Why is the question "Don''t you think our awful bus route should be fixed?" biased?', '["It asks about a bus route, and questions about buses are always biased","It uses a loaded word, which pushes people toward answering yes","It is too short to give data, because a good survey question has many words","It asks people to give a number, and numbers are not allowed in a survey"]', 'It uses a loaded word, which pushes people toward answering yes', NULL, 'The word "awful" and the phrase "Don''t you think" push people to answer yes. A fair question would ask how people rate the bus route.', 'checked', '{"lint":[],"solve":{"answer":"It uses a loaded word, which pushes people toward answering yes","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Awful'' is a loaded word and ''Don''t you think'' leads toward yes. The other reasons are false.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6e8946b9-6027-46c8-b8c9-82d0e85c6dbc', 'NC26.8.RD.2', 1, 'choice', 'Identify bias in how a sample is chosen', 'Leo wants to know the favorite sport of the students at his school. He asks only the members of the soccer team. Why might his sample be biased?', '["Soccer team members are more likely to pick soccer than other students are","The sample is too large, because a sample should never include a whole team of players","Students on teams cannot be asked questions, because they are busy with practice and games","Soccer is not a sport that all schools play, so the team could not name a favorite sport"]', 'Soccer team members are more likely to pick soccer than other students are', NULL, 'The soccer players are not typical of all students, because they are likely to name soccer. The sample favors one answer, so it is biased.', 'checked', '{"lint":[],"solve":{"answer":"Soccer team members are more likely to pick soccer than other students are","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Soccer players are more likely to favour soccer, so the sample is not representative of the school.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7282483-fec0-49b4-997d-54f41623c563', 'NC26.8.RD.2', 1, 'choice', 'Identify bias in how a sample is chosen', 'A radio station that plays only country music asks its listeners to call in and vote for their favorite type of music. Why are the results likely biased?', '["Radio stations play too many songs for their listeners to pick a favorite type","Phone calls cost money, so too few listeners would be able to vote in the poll","Its listeners are more likely to prefer country music than people in general are","The poll asks about types of music, which are not numbers, so it cannot give results"]', 'Its listeners are more likely to prefer country music than people in general are', NULL, 'The people who call are the station''s own listeners, and they probably like country music more than most people do. The sample does not represent everyone.', 'checked', '{"lint":[],"solve":{"answer":"Its listeners are more likely to prefer country music than people in general are","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Listeners of a country-only station likely prefer country music; the sample over-represents that preference (also voluntary response). Other options are false.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63707945-e494-4ce5-b2ef-a2fa93b6b49d', 'NC26.8.RD.2', 1, 'choice', 'Identify and carry out random sampling', 'A class has 28 students numbered 1 to 28. Which method chooses a random sample of 7 students?', '["A computer picks 7 different numbers from 1 to 28 purely by chance, with no one deciding","The 7 students who sit nearest the door are chosen, since they are the easiest to reach","The 7 tallest students in the class are chosen, since they are the easiest to find","The teacher chooses the 7 students who finished first, since they are done with their work"]', 'A computer picks 7 different numbers from 1 to 28 purely by chance, with no one deciding', NULL, 'In a random sample, chance decides who is chosen, so every student has the same chance. The other methods choose students by where they sit, how tall they are or how fast they work.', 'checked', '{"lint":[],"solve":{"answer":"A computer picks 7 different numbers from 1 to 28 purely by chance, with no one deciding","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample gives every student an equal chance by chance alone: a computer picking 7 different numbers from 1-28. Others are convenience/judgment samples.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('993e2aae-cd12-4df4-abc7-d506259c449f', 'NC26.8.RD.2', 1, 'choice', 'Design a simulation', 'About 1 out of every 4 students at a school walks to school. Which tool could simulate choosing one student at random and seeing whether the student walks?', '["A fair coin that is flipped once, with heads meaning \"walks\" and tails meaning \"does not walk\"","A number cube, with a 1 meaning \"walks\" and 2 through 6 meaning \"does not walk\"","A number cube, with a 1 or 2 meaning \"walks\" and 3 through 6 meaning \"does not walk\"","A spinner with 4 equal sections, one labeled \"walks\" and 3 labeled \"does not walk\""]', 'A spinner with 4 equal sections, one labeled "walks" and 3 labeled "does not walk"', NULL, 'One section out of 4 equal sections is a chance of 1 in 4. A coin gives 1 in 2, one face of a cube gives 1 in 6, and two faces of a cube give 2 in 6, or 1 in 3.', 'checked', '{"lint":[],"solve":{"answer":"A spinner with 4 equal sections, one labeled \"walks\" and 3 labeled \"does not walk\"","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need P(walks)=1/4. Cube 1 -> 1/6; coin -> 1/2; spinner 1 of 4 equal -> 1/4; cube 1 or 2 -> 1/3. Spinner.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('173aa002-f0cb-499e-83c0-30ec19fa7561', 'NC26.8.RD.2', 1, 'choice', 'Judge whether a sample is valid for several populations', 'Which sample is more likely to give a reliable picture of all 600 students at a school?', '["5 students chosen at random from a list of all of the students in the school","100 students who are all taken from one single class or one grade of the school","100 students chosen at random from a list of all the students","The 100 tallest students, found by measuring every student in the school"]', '100 students chosen at random from a list of all the students', NULL, 'A larger sample chosen at random from everyone is more reliable. A sample of 5 students is too small, and students from one class or one grade, or the tallest students, are not typical of the whole school.', 'checked', '{"lint":[],"solve":{"answer":"100 students chosen at random from a list of all the students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random and reasonably large: 100 chosen at random from a full list. Tallest and single-class samples are biased; 5 is too small.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2f446e1-1899-496f-b086-30a6b3c7652b', 'NC26.8.RD.2', 1, 'choice', 'Judge whether a sample is valid for several populations', 'A researcher wants to compare three schools. Why should she sample students from each of the three schools?', '["So that she can use fewer students in all and still compare the three schools","So that every population being compared is represented in the data","So that every answer is the same at all three schools and the data are easy to read","So that only the biggest school counts when the results are put together"]', 'So that every population being compared is represented in the data', NULL, 'To compare populations, the sample must include members of each one. Leaving a school out would mean she could say nothing about it.', 'checked', '{"lint":[],"solve":{"answer":"So that every population being compared is represented in the data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To compare three populations each must be represented in the data.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('09c4500a-de8f-4ca1-aa54-5d920be5d08b', 'NC26.8.RD.2', 1, 'numeric', 'Random sampling from several populations', 'A school has 100 students in grade 6, 100 in grade 7 and 200 in grade 8. A researcher takes a random sample of 40 students, with the number from each grade in proportion to the size of the grade. How many of the sampled students are in grade 8?', '[]', '20', '40*200/400', 'Grade 8 has 200 of the 400 students, which is one half. One half of the sample of 40 is $40 \times \frac{200}{400} = 20$ students.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 8 is 200/400 = 1/2 of the school; 40x1/2=20.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('73450ffc-e3e3-4310-97a9-185940758f8e', 'NC26.8.RD.2', 1, 'choice', 'Collect and organize data from several populations', 'A researcher will compare how many hours of sleep students get at four schools. She takes a random sample at each school. For each student in the samples, what should she record?', '["The student''s school and the hours of sleep","Only the name of the student''s school","The student''s school and favorite subject","Only the number of students in the sample"]', 'The student''s school and the hours of sleep', NULL, 'To compare the four schools, each answer must be matched to its school. So she records which school the student attends and the number of hours of sleep. The school alone, a favorite subject or the sample size cannot show how the schools compare in sleep.', 'checked', '{"lint":[],"solve":{"answer":"The student''s school and the hours of sleep","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"To compare sleep across schools she needs each student''s school (the group) and hours of sleep (the variable).","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a08340d-f1d5-4fde-ac29-e8aeda0ccf58', 'NC26.8.RD.2', 1, 'numeric', 'Use a simulation of random samples', 'A simulation picks random samples of 4 students and counts the girls in each. In 10 trials, the numbers of girls were 2, 1, 3, 2, 2, 4, 2, 1, 2 and 3. In what percent of the trials were there at least 3 girls?', '[]', '30', '3/10*100', 'The trials with at least 3 girls had 3, 4 and 3 girls, which is 3 trials out of 10. $3 \div 10 = 0.3$, which is 30 percent.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trials with 3 or more girls: 3, 4, 3 = 3 of 10 = 30%.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56e29d2c-0dd7-484a-ba7f-dfdca197d995', 'NC26.8.RD.2', 1, 'choice', 'Validity of a sample', 'A researcher compares sleep at three schools. She asks 3 random students at each school. Why would asking 40 random students at each school be better?', '["A larger random sample is more likely to look like the whole school.","A larger sample removes the bias from a badly worded question.","A larger sample means all three schools must have the same mean.","A larger sample turns a convenience sample into a random sample."]', 'A larger random sample is more likely to look like the whole school.', NULL, 'With only 3 students, a few unusual answers could give a very wrong picture of a school. A larger random sample is more likely to represent the whole school. Size does not fix a biased question, does not make the schools equal, and does not make a convenience sample random.', 'checked', '{"lint":[],"solve":{"answer":"A larger random sample is more likely to look like the whole school.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples vary less and are more likely to represent the population; the other claims are false.","run_id":"claude-code","at":"2026-10-18T03:28:53.247Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34892d35-4130-4b97-ad25-5e36fa7c94ec', 'NC26.8.RD.2', 2, 'choice', 'Identify bias in a sample', 'A town wants to know whether its residents want a new park. The town surveys 100 people as they leave a sports store. Why might this sample be biased?', '["One hundred people is always too few for a survey","People at a sports store may not represent all of the town''s residents","Surveys cannot be given outside a person''s home","People who are leaving a store cannot answer honestly"]', 'People at a sports store may not represent all of the town''s residents', NULL, 'A sample is biased when it does not represent the whole population. People shopping at a sports store may like outdoor activities more than other residents, so their answers may not match the whole town.', 'checked', '{"lint":[],"solve":{"answer":"People at a sports store may not represent all of the town''s residents","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sports-store shoppers are likely more interested in parks/sports than the general town population, so they may not represent all residents.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c178ea5-dd7a-44ce-a0a2-4a0bf0649b88', 'NC26.8.RD.2', 2, 'choice', 'Choose a simulation', 'About 40% of the students at a school are in the band. Which tool could be used to simulate choosing one student at random and seeing whether the student is in the band?', '["A spinner with 10 equal sections, 4 of them labeled \"band\"","A coin: heads means the student is in the band","A number cube: rolling a 4 means the student is in the band","A spinner with 4 equal sections, 1 of them labeled \"band\""]', 'A spinner with 10 equal sections, 4 of them labeled "band"', NULL, 'The tool must give "band" with probability 40%, which is $\frac{4}{10}$. A 10-section spinner with 4 band sections does that. A coin gives 50%, a number cube gives about 17%, and a 4-section spinner with one band section gives 25%.', 'checked', '{"lint":[],"solve":{"answer":"A spinner with 10 equal sections, 4 of them labeled \"band\"","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need a 40% chance: 4 of 10 equal sections = 40%. Others give 25%, 50%, 1/6.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25aa734a-1f4a-432c-8548-adf7de552f1c', 'NC26.8.RD.2', 2, 'numeric', 'Compare samples from several populations', 'A researcher asks 40 randomly chosen students at each of three schools whether they own a bike. At School A, 22 of the 40 students say yes. At School B, 26 say yes. At School C, 30 say yes. How many percentage points higher is the percent of bike owners in the sample from School C than in the sample from School A?', '[]', '20', '30/40*100-22/40*100', 'School C: $\frac{30}{40} = 75\%$. School A: $\frac{22}{40} = 55\%$. (School B, $\frac{26}{40} = 65\%$, is not needed.) The difference is $75 - 55 = 20$ percentage points.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"School A: 22/40 = 55%. School C: 30/40 = 75%. Difference = 20 percentage points.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89945f99-4d64-473a-9952-fbe121c8daa0', 'NC26.8.RD.2', 2, 'choice', 'Recognize a statistical question', 'Which statement about statistical questions is true?', '["The answers to a statistical question are expected to vary","A statistical question has exactly one correct number as its answer","A statistical question can only ask about one person","A statistical question cannot be answered by collecting data"]', 'The answers to a statistical question are expected to vary', NULL, 'A statistical question is answered by collecting data, and the data are expected to vary. That is why it is asked about a group.', 'checked', '{"lint":[],"solve":{"answer":"The answers to a statistical question are expected to vary","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question anticipates variability in the data.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f842aa4-86d6-4da0-ac0b-0a695d994714', 'NC26.8.RD.2', 2, 'numeric', 'Recognize a statistical question', 'Here are four questions. (1) How many players are on the Hawks team? (2) How far do the players on each of three teams live from the field? (3) How many goals did the players on each team score this season? (4) How tall are the players on each of the three teams? How many of the four are statistical questions?', '[]', '3', '3', 'Question (1) has one answer, a single count. Questions (2), (3) and (4) ask about many players, and the data will vary, so they are statistical. The answer is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) one count: not statistical. (2) distances of players vary: statistical. (3) goals per player vary: statistical. (4) heights vary: statistical. Count = 3.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('26aa5dcd-1a54-4bfd-baf7-d80582f45269', 'NC26.8.RD.2', 2, 'numeric', 'Write a question that compares several populations', 'Each grade is one population in the question "How do the typical weights of backpacks of students in grades 6, 7 and 8 compare?" A researcher samples 25 students from each population. How many students are in the whole sample?', '[]', '75', '25*3', 'There are 3 populations (grades 6, 7 and 8) with 25 students from each, so the sample has 25 x 3 = 75 students.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy arithmetic (25 x 3) for Grade 8.","work":"25 x 3 = 75 students.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8d2e0fc-86cf-45dc-95f6-e2996925387c', 'NC26.8.RD.2', 2, 'numeric', 'Spot a biased or unclear survey question', 'Four survey questions are listed. (1) "How many hours do you sleep on school nights?" (2) "You agree that homework is too hard, right?" (3) "How many minutes do you spend on homework each night?" (4) "Isn''t it great that our school has so many clubs?" How many of the four questions are worded fairly?', '[]', '2', '2', 'Questions (2) and (4) push people toward an answer. Questions (1) and (3) simply ask for a number. So 2 questions are fair.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) neutral, (2) leading, (3) neutral, (4) leading. Fair: 2.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f63ff980-72bd-42ab-a1ae-a1119e00ca4b', 'NC26.8.RD.2', 2, 'numeric', 'Identify bias in how a sample is chosen', 'To find the percent of students who exercise every day, one researcher asks the 50 students waiting in line at the school fitness room, and 40 say yes. Another researcher picks 40 students at random from the list of all students, and 12 say yes. How many percentage points higher is the percent from the fitness-room sample than the percent from the random sample?', '[]', '50', '40/50*100-12/40*100', 'Fitness-room sample: 40/50 = 80%. Random sample: 12/40 = 30%. The difference is 80 - 30 = 50 percentage points. The fitness-room line is full of students who like to exercise, so it is biased.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fitness room: 40/50 = 80%. Random: 12/40 = 30%. Difference = 50 percentage points.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3986b70-10ed-486c-9fa9-5d4767d11a67', 'NC26.8.RD.2', 2, 'choice', 'Identify bias in how a sample is chosen', 'Which sampling method is a convenience sample, which can be biased?', '["Using random numbers to choose 30 students from the class lists","Choosing every fifth name from a list of all the students","Drawing 30 names from a hat holding every student''s name","Surveying the first 30 students who walk into the cafeteria"]', 'Surveying the first 30 students who walk into the cafeteria', NULL, 'A convenience sample takes whoever is easiest to reach. The first students in the cafeteria may not be typical of everyone. The other methods use chance or a fixed rule across the whole list.', 'checked', '{"lint":[],"solve":{"answer":"Surveying the first 30 students who walk into the cafeteria","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The first 30 into the cafeteria is a convenience sample; the others are random or systematic.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9944448f-2833-4c86-874a-aa5c34a2967f', 'NC26.8.RD.2', 2, 'choice', 'Identify and carry out random sampling', 'Which sampling method is NOT random?', '["Drawing names from a hat holding every name","Letting students volunteer by raising their hands","Using a random number generator to pick student ID numbers","Spinning a spinner with one equal section for each student number"]', 'Letting students volunteer by raising their hands', NULL, 'When students volunteer, the students decide whether they are in the sample, not chance. In the other methods, chance picks the students.', 'checked', '{"lint":[],"solve":{"answer":"Letting students volunteer by raising their hands","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volunteers self-select; not random.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53023167-3012-4ab3-bc60-ef8597ee7e7a', 'NC26.8.RD.2', 2, 'numeric', 'Identify and carry out random sampling', 'A teacher numbers 40 students from 1 to 40 and reads random numbers from a table: 27, 05, 33, 05, 41, 18, 12. She skips repeated numbers and numbers over 40. What is the number of the fourth student chosen?', '[]', '18', '18', 'Read the numbers in order: 27 is chosen, 5 is chosen, 33 is chosen, 5 is a repeat so skip it, 41 is over 40 so skip it, 18 is chosen. The fourth student is number 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"27 (1st), 05 (2nd), 33 (3rd), 05 repeat skip, 41 > 40 skip, 18 (4th). Fourth = 18.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('273146a0-8d9a-4dd0-8170-79e580a48c32', 'NC26.8.RD.2', 2, 'choice', 'Design a simulation', 'In a town, 60% of the families own a car. Random digits from 0 to 9 are used to simulate choosing one family. Which assignment of digits models this?', '["The digits 0 to 5 mean the family owns a car, and the digits 6 to 9 mean it does not","The digits 0 to 6 mean the family owns a car, and the digits 7 to 9 mean it does not","The digits 0 to 3 mean the family owns a car, and the digits 4 to 9 mean it does not","The digits 0 to 8 mean the family owns a car, and the digit 9 means it does not"]', 'The digits 0 to 5 mean the family owns a car, and the digits 6 to 9 mean it does not', NULL, 'Six of the ten digits (0, 1, 2, 3, 4, 5) make 60%. The other assignments give 70%, 40% and 90%.', 'checked', '{"lint":[],"solve":{"answer":"The digits 0 to 5 mean the family owns a car, and the digits 6 to 9 mean it does not","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60% of 10 digits = 6 digits: 0-5 for car, 6-9 not.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('620453ac-7e8b-42c8-bc1b-beb4d6f18823', 'NC26.8.RD.2', 2, 'numeric', 'Design a simulation', 'A number cube is used to simulate whether one student is in the chess club (a 6 means yes). A trial is a sample of 5 students. How many rolls are needed to run 4 trials?', '[]', '20', '5*4', 'Each trial needs one roll for each of the 5 students. Four trials need 5 x 4 = 20 rolls.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 rolls per trial x 4 trials = 20 rolls.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3224ca25-dfbe-4e61-ac07-23a963cd728e', 'NC26.8.RD.2', 2, 'numeric', 'Design a simulation', 'The digits 0 to 3 stand for a student who owns a bike. A simulation of 20 students generates these digits: 7 2 9 0 4 1 8 3 5 6 0 2 9 7 1 4 8 6 3 5. How many of the 20 simulated students own a bike?', '[]', '8', '8', 'Count the digits from 0 to 3: 2, 0, 1, 3, 0, 2, 1, 3. That is 8 digits, so 8 of the 20 simulated students own a bike.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Digits 0-3 among 7 2 9 0 4 1 8 3 5 6 0 2 9 7 1 4 8 6 3 5: 2,0,1,3,0,2,1,3 = 8.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('caa6102a-30eb-45a1-a888-c0fa58c2816e', 'NC26.8.RD.2', 2, 'numeric', 'Estimate a probability from simulation results', 'Ana runs a simulation of random samples of 5 students from a population in which 20% wear glasses. For 10 trials, the numbers of students in the sample who wear glasses are 0, 1, 2, 0, 1, 1, 3, 0, 1, 2. In what percent of the trials did the sample have 2 or more students who wear glasses?', '[]', '30', '3/10*100', 'The trials with 2 or more are 2, 3 and 2, which is 3 trials out of 10. That is 3/10 = 30%.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Trials with 2 or more: 2, 3, 2 -> 3 of 10 = 30%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('416aa58c-e2fe-4f79-b683-a02207dc0d5f', 'NC26.8.RD.2', 2, 'numeric', 'Estimate a probability from simulation results', 'A simulation takes 8 random samples of 10 students each from a school where 60% like math. The numbers of students who like math in the 8 samples are 5, 6, 7, 4, 6, 8, 6, 6. What is the mean number of students who like math per sample?', '[]', '6', '(5+6+7+4+6+8+6+6)/8', 'The total is 5 + 6 + 7 + 4 + 6 + 8 + 6 + 6 = 48. The mean is 48 / 8 = 6 students per sample.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5+6+7+4+6+8+6+6 = 48. 48/8 = 6.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0233e002-941b-4d21-8684-e38c31f2a0bd', 'NC26.8.RD.2', 2, 'numeric', 'Estimate a probability from simulation results', 'In a simulation of 200 trials, a sample of 12 students had 3 or fewer left-handed students in 30 of the trials. What is the estimated probability of that result, written as a decimal?', '[]', '0.15', '30/200', 'The estimate is the number of trials with that result divided by the number of trials: 30 / 200 = 0.15.', 'checked', '{"lint":[],"solve":{"answer":"0.15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/200 = 0.15.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b72cd78f-0c11-4ee5-b6bf-95673c14a2d1', 'NC26.8.RD.2', 2, 'numeric', 'Judge whether a sample is valid for several populations', 'A school has 200 sixth graders, 300 seventh graders and 500 eighth graders. A researcher chooses a random sample of 50 students from the list of all the students. About how many eighth graders would you expect in the sample?', '[]', '25', '500/1000*50', 'Eighth graders are 500 of the 1,000 students, which is half. Half of 50 is 25, so about 25 eighth graders are expected.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Eighth graders are 500/1000 = 1/2 of students. 50 x 1/2 = 25.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a0a20fac-41ca-40cf-95ec-fe91318dbc7b', 'NC26.8.RD.2', 2, 'numeric', 'Judge whether a sample is valid for several populations', 'A club has 40 members from Town A, 60 from Town B and 100 from Town C. A researcher wants a sample of 20 members, with each town in proportion to its size. How many members should be sampled from Town B?', '[]', '6', '60/200*20', 'There are 40 + 60 + 100 = 200 members. Town B has 60/200 = 3/10 of them, and 3/10 of 20 is 6 members.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 200. Town B share 60/200 = 0.3. 0.3 x 20 = 6.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('925fbbb2-46f8-4034-ada3-ec2001c5ed3f', 'NC26.8.RD.2', 2, 'numeric', 'Organize and summarize data from several populations', 'Hours of sleep for 5 students from each of two grades are listed. Grade 6: 10, 9, 9, 10, 12. Grade 8: 8, 7, 9, 8, 8. How many more hours of sleep, on average, do the 6th graders get than the 8th graders?', '[]', '2', '(10+9+9+10+12)/5-(8+7+9+8+8)/5', 'Grade 6 mean: (10 + 9 + 9 + 10 + 12) / 5 = 50 / 5 = 10 hours. Grade 8 mean: (8 + 7 + 9 + 8 + 8) / 5 = 40 / 5 = 8 hours. The difference is 10 - 8 = 2 hours.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 6 mean = (10+9+9+10+12)/5 = 50/5 = 10. Grade 8 mean = (8+7+9+8+8)/5 = 40/5 = 8. Difference 2. (Medians also 10 and 8.)","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f20661d-c12a-486f-a8d7-05b8ef50781c', 'NC26.8.RD.2', 2, 'numeric', 'Organize and summarize data from several populations', 'A survey asked 40 students at each of three schools whether they walk to school. At School X, 16 said yes. At School Y, 10 said yes. At School Z, 22 said yes. What percent of all the students surveyed walk to school?', '[]', '40', '(16+10+22)/120*100', 'Students who walk: 16 + 10 + 22 = 48. Students surveyed: 3 x 40 = 120. The percent is 48 / 120 = 0.4 = 40%.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Yes: 16 + 10 + 22 = 48 of 3 x 40 = 120. 48/120 = 40%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e088a16-fe1f-4f38-9ecc-823598dfbd46', 'NC26.8.RD.2', 2, 'numeric', 'Organize and summarize data from several populations', 'School A has 400 students, and 120 of them own a bike. School B has 300 students, and 150 own a bike. School C has 300 students, and 80 own a bike. What percent of the students in the three schools together own a bike?', '[]', '35', '(120+150+80)/(400+300+300)*100', 'Bike owners: 120 + 150 + 80 = 350. All students: 400 + 300 + 300 = 1,000. The percent is 350 / 1,000 = 35%.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Owners: 120 + 150 + 80 = 350 of 400 + 300 + 300 = 1000. 35%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30610340-973d-4651-84c7-13880b7207ab', 'NC26.8.RD.2', 2, 'numeric', 'Use random samples to predict for populations', 'Random samples of 50 students were taken in each of three towns, and the students were asked if they take the bus. In Town A, 20 take the bus; in Town B, 30; in Town C, 35. Town A has 1,000 students, Town B has 500 and Town C has 400. Predict how many students in the three towns take the bus altogether.', '[]', '980', '20/50*1000+30/50*500+35/50*400', 'Town A: 20/50 = 40% of 1,000 = 400. Town B: 30/50 = 60% of 500 = 300. Town C: 35/50 = 70% of 400 = 280. Total: 400 + 300 + 280 = 980 students.', 'checked', '{"lint":[],"solve":{"answer":"980","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 20/50 = 0.4 x 1000 = 400. B: 30/50 = 0.6 x 500 = 300. C: 35/50 = 0.7 x 400 = 280. Total 980.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e42802d4-52ad-48c8-ae72-9115ba4e1a01', 'NC26.8.RD.2', 2, 'numeric', 'Use random samples to predict for populations', 'In a random sample of 60 students at a school, 18 said they walk to school. Using this sample, a researcher predicts that 150 students at the school walk. How many students attend the school?', '[]', '500', '150/(18/60)', '18 out of 60 is 30%. If 30% of the students is 150, then the school has 150 / 0.3 = 500 students.', 'checked', '{"lint":[],"solve":{"answer":"500","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/60 = 0.3. 0.3 x N = 150, N = 500.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b9af519-bc7b-4fb4-b60d-aa276a6d2ded', 'NC26.8.RD.2', 2, 'choice', 'Recognize a statistical question', 'Which question is a statistical question that compares four populations?', '["How many books did Eli read last month, and how does that compare with what he read the month before?","How many grades does our school have, counting every grade from grade 5 up to grade 8?","Did Eli or Mia read more books last month, and how many more did that person read?","How do the typical numbers of books read per month by students in grades 5, 6, 7 and 8 compare?"]', 'How do the typical numbers of books read per month by students in grades 5, 6, 7 and 8 compare?', NULL, 'The question about the typical numbers of books read in grades 5, 6, 7 and 8 names four groups and a measurement that varies from student to student. The other questions ask about one or two people or have a single answer.', 'checked', '{"lint":[],"solve":{"answer":"How do the typical numbers of books read per month by students in grades 5, 6, 7 and 8 compare?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Statistical (variability) and four populations (grades 5-8): typical books read per month by grades 5,6,7,8. Others are about one or two people or a single fact.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9df25c76-fb95-406c-9461-b9a86ff722a2', 'NC26.8.RD.2', 2, 'choice', 'Write a question that compares several populations', 'A student writes "Do people like the park?" to compare three neighborhoods. Which revision is the best statistical question?', '["Is the park nice enough that residents of the three neighborhoods would want to visit it?","How big is the park, in acres, that the residents of the three neighborhoods can visit?","How many times per month do residents of each of the three neighborhoods visit the park?","Do the residents of each of the three neighborhoods have a park in their neighborhood?"]', 'How many times per month do residents of each of the three neighborhoods visit the park?', NULL, 'The best revision names the three populations (residents of each neighborhood) and a measurement that varies (visits per month).', 'checked', '{"lint":[],"solve":{"answer":"How many times per month do residents of each of the three neighborhoods visit the park?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Best revision is measurable, variable, and names the three populations: visits per month by residents of each neighborhood. Others are opinion, single fact, or yes/no fact.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d3343640-5d1c-42cc-8e71-27263c62846b', 'NC26.8.RD.2', 2, 'choice', 'Write a question that compares several populations', 'A store owner wants to compare the number of items customers buy on Saturday, Sunday and Monday. Which plan fits this question?', '["Record how many customers come into the store on Saturday only, and nothing else","Record the number of items bought by customers on each of the three days","Ask one customer on each day which item is that customer''s favorite item","Record the price of the most expensive item that is sold on each of the three days"]', 'Record the number of items bought by customers on each of the three days', NULL, 'To compare items bought on the three days, the data must be the number of items per customer on each of the three days. The other plans collect different data or data for only one day.', 'checked', '{"lint":[],"solve":{"answer":"Record the number of items bought by customers on each of the three days","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Question compares items bought per customer across 3 days, so record items bought by customers on each of the three days.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a445fc0d-0cbb-4068-aae3-e868af74af33', 'NC26.8.RD.2', 2, 'choice', 'Spot a biased or unclear survey question', 'A survey asks "How much do you love our great new gym?" Which question is a fair replacement?', '["How would you rate the new gym on a scale from 1 (poor) to 5 (excellent)?","How much do you enjoy the great new gym that the school just built this year?","Do you love the new gym, now that it has so many exciting things to try?","Isn''t the new gym the best place at school for students to spend their free time?"]', 'How would you rate the new gym on a scale from 1 (poor) to 5 (excellent)?', NULL, 'The fair question gives a full range of answers and uses no loaded words. The others still use loaded words such as great, exciting or best, or ask only about love.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate the new gym on a scale from 1 (poor) to 5 (excellent)?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Neutral rating scale 1-5 removes ''love'' and ''great''. Other options keep loaded wording.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7acd87dd-4201-496a-a52b-648a62f61638', 'NC26.8.RD.2', 2, 'choice', 'Spot a biased or unclear survey question', 'Which problem does the survey question "Do you like pizza and tacos?" have?', '["It uses a loaded word that pushes people to answer yes about both of the foods","It is too long, since a good survey question must have fewer than five words","It asks for a number, so people cannot answer it with a simple yes or no","It asks about two things at once, so one answer may not fit what a person thinks"]', 'It asks about two things at once, so one answer may not fit what a person thinks', NULL, 'A student who likes pizza but not tacos cannot answer yes or no. A fair survey asks about one thing at a time.', 'checked', '{"lint":[],"solve":{"answer":"It asks about two things at once, so one answer may not fit what a person thinks","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double-barreled: asks about pizza and tacos at once; someone may like one only.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99c6703e-733e-4dca-8e61-4b781f5154af', 'NC26.8.RD.2', 2, 'choice', 'Identify bias in how a sample is chosen', 'A website posts a poll that asks, "Do you use the internet every day?" Why might the results be biased?', '["The poll asks too many people at once, so the results cannot be counted correctly","Only people who are online and choose to answer are counted, so others are left out","The website has too many pages, so people cannot find the poll to answer it","Everyone in the town sees the poll, which makes the sample too large to be fair"]', 'Only people who are online and choose to answer are counted, so others are left out', NULL, 'People who answer a poll on a website are online and chose to respond, so people who are not online are left out. The results favor internet users.', 'checked', '{"lint":[],"solve":{"answer":"Only people who are online and choose to answer are counted, so others are left out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Online voluntary poll on internet use includes only online people who choose to answer; non-users are excluded.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa4411f6-4286-427f-ab28-32a2604b1ea9', 'NC26.8.RD.2', 2, 'choice', 'Identify bias in how a sample is chosen', 'A researcher compares the commute times of workers in four towns by surveying 50 people in each town, but in Town C all 50 people are chosen at the train station. Why might the Town C results be biased?', '["There are 50 people from each town, which is too many people to give fair results in a comparison","The researcher surveyed four towns instead of one, so the towns cannot be compared fairly","People at the train station mostly commute by train, so they may not match all workers in the town","People at a train station are always in a hurry, so none of them would answer questions about commuting"]', 'People at the train station mostly commute by train, so they may not match all workers in the town', NULL, 'People at a train station are more likely to be train commuters, and their commute times may differ from those of other workers. The other reasons do not describe a problem with how the Town C sample was chosen.', 'checked', '{"lint":[],"solve":{"answer":"People at the train station mostly commute by train, so they may not match all workers in the town","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sampling at the train station over-represents train commuters, unlike other towns'' samples.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c70a3987-2bbd-4674-b978-ae4868cf4d75', 'NC26.8.RD.2', 2, 'choice', 'Identify and carry out random sampling', 'School A has 300 students, School B has 200 and School C has 500. A researcher wants a random sample of 30 students from the three schools together. Which plan gives every student the same chance of being chosen?', '["Ask each of the three principals to pick the 10 students that the principal thinks are typical","Choose the first 10 students on each school''s list, so that every school has the same number","Put the names of all 1,000 students on one list and choose 30 names with a random number generator","Choose all 30 students from School C, the largest school, because it has the most students of all"]', 'Put the names of all 1,000 students on one list and choose 30 names with a random number generator', NULL, 'One combined list and a random choice gives all 1,000 students the same chance. Asking principals, taking the first names on a list or using only one school does not.', 'checked', '{"lint":[],"solve":{"answer":"Put the names of all 1,000 students on one list and choose 30 names with a random number generator","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal chance for every one of 1000 students: one combined list and random selection of 30.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d6938b5-11e0-4058-9eac-6dcaea1ece54', 'NC26.8.RD.2', 2, 'choice', 'Judge whether a sample is valid for several populations', 'Which plan would be the best way to compare the reading time of students at four schools?', '["Take a random sample of the same size from each school and ask every student the same question","Ask only the best readers at each school, since they know how much time they spend reading","Take 100 students from one school and only 5 from each of the other three schools, then compare","Ask a different question at each school, so that every school can answer in its own way"]', 'Take a random sample of the same size from each school and ask every student the same question', NULL, 'To compare fairly, each school gets a random sample of a similar size and the same question. The other plans leave out typical students, use very unequal sample sizes or collect different data.', 'checked', '{"lint":[],"solve":{"answer":"Take a random sample of the same size from each school and ask every student the same question","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"''Same size'' is not strictly required for a fair comparison, but it is clearly the best option offered.","work":"Fair comparison: random samples, comparable size, same question at every school.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a714afcb-abe5-4de9-b472-58c75f7cf8c3', 'NC26.8.RD.2', 3, 'choice', 'Choose the sample that best represents several populations', 'A school has 300 students in each of grades 6, 7 and 8. A researcher wants to compare how much sleep students in each grade get. Which sample would best represent all of the school''s students?', '["The first 60 students who arrive at school in the morning","60 students who are on the school''s sports teams","60 students who choose to answer a poll on the school website","20 students chosen at random from each grade''s class list"]', '20 students chosen at random from each grade''s class list', NULL, 'A good sample is random and includes students from every grade. Choosing 20 at random from each grade''s list does that. The other samples are not random and may over-represent early arrivals, athletes or students who like to answer polls.', 'checked', '{"lint":[],"solve":{"answer":"20 students chosen at random from each grade''s class list","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from each grade (equal-sized grades) represents the whole school; the others are voluntary, convenience or biased (sports teams).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99d529be-c75e-4c16-ae96-714e3172428a', 'NC26.8.RD.2', 3, 'numeric', 'Estimate a probability from simulation results', 'Mia simulates choosing random samples of 10 students from a population in which 30% of students like soccer. She runs 25 trials. In 6 of the 25 trials, 5 or more of the 10 students in the sample liked soccer. Based on her simulation, what is the estimated probability, as a percent, that a random sample of 10 students has 5 or more who like soccer?', '[]', '24', '6/25*100', 'The estimate is the fraction of trials in which the event happened: $\frac{6}{25} = 0.24 = 24\%$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Estimated probability = 6/25 = 0.24 = 24%.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cdd81a0-10f8-4b72-8929-0c191f2c89f9', 'NC26.8.RD.2', 3, 'choice', 'Recognize an unbiased survey question', 'A student wants to ask classmates about their sleep. Which survey question is the least biased, meaning it does not push people toward a particular answer?', '["Don''t you agree that students sleep far too little?","How many hours do you usually sleep on a school night?","How terribly do you sleep on school nights?","Wouldn''t you say that you are always too tired at school?"]', 'How many hours do you usually sleep on a school night?', NULL, 'A fair question uses neutral wording. The other three questions use loaded words ("far too little", "terribly", "always too tired") that suggest the answer the writer expects.', 'checked', '{"lint":[],"solve":{"answer":"How many hours do you usually sleep on a school night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The neutral question asks for hours without leading wording.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa620905-3292-4508-8b84-c020ca662663', 'NC26.8.RD.2', 3, 'numeric', 'Recognize a statistical question', 'Here are five questions. (1) What is the typical number of text messages a teenager in our town sends each day? (2) How many text messages did Zoe send today? (3) How much does a ticket to the town fair cost? (4) How long do the students in each of four classes take to finish the same test? (5) What was the high temperature in our town yesterday? How many of the five are statistical questions?', '[]', '2', '2', 'Questions (1) and (4) ask about many people or classes, and the data will vary, so they are statistical. Questions (2), (3) and (5) each have a single answer. The answer is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) statistical, (2) one answer, (3) one price, (4) statistical, (5) one value. Count = 2.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43e2468c-6694-4992-b36f-1c7eb65ca860', 'NC26.8.RD.2', 3, 'choice', 'Spot a biased or unclear survey question', 'Which survey question about a school''s start time is least likely to bias the answers?', '["Wouldn''t you like school to start later so you can finally get enough sleep?","Most students want a later start. Do you want one too?","What start time would you prefer: 7:30, 8:00, 8:30 or 9:00?","Do you want school to start at the awful time of 7:30?"]', 'What start time would you prefer: 7:30, 8:00, 8:30 or 9:00?', NULL, 'The fair question gives a range of choices and no reason to pick one. The others suggest the "right" answer with phrases such as "finally get enough sleep", "most students want" and "awful".', 'checked', '{"lint":[],"solve":{"answer":"What start time would you prefer: 7:30, 8:00, 8:30 or 9:00?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Listing neutral time choices without loaded wording is least biased.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffdadc1a-f031-496f-8d6f-20989dd99176', 'NC26.8.RD.2', 3, 'numeric', 'Identify bias in how a sample is chosen', 'A town has 8,000 residents. A phone poll that called only landline numbers found that 70% of those reached support a new tax. A random sample of residents, reached by both landline and cell phone, found that 55% support it. If the random sample is trusted, how many fewer residents support the tax than the landline poll suggests?', '[]', '1200', '8000*(0.7-0.55)', 'The landline poll suggests 70% of 8,000 = 5,600 residents. The random sample suggests 55% of 8,000 = 4,400 residents. The difference is 5,600 - 4,400 = 1,200 residents.', 'checked', '{"lint":[],"solve":{"answer":"1200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Landline: 0.70 x 8000 = 5600. Random: 0.55 x 8000 = 4400. Difference 1200.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e76416c7-56d0-446f-9a0b-d11f113cb862', 'NC26.8.RD.2', 3, 'numeric', 'Identify and carry out random sampling', 'A systematic sample starts with student 4 on a list of 100 students and then takes every 6th student after that (4, 10, 16, and so on). How many students are in the sample?', '[]', '17', '17', 'The students chosen are 4, 10, 16, ..., 100. Each step adds 6, and (100 - 4) / 6 = 16 steps, so there are 16 + 1 = 17 students.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4, 10, ..., 4 + 6k <= 100 gives k <= 16, so k = 0..16: 17 students (last is 100).","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71c30e12-b3c4-43d5-b140-c4a73fc172be', 'NC26.8.RD.2', 3, 'numeric', 'Identify and carry out random sampling', 'A random number generator is used to choose 5 students from a list numbered 1 to 60. It produces 17, 42, 17, 8, 63, 55, 31. Repeated numbers and numbers over 60 are skipped. What is the sum of the numbers of the five students chosen?', '[]', '153', '17+42+8+55+31', 'Skip the second 17 (a repeat) and 63 (over 60). The students chosen are 17, 42, 8, 55 and 31. Their sum is 17 + 42 + 8 + 55 + 31 = 153.', 'checked', '{"lint":[],"solve":{"answer":"153","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 (1), 42 (2), 17 repeat skip, 8 (3), 63 > 60 skip, 55 (4), 31 (5). Sum 17 + 42 + 8 + 55 + 31 = 153.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('941b1744-8341-4dd4-bfa2-8b4ca1e2cbdc', 'NC26.8.RD.2', 3, 'choice', 'Design a simulation', 'One in 3 students at a school likes tea. Which tool can NOT be used to simulate choosing one student and seeing whether the student likes tea?', '["A number cube, with a 1 or 2 meaning the student likes tea","A spinner with 3 equal sections, one labeled tea","A bag with 1 green marble and 2 red marbles, with green meaning tea","A fair coin, with heads meaning the student likes tea"]', 'A fair coin, with heads meaning the student likes tea', NULL, 'A coin gives a chance of 1 in 2. A cube with two favorable faces, a spinner with 1 of 3 equal sections and a bag with 1 of 3 marbles each give a chance of 1 in 3.', 'checked', '{"lint":[],"solve":{"answer":"A fair coin, with heads meaning the student likes tea","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A coin gives 1/2, not 1/3. Cube 1-2 = 1/3, spinner 1 of 3, bag 1 of 3 all work.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3a2ca69-cda3-4ac7-bd3a-e1293ebe1e75', 'NC26.8.RD.2', 3, 'choice', 'Design a simulation', 'In a school, 25% of the students are in grade 6, 25% are in grade 7 and 50% are in grade 8. Random numbers from 1 to 20 are used to simulate choosing one student. Which assignment models this?', '["1 to 5 mean grade 6, 6 to 10 mean grade 7, and 11 to 15 mean grade 8","1 to 5 mean grade 6, 6 to 10 mean grade 7, and 11 to 20 mean grade 8","1 to 10 mean grade 6, 11 to 15 mean grade 7, and 16 to 20 mean grade 8","1 to 7 mean grade 6, 8 to 14 mean grade 7, and 15 to 20 mean grade 8"]', '1 to 5 mean grade 6, 6 to 10 mean grade 7, and 11 to 20 mean grade 8', NULL, '25% of 20 numbers is 5 numbers for grade 6, 5 numbers for grade 7 and 10 numbers for grade 8, which uses all 20 numbers. Giving grade 8 only 11 to 15 models just 25% for grade 8 and leaves 16 to 20 unassigned. Giving grade 6 the numbers 1 to 10 models 50% for grade 6, and the groups 7, 7 and 6 numbers model 35%, 35% and 30%.', 'checked', '{"lint":[],"solve":{"answer":"1 to 5 mean grade 6, 6 to 10 mean grade 7, and 11 to 20 mean grade 8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 numbers: 25% = 5, 25% = 5, 50% = 10. 1-5, 6-10, 11-20.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ca25c2e-253d-4f45-8a2b-868a11d8ef8f', 'NC26.8.RD.2', 3, 'numeric', 'Design a simulation', 'At a school, 30% of the students are in grade 6, 30% are in grade 7 and 40% are in grade 8. In a simulation, the digits 0 to 2 stand for grade 6, the digits 3 to 5 for grade 7 and the digits 6 to 9 for grade 8. The simulation makes these 20 digits: 5 8 1 9 0 3 6 2 7 4 8 8 1 6 9 0 5 7 2 6. How many more of the simulated students are in grade 8 than in grade 6?', '[]', '4', '10-6', 'Grade 8 digits (6 to 9): 8, 9, 6, 7, 8, 8, 6, 9, 7, 6, which is 10 digits. Grade 6 digits (0 to 2): 1, 0, 2, 1, 0, 2, which is 6 digits. The difference is 10 - 6 = 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 6 (0-2): 1,0,2,1,0,2 = 6. Grade 7 (3-5): 5,3,4,5 = 4. Grade 8 (6-9): 8,9,6,7,8,8,6,9,7,6 = 10. Total 20. 10 - 6 = 4.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83168e4c-acb5-47a9-9d9b-adb507b4dddd', 'NC26.8.RD.2', 3, 'numeric', 'Estimate a probability from simulation results', 'In a population, 40% of the students like soccer. A simulation takes 20 random samples of 5 students. The numbers of students who like soccer in the 20 samples are 2, 3, 1, 2, 0, 4, 1, 2, 3, 2, 0, 1, 3, 2, 1, 2, 2, 3, 0, 5. In what fraction of the 20 samples did exactly 2 students like soccer?', '[]', '7/20', '7/20', 'Count the samples with exactly 2 students: 7 of the 20 samples. The fraction is 7/20.', 'checked', '{"lint":[],"solve":{"answer":"7/20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Count 2s: 2,3,1,2,0,4,1,2,3,2,0,1,3,2,1,2,2,3,0,5 -> positions 1,4,8,10,14,16,17 = 7. 7/20.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7de1d9b-f931-40c2-849c-71ed6132ef32', 'NC26.8.RD.2', 3, 'numeric', 'Estimate a probability from simulation results', 'A simulation estimates that the chance a random sample of 8 students has 6 or more girls is 0.04. If 500 such random samples were taken, about how many would you expect to have 6 or more girls?', '[]', '20', '0.04*500', '0.04 of 500 samples is 0.04 x 500 = 20 samples.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.04 x 500 = 20.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('25318d52-d28e-4f22-b336-b9adb21353fd', 'NC26.8.RD.2', 3, 'numeric', 'Estimate a probability from simulation results', 'Simulation 1 has 40 trials and 14 of them are successes. Simulation 2 has 60 trials and 16 of them are successes. If the results of both simulations are combined, what is the estimated percent of trials that are successes?', '[]', '30', '(14+16)/(40+60)*100', 'Combined successes: 14 + 16 = 30. Combined trials: 40 + 60 = 100. The percent is 30 / 100 = 30%.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Combined: (14 + 16)/(40 + 60) = 30/100 = 30%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65405463-9a7d-48c2-8516-04183aafff76', 'NC26.8.RD.2', 3, 'numeric', 'Judge whether a sample is valid for several populations', 'A proportional random sample of 60 students from a school includes 18 eighth graders. What percent of the school''s students are in eighth grade?', '[]', '30', '18/60*100', 'In a proportional sample, the sample has the same share of eighth graders as the school. 18 / 60 = 0.3 = 30%.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Minor: \"proportional random sample\" is uncommon wording for Grade 8; as a plain random sample the result is only an estimate (\"about 30%\").","work":"18/60 = 0.3 = 30%.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4bc4039c-2571-4f75-b7bb-4054c1a0d1ab', 'NC26.8.RD.2', 3, 'numeric', 'Organize and summarize data from several populations', 'The times, in minutes, that 7 students at each of two schools take to reach school are listed. Pine: 5, 25, 10, 15, 30, 10, 20. Oak: 12, 14, 9, 11, 15, 10, 13. How many minutes greater is the median time at Pine than the median time at Oak?', '[]', '3', '15-12', 'Pine in order: 5, 10, 10, 15, 20, 25, 30, so the median is 15. Oak in order: 9, 10, 11, 12, 13, 14, 15, so the median is 12. The difference is 15 - 12 = 3 minutes.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pine sorted: 5,10,10,15,20,25,30 -> median 15. Oak sorted: 9,10,11,12,13,14,15 -> median 12. Difference 3.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89b148de-45a6-4ca6-a02b-58c18d218b0f', 'NC26.8.RD.2', 3, 'numeric', 'Organize and summarize data from several populations', 'Test scores for three classes are listed. Class 1: 70, 85, 90, 75. Class 2: 60, 95, 80, 85. Class 3: 88, 90, 86, 92. What is the range of the class whose scores are the most spread out?', '[]', '35', '95-60', 'Class 1 range: 90 - 70 = 20. Class 2 range: 95 - 60 = 35. Class 3 range: 92 - 86 = 6. The greatest range is 35.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges: Class 1: 90 - 70 = 20. Class 2: 95 - 60 = 35. Class 3: 92 - 86 = 6. Most spread out is Class 2 (also largest MAD): 35.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a6797ac-0578-4ee9-9696-c4226a8e4b4c', 'NC26.8.RD.2', 3, 'numeric', 'Use random samples to predict for populations', 'A random sample of 40 students at School A shows that 14 have pets. A random sample of 60 students at School B shows that 15 have pets. School A has 800 students and School B has 1,200 students. About how many more students are predicted to have pets at School B than at School A?', '[]', '20', '15/60*1200-14/40*800', 'School A: 14/40 = 35% of 800 = 280 students. School B: 15/60 = 25% of 1,200 = 300 students. School B has 300 - 280 = 20 more.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 14/40 = 0.35 x 800 = 280. B: 15/60 = 0.25 x 1200 = 300. Difference 20.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8748d924-5acc-42d3-ba23-19f98b27ff31', 'NC26.8.RD.2', 3, 'numeric', 'Use random samples to predict for populations', 'A random sample of 50 students from a school of 900 found 9 who are vegetarian. A second random sample of 100 students from the same school found 17 vegetarians. Combine the two samples to predict how many of the 900 students are vegetarian.', '[]', '156', '(9+17)/(50+100)*900', 'Combined, there are 9 + 17 = 26 vegetarians among 50 + 100 = 150 students. That is 26/150 of the students. Predict 26/150 x 900 = 156 students.', 'checked', '{"lint":[],"solve":{"answer":"156","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Combined: (9 + 17)/(50 + 100) = 26/150. 26/150 x 900 = 26 x 6 = 156.","run_id":"claude-code","at":"2026-10-18T01:07:55.285Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0220db67-4bf8-4cba-841e-134ee6e0a18b', 'NC26.8.RD.2', 3, 'choice', 'Recognize a statistical question', 'Which question is a statistical question?', '["How old is the principal of Lake School, who has led the school for many years?","What is the typical age of the teachers who teach at Lake School this year?","How many students go to Lake School, including the new students this year?","What time does school start at Lake School on a normal weekday morning?"]', 'What is the typical age of the teachers who teach at Lake School this year?', NULL, 'The teachers at the school have different ages, so the data vary and the question asks for a typical value. The other questions each have one answer.', 'checked', '{"lint":[],"solve":{"answer":"What is the typical age of the teachers who teach at Lake School this year?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Typical age of teachers varies among teachers -> statistical. Others have a single answer.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('82637548-cf7c-449f-b717-da1426144981', 'NC26.8.RD.2', 3, 'choice', 'Write a question that compares several populations', 'Which question names the populations and says what will be measured?', '["Do kids who go to school in the middle grades do their homework when they get home from school?","How much homework is there for the students who go to school at Oak Middle School?","What do the students at Oak Middle School think about school, their teachers and their classes?","How many minutes per night do 6th, 7th and 8th graders at Oak Middle School spend on homework?"]', 'How many minutes per night do 6th, 7th and 8th graders at Oak Middle School spend on homework?', NULL, 'The question about 6th, 7th and 8th graders at Oak Middle School names three groups and the measurement (minutes per night on homework). The other questions are too vague.', 'checked', '{"lint":[],"solve":{"answer":"How many minutes per night do 6th, 7th and 8th graders at Oak Middle School spend on homework?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Names populations (6th, 7th, 8th graders at Oak MS) and measure (minutes per night on homework).","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2969a90-1db4-4082-84d7-3594f428a41e', 'NC26.8.RD.2', 3, 'choice', 'Write a question that compares several populations', 'Which question can be investigated by sampling each of four populations and gives numerical data for all four?', '["What is the favorite color of each of the teens, young adults, adults and seniors in our town?","How many people live in our town, counting the teens, young adults, adults and seniors?","How many text messages per day do teens, young adults, adults and seniors in our town send?","Do the seniors in our town have phones, or do they prefer to use a landline at home?"]', 'How many text messages per day do teens, young adults, adults and seniors in our town send?', NULL, 'The question about text messages has four populations (the four age groups) and a number for each person. A favorite color is not a number, and the other questions concern one population or one answer.', 'checked', '{"lint":[],"solve":{"answer":"How many text messages per day do teens, young adults, adults and seniors in our town send?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerical data and four populations: texts per day by teens, young adults, adults, seniors. Favorite color is categorical; town population is one number; seniors only is one population and categorical.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2282471-d3d8-4598-a636-8d12cdfd0544', 'NC26.8.RD.2', 3, 'choice', 'Write a question that compares several populations', 'In the question "How do the numbers of siblings of students in grades 6, 7 and 8 compare?", what is the variable being measured and what separates the populations?', '["The variable is the number of siblings, and the populations are the students in each grade","The variable is the grade, and the populations are the numbers of siblings that students have","The variable is the number of students, and the populations are the siblings in each grade","The variable is the school, and the population is all of the siblings of the students in the school"]', 'The variable is the number of siblings, and the populations are the students in each grade', NULL, 'Each student gives a number of siblings, which is the variable. The students are separated into populations by grade.', 'checked', '{"lint":[],"solve":{"answer":"The variable is the number of siblings, and the populations are the students in each grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Measured variable: number of siblings; populations separated by grade.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6925645d-444c-4364-8fd4-0f812f937c6c', 'NC26.8.RD.2', 3, 'choice', 'Spot a biased or unclear survey question', 'Which survey question should be split into two separate questions?', '["How many books do you check out of the library in each month of the school year, on average?","What time do you usually visit the library on a school day after your classes?","Which library service do you use most often, such as books, computers or study rooms?","Do you think the library should have longer hours and also have more computers for students?"]', 'Do you think the library should have longer hours and also have more computers for students?', NULL, 'A person may want longer hours but not more computers, so one answer cannot fit both ideas. The question should be split.', 'checked', '{"lint":[],"solve":{"answer":"Do you think the library should have longer hours and also have more computers for students?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Longer hours and also more computers'' asks two things at once.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d573ca32-d7e0-45f5-b290-2fc55fa3ecdb', 'NC26.8.RD.2', 3, 'choice', 'Spot a biased or unclear survey question', 'Students are asked, "How many hours do you sleep on a school night?" Which set of answer choices covers every possible answer with no overlaps?', '["At least 0 and at most 6; at least 6 and at most 8; at least 8 and at most 10; at least 10 and at most 12","Less than 6; at least 6 and less than 8; at least 8 and less than 10; 10 or more","Less than 6; at least 6 and less than 8; at least 9 and less than 10; 11 or more","5 hours or less; exactly 6 or 7 hours; exactly 8 hours; exactly 9 or 10 hours"]', 'Less than 6; at least 6 and less than 8; at least 8 and less than 10; 10 or more', NULL, 'Good answer choices leave no gaps and have no overlaps. The set starting with "Less than 6" and ending with "10 or more" covers every number of hours exactly once. The set of ranges that begin and end at the same numbers overlaps at 6, 8 and 10. The other two sets leave out possible answers such as 8.5 hours, and the last also leaves out 5.5 hours and 12 hours.', 'checked', '{"lint":[],"solve":{"answer":"Less than 6; at least 6 and less than 8; at least 8 and less than 10; 10 or more","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Option 1: <6, [6,8), [8,10), >=10 -- covers all nonnegative values, no overlap. Option 2 overlaps at 6,8,10 and misses >12. Option 3 has gaps (e.g. 5.5, 7.5). Option 4 misses [8,9) and [10,11).","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5629357f-bb7d-4bb4-b91a-9e60ac97d447', 'NC26.8.RD.2', 3, 'choice', 'Identify bias in how a sample is chosen', 'A researcher compares how many hours students at Schools A, B and C spend on homework. At School A she surveys students in the after-school homework club, at School B she surveys a random sample, and at School C she surveys students in the library. Why can''t she fairly compare the three schools?', '["She surveyed three schools instead of one, so the results cannot be compared with one another","Homework cannot be compared between schools, because every school gives its own kind of homework to students","She should have surveyed fewer students at School B, since a random sample must always be the smallest","The samples were chosen in different ways, so differences may come from how the students were picked"]', 'The samples were chosen in different ways, so differences may come from how the students were picked', NULL, 'Students in a homework club or in the library may do more homework than typical students, but the random sample is typical. A difference may reflect how the samples were chosen and not the schools themselves.', 'checked', '{"lint":[],"solve":{"answer":"The samples were chosen in different ways, so differences may come from how the students were picked","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Different selection methods (homework club, random, library) introduce different biases, so differences may reflect sampling not schools.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('725493ee-8f46-4dc4-b2b9-0c23bb10741a', 'NC26.8.RD.2', 3, 'choice', 'Identify bias in how a sample is chosen', 'A school emails a survey about a new bus schedule to all 800 families. Only 12% reply. What is the biggest concern?', '["Families with strong opinions are more likely to reply, so the replies may not represent everyone","A reply rate of 12% is too high, so the replies are too many to give a fair picture of the 800 families","Email surveys cannot reach families, so the school learned nothing from any of the replies","The school should have asked fewer families, because a survey of 800 families is too large"]', 'Families with strong opinions are more likely to reply, so the replies may not represent everyone', NULL, 'When few people reply, those who do are often the ones who feel strongly. Their answers may differ from the opinions of the families who did not reply.', 'checked', '{"lint":[],"solve":{"answer":"Families with strong opinions are more likely to reply, so the replies may not represent everyone","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Low response rate -> nonresponse/voluntary bias: those with strong opinions more likely reply.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ab4487c-7c02-4b81-930a-8c8ad3140595', 'NC26.8.RD.2', 3, 'choice', 'Identify bias in how a sample is chosen', 'A researcher compares grades 5, 6, 7 and 8 and takes the first 25 students from each grade who turn in a permission form. Why might this sample be biased?', '["She sampled the same number of students from each grade, but a fair comparison needs different numbers","She sampled four grades instead of one, and a fair comparison must use only one grade at a time","Students who turn in forms first may differ from the other students in the grade","Permission forms are not allowed in surveys, so the students she asked cannot be counted"]', 'Students who turn in forms first may differ from the other students in the grade', NULL, 'The students who return forms first may be more organized or more interested than the rest, so they may not be typical of the grade. The sample was not chosen by chance.', 'checked', '{"lint":[],"solve":{"answer":"Students who turn in forms first may differ from the other students in the grade","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First to turn in forms is a non-random group that may differ (more organised etc.).","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36f52e9b-6d13-484a-9a50-ece9fcfb5c28', 'NC26.8.RD.2', 3, 'choice', 'Identify and carry out random sampling', 'Nia says, "My sample is random because I picked students from all four grades." Which response is best?', '["She is right, because using students from all four grades always makes a sample random, whoever is picked","She is not yet right, because a sample is random only if the students in each grade were chosen by chance","She is wrong, because a random sample can never include students from every one of the grades","She is right, because the sample is large, and every large sample is a random sample"]', 'She is not yet right, because a sample is random only if the students in each grade were chosen by chance', NULL, 'What makes a sample random is that chance decides who is chosen. Including all four grades is useful, but Nia could still have picked her friends in each grade.', 'checked', '{"lint":[],"solve":{"answer":"She is not yet right, because a sample is random only if the students in each grade were chosen by chance","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Wording ''She is not yet right'' is slightly odd; the key point holds.","work":"Including all grades does not make a sample random; random requires selection by chance. Option 1.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb5c2a45-a3bb-4532-8586-1aa1619c92d6', 'NC26.8.RD.2', 3, 'choice', 'Design a simulation', 'A simulation of samples of 10 students from a school where 40% like soccer is run 20 times and then 200 times. Which statement is most likely true?', '["The two estimates will be exactly the same, because they come from the same model","20 trials give a more exact answer than 200 trials, because there is less to average","The estimate of the chance from 200 trials is probably closer to the true chance","Running more trials changes what the model stands for, so the 200 trials model a different school"]', 'The estimate of the chance from 200 trials is probably closer to the true chance', NULL, 'More trials make the estimate settle closer to the true chance. The number of trials does not change the model, and two runs will usually not agree exactly.', 'checked', '{"lint":[],"solve":{"answer":"The estimate of the chance from 200 trials is probably closer to the true chance","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"More trials give a more stable estimate, probably closer to the true probability.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0855883c-c9a5-46c4-a294-bb9fa1424e22', 'NC26.8.RD.2', 3, 'choice', 'Estimate a probability from simulation results', 'A school has 50% pizza fans. In a simulation of 100 random samples of 10 students, 9 or 10 pizza fans happened in only 1 of the 100 samples. A real random sample of 10 students from another school has 9 pizza fans. What does this suggest?', '["The other school probably has more than 50% pizza fans, since 9 of 10 is rare when the true percent is 50%","Exactly 90% of all of the students at the other school like pizza, since 9 out of the 10 students in the sample do","The real sample must be wrong because it differs from the simulation, so it should be taken again","Nothing can be learned from a random sample of 10, because a sample that small is always meaningless"]', 'The other school probably has more than 50% pizza fans, since 9 of 10 is rare when the true percent is 50%', NULL, 'In the simulation, a sample like this happened only about 1% of the time when the true percent is 50%. So it is likely that the other school has more than 50% pizza fans. A sample suggests a percent but does not prove an exact one.', 'checked', '{"lint":[],"solve":{"answer":"The other school probably has more than 50% pizza fans, since 9 of 10 is rare when the true percent is 50%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Under 50%, 9+ of 10 occurred 1/100 times (true P = 11/1024 ~ 1.1%), so 9 of 10 is unusual -> evidence the other school has more than 50% pizza fans.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('babaa2cd-0cd4-4e43-8aab-e7cfadea2fd4', 'NC26.8.RD.2', 3, 'choice', 'Judge whether a sample is valid for several populations', 'Two researchers compare bike ownership at three schools with 200, 600 and 1,200 students. Researcher A takes a random sample of 20 students from each school. Researcher B takes a random sample of 60 students from each school. Which gives more reliable information for comparing the schools, and why?', '["Researcher A, because fewer students are asked, so each of the answers can be checked closely","Neither, because the schools have different sizes, so the same sample size cannot be used","Neither, because a sample can never be used to compare schools, only asking everyone can","Researcher B, because larger random samples vary less from the true percents of each school"]', 'Researcher B, because larger random samples vary less from the true percents of each school', NULL, 'Larger random samples give percents that are closer to the true percents for each school. The school sizes do not make a smaller sample better.', 'checked', '{"lint":[],"solve":{"answer":"Researcher B, because larger random samples vary less from the true percents of each school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger random samples have less sampling variability: Researcher B (60 each).","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aa7dd6d-66aa-40b0-9378-5465c378c4bf', 'NC26.8.RD.2', 3, 'choice', 'Judge whether a sample is valid for several populations', 'Two random samples of 20 students each are taken at School A and School B. The sample from School A shows that 40% own a bike, and the sample from School B shows that 45% own a bike. Why shouldn''t the researcher conclude that more students at School B own a bike?', '["Samples should be taken from only one school, because two schools cannot be compared by sampling","Random samples are never reliable, because they are chosen by chance and not by the researcher","Random samples of 20 can differ by chance, so a difference of 5 percentage points may not be real","Bike percents cannot be compared between schools, because each school has different students"]', 'Random samples of 20 can differ by chance, so a difference of 5 percentage points may not be real', NULL, 'Small random samples vary from the true percent just by chance, so a 5-point difference could be due to chance. Larger samples would give a better comparison.', 'checked', '{"lint":[],"solve":{"answer":"Random samples of 20 can differ by chance, so a difference of 5 percentage points may not be real","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"With n=20, 40% vs 45% is 8 vs 9 students; sampling variability easily explains that. Option 4.","run_id":"claude-code","at":"2026-10-18T03:32:33.469Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d171f08c-e5c9-4df7-874c-6cb707dedf90', 'NC26.8.RD.3', 1, 'numeric', 'Compare the ranges of two data sets', 'Data set P is 3, 5, 5, 8, 9. Data set Q is 1, 4, 6, 7, 12. How much greater is the range of Q than the range of P?', '[]', '5', '(12-1)-(9-3)', 'The range of P is $9 - 3 = 6$. The range of Q is $12 - 1 = 11$. The difference is $11 - 6 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range P = 9 - 3 = 6. Range Q = 12 - 1 = 11. Difference = 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d18d25c-03ec-4b5a-b664-3f25fb1ec448', 'NC26.8.RD.3', 1, 'choice', 'Compare the medians of two data sets', 'Quiz scores for two classes are listed. Class A: 70, 75, 80, 85, 90. Class B: 60, 78, 82, 84, 96. Which statement is true?', '["Class B''s median is 2 points higher than Class A''s median","Class A''s median is 2 points higher than Class B''s median","The two classes have the same median","Class B''s median is 16 points higher than Class A''s median"]', 'Class B''s median is 2 points higher than Class A''s median', NULL, 'The median is the middle value of the ordered list. Class A: 80. Class B: 82. So Class B''s median is 2 points higher. (The two classes have the same mean, 80, but not the same median. The ranges are 20 and 36, which differ by 16.)', 'checked', '{"lint":[],"solve":{"answer":"Class B''s median is 2 points higher than Class A''s median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median A = 80 (middle of 5). Median B = 82. B is 2 points higher.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08b49d5a-bc05-449b-9099-7fb372e41e17', 'NC26.8.RD.3', 1, 'numeric', 'Find the smallest range among three data sets', 'Three data sets are listed. Set X: 12, 15, 18, 20. Set Y: 10, 11, 13, 14. Set Z: 5, 9, 12, 21. What is the smallest range of the three sets?', '[]', '4', '14-10', 'Set X: $20 - 12 = 8$. Set Y: $14 - 10 = 4$. Set Z: $21 - 5 = 16$. The smallest range is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range X = 20 - 12 = 8; Y = 14 - 10 = 4; Z = 21 - 5 = 16. Smallest = 4.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bcd8b530-a077-45fb-9d42-dcd9bac4608d', 'NC26.8.RD.3', 1, 'numeric', 'Compare the centers (mean or median) of several data sets', 'Three gardens were checked on three days, and the number of tomatoes picked each day is listed. Garden X: 4, 6, 8. Garden Y: 5, 7, 9. Garden Z: 2, 5, 8. How much greater is the greatest of the three means than the least of the three means?', '[]', '2', '(5+7+9)/3-((2+5+8)/3)', 'The means are 6 (Garden X), 7 (Garden Y) and 5 (Garden Z). The greatest is 7 and the least is 5, so the difference is $7 - 5 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means: X = 18/3 = 6, Y = 21/3 = 7, Z = 15/3 = 5. Greatest minus least = 7 - 5 = 2.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('776d66fb-560d-4736-8d22-1433bc679078', 'NC26.8.RD.3', 1, 'choice', 'Compare the centers (mean or median) of several data sets', 'Four classes each asked five students how many pets they have. Class A: 0, 1, 2, 2, 3. Class B: 1, 1, 1, 4, 9. Class C: 2, 2, 3, 3, 4. Class D: 0, 0, 2, 6, 7. Which class has the greatest median number of pets?', '["Class A","Class B","Class C","Class D"]', 'Class C', NULL, 'Each list is already in order, so the median is the middle value: Class A has 2, Class B has 1, Class C has 3 and Class D has 2. The greatest median is 3, in Class C. (Class B has the greatest mean, but the question asks for the median.)', 'checked', '{"lint":[],"solve":{"answer":"Class C","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians (middle of 5 sorted): A 2, B 1, C 3, D 2. Greatest is Class C.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ffa6385f-698e-4852-8bc2-404c92982247', 'NC26.8.RD.3', 1, 'numeric', 'Compare the centers (mean or median) of several data sets', 'Two sets of numbers are listed in the order they were collected. Set P: 8, 3, 9, 5, 7. Set Q: 11, 2, 13, 10, 6. How much greater is the median of Set Q than the median of Set P?', '[]', '3', '10-7', 'Put each set in order. Set P: 3, 5, 7, 8, 9, so its median is 7. Set Q: 2, 6, 10, 11, 13, so its median is 10. The difference is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P sorted 3, 5, 7, 8, 9: median 7. Q sorted 2, 6, 10, 11, 13: median 10. 10 - 7 = 3.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8576322b-cf87-470a-96eb-8166dfb40d1e', 'NC26.8.RD.3', 1, 'choice', 'Compare the centers (mean or median) of several data sets', 'Four data sets are listed. Which data set has a mean of 10?', '["3, 5, 8, 14, 20","2, 5, 10, 15, 20","6, 8, 10, 12, 13","10, 10, 10, 10, 20"]', '3, 5, 8, 14, 20', NULL, 'The mean is the sum divided by the number of values. For 3, 5, 8, 14, 20 the sum is 50 and 50 divided by 5 is 10. The other sets have means 10.4, 9.8 and 12. (Three of the sets have a median of 10, but the question asks for the mean.)', 'checked', '{"lint":[],"solve":{"answer":"3, 5, 8, 14, 20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sums: 49 (mean 9.8), 52 (10.4), 50 (10), 60 (12). Only 3, 5, 8, 14, 20 has mean 10.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4577c4d7-78db-444c-81d4-205c94f61506', 'NC26.8.RD.3', 1, 'numeric', 'Compare the spread (range or interquartile range) of several data sets', 'Three sets of numbers are listed. Set W: 5, 9, 14. Set X: 8, 10, 11, 12. Set Y: 2, 4, 6, 8, 10. What is the greatest range of the three sets?', '[]', '9', '14-5', 'The ranges are $14 - 5 = 9$ for Set W, $12 - 8 = 4$ for Set X and $10 - 2 = 8$ for Set Y. The greatest is 9.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges: W 14 - 5 = 9, X 12 - 8 = 4, Y 10 - 2 = 8. Greatest 9.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
