INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('48f70bfb-9d4d-4356-a610-2e2fea837ebf', 'NC26.8.RD.3', 1, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'Four teams each had three jumpers in a long-jump contest. The distances, in meters, are listed. Red team: 3.1, 3.4, 3.2. Blue team: 2.8, 3.9, 3.3. Green team: 3.0, 3.6, 3.1. Gold team: 2.9, 3.5, 3.0. Which team has the smallest range of distances?', '["Blue team","Red team","Green team","Gold team"]', 'Red team', NULL, 'Range is the greatest distance minus the least distance. Red: $3.4 - 3.1 = 0.3$. Blue: $3.9 - 2.8 = 1.1$. Green: $3.6 - 3.0 = 0.6$. Gold: $3.5 - 2.9 = 0.6$. The smallest range is 0.3, the Red team.', 'checked', '{"lint":[],"solve":{"answer":"Red team","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges: Red 3.4 - 3.1 = 0.3, Blue 3.9 - 2.8 = 1.1, Green 3.6 - 3.0 = 0.6, Gold 3.5 - 2.9 = 0.6. Red smallest.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2cc8cd37-2f87-4282-b93e-01a48bef75f0', 'NC26.8.RD.3', 1, 'numeric', 'Compare the spread (range or interquartile range) of several data sets', 'Two bus routes were timed on five mornings. The trip times in minutes are listed. Route 1: 12, 18, 15, 20, 11. Route 2: 16, 17, 15, 18, 16. How many minutes greater is the range of Route 1 than the range of Route 2?', '[]', '6', '(20-11)-(18-15)', 'Route 1 has a range of $20 - 11 = 9$ minutes. Route 2 has a range of $18 - 15 = 3$ minutes. The difference is $9 - 3 = 6$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Route 1 range 20 - 11 = 9. Route 2 range 18 - 15 = 3. 9 - 3 = 6.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('950ceb9b-eda5-4ac7-83bb-a44252a62a24', 'NC26.8.RD.3', 1, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'Three sets all have a mean of 5. Set A: 5, 5, 5, 5. Set B: 3, 4, 6, 7. Set C: 1, 5, 5, 9. Which statement is true?', '["Set A has a range of 5","Set B and Set C have the same range","Set C has the greatest range","Set B has the smallest range"]', 'Set C has the greatest range', NULL, 'The ranges are $5 - 5 = 0$ for Set A, $7 - 3 = 4$ for Set B and $9 - 1 = 8$ for Set C. Set C has the greatest range. Set A has the smallest range (its values are all the same), and Sets B and C do not have equal ranges.', 'checked', '{"lint":[],"solve":{"answer":"Set C has the greatest range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges: A 0, B 7 - 3 = 4, C 9 - 1 = 8. Only ''Set C has the greatest range'' is true (A''s range is 0, B''s is not smallest).","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('590b4ad5-1d23-4d27-8ca7-0f19c097179d', 'NC26.8.RD.3', 1, 'choice', 'Describe and compare the shapes of distributions', 'A quiz had scores from 1 to 5. The number of students at each score was: score 1, one student; score 2, three students; score 3, six students; score 4, three students; score 5, one student. Which best describes the shape of the data?', '["Symmetric, with one peak in the middle","Skewed right, with a long tail toward high scores","Skewed left, with a long tail toward low scores","Two separate peaks with a gap between them"]', 'Symmetric, with one peak in the middle', NULL, 'The counts rise to a single peak at score 3 and fall away in the same way on both sides (1, 3, 6, 3, 1). The two halves match, so the shape is symmetric with one peak in the middle.', 'checked', '{"lint":[],"solve":{"answer":"Symmetric, with one peak in the middle","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 1, 3, 6, 3, 1: mirror image around score 3, single peak at 3: symmetric.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab5fd390-901a-4aea-9544-34f4c23e01de', 'NC26.8.RD.3', 1, 'choice', 'Describe and compare the shapes of distributions', 'Four data sets are listed. Which one has two clusters with a large gap between them?', '["1, 2, 2, 3, 3, 4","1, 2, 2, 10, 11, 11","5, 5, 6, 6, 7, 8","3, 4, 5, 6, 7, 8"]', '1, 2, 2, 10, 11, 11', NULL, 'Look for a big jump between neighbouring values. In 1, 2, 2, 10, 11, 11, the values stay near 1 and 2, then jump to 10 and 11: two clusters with a gap of 7 between them. The other sets move up in steps of 1 or 0.', 'checked', '{"lint":[],"solve":{"answer":"1, 2, 2, 10, 11, 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1, 2, 2 and 10, 11, 11 form two clusters with a gap from 2 to 10. Others are spread evenly.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63100ac2-a85d-4988-99c7-b3a7594d1546', 'NC26.8.RD.3', 1, 'numeric', 'Plot several data sets on one number line', 'Three data sets are going to be plotted on one number line. Set A: 3, 8, 12. Set B: 5, 9, 15. Set C: 1, 7, 10. How far is it on the number line from the lowest value of all three sets to the highest value of all three sets?', '[]', '14', '15-1', 'The lowest value in any set is 1 (Set C) and the highest is 15 (Set B). The distance between them is $15 - 1 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lowest of all is 1 (Set C), highest 15 (Set B). 15 - 1 = 14.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0f19e9d7-15c1-4f7f-926c-b8c81355ca96', 'NC26.8.RD.3', 1, 'choice', 'Plot several data sets on one number line', 'Three sets will be plotted on one number line. Set A: 4, 9, 17. Set B: 12, 25, 31. Set C: 7, 22, 38. Which number line can show every value?', '["A line from 0 to 30","A line from 5 to 35","A line from 10 to 40","A line from 0 to 40"]', 'A line from 0 to 40', NULL, 'The lowest value is 4 and the highest is 38, so the line must start at 4 or lower and end at 38 or higher. Only the line from 0 to 40 does both. The line from 0 to 30 misses 31 and 38, the line from 5 to 35 misses 4 and 38, and the line from 10 to 40 misses 4, 7 and 9.', 'checked', '{"lint":[],"solve":{"answer":"A line from 0 to 40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values run from 4 to 38. Only 0 to 40 contains both; 0-30 misses 31 and 38, 5-35 misses 4 and 38, 10-40 misses 4, 7, 9.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f9fb37f-dd66-4c89-ad4d-2cac708c51b0', 'NC26.8.RD.3', 1, 'numeric', 'Plot several data sets on one number line', 'Three data sets are shown as dot plots on the same number line, with one dot above a number each time that number occurs in a set. Set A: 2, 4, 4, 7. Set B: 4, 5, 7, 7, 9. Set C: 1, 4, 7. In all, how many dots are above the number 4?', '[]', '4', NULL, 'Count the 4s in each set: Set A has two 4s, Set B has one and Set C has one. The total is $2 + 1 + 1 = 4$ dots.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 appears twice in A, once in B, once in C: 4 dots.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('be6b01e6-2aa4-4a92-a560-afd506fd5e3d', 'NC26.8.RD.3', 1, 'choice', 'Plot several data sets on one number line', 'Three data sets are plotted on one number line. Two sets overlap when the stretch of line from the lowest to the highest value of one set shares some part with the other set''s stretch. Set A: 2, 3, 5, 6. Set B: 5, 6, 7, 8. Set C: 11, 12, 12, 13. Which statement is true?', '["Sets A and B overlap, and Set C is apart from both","Sets B and C overlap","All three sets overlap","No two of the sets overlap"]', 'Sets A and B overlap, and Set C is apart from both', NULL, 'Set A covers 2 to 6, Set B covers 5 to 8 and Set C covers 11 to 13. A and B share the stretch from 5 to 6, so they overlap. Set C starts at 11, after Set B ends at 8, so it overlaps neither of the others.', 'checked', '{"lint":[],"solve":{"answer":"Sets A and B overlap, and Set C is apart from both","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A spans 2-6, B spans 5-8, C spans 11-13. A and B share 5-6; C touches neither.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('528d3b63-3ca3-49cc-8246-8507d7a29e38', 'NC26.8.RD.3', 1, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display shows quiz scores. In it, a stem of 2 with a leaf of 1 means a score of 21. Stem 2 has the leaves 1, 4, 4 and 7. Stem 3 has the leaves 0, 4, 4, 4 and 9. The mode is the value that occurs most often. What is the mode?', '[]', '34', NULL, 'Write out the scores: 21, 24, 24, 27, 30, 34, 34, 34, 39. The score 34 appears three times, more than any other score, so the mode is 34.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scores 21, 24, 24, 27, 30, 34, 34, 34, 39. 34 occurs 3 times: mode 34.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41604a3a-e9c2-4804-8955-1f92a3aa00aa', 'NC26.8.RD.3', 1, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display shows the ages of people at a picnic. A stem of 1 with a leaf of 2 means 12 years old. Stem 1 has the leaves 2, 4, 7. Stem 2 has the leaves 0, 3, 3, 9. Stem 3 has the leaves 1, 5. How many of the people are 20 years old or older?', '[]', '6', NULL, 'The ages are 12, 14, 17, 20, 23, 23, 29, 31, 35. The ages that are at least 20 are those on stems 2 and 3: 20, 23, 23, 29, 31, 35. That is 6 people.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ages 12, 14, 17, 20, 23, 23, 29, 31, 35. 20 or older: 20, 23, 23, 29, 31, 35 = 6.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3bcfb5b5-ff90-4676-89b4-4c8d77ffc78d', 'NC26.8.RD.3', 1, 'choice', 'Read a stem-and-leaf display', 'A stem-and-leaf display shows the weights, in pounds, of some puppies. A stem of 5 with a leaf of 1 means 51 pounds. Stem 5 has the leaves 1, 6. Stem 6 has the leaves 0, 3, 3, 8. Stem 7 has the leaves 2, 4. What is the range of the weights, in pounds?', '["8","13","23","24"]', '23', '74-51', 'The weights are 51, 56, 60, 63, 63, 68, 72, 74. The heaviest is 74 and the lightest is 51, so the range is $74 - 51 = 23$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Weights 51, 56, 60, 63, 63, 68, 72, 74. Range 74 - 51 = 23.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a8f6837-7060-4802-9d71-f89a9c4f7599', 'NC26.8.RD.3', 1, 'choice', 'Read and compare box plots from five-number summaries', 'Two box plots are described by their minimum, Q1, median, Q3 and maximum. Box plot A: 3, 7, 10, 14, 20. Box plot B: 5, 9, 12, 15, 18. Which statement is true?', '["Box plot B has the greater median","Box plot A has the greater minimum","Box plot A has the smaller range","Box plot B has the longer box"]', 'Box plot B has the greater median', NULL, 'Medians: A is 10 and B is 12, so B has the greater median. Minimums: 3 and 5, so B has the greater minimum. Ranges: $20 - 3 = 17$ for A and $18 - 5 = 13$ for B, so A has the greater range. Boxes: $14 - 7 = 7$ for A and $15 - 9 = 6$ for B, so A has the longer box.', 'checked', '{"lint":[],"solve":{"answer":"Box plot B has the greater median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: range 17, box 7, median 10, min 3. B: range 13, box 6, median 12, min 5. Only ''B has the greater median'' is true.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fccc2b0e-7ec8-45a2-8753-dc758fd3a5c0', 'NC26.8.RD.3', 1, 'numeric', 'Read a histogram or frequency table', 'A histogram shows how many books 30 students read this summer. The bar for 0 to 2 books shows 4 students, the bar for 3 to 5 books shows 11 students, the bar for 6 to 8 books shows 9 students and the bar for 9 to 11 books shows 6 students. How many students read 6 or more books?', '[]', '15', '9+6', 'The students who read 6 or more books are in the last two bars: $9 + 6 = 15$ students.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6-8: 9, 9-11: 6. 9 + 6 = 15.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
