INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7ec24e6-c519-4884-9996-df12def0af54', 'NC26.8.RD.3', 1, 'numeric', 'Draw a conclusion by comparing groups in context', 'A school gives a prize to each class whose median score is at least 70. Class A: 65, 70, 80. Class B: 55, 60, 90. Class C: 70, 72, 74. Class D: 50, 75, 78. How many classes get a prize?', '[]', '3', NULL, 'The medians are 70 (Class A), 60 (Class B), 72 (Class C) and 75 (Class D). Classes A, C and D have a median of at least 70, so 3 classes get a prize. (Class B has a very high score, but its median is only 60.)', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians: A 70 (yes), B 60 (no), C 72 (yes), D 75 (yes). 3 classes.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
