INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee4c31cf-4aae-462d-a1d7-399fe1905dd8', 'NC26.8.RD.3', 1, 'choice', 'Draw a conclusion by comparing groups in context', 'The minutes that five customers waited were recorded at two cafes. Cafe 1: 2, 4, 6, 8, 10. Cafe 2: 5, 5, 6, 7, 7. Which statement is true?', '["Cafe 1 has the shorter mean wait","The waits at Cafe 2 vary more than the waits at Cafe 1","Every wait at Cafe 1 was longer than every wait at Cafe 2","The mean waits are equal, but the waits at Cafe 2 are more consistent"]', 'The mean waits are equal, but the waits at Cafe 2 are more consistent', NULL, 'Both cafes have a mean wait of 6 minutes. The waits at Cafe 1 range from 2 to 10 (range 8), while the waits at Cafe 2 range from 5 to 7 (range 2). So the means are equal, and Cafe 2 is more consistent.', 'checked', '{"lint":[],"solve":{"answer":"The mean waits are equal, but the waits at Cafe 2 are more consistent","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cafe 1 mean 30/5 = 6, range 8. Cafe 2 mean 30/5 = 6, range 2. Equal means, Cafe 2 more consistent.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c94b512-130e-4986-b23e-b9349c65f5d1', 'NC26.8.RD.3', 1, 'choice', 'Describe and compare the shapes of distributions', 'Two sets are plotted on one number line. Set A: 5, 6, 6, 7, 7, 7, 8, 8, 9. Set B: 1, 1, 2, 2, 3, 4, 6, 9, 15. Which statement describes the shapes?', '["Set A is roughly symmetric, and Set B is skewed right","Set A is skewed right, and Set B is roughly symmetric","Set A is skewed left, and Set B is skewed right","Set A is roughly symmetric, and Set B is skewed left"]', 'Set A is roughly symmetric, and Set B is skewed right', NULL, 'Set A is balanced around its middle value 7: the values 5, 6, 6 on the left match 8, 8, 9 on the right, so it is roughly symmetric. Set B has most of its values near the small end and a long tail stretching toward the large values 9 and 15, so it is skewed right.', 'checked', '{"lint":[],"solve":{"answer":"Set A is roughly symmetric, and Set B is skewed right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A is centred at 7 with matching sides: symmetric. B bunches at 1-4 with a long tail to 15: skewed right.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
