INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('697543bd-89ae-431c-9bcf-84e97957a2f5', 'NC26.8.RD.3', 1, 'numeric', 'Effect of an outlier when comparing data sets', 'Two sets of ages are plotted on one number line. Set A: 11, 12, 12, 13. Set B: 11, 12, 12, 13, 40. How much greater is the range of Set B than the range of Set A?', '[]', '27', '(40-11)-(13-11)', 'The range of Set A is $13 - 11 = 2$. The range of Set B is $40 - 11 = 29$, because of the far-away value 40. The difference is $29 - 2 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A range 13-11=2; B range 40-11=29; 29-2=27.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64e7cbf1-46b1-4058-b6bd-f1e879f32733', 'NC26.8.RD.3', 1, 'choice', 'Effect of an outlier when comparing data sets', 'Set A is 8, 9, 10, 11, 12. Set B is the same except that 12 is replaced by 60. Which of these is the same for both sets?', '["The mean","The range","The greatest value","The median"]', 'The median', NULL, 'Both sets have 10 as the middle value, so the median stays 10. The mean changes (from 10 to 19.6), the range changes (from 4 to 52) and the greatest value changes (from 12 to 60).', 'checked', '{"lint":[],"solve":{"answer":"The median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: median 10, range 4, mean 10, max 12. B: 8,9,10,11,60 median 10, range 52, mean 19.6, max 60. Only median same.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('540edae3-03b1-46d0-8f28-e2653b19f902', 'NC26.8.RD.3', 1, 'numeric', 'Effect of an outlier when comparing data sets', 'Set A is 10, 10, 10, 10, and its mean is 10. Set B has those four values and one more value, 60. What is the mean of Set B?', '[]', '20', '(40+60)/5', 'The five values of Set B add up to $10 + 10 + 10 + 10 + 60 = 100$. The mean is $100 \div 5 = 20$. The one far-away value 60 doubles the mean.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum 40+60=100, 100/5=20.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('769e8690-0471-44eb-ab83-1c32fd052261', 'NC26.8.RD.3', 1, 'choice', 'Read and compare box plots from five-number summaries', 'Two box plots are given as minimum, Q1, median, Q3 and maximum. Plot A: 5, 15, 25, 35, 45. Plot B: 10, 20, 25, 30, 40. Which statement is true?', '["Plot A has the greater median","Plot B has the greater range","Plot B has the greater IQR","Plot A has the greater IQR"]', 'Plot A has the greater IQR', NULL, 'The medians are both 25. The ranges are $45 - 5 = 40$ for A and $40 - 10 = 30$ for B, so A has the greater range. The IQRs are $35 - 15 = 20$ for A and $30 - 20 = 10$ for B, so A has the greater IQR.', 'checked', '{"lint":[],"solve":{"answer":"Plot A has the greater IQR","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR A 35-15=20, B 30-20=10. Medians both 25. Range A 40, B 30. A has greater IQR.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5467ec17-7e1e-474b-97fc-5113e116ba43', 'NC26.8.RD.3', 1, 'numeric', 'Read and compare box plots from five-number summaries', 'Two box plots are drawn on one number line. Plot A has minimum 22 and maximum 71. Plot B has minimum 30 and maximum 65. How much greater is the range of Plot A than the range of Plot B?', '[]', '14', '(71-22)-(65-30)', 'The range of Plot A is $71 - 22 = 49$. The range of Plot B is $65 - 30 = 35$. The difference is $49 - 35 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A range 71-22=49; B range 65-30=35; 49-35=14.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e1dd366-d79a-4c2a-8562-a565e3c3f0d7', 'NC26.8.RD.3', 1, 'choice', 'Read a histogram or frequency table', 'Two histograms show the quiz scores of two classes. Class A: 60 to 69, 4 students; 70 to 79, 9 students; 80 to 89, 7 students; 90 to 99, 3 students. Class B: 60 to 69, 6 students; 70 to 79, 8 students; 80 to 89, 5 students; 90 to 99, 2 students. How many students in the two classes together scored 80 or above?', '["7","10","12","17"]', '17', '10+7', 'Class A has $7 + 3 = 10$ students at 80 or above. Class B has $5 + 2 = 7$. Together that is $10 + 7 = 17$ students.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 7+3=10; B: 5+2=7; total 17.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('047ff4be-eedc-4020-a50a-1b6b6753db10', 'NC26.8.RD.3', 1, 'choice', 'Read a histogram or frequency table', 'A histogram shows how many minutes 24 students spent on the bus. The bars show: 0 to 9 minutes, 3 students; 10 to 19 minutes, 9 students; 20 to 29 minutes, 6 students; 30 to 39 minutes, 4 students; 40 to 49 minutes, 2 students. Which best describes the shape of the data?', '["Skewed left, with a tail toward the shorter times","Skewed right, with a tail toward the longer times","Symmetric, with the bars balanced around the middle","Uniform, with all of the bars about the same height"]', 'Skewed right, with a tail toward the longer times', NULL, 'The tallest bar (9 students) is near the short-time end, and the bars then get shorter and shorter toward the long times (6, 4, 2). A tail stretching toward the larger values means the data are skewed right.', 'checked', '{"lint":[],"solve":{"answer":"Skewed right, with a tail toward the longer times","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 3,9,6,4,2 (sum 24): peak at 10-19, tapering toward longer times: skewed right.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3287a481-7213-4fd4-801c-74da93128ecb', 'NC26.8.RD.3', 1, 'choice', 'Draw a conclusion by comparing groups in context', 'Bakery A sold 12, 14, 15, 16 and 18 cakes on five days. Bakery B sold 20, 22, 23, 24 and 26 cakes on five other days. Which statement is supported by these data?', '["Bakery A has the greater median number of cakes sold","Bakery A has the greater range of cakes sold","Every value for Bakery B is greater than every value for Bakery A","The values for the two bakeries overlap"]', 'Every value for Bakery B is greater than every value for Bakery A', NULL, 'The least value for Bakery B (20) is greater than the greatest value for Bakery A (18), so every B value is greater than every A value and the two sets do not overlap. Bakery B also has the greater median (23 against 15), and the two ranges are equal (6 and 6).', 'checked', '{"lint":[],"solve":{"answer":"Every value for Bakery B is greater than every value for Bakery A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A max 18 < B min 20, so every B value exceeds every A value. Medians 15 vs 23; ranges both 6; no overlap.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('014759da-0a02-4600-8168-ec102660b2a9', 'NC26.8.RD.3', 2, 'choice', 'Compare distributions: outliers and medians', 'Test scores are listed for two groups. Group 1: 45, 82, 84, 85, 85, 86, 88. Group 2: 70, 75, 78, 80, 82, 85, 88. Which statement is true?', '["Group 2 has an outlier, and its median is higher than Group 1''s median","Neither group has an outlier, and the medians are equal","Group 1 has an outlier, and its median is lower than Group 2''s median","Group 1 has an outlier, and its median is higher than Group 2''s median"]', 'Group 1 has an outlier, and its median is higher than Group 2''s median', NULL, 'Group 1 has one score, 45, far below all of the others, so it is an outlier. Group 2''s scores are spread fairly evenly with no outlier. The median of Group 1 is the 4th of 7 values, 85. The median of Group 2 is 80. So Group 1 has an outlier and the higher median.', 'checked', '{"lint":[],"solve":{"answer":"Group 1 has an outlier, and its median is higher than Group 2''s median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group 1 median = 85; Q1 = 82, Q3 = 86, IQR 4, lower fence 76, so 45 is an outlier. Group 2 median = 80; Q1 = 75, Q3 = 85, IQR 10, fences 60 and 100, no outlier. Group 1 has an outlier and higher median.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84257947-9259-47ab-8b69-6381109471b8', 'NC26.8.RD.3', 2, 'numeric', 'Compare the means of two data sets', 'Data set A is 10, 12, 14, 16. Data set B is 9, 13, 19, 23. How much greater is the mean of B than the mean of A?', '[]', '3', '(9+13+19+23)/4-(10+12+14+16)/4', 'Mean of A: $\frac{10+12+14+16}{4} = \frac{52}{4} = 13$. Mean of B: $\frac{9+13+19+23}{4} = \frac{64}{4} = 16$. The difference is $16 - 13 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean A = 52/4 = 13. Mean B = 64/4 = 16. Difference = 3.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc6011ff-19cc-478e-a39f-a6d048513158', 'NC26.8.RD.3', 2, 'choice', 'Compare the spread of three data sets with equal means', 'Three data sets each have six values and a mean of 10. Set A: 9, 9, 10, 10, 11, 11. Set B: 5, 8, 10, 10, 12, 15. Set C: 10, 10, 10, 10, 10, 10. Which set''s values are the most spread out?', '["Set A","Set B","Set C","They are equally spread out because their means are equal"]', 'Set B', NULL, 'Set A ranges from 9 to 11 (range 2). Set B ranges from 5 to 15 (range 10). Set C has no spread at all (range 0). Set B is the most spread out. Equal means do not mean equal spread.', 'checked', '{"lint":[],"solve":{"answer":"Set B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range A = 2, B = 10, C = 0; B''s values are farthest from 10.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32863246-5be4-4ef7-b694-db8360746623', 'NC26.8.RD.3', 2, 'numeric', 'Compare the centers (mean or median) of several data sets', 'Three sets of numbers are listed in the order they were collected. Set A: 14, 9, 16, 12, 19. Set B: 11, 20, 8, 13, 23. Set C: 10, 18, 15, 17, 5. What is the mean of the set that has the greatest median?', '[]', '13', '(10+18+15+17+5)/5', 'In order, Set A is 9, 12, 14, 16, 19 (median 14), Set B is 8, 11, 13, 20, 23 (median 13) and Set C is 5, 10, 15, 17, 18 (median 15). Set C has the greatest median. Its mean is $(10+18+15+17+5) \div 5 = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians: A sorted 9,12,14,16,19 -> 14; B 8,11,13,20,23 -> 13; C 5,10,15,17,18 -> 15. C greatest. Mean of C = 65/5 = 13.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c85340a-3f5e-48ec-b96a-8b5cc942026d', 'NC26.8.RD.3', 2, 'choice', 'Compare the centers (mean or median) of several data sets', 'Set M is 3, 4, 4, 5, 24. Set N is 8, 9, 10, 11, 12. Which statement is true?', '["Set M has the greater mean","Set N has the greater median","Both sets have the same median","Set N has a mean that is different from its median"]', 'Set N has the greater median', NULL, 'Set M has a mean of 8 and a median of 4. Set N has a mean of 10 and a median of 10. So Set N has the greater median, and also the greater mean. The one very large value, 24, pulls the mean of Set M far above its median, but not past Set N''s mean.', 'checked', '{"lint":[],"solve":{"answer":"Set N has the greater median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"M: median 4, mean 40/5 = 8. N: median 10, mean 50/5 = 10. N has the greater median (true); N mean = median; medians differ; M mean 8 < 10.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0148c789-f3b3-49c7-9f28-df055ce97081', 'NC26.8.RD.3', 2, 'choice', 'Compare the centers (mean or median) of several data sets', 'Four students each took four turns at a ring-toss game, and the points from each turn are listed. Mia: 12, 15, 9, 14. Noah: 13, 13, 12, 13. Owen: 7, 20, 10, 11. Pia: 16, 8, 14, 11. Which student has the greatest mean score?', '["Mia","Noah","Owen","Pia"]', 'Noah', NULL, 'The sums are Mia 50, Noah 51, Owen 48 and Pia 49. All four students took 4 turns, so the greatest sum gives the greatest mean. Noah''s mean is 12.75. (Owen has the single highest score, 20, but not the highest mean.)', 'checked', '{"lint":[],"solve":{"answer":"Noah","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Means: Mia 50/4 = 12.5, Noah 51/4 = 12.75, Owen 48/4 = 12, Pia 49/4 = 12.25. Noah greatest.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('479faaf7-b4e3-4649-8bdc-1e627afee300', 'NC26.8.RD.3', 2, 'numeric', 'Compare the centers (mean or median) of several data sets', 'Four data sets each have six values. Set 1: 3, 5, 8, 9, 12, 15. Set 2: 1, 4, 9, 12, 13, 20. Set 3: 6, 6, 7, 9, 9, 9. Set 4: 2, 3, 9, 10, 12, 12. What is the greatest of the four medians?', '[]', '10.5', '(9+12)/2', 'With six values, the median is the mean of the 3rd and 4th values. Set 1: 8.5. Set 2: $(9 + 12) \div 2 = 10.5$. Set 3: 8. Set 4: 9.5. The greatest median is 10.5.', 'checked', '{"lint":[],"solve":{"answer":"10.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians (avg of 3rd and 4th): Set 1 (8+9)/2 = 8.5; Set 2 (9+12)/2 = 10.5; Set 3 (7+9)/2 = 8; Set 4 (9+10)/2 = 9.5. Greatest 10.5.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02c89337-ff9f-4fc4-9ea9-b86bb66abdf3', 'NC26.8.RD.3', 2, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'Sets A, B and C each have 8 values and the same range. Set A: 4, 9, 10, 11, 12, 13, 14, 20. Set B: 4, 5, 6, 8, 12, 15, 18, 20. Set C: 4, 6, 8, 10, 14, 16, 18, 20. The IQR is Q3 minus Q1, using the medians of the lower four and upper four values. Which statement is true?', '["Set B has the smallest IQR","Set C has the greatest IQR","The three sets have the same IQR because their ranges are equal","Set A has the smallest IQR"]', 'Set A has the smallest IQR', NULL, 'All three ranges are $20 - 4 = 16$. Set A: $Q_1 = 9.5$ and $Q_3 = 13.5$, so IQR $= 4$. Set B: $Q_1 = 5.5$ and $Q_3 = 16.5$, so IQR $= 11$. Set C: $Q_1 = 7$ and $Q_3 = 17$, so IQR $= 10$. Set A has the smallest IQR. Equal ranges do not mean equal IQRs.', 'checked', '{"lint":[],"solve":{"answer":"Set A has the smallest IQR","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: Q1 (9+10)/2 = 9.5, Q3 (13+14)/2 = 13.5, IQR 4. B: Q1 (5+6)/2 = 5.5, Q3 (15+18)/2 = 16.5, IQR 11. C: Q1 (6+8)/2 = 7, Q3 (16+18)/2 = 17, IQR 10. Ranges all 16. A smallest IQR; B (not C) greatest.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f119ed6b-55e7-4169-8e6b-e7fac78e9c25', 'NC26.8.RD.3', 2, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'The daily high temperatures, in degrees Fahrenheit, were recorded for five days in four towns. Town A: 61, 68, 70, 73, 65. Town B: 55, 57, 59, 56, 58. Town C: 48, 66, 52, 71, 60. Town D: 63, 64, 70, 66, 62. How much greater is the greatest range of the four towns than the smallest range?', '["27","23","19","15"]', '19', '23-4', 'The ranges are Town A $73 - 61 = 12$, Town B $59 - 55 = 4$, Town C $71 - 48 = 23$ and Town D $70 - 62 = 8$. The greatest is 23 and the smallest is 4, so the difference is $23 - 4 = 19$.', 'checked', '{"lint":[],"solve":{"answer":"19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ranges: A 73 - 61 = 12, B 59 - 55 = 4, C 71 - 48 = 23, D 70 - 62 = 8. 23 - 4 = 19.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31250b1c-26c3-44ea-9c13-a6d492feb97c', 'NC26.8.RD.3', 2, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'Two data sets are described by five numbers each: the minimum, Q1, median, Q3 and maximum, in that order. Set A: 10, 20, 25, 30, 60. Set B: 5, 15, 25, 35, 45. Which statement is true?', '["Set A has the greater range, and Set B has the greater IQR","Set A has the greater range and the greater IQR","Set B has the greater range and the greater IQR","Set B has the greater range, and Set A has the greater IQR"]', 'Set A has the greater range, and Set B has the greater IQR', NULL, 'Set A has a range of $60 - 10 = 50$ and an IQR of $30 - 20 = 10$. Set B has a range of $45 - 5 = 40$ and an IQR of $35 - 15 = 20$. Set A has the greater range, but Set B has the greater IQR.', 'checked', '{"lint":[],"solve":{"answer":"Set A has the greater range, and Set B has the greater IQR","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: range 60 - 10 = 50, IQR 30 - 20 = 10. B: range 45 - 5 = 40, IQR 35 - 15 = 20. A greater range, B greater IQR.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e69289ac-8d75-4508-b8b5-a10828838656', 'NC26.8.RD.3', 2, 'choice', 'Describe and compare the shapes of distributions', 'Eleven students counted the text messages they sent yesterday. The number of students in each group was: 0 to 10 messages, six students; 11 to 20 messages, three students; 21 to 30 messages, one student; 31 to 40 messages, one student. Which best describes the shape of the data?', '["Symmetric, with one peak in the middle","Skewed left, with a long tail toward small numbers","Skewed right, with a long tail toward large numbers","Two separate peaks with a gap between them"]', 'Skewed right, with a long tail toward large numbers', NULL, 'Most of the students are in the lowest group, and the counts shrink steadily as the number of messages grows (6, 3, 1, 1). The tail stretches toward the large numbers, so the data are skewed right.', 'checked', '{"lint":[],"solve":{"answer":"Skewed right, with a long tail toward large numbers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Counts 6, 3, 1, 1 from low to high: peak at the low end, tail toward large numbers: skewed right.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7a8679b-5531-4994-9cae-ff2c82949c41', 'NC26.8.RD.3', 2, 'choice', 'Describe and compare the shapes of distributions', 'Four data sets each have seven values. Which set is symmetric, with the values balanced evenly on both sides of the middle value?', '["3, 5, 6, 7, 8, 9, 11","2, 2, 3, 3, 4, 9, 14","1, 8, 9, 9, 10, 10, 10","1, 1, 1, 1, 5, 9, 20"]', '3, 5, 6, 7, 8, 9, 11', NULL, 'In a symmetric set, the lowest and highest values are the same distance from the middle, and so are the next pair, and so on. For 3, 5, 6, 7, 8, 9, 11 the middle value is 7 and the pairs 3 and 11, 5 and 9, 6 and 8 each add to 14. The other sets have a tail on one side, so they are not balanced.', 'checked', '{"lint":[],"solve":{"answer":"3, 5, 6, 7, 8, 9, 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3, 5, 6, 7, 8, 9, 11: around 7 the distances are 4, 2, 1 below and 1, 2, 4 above: symmetric. Others have long tails one way.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd8f3423-c8ea-4d26-8849-bf8b53313c8a', 'NC26.8.RD.3', 2, 'choice', 'Effect of an outlier when comparing data sets', 'Set A is 6, 7, 7, 8, 9. Set B is the same except that 9 is replaced by 40. By how much does the mean increase from Set A to Set B?', '["0","6.2","13.6","31"]', '6.2', '(6+7+7+8+40)/5-(6+7+7+8+9)/5', 'Set A has a mean of $6+7+7+8+9 = 37$ divided by 5, which is 7.4. Set B has a mean of 68 divided by 5, which is 13.6. The mean increases by $13.6 - 7.4 = 6.2$. (The median stays 7, but the mean changes.)', 'checked', '{"lint":[],"solve":{"answer":"6.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: sum 37, mean 7.4. B: sum 68, mean 13.6. Increase 6.2 (equivalently 31/5).","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d680166-7e44-477f-a83e-a4613535d9ea', 'NC26.8.RD.3', 2, 'choice', 'Effect of an outlier when comparing data sets', 'Class P scores: 74, 76, 77, 78, 80. Class Q scores: 75, 77, 78, 79, 21. Which statement is true?', '["The classes have the same median, but Class Q has the lower mean","Class Q has the lower median","Class P has the greater range","The classes have the same mean"]', 'The classes have the same median, but Class Q has the lower mean', NULL, 'Class P: median 77, mean 77, range 6. Class Q: median 77, mean 66, range 58. The medians match, but the one very low score, 21, pulls the mean of Class Q down.', 'checked', '{"lint":[],"solve":{"answer":"The classes have the same median, but Class Q has the lower mean","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: median 77, mean 385/5 = 77, range 6. Q sorted 21, 75, 77, 78, 79: median 77, mean 330/5 = 66, range 58. Same median, Q lower mean.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cb1f026b-a153-471c-95c8-f636ce6ef0d7', 'NC26.8.RD.3', 2, 'choice', 'Effect of an outlier when comparing data sets', 'Set A is 40, 42, 43, 45, 46, 48. Set B is the same except that 48 is replaced by 120. Which statement is true?', '["The means are the same","The median of Set B is much greater than the median of Set A","The medians are the same, but the range of Set B is much greater","The ranges are the same"]', 'The medians are the same, but the range of Set B is much greater', NULL, 'Both sets have a median of $(43 + 45) \div 2 = 44$, because the changed value is above the middle. The range jumps from $48 - 40 = 8$ to $120 - 40 = 80$, and the mean also rises (from 44 to 56).', 'checked', '{"lint":[],"solve":{"answer":"The medians are the same, but the range of Set B is much greater","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians both (43+45)/2 = 44. Means 44 vs 56. Ranges 8 vs 80. Same medians, B''s range much greater.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e657c6ef-3462-4c2d-ac71-b9408b99adf4', 'NC26.8.RD.3', 2, 'numeric', 'Plot several data sets on one number line', 'Three sets are shown on one number line, with one dot for each value. Set A: 1, 2, 2, 3, 3, 3, 4, 4, 5. Set B: 2, 3, 3, 3, 3, 4, 4, 5, 5, 6. Set C: 0, 0, 1, 1, 1, 2, 2, 3. In all, how many dots are above numbers that are 3 or greater?', '[]', '16', '6+9+1', 'Count the values that are 3 or greater in each set: Set A has 6 (3, 3, 3, 4, 4, 5), Set B has 9 (3, 3, 3, 3, 4, 4, 5, 5, 6) and Set C has 1 (3). The total is 16 dots.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values >= 3: A: 3,3,3,4,4,5 = 6; B: 3,3,3,3,4,4,5,5,6 = 9; C: 3 = 1. Total 16.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f14e6ae7-223e-4849-ad08-8f0f4e092aa7', 'NC26.8.RD.3', 2, 'choice', 'Plot several data sets on one number line', 'Three sets of lengths, in centimeters, will be plotted on one number line. Set A: 2.4, 3.1, 4.8. Set B: 1.9, 3.5, 5.2. Set C: 2.7, 4.0, 6.3. Which number line can show every value?', '["A line from 2 to 6","A line from 1 to 7","A line from 0 to 5","A line from 2 to 7"]', 'A line from 1 to 7', NULL, 'The lowest value is 1.9 and the highest is 6.3, so the line must start at 1.9 or lower and end at 6.3 or higher. Only the line from 1 to 7 works. The line from 2 to 6 misses 1.9 and 6.3, the line from 0 to 5 misses 5.2 and 6.3, and the line from 2 to 7 misses 1.9.', 'checked', '{"lint":[],"solve":{"answer":"A line from 1 to 7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values run from 1.9 to 6.3. Only 1 to 7 contains both.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a4e4be05-e287-422a-a4f1-5ed9ccae75c6', 'NC26.8.RD.3', 2, 'numeric', 'Plot several data sets on one number line', 'Set A and Set B are plotted on one number line. Set A: 2, 4, 6. Set B: 3, 5, 9, 11. What is the median of all the values shown on the line?', '[]', '5', '5', 'Put all seven values in order: 2, 3, 4, 5, 6, 9, 11. The middle (4th) value is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All values sorted 2, 3, 4, 5, 6, 9, 11: middle (4th) is 5.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9ffa874-05b0-413a-ad81-7c8b829cbead', 'NC26.8.RD.3', 2, 'choice', 'Plot several data sets on one number line', 'The heights, in centimeters, of seedlings in three trays are plotted on one number line. Tray A: 40, 44, 45, 47, 52. Tray B: 42, 46, 50, 53, 60. Tray C: 38, 41, 43, 49, 55. Which statement is true?', '["Tray C has the greatest range","Tray A has the greatest minimum","Tray B has the greatest median and the greatest maximum","Tray C has the greatest median"]', 'Tray B has the greatest median and the greatest maximum', NULL, 'Medians: Tray A 45, Tray B 50, Tray C 43. Maximums: 52, 60 and 55. Ranges: 12, 18 and 17. Minimums: 40, 42 and 38. Tray B has the greatest median and the greatest maximum; it also has the greatest range and minimum, so the other statements are false.', 'checked', '{"lint":[],"solve":{"answer":"Tray B has the greatest median and the greatest maximum","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: med 45, min 40, max 52, range 12. B: med 50, min 42, max 60, range 18. C: med 43, min 38, max 55, range 17. B has greatest median and max (true); C''s range 17 < 18; B has greatest minimum.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a357f121-ae07-456c-8290-2d3a6fb06190', 'NC26.8.RD.3', 2, 'numeric', 'Read a stem-and-leaf display', 'A back-to-back stem-and-leaf display compares two sets of times, in seconds, using the same stems. A stem of 4 with a leaf of 1 means 41. Stem 4: Set A has the leaves 1, 3, 5 and Set B has 6, 8. Stem 5: Set A has 0, 2, 2, 6 and Set B has 1, 5, 7, 9. Stem 6: Set A has 1, 4 and Set B has 0, 2, 3, 3. How much greater is the median of Set B than the median of Set A?', '[]', '6', '(57+59)/2-52', 'Set A has 9 values: 41, 43, 45, 50, 52, 52, 56, 61, 64. Its median is the 5th value, 52. Set B has 10 values: 46, 48, 51, 55, 57, 59, 60, 62, 63, 63. Its median is the mean of the 5th and 6th values: $(57 + 59) \div 2 = 58$. The difference is $58 - 52 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 41, 43, 45, 50, 52, 52, 56, 61, 64 (9 values), median 52. B: 46, 48, 51, 55, 57, 59, 60, 62, 63, 63 (10 values), median (57+59)/2 = 58. 58 - 52 = 6.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01e40fb4-2cf7-4367-a0ac-dee2fa2a2094', 'NC26.8.RD.3', 2, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display shows the lengths of some fish, in inches. A stem of 2 with a leaf of 3 means 2.3 inches. Stem 2 has the leaves 3, 5, 7. Stem 3 has the leaves 0, 2, 2, 8. Stem 4 has the leaves 1, 6. What is the median length, in inches?', '[]', '3.2', NULL, 'The lengths in order are 2.3, 2.5, 2.7, 3.0, 3.2, 3.2, 3.8, 4.1, 4.6. There are 9 values, so the median is the 5th one: 3.2 inches.', 'checked', '{"lint":[],"solve":{"answer":"3.2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lengths 2.3, 2.5, 2.7, 3.0, 3.2, 3.2, 3.8, 4.1, 4.6 (9 values). Median (5th) 3.2.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0de363f-6ac9-4d1a-bdc9-48625d2412e9', 'NC26.8.RD.3', 2, 'choice', 'Read a stem-and-leaf display', 'Two sets are shown on a back-to-back stem-and-leaf display (a stem of 2 with a leaf of 1 means 21). Stem 2: Set P has the leaves 1, 5, 8 and Set R has 6, 9. Stem 3: P has 0, 2, 4, 4 and R has 5, 7, 8. Stem 4: P has 1, 3 and R has 0, 2, 2, 6, 9. Stem 5: P has none and R has 1, 5. Which statement is true?', '["Set P has the greater median","Set P has the greater range","The two sets have the same number of values","Set R has the greater median, and Set P has the smaller range"]', 'Set R has the greater median, and Set P has the smaller range', NULL, 'Set P has 9 values: 21, 25, 28, 30, 32, 34, 34, 41, 43, with median 32 and range 22. Set R has 12 values: 26, 29, 35, 37, 38, 40, 42, 42, 46, 49, 51, 55, with median 41 and range 29. So Set R has the greater median, and Set P has the smaller range.', 'checked', '{"lint":[],"solve":{"answer":"Set R has the greater median, and Set P has the smaller range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: 21, 25, 28, 30, 32, 34, 34, 41, 43 (9), median 32, range 22. R: 26, 29, 35, 37, 38, 40, 42, 42, 46, 49, 51, 55 (12), median (40+42)/2 = 41, range 29. R greater median, P smaller range.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1eab61d9-4567-4955-b362-0a4d99b9b0ae', 'NC26.8.RD.3', 2, 'numeric', 'Read and compare box plots from five-number summaries', 'Three box plots are described by their minimum, Q1, median, Q3 and maximum. Plot X: 20, 35, 45, 60, 80. Plot Y: 30, 40, 50, 55, 70. Plot Z: 10, 30, 52, 65, 90. How much greater is the greatest IQR of the three plots than the least IQR?', '[]', '20', '(65-30)-(55-40)', 'The IQR is Q3 minus Q1. Plot X: $60 - 35 = 25$. Plot Y: $55 - 40 = 15$. Plot Z: $65 - 30 = 35$. The greatest is 35 and the least is 15, so the difference is 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQRs: X 60 - 35 = 25, Y 55 - 40 = 15, Z 65 - 30 = 35. 35 - 15 = 20.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93f9bbfa-1f48-421e-b1f2-57b046f775b9', 'NC26.8.RD.3', 2, 'choice', 'Read and compare box plots from five-number summaries', 'A box plot is drawn from these five numbers: minimum 10, Q1 28, median 30, Q3 36 and maximum 70. The whiskers run from the box to the minimum and to the maximum. Which statement is true?', '["The median is exactly halfway between Q1 and Q3","Half of the values are greater than 36","The IQR is 26","The upper whisker is longer than the lower whisker"]', 'The upper whisker is longer than the lower whisker', NULL, 'The lower whisker is $28 - 10 = 18$ long and the upper whisker is $70 - 36 = 34$ long, so the upper whisker is longer. The halfway point between Q1 and Q3 is 32, not 30. Only a quarter of the values are above Q3 = 36. The IQR is $36 - 28 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"The upper whisker is longer than the lower whisker","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Lower whisker 28 - 10 = 18, upper 70 - 36 = 34: upper longer (true). IQR is 8, not 26. A quarter (not half) exceed 36. Halfway between 28 and 36 is 32, not 30.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b1a920a-36ff-442e-9ec3-5b94ce4b2a2b', 'NC26.8.RD.3', 2, 'numeric', 'Read a histogram or frequency table', 'Two histograms show the scores of two classes. Class A: 90 to 100, five students; 80 to 89, nine students; 70 to 79, seven students; 60 to 69, four students. Class B: 90 to 100, three students; 80 to 89, six students; 70 to 79, eleven students; 60 to 69, five students. How many more students in Class A than in Class B scored 80 or above?', '[]', '5', '(5+9)-(3+6)', 'Class A: $5 + 9 = 14$ students scored 80 or above. Class B: $3 + 6 = 9$ students. The difference is $14 - 9 = 5$ students.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 80+: 5 + 9 = 14. B 80+: 3 + 6 = 9. 14 - 9 = 5.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c10c38fa-d3e6-40d8-a0e4-c28f60436f38', 'NC26.8.RD.3', 2, 'choice', 'Read a histogram or frequency table', 'Class A has 20 students, and 5 of them scored 90 or above. Class B has 40 students, and 8 of them scored 90 or above. Which statement is true?', '["A greater percent of Class A than of Class B scored 90 or above","A greater percent of Class B than of Class A scored 90 or above, because more students in Class B did","The same percent of both classes scored 90 or above","Fewer students in Class B than in Class A scored 90 or above"]', 'A greater percent of Class A than of Class B scored 90 or above', NULL, 'Compare percents, not counts. Class A: $5 \div 20 = 25\%$. Class B: $8 \div 40 = 20\%$. A greater percent of Class A scored 90 or above, even though Class B has more such students (8 compared with 5).', 'checked', '{"lint":[],"solve":{"answer":"A greater percent of Class A than of Class B scored 90 or above","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 5/20 = 25%. B: 8/40 = 20%. A greater percent. B has more students (8 > 5), so the last option is false.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6fa3d14-eada-4ace-8f91-f6cd8dd820fb', 'NC26.8.RD.3', 2, 'numeric', 'Draw a conclusion by comparing groups in context', 'A coach timed three runners in five races. The times, in seconds, are listed. Runner A: 13, 11, 12, 14, 12. Runner B: 12, 10, 13, 11, 15. Runner C: 14, 13, 12, 12, 16. Of all 15 times, how many are faster (less) than the median time of Runner A?', '[]', '3', NULL, 'Runner A''s times in order are 11, 12, 12, 13, 14, so the median is 12. The times less than 12 are 11 (Runner A), 10 and 11 (Runner B), and none for Runner C. That is 3 times.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted 11, 12, 12, 13, 14: median 12. Times < 12: A: 11; B: 10, 11; C: none. Total 3.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bfe932e-eb47-4d4c-8d02-43a9ed755978', 'NC26.8.RD.3', 2, 'choice', 'Draw a conclusion by comparing groups in context', 'The prices of five homes in each of two neighborhoods are listed, in thousands of dollars. Neighborhood X: 220, 240, 250, 260, 900. Neighborhood Y: 280, 290, 300, 310, 320. Which statement is true?', '["The median price is greater in Y, but the mean price is greater in X","Every home in X costs more than every home in Y","The mean price and the median price of X are equal","The prices in Y have the greater range"]', 'The median price is greater in Y, but the mean price is greater in X', NULL, 'Neighborhood X: median 250, mean 374, range 680. Neighborhood Y: median 300, mean 300, range 40. The one very expensive home (900) lifts the mean of X above that of Y, while the median shows that a typical home in Y costs more.', 'checked', '{"lint":[],"solve":{"answer":"The median price is greater in Y, but the mean price is greater in X","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: median 250, mean 1870/5 = 374, range 680. Y: median 300, mean 300, range 40. Median greater in Y, mean greater in X.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('040a7eae-eb93-48d2-ad9d-60e2a653ee47', 'NC26.8.RD.3', 2, 'choice', 'Draw a conclusion by comparing groups in context', 'Class P scores: 68, 72, 76, 78, 85. Class Q scores: 70, 79, 84, 88, 92. A score of 80 is compared with the median of each class. Which statement is true?', '["The score of 80 is above both medians","The score of 80 is above the median of Class P and below the median of Class Q","The score of 80 is below both medians","The score of 80 is below the median of Class P and above the median of Class Q"]', 'The score of 80 is above the median of Class P and below the median of Class Q', NULL, 'The median of Class P is 76 and the median of Class Q is 84. A score of 80 is greater than 76 and less than 84, so it is above the median of Class P and below the median of Class Q.', 'checked', '{"lint":[],"solve":{"answer":"The score of 80 is above the median of Class P and below the median of Class Q","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P median 76, Q median 84. 80 > 76 and 80 < 84.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('461fae2c-e18f-440e-82a2-8354ab3ba7de', 'NC26.8.RD.3', 2, 'numeric', 'Compare the spread (range or interquartile range) of several data sets', 'Sets A and B are plotted on one number line, and each has seven values. With seven values, Q1 is the median of the lowest three and Q3 is the median of the highest three (the middle value is left out). Set A: 12, 4, 9, 7, 15, 6, 10. Set B: 20, 8, 14, 3, 11, 17, 5. How much greater is the IQR of Set B than the IQR of Set A?', '[]', '6', '(17-5)-(12-6)', 'In order, Set A is 4, 6, 7, 9, 10, 12, 15. Q1 is the median of 4, 6, 7, which is 6, and Q3 is the median of 10, 12, 15, which is 12. So its IQR is $12 - 6 = 6$. In order, Set B is 3, 5, 8, 11, 14, 17, 20. Q1 is 5 and Q3 is 17, so its IQR is $17 - 5 = 12$. The difference is $12 - 6 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted 4,6,7,9,10,12,15: Q1=6, Q3=12, IQR 6. B sorted 3,5,8,11,14,17,20: Q1=5, Q3=17, IQR 12. 12-6=6.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e71619a8-f951-46fc-aa15-6e18209a6de8', 'NC26.8.RD.3', 2, 'choice', 'Describe and compare the shapes of distributions', 'Two sets are plotted on one number line. Set X: 3, 4, 4, 5, 6, 7, 25. Set Y: 1, 20, 21, 21, 22, 23, 24. Which statement is true?', '["For both sets the mean is greater than the median","For Set X the mean is less than the median, and for Set Y the mean is greater than the median","For both sets the mean is less than the median","For Set X the mean is greater than the median, and for Set Y the mean is less than the median"]', 'For Set X the mean is greater than the median, and for Set Y the mean is less than the median', NULL, 'Set X has a median of 5. Its sum is 54, so its mean is about 7.7, pulled up by the large value 25. Set Y has a median of 21. Its sum is 132, so its mean is about 18.9, pulled down by the small value 1. So the mean of X is greater than its median and the mean of Y is less than its median.', 'checked', '{"lint":[],"solve":{"answer":"For Set X the mean is greater than the median, and for Set Y the mean is less than the median","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: median 5, mean 54/7=7.71 > median. Y: median 21, mean 132/7=18.86 < median.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('10a33967-937f-4fc7-ada5-105e5813a215', 'NC26.8.RD.3', 2, 'numeric', 'Describe clusters and gaps in a distribution', 'Two sets are plotted on one number line. In each, the dots form two clusters. The gap is the empty stretch from the greatest value of the lower cluster to the least value of the upper cluster. Set A: 5, 6, 7, 8, 30, 31, 32. Set B: 5, 6, 7, 20, 21, 22. How much wider is the gap in Set A than the gap in Set B?', '[]', '9', '(30-8)-(20-7)', 'In Set A the lower cluster ends at 8 and the upper cluster starts at 30, so the gap is $30 - 8 = 22$. In Set B the lower cluster ends at 7 and the upper cluster starts at 20, so the gap is $20 - 7 = 13$. The gap in A is $22 - 13 = 9$ wider.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A gap 30-8=22; B gap 20-7=13; 22-13=9.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f406589-abe0-4eb5-a452-a3c9d4a0ae79', 'NC26.8.RD.3', 2, 'numeric', 'Read and compare box plots from five-number summaries', 'Two box plots are drawn on one number line. Plot A has minimum 12, Q1 30, median 40, Q3 52 and maximum 80. The box of Plot B is exactly as long as the box of Plot A, and the Q1 of Plot B is 41. What is Q3 for Plot B?', '[]', '63', '41+(52-30)', 'The box of Plot A runs from 30 to 52, so it is $52 - 30 = 22$ long. The box of Plot B is also 22 long and starts at 41, so it ends at $41 + 22 = 63$.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Box A length 52-30=22; Q3 of B = 41+22=63.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('376052da-2055-4797-aafd-34784da72eec', 'NC26.8.RD.3', 3, 'numeric', 'Mean of two data sets combined', 'Group 1 has the values 3, 7 and 8. Group 2 has the values 5, 9, 11 and 13. What is the mean of all seven values together?', '[]', '8', '(3+7+8+5+9+11+13)/7', 'Add all seven values: $3 + 7 + 8 + 5 + 9 + 11 + 13 = 56$. Divide by 7: $56 \div 7 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum = 3+7+8 + 5+9+11+13 = 18 + 38 = 56. Mean = 56/7 = 8.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('489208b7-dcfa-4dbc-9bc1-9da34b0a2a01', 'NC26.8.RD.3', 3, 'choice', 'Compare interquartile ranges of four data sets', 'Four data sets are summarized by their minimum, first quartile, median, third quartile and maximum, in that order. Set A: 5, 12, 15, 20, 30. Set B: 3, 15, 18, 21, 45. Set C: 8, 10, 16, 22, 28. Set D: 14, 18, 21, 24, 26. Which set has the greatest interquartile range?', '["Set A","Set B","Set C","Set D"]', 'Set C', NULL, 'The interquartile range is the third quartile minus the first quartile. Set A: $20 - 12 = 8$. Set B: $21 - 15 = 6$. Set C: $22 - 10 = 12$. Set D: $24 - 18 = 6$. Set C has the greatest. (Set B has the greatest range, but that is a different measure.)', 'checked', '{"lint":[],"solve":{"answer":"Set C","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR = Q3 - Q1: A 20 - 12 = 8; B 21 - 15 = 6; C 22 - 10 = 12; D 24 - 18 = 6. Greatest: C.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1d7fefb-cf8d-437c-9679-2f905ecdde64', 'NC26.8.RD.3', 3, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display for 9 test scores is described here. Stem 6 has leaves 2 and 5. Stem 7 has leaves 0, 4, 4 and 8. Stem 8 has leaves 1, 3 and 9. (Stem 6 with leaf 2 means a score of 62.) What is the median score?', '[]', '74', NULL, 'The scores in order are 62, 65, 70, 74, 74, 78, 81, 83, 89. There are 9 scores, so the median is the 5th one, which is 74.', 'checked', '{"lint":[],"solve":{"answer":"74","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scores in order: 62, 65, 70, 74, 74, 78, 81, 83, 89. Median (5th of 9) = 74.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cda071e6-7ca6-4707-8c38-bf9771b7eb1e', 'NC26.8.RD.3', 3, 'numeric', 'Compare the centers (mean or median) of several data sets', 'A quiz was given to three groups. Group P has 4 students with a mean score of 10. Group Q has 6 students with a mean score of 15. Group R has 10 students with a mean score of 12. What is the mean score of all 20 students together?', '[]', '12.5', '(4*10+6*15+10*12)/20', 'Each group''s total is its size times its mean: $4 \times 10 = 40$, $6 \times 15 = 90$ and $10 \times 12 = 120$. The grand total is $40 + 90 + 120 = 250$. Divide by 20 students: $250 \div 20 = 12.5$.', 'checked', '{"lint":[],"solve":{"answer":"12.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Totals: 4 x 10 = 40, 6 x 15 = 90, 10 x 12 = 120. Sum 250 / 20 = 12.5.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8557d759-4e78-427d-8285-ad0ebd23e523', 'NC26.8.RD.3', 3, 'numeric', 'Compare the centers (mean or median) of several data sets', 'Set H is 20, 22, 24, 26, 28. Set J starts as 17, 21, 25, 29, and a fifth value will be added so that Set J has the same mean as Set H. What must the fifth value be?', '[]', '28', '5*24-(17+21+25+29)', 'Set H has a mean of 24, so Set J needs a total of $5 \times 24 = 120$. The four values already there add to 92. The fifth value is $120 - 92 = 28$.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"H mean = 120/5 = 24. J needs total 5 x 24 = 120. 17+21+25+29 = 92, so fifth = 28.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d7dd4be-4b7b-47b4-9083-1b02175077d7', 'NC26.8.RD.3', 3, 'choice', 'Compare the centers (mean or median) of several data sets', 'Four data sets each have five values. Set P: 4, 5, 6, 7, 8. Set Q: 2, 3, 6, 10, 14. Set R: 1, 8, 9, 9, 10. Set S: 1, 2, 3, 4, 25. Which set has the greatest difference between its mean and its median?', '["Set P","Set Q","Set R","Set S"]', 'Set S', NULL, 'Mean and median for each set: P is 6 and 6 (difference 0). Q is 7 and 6 (difference 1). R is 7.4 and 9 (difference 1.6). S is 7 and 3 (difference 4). Set S has the greatest difference, because its one large value 25 pulls the mean up.', 'checked', '{"lint":[],"solve":{"answer":"Set S","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: mean 6, median 6, diff 0. Q: mean 35/5 = 7, median 6, diff 1. R: mean 37/5 = 7.4, median 9, diff 1.6. S: mean 35/5 = 7, median 3, diff 4. Set S.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('230e65fc-2b89-46f9-9ea2-c96273fcce06', 'NC26.8.RD.3', 3, 'choice', 'Compare the centers (mean or median) of several data sets', 'Class P and Class Q each have 8 students. Class P has a mean score of 78 and a median score of 80. Class Q has a mean score of 82 and a median score of 76. Which statement must be true?', '["The students in Class Q scored more points in total than the students in Class P","Every student in Class Q scored higher than every student in Class P","Class P has the greater mean","Class Q has the greater median"]', 'The students in Class Q scored more points in total than the students in Class P', NULL, 'The classes are the same size, so the class with the greater mean has the greater total: Class Q has $8 \times 82 = 656$ points and Class P has $8 \times 78 = 624$. The other statements fail: Class Q''s median is lower (76 compared with 80), so Class Q has students at or below 76, while Class P has students at or above 80, so not every Class Q student scored higher; and Class P''s mean is lower, not greater.', 'checked', '{"lint":[],"solve":{"answer":"The students in Class Q scored more points in total than the students in Class P","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same size (8): totals P = 624, Q = 656, so Q''s total is greater (must be true). Q''s median 76 < 80; ''every student'' not implied; P''s mean is smaller.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90581467-2519-493f-a82e-6a739474f39e', 'NC26.8.RD.3', 3, 'numeric', 'Compare the spread (range or interquartile range) of several data sets', 'Set A has a smallest value of 13 and a range of 24. Set B has the same greatest value as Set A and a range of 15. What is the smallest value of Set B?', '[]', '22', '13+24-15', 'The greatest value of Set A is the smallest value plus the range: $13 + 24 = 37$. Set B has the same greatest value, 37, and a range of 15, so its smallest value is $37 - 15 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A''s greatest = 13 + 24 = 37. B''s smallest = 37 - 15 = 22.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('32df8788-2c4b-411c-b5db-6667c4b3f6cc', 'NC26.8.RD.3', 3, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'Two sets each have 8 values. Set X: 2, 8, 9, 10, 11, 12, 13, 30. Set Y: 5, 6, 8, 10, 14, 17, 19, 21. Q1 and Q3 are the medians of the lower four and upper four values. Which statement is true?', '["Both the range and the IQR are greater for X","The range is greater for Y, but the IQR is greater for X","Both the range and the IQR are greater for Y","The range is greater for X, but the IQR is greater for Y"]', 'The range is greater for X, but the IQR is greater for Y', NULL, 'Set X: range $30 - 2 = 28$; $Q_1 = 8.5$ and $Q_3 = 12.5$, so IQR $= 4$. Set Y: range $21 - 5 = 16$; $Q_1 = 7$ and $Q_3 = 18$, so IQR $= 11$. X has the greater range (because of the single value 30), but Y has the greater IQR.', 'checked', '{"lint":[],"solve":{"answer":"The range is greater for X, but the IQR is greater for Y","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"X: range 28; Q1 (8+9)/2 = 8.5, Q3 (12+13)/2 = 12.5, IQR 4. Y: range 16; Q1 (6+8)/2 = 7, Q3 (17+19)/2 = 18, IQR 11. Range greater for X, IQR greater for Y.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a503268-ff42-4a1a-8a12-cb3de367f1cf', 'NC26.8.RD.3', 3, 'numeric', 'Compare the spread (range or interquartile range) of several data sets', 'Two sets each have six values. Set A: 13, 21, 9, 17, 25, 11. Set B: 30, 18, 24, 12, 16, 22. With six values, Q1 is the median of the lowest three values and Q3 is the median of the highest three values. How much greater is the IQR of Set A than the IQR of Set B?', '[]', '2', '(21-11)-(24-16)', 'Set A in order is 9, 11, 13, 17, 21, 25: $Q_1 = 11$ and $Q_3 = 21$, so its IQR is $21 - 11 = 10$. Set B in order is 12, 16, 18, 22, 24, 30: $Q_1 = 16$ and $Q_3 = 24$, so its IQR is $24 - 16 = 8$. The difference is $10 - 8 = 2$. (Set B has the greater range, but Set A has the greater IQR.)', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A sorted 9, 11, 13, 17, 21, 25: Q1 = 11, Q3 = 21, IQR 10. B sorted 12, 16, 18, 22, 24, 30: Q1 = 16, Q3 = 24, IQR 8. 10 - 8 = 2.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9f99f89-5164-4901-be7d-a653309420fe', 'NC26.8.RD.3', 3, 'choice', 'Describe and compare the shapes of distributions', 'Two classes of 28 students took a test. The number of students with scores in each interval is listed. Class 1: 50 to 59, two students; 60 to 69, six; 70 to 79, twelve; 80 to 89, six; 90 to 99, two. Class 2: 50 to 59, ten students; 60 to 69, three; 70 to 79, two; 80 to 89, three; 90 to 99, ten. Which statement is true?', '["Class 1 is skewed right and Class 2 is symmetric","Both classes are symmetric about the same center, but Class 2 is much more spread out","Class 2 has a single peak in the 70s","Class 1 is more spread out than Class 2"]', 'Both classes are symmetric about the same center, but Class 2 is much more spread out', NULL, 'Class 1 counts (2, 6, 12, 6, 2) are balanced around the 70s with a single peak there. Class 2 counts (10, 3, 2, 3, 10) are also balanced around the 70s, but the peaks are at the two ends and the middle is nearly empty. So both are symmetric about the same center, and Class 2 is much more spread out.', 'checked', '{"lint":[],"solve":{"answer":"Both classes are symmetric about the same center, but Class 2 is much more spread out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Class 1: 2, 6, 12, 6, 2 (symmetric, one peak in 70s). Class 2: 10, 3, 2, 3, 10 (symmetric about the 70s, peaks at both ends, much more spread). Only the last statement is true.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2082b00a-8b34-4ac5-9c56-2703116adad9', 'NC26.8.RD.3', 3, 'numeric', 'Plot several data sets on one number line', 'Three sets are plotted on one number line. Set A: 4, 8, 9, 15. Set B: 6, 7, 12. Set C: 3, 10, 11, 14, 20. What is the median of all the values shown?', '[]', '9.5', '(9+10)/2', 'There are 12 values in all. In order they are 3, 4, 6, 7, 8, 9, 10, 11, 12, 14, 15, 20. The median is the mean of the 6th and 7th values: $(9 + 10) \div 2 = 9.5$.', 'checked', '{"lint":[],"solve":{"answer":"9.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 values sorted: 3, 4, 6, 7, 8, 9, 10, 11, 12, 14, 15, 20. Median (9+10)/2 = 9.5.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c4b4785-8c2a-45e3-b5e8-dfb72805e2e0', 'NC26.8.RD.3', 3, 'numeric', 'Plot several data sets on one number line', 'Three sets are plotted on one number line. The values of Set A run from 14 to 38. The values of Set B run from 22 to 47. The values of Set C run from 30 to 62. For how many units of the number line do the stretches of all three sets overlap?', '[]', '8', '38-30', 'All three sets cover a part of the line only where the latest start and the earliest end meet. The latest start is 30 (Set C) and the earliest end is 38 (Set A). The shared stretch runs from 30 to 38, which is $38 - 30 = 8$ units.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Common part of 14-38, 22-47, 30-62 is 30-38: 8 units.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6be50784-7780-4419-b37a-12cceadc6167', 'NC26.8.RD.3', 3, 'numeric', 'Read a stem-and-leaf display', 'Three stem-and-leaf displays show test scores (a stem of 6 with a leaf of 4 means 64). Display A: stem 6 has leaves 1, 4, 8; stem 7 has 0, 2, 5, 5, 9; stem 8 has 3, 6. Display B: stem 6 has 5; stem 7 has 1, 3, 6, 8; stem 8 has 0, 2, 4, 7, 9; stem 9 has 1. Display C: stem 5 has 9; stem 6 has 2, 6, 6; stem 7 has 4, 5, 9; stem 8 has 1, 8. What is the range of the display that has the greatest median?', '[]', '26', '91-65', 'Medians: A has 10 values with median 73.5; B has 11 values (65, 71, 73, 76, 78, 80, 82, 84, 87, 89, 91) with median 80; C has 9 values with median 74. Display B has the greatest median. Its range is $91 - 65 = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 61,64,68,70,72,75,75,79,83,86 (10), median 73.5. B: 65,71,73,76,78,80,82,84,87,89,91 (11), median 80. C: 59,62,66,66,74,75,79,81,88 (9), median 74. B greatest; range 91 - 65 = 26.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3acbcc4f-cf87-482e-a535-9fbd485de922', 'NC26.8.RD.3', 3, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display shows the populations of ten small towns, in thousands of people. A stem of 11 with a leaf of 2 means 11.2 thousand. Stem 11 has the leaves 2, 5. Stem 12 has the leaves 0, 4, 4, 9. Stem 13 has the leaves 1, 6, 8. Stem 14 has the leaf 3. What is the median population, in thousands?', '[]', '12.65', '(12.4+12.9)/2', 'The values in order are 11.2, 11.5, 12.0, 12.4, 12.4, 12.9, 13.1, 13.6, 13.8, 14.3. There are 10 values, so the median is the mean of the 5th and 6th: $(12.4 + 12.9) \div 2 = 12.65$ thousand.', 'checked', '{"lint":[],"solve":{"answer":"12.65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"11.2, 11.5, 12.0, 12.4, 12.4, 12.9, 13.1, 13.6, 13.8, 14.3 (10 values). Median (12.4 + 12.9)/2 = 12.65.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9939ad0a-cdbd-4b37-8ced-408a15fd20f0', 'NC26.8.RD.3', 3, 'numeric', 'Read a stem-and-leaf display', 'A stem-and-leaf display of test scores splits each stem in two. A stem marked L holds leaves 0 to 4, and a stem marked H holds leaves 5 to 9, so 6L with leaf 3 means 63 and 6H with leaf 5 means 65. 6L: 1, 3. 6H: 5, 7, 9. 7L: 0, 2, 2, 4. 7H: 5, 5, 6, 8. 8L: 1, 3, 3. 8H: 6, 9. How many scores are from 75 to 84, including both 75 and 84?', '[]', '7', NULL, 'The scores are 61, 63, 65, 67, 69, 70, 72, 72, 74, 75, 75, 76, 78, 81, 83, 83, 86, 89. Those from 75 to 84 are 75, 75, 76, 78 (stem 7H) and 81, 83, 83 (stem 8L). That is $4 + 3 = 7$ scores.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Scores: 61,63, 65,67,69, 70,72,72,74, 75,75,76,78, 81,83,83, 86,89. From 75 to 84: 75,75,76,78,81,83,83 = 7.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c95c9700-804d-497d-b42c-c3155edf91e5', 'NC26.8.RD.3', 3, 'choice', 'Read and compare box plots from five-number summaries', 'Three box plots are described by their minimum, Q1, median, Q3 and maximum. Plot X: 40, 52, 60, 68, 90. Plot Y: 55, 62, 70, 78, 85. Plot Z: 48, 58, 62, 66, 76. Which statement is true?', '["Plots X and Y have the same IQR, but Plot X has the greater range","Plots Y and Z have the same IQR","Plot Z has the greatest range","Plot X has the smallest IQR"]', 'Plots X and Y have the same IQR, but Plot X has the greater range', NULL, 'IQRs: X $68 - 52 = 16$, Y $78 - 62 = 16$, Z $66 - 58 = 8$. Ranges: X $90 - 40 = 50$, Y $85 - 55 = 30$, Z $76 - 48 = 28$. X and Y have equal IQRs (16), and X has the greater range.', 'checked', '{"lint":[],"solve":{"answer":"Plots X and Y have the same IQR, but Plot X has the greater range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"IQR: X 16, Y 16, Z 8. Range: X 50, Y 30, Z 28. X and Y same IQR, X greater range (true).","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ed3741d-b1b4-4f59-8527-018a3b0862e7', 'NC26.8.RD.3', 3, 'numeric', 'Read and compare box plots from five-number summaries', 'A box plot has a median of 50 and an IQR of 24. Q1 is 14 less than the median. What is Q3?', '[]', '60', '50-14+24', 'Q1 is $50 - 14 = 36$. The IQR is Q3 minus Q1, so Q3 is Q1 plus the IQR: $36 + 24 = 60$.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q1 = 50 - 14 = 36. Q3 = Q1 + IQR = 36 + 24 = 60.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5d240acb-ea5a-4fad-a0a0-734f7b427881', 'NC26.8.RD.3', 3, 'choice', 'Read and compare box plots from five-number summaries', 'A box plot has minimum 2, Q1 5, median 8, Q3 12 and maximum 20. Q1 and Q3 are the medians of the lower four and upper four values. Which set of eight values matches this box plot?', '["2, 3, 6, 7, 9, 11, 13, 20","2, 4, 6, 7, 9, 11, 13, 20","2, 4, 6, 8, 9, 11, 13, 20","2, 4, 6, 7, 9, 10, 13, 20"]', '2, 4, 6, 7, 9, 11, 13, 20', NULL, 'For 2, 4, 6, 7, 9, 11, 13, 20: the minimum is 2 and the maximum is 20. The lower four are 2, 4, 6, 7, so $Q_1 = (4 + 6) \div 2 = 5$. The median is $(7 + 9) \div 2 = 8$. The upper four are 9, 11, 13, 20, so $Q_3 = (11 + 13) \div 2 = 12$. Each other set changes one value, which moves one of Q1 (to 4.5), the median (to 8.5) or Q3 (to 11.5).', 'checked', '{"lint":[],"solve":{"answer":"2, 4, 6, 7, 9, 11, 13, 20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need Q1 5, median 8, Q3 12. Option 1: median (8+9)/2 = 8.5, no. Option 2: Q1 (4+6)/2 = 5, median (7+9)/2 = 8, Q3 (11+13)/2 = 12, yes. Option 3: Q1 4.5, no. Option 4: Q3 11.5, no.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('662a91a0-8c75-4cda-9bec-f19922a3885d', 'NC26.8.RD.3', 3, 'numeric', 'Read a histogram or frequency table', 'A histogram of 50 values has five bars. Four of the bars show 6, 14, 8 and 2 values. The fifth bar is the tallest bar. What percent of all 50 values are in the tallest bar?', '[]', '40', '(50-(6+14+8+2))/50*100', 'The four known bars hold $6 + 14 + 8 + 2 = 30$ values, so the fifth bar holds $50 - 30 = 20$ values. That is the tallest bar. As a percent of 50: $20 \div 50 \times 100 = 40\%$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 + 14 + 8 + 2 = 30; fifth bar 50 - 30 = 20 (indeed tallest). 20/50 = 40%.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db03694a-127a-4c96-974a-5f484e4be0ad', 'NC26.8.RD.3', 3, 'choice', 'Read a histogram or frequency table', 'A histogram shows the ages of 40 people at a concert. The bars show: 10 to 19 years, 11 people; 20 to 29 years, 6 people; 30 to 39 years, 5 people; 40 to 49 years, 9 people; 50 to 59 years, 6 people; 60 to 69 years, 3 people. In which interval does the median age fall?', '["10 to 19 years","20 to 29 years","30 to 39 years","40 to 49 years"]', '30 to 39 years', NULL, 'With 40 people, the median is the mean of the 20th and 21st ages when they are put in order. Add up the bars from the youngest: 11, then $11 + 6 = 17$, then $17 + 5 = 22$. The 20th and 21st people are both inside the third bar, so the median age falls in 30 to 39 years. (The tallest bar, 10 to 19 years, is not where the middle of the data is.)', 'checked', '{"lint":[],"solve":{"answer":"30 to 39 years","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 values: median between 20th and 21st. Cumulative: 11, 17, 22. Both the 20th and 21st fall in 30 to 39.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c42f26b-7370-4f95-8b88-aac4e29cdad9', 'NC26.8.RD.3', 3, 'numeric', 'Read a histogram or frequency table', 'Three classes recorded how many students scored 90 or above. Class A: 10 of 40 students. Class B: 8 of 25 students. Class C: 12 of 60 students. What is the greatest of the three percents minus the least of the three percents?', '[]', '12', '8/25*100-12/60*100', 'Class A: $10 \div 40 = 25\%$. Class B: $8 \div 25 = 32\%$. Class C: $12 \div 60 = 20\%$. The greatest percent is 32 and the least is 20, so the difference is 12 percentage points.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A 10/40 = 25%, B 8/25 = 32%, C 12/60 = 20%. 32 - 20 = 12.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c1df347-af3c-44f8-be73-ffbd5da4e67a', 'NC26.8.RD.3', 3, 'numeric', 'Draw a conclusion by comparing groups in context', 'Set A: 38, 44, 49, 51, 53, 57, 61, 70. Set B: 41, 47, 50, 53, 55, 58, 60, 66. How many of the values in Set B are greater than the median of Set A?', '[]', '5', NULL, 'Set A has 8 values, so its median is the mean of the 4th and 5th: $(51 + 53) \div 2 = 52$. The values in Set B that are greater than 52 are 53, 55, 58, 60 and 66. That is 5 values.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A median (51 + 53)/2 = 52. B values above 52: 53, 55, 58, 60, 66 = 5.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b2c99cc-1d12-4822-bffc-2eb34b3e528f', 'NC26.8.RD.3', 3, 'choice', 'Draw a conclusion by comparing groups in context', 'Set A: 20, 22, 25, 27, 30. Set B: 28, 31, 35, 38, 40, 44. The two sets are plotted on one number line. Which statement is true?', '["Every value in Set B is greater than every value in Set A","The median of Set A is greater than the median of Set B","More than half of Set B''s values are greater than every value in Set A","The two sets do not overlap on the number line"]', 'More than half of Set B''s values are greater than every value in Set A', NULL, 'The greatest value in Set A is 30. In Set B, five of the six values (31, 35, 38, 40, 44) are greater than 30, which is more than half. Not every value in B is greater than every value in A, because 28 is not. The sets do overlap (A reaches 30, and B starts at 28), and the median of A (25) is less than the median of B (36.5).', 'checked', '{"lint":[],"solve":{"answer":"More than half of Set B''s values are greater than every value in Set A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A max 30, median 25; B median (35+38)/2 = 36.5, B min 28 < 30 so sets overlap. B values above 30: 31, 35, 38, 40, 44 = 5 of 6, more than half (true).","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9cf40e2-eca8-4410-b3d9-93a8a73a51e9', 'NC26.8.RD.3', 3, 'numeric', 'Draw a conclusion by comparing groups in context', 'Set A has 4 values and a mean of 50. Set B has a mean of 62. When the two sets are put together, the mean of all the values is 58. How many values are in Set B?', '[]', '8', '(4*(58-50))/(62-58)', 'Let Set B have $n$ values. The total of all the values is $4 \times 50 + 62n = 200 + 62n$, and there are $4 + n$ values with a mean of 58, so $200 + 62n = 58(4 + n) = 232 + 58n$. Then $4n = 32$ and $n = 8$. Check: $(200 + 496) \div 12 = 58$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 50 + 62n = 58(4 + n): 200 + 62n = 232 + 58n, 4n = 32, n = 8.","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dd57885e-0b0c-4441-b3b0-4e6c06c3fe05', 'NC26.8.RD.3', 3, 'choice', 'Draw a conclusion by comparing groups in context', 'A teacher wants the class with a median score of at least 80 whose scores are the most consistent, meaning the smallest IQR. The classes have (median, IQR): Class A (82, 12), Class B (82, 6), Class C (79, 4), Class D (85, 18). Which class should the teacher choose?', '["Class A","Class B","Class C","Class D"]', 'Class B', NULL, 'First keep the classes with a median of at least 80: A, B and D. (Class C has the smallest IQR, but its median is only 79.) Among A, B and D the IQRs are 12, 6 and 18, so the smallest is 6, in Class B.', 'checked', '{"lint":[],"solve":{"answer":"Class B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Median at least 80: A (82), B (82), D (85); C (79) excluded. Smallest IQR among them: B (6).","run_id":"claude-code","at":"2026-10-18T01:10:01.076Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f7abcf4-365a-4068-bae7-360ad0bdd460', 'NC26.8.RD.3', 3, 'choice', 'Compare the spread (range or interquartile range) of several data sets', 'Four sets each have eight values. The IQR is Q3 minus Q1, where Q1 is the median of the lowest four values and Q3 is the median of the highest four. Set P: 2, 18, 19, 20, 21, 22, 23, 40. Set Q: 10, 12, 14, 16, 20, 24, 28, 30. Set R: 5, 10, 12, 14, 18, 20, 22, 25. Set S: 6, 9, 11, 13, 15, 17, 19, 22. Which set has the greatest range but the smallest IQR?', '["Set Q","Set R","Set P","Set S"]', 'Set P', NULL, 'Ranges: P is $40 - 2 = 38$, Q is 20, R is 20, S is 16, so P has the greatest range. IQRs: P has Q1 = 18.5 and Q3 = 22.5, so IQR 4. Q has Q1 = 13 and Q3 = 26, so IQR 13. R has Q1 = 11 and Q3 = 21, so IQR 10. S has Q1 = 10 and Q3 = 18, so IQR 8. P also has the smallest IQR, so the answer is Set P. (One extreme value stretches the range of P but not its middle half.)', 'checked', '{"lint":[],"solve":{"answer":"Set P","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: range 38, Q1=(2+18... median of 2,18,19,20)=18.5, Q3=22.5, IQR 4. Q: range 20, IQR 26-13=13. R: range 20, IQR 21-11=10. S: range 16, IQR 18-10=8. P has greatest range and smallest IQR.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('162d89af-e507-4afb-baa8-c2c46a605f7d', 'NC26.8.RD.3', 3, 'numeric', 'Describe and compare the shapes of distributions', 'The median of a box plot is closer to Q1 than to Q3 when the data are stretched out toward the larger values. Four box plots are given as minimum, Q1, median, Q3 and maximum. Plot A: 10, 20, 24, 40, 70. Plot B: 12, 30, 45, 50, 60. Plot C: 5, 14, 20, 26, 35. Plot D: 0, 8, 12, 30, 52. For how many of the plots is the median closer to Q1 than to Q3?', '[]', '2', '2', 'Compare (median - Q1) with (Q3 - median). Plot A: 4 and 16, so closer to Q1. Plot B: 15 and 5, so closer to Q3. Plot C: 6 and 6, so equally far. Plot D: 4 and 18, so closer to Q1. Two plots (A and D) have the median closer to Q1.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 24-20=4 vs 40-24=16 yes. B: 15 vs 5 no. C: 6 vs 6 equal, no. D: 4 vs 18 yes. Count 2.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb93579d-13d5-4158-8ee5-c2b4f6a1d049', 'NC26.8.RD.3', 3, 'choice', 'Describe and compare the shapes of distributions', 'Sets X, Y and Z are plotted on one number line. Set X: 14, 15, 16, 17, 18. Set Y: 14, 15, 16, 17, 38. Set Z: 1, 15, 16, 17, 18. Which statement is true?', '["All three medians are equal, and Set Y has the greatest mean and Set Z the least","All three medians are equal, and Set Y has the least mean and Set Z the greatest","Set Y has the greatest median and the greatest mean of the three sets","All three means are equal, because all three medians are equal"]', 'All three medians are equal, and Set Y has the greatest mean and Set Z the least', NULL, 'Each set has the middle value 16, so the medians are all 16. The means are 16 for Set X, $100 \div 5 = 20$ for Set Y (pulled up by 38) and $67 \div 5 = 13.4$ for Set Z (pulled down by 1). So Y has the greatest mean and Z the least.', 'checked', '{"lint":[],"solve":{"answer":"All three medians are equal, and Set Y has the greatest mean and Set Z the least","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medians all 16. Means: X 80/5=16, Y 100/5=20, Z 67/5=13.4. Y greatest, Z least.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49bc6822-aed4-4b42-8b0c-34913cce9f51', 'NC26.8.RD.3', 3, 'numeric', 'Effect of an outlier when comparing data sets', 'A value is an outlier if it is more than 1.5 times the IQR above Q3. Four sets are plotted on one number line, and the value 70 is one of the values in each. Set A: Q1 = 20, Q3 = 32. Set B: Q1 = 36, Q3 = 60. Set C: Q1 = 44, Q3 = 52. Set D: Q1 = 22, Q3 = 34. In how many of the four sets is 70 an outlier?', '[]', '3', '3', 'Upper fence = Q3 + 1.5 x IQR. Set A: IQR 12, fence $32 + 18 = 50$, and 70 is above it. Set B: IQR 24, fence $60 + 36 = 96$, and 70 is below it. Set C: IQR 8, fence $52 + 12 = 64$, and 70 is above it. Set D: IQR 12, fence $34 + 18 = 52$, and 70 is above it. So 70 is an outlier in 3 sets.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fences Q3+1.5*IQR: A 32+18=50 (70 outlier); B 60+36=96 (no); C 52+12=64 (yes); D 34+18=52 (yes). Count 3.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1055562-5998-4f45-8867-e51eb626b9cb', 'NC26.8.RD.3', 3, 'numeric', 'Effect of an outlier when comparing data sets', 'Set A has five values and a mean of 12. Set B has the same five values plus a sixth value, an outlier of 72. How much greater is the mean of Set B than the mean of Set A?', '[]', '10', '(5*12+72)/6-12', 'The five values of Set A add up to $5 \times 12 = 60$. Adding 72 gives a total of 132 for six values, so the mean of Set B is $132 \div 6 = 22$. The difference is $22 - 12 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sum A=60; B sum 132, mean 132/6=22; 22-12=10.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0951c4d-3e99-4f09-8574-b89b7f203838', 'NC26.8.RD.3', 3, 'numeric', 'Effect of an outlier when comparing data sets', 'Set A is 12, 14, 15, 17, 22. Set B is Set A with one more value, 100, added. Adding the 100 raises the mean by some amount and raises the median by some amount. How much greater is the rise in the mean than the rise in the median?', '[]', '13', '(180/6-80/5)-((15+17)/2-15)', 'Set A: the sum is 80, so the mean is 16, and the median is 15. Set B has six values with a sum of 180, so its mean is 30, and its median is $(15 + 17) \div 2 = 16$. The mean rises by $30 - 16 = 14$ and the median rises by $16 - 15 = 1$. The mean rises $14 - 1 = 13$ more.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: mean 80/5=16, median 15. B: mean 180/6=30, median (15+17)/2=16. Mean rise 14, median rise 1, 14-1=13.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('adb35733-c87a-4275-b92a-3d431159f71c', 'NC26.8.RD.3', 3, 'numeric', 'Read and compare box plots from five-number summaries', 'In a box plot, the lower whisker runs from the minimum to Q1, and the upper whisker runs from Q3 to the maximum. Four box plots are given as minimum, Q1, median, Q3 and maximum. Plot W: 0, 10, 15, 22, 36. Plot X: 12, 20, 28, 40, 70. Plot Y: 5, 25, 33, 45, 60. Plot Z: 30, 36, 50, 62, 90. For how many plots is the upper whisker longer than the lower whisker?', '[]', '3', '3', 'Plot W: lower whisker $10 - 0 = 10$, upper $36 - 22 = 14$, so the upper is longer. Plot X: lower 8, upper 30, so the upper is longer. Plot Y: lower 20, upper 15, so the lower is longer. Plot Z: lower 6, upper 28, so the upper is longer. The upper whisker is longer for 3 plots.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"W: lower 10, upper 14 yes. X: lower 8, upper 30 yes. Y: lower 20, upper 15 no. Z: lower 6, upper 28 yes. Count 3.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e108ecb8-4239-43ac-8cc4-ea99813e2ca4', 'NC26.8.RD.4', 1, 'numeric', 'Compute a variance', 'The variance of a data set is the mean of the squared distances of the values from the mean. The data set 3, 5, 7, 9 has a mean of 6. What is its variance?', '[]', '5', '(9+1+1+9)/4', 'The distances from the mean 6 are 3, 1, 1 and 3. Their squares are 9, 1, 1 and 9. The mean of the squares is $\frac{9+1+1+9}{4} = \frac{20}{4} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distances from 6: -3, -1, 1, 3; squares 9, 1, 1, 9; sum 20; mean 20/4 = 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f165d422-07a9-48fa-b5da-0ea7a126d133', 'NC26.8.RD.4', 1, 'choice', 'Interpret standard deviation as spread', 'Two data sets have the same mean. Set X has a standard deviation of 2 and Set Y has a standard deviation of 7. Which statement is true?', '["The values in Set Y are more spread out than the values in Set X","The values in Set X are more spread out than the values in Set Y","Both sets are equally spread out, because they have the same mean","Set Y has a greater mean than Set X"]', 'The values in Set Y are more spread out than the values in Set X', NULL, 'The standard deviation measures how far values typically are from the mean. A larger standard deviation means more spread. Set Y''s is larger, so its values are more spread out.', 'checked', '{"lint":[],"solve":{"answer":"The values in Set Y are more spread out than the values in Set X","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Larger standard deviation means more spread: Y (7) is more spread than X (2).","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('335b06d5-4f0b-4ca9-af2a-b518ca1350ca', 'NC26.8.RD.4', 1, 'numeric', 'Relate variance and standard deviation', 'A data set has a variance of 25. What is its standard deviation?', '[]', '5', '25/5', 'The standard deviation is the square root of the variance. $\sqrt{25} = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Standard deviation = sqrt(25) = 5.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92c4d444-ae59-48f1-bc77-5326e72daacd', 'NC26.8.RD.4', 1, 'numeric', 'Find the mean and deviations from the mean', 'Five students counted the books they read this month: 3, 5, 6, 4 and 7. The first step toward a standard deviation is finding the mean. What is the mean number of books?', '[]', '5', '(3+5+6+4+7)/5', 'Add: 3 + 5 + 6 + 4 + 7 = 25. Divide by 5 values: 25 / 5 = 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3+5+6+4+7 = 25; 25/5 = 5.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
