INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83589c4a-6422-4e42-bb53-bdf978f684e3', 'NC26.8.RD.4', 1, 'numeric', 'Find the mean and deviations from the mean', 'The mean of a data set is 20. A deviation is a value minus the mean. What is the deviation of the value 14?', '[]', '-6', '14-20', 'The deviation is 14 - 20 = -6. It is negative because 14 is below the mean.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"14 - 20 = -6.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
