INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d4dc106-4cf3-4479-9b51-0d2bdfd0a919', 'NC26.8.RD.4', 1, 'numeric', 'Find the mean and deviations from the mean', 'A data set has a mean of 7 and contains the value 3. What is the square of the distance from 3 to the mean?', '[]', '16', '(3-7)^2', 'The distance from 3 to 7 is 4 (the deviation is -4). Squared: 4 x 4 = 16.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance |3-7| = 4; squared 16.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
