INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fac94972-d082-4d67-a698-4c1828201ca0', 'NC26.8.RD.4', 1, 'choice', 'Compute a variance', 'Two seedlings measure 2 cm and 8 cm. The mean height is 5 cm. What is the variance of the two heights? (The variance is the mean of the squared distances from the mean.)', '["3","18","9","6"]', '9', '((2-10/2)^2+(8-10/2)^2)/2', 'Distances from 5 are -3 and 3. Squared: 9 and 9. The mean of 9 and 9 is 9. (3 is the standard deviation, 18 is the sum, 6 is the range.)', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Deviations -3, 3; squares 9, 9; mean 9.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
