VALUES ('8f56443e-5adf-4c4a-958e-ef90e255ef91', 'NC26.8.RD.4', 1, 'choice', 'Relate variance and standard deviation', 'A data set has a standard deviation of 9. What is its variance?', '["18","3","9","81"]', '81', '9^2', 'The variance is the standard deviation squared: 9 x 9 = 81.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Variance = SD^2 = 81.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
