INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e2f88cc-15cc-4727-95c1-4e8fa0862073', 'NC26.8.RD.4', 1, 'choice', 'Relate variance and standard deviation', 'Which statement correctly relates the variance and the standard deviation of a data set?', '["The standard deviation is the square of the variance","The standard deviation is the square root of the variance","The standard deviation is half of the variance","The variance is the square root of the standard deviation"]', 'The standard deviation is the square root of the variance', NULL, 'Squaring the standard deviation gives the variance, so taking the square root of the variance gives the standard deviation.', 'checked', '{"lint":[],"solve":{"answer":"The standard deviation is the square root of the variance","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SD = sqrt(variance).","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
