INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b21ef6a-89a3-4a1d-99ac-0103dab69393', 'NC26.8.RD.4', 1, 'numeric', 'Relate variance and standard deviation', 'A calculator reports a variance of 144 for a list of race times. What is the standard deviation of the times?', '[]', '12', '12', 'The standard deviation is the square root of the variance. The square root of 144 is 12, because 12 x 12 = 144.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(144) = 12.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
