INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57870a07-ee29-4126-8cc7-7d25af7cd978', 'NC26.8.RD.4', 1, 'choice', 'Compare spread without computing', 'Class A and Class B both have a mean test score of 80. Class A''s scores run from 78 to 82. Class B''s scores run from 60 to 100. Which class most likely has the larger standard deviation?', '["Class A, since its scores are closer to the mean","Class B, since its scores are more spread out","Class A, since its scores are all about equal","Neither, since the two means are the same"]', 'Class B, since its scores are more spread out', NULL, 'The standard deviation measures spread around the mean. Class B''s scores are much more spread out, so its standard deviation is larger.', 'checked', '{"lint":[],"solve":{"answer":"Class B, since its scores are more spread out","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same mean; B spans 60-100 vs A 78-82, so B is more spread out and most likely has the larger SD.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
