INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('788e5e60-861e-40b6-b41b-d60415b87ff0', 'NC26.8.RD.4', 1, 'choice', 'Compare spread without computing', 'A data set has a standard deviation of 0. What must be true?', '["The mean of the values is 0","Half of the values are 0","All the values are the same","All the values are different"]', 'All the values are the same', NULL, 'A standard deviation of 0 means no value is any distance from the mean, so every value equals the mean.', 'checked', '{"lint":[],"solve":{"answer":"All the values are the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"SD 0 means every squared distance is 0, so every value equals the mean: all the same.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
