INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a04275b8-bd4e-4cb9-8c9c-8a1025a04004', 'NC26.8.RD.4', 1, 'choice', 'Effect of changing every value on mean and spread', 'Mr. Ray adds 8 points to every score on a quiz. What happens to the standard deviation of the scores?', '["It increases by 8","It is multiplied by 8","It stays the same","It decreases by 8"]', 'It stays the same', NULL, 'Adding the same number to every value slides the whole data set up. The distances between values do not change, so the spread stays the same.', 'checked', '{"lint":[],"solve":{"answer":"It stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding a constant shifts every value and the mean equally; deviations unchanged, SD unchanged.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
