INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2bbd13eb-9094-4363-aaba-9fc014d048a4', 'NC26.8.RD.4', 2, 'numeric', 'Effect of changing every value on mean and spread', 'A rope company doubles the length of every rope it sells. The old lengths had a mean of 14 feet and a standard deviation of 3 feet. What is the standard deviation of the new lengths, in feet?', '[]', '6', '3*2', 'Multiplying every value by 2 multiplies the standard deviation by 2: 3 x 2 = 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling multiplies SD by 2: 6.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
