INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1acb3f2-a7f7-4d60-9ead-61e0abd3f22e', 'NC26.8.RD.4', 3, 'choice', 'Relate variance and standard deviation', 'A data set has a standard deviation of 0.5. Which statement about its variance is true?', '["It is 0.25, which is smaller than the standard deviation","It is 0.25, which is larger than the standard deviation","It is 1, which is larger than the standard deviation","It is 0.5, which equals the standard deviation"]', 'It is 0.25, which is smaller than the standard deviation', NULL, 'The variance is the square of the standard deviation: 0.5 x 0.5 = 0.25. Squaring a number between 0 and 1 makes it smaller, so 0.25 is less than 0.5.', 'checked', '{"lint":[],"solve":{"answer":"It is 0.25, which is smaller than the standard deviation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"0.5^2 = 0.25 < 0.5.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ecd7d078-26f9-4ce5-afb0-3100f3d67a87', 'NC26.8.RD.4', 3, 'choice', 'Compare spread without computing', 'List P is 10, 20, 30. List Q is 100, 110, 120. List R is 5, 20, 35. Which statement about their standard deviations is true?', '["Q is the greatest, since its values are the largest","All three are equal, since each has three values","P and Q are equal, and R is the greatest","R is the greatest and Q is the smallest"]', 'P and Q are equal, and R is the greatest', NULL, 'Q is P with 90 added to every value, so P and Q have the same spread. R''s values are farther from its mean (15 from it, against 10), so R has the greatest standard deviation.', 'checked', '{"lint":[],"solve":{"answer":"P and Q are equal, and R is the greatest","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P: deviations -10,0,10; Q: -10,0,10 (same); R: -15,0,15, larger. P = Q, R greatest.","run_id":"claude-code","at":"2026-10-18T03:36:40.838Z"}}', 'ai', NULL, NULL)
