INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed00a91c-5de1-40ca-ab68-7338866803f2', 'NC26.8.RD.5', 1, 'choice', 'Compare the medians of several data sets', 'The median trip time on Route B is 25 minutes. What does that tell you about the trips on Route B?', '["Every trip took exactly 25 minutes.","Half of the trips took 25 minutes or less.","The most common trip time was 25 minutes.","The shortest trip and the longest trip averaged 25 minutes."]', 'Half of the trips took 25 minutes or less.', NULL, 'The median is the middle value when the times are put in order, so half of the values are at or below it and half are at or above it. It does not say every trip was 25 minutes, it is not the most common value (the mode), and it is not necessarily halfway between the shortest and longest.', 'checked', '{"lint":[],"solve":{"answer":"Half of the trips took 25 minutes or less.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The median splits the ordered trip times so that (at least) half are at or below 25 minutes. The others describe the mode, the midrange and a constant set.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2e27e800-0a0c-4be2-96d7-dbe7a3b0f674', 'NC26.8.RD.5', 1, 'numeric', 'Compare the medians of several data sets', 'Two groups of five students counted how many push-ups they could do. Group A: 12, 8, 15, 10, 9. Group B: 14, 20, 11, 13, 18. How many greater is the median of Group B than the median of Group A?', '[]', '4', '14-10', 'Group A in order: 8, 9, 10, 12, 15, so its median is 10. Group B in order: 11, 13, 14, 18, 20, so its median is 14. The difference is $14 - 10 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A ordered 8, 9, 10, 12, 15: median 10. B ordered 11, 13, 14, 18, 20: median 14. 14 - 10 = 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
