INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('452befa9-2606-4f9c-ba6c-850a70cd95d3', 'NC26.8.RD.5', 1, 'numeric', 'Draw conclusions and recommend a plan from the data', 'A school compares three study programs. The mean gain in test score was 8 points for Program A, 11 points for Program B and 5 points for Program C. If 40 students join the program with the greatest mean gain, how many points in total would the school expect them to gain altogether?', '[]', '440', '40*11', 'Program B has the greatest mean gain, 11 points. For 40 students the expected total is $40 \times 11 = 440$ points.', 'checked', '{"lint":[],"solve":{"answer":"440","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Greatest mean gain is Program B, 11 points. 40 x 11 = 440.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7daf7d54-35fa-48b2-a238-3758ce0f67ad', 'NC26.8.RD.5', 1, 'choice', 'Reflect on sampling and methods', 'A student wants to compare how many hours students at her school sleep. Which sample is most likely to represent all the students at the school?', '["10 students chosen at random from a list of every student","The first 10 students in the lunch line","The 10 members of the chess club","The 10 friends of the person doing the survey"]', '10 students chosen at random from a list of every student', NULL, 'A random sample from the whole school gives every student the same chance to be chosen. The other groups are chosen by something that may be linked to how much they sleep.', 'checked', '{"lint":[],"solve":{"answer":"10 students chosen at random from a list of every student","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from a list of every student is the representative one; the others are convenience or self-similar groups.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('baca44b5-1410-46c3-a227-cdeef28837fa', 'NC26.8.RD.5', 1, 'choice', 'Reflect on sampling and methods', 'Which survey question is the fairest way to find out how many hours students sleep?', '["Don''t you agree that students should sleep 9 hours?","Students who sleep too little fail tests. How many hours do you sleep?","How many hours did you sleep last night?","Do you like to sleep a lot?"]', 'How many hours did you sleep last night?', NULL, 'A fair question does not push people toward an answer and asks for the number you want to know. The first question asks for hours directly. The others lead the answer or ask for something else.', 'checked', '{"lint":[],"solve":{"answer":"How many hours did you sleep last night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The neutral, specific question is \"How many hours did you sleep last night?\"; the others are leading or vague.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29557680-aabe-4a21-b419-a81acbab52da', 'NC26.8.RD.5', 1, 'choice', 'Reflect on sampling and methods', 'Why is it better to survey 100 randomly chosen students than 5 randomly chosen students?', '["A larger sample always gives the same results as a smaller sample.","A larger sample lets the surveyor choose which students to include.","A larger sample removes the need to ask a fair question.","A larger random sample is more likely to be close to the whole population."]', 'A larger random sample is more likely to be close to the whole population.', NULL, 'With more randomly chosen students, one unusual student has less effect, so the results are more likely to be close to what the whole population would say. A bigger sample does not make the results identical, and it does not fix unfair questions or biased selection.', 'checked', '{"lint":[],"solve":{"answer":"A larger random sample is more likely to be close to the whole population.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A larger random sample tends to give results closer to the population.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('647221ba-e992-4615-9995-61cc67607f59', 'NC26.8.RD.5', 1, 'numeric', 'Summarize a distribution with its five-number summary', 'The five-number summary of a set of test scores is: least 4, Q1 9, median 13, Q3 18, greatest 26. What is the range of the scores?', '[]', '22', '26-4', 'The range is the greatest value minus the least value: $26 - 4 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"26 - 4 = 22.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7ad9710-bfa7-4a56-b32d-16e934521a28', 'NC26.8.RD.5', 1, 'numeric', 'Summarize a distribution with its five-number summary', 'The five-number summary of the time (in minutes) that students spend on homework is: least 10, Q1 25, median 40, Q3 55, greatest 90. What is the interquartile range?', '[]', '30', '55-25', 'The interquartile range is Q3 minus Q1: $55 - 25 = 30$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q3 - Q1 = 55 - 25 = 30.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd2f23f1-e881-40ba-ada5-0926d9ade4af', 'NC26.8.RD.5', 1, 'choice', 'Summarize a distribution with its five-number summary', 'In a five-number summary, about what fraction of the values lies between Q1 and Q3?', '["About one half","About one quarter","About three quarters","All of them"]', 'About one half', NULL, 'The values are split into four parts of about equal size by Q1, the median and Q3. The two middle parts, between Q1 and Q3, hold about half of the values.', 'checked', '{"lint":[],"solve":{"answer":"About one half","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Q1 to Q3 holds the middle 50%: about one half.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('466f9744-0161-4c08-b1b8-75b9312fce46', 'NC26.8.RD.5', 2, 'numeric', 'Combined mean of groups of different sizes', 'Group 1 has 10 students with a mean score of 80 points. Group 2 has 30 students with a mean score of 60 points. What is the mean score of all 40 students together?', '[]', '65', '(10*80+30*60)/40', 'Group 1''s total is $10 \times 80 = 800$ and Group 2''s total is $30 \times 60 = 1800$. The total for all 40 students is $2600$, so the mean is $2600 \div 40 = 65$. (It is closer to 60 than to 80 because Group 2 is larger.)', 'checked', '{"lint":[],"solve":{"answer":"65","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(10*80 + 30*60)/40 = (800 + 1800)/40 = 2600/40 = 65.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('245e609e-ab46-4316-81b5-8341c120ef21', 'NC26.8.RD.5', 2, 'choice', 'Compare center and spread across populations', 'Plants were grown with three fertilizers, and their heights after four weeks were recorded in centimeters. Fertilizer A: mean 12, range 3. Fertilizer B: mean 14, range 12. Fertilizer C: mean 13, range 4. Which statement is supported by these data?', '["Fertilizer A has the highest mean height and varies the least","Fertilizer C has the lowest mean height and varies the most","Fertilizer B has the highest mean height, but its heights vary the most","Every plant grown with Fertilizer B was taller than every plant grown with Fertilizer A"]', 'Fertilizer B has the highest mean height, but its heights vary the most', NULL, 'B has the highest mean (14) and the largest range (12), so it varies the most. A has the lowest mean (12), not the highest, and C is neither the lowest in mean nor the most variable. "Every plant grown with Fertilizer B was taller" is not supported: means and ranges do not tell us that every plant was taller.', 'checked', '{"lint":[],"solve":{"answer":"Fertilizer B has the highest mean height, but its heights vary the most","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B has highest mean (14) and largest range (12). A has lowest mean; C does not vary most; means/ranges cannot show every B plant taller.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20a3f420-fc29-45e4-ab2c-86d8ec67b1be', 'NC26.8.RD.5', 2, 'choice', 'Compare percents when sample sizes differ', 'Students in three grades were asked whether they like a new class schedule. In Grade 6, 18 of 20 students said yes. In Grade 7, 30 of 50 said yes. In Grade 8, 33 of 44 said yes. Which grade had the greatest percent of students saying yes?', '["Grade 6","Grade 7","Grade 8","The three grades are tied"]', 'Grade 6', NULL, 'Compare percents, not counts. Grade 6: $\frac{18}{20} = 90\%$. Grade 7: $\frac{30}{50} = 60\%$. Grade 8: $\frac{33}{44} = 75\%$. Grade 6 is greatest, even though Grade 8 had the most students saying yes.', 'checked', '{"lint":[],"solve":{"answer":"Grade 6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 6: 18/20 = 90%. Grade 7: 30/50 = 60%. Grade 8: 33/44 = 75%. Greatest: Grade 6.","run_id":"claude-code","at":"2026-10-17T18:34:49.484Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a7690ea-9e3d-4ae6-a9e0-fefcbbcb62d8', 'NC26.8.RD.5', 2, 'choice', 'Compare the means of several populations', 'A researcher asked students in four clubs how many hours a week they read. The means were 5.5 hours for Chess, 4.0 hours for Art, 6.5 hours for Drama and 5.0 hours for Robotics. Which statement is true?', '["The mean for Drama is 2.5 hours greater than the mean for Art.","The mean for Chess is 2.0 hours greater than the mean for Art.","The mean for Robotics is 0.5 hours greater than the mean for Chess.","The mean for Drama is 1.0 hour less than the mean for Robotics."]', 'The mean for Drama is 2.5 hours greater than the mean for Art.', NULL, 'Drama minus Art is $6.5 - 4.0 = 2.5$ hours, so that statement is true. Chess minus Art is only 1.5 hours. Robotics (5.0) is 0.5 hours LESS than Chess (5.5), and Drama (6.5) is 1.5 hours MORE than Robotics (5.0).', 'checked', '{"lint":[],"solve":{"answer":"The mean for Drama is 2.5 hours greater than the mean for Art.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Robotics 5.0 < Chess 5.5 (false). Drama - Art = 6.5 - 4.0 = 2.5 (true). Drama is 1.5 MORE than Robotics (false). Chess - Art = 1.5, not 2.0 (false).","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40cb56cb-2acd-4218-be7b-cd02d3a3dbe6', 'NC26.8.RD.5', 2, 'numeric', 'Compare the means of several populations', 'Plants were grown in three kinds of soil. After a month their heights, in centimeters, were: Soil A: 8, 11, 9, 12, 10. Soil B: 13, 12, 15, 11, 14. Soil C: 9, 14, 10, 8, 14. How many centimeters greater is the greatest of the three soil means than the least of them?', '[]', '3', '(13+12+15+11+14)/5-(8+11+9+12+10)/5', 'Soil A: $(8 + 11 + 9 + 12 + 10) \div 5 = 10$. Soil B: $(13 + 12 + 15 + 11 + 14) \div 5 = 13$. Soil C: $(9 + 14 + 10 + 8 + 14) \div 5 = 11$. The greatest mean is 13 and the least is 10, a difference of 3 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 8+11+9+12+10 = 50, mean 10. B: 13+12+15+11+14 = 65, mean 13. C: 9+14+10+8+14 = 55, mean 11. 13 - 10 = 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fb6757a-2d17-416e-abc1-cefa61aa2205', 'NC26.8.RD.5', 2, 'numeric', 'Compare the means of several populations', 'Students in three grades were asked how many minutes they spend on homework on a school night. The mean for Grade 7 was 9 minutes more than the mean for Grade 6, and the mean for Grade 8 was 12 minutes more than the mean for Grade 7. The mean for Grade 6 was 31 minutes. What was the mean for Grade 8, in minutes?', '[]', '52', '31+9+12', 'Grade 7: $31 + 9 = 40$ minutes. Grade 8: $40 + 12 = 52$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 6 = 31; Grade 7 = 31 + 9 = 40; Grade 8 = 40 + 12 = 52.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b8036e43-b18c-4236-8726-b0ec39d9693a', 'NC26.8.RD.5', 2, 'numeric', 'Combined mean of groups of different sizes', 'Three hiking groups weighed their packs. The 4 hikers in Group 1 had a mean pack weight of 30 pounds, the 6 hikers in Group 2 had a mean of 25 pounds and the 10 hikers in Group 3 had a mean of 20 pounds. What is the mean pack weight of all 20 hikers, in pounds?', '[]', '23.5', '(4*30+6*25+10*20)/20', 'The pack weights add to $4 \times 30 + 6 \times 25 + 10 \times 20 = 120 + 150 + 200 = 470$ pounds. The mean is $470 \div 20 = 23.5$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"23.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 x 30 = 120; 6 x 25 = 150; 10 x 20 = 200; total 470; 470 / 20 = 23.5.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ba4a3ed8-49aa-4e1e-97b7-3a25f4998e9d', 'NC26.8.RD.5', 2, 'numeric', 'Combined mean of groups of different sizes', 'A store recorded how many customers came each day. Over 20 weekdays the mean was 90 customers a day. Over 8 weekend days the mean was 160 customers a day. What was the mean number of customers a day over all 28 days?', '[]', '110', '(20*90+8*160)/28', 'Weekdays brought $20 \times 90 = 1800$ customers and weekend days brought $8 \times 160 = 1280$ customers. That is $3080$ customers in 28 days, and $3080 \div 28 = 110$.', 'checked', '{"lint":[],"solve":{"answer":"110","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 x 90 = 1800; 8 x 160 = 1280; total 3080; 3080 / 28 = 110.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41c2f421-1e6a-42ab-9b90-8cd79093d68f', 'NC26.8.RD.5', 2, 'choice', 'Combined mean of groups of different sizes', 'Group 1 has 12 students with a mean of 70 points. Group 2 has 18 students with a mean of 90 points. Which expression gives the mean of all the students?', '["$(70 + 90) \\div 2$","$(12 \\times 70 + 18 \\times 90) \\div 30$","$(12 + 18) \\div (70 + 90)$","$(12 \\times 70 + 18 \\times 90) \\div 2$"]', '$(12 \times 70 + 18 \times 90) \div 30$', NULL, 'Multiply each mean by its group size to get each group''s total points, add the totals, then divide by the number of students in both groups, $12 + 18 = 30$. Averaging 70 and 90 ignores the group sizes, and dividing by 2 instead of 30 does not give a mean of students.', 'checked', '{"lint":[],"solve":{"answer":"$(12 \\times 70 + 18 \\times 90) \\div 30$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total points 12 x 70 + 18 x 90, divided by the number of students 12 + 18 = 30.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7fda02d8-129e-4e2d-82bb-29dbf2e01244', 'NC26.8.RD.5', 2, 'numeric', 'Find a missing value or group mean from an overall mean', 'A cafe served 100 customers one day. In the morning 25 customers spent a mean of 16 dollars each. The other 75 customers came in the afternoon. The mean amount spent by all 100 customers was 22 dollars. What was the mean amount spent by an afternoon customer, in dollars?', '[]', '24', '(100*22-25*16)/75', 'All customers spent $100 \times 22 = 2200$ dollars. The morning customers spent $25 \times 16 = 400$ dollars. The afternoon customers spent $2200 - 400 = 1800$ dollars, so their mean is $1800 \div 75 = 24$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 100 x 22 = 2200. Morning 25 x 16 = 400. Afternoon 1800 / 75 = 24.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1fa0b24-c7ea-479a-812c-19d7357fab62', 'NC26.8.RD.5', 2, 'numeric', 'Find a missing value or group mean from an overall mean', 'A teacher recorded 24 test scores with a mean of 78. After the test of a student who had been absent was added, the mean of all 25 scores was 77. What was the score of the late test?', '[]', '53', '25*77-24*78', 'The 25 scores add to $25 \times 77 = 1925$. The first 24 scores add to $24 \times 78 = 1872$. The late score is $1925 - 1872 = 53$.', 'checked', '{"lint":[],"solve":{"answer":"53","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"25 x 77 = 1925; 24 x 78 = 1872; 1925 - 1872 = 53.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d2d6668-6e08-4d26-b5fb-4d495ff7561f', 'NC26.8.RD.5', 2, 'choice', 'Find a missing value or group mean from an overall mean', 'Class A has a mean score of 70 and Class B has a mean score of 90. The two classes together have a mean score of 82. Which statement must be true?', '["Class A has more students than Class B.","The two classes have the same number of students.","It cannot be told which class has more students without knowing the exact numbers.","Class B has more students than Class A."]', 'Class B has more students than Class A.', NULL, 'If the classes were the same size, the combined mean would be exactly halfway, 80. The combined mean 82 is closer to 90 than to 70, so the class with mean 90, Class B, counts for more. Class B has more students.', 'checked', '{"lint":[],"solve":{"answer":"Class B has more students than Class A.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"70a + 90b = 82(a + b) gives 8b = 12a, so b = 1.5a: Class B has more students (82 is nearer 90).","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a8c9b5f-b8f6-48e7-9a80-e06a5f554ca0', 'NC26.8.RD.5', 2, 'numeric', 'Compare the medians of several data sets', 'Six people waited 12, 5, 9, 15, 7 and 10 minutes at a bus stop. What is the median waiting time, in minutes?', '[]', '9.5', '(9+10)/2', 'In order: 5, 7, 9, 10, 12, 15. With six values the median is halfway between the two middle ones, 9 and 10: $(9 + 10) \div 2 = 9.5$ minutes.', 'checked', '{"lint":[],"solve":{"answer":"9.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered 5, 7, 9, 10, 12, 15. Median (9 + 10) / 2 = 9.5.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43e25709-f763-4aca-92a9-394893aaf3d2', 'NC26.8.RD.5', 2, 'choice', 'Compare the medians of several data sets', 'Three bakeries recorded the number of loaves left unsold each day. Bakery A (5 days): 4, 9, 6, 2, 8. Bakery B (6 days): 3, 7, 6, 10, 1, 9. Bakery C (4 days): 6, 4, 8, 5. Which bakery has the greatest median number of unsold loaves?', '["Bakery B","Bakery A","Bakery C","All three bakeries have the same median"]', 'Bakery B', NULL, 'Bakery A in order: 2, 4, 6, 8, 9, median 6. Bakery B in order: 1, 3, 6, 7, 9, 10, median 6.5 (the middle two are 6 and 7). Bakery C in order: 4, 5, 6, 8, median 5.5. Bakery B has the greatest median.', 'checked', '{"lint":[],"solve":{"answer":"Bakery B","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A ordered 2, 4, 6, 8, 9: median 6. B ordered 1, 3, 6, 7, 9, 10: median 6.5. C ordered 4, 5, 6, 8: median 5.5. B is greatest.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2e185e2-f606-4381-9b22-2665082453f1', 'NC26.8.RD.5', 2, 'numeric', 'Compare the medians of several data sets', 'Four runners finished a race in 31, 28, 35 and 30 seconds. A fifth runner then finished in 27 seconds. What is the median finishing time of all five runners, in seconds?', '[]', '30', '30', 'In order the five times are 27, 28, 30, 31, 35. The middle (third) one is 30 seconds.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ordered 27, 28, 30, 31, 35: median 30.","run_id":"claude-code","at":"2026-10-18T01:08:17.741Z"}}', 'ai', NULL, NULL)
