INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('088db34d-f96b-440b-8b0e-7cc433092145', 'NC26.M1.RMM.1', 1, 'choice', 'Build a model from a situation or data', 'A pottery studio charges 30 dollars to register plus 12 dollars for each class. Which equation gives the total cost $C$ after $n$ classes?', '["$C = 12 + 30n$","$C = 42n$","$C = 30 + 12n$","$C = 30n + 12$"]', '$C = 30 + 12n$', NULL, 'The 30 dollar registration is paid once. The 12 dollar fee is paid for each of the $n$ classes, so the total is $30 + 12n$.', 'checked', '{"lint":[],"solve":{"answer":"$C = 30 + 12n$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fixed 30 plus 12 per class: C = 30 + 12n.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
