INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5648cf7a-cde0-4a17-ae57-bd526486140b', 'NC26.M1.RMM.1', 1, 'choice', 'Revise a model', 'A model''s predictions are always exactly 5 too high. Which is a sensible revision?', '["Raise the model''s starting value by an extra 5","Lower the model''s starting value by 5","Multiply the model''s rate of change by 5","Throw away all of the data"]', 'Lower the model''s starting value by 5', NULL, 'If every prediction is 5 too high, lowering the starting value by 5 shifts all predictions down to match the measurements.', 'checked', '{"lint":[],"solve":{"answer":"Lower the model''s starting value by 5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Constant overestimate of 5: subtract 5 from the starting value.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
