INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebedbc30-7aad-45e1-99c8-df9f905f4706', 'NC26.M1.RMM.1', 1, 'numeric', 'Explain what a model''s parts mean', 'In the model $T = 8 + 5h$, $T$ is the dollars a tutor charges for $h$ hours. How many dollars does each extra hour add to the charge?', '[]', '5', '5', 'The number multiplying $h$ is the amount added for each hour. It is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 5 dollars per hour.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
