INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f75be990-39d9-4a2e-945e-64081258681f', 'NC26.M1.RMM.1', 1, 'numeric', 'Explain what a model''s parts mean', 'In the model $N = 5 \times 3^t$, $N$ is the number of bacteria after $t$ hours. How many bacteria does the model say there are at the start, when $t = 0$?', '[]', '5', '5*3^0', 'Put $t = 0$: $5 \times 3^0 = 5 \times 1 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 x 3^0 = 5.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
