INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5b75ef40-4ed0-4ca9-b032-c5f499afa423', 'NC26.M1.RMM.1', 1, 'numeric', 'Critique a model and its limits', 'A model says 7.5 buses are needed for a field trip. What is the fewest buses the school can order so that everyone can go?', '[]', '8', '8', 'You cannot order half a bus, and 7 buses would be too few. Round up to 8.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7.5 buses -> round up to 8.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
