INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c28d787a-40e3-4d62-8e93-ef93596cbcee', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the problem a model should answer', 'Which question can be answered using a mathematical model?', '["Is saving money for the future more fun than spending it right away?","How many weeks until saving 15 dollars a week reaches 240 dollars?","Who is the best at saving money among all the students in the class?","Should students be paid an allowance for doing their chores at home?"]', 'How many weeks until saving 15 dollars a week reaches 240 dollars?', NULL, 'A model works with quantities. The first question asks for a number of weeks from a rate of saving and a target; the others are matters of opinion or comparison.', 'checked', '{"lint":[],"solve":{"answer":"How many weeks until saving 15 dollars a week reaches 240 dollars?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only the savings question is quantitative: 240/15 = 16 weeks.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1839d25-e6d6-43eb-b91b-f90498f4417e', 'NC26.M1.RMM.1', 2, 'choice', 'Name quantities and variables', 'Mia is modeling how many weeks she needs to save for a 300 dollar tablet. She saves 20 dollars a week. Which piece of information is not needed for the model?', '["The tablet''s price","Her saving each week","Her savings so far","The color of the tablet"]', 'The color of the tablet', NULL, 'The model needs the price, the weekly saving and the amount saved already. The color has no effect on the number of weeks.', 'checked', '{"lint":[],"solve":{"answer":"The color of the tablet","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Color is irrelevant; price, current savings and weekly saving all affect the weeks.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c62e76e7-a563-4b72-9204-5bb3df566746', 'NC26.M1.RMM.1', 2, 'choice', 'Name quantities and variables', 'In a model, $d$ is a distance in miles and $t$ is a time in hours. What does $\frac{d}{t}$ represent?', '["Speed in miles per hour","Time in hours for each mile","Distance in miles","Time in hours"]', 'Speed in miles per hour', NULL, 'Distance divided by time is a rate of travel: miles per hour, or speed.', 'checked', '{"lint":[],"solve":{"answer":"Speed in miles per hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"miles/hours = speed in mph.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30eacbca-0b1d-4a41-86a1-c5d741dead98', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'A model for a trip says the time is $t = \frac{d}{50}$ hours for a distance of $d$ miles. Which real-world factor does this model ignore?', '["The total length of the trip in miles, which the model uses","The assumed speed of 50 miles per hour on the whole trip","Traffic and stops that slow the average speed","The units of the distance"]', 'Traffic and stops that slow the average speed', NULL, 'The model assumes a steady 50 miles per hour, so it ignores anything that changes the speed, such as traffic and stops.', 'checked', '{"lint":[],"solve":{"answer":"Traffic and stops that slow the average speed","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d/50 assumes constant 50 mph; ignores traffic and stops. Other options are things the model uses.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66b91c1f-f11b-4d14-982d-9e386ae407c1', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'A model for a town is $P = 2000(1.05)^t$ people after $t$ years. Which assumption does it make?', '["The population grows by the same number of people each year","The population stops growing altogether after 5 years","The population grows by the same percent each year","The population falls by 5% of its size every single year"]', 'The population grows by the same percent each year', NULL, 'Multiplying by 1.05 each year is growth of 5% of the current population every year, which is a constant percent, not a constant number of people.', 'checked', '{"lint":[],"solve":{"answer":"The population grows by the same percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 1.05 each year: constant percent growth (5%).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f17d736-f1db-4240-bc40-2c0f241b0213', 'NC26.M1.RMM.1', 2, 'choice', 'Identify the assumptions of a model', 'Dan models the time to fill a bathtub by assuming the faucet runs at a steady rate. Which event would break this assumption?', '["The water pressure drops while others use water in the house","The tub turns out to hold more water than expected","Dan fills the tub in the evening instead of the morning","Dan measures the water in liters, not gallons"]', 'The water pressure drops while others use water in the house', NULL, 'A change in pressure changes how fast the water flows, so the rate is no longer steady. The other events do not affect the rate.', 'checked', '{"lint":[],"solve":{"answer":"The water pressure drops while others use water in the house","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A pressure drop changes flow rate, breaking the steady-rate assumption.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('acbc7010-cede-4184-938e-a3bbefa84859', 'NC26.M1.RMM.1', 2, 'choice', 'Build a model from a situation or data', 'A hot tub holds 500 gallons and drains 25 gallons each minute. Which equation gives the gallons $G$ left after $m$ minutes?', '["$G = 25 - 500m$","$G = 500 + 25m$","$G = 475m$","$G = 500 - 25m$"]', '$G = 500 - 25m$', NULL, 'The tub starts at 500 gallons and loses 25 gallons for each of the $m$ minutes, so $G = 500 - 25m$.', 'checked', '{"lint":[],"solve":{"answer":"$G = 500 - 25m$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 500, minus 25 per minute: G = 500 - 25m.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('76e89df5-b701-4811-80a7-865f927c68c9', 'NC26.M1.RMM.1', 2, 'choice', 'Build a model from a situation or data', 'A savings account starts with 800 dollars and earns 3% interest each year. Which equation gives the balance $A$ after $t$ years?', '["$A = 800 + 0.03t$","$A = 800(1.03)^t$","$A = 800(0.03)^t$","$A = 800 \\times 3^t$"]', '$A = 800(1.03)^t$', NULL, 'Each year the balance is multiplied by 1.03 (100% plus 3%), so after $t$ years it is $800(1.03)^t$.', 'checked', '{"lint":[],"solve":{"answer":"$A = 800(1.03)^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3% growth: factor 1.03: A = 800(1.03)^t.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3440d8af-20c4-441b-bd42-c316977d561d', 'NC26.M1.RMM.1', 2, 'numeric', 'Build a model from a situation or data', 'A seedling is 12 centimeters tall at week 0 and 42 centimeters tall at week 5. If it grows by the same amount each week, how many centimeters does it grow per week?', '[]', '6', '(42-12)/5', 'It grows $42 - 12 = 30$ centimeters in 5 weeks, so $30 \div 5 = 6$ centimeters each week.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(42 - 12)/5 = 30/5 = 6.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60fb0885-6585-4580-b19d-5bf93c62f165', 'NC26.M1.RMM.1', 2, 'numeric', 'Build a model from a situation or data', 'A culture had 80 cells at hour 0, 120 cells at hour 1 and 180 cells at hour 2. The cells grow by the same factor each hour. What is that factor?', '[]', '1.5', '120/80', 'Divide each count by the one before: $120 \div 80 = 1.5$ and $180 \div 120 = 1.5$.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"120/80 = 1.5, 180/120 = 1.5.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('370d7b54-2813-439a-b86d-34458bcbd789', 'NC26.M1.RMM.1', 2, 'choice', 'Build a model from a situation or data', 'A farmer has 40 meters of fence for a rectangular pen. If the width is $w$ meters, which equation gives the area $A$ in square meters?', '["$A = w(40 - w)$","$A = w(20 - w)$","$A = 40w$","$A = 20 - w^2$"]', '$A = w(20 - w)$', NULL, 'Two widths and two lengths use 40 meters, so width plus length is 20. The length is $20 - w$, and the area is $w(20 - w)$.', 'checked', '{"lint":[],"solve":{"answer":"$A = w(20 - w)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2w + 2L = 40 -> L = 20 - w; A = w(20 - w).","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6486637e-6e3c-423f-856d-f3096f078727', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'The model $M = 200 \times (0.5)^h$ gives the milligrams of a medicine in the blood $h$ hours after a dose. How many milligrams does it give after 3 hours?', '[]', '25', '200*0.5^3', 'Put $h = 3$: $200 \times 0.5^3 = 200 \times 0.125 = 25$.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200 x 0.125 = 25.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61c08f1c-b387-4b47-b971-5667d557bf75', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'A baker sells loaves at 4 dollars each. Each loaf costs 1.50 dollars to make. In a model of profit, how many dollars of profit come from selling 40 loaves?', '[]', '100', '40*(4-1.5)', 'Profit per loaf is $4 - 1.50 = 2.50$ dollars. For 40 loaves: $40 \times 2.50 = 100$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Profit per loaf 4 - 1.50 = 2.50; 40 x 2.50 = 100.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a02e98f7-6c11-413d-9257-78c0b33b1bd4', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'The height of a thrown ball is modeled by $h = -5t^2 + 40t$ meters after $t$ seconds. What height does the model give after 3 seconds, in meters?', '[]', '75', '-5*9+40*3', 'Put $t = 3$: $-5 \times 9 + 40 \times 3 = -45 + 120 = 75$.', 'checked', '{"lint":[],"solve":{"answer":"75","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5(9) + 40(3) = -45 + 120 = 75.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9942af27-32c3-40fe-a4b6-cf18e84076dd', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'Plan A costs 15 dollars plus 4 dollars per visit. Plan B costs 7 dollars per visit. For how many visits do the two plans cost the same?', '[]', '5', '15/(7-4)', 'Set $15 + 4v = 7v$. Then $15 = 3v$, so $v = 5$. Both plans cost 35 dollars.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"15 + 4v = 7v -> 3v = 15 -> v = 5.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('540434c4-3359-45bb-9bb7-5514e4db3c55', 'NC26.M1.RMM.1', 2, 'numeric', 'Analyse a model to predict or solve', 'A parking garage charges $P = 3 + 2h$ dollars for $h$ hours. For how many hours can a driver park with 15 dollars?', '[]', '6', '(15-3)/2', 'Solve $3 + 2h = 15$. Then $2h = 12$, so $h = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 + 2h = 15 -> h = 6.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7f774a5-f234-4155-b105-2750e0ecaa6e', 'NC26.M1.RMM.1', 2, 'numeric', 'Test a conjecture or model against data', 'The model $P = 12 + 3d$ gives the pages $P$ read after $d$ days. A student has really read 31 pages after 5 days. By how many pages is the real number above the prediction?', '[]', '4', '31-(12+3*5)', 'The model predicts $12 + 3 \times 5 = 27$ pages. The real number is 31, which is $31 - 27 = 4$ more.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Prediction 12 + 15 = 27; 31 - 27 = 4.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ed37a91-6de9-4d28-b8db-f85f2abc6099', 'NC26.M1.RMM.1', 2, 'choice', 'Test a conjecture or model against data', 'A student claims the values 3, 6, 12, 24 at times 0, 1, 2, 3 follow a linear pattern. Which statement is correct?', '["The claim is true, because each value is larger than the value before it","The claim is true, because the first two values differ by 3","The claim is false, because the values are all multiples of 3","The claim is false, because the differences 3, 6 and 12 are not equal"]', 'The claim is false, because the differences 3, 6 and 12 are not equal', NULL, 'A linear pattern has a constant difference. These differences keep doubling, so the pattern is not linear (it is exponential).', 'checked', '{"lint":[],"solve":{"answer":"The claim is false, because the differences 3, 6 and 12 are not equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Differences 3, 6, 12 not constant, so not linear.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc53243a-1aa7-4e88-bd09-19d48057db1f', 'NC26.M1.RMM.1', 2, 'numeric', 'Test a conjecture or model against data', 'A model predicts temperatures of 77, 74 and 71 degrees at minutes 1, 2 and 3. The measured temperatures are 77, 73 and 69 degrees. What is the total of the amounts by which the model is too high?', '[]', '3', '(77-77)+(74-73)+(71-69)', 'The model is too high by $77 - 77 = 0$, then $74 - 73 = 1$, then $71 - 69 = 2$. The total is $0 + 1 + 2 = 3$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Over by 0, 1, 2: total 3.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('733fc945-abb6-46bb-aca5-17711d0a17bf', 'NC26.M1.RMM.1', 2, 'choice', 'Revise a model', 'A student''s straight-line model of a plant''s height fit the first 6 weeks, but it overpredicts later as the plant''s growth slows. Which revision is best?', '["Choose a model whose weekly growth gets smaller over time","Make the weekly growth larger so the line climbs faster than before","Remove the later weeks from the data","Keep the straight line, since it fit the first six weeks of data very well"]', 'Choose a model whose weekly growth gets smaller over time', NULL, 'The data show growth slowing, which a straight line cannot show. A revised model should let the weekly growth shrink.', 'checked', '{"lint":[],"solve":{"answer":"Choose a model whose weekly growth gets smaller over time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth slows, so use a model with decreasing growth rate.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('949f4b0c-8252-4656-b747-5a6622a6e46f', 'NC26.M1.RMM.1', 2, 'numeric', 'Revise a model', 'A model $C = 20 + 5h$ gives a charge in dollars for $h$ hours. The real charges are always 3 dollars higher than the model''s. What starting value (the constant) should the revised model have?', '[]', '23', '20+3', 'Adding 3 to every prediction raises the constant from 20 to 23, giving $C = 23 + 5h$.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"20 + 3 = 23; C = 23 + 5h.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('47246da1-5cee-44a5-83c2-49e6fd0962f6', 'NC26.M1.RMM.1', 2, 'numeric', 'Revise a model', 'A sales model $S = 100 + mt$ gives sales after $t$ months. A revised line must start at 100 when $t = 0$ and pass through the real sales of 260 at month 10. What should $m$ be?', '[]', '16', '(260-100)/10', 'The line must rise $260 - 100 = 160$ in 10 months, so $m = 160 \div 10 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(260 - 100)/10 = 16.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0d6d0e58-48a7-496d-9a7b-75169ea52785', 'NC26.M1.RMM.1', 2, 'numeric', 'Explain what a model''s parts mean', 'In the model $N = 250(1.06)^t$, $N$ is the number of members after $t$ years. By what percent does the membership grow each year?', '[]', '6', '6', 'The factor 1.06 means 100% of last year plus 6% more, so the membership grows 6% each year.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.06 -> 6% growth.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7637076-c2d4-4e3c-bca6-24cbcbe42ed3', 'NC26.M1.RMM.1', 2, 'numeric', 'Explain what a model''s parts mean', 'The model $h = -5t^2 + 30t$ gives the height in meters of a ball $t$ seconds after it is thrown. At what time $t$ above 0 does the ball return to the ground?', '[]', '6', '6', 'Set $h = 0$: $-5t(t - 6) = 0$, so $t = 0$ or $t = 6$. The ball lands at 6 seconds.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-5t^2 + 30t = 0 -> 5t(6 - t) = 0 -> t = 6.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9eac1c89-c241-4495-9429-f82006d9e69d', 'NC26.M1.RMM.1', 2, 'choice', 'Critique a model and its limits', 'A model predicts that a bacteria colony will cover the whole planet within 3 years. What best explains the problem?', '["Bacteria stop reproducing once the first day has passed, so growth ends","The colony shrinks whenever someone measures or counts it","Food and space limit the growth, which the model ignores","Population models must always be linear, never exponential"]', 'Food and space limit the growth, which the model ignores', NULL, 'Real colonies run out of food and space, so unlimited growth stops. A model that ignores these limits predicts impossible sizes.', 'checked', '{"lint":[],"solve":{"answer":"Food and space limit the growth, which the model ignores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Unlimited exponential growth ignores limits on food and space.","run_id":"claude-code","at":"2026-10-18T03:37:40.865Z"}}', 'ai', NULL, NULL)
