INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3943bfb7-6354-45e6-b8c7-607e2796a7b8', 'NC26.M1.ANFR.1', 1, 'choice', 'Square a binomial or multiply conjugates', 'Multiply: $(x + 4)(x - 4)$.', '["$x^{2} + 16$","$x^{2} - 8$","$x^{2} - 8x + 16$","$x^{2} - 16$"]', '$x^{2} - 16$', NULL, '$x \cdot x = x^{2}$; $x \cdot (-4) = -4x$; $4 \cdot x = 4x$; $4 \cdot (-4) = -16$. The $x$ terms cancel: $-4x + 4x = 0$. The product is $x^{2} - 16$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{2} - 16$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference of squares: x^2 - 4x + 4x - 16 = x^2 - 16.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9309b798-ae20-4ed5-a6ef-cd663f255e04', 'NC26.M1.ANFR.1', 1, 'numeric', 'Area model for a product', 'A rectangle has width $x + 1$ and length $x + 4$. It is cut into four smaller rectangles with areas $x^{2}$, $4x$, $x$ and $c$. What is $c$?', '[]', '4', '1*4', 'The small rectangle with sides 1 and 4 has area $1 \times 4 = 4$. So $c = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parts: x*x = x^2, x*4 = 4x, 1*x = x, 1*4 = 4. c = 4.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36c76f8e-f4e0-4e62-a136-8683d0c198bd', 'NC26.M1.ANFR.1', 1, 'choice', 'Area model for a product', 'An area model for $(x + 3)(x + 2)$ has four parts with areas $x^{2}$, $2x$, $3x$ and $6$. What is the total area?', '["$x^{2} + 6$","$x^{2} + 6x + 5$","$x^{2} + 5x + 6$","$5x + 6$"]', '$x^{2} + 5x + 6$', NULL, 'Add the four areas: $x^{2} + 2x + 3x + 6$. Combine the two $x$ parts: $2x + 3x = 5x$. The total area is $x^{2} + 5x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{2} + 5x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 + 2x + 3x + 6 = x^2 + 5x + 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
