INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b30a268b-1c75-404b-9f6e-9a20f1ebc3cd', 'NC26.M1.ANFR.1', 1, 'numeric', 'Rewrite an expression in an equivalent form', 'When $x^{2} + 3x + 5x$ is written with like terms combined, it is $x^{2} + bx$. What is $b$?', '[]', '8', '3+5', 'The terms $3x$ and $5x$ are like terms, so $3x + 5x = 8x$. The expression is $x^{2} + 8x$, so $b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 5x = 8x, so x^2 + 8x, b = 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c7d76992-1601-4a76-a463-e0c161000096', 'NC26.M1.ANFR.1', 1, 'choice', 'Rewrite an expression in an equivalent form', 'Which expression is equivalent to $4(x + 1) - 4$?', '["$4x + 8$","$4x + 4$","$4x - 3$","$4x$"]', '$4x$', NULL, 'Distribute the 4: $4(x + 1) = 4x + 4$. Then subtract 4: $4x + 4 - 4 = 4x$.', 'checked', '{"lint":[],"solve":{"answer":"$4x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x + 4 - 4 = 4x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c3106cd-e717-455b-882d-6ef6a1475f84', 'NC26.M1.ANFR.1', 1, 'numeric', 'Rewrite an expression in an equivalent form', 'The expression $5(x + 2) - 3x$ is equivalent to $2x + k$. What is $k$?', '[]', '10', '5*2', 'Distribute the 5: $5x + 10 - 3x$. Combine the $x$ terms: $5x - 3x = 2x$. So the expression is $2x + 10$ and $k = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 10 - 3x = 2x + 10, k = 10.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56688d7f-0094-4f48-b47a-2de6071305ec', 'NC26.M1.ANFR.1', 2, 'choice', 'Subtract polynomials, distributing the negative', 'Subtract: $(5x^2 + 3x - 4) - (2x^2 - x + 6)$.', '["$3x^2 + 2x + 2$","$7x^2 + 2x + 2$","$3x^2 + 4x - 10$","$3x^2 + 4x + 2$"]', '$3x^2 + 4x - 10$', NULL, 'Subtracting changes the sign of every term in the second polynomial: $5x^2 + 3x - 4 - 2x^2 + x - 6$. Combine like terms: $3x^2 + 4x - 10$.', 'checked', '{"lint":[],"solve":{"answer":"$3x^2 + 4x - 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x^2 - 2x^2 = 3x^2; 3x - (-x) = 4x; -4 - 6 = -10. Result 3x^2 + 4x - 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
