INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d73b262-0e31-4f50-9a3e-4c975e59a99f', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply two binomials', 'Multiply: $(x + 4)(x - 2)$.', '["$x^2 - 8$","$x^2 + 2x - 8$","$x^2 + 6x - 8$","$x^2 + 2x + 8$"]', '$x^2 + 2x - 8$', NULL, 'Multiply each term by each term: $x \cdot x + x(-2) + 4 \cdot x + 4(-2) = x^2 - 2x + 4x - 8 = x^2 + 2x - 8$.', 'checked', '{"lint":[],"solve":{"answer":"$x^2 + 2x - 8$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 2x + 4x - 8 = x^2 + 2x - 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d99576fa-d9db-472d-b132-27ad20435190', 'NC26.M1.ANFR.1', 2, 'numeric', 'Use an area model for a product', 'A rectangle has width $x + 2$ and length $x + 6$. Cutting it into four smaller rectangles gives areas $x^2$, $6x$, $2x$ and 12. The total area is $x^2 + bx + c$. What is $b$?', '[]', '8', '2+6', 'The four parts add to $x^2 + 6x + 2x + 12 = x^2 + 8x + 12$. So $b = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 2)(x + 6) = x^2 + 6x + 2x + 12 = x^2 + 8x + 12, matching the four pieces. b = 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbf232db-0d4f-47b0-af49-6a4de749be42', 'NC26.M1.ANFR.1', 2, 'numeric', 'Multiply powers with the same base', 'Find the value of $n$ that makes this statement true for every $a$: $a^{n} \cdot a^{7} = a^{12}$.', '[]', '5', '12-7', 'The exponents add when the bases are the same, so $n + 7 = 12$. Then $n = 12 - 7 = 5$. Check: $a^{5} \cdot a^{7} = a^{12}$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^n * a^7 = a^(n+7) = a^12 for every a, so n + 7 = 12, n = 5. (a = 0 also checks: 0 = 0.)","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f8d517e8-59ab-4393-a5f7-9c9e8bc240dd', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply powers with the same base', 'Simplify $(-2x^{3})(5x^{4})$.', '["$-10x^{12}$","$3x^{7}$","$-10x^{7}$","$10x^{7}$"]', '$-10x^{7}$', NULL, 'Multiply the coefficients: $-2 \times 5 = -10$. Add the exponents of $x$: $3 + 4 = 7$. The product is $-10x^{7}$.', 'checked', '{"lint":[],"solve":{"answer":"$-10x^{7}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Coefficients: (-2)(5) = -10. Powers: x^3 * x^4 = x^7. Product -10x^7.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d58f9c26-95c0-4346-8d5d-1857fee99834', 'NC26.M1.ANFR.1', 2, 'choice', 'Divide powers with the same base', 'Which expression is equal to $\frac{12a^{7}}{3a^{2}}$, for $a \neq 0$?', '["$4a^{5}$","$9a^{5}$","$4a^{9}$","$36a^{5}$"]', '$4a^{5}$', NULL, 'Divide the coefficients: $12 \div 3 = 4$. Subtract the exponents: $7 - 2 = 5$. The result is $4a^{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$4a^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12/3 = 4; a^(7-2) = a^5. Result 4a^5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c87df8a8-4f83-4388-afd4-86ab87d64af9', 'NC26.M1.ANFR.1', 2, 'numeric', 'Divide powers with the same base', 'Priya writes $\frac{3^{8}}{3^{5}}$ as a whole number. What number does she write?', '[]', '27', '3^(8-5)', 'Subtract the exponents: $\frac{3^{8}}{3^{5}} = 3^{8-5} = 3^{3}$. Then $3^{3} = 3 \times 3 \times 3 = 27$.', 'checked', '{"lint":[],"solve":{"answer":"27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^8 / 3^5 = 3^3 = 27.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fc7d9fb-439d-4311-8bed-d3d693be8240', 'NC26.M1.ANFR.1', 2, 'choice', 'Raise a power to a power', 'Which expression is equal to $(a^{-2})^{3}$, for $a \neq 0$?', '["$a^{6}$","$\\frac{1}{a^{6}}$","$a^{-5}$","$a$"]', '$\frac{1}{a^{6}}$', NULL, 'Multiply the exponents: $(-2) \times 3 = -6$, so the expression is $a^{-6}$. A negative exponent means a reciprocal, so $a^{-6} = \frac{1}{a^{6}}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{a^{6}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(a^-2)^3 = a^-6 = 1/a^6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9c80c22d-1bc7-412b-ba1c-61a13827c514', 'NC26.M1.ANFR.1', 2, 'numeric', 'Raise a power to a power', 'For what value of $m$ is $(y^{m})^{4}$ equal to $y^{20}$ for every nonzero $y$?', '[]', '5', '20/4', 'Multiply the exponents: $(y^{m})^{4} = y^{4m}$. This must equal $y^{20}$, so $4m = 20$ and $m = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(y^m)^4 = y^(4m) = y^20 for every nonzero y, so 4m = 20, m = 5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('013027b5-a920-4892-b9d9-aea9aa5a9756', 'NC26.M1.ANFR.1', 2, 'choice', 'Raise a product or quotient to a power', 'Simplify $(-2a^{3}b^{2})^{4}$.', '["$-8a^{12}b^{8}$","$16a^{7}b^{6}$","$16a^{12}b^{8}$","$-16a^{12}b^{8}$"]', '$16a^{12}b^{8}$', NULL, 'Raise each factor to the 4th power. $(-2)^{4} = 16$, because an even power of a negative number is positive. $(a^{3})^{4} = a^{12}$ and $(b^{2})^{4} = b^{8}$. The result is $16a^{12}b^{8}$.', 'checked', '{"lint":[],"solve":{"answer":"$16a^{12}b^{8}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2)^4 = 16; (a^3)^4 = a^12; (b^2)^4 = b^8. Result 16a^12b^8 (even power makes it positive).","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('eb90e63b-07f9-44bd-ba50-130ba47476a5', 'NC26.M1.ANFR.1', 2, 'numeric', 'Raise a product or quotient to a power', 'Write the value of $\left(\frac{2}{3}\right)^{3}$ as a fraction.', '[]', '8/27', '(2/3)^3', 'A power of a quotient is the quotient of the powers: $\left(\frac{2}{3}\right)^{3} = \frac{2^{3}}{3^{3}} = \frac{8}{27}$.', 'checked', '{"lint":[],"solve":{"answer":"8/27","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)^3 = 2^3/3^3 = 8/27.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b1760434-8564-4b21-a3c4-97d1ec48d5ed', 'NC26.M1.ANFR.1', 2, 'choice', 'Zero and negative exponents', 'Which expression is equal to $\frac{3}{x^{4}}$, for $x \neq 0$?', '["$(3x)^{-4}$","$3x^{4}$","$-3x^{4}$","$3x^{-4}$"]', '$3x^{-4}$', NULL, '$\frac{1}{x^{4}} = x^{-4}$, so $\frac{3}{x^{4}} = 3 \cdot x^{-4} = 3x^{-4}$. The 3 is not part of the power: in $(3x)^{-4}$ the 3 would be raised to the power too.', 'checked', '{"lint":[],"solve":{"answer":"$3x^{-4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3/x^4 = 3 * x^-4 = 3x^-4. (3x)^-4 = 1/(81x^4), not equal.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ed9651a-b9b0-48e3-b9b0-fccfb7c102b1', 'NC26.M1.ANFR.1', 2, 'numeric', 'Zero and negative exponents', 'What is the value of $\left(\frac{1}{2}\right)^{-3}$?', '[]', '8', '2^3', 'A negative exponent flips the fraction: $\left(\frac{1}{2}\right)^{-3} = \left(\frac{2}{1}\right)^{3} = 2^{3} = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^-3 = 2^3 = 8.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9eda06b-6612-4337-8bce-74ddab17f929', 'NC26.M1.ANFR.1', 2, 'choice', 'Combine several exponent properties', 'Which statement is true for every nonzero $x$?', '["$x^{2} \\cdot x^{4} = x^{8}$","$(x^{-2})^{-3} = x^{6}$","$(x^{2})^{4} = x^{6}$","$\\frac{x^{8}}{x^{2}} = x^{4}$"]', '$(x^{-2})^{-3} = x^{6}$', NULL, '$(x^{-2})^{-3} = x^{(-2)(-3)} = x^{6}$, which is true. The others are false: $x^{2} \cdot x^{4} = x^{6}$, $(x^{2})^{4} = x^{8}$ and $\frac{x^{8}}{x^{2}} = x^{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$(x^{-2})^{-3} = x^{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^8/x^2 = x^6 (not x^4); (x^2)^4 = x^8 (not x^6); (x^-2)^-3 = x^6 TRUE; x^2*x^4 = x^6 (not x^8). Only the third is true.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99c3be01-9e47-47d8-a7ba-1f95b0b10b32', 'NC26.M1.ANFR.1', 2, 'numeric', 'Combine several exponent properties', 'What is the value of $\frac{(3^{2})^{3}}{3^{4}}$?', '[]', '9', '3^(2*3-4)', 'First $(3^{2})^{3} = 3^{6}$. Then $\frac{3^{6}}{3^{4}} = 3^{6-4} = 3^{2} = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3^2)^3 = 3^6; 3^6/3^4 = 3^2 = 9.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fd85fab4-7078-437e-856e-f80ec31b7845', 'NC26.M1.ANFR.1', 2, 'choice', 'Compare polynomial and integer operations', 'Polynomials and integers are alike in some ways and different in others. Which statement about dividing one polynomial by another is correct?', '["The quotient is always a polynomial, just as the quotient of two integers is always an integer","The quotient is always a polynomial, even though the quotient of two integers is not always an integer","The quotient is not always a polynomial, just as the quotient of two integers is not always an integer","The quotient is never a polynomial, but the quotient of two integers is always an integer"]', 'The quotient is not always a polynomial, just as the quotient of two integers is not always an integer', NULL, 'Integers are closed under adding, subtracting and multiplying, but not dividing: $1 \div 2$ is not an integer. Polynomials behave the same way: $1 \div x$ is not a polynomial. So division does not always give a polynomial.', 'checked', '{"lint":[],"solve":{"answer":"The quotient is not always a polynomial, just as the quotient of two integers is not always an integer","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Neither polynomials nor integers are closed under division: e.g. 1/x is not a polynomial and 1/2 is not an integer. So the first option.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad39d60c-ac4d-47f8-8384-72561f7948d1', 'NC26.M1.ANFR.1', 2, 'numeric', 'Compare polynomial and integer operations', 'Let $x = 10$. Then $(x+2)(x+3)$ matches the product $12 \times 13$. Multiplying the polynomials gives $x^{2} + 5x + 6$. What is the value of $x^{2} + 5x + 6$ when $x = 10$?', '[]', '156', '100+50+6', 'With $x = 10$: $x^{2} + 5x + 6 = 100 + 50 + 6 = 156$. This agrees with $12 \times 13 = 156$, which shows that multiplying polynomials follows the same pattern as multiplying whole numbers.', 'checked', '{"lint":[],"solve":{"answer":"156","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10^2 + 5(10) + 6 = 100 + 50 + 6 = 156. Check 12 x 13 = 156.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb2ff9bc-d688-4a4b-8eaf-eebe2c44535f', 'NC26.M1.ANFR.1', 2, 'choice', 'Compare polynomial and integer operations', 'Which operation on two polynomials can give a result that is not a polynomial?', '["Addition","Subtraction","Multiplication","Division"]', 'Division', NULL, 'The sum, difference and product of two polynomials are always polynomials. A quotient is not always one: $1 \div x$ is not a polynomial.', 'checked', '{"lint":[],"solve":{"answer":"Division","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Addition, subtraction and multiplication of polynomials always give polynomials; division can give e.g. x/x^2 = 1/x, not a polynomial.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f6cd27f-a7e3-40f8-ad32-b5d4d73d1058', 'NC26.M1.ANFR.1', 2, 'choice', 'Add polynomials', 'Add: $(3x^{2} - 4x + 7) + (-5x^{2} + 6x - 2)$.', '["$8x^{2} + 2x + 5$","$-2x^{2} - 10x + 5$","$-2x^{2} + 2x + 9$","$-2x^{2} + 2x + 5$"]', '$-2x^{2} + 2x + 5$', NULL, 'Add like terms: $3x^{2} + (-5x^{2}) = -2x^{2}$; $-4x + 6x = 2x$; $7 + (-2) = 5$. The sum is $-2x^{2} + 2x + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$-2x^{2} + 2x + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2: 3 - 5 = -2; x: -4 + 6 = 2; constants: 7 - 2 = 5. Result -2x^2 + 2x + 5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6d0e060-07f1-4fd2-bfc6-509b107e68f0', 'NC26.M1.ANFR.1', 2, 'numeric', 'Add polynomials', 'The sum $(4x^{2} + 3x - 8) + (x^{2} - 9x + 5)$ is written as $ax^{2} + bx + c$. What is $a + b + c$?', '[]', '-4', '(4+1)+(3-9)+(-8+5)', 'Add like terms: $4x^{2} + x^{2} = 5x^{2}$; $3x - 9x = -6x$; $-8 + 5 = -3$. So $a = 5$, $b = -6$ and $c = -3$, and $a + b + c = 5 - 6 - 3 = -4$.', 'checked', '{"lint":[],"solve":{"answer":"-4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = 4 + 1 = 5; b = 3 - 9 = -6; c = -8 + 5 = -3. a + b + c = 5 - 6 - 3 = -4.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('464d079c-40da-45aa-a1ce-39e4c7aba58b', 'NC26.M1.ANFR.1', 2, 'choice', 'Subtract polynomials', 'Subtract: $(4x^{2} - 7x + 2) - (6x^{2} + 3x - 5)$.', '["$-2x^{2} - 10x + 7$","$-2x^{2} - 10x - 3$","$-2x^{2} - 4x - 3$","$10x^{2} - 10x + 7$"]', '$-2x^{2} - 10x + 7$', NULL, 'Distribute the minus sign to every term of the second polynomial: $4x^{2} - 7x + 2 - 6x^{2} - 3x + 5$. Combine like terms: $4x^{2} - 6x^{2} = -2x^{2}$; $-7x - 3x = -10x$; $2 + 5 = 7$. The result is $-2x^{2} - 10x + 7$.', 'checked', '{"lint":[],"solve":{"answer":"$-2x^{2} - 10x + 7$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x^2 - 7x + 2 - 6x^2 - 3x + 5 = -2x^2 - 10x + 7.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8f4c04b-2d04-4142-b85f-9666c4ee0194', 'NC26.M1.ANFR.1', 2, 'numeric', 'Subtract polynomials', 'Subtract $(3x^{2} + 2x - 9)$ from $(8x^{2} - x + 4)$. The result is $ax^{2} + bx + c$. What is $c$?', '[]', '13', '4+9', 'Subtracting from means: $(8x^{2} - x + 4) - (3x^{2} + 2x - 9) = 5x^{2} - 3x + 13$. The constant is $4 - (-9) = 13$, so $c = 13$.', 'checked', '{"lint":[],"solve":{"answer":"13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(8x^2 - x + 4) - (3x^2 + 2x - 9) = 5x^2 - 3x + 13, c = 13.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('13c6fd86-287d-4e36-aaf7-c52e4a2e2163', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply a monomial by a polynomial', 'Multiply: $-2x(3x^{2} - 4x + 5)$.', '["$-6x^{3} - 8x^{2} - 10x$","$-6x^{3} + 8x^{2} - 10x$","$-6x^{2} + 8x - 10$","$-6x^{3} + 8x^{2} - 10$"]', '$-6x^{3} + 8x^{2} - 10x$', NULL, 'Multiply $-2x$ by each term: $-2x \cdot 3x^{2} = -6x^{3}$; $-2x \cdot (-4x) = 8x^{2}$; $-2x \cdot 5 = -10x$. The result is $-6x^{3} + 8x^{2} - 10x$.', 'checked', '{"lint":[],"solve":{"answer":"$-6x^{3} + 8x^{2} - 10x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x*3x^2 = -6x^3; -2x*(-4x) = 8x^2; -2x*5 = -10x. Result -6x^3 + 8x^2 - 10x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e95877cc-5970-4054-b02c-6c77bc0a32b8', 'NC26.M1.ANFR.1', 2, 'numeric', 'Multiply a monomial by a polynomial', 'When $3x(2x^{2} + x - 4)$ is expanded, what is the coefficient of the $x$ term?', '[]', '-12', '3*(-4)', 'Multiply $3x$ by each term: $3x \cdot 2x^{2} = 6x^{3}$; $3x \cdot x = 3x^{2}$; $3x \cdot (-4) = -12x$. The $x$ term is $-12x$, so its coefficient is $-12$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x(2x^2 + x - 4) = 6x^3 + 3x^2 - 12x; x coefficient -12.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c152f60e-f0c0-48ea-b4c8-320a158739f6', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply two binomials', 'Multiply: $(2x - 3)(x + 5)$.', '["$2x^{2} - 15$","$2x^{2} + 7x - 15$","$2x^{2} + 13x - 15$","$2x^{2} + 7x + 15$"]', '$2x^{2} + 7x - 15$', NULL, '$2x \cdot x = 2x^{2}$; $2x \cdot 5 = 10x$; $-3 \cdot x = -3x$; $-3 \cdot 5 = -15$. Combine: $10x - 3x = 7x$. The product is $2x^{2} + 7x - 15$.', 'checked', '{"lint":[],"solve":{"answer":"$2x^{2} + 7x - 15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^2 + 10x - 3x - 15 = 2x^2 + 7x - 15.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af10ac60-22ef-4178-82f4-96baca7d3ef6', 'NC26.M1.ANFR.1', 2, 'numeric', 'Multiply two binomials', 'What is the coefficient of $x$ in the product $(3x - 2)(2x - 5)$?', '[]', '-19', '3*(-5)+(-2)*2', 'The $x$ terms come from $3x \cdot (-5) = -15x$ and $-2 \cdot 2x = -4x$. Together they make $-19x$, so the coefficient is $-19$. (The full product is $6x^{2} - 19x + 10$.)', 'checked', '{"lint":[],"solve":{"answer":"-19","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x^2 - 15x - 4x + 10 = 6x^2 - 19x + 10; coefficient of x is -19.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('53c9dc8c-35da-473d-8ef5-a4a30f172d5a', 'NC26.M1.ANFR.1', 2, 'choice', 'Square a binomial or multiply conjugates', 'Expand: $(x + 5)^{2}$.', '["$x^{2} + 25$","$x^{2} + 10x$","$x^{2} + 10x + 25$","$x^{2} + 5x + 25$"]', '$x^{2} + 10x + 25$', NULL, '$(x + 5)^{2} = (x + 5)(x + 5)$. Then $x \cdot x = x^{2}$, $x \cdot 5 + 5 \cdot x = 10x$ and $5 \cdot 5 = 25$. The result is $x^{2} + 10x + 25$. The middle term is easy to forget.', 'checked', '{"lint":[],"solve":{"answer":"$x^{2} + 10x + 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 5)(x + 5) = x^2 + 5x + 5x + 25 = x^2 + 10x + 25.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9989b7bd-8555-4bee-a612-7e3655ae9b52', 'NC26.M1.ANFR.1', 2, 'numeric', 'Square a binomial or multiply conjugates', 'When $(3x - 2)^{2}$ is expanded as $ax^{2} + bx + c$, what is $b$?', '[]', '-12', '2*3*(-2)', '$(3x - 2)^{2} = (3x - 2)(3x - 2) = 9x^{2} - 6x - 6x + 4 = 9x^{2} - 12x + 4$. So $b = -12$.', 'checked', '{"lint":[],"solve":{"answer":"-12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3x - 2)^2 = 9x^2 - 6x - 6x + 4 = 9x^2 - 12x + 4, b = -12.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2affa04e-cec5-4796-93e1-eaa4fab6f75c', 'NC26.M1.ANFR.1', 2, 'choice', 'Multiply a binomial by a trinomial, or three factors', 'Multiply: $(x + 2)(x^{2} - 3x + 1)$.', '["$x^{3} - x^{2} - 5x + 2$","$x^{3} - 5x^{2} - 5x + 2$","$x^{3} - x^{2} - 5x - 2$","$x^{3} - x^{2} - 6x + 2$"]', '$x^{3} - x^{2} - 5x + 2$', NULL, 'Multiply every term of the trinomial by $x$: $x^{3} - 3x^{2} + x$. Then by 2: $2x^{2} - 6x + 2$. Add and combine like terms: $x^{3} + (-3x^{2} + 2x^{2}) + (x - 6x) + 2 = x^{3} - x^{2} - 5x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{3} - x^{2} - 5x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x(x^2 - 3x + 1) = x^3 - 3x^2 + x; 2(x^2 - 3x + 1) = 2x^2 - 6x + 2. Sum x^3 - x^2 - 5x + 2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6b483bb-af08-460a-90ee-a82393a0c2c2', 'NC26.M1.ANFR.1', 2, 'choice', 'Area model for a product', 'An area model for $(2x + 3)(x + 4)$ has four parts. Which list gives the four areas?', '["$2x^{2}$, $4x$, $3x$, $12$","$2x^{2}$, $8x$, $3x$, $12$","$2x^{2}$, $8x$, $3x$, $7$","$2x$, $8x$, $3x$, $12$"]', '$2x^{2}$, $8x$, $3x$, $12$', NULL, 'Multiply each side of the first factor by each side of the second: $2x \cdot x = 2x^{2}$; $2x \cdot 4 = 8x$; $3 \cdot x = 3x$; $3 \cdot 4 = 12$. The areas are $2x^{2}$, $8x$, $3x$ and $12$.', 'checked', '{"lint":[],"solve":{"answer":"$2x^{2}$, $8x$, $3x$, $12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x*x = 2x^2, 2x*4 = 8x, 3*x = 3x, 3*4 = 12.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b78c98fb-f7cf-4aad-8f7d-0e2a958444d2', 'NC26.M1.ANFR.1', 2, 'numeric', 'Area model for a product', 'A rectangle is $2x + 1$ units long and $x + 3$ units wide. An area model gives its area as $2x^{2} + 7x + 3$ square units. How many square units is the area when $x = 4$?', '[]', '63', '2*16+7*4+3', 'Put $x = 4$ into the area: $2(16) + 7(4) + 3 = 32 + 28 + 3 = 63$. Check: the sides are $9$ and $7$, and $9 \times 7 = 63$.', 'checked', '{"lint":[],"solve":{"answer":"63","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(16) + 7(4) + 3 = 32 + 28 + 3 = 63. Check (2*4 + 1)(4 + 3) = 9*7 = 63.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8ba86db9-b15f-4e9e-a2f0-671b23119272', 'NC26.M1.ANFR.1', 2, 'choice', 'Rewrite an expression in an equivalent form', 'Which expression is equivalent to $3(x + 2) + 2x$?', '["$5x + 2$","$5x^{2} + 6$","$5x + 6$","$3x + 8$"]', '$5x + 6$', NULL, 'Distribute the 3: $3x + 6 + 2x$. Combine the $x$ terms: $3x + 2x = 5x$. The expression is $5x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$5x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 6 + 2x = 5x + 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37e8fc10-df1e-447a-ac09-8e0a31d7aea2', 'NC26.M1.ANFR.1', 2, 'choice', 'Rewrite an expression in an equivalent form', 'The expressions $(x + 4)^{2}$ and $x^{2} + 16$ are not equivalent, but they give the same result for one of the values of $x$ below. Which value is it?', '["-4","0","1","2"]', '0', '0', 'Try each value. At $x = 0$ both give 16. At $x = -4$ they give 0 and 32. At $x = 1$ they give 25 and 17. At $x = 2$ they give 36 and 20. The expressions differ in general because $(x + 4)^{2} = x^{2} + 8x + 16$, which has an extra $8x$ that is zero only at $x = 0$.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 4)^2 = x^2 + 8x + 16; equal to x^2 + 16 only when 8x = 0, x = 0. Check: x=1: 25 vs 17; x=2: 36 vs 20; x=-4: 0 vs 32.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1a0afe8-218a-4dda-8fe8-8f420ebf731c', 'NC26.M1.ANFR.1', 3, 'choice', 'Divide powers with negative exponents', 'Simplify $\frac{x^5 y^{-2}}{x^2 y^{-6}}$, where $x$ and $y$ are not zero.', '["$x^3 y^{-4}$","$x^3 y^{-8}$","$x^7 y^4$","$x^3 y^4$"]', '$x^3 y^4$', NULL, 'When you divide powers with the same base, subtract the exponents. For $x$: $5 - 2 = 3$. For $y$: $-2 - (-6) = -2 + 6 = 4$. The result is $x^3 y^4$.', 'checked', '{"lint":[],"solve":{"answer":"$x^3 y^4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^(5-2) = x^3; y^(-2 - (-6)) = y^4. Result x^3 y^4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43e8ed3b-cde0-426c-be8d-6776d34b4605', 'NC26.M1.ANFR.1', 3, 'numeric', 'Find a coefficient after multiplying binomials', 'When $(2x - 1)(x + 4)$ is written in the form $ax^2 + bx + c$, what is $b$?', '[]', '7', '2*4-1*1', '$(2x - 1)(x + 4) = 2x^2 + 8x - x - 4 = 2x^2 + 7x - 4$. The middle terms $8x$ and $-x$ combine to $7x$, so $b = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x - 1)(x + 4) = 2x^2 + 8x - x - 4 = 2x^2 + 7x - 4. b = 7.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('598e6fdb-fd4e-44b5-8f4e-b1dbcc027614', 'NC26.M1.ANFR.1', 3, 'choice', 'Raise a product to a power', 'Simplify $(3x^2 y)^3$.', '["$27x^5y^3$","$27x^6y^3$","$3x^6y^3$","$9x^6y^3$"]', '$27x^6y^3$', NULL, 'Cube every factor: $3^3 = 27$, $(x^2)^3 = x^6$ (multiply exponents) and $y^3$. The result is $27x^6y^3$.', 'checked', '{"lint":[],"solve":{"answer":"$27x^6y^3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^3 = 27, (x^2)^3 = x^6, y^3. Result 27x^6y^3.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc05cbaa-b852-4059-8b6d-907533efc07c', 'NC26.M1.ANFR.1', 3, 'choice', 'Multiply powers with the same base', 'Simplify $(2a^{-2}b^{3})(6a^{5}b^{-1})$, where $a$ and $b$ are not zero.', '["$12a^{7}b^{4}$","$8a^{3}b^{2}$","$12a^{3}b^{2}$","$12a^{-7}b^{2}$"]', '$12a^{3}b^{2}$', NULL, 'Multiply the coefficients: $2 \times 6 = 12$. For $a$, add the exponents: $-2 + 5 = 3$. For $b$, add the exponents: $3 + (-1) = 2$. The product is $12a^{3}b^{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$12a^{3}b^{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2*6 = 12; a^(-2+5) = a^3; b^(3-1) = b^2. Result 12a^3b^2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c03f3fe6-6614-4591-9871-d00668dbc870', 'NC26.M1.ANFR.1', 3, 'numeric', 'Multiply powers with the same base', 'Solve for $n$: $5^{n} \cdot 5^{-2} \cdot 5^{4} = 5^{9}$.', '[]', '7', '9+2-4', 'Add the exponents on the left: $n + (-2) + 4 = n + 2$. This must equal 9, so $n = 9 - 2 = 7$. Check: $5^{7} \cdot 5^{-2} \cdot 5^{4} = 5^{9}$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n + (-2) + 4 = 9, so n + 2 = 9, n = 7.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae6a0ade-8ebc-4009-889e-308d52b4e8cd', 'NC26.M1.ANFR.1', 3, 'numeric', 'Divide powers with the same base', 'What is the value of $\frac{2^{3} \cdot 2^{-5}}{2^{-6}}$?', '[]', '16', '2^(3-5+6)', 'In the top, add the exponents: $3 + (-5) = -2$, so the top is $2^{-2}$. Now divide by $2^{-6}$ by subtracting: $-2 - (-6) = 4$. The value is $2^{4} = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Numerator 2^(3-5) = 2^-2. Divide by 2^-6: 2^(-2-(-6)) = 2^4 = 16.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7040cce6-efdd-4a22-a440-54c270a2f3a3', 'NC26.M1.ANFR.1', 3, 'choice', 'Divide powers with the same base', 'Simplify $\frac{18p^{4}q^{3}}{6p^{9}q}$ so that every exponent is positive. Assume $p$ and $q$ are not zero.', '["$\\frac{3p^{5}}{q^{2}}$","$3p^{5}q^{2}$","$\\frac{12q^{2}}{p^{5}}$","$\\frac{3q^{2}}{p^{5}}$"]', '$\frac{3q^{2}}{p^{5}}$', NULL, 'Divide the coefficients: $18 \div 6 = 3$. For $p$: $4 - 9 = -5$, so $p^{-5} = \frac{1}{p^{5}}$. For $q$: $3 - 1 = 2$. The result is $\frac{3q^{2}}{p^{5}}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{3q^{2}}{p^{5}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"18/6 = 3; p^(4-9) = p^-5 = 1/p^5; q^(3-1) = q^2. Result 3q^2/p^5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67bec30f-f4c2-41b2-8f8c-914f545e4a73', 'NC26.M1.ANFR.1', 3, 'choice', 'Raise a power to a power', 'Which expression is equal to $\left(\left(x^{2}\right)^{3}\right)^{2}$, for $x \neq 0$?', '["$x^{12}$","$x^{7}$","$x^{8}$","$x^{10}$"]', '$x^{12}$', NULL, 'Work from the inside. $(x^{2})^{3} = x^{2 \times 3} = x^{6}$. Then $(x^{6})^{2} = x^{6 \times 2} = x^{12}$. Altogether the exponents multiply: $2 \times 3 \times 2 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"((x^2)^3)^2 = x^(2*3*2) = x^12.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b6d19267-7eec-4682-89b3-35cbd4dc3f3d', 'NC26.M1.ANFR.1', 3, 'numeric', 'Raise a power to a power', 'A number is written as $\left(3^{-2}\right)^{-2}$. What is its value?', '[]', '81', '3^4', 'Multiply the exponents: $(-2) \times (-2) = 4$. So the number is $3^{4} = 3 \times 3 \times 3 \times 3 = 81$.', 'checked', '{"lint":[],"solve":{"answer":"81","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3^-2)^-2 = 3^((-2)(-2)) = 3^4 = 81.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcde4de4-83fc-4199-bb6d-362a926a36f6', 'NC26.M1.ANFR.1', 3, 'choice', 'Raise a product or quotient to a power', 'Simplify $\left(\frac{2x^{2}}{y^{3}}\right)^{-2}$, where $x$ and $y$ are not zero.', '["$\\frac{4x^{4}}{y^{6}}$","$\\frac{y^{6}}{4x^{4}}$","$\\frac{y^{6}}{2x^{4}}$","$\\frac{y^{6}}{4x^{2}}$"]', '$\frac{y^{6}}{4x^{4}}$', NULL, 'The exponent $-2$ flips the fraction and squares it: $\left(\frac{2x^{2}}{y^{3}}\right)^{-2} = \left(\frac{y^{3}}{2x^{2}}\right)^{2} = \frac{y^{6}}{4x^{4}}$. The 2 is squared to 4, and $(x^{2})^{2} = x^{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{y^{6}}{4x^{4}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Negative exponent flips: (2x^2/y^3)^-2 = (y^3/(2x^2))^2 = y^6/(4x^4).","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('59573b70-72ae-4910-8c85-58c88b4703aa', 'NC26.M1.ANFR.1', 3, 'numeric', 'Raise a product or quotient to a power', 'Find $k$ so that $(2x^{k})^{3}$ equals $8x^{15}$ for every $x$.', '[]', '5', '15/3', 'Cube each factor: $(2x^{k})^{3} = 2^{3}x^{3k} = 8x^{3k}$. The 8 already matches. Then $3k = 15$, so $k = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x^k)^3 = 8x^(3k) = 8x^15 for every x, so 3k = 15, k = 5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e197a70-af16-4737-8780-ef4ae2743649', 'NC26.M1.ANFR.1', 3, 'choice', 'Zero and negative exponents', 'Which expression is equal to $\frac{x^{-2}y^{3}}{z^{-4}}$ with only positive exponents? Assume $x$, $y$ and $z$ are not zero.', '["$\\frac{x^{2}y^{3}}{z^{4}}$","$x^{2}y^{3}z^{4}$","$\\frac{y^{3}z^{4}}{x^{2}}$","$\\frac{y^{3}}{x^{2}z^{4}}$"]', '$\frac{y^{3}z^{4}}{x^{2}}$', NULL, 'A factor with a negative exponent moves across the fraction bar and its exponent becomes positive. $x^{-2}$ in the top goes to the bottom as $x^{2}$. $z^{-4}$ in the bottom goes to the top as $z^{4}$. The result is $\frac{y^{3}z^{4}}{x^{2}}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{y^{3}z^{4}}{x^{2}}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^-2 moves to the denominator as x^2; z^-4 in the denominator moves to the numerator as z^4. Result y^3 z^4 / x^2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('360236da-a467-46dc-be9a-84831662f4f5', 'NC26.M1.ANFR.1', 3, 'numeric', 'Zero and negative exponents', 'Find the sum $2^{-2} + 2^{-1} + 2^{0}$. Give the sum as a fraction.', '[]', '7/4', '1/4+1/2+1', '$2^{-2} = \frac{1}{4}$, $2^{-1} = \frac{1}{2}$ and $2^{0} = 1$. The sum is $\frac{1}{4} + \frac{2}{4} + \frac{4}{4} = \frac{7}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"7/4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^-2 + 2^-1 + 2^0 = 1/4 + 1/2 + 1 = 1/4 + 2/4 + 4/4 = 7/4.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3567095f-8867-45a0-8563-afb078bd7fad', 'NC26.M1.ANFR.1', 3, 'choice', 'Combine several exponent properties', 'Simplify $\frac{(2a^{2}b)^{3}}{4a^{5}b^{-2}}$, where $a$ and $b$ are not zero.', '["$2ab^{5}$","$2ab$","$4ab^{5}$","$2a^{11}b^{5}$"]', '$2ab^{5}$', NULL, 'Cube the top: $(2a^{2}b)^{3} = 8a^{6}b^{3}$. Divide the coefficients: $8 \div 4 = 2$. Subtract the exponents: $a^{6-5} = a$ and $b^{3-(-2)} = b^{5}$. The result is $2ab^{5}$.', 'checked', '{"lint":[],"solve":{"answer":"$2ab^{5}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2a^2b)^3 = 8a^6b^3. Divide by 4a^5b^-2: 8/4 = 2, a^(6-5) = a, b^(3-(-2)) = b^5. Result 2ab^5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99c3d30a-b7df-4f51-8f0e-8384350e1a22', 'NC26.M1.ANFR.1', 3, 'numeric', 'Combine several exponent properties', 'What is the value of $\frac{2^{-3} \cdot 4^{2}}{2^{-1}}$?', '[]', '4', '(1/8*16)/(1/2)', 'Write $4^{2}$ as $(2^{2})^{2} = 2^{4}$. The top is $2^{-3} \cdot 2^{4} = 2^{1}$. Dividing by $2^{-1}$ gives $2^{1-(-1)} = 2^{2} = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4^2 = 2^4. Numerator 2^(-3+4) = 2^1. Divide by 2^-1: 2^(1+1) = 4. Check: (1/8)(16) = 2; 2 / (1/2) = 4.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03ef80c7-1c1e-4e07-b2d1-2322bd2ccd20', 'NC26.M1.ANFR.1', 3, 'numeric', 'Combine several exponent properties', 'Find $n$ so that $\frac{x^{n} \cdot x^{-3}}{x^{2}} = x^{4}$ for every nonzero $x$.', '[]', '9', '4+2+3', 'The exponent on the left is $n + (-3) - 2 = n - 5$. Set it equal to 4: $n - 5 = 4$, so $n = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^(n-3-2) = x^4, so n - 5 = 4, n = 9.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c647385-740e-40d1-9ac7-f78b03e882d0', 'NC26.M1.ANFR.1', 3, 'choice', 'Compare polynomial and integer operations', 'Two polynomials each have degree 3. Which statement about their sum must be true?', '["The sum has degree exactly 3","The sum has degree at most 3","The sum has degree exactly 6","The sum has degree at least 3"]', 'The sum has degree at most 3', NULL, 'Adding never creates a higher power, so the degree cannot be more than 3. It can be less: $(x^{3} + 2) + (-x^{3} + 5) = 7$ has no $x$ at all. So the degree is at most 3, but not always exactly 3.', 'checked', '{"lint":[],"solve":{"answer":"The sum has degree at most 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adding cannot create a term above x^3, but the x^3 terms can cancel (x^3 + 1) + (-x^3 + x) = x + 1, degree 1. So degree at most 3; not exactly 3, not 6, not at least 3.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2a05761-4f6c-4a24-8e42-3ae17647e3aa', 'NC26.M1.ANFR.1', 3, 'numeric', 'Compare polynomial and integer operations', 'The sum $347 + 285$ can be written, with $x = 10$, as $(3x^{2} + 4x + 7) + (2x^{2} + 8x + 5)$. When the polynomials are added, the sum is $5x^{2} + bx + c$. What is $b + c$?', '[]', '24', '(4+8)+(7+5)', 'Add like terms: $3x^{2} + 2x^{2} = 5x^{2}$, $4x + 8x = 12x$ and $7 + 5 = 12$. So $b = 12$ and $c = 12$, and $b + c = 24$. Check with $x = 10$: $500 + 120 + 12 = 632 = 347 + 285$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add like terms: (3+2)x^2 + (4+8)x + (7+5) = 5x^2 + 12x + 12. b + c = 12 + 12 = 24. (Check at x = 10: 500 + 120 + 12 = 632 = 347 + 285.)","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c6683eb6-1089-4971-8b81-6f15dd9d1eb6', 'NC26.M1.ANFR.1', 3, 'choice', 'Add polynomials', 'Add: $(3a^{2}b - 2ab + 5) + (a^{2}b + 6ab^{2} - 7)$.', '["$4a^{2}b + 4ab^{2} - 2$","$4a^{2}b - 2ab + 6ab^{2} + 12$","$4a^{2}b - 2ab + 6ab^{2} - 2$","$3a^{2}b - 2ab + 6ab^{2} - 2$"]', '$4a^{2}b - 2ab + 6ab^{2} - 2$', NULL, 'Only terms with exactly the same letters and powers combine. $3a^{2}b + a^{2}b = 4a^{2}b$. The terms $-2ab$ and $6ab^{2}$ have no partner, so they stay as they are. The constants give $5 + (-7) = -2$. The sum is $4a^{2}b - 2ab + 6ab^{2} - 2$.', 'checked', '{"lint":[],"solve":{"answer":"$4a^{2}b - 2ab + 6ab^{2} - 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2b: 3 + 1 = 4; ab: -2 (no partner); ab^2: +6 (no partner, unlike ab); constants 5 - 7 = -2. Result 4a^2b - 2ab + 6ab^2 - 2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c12bb75-df3d-4303-abc1-baa3db12719b', 'NC26.M1.ANFR.1', 3, 'numeric', 'Add polynomials', 'The sum of $(5x^{2} + kx - 3)$ and $(2x^{2} - 4x + 9)$ is $7x^{2} + 3x + 6$. What is $k$?', '[]', '7', '3+4', 'Adding the $x$ terms gives $kx + (-4x) = (k - 4)x$. This must equal $3x$, so $k - 4 = 3$ and $k = 7$. The other terms check: $5x^{2} + 2x^{2} = 7x^{2}$ and $-3 + 9 = 6$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x terms: kx - 4x = 3x, so k - 4 = 3, k = 7. (x^2: 7 ok; constants: 6 ok.)","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a50547c0-7293-420a-9808-80a5520522c4', 'NC26.M1.ANFR.1', 3, 'choice', 'Subtract polynomials', 'Which expression is equal to $(2a^{2}b - 3ab + 4) - (5a^{2}b - 7ab - 1)$?', '["$-3a^{2}b - 10ab + 3$","$-3a^{2}b + 4ab + 3$","$3a^{2}b + 4ab + 5$","$-3a^{2}b + 4ab + 5$"]', '$-3a^{2}b + 4ab + 5$', NULL, 'Distribute the minus: $2a^{2}b - 3ab + 4 - 5a^{2}b + 7ab + 1$. Combine like terms: $2a^{2}b - 5a^{2}b = -3a^{2}b$; $-3ab + 7ab = 4ab$; $4 + 1 = 5$. The result is $-3a^{2}b + 4ab + 5$.', 'checked', '{"lint":[],"solve":{"answer":"$-3a^{2}b + 4ab + 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a^2b: 2 - 5 = -3; ab: -3 + 7 = 4; constants: 4 + 1 = 5. Result -3a^2b + 4ab + 5.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ecb4fae-1de4-4f58-a273-85e69a19408b', 'NC26.M1.ANFR.1', 3, 'numeric', 'Subtract polynomials', 'When $(7x^{2} + 5x + k)$ is subtracted from $(10x^{2} + 2x - 3)$, the result is $3x^{2} - 3x + 6$. What is $k$?', '[]', '-9', '-3-6', 'The constant terms give $-3 - k = 6$, so $k = -3 - 6 = -9$. Check the rest: $10x^{2} - 7x^{2} = 3x^{2}$ and $2x - 5x = -3x$. With $k = -9$ the constant is $-3 - (-9) = 6$.', 'checked', '{"lint":[],"solve":{"answer":"-9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(10x^2 + 2x - 3) - (7x^2 + 5x + k) = 3x^2 - 3x + (-3 - k). Set -3 - k = 6, k = -9.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c93ad60a-e5ad-4f4d-bbdc-77d347040b54', 'NC26.M1.ANFR.1', 3, 'choice', 'Multiply a monomial by a polynomial', 'Simplify: $2x(x^{2} - 3) - x(x^{2} + 4x)$.', '["$x^{3} - 4x^{2} - 6x$","$x^{3} + 4x^{2} - 6x$","$3x^{3} - 4x^{2} - 6x$","$x^{3} - 4x^{2} - 2x$"]', '$x^{3} - 4x^{2} - 6x$', NULL, 'Expand each part: $2x(x^{2} - 3) = 2x^{3} - 6x$ and $x(x^{2} + 4x) = x^{3} + 4x^{2}$. Subtract: $2x^{3} - 6x - x^{3} - 4x^{2}$. Combine like terms to get $x^{3} - 4x^{2} - 6x$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{3} - 4x^{2} - 6x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x^3 - 6x - (x^3 + 4x^2) = x^3 - 4x^2 - 6x.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40461254-29d1-4470-bfc5-bee36ab06438', 'NC26.M1.ANFR.1', 3, 'choice', 'Multiply two binomials', 'Multiply: $(4x - 3)(2x - 7)$.', '["$8x^{2} - 34x + 21$","$8x^{2} - 22x + 21$","$8x^{2} - 34x - 21$","$8x^{2} + 34x + 21$"]', '$8x^{2} - 34x + 21$', NULL, '$4x \cdot 2x = 8x^{2}$; $4x \cdot (-7) = -28x$; $-3 \cdot 2x = -6x$; $(-3)(-7) = 21$. Combine: $-28x - 6x = -34x$. The product is $8x^{2} - 34x + 21$.', 'checked', '{"lint":[],"solve":{"answer":"$8x^{2} - 34x + 21$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8x^2 - 28x - 6x + 21 = 8x^2 - 34x + 21.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0c6896ea-d819-4f86-b616-e49706f73873', 'NC26.M1.ANFR.1', 3, 'numeric', 'Multiply two binomials', 'The product $(x + a)(x - 4)$ equals $x^{2} + 3x - 28$ for every $x$. What is $a$?', '[]', '7', '3+4', 'Multiplying out gives $x^{2} + (a - 4)x - 4a$. Matching the $x$ term: $a - 4 = 3$, so $a = 7$. Check the constant: $-4 \times 7 = -28$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + a)(x - 4) = x^2 + (a - 4)x - 4a. -4a = -28 gives a = 7; check a - 4 = 3. a = 7.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ef7fbb3-4502-4ffa-9709-a7a0dbcd7bcc', 'NC26.M1.ANFR.1', 3, 'choice', 'Square a binomial or multiply conjugates', 'Which expression is equal to $(3a - 2b)(3a + 2b)$?', '["$9a^{2} + 4b^{2}$","$9a^{2} - 4b^{2}$","$3a^{2} - 2b^{2}$","$9a^{2} - 12ab - 4b^{2}$"]', '$9a^{2} - 4b^{2}$', NULL, '$3a \cdot 3a = 9a^{2}$; $3a \cdot 2b = 6ab$; $-2b \cdot 3a = -6ab$; $-2b \cdot 2b = -4b^{2}$. The $ab$ terms cancel, leaving $9a^{2} - 4b^{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$9a^{2} - 4b^{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"9a^2 + 6ab - 6ab - 4b^2 = 9a^2 - 4b^2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('115e718f-6ed2-4b9a-b40b-f6f6c52ba340', 'NC26.M1.ANFR.1', 3, 'numeric', 'Square a binomial or multiply conjugates', 'When $(x + 3)^{2} - (x - 3)^{2}$ is simplified, the result is $kx$. What is $k$?', '[]', '12', '6+6', '$(x + 3)^{2} = x^{2} + 6x + 9$ and $(x - 3)^{2} = x^{2} - 6x + 9$. Subtract: $x^{2} + 6x + 9 - x^{2} + 6x - 9 = 12x$. So $k = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x^2 + 6x + 9) - (x^2 - 6x + 9) = 12x, k = 12.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('097f706b-853f-4bf5-8118-0a4fdf97ffd4', 'NC26.M1.ANFR.1', 3, 'numeric', 'Multiply a binomial by a trinomial, or three factors', 'The product $(2x - 1)(x^{2} + 3x - 5)$ is written as $2x^{3} + ax^{2} + bx + c$. What is $b$?', '[]', '-13', '2*(-5)+(-1)*3', 'The $x$ terms come from $2x \cdot (-5) = -10x$ and $-1 \cdot 3x = -3x$. Together they make $-13x$, so $b = -13$. (The full product is $2x^{3} + 5x^{2} - 13x + 5$, so $a = 5$ and $c = 5$.)', 'checked', '{"lint":[],"solve":{"answer":"-13","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x(x^2 + 3x - 5) = 2x^3 + 6x^2 - 10x; -1(x^2 + 3x - 5) = -x^2 - 3x + 5. Sum 2x^3 + 5x^2 - 13x + 5, b = -13.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00644427-499a-401f-8cdd-065d6f930bd1', 'NC26.M1.ANFR.1', 3, 'choice', 'Multiply a binomial by a trinomial, or three factors', 'Which expression is equal to $(x + 1)(x + 2)(x + 3)$?', '["$x^{3} + 3x^{2} + 2x + 6$","$x^{3} + 6x^{2} + 6x + 6$","$x^{3} + 6x^{2} + 11x$","$x^{3} + 6x^{2} + 11x + 6$"]', '$x^{3} + 6x^{2} + 11x + 6$', NULL, 'First multiply two of them: $(x + 1)(x + 2) = x^{2} + 3x + 2$. Then multiply by $(x + 3)$: $x^{3} + 3x^{2} + 3x^{2} + 9x + 2x + 6 = x^{3} + 6x^{2} + 11x + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{3} + 6x^{2} + 11x + 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 1)(x + 2) = x^2 + 3x + 2; times (x + 3): x^3 + 3x^2 + 2x + 3x^2 + 9x + 6 = x^3 + 6x^2 + 11x + 6.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c13dc159-08f5-485e-9815-50c8f11f7dbb', 'NC26.M1.ANFR.1', 3, 'numeric', 'Multiply a binomial by a trinomial, or three factors', 'A box has length $x + 4$ inches, width $x + 2$ inches and height $x$ inches. Its volume is $x^{3} + bx^{2} + cx$ cubic inches. What is $b + c$?', '[]', '14', '6+8', 'Volume is length times width times height. $(x + 4)(x + 2) = x^{2} + 6x + 8$. Multiply by $x$: $x^{3} + 6x^{2} + 8x$. So $b = 6$, $c = 8$ and $b + c = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 4)(x + 2) = x^2 + 6x + 8; times x: x^3 + 6x^2 + 8x. b + c = 6 + 8 = 14.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4752d8f-236e-4ad3-8d68-b3f34e08f232', 'NC26.M1.ANFR.1', 3, 'choice', 'Area model for a product', 'A rectangle has sides $x + 6$ and $x - 2$. Its area model has parts $x^{2}$, $-2x$, $6x$ and $-12$. Which expression is the area?', '["$x^{2} + 4x - 12$","$x^{2} + 8x - 12$","$x^{2} + 4x + 12$","$x^{2} - 4x - 12$"]', '$x^{2} + 4x - 12$', NULL, 'Add the four parts: $x^{2} - 2x + 6x - 12$. Combine the $x$ parts: $-2x + 6x = 4x$. The area is $x^{2} + 4x - 12$.', 'checked', '{"lint":[],"solve":{"answer":"$x^{2} + 4x - 12$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x^2 - 2x + 6x - 12 = x^2 + 4x - 12.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
