INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da904731-a886-45a6-825c-d4586da14e4e', 'NC26.M1.ANFR.1', 3, 'numeric', 'Area model for a product', 'A rectangle''s area model has the four parts $6x^{2}$, $-4x$, $-9x$ and $6$. One side of the rectangle is $2x - 3$. The other side is $3x + k$. What is $k$?', '[]', '-2', '-4/2', 'The part $-4x$ comes from $2x$ times $k$. So $2k = -4$ and $k = -2$. Check the others: $2x \cdot 3x = 6x^{2}$, $-3 \cdot 3x = -9x$ and $(-3)(-2) = 6$.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2x - 3)(3x + k) = 6x^2 + 2kx - 9x - 3k. Parts match: 2kx = -4x gives k = -2; -3k = 6 gives k = -2. Consistent: k = -2.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('273b9d8f-26fe-49fa-96c4-1499b90e6cdc', 'NC26.M1.ANFR.1', 3, 'choice', 'Rewrite an expression in an equivalent form', 'Which expression is equivalent to $(x + 3)^{2} - (x + 3)(x - 3)$?', '["$6x$","$6x + 18$","$18$","$2x^{2} + 6x$"]', '$6x + 18$', NULL, '$(x + 3)^{2} = x^{2} + 6x + 9$ and $(x + 3)(x - 3) = x^{2} - 9$. Subtract, distributing the minus sign: $x^{2} + 6x + 9 - x^{2} + 9 = 6x + 18$.', 'checked', '{"lint":[],"solve":{"answer":"$6x + 18$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x + 3)^2 = x^2 + 6x + 9; (x + 3)(x - 3) = x^2 - 9. Difference 6x + 18.","run_id":"claude-code","at":"2026-10-17T19:07:54.373Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3763fa3c-ef8a-489b-a878-da2c1b1cec75', 'NC26.M1.ANFR.2', 1, 'choice', 'Recognize an arithmetic sequence', 'Which list of numbers is an arithmetic sequence?', '["2, 6, 18, 54","1, 2, 4, 7","5, 9, 13, 17","3, 6, 12, 24"]', '5, 9, 13, 17', NULL, 'An arithmetic sequence adds the same number each time. 5, 9, 13, 17 adds 4 every time. 2, 6, 18, 54 and 3, 6, 12, 24 multiply by the same number, and 1, 2, 4, 7 adds 1, then 2, then 3.', 'checked', '{"lint":[],"solve":{"answer":"5, 9, 13, 17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5,9,13,17: differences 4,4,4 -> arithmetic. 1,2,4,7: differences 1,2,3 no. 3,6,12,24 and 2,6,18,54 are geometric with non-constant differences.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2f17e147-ec2e-4214-87c1-84eefd68152e', 'NC26.M1.ANFR.2', 1, 'numeric', 'Continue a geometric pattern', 'A pattern begins 4, 12, 36, 108. Each number is the same multiple of the number before it. What is the next number in the pattern?', '[]', '324', '108*3', 'Each number is 3 times the one before it: $4 \times 3 = 12$, $12 \times 3 = 36$, $36 \times 3 = 108$. The next is $108 \times 3 = 324$.', 'checked', '{"lint":[],"solve":{"answer":"324","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratio 12/4 = 3, 36/12 = 3, 108/36 = 3. Next: 108 * 3 = 324.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43222945-b49f-40f7-a4f7-79232e00b7eb', 'NC26.M1.ANFR.2', 1, 'choice', 'Match a situation to exponential growth', 'Which situation is best described by exponential growth?', '["A plumber charges 40 dollars plus 15 dollars per hour","The number of views of a video doubles every day","A runner covers 3 kilometers every 15 minutes","A tree grows 4 centimeters every year"]', 'The number of views of a video doubles every day', NULL, 'Exponential growth multiplies by the same factor each step. Doubling every day is multiplying by 2. The other three situations add the same amount each time, so they are linear.', 'checked', '{"lint":[],"solve":{"answer":"The number of views of a video doubles every day","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Doubling every day is a constant multiplier -> exponential. The other three add a constant amount per unit -> linear.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a31d06c2-1818-460c-b449-11e9d9f91685', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a table', 'The values of $y$ at $x = 0, 1, 2, 3$ are 5, 8, 11, 14. What happens to $y$ each time $x$ increases by 1?', '["It increases by 3","It is multiplied by 3","It increases by 1","It increases by 5"]', 'It increases by 3', NULL, '$8 - 5 = 3$, $11 - 8 = 3$ and $14 - 11 = 3$. The same amount, 3, is added each time, so $y$ increases by 3 each time $x$ goes up by 1. This is a linear pattern.', 'checked', '{"lint":[],"solve":{"answer":"It increases by 3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8-5=3, 11-8=3, 14-11=3: y increases by 3 each time x increases by 1. Not multiplied by 3 (5*3=15, not 8).","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ddce5b5e-9308-452d-8e3a-2c78cb8b669d', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a table', 'Each list gives the values of $y$ at $x = 0, 1, 2, 3$. Which list shows a linear relationship?', '["2, 4, 8, 16","2, 5, 8, 11","2, 3, 5, 8","2, 4, 6, 9"]', '2, 5, 8, 11', NULL, 'A linear relationship adds the same amount each time. In 2, 5, 8, 11 each value is 3 more than the one before. The list 2, 4, 8, 16 doubles each time, 2, 3, 5, 8 adds 1, 2, 3, and 2, 4, 6, 9 adds 2, 2, 3.', 'checked', '{"lint":[],"solve":{"answer":"2, 5, 8, 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,3,5,8: differences 1,2,3 (not constant). 2,5,8,11: differences 3,3,3 -> linear. 2,4,6,9: differences 2,2,3 (not constant). 2,4,8,16: ratio 2 (exponential). Only 2,5,8,11 is linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('02448768-30a8-4196-844c-33a48ee12f62', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a table', 'The values of $y$ are 1, 3, 9, 27 when $x$ is 0, 1, 2, 3. How should this relationship be described?', '["Linear, because $y$ increases by 2 each time","Linear, because $y$ keeps increasing","Exponential, because $y$ increases by 3 each time","Exponential, because $y$ is multiplied by 3 each time"]', 'Exponential, because $y$ is multiplied by 3 each time', NULL, '$3 \div 1 = 3$, $9 \div 3 = 3$ and $27 \div 9 = 3$, so $y$ is multiplied by 3 each time. The differences are 2, 6, 18, which are not equal. A constant multiplier means the relationship is exponential.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because $y$ is multiplied by 3 each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1*3=3, 3*3=9, 9*3=27: constant ratio 3, so exponential because y is multiplied by 3 each time. Differences 2,6,18 are not constant, so not linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2f2c9fa-46e6-4c43-a540-8ae552fa81b3', 'NC26.M1.ANFR.2', 1, 'numeric', 'Tell linear from exponential in a table', 'The values of $y$ at $x = 1, 2, 3, 4$ are 100, 90, 80, 70. By how much does $y$ change each time $x$ goes up by 1? (Use a negative number for a decrease.)', '[]', '-10', '90-100', '$90 - 100 = -10$, $80 - 90 = -10$ and $70 - 80 = -10$. The value of $y$ changes by $-10$ each time.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90-100=-10, 80-90=-10, 70-80=-10. y changes by -10 each time x goes up by 1.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('460cfac9-028e-4cfd-afa2-61a2367ec944', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a situation or equation', 'Which situation is linear?', '["The number of bacteria in a dish doubles every hour","A car loses 10% of its value every year","A candle burns down 3 centimeters every hour","The views of a video triple every day"]', 'A candle burns down 3 centimeters every hour', NULL, 'A linear situation changes by the same amount each time. The candle loses 3 centimeters each hour. The other three change by multiplying (doubling, losing 10% of the current value, tripling), so they are exponential.', 'checked', '{"lint":[],"solve":{"answer":"A candle burns down 3 centimeters every hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Candle: subtracts a constant 3 cm per hour -> linear. Bacteria doubling, losing 10% per year, tripling views: all constant ratios -> exponential. Answer: the candle.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c4cd915-3cd8-4d35-8377-91d58833c007', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a situation or equation', 'Which equation is an exponential relationship?', '["$y = 5x$","$y = x^5$","$y = 5^x$","$y = x + 5$"]', '$y = 5^x$', NULL, 'In an exponential relationship the variable $x$ is in the exponent. $y = 5^x$ multiplies by 5 each time $x$ goes up by 1. $y = 5x$ and $y = x + 5$ are linear, and $y = x^5$ has $x$ as the base, not the exponent.', 'checked', '{"lint":[],"solve":{"answer":"$y = 5^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=x+5 and y=5x are linear; y=x^5 is a power (polynomial) function; y=5^x has the variable in the exponent with constant base 5 -> exponential.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74b4738e-ebed-4f97-81df-d39c64c1fb60', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a situation or equation', 'Maya earns 12 dollars for each hour she works, so her pay for $h$ hours is $P = 12h$ dollars. How should this relationship be described?', '["Exponential, with a growth factor of 12","Linear, with a rate of 12 dollars per hour","Linear, with a starting amount of 12 dollars","Exponential, with a rate of 12 dollars per hour"]', 'Linear, with a rate of 12 dollars per hour', NULL, 'Each extra hour adds the same 12 dollars, so the relationship is linear and 12 is the rate, in dollars per hour. With 0 hours she earns 0 dollars, so there is no starting amount.', 'checked', '{"lint":[],"solve":{"answer":"Linear, with a rate of 12 dollars per hour","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P=12h: each extra hour adds 12 dollars, a constant rate of change -> linear with rate 12 dollars per hour. Starting amount (h=0) is 0, not 12. Not exponential.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9165d125-ef15-43d4-bece-5fbe838a2f33', 'NC26.M1.ANFR.2', 1, 'choice', 'Tell linear from exponential in a situation or equation', 'Which statement describes exponential growth?', '["The amount is multiplied by the same number greater than 1 in each step","The amount increases by the same number in each step","The amount is multiplied by a number between 0 and 1 in each step","The amount stays the same in each step"]', 'The amount is multiplied by the same number greater than 1 in each step', NULL, 'Exponential growth multiplies by the same number each step, and that number is greater than 1 so the amount gets bigger. Adding the same number each step is linear growth, and multiplying by a number between 0 and 1 is exponential decay.', 'checked', '{"lint":[],"solve":{"answer":"The amount is multiplied by the same number greater than 1 in each step","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Exponential growth: multiply by the same factor b>1 each step. \"Stays the same\" is constant; \"increases by same number\" is linear; factor between 0 and 1 is exponential decay.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99e6da94-cb63-4624-9cd2-5057e8be6fa9', 'NC26.M1.ANFR.2', 1, 'choice', 'Recognize a pattern that is neither linear nor exponential', 'Which equation is neither linear nor exponential?', '["$y = 3x - 1$","$y = 3^x$","$y = 2(0.5)^x$","$y = x^2 + 1$"]', '$y = x^2 + 1$', NULL, '$y = 3x - 1$ is linear, and $y = 3^x$ and $y = 2(0.5)^x$ have $x$ in the exponent, so they are exponential. In $y = x^2 + 1$ the variable is squared, which is neither.', 'checked', '{"lint":[],"solve":{"answer":"$y = x^2 + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3^x exponential growth; y=2(0.5)^x exponential decay; y=3x-1 linear; y=x^2+1 quadratic -> neither linear nor exponential.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e74a5ad4-1818-4560-8964-21c27fd7ac4b', 'NC26.M1.ANFR.2', 1, 'choice', 'Recognize a pattern that is neither linear nor exponential', 'The values of $y$ at $x = 1, 2, 3, 4$ are 1, 4, 9, 16. Which statement is true?', '["Linear, because $y$ goes up by 3 at the start","Exponential, because $y$ is multiplied by 4 at the start","Linear, because $y$ keeps increasing","Neither, because the differences and the ratios both change"]', 'Neither, because the differences and the ratios both change', NULL, 'The differences are $4 - 1 = 3$, $9 - 4 = 5$, $16 - 9 = 7$, which are not equal, so it is not linear. The ratios are $4$, $2.25$, $1.78$, which are not equal, so it is not exponential.', 'checked', '{"lint":[],"solve":{"answer":"Neither, because the differences and the ratios both change","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1,4,9,16: differences 3,5,7 (not equal); ratios 4, 2.25, 1.78 (not equal). So neither linear nor exponential (it is y=x^2).","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6952eab3-d672-4876-8e82-7fe4b7fce9f1', 'NC26.M1.ANFR.2', 1, 'choice', 'Recognize a pattern that is neither linear nor exponential', 'After its first two terms, each term of the pattern 2, 3, 5, 8, 13 is the sum of the two terms before it. Which statement is true?', '["It is arithmetic with common difference 1","It is neither arithmetic nor geometric","It is geometric with common ratio 1.5","It is both arithmetic and geometric"]', 'It is neither arithmetic nor geometric', NULL, 'The differences are 1, 2, 3, 5, which are not equal, so it is not arithmetic. The ratios are $1.5$, $1.67$, $1.6$, $1.625$, which are not equal, so it is not geometric.', 'checked', '{"lint":[],"solve":{"answer":"It is neither arithmetic nor geometric","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2,3,5,8,13: differences 1,2,3,5 not constant -> not arithmetic; ratios 1.5, 1.67, 1.6, 1.625 not constant -> not geometric. So neither.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf17b05e-4a03-4382-8cc1-c366970f1a27', 'NC26.M1.ANFR.2', 1, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'What is the common difference of the arithmetic sequence 7, 12, 17, 22, ...?', '[]', '5', '12-7', 'Subtract a term from the next one: $12 - 7 = 5$. Check: $17 - 12 = 5$ and $22 - 17 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12-7=5, 17-12=5, 22-17=5. Common difference 5.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4940e659-8914-492f-8810-b0fefa82b1e7', 'NC26.M1.ANFR.2', 1, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'The first term of an arithmetic sequence is 10 and the common difference is 4. What is the 4th term?', '[]', '22', '10+3*4', 'The terms are 10, 14, 18, 22. The 4th term is $10 + 3 \times 4 = 22$.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Terms: 10, 14, 18, 22. a4 = 10 + 3*4 = 22.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
