INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b67ee5e8-2b1d-44f5-9e80-a5d59639cc22', 'NC26.M1.ANFR.2', 1, 'choice', 'Arithmetic sequences: difference, terms and formulas', 'An arithmetic sequence starts at 20 and has common difference $-3$. Which list shows its first four terms?', '["20, 17, 14, 11","20, 23, 26, 29","23, 20, 17, 14","20, -60, 180, -540"]', '20, 17, 14, 11', NULL, 'Add $-3$ each time: $20$, $20 - 3 = 17$, $17 - 3 = 14$, $14 - 3 = 11$. The list 20, 23, 26, 29 adds 3 instead, 23, 20, 17, 14 starts at the wrong term, and the last list multiplies instead of adding.', 'checked', '{"lint":[],"solve":{"answer":"20, 17, 14, 11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 20, add -3: 20, 17, 14, 11.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a288ab7-4012-4747-99e1-fb04590487e7', 'NC26.M1.ANFR.2', 1, 'numeric', 'Arithmetic sequences: difference, terms and formulas', 'In a sequence, each term is the same amount less than the term before it: 50, 44, 38, 32, ... What is the next term?', '[]', '26', '32-6', 'Each term is $50 - 44 = 6$ less than the one before. The next term is $32 - 6 = 26$.', 'checked', '{"lint":[],"solve":{"answer":"26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50-44=6, 44-38=6, 38-32=6; each term is 6 less. Next: 32-6=26.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
