INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcd0b731-d7a9-4d6e-9619-1ef080184094', 'NC26.M1.ANFR.2', 1, 'numeric', 'Geometric sequences: ratio, terms and formulas', 'A geometric sequence has first term 2 and common ratio 5. What is its third term?', '[]', '50', '2*5^2', 'The terms are 2, $2 \times 5 = 10$, $10 \times 5 = 50$. The third term is 50.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 2*5=10, 10*5=50. Third term 50.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
