INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('03826c3b-f3f8-40ff-81fc-de13e78aa52c', 'NC26.M1.ANFR.2', 1, 'choice', 'Geometric sequences: ratio, terms and formulas', 'What is the common ratio of the geometric sequence 80, 40, 20, 10, ...?', '["2","-40","0.5","0.25"]', '0.5', '40/80', 'Divide a term by the one before it: $40 \div 80 = 0.5$. Check: $20 \div 40 = 0.5$ and $10 \div 20 = 0.5$. The value 2 is the ratio read backwards, and $-40$ is the change from the first term to the second, not a ratio.', 'checked', '{"lint":[],"solve":{"answer":"0.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40/80=0.5, 20/40=0.5, 10/20=0.5. Common ratio 0.5.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef5ece79-c9ad-492d-a3cc-3af80c526fd4', 'NC26.M1.ANFR.2', 1, 'choice', 'Geometric sequences: ratio, terms and formulas', 'Each term of the pattern 1, 5, 25, 125 is the same multiple of the term before it. Which number comes next?', '["625","130","150","250"]', '625', '125*5', 'Each term is 5 times the one before, so the next term is $125 \times 5 = 625$. Adding 5 would give 130, adding 25 would give 150 and doubling would give 250; none of these follows the pattern.', 'checked', '{"lint":[],"solve":{"answer":"625","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each term is 5 times the previous: 1,5,25,125, next 125*5=625.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7f2f0ece-1fbd-402a-8f42-9e11164e3eeb', 'NC26.M1.ANFR.2', 1, 'numeric', 'Predict a value from a table', 'A bike shop charges 7 dollars for 1 hour, 12 dollars for 2 hours and 17 dollars for 3 hours, and the pattern continues. How many dollars does it charge for 4 hours?', '[]', '22', '17+5', 'The charge goes up by $12 - 7 = 5$ dollars for each extra hour. For 4 hours it is $17 + 5 = 22$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7, 12, 17: adds 5 each hour (linear). 4 hours: 17+5=22.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
