INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da10f1a5-6cb3-45b7-b31d-1c1fc0ee3ede', 'NC26.M1.ANFR.2', 1, 'numeric', 'Predict a value from a table', 'A video has 3 views on day 0, 6 views on day 1, 12 views on day 2 and 24 views on day 3. The pattern continues. How many views are there on day 4?', '[]', '48', '24*2', 'The views double each day: $3 \times 2 = 6$, $6 \times 2 = 12$, $12 \times 2 = 24$. On day 4 there are $24 \times 2 = 48$ views.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3,6,12,24: doubles each day. Day 4: 24*2=48.","run_id":"claude-code","at":"2026-10-18T01:07:02.762Z"}}', 'ai', NULL, NULL)
