VALUES ('86f9dfd8-fa04-47d7-9f9f-0f598b39750b', 'NC26.M1.ANFR.3', 1, 'numeric', 'Evaluate and interpret a function in context', 'Tia has saved $S(w) = 50 + 15w$ dollars after $w$ weeks. How many dollars had she saved at the very start, when $w = 0$?', '[]', '50', '50+15*0', '$S(0) = 50 + 15 \times 0 = 50$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"50","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S(0) = 50 + 15*0 = 50 dollars.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
