INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3005d5dd-176f-4f81-9e33-e77fcb5c58e3', 'NC26.M1.ANFR.3', 1, 'numeric', 'Find the domain of a function', 'A function has these input-output pairs: $(2, 7)$, $(4, 11)$, $(6, 15)$ and $(8, 19)$. What is the sum of the numbers in its domain?', '[]', '20', '2+4+6+8', 'The domain is the set of inputs, the first numbers of the pairs: 2, 4, 6 and 8. Their sum is $2 + 4 + 6 + 8 = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Domain = inputs {2, 4, 6, 8}; sum = 20.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
