INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efcd8f19-b780-4450-8e9d-0d0304962536', 'NC26.M1.ANFR.3', 2, 'choice', 'Tell growth from decay and find the factor or rate', 'Which function describes a quantity that decays by 25% each period?', '["$f(x) = 100(0.75)^x$","$f(x) = 100(0.25)^x$","$f(x) = 100(1.25)^x$","$f(x) = 100 - 0.25x$"]', '$f(x) = 100(0.75)^x$', NULL, 'Decaying by 25% leaves 75% of the amount, so the factor is $0.75$: $f(x) = 100(0.75)^x$. A factor of 0.25 would lose 75% each period, 1.25 is growth, and $100 - 0.25x$ is linear.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = 100(0.75)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Decay of 25% leaves 75% each period: factor 0.75. f(x) = 100(0.75)^x. 1.25 is growth; 0.25 is decay of 75%; 100 - 0.25x is linear.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ead3c517-0222-4149-aab8-75bffa6c4dec', 'NC26.M1.ANFR.3', 2, 'numeric', 'Tell growth from decay and find the factor or rate', 'For $f(x) = 200(1.05)^x$, what is the percent growth rate per period? Give the number of percent.', '[]', '5', '(1.05-1)*100', 'The growth factor is $1.05 = 1 + 0.05$, so the quantity grows by $0.05 = 5\%$ each period.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 1.05 = 1 + 0.05: growth of 5% per period.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('da1078ce-6482-4922-9b4e-1cc252051a2a', 'NC26.M1.ANFR.3', 2, 'numeric', 'Find and use an average rate of change', 'Let $g(x) = 3^x$. What is the average rate of change of $g$ from $x = 0$ to $x = 2$?', '[]', '4', '(3^2-3^0)/2', '$g(0) = 1$ and $g(2) = 9$. The average rate of change is $(9 - 1) \div (2 - 0) = 8 \div 2 = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g(0) = 1, g(2) = 9. (9 - 1)/(2 - 0) = 8/2 = 4.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6825007f-a63d-4f78-947b-9538f6ed107b', 'NC26.M1.ANFR.3', 2, 'numeric', 'Find and use an average rate of change', 'A function has $f(0) = 4$, $f(2) = 10$, $f(5) = 19$ and $f(9) = 31$. What is the average rate of change of $f$ from $x = 2$ to $x = 9$?', '[]', '3', '(31-10)/(9-2)', 'The change in output is $31 - 10 = 21$ and the change in input is $9 - 2 = 7$. The average rate of change is $21 \div 7 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(f(9) - f(2))/(9 - 2) = (31 - 10)/7 = 21/7 = 3.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb2abf62-4507-47b2-9988-03d22ff05e5f', 'NC26.M1.ANFR.3', 2, 'choice', 'Find and use an average rate of change', 'A town had $15{,}600$ residents in 2012 and $14{,}000$ residents in 2020. What was the average rate of change of its population, in people per year?', '["$200$","$-1600$","$-160$","$-200$"]', '$-200$', '(14000-15600)/(2020-2012)', 'The change is $14000 - 15600 = -1600$ people over $2020 - 2012 = 8$ years, so the average rate of change is $-1600 \div 8 = -200$ people per year.', 'checked', '{"lint":[],"solve":{"answer":"$-200$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(14000 - 15600)/(2020 - 2012) = -1600/8 = -200 people per year.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a4085f2-8235-40fa-90c5-4b2445f31296', 'NC26.M1.ANFR.3', 2, 'numeric', 'Find and use an average rate of change', 'Let $f(x) = 80(0.5)^x$. What is the average rate of change of $f$ from $x = 1$ to $x = 3$?', '[]', '-15', '(80*0.5^3-80*0.5)/(3-1)', '$f(1) = 40$ and $f(3) = 10$. The average rate of change is $(10 - 40) \div (3 - 1) = -30 \div 2 = -15$.', 'checked', '{"lint":[],"solve":{"answer":"-15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1) = 40, f(3) = 10. (10 - 40)/(3 - 1) = -30/2 = -15.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89e9f6db-0d80-443b-b8ca-9d430c842253', 'NC26.M1.ANFR.3', 2, 'choice', 'Compare two functions', 'Let $f(x) = 6x - 4$. Function $g$ is linear with $g(0) = 3$, $g(1) = 8$ and $g(2) = 13$. Which statement is true?', '["$g$ has both the greater rate of change and the greater $y$-intercept","$f$ has the greater rate of change, and $g$ has the greater $y$-intercept","$f$ has both the greater rate of change and the greater $y$-intercept","$g$ has the greater rate of change, and $f$ has the greater $y$-intercept"]', '$f$ has the greater rate of change, and $g$ has the greater $y$-intercept', NULL, 'The rate of $f$ is 6 and the rate of $g$ is 5 (its values go up by 5 each time), so $f$ changes faster. The $y$-intercept of $f$ is $-4$ and of $g$ is $g(0) = 3$, so $g$ has the greater $y$-intercept.', 'checked', '{"lint":[],"solve":{"answer":"$f$ has the greater rate of change, and $g$ has the greater $y$-intercept","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f: rate 6, y-intercept -4. g: rate 5 (3, 8, 13), y-intercept 3. f has the greater rate; g has the greater y-intercept.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c8342e40-2791-43ab-b142-9203f564fa16', 'NC26.M1.ANFR.3', 2, 'numeric', 'Compare two functions', 'Plan A costs $C = 12 + 4m$ dollars for $m$ miles. Plan B costs $D = 6m$ dollars. For how many miles do the two plans cost the same?', '[]', '6', '12/(6-4)', 'Set $12 + 4m = 6m$. Subtract $4m$: $12 = 2m$, so $m = 6$. Check: both plans cost 36 dollars for 6 miles.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 + 4m = 6m -> 12 = 2m -> m = 6 miles (both cost 36).","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88e20b1e-140d-4a17-8dfd-fec3572724eb', 'NC26.M1.ANFR.3', 2, 'choice', 'Compare two functions', 'Let $f(x) = 100(0.9)^x$ and $g(x) = 100(0.7)^x$. Which statement is true?', '["$f$ decays faster, because 0.9 is greater than 0.7","$f$ and $g$ decay equally fast, because both start at 100","$f$ decays faster, because it loses 90% each step","$g$ decays faster, because it loses 30% each step while $f$ loses 10%"]', '$g$ decays faster, because it loses 30% each step while $f$ loses 10%', NULL, 'The factor 0.9 keeps 90% of the value (a loss of 10% per step) and the factor 0.7 keeps 70% (a loss of 30% per step). The smaller factor means faster decay, so $g$ decays faster.', 'checked', '{"lint":[],"solve":{"answer":"$g$ decays faster, because it loses 30% each step while $f$ loses 10%","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f keeps 90% (loses 10%) per step; g keeps 70% (loses 30%). g decays faster.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('842eedbe-20d8-4809-8021-e7022ff33a07', 'NC26.M1.ANFR.3', 2, 'numeric', 'Compare two functions', 'Let $f(x) = 7x + 2$. Function $g$ is linear with $g(0) = 30$ and $g(5) = 10$. How much greater is the rate of change of $f$ than the rate of change of $g$?', '[]', '11', '7-(10-30)/5', 'The rate of $f$ is 7. The rate of $g$ is $(10 - 30) \div 5 = -4$. The difference is $7 - (-4) = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rate of f = 7. Rate of g = (10 - 30)/5 = -4. 7 - (-4) = 11.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b4ee38d8-a465-4322-979d-85e5850c2e1c', 'NC26.M1.ANFR.3', 2, 'choice', 'Tell growth from decay and find the factor or rate', 'The function $f(x) = 120(0.85)^x$ models a quantity. Which describes the kind of change and its percent rate per step?', '["Decay of 85% per step","Growth of 15% per step","Growth of 85% per step","Decay of 15% per step"]', 'Decay of 15% per step', NULL, 'The factor 0.85 is less than 1, so the quantity decays. Each step keeps 85% of the amount, so it loses $100\% - 85\% = 15\%$ per step.', 'checked', '{"lint":[],"solve":{"answer":"Decay of 15% per step","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factor 0.85 < 1, decay; 1-0.85=0.15, 15% per step.","run_id":"claude-code","at":"2026-10-18T03:28:53.209Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50d4bafc-e6ac-4f0b-ae1c-23e20d386906', 'NC26.M1.ANFR.3', 3, 'choice', 'Find the range of an exponential function', 'Let $g(x) = 2(3)^x$ for all real numbers $x$. What is the range of $g$?', '["All real numbers","$y \\ge 2$","$y > 0$","$y \\ge 0$"]', '$y > 0$', NULL, 'A positive number raised to any power is positive, and $2(3)^x$ gets as close to 0 as you like for very negative $x$ without ever reaching it. So every output is greater than 0, and every positive number is an output: $y > 0$.', 'checked', '{"lint":[],"solve":{"answer":"$y > 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3^x > 0 for all real x and takes every positive value, so 2(3)^x takes every value > 0, never 0. Range y > 0. (y >= 2 is wrong: e.g. g(-1) = 2/3.)","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('513b73f4-58d1-4fef-a12f-4fac631be0d4', 'NC26.M1.ANFR.3', 3, 'choice', 'Compare the rates of change of two functions', 'Function $f$ is $f(x) = 5x - 2$. Function $g$ is linear with $g(0) = 1$, $g(2) = 9$ and $g(4) = 17$. Which function has the greater rate of change, and what are the two rates?', '["$g$ has the greater rate: 8 compared with 5","$g$ has the greater rate: 16 compared with 5","$f$ has the greater rate: 5 compared with 4","The rates are equal: both are 4"]', '$f$ has the greater rate: 5 compared with 4', NULL, 'The rate of change of $f$ is its slope, 5. For $g$, the output rises from 1 to 9 while the input rises by 2, so the rate is $\frac{9 - 1}{2} = 4$ (the same from 2 to 4: $\frac{17 - 9}{2} = 4$). Since $5 > 4$, $f$ has the greater rate.', 'checked', '{"lint":[],"solve":{"answer":"$f$ has the greater rate: 5 compared with 4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f slope 5. g: (9 - 1)/(2 - 0) = 4, (17 - 9)/2 = 4. f is greater: 5 vs 4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a9f8d04-7f6d-4b2d-851d-9d0c4594a548', 'NC26.M1.ANFR.3', 3, 'numeric', 'Average rate of change of an exponential function', 'Let $f(x) = 3(2)^x$. What is the average rate of change of $f$ from $x = 1$ to $x = 3$?', '[]', '9', '(3*2^3-3*2^1)/(3-1)', '$f(1) = 3(2) = 6$ and $f(3) = 3(8) = 24$. The average rate of change is $\frac{24 - 6}{3 - 1} = \frac{18}{2} = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(1) = 3*2 = 6, f(3) = 3*8 = 24. (24 - 6)/(3 - 1) = 18/2 = 9.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b153e16-7c58-4ddc-a4fc-519599cbf5c7', 'NC26.M1.ANFR.3', 3, 'numeric', 'Evaluate a function written in function notation', 'Let $f(x) = 2x + 3$. If $f(a) = 17$, what is $f(a + 2)$?', '[]', '21', '17+2*2', 'Adding 2 to the input adds $2 \times 2 = 4$ to the output, because the rate of $f$ is 2. So $f(a + 2) = 17 + 4 = 21$. (Or solve $2a + 3 = 17$ to get $a = 7$, then $f(9) = 21$.)', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2a + 3 = 17 -> a = 7. f(a + 2) = f(9) = 21. (Or f(a) + 2*2 = 21.)","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7251ac14-a023-4c0a-98ce-e31dcbd11cb2', 'NC26.M1.ANFR.3', 3, 'choice', 'Evaluate a function written in function notation', 'Let $f(x) = 3^x$. Which expression is equal to $f(x + 1)$?', '["$f(x) + 3$","$f(x) + 1$","$3f(x)$","$f(3x)$"]', '$3f(x)$', NULL, '$f(x + 1) = 3^{x+1} = 3^x \cdot 3 = 3f(x)$. For example, $f(2 + 1) = 27$ and $3f(2) = 3 \times 9 = 27$, while $f(2) + 3 = 12$ and $f(2) + 1 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"$3f(x)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x + 1) = 3^(x+1) = 3 * 3^x = 3f(x).","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('60bd20be-547a-4d52-a2cb-3bf31519c182', 'NC26.M1.ANFR.3', 3, 'numeric', 'Evaluate a function written in function notation', 'A linear function $f$ has $f(2) = 5$ and $f(6) = 17$. What is $f(10)$?', '[]', '29', '17+(17-5)/(6-2)*(10-6)', 'From $x = 2$ to $x = 6$ the output goes up by 12, so the rate is $12 \div 4 = 3$. From $x = 6$ to $x = 10$ the output goes up by $4 \times 3 = 12$, so $f(10) = 17 + 12 = 29$.', 'checked', '{"lint":[],"solve":{"answer":"29","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (17 - 5)/(6 - 2) = 3. f(10) = 17 + 3*4 = 29.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aabd1db5-c1a6-4048-b049-e7c7afd9b35f', 'NC26.M1.ANFR.3', 3, 'numeric', 'Evaluate a function written in function notation', 'Let $f(x) = 4(1.5)^x$. What is $f(4)$?', '[]', '20.25', '4*1.5^4', '$1.5^4 = 1.5 \times 1.5 \times 1.5 \times 1.5 = 5.0625$. So $f(4) = 4 \times 5.0625 = 20.25$.', 'checked', '{"lint":[],"solve":{"answer":"20.25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5^2 = 2.25, 1.5^4 = 5.0625. f(4) = 4 * 5.0625 = 20.25.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab055091-f69a-436b-8bf7-e2988027b872', 'NC26.M1.ANFR.3', 3, 'numeric', 'Evaluate and interpret a function in context', 'The amount of medicine in a person''s body is $M(t) = 200(0.5)^t$ milligrams after $t$ hours. After how many hours are there 12.5 milligrams left?', '[]', '4', NULL, 'Halve 200 repeatedly: 100 after 1 hour, 50 after 2, 25 after 3 and 12.5 after 4. So $M(4) = 12.5$ and the answer is 4 hours.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200(0.5)^t = 12.5 -> 0.5^t = 12.5/200 = 1/16 -> t = 4 hours. (200, 100, 50, 25, 12.5)","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5861542-4810-4dab-bb5d-c69513e593c1', 'NC26.M1.ANFR.3', 3, 'choice', 'Evaluate and interpret a function in context', '$C(n) = 15 + 4n$ is the cost, in dollars, of renting a game for $n$ extra days. Which question is answered by solving $C(n) = 47$?', '["How much does it cost to rent the game for 47 extra days?","For how many extra days does the rental cost 47 dollars?","How much does each extra day cost?","How much does it cost to rent the game with no extra days?"]', 'For how many extra days does the rental cost 47 dollars?', NULL, 'Solving $C(n) = 47$ means the output (the cost) is 47 and the unknown is the input $n$ (the extra days). So it answers: for how many extra days does the rental cost 47 dollars? (Here $15 + 4n = 47$ gives $n = 8$.)', 'checked', '{"lint":[],"solve":{"answer":"For how many extra days does the rental cost 47 dollars?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solving C(n) = 47 finds the input n giving output 47: the number of extra days for which the cost is 47 dollars (n = 8).","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('50a2ccc7-aaa4-4918-847a-a02fdebea7fd', 'NC26.M1.ANFR.3', 3, 'numeric', 'Evaluate and interpret a function in context', 'A computer''s value is $V(t) = 1200(0.75)^t$ dollars after $t$ years. How many dollars of value does it lose during the second year, from $t = 1$ to $t = 2$?', '[]', '225', '1200*0.75-1200*0.75^2', '$V(1) = 1200 \times 0.75 = 900$ and $V(2) = 900 \times 0.75 = 675$. The loss during the second year is $900 - 675 = 225$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"225","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V(1) = 1200 * 0.75 = 900. V(2) = 900 * 0.75 = 675. Loss = 900 - 675 = 225.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('17e55c9c-9880-460d-af3b-cb198f54b519', 'NC26.M1.ANFR.3', 3, 'choice', 'Find the domain of a function', 'A concert hall has 400 seats and tickets cost 25 dollars each. The function $R(n) = 25n$ gives the money collected from $n$ tickets sold. Which statement is correct?', '["Domain: whole numbers 0 to 400. Range: multiples of 25 from 0 to 10000","Domain: whole numbers 0 to 10000. Range: whole numbers 0 to 400","Domain: all real numbers from 0 to 400. Range: all real numbers from 0 to 10000","Domain: multiples of 25 from 0 to 10000. Range: whole numbers 0 to 400"]', 'Domain: whole numbers 0 to 400. Range: multiples of 25 from 0 to 10000', NULL, 'The inputs are numbers of tickets: the whole numbers 0 through 400. The outputs are 25 times those: 0, 25, 50, ..., up to $25 \times 400 = 10000$, the multiples of 25 from 0 to 10000.', 'checked', '{"lint":[],"solve":{"answer":"Domain: whole numbers 0 to 400. Range: multiples of 25 from 0 to 10000","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n = tickets sold: whole numbers 0 to 400. R = 25n: multiples of 25 from 0 to 25*400 = 10000.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef8c4553-1cc6-42eb-aad4-3f95a7dd2145', 'NC26.M1.ANFR.3', 3, 'numeric', 'Find the domain of a function', 'A discrete function has as its domain every whole number $n$ with $3 \le n \le 40$. How many numbers are in its domain?', '[]', '38', '40-3+1', 'The whole numbers from 3 to 40 include both ends: $40 - 3 + 1 = 38$ numbers.', 'checked', '{"lint":[],"solve":{"answer":"38","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Whole numbers 3 to 40 inclusive: 40 - 3 + 1 = 38.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8a9d4e3-5586-4732-97bc-4b0c8213365d', 'NC26.M1.ANFR.3', 3, 'choice', 'Find the domain of a function', 'A store sells rice by weight. A customer may buy any amount from 0.5 pounds up to 10 pounds. A function gives the cost of $w$ pounds. Which is its domain?', '["$0 \\le w \\le 10$","The whole numbers from 1 through 10","$w \\ge 0.5$","$0.5 \\le w \\le 10$"]', '$0.5 \le w \le 10$', NULL, 'The inputs are the weights a customer may buy: any amount from 0.5 pounds to 10 pounds, so $0.5 \le w \le 10$. Weights below 0.5 are not allowed, whole numbers alone would leave out amounts like 2.5, and there is an upper limit of 10.', 'checked', '{"lint":[],"solve":{"answer":"$0.5 \\le w \\le 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Any amount from 0.5 up to 10 pounds, so 0.5 <= w <= 10 (continuous).","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('81acf5f0-4f74-4802-99ac-9d6265ff8955', 'NC26.M1.ANFR.3', 3, 'choice', 'Find the range of a function', 'Let $f(x) = -4(2)^x$ for all real numbers $x$. What is the range of $f$?', '["$y > 0$","$y \\le -4$","$y < 0$","All real numbers"]', '$y < 0$', NULL, '$2^x$ is always positive, so $-4(2)^x$ is always negative. The outputs get closer and closer to 0 for negative $x$ and more and more negative for large $x$, so the range is $y < 0$.', 'checked', '{"lint":[],"solve":{"answer":"$y < 0$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2^x takes every positive value; times -4 gives every negative value, never 0. Range y < 0.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('744942a9-e698-42b5-b394-a89ad84325ab', 'NC26.M1.ANFR.3', 3, 'numeric', 'Find the range of a function', 'The function $g(x) = 100(0.5)^x$ has domain $\{0, 1, 2, 3, 4, 5\}$. What is the smallest number in its range?', '[]', '3.125', '100*0.5^5', 'The function decreases, so the smallest output is at $x = 5$: $g(5) = 100 \times 0.5^5 = 100 \div 32 = 3.125$.', 'checked', '{"lint":[],"solve":{"answer":"3.125","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g decreases: g(5) = 100/32 = 3.125 is the smallest output.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5835f199-3a92-4c70-b527-cfe82b648d68', 'NC26.M1.ANFR.3', 3, 'choice', 'Find the range of a function', 'The function $f(x) = -3x + 9$ has domain $0 \le x \le 5$. Which describes its range?', '["$0 \\le y \\le 5$","$-6 \\le y \\le 9$","$9 \\le y \\le 24$","$-6 \\le y \\le 0$"]', '$-6 \le y \le 9$', NULL, 'The function decreases, so the largest output is $f(0) = 9$ and the smallest is $f(5) = -15 + 9 = -6$. The range is $-6 \le y \le 9$.', 'checked', '{"lint":[],"solve":{"answer":"$-6 \\le y \\le 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = 9, f(5) = -15 + 9 = -6; f decreasing and continuous on the interval. Range -6 <= y <= 9.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bff6ca1f-64a6-4cf9-9637-7cfb9d43d82d', 'NC26.M1.ANFR.3', 3, 'numeric', 'Find the range of a function', 'The function $f(x) = 2(3)^x$ has domain $\{0, 1, 2, 3, 4\}$. How many numbers in its range are greater than 50?', '[]', '2', NULL, 'The outputs are $f(0) = 2$, $f(1) = 6$, $f(2) = 18$, $f(3) = 54$ and $f(4) = 162$. The ones greater than 50 are 54 and 162, so there are 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outputs: 2, 6, 18, 54, 162. Greater than 50: 54 and 162 -> 2.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('66e68078-8948-4612-adcf-fbe969fb3662', 'NC26.M1.ANFR.3', 3, 'choice', 'Decide whether a function is discrete or continuous', 'A tank fills steadily for 10 minutes. Model 1 gives the height of the water at every moment. Model 2 gives it only at the end of each whole minute. Which statement is correct?', '["Model 1 is continuous and Model 2 is discrete","Model 1 is discrete and Model 2 is continuous","Both models are continuous","Both models are discrete"]', 'Model 1 is continuous and Model 2 is discrete', NULL, 'Model 1 has an output for every time from 0 to 10 minutes, so its graph has no gaps: continuous. Model 2 has outputs only at whole minutes, so its graph is separate points: discrete.', 'checked', '{"lint":[],"solve":{"answer":"Model 1 is continuous and Model 2 is discrete","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Model 1 is defined at every moment (continuous); Model 2 only at whole minutes (discrete).","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6408366-a174-4e66-a4f2-ea1c4a6f64a0', 'NC26.M1.ANFR.3', 3, 'choice', 'Decide whether a function is discrete or continuous', 'Which domain makes the graph of $f(x) = 4x + 2$ a solid line segment rather than separate points?', '["$x = 1, 2, 3, 4, 5$ only","$x = 1$ and $x = 5$ only","The whole numbers $x$ with $1 < x < 5$","All real numbers $x$ with $1 \\le x \\le 5$"]', 'All real numbers $x$ with $1 \le x \le 5$', NULL, 'A solid segment needs every number between the end points as an input, so the domain must be all real numbers from 1 to 5. The other domains are lists of separate numbers, which give separate points.', 'checked', '{"lint":[],"solve":{"answer":"All real numbers $x$ with $1 \\le x \\le 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A solid segment needs every real x in an interval: 1 <= x <= 5 (all reals). Whole-number or two-point domains give separate points.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('04b8b277-7334-4320-a8d2-3e381acbd349', 'NC26.M1.ANFR.3', 3, 'choice', 'Decide whether a function is discrete or continuous', 'Which function has a graph made of separate points?', '["$d(t) = 4t$, the distance walked at any time $t$ from 0 to 2 hours","$W(n) = 3n$, the number of wheels on $n$ tricycles","$C(p) = 3p$, the cost of $p$ pounds of grapes, for any weight from 0 to 10 pounds","$h(t) = 2 + 5t$, the height of a plant at any time $t$ over 4 weeks"]', '$W(n) = 3n$, the number of wheels on $n$ tricycles', NULL, 'The number of tricycles must be a whole number, so $W$ has only separate inputs and its graph is separate points. Time, weight and plant height can take any value in a range, so the other three graphs are solid lines.', 'checked', '{"lint":[],"solve":{"answer":"$W(n) = 3n$, the number of wheels on $n$ tricycles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number of tricycles n must be a whole number -> separate points. Walking time, weight of grapes and plant-growth time can be any value in an interval -> continuous.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4112a8e0-d039-48cd-89dc-9c81b29025b7', 'NC26.M1.ANFR.3', 3, 'numeric', 'Tell growth from decay and find the factor or rate', 'A population is $P(t) = 800(1.25)^t$. By how many people does it grow from $t = 1$ to $t = 2$?', '[]', '250', '800*1.25^2-800*1.25', '$P(1) = 800 \times 1.25 = 1000$ and $P(2) = 1000 \times 1.25 = 1250$. It grows by $1250 - 1000 = 250$ people.', 'checked', '{"lint":[],"solve":{"answer":"250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"P(1) = 800 * 1.25 = 1000. P(2) = 1000 * 1.25 = 1250. Growth = 250.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5fa3ca01-1aca-431d-9f39-cba3d6496099', 'NC26.M1.ANFR.3', 3, 'choice', 'Tell growth from decay and find the factor or rate', 'An exponential function has $f(0) = 50$ and $f(1) = 35$. Which statement is true?', '["$f(x) = 50(1.3)^x$, so $f$ shows growth","$f(x) = 50(35)^x$, so $f$ shows growth","$f(x) = 50(0.7)^x$, so $f$ shows decay","$f(x) = 50 - 15x$, so $f$ shows exponential decay"]', '$f(x) = 50(0.7)^x$, so $f$ shows decay', NULL, 'The initial value is $f(0) = 50$ and the factor is $f(1) \div f(0) = 35 \div 50 = 0.7$. So $f(x) = 50(0.7)^x$, which is less than 1, so it is decay. The function $50 - 15x$ is linear, not exponential.', 'checked', '{"lint":[],"solve":{"answer":"$f(x) = 50(0.7)^x$, so $f$ shows decay","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Initial 50, factor 35/50 = 0.7 < 1: f(x) = 50(0.7)^x, decay.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('657e7278-e1aa-4c48-839c-5e99289a0690', 'NC26.M1.ANFR.3', 3, 'numeric', 'Tell growth from decay and find the factor or rate', 'An investment of 500 dollars grows by 6% each year. How many dollars is it worth after 2 years?', '[]', '561.8', '500*1.06^2', 'The growth factor is $1.06$. After 2 years the value is $500 \times 1.06^2 = 500 \times 1.1236 = 561.8$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"561.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"500 * 1.06^2 = 500 * 1.1236 = 561.80 dollars.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3ae3ef63-3655-480a-9e7e-59a984697194', 'NC26.M1.ANFR.3', 3, 'numeric', 'Find and use an average rate of change', 'Let $f(x) = 81\left(\frac{1}{3}\right)^x$. What is the average rate of change of $f$ from $x = 0$ to $x = 3$?', '[]', '-26', '(81*(1/3)^3-81)/3', '$f(0) = 81$ and $f(3) = 81 \times \frac{1}{27} = 3$. The average rate of change is $(3 - 81) \div 3 = -78 \div 3 = -26$.', 'checked', '{"lint":[],"solve":{"answer":"-26","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = 81, f(3) = 81/27 = 3. (3 - 81)/3 = -78/3 = -26.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a6f5e85-ca97-4241-ae95-b073609685b5', 'NC26.M1.ANFR.3', 3, 'choice', 'Find and use an average rate of change', 'Let $f(x) = 2^x$. On which interval is the average rate of change of $f$ the greatest?', '["From $x = 3$ to $x = 5$","From $x = 0$ to $x = 2$","From $x = 1$ to $x = 3$","From $x = 2$ to $x = 4$"]', 'From $x = 3$ to $x = 5$', NULL, 'Each interval has length 2. The average rates are $(4 - 1) \div 2 = 1.5$, $(8 - 2) \div 2 = 3$, $(16 - 4) \div 2 = 6$ and $(32 - 8) \div 2 = 12$. The greatest is from $x = 3$ to $x = 5$. The rate of an exponential growth function keeps increasing.', 'checked', '{"lint":[],"solve":{"answer":"From $x = 3$ to $x = 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"All intervals have width 2. [0,2]: (4-1)/2 = 1.5; [1,3]: (8-2)/2 = 3; [2,4]: (16-4)/2 = 6; [3,5]: (32-8)/2 = 12. Greatest on [3,5].","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f66d6aa-a5d6-4b5e-97e5-213863af73a8', 'NC26.M1.ANFR.3', 3, 'numeric', 'Find and use an average rate of change', 'A linear function $f$ has an average rate of change of $-4$ from $x = 1$ to $x = 6$, and $f(1) = 30$. What is $f(6)$?', '[]', '10', '30+(6-1)*(-4)', 'The change in output is the rate times the change in input: $-4 \times 5 = -20$. So $f(6) = 30 - 20 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(6) = f(1) + (-4)(6 - 1) = 30 - 20 = 10.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7e6abe9-09e6-46a4-b7a1-e00f117e5996', 'NC26.M1.ANFR.3', 3, 'choice', 'Find and use an average rate of change', 'For which kind of function is the average rate of change the same on every interval of $x$-values?', '["Exponential functions","Linear functions","Both linear and exponential functions","Neither linear nor exponential functions"]', 'Linear functions', NULL, 'A linear function changes by the same amount for every equal step in $x$, so its average rate of change is its slope on every interval. An exponential function changes by more or less on each step, so its average rate of change depends on the interval.', 'checked', '{"lint":[],"solve":{"answer":"Linear functions","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only a linear function has a constant rate of change on every interval; an exponential function''s average rate of change varies with the interval.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c2b64422-b514-4ead-a829-614de3ad0558', 'NC26.M1.ANFR.3', 3, 'numeric', 'Find and use an average rate of change', 'A cup of tea cools. Its temperature in degrees is 90 at 0 minutes, 70 at 5 minutes, 58 at 10 minutes and 50 at 15 minutes. What is the average rate of change of the temperature from 5 minutes to 15 minutes, in degrees per minute?', '[]', '-2', '(50-70)/(15-5)', 'The change in temperature is $50 - 70 = -20$ degrees over $15 - 5 = 10$ minutes, so the average rate of change is $-20 \div 10 = -2$ degrees per minute.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(50 - 70)/(15 - 5) = -20/10 = -2 degrees per minute.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('066592c1-cdb0-4a41-b210-c58baa38f80a', 'NC26.M1.ANFR.3', 3, 'numeric', 'Compare two functions', 'Function $f$ is linear with $f(0) = 5$ and $f(1) = 8$. Function $g$ is $g(x) = 2(3)^x$. How much greater is $g(3)$ than $f(3)$?', '[]', '40', '2*3^3-(5+3*3)', 'The rate of $f$ is $8 - 5 = 3$, so $f(3) = 5 + 3 \times 3 = 14$. Also $g(3) = 2 \times 3^3 = 54$. The difference is $54 - 14 = 40$.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(x) = 3x + 5, f(3) = 14. g(3) = 2 * 27 = 54. 54 - 14 = 40.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3219c7f4-1226-4c44-9ac9-27f2e337a7f2', 'NC26.M1.ANFR.3', 3, 'numeric', 'Compare two functions', 'Function $f$ is $f(x) = 4(2)^x$. Function $g$ is $g(x) = 6x + 1$. Function $h$ is exponential with $h(0) = 5$ and $h(1) = 15$. What is the greatest of $f(3)$, $g(3)$ and $h(3)$?', '[]', '135', '5*3^3', '$f(3) = 4 \times 8 = 32$ and $g(3) = 6 \times 3 + 1 = 19$. For $h$ the factor is $15 \div 5 = 3$, so $h(3) = 5 \times 3^3 = 135$. The greatest is 135.', 'checked', '{"lint":[],"solve":{"answer":"135","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(3) = 4 * 8 = 32. g(3) = 19. h(x) = 5(3)^x (factor 15/5 = 3), h(3) = 135. Greatest is 135.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bf4fb5d6-2a61-495b-a123-75bf048a7a12', 'NC26.M1.ANFR.3', 3, 'choice', 'Compare two functions', 'Let $f(x) = 10 + 2x$ and $g(x) = 10(1.2)^x$. Which statement is true?', '["They are equal at $x = 0$ and at $x = 1$, and $g$ is greater at $x = 2$","They are equal at $x = 0$, and $g$ is greater at $x = 1$","$f$ is greater than $g$ at $x = 2$","$g$ is less than $f$ for every $x > 0$"]', 'They are equal at $x = 0$ and at $x = 1$, and $g$ is greater at $x = 2$', NULL, '$f(0) = g(0) = 10$. $f(1) = 12$ and $g(1) = 10 \times 1.2 = 12$. $f(2) = 14$ and $g(2) = 10 \times 1.44 = 14.4$, so $g$ is greater at $x = 2$.', 'checked', '{"lint":[],"solve":{"answer":"They are equal at $x = 0$ and at $x = 1$, and $g$ is greater at $x = 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f(0) = 10 = g(0); f(1) = 12, g(1) = 12 (equal); f(2) = 14, g(2) = 10*1.44 = 14.4 > 14. So equal at 0 and 1 and g greater at 2. Option \"g greater at x=1\" is false (equal); \"f greater at 2\" false; \"g less for every x>0\" false.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('61c937c9-55c7-47ca-b4f1-229137bc63af', 'NC26.M1.ANFR.3', 3, 'numeric', 'Compare two functions', 'How much greater is the average rate of change of $g(x) = 2^x$ than that of $f(x) = 6x + 4$ from $x = 2$ to $x = 6$?', '[]', '9', '(2^6-2^2)/(6-2)-6', 'For $g$: $(64 - 4) \div 4 = 15$. For $f$, a linear function, the rate is 6 on every interval. The difference is $15 - 6 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"g: (2^6 - 2^2)/(6 - 2) = (64 - 4)/4 = 15. f: rate 6. 15 - 6 = 9.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4f00d31d-5007-4799-8102-d29074fe5a8d', 'NC26.M1.ANFR.3', 3, 'choice', 'Compare two functions', 'Both $f(x) = 100(0.8)^x$ and $g(x) = 100 - 8x$ start at 100 and decrease. Which statement is true?', '["$f$ loses 20 each step, while $g$ loses 8% of its value each step","$f$ and $g$ both lose 8 each step","$f$ loses 20% of its current value each step, while $g$ loses 8 each step","$f$ loses 0.8 each step, while $g$ loses 8 each step"]', '$f$ loses 20% of its current value each step, while $g$ loses 8 each step', NULL, '$f$ is exponential decay with factor 0.8, so each step it keeps 80% and loses 20% of its current value. $g$ is linear with rate $-8$, so each step it loses exactly 8.', 'checked', '{"lint":[],"solve":{"answer":"$f$ loses 20% of its current value each step, while $g$ loses 8 each step","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"f multiplies by 0.8 each step: loses 20% of its current value. g subtracts 8 each step. Other options misdescribe one or both.","run_id":"claude-code","at":"2026-10-18T01:07:02.801Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
