VALUES ('38333c5f-e866-4b4e-930e-c0f814155356', 'NC26.M1.ANFR.4', 1, 'choice', 'Choose a linear or exponential model', 'For $x = 1, 2, 3, 4$, a table gives $y = 3, 6, 9, 12$. Which statement describes the function?', '["Exponential, because $y$ keeps getting larger","Exponential, because $y$ is multiplied by 2 each time","Neither, because $y$ is not the same each time","Linear, because $y$ increases by the same amount each time"]', 'Linear, because $y$ increases by the same amount each time', NULL, '$y$ goes up by 3 every time $x$ goes up by 1. A constant change means the function is linear.', 'checked', '{"lint":[],"solve":{"answer":"Linear, because $y$ increases by the same amount each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3, 6, 9, 12 increases by 3 each step: linear. Ratios 2, 1.5, 1.33 are not constant.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4ca29b19-1304-4495-a638-163619ec45d3', 'NC26.M1.ANFR.4', 1, 'choice', 'Choose a linear or exponential model', 'For $x = 0, 1, 2, 3$, a table gives $y = 2, 6, 18, 54$. Which statement describes the function?', '["Linear, because $y$ increases each time","Linear, because $y$ increases by 4 each time","Exponential, because $y$ is multiplied by 3 each time","Exponential, because $y$ is multiplied by 2 each time"]', 'Exponential, because $y$ is multiplied by 3 each time', NULL, '$6 \div 2 = 3$, $18 \div 6 = 3$ and $54 \div 18 = 3$. A constant multiplier means the function is exponential.', 'checked', '{"lint":[],"solve":{"answer":"Exponential, because $y$ is multiplied by 3 each time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2, 6, 18, 54: ratio 3 each step, exponential.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a967f7b5-a81e-43b8-a980-32a14efaecaf', 'NC26.M1.ANFR.4', 1, 'numeric', 'Choose a linear or exponential model', 'The y-values in a table are 5, 10, 20, 40 as $x$ goes from 0 to 3. By what number is each y-value multiplied to get the next one?', '[]', '2', '10/5', '$10 \div 5 = 2$, $20 \div 10 = 2$ and $40 \div 20 = 2$. Each value is multiplied by 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"10/5 = 20/10 = 40/20 = 2.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
