INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4bf02e0-b9ec-44a3-b4cb-6f7d9346a452', 'NC26.M1.ANFR.4', 1, 'choice', 'Interpret the parts of a linear or exponential function', 'The function $h(t) = 50 - 4t$ gives the height of the water in a tank, in centimeters, after $t$ minutes. What does 50 mean?', '["The water is 50 centimeters tall at the start","The water level drops 50 centimeters each minute","The tank is empty after 50 minutes","The water is 50 centimeters tall after 4 minutes"]', 'The water is 50 centimeters tall at the start', NULL, 'At $t = 0$ the height is $h(0) = 50$, so 50 is the starting height. The 4 is the drop each minute.', 'checked', '{"lint":[],"solve":{"answer":"The water is 50 centimeters tall at the start","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h(0) = 50: the water is 50 cm high at the start. (Empty at t = 12.5, not 50.)","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
