VALUES ('dd4a0ff2-c6d2-41af-818a-56525f9a05a0', 'NC26.M1.ANFR.4', 1, 'numeric', 'Write and use an explicit rule for a sequence', 'An explicit rule for a sequence is $a_n = 3n + 2$. What is $a_{10}$?', '[]', '32', '3*10+2', '$a_{10} = 3 \cdot 10 + 2 = 32$.', 'checked', '{"lint":[],"solve":{"answer":"32","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*10 + 2 = 32.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
