INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff380d03-0d4e-4e6f-a788-f763eaf7ed45', 'NC26.M1.ANFR.4', 1, 'choice', 'Write and use an explicit rule for a sequence', 'Which explicit rule matches the sequence 6, 11, 16, 21, ...?', '["$a_n = 6n$","$a_n = 5n + 6$","$a_n = 5n + 1$","$a_n = n + 5$"]', '$a_n = 5n + 1$', NULL, 'The terms rise by 5, so the rule starts $5n$. At $n = 1$ the term is 6, so add 1: $a_n = 5n + 1$.', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 5n + 1$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Difference 5, a1 = 6: a_n = 6 + 5(n-1) = 5n + 1.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
