VALUES ('2377d765-386b-4234-876e-154785fb73ce', 'NC26.M1.ANFR.4', 2, 'numeric', 'Evaluate a recursive rule for a geometric sequence', 'A sequence is defined by $a_1 = -2$ and $a_n = 3a_{n-1}$ for $n \ge 2$. What is $a_4$?', '[]', '-54', '-2*3^3', 'The terms are $-2, -6, -18, -54$. So $a_4 = -54$.', 'checked', '{"lint":[],"solve":{"answer":"-54","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2, -6, -18, -54. a4 = -54.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
