INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('39a91d1f-f0a8-49dc-a7d9-bbff0a046092', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a recursive rule for a sequence', 'A sequence begins 81, 27, 9, 3, ... Which recursive rule describes it?', '["$a_1 = 81$, $a_n = \\frac{1}{3}a_{n-1}$","$a_1 = 81$, $a_n = 3a_{n-1}$","$a_1 = 3$, $a_n = \\frac{1}{3}a_{n-1}$","$a_1 = 81$, $a_n = a_{n-1} - 54$"]', '$a_1 = 81$, $a_n = \frac{1}{3}a_{n-1}$', NULL, 'Each term is one third of the term before it ($81 \div 3 = 27$, $27 \div 3 = 9$), and the first term is 81.', 'checked', '{"lint":[],"solve":{"answer":"$a_1 = 81$, $a_n = \\frac{1}{3}a_{n-1}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each term is one third of the previous; first term 81. The subtract-54 option gives 81, 27, -27, so fails.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
