INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a62780c4-7fa8-46e1-bd7c-2f310d657da5', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a linear function from a situation', 'A pool already holds 120 gallons of water. A hose adds 15 gallons every minute. Which function gives the gallons $G$ in the pool after $m$ minutes?', '["$G(m) = 120m + 15$","$G(m) = 15m + 120$","$G(m) = 15(m + 120)$","$G(m) = 120 - 15m$"]', '$G(m) = 15m + 120$', NULL, 'The pool starts at 120 gallons and gains 15 gallons each minute: $G(m) = 15m + 120$.', 'checked', '{"lint":[],"solve":{"answer":"$G(m) = 15m + 120$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 120, plus 15 per minute: G(m) = 15m + 120.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e1ba1d1-50ab-4163-9a40-9242ba32514f', 'NC26.M1.ANFR.4', 2, 'choice', 'Write and use an exponential function from a situation', 'A car is worth 20000 dollars and loses 15% of its value each year. Which function gives its value $V$, in dollars, after $t$ years?', '["$V(t) = 20000 \\cdot 0.15^t$","$V(t) = 20000 \\cdot 0.85^t$","$V(t) = 20000 \\cdot 1.15^t$","$V(t) = 20000 - 0.15t$"]', '$V(t) = 20000 \cdot 0.85^t$', NULL, 'Each year the car keeps $100\% - 15\% = 85\%$ of its value, so the growth factor is 0.85: $V(t) = 20000 \cdot 0.85^t$.', 'checked', '{"lint":[],"solve":{"answer":"$V(t) = 20000 \\cdot 0.85^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Keeps 85% each year: V(t) = 20000*0.85^t.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3cb4121-c5be-49e8-8c8f-94569fa9894c', 'NC26.M1.ANFR.4', 2, 'choice', 'Write and use an exponential function from a situation', 'A channel has 2000 followers and gains 12% more followers each month. Which function gives the number of followers $F$ after $m$ months?', '["$F(m) = 2000 \\cdot 1.12^m$","$F(m) = 2000 \\cdot 0.12^m$","$F(m) = 2000 \\cdot 12^m$","$F(m) = 2000 + 0.12m$"]', '$F(m) = 2000 \cdot 1.12^m$', NULL, 'A 12% gain multiplies the number by $1 + 0.12 = 1.12$ each month: $F(m) = 2000 \cdot 1.12^m$.', 'checked', '{"lint":[],"solve":{"answer":"$F(m) = 2000 \\cdot 1.12^m$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grows 12% each month: factor 1.12. F(m) = 2000*1.12^m.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d6e0fe9-558f-431c-bd2c-532986de65d7', 'NC26.M1.ANFR.4', 2, 'choice', 'Write and use an exponential function from a situation', 'A sample of 80 grams of a substance halves in mass every year. Which function gives the mass $M$, in grams, after $t$ years?', '["$M(t) = 80 - \\frac{1}{2}t$","$M(t) = \\frac{1}{2} \\cdot 80^t$","$M(t) = 80 \\cdot 2^t$","$M(t) = 80 \\cdot (\\frac{1}{2})^t$"]', '$M(t) = 80 \cdot (\frac{1}{2})^t$', NULL, 'The mass starts at 80 and is multiplied by $\frac{1}{2}$ each year: $M(t) = 80 \cdot (\frac{1}{2})^t$.', 'checked', '{"lint":[],"solve":{"answer":"$M(t) = 80 \\cdot (\\frac{1}{2})^t$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Halves each year: M(t) = 80*(1/2)^t.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0372fb5b-7398-42d6-9b73-9303f404a7a7', 'NC26.M1.ANFR.4', 2, 'numeric', 'Write and use an exponential function from a situation', 'A new phone is worth 800 dollars and loses half of its value each year. How many dollars is it worth after 3 years?', '[]', '100', '800/2^3', 'Halve three times: 800, 400, 200, 100. After 3 years it is worth 100 dollars.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800 -> 400 -> 200 -> 100 after 3 years.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
