INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b371d7-aa28-485a-a395-239e82a4428a', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a line in slope-intercept form', 'A line has slope 2 and passes through the point $(1, 4)$. Which is its equation?', '["$y = 2x + 4$","$y = 2x + 3$","$y = 2x + 2$","$y = 2x + 6$"]', '$y = 2x + 2$', NULL, 'Put $m = 2$, $x = 1$, $y = 4$ into $y = mx + b$: $4 = 2 + b$, so $b = 2$ and $y = 2x + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 = 2*1 + b, b = 2. y = 2x + 2.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca567cc4-e272-45de-8a65-0e812a175b82', 'NC26.M1.ANFR.4', 2, 'numeric', 'Write a line in slope-intercept form', 'A linear function has these values: when $x$ is 0, 1, 2, 3, the value of $y$ is 4, 7, 10, 13. What is $y$ when $x = 10$?', '[]', '34', '3*10+4', '$y$ rises by 3 each time $x$ rises by 1, and $y = 4$ at $x = 0$. So $y = 3x + 4$, and at $x = 10$, $y = 34$.', 'checked', '{"lint":[],"solve":{"answer":"34","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope 3, intercept 4: y = 3x + 4. At x = 10, y = 34.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e4f3c881-af43-479f-9650-359717982802', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a line in slope-intercept form', 'A line passes through the points $(2, 3)$ and $(4, 11)$. Which equation represents the line?', '["$y = 4x + 5$","$y = 4x - 5$","$y = 4x + 3$","$y = \\frac{1}{4}x - 5$"]', '$y = 4x - 5$', NULL, 'The slope is $\frac{11 - 3}{4 - 2} = 4$. Using $(2, 3)$: $3 = 4 \cdot 2 + b$, so $b = -5$ and $y = 4x - 5$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x - 5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (11-3)/(4-2) = 4. 3 = 4*2 + b, b = -5. y = 4x - 5. Check (4, 11): 16 - 5 = 11.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('195f395b-ae54-4815-a2db-36708e5cbbc3', 'NC26.M1.ANFR.4', 2, 'numeric', 'Write a line in slope-intercept form', 'A line passes through the points $(-1, 7)$ and $(2, -2)$. What is its slope?', '[]', '-3', '(-2-7)/(2-(-1))', 'Slope $= \frac{-2 - 7}{2 - (-1)} = \frac{-9}{3} = -3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-2 - 7)/(2 - (-1)) = -9/3 = -3.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
