INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dc37dabe-e580-4c30-b03e-f85b2fe7711a', 'NC26.M1.ANFR.4', 2, 'choice', 'Write a line in slope-intercept form', 'Which equation is $2x + y = 10$ written in slope-intercept form?', '["$y = -2x + 10$","$y = 2x + 10$","$y = -2x - 10$","$y = 2x - 10$"]', '$y = -2x + 10$', NULL, 'Subtract $2x$ from both sides: $y = -2x + 10$.', 'checked', '{"lint":[],"solve":{"answer":"$y = -2x + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 10 - 2x = -2x + 10.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
