INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b59affc1-6b1d-4c19-9c77-ecc83940aab8', 'NC26.M1.ANFR.4', 2, 'choice', 'Choose a linear or exponential model', 'Which situation is best modeled by an exponential function?', '["A bank balance of 1000 dollars grows by 4% each year","A plumber charges 40 dollars plus 30 dollars per hour","A sunflower grows 3 centimeters each day","A bus travels at 50 miles per hour"]', 'A bank balance of 1000 dollars grows by 4% each year', NULL, 'A percent growth multiplies the amount by the same factor each period, which is exponential. The other three add the same amount each time, which is linear.', 'checked', '{"lint":[],"solve":{"answer":"A bank balance of 1000 dollars grows by 4% each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth by a fixed percent (4% per year) is exponential; the others are constant rates (linear).","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
