INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c84d0c82-2095-4f60-82a1-330744a2e133', 'NC26.M1.ANFR.4', 2, 'choice', 'Choose a linear or exponential model', 'For $x = 0, 1, 2, 3$, which list of $y$-values comes from a linear function?', '["$y = 4, 8, 16, 32$","$y = 4, 6, 9, 13$","$y = 4, 7, 10, 13$","$y = 4, 12, 36, 108$"]', '$y = 4, 7, 10, 13$', NULL, 'Only 4, 7, 10, 13 goes up by the same amount (3) each time. The others are multiplied by a constant (2 or 3) or have changing differences.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4, 7, 10, 13$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4, 7, 10, 13 has constant difference 3. 4, 6, 9, 13 has differences 2, 3, 4; others are geometric.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
