INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8f9e226-d53c-4900-917d-fe2a4b3b1685', 'NC26.M1.ANFR.4', 2, 'numeric', 'Choose a linear or exponential model', 'A function has $f(0) = 3$, $f(1) = 6$ and $f(2) = 12$, and it is exponential. What is $f(4)$?', '[]', '48', '3*2^4', 'Each value is twice the one before, so $f(x) = 3 \cdot 2^x$. Then $f(4) = 3 \cdot 16 = 48$.', 'checked', '{"lint":[],"solve":{"answer":"48","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = 3, b = 2: f(4) = 3*16 = 48.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
