INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5778e7d-02fe-4296-afd1-373f9ea6c5eb', 'NC26.M1.ANFR.4', 3, 'numeric', 'Evaluate a recursive rule for an arithmetic sequence', 'A sequence has $a_1 = 50$ and $a_n = a_{n-1} - 8$ for $n \ge 2$. What is the first negative term of the sequence?', '[]', '-6', '50-8*7', 'The terms are 50, 42, 34, 26, 18, 10, 2, -6. The first negative term is $a_8 = 50 - 8 \cdot 7 = -6$.', 'checked', '{"lint":[],"solve":{"answer":"-6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50, 42, 34, 26, 18, 10, 2, -6. First negative term is -6.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
