INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('29be13a3-94ea-45e0-8267-dc7e25e973a7', 'NC26.M1.ANFR.4', 3, 'numeric', 'Choose a linear or exponential model', 'What is the least positive whole number $x$ for which $2^x$ is greater than $10x$?', '[]', '6', NULL, '$x = 5$: $2^5 = 32$ and $10 \cdot 5 = 50$, so no. $x = 6$: $2^6 = 64$ and $10 \cdot 6 = 60$, so yes. Smaller values fail too ($2 < 10$, $4 < 20$, $8 < 30$, $16 < 40$).', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=1: 2 vs 10; x=2: 4 vs 20; x=3: 8 vs 30; x=4: 16 vs 40; x=5: 32 vs 50; x=6: 64 vs 60 -> true. Least is 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42f0c8f0-9f11-4209-a147-691e7fac7b8b', 'NC26.M1.ANFR.4', 3, 'numeric', 'Choose a linear or exponential model', 'Plan A starts with 100 dollars and adds 20 dollars each month. Plan B starts with 100 dollars and grows by 20% each month. How many more dollars does Plan B have than Plan A after 3 months?', '[]', '12.8', '100*1.2^3-(100+20*3)', 'Plan A has $100 + 20 \cdot 3 = 160$ dollars. Plan B has $100 \cdot 1.2^3 = 172.8$ dollars. The difference is $172.8 - 160 = 12.8$.', 'checked', '{"lint":[],"solve":{"answer":"12.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 100 + 3*20 = 160. B: 100*1.2^3 = 100*1.728 = 172.8. Difference 12.8.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed1d7cc2-b272-4f8c-9766-51d9cdbd48b5', 'NC26.M1.ANFR.4', 3, 'numeric', 'Interpret the parts of a linear or exponential function', 'A population grows by 20% each year. By what percent has it grown in total after 2 years?', '[]', '44', '(1.2^2-1)*100', 'After 2 years the population is multiplied by $1.2^2 = 1.44$. That is a total increase of 44%, not 40%.', 'checked', '{"lint":[],"solve":{"answer":"44","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.2^2 = 1.44, so total growth 44%.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8929cd27-4092-48e0-8968-58c732099e72', 'NC26.M1.ANFR.4', 3, 'choice', 'Interpret the parts of a linear or exponential function', 'The function $f(x) = a \cdot b^x$ has $f(0) = 8$ and $f(1) = 12$. Which statement is true about $f$?', '["$f$ increases by 4 each time $x$ increases by 1","$f$ increases by 50% each time $x$ increases by 1","$f$ increases by 12% each time $x$ increases by 1","$f$ doubles each time $x$ increases by 1"]', '$f$ increases by 50% each time $x$ increases by 1', NULL, '$f(0) = a = 8$ and $f(1) = 8b = 12$, so $b = 1.5$. A factor of 1.5 is an increase of 50% each step. (Going from 8 to 12 is a rise of 4 only the first time.)', 'checked', '{"lint":[],"solve":{"answer":"$f$ increases by 50% each time $x$ increases by 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a = 8, b = 12/8 = 1.5: increases by 50% per unit of x.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f5d3ffd-a844-440a-b7d6-d430502e6898', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write and use an explicit rule for a sequence', 'The explicit rule for a sequence is $a_n = 5 \cdot 2^{n-1}$. Which term number $n$ has the value 320?', '[]', '7', '7', '$5 \cdot 2^{n-1} = 320$ gives $2^{n-1} = 64 = 2^6$, so $n - 1 = 6$ and $n = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5*2^(n-1) = 320, 2^(n-1) = 64, n-1 = 6, n = 7.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('83752e9b-5f57-42ae-8854-de6eb23c5897', 'NC26.M1.ANFR.4', 3, 'choice', 'Write and use an explicit rule for a sequence', 'A sequence has the recursive rule $a_1 = 6$ and $a_n = a_{n-1} + 4$. Which explicit rule gives the same sequence?', '["$a_n = 4n + 6$","$a_n = 4n + 2$","$a_n = 6n + 4$","$a_n = 4n - 2$"]', '$a_n = 4n + 2$', NULL, 'The terms are 6, 10, 14, ..., so the rule is $4n + b$. At $n = 1$, $4 + b = 6$ gives $b = 2$: $a_n = 4n + 2$.', 'checked', '{"lint":[],"solve":{"answer":"$a_n = 4n + 2$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a_n = 6 + 4(n-1) = 4n + 2. Check n=1: 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f6a90908-3252-4a4f-8737-e3757d70fe82', 'NC26.M1.ANFR.4', 3, 'numeric', 'Write and use an explicit rule for a sequence', 'The first level of a parking garage has 140 spaces, and each higher level has 6 fewer spaces than the level below it. How many spaces are on level 15?', '[]', '56', '140-6*14', 'Level 15 is 14 levels above level 1, so it has $140 - 6 \cdot 14 = 140 - 84 = 56$ spaces.', 'checked', '{"lint":[],"solve":{"answer":"56","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"140 - 6*(15-1) = 140 - 84 = 56.","run_id":"claude-code","at":"2026-10-18T01:05:46.600Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a652008c-eb8c-4321-a96e-4a63cea25592', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a one-step-plus-one linear equation', 'Solve for $x$: $3x + 5 = 20$.', '[]', '5', '(20-5)/3', 'Subtract 5 from both sides: $3x = 15$. Divide both sides by 3: $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x = 15, x = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
