VALUES ('db3632fc-e30a-422a-9de2-c625e19e5c83', 'NC26.M1.ANFR.5', 1, 'choice', 'Solve a linear equation in one variable', 'Which value of $x$ makes $4x - 5 = 11$ true?', '["1.5","16","6","4"]', '4', '(11+5)/4', 'Add 5 to both sides: $4x = 16$. Divide by 4: $x = 4$. Check: $4 \cdot 4 - 5 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 5 = 11 -> 4x = 16 -> x = 4. Check: 16 - 5 = 11.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
