INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9cf4931-50a1-4f1c-877f-57647f507df9', 'NC26.M1.ANFR.5', 1, 'numeric', 'Solve a formula for a quantity', 'The mean of two test scores is $A = \frac{x + y}{2}$. A student''s mean is 84 and the first score $x$ is 79. What is the second score $y$?', '[]', '89', '2*84-79', 'Multiply both sides by 2: $x + y = 168$. Then $y = 168 - 79 = 89$.', 'checked', '{"lint":[],"solve":{"answer":"89","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"84 = (79 + y)/2 -> 168 = 79 + y -> y = 89.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
