INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86c72f5e-d802-4246-a317-5979ec2b4907', 'NC26.M1.ANFR.5', 1, 'choice', 'Write an exponential equation from a situation', 'A 400-milligram dose of medicine halves every hour. Which equation can be solved to find the number of hours $t$ until 25 milligrams remain?', '["$400 - \\frac{1}{2}t = 25$","$400 \\cdot (\\frac{1}{2})^t = 25$","$400 \\cdot 2^t = 25$","$\\frac{1}{2} \\cdot 400^t = 25$"]', '$400 \cdot (\frac{1}{2})^t = 25$', NULL, 'The amount starts at 400 and is multiplied by $\frac{1}{2}$ each hour, so after $t$ hours it is $400 \cdot (\frac{1}{2})^t$.', 'checked', '{"lint":[],"solve":{"answer":"$400 \\cdot (\\frac{1}{2})^t = 25$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Amount = 400 * (1/2)^t; set equal to 25: 400 * (1/2)^t = 25 (t = 4).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
