INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ae2b8f8-5aa4-4dcd-9fea-d16936c8e955', 'NC26.M1.ANFR.5', 1, 'choice', 'Interpret the solution of an equation or inequality', 'The equation $7.5h + 12 = 57$ models total pay in dollars for $h$ hours of work, including a 12 dollar bonus. Its solution is $h = 6$. What does the solution tell us?', '["Working 57 hours earns a total of 6 dollars","The hourly pay is 6 dollars","Working 6 hours earns a total of 57 dollars","The bonus is 6 dollars"]', 'Working 6 hours earns a total of 57 dollars', NULL, 'The equation asks for the hours that give a total of 57 dollars. The solution $h = 6$ means 6 hours of work gives 57 dollars.', 'checked', '{"lint":[],"solve":{"answer":"Working 6 hours earns a total of 57 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"h = 6 hours gives total pay 7.5(6) + 12 = 57 dollars. So working 6 hours earns 57 dollars in total.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
