INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f88c67e-9d84-40fb-8b27-a38e731590bb', 'NC26.M1.ANFR.5', 1, 'choice', 'Write and solve a linear equation or inequality from a situation', 'Sam has 15 stickers and buys packs of 6 stickers. He wants 51 stickers in all. Which equation can be solved to find the number of packs $p$?', '["$6 + 15p = 51$","$21p = 51$","$15 + 6p = 51$","$15 \\cdot 6p = 51$"]', '$15 + 6p = 51$', NULL, 'He starts with 15 and adds 6 stickers for each pack: $15 + 6p = 51$.', 'checked', '{"lint":[],"solve":{"answer":"$15 + 6p = 51$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Start 15, plus 6 per pack: 15 + 6p = 51 (p = 6).","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
