INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b3bb865a-8ff7-40a8-9498-d8e4ee986282', 'NC26.M1.ANFR.5', 1, 'choice', 'Write and solve a linear equation or inequality from a situation', 'Which inequality states "3 less than twice a number is at most 9"?', '["$2n - 3 \\ge 9$","$2(n - 3) \\le 9$","$3 - 2n \\le 9$","$2n - 3 \\le 9$"]', '$2n - 3 \le 9$', NULL, '"Twice a number" is $2n$, "3 less than" that is $2n - 3$, and "at most 9" means $\le 9$.', 'checked', '{"lint":[],"solve":{"answer":"$2n - 3 \\le 9$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Twice a number: 2n; 3 less than that: 2n - 3; at most 9: <= 9. So 2n - 3 <= 9.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8df55f7c-ad0b-4c2b-bbc8-947cdff2c1ae', 'NC26.M1.ANFR.5', 1, 'numeric', 'Write and solve a linear equation or inequality from a situation', 'Adult tickets cost 8 dollars and child tickets cost 5 dollars. A theater sold 12 adult tickets and some child tickets for a total of 126 dollars. How many child tickets were sold?', '[]', '6', '(126-12*8)/5', 'Adult tickets bring in $12 \cdot 8 = 96$ dollars. The child tickets bring in $126 - 96 = 30$ dollars, so $30 \div 5 = 6$ child tickets.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8(12) + 5c = 126 -> 96 + 5c = 126 -> 5c = 30 -> c = 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('79f5fc23-b6eb-491d-b0b2-3bb7647f7338', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear inequality, reversing the sign', 'Solve the inequality $-2x + 3 < 11$.', '["$x < -4$","$x > 4$","$x < 4$","$x > -4$"]', '$x > -4$', NULL, 'Subtract 3 from both sides: $-2x < 8$. Dividing both sides by $-2$ reverses the inequality sign: $x > -4$.', 'checked', '{"lint":[],"solve":{"answer":"$x > -4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-2x + 3 < 11 -> -2x < 8 -> divide by -2 and flip: x > -4. Check x = 0: 3 < 11 true.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c9fe7a4c-d1cc-4572-9e15-5aff7fdf5f47', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a formula for a quantity, given a value', 'The formula $F = \frac{9}{5}C + 32$ changes a temperature in degrees Celsius $C$ to degrees Fahrenheit $F$. A temperature is 68 degrees Fahrenheit. What is it in degrees Celsius?', '[]', '20', '(68-32)*5/9', 'Put $F = 68$ in the formula: $68 = \frac{9}{5}C + 32$. Subtract 32: $36 = \frac{9}{5}C$. Multiply by $\frac{5}{9}$: $C = 36 \times \frac{5}{9} = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"68 = (9/5)C + 32 -> (9/5)C = 36 -> C = 36 * 5/9 = 20.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('90c25faa-1050-4d16-8a75-58c5016fcfda', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a simple exponential equation in context', 'A culture starts with 3 bacteria and triples every hour, so after $t$ hours it has $3 \cdot 3^t$ bacteria. After how many hours are there 243 bacteria?', '[]', '4', '4', 'Solve $3 \cdot 3^t = 243$. Divide by 3: $3^t = 81$. Since $3^4 = 81$, $t = 4$ hours. (Check: 3, 9, 27, 81, 243.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 * 3^t = 243 -> 3^t = 81 = 3^4 -> t = 4. Check: 3 * 81 = 243.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('06de6617-d335-443d-8a29-70e4d9099200', 'NC26.M1.ANFR.5', 2, 'choice', 'Justify the steps in solving an equation', 'A student rewrites $5x - 2x + 4 = 19$ as $3x + 4 = 19$. What justifies this step?', '["Division property of equality","Addition property of equality","Multiplication property of equality","Combining like terms"]', 'Combining like terms', NULL, '$5x$ and $-2x$ are like terms, and combining them gives $3x$. Nothing is done to both sides.', 'checked', '{"lint":[],"solve":{"answer":"Combining like terms","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 2x = 3x on the left side only: combining like terms.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
