INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8936052-394e-4f3d-ab58-c87ba6d167e6', 'NC26.M1.ANFR.5', 2, 'numeric', 'Justify the steps in solving an equation', 'In solving $6x + 5 = 2x + 21$, a student subtracts $2x$ from both sides and then subtracts 5 from both sides, giving $4x = c$. What is $c$?', '[]', '16', '21-5', 'After subtracting $2x$: $4x + 5 = 21$. After subtracting 5: $4x = 16$. So $c = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x + 5 = 2x + 21; subtract 2x: 4x + 5 = 21; subtract 5: 4x = 16. c = 16.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('458c302c-9dcd-4073-8001-7913baeee490', 'NC26.M1.ANFR.5', 2, 'choice', 'Justify the steps in solving an equation', 'A student solves $-3x \ge 12$ and writes $x \le -4$. Which statement justifies reversing the inequality sign?', '["Dividing both sides of an inequality by a positive number reverses the inequality sign","Subtracting a number from both sides of an inequality reverses the inequality sign","The sign always reverses when the answer is negative","Dividing both sides of an inequality by a negative number reverses the inequality sign"]', 'Dividing both sides of an inequality by a negative number reverses the inequality sign', NULL, 'The student divided both sides by $-3$. Dividing (or multiplying) by a negative number flips the direction of the inequality: $x \le -4$.', 'checked', '{"lint":[],"solve":{"answer":"Dividing both sides of an inequality by a negative number reverses the inequality sign","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-3x >= 12, divide by -3: x <= -4. The reversal is because both sides were divided by a negative number.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88175f15-a0f5-4d47-a2e8-eb2d08c1cbf9', 'NC26.M1.ANFR.5', 2, 'choice', 'Justify the steps in solving an equation', 'A student solves $2(x - 3) = 10$ and writes $2x - 3 = 10$ as the first line. Which property was applied incorrectly?', '["Division property of equality","Addition property of equality","Distributive property","Combining like terms"]', 'Distributive property', NULL, 'The 2 must multiply both terms in the parentheses: $2(x - 3) = 2x - 6$. The student multiplied only the first term.', 'checked', '{"lint":[],"solve":{"answer":"Distributive property","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(x - 3) should be 2x - 6; writing 2x - 3 means the 2 was not distributed to the -3: distributive property misapplied.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('df4d835e-6557-4439-9e5d-c9359464f0af', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $5(x - 2) = 3x + 6$.', '[]', '8', '(6+10)/2', 'Distribute: $5x - 10 = 3x + 6$. Subtract $3x$: $2x - 10 = 6$. Add 10: $2x = 16$. So $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x - 10 = 3x + 6 -> 2x = 16 -> x = 8. Check: 5(6) = 30, 24 + 6 = 30.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('580faadb-7536-46bc-872d-613277fa4ed5', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear equation in one variable', 'Solve for $x$: $7 - 3x = 2x - 13$.', '[]', '4', '(7+13)/5', 'Add $3x$ to both sides: $7 = 5x - 13$. Add 13: $20 = 5x$. So $x = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 - 3x = 2x - 13 -> 20 = 5x -> x = 4. Check: 7 - 12 = -5, 8 - 13 = -5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
