INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80599dec-a7a9-4fa4-949c-30d12a8dc9ac', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear equation in one variable', 'Solve for $x$: $\frac{2}{3}x + 4 = 10$.', '["21","4","9","6"]', '9', '(10-4)*3/2', 'Subtract 4: $\frac{2}{3}x = 6$. Multiply by $\frac{3}{2}$: $x = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2/3)x + 4 = 10 -> (2/3)x = 6 -> x = 6 * 3/2 = 9.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
