INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('86da207b-b51f-426c-80e9-ae6dadc31cab', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear inequality in one variable', 'What is the greatest whole number that satisfies $4x - 7 < 21$?', '[]', '6', NULL, 'Add 7: $4x < 28$. Divide by 4: $x < 7$. The greatest whole number less than 7 is 6.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x - 7 < 21 -> 4x < 28 -> x < 7. Greatest whole number 6.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
