INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('63486b96-a9fe-4e3b-ac03-cb78e5a2003a', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a linear inequality in one variable', 'How many positive whole numbers satisfy $2x + 3 \le 17$?', '[]', '7', '(17-3)/2', 'Subtract 3: $2x \le 14$, so $x \le 7$. The positive whole numbers 1, 2, 3, 4, 5, 6, 7 all work, which is 7 numbers.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 3 <= 17 -> 2x <= 14 -> x <= 7. Positive whole numbers 1 through 7: 7 of them.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
