INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af01bbf8-3792-492a-ba63-4ddecc67cf51', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a linear inequality in one variable', 'Which number is a solution of $-4x + 2 > 10$?', '["-2","0","2","-3"]', '-3', NULL, 'Subtract 2: $-4x > 8$. Dividing by $-4$ reverses the sign: $x < -2$. Of the choices, only $-3$ is less than $-2$. (Check: $-4(-3) + 2 = 14 > 10$.)', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-4x + 2 > 10 -> -4x > 8 -> x < -2. Options: 0 no, -3 yes (12 + 2 = 14 > 10), 2 no, -2 gives 10 > 10 false. Only -3.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
