INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f33047c8-a459-4016-8b0b-a3882eb1e0d7', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a formula for a quantity', 'Solve the formula $y = mx + b$ for $x$.', '["$x = \\frac{y}{m} + b$","$x = y - b - m$","$x = \\frac{y + b}{m}$","$x = \\frac{y - b}{m}$"]', '$x = \frac{y - b}{m}$', NULL, 'Subtract $b$ from both sides: $y - b = mx$. Divide both sides by $m$: $x = \frac{y - b}{m}$.', 'checked', '{"lint":[],"solve":{"answer":"$x = \\frac{y - b}{m}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = mx + b -> y - b = mx -> x = (y - b)/m.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0bd64c52-0611-4333-a967-cf21df064e50', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve a formula for a quantity', 'The simple interest formula is $I = Prt$. A loan of 600 dollars earned 90 dollars in interest over 3 years. What is the yearly rate $r$, written as a decimal?', '[]', '0.05', '90/(600*3)', 'Solve for $r$: $r = \frac{I}{Pt} = \frac{90}{600 \cdot 3} = \frac{90}{1800} = 0.05$.', 'checked', '{"lint":[],"solve":{"answer":"0.05","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"I = Prt -> r = I/(Pt) = 90/(600*3) = 90/1800 = 0.05.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fff136b0-b618-4a94-ae9a-1077c5ca3912', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve a formula for a quantity', 'Solve the equation $3x + 2y = 12$ for $y$.', '["$y = \\frac{12 + 3x}{2}$","$y = \\frac{12 - 3x}{2}$","$y = 12 - 3x$","$y = 6 - 3x$"]', '$y = \frac{12 - 3x}{2}$', NULL, 'Subtract $3x$: $2y = 12 - 3x$. Divide every term by 2: $y = \frac{12 - 3x}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"$y = \\frac{12 - 3x}{2}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2y = 12 -> 2y = 12 - 3x -> y = (12 - 3x)/2. (6 - 3x is wrong: only 12 was halved.)","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6741f74-f2e7-4e59-bdb6-4d684aa94eb1', 'NC26.M1.ANFR.5', 2, 'choice', 'Write an exponential equation from a situation', 'A town of 12000 people grows 3% each year. Which equation can be solved to find the number of years $t$ until the population is 15000?', '["$12000 \\cdot 1.03^t = 15000$","$12000 \\cdot 0.03^t = 15000$","$12000 + 0.03t = 15000$","$12000 \\cdot 3^t = 15000$"]', '$12000 \cdot 1.03^t = 15000$', NULL, 'A 3% increase multiplies the population by 1.03 each year, so after $t$ years it is $12000 \cdot 1.03^t$.', 'checked', '{"lint":[],"solve":{"answer":"$12000 \\cdot 1.03^t = 15000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Growth 3% per year: factor 1.03. 12000 * 1.03^t = 15000.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('157e44a6-6931-400e-af2f-41e91d5bbdf3', 'NC26.M1.ANFR.5', 2, 'choice', 'Write an exponential equation from a situation', 'A truck worth 18000 dollars loses 12% of its value each year. Which equation can be solved to find the number of years $t$ until it is worth 9000 dollars?', '["$18000 \\cdot 0.88^t = 9000$","$18000 \\cdot 0.12^t = 9000$","$18000 \\cdot 1.12^t = 9000$","$18000 - 0.12t = 9000$"]', '$18000 \cdot 0.88^t = 9000$', NULL, 'Losing 12% leaves 88% of the value each year, so the value after $t$ years is $18000 \cdot 0.88^t$.', 'checked', '{"lint":[],"solve":{"answer":"$18000 \\cdot 0.88^t = 9000$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Loses 12% per year: factor 1 - 0.12 = 0.88. 18000 * 0.88^t = 9000.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9c24567-6ca9-49c3-9360-170ea8aa6f3f', 'NC26.M1.ANFR.5', 2, 'numeric', 'Write an exponential equation from a situation', 'A drug amount halves every 4 hours. Starting from 120 milligrams, the equation $120 \cdot (\frac{1}{2})^n = 7.5$ gives the number of 4-hour periods $n$ until 7.5 milligrams remain. What is $n$?', '[]', '4', NULL, 'Divide by 120: $(\frac{1}{2})^n = \frac{7.5}{120} = \frac{1}{16}$. Since $2^4 = 16$, $n = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)^n = 7.5/120 = 1/16 = (1/2)^4 -> n = 4.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('92c39aa5-1022-4031-b038-c3f20041bcea', 'NC26.M1.ANFR.5', 2, 'numeric', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $7 \cdot 2^x = 224$.', '[]', '5', NULL, 'Divide by 7: $2^x = 32$. Since $2^5 = 32$, $x = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 * 2^x = 224 -> 2^x = 32 -> x = 5.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3e4e971-2767-4a98-98ed-ca236b19bbd7', 'NC26.M1.ANFR.5', 2, 'choice', 'Solve an exponential equation with a table or by reasoning', 'Solve for $x$: $100 \cdot (\frac{1}{2})^x = 12.5$.', '["8","4","3","6"]', '3', '3', 'Divide by 100: $(\frac{1}{2})^x = 0.125 = \frac{1}{8}$. Since $(\frac{1}{2})^3 = \frac{1}{8}$, $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"100 (1/2)^x = 12.5 -> (1/2)^x = 0.125 = 1/8 -> x = 3.","run_id":"claude-code","at":"2026-10-18T01:05:46.640Z"}}', 'ai', NULL, NULL)
