INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d13fc39-a467-46e5-93cb-7251e7426ebb', 'NC26.M1.ANFR.6', 1, 'choice', 'Decide which side is shaded', 'The inequality $x < 4$ is graphed on a coordinate plane. Which part is shaded?', '["The region to the right of the vertical line $x = 4$","The region above the horizontal line $y = 4$","The region to the left of the vertical line $x = 4$","The region below the horizontal line $y = 4$"]', 'The region to the left of the vertical line $x = 4$', NULL, 'The boundary is the vertical line $x = 4$. Solutions have $x$-values less than 4, which are the points to the left of the line.', 'checked', '{"lint":[],"solve":{"answer":"The region to the left of the vertical line $x = 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x < 4: all points left of the vertical line x = 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
