INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2002dd62-93cd-4d80-829a-fa0bc8c58bd2', 'NC26.M1.ANFR.6', 1, 'numeric', 'Intercepts of the boundary line', 'What is the $x$-intercept of the boundary line of $2x + 5y \le 20$? Give the $x$-coordinate.', '[]', '10', '20/2', 'The line crosses the $x$-axis where $y = 0$. Then $2x = 20$, so $x = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 0: 2x = 20, x = 10.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
