INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0f15053-8066-4bb1-9ecf-49ffb6b7526d', 'NC26.M1.ANFR.6', 1, 'numeric', 'Greatest or least value of one variable', 'A basket holds at most 20 pieces of fruit, $a$ apples and $p$ pears, so $a + p \le 20$. If the basket has 8 apples, what is the greatest whole number of pears it can have?', '[]', '12', '20-8', 'With $a = 8$: $8 + p \le 20$, so $p \le 12$. The greatest number of pears is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8 + p <= 20 -> p <= 12.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
