INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d456565-4ec3-467f-8eca-955173f84f1f', 'NC26.M1.ANFR.6', 2, 'numeric', 'Interpret a solution of an inequality in context', 'A school buys $x$ notebooks at 3 dollars each and $y$ pens at 2 dollars each. Its budget is 60 dollars, so $3x + 2y \le 60$. If the school buys 12 notebooks, what is the greatest number of pens it can buy?', '[]', '12', '(60-3*12)/2', 'With $x = 12$: $36 + 2y \le 60$, so $2y \le 24$ and $y \le 12$. The greatest number of pens is 12.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(12) + 2y <= 60 -> 2y <= 24 -> y <= 12. Greatest 12.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8ec0be2-f67f-41da-b7ab-3febac86137f', 'NC26.M1.ANFR.6', 2, 'choice', 'Find a point that is not a solution', 'Which point is NOT a solution of $2x + 3y \le 12$?', '["$(0, 0)$","$(3, 2)$","$(-2, 4)$","$(6, 1)$"]', '$(6, 1)$', NULL, 'Test each point. $(0, 0)$: $0 \le 12$ is true. $(3, 2)$: $6 + 6 = 12 \le 12$ is true. $(-2, 4)$: $-4 + 12 = 8 \le 12$ is true. $(6, 1)$: $12 + 3 = 15 \le 12$ is false.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3,2): 6 + 6 = 12 <= 12 yes. (6,1): 12 + 3 = 15 > 12 NOT a solution. (-2,4): -4 + 12 = 8 yes. (0,0): 0 yes.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('62649bf7-b093-4b2d-9b35-c79b28c9538d', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a context', 'Ava jogs at 6 miles per hour for $j$ hours and walks at 3 miles per hour for $w$ hours. She wants to cover more than 15 miles in all. Which inequality models this?', '["$6j + 3w \\ge 15$","$3j + 6w > 15$","$6j + 3w > 15$","$6j + 3w < 15$"]', '$6j + 3w > 15$', NULL, 'Distance is rate times time: $6j$ miles jogging and $3w$ miles walking. "More than 15" does not include 15, so the symbol is $>$: $6j + 3w > 15$.', 'checked', '{"lint":[],"solve":{"answer":"$6j + 3w > 15$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance 6j + 3w, \"more than 15\": strict >.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74711309-f18b-4e27-a200-dbb73a8795d3', 'NC26.M1.ANFR.6', 2, 'numeric', 'Write an inequality from a context', 'A trainer charges 30 dollars an hour for private lessons ($p$ hours) and 15 dollars an hour for group lessons ($g$ hours). To earn at least 450 dollars, $30p + 15g \ge 450$. Dividing every term by 15 gives $2p + g \ge M$. What number is $M$?', '[]', '30', '450/15', 'Divide each term by 15: $30p \div 15 = 2p$, $15g \div 15 = g$ and $450 \div 15 = 30$. The inequality is $2p + g \ge 30$, so $M = 30$.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"30/15 = 2, 15/15 = 1, 450/15 = 30, so 2p + g >= 30.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a3e45df-c562-40bf-90b5-7b1ee94868e8', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a context', 'Noah has 80 dollars. He buys $s$ shirts at 15 dollars each and $h$ hats at 9 dollars each, and he also pays one shipping fee of 5 dollars. Which inequality shows what he can buy?', '["$15s + 9h \\le 85$","$15s + 9h + 5 \\ge 80$","$15s + 14h \\le 80$","$15s + 9h + 5 \\le 80$"]', '$15s + 9h + 5 \le 80$', NULL, 'Shirts cost $15s$ and hats cost $9h$. The 5 dollar fee is paid once, so it is added once to the total: $15s + 9h + 5$. He can spend at most 80 dollars, so $15s + 9h + 5 \le 80$.', 'checked', '{"lint":[],"solve":{"answer":"$15s + 9h + 5 \\le 80$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cost 15s + 9h plus the 5 dollar fee, at most 80: 15s + 9h + 5 <= 80.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d10c39d-85e8-48a1-b31b-a52a429326c2', 'NC26.M1.ANFR.6', 2, 'choice', 'Test a point in a linear inequality', 'Which point is a solution of $3x - 2y > 5$?', '["$(3, 1)$","$(1, -1)$","$(2, 2)$","$(-2, -5)$"]', '$(3, 1)$', NULL, 'Test each point in $3x - 2y > 5$. $(3, 1)$ gives $9 - 2 = 7$, and $7 > 5$ is true. $(1, -1)$ gives $3 + 2 = 5$, which is not greater than 5. $(2, 2)$ gives $2$, and $(-2, -5)$ gives $-6 + 10 = 4$. Only $(3, 1)$ works.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 2y: (-2,-5) 4; (1,-1) 5 (not > 5); (2,2) 2; (3,1) 7 > 5 yes.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('27ae06d6-8268-4ad3-96d2-4a417f768e3a', 'NC26.M1.ANFR.6', 2, 'numeric', 'Test a point in a linear inequality', 'How many of the points $(-1, 2)$, $(0, -4)$, $(3, -2)$, $(-5, 0)$ and $(2, 1)$ make $y \ge 2x - 3$ true?', '[]', '3', NULL, 'Check $y \ge 2x - 3$ at each point. $(-1, 2)$: $2 \ge -5$ true. $(0, -4)$: $-4 \ge -3$ false. $(3, -2)$: $-2 \ge 3$ false. $(-5, 0)$: $0 \ge -13$ true. $(2, 1)$: $1 \ge 1$ true. That is 3 points.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x - 3: (-1,2): 2 >= -5 yes; (0,-4): -4 >= -3 no; (3,-2): -2 >= 3 no; (-5,0): 0 >= -13 yes; (2,1): 1 >= 1 yes. 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7ddaacaf-64f9-4e52-80dc-58100410c5ca', 'NC26.M1.ANFR.6', 2, 'choice', 'Test a point in a linear inequality', 'Nia says $(4, -3)$ is a solution of $x + 2y \le -2$. Which statement is correct?', '["She is wrong, because $4 + 2(-3) = -2$ and $-2$ is not less than $-2$","She is right, because $4 + 2(-3) = -2$ and $-2 \\le -2$ is true","She is wrong, because $4 + 2(-3) = 10$ and $10 \\le -2$ is false","She is right, because $4 + (-3) = 1$ and $1 \\le 2$ is true"]', 'She is right, because $4 + 2(-3) = -2$ and $-2 \le -2$ is true', NULL, 'Substitute: $4 + 2(-3) = 4 - 6 = -2$. The inequality says "less than or equal to", and $-2 \le -2$ is true, so $(4, -3)$ is a solution and Nia is right.', 'checked', '{"lint":[],"solve":{"answer":"She is right, because $4 + 2(-3) = -2$ and $-2 \\le -2$ is true","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 + 2(-3) = -2 and -2 <= -2 is true (the symbol includes equality), so she is right.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('95b93054-e5ce-499a-ae68-f910b1f381d4', 'NC26.M1.ANFR.6', 2, 'choice', 'Interpret a solution in context', 'A club must raise at least 600 dollars. Adult tickets cost 12 dollars each ($a$ sold) and student tickets cost 8 dollars each ($s$ sold), so $12a + 8s \ge 600$. The club sells 30 adult tickets and 25 student tickets. Which statement is true?', '["The goal is met, with 40 dollars to spare","The goal is met, with exactly 600 dollars raised","The goal is not met; sales are 40 dollars short","The goal is not met; sales are 240 dollars short"]', 'The goal is not met; sales are 40 dollars short', NULL, 'Sales are $12(30) + 8(25) = 360 + 200 = 560$ dollars. Since $560 < 600$, the pair $(30, 25)$ is not a solution, and the club is $600 - 560 = 40$ dollars short.', 'checked', '{"lint":[],"solve":{"answer":"The goal is not met; sales are 40 dollars short","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12(30) + 8(25) = 360 + 200 = 560 < 600: 40 dollars short.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20ead600-45f0-4d41-826b-ea671709cec0', 'NC26.M1.ANFR.6', 2, 'numeric', 'Interpret a solution in context', 'A truck''s load limit is 2000 pounds, so $40c + 25p \le 2000$, where $c$ is the number of apple crates (40 pounds each) and $p$ is the number of pear crates (25 pounds each). A driver loads 30 apple crates and 24 pear crates. By how many pounds is the load under the limit?', '[]', '200', '2000-(40*30+25*24)', 'The load weighs $40(30) + 25(24) = 1200 + 600 = 1800$ pounds. The limit is 2000, so the load is $2000 - 1800 = 200$ pounds under it.', 'checked', '{"lint":[],"solve":{"answer":"200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40(30) + 25(24) = 1200 + 600 = 1800; 2000 - 1800 = 200.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e3311167-e6e7-4293-8d85-cfbc054d2000', 'NC26.M1.ANFR.6', 2, 'choice', 'Interpret a solution in context', 'A tutor has 20 hours a week for sessions. A group session ($g$ of them) takes 1.5 hours and a private session ($p$ of them) takes 1 hour, so $1.5g + p \le 20$. The pair $(g, p) = (8, 8)$ gives $1.5(8) + 8 = 20$. What does this tell us?', '["The tutor has 8 hours left over after these sessions","The tutor is 8 hours over the limit with these sessions","The tutor teaches 16 hours, so 4 hours are left over","The tutor uses all 20 hours, with none left over"]', 'The tutor uses all 20 hours, with none left over', NULL, 'The 8 group sessions take $1.5 \times 8 = 12$ hours and the 8 private sessions take 8 hours, a total of 20 hours. The limit is 20, so the plan fits exactly and no time is left.', 'checked', '{"lint":[],"solve":{"answer":"The tutor uses all 20 hours, with none left over","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5(8) + 8 = 12 + 8 = 20 = the limit: all 20 hours used, none left.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56e3f74d-5af9-4f2a-95f2-3e679633e692', 'NC26.M1.ANFR.6', 2, 'choice', 'Solid or dashed boundary line', 'Pens cost 2 dollars each and pads cost 5 dollars each. Which rule for the total cost gives an inequality with a dashed boundary line when graphed?', '["The total cost is less than 40 dollars","The total cost is at most 40 dollars","The total cost is at least 40 dollars","The total cost is no less than 40 dollars"]', 'The total cost is less than 40 dollars', NULL, 'A dashed line goes with a strict inequality. "Less than 40" is strict ($<$). "At most", "at least" and "no less than" all allow a total of exactly 40, so those graphs have solid lines.', 'checked', '{"lint":[],"solve":{"answer":"The total cost is less than 40 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dashed needs a strict inequality: \"less than 40\" is 2x + 5y < 40. At least / at most / no less than include equality (solid).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f1033c06-d5a3-4d9a-a97c-f9482e0e9476', 'NC26.M1.ANFR.6', 2, 'numeric', 'Solid or dashed boundary line', 'How many of these inequalities are graphed with a solid boundary line: $3x - 2y \ge 12$, $5x + y < 8$, $y \le 4x$, $x - y > 1$, $2x + 3y \ge 6$?', '[]', '3', NULL, 'Solid lines go with $\le$ and $\ge$. The inequalities $3x - 2y \ge 12$, $y \le 4x$ and $2x + 3y \ge 6$ include "or equal to". $5x + y < 8$ and $x - y > 1$ are strict. So 3 have solid lines.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solid for >= or <=: 3x - 2y >= 12, y <= 4x, 2x + 3y >= 6. That is 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d53d288-0dc8-42ac-b0bd-94bf4880cf65', 'NC26.M1.ANFR.6', 2, 'choice', 'Solid or dashed boundary line', 'Taylor graphs $y > -2x + 6$ and draws a solid boundary line. Which statement is correct?', '["The line is correct, because every graph of a linear inequality has a solid boundary","The line should be dashed, because a point on the line makes $y > -2x + 6$ false","The line should be dashed, because the slope of the line is negative","The line is correct, because a point on the line makes $y > -2x + 6$ true"]', 'The line should be dashed, because a point on the line makes $y > -2x + 6$ false', NULL, 'Take a point on the line, such as $(0, 6)$. Then $6 > 6$ is false, so points on the line are not solutions. The boundary must be dashed. The slope does not decide this.', 'checked', '{"lint":[],"solve":{"answer":"The line should be dashed, because a point on the line makes $y > -2x + 6$ false","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strict >: a point on the line gives equality, which makes > false, so the line must be dashed.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2d6b3f4-e04c-4440-a540-88632590c6a3', 'NC26.M1.ANFR.6', 2, 'choice', 'Decide which side is shaded', 'Which point cannot be used as a test point to decide which side of the line $y = 2x$ to shade?', '["$(0, 3)$","$(4, 1)$","$(0, 0)$","$(1, 6)$"]', '$(0, 0)$', NULL, 'A test point must not be on the boundary line. The point $(0, 0)$ is on $y = 2x$, since $0 = 2(0)$. The points $(0, 3)$, $(4, 1)$ and $(1, 6)$ are not on the line, so any of them works.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(0,0) satisfies y = 2x (0 = 0), so it lies on the line and cannot decide a side. (1,6), (4,1), (0,3) are off the line.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fab2d405-4627-47ec-9598-e797a6fbe0d0', 'NC26.M1.ANFR.6', 2, 'numeric', 'Decide which side is shaded', 'The point $(2, 3)$ lies in the shaded region of $4x - y > k$, where $k$ is a whole number. What is the greatest whole number $k$ can be?', '[]', '4', '5-1', 'At $(2, 3)$, $4x - y = 8 - 3 = 5$. The point is shaded only if $5 > k$. The greatest whole number less than 5 is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4(2) - 3 = 5 > k, so k < 5; greatest whole number k = 4.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b0cb0a25-6f0c-42b0-8baa-92dfd018c02f', 'NC26.M1.ANFR.6', 2, 'choice', 'Decide which side is shaded', 'The boundary line of $2x - 5y < 10$ is graphed. Testing the origin gives $0 < 10$, which is true. Which part is shaded?', '["The side not containing the origin, which is below the line","The side below the line, because the symbol is \"less than\"","The side containing the origin, which is below the line","The side containing the origin, which is above the line"]', 'The side containing the origin, which is above the line', NULL, 'Because $(0, 0)$ makes the inequality true, the shaded side is the one containing the origin. Solving gives $y > \frac{2}{5}x - 2$, and the origin has $0 > -2$, so that side is above the line. The symbol alone does not tell which side is shaded.', 'checked', '{"lint":[],"solve":{"answer":"The side containing the origin, which is above the line","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line 2x - 5y = 10 has y-intercept -2, so the origin is above it. Origin test true, so shade the side containing the origin, which is above (equivalently y > 0.4x - 2).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c118d711-66b9-4487-a7d0-cb0ab5c6e640', 'NC26.M1.ANFR.6', 2, 'numeric', 'Intercepts of the boundary line', 'The boundary line of $3x - 4y \ge 24$ crosses the $x$-axis at what $x$-value?', '[]', '8', '24/3', 'On the $x$-axis $y = 0$. The boundary line is $3x - 4y = 24$, so $3x = 24$ and $x = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 0: 3x = 24, x = 8.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb2433dc-e6ed-465e-ad18-bb1e1cd51d26', 'NC26.M1.ANFR.6', 2, 'choice', 'Intercepts of the boundary line', 'Which pair gives the intercepts of the boundary line of $5x + 2y < 30$?', '["$(6, 0)$ and $(0, 15)$","$(0, 6)$ and $(15, 0)$","$(5, 0)$ and $(0, 2)$","$(30, 0)$ and $(0, 30)$"]', '$(6, 0)$ and $(0, 15)$', NULL, 'For the $x$-intercept let $y = 0$: $5x = 30$, so $x = 6$ and the point is $(6, 0)$. For the $y$-intercept let $x = 0$: $2y = 30$, so $y = 15$ and the point is $(0, 15)$.', 'checked', '{"lint":[],"solve":{"answer":"$(6, 0)$ and $(0, 15)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 2y = 30: x-intercept 6 -> (6,0); y-intercept 15 -> (0,15).","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('865e02cf-7a49-4296-9118-cc29d35bd892', 'NC26.M1.ANFR.6', 2, 'choice', 'Write an inequality from a described graph', 'A dashed boundary line passes through $(0, 3)$ and $(2, 7)$, and the region below it is shaded. Which inequality does the graph show?', '["$y > 2x + 3$","$y < 3x + 2$","$y < 2x + 3$","$y < 4x + 3$"]', '$y < 2x + 3$', NULL, 'The slope is $\frac{7 - 3}{2 - 0} = 2$ and the $y$-intercept is 3, so the line is $y = 2x + 3$. A dashed line with shading below gives $y < 2x + 3$.', 'checked', '{"lint":[],"solve":{"answer":"$y < 2x + 3$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope (7 - 3)/(2 - 0) = 2, intercept 3: y = 2x + 3. Dashed, below: y < 2x + 3.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('458628c1-3b0b-41ce-b710-a72637aec048', 'NC26.M1.ANFR.6', 2, 'numeric', 'Write an inequality from a described graph', 'The boundary line of a graph passes through $(0, -1)$ and $(3, 5)$. What is its slope?', '[]', '2', '(5+1)/3', 'Slope is rise over run: $\frac{5 - (-1)}{3 - 0} = \frac{6}{3} = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5 - (-1)) / (3 - 0) = 6/3 = 2.","run_id":"claude-code","at":"2026-10-18T01:08:17.780Z"}}', 'ai', NULL, NULL)
