INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('850777ec-0b98-4621-bfbc-17da9723adf4', 'NC26.M1.ANFR.7', 1, 'choice', 'Count the solutions of a system', 'Two lines have different slopes. How many solutions does the system of their equations have?', '["Exactly one solution","No solution at all","Infinitely many","Exactly two solutions"]', 'Exactly one solution', NULL, 'Lines with different slopes cross exactly once, so the system has exactly one solution.', 'checked', '{"lint":[],"solve":{"answer":"Exactly one solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Different slopes intersect once.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
