INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e773dcd-cd63-4b15-95c0-05dda8ecb80f', 'NC26.M1.ANFR.7', 1, 'choice', 'Count the solutions of a system', 'The graphs of two lines are parallel and never touch. What does this tell you about the solutions of the system?', '["There is one solution","There are two solutions","There is no solution","There are infinitely many solutions"]', 'There is no solution', NULL, 'A solution is a point on both graphs. Parallel lines never share a point, so there is no solution.', 'checked', '{"lint":[],"solve":{"answer":"There is no solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel distinct lines never meet.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
