INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aeb38265-22de-4918-b3da-d7423695c64c', 'NC26.M1.ANFR.7', 1, 'numeric', 'Interpret the solution of a system in context', 'Two walkers are at distances $d = 40 + 2t$ and $d = 10 + 5t$ meters from home after $t$ seconds. The solution of the system is $(10, 60)$. After how many seconds are the walkers the same distance from home?', '[]', '10', '10', 'The solution $(10, 60)$ says that when $t = 10$ both distances are 60 meters. So they are the same distance after 10 seconds.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Very easy: the answer is the x-value given in the stem.","work":"t = 10 (check 40+20 = 10+50 = 60).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
