INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d2a321e-344a-45e2-9538-b2d636bec8bc', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system from a situation', 'The sum of two numbers is 20 and their difference is 4. What is the larger number?', '[]', '12', '(20+4)/2', 'Let the numbers be $x$ and $y$ with $x + y = 20$ and $x - y = 4$. Adding gives $2x = 24$, so the larger number is 12 (and the smaller is 8).', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=20, x-y=4: x=12.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
