INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('223439d6-aeef-4b2e-aa51-8b4b496da643', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system from a situation', 'A box holds 15 marbles, all red or blue. There are 3 more red marbles than blue marbles. How many blue marbles are in the box?', '[]', '6', '(15-3)/2', 'With $r + b = 15$ and $r = b + 3$: $b + 3 + b = 15$, so $2b = 12$ and $b = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+b=15, r=b+3: 2b=12, b=6.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
