INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c9357fc-58ce-462b-997f-5073294fc128', 'NC26.M1.ANFR.7', 1, 'numeric', 'Solve a system from a situation', 'At a fair, a ride ticket costs 2 dollars and a game ticket costs 1 dollar. Zoe bought 10 tickets for 14 dollars. How many ride tickets did she buy?', '[]', '4', '14-10', 'Let $r$ be ride tickets and $g$ game tickets: $r + g = 10$ and $2r + g = 14$. Subtracting the first from the second gives $r = 4$.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r+g=10, 2r+g=14: r=4.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bfd2a530-a4b6-40c0-bd2a-d89c5100b0a3', 'NC26.M1.ANFR.7', 1, 'choice', 'Solve a system from a situation', 'Tia and Uri have 18 stickers together. Tia has twice as many stickers as Uri. How many stickers does Tia have?', '["9","6","12","36"]', '12', '18/3*2', 'With $t + u = 18$ and $t = 2u$: $3u = 18$, so $u = 6$ and $t = 12$. Twelve is Tia''s number.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"t=2u, 3u=18, u=6, t=12.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
