INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb3b84d1-a485-4735-a267-e248e9521860', 'NC26.M1.ANFR.7', 1, 'choice', 'Systems of inequalities in context', 'Which ordered pair makes both $x + y < 8$ and $x > 2$ true?', '["$(4, 3)$","$(2, 3)$","$(5, 4)$","$(1, 1)$"]', '$(4, 3)$', NULL, 'Check both rules. $(4, 3)$: $4 + 3 = 7 < 8$ and $4 > 2$, so it works. $(2, 3)$ fails $x > 2$, $(5, 4)$ has sum 9 and $(1, 1)$ fails $x > 2$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,3): x>2 false. (1,1) false. (4,3): 7<8, 4>2 true. (5,4): 9 not < 8.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88b35da3-9658-4831-8026-4e6419ff2bb1', 'NC26.M1.ANFR.7', 1, 'choice', 'Systems of inequalities in context', 'Maya buys apples, $a$, and pears, $p$. She buys at most 10 pieces of fruit, so $a + p \le 10$, and at least 4 apples, so $a \ge 4$. Which pair $(a, p)$ satisfies both?', '["$(6, 6)$","$(5, 4)$","$(3, 5)$","$(4, 7)$"]', '$(5, 4)$', NULL, 'Check each pair in both. $(3, 5)$ has only 3 apples. $(6, 6)$ has $6 + 6 = 12$ pieces, more than 10. $(4, 7)$ has $4 + 7 = 11$ pieces, more than 10. $(5, 4)$ has $5 + 4 = 9 \le 10$ and $5 \ge 4$, so it works.', 'checked', '{"lint":[],"solve":{"answer":"$(5, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5,4): 9<=10, 5>=4 yes. (6,6): 12>10 no. (4,7): 11>10 no. (3,5): 3<4 no. Only (5,4).","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a9f92336-8d87-4d6e-a768-3a37a1a82c4c', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $y = 2x + 3$ and $y = 2x - 5$ have?', '["Exactly one solution","Infinitely many solutions","Exactly two solutions","No solution"]', 'No solution', NULL, 'Both lines have slope 2 but different y-intercepts (3 and $-5$), so they are parallel and never meet. Setting the right sides equal gives $2x + 3 = 2x - 5$, which is never true.', 'checked', '{"lint":[],"solve":{"answer":"No solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same slope 2, different intercepts 3 and -5: parallel lines, never meet. No solution.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('28800c1a-e9f6-49c0-bce7-4e300597eceb', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system from a situation', 'A rental shop has bikes (2 wheels each) and trikes (3 wheels each). There are 14 vehicles with 38 wheels in all. How many trikes are there?', '[]', '10', '38-2*14', 'Let $b$ be bikes and $t$ be trikes. Then $b + t = 14$ and $2b + 3t = 38$. Replacing $b$ with $14 - t$: $2(14 - t) + 3t = 38$, so $28 + t = 38$ and $t = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"b + t = 14, 2b + 3t = 38. 2(14) + t = 38 -> t = 10, b = 4. Check 8 + 30 = 38.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b34525e-e29d-4a0c-b020-22dea06879db', 'NC26.M1.ANFR.7', 2, 'numeric', 'Find the intersection of two lines', 'The lines $y = x + 2$ and $y = -x + 8$ cross at one point. What is the y-coordinate of that point?', '[]', '5', '(8-2)/2+2', 'At the crossing point the y-values are equal: $x + 2 = -x + 8$, so $2x = 6$ and $x = 3$. Then $y = 3 + 2 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + 2 = -x + 8 -> 2x = 6 -> x = 3, y = 5.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a2fd096e-dc36-43c2-b6d5-bc19a53dba14', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'Chen mows lawns ($m$) and walks dogs ($w$). Chen earns 15 dollars for each lawn and 8 dollars for each dog walk. Last week Chen did 11 jobs and earned 102 dollars. Which system models this?', '["$m + w = 11$ and $15m + 8w = 102$","$m + w = 11$ and $8m + 15w = 102$","$m + w = 102$ and $15m + 8w = 11$","$m + w = 11$ and $15m - 8w = 102$"]', '$m + w = 11$ and $15m + 8w = 102$', NULL, 'The number of jobs gives $m + w = 11$. The money earned gives $15m + 8w = 102$, with 15 dollars on each lawn and 8 dollars on each walk.', 'checked', '{"lint":[],"solve":{"answer":"$m + w = 11$ and $15m + 8w = 102$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Jobs m+w=11; earnings 15m+8w=102 (m=2, w=9).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1040506c-f72c-464d-b51b-98ed582babac', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'The length $L$ of a rectangle is 4 centimeters more than twice its width $w$. The perimeter is 38 centimeters. Which system models this?', '["$L = 2w + 4$ and $L + w = 38$","$L = 2w + 4$ and $2L + 2w = 38$","$L = 2(w + 4)$ and $2L + 2w = 38$","$L = 2w - 4$ and $2L + 2w = 38$"]', '$L = 2w + 4$ and $2L + 2w = 38$', NULL, '"4 more than twice the width" is $L = 2w + 4$. The perimeter is two lengths plus two widths: $2L + 2w = 38$.', 'checked', '{"lint":[],"solve":{"answer":"$L = 2w + 4$ and $2L + 2w = 38$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"L = 2w + 4; perimeter 2L + 2w = 38.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7758d50-576b-48ac-9d2b-3f8d28eefbba', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'One candle is 20 cm tall and burns down 2 cm every hour. A second candle is 16 cm tall and burns down 1 cm every hour. Let $x$ be the hours burned and $y$ the height in cm. Which system gives the two heights?', '["$y = 20 + 2x$ and $y = 16 + x$","$y = 2x - 20$ and $y = x - 16$","$y = 20 - 2x$ and $y = 16 - x$","$y = 20x - 2$ and $y = 16x - 1$"]', '$y = 20 - 2x$ and $y = 16 - x$', NULL, 'Each candle starts at its full height and loses height every hour, so the burning rate is subtracted: $y = 20 - 2x$ and $y = 16 - x$.', 'checked', '{"lint":[],"solve":{"answer":"$y = 20 - 2x$ and $y = 16 - x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Heights decrease from 20 by 2 per hour and from 16 by 1 per hour.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fff813c9-677b-45bb-be08-6cfb136d7aa5', 'NC26.M1.ANFR.7', 2, 'choice', 'Build a system from a situation', 'Which situation is modeled by the system $x + y = 25$ and $3x + 2y = 60$?', '["A total of 25 tickets were bought: x at 2 dollars each and y at 3 dollars each, costing 60 dollars in all.","A total of 60 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 25 dollars in all.","A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, and the y tickets cost 60 dollars.","A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 60 dollars in all."]', 'A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 60 dollars in all.', NULL, 'In $x + y = 25$ the tickets are counted, so there are 25 tickets. In $3x + 2y = 60$ the $x$ tickets cost 3 dollars each and the $y$ tickets cost 2 dollars each, and the total cost is 60 dollars.', 'checked', '{"lint":[],"solve":{"answer":"A total of 25 tickets were bought: x at 3 dollars each and y at 2 dollars each, costing 60 dollars in all.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=25 counts tickets; 3x+2y=60 is the total cost with x at $3, y at $2.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
