INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b7a2495e-3b2b-4e22-b2ce-24a6f91b8ed1', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by substitution', 'Which ordered pair $(x, y)$ is the solution of $x = 2y - 3$ and $3x + y = 5$?', '["$(2, 1)$","$(1, 2)$","$(3, 3)$","$(0, 5)$"]', '$(1, 2)$', NULL, 'Substitute $x = 2y - 3$: $3(2y - 3) + y = 5$, so $7y - 9 = 5$ and $y = 2$. Then $x = 2(2) - 3 = 1$. Check: $3(1) + 2 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"$(1, 2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(2y-3)+y=5, 7y=14, y=2, x=1. (1,2). Check others fail.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
