INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c744e0cd-b802-4175-b36e-46946ce6116a', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by substitution', 'Which ordered pair is the solution of both $y = 3x - 1$ and $2x + y = 14$?', '["$(8, 3)$","$(2, 5)$","$(3, 8)$","$(1, 12)$"]', '$(3, 8)$', NULL, 'Substitute $y = 3x - 1$: $2x + 3x - 1 = 14$, so $5x = 15$ and $x = 3$. Then $y = 3(3) - 1 = 8$. Check: $2(3) + 8 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x + 3x - 1 = 14, x=3, y=8.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43687492-afa4-4005-953e-43a7977ea5a1', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by substitution', 'The equations $5x + 2y = 26$ and $y = 2x - 5$ make a system. What is $y$?', '[]', '3', '2*(26+10)/9-5', 'Replace $y$ by $2x - 5$: $5x + 2(2x - 5) = 26$, so $9x - 10 = 26$ and $x = 4$. Then $y = 2(4) - 5 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5x + 2(2x-5) = 26, 9x = 36, x=4, y=3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d931b7c0-6557-4471-a1fc-76e48b88be08', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by graphing', 'The lines $y = 3x - 2$ and $y = x + 4$ are graphed. What is the $x$-coordinate of the point where they cross?', '[]', '3', '(4+2)/(3-1)', 'Set the two expressions equal: $3x - 2 = x + 4$. Then $2x = 6$ and $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 2 = x + 4, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('37d65915-50a8-4b87-bc0f-5f0fafeef6aa', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by graphing', 'One line has slope 3 and passes through $(0, -1)$. Another line has slope $-1$ and passes through $(0, 11)$. Which point is where the two lines cross?', '["$(8, 3)$","$(3, 8)$","$(2, 9)$","$(4, 11)$"]', '$(3, 8)$', NULL, 'The lines are $y = 3x - 1$ and $y = -x + 11$. Setting them equal gives $4x = 12$, so $x = 3$ and $y = 3(3) - 1 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 8)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y=3x-1 and y=-x+11: 4x=12, x=3, y=8.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('908251ba-9ed9-461a-b8f8-6c9bc1349ef4', 'NC26.M1.ANFR.7', 2, 'numeric', 'Solve a system by graphing', 'The lines $y = 2x + 3$ and $y = -x + 12$ are graphed together. What is the $y$-coordinate of their crossing point?', '[]', '9', '2*(12-3)/3+3', 'Set $2x + 3 = -x + 12$. Then $3x = 9$ and $x = 3$. So $y = 2(3) + 3 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+3 = -x+12, x=3, y=9.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('783e71c8-d7bd-4a50-8eab-e2c49a301133', 'NC26.M1.ANFR.7', 2, 'choice', 'Solve a system by graphing', 'Without drawing them, which pair of lines would cross each other on the $y$-axis?', '["$y = 2x + 4$ and $y = 2x - 3$","$y = 2x + 4$ and $y = -3x - 4$","$y = 2x + 4$ and $y = -3x + 4$","$y = 2x + 4$ and $y = 4x + 2$"]', '$y = 2x + 4$ and $y = -3x + 4$', NULL, 'Lines cross on the $y$-axis when they have the same $y$-intercept and different slopes. Both lines in the correct pair have $y$-intercept 4 and their slopes differ. The pair with equal slopes is parallel and never crosses.', 'checked', '{"lint":[],"solve":{"answer":"$y = 2x + 4$ and $y = -3x + 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same y-intercept 4 and different slopes: cross at (0,4).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ae569eeb-2b21-4261-be6f-e68e1e66e430', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'Which system has no solution?', '["$y = 4x - 1$ and $8x - 2y = 2$","$y = 4x - 1$ and $8x - 2y = 6$","$y = 4x - 1$ and $8x + 2y = 6$","$y = 4x - 1$ and $2x - 2y = 6$"]', '$y = 4x - 1$ and $8x - 2y = 6$', NULL, 'Write each second equation as $y = mx + b$. In the correct system $8x - 2y = 6$ becomes $y = 4x - 3$: the same slope as $y = 4x - 1$ but a different intercept, so the lines are parallel. The other systems have a different slope (one solution) or are the same line.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4x - 1$ and $8x - 2y = 6$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Substituting y=4x-1: 8x-2y = 2 always. So 8x-2y=2 is the same line; 8x-2y=6 is parallel, no solution. Others have different slopes.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9f59f4e6-46e8-4eb5-bd69-241950f2cefe', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'How many solutions does the system $y = -2x + 6$ and $4x + 2y = 12$ have?', '["No solution at all","Exactly one solution","Infinitely many","Exactly two solutions"]', 'Infinitely many', NULL, 'Solve $4x + 2y = 12$ for $y$: $2y = -4x + 12$, so $y = -2x + 6$. The two equations are the same line, so there are infinitely many solutions.', 'checked', '{"lint":[],"solve":{"answer":"Infinitely many","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4x+2y=12 gives y=-2x+6, identical.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d8274a5-0f6d-4770-b9ea-4962f16eadd6', 'NC26.M1.ANFR.7', 2, 'numeric', 'Count the solutions of a system', 'The system $y = 5x + 1$ and $y = mx + 4$ has no solution. What is $m$?', '[]', '5', '5', 'No solution means the lines are parallel with different intercepts. Parallel lines have equal slopes, so $m = 5$. The intercepts 1 and 4 differ, as needed.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Parallel with different intercepts needs m = 5.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20ccea15-ad55-4f71-9a0c-ba205adeb4d0', 'NC26.M1.ANFR.7', 2, 'choice', 'Count the solutions of a system', 'Mia starts 100 meters from a flagpole and runs away from it at 6 meters per second. Noah starts 20 meters from the flagpole and also runs away from it at 6 meters per second. The system $d = 100 + 6t$ and $d = 20 + 6t$ models their distances after $t$ seconds. Will they ever be the same distance from the flagpole?', '["Yes, because both lines have the same slope as each other","Yes, exactly once, at the point where the lines cross","Yes, always, since the two lines are in fact the same","No, the lines are parallel, so there is no solution"]', 'No, the lines are parallel, so there is no solution', NULL, 'Both lines have slope 6 but different starting values (100 and 20), so they are parallel and never meet. Noah is always 80 meters closer.', 'checked', '{"lint":[],"solve":{"answer":"No, the lines are parallel, so there is no solution","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same slope 6, different intercepts 100 and 20: parallel, the gap stays 80 m.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aaaafbf9-b10b-4cd2-8d5a-54991b23d2df', 'NC26.M1.ANFR.7', 2, 'choice', 'Interpret the solution of a system in context', 'A school sells shirts ($s$) and caps ($c$). The system $s + c = 50$ and $12s + 8c = 520$ has the solution $(30, 20)$. Which sentence matches this solution?', '["30 shirts and 20 caps were sold","20 shirts and 30 caps were sold","30 shirts were sold for 20 dollars each","50 shirts and 30 caps were sold"]', '30 shirts and 20 caps were sold', NULL, 'The first number is $s$, the number of shirts, and the second is $c$, the number of caps. Check: $30 + 20 = 50$ items and $12(30) + 8(20) = 520$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"30 shirts and 20 caps were sold","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s=30, c=20; 30+20=50, 360+160=520.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4e5ab6ff-8ec1-45c5-b1ad-3f96b464f9aa', 'NC26.M1.ANFR.7', 2, 'choice', 'Interpret the solution of a system in context', 'The system $y = 50 + 10x$ and $y = 20 + 10x$ models two savings plans. A student says $(3, 80)$ is a solution. Which reply is correct?', '["It is a solution, because the point fits the first equation","It is not a solution, because the point fits the first equation but not the second","It is a solution, because both plans reach 80 dollars at $x = 3$","It is not a solution, because the point fits the second equation but not the first"]', 'It is not a solution, because the point fits the first equation but not the second', NULL, 'A solution must fit both equations. First: $50 + 10(3) = 80$, which works. Second: $20 + 10(3) = 50$, not 80. So $(3, 80)$ is not a solution.', 'checked', '{"lint":[],"solve":{"answer":"It is not a solution, because the point fits the first equation but not the second","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First: 50+30=80 fits. Second: 20+30=50, not 80. Not a solution.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b5f5a17d-738c-4bfb-8588-8616e9156a04', 'NC26.M1.ANFR.7', 2, 'numeric', 'Interpret the solution of a system in context', 'Pool A holds 200 liters and fills at 15 liters per minute. Pool B holds 80 liters and fills at 25 liters per minute. The two pools hold the same amount after 12 minutes. How many liters does each pool hold then?', '[]', '380', '200+15*12', 'Pool A: $200 + 15(12) = 380$ liters. Check pool B: $80 + 25(12) = 380$ liters.', 'checked', '{"lint":[],"solve":{"answer":"380","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"200 + 15(12) = 380; 80 + 25(12) = 380.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
