INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57cb8850-fea4-410c-9257-9bd9fed88666', 'NC26.M1.ANFR.7', 3, 'choice', 'Interpret the solution of a system in context', 'A gym offers Plan A, which costs $y = 30 + 4x$ dollars for $x$ visits, and Plan B, which costs $y = 10 + 6x$ dollars for $x$ visits. The solution of the system is $(10, 70)$. What does it mean?', '["Plan A costs 10 dollars and Plan B costs 70 dollars","After 10 visits both plans cost the same total, 70 dollars","After 70 visits both plans cost the same total, 10 dollars","Plan B is cheaper no matter how many visits"]', 'After 10 visits both plans cost the same total, 70 dollars', NULL, 'The solution is the $(x, y)$ that makes both equations true: at $x = 10$ visits, Plan A costs $30 + 40 = 70$ and Plan B costs $10 + 60 = 70$. So after 10 visits the two plans cost the same, 70 dollars.', 'checked', '{"lint":[],"solve":{"answer":"After 10 visits both plans cost the same total, 70 dollars","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 10 visits, y = 70 dollars: 30 + 40 = 70 and 10 + 60 = 70. Both plans cost 70 after 10 visits.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee8bc7ec-c0c0-4f71-bcfe-dc62a5cd2952', 'NC26.M1.ANFR.7', 3, 'numeric', 'Find the value that gives infinitely many solutions', 'The system $y = 3x + 4$ and $2y = 6x + k$ has infinitely many solutions. What is $k$?', '[]', '8', '2*4', 'The system has infinitely many solutions when both equations describe the same line. Multiplying $y = 3x + 4$ by 2 gives $2y = 6x + 8$, so $k = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Double the first: 2y = 6x + 8. Same line iff k = 8.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2114a52-d059-439c-aa46-b20af868af41', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution with a coefficient', 'A system has the equations $3x + 2y = 16$ and $y = x + 3$. What is $y$?', '[]', '5', '(16-6)/5+3', 'Substitute $y = x + 3$: $3x + 2(x + 3) = 16$, so $5x + 6 = 16$ and $x = 2$. Then $y = 2 + 3 = 5$. Check: $3(2) + 2(5) = 16$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x + 2(x + 3) = 16 -> 5x + 6 = 16 -> x = 2, y = 5. Check 6 + 10 = 16.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7663d683-5501-40ac-9c98-5405570ae0fa', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'Sam has 3 times as many stickers as Lia. If Sam gives Lia 10 stickers, they will have the same number. Let $s$ be Sam''s stickers and $l$ be Lia''s stickers now. Which system models this?', '["$s = 3l$ and $s - 10 = l + 10$","$s = 3l$ and $s + 10 = l - 10$","$s = l + 3$ and $s - 10 = l + 10$","$l = 3s$ and $s - 10 = l + 10$"]', '$s = 3l$ and $s - 10 = l + 10$', NULL, 'Sam has 3 times as many: $s = 3l$. After Sam gives away 10 he has $s - 10$ and Lia has $l + 10$, and these are equal.', 'checked', '{"lint":[],"solve":{"answer":"$s = 3l$ and $s - 10 = l + 10$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s=3l; after giving: s-10 = l+10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('378d03af-adf5-401c-b8f2-9737f1a90840', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'A school sold adult tickets ($a$) at 7 dollars and student tickets ($s$) at 4 dollars. It sold 3 times as many student tickets as adult tickets and took in 228 dollars. Which system models this?', '["$a = 3s$ and $7a + 4s = 228$","$s = 3a$ and $7a + 4s = 228$","$s = 3a$ and $4a + 7s = 228$","$s = a + 3$ and $7a + 4s = 228$"]', '$s = 3a$ and $7a + 4s = 228$', NULL, '"3 times as many student tickets" gives $s = 3a$. The money is 7 dollars for each adult ticket and 4 dollars for each student ticket: $7a + 4s = 228$.', 'checked', '{"lint":[],"solve":{"answer":"$s = 3a$ and $7a + 4s = 228$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"s = 3a; revenue 7a + 4s = 228 (a=12, s=36).","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('decfcaf4-98bd-412c-a1ce-a65a91fe14d3', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'A boat travels 24 km upstream in 3 hours and 24 km downstream in 2 hours. Let $b$ be the boat''s speed in still water and $c$ the speed of the current, both in km per hour. Going upstream the current slows the boat; going downstream it speeds the boat up. Which system models this?', '["$3(b + c) = 24$ and $2(b - c) = 24$","$3b - c = 24$ and $2b + c = 24$","$3(b - c) = 24$ and $2(b + c) = 24$","$b - c = 3$ and $b + c = 2$"]', '$3(b - c) = 24$ and $2(b + c) = 24$', NULL, 'Distance is speed times time. Upstream the speed is $b - c$ for 3 hours: $3(b - c) = 24$. Downstream the speed is $b + c$ for 2 hours: $2(b + c) = 24$.', 'checked', '{"lint":[],"solve":{"answer":"$3(b - c) = 24$ and $2(b + c) = 24$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"distance = rate x time: 3(b-c)=24, 2(b+c)=24.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db0dfd2a-e6ff-4236-a6b5-730a4927e441', 'NC26.M1.ANFR.7', 3, 'choice', 'Build a system from a situation', 'A 10-liter juice mix is made from juice that is 20% fruit ($x$ liters) and juice that is 50% fruit ($y$ liters). The mix is 35% fruit, so it holds 3.5 liters of fruit. Which system models this?', '["$x + y = 10$ and $0.2x + 0.5y = 35$","$x + y = 10$ and $20x + 50y = 3.5$","$x + y = 3.5$ and $0.2x + 0.5y = 10$","$x + y = 10$ and $0.2x + 0.5y = 3.5$"]', '$x + y = 10$ and $0.2x + 0.5y = 3.5$', NULL, 'The amounts of juice add to 10 liters: $x + y = 10$. The fruit in each juice is 20% of $x$ plus 50% of $y$, which is $0.2x + 0.5y$, and the mix holds 3.5 liters of fruit.', 'checked', '{"lint":[],"solve":{"answer":"$x + y = 10$ and $0.2x + 0.5y = 3.5$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Volume x+y=10; fruit 0.2x+0.5y=3.5.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98692731-eaa8-4a9b-9bfa-5e2e50592dbe', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution', 'Solve the system $3x - 2y = 7$ and $y = 2x - 5$. What is $x$?', '[]', '3', '(7-10)/(3-4)', 'Replace $y$ by $2x - 5$: $3x - 2(2x - 5) = 7$, so $3x - 4x + 10 = 7$. Then $-x = -3$ and $x = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3x - 2(2x-5) = 7, -x + 10 = 7, x = 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0e66db08-a779-4c90-a922-71e5c1d92421', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution', 'Solve the system $x = 4y - 5$ and $2x + 3y = 23$. What is $x + y$?', '[]', '10', '4*3-5+3', 'Replace $x$ by $4y - 5$: $2(4y - 5) + 3y = 23$, so $11y - 10 = 23$ and $y = 3$. Then $x = 4(3) - 5 = 7$, and $x + y = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(4y-5)+3y=23, 11y=33, y=3, x=7, sum 10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d90b256-e008-4550-ac6d-54a1053ed04e', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by substitution', 'A system has the equations $y = \frac{1}{2}x + 3$ and $x + y = 9$. What is $y$?', '[]', '5', '9-4', 'Replace $y$ by $rac{1}{2}x + 3$: $x + rac{1}{2}x + 3 = 9$, so $rac{3}{2}x = 6$ and $x = 4$. Then $y = 9 - 4 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x + x/2 + 3 = 9, 1.5x = 6, x=4, y=5.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
