INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5e57ad5b-f718-4c9d-a982-b9053f47e5f4', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system by graphing', 'The lines $2x + y = 10$ and $x - y = 2$ are graphed. What is the $y$-coordinate of their crossing point?', '[]', '2', '10-2*(12/3)', 'Add the equations: $3x = 12$, so $x = 4$. Then $y = 10 - 2(4) = 2$. Check in the second equation: $4 - 2 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Add: 3x=12, x=4, y=2.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
