INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a8e8372e-96e2-4acb-95f5-ba7c4b2f8af8', 'NC26.M1.ANFR.7', 3, 'numeric', 'Count the solutions of a system', 'The system $3x + 2y = 10$ and $6x + 4y = c$ has infinitely many solutions. What is $c$?', '[]', '20', '2*10', 'The second equation must be the first with every part doubled: $6x + 4y = 2 \times 10 = 20$. So $c = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Second must be 2 times the first: c = 20.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b9f7b3a0-7453-4db5-b923-8af0b930af91', 'NC26.M1.ANFR.7', 3, 'numeric', 'Count the solutions of a system', 'The system $2x + 5y = 7$ and $4x + ky = 20$ has no solution. What is $k$?', '[]', '10', '2*5', 'The $x$-terms are doubled, so for parallel lines the $y$-term must be doubled too: $k = 2 \times 5 = 10$. The right side would then be 14, but it is 20, so the lines are parallel and never meet.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need 4/2 = k/5 with 20 not equal 2*7=14: k = 10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('459a6a47-5abf-4062-b45d-38e7e387fb61', 'NC26.M1.ANFR.7', 3, 'choice', 'Count the solutions of a system', 'Which system has exactly one solution?', '["$x + y = 4$ and $x - y = 4$","$x + y = 4$ and $3x + 3y = 12$","$x + y = 4$ and $2x + 2y = 7$","$x + y = 4$ and $x + y = 5$"]', '$x + y = 4$ and $x - y = 4$', NULL, 'The correct system has lines with different slopes, so it crosses once (at $(4, 0)$). The other three systems have the same slope as $x + y = 4$: one is the same line and two are parallel lines.', 'checked', '{"lint":[],"solve":{"answer":"$x + y = 4$ and $x - y = 4$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x+y=4 and x-y=4 have different slopes: one solution (4,0). Others parallel or identical.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f13ad2c2-b034-4d11-a315-1a50b6927ee3', 'NC26.M1.ANFR.7', 3, 'choice', 'Count the solutions of a system', 'A student says: "The system $3x - y = 4$ and $6x - 2y = 8$ has two different equations, so it must have exactly one solution." Which reply is correct?', '["It has no solution, because the two lines have the same slope as each other","It has infinitely many solutions, because the second equation is twice the first","It has exactly two solutions, because there are two different equations","The student is right, because the two equations look quite different"]', 'It has infinitely many solutions, because the second equation is twice the first', NULL, 'Doubling $3x - y = 4$ gives $6x - 2y = 8$ exactly. The two equations describe the same line, so every point on it is a solution.', 'checked', '{"lint":[],"solve":{"answer":"It has infinitely many solutions, because the second equation is twice the first","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6x-2y=8 is 2(3x-y=4): same line, infinitely many.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1351f39c-a5f0-4865-868b-ce2faaf62950', 'NC26.M1.ANFR.7', 3, 'numeric', 'Count the solutions of a system', 'One line passes through $(0, 1)$ and $(1, 3)$. Another line passes through $(0, 4)$ and $(1, 6)$. How many points do the two lines have in common?', '[]', '0', NULL, 'Both lines rise 2 for every 1 across, so they have the same slope 2. Their $y$-intercepts, 1 and 4, differ, so the lines are parallel and share no point.', 'checked', '{"lint":[],"solve":{"answer":"0","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both slope 2, intercepts 1 and 4: parallel, no common points.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dcd2c24d-557e-4c16-8516-4078853cbb8e', 'NC26.M1.ANFR.7', 3, 'choice', 'Interpret the solution of a system in context', 'Kayak shop P charges $y = 25x$ dollars for $x$ hours. Kayak shop Q charges $y = 15x + 30$ dollars for $x$ hours. The solution of the system is $(3, 75)$. Maria wants a kayak for 5 hours. Which choice is best?', '["Shop P, because for more than 3 hours its total is lower","Shop Q, because its price for each hour is higher","Shop P, because its price for each hour is lower","Shop Q, because for more than 3 hours its total is lower"]', 'Shop Q, because for more than 3 hours its total is lower', NULL, 'The prices match at 3 hours. After that, shop P grows by 25 dollars an hour and shop Q by only 15. For 5 hours: P costs $25(5) = 125$ dollars and Q costs $15(5) + 30 = 105$ dollars, so Q is cheaper.', 'checked', '{"lint":[],"solve":{"answer":"Shop Q, because for more than 3 hours its total is lower","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5 hours: P 125, Q 75+30=105. Q is cheaper beyond 3 hours.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b9f4b94-8ddf-45cb-a1b3-638923271f9a', 'NC26.M1.ANFR.7', 3, 'numeric', 'Interpret the solution of a system in context', 'Printer 1 prints $y = 12x$ pages after $x$ minutes. Printer 2 already had 60 pages printed and prints $y = 7x + 60$ pages after $x$ minutes. They have printed the same number of pages at $(12, 144)$. After 14 minutes, how many more pages has printer 1 printed than printer 2?', '[]', '10', '12*14-(7*14+60)', 'After 14 minutes printer 1 has $12(14) = 168$ pages and printer 2 has $7(14) + 60 = 158$ pages. The difference is $168 - 158 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=14: 168 vs 98+60=158. Difference 10.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
