INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a357b56-2a35-438b-98dc-647a91673258', 'NC26.M1.ANFR.7', 3, 'choice', 'Interpret the solution of a system in context', 'Liquid A is heated and its temperature is $y = 40 + 6x$ degrees after $x$ hours. Liquid B is cooled and its temperature is $y = 90 - 4x$ degrees. The solution of the system is $(5, 70)$. Which statement is true at 3 hours?', '["Liquid B is warmer than liquid A","Liquid A is warmer than liquid B","Liquid A and liquid B are the same temperature","Liquid A is at 70 degrees"]', 'Liquid B is warmer than liquid A', NULL, 'At 3 hours liquid A is $40 + 6(3) = 58$ degrees and liquid B is $90 - 4(3) = 78$ degrees. B is warmer, as expected before the temperatures meet at 5 hours.', 'checked', '{"lint":[],"solve":{"answer":"Liquid B is warmer than liquid A","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=3: A 58, B 78. B warmer.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7bd34e69-7ee6-4ebd-b9ad-59ed6c342de7', 'NC26.M1.ANFR.7', 3, 'choice', 'Interpret the solution of a system in context', 'Job 1 pays $y = 7x$ dollars for $x$ hours. Job 2 pays $y = 12x - 20$ dollars for $x$ hours, because 20 dollars is taken off for equipment. The solution of the system is $(4, 28)$. If Maya works 6 hours, which statement is true?', '["Job 1 pays 10 dollars more than job 2","Job 2 pays 10 dollars more than job 1","Job 2 pays 24 dollars more than job 1","The two jobs pay the same amount"]', 'Job 2 pays 10 dollars more than job 1', NULL, 'For 6 hours job 1 pays $7(6) = 42$ dollars and job 2 pays $12(6) - 20 = 52$ dollars. Job 2 pays $52 - 42 = 10$ dollars more.', 'checked', '{"lint":[],"solve":{"answer":"Job 2 pays 10 dollars more than job 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x=6: Job 1 42, Job 2 72-20=52. Job 2 pays 10 more.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e35754c6-012e-4d98-b120-53556e74eadc', 'NC26.M1.ANFR.7', 3, 'numeric', 'Interpret the solution of a system in context', 'A plan costs $y = 5x + c$ dollars for $x$ hours, where $c$ is the starting fee in dollars. This plan is one equation of a system whose solution is $(3, 17)$. What is $c$?', '[]', '2', '17-5*3', 'At the solution $x = 3$ and $y = 17$ fit the equation $y = 5x + c$: $17 = 15 + c$, so $c = 2$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"17 = 5(3) + c, c = 2.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef28cd0a-9356-4614-8787-2389551199f6', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system from a situation', 'A store sells notebooks for 3 dollars each and binders for 7 dollars each. Kai buys 12 items for 72 dollars. How many binders does Kai buy?', '[]', '9', '(72-3*12)/4', 'Let $n$ be notebooks and $b$ binders: $n + b = 12$ and $3n + 7b = 72$. Replace $n$ by $12 - b$: $36 - 3b + 7b = 72$, so $4b = 36$ and $b = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"n+b=12, 3n+7b=72: 36+4b=72, b=9.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c8cd105-e7b8-4059-9e96-d385800df898', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system from a situation', 'A boat goes 40 km downstream in 4 hours and then 40 km back upstream in 5 hours. What is the speed of the current, in km per hour?', '[]', '1', '(40/4-40/5)/2', 'Downstream speed is $40 \div 4 = 10$ km/h, which is boat plus current. Upstream speed is $40 \div 5 = 8$ km/h, boat minus current. The difference, 2 km/h, is twice the current, so the current is 1 km/h.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Down 10 = b+c, up 8 = b-c: c = 1.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9aefd18e-1701-4cf4-a5da-bdb910c82123', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system from a situation', 'Some dimes and quarters make 25 coins worth 430 cents in all. How many quarters are there?', '[]', '12', '(430-10*25)/15', 'With $d + q = 25$ and $10d + 25q = 430$, replace $d$ by $25 - q$: $250 + 15q = 430$, so $15q = 180$ and $q = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"d+q=25, 10d+25q=430: 250+15q=430, q=12.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8983fcea-6d91-40e5-b86a-edfa2c22dae3', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system from a situation', 'Amy is 3 times as old as Ben. In 6 years, Amy will be twice as old as Ben will be then. How old is Ben now?', '[]', '6', '12-6', 'With $a = 3b$ and $a + 6 = 2(b + 6)$: $3b + 6 = 2b + 12$, so $b = 6$. (Amy is 18; in 6 years she is 24 and Ben is 12.)', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A=3B, 3B+6 = 2(B+6), B = 6.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('18b2fd2b-ffce-470d-82ba-54498f56a58e', 'NC26.M1.ANFR.7', 3, 'numeric', 'Solve a system from a situation', 'A prize of 80 dollars in total is shared among 3 first-place winners and 2 second-place winners. Each first-place winner gets 10 dollars more than each second-place winner. How many dollars does each first-place winner get?', '[]', '20', '(80+20)/5', 'Let $x$ be first-place and $y$ second-place money: $x = y + 10$ and $3x + 2y = 80$. Replace $y$ by $x - 10$: $3x + 2x - 20 = 80$, so $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(s+10)+2s=80, 5s=50, s=10; first place 20.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a1d2f9f-6d47-4b57-8930-873d4bbf597b', 'NC26.M1.ANFR.7', 3, 'choice', 'Systems of inequalities in context', 'Zara has at most 40 minutes for homework. She needs at least 15 minutes of math ($m$) and at least 10 minutes of reading ($r$). Which pair $(m, r)$ is possible?', '["$(30, 15)$","$(12, 25)$","$(25, 8)$","$(20, 20)$"]', '$(20, 20)$', NULL, 'The rules are $m + r \le 40$, $m \ge 15$ and $r \ge 10$. $(20, 20)$ has total 40 and meets both minimums. $(30, 15)$ totals 45. $(12, 25)$ has too little math. $(25, 8)$ has too little reading.', 'checked', '{"lint":[],"solve":{"answer":"$(20, 20)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need m>=15, r>=10, m+r<=40. Only (20,20) works.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a84fda75-2ecb-46b3-ac16-6a4225d98402', 'NC26.M1.ANFR.7', 3, 'numeric', 'Systems of inequalities in context', 'Whole numbers $x$ and $y$ satisfy $x + y \le 10$ and $x \ge 2y$. If $x = 6$, what is the greatest possible value of $y$?', '[]', '3', '6/2', 'With $x = 6$: $6 + y \le 10$ gives $y \le 4$, and $6 \ge 2y$ gives $y \le 3$. Both must hold, so the greatest whole number is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6+y<=10 gives y<=4; 6>=2y gives y<=3. Max 3.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9b95d809-c8da-43fd-8ed6-cfb71cddeb69', 'NC26.M1.ANFR.7', 3, 'choice', 'Systems of inequalities in context', 'A club wants to raise at least 100 dollars by selling cookies ($c$) for 2 dollars each and brownies ($b$) for 4 dollars each. It can bake no more than 40 items in all. Which system models this?', '["$2c + 4b \\ge 100$ and $c + b \\le 40$","$2c + 4b \\le 100$ and $c + b \\ge 40$","$2c + 4b \\ge 100$ and $c + b \\ge 40$","$4c + 2b \\ge 100$ and $c + b \\le 40$"]', '$2c + 4b \ge 100$ and $c + b \le 40$', NULL, '"At least 100 dollars" means $2c + 4b \ge 100$. "No more than 40 items" means $c + b \le 40$.', 'checked', '{"lint":[],"solve":{"answer":"$2c + 4b \\ge 100$ and $c + b \\le 40$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Money 2c+4b>=100; items c+b<=40.","run_id":"claude-code","at":"2026-10-18T03:30:59.055Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6ed44b1c-7ff3-4294-b490-c0df562ae153', 'NC26.M1.SGMR.1', 1, 'choice', 'Find the image of a point under a translation', 'The point $(3, 5)$ is translated 4 units to the right and 2 units down. What are the coordinates of its image?', '["$(7, 7)$","$(-1, 3)$","$(7, 3)$","$(5, 9)$"]', '$(7, 3)$', NULL, 'Moving right adds to the x-coordinate: $3 + 4 = 7$. Moving down subtracts from the y-coordinate: $5 - 2 = 3$. The image is $(7, 3)$.', 'checked', '{"lint":[],"solve":{"answer":"$(7, 3)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(3 + 4, 5 - 2) = (7, 3).","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('67ccfac4-cc98-4936-815e-04105c5c9ac2', 'NC26.M1.SGMR.1', 1, 'choice', 'Know what rigid transformations preserve', 'Which pair of properties is the same for a figure and its image under any rotation, reflection or translation?', '["Side lengths and angle measures","Side lengths and orientation","Angle measures and location","Location and orientation"]', 'Side lengths and angle measures', NULL, 'Rigid transformations keep the shape and size: side lengths and angle measures do not change. A translation, rotation or reflection moves the figure, so its location changes, and a reflection reverses its orientation.', 'checked', '{"lint":[],"solve":{"answer":"Side lengths and angle measures","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid motions preserve distance and angle measure. Location changes under translations; orientation is reversed by reflections.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9308cf88-e5d7-4a71-8023-2d17516aed85', 'NC26.M1.SGMR.1', 1, 'numeric', 'Find the image of a point under a reflection', 'The point $(-4, 7)$ is reflected across the y-axis. What is the x-coordinate of its image?', '[]', '4', '-(-4)', 'A reflection across the y-axis changes the sign of the x-coordinate and keeps the y-coordinate. The image of $(-4, 7)$ is $(4, 7)$, so the x-coordinate is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflection across y-axis: (x, y) -> (-x, y). (-4, 7) -> (4, 7). x-coordinate 4.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9e961976-1ee9-44a4-b4d3-20be69477dd1', 'NC26.M1.SGMR.1', 1, 'choice', 'Properties kept by rigid transformations', 'Priya slides a paper triangle across her desk without turning or flipping it. Which statement is true about the triangle before and after the slide?', '["Each side keeps its length and each angle keeps its measure.","Each side keeps its length, but the angle measures change.","Each angle keeps its measure, but the side lengths change.","The side lengths and the angle measures both change."]', 'Each side keeps its length and each angle keeps its measure.', NULL, 'Sliding a figure without turning or flipping it is a translation. A translation is a rigid transformation, so it keeps every length and every angle measure. Only the position of the triangle changes.', 'checked', '{"lint":[],"solve":{"answer":"Each side keeps its length and each angle keeps its measure.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A slide without turning or flipping is a translation, a rigid motion: all side lengths and angle measures are preserved.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed7b52a4-4e82-4926-b503-12753a6e1453', 'NC26.M1.SGMR.1', 1, 'choice', 'Properties kept by rigid transformations', 'Which property of a figure can change when the figure is translated?', '["the length of each of its sides","the measure of each of its angles","the amount of space it covers","the position of the figure on the plane"]', 'the position of the figure on the plane', NULL, 'A translation slides every point the same distance in the same direction, so the figure ends up in a new place. Side lengths, angle measures and the area it covers stay the same.', 'checked', '{"lint":[],"solve":{"answer":"the position of the figure on the plane","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A translation preserves angles, lengths and area; only the location changes.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5061bea2-7ef9-400a-b1f1-a0223fdb1757', 'NC26.M1.SGMR.1', 1, 'numeric', 'Properties kept by rigid transformations', 'A triangle has angles that measure 50, 60 and 70 degrees. The triangle is rotated about a point. What is the measure, in degrees, of the largest angle of the image?', '[]', '70', '70', 'A rotation is a rigid transformation, so it keeps every angle measure. The image has angles of 50, 60 and 70 degrees, and the largest is 70 degrees.', 'checked', '{"lint":[],"solve":{"answer":"70","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotation preserves angle measures, so the image has angles 50, 60, 70; largest is 70.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
