VALUES ('f2ebe805-20ca-46bb-aa43-d589c21a68be', 'NC26.M1.SGMR.1', 1, 'choice', 'Image of a point under a translation', 'A point at $(-3, 4)$ is shifted 2 units up. What are the coordinates of the new point?', '["$(-3, 2)$","$(-1, 4)$","$(-3, 6)$","$(-5, 4)$"]', '$(-3, 6)$', NULL, 'Moving up adds to the y-coordinate and leaves the x-coordinate alone: $(-3, 4 + 2) = (-3, 6)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-3, 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3, 4+2) = (-3, 6).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
