INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('45124a33-e49a-4abc-8b12-027f9f9236af', 'NC26.M1.SGMR.1', 1, 'choice', 'Image of a point under a reflection', 'A point that is not on the x-axis is reflected across the x-axis. Which statement is true?', '["Its y-coordinate stays the same and its x-coordinate changes sign.","Its x-coordinate stays the same and its y-coordinate changes sign.","Its two coordinates swap places, with no change of sign.","Both of its coordinates change sign, with no other change."]', 'Its x-coordinate stays the same and its y-coordinate changes sign.', NULL, 'The x-axis is a horizontal line, so a reflection moves a point straight up or down to the same distance on the other side. The x-coordinate stays the same and the y-coordinate changes sign.', 'checked', '{"lint":[],"solve":{"answer":"Its x-coordinate stays the same and its y-coordinate changes sign.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x, y) -> (x, -y): x unchanged, y changes sign (y is nonzero since the point is off the axis).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
