INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4d9a6d51-2aed-4d7f-83b4-9536983b6044', 'NC26.M1.SGMR.1', 1, 'choice', 'Transformations written in function notation', 'Which rule describes a translation of 4 units to the left and 6 units up?', '["$T(x, y) = (x + 4, y - 6)$","$T(x, y) = (x - 4, y + 6)$","$T(x, y) = (x - 4, y - 6)$","$T(x, y) = (x + 6, y - 4)$"]', '$T(x, y) = (x - 4, y + 6)$', NULL, 'Moving left subtracts from x, so the first part is $x - 4$. Moving up adds to y, so the second part is $y + 6$.', 'checked', '{"lint":[],"solve":{"answer":"$T(x, y) = (x - 4, y + 6)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left 4: x - 4; up 6: y + 6.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
