INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4213f617-2ea3-4834-ba12-2e8c5b3d79a1', 'NC26.M1.SGMR.1', 1, 'choice', 'Identify the transformation from points and images', 'A point moves from $(2, 5)$ to $(7, 5)$. Which transformation could this be?', '["a reflection across the x-axis","a rotation of 90 degrees counterclockwise about the origin","a translation 5 units to the right","a reflection across the y-axis"]', 'a translation 5 units to the right', NULL, 'The y-coordinate stays 5 and the x-coordinate grows from 2 to 7, so the point slid 5 units to the right. A reflection or a rotation would also change the y-coordinate or reverse the sign of x.', 'checked', '{"lint":[],"solve":{"answer":"a translation 5 units to the right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x increases by 5, y same: translation 5 right. Reflections give (2,-5), (-2,5); 90 ccw gives (-5,2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
