INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cbffc277-b8ba-494a-a473-75eb08fb5fcd', 'NC26.M1.SGMR.1', 1, 'choice', 'Identify the transformation from points and images', 'The points $(1, 2)$ and $(3, 5)$ move to $(-1, 2)$ and $(-3, 5)$. Which transformation does this?', '["a reflection across the x-axis","a reflection across the y-axis","a rotation of 180 degrees about the origin","a translation 2 units to the left"]', 'a reflection across the y-axis', NULL, 'Each x-coordinate changes sign and each y-coordinate stays the same, which is a reflection across the y-axis. A slide 2 units left would fit the first point, but it would move $(3, 5)$ to $(1, 5)$, not $(-3, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"a reflection across the y-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x changes sign, y kept for both points: reflection across y-axis. A translation 2 left would give (1,5) for (3,5).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
