INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee36a39c-fb6b-473f-816a-79e22dc2128b', 'NC26.M1.SGMR.1', 1, 'choice', 'Show congruence by a sequence of moves', 'Which statement explains why a figure and its image under a rotation are congruent?', '["A rotation is rigid, so it keeps every length and every angle measure.","A rotation leaves every point of the figure in the same place, so nothing changes.","A rotation keeps the side lengths but is allowed to change the angle measures.","A rotation makes the image match the original by stretching the figure to fit."]', 'A rotation is rigid, so it keeps every length and every angle measure.', NULL, 'A rotation is a rigid transformation. It moves the figure without changing any length or angle, so the image has exactly the same size and shape as the original.', 'checked', '{"lint":[],"solve":{"answer":"A rotation is rigid, so it keeps every length and every angle measure.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotations are rigid: they preserve all lengths and angles, so figure and image are congruent. Other options are false.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5abffd6-f52a-4c7b-aec1-3e0d316a00db', 'NC26.M1.SGMR.1', 1, 'choice', 'Show congruence by a sequence of moves', 'Which statement describes two congruent figures?', '["One can be stretched or shrunk until it matches the other one exactly.","They have the same shape, but one of them may be larger or smaller.","They have the same area, even when their shapes are quite different.","One can be carried onto the other by translations, rotations and reflections."]', 'One can be carried onto the other by translations, rotations and reflections.', NULL, 'Congruent figures have exactly the same size and shape. That means a sequence of rigid transformations (translations, rotations and reflections) can carry one onto the other.', 'checked', '{"lint":[],"solve":{"answer":"One can be carried onto the other by translations, rotations and reflections.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Congruence: one maps onto the other by a sequence of rigid motions.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00c357f7-827a-483d-8276-b735eb99647f', 'NC26.M1.SGMR.1', 1, 'numeric', 'Show congruence by a sequence of moves', 'Triangle $ABC$ has vertices $A(0, 0)$, $B(3, 0)$ and $C(0, 2)$. Triangle $DEF$ has vertices $D(5, 1)$, $E(8, 1)$ and $F(5, 3)$. A translation maps $ABC$ onto $DEF$. How many units to the right does it move the triangle?', '[]', '5', '5-0', 'A moves to $D$, from $(0, 0)$ to $(5, 1)$. So the translation is 5 units right and 1 unit up. The other two vertices follow the same move, so the translation is 5 units to the right.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A(0,0) -> D(5,1): 5 right, 1 up. Check B(3,0) -> (8,1) = E. 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b2c32460-881a-4d2d-adb7-575269e55099', 'NC26.M1.SGMR.1', 1, 'numeric', 'Use congruence to find lengths, angles and areas', 'Rectangle $A$ is translated and then rotated until it lands exactly on rectangle $B$. Rectangle $A$ is 3 centimeters wide and 8 centimeters long. What is the area of rectangle $B$, in square centimeters?', '[]', '24', '3*8', 'Rigid transformations keep side lengths, so rectangle $B$ is also 3 centimeters by 8 centimeters. Its area is $3 \times 8 = 24$ square centimeters.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid motions preserve area: B is 3 by 8, area 24.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
