INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80762f36-7105-42ce-a4e6-49cd722149ed', 'NC26.M1.SGMR.1', 2, 'choice', 'Image of a point under a rotation about the origin', 'The point $(-4, 3)$ is rotated 90 degrees clockwise about the origin. Which point is the image?', '["$(3, 4)$","$(-3, -4)$","$(4, -3)$","$(3, -4)$"]', '$(3, 4)$', NULL, 'A 90 degree clockwise turn about the origin sends $(x, y)$ to $(y, -x)$. So $(-4, 3)$ goes to $(3, 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 clockwise: (x, y) -> (y, -x). (-4, 3) -> (3, 4).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
