INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('af783c89-e4ad-4521-870c-52b4f2b6f976', 'NC26.M1.SGMR.1', 2, 'choice', 'Image of a point under a rotation about the origin', 'A point on the positive x-axis is rotated 270 degrees counterclockwise about the origin. Where does the image lie?', '["on the positive y-axis","on the negative x-axis","on the positive x-axis","on the negative y-axis"]', 'on the negative y-axis', NULL, 'Each 90 degree counterclockwise turn takes a point on the positive x-axis to the positive y-axis, then the negative x-axis, then the negative y-axis. After three of them, 270 degrees, the image is on the negative y-axis.', 'checked', '{"lint":[],"solve":{"answer":"on the negative y-axis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"270 ccw = 90 cw. (1, 0) -> (0, -1): negative y-axis.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
