INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3917dfdc-8b0a-4b3c-988c-7551a965f3ab', 'NC26.M1.SGMR.1', 2, 'choice', 'Find the preimage of a point', 'A translation moves point $K$ 5 units left and 2 units down. The image of $K$ is $(0, -4)$. What are the coordinates of $K$?', '["$(5, -2)$","$(-5, -6)$","$(5, -6)$","$(-5, -2)$"]', '$(5, -2)$', NULL, 'The translation subtracted 5 from x and 2 from y, so undo it: add 5 to x and add 2 to y. $K = (0 + 5, -4 + 2) = (5, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(5, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo: 5 right, 2 up: (0+5, -4+2) = (5, -2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
