INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ca41f548-ebad-4cde-9fef-0f7c609fb9e1', 'NC26.M1.SGMR.1', 2, 'choice', 'Image after a sequence of transformations', 'Dev rotates the point $(3, 1)$ 90 degrees counterclockwise about the origin and then reflects the result across the x-axis. Emma starts at $(3, 1)$, reflects it across the x-axis first, and then rotates the result 90 degrees counterclockwise about the origin. Which statement is true?', '["They end at the same point, $(-1, -3)$.","They end at the same point, $(1, 3)$.","They end at different points: Dev at $(-1, -3)$ and Emma at $(1, 3)$.","They end at different points: Dev at $(1, 3)$ and Emma at $(-1, -3)$."]', 'They end at different points: Dev at $(-1, -3)$ and Emma at $(1, 3)$.', NULL, 'Dev: the turn sends $(3, 1)$ to $(-1, 3)$, and the reflection sends that to $(-1, -3)$. Emma: the reflection sends $(3, 1)$ to $(3, -1)$, and the turn sends that to $(1, 3)$. The order of the moves changes the result.', 'checked', '{"lint":[],"solve":{"answer":"They end at different points: Dev at $(-1, -3)$ and Emma at $(1, 3)$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Dev: (3,1) -> ccw (-1,3) -> reflect x (-1,-3). Emma: (3,1) -> (3,-1) -> ccw (1,3). Different points.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80c95bc8-28fb-4cb7-bd22-59162904948b', 'NC26.M1.SGMR.1', 2, 'numeric', 'Image after a sequence of transformations', 'The point $(-3, 6)$ is reflected across the y-axis. The image is then moved 2 units down and 4 units to the left. What is the sum of the coordinates of the final point?', '[]', '3', '3-4+6-2', 'The reflection gives $(3, 6)$. Moving 2 units down and 4 units left gives $(-1, 4)$. The sum is $-1 + 4 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(-3,6) -> (3,6) -> (3-4, 6-2) = (-1, 4). Sum 3.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f1da3eb-60dd-4aa0-ba2a-936a9a82ed06', 'NC26.M1.SGMR.1', 2, 'choice', 'Show congruence by a sequence of moves', 'Triangle $PQR$ has vertices $P(1, 1)$, $Q(4, 1)$ and $R(1, 3)$. Triangle $STU$ has vertices $S(-1, 4)$, $T(2, 4)$ and $U(-1, 2)$. Which sequence of moves maps $P$ to $S$, $Q$ to $T$ and $R$ to $U$?', '["translate 2 units left and 5 units up, then reflect across the x-axis","reflect across the y-axis, then translate 2 units left and 5 units up","reflect across the x-axis, then translate 2 units left and 5 units up","reflect across the x-axis, then translate 2 units right and 5 units up"]', 'reflect across the x-axis, then translate 2 units left and 5 units up', NULL, 'Reflecting $PQR$ across the x-axis gives $(1, -1)$, $(4, -1)$ and $(1, -3)$. Moving each point 2 units left and 5 units up then gives $(-1, 4)$, $(2, 4)$ and $(-1, 2)$, which are $S$, $T$ and $U$. So the triangles are congruent.', 'checked', '{"lint":[],"solve":{"answer":"reflect across the x-axis, then translate 2 units left and 5 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect x then (-2,+5): P(1,1)->(1,-1)->(-1,4)=S; Q(4,1)->(4,-1)->(2,4)=T; R(1,3)->(1,-3)->(-1,2)=U. Option A gives P->(-3,6); B gives (3,4); D gives (-1,-6).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('203d2a96-09bc-4524-81db-3bd556b16ccc', 'NC26.M1.SGMR.1', 2, 'choice', 'Show congruence by a sequence of moves', 'Triangle $ABC$ has vertices $A(2, 1)$, $B(5, 1)$ and $C(2, 3)$. Triangle $DEF$ has vertices $D(3, 2)$, $E(3, 5)$ and $F(1, 2)$. Which sequence of moves maps $A$ to $D$, $B$ to $E$ and $C$ to $F$?', '["rotate 90 degrees clockwise about the origin, then translate 4 units right","rotate 90 degrees counterclockwise about the origin, then translate 4 units right","translate 4 units right, then rotate 90 degrees counterclockwise about the origin","rotate 180 degrees about the origin, then translate 4 units right"]', 'rotate 90 degrees counterclockwise about the origin, then translate 4 units right', NULL, 'The turn sends $(x, y)$ to $(-y, x)$: $A$ to $(-1, 2)$, $B$ to $(-1, 5)$ and $C$ to $(-3, 2)$. Then moving each point 4 units right gives $(3, 2)$, $(3, 5)$ and $(1, 2)$, which are $D$, $E$ and $F$.', 'checked', '{"lint":[],"solve":{"answer":"rotate 90 degrees counterclockwise about the origin, then translate 4 units right","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 ccw (x,y)->(-y,x) then +4 in x: A(2,1)->(-1,2)->(3,2)=D; B(5,1)->(-1,5)->(3,5)=E; C(2,3)->(-3,2)->(1,2)=F. Others: cw gives A->(5,-2); 180 gives (2,-1); translate-then-ccw gives A->(-1,6).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('35ead7ae-f01f-4d3b-a064-2e3e52445611', 'NC26.M1.SGMR.1', 2, 'numeric', 'Show congruence by a sequence of moves', 'Triangle $ABC$ has vertices $A(1, 1)$, $B(3, 1)$ and $C(1, 4)$. It is reflected across the y-axis and then translated, so that the final image of $A$ is the point $(3, 2)$. What is the y-coordinate of the final image of $C$?', '[]', '5', '4+1', 'The reflection sends $A(1, 1)$ to $(-1, 1)$. To reach $(3, 2)$, the translation moves 4 units right and 1 unit up. The reflection sends $C(1, 4)$ to $(-1, 4)$, and the translation then gives $(3, 5)$. The y-coordinate is 5.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect y-axis: A(-1,1), C(-1,4). Translation sending (-1,1) to (3,2) is (+4,+1). C -> (3,5). y = 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bc8af0d8-a51e-4b08-8916-80057abb5bab', 'NC26.M1.SGMR.1', 2, 'numeric', 'Use congruence to find lengths, angles and areas', 'Triangle $ABC$ is mapped onto triangle $A''B''C''$ by a sequence of rigid transformations. Side $AB = 3x + 2$ and side $A''B'' = 20$. What is the value of $x$?', '[]', '6', '(20-2)/3', 'Rigid transformations keep lengths, so $AB = A''B''$. Then $3x + 2 = 20$, so $3x = 18$ and $x = 6$.', 'checked', '{"lint":[],"solve":{"answer":"6","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = A''B'': 3x + 2 = 20, x = 6.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5489b2a8-b590-4074-b264-a19d0a44cad2', 'NC26.M1.SGMR.1', 2, 'numeric', 'Use congruence to find lengths, angles and areas', 'Quadrilateral $WXYZ$ is reflected across the y-axis to form quadrilateral $W''X''Y''Z''$. The measure of $\angle X$ is $(5y + 10)^\circ$ and the measure of $\angle X''$ is $85^\circ$. What is the value of $y$?', '[]', '15', '(85-10)/5', 'A reflection keeps angle measures, so $5y + 10 = 85$. Then $5y = 75$ and $y = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5y + 10 = 85, 5y = 75, y = 15.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07f03ea6-6057-43c1-aa45-2384719f4fc8', 'NC26.M1.SGMR.1', 2, 'choice', 'Use congruence to find lengths, angles and areas', 'Triangle $ABC$ has vertices $A(1, 1)$, $B(5, 1)$ and $C(1, 4)$. Triangle $A''B''C''$ is its image after a rotation. Which statement must be true?', '["Triangle $A''B''C''$ has a right angle at $B''$.","Triangle $A''B''C''$ has a right angle at $A''$.","Triangle $A''B''C''$ has a right angle at $C''$.","Triangle $A''B''C''$ has no right angle."]', 'Triangle $A''B''C''$ has a right angle at $A''$.', NULL, 'Side $AB$ is horizontal and side $AC$ is vertical, so $\angle A$ is a right angle. A rotation keeps angle measures, so $\angle A''$ is a right angle too.', 'checked', '{"lint":[],"solve":{"answer":"Triangle $A''B''C''$ has a right angle at $A''$.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB is horizontal, AC vertical: right angle at A. Rotation preserves angles and correspondence, so the right angle is at A''.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a3793ef7-e5e5-4896-a212-ccb098b6353b', 'NC26.M1.SGMR.1', 3, 'numeric', 'Use congruence to find a perimeter after two moves', 'Triangle ABC has vertices $A(0, 0)$, $B(4, 0)$ and $C(0, 3)$, so $AB = 4$, $AC = 3$ and $BC = 5$. The triangle is reflected across the x-axis and then translated 6 units to the right. What is the perimeter of the final image?', '[]', '12', '4+3+5', 'Reflections and translations are rigid transformations, so side lengths do not change. The image is congruent to ABC and has perimeter $4 + 3 + 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rigid motions preserve lengths, so the image is congruent: perimeter 4 + 3 + 5 = 12.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e6003365-cb01-4e50-b599-68967118d8a4', 'NC26.M1.SGMR.1', 3, 'numeric', 'Undo a sequence of transformations to find the preimage', 'A figure is translated 5 units to the left and then reflected across the x-axis. The image of one of its points is $(-1, -6)$. What is the sum of the x-coordinate and the y-coordinate of the original point?', '[]', '10', '(-1+5)+6', 'Work backwards. Undo the reflection across the x-axis: $(-1, -6)$ becomes $(-1, 6)$. Undo the translation 5 units left by moving 5 units right: $(4, 6)$. The sum is $4 + 6 = 10$. (Check forward: $(4, 6)$ moves left to $(-1, 6)$, then reflects to $(-1, -6)$.)', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo reflection across x-axis: (-1, -6) -> (-1, 6). Undo translation 5 left (move 5 right): (4, 6). Check: (4,6) -> (-1,6) -> (-1,-6). Sum 10.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9fa1cd67-4d0d-4216-9625-f11c8121022d', 'NC26.M1.SGMR.1', 3, 'choice', 'Describe a sequence of moves that shows congruence', 'Triangle $T$ has vertices $(0, 0)$, $(2, 0)$ and $(0, 1)$. Triangle $T''$ has vertices $(3, 3)$, $(3, 5)$ and $(2, 3)$. Which sequence of rigid transformations maps $T$ onto $T''$?', '["Rotate 90 degrees clockwise about the origin, then translate 3 units right and 3 units up","Reflect across the y-axis, then translate 3 units right and 3 units up","Rotate 90 degrees counterclockwise about the origin, then translate 3 units right and 3 units up","Reflect across the x-axis, then translate 3 units right and 3 units up"]', 'Rotate 90 degrees counterclockwise about the origin, then translate 3 units right and 3 units up', NULL, 'Rotating 90 degrees counterclockwise takes $(x, y)$ to $(-y, x)$: $(0, 0)$, $(0, 2)$ and $(-1, 0)$. Translating 3 right and 3 up gives $(3, 3)$, $(3, 5)$ and $(2, 3)$, which is $T''$. The other sequences give $(3, 3), (3, 1), (4, 3)$ or $(3, 3), (1, 3), (3, 4)$ or $(3, 3), (5, 3), (3, 2)$. Since a sequence of rigid moves maps $T$ onto $T''$, the triangles are congruent.', 'checked', '{"lint":[],"solve":{"answer":"Rotate 90 degrees counterclockwise about the origin, then translate 3 units right and 3 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotate 90 CCW (x,y)->(-y,x): (0,0),(2,0),(0,1) -> (0,0),(0,2),(-1,0); translate (+3,+3): (3,3),(3,5),(2,3) = T''. Others: y-reflect+translate gives (3,3),(1,3),(3,4); x-reflect gives (3,3),(5,3),(3,2); 90 CW gives (3,3),(3,1),(4,3). Only the CCW option works.","run_id":"claude-code","at":"2026-10-17T18:34:55.971Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e006cb76-2cd8-4dfa-93b2-5802f140da40', 'NC26.M1.SGMR.1', 3, 'choice', 'Properties kept by rigid transformations', 'Which statement about rigid transformations is FALSE?', '["A reflection of a figure has a different area from the original figure.","A rotation of a figure has the same perimeter as the original figure.","A translation of a figure has the same angle measures as the original figure.","A reflection of a figure has the same side lengths as the original figure."]', 'A reflection of a figure has a different area from the original figure.', NULL, 'Every rigid transformation keeps side lengths and angle measures, so it also keeps the perimeter and the area. The statement that a reflection changes the area is the false one.', 'checked', '{"lint":[],"solve":{"answer":"A reflection of a figure has a different area from the original figure.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflections preserve lengths; rotations preserve perimeter; translations preserve angles. A reflection preserves area too, so the statement that it changes area is false.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a802011-ee24-4871-b289-aab5a80c8dac', 'NC26.M1.SGMR.1', 3, 'numeric', 'Properties kept by rigid transformations', 'Points $A$ and $B$ are 5 units apart. One rigid transformation maps $A$ to $A''$ and $B$ to $B''$. A second rigid transformation then maps $A''$ to $A''''$ and $B''$ to $B''''$. How far apart, in units, are $A''''$ and $B''''$?', '[]', '5', '5', 'Each rigid transformation keeps the distance between any two points. The distance stays 5 units after the first move and after the second move.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each rigid transformation preserves distance: AB = A''B'' = A''''B'''' = 5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('55fa3002-bf35-4657-be59-aa984f68f6bf', 'NC26.M1.SGMR.1', 3, 'choice', 'Properties kept by rigid transformations', 'Which rigid transformation leaves exactly one point of the plane in its original place?', '["a translation of 4 units to the right","a reflection across the y-axis","a rotation of 360 degrees about the origin","a rotation of 90 degrees about the origin"]', 'a rotation of 90 degrees about the origin', NULL, 'A rotation of 90 degrees about the origin moves every point except the origin, which is the center of the turn. A translation moves every point, a reflection leaves a whole line of points in place, and a full 360 degree turn leaves every point in place.', 'checked', '{"lint":[],"solve":{"answer":"a rotation of 90 degrees about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"360 rotation fixes every point; a nonzero translation fixes none; reflection across y-axis fixes the whole y-axis; a 90 rotation about the origin fixes only the origin.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('00addf65-eb56-401d-838a-8731397049c9', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a translation', 'A triangle has vertices $(2, 3)$, $(6, 3)$ and $(4, 7)$. After a translation, the vertex that was at $(6, 3)$ is at $(-1, 8)$. What is the x-coordinate of the image of the vertex that was at $(4, 7)$?', '[]', '-3', '4-7', 'The vertex went from $(6, 3)$ to $(-1, 8)$, which is 7 units left and 5 units up. Every point moves the same way, so $(4, 7)$ goes to $(4 - 7, 7 + 5) = (-3, 12)$. Its x-coordinate is $-3$.', 'checked', '{"lint":[],"solve":{"answer":"-3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vector = (-1-6, 8-3) = (-7, 5). (4,7) -> (-3, 12). x = -3.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff9a980f-2450-4840-a717-67fee5bf33a7', 'NC26.M1.SGMR.1', 3, 'choice', 'Image of a point under a translation', 'Point $P$ is at $(4, -1)$. It is moved 3 units left, then 5 units up, then 2 units right. Where is it now?', '["$(9, 4)$","$(-1, 4)$","$(3, -6)$","$(3, 4)$"]', '$(3, 4)$', NULL, 'Track the point. Left 3: $(1, -1)$. Up 5: $(1, 4)$. Right 2: $(3, 4)$. The final point is $(3, 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x: 4 - 3 + 2 = 3; y: -1 + 5 = 4. (3, 4).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4bded14-2256-48d9-b6d4-85ce81b1f853', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a translation', 'A translation moves the point $(a, 4)$ to $(9, 1)$. The same translation moves the point $(0, 0)$ to $(-2, -3)$. What is the value of $a$?', '[]', '11', '9+2', 'The origin moved from $(0, 0)$ to $(-2, -3)$, so every point moves 2 units left and 3 units down. Then $(a, 4)$ goes to $(a - 2, 1)$. Setting $a - 2 = 9$ gives $a = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vector (-2, -3). a - 2 = 9 so a = 11; check y: 4 - 3 = 1.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30f06809-ac61-4b89-9451-dea68b965de0', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a reflection', 'The point $(6, 2)$ is reflected across the vertical line $x = 4$. What is the x-coordinate of its image?', '[]', '2', '2*4-6', 'The point is 2 units to the right of the line $x = 4$, so the image is 2 units to the left of it, at $x = 2$. In symbols, $2 \times 4 - 6 = 2$.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"6 is 2 right of x = 4, so the image is 2 left: x = 2.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
