INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('98240947-1722-40be-a362-97a67b6bd123', 'NC26.M1.SGMR.1', 3, 'choice', 'Image of a point under a reflection', 'The point $(-1, 5)$ is reflected across the horizontal line $y = 2$. What are the coordinates of its image?', '["$(-1, -5)$","$(-1, 7)$","$(-1, -1)$","$(1, 5)$"]', '$(-1, -1)$', NULL, 'The point is 3 units above the line $y = 2$, so its image is 3 units below it, at $y = 2 - 3 = -1$. The x-coordinate does not change, so the image is $(-1, -1)$.', 'checked', '{"lint":[],"solve":{"answer":"$(-1, -1)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y = 5 is 3 above y = 2; image is 3 below: y = -1. x unchanged: (-1, -1).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('328be99f-2588-4f63-8f6b-5e0c12b33a77', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a reflection', 'The point $C(-3, 1)$ is reflected across a vertical line $x = c$, and its image is $C''(5, 1)$. What is the value of $c$?', '[]', '1', '(-3+5)/2', 'The line of reflection is halfway between a point and its image. Halfway between $x = -3$ and $x = 5$ is $(-3 + 5) \div 2 = 1$, so the line is $x = 1$.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mirror line is midway: c = (-3 + 5)/2 = 1.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed5845ed-1607-4166-9e12-f44d5c81d70d', 'NC26.M1.SGMR.1', 3, 'choice', 'Image of a point under a rotation about the origin', 'A rectangle has vertices $(1, 2)$, $(5, 2)$, $(5, 4)$ and $(1, 4)$. It is rotated 90 degrees clockwise about the origin. Which point is the image of the vertex $(5, 4)$?', '["$(-4, 5)$","$(4, 5)$","$(4, -5)$","$(5, -4)$"]', '$(4, -5)$', NULL, 'A 90 degree clockwise turn sends $(x, y)$ to $(y, -x)$. The vertex $(5, 4)$ goes to $(4, -5)$.', 'checked', '{"lint":[],"solve":{"answer":"$(4, -5)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 cw: (x, y) -> (y, -x). (5, 4) -> (4, -5).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fbe78f6-6bae-4733-b14f-96297895e377', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a rotation about the origin', 'The point $(-3, 5)$ is rotated 90 degrees counterclockwise about the origin three times in a row. What is the sum of the coordinates of the final image?', '[]', '8', '5+3', 'A 90 degree counterclockwise turn sends $(x, y)$ to $(-y, x)$. Starting at $(-3, 5)$: first $(-5, -3)$, then $(3, -5)$, then $(5, 3)$. The sum of the coordinates is $5 + 3 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three 90 ccw turns = 270 ccw = 90 cw: (x, y) -> (y, -x). (-3, 5) -> (5, 3). Check step by step: (-3,5) -> (-5,-3) -> (3,-5) -> (5,3). Sum 8.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
