INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('612df198-1bbd-41f9-bfc4-a82b4ca4825a', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image of a point under a rotation about the origin', 'The point $Q(-8, -3)$ is rotated 270 degrees clockwise about the origin. What is the x-coordinate of the image?', '[]', '3', '3', 'A 270 degree clockwise turn is the same as a 90 degree counterclockwise turn, which sends $(x, y)$ to $(-y, x)$. So $(-8, -3)$ goes to $(3, -8)$, and the x-coordinate is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"270 cw = 90 ccw: (x, y) -> (-y, x). (-8, -3) -> (3, -8). x = 3.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6222a0a1-6464-42bb-a991-46318681fdf2', 'NC26.M1.SGMR.1', 3, 'numeric', 'Transformations written in function notation', 'A translation is given by $T(x, y) = (x - 6, y + 3)$. It is applied to the point $(2, 5)$, and then applied again to the result. What is the x-coordinate of the final point?', '[]', '-10', '2-6-6', 'First application: $T(2, 5) = (-4, 8)$. Second application: $T(-4, 8) = (-10, 11)$. The x-coordinate is $-10$.', 'checked', '{"lint":[],"solve":{"answer":"-10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(2,5) -> (-4, 8) -> (-10, 11). x = -10.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ebd18bcc-caae-46ad-9136-ef51d4f26eff', 'NC26.M1.SGMR.1', 3, 'choice', 'Transformations written in function notation', 'Which rule describes the translation that moves the point $(2, -3)$ to the point $(-1, 4)$?', '["$T(x, y) = (x + 3, y - 7)$","$T(x, y) = (x - 3, y - 7)$","$T(x, y) = (x - 3, y + 7)$","$T(x, y) = (x + 7, y - 3)$"]', '$T(x, y) = (x - 3, y + 7)$', NULL, 'The x-coordinate went from 2 to $-1$, a change of $-3$. The y-coordinate went from $-3$ to 4, a change of $+7$. So the rule is $T(x, y) = (x - 3, y + 7)$.', 'checked', '{"lint":[],"solve":{"answer":"$T(x, y) = (x - 3, y + 7)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Change: x 2 -> -1 is -3; y -3 -> 4 is +7. (x - 3, y + 7).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1c4edeb7-ff5f-402e-bc1d-9b258f3d79eb', 'NC26.M1.SGMR.1', 3, 'numeric', 'Transformations written in function notation', 'Let $T(x, y) = (x + 2, y - 4)$ and $R(x, y) = (-x, y)$. The rule $T$ is applied to the point $(6, 1)$, and then $R$ is applied to the result. What is the x-coordinate of the final point?', '[]', '-8', '-(6+2)', '$T(6, 1) = (8, -3)$. Then $R(8, -3) = (-8, -3)$. The x-coordinate is $-8$.', 'checked', '{"lint":[],"solve":{"answer":"-8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"T(6, 1) = (8, -3); R(8, -3) = (-8, -3). x = -8.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb2f4b3e-544a-416c-96e2-b152d1bc9427', 'NC26.M1.SGMR.1', 3, 'numeric', 'Find the preimage of a point', 'A point is rotated 90 degrees clockwise about the origin and then translated 3 units up. Its final image is $(5, 1)$. What is the x-coordinate of the original point?', '[]', '2', '2', 'Undo the moves in reverse order. Undo the translation by moving 3 units down: $(5, -2)$. Undo the clockwise turn by turning 90 degrees counterclockwise, which sends $(x, y)$ to $(-y, x)$: $(2, 5)$. The original x-coordinate is 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undo translation: (5, -2). 90 cw maps (x, y) -> (y, -x) = (5, -2), so y = 5, x = 2. Original (2, 5); x = 2.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f9941d87-5a89-4d38-a690-455d7306c5bb', 'NC26.M1.SGMR.1', 3, 'choice', 'Find the preimage of a point', 'The rule $T(x, y) = (x - 7, y + 3)$ maps a point $P$ to the point $(1, 1)$. What are the coordinates of $P$?', '["$(-6, 4)$","$(8, 4)$","$(-6, -2)$","$(8, -2)$"]', '$(8, -2)$', NULL, 'The rule subtracts 7 from x and adds 3 to y, so undo it: add 7 to x and subtract 3 from y. $P = (1 + 7, 1 - 3) = (8, -2)$.', 'checked', '{"lint":[],"solve":{"answer":"$(8, -2)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x - 7 = 1 -> x = 8; y + 3 = 1 -> y = -2. P = (8, -2).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3abd0631-0ca9-4235-9210-c6a04ad2d116', 'NC26.M1.SGMR.1', 3, 'numeric', 'Find the preimage of a point', 'A rectangle is reflected across the vertical line $x = 3$. One vertex of the image is at $(7, 2)$. What is the x-coordinate of the matching vertex of the original rectangle?', '[]', '-1', '2*3-7', 'The image vertex is 4 units to the right of the line $x = 3$, so the original vertex is 4 units to the left of it, at $x = 3 - 4 = -1$. In symbols, $2 \times 3 - 7 = -1$.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"7 is 4 right of x = 3, so the original is 4 left: x = -1.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdc76f89-d7a7-4397-bd2d-9e0bd7ddd8bc', 'NC26.M1.SGMR.1', 3, 'choice', 'Identify the transformation from points and images', 'A transformation takes $A(1, 4)$ to $A''(4, 1)$ and $B(2, 7)$ to $B''(7, 2)$. Which transformation is it?', '["a rotation of 90 degrees clockwise about the origin","a reflection across the y-axis","a reflection across the line $y = x$","a translation 3 units right and 3 units down"]', 'a reflection across the line $y = x$', NULL, 'In each case the two coordinates swapped places, which is a reflection across the line $y = x$. A slide of 3 right and 3 down fits $A$, but it would take $B$ to $(5, 4)$, not $(7, 2)$.', 'checked', '{"lint":[],"solve":{"answer":"a reflection across the line $y = x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Coordinates swap for both points: reflection across y = x. Translation (3,-3) sends B to (5,4); 90 cw sends A to (4,-1).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fe258765-d121-412f-bd9b-bd6033704bad', 'NC26.M1.SGMR.1', 3, 'numeric', 'Identify the transformation from points and images', 'A single translation takes $A(3, -2)$ to $A''(-1, 5)$. The same translation takes $B$ to $B''(4, 6)$. What is the sum of the coordinates of $B$?', '[]', '7', '8-1', 'From $A$ to $A''$ the point moved 4 units left and 7 units up. To find $B$, undo that: move $B''$ 4 units right and 7 units down. $B = (4 + 4, 6 - 7) = (8, -1)$, and the sum is $8 + (-1) = 7$.', 'checked', '{"lint":[],"solve":{"answer":"7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vector = (-1-3, 5-(-2)) = (-4, 7). B = (4+4, 6-7) = (8, -1). Sum 7.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7a63e84d-7a8a-4900-b118-2d7fc1a77a87', 'NC26.M1.SGMR.1', 3, 'choice', 'Identify the transformation from points and images', 'A rotation about the origin takes $P(6, 2)$ to $P''(-2, 6)$. The same rotation takes $Q(4, -3)$ to $Q''$. What are the coordinates of $Q''$?', '["$(-3, -4)$","$(3, 4)$","$(-4, 3)$","$(3, -4)$"]', '$(3, 4)$', NULL, 'A rotation sending $(6, 2)$ to $(-2, 6)$ is a 90 degree counterclockwise turn, which sends $(x, y)$ to $(-y, x)$. So $Q(4, -3)$ goes to $(3, 4)$.', 'checked', '{"lint":[],"solve":{"answer":"$(3, 4)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(6,2) -> (-2,6) is (x, y) -> (-y, x), 90 ccw. (4, -3) -> (3, 4).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d2c8f763-207c-4a41-bd97-af0b57d9ff34', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image after a sequence of transformations', 'Vertex $A(1, 2)$ of a triangle is reflected across the vertical line $x = 3$, then rotated 180 degrees about the origin, then translated 2 units up. What is the sum of the coordinates of the final image of $A$?', '[]', '-5', '-5+0', 'The reflection across $x = 3$ gives $(5, 2)$. The 180 degree turn gives $(-5, -2)$. Moving 2 units up gives $(-5, 0)$. The sum is $-5 + 0 = -5$.', 'checked', '{"lint":[],"solve":{"answer":"-5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Reflect across x = 3: (1,2) -> (5,2). Rotate 180: (-5,-2). Up 2: (-5, 0). Sum -5.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bb7b5409-7eb8-4e41-8ed0-0b6e80796036', 'NC26.M1.SGMR.1', 3, 'choice', 'Image after a sequence of transformations', 'Reflecting a figure across the x-axis and then across the y-axis has the same effect as which single transformation?', '["a reflection across the line $y = x$","a rotation of 180 degrees about the origin","a rotation of 90 degrees counterclockwise about the origin","a rotation of 90 degrees clockwise about the origin"]', 'a rotation of 180 degrees about the origin', NULL, 'The first reflection sends $(x, y)$ to $(x, -y)$ and the second sends that to $(-x, -y)$. Changing the sign of both coordinates is a rotation of 180 degrees about the origin.', 'checked', '{"lint":[],"solve":{"answer":"a rotation of 180 degrees about the origin","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(x,y) -> (x,-y) -> (-x,-y): rotation of 180 about the origin.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4a1979e3-18c6-419e-877b-04f9929027e5', 'NC26.M1.SGMR.1', 3, 'numeric', 'Image after a sequence of transformations', 'The point $P(5, -2)$ is reflected across the line $y = x$, then translated 4 units down, then reflected across the y-axis. What is the sum of the coordinates of the final point?', '[]', '3', '2+1', 'Reflecting across $y = x$ swaps the coordinates: $(-2, 5)$. Moving 4 units down gives $(-2, 1)$. Reflecting across the y-axis gives $(2, 1)$. The sum is $2 + 1 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(5,-2) -> y = x: (-2,5) -> down 4: (-2,1) -> across y-axis: (2,1). Sum 3.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8eddbd6a-a945-4a1a-8956-458df3df76ac', 'NC26.M1.SGMR.1', 3, 'choice', 'Show congruence by a sequence of moves', 'Triangle $JKL$ has vertices $J(0, 0)$, $K(4, 0)$ and $L(0, 3)$. Triangle $J''K''L''$ has vertices $J''(2, 5)$, $K''(2, 1)$ and $L''(5, 5)$. Which sequence of moves maps $J$ to $J''$, $K$ to $K''$ and $L$ to $L''$?', '["rotate 90 degrees clockwise about the origin, then translate 2 units right and 5 units up","rotate 90 degrees counterclockwise about the origin, then translate 2 units right and 5 units up","reflect across the x-axis, then translate 2 units right and 5 units up","translate 2 units right and 5 units up, then rotate 90 degrees clockwise about the origin"]', 'rotate 90 degrees clockwise about the origin, then translate 2 units right and 5 units up', NULL, 'Side $JK$ lies along the x-axis, and $J''K''$ points straight down from $J''$. A 90 degree clockwise turn sends $(x, y)$ to $(y, -x)$: $J$ stays at $(0, 0)$, $K$ goes to $(0, -4)$ and $L$ goes to $(3, 0)$. Moving each point 2 units right and 5 units up gives $(2, 5)$, $(2, 1)$ and $(5, 5)$.', 'checked', '{"lint":[],"solve":{"answer":"rotate 90 degrees clockwise about the origin, then translate 2 units right and 5 units up","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"90 cw (x,y)->(y,-x) then (+2,+5): J->(0,0)->(2,5); K(4,0)->(0,-4)->(2,1); L(0,3)->(3,0)->(5,5). All match. B gives J->(5,-2); C gives K->(2,9); D gives K->(6,5).","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ade6daef-288b-467b-98d4-350d65587a97', 'NC26.M1.SGMR.1', 3, 'choice', 'Show congruence by a sequence of moves', 'The vertices of triangle $ABC$ go around clockwise in the order $A, B, C$. The vertices of congruent triangle $A''B''C''$, with $A''$ matching $A$, $B''$ matching $B$ and $C''$ matching $C$, go around counterclockwise in the order $A'', B'', C''$. Which type of move must be part of any sequence of rigid transformations that maps $ABC$ onto $A''B''C''$?', '["a rotation","a translation","a rotation of 180 degrees","a reflection"]', 'a reflection', NULL, 'Translations and rotations keep the order of the vertices clockwise or counterclockwise. Only a reflection reverses it, so any sequence that turns a clockwise triangle into a counterclockwise one must include a reflection.', 'checked', '{"lint":[],"solve":{"answer":"a reflection","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Orientation is reversed; rotations and translations preserve orientation, so a reflection must be used.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5a6d94f0-b36d-4b88-8e20-5fb30be6bd08', 'NC26.M1.SGMR.1', 3, 'numeric', 'Show congruence by a sequence of moves', 'Triangle $ABC$ has vertices $A(2, 1)$, $B(6, 1)$ and $C(2, 4)$. A rotation of 180 degrees about the origin followed by a translation maps $A$ to $A''(1, 5)$. What is the sum of the coordinates of $C''$?', '[]', '3', '-2+3-4+6', 'The rotation sends $A(2, 1)$ to $(-2, -1)$. To reach $(1, 5)$, the translation moves 3 units right and 6 units up. The rotation sends $C(2, 4)$ to $(-2, -4)$, and the translation then gives $(1, 2)$. The sum is $1 + 2 = 3$.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180: A(2,1) -> (-2,-1); translation to (1,5) is (+3,+6). C(2,4) -> (-2,-4) -> (1,2). Sum 3.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2fd3d6a6-a894-434c-8cb6-6535833ff491', 'NC26.M1.SGMR.1', 3, 'numeric', 'Use congruence to find lengths, angles and areas', 'A triangle has vertices $(1, 1)$, $(7, 1)$ and $(1, 5)$. It is rotated 90 degrees clockwise about the origin and then translated 3 units left. What is the area of the final image, in square units?', '[]', '12', '6*4/2', 'The triangle has a horizontal side of 6 units and a vertical side of 4 units that meet at a right angle. Its area is $6 \times 4 \div 2 = 12$ square units. The moves are rigid, so the image has the same area.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Right triangle with legs 6 and 4: area 12; rigid motions preserve area.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a38c76f8-e073-4a80-8eda-cb35bec6f08b', 'NC26.M1.SGMR.1', 3, 'numeric', 'Use congruence to find lengths, angles and areas', 'Triangle $ABC$ is mapped onto triangle $DEF$ by a sequence of rigid transformations. Side $AB = 7$, side $BC = 9$, and the perimeter of triangle $DEF$ is 30. What is the length of side $AC$?', '[]', '14', '30-7-9', 'Rigid transformations keep side lengths, so triangle $ABC$ also has perimeter 30. Then $AC = 30 - 7 - 9 = 14$.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Congruent, so perimeter of ABC is 30: AC = 30 - 7 - 9 = 14.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d9be773-7d1b-49ef-a391-60f60f071c77', 'NC26.M1.SGMR.1', 3, 'choice', 'Use congruence to find lengths, angles and areas', 'A triangle has sides of 5, 12 and 13 units, so its perimeter is 30 units and its area is 30 square units. Which of these could NOT be the image of this triangle after a sequence of rotations, reflections and translations?', '["a triangle whose shortest side is 6 units","a right triangle with an area of 30 square units","a triangle with a perimeter of 30 units","a triangle whose longest side is 13 units"]', 'a triangle whose shortest side is 6 units', NULL, 'The image is congruent to the original, so its sides are still 5, 12 and 13 units, its perimeter is still 30 and its area is still 30. A shortest side of 6 units is not possible, because the shortest side stays 5 units.', 'checked', '{"lint":[],"solve":{"answer":"a triangle whose shortest side is 6 units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The image is congruent: sides 5, 12, 13, perimeter 30, right triangle with area 30. Shortest side must be 5, not 6.","run_id":"claude-code","at":"2026-10-18T01:07:47.267Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('01bf57d6-7915-46e7-9e86-0760f679b84f', 'NC26.M1.SGMR.2', 1, 'numeric', 'Corresponding sides of congruent triangles', 'Triangle $ABC$ is congruent to triangle $DEF$, with $A$ matching $D$, $B$ matching $E$, and $C$ matching $F$. In triangle $ABC$, $AB = 7$ cm, $BC = 9$ cm, and $AC = 11$ cm. What is the length of $EF$, in centimeters?', '[]', '9', '9', 'The letters match in order, so $B$ matches $E$ and $C$ matches $F$. That makes side $EF$ match side $BC$. Matching sides of congruent triangles are equal, so $EF = BC = 9$ centimeters.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correspondence A-D, B-E, C-F, so EF corresponds to BC = 9 cm.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2a1b7828-b494-42a3-a489-44dbc2d0254f', 'NC26.M1.SGMR.2', 1, 'choice', 'Naming the SSS criterion', 'Two triangles have three pairs of equal sides. Which rule shows that the two triangles are congruent?', '["SAS","ASA","SSS","AAA"]', 'SSS', NULL, 'Three pairs of equal sides is the side-side-side (SSS) rule. SAS and ASA each need an angle, and equal angles alone (AAA) do not prove congruence.', 'checked', '{"lint":[],"solve":{"answer":"SSS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three pairs of equal sides is the Side-Side-Side criterion.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('949ee55d-1f09-49c5-aa5b-7faf9c55c142', 'NC26.M1.SGMR.2', 1, 'choice', 'Rigid motions and congruence', 'Which of these transformations does NOT always produce a figure congruent to the original?', '["a dilation with scale factor 2","a translation","a reflection","a rotation"]', 'a dilation with scale factor 2', NULL, 'Translations, reflections and rotations are rigid motions: they keep every length and angle, so the image is congruent to the original. A dilation with scale factor 2 doubles every length, so the image is larger and not congruent.', 'checked', '{"lint":[],"solve":{"answer":"a dilation with scale factor 2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Translations, rotations and reflections are rigid motions and preserve size; a dilation with scale factor 2 doubles lengths, so the image is not congruent.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
