INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('743810aa-efc1-47bc-84d0-1c0bae3d2081', 'NC26.M1.SGMR.2', 1, 'choice', 'Rigid motions preserve size and shape', 'Which of these moves is a rigid motion?', '["Turning a triangle $90^\\circ$ about a vertex","Doubling the length of every side of a triangle","Stretching a triangle to twice its original height","Shrinking a triangle to half of its original size"]', 'Turning a triangle $90^\circ$ about a vertex', NULL, 'A rigid motion moves a figure without changing its size or shape. A turn (rotation) does that. The other moves change lengths.', 'checked', '{"lint":[],"solve":{"answer":"Turning a triangle $90^\\circ$ about a vertex","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Rotation is rigid; the others change size.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
