INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e8fd0416-66c7-4824-9ba6-828c66453a2c', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'In triangles $ABC$ and $DEF$, $\angle A = \angle D$, $\angle B = \angle E$ and $BC = EF$. Using only the facts given, which rule shows that the triangles are congruent?', '["SSS (side-side-side)","SAS (side-angle-side)","ASA (angle-side-angle)","AAS (angle-angle-side)"]', 'AAS (angle-angle-side)', NULL, 'Two angles and a side are equal. The side $BC$ is not the side between $\angle A$ and $\angle B$ (that is $AB$), so the rule is AAS.', 'checked', '{"lint":[],"solve":{"answer":"AAS (angle-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Angles A, B; side BC is not between A and B (that is AB): AAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d5b64d6-076c-4298-aec7-7c7c5db6ba5a', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Triangle $ABC$ has sides of 5 cm, 7 cm and 9 cm. Triangle $XYZ$ has sides of 9 cm, 5 cm and 7 cm. What can be concluded?', '["They are congruent, by SSS","They are congruent, by SAS","They are not congruent, as the sides are in a different order","They cannot be compared without the angles"]', 'They are congruent, by SSS', NULL, 'Both triangles have the same three side lengths. The order in which they are listed does not matter, so they are congruent by SSS.', 'checked', '{"lint":[],"solve":{"answer":"They are congruent, by SSS","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Same three side lengths: SSS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb325b13-8dcc-4755-ad26-a6e75bfc83ce', 'NC26.M1.SGMR.2', 1, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Which rule uses two angles and a side that is NOT between those two angles?', '["SSS (side-side-side)","AAS (angle-angle-side)","SAS (side-angle-side)","ASA (angle-side-angle)"]', 'AAS (angle-angle-side)', NULL, 'In AAS the equal side is not between the two equal angles. In ASA the side is between them.', 'checked', '{"lint":[],"solve":{"answer":"AAS (angle-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Non-included side: AAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
