INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e3807cb-8e19-4c65-a414-c61d7fd43a95', 'NC26.M1.SGMR.2', 1, 'choice', 'Why some information does not prove congruence', 'Triangle 1 has angles of $30^\circ$, $60^\circ$ and $90^\circ$ and a shortest side of 3 cm. Triangle 2 has the same three angles and a shortest side of 6 cm. Are the triangles congruent?', '["Yes, because the three angles are equal","Yes, because both are right triangles","It cannot be decided without more angles","No, because their matching sides are not equal"]', 'No, because their matching sides are not equal', NULL, 'Congruent triangles have equal matching sides. The shortest sides, 3 cm and 6 cm, are different, so the triangles are the same shape but not the same size, and are not congruent.', 'checked', '{"lint":[],"solve":{"answer":"No, because their matching sides are not equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Shortest sides 3 vs 6 differ: not congruent (similar only).","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89245057-f8d4-4001-b762-fb8d76d56055', 'NC26.M1.SGMR.2', 1, 'choice', 'Why some information does not prove congruence', 'Two triangles each have a side of 6 cm and a side of 8 cm. Is that enough to say they are congruent?', '["No, the angle between them or the third side is also needed","Yes, two equal pairs of sides are always enough to prove it","Yes, as long as the two triangles have equal perimeters","No, because three equal angles are always required in every case"]', 'No, the angle between them or the third side is also needed', NULL, 'Two sides do not fix a triangle: the angle between them can open wider or narrower. Another fact, such as the included angle or the third side, is needed.', 'checked', '{"lint":[],"solve":{"answer":"No, the angle between them or the third side is also needed","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two sides alone are not enough; need included angle (SAS) or third side (SSS).","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
