INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7399c41-5fd6-4041-9785-59aee214f76b', 'NC26.M1.SGMR.2', 1, 'choice', 'Why some information does not prove congruence', 'One triangle has three sides of 3 cm. Another triangle has three sides of 4 cm. Are they congruent?', '["Yes, because every angle in both triangles is $60^\\circ$","No, because their side lengths are different","Yes, because both triangles have three equal sides","Yes, because the two triangles have the same shape"]', 'No, because their side lengths are different', NULL, 'Both triangles have three $60^\circ$ angles, but the sides, 3 cm and 4 cm, are not equal. Congruent triangles must have equal sides, so these are not congruent.', 'checked', '{"lint":[],"solve":{"answer":"No, because their side lengths are different","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides 3 vs 4 differ.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4666075b-cc23-47bd-a5b4-47ce734af0c5', 'NC26.M1.SGMR.2', 1, 'numeric', 'Using the angle sum before arguing congruence', 'Two congruent triangles are drawn. In the first triangle, two of the angles are $35^\circ$ and $85^\circ$. What is the measure of the third angle of the second triangle, in degrees?', '[]', '60', '180-35-85', 'The angles of the first triangle add to $180^\circ$, so its third angle is $180 - 35 - 85 = 60^\circ$. The second triangle has the same angles.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"180-35-85 = 60.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('631a9319-e1c6-4d22-ae1a-671e82dcf31c', 'NC26.M1.SGMR.2', 1, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle ABC \cong \triangle FED$, with the vertices matching in the order written. Which angle of $\triangle FED$ matches $\angle B$?', '["$\\angle F$","$\\angle D$","$\\angle B$","$\\angle E$"]', '$\angle E$', NULL, 'The letters match in order: $A$ with $F$, $B$ with $E$, $C$ with $D$. So $\angle B$ matches $\angle E$.', 'checked', '{"lint":[],"solve":{"answer":"$\\angle E$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A-F, B-E, C-D: angle E.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ad0eaf67-7736-4513-8b4f-2214bf4763d6', 'NC26.M1.SGMR.2', 1, 'choice', 'Reading a congruence statement (vertex order)', '$\triangle RST \cong \triangle UVW$, with the vertices matching in the order written. Which pair of sides must be equal in length?', '["$ST$ and $VW$","$ST$ and $UV$","$ST$ and $UW$","$RT$ and $VW$"]', '$ST$ and $VW$', NULL, '$R$ matches $U$, $S$ matches $V$ and $T$ matches $W$. Side $ST$ joins $S$ and $T$, so it matches $VW$.', 'checked', '{"lint":[],"solve":{"answer":"$ST$ and $VW$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"S-V, T-W: ST matches VW.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
