INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dd07972-5f27-4a0c-bd9d-3bdda7b3c20d', 'NC26.M1.SGMR.2', 2, 'choice', 'Corresponding parts of congruent triangles', 'Two triangles are congruent. Which statement about their areas must be true?', '["One area is larger than the other","One area is twice the other","The two areas are equal","The areas depend on the letters used"]', 'The two areas are equal', NULL, 'Congruent triangles have the same shape and size, so the space they cover, their area, is the same.', 'checked', '{"lint":[],"solve":{"answer":"The two areas are equal","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Congruent figures have equal area.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
