INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f654457e-3d35-4440-9066-51b49c781d1f', 'NC26.M1.SGMR.2', 2, 'numeric', 'Solving for an unknown using congruent triangles', 'In triangles $ABC$ and $DEF$, $AB = DE$, $BC = EF$, $\angle B = (3x + 4)^\circ$ and $\angle E = (5x - 20)^\circ$. The triangles are congruent by SAS. What is the value of $x$?', '[]', '12', '(20+4)/2', 'The triangles are congruent, so the matching angles $B$ and $E$ are equal: $3x + 4 = 5x - 20$. Then $2x = 24$ and $x = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"B is the included angle between AB and BC, E between DE and EF; SAS needs B = E: 3x+4 = 5x-20, x = 12 (40 degrees).","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
