INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b45674bd-261d-444f-9823-617c65fe48ac', 'NC26.M1.SGMR.2', 2, 'numeric', 'Rigid motions preserve size and shape', 'A triangle has vertices $A(2, 3)$, $B(6, 3)$ and $C(2, 6)$. It is reflected across the $x$-axis. What is the perimeter of the reflected triangle, in units?', '[]', '12', '4+3+5', 'The sides of the original are $AB = 4$, $AC = 3$ and $BC = 5$ (a 3-4-5 right triangle). The reflection keeps these lengths, so the perimeter is $4 + 3 + 5 = 12$.', 'checked', '{"lint":[],"solve":{"answer":"12","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = 4, AC = 3, BC = 5; perimeter 12, preserved by reflection.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('40900c15-d7e1-4b1c-af12-e6ef21afa03c', 'NC26.M1.SGMR.2', 2, 'numeric', 'Rigid motions preserve size and shape', 'A triangle has vertices $(1, 1)$, $(4, 1)$ and $(4, 5)$. It is translated 2 units left and 3 units up. What is the $y$-coordinate of the image of the vertex $(4, 5)$?', '[]', '8', '5+3', 'Moving 3 units up adds 3 to the $y$-coordinate: $5 + 3 = 8$. (The move 2 units left changes only the $x$-coordinate, to 2.)', 'checked', '{"lint":[],"solve":{"answer":"8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(4,5) -> (2,8); y = 8.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84e167aa-3e6c-44e4-b5da-f413a90dfad4', 'NC26.M1.SGMR.2', 2, 'choice', 'Rigid motions preserve size and shape', 'Triangle $ABC$ is reflected across a line and then translated 6 units to the right to make triangle $DEF$. What can be concluded?', '["The triangles are only similar, as two moves were used","The triangles have equal angles but may have unequal sides","$\\triangle ABC \\cong \\triangle DEF$, as both moves keep lengths and angles","$\\triangle ABC \\cong \\triangle DEF$ only if the line passes through a vertex"]', '$\triangle ABC \cong \triangle DEF$, as both moves keep lengths and angles', NULL, 'A reflection and a translation are both rigid motions. A sequence of rigid motions keeps all lengths and angles, so the final triangle is congruent to the first.', 'checked', '{"lint":[],"solve":{"answer":"$\\triangle ABC \\cong \\triangle DEF$, as both moves keep lengths and angles","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Composition of rigid motions is rigid, so congruent.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3afc6af6-834c-4c74-853e-2439349c2fe3', 'NC26.M1.SGMR.2', 2, 'numeric', 'Rigid motions preserve size and shape', 'A rigid motion maps $\triangle ABC$ onto $\triangle A''B''C''$. Angle $A$ measures $52^\circ$, and angle $A''$ measures $(2x + 4)^\circ$. What is the value of $x$?', '[]', '24', '(52-4)/2', 'Rigid motions keep angle measures, so $2x + 4 = 52$. Then $2x = 48$ and $x = 24$.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2x+4 = 52, x = 24.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87cdd4e1-3aa7-4c8c-a274-2eb3f5f8bf0c', 'NC26.M1.SGMR.2', 2, 'choice', 'Choosing the congruence criterion (SSS, SAS, ASA, AAS)', 'Triangles $ABC$ and $DBC$ share the side $BC$. Also $AB = DB$ and $\angle ABC = \angle DBC$. Which rule shows that $\triangle ABC \cong \triangle DBC$?', '["SSS (side-side-side)","ASA (angle-side-angle)","AAS (angle-angle-side)","SAS (side-angle-side)"]', 'SAS (side-angle-side)', NULL, '$AB = DB$, $\angle ABC = \angle DBC$ (the angle between $AB$ and $BC$) and $BC = BC$ (shared). Two sides and the angle between them match, so SAS.', 'checked', '{"lint":[],"solve":{"answer":"SAS (side-angle-side)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"AB = DB, included angle ABC = DBC, shared BC: SAS.","run_id":"claude-code","at":"2026-10-18T03:39:02.764Z"}}', 'ai', NULL, NULL)
