INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b997c20-b849-4cf2-a09d-5fa53c624c0a', 'NC26.M1.SGMR.3', 1, 'numeric', 'Classify a triangle by its sides', 'A triangle has vertices $(0, 0)$, $(6, 0)$ and $(0, 6)$. How many of its sides are exactly 6 units long?', '[]', '2', '2', 'The side from $(0, 0)$ to $(6, 0)$ runs along the $x$-axis and is 6 units long. The side from $(0, 0)$ to $(0, 6)$ runs along the $y$-axis and is 6 units long. The third side is slanted and longer than 6. So 2 sides are 6 units long.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sides: 6 (along x-axis), 6 (along y-axis), 6*sqrt(2) (hypotenuse). Two sides of 6.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
