INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('69b1d229-ebac-46a0-bcca-130b3bf905de', 'NC26.M1.SGMR.3', 1, 'choice', 'Decide whether a triangle is a right triangle', 'A triangle has vertices $(0, 0)$, $(5, 0)$ and $(0, 7)$. At which vertex is the right angle?', '["$(0, 0)$","$(5, 0)$","$(0, 7)$","The triangle has no right angle"]', '$(0, 0)$', NULL, 'One side runs along the $x$-axis (horizontal) and another along the $y$-axis (vertical). Horizontal and vertical lines are perpendicular, so the angle where they meet, at $(0, 0)$, is a right angle.', 'checked', '{"lint":[],"solve":{"answer":"$(0, 0)$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Legs along the x-axis and y-axis meet at (0, 0).","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab11382f-7920-435c-9539-7193b0b73382', 'NC26.M1.SGMR.3', 1, 'numeric', 'Decide whether a triangle is a right triangle', 'In triangle $ABC$, $A$ is $(0, 0)$, $B$ is $(4, 0)$ and $C$ is $(4, 6)$. What is the measure of angle $B$, in degrees?', '[]', '90', '90', 'Side $BA$ is horizontal (along the $x$-axis) and side $BC$ is vertical (it goes straight up from $(4, 0)$ to $(4, 6)$). A horizontal line and a vertical line meet at a right angle, so angle $B$ is 90 degrees.', 'checked', '{"lint":[],"solve":{"answer":"90","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"BA = (-4, 0) horizontal, BC = (0, 6) vertical: angle B = 90.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
