INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3df6af9b-94ee-4772-83b8-2bd2f5578ea6', 'NC26.M1.SGMR.3', 1, 'choice', 'Perimeter from coordinates', 'A rectangle has opposite corners at $(-3, 1)$ and $(4, 5)$, and its sides are horizontal and vertical. What is its perimeter, in units?', '["28","22","11","14"]', '22', '2*(7+4)', 'The width is $4 - (-3) = 7$ and the height is $5 - 1 = 4$. The perimeter is $2(7 + 4) = 22$ units. (28 is the area, and 11 is only half the perimeter.)', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 4 - (-3) = 7, height 5 - 1 = 4. Perimeter 2(11) = 22.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
