INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('77bd3861-5a4a-4d0a-b071-8a4609263641', 'NC26.M1.SGMR.3', 1, 'numeric', 'Area from coordinates', 'A rectangle has opposite corners at $(2, 3)$ and $(9, 6)$, and its sides are horizontal and vertical. What is its area, in square units?', '[]', '21', '7*3', 'The width is $9 - 2 = 7$ and the height is $6 - 3 = 3$. The area is $7 \times 3 = 21$ square units.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Width 7, height 3: area 21.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
