INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e5bc9f0a-a585-41db-b8c0-013789be8356', 'NC26.M1.SGMR.3', 1, 'numeric', 'Area from coordinates', 'A right triangle has vertices $(0, 0)$, $(6, 0)$ and $(0, 5)$. What is its area, in square units?', '[]', '15', '6*5/2', 'The two legs lie along the axes, with lengths 6 and 5. The area of a triangle is $\frac{1}{2} \times \text{base} \times \text{height} = \frac{1}{2} \times 6 \times 5 = 15$ square units.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1/2)(6)(5) = 15.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('87b2c70b-6b3c-4dcf-8876-b87ea0371a14', 'NC26.M1.SGMR.3', 1, 'choice', 'Area from coordinates', 'A triangle has vertices $(1, 2)$, $(7, 2)$ and $(4, 8)$. What is its area, in square units?', '["36","12","18","24"]', '18', '6*6/2', 'The base from $(1, 2)$ to $(7, 2)$ is horizontal and 6 units long. The height is the vertical distance from the base to the top vertex: $8 - 2 = 6$. The area is $\frac{1}{2} \times 6 \times 6 = 18$ square units. (36 forgets the one half.)', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Base 6 (on y = 2), height 8 - 2 = 6. Area 18.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
