INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('052826ed-19f7-4ea3-a91e-b71419ef5fb9', 'NC26.M1.SGMR.3', 1, 'numeric', 'Distance between two points', 'A vertical segment connects $(2, 3)$ and $(2, 12)$. How long is the segment, in units?', '[]', '9', '12-3', 'Both points have $x$-coordinate 2, so the segment is vertical. Its length is the difference of the $y$-coordinates: $12 - 3 = 9$ units.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"12 - 3 = 9.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
