INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4af600c2-eb2a-4444-8cbe-5f447741c847', 'NC26.M1.SGMR.3', 1, 'numeric', 'Distance between two points', 'How far is the point $(6, 8)$ from the origin, in units?', '[]', '10', '10', 'Use the distance formula: $\sqrt{(6 - 0)^2 + (8 - 0)^2} = \sqrt{36 + 64} = \sqrt{100} = 10$ units.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"sqrt(36 + 64) = 10.","run_id":"claude-code","at":"2026-10-18T01:07:47.307Z"}}', 'ai', NULL, NULL)
