INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0869d20d-c7d9-41a3-bf79-ac3ac3de530f', 'NC26.M1.SDSR.1', 1, 'numeric', 'Joint probability from a two-way table', 'A survey of 25 students found that 6 are in grade 7 and have a pet, 9 are in grade 7 and have no pet, 4 are in grade 8 and have a pet, and 6 are in grade 8 and have no pet. One student is chosen at random. What is the probability that the student is in grade 8 and has a pet? Write your answer as a fraction.', '[]', '4/25', '4/25', 'Exactly 4 of the 25 students are in grade 8 and have a pet, so the probability is $\frac{4}{25}$.', 'checked', '{"lint":[],"solve":{"answer":"4/25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Grade 8 with pet = 4; total 6+9+4+6 = 25; P = 4/25.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
