INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('74ea20e6-373a-4719-8d52-61e4ab4e24f3', 'NC26.M1.SDSR.1', 1, 'choice', 'Marginal probability from a two-way table', 'In a class of 24 students, 6 boys wear glasses, 4 girls wear glasses, 8 boys do not and 6 girls do not. One student is chosen at random. What is the probability that the student wears glasses?', '["$\\frac{1}{4}$","$\\frac{5}{12}$","$\\frac{5}{7}$","$\\frac{7}{12}$"]', '$\frac{5}{12}$', NULL, '$6 + 4 = 10$ students wear glasses out of 24, so the probability is $\frac{10}{24} = \frac{5}{12}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{5}{12}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Glasses: 6 + 4 = 10; total 24; 10/24 = 5/12.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
