INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08f74382-4c3d-4612-b31c-ed0921d17a98', 'NC26.M1.SDSR.1', 1, 'numeric', 'Probability from a sample space', 'A spinner has 10 equal sections numbered 1 to 10. What is the probability that it lands on a multiple of 3? Write your answer as a fraction.', '[]', '3/10', '3/10', 'The multiples of 3 from 1 to 10 are 3, 6 and 9, so 3 of 10 equally likely outcomes work: $\frac{3}{10}$.', 'checked', '{"lint":[],"solve":{"answer":"3/10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 3 in 1-10: 3, 6, 9; 3/10.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
