INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f0280f44-70ca-4696-9ba0-872fdd84a166', 'NC26.M1.SDSR.1', 1, 'choice', 'Probability from a sample space', 'The four letters of the word MATH are written on four cards, and one card is picked at random. What is the probability that the card shows a vowel?', '["$\\frac{3}{4}$","$\\frac{1}{3}$","$\\frac{1}{4}$","$\\frac{1}{2}$"]', '$\frac{1}{4}$', NULL, 'Only A is a vowel, so 1 of the 4 equally likely cards works: $\frac{1}{4}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{4}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Vowels in M, A, T, H: only A; 1/4.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
