INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93e2da44-95ad-4837-87a7-a1ef0db9d4f0', 'NC26.M1.SDSR.1', 1, 'choice', 'Summarising raw data in a table', 'Eight students named their pet: cat, dog, cat, fish, dog, cat, dog, cat. Which tally is correct?', '["Cat 3, dog 4, fish 1","Cat 4, dog 2, fish 2","Cat 5, dog 2, fish 1","Cat 4, dog 3, fish 1"]', 'Cat 4, dog 3, fish 1', NULL, 'Counting each answer: cat appears 4 times, dog 3 times and fish once, and $4 + 3 + 1 = 8$.', 'checked', '{"lint":[],"solve":{"answer":"Cat 4, dog 3, fish 1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft: very easy tally for Math 1, but it is summarising categorical data.","work":"cat at 1,3,6,8 = 4; dog at 2,5,7 = 3; fish 1. Sum 8.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
