INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8cd17d03-2ed4-473a-b562-d9b64741afc0', 'NC26.M1.SDSR.1', 1, 'choice', 'Reading counts in a two-way table', 'A table shows lunch choices. Sixth graders: 12 chose pizza and 8 chose tacos. Seventh graders: 9 chose pizza and 11 chose tacos. Which statement is true?', '["More sixth graders chose tacos than seventh graders","Fewer than 20 students in all chose pizza","More seventh graders chose tacos than sixth graders","The same number in each grade chose pizza"]', 'More seventh graders chose tacos than sixth graders', NULL, 'Tacos: 11 seventh graders and 8 sixth graders, so more seventh graders chose tacos. In all, $12 + 9 = 21$ chose pizza, and 12 is not 9.', 'checked', '{"lint":[],"solve":{"answer":"More seventh graders chose tacos than sixth graders","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Pizza total 21 (not <20); pizza 12 vs 9 (not same); tacos 7th 11 > 6th 8. True: more seventh graders chose tacos.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
