INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d077150-b950-4019-92c8-3487defab7b3', 'NC26.M1.SDSR.1', 1, 'numeric', 'Probability from a sample space', 'A card is drawn at random from cards numbered 1 to 12. What is the probability that the number is a factor of 12? Write your answer as a fraction.', '[]', '1/2', '1/2', 'The factors of 12 are 1, 2, 3, 4, 6 and 12, so 6 of the 12 cards work: $\frac{6}{12} = \frac{1}{2}$.', 'checked', '{"lint":[],"solve":{"answer":"1/2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Factors of 12: 1,2,3,4,6,12 = 6; 6/12 = 1/2.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
