INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('42f9d35b-433f-44ac-8ac3-24be577389b5', 'NC26.M1.SDSR.1', 2, 'choice', 'Row and column totals of a two-way table', 'A quiz recorded results by team. Team Red: 8 passed and 4 failed. Team Blue: 6 passed and 9 failed. Team Green: 10 passed and 3 failed. How many students are on Team Blue?', '["6","24","9","15"]', '15', '6+9', 'Team Blue is those who passed plus those who failed: $6 + 9 = 15$. (24 is the total who passed; 6 and 9 are only parts of Team Blue.)', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Blue: 6 + 9 = 15.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
