INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('34d2fbe9-574f-43fc-b6d6-cc93b585a525', 'NC26.M1.SDSR.1', 2, 'numeric', 'Finding a missing entry in a two-way table', 'A group of 80 people includes 45 adults. In all, 30 of the 80 own a bike, and 12 of the adults own one. How many children do NOT own a bike?', '[]', '17', '(80-45)-(30-12)', 'There are $80 - 45 = 35$ children. Children with a bike: $30 - 12 = 18$. So $35 - 18 = 17$ children have no bike.', 'checked', '{"lint":[],"solve":{"answer":"17","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Children 35; children with bike 30 - 12 = 18; children without = 17.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
