INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d98be8f0-4ab7-465a-8379-644247492f69', 'NC26.M1.SDSR.1', 2, 'choice', 'Finding a missing entry in a two-way table', 'A survey of 120 students found that 70 are girls. Everyone chose art or music. In all, 45 girls and 30 boys chose art. How many students chose music?', '["45","75","25","20"]', '45', '120-45-30', 'Students who chose art: $45 + 30 = 75$. Everyone else chose music: $120 - 75 = 45$. (25 is the girls who chose music, and 20 the boys.)', 'checked', '{"lint":[],"solve":{"answer":"45","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Art = 45 + 30 = 75; music = 120 - 75 = 45 (girls 25, boys 20, consistent).","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
