INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8188b36c-a277-4772-bab5-db87610f7ec9', 'NC26.M1.SDSR.1', 2, 'choice', 'Joint probability from a two-way table', 'A music survey of 60 people found that 18 teens like rock, 12 teens like pop, 20 adults like rock and 10 adults like pop. One person is chosen at random. What is the probability that the person is an adult who likes pop?', '["$\\frac{1}{3}$","$\\frac{1}{6}$","$\\frac{11}{30}$","$\\frac{1}{2}$"]', '$\frac{1}{6}$', NULL, '10 of the 60 people are adults who like pop: $\frac{10}{60} = \frac{1}{6}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{1}{6}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Adult pop = 10; total 60; 10/60 = 1/6.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('533f6f4e-29d5-4189-be92-984db7f0fb10', 'NC26.M1.SDSR.1', 2, 'numeric', 'Joint probability from a two-way table', 'A club has 40 students: 16 boys and 24 girls. Exactly 6 of the boys and 9 of the girls wear glasses. One student is chosen at random. What is the probability that the student is a girl who wears glasses? Write your answer as a fraction.', '[]', '9/40', '9/40', '9 of the 40 students are girls who wear glasses, so the probability is $\frac{9}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"9/40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Girls with glasses 9; 9/40.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
