INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('84336e86-86f8-40b6-affc-e0e206664ba9', 'NC26.M1.SDSR.1', 2, 'choice', 'Probability of a complement (not)', 'In a survey of 80 students, 14 are girls who play tennis. One student is chosen at random. What is the probability that the student is NOT a girl who plays tennis?', '["$\\frac{7}{40}$","$\\frac{7}{33}$","$\\frac{13}{20}$","$\\frac{33}{40}$"]', '$\frac{33}{40}$', NULL, '$80 - 14 = 66$ students are not girls who play tennis, so the probability is $\frac{66}{80} = \frac{33}{40}$.', 'checked', '{"lint":[],"solve":{"answer":"$\\frac{33}{40}$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 - 14/80 = 66/80 = 33/40.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
