INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3985b274-fb48-43e4-baaf-411e3f4afd6b', 'NC26.M1.SDSR.1', 3, 'numeric', 'Listing a sample space and counting outcomes', 'Two dice are rolled, and the results are written as an ordered pair. How many outcomes have a sum of 9 or more?', '[]', '10', '4+3+2+1', 'Sum 9: (3,6), (4,5), (5,4), (6,3) is 4. Sum 10: (4,6), (5,5), (6,4) is 3. Sum 11: (5,6), (6,5) is 2. Sum 12: (6,6) is 1. Total $4 + 3 + 2 + 1 = 10$.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Soft: \"two dice\" does not say six-sided; standard assumption.","work":"Sum 9: 4, 10: 3, 11: 2, 12: 1; total 10.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
