INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8a81715c-4a9a-4791-b4c5-5ec3f5acd049', 'NC26.M1.SDSR.1', 3, 'choice', 'Listing a sample space and counting outcomes', 'A diner''s meal is one of 3 main dishes, one of 4 sides and one of 2 drinks. How many different meals are possible?', '["9","12","24","14"]', '24', '3*4*2', 'Multiply the choices: $3 \times 4 \times 2 = 24$. (9 adds them, 12 leaves out the drinks, 14 is $(3 + 4) \times 2$.)', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3 x 4 x 2 = 24.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
