INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5348e733-da77-4df0-83cd-a77d6896f42e', 'NC26.M1.SDSR.1', 3, 'choice', 'Reading and, or and not in words', 'Event A is "a student plays soccer" and event B is "a student plays tennis". Which phrase describes "not (A or B)"?', '["A student who does not play soccer or does not play tennis","A student who plays soccer but does not play tennis","A student who plays neither soccer nor tennis","A student who plays at least one of the two sports"]', 'A student who plays neither soccer nor tennis', NULL, '"A or B" means soccer, tennis or both. Its complement is everyone who plays neither sport.', 'checked', '{"lint":[],"solve":{"answer":"A student who plays neither soccer nor tennis","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"not (A or B) = neither (De Morgan).","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e573aa7e-9018-4e5a-a2d1-fc2da7426673', 'NC26.M1.SDSR.1', 3, 'numeric', 'Row and column totals of a two-way table', 'A survey sorted students by sex and favorite pet (cat or dog). The boys'' total was 27. Of the students who chose cats, 16 were boys and 14 were girls. In all, 11 girls chose dogs. How many students were surveyed?', '[]', '52', '27+14+11', 'Boys who chose dogs: $27 - 16 = 11$. Girls: $14 + 11 = 25$. Everyone surveyed: $27 + 25 = 52$.', 'checked', '{"lint":[],"solve":{"answer":"52","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Boys dogs 27 - 16 = 11; girls 14 + 11 = 25; total 27 + 25 = 52.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1f33c576-ddb3-4ac2-89e5-87c2d0fde2a8', 'NC26.M1.SDSR.1', 3, 'choice', 'Reading and, or and not in words', 'The probability that a student plays chess or soccer is found by adding P(chess) and P(soccer) and then subtracting P(chess and soccer). Why is P(chess and soccer) subtracted?', '["Students who play neither are counted twice when the two groups are added","Students who play one game are counted twice when the two groups are added","Students who play both should not be included in the answer at all","Students who play both are counted twice when the two groups are added"]', 'Students who play both are counted twice when the two groups are added', NULL, 'Adding P(chess) and P(soccer) counts each student who plays both games in both groups. Subtracting P(chess and soccer) once leaves them counted once, which is right for "or".', 'checked', '{"lint":[],"solve":{"answer":"Students who play both are counted twice when the two groups are added","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Students in both are in each group, so counted twice.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a38ed65a-e1b1-47bd-9663-8b81ebe296d1', 'NC26.M1.SDSR.1', 3, 'numeric', 'Joint probability from a two-way table', 'A student is chosen at random from a group of 80. The probability that the student is a girl who plays chess is $\frac{3}{16}$. How many of the 80 students are girls who play chess?', '[]', '15', '80*3/16', '$\frac{3}{16}$ of the 80 students is $\frac{3}{16} \times 80 = 15$.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"80 x 3/16 = 15.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1ca91262-6f68-4a57-a1e1-5adb64a12327', 'NC26.M1.SDSR.1', 3, 'choice', 'Row and column totals of a two-way table', 'Which statement is true of every two-way table of counts with two rows and two columns?', '["Both sets of totals add to the same number","Each row total equals the column total beside it","The row totals are equal to one another","The largest cell is larger than every total"]', 'Both sets of totals add to the same number', NULL, 'Both sets of totals count every person once, so each set adds to the number of people in the table. The other statements need not hold.', 'checked', '{"lint":[],"solve":{"answer":"Both sets of totals add to the same number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Row totals and column totals each sum to the grand total.","run_id":"claude-code","at":"2026-10-18T03:37:30.634Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d20e0026-973f-4c35-9503-b61564714645', 'NC26.M1.SDSR.2', 1, 'choice', 'Telling a statistical question from a non-statistical one', 'Which of these is a statistical question?', '["How many hours do students at our school sleep on school nights?","How tall is the tallest tree in the park?","What is the sum of 14 and 9?","How many students are in Ms. Lee''s class today?"]', 'How many hours do students at our school sleep on school nights?', NULL, 'A statistical question expects the answers to vary. Students sleep different numbers of hours, so the data will vary. The other three questions each have one fixed answer.', 'checked', '{"lint":[],"solve":{"answer":"How many hours do students at our school sleep on school nights?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question anticipates variability in the data. Sleep hours of students vary from student to student. The others each have one fixed answer (a sum, one tallest tree, one class count).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('80845075-bc8f-4de1-b7fa-8b9ee83f70fb', 'NC26.M1.SDSR.2', 1, 'choice', 'Categorical and numerical variables', 'For each student in a survey, a researcher records favorite color, number of siblings, height in centimeters, and minutes taken to run a mile. Which of these variables is categorical?', '["number of siblings","height in centimeters","minutes taken to run a mile","favorite color"]', 'favorite color', NULL, 'A categorical variable puts each person into a group or category, such as a color. The other three are measured or counted as numbers.', 'checked', '{"lint":[],"solve":{"answer":"favorite color","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Favorite color is a category; minutes, siblings and height are numerical.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6550f206-dc5e-45ed-8476-f44bdc503fb7', 'NC26.M1.SDSR.2', 1, 'choice', 'Sampling bias from convenience', 'Maya wants to know the favorite lunch of all the students at her school, so she asks only the students at her own lunch table. Why might her results be biased?', '["She asked about lunch, and lunch choices cannot be counted","Her table may not represent all of the students at the school","She asked too many students","She did not ask any teachers"]', 'Her table may not represent all of the students at the school', NULL, 'Her friends at one table may have different tastes from the rest of the school, so the sample may not represent all students. That is a biased sample.', 'checked', '{"lint":[],"solve":{"answer":"Her table may not represent all of the students at the school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A convenience sample of one lunch table may not represent the whole school.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fab8c138-445f-4b17-94dd-68f39596840f', 'NC26.M1.SDSR.2', 1, 'choice', 'Telling statistical questions from non-statistical ones', 'A teacher wants to learn about her class. Which of these questions is a statistical question?', '["How many minutes long is the lunch period on the schedule for my class?","How many minutes does it take the students in my class to get to school?","What time does my class begin on a regular school day at our school?","How many chairs are in the room where my class meets for lessons?"]', 'How many minutes does it take the students in my class to get to school?', NULL, 'A statistical question expects different answers from different people or things, so it can only be answered by collecting data. Travel times to school differ from student to student. The other three questions each have one fixed answer that can simply be looked up.', 'checked', '{"lint":[],"solve":{"answer":"How many minutes does it take the students in my class to get to school?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question expects answers that vary. Travel time to school differs from student to student. Chairs in a room, the scheduled lunch length and the class start time are each one fixed value.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3d7885a6-5eb0-46d4-a4dc-ea08b2c1b27c', 'NC26.M1.SDSR.2', 1, 'choice', 'Telling statistical questions from non-statistical ones', 'A store manager is collecting information. Which of these is NOT a statistical question?', '["How much money do customers spend in the store on a Saturday?","How many customers visit the store on each day of the week?","How long do customers wait in the checkout line?","What time does the store open on a regular weekday morning?"]', 'What time does the store open on a regular weekday morning?', NULL, 'The opening time is one fixed fact, so the answer does not vary. Spending, daily visits and waiting time all vary from customer to customer or day to day, so each needs data to answer.', 'checked', '{"lint":[],"solve":{"answer":"What time does the store open on a regular weekday morning?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Store opening time is one fixed value, so it is not statistical. Money spent, customers per day and wait times all vary.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2dceb163-bc5b-4d64-ba02-919aa08f58ea', 'NC26.M1.SDSR.2', 1, 'numeric', 'Telling statistical questions from non-statistical ones', 'Here are four questions. (A) What is the capital of North Carolina? (B) How long are the movies shown at the town theater? (C) How many players from one team are on a soccer field during a game? (D) How much do the houses on Pine Street cost? How many of the four are statistical questions?', '[]', '2', NULL, 'A statistical question expects the answers to vary. (A) has one fixed answer and (C) is set by the rules of soccer, so neither is statistical. (B) movie lengths differ and (D) house prices differ, so both are statistical. That makes 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) one fixed answer (Raleigh): no. (B) movie lengths vary: yes. (C) fixed by the rules (11): no. (D) house prices vary: yes. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('556f172e-d07e-46bf-8a3f-e21bb1cfebd4', 'NC26.M1.SDSR.2', 1, 'choice', 'Telling statistical questions from non-statistical ones', 'The question ''How tall are the players on the basketball team?'' is a statistical question. Which reason explains why?', '["Different players are expected to have different heights.","The answer is a single fixed number that never changes.","The question can be answered by looking in the league''s rule book.","The question is really only about one particular player."]', 'Different players are expected to have different heights.', NULL, 'A question is statistical when its answers are expected to vary. Players on a team are not all the same height, so we must collect many heights to answer it. It is not about one player, and no rule book gives the answer.', 'checked', '{"lint":[],"solve":{"answer":"Different players are expected to have different heights.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"It is statistical because the data (heights of different players) are expected to vary. The other reasons describe non-statistical questions.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('815e0ab7-ac02-4840-81f7-44d956259bfb', 'NC26.M1.SDSR.2', 1, 'numeric', 'Telling statistical questions from non-statistical ones', 'Maria wrote four questions for her class survey. (1) How many sides does a pentagon have? (2) What day of the week is it today? (3) How many minutes of exercise do her classmates get each day? (4) How many months are in a year? How many of her questions are statistical?', '[]', '1', NULL, 'Questions (1), (2) and (4) each have one fixed answer (5 sides, one weekday, 12 months), so they are not statistical. Only (3) has answers that differ from classmate to classmate. So 1 question is statistical.', 'checked', '{"lint":[],"solve":{"answer":"1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(1) 5 sides, fixed. (2) one answer. (3) exercise minutes vary across classmates: statistical. (4) 12, fixed. Total 1.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b216a36f-5374-4374-9457-da004f8a3ec3', 'NC26.M1.SDSR.2', 1, 'choice', 'Posing a statistical question for a context', 'A class wants to find out how students get to school. Which is a good statistical question to ask?', '["How did Priya travel to school on the day of the big storm?","How do the students in our school usually travel to school?","How many days of school are there in one regular school week?","What is the name of the company that runs the buses for our school?"]', 'How do the students in our school usually travel to school?', NULL, 'A good statistical question is about a whole group and expects different answers. Students travel in different ways, so we collect data from many of them. The other three have one fixed answer.', 'checked', '{"lint":[],"solve":{"answer":"How do the students in our school usually travel to school?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Asking how the students in the school usually travel collects data that vary. Priya''s trip is one person, the bus company name is one fact, days per week is fixed.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c44fa9d-6c1f-4bf9-94a5-265766cd8e20', 'NC26.M1.SDSR.2', 1, 'choice', 'Posing a statistical question for a context', 'The question ''How many pages are in Dana''s math textbook?'' has one fixed answer. Which rewrite makes it a statistical question?', '["How many pages are in Dana''s math textbook, including the index?","How many chapters and units are in Dana''s math textbook this year?","How many pages are in the math textbooks used in our school district?","Does Dana''s math textbook have more than 300 pages in all?"]', 'How many pages are in the math textbooks used in our school district?', NULL, 'To be statistical, the question must be about many textbooks whose page counts can differ. Only the district-wide version does that. The other versions still ask about one book and have one answer.', 'checked', '{"lint":[],"solve":{"answer":"How many pages are in the math textbooks used in our school district?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Asking about page counts of the textbooks used across the district gives data that vary. The others still ask about the one book or a yes/no fact about it.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6527ef2f-db37-409a-b1dd-0918c99859b1', 'NC26.M1.SDSR.2', 1, 'numeric', 'Posing a statistical question for a context', 'Four statistical questions are written below. (A) Do students who play sports sleep more hours than students who do not? (B) How many hours do students at our school sleep on a school night? (C) Do students who ride the bus spend more time on homework than students who walk to school? (D) How many students at our school play a sport? How many of the four compare two groups of students?', '[]', '2', NULL, 'Question (A) compares students who play sports with those who do not. Question (C) compares bus riders with walkers. Questions (B) and (D) each look at one group of students only. So 2 compare two groups.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) sports vs non-sports students: compares two groups. (B) one group. (C) bus riders vs walkers: compares two groups. (D) a count. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c298da52-ed39-4268-8e4a-29f6abbc739e', 'NC26.M1.SDSR.2', 1, 'choice', 'Identifying variables in a multivariate dataset', 'For each pet at an animal shelter, a worker records the pet''s species, its color, its weight in pounds, and whether it was adopted. Which of these variables is numerical?', '["The pet''s species","The pet''s weight in pounds","The pet''s color","Whether the pet was adopted"]', 'The pet''s weight in pounds', NULL, 'A numerical variable has values that are measured or counted numbers. Weight in pounds is a number. Species, color and adopted (yes or no) are categories.', 'checked', '{"lint":[],"solve":{"answer":"The pet''s weight in pounds","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Weight in pounds is a measured number. Color, species and adopted (yes/no) are categories.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('31824318-9103-40e3-a3fe-59ff5d6984e5', 'NC26.M1.SDSR.2', 1, 'numeric', 'Identifying variables in a multivariate dataset', 'A dataset has 25 students, with 4 variables recorded for each student. How many individual values are in the dataset?', '[]', '100', '25*4', 'Each of the 25 students has one value for each of the 4 variables. That gives $25 \times 4 = 100$ values.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each of 25 students has 4 values: 25 x 4 = 100.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
