INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bbddf768-b080-436e-b5d5-d40a44855e93', 'NC26.M1.SDSR.2', 1, 'choice', 'Identifying variables in a multivariate dataset', 'In a dataset about cars, which variable is categorical?', '["Body style, such as sedan, truck or van","Miles driven by each car this year","Price of each car in dollars","Engine size of each car in liters"]', 'Body style, such as sedan, truck or van', NULL, 'A categorical variable sorts each car into a group. Body style does that. Miles, price and engine size are all measured as numbers.', 'checked', '{"lint":[],"solve":{"answer":"Body style, such as sedan, truck or van","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Body style (sedan, truck, van) is a category. Miles, price and engine size are measured numbers.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
