INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9a6ae0fb-c9a7-4208-ae7d-bf07f193edbf', 'NC26.M1.SDSR.2', 1, 'numeric', 'Identifying variables in a multivariate dataset', 'A survey records five variables: eye color, age in years, favorite sport, height in inches, and type of pet owned. How many of these variables are categorical?', '[]', '3', NULL, 'Eye color, favorite sport and type of pet owned put people into categories. Age in years and height in inches are numbers. So 3 variables are categorical.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Categorical: eye color, favorite sport, type of pet = 3. Numerical: age, height.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
