INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3e68f0fa-c4c3-465d-b2da-e50cd18e3e4e', 'NC26.M1.SDSR.2', 1, 'choice', 'Sampling bias from who is included or left out', 'To find out how all the students in a school get to school, a student surveys only the students standing in the bus line. Why might the results be biased?', '["Surveying students at all is a poor way to learn about a school.","The students in the bus line are too numerous to be counted by the surveyor.","Students in the bus line would not tell the truth to the person asking.","Students who walk, bike or ride in cars are left out of the sample."]', 'Students who walk, bike or ride in cars are left out of the sample.', NULL, 'The goal is to learn about all the students, but the sample contains only bus riders. Students who get to school in other ways have no chance of being asked, so the results can lean toward the bus.', 'checked', '{"lint":[],"solve":{"answer":"Students who walk, bike or ride in cars are left out of the sample.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only bus riders are asked, so walkers, bikers and car riders are left out: undercoverage that over-represents the bus.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ab8facef-5063-4d0d-92ab-d35b6466b6be', 'NC26.M1.SDSR.2', 1, 'numeric', 'Sampling bias from who is included or left out', 'A school wants to learn the favorite music of all its students. Four plans are proposed. (A) Draw 60 names at random from a list of all students. (B) Ask the 60 members of the school band. (C) Ask every 10th name on the full list of students. (D) Ask 60 students who are standing in line at the vending machines. How many of the four plans are likely to give a biased sample?', '[]', '2', NULL, 'Plans (A) and (C) give every student a fair chance of being chosen. Plan (B) asks only band members, and plan (D) asks only students who are at the vending machines, so those groups may not represent the whole school. So 2 plans are likely to be biased.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) simple random sample: not biased. (B) band members: biased toward music fans of a kind. (C) every 10th on the full list: systematic, not biased. (D) vending-machine line: convenience, biased. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('46c8bc13-522f-4555-ac17-057b767432e4', 'NC26.M1.SDSR.2', 1, 'numeric', 'Sampling bias from who is included or left out', 'A town has 2,000 residents. A survey is sent only to households with a car, which covers 1,500 of the residents. What percent of the residents are left out of the survey?', '[]', '25', '(2000-1500)/2000*100', 'Residents left out: $2000 - 1500 = 500$. As a percent of the town: $500 \div 2000 \times 100 = 25$. So 25 percent are left out.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Left out 2000 - 1500 = 500. 500/2000 = 0.25 = 25 percent.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('96f0cae0-b24c-42a0-9c53-8a3b3eb8a4c6', 'NC26.M1.SDSR.2', 1, 'choice', 'Voluntary response and non-response bias', 'A movie website lets visitors click a link to rate a movie, but only people with strong feelings take the time to click. What kind of bias is this?', '["Bias from a leading question","Bias from a measuring error","Voluntary response bias","Bias from leaving out a group"]', 'Voluntary response bias', NULL, 'When people choose for themselves whether to respond, those with strong opinions respond most. That is voluntary response bias.', 'checked', '{"lint":[],"solve":{"answer":"Voluntary response bias","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"People choose themselves to respond, and those with strong feelings do: voluntary response bias.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('313b0f8c-9c2e-4f3b-8b5f-aad94c660ea5', 'NC26.M1.SDSR.2', 1, 'numeric', 'Voluntary response and non-response bias', 'A survey was mailed to 200 students. A total of 50 students sent it back. What percent of the students responded?', '[]', '25', '50/200*100', 'The response rate is $50 \div 200 = 0.25$, which is 25 percent.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"50/200 = 0.25 = 25 percent.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('201a5470-fde3-4a38-b87f-c1e2991729b3', 'NC26.M1.SDSR.2', 1, 'choice', 'Voluntary response and non-response bias', 'Why are online polls that anyone may choose to answer often biased?', '["People who answer online polls always give false answers on purpose.","People with strong opinions are more likely to choose to answer.","Online polls always have many more questions than other kinds of surveys.","Everyone has exactly the same chance of being asked to take part."]', 'People with strong opinions are more likely to choose to answer.', NULL, 'When answering is up to each person, the people who feel most strongly are the ones who respond, so the answers do not match the whole group.', 'checked', '{"lint":[],"solve":{"answer":"People with strong opinions are more likely to choose to answer.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Self-selected respondents are mostly people with strong opinions: voluntary response bias.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a51b43c1-7b1d-4ca0-af05-b3618db57fbe', 'NC26.M1.SDSR.2', 1, 'numeric', 'Biased wording of survey questions', 'Four survey questions are listed. (A) ''How many hours do you sleep on a school night?'' (B) ''Wouldn''t you agree that sleeping less than 8 hours is lazy?'' (C) ''How many days a week do you eat breakfast?'' (D) ''Isn''t it silly to skip breakfast when it is so healthy?'' How many of them are leading questions, ones that push people toward an answer?', '[]', '2', NULL, 'Questions (A) and (C) ask neutrally for a number. Question (B) calls short sleep ''lazy'' and question (D) calls skipping breakfast ''silly'', which push the answer. So 2 are leading.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(B) ''Wouldn''t you agree ... lazy?'' and (D) ''Isn''t it silly ...?'' are leading. (A) and (C) are neutral. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f7970b16-be60-4127-bbdb-4b58a1ba8bc5', 'NC26.M1.SDSR.2', 1, 'choice', 'Biased wording of survey questions', 'Why is ''Do you agree that terrible littering is ruining our park?'' a biased question?', '["It asks about a park instead of a school.","Its wording pushes people to agree.","It asks for a word instead of a number.","It is shorter than most survey questions."]', 'Its wording pushes people to agree.', NULL, 'The words ''terrible'' and ''ruining'' suggest the answer the writer wants, which is a leading question. The topic and the length of a question do not make it biased.', 'checked', '{"lint":[],"solve":{"answer":"Its wording pushes people to agree.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Do you agree that terrible littering is ruining...'' uses loaded words and asks for agreement: the wording pushes people to agree.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f2acf4a3-c863-4968-8ff4-5bbd410512b1', 'NC26.M1.SDSR.2', 1, 'choice', 'Biased wording of survey questions', 'Which question about the school play is NOT biased?', '["How fantastic was the school play that our students put on?","Didn''t you think the school play was great, like everyone else did?","How would you rate the school play, from poor to excellent?","Wasn''t the school play the best show anyone has ever seen?"]', 'How would you rate the school play, from poor to excellent?', NULL, 'The rating question lets the person pick any answer from poor to excellent. The other three suggest that the play was great and push the person toward agreeing.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate the school play, from poor to excellent?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''How would you rate the school play, from poor to excellent?'' is neutral with a balanced scale; the others are leading.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b478079e-d0dc-4f11-bb9a-38d486f8945e', 'NC26.M1.SDSR.2', 1, 'numeric', 'Choosing an unbiased sampling method', 'A club wants a fair sample of its 50 members. Four plans are proposed. (A) Write each member''s name on a card, mix the cards and draw 10. (B) Ask the 10 members who arrive first at the meeting. (C) Ask the 10 members who are friends of the club president. (D) Give each member a number from 1 to 50 and let a computer pick 10 numbers at random. How many of the plans give a random sample?', '[]', '2', NULL, 'In plans (A) and (D) every member has the same chance of being chosen, so they give random samples. In plans (B) and (C) the people are chosen by arrival time or friendship, not by chance. So 2 plans give random samples.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) drawing cards: random. (B) first to arrive: convenience. (C) president''s friends: not random. (D) computer picks: random. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('315f5c22-5b70-4e2b-b1d8-02801650cf49', 'NC26.M1.SDSR.2', 1, 'choice', 'Choosing an unbiased sampling method', 'What does ''random'' mean in a random sample?', '["Every member of the group has an equal chance of being chosen.","The members are chosen without thinking about it or following any plan.","The members are the ones who are easiest for the surveyor to reach.","The members are picked by whoever happens to be running the survey."]', 'Every member of the group has an equal chance of being chosen.', NULL, 'A random sample is chosen by chance so that each member has the same chance of being picked. Choosing ''without thinking'' or picking easy-to-reach people is not the same thing and can bring in bias.', 'checked', '{"lint":[],"solve":{"answer":"Every member of the group has an equal chance of being chosen.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"In a (simple) random sample every member of the population has an equal chance of being chosen.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1aca263e-b763-4329-9e3e-23554af8394f', 'NC26.M1.SDSR.2', 1, 'choice', 'Measurement and response bias', 'A class wants to know how much time students really spend on their phones each day. Which method is likely to give the most accurate numbers?', '["Reading the usage report that each student''s own phone keeps","Asking each student to guess from memory at the end of the month","Asking each student''s friends to guess the numbers","Asking the teacher to guess the numbers for each student"]', 'Reading the usage report that each student''s own phone keeps', NULL, 'A usage report records the time as it happens, so it depends less on memory or guessing. People are often poor at guessing their own phone time, and others are worse.', 'checked', '{"lint":[],"solve":{"answer":"Reading the usage report that each student''s own phone keeps","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The phone''s own usage report measures directly; guesses by friends, the teacher or memory are less accurate.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('437449da-741a-4ec1-9d4c-6bf0a23692b5', 'NC26.M1.SDSR.2', 1, 'choice', 'Measurement and response bias', 'A scale that always reads 2 pounds too heavy is used to weigh everyone in a class. What problem does this cause?', '["The weights vary too much from student to student, so no pattern appears.","The sample is far too small, so the data are no use at all.","The students were not chosen at random from the school.","Every weight is measured too high, so the data are biased."]', 'Every weight is measured too high, so the data are biased.', NULL, 'A scale that always reads 2 pounds too high shifts every value in the same direction, which is measurement bias. It is not a problem of sample size or how the students were chosen.', 'checked', '{"lint":[],"solve":{"answer":"Every weight is measured too high, so the data are biased.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A scale that always reads 2 pounds heavy shifts every value up: systematic measurement bias.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a034ece-fa1f-4285-a54d-396cb1d08c19', 'NC26.M1.SDSR.2', 1, 'choice', 'Measurement and response bias', 'A student asks classmates, in front of the whole class, how many times they have been late this month. Why might the answers be biased?', '["Students may forget the question because it has too many words.","Students will all give exactly the same number.","Students may give lower numbers to avoid being embarrassed.","Students may report more late days than they really had."]', 'Students may give lower numbers to avoid being embarrassed.', NULL, 'When people answer in front of others, they may not tell the truth about things that make them look bad. Their answers can be lower than the real counts.', 'checked', '{"lint":[],"solve":{"answer":"Students may give lower numbers to avoid being embarrassed.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Asked publicly, students may under-report lateness to avoid embarrassment (response bias).","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4dd81733-15c8-400d-9ad6-d995ac789f41', 'NC26.M1.SDSR.2', 1, 'choice', 'Telling statistical questions from non-statistical ones', 'A librarian writes down how many books each student checks out in one week. Which statistical question can she answer with this data?', '["In what year was the library built?","How many books do students check out in a week?","How many floors does the library have?","What is the name of the library?"]', 'How many books do students check out in a week?', NULL, 'Her data differ from student to student, so it answers a question that expects different answers. The other three questions each have one fixed answer that the data cannot give.', 'checked', '{"lint":[],"solve":{"answer":"How many books do students check out in a week?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Data on books per student per week answers ''How many books do students check out in a week?'', which has variability. Others have single answers.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fcd7ac6b-24c6-4fb3-9a4e-8b146cec8eed', 'NC26.M1.SDSR.2', 2, 'numeric', 'Counting statistical questions', 'Here are five questions. (A) How tall is the flagpole at our school? (B) How tall are the students at our school? (C) How many sides does a hexagon have? (D) How fast do drivers travel on Oak Street? (E) What is today''s date? How many of the five are statistical questions?', '[]', '2', NULL, 'A statistical question expects varying answers. (B) and (D) do: students differ in height and drivers differ in speed. (A), (C) and (E) each have one fixed answer. So 2 are statistical.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) one flagpole, one height: not statistical. (B) heights vary among students: statistical. (C) six: not. (D) speeds vary among drivers: statistical. (E) one date: not. Count = 2.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4b274f63-3fc6-499f-9ee4-f075d92cc00e', 'NC26.M1.SDSR.2', 2, 'choice', 'Voluntary response bias', 'A radio station asks listeners to call in to vote on whether the town needs a new park. It then reports the result as the opinion of the whole town. What is the main problem?', '["So many people called that the data cannot be organized","Only listeners who choose to call are counted, so the votes may not represent the whole town","The question has more than one possible answer","Radio stations are not allowed to collect data"]', 'Only listeners who choose to call are counted, so the votes may not represent the whole town', NULL, 'Only people who listen and care enough to call are included (voluntary response), so they may differ from the town as a whole.', 'checked', '{"lint":[],"solve":{"answer":"Only listeners who choose to call are counted, so the votes may not represent the whole town","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Voluntary-response sample: only listeners who choose to call are counted, so it may not represent the town.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3c8eaef4-4221-41b2-9cab-191318a208f9', 'NC26.M1.SDSR.2', 2, 'choice', 'Telling statistical questions from non-statistical ones', 'Which question would be answered by collecting data that vary from one household to the next?', '["How many gallons does the town''s main water tank hold when full?","On what day of the month are water bills mailed in our town?","How much water does a household in our town use in one month?","How many water meters did the town install last year?"]', 'How much water does a household in our town use in one month?', NULL, 'Water use differs from household to household, so many households must be measured. The tank size, the mailing day and the number of meters installed are each a single fixed fact.', 'checked', '{"lint":[],"solve":{"answer":"How much water does a household in our town use in one month?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Household water use varies from one household to the next. Tank capacity, billing day and meters installed last year are each single fixed values.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd85b050-e0fd-4bf1-8f93-440b18d37105', 'NC26.M1.SDSR.2', 2, 'choice', 'Telling statistical questions from non-statistical ones', 'All of these questions are about Lincoln High School. Which one is NOT a statistical question?', '["How many hours a night do students at Lincoln High spend on homework?","Which sport do students at Lincoln High like best to watch?","What time does the first class begin on a regular school day?","How far from the school do students at Lincoln High live?"]', 'What time does the first class begin on a regular school day?', NULL, 'The start time of the first class is one fixed answer. Homework time, favorite sport and distance from school all differ from student to student, so they are statistical.', 'checked', '{"lint":[],"solve":{"answer":"What time does the first class begin on a regular school day?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"First class start time is a single scheduled value. Homework hours, distance from school and favorite sport vary among students.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6b7bbdb9-941c-4a68-8cde-7cd25b6fc2ba', 'NC26.M1.SDSR.2', 2, 'choice', 'Telling statistical questions from non-statistical ones', 'Which statement best describes what makes a question statistical?', '["It can be answered with a single number that is found in a reference book.","It asks about a number, and the answer must always be a whole number.","It asks about a group of people, so the answer must be given as a percent.","It can be answered by collecting data, and the data are expected to vary."]', 'It can be answered by collecting data, and the data are expected to vary.', NULL, 'A statistical question anticipates variability: different individuals give different values, so data must be collected. A question with one fixed answer is not statistical, and the answer need not be a whole number or a percent.', 'checked', '{"lint":[],"solve":{"answer":"It can be answered by collecting data, and the data are expected to vary.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A statistical question is answered by collecting data that are expected to vary. The other options add false conditions (whole numbers, percents, reference book).","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6163e2ac-1c72-441a-b9e8-9afc65dec377', 'NC26.M1.SDSR.2', 2, 'choice', 'Posing a statistical question for a context', 'A student has data on each classmate''s hours of exercise per week and resting heart rate. Which is a statistical question that these two variables could help answer?', '["Do students who exercise more hours tend to have lower resting heart rates?","Do students who sleep more hours each night tend to have lower resting heart rates?","What is the name of the student who has the lowest resting heart rate?","How many calories does a typical teenager need to eat each day?"]', 'Do students who exercise more hours tend to have lower resting heart rates?', NULL, 'The exercise question uses both variables, exercise and heart rate, and expects the answers to vary. The sleep question needs a variable that was not collected. The name of one student has one fixed answer. The calorie question has nothing to do with the data.', 'checked', '{"lint":[],"solve":{"answer":"Do students who exercise more hours tend to have lower resting heart rates?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The two variables are exercise hours and resting heart rate; only option A uses exactly those. B needs sleep data, C is one name, D needs calorie data.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1d1de826-2e48-48ca-aef7-9e97bbe50fd9', 'NC26.M1.SDSR.2', 2, 'numeric', 'Posing a statistical question for a context', 'Four questions are written about a school. (A) Is our school a good school? (B) How many hours a week do students at our school spend reading for fun? (C) Are the people in our town happy? (D) What is the typical time students at our school spend traveling to school? How many of the four are too vague to be answered by collecting data as they are written?', '[]', '2', NULL, 'Question (A) does not say what ''good'' means, and question (C) does not say what ''happy'' means or how to measure it, so data could not answer them as written. Questions (B) and (D) name a clear quantity to measure. So 2 are too vague.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) ''good school'' is undefined: vague. (B) hours reading: measurable. (C) ''happy'' undefined: vague. (D) travel time: measurable. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3b9ee796-b241-4bec-8c44-1d18be1351b6', 'NC26.M1.SDSR.2', 2, 'choice', 'Posing a statistical question for a context', 'A student wants to ask whether the time spent on homework changes with grade level at her school. Which is the best statistical question?', '["How much homework did our math teacher assign to the class on Tuesday?","Is homework a good idea for students, or does it do more harm than good?","What grade is the one student who has the most homework tonight?","Do students in higher grades spend more time on homework each night?"]', 'Do students in higher grades spend more time on homework each night?', NULL, 'The best question names the two variables, grade level and nightly homework time, and expects the answers to vary. The Tuesday assignment and the single student are fixed facts, and ''a good idea'' is an opinion that data cannot settle.', 'checked', '{"lint":[],"solve":{"answer":"Do students in higher grades spend more time on homework each night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The question must link grade level and homework time across students: ''Do students in higher grades spend more time on homework each night?''","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('88bd8bbe-31a0-4a61-bbe3-087b9130f48a', 'NC26.M1.SDSR.2', 2, 'choice', 'Posing a statistical question for a context', 'A student asks, ''Did Ms. Chen''s class do well on the quiz?'' Which rewrite is the clearest statistical question?', '["What score did Ms. Chen''s best student get on the quiz?","How do quiz scores in Ms. Chen''s class compare with scores in other classes?","Did Ms. Chen give her class a quiz on Friday afternoon?","How many questions were on the quiz that Ms. Chen gave to her class last week?"]', 'How do quiz scores in Ms. Chen''s class compare with scores in other classes?', NULL, '''Do well'' is replaced by a measurable comparison of scores for two groups of students. The scores vary, so data must be collected. The other three questions are about a single score, a yes-or-no fact and a count of quiz questions.', 'checked', '{"lint":[],"solve":{"answer":"How do quiz scores in Ms. Chen''s class compare with scores in other classes?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only C collects scores that vary and compares them. A is yes/no about one event, B a fixed count, D one student''s score.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d776dee2-d732-4be1-8142-c422cfb0ff2c', 'NC26.M1.SDSR.2', 2, 'choice', 'Identifying variables in a multivariate dataset', 'A researcher studies the relationship between how students get to school (bus, car, walk or bike) and the number of minutes the trip takes. Which statement is correct?', '["Both variables are categorical.","How students get to school is numerical, and trip time is categorical.","Both variables are numerical.","How students get to school is categorical, and trip time is numerical."]', 'How students get to school is categorical, and trip time is numerical.', NULL, 'The way of traveling puts each student in a category (bus, car, walk or bike). The number of minutes is a measured number. So one variable is categorical and the other is numerical.', 'checked', '{"lint":[],"solve":{"answer":"How students get to school is categorical, and trip time is numerical.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mode of travel (bus, car, walk, bike) is categorical; trip minutes is numerical.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f4e7455a-0a41-43be-93ab-967098a66f5b', 'NC26.M1.SDSR.2', 2, 'numeric', 'Identifying variables in a multivariate dataset', 'A plan was made to record 5 variables for each of 30 students. For 3 of the students, 2 of the variables were never recorded. How many values were actually recorded?', '[]', '144', '30*5-3*2', 'Planned values: $30 \times 5 = 150$. Missing values: $3 \times 2 = 6$. Recorded values: $150 - 6 = 144$.', 'checked', '{"lint":[],"solve":{"answer":"144","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Planned 30 x 5 = 150 values. Missing 3 x 2 = 6. Recorded 150 - 6 = 144.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4297d7dd-1e23-47e4-85f7-2b4d1be154f7', 'NC26.M1.SDSR.2', 2, 'numeric', 'Identifying variables in a multivariate dataset', 'For each day, Mia records the temperature in degrees, the weather type (sunny, cloudy or rainy), and the number of visitors to the pool. How many of these variables are numerical?', '[]', '2', NULL, 'Temperature in degrees and the number of visitors are numbers. The weather type is a category. So 2 variables are numerical.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Temperature and number of visitors are numerical; weather type is categorical. Total 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7cd45bee-d68e-4394-bf57-445c1b7b42b6', 'NC26.M1.SDSR.2', 2, 'numeric', 'Matching questions to the variables a dataset holds', 'A dataset has 5 variables. A question about a relationship compares two of the variables. How many different pairs of variables can be compared?', '[]', '10', '5*4/2', 'Each of the 5 variables can pair with 4 others, giving $5 \times 4 = 20$ ordered pairs. Each pair is counted twice, so there are $20 \div 2 = 10$ different pairs.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Number of pairs from 5 variables: 5 x 4 / 2 = 10 (AB, AC, AD, AE, BC, BD, BE, CD, CE, DE).","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5b53340-a9ec-4a38-85a9-b212af92801b', 'NC26.M1.SDSR.2', 2, 'numeric', 'Matching questions to the variables a dataset holds', 'A dataset has four columns for each worker: age, hours worked per week, hourly pay, and city. Five questions are asked. (A) Is hourly pay generally higher in one city than in the others? (B) Do workers with a college degree earn more per hour? (C) Do workers who work more hours per week tend to be older? (D) Do workers who commute farther work more hours? (E) Do older workers tend to earn higher hourly pay? How many of these can be answered using only the four columns?', '[]', '3', NULL, 'Question (A) uses city and pay. Question (C) uses hours and age. Question (E) uses age and pay. Question (B) needs education and question (D) needs commuting distance, which are not in the data. So 3 can be answered.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) pay vs city: yes. (B) college degree not recorded: no. (C) hours vs age: yes. (D) commute not recorded: no. (E) age vs pay: yes. Total 3.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9ff8a0a9-d942-49b7-a275-c3de50b40e40', 'NC26.M1.SDSR.2', 2, 'choice', 'Matching questions to the variables a dataset holds', 'A dataset lists each student''s grade level, hours of sleep, and quiz score. Which question would need information that is NOT in the dataset?', '["Do students who sleep more tend to score higher on quizzes?","Do ninth graders sleep more than tenth graders?","Does the typical quiz score differ from grade to grade?","Do students who eat breakfast score higher on quizzes?"]', 'Do students who eat breakfast score higher on quizzes?', NULL, 'Breakfast is not one of the three recorded variables. The sleep and score question, the grade and sleep question, and the grade and score question all use only variables in the dataset.', 'checked', '{"lint":[],"solve":{"answer":"Do students who eat breakfast score higher on quizzes?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Breakfast is not in the dataset. A uses grade and sleep, C sleep and score, D score and grade.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3aeb2865-43a6-4116-963f-e81244c24634', 'NC26.M1.SDSR.2', 2, 'choice', 'Sampling bias from who is included or left out', 'A company wants to know how well customers like its tablet. It surveys only customers who contacted its help line. What is the main source of bias?', '["People who call tend to be happier with the tablet, so the results lean positive.","People who call are chosen at random from all customers, so the results are not biased.","People who call about a problem are more likely to be unhappy, so results lean negative.","People who call are fewer in number than all customers, so the results are biased."]', 'People who call about a problem are more likely to be unhappy, so results lean negative.', NULL, 'Customers usually call a help line because something is wrong, so the sample is not typical of all customers and leans negative. Having a smaller sample than the whole group does not by itself cause bias.', 'checked', '{"lint":[],"solve":{"answer":"People who call about a problem are more likely to be unhappy, so results lean negative.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Help-line callers usually have a problem, so they are more likely to be unhappy and the results lean negative.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('252133f4-a3a2-4817-bd59-92256c764e24', 'NC26.M1.SDSR.2', 2, 'choice', 'Sampling bias from who is included or left out', 'A city wants to know how often residents use its public parks. A worker interviews people only inside a park on weekday mornings. Why is this sample likely to be biased?', '["People inside the park will refuse to answer, so use will seem lower than it really is.","Weekday mornings have too many people at parks, so the survey will be far too large.","Interviews are always more biased than written surveys, no matter who is asked.","People who use parks are more likely to be included, so use will seem higher than it is."]', 'People who use parks are more likely to be included, so use will seem higher than it is.', NULL, 'Residents who never visit a park cannot be found in a park, and the people who do visit are the ones included. Park use will seem higher than it really is across all residents.', 'checked', '{"lint":[],"solve":{"answer":"People who use parks are more likely to be included, so use will seem higher than it is.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Interviewing only people already in a park includes only park users, so park use seems higher than it is.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('efea783f-1ab5-460a-b72a-203c514cc7cb', 'NC26.M1.SDSR.2', 2, 'numeric', 'Sampling bias from who is included or left out', 'A survey is taken in the school library. Of the 60 students asked, 45 said they read for fun every day. A random sample from the whole school finds that 40 percent of all students read for fun every day. By how many percentage points is the library group''s percent higher than the whole-school percent?', '[]', '35', '45/60*100-40', 'In the library, $45 \div 60 = 0.75$, which is 75 percent. The whole-school figure is 40 percent. The difference is $75 - 40 = 35$ percentage points. Students in the library are more likely to be readers, so the library sample is biased.', 'checked', '{"lint":[],"solve":{"answer":"35","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Library: 45/60 = 75 percent. Whole school: 40 percent. Difference 75 - 40 = 35 points.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6a341377-1bc8-402f-a812-51064bc4b1e2', 'NC26.M1.SDSR.2', 2, 'numeric', 'Voluntary response and non-response bias', 'A survey was sent to 500 randomly chosen households and 120 households replied. What percent of the households did NOT reply?', '[]', '76', '(500-120)/500*100', 'Households that did not reply: $500 - 120 = 380$. As a percent: $380 \div 500 \times 100 = 76$. So 76 percent did not reply.', 'checked', '{"lint":[],"solve":{"answer":"76","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Did not reply 500 - 120 = 380. 380/500 = 0.76 = 76 percent.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36aff85d-88cc-4350-9110-4666e511bfc2', 'NC26.M1.SDSR.2', 2, 'choice', 'Voluntary response and non-response bias', 'Survey A was emailed to 1,000 people and 900 responded. Survey B was emailed to 1,000 people and 100 responded. Which statement is best?', '["Survey A is more at risk, because having a high response rate adds more bias.","Both are equally at risk, because both were emailed to exactly 1,000 people.","Neither can have non-response bias, because both were emailed to many people.","Survey B is more at risk, because most of the people it asked did not answer."]', 'Survey B is more at risk, because most of the people it asked did not answer.', NULL, 'Non-response bias is a worry when many chosen people do not answer, since those who answered may differ from those who did not. Survey B had only 10 percent respond, while Survey A had 90 percent.', 'checked', '{"lint":[],"solve":{"answer":"Survey B is more at risk, because most of the people it asked did not answer.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Survey B had a 10 percent response rate, so most people did not answer: much more risk of non-response bias.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d6370169-960d-422a-9980-22ab4e13192d', 'NC26.M1.SDSR.2', 2, 'choice', 'Voluntary response and non-response bias', 'A town posts a link on its website asking residents to rate the library. Forty people respond, and 36 give the top rating. Which conclusion is justified?', '["Since 36 of 40 gave the top rating, about 90 percent of all residents would too.","Since the survey was online, it applies to every library in the state.","Since 40 is a small number, the result is certainly wrong.","These 40 people chose to respond, so the result may not describe all residents."]', 'These 40 people chose to respond, so the result may not describe all residents.', NULL, 'People who volunteer to answer, perhaps the library''s biggest fans, may differ from other residents. We cannot assume the 90 percent applies to all residents, and we also cannot say the result is certainly wrong.', 'checked', '{"lint":[],"solve":{"answer":"These 40 people chose to respond, so the result may not describe all residents.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The 40 responders chose to respond (voluntary response), so their views may not represent all residents.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c23613f8-aabd-4ce9-b889-2b0dd71e5cda', 'NC26.M1.SDSR.2', 2, 'choice', 'Biased wording of survey questions', 'A survey asks, ''Do you like the new library and the new gym?'' What is the main problem with this question?', '["It asks about two things at once, so one answer cannot be understood.","It uses a loaded word that pushes people to answer yes to the question.","It asks for a number, but it gives people only yes or no as answers.","It is too short to give the surveyor any useful information at all."]', 'It asks about two things at once, so one answer cannot be understood.', NULL, 'A student who likes the library but not the gym cannot answer honestly with one yes or no. A question should ask about one thing at a time.', 'checked', '{"lint":[],"solve":{"answer":"It asks about two things at once, so one answer cannot be understood.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"It asks about the library and the gym together (double-barreled), so a single yes/no cannot be interpreted.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65e077d5-167c-4497-ab27-c8edc2b32b46', 'NC26.M1.SDSR.2', 2, 'choice', 'Biased wording of survey questions', 'A survey on school start times asks, ''Do you want to let students sleep in, or do you want to keep forcing them out of bed so early?'' How does the wording affect the results?', '["It makes both plans sound equally good, so the answers split evenly between them.","It makes keeping the early start sound unpleasant, so more people vote to let students sleep in.","It makes letting students sleep in sound unpleasant, so more people vote to keep the early start.","It has no effect on the answers, because both plans are stated in the question."]', 'It makes keeping the early start sound unpleasant, so more people vote to let students sleep in.', NULL, '''Forcing them out of bed'' is a loaded phrase that makes keeping the early start sound unfair, which pushes people toward letting students sleep in.', 'checked', '{"lint":[],"solve":{"answer":"It makes keeping the early start sound unpleasant, so more people vote to let students sleep in.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"''Keep forcing them out of bed so early'' makes the early start sound unpleasant, pushing votes toward letting students sleep in.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('521c60c4-c660-4cfe-87b9-bd5e3fc11237', 'NC26.M1.SDSR.2', 2, 'choice', 'Biased wording of survey questions', 'Which is the best way to fix the biased question ''How much do you love our super-fast new bus system?''', '["How much do you love the new bus system, from a little bit to a great deal?","Don''t you think the new bus system is much better than the old one was?","How fast and how wonderful is the new bus system that we now have?","How would you rate the new bus system, from 1 (poor) to 5 (excellent)?"]', 'How would you rate the new bus system, from 1 (poor) to 5 (excellent)?', NULL, 'A fair question uses neutral words and allows answers from bad to good. The other versions still push toward a positive answer by using words such as ''love'', ''better'' and ''wonderful''.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate the new bus system, from 1 (poor) to 5 (excellent)?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D removes ''love'' and ''super-fast'' and uses a balanced 1-5 scale. A still assumes love, B and C are leading.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a1ccd842-1ad7-4435-b23a-74327e7a2141', 'NC26.M1.SDSR.2', 2, 'numeric', 'Choosing an unbiased sampling method', 'A school has 300 ninth graders and 200 tenth graders. A stratified random sample of 50 students takes students from each grade in proportion to its size. How many ninth graders are in the sample?', '[]', '30', '300/500*50', 'Ninth graders are $300 \div 500 = \frac{3}{5}$ of the school. In a sample of 50, that is $\frac{3}{5} \times 50 = 30$ ninth graders.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ninth graders are 300/500 = 3/5 of the school. 3/5 x 50 = 30.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fb299dfa-296d-41f0-90db-6c4e8d87f047', 'NC26.M1.SDSR.2', 2, 'choice', 'Choosing an unbiased sampling method', 'In a school, 80 percent of the students are in beginner classes and 20 percent are in advanced classes. A researcher wants both levels represented fairly. Which method is best?', '["Pick the first 50 students who volunteer from either of the two levels.","Pick only advanced students, since that group is the smaller group.","Pick only beginner students, since that group is the larger group.","Pick a random sample from each level, in proportion to its size."]', 'Pick a random sample from each level, in proportion to its size.', NULL, 'A stratified random sample takes a random sample from each level, and taking numbers in proportion keeps the sample like the school. The other plans leave a group out or let volunteers choose themselves.', 'checked', '{"lint":[],"solve":{"answer":"Pick a random sample from each level, in proportion to its size.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Stratified random sampling in proportion (80/20) represents both levels fairly. Volunteers and single-level samples are biased.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('89d9a170-469a-4152-9d11-3aa087f3f66e', 'NC26.M1.SDSR.2', 2, 'numeric', 'Choosing an unbiased sampling method', 'A list has 1,500 customers. A researcher wants a systematic sample of 100 customers: she picks a random starting customer and then every kth customer after that. What should k be?', '[]', '15', '1500/100', 'To end up with 100 customers from 1,500, she takes one customer out of every $1500 \div 100 = 15$. So k = 15.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"k = 1500/100 = 15.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d405eae7-e42d-4189-a369-f2ca33211431', 'NC26.M1.SDSR.2', 2, 'choice', 'Choosing an unbiased sampling method', 'Each of the 60 members of a club is given a number from 1 to 60. Which choice gives a simple random sample of 10 members?', '["Pick the 10 members who were given the lowest numbers on the list.","Use a computer to pick 10 different numbers from 1 to 60 at random.","Pick the 10 members who happen to sit nearest the door of the room.","Pick the 10 members whose names come first in the alphabet."]', 'Use a computer to pick 10 different numbers from 1 to 60 at random.', NULL, 'A simple random sample gives every member the same chance, which a computer''s random choice does. Choosing by number order, seating or alphabet does not.', 'checked', '{"lint":[],"solve":{"answer":"Use a computer to pick 10 different numbers from 1 to 60 at random.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A simple random sample gives every set of 10 an equal chance: a computer picking 10 different numbers from 1-60 at random.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56351bef-1837-46c1-97fb-7d9037290e67', 'NC26.M1.SDSR.2', 2, 'numeric', 'Measurement and response bias', 'A scale reads 3 pounds too high. The readings for nine students have a mean of 120 pounds. What is the mean of the students'' true weights, in pounds?', '[]', '117', '120-3', 'Every reading is 3 pounds too high, so the mean is also 3 pounds too high. The true mean is $120 - 3 = 117$ pounds.', 'checked', '{"lint":[],"solve":{"answer":"117","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each reading is 3 too high, so the mean is 3 too high: 120 - 3 = 117.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('217c6ee4-aedf-4f65-b68b-ab0c42843270', 'NC26.M1.SDSR.2', 2, 'numeric', 'Measurement and response bias', 'Two polls ask teenagers whether they have ever skipped school. In an anonymous written poll of 200 teenagers, 30 percent said yes. In a face-to-face poll with an adult interviewer, 12 percent of another 200 teenagers said yes. How many fewer teenagers, out of 200, said yes in the face-to-face poll?', '[]', '36', '200*0.30-200*0.12', 'Anonymous poll: $200 \times 0.30 = 60$ said yes. Face-to-face poll: $200 \times 0.12 = 24$ said yes. The difference is $60 - 24 = 36$ teenagers. Teenagers may hide the truth when an adult is asking.', 'checked', '{"lint":[],"solve":{"answer":"36","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Anonymous: 0.30 x 200 = 60. Face to face: 0.12 x 200 = 24. Fewer: 60 - 24 = 36.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d7665ca6-c51f-4bb7-93c4-609a12674886', 'NC26.M1.SDSR.2', 2, 'choice', 'Measurement and response bias', 'Students measure each other''s arm spans with a loose tape held in different ways, and each student rounds in their own way. What is the main weakness of the data?', '["Different ways of measuring add errors that make the data unreliable.","Arm span is a categorical variable, so it cannot be measured with a tape.","The data are biased because the students know each other well.","There is no problem, because measuring errors always cancel out exactly."]', 'Different ways of measuring add errors that make the data unreliable.', NULL, 'A fair study uses one clear method for every measurement. When each person measures differently, the differences in the data may come from the method instead of from the arm spans.', 'checked', '{"lint":[],"solve":{"answer":"Different ways of measuring add errors that make the data unreliable.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Inconsistent methods and rounding add measurement error, so the data are unreliable.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b88becc6-7f9a-4c53-bd5a-c02ba8c9bd2e', 'NC26.M1.SDSR.2', 2, 'numeric', 'Telling statistical questions from non-statistical ones', 'Six questions are asked about Cedar School. (A) What is the street address of the school? (B) How many hours of sleep do the students get on school nights? (C) What time does the first bell ring? (D) How many minutes does each student''s trip to school take? (E) How many pets does each student have? (F) How many books do the students read in a month? How many of the six are statistical questions?', '[]', '4', NULL, 'A statistical question expects different answers from different people or things. Questions (B), (D), (E) and (F) ask about every student, and the answers vary. Questions (A) and (C) each have one fixed answer. So 4 are statistical.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Statistical (anticipate variability): B sleep hours, D trip minutes, E pets, F books. Not: A address, C bell time. 4.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('94c48f58-4cfe-4ae0-8e97-d52368baa6f9', 'NC26.M1.SDSR.2', 2, 'choice', 'Explain how non-response biases a survey', 'A survey about school lunches was sent to 400 randomly chosen students. Only 100 of them sent it back, mostly students with strong opinions about the lunches. Why might the results be biased?', '["Choosing students at random always gives biased results","The students who replied may differ from those who did not","Surveying 400 students is too many to be fair","The students should all have been in the same grade"]', 'The students who replied may differ from those who did not', NULL, 'The students were chosen at random, which is a good way to sample. But three quarters of them did not reply, and the ones who did mostly have strong opinions. Their answers may not match the views of the students who stayed silent, so the results may be biased. A large sample and a mix of grades do not cause bias.', 'checked', '{"lint":[],"solve":{"answer":"The students who replied may differ from those who did not","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Only 100 of 400 replied, mostly those with strong opinions: voluntary response / nonresponse bias. The responders may not represent those who did not reply. Random selection does not always bias; same grade is irrelevant; 400 is not ''too many''.","run_id":"claude-code","at":"2026-10-17T18:41:51.098Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0b33671e-1fc7-42cb-ac5c-b3a122166dfb', 'NC26.M1.SDSR.2', 3, 'choice', 'Biased survey wording', 'Which survey question about the school cafeteria is the most neutral (least biased)?', '["Don''t you agree that the cafeteria food is terrible and should be changed?","Most students love the new menu. Do you love it too?","Wouldn''t you say the cafeteria needs more healthy options?","How would you rate the cafeteria food: poor, fair, good, or excellent?"]', 'How would you rate the cafeteria food: poor, fair, good, or excellent?', NULL, 'The other three questions push the reader toward a particular answer (leading questions). The rating question offers balanced choices and does not suggest which to pick.', 'checked', '{"lint":[],"solve":{"answer":"How would you rate the cafeteria food: poor, fair, good, or excellent?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The rating scale question does not suggest an answer. The others are leading (love it too, don''t you agree it is terrible, wouldn''t you say it needs more).","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0a2e05e2-9704-4155-9260-285ec0b34812', 'NC26.M1.SDSR.2', 3, 'choice', 'Choosing an unbiased sampling method', 'A school has 1,200 students. Which method is most likely to give an unbiased estimate of the average time students spend on homework?', '["Ask 100 students chosen at random from the full list of students","Ask all 30 members of the math club","Ask the first 50 students who arrive at school in the morning","Ask the 100 students who are in the library after school"]', 'Ask 100 students chosen at random from the full list of students', NULL, 'A random sample from the complete list gives every student an equal chance of being chosen. The other groups are likely to spend more or less time on homework than the typical student.', 'checked', '{"lint":[],"solve":{"answer":"Ask 100 students chosen at random from the full list of students","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A simple random sample from the full list is unbiased; early arrivals, library students and math club are convenience groups likely to differ in homework time.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6c9b677e-c792-4427-8f57-4d3da83842f1', 'NC26.M1.SDSR.2', 3, 'choice', 'Questions a dataset can answer', 'A student collects data from her classmates on three things: hours of sleep, hours of screen time, and last test score. Which question can she investigate with this data?', '["Which classmates prefer pizza to pasta?","How many hours do students in other countries sleep?","Is there a relationship between hours of sleep and test score among her classmates?","Will the school''s fire alarm be replaced next year?"]', 'Is there a relationship between hours of sleep and test score among her classmates?', NULL, 'A question can be investigated only with data that has been collected. Sleep and test score were recorded for each classmate, so she can look for a relationship between them. The other questions need data she does not have.', 'checked', '{"lint":[],"solve":{"answer":"Is there a relationship between hours of sleep and test score among her classmates?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"She has sleep, screen time and test score for her classmates, so she can study a relationship between sleep and test score among them. The others need data she did not collect.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c2d067a-d738-4bae-b069-2f1323233d11', 'NC26.M1.SDSR.2', 3, 'numeric', 'Telling statistical questions from non-statistical ones', 'Eight questions are listed. (A) What is the median of the numbers 3, 7, 9, 12 and 15? (B) How do the hours students spend at part-time jobs compare with their grades? (C) How many minutes late do the buses on Route 5 arrive each morning? (D) What is the posted speed limit on Elm Road? (E) How do the prices of used cars change with the age of the car? (F) How many centimeters are in one meter? (G) How much rain does our town get in a typical month? (H) Is 51 a prime number? How many are statistical questions?', '[]', '4', NULL, 'Questions (A), (D), (F) and (H) each have one fixed, checkable answer, so they are not statistical. Questions (B), (C), (E) and (G) have answers that vary from student to student, bus to bus, car to car or month to month, so they need data. That is 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"(A) median of given numbers: a computation, no. (B) job hours vs grades: yes. (C) minutes late vary day to day: yes. (D) posted limit: no. (E) price vs age: yes. (F) 100: no. (G) monthly rain varies: yes. (H) 51 = 3x17: no. Total 4.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6561de8-4b8e-4308-8ac8-478e86d4b3bf', 'NC26.M1.SDSR.2', 3, 'choice', 'Telling statistical questions from non-statistical ones', 'Which statement correctly explains why ''How long does a battery of this brand last?'' is statistical, while ''How many batteries come in this package?'' is not?', '["Time questions are always statistical, and counting questions never are.","Batteries vary in how long they last, while the package count is fixed.","Questions about products are statistical only when a store is mentioned.","The battery question can be answered with one number, but the package question cannot."]', 'Batteries vary in how long they last, while the package count is fixed.', NULL, 'Batteries are not all identical, so their lifetimes vary and we must test many of them. A package holds one printed number of batteries, so that answer does not vary. Whether a question involves time or counting does not decide it; variability does.', 'checked', '{"lint":[],"solve":{"answer":"Batteries vary in how long they last, while the package count is fixed.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Battery life varies from battery to battery; the number in a package is fixed. That is the distinction.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('283c0d10-6751-4cea-a53e-d8ad3464d940', 'NC26.M1.SDSR.2', 3, 'choice', 'Telling statistical questions from non-statistical ones', 'Aiden says that ''What is the average height of the ninth graders at our school?'' is not a statistical question, because its answer is one number. Which response is correct?', '["It is statistical, because the heights being averaged vary from student to student.","He is right, because any question with a single number as its answer is not statistical.","He is right, because averages are never used to answer statistical questions.","It is not statistical, because it asks about students rather than objects."]', 'It is statistical, because the heights being averaged vary from student to student.', NULL, 'A statistical question can have a single summary number as its answer. What makes it statistical is that the data behind the average, the heights, vary from student to student. Averages are one of the main tools for answering such questions.', 'checked', '{"lint":[],"solve":{"answer":"It is statistical, because the heights being averaged vary from student to student.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An average summarizes heights that vary from student to student, so the question is statistical even though the final answer is one number.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('41c4bc43-03d0-4c6b-8540-b3155f73934f', 'NC26.M1.SDSR.2', 3, 'choice', 'Posing a statistical question for a context', 'A group wants to investigate whether study habits affect grades. Which question names a clearly measurable variable on both sides?', '["Do students who study harder tend to get better results in their classes?","Do students who care more about school tend to be happier with their grades overall?","Do students who study well tend to do well on tests and homework?","Do students who study more hours per week tend to have higher grade averages?"]', 'Do students who study more hours per week tend to have higher grade averages?', NULL, 'Hours of study per week and grade average can both be measured with numbers. Words like ''harder'', ''care more'', ''study well'' and ''better results'' are not measured the same way by everyone, so the other questions are hard to answer with data.', 'checked', '{"lint":[],"solve":{"answer":"Do students who study more hours per week tend to have higher grade averages?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hours studied per week and grade average are both measurable. ''Study harder'', ''care more'', ''study well'' are not clearly measurable.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('620b6826-db47-4e16-a06b-7587c6e7b676', 'NC26.M1.SDSR.2', 3, 'choice', 'Posing a statistical question for a context', 'Which question is a statistical question that involves three variables?', '["Do hours of sleep and screen time together help explain students'' test scores?","How do hours of sleep relate to test scores for the students in our school?","How do hours of screen time compare for students who are in different grades?","What is the typical number of hours of sleep for the students in our school?"]', 'Do hours of sleep and screen time together help explain students'' test scores?', NULL, 'The question about sleep and screen time together uses sleep, screen time and test scores: three variables. The sleep and test-score question uses two. The screen time and grade question uses two. The question about typical hours of sleep uses only one variable.', 'checked', '{"lint":[],"solve":{"answer":"Do hours of sleep and screen time together help explain students'' test scores?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D involves sleep hours, screen time and test scores: three variables. A and B involve two, C one.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a79b0257-3a4f-4479-a42c-4bd64ab12d6b', 'NC26.M1.SDSR.2', 3, 'choice', 'Posing a statistical question for a context', 'A group wants to find out whether the link between study time and quiz scores is the same for ninth graders as for tenth graders. Which question fits best?', '["Do students who study more minutes each night tend to score higher on their quizzes?","Do ninth graders and tenth graders have different average study times each night?","Is the link between study time and quiz scores the same for ninth and tenth graders?","Do ninth graders earn higher quiz scores than tenth graders do on the same quizzes?"]', 'Is the link between study time and quiz scores the same for ninth and tenth graders?', NULL, 'The goal needs three variables: study time, quiz score and grade level, with the relationship examined separately for each grade. Each of the other questions leaves one of those variables out.', 'checked', '{"lint":[],"solve":{"answer":"Is the link between study time and quiz scores the same for ninth and tenth graders?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The goal is whether the study-time/score relationship differs by grade: three variables (study time, score, grade). Only D asks that.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ef8374a8-eee7-421a-ae7a-933829096801', 'NC26.M1.SDSR.2', 3, 'numeric', 'Posing a statistical question for a context', 'A team writes statistical questions that each pair one numerical variable with one categorical variable. The numerical variables are height, age and quiz score. The categorical variables are eye color, bus rider (yes or no) and favorite subject. How many different pairs could they use?', '[]', '9', '3*3', 'Each of the 3 numerical variables can be paired with each of the 3 categorical variables. That gives $3 \times 3 = 9$ pairs.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Each pair takes one of 3 numerical and one of 3 categorical variables: 3 x 3 = 9.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bdfd4a28-700d-4c36-b17c-0665eaf58e82', 'NC26.M1.SDSR.2', 3, 'choice', 'Identifying variables in a multivariate dataset', 'A coach records, for each player, jersey number, height in inches, points scored and age in years. Which of these variables is categorical even though its values are written as numbers?', '["The height of each player in inches","The number of points each player scored","The jersey number worn by each player","The age of each player in years"]', 'The jersey number worn by each player', NULL, 'A jersey number is only a label that identifies a player; adding or averaging jersey numbers has no meaning. Height, points and age are real quantities, so they are numerical.', 'checked', '{"lint":[],"solve":{"answer":"The jersey number worn by each player","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A jersey number is a label; averaging jersey numbers means nothing, so it is categorical. Height, points and age are numerical.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43c4e5c0-7f24-405a-a4e6-1e50ee455496', 'NC26.M1.SDSR.2', 3, 'choice', 'Identifying variables in a multivariate dataset', 'Which question asks about a relationship between a categorical variable and a numerical variable?', '["Do students who spend more minutes traveling to school also spend more minutes on homework?","Are students who ride the bus more likely to also be in the band?","Do students who ride the bus spend more minutes traveling to school than students who walk?","How many minutes do students spend traveling to school?"]', 'Do students who ride the bus spend more minutes traveling to school than students who walk?', NULL, 'Riding the bus or walking is categorical and minutes of travel is numerical. The homework question links two numerical variables. The band question links two categorical variables. The question about travel minutes alone involves only one numerical variable.', 'checked', '{"lint":[],"solve":{"answer":"Do students who ride the bus spend more minutes traveling to school than students who walk?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"D: bus vs walk (categorical) against minutes traveling (numerical). A is two categorical, B two numerical, C one numerical variable.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('901f393d-32a0-4e78-9da1-407ae37919f2', 'NC26.M1.SDSR.2', 3, 'numeric', 'Identifying variables in a multivariate dataset', 'A survey records each student''s grade (9, 10, 11 or 12), whether the student rides the bus (yes or no), and whether the student plays a sport (yes or no). If a researcher sorts the students into groups using all three variables at once, how many different groups are possible?', '[]', '16', '4*2*2', 'There are 4 choices for grade, 2 for bus and 2 for sport. The number of possible groups is $4 \times 2 \times 2 = 16$.', 'checked', '{"lint":[],"solve":{"answer":"16","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4 grades x 2 bus x 2 sport = 16 groups.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a68806e1-0527-4ca1-b9ec-06d9f899d2b4', 'NC26.M1.SDSR.2', 3, 'choice', 'Matching questions to the variables a dataset holds', 'A researcher has data on each house in a neighborhood: price, square feet, number of bedrooms, and age. Which question requires collecting an additional variable?', '["Do larger houses tend to cost more?","Do houses closer to the school sell for higher prices?","Do newer houses tend to have more bedrooms?","Does the price per square foot differ between older and newer houses?"]', 'Do houses closer to the school sell for higher prices?', NULL, 'Distance from the school is not among the recorded variables. Size and price, age and bedrooms, and price per square foot (price divided by square feet) can all be found from the existing columns.', 'checked', '{"lint":[],"solve":{"answer":"Do houses closer to the school sell for higher prices?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Distance to the school is not recorded. Price per square foot = price / square feet, computable, and compared with age; bedrooms and age are recorded.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30d6fa82-d019-42e0-b6f0-2cd616e3340f', 'NC26.M1.SDSR.2', 3, 'choice', 'Matching questions to the variables a dataset holds', 'A researcher wants to answer, ''Do students in the band have higher grades than students who are not in the band?'' Which two variables must be recorded for each student?', '["Whether the student is in the band, and the student''s grade average","The student''s instrument, and the student''s grade level","The number of students in the band, and the school''s overall grade average","The student''s grade average, and the number of students in the school"]', 'Whether the student is in the band, and the student''s grade average', NULL, 'To compare two groups of students, we need each student''s group (in the band or not) and each student''s grade average. The other pairs either leave out a student''s group, or give totals for the whole school instead of values for each student.', 'checked', '{"lint":[],"solve":{"answer":"Whether the student is in the band, and the student''s grade average","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need band membership (yes/no) and each student''s grade average.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c005ad8-b1a1-49c7-97f3-6291c2297c95', 'NC26.M1.SDSR.2', 3, 'choice', 'Matching questions to the variables a dataset holds', 'For 200 households, a dataset records the number of people, the monthly electricity bought from the power company, and whether the home has solar panels (yes or no). Which question can be answered with this data?', '["Do homes with solar panels pay less for their internet service each month?","Do homes with more people living in them have larger yards around the house?","Do homes with solar panels buy less electricity from the power company?","Do homes with solar panels tend to have more rooms than other homes?"]', 'Do homes with solar panels buy less electricity from the power company?', NULL, 'The question about electricity uses two recorded variables, solar panels and electricity bought. Internet cost, yard size and number of rooms were not recorded.', 'checked', '{"lint":[],"solve":{"answer":"Do homes with solar panels buy less electricity from the power company?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Solar panels and electricity bought are both recorded. Internet cost, rooms and yards are not.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1a1a98b6-57a5-4743-b85d-4f6cc6ac1d69', 'NC26.M1.SDSR.2', 3, 'choice', 'Sampling bias from who is included or left out', 'A researcher increases her sample from 100 students to 1,000 students, but still surveys only students who are in the library. Which statement is true?', '["The results are still biased, since a bigger sample does not fix who is left out.","The bias is removed, because the sample is now ten times as large as it was at first.","The results are now unbiased, but they are less precise than they were before.","The bias is greater, because more students were asked in the same place."]', 'The results are still biased, since a bigger sample does not fix who is left out.', NULL, 'Bias comes from how the sample is chosen, not from how big it is. Students who are not in the library still have no chance of being asked, so a bigger sample from the same place is just as biased.', 'checked', '{"lint":[],"solve":{"answer":"The results are still biased, since a bigger sample does not fix who is left out.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A larger sample from the same place still leaves out non-library students: still biased.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('011c32e7-c2ca-4ca4-807b-cfe72ab83837', 'NC26.M1.SDSR.2', 3, 'choice', 'Sampling bias from who is included or left out', 'Which situation is an example of undercoverage?', '["A survey is sent to random households, but few reply and most replies come from people with strong opinions.","Names for a town survey are taken from a phone book, which leaves out households with no listed number.","A survey is posted online and anyone who wishes can answer it.","A survey asks, ''Don''t you agree that the park is wonderful?''"]', 'Names for a town survey are taken from a phone book, which leaves out households with no listed number.', NULL, 'Undercoverage happens when part of the group has no chance of being included. A phone book misses households without a listed number. The other situations describe non-response, voluntary response and a leading question.', 'checked', '{"lint":[],"solve":{"answer":"Names for a town survey are taken from a phone book, which leaves out households with no listed number.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Undercoverage means part of the population cannot be chosen: the phone book leaves out households with no listed number. A is non-response, B voluntary response, C a leading question.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c1451129-31b9-40bc-9faa-896a9be665ea', 'NC26.M1.SDSR.2', 3, 'choice', 'Sampling bias from who is included or left out', 'Two students estimate the typical weekly spending of teenagers in a city. Ana surveys 200 teenagers at the mall on a Saturday afternoon. Ben surveys 50 teenagers chosen at random from the rosters of all the city''s schools. Which statement is best?', '["Ben''s result is likely less biased, even though his sample is smaller.","Ana''s result is less biased, because her sample is larger than Ben''s sample.","Both results are unbiased, because both students surveyed only teenagers.","Neither result can be biased, because both students asked real teenagers."]', 'Ben''s result is likely less biased, even though his sample is smaller.', NULL, 'Teenagers at the mall on a Saturday are likely to spend more than other teenagers, and teenagers who never go to the mall are left out. Ben''s random sample gives every student a fair chance, so it is less biased. Size does not make up for a biased way of choosing.', 'checked', '{"lint":[],"solve":{"answer":"Ben''s result is likely less biased, even though his sample is smaller.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ana''s mall sample is a convenience sample (teens at a mall likely spend more); size does not fix bias. Ben''s random sample from all school rosters is likely less biased.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('aa744c5a-7167-4170-8bfa-ed09079c12d9', 'NC26.M1.SDSR.2', 3, 'numeric', 'Voluntary response and non-response bias', 'A survey was emailed to 800 students and 320 replied. Of those who replied, 240 said they eat breakfast every day. Nothing is known about the students who did not reply. What is the greatest number of the 800 students who could eat breakfast every day?', '[]', '720', '240+(800-320)', 'Students who did not reply: $800 - 320 = 480$. At most, all 480 of them eat breakfast, along with the 240 known to do so. The greatest possible number is $240 + 480 = 720$.', 'checked', '{"lint":[],"solve":{"answer":"720","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"240 repliers eat breakfast; at most all 800 - 320 = 480 non-repliers also do. Greatest 240 + 480 = 720.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('0ab57a55-6628-497a-b422-b34d8649d53f', 'NC26.M1.SDSR.2', 3, 'numeric', 'Voluntary response and non-response bias', 'A survey was emailed to 800 students. Only 20 percent replied, and 60 percent of the replies said the students like the new bell schedule. Nothing is known about the students who did not reply. What is the smallest number of the 800 students who could like the new schedule?', '[]', '96', '800*0.2*0.6', 'Students who replied: $800 \times 0.2 = 160$. Of these, $160 \times 0.6 = 96$ like the schedule. All of the other 640 students might not like it, so the smallest possible number is 96.', 'checked', '{"lint":[],"solve":{"answer":"96","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Replies 0.20 x 800 = 160. Like it 0.60 x 160 = 96. Smallest when no non-replier likes it: 96.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('755183fb-b816-4d9f-b03c-f5dacf1e9e00', 'NC26.M1.SDSR.2', 3, 'choice', 'Voluntary response and non-response bias', 'A company reports, ''85 percent of those who responded to our survey were satisfied.'' It does not say how many people were asked. What is the most important question to ask before trusting the 85 percent?', '["What percent of the people who were asked actually responded?","How many pages long was the survey form that people filled in?","On which day of the week was the survey sent to the people?","What reading level was the survey form written at?"]', 'What percent of the people who were asked actually responded?', NULL, 'If only a small share of the people asked responded, those who did may not represent everyone, and the 85 percent could be misleading. The length, the day sent and the reading level matter much less.', 'checked', '{"lint":[],"solve":{"answer":"What percent of the people who were asked actually responded?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Without the response rate, the 85 percent may describe only a small self-selected group; the key question is what percent responded.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2d661981-c22e-43f4-b0ea-8ae567740bbc', 'NC26.M1.SDSR.2', 3, 'choice', 'Biased wording of survey questions', 'A survey asks students to rate the new school menu using only these choices: Excellent, Very good, Good, or Fair. What is the problem?', '["The choices are too many to compare, so most students will skip the question.","The choices are all negative, so the menu will look worse than students feel.","The choices lean positive, so the results make the menu look better than it is.","There is no problem, because every student can pick one of the four choices."]', 'The choices lean positive, so the results make the menu look better than it is.', NULL, 'There is no choice such as Poor, so a student who dislikes the menu has no honest answer to give. The set of answers tilts toward the positive and biases the results.', 'checked', '{"lint":[],"solve":{"answer":"The choices lean positive, so the results make the menu look better than it is.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three of four choices are positive and there is no ''Poor'', so the scale leans positive and makes the menu look better.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e54de270-5fee-46a6-bfb2-d6d360940687', 'NC26.M1.SDSR.2', 3, 'numeric', 'Biased wording of survey questions', 'In a survey, 120 students were asked a leading question about later school start times, and 90 said yes. A different group of 120 students was asked a neutral version, and 60 said yes. By how many percentage points did the leading question raise the percent who said yes?', '[]', '25', '90/120*100-60/120*100', 'Leading version: $90 \div 120 = 75$ percent. Neutral version: $60 \div 120 = 50$ percent. The difference is $75 - 50 = 25$ percentage points.', 'checked', '{"lint":[],"solve":{"answer":"25","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Leading: 90/120 = 75 percent. Neutral: 60/120 = 50 percent. Raised by 25 points.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('445d1e56-a4a2-44d8-89cb-a52bd1d61728', 'NC26.M1.SDSR.2', 3, 'choice', 'Biased wording of survey questions', 'Four students write a question about homework. Which one would give the most trustworthy results?', '["Do you do too much homework, as most students in your grade say they do?","About how many hours of homework do you do on a typical school night?","Is homework, which helps students learn a lot, really too long each night?","Don''t you hate how much homework your teachers give you every night?"]', 'About how many hours of homework do you do on a typical school night?', NULL, 'The question about a typical school night is neutral and asks for a number. The others use phrases such as ''as most students say'', ''which helps students learn'' and ''hate'', which push the answer in one direction.', 'checked', '{"lint":[],"solve":{"answer":"About how many hours of homework do you do on a typical school night?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"C is neutral and asks for a measurable amount. The others are leading (helps a lot, hate, as most students say).","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('20129788-d6d3-42d7-a932-c72ab579a5e2', 'NC26.M1.SDSR.2', 3, 'choice', 'Biased wording of survey questions', 'A survey asks, ''Most experts say too much screen time is harmful. How many hours of screen time do you have each day?'' What is the main problem?', '["It asks for a number of hours, which no one is able to answer exactly.","It does not say which unit of time the answer should be given in.","Mentioning experts can pressure people to report fewer hours than they have.","It asks about screen time instead of asking about hours of sleep."]', 'Mentioning experts can pressure people to report fewer hours than they have.', NULL, 'The first sentence tells people what answer is socially acceptable, so some will understate their screen time. The question does ask for hours, and the topic is the writer''s choice.', 'checked', '{"lint":[],"solve":{"answer":"Mentioning experts can pressure people to report fewer hours than they have.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The preface about experts pressures people to under-report screen time. The question does name hours as the unit.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3deaa15c-fcab-4fb2-af4e-679a74b091e5', 'NC26.M1.SDSR.2', 3, 'numeric', 'Choosing an unbiased sampling method', 'A town has 4,000 adults aged 18 to 34, 3,000 aged 35 to 54, and 3,000 aged 55 or older. A stratified sample of 200 adults is taken in proportion to each group''s size. How many adults aged 35 to 54 are in the sample?', '[]', '60', '3000/10000*200', 'The town has $4000 + 3000 + 3000 = 10{,}000$ adults, and the middle group is $3000 \div 10000 = 0.3$ of them. In the sample, $0.3 \times 200 = 60$ adults.', 'checked', '{"lint":[],"solve":{"answer":"60","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 4000 + 3000 + 3000 = 10000. Ages 35-54: 3000/10000 = 0.3; 0.3 x 200 = 60.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('93e79dea-48f1-47a9-8361-5915c040ff66', 'NC26.M1.SDSR.2', 3, 'choice', 'Choosing an unbiased sampling method', 'A school wants a survey of 50 students that reflects its grades. Grade 9 has 200 students, grade 10 has 150, and grade 11 has 150. Which sample is stratified in proportion to the grades?', '["17 from grade 9, 17 from grade 10 and 16 from grade 11, each chosen at random","25 from grade 9, 15 from grade 10 and 10 from grade 11, each chosen at random","20 from grade 9, 15 from grade 10 and 15 from grade 11, each chosen at random","All 50 from grade 9, because it is the largest grade, chosen at random"]', '20 from grade 9, 15 from grade 10 and 15 from grade 11, each chosen at random', NULL, 'The school has 500 students, so a sample of 50 is one student for every 10. That gives $200 \div 10 = 20$ from grade 9, and $150 \div 10 = 15$ from each of grades 10 and 11. Taking equal numbers from each grade is not proportional.', 'checked', '{"lint":[],"solve":{"answer":"20 from grade 9, 15 from grade 10 and 15 from grade 11, each chosen at random","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Total 500. Grade 9: 200/500 x 50 = 20. Grades 10 and 11: 150/500 x 50 = 15 each. So 20, 15, 15.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('43526ddd-f37c-46ee-ac8c-99afe29b941e', 'NC26.M1.SDSR.2', 3, 'choice', 'Choosing an unbiased sampling method', 'Which sampling plan is best for finding how a city''s residents feel about a new bike lane?', '["Post a link on the city''s page and count every reply that comes in this month.","Interview 500 people who shop on the city''s busiest street on a Saturday.","Ask 500 cyclists at the start of the proposed lane on a sunny morning.","Mail the survey to 500 addresses chosen at random from the full address list."]', 'Mail the survey to 500 addresses chosen at random from the full address list.', NULL, 'Choosing addresses at random from a complete list gives every household a fair chance of being included. The other plans use volunteers, shoppers on one street or cyclists, who are not typical of all residents.', 'checked', '{"lint":[],"solve":{"answer":"Mail the survey to 500 addresses chosen at random from the full address list.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample from the full address list represents all residents. Cyclists, busy-street shoppers and an online link are biased.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('64d955f2-3fc5-4248-a714-58d5b12c28cf', 'NC26.M1.SDSR.2', 3, 'numeric', 'Measurement and response bias', 'A thermometer is known to read 2 degrees too low. Five readings are 18, 21, 20, 23 and 18 degrees. What is the mean of the corrected temperatures, in degrees?', '[]', '22', '(18+21+20+23+18)/5+2', 'The mean of the readings is $(18 + 21 + 20 + 23 + 18) \div 5 = 100 \div 5 = 20$. Each reading is 2 too low, so the corrected mean is $20 + 2 = 22$ degrees.', 'checked', '{"lint":[],"solve":{"answer":"22","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mean of readings (18 + 21 + 20 + 23 + 18)/5 = 100/5 = 20. Each true value is 2 higher: 22.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c39b7955-fef4-4181-a607-2e25a14d5f7e', 'NC26.M1.SDSR.2', 3, 'choice', 'Measurement and response bias', 'Two ways of learning how much time students spend on homework are compared. Plan 1: each student writes the time in a log every day for a week. Plan 2: each student is asked once, at the end of the term, to say how many hours a week they usually spend. Which statement is best?', '["The one-time question is more accurate, because students remember well after months.","The daily log is likely more accurate, because it depends less on memory.","Both plans are equally accurate, because both come from students.","The log is less accurate, because writing it down takes time."]', 'The daily log is likely more accurate, because it depends less on memory.', NULL, 'Writing times down as they happen avoids depending on memory. A single answer about a whole term relies on remembering and estimating, which usually introduces errors.', 'checked', '{"lint":[],"solve":{"answer":"The daily log is likely more accurate, because it depends less on memory.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A daily log is recorded at the time and relies less on memory than a one-time estimate months later.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5c163eb4-d0ab-4ccf-9763-b1326fa3d1a2', 'NC26.M1.SDSR.2', 3, 'choice', 'Measurement and response bias', 'Researchers compare daily step counts for two groups. Group A wears the step counter on the wrist and Group B wears it on the ankle, where it counts more steps. Group B''s counts are higher. What is the main problem with concluding that Group B walks more?', '["The device placement differs, so the gap may come from the measuring method.","Both groups wore a step counter, so the two samples must be biased.","Step counts can never be fairly compared between any two different people.","Ankle counters are always more accurate, so Group B''s counts are the true ones."]', 'The device placement differs, so the gap may come from the measuring method.', NULL, 'The two groups were measured in different ways, so the gap in counts could come from where the device was worn instead of from how much people walk. To compare groups, measure everyone in the same way.', 'checked', '{"lint":[],"solve":{"answer":"The device placement differs, so the gap may come from the measuring method.","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Group B''s counters sit on the ankle, which counts more steps, so the difference may come from the measurement method, not walking.","run_id":"claude-code","at":"2026-10-18T01:07:42.228Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b7119e6-f840-44a1-a852-58aaf1302e0a', 'NC26.M1.SDSR.2', 3, 'choice', 'Spotting sources of bias', 'A teacher wants to know how many hours students really spend on homework each night. She asks each student to say the number out loud in front of the whole class. What is the most likely problem with the data?', '["Students may give answers that make them look good, so the reported hours may not be true","The question is not statistical, because the hours vary from one student to the next","The sample is too large to be useful, because every student in the class answered","Hours of homework are categorical data, so they cannot be compared"]', 'Students may give answers that make them look good, so the reported hours may not be true', NULL, 'Answering out loud in front of classmates and the teacher can push students to say what sounds best, which biases the data. Varying answers are what make a question statistical, a larger sample is not a problem, and hours are numerical data.', 'checked', '{"lint":[],"solve":{"answer":"Students may give answers that make them look good, so the reported hours may not be true","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Public reporting causes response bias: students may inflate or shade answers.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d1a2cd46-bfcd-446d-bee5-f5cfc8f83e4c', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging the credibility of a source', 'Which source is the most credible for finding the average number of students per class in a state''s public schools?', '["A social media post by an anonymous account that gives no sources","An advertisement from a company that sells school supplies","A classmate''s estimate based on only her own class","A report from the state education agency that explains how its data were collected"]', 'A report from the state education agency that explains how its data were collected', NULL, 'A credible source is open about how its data were collected and covers the whole group. The other sources give no method, may have a reason to exaggerate, or look at only one class.', 'checked', '{"lint":[],"solve":{"answer":"A report from the state education agency that explains how its data were collected","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"An official agency report that documents its methods is the most credible; the others are anonymous, anecdotal or commercially motivated.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('07b8f6d6-2701-41d1-b964-ccbb2759b525', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'A student wants to predict the selling price of a house. Which variable is the LEAST useful for this?', '["the size of the house in square feet","the favorite color of the owner","the number of bedrooms","the neighborhood"]', 'the favorite color of the owner', NULL, 'Size, number of bedrooms and neighborhood all affect what buyers pay. The owner''s favorite color has no connection to the price.', 'checked', '{"lint":[],"solve":{"answer":"the favorite color of the owner","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Size, bedrooms and neighborhood all relate to price; the owner''s favorite color does not.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97a97467-dfea-4edb-abf6-5a1b4dc4f461', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging the credibility of a data source', 'Tanya wants to know how much rain fell in Raleigh last month. Which source is the most trustworthy?', '["Rain gauge records posted by a weather service","A neighbor who remembers it as a rainy month","A store poster that advertises rain jackets","A popular video titled \"Wildest Weather Ever!\""]', 'Rain gauge records posted by a weather service', NULL, 'Measured records from a weather service are collected with instruments and a stated method. A memory, an ad and a catchy video title are not measurements.', 'checked', '{"lint":[],"solve":{"answer":"Rain gauge records posted by a weather service","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Measured rain gauge records from a weather service are direct, documented data; the others are entertainment, advertising or memory.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d192b6a6-e72b-412b-b711-64d5e7222d5e', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging the credibility of a data source', 'A survey about the best sneaker brand was paid for by a sneaker company. Why should you be careful with its results?', '["Companies are never able to collect any data about sneakers or shoes","The company could gain if the results favor its own sneakers","Sneakers are too hard to compare, so no survey could work","Surveys are only trustworthy when they are very short"]', 'The company could gain if the results favor its own sneakers', NULL, 'A source that profits from a certain result may be biased, so we look at how the data were collected. Companies can collect data, and length is not what makes a survey trustworthy.', 'checked', '{"lint":[],"solve":{"answer":"The company could gain if the results favor its own sneakers","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Sponsor bias: the company benefits if results favor its brand.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e2a33fed-0fd1-4eea-a43b-8075bfb16575', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging the credibility of a data source', 'Which detail makes a data source MORE trustworthy?', '["It uses large, colorful pictures and bold headings","It was shared by many people on several different social media sites","It explains who collected the data and how it was collected","It uses many technical words and long, complicated sentences"]', 'It explains who collected the data and how it was collected', NULL, 'A trustworthy source tells you who collected the data and how, so that others can check it. Looks, popularity and technical words do not show that data are sound.', 'checked', '{"lint":[],"solve":{"answer":"It explains who collected the data and how it was collected","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Transparency about who collected data and how raises trust; popularity, visuals and jargon do not.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('51d4f607-4680-4e69-aa18-f755d3dabe98', 'NC26.M1.SDSR.3', 1, 'numeric', 'Judging the credibility of a data source', 'Mia scores a website with a checklist: 1 point if it names its author, 1 point if it gives a date, 1 point if it lists where its data came from, and 1 point if it is NOT trying to sell a product. Website Q names its author, has no date, lists its data source, and sells a product. How many points does Website Q score?', '[]', '2', '1+0+1+0', 'Website Q earns 1 point for naming its author and 1 point for listing its data source. It has no date (0) and it sells a product (0). Total: 1 + 1 = 2 points.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Author: 1. Date: 0. Data source: 1. Not selling: 0 (it sells). Total 2.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d79522a9-1519-41dd-8c7a-98f9ab27ae26', 'NC26.M1.SDSR.3', 1, 'choice', 'Judging the credibility of a data source', 'A school wants to know what its students think about a new lunch menu. Which survey result is the most likely to be reliable?', '["Asking the 6 students sitting at one lunch table in the cafeteria today","Asking only the students who belong to the school''s chess club team","Counting the answers of students who visit the school''s website","Asking 150 students chosen at random from the school''s list"]', 'Asking 150 students chosen at random from the school''s list', NULL, 'A large group chosen at random from the whole school represents the students. A single table, one club, or people who choose to answer online may not be typical.', 'checked', '{"lint":[],"solve":{"answer":"Asking 150 students chosen at random from the school''s list","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A random sample of 150 from the full list is representative; the others are self-selected or tiny/biased groups.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ed02fb02-a645-4c2e-b997-46a7606fc7d5', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'A coach asks, "Does more practice time lead to more free throws made?" Which variable is the outcome being predicted?', '["The number of free throws made","The minutes of practice time","The names of the players","The color of the basketball"]', 'The number of free throws made', NULL, 'Practice time is used to predict the number of free throws made, so free throws made is the outcome.', 'checked', '{"lint":[],"solve":{"answer":"The number of free throws made","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outcome (response) is free throws made; practice time is the predictor.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
