INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3398cf01-7012-4924-9e03-e0c95c0f4a35', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'A baker wants to predict how many cups of hot chocolate she will sell each day. Which variable would help the most?', '["The color of her apron","The outdoor temperature that day","The number of windows in her shop","The weight of her bag of flour"]', 'The outdoor temperature that day', NULL, 'Colder days probably mean more hot chocolate. The other variables have no clear link to sales of the drink.', 'checked', '{"lint":[],"solve":{"answer":"The outdoor temperature that day","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Hot chocolate demand depends on temperature; others irrelevant.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
