INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('12e4ba4d-7819-446e-b209-47ac7d69c0ef', 'NC26.M1.SDSR.3', 1, 'choice', 'Choosing relevant variables', 'Which question can be investigated using the variables "minutes of exercise per day" and "resting heart rate"?', '["Do people who exercise more tend to have lower resting heart rates?","Which sport do people who exercise like to play the most?","Do people with calm hearts tend to have more brothers and sisters?","How much taller are people who exercise than people who do not?"]', 'Do people who exercise more tend to have lower resting heart rates?', NULL, 'Only the first question can be answered by comparing these two variables.', 'checked', '{"lint":[],"solve":{"answer":"Do people who exercise more tend to have lower resting heart rates?","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Both variables appear only in the first question (exercise vs resting heart rate).","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
