INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b94d86e2-6dc4-4808-81bd-34bec08f6127', 'NC26.M1.SDSR.3', 1, 'choice', 'Evaluating a dataset for a question', 'Nia wants to know how long students at her own school take to get to school. Which data would answer her question best?', '["Travel times from a random group of students at her school","Travel times of adults who drive to work in her town","The number of buses owned by her school and its district","The lengths of all the roads in the area near her school"]', 'Travel times from a random group of students at her school', NULL, 'Only travel times from students at her school match her question.', 'checked', '{"lint":[],"solve":{"answer":"Travel times from a random group of students at her school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Need travel times of students at her school; a random group of them answers it.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
