INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a02334db-02e2-47fa-88c8-99109600b9e7', 'NC26.M1.SDSR.3', 1, 'choice', 'Evaluating a dataset for a question', 'In a dataset of plant heights, some values are in inches and others in centimeters, and the unit is not labeled. What should be done before comparing the heights?', '["Compare them as they are, since all are heights","Find each value''s unit and convert them all to one unit","Remove all of the rows that have the smaller numbers in them","Round every height to the nearest ten"]', 'Find each value''s unit and convert them all to one unit', NULL, 'Values in different units cannot be compared directly, so first find the units and convert to a single one.', 'checked', '{"lint":[],"solve":{"answer":"Find each value''s unit and convert them all to one unit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Mixed unlabeled units must be identified and converted to one unit before comparing.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
