INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ec9f4243-2041-4782-83b0-1f28adc0188d', 'NC26.M1.SDSR.3', 1, 'choice', 'Evaluating a dataset for a question', 'Which column of a student dataset is categorical?', '["Number of siblings","Age in years","Favorite color","Minutes spent on homework"]', 'Favorite color', NULL, 'A categorical variable puts people in groups by a quality, such as a color. The other columns are measured or counted numbers.', 'checked', '{"lint":[],"solve":{"answer":"Favorite color","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Favorite color is a category; the rest are numeric.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
