INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d5c64a6d-b470-4e2c-ade4-056a10499e64', 'NC26.M1.SDSR.3', 1, 'numeric', 'Evaluating a dataset for a question', 'Daily steps, in thousands, for seven days: 6, 7, 5, 6, 40, 7, 6. One value is most likely a typing error. What is that value?', '[]', '40', NULL, 'Six of the values are between 5 and 7, while 40 is far away from them. A person is unlikely to take 40 thousand steps, so 40 is the likely error.', 'checked', '{"lint":[],"solve":{"answer":"40","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Values cluster 5-7 thousand; 40 is the anomaly.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
