INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6d0ca6c4-6a46-4cec-8a68-7e4626422669', 'NC26.M1.SDSR.3', 3, 'choice', 'Choosing relevant variables', 'To compare how safe the roads are in two cities of very different sizes, which variable is the better choice?', '["Total accidents in each city","Accidents per 10,000 residents","Total residents in each city","Total number of roads in each city"]', 'Accidents per 10,000 residents', NULL, 'Counts depend on the size of the city. A rate such as accidents per 10,000 residents makes the cities comparable.', 'checked', '{"lint":[],"solve":{"answer":"Accidents per 10,000 residents","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A rate per population adjusts for city size.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c940077e-301f-4b2c-8fe4-3b607d5d5db0', 'NC26.M1.SDSR.3', 3, 'numeric', 'Choosing relevant variables', 'City A had 90 accidents and has 30,000 residents. City B had 60 accidents and has 12,000 residents. How many more accidents per 10,000 residents does City B have than City A?', '[]', '20', '60/12000*10000-90/30000*10000', 'City A: 90 / 3 = 30 accidents per 10,000 residents (30,000 residents is three groups of 10,000). City B: 60 / 1.2 = 50 per 10,000. The difference is 50 - 30 = 20.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A: 90/30000*10000 = 30. B: 60/12000*10000 = 50. 50-30 = 20.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6bbc0c6a-972e-4c0c-b622-d88bbcf423b7', 'NC26.M1.SDSR.3', 3, 'choice', 'Choosing relevant variables', 'Four variables are checked against a final score. The correlation coefficients are: hours studied, $r = 0.71$; absences, $r = -0.64$; shoe size, $r = 0.03$; homework average, $r = 0.82$. Which two variables are the strongest predictors of the final score?', '["Hours studied and number of absences","Homework average and student shoe size","Homework average and hours studied","Absences and shoe size"]', 'Homework average and hours studied', NULL, 'Strength depends on how far $r$ is from 0, not on its sign. The two largest values of |r| are 0.82 (homework average) and 0.71 (hours studied).', 'checked', '{"lint":[],"solve":{"answer":"Homework average and hours studied","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|r|: homework 0.82, hours 0.71, absences 0.64, shoe 0.03. Top two: homework, hours.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9607f688-3d9f-4727-9fe4-01b35cbe8feb', 'NC26.M1.SDSR.3', 3, 'choice', 'Choosing relevant variables', 'A model predicts a house''s price from its floor area, but its errors are large. The residuals are mostly positive for houses near the lake and mostly negative for houses far from the lake. Which variable should be added?', '["Color of the front door","First name of the owner","Number of letters in the street name","Distance from the lake"]', 'Distance from the lake', NULL, 'The errors follow a pattern tied to location near the lake, so the distance from the lake is the variable that can improve the model.', 'checked', '{"lint":[],"solve":{"answer":"Distance from the lake","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Residual pattern by lake proximity means distance from lake explains the missing variation.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('30847447-b689-44e0-b61b-03708d41c372', 'NC26.M1.SDSR.3', 3, 'numeric', 'Evaluating a dataset for a question', 'The hours of sleep recorded for 8 students are 7, 9, 8, 6, 70, 8, 7 and 8. The value 70 was a typing mistake for 7. What is the correct mean number of hours of sleep?', '[]', '7.5', '(7+9+8+6+7+8+7+8)/8', 'Correct the value: 7, 9, 8, 6, 7, 8, 7, 8. The sum is 60, and 60 / 8 = 7.5 hours.', 'checked', '{"lint":[],"solve":{"answer":"7.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Corrected: 7+9+8+6+7+8+7+8 = 60; 60/8 = 7.5.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
