INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('836504bf-06d2-467a-9926-cf2a63a2bfce', 'NC26.M1.SDSR.3', 3, 'numeric', 'Evaluating a dataset for a question', 'Each of 60 survey forms has 10 questions. Across all of the forms, 90 answers are blank. What percent of all the answers are blank?', '[]', '15', '90/(60*10)*100', 'There are 60 x 10 = 600 answers in all. 90 / 600 = 0.15, which is 15 percent.', 'checked', '{"lint":[],"solve":{"answer":"15","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"60*10 = 600 answers; 90/600 = 15%.","run_id":"claude-code","at":"2026-10-18T03:38:57.604Z"}}', 'ai', NULL, NULL)
