INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('bd18f716-e669-4af1-904e-c22086c9d4e6', 'NC26.M1.SDSR.4', 1, 'numeric', 'Reading a point in context', 'Five dogs are plotted with age in years on the horizontal axis and weight in pounds on the vertical axis: $(1, 20)$, $(3, 45)$, $(5, 60)$, $(8, 58)$ and $(10, 50)$. What is the age, in years, of the heaviest dog?', '[]', '5', '5', 'The heaviest dog has the greatest vertical value, 60 pounds, at the point $(5, 60)$. The age is the horizontal value, 5 years.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Largest weight is 60 at (5, 60), so the heaviest dog is 5 years old.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
