INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('db5098ca-e62b-4c16-bb6e-942b8cc1bd28', 'NC26.M1.SDSR.4', 1, 'choice', 'Outliers, clusters and gaps', 'What is a point called when it lies far away from the pattern of all the other points in a scatter plot?', '["A cluster","A gap","An outlier","A trend"]', 'An outlier', NULL, 'A point that stands apart from the overall pattern is an outlier. A cluster is a group of points close together, and a gap is an empty region.', 'checked', '{"lint":[],"solve":{"answer":"An outlier","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A point far from the pattern of the others is an outlier.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('358afe9d-6865-46f8-8e45-33828ae1e6c5', 'NC26.M1.SDSR.4', 1, 'choice', 'Interpolation and extrapolation', 'A line of best fit is made from data with $x$-values from 10 to 30. Using the line to predict $y$ for $x = 20$ is called which of these?', '["Extrapolation","Correlation","Residual","Interpolation"]', 'Interpolation', NULL, 'Predicting inside the range of the data is interpolation. Predicting outside the range is extrapolation.', 'checked', '{"lint":[],"solve":{"answer":"Interpolation","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 20 is inside 10 to 30: interpolation.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6215da95-d729-4954-b4b1-e094b89436f2', 'NC26.M1.SDSR.4', 1, 'numeric', 'Critiquing a misleading display', 'A pie chart labels its slices 40 percent, 35 percent, 30 percent and 25 percent. These labels add up to more than 100 percent. By how many percentage points do they pass 100 percent?', '[]', '30', '40+35+30+25-100', 'The labels add to $40 + 35 + 30 + 25 = 130$ percent. A whole pie is 100 percent, so the labels are $130 - 100 = 30$ points too many.', 'checked', '{"lint":[],"solve":{"answer":"30","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"40 + 35 + 30 + 25 = 130. 130 - 100 = 30.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f037af97-70af-4fe6-854c-7cf2ed0dcf2c', 'NC26.M1.SDSR.4', 1, 'choice', 'Critiquing a misleading display', 'The labels on the vertical axis of a bar graph are 0, 10, 20, 50 and 100, drawn at equal spacing. Why is this misleading?', '["Equal spaces on the axis stand for different amounts","The axis has too few labels","The axis should start at 10 instead of 0","The labels should be written in order from largest to smallest"]', 'Equal spaces on the axis stand for different amounts', NULL, 'On a fair axis, equal spaces stand for equal amounts. Here the step from 20 to 50 uses the same space as the step from 0 to 10, which distorts the bar heights.', 'checked', '{"lint":[],"solve":{"answer":"Equal spaces on the axis stand for different amounts","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Equal gaps stand for 10, 10, 30, 50 units: unequal amounts, misleading.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('6137a21c-2364-41eb-bf1f-7966d6f3be11', 'NC26.M1.SDSR.4', 1, 'choice', 'Critiquing a misleading display', 'A graph of monthly rainfall has no title and no labels on either axis. What is the main problem with it?', '["The graph has too many bars for a reader to count them","The bars are not all drawn in the same color, so it looks messy","A reader cannot tell what is measured or in which units","The graph shows rainfall instead of showing temperature"]', 'A reader cannot tell what is measured or in which units', NULL, 'Without a title and labels, a reader cannot tell which quantities are shown or what units they have, so the graph cannot be interpreted.', 'checked', '{"lint":[],"solve":{"answer":"A reader cannot tell what is measured or in which units","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Without title or axis labels a reader cannot tell what is measured or its units.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5ddc12c4-338a-430d-9f28-8163be5690cc', 'NC26.M1.SDSR.4', 1, 'choice', 'Reading non-standard displays', 'A bubble chart plots each country: the horizontal position is average income, the vertical position is life expectancy, and the size of each bubble shows population. What does a bigger bubble mean?', '["The country has a larger population","The country has a higher average income","The country has a longer life expectancy","The country has more land"]', 'The country has a larger population', NULL, 'Position shows income and life expectancy. The size of the bubble is the third variable, which the chart says is population.', 'checked', '{"lint":[],"solve":{"answer":"The country has a larger population","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Bubble size shows population, so a bigger bubble means a larger population.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff8fb7e4-dbe5-462b-ae1b-c7ab99ea5ef8', 'NC26.M1.SDSR.4', 1, 'choice', 'Reading non-standard displays', 'A chart must show three numbers for each city on one plot: parks, average commute time and population. Which display can do this?', '["A pie chart, using one slice for each of the cities","A single bar graph, using the height of each bar","A scatter plot, using only its two axes for the numbers","A bubble chart, using bubble size for the third number"]', 'A bubble chart, using bubble size for the third number', NULL, 'A scatter plot shows two numbers by position. A bubble chart adds a third number as the size of each point, so it can show all three.', 'checked', '{"lint":[],"solve":{"answer":"A bubble chart, using bubble size for the third number","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Three numbers per city: two axes plus bubble size, a bubble chart.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8f9869fe-7ea8-471c-a3eb-ff6b9db159d8', 'NC26.M1.SDSR.4', 1, 'choice', 'Choosing and building a scatter plot', 'A teacher wants to see how the hours 20 students studied relate to their test scores. Which display is best?', '["A scatter plot, with one axis for hours and one for scores","A pie chart with one slice for each of the 20 students","A bar graph that shows only the names of the students","A table that lists only the scores, in order from low to high"]', 'A scatter plot, with one axis for hours and one for scores', NULL, 'To see how two numerical variables are related, each student''s pair of values is plotted as one point. That is a scatter plot.', 'checked', '{"lint":[],"solve":{"answer":"A scatter plot, with one axis for hours and one for scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two numerical variables per student: a scatter plot with hours and scores on the axes.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c927b1a1-d530-48d8-9a25-a0bd19dcec96', 'NC26.M1.SDSR.4', 1, 'choice', 'Choosing and building a scatter plot', 'A researcher wants to see whether the number of hours students study helps predict their quiz score. Which variable usually goes on the horizontal axis?', '["Hours studied","Quiz score","The students'' names","Whichever is larger"]', 'Hours studied', NULL, 'The variable used to predict, here hours studied, goes on the horizontal axis. The variable being predicted, the quiz score, goes on the vertical axis.', 'checked', '{"lint":[],"solve":{"answer":"Hours studied","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The explanatory (predictor) variable, hours studied, goes on the horizontal axis.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('f5319e46-a6b0-405a-985c-d183b8bc3fc9', 'NC26.M1.SDSR.4', 1, 'numeric', 'Reading non-standard displays', 'Each point on a scatter plot shows a student''s height and arm span, and the color of the point shows the student''s grade (6, 7 or 8). How many different variables does each point show?', '[]', '3', NULL, 'Each point shows the height, the arm span and the grade, so it shows 3 variables. The grade is carried by the color of the point.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Height, arm span and grade: 3 variables.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
