INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a66e50ec-5bf2-4a7d-9e0c-5528aa9efb67', 'NC26.M1.SDSR.4', 3, 'choice', 'Outliers, clusters and gaps', 'A scientist sees one point far from the pattern in a scatter plot of her measurements. What is the best thing to do?', '["Delete it at once, because every outlier is a mistake in measuring","Keep it and never mention it, because all of the data must be kept","Check whether it was recorded wrongly, and say what was done","Delete the points near it as well, so that the pattern is clear"]', 'Check whether it was recorded wrongly, and say what was done', NULL, 'An outlier may be a recording error, or it may be a real and important result. It should be checked, and a scientist should be open about it rather than silently removing or hiding data.', 'checked', '{"lint":[],"solve":{"answer":"Check whether it was recorded wrongly, and say what was done","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Investigate the outlier (recording error?) and report what was done; do not silently keep or delete.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e873c2f0-09d3-4475-8400-1d973b38413f', 'NC26.M1.SDSR.4', 3, 'numeric', 'Interpolation and extrapolation', 'A line of best fit was made from data with $x$-values from 20 to 60. For how many of the values $x = 10$, $25$, $40$, $55$ and $75$ would using the line to predict be extrapolation?', '[]', '2', '2', 'Extrapolation means going outside the range of the data. The values 10 and 75 are outside 20 to 60, while 25, 40 and 55 are inside. So 2 of the values would be extrapolation.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Range 20-60. Outside: 10 and 75. Inside: 25, 40, 55. Count 2.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a777cf47-75b1-4d7a-851e-e5a23913a39a', 'NC26.M1.SDSR.4', 3, 'choice', 'Interpolation and extrapolation', 'A line fits data with $x$-values from 20 to 60 very closely. A student predicts $y$ for $x = 100$ and says the answer is certain because the fit is so close. Which response is best?', '["The student is right: a close fit means the line works at any x","The student should use only the data point at x = 60 for the prediction","The student is right, but only if the line is steep enough to be reliable","A close fit from 20 to 60 does not guarantee the pattern continues to 100"]', 'A close fit from 20 to 60 does not guarantee the pattern continues to 100', NULL, 'A line describes the data it was fitted to. Beyond that range the relationship may change, so a prediction at $x = 100$ is extrapolation and uncertain, however close the fit was.', 'checked', '{"lint":[],"solve":{"answer":"A close fit from 20 to 60 does not guarantee the pattern continues to 100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"x = 100 is far outside 20-60; a close fit inside the range does not guarantee the pattern continues.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff328bad-fa9d-4560-887e-2e8ab2fd4cc0', 'NC26.M1.SDSR.4', 3, 'choice', 'Critiquing a misleading display', 'A graph draws ice-cream sales (left axis, 0 to 500) and sunburn cases (right axis, 0 to 50) as two lines that look almost identical. Which is a valid concern about drawing two different vertical scales on one graph?', '["It means the graph can show only one of the two variables at a time","It makes the values of both variables false, whatever they were","The scales can be chosen so two lines look more alike than they are","It forces the two lines to have exactly equal values everywhere"]', 'The scales can be chosen so two lines look more alike than they are', NULL, 'With separate axes the designer can stretch or shrink either line, so unrelated or loosely related data can be made to look closely matched. The values themselves are not changed.', 'checked', '{"lint":[],"solve":{"answer":"The scales can be chosen so two lines look more alike than they are","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Two independent scales can be chosen to make lines look alike, suggesting a closer link than exists.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c0afeb17-a5d9-4478-b1cf-89f44c1830d7', 'NC26.M1.SDSR.4', 3, 'choice', 'Critiquing a misleading display', 'A 3-D pie chart is tilted so that the slice nearest the viewer looks larger than another slice of exactly the same size at the back. Why is this misleading?', '["The slices of a 3-D pie do not have to add up to 100 percent","A pie chart cannot show two slices that have the same size","The slices at the back are always larger than they appear to be","Perspective makes slices near the viewer look larger than they are"]', 'Perspective makes slices near the viewer look larger than they are', NULL, 'In a 3-D view, parts closer to the viewer take up more of the picture. Equal shares then look unequal, so readers misjudge the data.', 'checked', '{"lint":[],"solve":{"answer":"Perspective makes slices near the viewer look larger than they are","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perspective in 3-D makes near slices look larger than equal slices at the back.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('627ffe07-a8c8-43df-bcfa-5493695cbaa0', 'NC26.M1.SDSR.4', 3, 'choice', 'Critiquing a misleading display', 'A headline says, "Sales soared 200 percent!" Sales rose from 1 item to 3 items. Why might the headline mislead readers?', '["A percent increase can never be more than 100 percent, so it is false","The increase is only 2 items, so a large percent hides a small change","The headline is fair, since a percent always describes a change fully","The word soared is wrong, because sales cannot rise by 2 items"]', 'The increase is only 2 items, so a large percent hides a small change', NULL, 'Going from 1 to 3 is an increase of 2, which is 200 percent of the starting value. The percent is correct, but because the starting amount is tiny, it makes a very small change sound enormous.', 'checked', '{"lint":[],"solve":{"answer":"The increase is only 2 items, so a large percent hides a small change","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1 to 3 is a 200 percent increase but only 2 items; the big percent hides a tiny change.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d9f3c0eb-2e50-4d94-a896-123f6d630995', 'NC26.M1.SDSR.4', 3, 'choice', 'Reading non-standard displays', 'A scatter plot of (hours studied, test score) has blue points for students who sleep 8 hours or more and red points for the others. At every number of hours studied, the blue points are above the red ones. What does this suggest?', '["Students who study more hours tend to sleep more hours each night","Sleeping for 8 hours makes every student score higher on every test","Students who sleep more tend to score higher after equal study time","Hours studied and test score are not related to each other at all"]', 'Students who sleep more tend to score higher after equal study time', NULL, 'The color is a third variable. At each study time the blue points are higher, so the well-rested students tend to score higher. The plot shows a pattern, not a proof of cause.', 'checked', '{"lint":[],"solve":{"answer":"Students who sleep more tend to score higher after equal study time","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At equal study hours, the 8+ hour sleepers score higher: those who sleep more tend to score higher after equal study time. D overstates (every, makes).","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ff57ee3c-ff1d-4ea2-a183-32b5aec92c0e', 'NC26.M1.SDSR.4', 3, 'numeric', 'Reading non-standard displays', 'A shaded grid shows the number of visitors to a library. The legend says: lightest 0 to 19, light 20 to 39, medium 40 to 59, dark 60 to 79, darkest 80 or more. Visitor counts are whole numbers. Monday morning is in the medium shade and Monday afternoon is in the darkest shade. What is the smallest possible difference between the two counts?', '[]', '21', '80-59', 'The medium shade allows at most 59 visitors and the darkest allows at least 80. The two counts are closest when the morning has 59 and the afternoon has 80, a difference of $80 - 59 = 21$.', 'checked', '{"lint":[],"solve":{"answer":"21","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Medium: 40-59, darkest: 80 or more. Smallest gap 80 - 59 = 21.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1084b7dc-bba0-4646-9fc2-f8168a16d57c', 'NC26.M1.SDSR.4', 3, 'choice', 'Reading non-standard displays', 'In a bubble chart of cities, the horizontal value is kilometers of bike lanes, the vertical value is the percent of commuters who bike, and the bubble size is population. The bubbles trend upward from the lower left to the upper right. Which conclusion is best supported?', '["Building more bike lanes will make a greater percent of commuters bike","Cities with more bike lanes tend to have a greater percent who bike","Cities with larger bubbles also have more kilometers of bike lanes","Larger cities have a greater percent of their commuters who bike"]', 'Cities with more bike lanes tend to have a greater percent who bike', NULL, 'The upward trend in position shows an association between bike lanes and biking. It does not prove that lanes cause biking, and bubble size (population) was not the thing that trended.', 'checked', '{"lint":[],"solve":{"answer":"Cities with more bike lanes tend to have a greater percent who bike","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"The upward trend links bike-lane km and percent who bike: cities with more lanes tend to have a greater percent. Causation (B) and population claims (A, C) are not supported.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7e92f264-ca42-4e96-b747-4dbc7031a869', 'NC26.M1.SDSR.4', 3, 'numeric', 'Choosing and building a scatter plot', 'A student is plotting $y$-values from 14 to 87. The vertical axis must start at 0 and go up in steps of 20, so it ends at a multiple of 20 that is at least 87. What number should the axis end at?', '[]', '100', '5*20', 'The multiples of 20 are 20, 40, 60, 80, 100. The first that is at least 87 is 100, so the axis should end at 100.', 'checked', '{"lint":[],"solve":{"answer":"100","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Multiples of 20: 80 < 87, 100 >= 87. End at 100.","run_id":"claude-code","at":"2026-10-18T01:07:42.266Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('2c2a2012-efb1-4eee-be71-0cb12376eacd', 'NC26.M1.SDSR.4', 3, 'numeric', 'Predicting from a line of best fit', 'A line of best fit for a puppy''s age, $x$ (in weeks), and its weight, $y$ (in pounds), is $y = 1.5x + 6$. At what age, in weeks, does the line predict a weight of 27 pounds?', '[]', '14', '(27-6)/1.5', 'Set the predicted weight equal to 27: $1.5x + 6 = 27$. Subtract 6 to get $1.5x = 21$, then divide by 1.5 to get $x = 14$ weeks.', 'checked', '{"lint":[],"solve":{"answer":"14","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1.5x + 6 = 27, 1.5x = 21, x = 14.","run_id":"claude-code","at":"2026-10-18T03:30:59.017Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99309c57-5f97-4fe2-8c83-fb38daa43f00', 'NC26.M1.SDSR.4', 3, 'numeric', 'Informal line of best fit', 'A line of best fit for children''s ages, $x$ (in years), and heights, $y$ (in centimeters), passes through $(5, 108)$ and $(13, 156)$. At what age does the line predict a height of 132 centimeters?', '[]', '9', '5+(132-108)/((156-108)/(13-5))', 'The slope is $\frac{156 - 108}{13 - 5} = 6$ centimeters per year. To go from 108 to 132 the height must rise 24 centimeters, which takes $24 / 6 = 4$ years after age 5. The age is $5 + 4 = 9$.', 'checked', '{"lint":[],"solve":{"answer":"9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = (156-108)/(13-5) = 48/8 = 6. y = 108 + 6(x-5). 132 = 108 + 6(x-5) -> x-5 = 4 -> x = 9.","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('75aea6af-aad5-4893-82b7-0bc78cb041d1', 'NC26.M1.SDSR.5', 1, 'choice', 'Strength of a correlation coefficient', 'Four data sets have these correlation coefficients, $r$. Which value shows the strongest linear relationship?', '["0.6","0.2","-0.4","-0.9"]', '-0.9', '-0.9', 'The strength of a linear relationship depends on how close $r$ is to $1$ or $-1$, not on its sign. Of the four, $-0.9$ is the closest to $-1$, so it is the strongest.', 'checked', '{"lint":[],"solve":{"answer":"-0.9","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strength is |r|: 0.9 > 0.6 > 0.4 > 0.2, so -0.9.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65317492-b01c-40f6-9dcb-42fd95bd0822', 'NC26.M1.SDSR.5', 1, 'numeric', 'Computing a residual', 'A residual is the actual value minus the predicted value. A line predicts a quiz score of 47 for a student, but the student actually scored 52. What is the residual?', '[]', '5', '52-47', 'Residual $=$ actual $-$ predicted $= 52 - 47 = 5$.', 'checked', '{"lint":[],"solve":{"answer":"5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Residual = 52 - 47 = 5.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('480de9e5-9d66-4e80-9fe0-90af384d4e92', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation is not causation', 'Data show that towns with more ice cream sales also have more sunburns. What is the best conclusion?', '["Eating ice cream causes people to get sunburned","Hot, sunny weather may cause both, so the data do not show that ice cream causes sunburns","Getting sunburned causes people to buy more ice cream","There is no relationship between ice cream sales and sunburns"]', 'Hot, sunny weather may cause both, so the data do not show that ice cream causes sunburns', NULL, 'The two go up together, so they are correlated. But a third variable, hot sunny weather, can explain both. A correlation alone does not show that one thing causes the other.', 'checked', '{"lint":[],"solve":{"answer":"Hot, sunny weather may cause both, so the data do not show that ice cream causes sunburns","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Correlation is not causation; hot sunny weather is a likely common cause of both.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('721bdea4-005c-4bea-958d-add00d2358c4', 'NC26.M1.SDSR.5', 1, 'numeric', 'Least-squares line: meaning and prediction', 'The least-squares line for a taxi ride is $\hat{y} = 2x + 3$, where $x$ is the number of miles driven and $\hat{y}$ is the predicted fare in dollars. What fare does the line predict for a 10-mile ride?', '[]', '23', '2*10+3', 'Put $x = 10$ into the line: $2(10) + 3 = 23$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"23","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2(10)+3=23","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ee205d1b-4fc0-4584-bb63-c6239bb6d173', 'NC26.M1.SDSR.5', 1, 'choice', 'Least-squares line: meaning and prediction', 'A least-squares line for a bike rental shop is $\hat{y} = 6x + 4$, where $x$ is the hours rented and $\hat{y}$ is the predicted cost in dollars. What does the slope 6 tell you?', '["A rental of 0 hours is predicted to cost 6 dollars","A rental of 6 hours is predicted to cost 4 dollars","Each extra hour adds about 6 dollars to the predicted cost","Every rental is predicted to last about 6 hours"]', 'Each extra hour adds about 6 dollars to the predicted cost', NULL, 'The slope is the change in the predicted $y$ for each 1-unit increase in $x$: 6 dollars more per hour.', 'checked', '{"lint":[],"solve":{"answer":"Each extra hour adds about 6 dollars to the predicted cost","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope = change in predicted cost per extra hour = 6 dollars.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('97160c69-5cf6-4914-be2f-4fac4a0354c0', 'NC26.M1.SDSR.5', 1, 'choice', 'Least-squares line: meaning and prediction', 'A least-squares line predicts the height $\hat{h}$ (in centimeters) of a burning candle after $t$ hours: $\hat{h} = 20 - 2t$. What does the 20 represent?', '["The predicted number of hours the candle will burn","The predicted height lost during each hour","The predicted height of the candle after 2 hours","The predicted height when the candle is first lit"]', 'The predicted height when the candle is first lit', NULL, 'The 20 is the value of the line at $t = 0$, the moment the candle is lit.', 'checked', '{"lint":[],"solve":{"answer":"The predicted height when the candle is first lit","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"At t=0, h=20: height when first lit.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d71b86a9-3db7-44b3-8caa-2f0cd88074a9', 'NC26.M1.SDSR.5', 1, 'numeric', 'Least-squares line: meaning and prediction', 'The least-squares line for a data set is $\hat{y} = 3x - 4$. What is the predicted value of $y$ when $x = 5$?', '[]', '11', '3*5-4', '$3(5) - 4 = 15 - 4 = 11$.', 'checked', '{"lint":[],"solve":{"answer":"11","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3(5)-4=11","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
