INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('cf8f2441-d738-498f-960d-c28fcae4ebac', 'NC26.M1.SDSR.5', 1, 'numeric', 'Exponential models', 'A dose of medicine in the body halves every hour. At first there are 500 milligrams. How many milligrams remain after 3 hours?', '[]', '62.5', '500*0.5^3', 'Halving 3 times: 500, 250, 125, 62.5. So 62.5 milligrams remain.', 'checked', '{"lint":[],"solve":{"answer":"62.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"500/8=62.5.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
