INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('dabcb705-aaed-4e74-8ddb-05494c9855d4', 'NC26.M1.SDSR.5', 1, 'choice', 'Correlation coefficient: sign and strength', 'In a data set, $y$ tends to get smaller as $x$ gets larger. The correlation coefficient $r$ is most likely', '["positive","a negative value","a value greater than 1","exactly 0"]', 'a negative value', NULL, 'A pattern that falls from left to right has a negative correlation.', 'checked', '{"lint":[],"solve":{"answer":"a negative value","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"y falls as x rises: negative r.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
