INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('442b59e0-98e2-4945-aad8-5bd06f6f00e5', 'NC26.M1.SDSR.5', 1, 'numeric', 'Correlation coefficient: sign and strength', 'All the data points lie exactly on the line $y = -3x + 7$. What is the correlation coefficient $r$?', '[]', '-1', NULL, 'Points exactly on a line with a negative slope give $r = -1$, a perfect negative linear relationship.', 'checked', '{"lint":[],"solve":{"answer":"-1","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Perfect line with negative slope: r=-1.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
