INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e900ea2d-16e8-4348-b281-71f1f566562e', 'NC26.M1.SDSR.5', 1, 'numeric', 'Residuals and residual plots', 'The line $\hat{y} = 2x + 5$ is used to predict $y$. At $x = 4$, the actual value of $y$ is 15. What is the residual?', '[]', '2', '15-(2*4+5)', 'Predicted: 2(4) + 5 = 13. Residual = 15 - 13 = 2.', 'checked', '{"lint":[],"solve":{"answer":"2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predicted 2(4)+5=13; 15-13=2.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a5fb9dcd-63d1-4daf-9b88-310d2ee784e9', 'NC26.M1.SDSR.5', 1, 'choice', 'Residuals and residual plots', 'A residual plot shows points scattered randomly above and below zero with no pattern. What does this suggest about a linear model?', '["The two variables have no relationship at all","A curved model is needed instead","A linear model is appropriate for the data","The line fits the data very badly"]', 'A linear model is appropriate for the data', NULL, 'Random scatter of residuals about zero is what we expect when a line is a good model.', 'checked', '{"lint":[],"solve":{"answer":"A linear model is appropriate for the data","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Random residual scatter: linear model appropriate.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5eaaa748-1a3f-4327-beb3-d8d44aa7c9fa', 'NC26.M1.SDSR.5', 1, 'choice', 'Outliers and influential points', 'What is an outlier in a scatter plot?', '["The point with the largest $x$-value in the data set","The point where the line crosses the $y$-axis","The point with the same $x$-value as another point","A point far from the overall pattern of the points"]', 'A point far from the overall pattern of the points', NULL, 'An outlier stands apart from the general pattern of the other points.', 'checked', '{"lint":[],"solve":{"answer":"A point far from the overall pattern of the points","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Outlier: far from overall pattern.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
