INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e1825506-7326-4dfa-b44b-aecab84a581c', 'NC26.M1.SDSR.5', 1, 'choice', 'Outliers and influential points', 'On a scatter plot, one point is far from the line, and it turns out that its value was typed wrongly. What should be done?', '["Correct the error, since the point was recorded wrongly","Move the line so that it passes through that one wrong point","Remove every other point from the data set, then draw a new line","Leave the error in the data and say nothing about it to anyone"]', 'Correct the error, since the point was recorded wrongly', NULL, 'If a point is far from the pattern because of a recording mistake, the right step is to fix the mistake.', 'checked', '{"lint":[],"solve":{"answer":"Correct the error, since the point was recorded wrongly","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A known recording error should be corrected.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
