INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('65ed6896-c1ce-4aeb-af66-da1b4cd883d1', 'NC26.M1.SDSR.5', 2, 'numeric', 'Least-squares line: meaning and prediction', 'For a data set, the mean of the $x$-values is 10 and the mean of the $y$-values is 50. The least-squares line has slope 3. What is its $y$-intercept?', '[]', '20', '50-3*10', 'A least-squares line passes through the point (mean of $x$, mean of $y$) = (10, 50). So $50 = 3(10) + b$, which gives $b = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LSRL passes through (10,50): 50=3(10)+b, b=20.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c5b4a61b-3958-48cf-a1e3-b6d1f5414f02', 'NC26.M1.SDSR.5', 2, 'numeric', 'Least-squares line: meaning and prediction', 'The least-squares line $\hat{y} = 2.5x + 10$ predicts the weight of a puppy, in pounds, at age $x$ weeks. At what age does the line predict a weight of 35 pounds?', '[]', '10', '(35-10)/2.5', 'Solve $2.5x + 10 = 35$: $2.5x = 25$, so $x = 10$ weeks.', 'checked', '{"lint":[],"solve":{"answer":"10","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.5x+10=35, 2.5x=25, x=10.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('49b04598-1204-4fb8-bed6-5e260f93b8e8', 'NC26.M1.SDSR.5', 2, 'choice', 'Least-squares line: meaning and prediction', 'As the temperature $x$ rises, the number of winter coats $y$ sold in a store falls. Which equation could be the least-squares line for these data?', '["$\\hat{y} = -4.2x + 300$","$\\hat{y} = 4.2x + 300$","$\\hat{y} = -4.2x - 300$","$\\hat{y} = 300x + 4.2$"]', '$\hat{y} = -4.2x + 300$', NULL, 'Sales fall as temperature rises, so the slope is negative. The intercept must also be positive: a negative intercept would predict negative sales on a very cold day.', 'checked', '{"lint":[],"solve":{"answer":"$\\hat{y} = -4.2x + 300$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Falling y means negative slope; -4.2x-300 gives negative sales for positive temps, so -4.2x+300.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e716440e-a9d0-4077-b89f-71c2058b437f', 'NC26.M1.SDSR.5', 2, 'numeric', 'Least-squares line: meaning and prediction', 'A line of best fit passes through the points $(2, 14)$ and $(6, 30)$. What value of $y$ does the line predict when $x = 10$?', '[]', '46', '30+(30-14)/(6-2)*(10-6)', 'Slope = (30 - 14) / (6 - 2) = 4. From $x = 6$ to $x = 10$ is 4 more units, so $y = 30 + 4(4) = 46$.', 'checked', '{"lint":[],"solve":{"answer":"46","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Slope=(30-14)/(6-2)=4; y=14+4(10-2)=46.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('08e7c1a5-a3a2-4de3-b8e2-7fee3b964822', 'NC26.M1.SDSR.5', 2, 'choice', 'Least-squares line: meaning and prediction', 'What makes a line the least-squares line for a data set?', '["It passes through as many of the data points as it possibly can do","It makes the sum of the squared residuals as small as possible","It has the same number of points above it as below it","It connects the first data point in the list to the last data point"]', 'It makes the sum of the squared residuals as small as possible', NULL, 'The least-squares line is the one for which the total of the squares of the residuals is smallest.', 'checked', '{"lint":[],"solve":{"answer":"It makes the sum of the squared residuals as small as possible","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Definition: minimizes sum of squared residuals.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e7732675-01d6-4fdc-95bf-ede6662c3b63', 'NC26.M1.SDSR.5', 2, 'numeric', 'Exponential models', 'An account holds 2000 dollars and grows by 10 percent each year, so $A = 2000(1.1)^t$. How many dollars are in the account after 2 years?', '[]', '2420', '2000*1.1^2', '$(1.1)^2 = 1.21$, and 2000 x 1.21 = 2420 dollars.', 'checked', '{"lint":[],"solve":{"answer":"2420","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2000(1.21)=2420.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8d9c6ecd-45b1-4a2b-81d2-32b455489c31', 'NC26.M1.SDSR.5', 2, 'choice', 'Exponential models', 'The values of $y$ for $x = 0, 1, 2, 3$ are 4, 12, 36, 108. Which equation fits these data?', '["$y = 4 + 8x$","$y = 4(3)^x$","$y = 4(8)^x$","$y = 12x + 4$"]', '$y = 4(3)^x$', NULL, 'Each value is 3 times the one before it (12/4 = 3, 36/12 = 3, 108/36 = 3), so the growth factor is 3 and the start is 4.', 'checked', '{"lint":[],"solve":{"answer":"$y = 4(3)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Ratios 12/4=36/12=108/36=3, start 4: y=4(3)^x.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('3f7bb393-ce76-429f-b733-2c68a9f006ae', 'NC26.M1.SDSR.5', 2, 'numeric', 'Exponential models', 'An exponential model passes through the points $(0, 6)$ and $(1, 15)$. What is its growth factor?', '[]', '2.5', '15/6', 'In $y = a \cdot b^x$, $a = 6$ (the value at $x = 0$). At $x = 1$, $y = 6b = 15$, so $b = 15/6 = 2.5$.', 'checked', '{"lint":[],"solve":{"answer":"2.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"a=6, ab=15, b=2.5.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5aa929d0-4ed6-418a-ac7e-b855d6ff6aac', 'NC26.M1.SDSR.5', 2, 'choice', 'Exponential models', 'The value of a machine is modeled by $V = 3000(0.85)^t$, where $t$ is in years. By what percent does its value decrease each year?', '["85 percent a year","0.85 percent a year","15 percent each year","8.5 percent a year"]', '15 percent each year', NULL, 'Each year the value is 0.85 times the year before, which is 85 percent of it. So it loses 100 - 85 = 15 percent.', 'checked', '{"lint":[],"solve":{"answer":"15 percent each year","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"1-0.85=0.15: 15 percent decrease per year.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d85a0c4e-4804-40e8-b372-81e2bbc3e885', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation coefficient: sign and strength', 'Compare two data sets: one has $r = -0.8$ and the other has $r = 0.6$. Which statement is true?', '["The set with $r = 0.6$ has the stronger linear relationship because it is positive","Both sets have equally strong relationships because both are far from 0","The set with $r = -0.8$ has the weaker relationship because it is negative","The set with $r = -0.8$ has the stronger linear relationship"]', 'The set with $r = -0.8$ has the stronger linear relationship', NULL, 'Strength depends on how close $|r|$ is to 1, not on the sign. $|{-0.8}| = 0.8$ is greater than $0.6$.', 'checked', '{"lint":[],"solve":{"answer":"The set with $r = -0.8$ has the stronger linear relationship","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"|-0.8|>|0.6|, so r=-0.8 is stronger.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('4289ffbe-5e63-4f23-82f6-4d596cec84c5', 'NC26.M1.SDSR.5', 2, 'numeric', 'Correlation coefficient: sign and strength', 'Heights in inches and weights in pounds of some adults have $r = 0.7$. Each height is then converted to centimeters. What is the new value of $r$?', '[]', '0.7', '0.7', 'Changing the units of a variable does not change $r$, so it is still 0.7.', 'checked', '{"lint":[],"solve":{"answer":"0.7","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r unchanged by positive linear change of units: 0.7.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
