INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('c4b39024-557d-4c8f-8910-dd1eeac9c66a', 'NC26.M1.SDSR.5', 2, 'numeric', 'Residuals and residual plots', 'The line $\hat{y} = 2x + 3$ is fit to the data points $(2, 9)$, $(4, 11)$ and $(6, 18)$. What is the greatest of the three residuals?', '[]', '3', '18-(2*6+3)', 'Predicted values: 7, 11, 15. Residuals: 9 - 7 = 2, 11 - 11 = 0, 18 - 15 = 3. The greatest is 3.', 'checked', '{"lint":[],"solve":{"answer":"3","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predictions 7,11,15; residuals 2,0,3; greatest 3.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('56c0cec6-4963-42f5-a9e3-271f39255d88', 'NC26.M1.SDSR.5', 2, 'choice', 'Residuals and residual plots', 'The residual for one student is $-8$ points. Which statement is correct?', '["The line predicted 8 points fewer than the student actually scored","The student scored exactly 8 points","The line''s prediction is off by 8 percent of the student''s actual score","The line predicted 8 points more than the student actually scored"]', 'The line predicted 8 points more than the student actually scored', NULL, 'Residual = actual - predicted = -8, so the prediction is 8 points higher than the actual score.', 'checked', '{"lint":[],"solve":{"answer":"The line predicted 8 points more than the student actually scored","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"-8=actual-predicted: predicted is 8 more than actual.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('7de1a764-23cc-4252-8ea3-6f4835d53d47', 'NC26.M1.SDSR.5', 2, 'numeric', 'Residuals and residual plots', 'The residuals for four data points are 2, $-3$, 1 and $-2$. What is the sum of the squares of these residuals?', '[]', '18', '2^2+3^2+1^2+2^2', 'Squares: 4, 9, 1, 4. Their sum is 4 + 9 + 1 + 4 = 18.', 'checked', '{"lint":[],"solve":{"answer":"18","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4+9+1+4=18.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5383c38f-1f09-42b8-9016-1d14f2d0f62b', 'NC26.M1.SDSR.5', 2, 'numeric', 'Outliers and influential points', 'With all 12 points, the slope of the least-squares line is 0.8. With one outlier removed, it is 2.3. By how much did the slope change when the outlier was removed?', '[]', '1.5', '2.3-0.8', '2.3 - 0.8 = 1.5, so that one point changed the slope a lot.', 'checked', '{"lint":[],"solve":{"answer":"1.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.3-0.8=1.5.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
