INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d0edce3e-a97a-4428-99c8-6fe555f79514', 'NC26.M1.SDSR.5', 2, 'choice', 'Outliers and influential points', 'A student wants to delete a point because it lowers the correlation. When is it reasonable to remove it?', '["Whenever it lowers $r$, as the goal is to get the highest $r$ possible","Never, because points can never be removed","Whenever it lies on the left side of the plot","Only with a good reason, such as a known recording error"]', 'Only with a good reason, such as a known recording error', NULL, 'A point should be removed only if there is a reason to believe it is an error or does not belong. Otherwise it should be kept, perhaps reporting the results both ways.', 'checked', '{"lint":[],"solve":{"answer":"Only with a good reason, such as a known recording error","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Remove only with a good reason, e.g. recording error.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8fe32769-77ea-44a7-9d01-f3f9a835c3e9', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation versus causation', 'Sales of heaters and sales of wool hats both rise in December. What is the best explanation?', '["Buying heaters makes people go out and buy wool hats too","Buying wool hats makes people buy heaters","The two are not linked in any way","A third variable, cold weather, influences both"]', 'A third variable, cold weather, influences both', NULL, 'Cold weather affects both. This is a lurking variable rather than one product causing the other.', 'checked', '{"lint":[],"solve":{"answer":"A third variable, cold weather, influences both","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Cold weather is a lurking variable for both.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('16cd34a3-19c2-4e2a-8c25-895b1c93deb7', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation versus causation', 'An observational study finds a strong positive correlation between time spent on a learning app and test scores. Which statement is supported?', '["Students who spend more time on the app tend to have higher scores","Spending more time on the app will raise the score of any single student","Higher test scores make students want to spend much more time on the app","App time is the only thing that affects test scores"]', 'Students who spend more time on the app tend to have higher scores', NULL, 'Observational data support a statement about association only, not about cause.', 'checked', '{"lint":[],"solve":{"answer":"Students who spend more time on the app tend to have higher scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Observational: only association is supported.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1b032ced-415a-4d36-ac79-546f2ff31edd', 'NC26.M1.SDSR.5', 2, 'numeric', 'Correlation versus causation', 'In an observational study of 500 students, 300 used a reading app and 200 did not. Of the users, 240 passed the test. Of the non-users, 120 passed. By how many percentage points is the users'' pass rate higher than the non-users'' pass rate?', '[]', '20', '240/300*100-120/200*100', 'Users: 240 / 300 = 80 percent. Non-users: 120 / 200 = 60 percent. The difference is 20 percentage points. Because students chose whether to use the app, this shows an association but does not prove the app caused it.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"240/300=80%, 120/200=60%; difference 20 points.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('a6259137-fe34-4a19-b827-88f56f1233f8', 'NC26.M1.SDSR.5', 2, 'choice', 'Correlation versus causation', 'A study only observed teens and did not assign them to any group. Which headline claims more than the study can show?', '["Teens who eat breakfast tend to do better in school","Eating breakfast makes teens do better in school","Breakfast and school grades are linked in a survey of teens","Teens who skip breakfast are less likely to have top grades"]', 'Eating breakfast makes teens do better in school', NULL, '"Makes" claims a cause. The other headlines describe only an association.', 'checked', '{"lint":[],"solve":{"answer":"Eating breakfast makes teens do better in school","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Causal claim from observational study: \"makes\".","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('e77e83e8-e4e8-43fa-a3b3-7b36e6cd47ba', 'NC26.M1.SDSR.5', 2, 'choice', 'Making and judging predictions', 'A line is fit to a park''s number of visitors each month from March to October. A planner uses it to predict visitors in December. Which statement is best?', '["It is reliable because the line is a least-squares line","It is reliable because December comes right after October","It is unreliable only when the correlation is negative","It is risky, since December is outside the months studied"]', 'It is risky, since December is outside the months studied', NULL, 'December is outside the range of the data, and visitor patterns in winter may be very different from the months studied.', 'checked', '{"lint":[],"solve":{"answer":"It is risky, since December is outside the months studied","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"December is outside March-October: extrapolation, risky.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ceef31c0-60bc-43e4-bfd1-94e2f398d562', 'NC26.M1.SDSR.5', 2, 'numeric', 'Making and judging predictions', 'The line $\hat{y} = 2.4x + 18$ is fit to data. For what value of $x$ does the line predict $y = 66$?', '[]', '20', '(66-18)/2.4', 'Solve $2.4x + 18 = 66$: $2.4x = 48$, so $x = 20$.', 'checked', '{"lint":[],"solve":{"answer":"20","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"2.4x+18=66, 2.4x=48, x=20.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8c59d45f-cf11-46ac-a464-20048f1a0b9f', 'NC26.M1.SDSR.5', 2, 'numeric', 'Making and judging predictions', 'A town''s population is modeled by $P = 5000(1.02)^t$, where $t$ is the number of years from now. What population does the model predict after 2 years?', '[]', '5202', '5000*1.02^2', '$(1.02)^2 = 1.0404$, and 5000 x 1.0404 = 5202 people.', 'checked', '{"lint":[],"solve":{"answer":"5202","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"5000(1.02)^2=5000(1.0404)=5202.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8734e375-3574-4860-8607-3b5586131343', 'NC26.M1.SDSR.5', 2, 'choice', 'Making and judging predictions', 'Which prediction is the most trustworthy?', '["A prediction from a line with $r = 0.95$ at an $x$-value inside the data''s range","A prediction from a line with $r = 0.3$ at an $x$-value inside the data''s range","A prediction from a line with $r = 0.95$ at an $x$-value far outside the data''s range","A prediction from a line with $r = 0.3$ at an $x$-value far outside the data''s range"]', 'A prediction from a line with $r = 0.95$ at an $x$-value inside the data''s range', NULL, 'Reliable predictions need a strong relationship and an $x$-value within the range of the data.', 'checked', '{"lint":[],"solve":{"answer":"A prediction from a line with $r = 0.95$ at an $x$-value inside the data''s range","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Strong r and interpolation.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('481e3a70-fb35-48dc-8b86-f59af54f31a1', 'NC26.M1.SDSR.5', 2, 'numeric', 'Outliers and influential points', 'The least-squares line $\hat{y} = 4x + 10$ is used for three students. At $x = 2$ the actual $y$ is 19, at $x = 5$ it is 31, and at $x = 8$ it is 70. One of the three points is an outlier. What is that point''s residual (actual value minus predicted value)?', '[]', '28', '70-(4*8+10)', 'The line predicts 18, 30 and 42. The residuals are $19 - 18 = 1$, $31 - 30 = 1$ and $70 - 42 = 28$. The point at $x = 8$ is far from the line, so it is the outlier, and its residual is 28.', 'checked', '{"lint":[],"solve":{"answer":"28","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Predictions: x=2 -> 18, x=5 -> 30, x=8 -> 42. Residuals: 19-18=1, 31-30=1, 70-42=28. The outlier is (8,70), residual 28.","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('b44027b7-7a94-4ea6-9de7-a0f5b17f44ae', 'NC26.M1.SDSR.5', 2, 'numeric', 'Outliers and influential points', 'A least-squares line fit to all of a data set is $\hat{y} = 1.2x + 9$. After one outlier is removed, the new line is $\hat{y} = 2x + 5$. At $x = 10$, how much greater is the prediction from the new line than the prediction from the line fit to all of the data?', '[]', '4', '(2*10+5)-(1.2*10+9)', 'The line fit to all of the data predicts $1.2(10) + 9 = 21$. The new line predicts $2(10) + 5 = 25$. The difference is $25 - 21 = 4$, so the outlier pulled the prediction down by 4.', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"New line at x=10: 2(10)+5=25. Old line: 1.2(10)+9=21. Difference 25-21=4.","run_id":"claude-code","at":"2026-10-18T03:43:15.049Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71b160e6-80e2-47c9-bd2e-f67015cefed0', 'NC26.M1.SDSR.5', 3, 'choice', 'Effect of an outlier on correlation', 'For a set of 20 data points, $r = 0.45$. After one point that lies far from the pattern is removed, $r$ becomes $0.92$. What does this suggest about that point?', '["It proved that the two variables are not related","Removing any point always raises the correlation","It was an outlier that was weakening the linear pattern","The two variables now cause each other"]', 'It was an outlier that was weakening the linear pattern', NULL, 'The remaining 19 points follow a strong linear pattern ($r = 0.92$). The one point far from it pulled the correlation down, so it is an outlier. Removing a point does not always raise $r$, and a correlation never proves cause.', 'checked', '{"lint":[],"solve":{"answer":"It was an outlier that was weakening the linear pattern","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Removing one far-off point raised r from 0.45 to 0.92, so that point was an outlier weakening the linear pattern.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('71d79481-19e1-4251-82d2-3ea126b109f1', 'NC26.M1.SDSR.5', 3, 'numeric', 'Evaluating an exponential model', 'The value of a car is modeled by $V = 20{,}000(0.9)^t$, where $V$ is its value in dollars and $t$ is its age in years. What is the value of the car after 2 years, in dollars?', '[]', '16200', '20000*0.9^2', 'Substitute $t = 2$: $V = 20{,}000(0.9)^2 = 20{,}000(0.81) = 16{,}200$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"16200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"V = 20000 x 0.9^2 = 20000 x 0.81 = 16200.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('5cef7b8a-73a0-44bf-930b-1bd18a57f245', 'NC26.M1.SDSR.5', 3, 'choice', 'Reading a residual plot', 'A residual plot for a linear model shows the residuals forming a clear U-shaped curve instead of a random scatter around 0. What does this suggest?', '["A straight line is not the best model; a curve may fit better","The linear model fits the data perfectly","The correlation coefficient must be exactly 0","Every data point is an outlier"]', 'A straight line is not the best model; a curve may fit better', NULL, 'A good linear model leaves residuals scattered randomly around 0. A clear curved pattern in the residuals means the data bend away from a straight line, so a curved model, such as an exponential one, may fit better.', 'checked', '{"lint":[],"solve":{"answer":"A straight line is not the best model; a curve may fit better","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"A curved pattern in residuals means the linear model misses curvature; a nonlinear model may fit better.","run_id":"claude-code","at":"2026-10-17T18:37:09.752Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('377d1473-04af-4cd6-9c17-ffebfd96664c', 'NC26.M1.SDSR.5', 3, 'numeric', 'Least-squares line: meaning and prediction', 'A data set has a mean $x$-value of 20 and a mean $y$-value of 65. Its least-squares line has slope 1.5. What $y$-value does the line predict when $x = 30$?', '[]', '80', '65+1.5*(30-20)', 'The line passes through (20, 65). Going from $x = 20$ to $x = 30$ is 10 units, which adds $1.5 \times 10 = 15$. So $y = 65 + 15 = 80$.', 'checked', '{"lint":[],"solve":{"answer":"80","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Line through (20,65), slope 1.5: 65+1.5(10)=80.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('1fb9c899-9f7c-42e7-bdee-19823cc07d8b', 'NC26.M1.SDSR.5', 3, 'numeric', 'Least-squares line: meaning and prediction', 'A least-squares line $\hat{y} = 8x + 120$ predicts a seedling''s height $\hat{y}$ in millimeters after $x$ days. How tall, in centimeters, does the line predict the seedling to be after 15 days?', '[]', '24', '(8*15+120)/10', '$8(15) + 120 = 240$ millimeters. There are 10 millimeters in a centimeter, so 240 / 10 = 24 centimeters.', 'checked', '{"lint":[],"solve":{"answer":"24","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"8(15)+120=240 mm = 24 cm.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('daf8e156-d2b9-43f8-b043-ad3b8e952a29', 'NC26.M1.SDSR.5', 3, 'numeric', 'Least-squares line: meaning and prediction', 'A calculator reports a regression equation of the form $y = a + bx$ with $a = 42.5$ and $b = -0.8$. What value of $y$ does the equation predict for $x = 25$?', '[]', '22.5', '42.5-0.8*25', '$y = 42.5 + (-0.8)(25) = 42.5 - 20 = 22.5$.', 'checked', '{"lint":[],"solve":{"answer":"22.5","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"42.5+(-0.8)(25)=42.5-20=22.5.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9426fd01-d5da-4b47-bd3b-fd07f4673271', 'NC26.M1.SDSR.5', 3, 'choice', 'Least-squares line: meaning and prediction', 'Which statement is true of every least-squares line?', '["It passes through the first data point in the list of data","It always has a slope that is equal to the correlation $r$","It passes through the point (mean of $x$, mean of $y$)","It always passes through the origin of the plot, $(0, 0)$"]', 'It passes through the point (mean of $x$, mean of $y$)', NULL, 'A least-squares line always goes through (mean of $x$, mean of $y$). The slope equals $r$ only in special cases, and the line need not pass through any data point or the origin.', 'checked', '{"lint":[],"solve":{"answer":"It passes through the point (mean of $x$, mean of $y$)","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"LSRL always passes through (xbar, ybar).","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('ea4ee432-b2d5-4ca9-8b9c-56326ee4d7d4', 'NC26.M1.SDSR.5', 3, 'numeric', 'Exponential models', 'A patch of algae covers 3 square meters and triples in area every day, so its area after $t$ days is $3(3)^t$ square meters. After how many days will it cover 243 square meters?', '[]', '4', NULL, 'Divide 243 by 3: $3^t = 81$. Since $3^4 = 81$, $t = 4$ days. (Check: 3, 9, 27, 81, 243.)', 'checked', '{"lint":[],"solve":{"answer":"4","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"3*3^t=243 -> 3^(t+1)=3^5 -> t=4.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('99612023-7af9-49b0-9143-e92ca0fd4daf', 'NC26.M1.SDSR.5', 3, 'numeric', 'Exponential models', 'A town has 4000 people and grows 25 percent per year, so $P = 4000(1.25)^t$. How many more people does the town have after 2 years than it has now?', '[]', '2250', '4000*1.25^2-4000', '$(1.25)^2 = 1.5625$, and 4000 x 1.5625 = 6250. The increase is 6250 - 4000 = 2250 people.', 'checked', '{"lint":[],"solve":{"answer":"2250","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"4000(1.25)^2=4000(1.5625)=6250; 6250-4000=2250.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('d8b728fe-d8f7-47b7-8178-f2d2b5c77834', 'NC26.M1.SDSR.5', 3, 'choice', 'Exponential models', 'For $x = 0, 1, 2, 3$ the values of $y$ are 80, 48, 28.8, 17.28. Which equation fits these data?', '["$y = 80(0.4)^x$","$y = 80 - 32x$","$y = 80(1.6)^x$","$y = 80(0.6)^x$"]', '$y = 80(0.6)^x$', NULL, 'Each value is 0.6 times the one before (48/80 = 0.6, 28.8/48 = 0.6, 17.28/28.8 = 0.6). The 0.4 would be the rate of decrease, not the factor.', 'checked', '{"lint":[],"solve":{"answer":"$y = 80(0.6)^x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"48/80=0.6, 28.8/48=0.6, 17.28/28.8=0.6: y=80(0.6)^x.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('36c6620b-408e-42a0-a306-a41dc220c341', 'NC26.M1.SDSR.5', 3, 'numeric', 'Exponential models', 'Money in a fund doubles every 3 years, so $A = 800(2)^{t/3}$, where $t$ is the number of years. How many dollars are in the fund after 6 years?', '[]', '3200', '800*2^(6/3)', 'For $t = 6$ the exponent is $6/3 = 2$, so $A = 800 \times 2^2 = 800 \times 4 = 3200$ dollars.', 'checked', '{"lint":[],"solve":{"answer":"3200","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"800*2^(6/3)=800*4=3200.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('9d46513a-713b-4abe-bcef-351d04e382f4', 'NC26.M1.SDSR.5', 3, 'choice', 'Correlation coefficient: sign and strength', 'A student swaps the two variables, using the old $y$-values as $x$ and the old $x$-values as $y$. What happens to $r$?', '["It changes sign","It becomes its reciprocal","It stays the same","It drops to 0"]', 'It stays the same', NULL, 'The correlation between $x$ and $y$ is the same as the correlation between $y$ and $x$.', 'checked', '{"lint":[],"solve":{"answer":"It stays the same","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r is symmetric in x and y: stays the same.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
