INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('395d9e4a-ed57-4bc6-9b19-5d102e9c13f2', 'NC26.M1.SDSR.5', 3, 'numeric', 'Correlation coefficient: sign and strength', 'A data set has $r = 0.8$. Every $x$-value is replaced by its opposite (each $x$ becomes $-x$). What is the new value of $r$?', '[]', '-0.8', '-0.8', 'Replacing $x$ by $-x$ turns a rising pattern into a falling one with the same tightness. So $r$ becomes $-0.8$.', 'checked', '{"lint":[],"solve":{"answer":"-0.8","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Negating x flips sign: -0.8.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('486f1a8f-7bb8-4022-88b4-1832535f1117', 'NC26.M1.SDSR.5', 3, 'choice', 'Correlation coefficient: sign and strength', 'For a large data set, $r = 0.97$. Which conclusion is justified?', '["Changes in $x$ are the cause of all of the changes in $y$","97 percent of the points lie on the line","$y$ increases by 0.97 for every 1-unit increase in $x$","There is a very strong positive linear association"]', 'There is a very strong positive linear association', NULL, 'An $r$ near 1 describes a strong positive linear association only. It does not prove cause, give the percent of points on the line, or give the slope.', 'checked', '{"lint":[],"solve":{"answer":"There is a very strong positive linear association","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"r=0.97 means very strong positive linear association; not slope, not causation, not percent on line.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('fa8e7e59-6c91-4109-a7e3-9dcfa8920a29', 'NC26.M1.SDSR.5', 3, 'choice', 'Correlation coefficient: sign and strength', 'For a sample of students, the correlation between hours of TV per week and test score is $r = -0.78$. Which interpretation is correct?', '["Students with more TV time tend to have clearly lower scores","Each hour of TV watched lowers a student''s score by 0.78 points","Seventy-eight percent of the students watch a lot of TV each week","TV is only a weak influence on scores because $r$ is negative"]', 'Students with more TV time tend to have clearly lower scores', NULL, 'A negative $r$ with $|r|$ fairly close to 1 shows a fairly strong negative association. $r$ is not a slope or a percent of students.', 'checked', '{"lint":[],"solve":{"answer":"Students with more TV time tend to have clearly lower scores","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Negative, fairly strong: more TV tends to go with lower scores.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('8b4e568d-47a3-4bc1-b5b3-b8e47359d1cb', 'NC26.M1.SDSR.5', 3, 'choice', 'Residuals and residual plots', 'A residual plot shows points close to zero for small values of $x$, but spreading farther and farther from zero as $x$ increases. What does this indicate?', '["Predictions are much less precise for large values of $x$","The model is nearly perfect for the large values of $x$ in the data","The data set must contain no outliers at all, even for large $x$","The relationship between the two variables is negative overall"]', 'Predictions are much less precise for large values of $x$', NULL, 'Residuals that grow in size as $x$ grows mean the errors in prediction are bigger for large $x$.', 'checked', '{"lint":[],"solve":{"answer":"Predictions are much less precise for large values of $x$","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"","work":"Fan shape: spread grows with x, so predictions less precise for large x.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, topic_id, difficulty, kind, skill, stem, choices, answer, compute, solution, status, checks, source, reviewed_by, reviewed_at)
VALUES ('57913e80-1589-474f-a170-cfc667cf0615', 'NC26.M1.SDSR.5', 3, 'numeric', 'Residuals and residual plots', 'A least-squares line is fit to four data points. Three of the residuals are 3, $-5$ and 4. What is the fourth residual?', '[]', '-2', '-(3-5+4)', 'The residuals from a least-squares line always add to 0. So 3 + (-5) + 4 + r = 0, which gives 2 + r = 0 and r = -2.', 'checked', '{"lint":[],"solve":{"answer":"-2","agreed":true,"single_answer":true,"aligned":true,"grade_appropriate":true,"error_free":true,"issues":"Relies on residuals of a least-squares line summing to 0, a fact not always taught in Math 1; fine if taught.","work":"LSRL residuals sum to 0: 3-5+4=2, so fourth=-2.","run_id":"claude-code","at":"2026-10-18T03:38:27.378Z"}}', 'ai', NULL, NULL)
